(* ═══════════════════════════════════════════════════════════════
   📤 PRG_06_Outputs — Barrière finale des sorties physiques (ST pur)
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF/AF_Partie-06_Acquisition_Qualification_IO_v2.3.md §5
   ⚙️ Exécuté en position 6 (après PRG_05_Translation).
   🛡️ Interlocks finaux M1/M2/M3 + agrégation PowerCutOff + chaîne AU.
   🔒 SafetyStructureNotValidated reste TRUE : aucune sortie moteur/frein
       autorisée tant que ce garde-fou n'est pas retiré.
   🎨 Organisation FONCTIONNELLE : chaque bloc regroupe la chaîne complète d'une
       fonction — conditions qui activent/désactivent la sortie (SafeStop / PowerCutOff /
       interlocks) → FB interlock → ordres → sorties physiques → bus inter-PRG. Lisible
       d'un coup d'œil.
   ═══════════════════════════════════════════════════════════════ *)

PROGRAM PRG_06_Outputs

VAR_INPUT
    // === 📥 ENTRÉES PROGRAMME (AUCUNE - PILOTÉ VIA GVL_IHM & PRG_02 À 05) ===
END_VAR

VAR_OUTPUT
    // === 🚌 BUS INTER-PRG (producteur unique) ===
    Data : ST_OutputsInterPrg; // <-- [BUS] Ordres actionneurs finaux (rebouclés FB_SimBench)

    // === 🚨 ÉTATS CHAÎNE AU & COUPURE ===
    EmergencyArmingPulseActive   : BOOL; // <-- [STAT] Impulsion rearmement AU active
    EmergencyArmingLockoutActive : BOOL; // <-- [STAT] Verrouillage rearmement AU actif
    ArmingSeqStep                : INT;  // <-- [STAT] Etape sequence rearmement AU
    RedundancyTestFailed         : BOOL; // <-- [DIAG] Test redondance AU echoue
    EmergencyArmingFailed        : BOOL; // <-- [DIAG] Echec rearmement AU
    EmergencyState               : ST_Safety_Emergency_State; // <-- [STAT] Etat chaine AU
    EmergencyDiag                : ST_Safety_Emergency_Diag;  // <-- [DIAG] Diagnostic chaine AU
    PowerCutOffActive            : BOOL; // <-- [SAFE] Demande de coupure finale active

    SafetyStructureNotValidated  : BOOL := FALSE; // 🔓 Garde-fou : autorisations M1/M2/M3 liees a leurs securites
    M1InterlockEnable            : BOOL; // <-- [SAFE] Gate finale M1 (Enable AND NOT PowerCutOff)
    M2InterlockEnable            : BOOL; // <-- [SAFE] Gate finale M2 (Enable AND NOT PowerCutOff)
    M3InterlockEnable            : BOOL; // <-- [SAFE] Gate finale M3 (Enable AND NOT PowerCutOff)
    M1PowerCutOffSafetyInfo      : BOOL; // <-- [DIAG] Securites M1 coupant la puissance
    M1SafeStopSafetyInfo         : BOOL; // <-- [DIAG] Securites M1 SafeStop
    M1BlockedBySafetyInfo        : BOOL; // <-- [DIAG] M1 bloque par securite (PowerCutOff OU SafeStop)
    M2PowerCutOffSafetyInfo      : BOOL; // <-- [DIAG] Securites M2 coupant la puissance
    M2SafeStopSafetyInfo         : BOOL; // <-- [DIAG] Securites M2 SafeStop
    M2BlockedBySafetyInfo        : BOOL; // <-- [DIAG] M2 bloque par securite (PowerCutOff OU SafeStop)
    M3PowerCutOffSafetyInfo      : BOOL; // <-- [DIAG] Securites M3 coupant la puissance
    M3SafeStopSafetyInfo         : BOOL; // <-- [DIAG] Securites M3 SafeStop
    M3BlockedBySafetyInfo        : BOOL; // <-- [DIAG] M3 bloque par securite (PowerCutOff OU SafeStop)

    // Les noms Device bruts (*_DQ / *_RQ) ne sont pas declares ici : les declarer
    // creerait une collision avec la globale homonyme du mapping E/S.
    M3_DriveControlWord          : WORD; // <-- [ACT] Mot commande variateur M3 (0x3101) — cible mapping E/S
    M3_DriveFreqRefWord          : WORD; // <-- [ACT] Consigne frequence M3 (0x3100, x100) — cible mapping E/S
    KoboldContactorCmd           : BOOL; // <-- [ACT] Ordre alimentation contacteur capteur fond Kobold
END_VAR

VAR
    // === 🛡️ SOUS-INSTANCES FB INTERLOCKS SORTIES ===
    instWinchOutputInterlockM1       : FB_WinchOutputInterlock;       // * [INST] Barriere finale treuil M1
    instWinchOutputInterlockM2       : FB_WinchOutputInterlock;       // * [INST] Barriere finale treuil M2
    instTranslationOutputInterlockM3 : FB_TranslationOutputInterlock; // * [INST] Barriere finale translation M3
    instSafetyEmergencyManagement    : FB_Safety_EmergencyManagement;    // * [INST] Gestionnaire de rearmement AU

    // === ⚡ ORDRES ACTIONNEURS (publiés via Data) ===
    M1RelayFwd                   : BOOL; // . [LOC] Ordre contacteur montee treuil M1
    M1RelayRev                   : BOOL; // . [LOC] Ordre contacteur descente treuil M1
    M1SpeedContactor1            : BOOL; // . [LOC] Ordre contacteur palier 1 treuil M1
    M1SpeedContactor2            : BOOL; // . [LOC] Ordre contacteur palier 2 treuil M1
    M1SpeedContactor3            : BOOL; // . [LOC] Ordre contacteur palier 3 treuil M1
    M1SpeedContactor4            : BOOL; // . [LOC] Ordre contacteur palier 4 treuil M1
    M1BrakeCmd                   : BOOL; // . [LOC] Ordre desserrage frein M1
    M2RelayFwd                   : BOOL; // . [LOC] Ordre contacteur montee/fermeture treuil M2
    M2RelayRev                   : BOOL; // . [LOC] Ordre contacteur descente/ouverture treuil M2
    M2SpeedContactor1            : BOOL; // . [LOC] Ordre contacteur palier 1 treuil M2
    M2SpeedContactor2            : BOOL; // . [LOC] Ordre contacteur palier 2 treuil M2
    M2SpeedContactor3            : BOOL; // . [LOC] Ordre contacteur palier 3 treuil M2
    M2SpeedContactor4            : BOOL; // . [LOC] Ordre contacteur palier 4 treuil M2
    M2BrakeCmd                   : BOOL; // . [LOC] Ordre desserrage frein M2
    TranslationBrakeCmd          : BOOL; // . [LOC] Demande frein M3 arbitree
    PowerKeepAliveACmd           : BOOL; // . [LOC] Maintien puissance voie A
    PowerKeepAliveBCmd           : BOOL; // . [LOC] Maintien puissance voie B
    EmergencyArmingCmd           : BOOL; // . [LOC] Impulsion rearmement puissance AU

    // === ⚙️ VARIABLES LOCALES INTERNES ===
    PowerCutOffReq                   : BOOL; // . [LOC] Demande agregative coupure puissance
END_VAR

// ═══════════════════════════════════════════════════════════════
// 🛗 §1 TREUIL M1 (Retenue) — conditions + interlock + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ D'un coup d'œil : ce qui active/désactive la sortie M1.
//   - M1InterlockEnable      : gate finale (Enable ET pas de PowerCutOff)
//   - M1PowerCutOffSafetyInfo: défauts qui COUPENT la puissance
//   - M1SafeStopSafetyInfo   : défauts qui font SafeStop (rampe rapide)
//   - M1BlockedBySafetyInfo  : synthèse (PowerCutOff OU SafeStop)
// Sources : PRG_04 (WinchM1FinalInterlockRequest / WinchM1Safety).

M1InterlockEnable := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.Enable
                      AND NOT PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.PowerCutOff;

M1PowerCutOffSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM1Safety.PowerCutOff
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaA
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaB
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaC
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaD
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaE
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ThermalFault;

M1SafeStopSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM1Safety.SafeStop
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.Error
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorOperatorComm
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorEncoder
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorPhaseRotation
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorOppositeDir
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorNoMovement;

M1BlockedBySafetyInfo := M1PowerCutOffSafetyInfo OR M1SafeStopSafetyInfo;

instWinchOutputInterlockM1(
    Enable                     := M1InterlockEnable,
    Reset                      := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged      := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.PowerContactorEngaged,
    SafeStop                   := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.SafeStop,
    BrakeFeedback              := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.BrakeFeedback,
    FwdRevSpeedFeedbackOff     := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.FwdRevSpeedFeedbackOff,
    RequestedRelayFwd          := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedRelayFwd,
    RequestedRelayRev          := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedRelayRev,
    RequestedContactor1        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor1,
    RequestedContactor2        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor2,
    RequestedContactor3        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor3,
    RequestedContactor4        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor4,
    RequestedStep               := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedStep
);

M1RelayFwd        := instWinchOutputInterlockM1.RelayFwd;
M1RelayRev        := instWinchOutputInterlockM1.RelayRev;
M1SpeedContactor1 := instWinchOutputInterlockM1.Contactor1;
M1SpeedContactor2 := instWinchOutputInterlockM1.Contactor2;
M1SpeedContactor3 := instWinchOutputInterlockM1.Contactor3;
M1SpeedContactor4 := instWinchOutputInterlockM1.Contactor4;
// Recalcul independant sur les DQ finaux (pas une recopie de BrakeCmd).
M1BrakeCmd        := M1RelayFwd OR M1RelayRev;

// ── Sorties physiques M1 ──
M1_RelayFwd_Up_DQ            := M1RelayFwd;
M1_RelayRev_Down_DQ          := M1RelayRev;
M1_SpeedContactor_1_DQ       := M1SpeedContactor1;
M1_SpeedContactor_2_DQ       := M1SpeedContactor2;
M1_SpeedContactor_3_DQ       := M1SpeedContactor3;
M1_SpeedContactor_4_DQ       := M1SpeedContactor4;
M1_BrakeRelease_RQ           := M1BrakeCmd;

// ── Bus inter-PRG M1 ──
Data.M1RelayFwd            := M1RelayFwd;
Data.M1RelayRev            := M1RelayRev;
Data.M1SpeedContactor1     := M1SpeedContactor1;
Data.M1SpeedContactor2     := M1SpeedContactor2;
Data.M1SpeedContactor3     := M1SpeedContactor3;
Data.M1SpeedContactor4     := M1SpeedContactor4;
Data.M1BrakeCmd            := M1BrakeCmd;

// ═══════════════════════════════════════════════════════════════
// 🛗 §2 TREUIL M2 (Benne) — conditions + interlock + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ Même lecture que M1 : gate finale, défauts PowerCutOff / SafeStop, synthèse.
// Sources : PRG_04 (WinchM2FinalInterlockRequest / WinchM2Safety / BucketState).

M2InterlockEnable := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.Enable
                      AND NOT PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.PowerCutOff;

M2PowerCutOffSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM2Safety.PowerCutOff
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaA
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaB
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaC
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaD
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaE
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ThermalFault;

M2SafeStopSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM2Safety.SafeStop
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.Error
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorOperatorComm
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorEncoder
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorPhaseRotation
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorOppositeDir
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorNoMovement
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.SlackCable
                     OR PRG_04_Treuils_Benne.Data.BucketState.Error
                     OR PRG_04_Treuils_Benne.Data.BucketState.CoupledMotionBlockedByBucket;

M2BlockedBySafetyInfo := M2PowerCutOffSafetyInfo OR M2SafeStopSafetyInfo;

instWinchOutputInterlockM2(
    Enable                     := M2InterlockEnable,
    Reset                      := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged      := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.PowerContactorEngaged,
    SafeStop                   := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.SafeStop,
    BrakeFeedback              := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.BrakeFeedback,
    FwdRevSpeedFeedbackOff     := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.FwdRevSpeedFeedbackOff,
    RequestedRelayFwd          := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedRelayFwd,
    RequestedRelayRev          := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedRelayRev,
    RequestedContactor1        := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedContactor1,
    RequestedContactor2        := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedContactor2,
    RequestedContactor3        := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedContactor3,
    RequestedContactor4        := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedContactor4,
    RequestedStep               := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedStep
);

M2RelayFwd        := instWinchOutputInterlockM2.RelayFwd;
M2RelayRev        := instWinchOutputInterlockM2.RelayRev;
M2SpeedContactor1 := instWinchOutputInterlockM2.Contactor1;
M2SpeedContactor2 := instWinchOutputInterlockM2.Contactor2;
M2SpeedContactor3 := instWinchOutputInterlockM2.Contactor3;
M2SpeedContactor4 := instWinchOutputInterlockM2.Contactor4;
// Recalcul independant, voir M1.
M2BrakeCmd        := M2RelayFwd OR M2RelayRev;

// ── Sorties physiques M2 ──
M2_RelayFwd_Up_Close_DQ      := M2RelayFwd;
M2_RelayRev_Down_Open_DQ     := M2RelayRev;
M2_SpeedContactor_1_DQ       := M2SpeedContactor1;
M2_SpeedContactor_2_DQ       := M2SpeedContactor2;
M2_SpeedContactor_3_DQ       := M2SpeedContactor3;
M2_SpeedContactor_4_DQ       := M2SpeedContactor4;
M2_BrakeRelease_RQ           := M2BrakeCmd;

// ── Bus inter-PRG M2 ──
Data.M2RelayFwd            := M2RelayFwd;
Data.M2RelayRev            := M2RelayRev;
Data.M2SpeedContactor1     := M2SpeedContactor1;
Data.M2SpeedContactor2     := M2SpeedContactor2;
Data.M2SpeedContactor3     := M2SpeedContactor3;
Data.M2SpeedContactor4     := M2SpeedContactor4;
Data.M2BrakeCmd            := M2BrakeCmd;

// ═══════════════════════════════════════════════════════════════
// ↔️ §3 TRANSLATION M3 (variateur AC600) — conditions + interlock + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ Même lecture : gate finale, défauts PowerCutOff / SafeStop, synthèse.
// Sources : PRG_05 (TranslationFinalInterlockRequest / TranslationSafety).

M3InterlockEnable := PRG_05_Translation.Data.TranslationFinalInterlockRequest.Enable
                      AND NOT PRG_05_Translation.Data.TranslationFinalInterlockRequest.PowerCutOff;

M3PowerCutOffSafetyInfo := PRG_05_Translation.Data.TranslationSafety.PowerCutOff
                        OR PRG_05_Translation.Data.TranslationSafety.ErrorMecaA
                        OR PRG_05_Translation.Data.TranslationSafety.ErrorMecaB
                        OR PRG_05_Translation.Data.TranslationSafety.ErrorBrakeThermal;

M3SafeStopSafetyInfo := PRG_05_Translation.Data.TranslationSafety.SafeStop
                     OR PRG_05_Translation.Data.TranslationSafety.Error
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorOperatorComm
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorDriveComm
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorPhaseRotation
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorLimitSwitch
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorSensorIncoherent;

M3BlockedBySafetyInfo := M3PowerCutOffSafetyInfo OR M3SafeStopSafetyInfo;

instTranslationOutputInterlockM3(
    Enable                     := M3InterlockEnable,
    Reset                      := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged      := PRG_05_Translation.Data.TranslationFinalInterlockRequest.PowerContactorEngaged,
    SafeStop                   := PRG_05_Translation.Data.TranslationFinalInterlockRequest.SafeStop,
    BrakeReleaseRequest        := PRG_05_Translation.Data.TranslationFinalInterlockRequest.BrakeReleaseRequest,
    BrakeCommandOpenConfirmed  := PRG_05_Translation.Data.TranslationFinalInterlockRequest.BrakeCommandOpenConfirmed,
    RequestedDriveControlWord  := PRG_05_Translation.Data.TranslationFinalInterlockRequest.RequestedDriveControlWord,
    RequestedDriveFreqHz       := PRG_05_Translation.Data.TranslationFinalInterlockRequest.RequestedDriveFreqHz
);

TranslationBrakeCmd := instTranslationOutputInterlockM3.BrakeCmd;
M3_CommandWord := instTranslationOutputInterlockM3.DriveControlWord;
M3_SetpointFrequencyHz := instTranslationOutputInterlockM3.DriveFreqRefWord;

// ── Sorties physiques M3 ──
M3_BrakeRelease_RQ           := TranslationBrakeCmd;

// ── Bus inter-PRG M3 ──
Data.TranslationBrakeCmd   := TranslationBrakeCmd;

// ═══════════════════════════════════════════════════════════════
// 🪝 §4 KOBOLD (capteur fond) — commande + sortie
// ═══════════════════════════════════════════════════════════════
// Source : PRG_04 (KoboldContactorCmdArbitrated).
KoboldContactorCmd := PRG_04_Treuils_Benne.Data.KoboldContactorCmdArbitrated;
M1_M2_KoboldMeasureEnable_DQ := KoboldContactorCmd;

// ═══════════════════════════════════════════════════════════════
// 🛡️ §5 AU / MAINTIEN PUISSANCE — coupure + réarmement + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ D'un coup d'œil : ce qui coupe la puissance (PowerCutOffReq) et ce qui
//    maintient/réarme (instSafetyEmergencyManagement) → sorties physiques.
// Sources : PRG_04/05 (PowerCutOff), GVL_IHM (ArmRequest / BtnEmergencyCutOff),
//           PRG_02 (EmergencyChainClosed / PowerContactorEngaged).

// PowerCutOffReq = agrégation OU strict des demandes de coupure des trois procédés (M5, A-04).
PowerCutOffReq := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.PowerCutOff
               OR PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.PowerCutOff
               OR PRG_05_Translation.Data.TranslationFinalInterlockRequest.PowerCutOff;

instSafetyEmergencyManagement(
    Enable := TRUE,
    Reset := PRG_07_Supervision.FaultMachineReset_IHM,
    ArmRequest := GVL_IHM.Modes.Cmd.BtnEmergencyArming,
    EmergencyChainClosed := PRG_02_Acquisition.HwIn.Machine.EmergencyChainClosed_DI,
    PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    PowerCutOffRequest := PowerCutOffReq,
    BtnEmergencyCutOff := GVL_IHM.Modes.Cmd.BtnEmergencyCutOff
);

// ── Ordres AU (logique) ──
PowerKeepAliveACmd := instSafetyEmergencyManagement.MaintainA_RQ;
PowerKeepAliveBCmd := instSafetyEmergencyManagement.MaintainB_RQ;
EmergencyArmingCmd := instSafetyEmergencyManagement.ArmPulse_RQ;

// ── Sorties physiques AU ──
PowerKeepAlive_A_RQ          := PowerKeepAliveACmd;
PowerKeepAlive_B_RQ          := PowerKeepAliveBCmd;
EmergencyArming_RQ           := EmergencyArmingCmd;

// ── Bus inter-PRG AU ──
Data.PowerKeepAliveACmd    := PowerKeepAliveACmd;
Data.PowerKeepAliveBCmd    := PowerKeepAliveBCmd;
Data.EmergencyArmingCmd    := EmergencyArmingCmd;

// ── Diagnostics chaîne AU ──
EmergencyArmingLockoutActive := instSafetyEmergencyManagement.EmergencyArmingLockoutActive;
ArmingSeqStep := instSafetyEmergencyManagement.ArmingSeqStep;
RedundancyTestFailed := instSafetyEmergencyManagement.RedundancyTestFailed;
EmergencyArmingFailed := instSafetyEmergencyManagement.EmergencyArmingFailed;
EmergencyState := instSafetyEmergencyManagement.State;
EmergencyDiag := instSafetyEmergencyManagement.Diag;
PowerCutOffActive := PowerCutOffReq;

END_PROGRAM

(* ═══════════════════════════════════════════════════════════════
   🔄 FB_Cycle — Séquenceur du Cycle Automatique (Grafcet de dragage)
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF/AF_Partie-04_Mode_SemiAuto_Sequenceur_v2.0.md
            DOC/WFLOW/AUDITS/DESIGN_SEMI_AUTO_CYCLE_v0.1.md
   🔌 Conforme au contrat FB standard (Partie3 §1bis) + §11bis R1-R9.
   🧩 Deux instances : instCycleMaintenance (MAINT_N1/N2) et
      instCycleSemiAuto (SEMI_AUTO) — gating sorties par mode.
   🕹️ Homme-mort (D2) : appui = autorisation 3 s ; mouvement continue
      sans appui ; arrêt au centre du manche (CycleMotionPermit).
   ⏱️ Tempo max d'étape : lancée SEULEMENT si pilotage joystick actif.
   🧊 CycleStepAtError : étape spécifique mémorisée avant STABILIZING (R9).
   🏁 Début de graphe : à la TRÉMIE, treuils en position HAUTE — rebouclage sur X0.
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Cycle
VAR_INPUT
    Enable                  : BOOL;         // Activation générale du séquenceur
    Reset                   : BOOL;         // Acquittement défaut (front)
    PowerContactorEngaged   : BOOL;         // Chaîne de sécurité OK
    Mode                    : E_Mode;       // Mode arbitré (SEMI_AUTO pour l'instance cycle)
    CycleMotionPermit       : BOOL;         // 🕹️ Manche défléchi (non centré) — D2
    DeadmanArmed            : BOOL;         // 🔫 Appui homme-mort (fenêtre 3 s)
    HeartbeatIhmOk          : BOOL;         // 💓 IHM↔PLC valide

    // Commandes opérateur
    StartCycle              : BOOL;         // Demande lancement / reprise (IHM)
    AbortCycle              : BOOL;         // Demande abandon (IHM) — pas de Pause (D3)

    // Cibles et paramètres (réutilise config maintenance — Q4)
    SelTarget               : INT;          // 🎯 Cible sélectionnée (GVL_IHM.TranslationM3.Cmd.SelTarget) : 1=Trémie, 2=P2, 3=P1, 4=Maintenance
    SetDepthM               : REAL;         // Profondeur de consigne (négative)
    SetOffsetM              : REAL;         // Écart de fermeture benne cible

    // Feedbacks physique & matériel
    KoboldContactFond       : BOOL;         // Retour dédié Kobold : TRUE = contact fond
    LimitLegalReached       : BOOL;         // Limite légale atteinte (descente interdite)
    LimitLegalDepthM        : REAL;         // Profondeur légale minimale autorisée
    WinchSyncError          : BOOL;         // Désynchronisme bloquant M1/M2
    WinchSyncDeltaM         : REAL;         // Écart codeurs M1/M2 pour diagnostic
    M1_CablePosM            : REAL;         // Position câble treuil M1 (recalée)
    M2_CablePosM            : REAL;         // Position câble treuil M2 (recalée)
    M1_MeasuredSpeedMps     : REAL;         // Vitesse linéaire mesurée M1 (m/s)
    M2_MeasuredSpeedMps     : REAL;         // Vitesse linéaire mesurée M2 (m/s)
    SpeedMismatchThresholdMps : REAL;       // Seuil écart vitesse ; 0 = contrôle désactivé
    SpeedMismatchTimeout    : TIME;         // Durée de confirmation ; 0 = contrôle désactivé
    CableLimitM1AscentM     : REAL;         // Limite haute d'exploitation M1

    // Feedbacks Translation M3
    Translation_At_P1           : BOOL;     // Capteur position P1 (arrêt travail)
    Translation_At_Tremie       : BOOL;     // Capteur fin de course trémie
    Translation_At_Maintenance : BOOL;     // Capteur fin de course maintenance
    Translation_Busy            : BOOL;     // Mouvement translation en cours
    Translation_Done            : BOOL;     // Cible translation atteinte

    // Feedbacks Benne
    Benne_Busy              : BOOL;         // Mouvement mâchoires benne en cours
    Benne_Done              : BOOL;         // Mouvement ouverture/fermeture terminé
    Benne_IsOpen            : BOOL;         // Benne mécaniquement ouvert mémorisé
    Benne_IsClosed          : BOOL;         // Benne mécaniquement fermé mémorisé
    Benne_IsRoughlyClosed   : BOOL;         // 🆕 Benne « à peu près fermée » (tolérance matière)

    // 🆕 Référencement (X1_HOMING)
    HomedM1                 : BOOL;         // Codeur M1 référencé
    HomedM2                 : BOOL;         // Codeur M2 référencé
    TopPositionSensor       : BOOL;         // Capteur position haute (référencement)
    HomingRequest           : BOOL;         // Demande de référencement (front)
END_VAR
VAR_OUTPUT
    Ready                   : BOOL;         // Séquenceur disponible
    Busy                    : BOOL;         // Cycle automatique actif
    Done                    : BOOL;         // Cycle automatique complété
    Error                   : BOOL;         // Défaut cycle
    ErrorId                 : WORD;         // bit0: timeout/limite, bit1: désynchronisme, bit2: cible invalide, bit3: stabilisation impossible, bit4: écart vitesse, bit5: perte heartbeat, bit6: tempo max étape
    SpeedMismatchMps        : REAL;         // Écart absolu vitesse M1/M2 (m/s)
    SpeedMismatchActive     : BOOL;         // Seuil vitesse dépassé sur le cycle courant
    SpeedMismatchConfirmed  : BOOL;         // Écart vitesse confirmé pendant SpeedMismatchTimeout

    // Commandes structurées (demandes de mouvement)
    WinchM1Cmd              : ST_WinchCmdDemand;        // Demande treuil M1
    WinchM2Cmd              : ST_WinchCmdDemand;        // Demande treuil M2
    TranslationCmd          : ST_TranslationCmdDemand;  // Demande translation M3
    BucketCmd               : ST_BucketCmdDemand;       // Demande benne

    // Métadonnées d'affichage IHM
    CycleStep               : E_CycleStep;  // Étape active du Grafcet
    CycleStateStr           : STRING(80);   // Libellé en clair de l'étape (Xn - texte)
    CycleStepAtError        : E_CycleStep;  // 🧊 Étape spécifique au moment du défaut (R9)
    SampleCount             : INT;          // 🆕 Compteur de prélèvements (RETAIN, Q3bis)
END_VAR
VAR
    ResetEdge               : R_TRIG;
    StartEdge               : R_TRIG;
    AbortEdge               : R_TRIG;
    ErrorEdge               : R_TRIG;       // 🧊 Capture CycleStepAtError avant bascule (R9)

    // Séquencement
    State                   : E_CycleStep := E_CycleStep.X0_PREPARATION;
    SavedState              : E_CycleStep := E_CycleStep.X0_PREPARATION;

    // Mémorisations et Timers
    TouchPositionM          : REAL;         // Position M1 mémorisée lors du contact fond
    RaiseTargetM            : REAL;         // Profondeur de remontée mémorisée
    DrainingTimer           : TON;          // Temporisateur de vidage (égouttage)
    StabilizationTimer      : TON;          // Temporisation maximale de remontée lente
    SpeedMismatchTimer      : TON;          // Confirmation temporelle écart de vitesse
    StepMaxTimer            : TON;          // 🆕 Tempo max d'étape (R5) — lancée si pilotage
    SelectedWorkTarget      : INT;          // Cible de travail mémorisée (1=Trémie, 3=P1, 4=Maintenance)

    // Paramètres internes
    CtrlAscentDistM         : REAL := 2.0;      // Distance de remontée lente de contrôle
    CtrlAscentToleranceM    : REAL := 0.25;     // Écart maximal admis entre les deux codeurs
    CtrlAscentTimeout       : TIME := T#30s;    // Temps max pour atteindre la zone de stabilisation
    DrainingTime            : TIME := T#5s;     // Temps d'égouttage par défaut
    StepMaxTimeout          : TIME := T#60s;   // 🆕 Tempo max d'étape (à valider, Q4)
END_VAR

// === IMPLEMENTATION ===

{region "Gate securite"}
// 🛑 1. GATES DE SÉCURITÉ ET BLOCAGE (R8)
IF NOT Enable OR NOT PowerContactorEngaged THEN
    WinchM1Cmd.StartStop   := FALSE;
    WinchM1Cmd.Direction   := 0;
    WinchM1Cmd.SpeedPct    := 0.0;

    WinchM2Cmd.StartStop   := FALSE;
    WinchM2Cmd.Direction   := 0;
    WinchM2Cmd.SpeedPct    := 0.0;

    TranslationCmd.Start   := FALSE;
    TranslationCmd.Target  := 0;

    BucketCmd.Open         := FALSE;
    BucketCmd.Close        := FALSE;
    BucketCmd.KoboldContactorCmd := FALSE;

    State                := E_CycleStep.X0_PREPARATION;   // retour à la PREMIÈRE étape (R8)
    CycleStep            := E_CycleStep.X0_PREPARATION;
    CycleStateStr        := 'X0 - Désactivé : sécurité absente ou auto désactivé';
    Ready                := FALSE;
    Busy                 := FALSE;
    Done                 := FALSE;
    RETURN;
END_IF;
{endregion}

{region "Preparation surveillance et commandes cycle"}
Ready := TRUE;
ResetEdge(CLK := Reset);
StartEdge(CLK := StartCycle);
AbortEdge(CLK := AbortCycle);
ErrorEdge(CLK := Error);

// 🧊 R9 — capture l'étape spécifique AVANT la bascule vers STABILIZING
IF ErrorEdge.Q THEN
    CycleStepAtError := State;
END_IF;

// ⏱️ T36 — surveillance indépendante de la remontée lente
StabilizationTimer(IN := (State = E_CycleStep.X7_CTRL_ASCENT), PT := CtrlAscentTimeout);

// 📏 T43 — comparaison vitesse réelle M1/M2
SpeedMismatchMps := ABS(M1_MeasuredSpeedMps - M2_MeasuredSpeedMps);
SpeedMismatchActive := (State = E_CycleStep.X7_CTRL_ASCENT)
                       AND CycleMotionPermit
                       AND (SpeedMismatchThresholdMps > 0.0)
                       AND (SpeedMismatchTimeout > T#0ms)
                       AND (SpeedMismatchMps > SpeedMismatchThresholdMps);
SpeedMismatchTimer(IN := SpeedMismatchActive, PT := SpeedMismatchTimeout);
SpeedMismatchConfirmed := SpeedMismatchTimer.Q;

// 🆕 Tempo max d'étape (R5) — lancée SEULEMENT si pilotage joystick actif (pas de défaut au repos)
StepMaxTimer(IN := CycleMotionPermit AND (State <> E_CycleStep.X0_PREPARATION)
                  AND (State <> E_CycleStep.X13_DONE_SYNC)
                  AND (State <> E_CycleStep.STABILIZING),
             PT := StepMaxTimeout);

IF ResetEdge.Q THEN
    Error := FALSE;
    ErrorId := 16#0000;
    SavedState := E_CycleStep.X0_PREPARATION;
    IF State = E_CycleStep.STABILIZING THEN
        State := E_CycleStep.X0_PREPARATION;
    END_IF;
END_IF;

// 💓 Perte IHM : repli mémorisé. La reconnexion seule ne relance jamais le cycle.
IF NOT HeartbeatIhmOk AND State <> E_CycleStep.STABILIZING THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0020;
    State := E_CycleStep.STABILIZING;
END_IF;

// Défaut de synchronisme : arrêt sûr et acquittement obligatoire.
IF WinchSyncError AND State <> E_CycleStep.STABILIZING THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0002;
    State := E_CycleStep.STABILIZING;
END_IF;

// 🛡️ T43 — écart de vitesse confirmé : arrêt du cycle et STABILIZING.
IF SpeedMismatchConfirmed AND State <> E_CycleStep.STABILIZING THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0010;
    State := E_CycleStep.STABILIZING;
END_IF;

// 🆕 Tempo max d'étape dépassée (blocage probable) → défaut
IF StepMaxTimer.Q AND State <> E_CycleStep.STABILIZING THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0040;
    State := E_CycleStep.STABILIZING;
END_IF;

// Gestion de l'Abandon (D3 — pas de Pause)
IF AbortEdge.Q THEN
    State := E_CycleStep.X0_PREPARATION;
END_IF;
{endregion}

{region "Machine etat cycle automatique"}
// 🔁 2. LOGIQUE DU SÉQUENCEUR (Machine d'état) — CASE sur enum unique (R1)
CASE State OF

    E_CycleStep.X0_PREPARATION:
        CycleStep := E_CycleStep.X0_PREPARATION;
        CycleStateStr := 'X0 - Vérification cohérence système';
        WinchM1Cmd.StartStop := FALSE; WinchM1Cmd.Direction := 0; WinchM1Cmd.SpeedPct := 0.0;
        WinchM2Cmd.StartStop := FALSE; WinchM2Cmd.Direction := 0; WinchM2Cmd.SpeedPct := 0.0;
        TranslationCmd.Start := FALSE; TranslationCmd.Target := 0;
        BucketCmd.Open := FALSE; BucketCmd.Close := FALSE; BucketCmd.KoboldContactorCmd := FALSE;
        Busy := FALSE; Done := FALSE;

        // Transition si système sain et réarmé (front reset ou démarrage)
        IF StartEdge.Q THEN
            State := E_CycleStep.X1_HOMING;
        END_IF;

    E_CycleStep.X1_HOMING:
        CycleStep := E_CycleStep.X1_HOMING;
        CycleStateStr := 'X1 - Référencement codeurs (vitesses lentes)';
        Busy := TRUE;

        // 🆕 Vitesses lentes pour chercher capteur top + référencement
        IF NOT HomedM1 OR NOT HomedM2 THEN
            WinchM1Cmd.StartStop := CycleMotionPermit;
            WinchM1Cmd.Direction := 1;   // montée lente vers capteur top
            WinchM1Cmd.SpeedPct := 10.0;
            WinchM2Cmd.StartStop := CycleMotionPermit;
            WinchM2Cmd.Direction := 1;
            WinchM2Cmd.SpeedPct := 10.0;
            IF HomingRequest THEN
                // déclenche le référencement (via FB_Encoder_Homing en aval)
                State := E_CycleStep.X2_WORK_POS_SELECT;
            END_IF;
        ELSE
            // déjà homé → passe vite
            State := E_CycleStep.X2_WORK_POS_SELECT;
        END_IF;

    E_CycleStep.X2_WORK_POS_SELECT:
        CycleStep := E_CycleStep.X2_WORK_POS_SELECT;
        CycleStateStr := 'X2 - Sélection position travail (P1)';
        Busy := TRUE;

        // 🆕 Destinations sélectionnables : Trémie(1), P1(3), Maintenance(4).
        // P2(2) n'est PAS une destination — capteur de passage en petite vitesse (PV).
        IF (SelTarget <> 1) AND (SelTarget <> 3) AND (SelTarget <> 4) THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0004;
            State := E_CycleStep.STABILIZING;
        ELSE
            SelectedWorkTarget := SelTarget;
            TranslationCmd.Target := SelTarget;
            TranslationCmd.Start := CycleMotionPermit;
            // Arrivée à la cible (Trémie/P1/Maintenance) — capteurs PV/PVP2/P2 = ralentissement
            IF CycleMotionPermit AND (
                (SelTarget = 1 AND Translation_At_Tremie) OR
                (SelTarget = 3 AND Translation_At_P1) OR
                (SelTarget = 4 AND Translation_At_Maintenance)) THEN
                TranslationCmd.Start := FALSE;
                State := E_CycleStep.X3_OPEN_BUCKET;
            END_IF;
        END_IF;

    E_CycleStep.X3_OPEN_BUCKET:
        CycleStep := E_CycleStep.X3_OPEN_BUCKET;
        CycleStateStr := 'X3 - Ouverture benne';
        Busy := TRUE;

        // 🆕 Ouverture benne ; si déjà ouverte → passe vite
        IF Benne_IsOpen THEN
            State := E_CycleStep.X4_DESCEND_OPEN;
        ELSE
            BucketCmd.Open := CycleMotionPermit;
            IF CycleMotionPermit AND Benne_Done AND Benne_IsOpen THEN
                BucketCmd.Open := FALSE;
                State := E_CycleStep.X4_DESCEND_OPEN;
            END_IF;
        END_IF;

    E_CycleStep.X4_DESCEND_OPEN:
        CycleStep := E_CycleStep.X4_DESCEND_OPEN;
        CycleStateStr := 'X4 - Plongée benne ouverte (synchro)';

        // M1 et M2 descendent ensemble (synchro gérée en aval)
        WinchM1Cmd.StartStop := CycleMotionPermit;
        WinchM1Cmd.Direction := -1;
        WinchM1Cmd.SpeedPct  := 50.0;
        WinchM2Cmd.StartStop := CycleMotionPermit;
        WinchM2Cmd.Direction := -1;
        WinchM2Cmd.SpeedPct  := 50.0;
        BucketCmd.KoboldContactorCmd := TRUE;

        // Transition uniquement sur le retour dédié Kobold.
        IF CycleMotionPermit AND KoboldContactFond THEN
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            BucketCmd.KoboldContactorCmd := FALSE;
            TouchPositionM := M1_CablePosM;
            IF LimitLegalDepthM < -0.01 THEN
                RaiseTargetM := MAX(TouchPositionM + 0.5, LimitLegalDepthM + 0.5);
            ELSE
                RaiseTargetM := TouchPositionM + 0.5;
            END_IF;
            State := E_CycleStep.X5_BOTTOM_CONFIRMED;
        ELSIF LimitLegalReached THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0001;
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            BucketCmd.KoboldContactorCmd := FALSE;
            State := E_CycleStep.STABILIZING;
        END_IF;

    E_CycleStep.X5_BOTTOM_CONFIRMED:
        CycleStep := E_CycleStep.X5_BOTTOM_CONFIRMED;
        CycleStateStr := 'X5 - Fond confirmé : remontée sécurisée';

        WinchM1Cmd.StartStop := CycleMotionPermit;
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct := 20.0;
        WinchM2Cmd.StartStop := CycleMotionPermit;
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct := 20.0;

        // Les deux treuils restent synchronisés jusqu'au-dessus de la limite légale.
        IF CycleMotionPermit AND (M1_CablePosM >= RaiseTargetM) AND (M2_CablePosM >= RaiseTargetM) THEN
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            State := E_CycleStep.X6_CLOSE_BUCKET;
        END_IF;

    E_CycleStep.X6_CLOSE_BUCKET:
        CycleStep := E_CycleStep.X6_CLOSE_BUCKET;
        CycleStateStr := 'X6 - Fermeture benne (tolérance à peu près fermé)';

        WinchM1Cmd.StartStop := FALSE;
        BucketCmd.Close := TRUE;

        // 🆕 Tolérance : si benne « à peu près fermée » (matière/objet), on remonte et on contrôle
        IF CycleMotionPermit AND (Benne_Done AND (Benne_IsClosed OR Benne_IsRoughlyClosed)) THEN
            BucketCmd.Close := FALSE;
            State := E_CycleStep.X7_CTRL_ASCENT;
        END_IF;

    E_CycleStep.X7_CTRL_ASCENT:
        CycleStep := E_CycleStep.X7_CTRL_ASCENT;
        CycleStateStr := 'X7 - Remontée lente de contrôle';

        WinchM1Cmd.StartStop := CycleMotionPermit;
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct  := 20.0;
        WinchM2Cmd.StartStop := CycleMotionPermit;
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct  := 20.0;

        // Contrôle des deux codeurs
        IF WinchSyncError OR (ABS(M1_CablePosM - M2_CablePosM) > CtrlAscentToleranceM) THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0008;
            State := E_CycleStep.STABILIZING;
        ELSIF CycleMotionPermit
           AND (M1_CablePosM >= (TouchPositionM + CtrlAscentDistM))
           AND (M2_CablePosM >= (TouchPositionM + CtrlAscentDistM))
           AND (ABS(M1_CablePosM - M2_CablePosM) <= CtrlAscentToleranceM) THEN
            State := E_CycleStep.X8_ASCENT_LOADED;
        ELSIF StabilizationTimer.Q THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0008;
            State := E_CycleStep.STABILIZING;
        END_IF;

    E_CycleStep.X8_ASCENT_LOADED:
        CycleStep := E_CycleStep.X8_ASCENT_LOADED;
        CycleStateStr := 'X8 - Remontée en charge';

        WinchM1Cmd.StartStop := CycleMotionPermit;
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct  := 70.0;
        WinchM2Cmd.StartStop := CycleMotionPermit;
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct  := 70.0;

        // Transition alignée sur la limite haute d'exploitation
        IF CycleMotionPermit AND M1_CablePosM >= CableLimitM1AscentM THEN
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            State := E_CycleStep.X9_DRAIN_PAUSE;
        END_IF;

    E_CycleStep.X9_DRAIN_PAUSE:
        CycleStep := E_CycleStep.X9_DRAIN_PAUSE;
        CycleStateStr := 'X9 - Égouttage du godet en cours';
        WinchM1Cmd.StartStop := FALSE;
        WinchM2Cmd.StartStop := FALSE;

        DrainingTimer(IN := TRUE, PT := DrainingTime);
        // 🆕 Temps écoulé affiché IHM (CycleStateStr + champ dédié)
        IF CycleMotionPermit AND DrainingTimer.Q THEN
            DrainingTimer(IN := FALSE);
            State := E_CycleStep.X10_TRANSLATE_DUMP;
        END_IF;

    E_CycleStep.X10_TRANSLATE_DUMP:
        CycleStep := E_CycleStep.X10_TRANSLATE_DUMP;
        CycleStateStr := 'X10 - Déplacement vers trémie (grille/crible libres)';

        TranslationCmd.Target := 1; // Trémie
        TranslationCmd.Start := CycleMotionPermit;

        // 🆕 Avertissement IHM : grille abaissée/libre, crible libre pour réceptionner la charge
        // (porté par CycleStateStr + OperatorAction côté supervision)

        // Transition si translation arrivé à la trémie
        IF CycleMotionPermit AND Translation_At_Tremie THEN
            TranslationCmd.Start := FALSE;
            State := E_CycleStep.X11_OPEN_DUMP;
        END_IF;

    E_CycleStep.X11_OPEN_DUMP:
        CycleStep := E_CycleStep.X11_OPEN_DUMP;
        CycleStateStr := 'X11 - Vidange / ouverture du godet (montée possible, descente ouvre)';

        // 🆕 Montée possible (treuils vers le haut) ; descente fait ouvrir la benne.
        // Montée : on laisse l'opérateur remonter les 2 treuils en synchro si besoin.
        WinchM1Cmd.StartStop := CycleMotionPermit AND (WinchM1Cmd.Direction = 1);
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct  := 20.0;
        WinchM2Cmd.StartStop := CycleMotionPermit AND (WinchM2Cmd.Direction = 1);
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct  := 20.0;

        // Descente → ouverture benne (vidage)
        BucketCmd.Open := CycleMotionPermit AND (WinchM1Cmd.Direction = -1);

        // 🆕 Contrôle convoyeurs par MESSAGE utilisateur (pas encore câblé) :
        // CycleStateStr + OperatorAction côté supervision demandent de vérifier
        // que les convoyeurs sont en route avant/au lâcher.
        IF CycleMotionPermit AND Benne_Done AND Benne_IsOpen THEN
            BucketCmd.Open := FALSE;
            State := E_CycleStep.X13_DONE_SYNC;
        END_IF;

    E_CycleStep.X13_DONE_SYNC:
        CycleStep := E_CycleStep.X13_DONE_SYNC;
        CycleStateStr := 'X13 - Cycle automatique complété - prêt';
        WinchM1Cmd.StartStop := FALSE;
        WinchM2Cmd.StartStop := FALSE;
        TranslationCmd.Start := FALSE;
        Done := TRUE;
        Busy := FALSE;

        // 🆕 Compteur de prélèvements (RETAIN, Q3bis) — compte inconditionnellement
        SampleCount := SampleCount + 1;

        // 🆕 Rebouclage sur X0_PREPARATION (trémie, treuils hauts) — pas de retour P1
        IF StartEdge.Q THEN
            Done := FALSE;
            State := E_CycleStep.X0_PREPARATION;
        END_IF;

    E_CycleStep.STABILIZING:
        CycleStep := E_CycleStep.STABILIZING;
        CycleStateStr := 'X14 - Cycle en attente / stabilisation (STAB)';
        WinchM1Cmd.StartStop := FALSE;
        WinchM2Cmd.StartStop := FALSE;
        TranslationCmd.Start := FALSE;
        BucketCmd.Open := FALSE;
        BucketCmd.Close := FALSE;

END_CASE;
{endregion}

{region "Repli homme mort"}
// 🛑 Relâchement du manche (retour au centre) : aucune demande d'actionneur ne reste active.
// L'étape est mémorisée et reprend au prochain appui valide (D2).
IF Busy AND NOT CycleMotionPermit THEN
    WinchM1Cmd.StartStop := FALSE;
    WinchM2Cmd.StartStop := FALSE;
    TranslationCmd.Start := FALSE;
    BucketCmd.Open := FALSE;
    BucketCmd.Close := FALSE;
    BucketCmd.KoboldContactorCmd := FALSE;
END_IF;
{endregion}

END_FUNCTION_BLOCK

(* =======================================================================
   📊 FB_Diag_IhmHeartbeat — Surveillance bidirectionnelle Heartbeat IHM/PLC
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Surveillance toggle IHM, generation toggle PLC et diagnostic timeout
   🛡️ Protection : FB de diagnostic autonome (sans action directe sur AU)
   📄 Doc métier : DOC/AF/AF_Partie-12_Fonction_Diagnostic_v1.0.md
   ======================================================================= *)
FUNCTION_BLOCK PUBLIC FB_Diag_IhmHeartbeat
VAR_INPUT
    // === COMMANDES & REGLAGES ===
    Enable                      : BOOL;         // --> [CMD] Active la surveillance (FALSE = IHM invalide)
    TglHeartbeatIhm             : BOOL;         // --> [HW]  Toggle IHM, inversion attendue toutes les 500 ms
    IhmTimeout                  : TIME := T#2s; // --> [CFG] Absence maximale de front IHM
    PlcTogglePeriod             : TIME := T#500ms; // --> [CFG] Periode du clignotant PLC
END_VAR
VAR_OUTPUT
    // === ETATS & DIAGNOSTICS IHM ===
    HeartbeatIhmOk              : BOOL;         // <-- [STAT] TRUE apres front IHM post-boot et avant timeout
    HeartbeatIhmTimeout         : BOOL;         // <-- [DIAG] TRUE = aucun front IHM depuis IhmTimeout
    TglHeartbeatPlc             : BOOL;         // <-- [STAT] Clignotant PLC a superviser cote IHM
    TimeSinceIhmEdge            : TIME;         // <-- [DIAG] Temps ecoule depuis le dernier front IHM
END_VAR
VAR
    // === SOUS-INSTANCES FB ===
    IhmTimeoutTon               : TON;          // * [INST] Timer de surveillance timeout IHM
    PlcToggleTon                : TON;          // * [INST] Timer clignotant heartbeat PLC

    // === CALCULS ET ETATS INTERNES ===
    LastIhmToggle               : BOOL;         // . [LOC]  Memoire du dernier etat toggle IHM
    IhmEdgeSeen                 : BOOL;         // . [LOC]  Verrou front vu (interdit RETAIN au boot)
    IhmEdgeDetected             : BOOL;         // . [LOC]  Front de changement toggle IHM detecte
END_VAR

// === IMPLEMENTATION ===

{region "§1 Gate"}
// 🛑 Sans Enable, aucune valeur mémorisée ne peut déclarer l'IHM valide.
IF NOT Enable THEN
    HeartbeatIhmOk := FALSE;
    HeartbeatIhmTimeout := TRUE;
    TglHeartbeatPlc := FALSE;
    TimeSinceIhmEdge := T#0s;
    LastIhmToggle := TglHeartbeatIhm;
    IhmEdgeSeen := FALSE;
    IhmTimeoutTon(IN := FALSE, PT := IhmTimeout);
    PlcToggleTon(IN := FALSE, PT := PlcTogglePeriod);
    RETURN;
END_IF;
{endregion}

{region "§2 Front IHM"}
// 📥 Front par comparaison : l'IHM écrit un BOOL toggle, pas une impulsion courte.
IhmEdgeDetected := (TglHeartbeatIhm <> LastIhmToggle);
LastIhmToggle := TglHeartbeatIhm;
IF IhmEdgeDetected THEN
    IhmEdgeSeen := TRUE;
END_IF;
{endregion}

{region "§3 Timeout IHM"}
// ⏱️ Le timer repart à chaque front. Au boot, il atteint le timeout au bout de IhmTimeout.
// HeartbeatIhmOk reste TRUE tant que le timeout n'est pas expiré (boot propre sans alarme au scan 1).
IhmTimeoutTon(IN := NOT IhmEdgeDetected, PT := IhmTimeout);
TimeSinceIhmEdge := IhmTimeoutTon.ET;
HeartbeatIhmTimeout := IhmTimeoutTon.Q;
HeartbeatIhmOk := NOT HeartbeatIhmTimeout;
{endregion}

{region "§4 Clignotant PLC"}
// 💡 Clignotant PLC indépendant : information de vie pour l'IHM, jamais signal Signal Safety autonome.
PlcToggleTon(IN := NOT PlcToggleTon.Q, PT := PlcTogglePeriod);
IF PlcToggleTon.Q THEN
    TglHeartbeatPlc := NOT TglHeartbeatPlc;
END_IF;
{endregion}

(* ═══════════════════════════════════════════════════════════════
   🌉 FB_CfgPersistBridge_DredgingAssistCfg — Pont IHM/persistance prélèvement
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK FB_CfgPersistBridge_DredgingAssistCfg
VAR_IN_OUT
    Hmi     : ST_DredgingAssistCfg;
    Persist : ST_DredgingAssistCfg;
END_VAR
VAR_OUTPUT
    JustRestored : BOOL;
END_VAR

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   ST_CommunCfg — Configuration des paramètres communs machine
   ═══════════════════════════════════════════════════════════════ *)
TYPE ST_CommunCfg :
STRUCT
    // Blocage instantané à 0m : sans défaut explicite,
    // ce champ vaut 0.0 tant qu'il n'a pas été réglé côté IHM -- "CablePosM <= 0.0" se déclenche
    // dès la position de référence, avant tout réglage réel de la cote légale. Défaut -999.0
    // (jamais atteint en pratique) : LimitLegalEnabled=TRUE sans réglage ne bloque plus rien par
    // erreur -- il faut régler la vraie cote pour que la protection devienne active.
    LimitLegalDepthMinAllowed_M : REAL := -999.0; (* 📐 Cote min de dragage autorisée (m, négatif) *)
    LimitLegalEnabled           : BOOL; (* 🟢 Activation de la limite légale *)
    SelHomingApproachEnable     : BOOL; (* 🔌 Case IHM : autorise le dépassement butée haute pour homing (si MAINT_N2) *)
    WinchMaxStepDescente        : INT := 3;     (* 🛑 Limitation palier vitesse en descente (1..5), commun M1/M2 *)
    WinchMaxStepAscent          : INT := 5;     (* 🚀 Limitation palier vitesse en montée (1..5), commun M1/M2 *)
    WinchSlowdownDistance_M     : REAL := 1.0;  (* 📏 Distance avant limite pour enclencher le ralentissement (m), commun M1/M2 *)
    // : WinchSlowSpeed_Pct (%) retiré — un treuil ne connaît que des paliers (1..5),
    // pas une vitesse continue.
    WinchSlowdownMaxStep        : INT := 1;     (* : Plafond palier dans la zone de ralentissement (1..5), commun M1/M2 *)
    CfgCableLimitAscent_M       : REAL := 7.5;  (* 📐 Limite haute d'exploitation NORMALE (m), commun M1/M2 *)
    TglEnableKoboldAutoStopDescent : BOOL := FALSE; (* : Arrêt auto descente sur détection fond Kobold (pilotage normal) *)
    // Coupe-circuit d'urgence pour le séquencement auto benne.
    // Défaut FALSE = mouvement M1/M2 synchro jamais
    // gouverné par instBucket.Busy sauf action MANUELLE benne/DumpAtTremie/ExtractionSequence).
    TglEnableCoupledBucketSequencing : BOOL := FALSE;
    Initialized                 : BOOL := FALSE; (* 🚦 flag restauration boot *)
END_STRUCT
END_TYPE

(* ═══════════════════════════════════════════════════════════════
   📡 FB_AcquisitionLegacyBridge — Pont temporaire acquisition historique
   ───────────────────────────────────────────────────────────────
   📄 Docs : DOC/AF_Partie-06_Acquisition_Qualification_IO_v2.0.md §2 ;
            DOC/AF_Partie-13_Fonction_Simulation_v2.0.md
   ⚙️ Pont ST temporaire appelé exclusivement par PRG_02_Acquisition_CFC.xml.
   🎯 Rôle unique : produire l'image matérielle HwIn consommée par le reste
      du programme. Aucune décision métier (SafeStop, mode, commande) ici.
   🔗 Producteur unique de HwIn ; consommateurs = PRG_01_Inputs_LD et suivants.
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK FB_AcquisitionLegacyBridge

VAR_OUTPUT
    HwReal                   : ST_HardwareImage;  (* Image matérielle brute lue sur le terrain *)
    HwSim                    : ST_HardwareImage;  (* Image produite par le banc de simulation *)
    HwIn                     : ST_HardwareImage;  (* Image aiguillée réel/simulé *)
    WinchInputSourceChanged  : BOOL;              (* Pulse 1 cycle sur bascule réel/simulé domaine Winch *)

    // 🆕 Migration PRG_00_Inputs : positions Translation M3 exposées en sortie de programme
    TranslationPosTremie      : BOOL;   (* TRUE = translation en position Trémie *)
    TranslationPosPV          : BOOL;   (* TRUE = translation en zone pré-ralentissement PV *)
    TranslationPosP2          : BOOL;   (* TRUE = translation en position P2 *)
    TranslationPosP1          : BOOL;   (* TRUE = translation en position P1 *)
    TranslationPosMaintenance : BOOL;   (* TRUE = translation en position Maintenance *)

    // 🆕 Migration PRG_00_Inputs : retours variateur M3 filtrés (PT1 T#0MS = recopie legacy)
    M3_StatusWord_Filtered        : UINT;
    M3_ActualFrequencyHz_Filtered : UINT;

    // 🔗 Contrat public : anciennement lus à travers instPosDecoderM3.
    //    Les sorties rendent la migration XML transparente aux consommateurs.
    M3_LimitSwitchFwd          : BOOL;
    M3_LimitSwitchRev          : BOOL;
    M3_SensorWordIncoherent    : BOOL;
    M3_SensorsWord             : BYTE;
END_VAR

VAR
    (* ── Instances de traitement complexes ── *)
    instSimBench             : FB_SimBench;
    instJoystick             : FB_Joystick;
    instEncoderAbsM1         : FB_Encoder_Abs;
    instEncoderScaleM1       : FB_Encoder_Scale;
    instHomingM1             : FB_Encoder_Homing;
    instEncoderAbsM2         : FB_Encoder_Abs;
    instEncoderScaleM2       : FB_Encoder_Scale;
    instHomingM2             : FB_Encoder_Homing;
    instPosDecoderM3         : FB_Translation_PositionDecoder;

    (* ── Filtrage des retours variateur M3 (migration PRG_00_Inputs) ── *)
    instCycleTimeAcq            : FB_CycleTime;
    instFilterM3StatusWord      : FB_Filter_PT1;
    instFilterM3ActualFreqHz      : FB_Filter_PT1;

    (* ── Mémoire de la source Winch (front bascule réel/simulé) ── *)
    WinchInputSourceSimulated            : BOOL;
    PreviousWinchInputSourceSimulated    : BOOL;
    WinchInputSourceInitialized          : BOOL;
END_VAR

// === IMPLEMENTATION ===

// ─── §0 MATÉRIEL ──► HwReal (Acquisition brute unique) ─────────────────────────

// Winch M1 / M2 et codeurs
HwReal.Winch.M1_ContactorsReleased_DI := M1_ContactorsReleased_DI;
HwReal.Winch.M1_ThermalOk_DI          := M1_ThermalOk_DI;
HwReal.Winch.M1_BrakeIsOpen_DI        := M1_BrakeIsOpen_DI;

HwReal.Winch.M2_ContactorsReleased_DI := M2_ContactorsReleased_DI;
HwReal.Winch.M2_ThermalOk_DI          := M2_ThermalOk_DI;
HwReal.Winch.M2_BrakeIsOpen_DI        := M2_BrakeIsOpen_DI;

HwReal.Winch.M1M2_TopPositionFree_DI  := M1M2_TopPositionFree_DI;
HwReal.Winch.M2_TensionedCable_DI     := M2_TensionedCable_DI;

HwReal.Winch.COD1_PosValue            := COD1_PosValue;
HwReal.Winch.COD1_Alarms              := COD1_Alarms;
HwReal.Winch.COD1_Warnings            := COD1_Warnings;
HwReal.Winch.COD1_DeviceState         := COD1_CODEUR.GetDeviceState();

HwReal.Winch.COD2_PosValue            := COD2_PosValue;
HwReal.Winch.COD2_Alarms              := COD2_Alarms;
HwReal.Winch.COD2_Warnings            := COD2_Warnings;
HwReal.Winch.COD2_DeviceState         := COD2_CODEUR.GetDeviceState();

// Translation M3 et variateur AC600
HwReal.Translation.M3_PosTremie_DI      := M3_PosTremie_DI;
HwReal.Translation.M3_PosPV_DI          := M3_PosPV_DI;
HwReal.Translation.M3_PosP2_DI          := M3_PosP2_DI;
HwReal.Translation.M3_PosP1_DI          := M3_PosP1_DI;
HwReal.Translation.M3_PosMaintenance_DI := M3_PosMaintenance_DI;
HwReal.Translation.M3_BrakeIsOpen_DI    := M3_BrakeIsOpen_DI;
HwReal.Translation.M3_ThermalFeedback_DI:= M3_ThermalFeedback_DI; // 🆕 T96 — diagnostic seul (voie déjà mappée CODESYS, jamais lue jusqu'ici)
HwReal.Translation.M3_StatusWord        := M3_StatusWord;
HwReal.Translation.M3_ActualFrequencyHz := M3_ActualFrequencyHz;
HwReal.Translation.AC600_DeviceState    := AC600_ECAT_Drive.GetDeviceState();

// Opérateur / Joystick / bus CANopen
HwReal.Operator.JoyXRaw_ANA1      := JoyXRaw_ANA1;
HwReal.Operator.JoyYRaw_ANA2      := JoyYRaw_ANA2;
HwReal.Operator.JoyBtnRaw         := JoyBtnRaw;
HwReal.Operator.CanBusState       := CANbus.GetBusState();
HwReal.Operator.JOY1_DeviceState  := JOY1_JOYSTICK_MCB560_CO4201A.GetDeviceState();

// Sécurités / Communs Machine
HwReal.Machine.PowerContactorEngaged_DI   := PowerContactorEngaged_DI;
HwReal.Machine.EmergencyChainClosed_DI    := EmergencyChainClosed_DI;
HwReal.Machine.PhaseRotationOk_DI         := PhaseRotationOk_DI;
HwReal.Machine.BrakeThermalOk_DI          := BrakeThermalOk_DI;
HwReal.Machine.M1_M2_KoboldContactFond_DI := M1_M2_KoboldContactFond_DI;
HwReal.Machine.HydraulicThermalOk_DI      := HydraulicThermalOk_DI;


// ─── §0bis HwReal / SimBench ──► HwIn (Aiguillage simulation par domaine) ──────

instSimBench(
    Enable                   := GVL_Simulation.SimulationModeActive,
    M1_RelayFwd              := GVL_Global.M1RelayFwd,
    M1_RelayRev              := GVL_Global.M1RelayRev,
    M1_SpeedContactor_1      := GVL_Global.M1SpeedContactor1,
    M1_SpeedContactor_2      := GVL_Global.M1SpeedContactor2,
    M1_SpeedContactor_3      := GVL_Global.M1SpeedContactor3,
    M1_SpeedContactor_4      := GVL_Global.M1SpeedContactor4,
    M1_SpeedRefPct           := PRG_TREUILS_CFC.M1_SpeedRef_Active,
    M1_PresetTriggerCmd      := PRG_02_Encoders.instEncoderAbsM1.PresetTriggerCmd,
    M1_PresetValueOut        := PRG_02_Encoders.instEncoderAbsM1.PresetValueOut,
    M1_BrakeCmd              := GVL_Global.M1BrakeCmd,
    M2_RelayFwd              := GVL_Global.M2RelayFwd,
    M2_RelayRev              := GVL_Global.M2RelayRev,
    M2_SpeedContactor_1      := GVL_Global.M2SpeedContactor1,
    M2_SpeedContactor_2      := GVL_Global.M2SpeedContactor2,
    M2_SpeedContactor_3      := GVL_Global.M2SpeedContactor3,
    M2_SpeedContactor_4      := GVL_Global.M2SpeedContactor4,
    M2_SpeedRefPct           := PRG_TREUILS_CFC.M2_SpeedRef_Active,
    M2_PresetTriggerCmd      := PRG_02_Encoders.instEncoderAbsM2.PresetTriggerCmd,
    M2_PresetValueOut        := PRG_02_Encoders.instEncoderAbsM2.PresetValueOut,
    M2_BrakeCmd              := GVL_Global.M2BrakeCmd,
    M3_Direction             := PRG_TRANSLATION_CFC.M3_Direction_Active,
    M3_SpeedRefPct           := PRG_TRANSLATION_CFC.M3_SpeedRef_Active,
    M3_BrakeCmd              := GVL_Global.TranslationBrakeCmd,
    M3_TargetNum             := GVL_IHM.TranslationM3.Cmd.SelTarget,
    PowerKeepAlive_A         := PRG_10_Outputs_LD.PowerKeepAlive_A_RQ,
    PowerKeepAlive_B         := PRG_10_Outputs_LD.PowerKeepAlive_B_RQ,
    EmergencyArming_RQ       := PRG_10_Outputs_LD.EmergencyArming_RQ,
    SimEncoderSpeedFactor    := GVL_Simulation.SimEncoderSpeedFactor,
    SimSyncDeviationInjectM1 := GVL_Simulation.SimSyncDeviationInjectM1,
    SimSyncDeviationInjectM2 := GVL_Simulation.SimSyncDeviationInjectM2,
    SimSyncDeviationOffset_M := GVL_Simulation.SimSyncDeviationOffset_M,
    SimM3SensorsWordActive   := GVL_Simulation.SimM3SensorsWordActive,
    SimM3SensorsWord         := GVL_Simulation.SimM3SensorsWord,
    SimJoystickRawX          := GVL_Simulation.SimJoystickRawX,
    SimJoystickRawY          := GVL_Simulation.SimJoystickRawY,
    SimJoystickRawButton     := GVL_Simulation.SimJoystickRawButton,
    SimKoboldContactValue    := GVL_Simulation.SimKoboldContactValue,
    BtnEmergencyStop         := GVL_IHM.Modes.Cmd.BtnEmergencyCutOff,
    HwReal                   := HwReal,
    RawPosM1                 := _SimEncoderRawPosM1,
    RawPosM2                 := _SimEncoderRawPosM2
);

// 🧪 Image du banc exposée pour lecture côte à côte ; aucune logique métier ne lit HwSim.
HwSim.Winch       := instSimBench.Winch;
HwSim.Translation := instSimBench.Translation;
HwSim.Operator    := instSimBench.Operator;
HwSim.Machine     := instSimBench.Machine;

// 🔄 Source Winch atomique + pulse générique. Au boot, la source initiale est mémorisée sans faux pulse.
WinchInputSourceSimulated := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimWinchActive;
IF NOT WinchInputSourceInitialized THEN
    PreviousWinchInputSourceSimulated := WinchInputSourceSimulated;
    WinchInputSourceInitialized := TRUE;
    WinchInputSourceChanged := FALSE;
ELSE
    WinchInputSourceChanged := (WinchInputSourceSimulated <> PreviousWinchInputSourceSimulated);
    PreviousWinchInputSourceSimulated := WinchInputSourceSimulated;
END_IF;

// Aiguillage domaine par domaine (réel si simulateur inactif pour ce domaine).
IF WinchInputSourceSimulated
    THEN HwIn.Winch := instSimBench.Winch;             ELSE HwIn.Winch := HwReal.Winch;             END_IF;
IF GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimTranslationActive
    THEN HwIn.Translation := instSimBench.Translation; ELSE HwIn.Translation := HwReal.Translation; END_IF;
IF GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimOperatorActive
