(* ═══════════════════════════════════════════════════════════════
   🧪 FB_SimBench — Enveloppe unique de simulation pour banc d'essai
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF/AF_Partie-13_Fonction_Simulation_v2.3.md
   
   🎯 Rôle : Compose les 4 blocs de modèle de simulation existants :
      - FB_Sim_Encoder (instM1, instM2)
      - FB_Sim_Translation (instTranslation)
      - FB_Sim_Joystick (instJoystick)
      - FB_Sim_Safety (instSafety)
   
   🔒 Brique réduite : 0 lecture de variable globale en interne.
      Toutes les entrées (commandes, stimuli, HwReal) sont passées en paramètres.
   
   🔴 RÈGLES SÉCURITÉ ET POLARITÉ :
      - Modèle frein M1/M2/M3 : M1_BrakeIsOpen_DI := M1_BrakeCmd (1 = OUVERT).
        Ne JAMAIS faire NOT BrakeCmd !
      - Retours contacteurs M1/M2 : 1 = tous retombés (TRUE quand RelayFwd=0 et RelayRev=0).
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_SimBench
VAR_INPUT
    Enable                     : BOOL;             (* --> [CMD] Activation globale (GVL_Simulation.SimulationModeActive) *)

    // ── Commandes issues de l'automate (Scan N-1 / PRG_07 / PRG_10) ──────────
    M1_RelayFwd                : BOOL;   (* --> [CMD] Sens avant M1 *)
    M1_RelayRev                : BOOL;   (* --> [CMD] Sens arrière M1 *)
    // Les 4 contacteurs de palier participent au retour unique
    // « tous contacteurs retombés » — sans eux, le modèle annonce l'arrêt alors qu'un
    // palier est encore engagé (fausse condition d'armement Méca A).
    M1_SpeedContactor_1        : BOOL;   (* --> [HW] Contacteur palier 1 M1 *)
    M1_SpeedContactor_2        : BOOL;   (* --> [HW] Contacteur palier 2 M1 *)
    M1_SpeedContactor_3        : BOOL;   (* --> [HW] Contacteur palier 3 M1 *)
    M1_SpeedContactor_4        : BOOL;   (* --> [HW] Contacteur palier 4 M1 *)
    M1_SpeedRefPct             : REAL;   (* --> [CMD] Consigne vitesse M1 *)
    M1_PresetTriggerCmd        : WORD;   (* --> [CMD] Trigger preset M1 *)
    M1_PresetValueOut          : UDINT;   (* --> [CFG] Valeur preset M1 *)
    M1_BrakeCmd                : BOOL;             (* --> [CMD] TRUE = commande desserrage frein M1 *)

    M2_RelayFwd                : BOOL;   (* --> [CMD] Sens avant M2 *)
    M2_RelayRev                : BOOL;   (* --> [CMD] Sens arrière M2 *)
    M2_SpeedContactor_1        : BOOL;   (* --> [HW] Idem M1, voir ci-dessus *)
    M2_SpeedContactor_2        : BOOL;   (* --> [HW] Contacteur palier 2 M2 *)
    M2_SpeedContactor_3        : BOOL;   (* --> [HW] Contacteur palier 3 M2 *)
    M2_SpeedContactor_4        : BOOL;   (* --> [HW] Contacteur palier 4 M2 *)
    M2_SpeedRefPct             : REAL;   (* --> [CMD] Consigne vitesse M2 *)
    M2_PresetTriggerCmd        : WORD;   (* --> [CMD] Trigger preset M2 *)
    M2_PresetValueOut          : UDINT;   (* --> [CFG] Valeur preset M2 *)
    M2_BrakeCmd                : BOOL;             (* --> [CMD] TRUE = commande desserrage frein M2 *)

    M3_Direction               : INT;              (* --> [CMD] 1 = Avant, -1 = Arrière, 0 = Arrêt *)
    M3_SpeedRefPct             : REAL;   (* --> [CMD] Consigne vitesse M3 *)
    M3_BrakeCmd                : BOOL;             (* --> [CMD] TRUE = commande desserrage frein M3 *)

    PowerKeepAlive_A           : BOOL;             (* --> [SAFE] TRUE = relais A maintenu sagement par le PLC *)
    PowerKeepAlive_B           : BOOL;             (* --> [SAFE] TRUE = relais B maintenu sagement par le PLC *)
    EmergencyArming_RQ         : BOOL;             (* --> [CMD] Impulsion de réarmement puissance *)

    // ── Stimuli & Paramètres de banc ─────────────────────────────────────────
    SimEncoderSpeedFactor      : REAL := 1.0;   (* --> [CFG] Facteur vitesse codeur *)
    SimSyncDeviationInjectM1   : BOOL := FALSE;   (* --> [TST] Injection écart synchro M1 *)
    SimSyncDeviationInjectM2   : BOOL := FALSE;   (* --> [TST] Injection écart synchro M2 *)
    SimSyncDeviationOffset_M   : REAL := 0.5;   (* --> [TST] Offset écart synchro *)

    SimM3SensorsWordOverrideActive : BOOL := FALSE;   (* --> [TST] Override mot capteurs M3 *)
    SimM3SensorsWord               : BYTE := 16#07;   (* --> [TST] Mot capteurs M3 forcé *)

    SimJoystickLeft_Rev_TREMIE_Active  : BOOL := FALSE;   (* --> [TST] Bouton joystick gauche *)
    SimJoystickRight_Fwd_MAINT_Active  : BOOL := FALSE;   (* --> [TST] Bouton joystick droite *)
    SimJoystickFwd_Up_Close_Active     : BOOL := FALSE;   (* --> [TST] Bouton joystick avant *)
    SimJoystickRev_Down_Open_Active    : BOOL := FALSE;   (* --> [TST] Bouton joystick arrière *)
    SimJoystickRawX                    : INT := 5000;   (* --> [TST] Valeur brute X *)
    SimJoystickRawY                    : INT := 5000;   (* --> [TST] Valeur brute Y *)
    SimJoystickRawButton               : BOOL := FALSE;   (* --> [TST] Bouton homme-mort *)

    SimKoboldContactValue      : BOOL := FALSE;   (* --> [TST] Contact fond Kobold *)
    BtnEmergencyStop           : BOOL := FALSE;    (* --> [TST] Simulation appui coup-de-poing AU *)

    // ── Image réelle fallback ────────────────────────────────────────────────
    HwReal                     : ST_HardwareImage;   (* --> [HW] Image réelle fallback *)
END_VAR

VAR_OUTPUT
    (* Sorties d'état du profil AF_Partie-03 §2.
       En LD, CODESYS réserve la PREMIÈRE broche de sortie au flux du rung :
       `Ready` n'y porte jamais d'expression, les broches suivantes oui. *)
    Ready                      : BOOL;             (* <-- [STAT] TRUE = banc prêt (Enable actif, modèles à jour) *)
    Busy                       : BOOL;             (* <-- [STAT] TRUE = cycle de simulation en cours *)
    Done                       : BOOL;             (* <-- [STAT] TRUE = images de simulation publiées ce scan *)

    Winch                      : ST_HwWinch;   (* <-- [DIAG] Image treuils simulée *)
    Translation                : ST_HwTranslation;   (* <-- [DIAG] Image translation simulée *)
    Operator                   : ST_HwOperator;   (* <-- [DIAG] Image opérateur simulée *)
    Machine                    : ST_HwMachine;   (* <-- [DIAG] Image machine simulée *)
END_VAR

VAR_IN_OUT
    RawPosM1                   : UDINT;            (* <-> [BUS] Mémoire _SimEncoderRawPosM1 dans GVL_PERSISTENT *)
    RawPosM2                   : UDINT;            (* <-> [BUS] Mémoire _SimEncoderRawPosM2 dans GVL_PERSISTENT *)
END_VAR

VAR CONSTANT
    CST_M3FullTravelTimeS       : REAL := 8.0; // Temps de Trémie à Maintenance à 100 %, modèle banc uniquement
END_VAR

VAR
    // Modèles sous-jacents
    instSimEncoderM1           : FB_Sim_Encoder;   (* * [INST] Modèle codeur M1 *)
    instSimEncoderM2           : FB_Sim_Encoder;   (* * [INST] Modèle codeur M2 *)
    instSimTranslation         : FB_Sim_Translation;   (* * [INST] Modèle translation M3 *)
    instSimJoystick            : FB_Sim_Joystick;   (* * [INST] Modèle joystick *)
    instSimSafety              : FB_Sim_Safety;   (* * [INST] Modèle sécurité *)

    // Calculs internes
    M1_PresetCmd               : BOOL;   (* . [LOC] Trigger preset M1 *)
    M2_PresetCmd               : BOOL;   (* . [LOC] Trigger preset M2 *)
    M1_OffsetPts               : DINT;   (* . [LOC] Offset synchro M1 *)
    M2_OffsetPts               : DINT;   (* . [LOC] Offset synchro M2 *)

    M3_RelayFwd                : BOOL;   (* . [LOC] Sens avant M3 *)
    M3_RelayRev                : BOOL;   (* . [LOC] Sens arrière M3 *)

    SimJoystickDirectionCount  : INT;   (* . [LOC] Nombre de directions actives *)

    M3_ActualFreqHz            : UINT;   (* . [LOC] Fréquence simulée M3 *)
    M3_StatusWordSim           : WORD;   (* . [LOC] StatusWord simulé M3 *)
END_VAR

// === IMPLEMENTATION ===

{region "§1 Repli image reelle banc desactive"}
IF NOT Enable THEN
    // 🔌 Banc désactivé : repli sur l'image réelle, aucune simulation en cours
    Ready       := FALSE;
    Busy        := FALSE;
    Done        := FALSE;
    Winch       := HwReal.Winch;
    Translation := HwReal.Translation;
    Operator    := HwReal.Operator;
    Machine     := HwReal.Machine;
    RETURN;
END_IF;

// ▶️ Banc actif : le cycle de simulation démarre pour ce scan
Ready := TRUE;
Busy  := TRUE;
Done  := FALSE;


{endregion}

{region "§2 Simulation treuils M1/M2"}
// ── 1. MODÈLE TREUILS (M1 + M2) ─────────────────────────────────────────────
// Presets codeurs : déclenchés si PresetTriggerCmd = 2
M1_PresetCmd := (M1_PresetTriggerCmd = 2);
M2_PresetCmd := (M2_PresetTriggerCmd = 2);

// Conversions d'injection d'écart synchro (0.5m -> points codeur avec 8192 pts/tour, 2m/tour)
// 1m = 4096 points codeur.
M1_OffsetPts := REAL_TO_DINT(SimSyncDeviationOffset_M * 4096.0);
M2_OffsetPts := REAL_TO_DINT(SimSyncDeviationOffset_M * 4096.0);

// Instance modèle codeur M1
instSimEncoderM1(
    Enable           := TRUE,
    RelayFwd         := M1_RelayFwd,
    RelayRev         := M1_RelayRev,
    SpeedRefPct      := M1_SpeedRefPct,
    PresetCmd        := M1_PresetCmd,
    PresetValue      := M1_PresetValueOut,
    SpeedScaleFactor := SimEncoderSpeedFactor,
    TestOffsetCmd    := SimSyncDeviationInjectM1,
    TestOffsetPts    := M1_OffsetPts,
    RawPos           := RawPosM1
);

// Instance modèle codeur M2
instSimEncoderM2(
    Enable           := TRUE,
    RelayFwd         := M2_RelayFwd,
    RelayRev         := M2_RelayRev,
    SpeedRefPct      := M2_SpeedRefPct,
    PresetCmd        := M2_PresetCmd,
    PresetValue      := M2_PresetValueOut,
    SpeedScaleFactor := SimEncoderSpeedFactor,
    TestOffsetCmd    := SimSyncDeviationInjectM2,
    TestOffsetPts    := M2_OffsetPts,
    RawPos           := RawPosM2
);

// Recopie structures Winch simulées :
// 🛑 POLARITÉ DE FREIN SIMULÉ : 1 = contacteur commandé = frein OUVERT.
// Câblage réel : DI = 1 ⟺ frein OUVERT. Le modèle produit donc M1_BrakeIsOpen_DI := M1_BrakeCmd !
Winch.M1_BrakeIsOpen_DI        := M1_BrakeCmd;
// Retour UNIQUE « tous contacteurs retombés » = sens ET vitesse.
// Omettre les paliers ferait croire à l'arrêt pendant les transitoires → Méca A armée à tort.
Winch.M1_ContactorsReleased_DI := NOT (M1_RelayFwd OR M1_RelayRev
                                    OR M1_SpeedContactor_1 OR M1_SpeedContactor_2
                                    OR M1_SpeedContactor_3 OR M1_SpeedContactor_4);
Winch.M1_ThermalOk_DI          := TRUE; // Sauf panne simulée

Winch.M2_BrakeIsOpen_DI        := M2_BrakeCmd;
Winch.M2_ContactorsReleased_DI := NOT (M2_RelayFwd OR M2_RelayRev
                                    OR M2_SpeedContactor_1 OR M2_SpeedContactor_2
                                    OR M2_SpeedContactor_3 OR M2_SpeedContactor_4);
Winch.M2_ThermalOk_DI          := TRUE;

Winch.M1M2_TopPositionFree_DI  := TRUE; // Butée libre au repos en simu
Winch.M2_TensionedCable_DI     := TRUE; // Câble tendu en simu

Winch.COD1_PosValue            := instSimEncoderM1.RawPosOut;
Winch.COD1_Alarms              := 0;
Winch.COD1_Warnings            := 0;
Winch.COD1_DeviceState         := DEVICE_STATE.RUNNING; // État device RUNNING (bus OK)

Winch.COD2_PosValue            := instSimEncoderM2.RawPosOut;
Winch.COD2_Alarms              := 0;
Winch.COD2_Warnings            := 0;
Winch.COD2_DeviceState         := DEVICE_STATE.RUNNING; // État device RUNNING


{endregion}

{region "§3 Simulation translation M3"}
// ── 2. MODÈLE TRANSLATION M3 (AC600) ─────────────────────────────────────────
M3_RelayFwd := (M3_Direction = 1);
M3_RelayRev := (M3_Direction = -1);

instSimTranslation(
    Enable          := TRUE,
    Direction       := M3_Direction,
    SpeedRefPct     := M3_SpeedRefPct,
    FullTravelTimeS := CST_M3FullTravelTimeS
);

// Remplissage capteurs de position M3 : l'override manuel conserve exactement le
// même ordre que FB_Translation_PositionDecoder (bit4=Trémie ... bit0=Maintenance).
IF SimM3SensorsWordOverrideActive THEN
    Translation.M3_PosTremie_DI      := SimM3SensorsWord.4;
    Translation.M3_PosPV_DI          := SimM3SensorsWord.3;
    Translation.M3_PosPVP2_DI        := SimM3SensorsWord.2;
    Translation.M3_PosP1_DI          := SimM3SensorsWord.1;
    Translation.M3_PosMaintenance_DI := SimM3SensorsWord.0;
ELSE
    Translation.M3_PosTremie_DI      := instSimTranslation.PosTremie;
    Translation.M3_PosPV_DI          := instSimTranslation.PosPV;
    Translation.M3_PosPVP2_DI        := instSimTranslation.PosP2;
    Translation.M3_PosP1_DI          := instSimTranslation.PosP1;
    Translation.M3_PosMaintenance_DI := instSimTranslation.PosMaintenance;
END_IF;

// Polarité frein M3 (1 = OUVERT)
Translation.M3_BrakeIsOpen_DI    := M3_BrakeCmd;

// Thermique moteur/variateur AC600 — pas de panne simulée, toujours OK (comme Winch.M1/M2_ThermalOk_DI)
Translation.M3_ThermalOK_DI      := TRUE;

// Simulation StatusWord AC600 : Bit 0 (Power Ready) = 1, Bit 7 (Comm Ready) = 1 -> 16#0087 en mouvement
// Bit0 retombe à l'arrêt, cohérent avec un variateur qui confirme l'arrêt sans rester "actif" —
// FB_Safety_Translation lit ce bit comme indicateur "mouvement non commandé" (Méca B, TonMecaB 3s) :
// un Bit0 forcé à 1 en continu à l'arrêt déclencherait un PowerCutOff simulé permanent après 3s.
// DrivePowerReady (diagnostic IHM seul, non consommé par un interlock) est le seul autre lecteur,
// aucune régression de mouvement possible.
IF (M3_Direction <> 0) THEN
    M3_StatusWordSim := 16#0087; // + Operating/Running
    M3_ActualFreqHz  := REAL_TO_UINT(M3_SpeedRefPct * 50.0); // 50.0 Hz à 100% (x100 -> 5000)
ELSE
    M3_StatusWordSim := 16#0080; // Comm Ready seul -- Bit0 retombé, arrêt confirmé
    M3_ActualFreqHz  := 0;
END_IF;

Translation.M3_StatusWord        := M3_StatusWordSim;
Translation.M3_ActualFrequencyHz := M3_ActualFreqHz;
Translation.AC600_DeviceState    := DEVICE_STATE.RUNNING; // État device RUNNING


{endregion}

{region "§4 Simulation operateur joystick"}
// ── 3. MODÈLE OPÉRATEUR / JOYSTICK ───────────────────────────────────────────
instSimJoystick(
    Enable     := TRUE,
    NeutralRaw := 5000,
    MaxRaw     := 10000
);

// Les boutons directionnels simplifient les essais : une commande unique impose
// une butée d'axe ; aucune commande ou une combinaison reste au neutre / stimulus avancé.
SimJoystickDirectionCount := BOOL_TO_INT(SimJoystickLeft_Rev_TREMIE_Active)
                           + BOOL_TO_INT(SimJoystickRight_Fwd_MAINT_Active)
                           + BOOL_TO_INT(SimJoystickFwd_Up_Close_Active)
                           + BOOL_TO_INT(SimJoystickRev_Down_Open_Active);
IF SimJoystickDirectionCount = 1 THEN
    IF SimJoystickLeft_Rev_TREMIE_Active THEN
        Operator.JoyXRaw_ANA1 := 0;
        Operator.JoyYRaw_ANA2 := 5000;
    ELSIF SimJoystickRight_Fwd_MAINT_Active THEN
        Operator.JoyXRaw_ANA1 := 10000;
        Operator.JoyYRaw_ANA2 := 5000;
    ELSIF SimJoystickFwd_Up_Close_Active THEN
        Operator.JoyXRaw_ANA1 := 5000;
        Operator.JoyYRaw_ANA2 := 10000;
    ELSE
        Operator.JoyXRaw_ANA1 := 5000;
        Operator.JoyYRaw_ANA2 := 0;
    END_IF;
ELSIF SimJoystickDirectionCount > 1 THEN
    // Deux directions simultanées ne créent jamais une diagonale / un double mouvement implicite.
    Operator.JoyXRaw_ANA1 := 5000;
    Operator.JoyYRaw_ANA2 := 5000;
ELSE
    Operator.JoyXRaw_ANA1 := SimJoystickRawX;
    Operator.JoyYRaw_ANA2 := SimJoystickRawY;
END_IF;

// Homme-mort : stimulus brut amont. En simulation avec boutons directionnels actifs,
// l'appui homme-mort est automatiquement inclus pour faciliter les essais sur banc.
Operator.JoyBtnRaw := SimJoystickRawButton OR (SimJoystickDirectionCount > 0);

Operator.CanBusState      := 2; // CANbusState 2 = ACTIVE
Operator.JOY1_DeviceState := DEVICE_STATE.RUNNING; // État device RUNNING


{endregion}

{region "§5 Simulation securite et image machine"}
// ── 4. MODÈLE SÉCURITÉ & COMMUNS MACHINE ─────────────────────────────────────
instSimSafety(
    Enable           := TRUE,
    PowerCutOff_A    := PowerKeepAlive_A,
    PowerCutOff_B    := PowerKeepAlive_B,
    EmergencyArming  := EmergencyArming_RQ,
    BtnEmergencyStop := BtnEmergencyStop
);

Machine.PowerContactorEngaged_DI   := instSimSafety.SimContactorOk;
Machine.EmergencyChainClosed_DI    := instSimSafety.SimChainOk;
Machine.PhaseRotationOk_DI             := TRUE;
Machine.M1_M2_M3_BrakeThermalOk_DI     := TRUE;
Machine.M1_M2_KoboldBottomTouch_DI     := SimKoboldContactValue;
Machine.HydraulicThermalOk_DI          := TRUE;
Machine.HopperFull_OR_GateRaised_DI    := FALSE; // Pas encore câblé, simulé inactif par défaut

// ✅ Cycle de simulation terminé : les 4 images sont publiées pour ce scan
Busy := FALSE;
Done := TRUE;

{endregion}

(* ═══════════════════════════════════════════════════════════════
   🧪 PRG_Test_KoboldMaintenance — Tests PLC isolés T81/T82
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF_Partie-04_Mode_SemiAuto_Sequenceur_v2.0.md §3ter
   ⚠️ Programme de qualification MANUELLE : non appelé par MainTask.
      L'opérateur l'appelle temporairement dans une tâche de test, pose TestEnable,
      puis lit Passed/Failed. Aucun accès E/S, aucun ordre machine.
   ═══════════════════════════════════════════════════════════════ *)
PROGRAM PRG_Test_KoboldMaintenance
VAR_INPUT
    TestEnable : BOOL;
    ResetTests : BOOL;
END_VAR
VAR_OUTPUT
    Busy       : BOOL;
    Passed     : BOOL;
    Failed     : BOOL;
    ErrorId    : WORD; (* bit0 Dive valide, bit1 Dive invalide, bit2 Extraction, bit3 défaut extraction *)
END_VAR
VAR
    ResetEdge        : R_TRIG;
    DiveValid        : FB_DiveSearch;
    DiveInvalid      : FB_DiveSearch;
    ExtractionValid  : FB_ExtractionSequence;
    ExtractionInvalid: FB_ExtractionSequence;
    DiveValidStep    : INT;
    DiveInvalidStep  : INT;
    ExtractionStep   : INT;
    DiveKobold       : BOOL;
    DiveMotion       : BOOL;
    DivePosition_M   : REAL;
    InvalidKobold    : BOOL;
    InvalidMotion    : BOOL;
    InvalidPosition_M: REAL;
    ExtractionMotion : BOOL;
    ExtractionClosed : BOOL;
    ExtractionBusy   : BOOL;
    ExtractionPos_M  : REAL;
END_VAR

ResetEdge(CLK := ResetTests);
IF ResetEdge.Q OR NOT TestEnable THEN
    Busy := FALSE; Passed := FALSE; Failed := FALSE; ErrorId := 16#0000;
    DiveValidStep := 0; DiveInvalidStep := 0; ExtractionStep := 0;
    DiveKobold := FALSE; DiveMotion := FALSE; DivePosition_M := 1.0;
    InvalidKobold := FALSE; InvalidMotion := FALSE; InvalidPosition_M := 1.0;
    ExtractionMotion := FALSE; ExtractionClosed := FALSE; ExtractionBusy := FALSE; ExtractionPos_M := 0.0;
ELSE
    Busy := NOT Passed AND NOT Failed;

    (* TC-KM-01 : Kobold hors eau 0 → immersion 1 dans fenêtre → fond 0. *)
    CASE DiveValidStep OF
        0: DiveMotion := FALSE; DiveKobold := FALSE; DivePosition_M := 1.0; DiveValidStep := 1;
        1: DiveMotion := FALSE; DiveKobold := FALSE; DivePosition_M := 1.0; DiveValidStep := 2;
        2: DiveMotion := TRUE;  DiveKobold := FALSE; DivePosition_M := 0.4; DiveValidStep := 3;
        3: DiveMotion := TRUE;  DiveKobold := TRUE;  DivePosition_M := 0.0; DiveValidStep := 4;
        4: DiveMotion := TRUE;  DiveKobold := TRUE;  DivePosition_M := -0.1; DiveValidStep := 5;
        5: DiveMotion := TRUE;  DiveKobold := FALSE; DivePosition_M := -0.2; DiveValidStep := 6;
    END_CASE;

    (* TC-KM-02 : front immersion hors fenêtre → T82 / ErrorId bit1. *)
    CASE DiveInvalidStep OF
        0: InvalidMotion := FALSE; InvalidKobold := FALSE; InvalidPosition_M := 1.0; DiveInvalidStep := 1;
        1: InvalidMotion := FALSE; InvalidKobold := FALSE; InvalidPosition_M := 1.0; DiveInvalidStep := 2;
        2: InvalidMotion := TRUE;  InvalidKobold := FALSE; InvalidPosition_M := 0.4; DiveInvalidStep := 3;
        3: InvalidMotion := TRUE;  InvalidKobold := TRUE;  InvalidPosition_M := 0.7; DiveInvalidStep := 4;
    END_CASE;

    (* TC-KM-03 : fond → fermeture → palier 1 sur 2 m → montée nominale. *)
    CASE ExtractionStep OF
        0: ExtractionMotion := FALSE; ExtractionClosed := FALSE; ExtractionBusy := FALSE; ExtractionPos_M := 0.0; ExtractionStep := 1;
        1: ExtractionMotion := FALSE; ExtractionStep := 2;
        2: ExtractionMotion := TRUE;  ExtractionStep := 3;
        3: ExtractionMotion := TRUE;  ExtractionClosed := FALSE; ExtractionBusy := TRUE; ExtractionStep := 4;
        4: ExtractionMotion := TRUE;  ExtractionClosed := TRUE;  ExtractionBusy := FALSE; ExtractionPos_M := 0.0; ExtractionStep := 5;
        5: ExtractionMotion := TRUE;  ExtractionPos_M := 0.0; ExtractionStep := 6;
        6: ExtractionMotion := TRUE;  ExtractionPos_M := 2.0; ExtractionStep := 7;
    END_CASE;
END_IF;

DiveValid(
    Enable := TestEnable, Reset := FALSE, PowerContactorEngaged := TRUE, Mode := E_Mode.MAINT_N1,
    MotionRequestActive := DiveMotion, MotionDirection := -1, BucketIsOpen := TRUE,
    KoboldImmersed := DiveKobold, M1Position_M := DivePosition_M, M2Position_M := DivePosition_M,
    PositionsValid := TRUE, DiveStartMin_M := 1.0, ImmersionUpper_M := 0.5, ImmersionLower_M := -0.5
);
DiveInvalid(
    Enable := TestEnable, Reset := FALSE, PowerContactorEngaged := TRUE, Mode := E_Mode.MAINT_N1,
    MotionRequestActive := InvalidMotion, MotionDirection := -1, BucketIsOpen := TRUE,
    KoboldImmersed := InvalidKobold, M1Position_M := InvalidPosition_M, M2Position_M := InvalidPosition_M,
    PositionsValid := TRUE, DiveStartMin_M := 1.0, ImmersionUpper_M := 0.5, ImmersionLower_M := -0.5
);
ExtractionValid(
    Enable := TestEnable, Reset := FALSE, PowerContactorEngaged := TRUE, Mode := E_Mode.MAINT_N1,
    MotionRequestActive := ExtractionMotion, MotionDirection := 1, BottomPositionConfirmed := TRUE,
    BucketIsClosed := ExtractionClosed, BucketBusy := ExtractionBusy, BucketError := FALSE,
    WinchSyncError := FALSE, M1Position_M := ExtractionPos_M, M2Position_M := ExtractionPos_M,
    M1MeasuredSpeedValid := TRUE, M2MeasuredSpeedValid := TRUE, PositionsValid := TRUE,
    ControlAscentDistance_M := 2.0
);
ExtractionInvalid(
    Enable := TestEnable, Reset := FALSE, PowerContactorEngaged := TRUE, Mode := E_Mode.MAINT_N1,
    MotionRequestActive := FALSE, MotionDirection := 0, BottomPositionConfirmed := FALSE,
    BucketIsClosed := FALSE, BucketBusy := FALSE, BucketError := FALSE, WinchSyncError := FALSE,
    M1Position_M := 0.0, M2Position_M := 0.0, M1MeasuredSpeedValid := TRUE,
    M2MeasuredSpeedValid := TRUE, PositionsValid := TRUE, ControlAscentDistance_M := 0.0
);

IF DiveValid.BottomTouchConfirmed THEN ErrorId := ErrorId OR 16#0001; END_IF;
IF DiveInvalid.Error AND ((DiveInvalid.ErrorId AND 16#0002) <> 16#0000) THEN ErrorId := ErrorId OR 16#0002; END_IF;
IF (ExtractionValid.ExtractionState = E_ExtractionSequenceState.CONTROL_ASCENT)
   AND ExtractionValid.ForceMinSpeedStep THEN ErrorId := ErrorId OR 16#0004; END_IF;
IF ExtractionValid.ExtractionState = E_ExtractionSequenceState.NOMINAL_ASCENT
   AND ExtractionValid.AscentPermit THEN ErrorId := ErrorId OR 16#0004; END_IF;
IF ExtractionInvalid.Error AND ((ExtractionInvalid.ErrorId AND 16#0008) <> 16#0000) THEN ErrorId := ErrorId OR 16#0008; END_IF;

IF (ErrorId AND 16#000F) = 16#000F THEN
    Passed := TRUE;
    Busy := FALSE;
END_IF;

(* =======================================================================
   🛡️ FB_Safety_EmergencyManagementLogic — Décision & Séquencement AU
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Machine d'état, fronts Reset/Arm, calcul ErrorId & consignes logiques
   🔒 Pattern Cause/Ack : Reset non conditionné, interlock sur Cause brute, debounce IHM + Ack
   📄 Doc métier : DOC/AF/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_Safety_EmergencyManagementLogic
VAR_INPUT
    // === COMMANDES & CONSIGNES ===
    Enable                  : BOOL; // --> [CMD]  Active la surveillance (TRUE = autorise)
    Reset                   : BOOL; // --> [CMD]  Front acquittement defauts
    ArmRequest              : BOOL; // --> [CMD]  Demande de rearmement (BtnEmergencyArming)
    PowerCutOffRequest      : BOOL; // --> [SAFE] Requete de coupure logique issue des metiers
    BtnEmergencyCutOff      : BOOL; // --> [CMD]  Commande d'ouverture d'urgence depuis l'IHM

    // === RETOURS MATERIELS (HW) ===
    EmergencyChainClosed    : BOOL; // --> [HW]   Retour physique boucle d'urgence amont contacteur
    PowerContactorEngaged   : BOOL; // --> [HW]   Confirmation contacteur de puissance principal
END_VAR
VAR_OUTPUT
    // === ERREURS & CONSIGNES LOGIQUES ===
    Error                   : BOOL; // <-- [DIAG] Synthese defaut actif
    ErrorId                 : WORD; // <-- [DIAG] Bitfield erreurs (bit0:Redundancy, bit1:Arming, bit3:Startup)
    Cmd                     : ST_Safety_Emergency_InternalCmd; // <-- [STAT] Structure de commande logique produite

    // === DIAGNOSTICS & RETOURS D'ETAT ===
    ArmingSeqStep                : INT;  // <-- [DIAG] Etape sequence (0=IDLE, 1=TestA, 2=RestoreA, 3=TestB, 4=RestoreB, 5=Pulse, 6=Confirm)
    RedundancyTestFailed         : BOOL; // <-- [DIAG] Defaut auto-test redondance (Cause lissee OR NOT Ack)
    EmergencyArmingFailed        : BOOL; // <-- [DIAG] Defaut rearmement contacteur (Cause lissee OR NOT Ack)
    EmergencyArmingLockoutActive : BOOL; // <-- [DIAG] Verrouillage temporel 5s entre essais
    Armable                      : BOOL; // <-- [STAT] Rearmement possible actuellement
    ArmingBusy                   : BOOL; // <-- [STAT] Sequence ou lockout en cours
    StartupFail                  : BOOL; // <-- [DIAG] Autotest demarrage echoue
END_VAR
VAR
    // === DETECTEURS DE FRONT INTERNES ===
    ResetEdge               : R_TRIG; // . [LOC] Detecteur front montant Reset
    ArmReqEdge              : R_TRIG; // . [LOC] Detecteur front montant ArmRequest
    EnableRising            : R_TRIG; // . [LOC] Detecteur front montant Enable
    RedundancyCauseEdge     : R_TRIG; // . [LOC] Detecteur nouvelle occurrence cause redondance
    ArmingFailedCauseEdge   : R_TRIG; // . [LOC] Detecteur nouvelle occurrence cause rearmement

    // === DRAPEAUX & FORCAGES LOGIQUES ===
    ForceTestA              : BOOL; // . [LOC] Forcage coupure canal A pendant test
    ForceTestB              : BOOL; // . [LOC] Forcage coupure canal B pendant test
    StartupCheckDone        : BOOL; // . [LOC] Autotest demarrage effectue
    StartupCheckOK          : BOOL; // . [LOC] Resultat autotest demarrage (latche)

    // === CAUSE & ACK DEFAUT REDONDANCE ===
    RedundancyTestFailedCause : BOOL;         // . [LOC] Cause brute : canal colle detecte a l'auto-test
    RedundancyTestFailedAck   : BOOL := TRUE; // . [LOC] Accuse operateur (TRUE = pas d'alarme a afficher)

    // === CAUSE & ACK DEFAUT REARMEMENT ===
    EmergencyArmingFailedCause : BOOL;         // . [LOC] Cause brute : contacteur non confirme sous 2s
    EmergencyArmingFailedAck   : BOOL := TRUE; // . [LOC] Accuse operateur (TRUE = pas d'alarme a afficher)

    // === TEMPORISATEURS LOGIQUES ===
    TonTestA                : TON; // . [LOC] Timer auto-test canal A
    TonRestoreA             : TON; // . [LOC] Timer restauration canal A
    TonTestB                : TON; // . [LOC] Timer auto-test canal B
    TonRestoreB             : TON; // . [LOC] Timer restauration canal B
    TonArmingPulse          : TON; // . [LOC] Timer impulsion rearmement
    TonArmingConfirm        : TON; // . [LOC] Timer attente confirmation contacteur
    TonArmingLockout        : TON; // . [LOC] Timer lockout anti-reessai
    TonRedundancyDisplay    : TON; // . [LOC] Timer debounce affichage IHM redondance
    TonArmingFailedDisplay  : TON; // . [LOC] Timer debounce affichage IHM rearmement
END_VAR
VAR CONSTANT
    // === TEMPORISATIONS NORMATIVES DE SECURITE (FIXES) ===
    CST_TestDuration         : TIME := T#200ms; // Duree auto-test canal A ou B
    CST_ArmingPulseDuration  : TIME := T#1s;    // Duree impulsion rearmement contacteur
    CST_ArmingConfirmTimeout : TIME := T#2s;    // Timeout confirmation engagement contacteur
    CST_ArmingLockout        : TIME := T#5s;    // Duree verrouillage anti-reessai apres echec
    CST_FaultDisplayDebounce : TIME := T#200ms; // Anti-clignotement affichage IHM uniquement
END_VAR

// === IMPLEMENTATION ===

{region "§1 Fronts de commande"}
// 🔄 Fronts
EnableRising(CLK := Enable);
ResetEdge(CLK := Reset);
ArmReqEdge(CLK := ArmRequest);

{endregion}

{region "§2 Gate neutralisation"}
// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    Error := FALSE;
    ErrorId := 16#0000;
    Cmd.MaintainA_Cmd := FALSE;
    Cmd.MaintainB_Cmd := FALSE;
    Cmd.ArmPulse_Cmd := FALSE;
    ArmingSeqStep := 0;
    RedundancyTestFailed := FALSE;
    EmergencyArmingFailed := FALSE;
    EmergencyArmingLockoutActive := FALSE;
    ForceTestA := FALSE;
    ForceTestB := FALSE;
    Armable := FALSE;
    ArmingBusy := FALSE;
    StartupFail := FALSE;
    StartupCheckDone := FALSE;
    StartupCheckOK := FALSE;
    // 🩹 Neutralisation = coupure surveillance, pas un defaut : Cause et Ack repartent propres
    RedundancyTestFailedCause := FALSE;
    RedundancyTestFailedAck := TRUE;
    EmergencyArmingFailedCause := FALSE;
    EmergencyArmingFailedAck := TRUE;
    TonTestA(IN := FALSE);
    TonRestoreA(IN := FALSE);
    TonTestB(IN := FALSE);
    TonRestoreB(IN := FALSE);
    TonArmingPulse(IN := FALSE);
    TonArmingConfirm(IN := FALSE);
    TonArmingLockout(IN := FALSE);
    TonRedundancyDisplay(IN := FALSE);
    TonArmingFailedDisplay(IN := FALSE);
    RETURN;
END_IF;

{endregion}

{region "§3 Autotest demarrage"}
// 🏁 2. AUTOTEST DÉMARRAGE (§5.4 AF01)
// Vérifications synchrones 1 cycle au premier passage Enable=TRUE
IF EnableRising.Q THEN
    StartupCheckDone := FALSE;
END_IF;

IF NOT StartupCheckDone THEN
    // Exécute les 4 contrôles en 1 cycle
    StartupCheckOK := EmergencyChainClosed          // 1. Boucle AU fermée
                      AND NOT PowerContactorEngaged // 2. Contacteur au repos
                      AND (ArmingSeqStep = 0);      // 4. Pas de séquence résiduelle
    StartupCheckDone := TRUE;
    StartupFail := NOT StartupCheckOK;
    IF NOT StartupCheckOK THEN
        ErrorId := 16#0008; // bit3 = startup autotest fail
        Error := TRUE;
    END_IF;
    RETURN; // 1 cycle pour laisser le temps aux entrées de se stabiliser
END_IF;

{endregion}

{region "§4 Acquittement defauts"}
// 🔍 3. ACQUITTEMENT DES DÉFAUTS (pattern Cause/Ack — §3.4bis AF01, §9 STD)
// ⚠️ Reset TOUJOURS effectif, efface l'affichage (Ack:=TRUE) et réinitialise Cause:=FALSE
// pour permettre une nouvelle tentative d'armement sans blocage IHM. Si le défaut persiste,
// la nouvelle tentative re-latchera Cause:=TRUE et Ack:=FALSE (TC-P01-009).
IF ResetEdge.Q THEN
    RedundancyTestFailedAck := TRUE;
    EmergencyArmingFailedAck := TRUE;
    RedundancyTestFailedCause := FALSE;
    EmergencyArmingFailedCause := FALSE;
    StartupFail := FALSE;
    ErrorId := 16#0000;
END_IF;

{endregion}

{region "§5 Sequence rearmement AU"}
// 🚦 4. DÉCLENCHEMENT DE LA SÉQUENCE DE SÉCURITÉ
// 🩹 Une nouvelle tentative repart d'une Cause propre : si le probleme persiste, il sera
// re-latche des le prochain echec (RedundancyCauseEdge/ArmingFailedCauseEdge -> Ack remis a FALSE,
// TC-P01-009). Ceci prouve par le run reel que la cause a disparu, pas juste un Reset optimiste.
IF ArmReqEdge.Q AND (ArmingSeqStep = 0) AND EmergencyChainClosed 
   AND NOT EmergencyArmingLockoutActive 
   AND NOT PowerContactorEngaged THEN
    ArmingSeqStep := 1;
    RedundancyTestFailedCause := FALSE;
    EmergencyArmingFailedCause := FALSE;
END_IF;

// ⏱️ Étape 1 : Coupe canal A seul, vérifie que la boucle tombe
TonTestA(IN := (ArmingSeqStep = 1), PT := CST_TestDuration);
IF ArmingSeqStep = 1 THEN
    ForceTestA := TRUE;
    IF TonTestA.Q THEN
        ForceTestA := FALSE;
        IF EmergencyChainClosed THEN
            RedundancyTestFailedCause := TRUE;
            ArmingSeqStep := 0;
        ELSE
            ArmingSeqStep := 2;
        END_IF;
    END_IF;
ELSE
    ForceTestA := FALSE;
END_IF;

// ⏱️ Étape 2 : Restaure A, attend le retour sain de la boucle amont
TonRestoreA(IN := (ArmingSeqStep = 2), PT := CST_TestDuration);
IF (ArmingSeqStep = 2) AND TonRestoreA.Q THEN
    IF EmergencyChainClosed THEN
        ArmingSeqStep := 3;
    ELSE
        ArmingSeqStep := 0;
    END_IF;
END_IF;

// ⏱️ Étape 3 : Coupe canal B seul, vérifie que la boucle tombe
TonTestB(IN := (ArmingSeqStep = 3), PT := CST_TestDuration);
IF ArmingSeqStep = 3 THEN
    ForceTestB := TRUE;
    IF TonTestB.Q THEN
        ForceTestB := FALSE;
        IF EmergencyChainClosed THEN
            RedundancyTestFailedCause := TRUE;
            ArmingSeqStep := 0;
        ELSE
            ArmingSeqStep := 4;
        END_IF;
    END_IF;
ELSE
    ForceTestB := FALSE;
END_IF;

// ⏱️ Étape 4 : Restaure B, attend le retour sain de la boucle amont
TonRestoreB(IN := (ArmingSeqStep = 4), PT := CST_TestDuration);
IF (ArmingSeqStep = 4) AND TonRestoreB.Q THEN
    IF EmergencyChainClosed THEN
        ArmingSeqStep := 5;
    ELSE
        ArmingSeqStep := 0;
    END_IF;
END_IF;

// ⏱️ Étape 5 : Les 2 canaux validés -> impulsion réarmement physique (1s)
TonArmingPulse(IN := (ArmingSeqStep = 5), PT := CST_ArmingPulseDuration);
Cmd.ArmPulse_Cmd := (ArmingSeqStep = 5);
IF (ArmingSeqStep = 5) AND TonArmingPulse.Q THEN
    ArmingSeqStep := 6;
END_IF;

// ⏱️ Étape 6 : Attente confirmation contacteur principal (2s max)
TonArmingConfirm(IN := (ArmingSeqStep = 6), PT := CST_ArmingConfirmTimeout);
IF ArmingSeqStep = 6 THEN
    IF PowerContactorEngaged THEN
        ArmingSeqStep := 0;
        EmergencyArmingLockoutActive := FALSE;
    ELSIF TonArmingConfirm.Q THEN
        EmergencyArmingFailedCause := TRUE;
        ArmingSeqStep := 0;
        EmergencyArmingLockoutActive := TRUE;
    END_IF;
END_IF;

// ⏱️ Séquence de verrouillage temporel (5s)
TonArmingLockout(IN := EmergencyArmingLockoutActive, PT := CST_ArmingLockout);
IF TonArmingLockout.Q THEN
    EmergencyArmingLockoutActive := FALSE;
END_IF;

{endregion}

{region "§6 Gestion cause et acquittement"}
// 3bis. PATTERN CAUSE/ACK — détection ré-apparition + acquittement (§3.4bis AF01, §9 STD)
// L'interlock sécurité (ci-dessous, arbitrage Cmd/Armable) utilise TOUJOURS la Cause brute,
// jamais l'Ack : l'acquittement opérateur n'ouvre jamais un interlock de sécurité.
RedundancyCauseEdge(CLK := RedundancyTestFailedCause);
IF RedundancyCauseEdge.Q THEN
    RedundancyTestFailedAck := FALSE; // nouvelle occurrence -> ré-alarme, ré-acquittement requis
END_IF;

ArmingFailedCauseEdge(CLK := EmergencyArmingFailedCause);
IF ArmingFailedCauseEdge.Q THEN
    EmergencyArmingFailedAck := FALSE;
END_IF;

{endregion}

{region "§7 Commandes et etats publics"}
// 📤 5. GÉNÉRATION DES CONSIGNES LOGIQUES — basées sur la Cause brute (jamais sur l'Ack)
Cmd.MaintainA_Cmd := NOT PowerCutOffRequest AND NOT ForceTestA AND NOT BtnEmergencyCutOff AND NOT RedundancyTestFailedCause;
Cmd.MaintainB_Cmd := NOT PowerCutOffRequest AND NOT ForceTestB AND NOT BtnEmergencyCutOff AND NOT RedundancyTestFailedCause;
// ArmPulse_Cmd déjà positionné à l'étape 5 ci-dessus (garder FALSE hors étape 5)
IF ArmingSeqStep <> 5 THEN
    Cmd.ArmPulse_Cmd := FALSE;
END_IF;

// 🚦 6. ÉTATS PUBLICS (repris par le composite dans State/Diag) — interlock sur Cause brute
Armable := EmergencyChainClosed
           AND (ArmingSeqStep = 0)
           AND NOT EmergencyArmingLockoutActive
           AND NOT RedundancyTestFailedCause
           AND NOT PowerContactorEngaged;

ArmingBusy := (ArmingSeqStep <> 0) OR EmergencyArmingLockoutActive;

{endregion}

{region "§8 Affichage defauts IHM"}
// 📤 7. AFFICHAGE IHM — debounce anti-clignotement (Cause lissée) OR NOT Ack (§9 STD)
// ⚠️ Uniquement pour l'affichage : l'action de sécurité ci-dessus (§5/§6) reste instantanée
// sur la Cause brute, jamais retardée par ce debounce.
TonRedundancyDisplay(IN := RedundancyTestFailedCause, PT := CST_FaultDisplayDebounce);
RedundancyTestFailed := TonRedundancyDisplay.Q OR NOT RedundancyTestFailedAck;

TonArmingFailedDisplay(IN := EmergencyArmingFailedCause, PT := CST_FaultDisplayDebounce);
EmergencyArmingFailed := TonArmingFailedDisplay.Q OR NOT EmergencyArmingFailedAck;

{endregion}

{region "§9 Synthese ErrorId"}
// 📤 8. SYNTHÈSE DES ERREURS (bitfield affiché, basé sur RedundancyTestFailed/EmergencyArmingFailed affichés)
ErrorId := 16#0000;
IF RedundancyTestFailed THEN
    ErrorId := ErrorId OR 16#0001;
END_IF;
IF EmergencyArmingFailed THEN
    ErrorId := ErrorId OR 16#0002;
END_IF;
// bit3 (16#0008) = StartupFail, positionné au §2 si autotest échoué
// — ne pas l'effacer ici (reset explicite requis)

Error := (ErrorId <> 16#0000);

{endregion}

