    (* RawX=9000 (au-dela du neutre 5000, hors zone morte) : OutPct = (9000-5000)/(10000-5000)*100 = 80% *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 9000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 80.0, 0.01, 'RawX=9000 : proportionnel, 80% -- pas seulement correct aux bornes 0/10000');
    ASSERT_EQ(fb.AXISCMDX.DIRECTION, 1, 'sens avant coherent');
    ASSERT_NEAR(fb.AXISCMDY.SPEEDREF, 0.0, 0.01, 'RawY toujours au neutre : axe Y inchange');

    (* RawY=300 (en-deca du neutre 5000, hors zone morte) : OutPct = (300-5000)/5000*100 = -94% *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 300, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_NEAR(fb.AXISCMDY.SPEEDREF, -94.0, 0.01, 'RawY=300 : proportionnel, -94% -- pas seulement correct aux bornes 0/10000');
    ASSERT_EQ(fb.AXISCMDY.DIRECTION, -1, 'sens arriere coherent');
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 0.0, 0.01, 'RawX revenu au neutre : axe X inchange');
END_TEST

(* ═══════════════════════════════════════════════════════════════
   🧪 FB_Sim_Safety — Simulation de la chaîne d'AU et du contacteur de puissance
   ───────────────────────────────────────────────────────────────
   📥 Enable          : activation de la simulation (SimulationModeActive AND NOT SensorEmergencyStopChainIsReal)
   📥 PowerCutOff_A   : demande de coupure PLC canal A (maintenu à TRUE en marche normale)
   📥 PowerCutOff_B   : demande de coupure PLC canal B (maintenu à TRUE en marche normale)
   📥 EmergencyArming : impulsion de réarmement (EmergencyArming_RQ)
   
   📤 SimChainOk      : simulation de la boucle AU (boutons relâchés et coupures PLC inactives)
   📤 SimContactorOk  : simulation du contacteur engagé (PowerContactorEngaged)
   
   ⚙️ Logique physique :
      - La chaîne d'AU (SimChainOk) est saine si les deux relais PLC de coupure sont maintenus fermés (TRUE).
      - Le contacteur s'engage (SimContactorOk) lors d'une impulsion de réarmement (EmergencyArming) 
        et s'auto-maintient tant que la chaîne reste saine (SimChainOk).
      - Toute coupure de la chaîne (SimChainOk = FALSE) fait retomber immédiatement le contacteur.
   ═══════════════════════════════════════════════════════════════
   📄 Docs : DOC/AF/AF_Partie-13_Fonction_Simulation_v2.3.md
*)
FUNCTION_BLOCK FB_Sim_Safety
VAR_INPUT
    Enable          : BOOL; // --> [CMD] Activation de la simulation
    PowerCutOff_A   : BOOL; // --> [SAFE] Commande coupure canal A (TRUE = OK/fermé)
    PowerCutOff_B   : BOOL; // --> [SAFE] Commande coupure canal B (TRUE = OK/fermé)
    EmergencyArming : BOOL; // --> [CMD] Impulsion de réarmement (TRUE = pulse)
    BtnEmergencyStop : BOOL; // --> [HW] Force l'ouverture de la boucle (TRUE = bouton appuyé/défaut)
END_VAR
VAR_OUTPUT
    SimChainOk      : BOOL; // <-- [STAT] Boucle AU simulée saine
    SimContactorOk  : BOOL; // <-- [STAT] Contacteur simulé engagé
END_VAR
VAR
    ContactorLatch  : BOOL; // . [LOC] Mémorisation de l'auto-maintien du contacteur
END_VAR

// === IMPLEMENTATION ===
{region "§1 Gate"}
IF NOT Enable THEN
    SimChainOk     := FALSE;
    SimContactorOk := FALSE;
    ContactorLatch := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Chaîne AU"}
// 1. La chaîne AU est saine si le PLC maintient les deux relais de coupure de puissance
// AND if no emergency stop button is pressed (BtnEmergencyStop is FALSE)
SimChainOk := PowerCutOff_A AND PowerCutOff_B AND NOT BtnEmergencyStop;
{endregion}

{region "§3 Auto-maintien contacteur"}
// 2. Logique d'auto-maintien (latch) du contacteur avec priorité à la coupure
IF NOT SimChainOk THEN
    ContactorLatch := FALSE;
ELSIF EmergencyArming THEN
    ContactorLatch := TRUE;
END_IF;

// Recopie vers la sortie
SimContactorOk := ContactorLatch;
{endregion}

(* =======================================================================
   💾 FB_CfgPersistBridge_BucketCfg — Pont persistance pour ST_BucketCfg
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Restauration et synchronisation bidirectionnelle IHM / Persist
   💾 Persistance : Transfert GVL_PERSISTENT <-> GVL_IHM sur Initialized
   📄 Doc métier : DOC/AF/AF_Partie-03_Contrats_Composants_v2.1.md §3
   ======================================================================= *)
FUNCTION_BLOCK FB_CfgPersistBridge_BucketCfg
VAR_OUTPUT
    // === ETATS RESTAURATION ===
    JustRestored            : BOOL;               // <-- [STAT] Vrai sur le cycle de restauration initiale
END_VAR
VAR_IN_OUT
    // === BUS CONFIGURATION ET PERSISTANCE ===
    Hmi                     : ST_BucketCfg;       // <-> [BUS] Structure de configuration IHM
    Persist                 : ST_BucketCfg;       // <-> [BUS] Structure de configuration persistante
END_VAR

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

