(* =======================================================================
   ⚙️ FB_Modes — Arbitrage du mode machine
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Source unique du mode arbitré et calcul du bus d'autorisations
   🔒 Sécurité : Refus du mode Semi-Auto en cas de défaut codeur
   🔌 Interface : Standard composant d'arbitrage applicatif
   📄 Doc métier : DOC/AF/AF_Partie-05_Modes_Maintenance_v2.0.md
                   DOC/AF/AF_Partie-03_Contrats_Composants_v2.1.md
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_Modes
VAR_INPUT
    // === GESTION FB & AUTORISATIONS ===
    Enable                  : BOOL;   // --> [CMD] Autorisation generale FB (TRUE = active)
    Reset                   : BOOL;   // --> [CMD] Front acquittement defauts
    PowerContactorEngaged   : BOOL;   // --> [SAFE] Chaine AU OK (TRUE = armee)

    // === SELECTIONS IHM & COMMANDES MODES ===
    SelMode                 : E_Mode; // --> [CMD] Selecteur de mode IHM
    SelSyncEnable           : BOOL;   // --> [CMD] Selection synchro treuils IHM
    InhibitM1Request        : BOOL;   // --> [CMD] Demande inhibition treuil M1
    InhibitM2Request        : BOOL;   // --> [CMD] Demande inhibition treuil M2
    SelHomingApproachEnable : BOOL;   // --> [CMD] Selection approche homing IHM
    JoystickWinchSelectRequest : INT; // --> [CMD] Selection treuils joystick (0=Couple, 1=M1, 2=M2)
    SelMaintenanceZoneAccess: BOOL;   // --> [CMD] Autorisation acces zone maintenance M3

    // === RETOURS CAPTEURS & DIAGNOSTICS ===
    EncoderFaultPresent     : BOOL;   // --> [HW] Defaut codeur agrege (1 cycle retard)
END_VAR
VAR_OUTPUT
    // === ETATS & DIAGNOSTICS IEC ===
    Ready                   : BOOL;   // <-- [STAT] FB pret a fonctionner
    // 🧩 Statut transverse (forme cible) — regroupe Busy/Done/Error/ErrorId/State/StateAtError.
    // ErrorId bit0: "Semi-Auto refusé (défaut codeur)".
    Status                  : ST_FbStatus;

    // === BUS D'AUTORISATIONS ARBITREES ===
    Auth                    : ST_Modes_Autorisations; // <-- [STAT] Bus d'autorisations typees machine
END_VAR
VAR
    // === SOUS-INSTANCES FB ===
    ResetEdge               : R_TRIG; // * [INST] Detecteur front montant Reset
    ErrorEdge               : R_TRIG; // * [INST] Detecteur front montant Error

    // === VARIABLES LOCALES & MEMOIRES ===
    PrevInhibitM1           : BOOL;   // . [LOC] Memoire etat inhibition M1 (exclusion mutuelle)
    PrevInhibitM2           : BOOL;   // . [LOC] Memoire etat inhibition M2 (exclusion mutuelle)
END_VAR

// === IMPLEMENTATION ===

{region "§1 Gate neutralisation"}
// 1. GATE — neutralisation si désactivé ou AU non armé
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Auth.Mode := E_Mode.DISABLE;
    Auth.SyncEnable := TRUE;
    Auth.InhibitM1 := FALSE;
    Auth.InhibitM2 := FALSE;
    Auth.HomingApproachEnable := FALSE;
    Auth.JoystickWinchSelectArbitrated := 0;  // Couplé nominal par défaut
    Auth.MaintenanceM3TargetEnable := FALSE;
    Ready := FALSE; Status.Busy := FALSE; Status.Done := FALSE;
    Status.State := E_State.DISABLED;
    PrevInhibitM1 := FALSE;
    PrevInhibitM2 := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
Status.State := E_State.READY;

{endregion}

{region "§2 Reset et arbitrage mode"}
// 2. RESET FRONT (bit0 = défaut codeur)
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFFE;  // Efface bit0 si front Reset
END_IF;

// 3. GARDE-FOU — refus SEMI_AUTO si défaut codeur
IF (SelMode = E_Mode.SEMI_AUTO) AND EncoderFaultPresent THEN
    Status.ErrorId := Status.ErrorId OR 16#0001;  // bit0 : défaut codeur
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFFE;
END_IF;

// 4. ARBITRAGE DU MODE
// MAINT_N2 accepté directement (authentification côté IHM).
IF (SelMode = E_Mode.SEMI_AUTO) AND EncoderFaultPresent THEN
    Auth.Mode := E_Mode.MAINT_N1;
ELSE
    Auth.Mode := SelMode;
END_IF;

{endregion}

{region "§3 Calcul autorisations machine"}
// 5. SYNC ENABLE — actionnable en MAINT_N1 ou MAINT_N2
// FALSE (désactivé) seulement si en MAINT_N1/N2 ET case décochée ; TRUE partout ailleurs.
Auth.SyncEnable := NOT ((Auth.Mode = E_Mode.MAINT_N1 OR Auth.Mode = E_Mode.MAINT_N2) AND NOT SelSyncEnable);

// 5bis. EXCLUSION MUTUELLE INHIBITIONS + RESET SYNC ENABLE
// Inhibition M1/M2 mutuellement exclusives (soit l'un, soit l'autre, jamais les deux).
// Si les deux demandés simultanément : on garde celle déjà active, sinon on rejette les deux.
// Reset SelSyncEnable si une inhibition devient active (synchro incompatible avec inhibit).
// Mémorisation états précédents pour détection front montant.

// Détection fronts montants inhibitions
IF InhibitM1Request AND NOT PrevInhibitM1 THEN
    // Front montant M1
    IF PrevInhibitM2 THEN
        // M2 déjà actif → rejette M1
        Auth.InhibitM1 := FALSE;
    ELSE
        // M2 inactif → active M1, désactive M2
        Auth.InhibitM1 := TRUE;
        Auth.InhibitM2 := FALSE;
        // Synchro incompatible avec inhibition → reset case IHM
        SelSyncEnable := FALSE;
    END_IF;
ELSIF InhibitM2Request AND NOT PrevInhibitM2 THEN
    // Front montant M2
    IF PrevInhibitM1 THEN
        // M1 déjà actif → rejette M2
        Auth.InhibitM2 := FALSE;
    ELSE
        // M1 inactif → active M2, désactive M1
        Auth.InhibitM2 := TRUE;
        Auth.InhibitM1 := FALSE;
        SelSyncEnable := FALSE;
    END_IF;
ELSE
    // Pas de front montant → maintenir états actuels
    // Mais si les deux demandes sont TRUE sans front (cas synchrone sans transition)
    IF InhibitM1Request AND InhibitM2Request THEN
        // Les deux demandées simultanément sans transition : repli sécurité
        Auth.InhibitM1 := FALSE;
        Auth.InhibitM2 := FALSE;
    END_IF;
END_IF;

// Mise à jour mémoires pour prochaine détection front
PrevInhibitM1 := InhibitM1Request;
PrevInhibitM2 := InhibitM2Request;

// 5bis-bis. Sortie inhibitions effectives (calculées ci-dessus)
Auth.InhibitM1 := (Auth.Mode = E_Mode.MAINT_N2) AND Auth.InhibitM1;
Auth.InhibitM2 := (Auth.Mode = E_Mode.MAINT_N2) AND Auth.InhibitM2;

// 5ter. AUTORISATION ARRÊT HAUT (HomingApproach)
// Uniquement actionnable en MAINT_N2.
Auth.HomingApproachEnable := (Auth.Mode = E_Mode.MAINT_N2) AND SelHomingApproachEnable;

// 5quater. SÉLECTEUR JOYSTICK TREUIL
// M1 seul ou M2 seul autorisé en MAINT_N1 et MAINT_N2. Forcé à Couplé (=0) sinon.
IF (Auth.Mode = E_Mode.MAINT_N2) OR (Auth.Mode = E_Mode.MAINT_N1) THEN
    Auth.JoystickWinchSelectArbitrated := JoystickWinchSelectRequest;
ELSE
    Auth.JoystickWinchSelectArbitrated := 0;  // Couplé nominal forcé
END_IF;

// 5quinquies. CIBLE TRANSLATION MAINTENANCE
// MAINT_N2 ou MAINT_N1 + bit IHM dédié (SelMaintenanceZoneAccess) exigé EN PLUS
Auth.MaintenanceM3TargetEnable := ((Auth.Mode = E_Mode.MAINT_N2) OR (Auth.Mode = E_Mode.MAINT_N1)) AND SelMaintenanceZoneAccess;

// GATE — désactivation inhibitions/sync si mode change (sortie N1/N2)
IF (Auth.Mode <> E_Mode.MAINT_N2) AND (Auth.Mode <> E_Mode.MAINT_N1) THEN
    Auth.InhibitM1 := FALSE;
    Auth.InhibitM2 := FALSE;
    Auth.HomingApproachEnable := FALSE;
    Auth.MaintenanceM3TargetEnable := FALSE;
    Auth.JoystickWinchSelectArbitrated := 0;
END_IF;

{endregion}

{region "§4 Etats et defauts"}
// 6. SORTIES ÉTAT
Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;

Status.Busy := FALSE;
Status.Done := FALSE;

{endregion}

END_FUNCTION_BLOCK

SETUP
VAR
    fb : FB_RAMP;
END_VAR
END_SETUP

TEST 'Accel : consigne progresse par pas de AccelRate*CycleTimeS vers la cible'
    fb(TARGET := 100.0, ACCELRATE := 50.0, DECELRATE := 200.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 5.0, 0.001, 'pas 1 : 0 -> 5.0 (50%/s * 0.1s), s eloigne de zero donc AccelRate');

    fb(TARGET := 100.0, ACCELRATE := 50.0, DECELRATE := 200.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 10.0, 0.001, 'pas 2 : 5.0 -> 10.0, meme taux tant que la cible n est pas atteinte');
END_TEST

TEST 'Decel : retour vers zero utilise DecelRate (taux different d Accel)'
    (* monte a 40% avec Accel *)
    fb(TARGET := 40.0, ACCELRATE := 50.0, DECELRATE := 10.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 5.0, 0.001, 'montee : AccelRate (50%/s)');
    fb(TARGET := 40.0, ACCELRATE := 50.0, DECELRATE := 10.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 10.0, 0.001, 'montee : toujours AccelRate, cible pas encore atteinte');

    (* cible ramenee a 0 : retour vers zero -> DecelRate, taux bien plus faible ici *)
    fb(TARGET := 0.0, ACCELRATE := 50.0, DECELRATE := 10.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 9.0, 0.001, 'retour vers zero : DecelRate (10%/s), pas de 1.0 seulement -- pas AccelRate');
END_TEST

TEST 'Atteinte de la cible : la rampe s arrete pile dessus, pas de depassement'
    fb(TARGET := 3.0, ACCELRATE := 50.0, DECELRATE := 200.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 3.0, 0.001, 'le pas (5.0) depasserait la cible (3.0) : clampe exactement dessus, pas de depassement');

    fb(TARGET := 3.0, ACCELRATE := 50.0, DECELRATE := 200.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 3.0, 0.001, 'cible deja atteinte : reste stable, aucune oscillation autour de la cible');
END_TEST

TEST 'Garde-fou : une valeur Current deja hors plage (etat corrompu) reste bornee a +/-100'
    (* Simule un etat interne deja corrompu au-dela de la plage normalisee -- le FB doit se
       proteger lui-meme, pas seulement empecher d y entrer *)
    fb(TARGET := 500.0, ACCELRATE := 1000.0, DECELRATE := 1000.0, CYCLETIMES := 1.0);
    ASSERT_NEAR(fb.CURRENT, 100.0, 0.001, 'Target hors plage (500) et grand pas (1000%/s) : Current ne depasse jamais +100');
END_TEST

(* ═══════════════════════════════════════════════════════════════
   ⏱️ FB_CycleTime — Mesure du temps de cycle réel de la tâche
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-08_Fonction_Joystick_v2.0.md §2
      (base de temps utilisée par FB_Filter_PT1, composé dans FB_Joystick)
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK FB_CycleTime
VAR_INPUT
    DefaultValueS : REAL := 0.004; (* Valeur de secours par défaut (ex. 4ms) *)
END_VAR
VAR_OUTPUT
    CycleTimeS    : REAL;          (* Temps écoulé réel calculé (secondes) *)
END_VAR
VAR
    TimeCurrent   : TIME;          (* Temps système actuel *)
    TimeLast      : TIME;          (* Empreinte de temps du cycle précédent *)
    DeltaTimeMs   : UDINT;         (* Écart brut calculé (ms) *)
    InitDone      : BOOL;          (* Drapeau d'initialisation du premier cycle *)
END_VAR

// 1. ACQUISITION DU TEMPS SYSTÈME
TimeCurrent := TIME();

// 2. INITIALISATION UNIQUE AU PREMIER CYCLE
IF NOT InitDone THEN
    TimeLast := TimeCurrent;
    InitDone := TRUE;
    CycleTimeS := DefaultValueS;
    RETURN;
END_IF;

// 3. CALCUL DU DELTA EN MILLISECONDES
DeltaTimeMs := TIME_TO_UDINT(TimeCurrent - TimeLast);

// 4. CONVERSION ET CHARGE DE SECOURS
IF DeltaTimeMs > 0 THEN
    CycleTimeS := UDINT_TO_REAL(DeltaTimeMs) / 1000.0;
ELSE
    CycleTimeS := DefaultValueS;
END_IF;

// 5. ARCHIVAGE POUR LE PROCHAIN CYCLE
TimeLast := TimeCurrent;

SETUP
VAR
    fb : FB_CYCLETIME;
END_VAR
END_SETUP

TEST 'Premier cycle retourne la valeur de secours (pas de dt mesurable)'
    fb(DEFAULTVALUES := 0.004);
    ASSERT_NEAR(fb.CYCLETIMES, 0.004, 0.0001, 'premier appel : aucun dt reel disponible, DefaultValueS renvoye tel quel');
END_TEST

TEST 'Cycle suivant calcule le dt reel ecoule (ms->s)'
    fb(DEFAULTVALUES := 0.004);
    ADVANCE_TIME(10000000);
    fb(DEFAULTVALUES := 0.004);
    ASSERT_NEAR(fb.CYCLETIMES, 0.01, 0.0001, '10ms ecoulees entre les 2 appels -> 0.01s calcule (pas la valeur de secours)');

    ADVANCE_TIME(25000000);
    fb(DEFAULTVALUES := 0.004);
    ASSERT_NEAR(fb.CYCLETIMES, 0.025, 0.0001, 'dt variable d un cycle a l autre correctement mesure (25ms)');
END_TEST

(* ═══════════════════════════════════════════════════════════════
   🧪 FB_Sim_Encoder — Simulation physique d'un codeur absolu de treuil
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF/AF_Partie-13_Fonction_Simulation_v2.3.md
   🧩 Brique réduite (Partie3 §1bis, "briques E/S & diagnostics") : pas de contrat
      Enable/Reset/Error complet, pas de StartStop/SafeStop — outil de banc, pas
      du métier machine.
   🎯 Rôle : fait "compter" un codeur absolu comme si le treuil tournait
      réellement, à partir des relais de sens commandés et de la vitesse rampée
      courante.
   📥 Enable      : simulation active (SimulationModeActive AND NOT BusEncoderMxIsReal)
   📥 RelayFwd/RelayRev : sens commandé (contacteurs de sens du treuil)
   📥 SpeedRefPct : vitesse rampée courante (magnitude, %) — ex. instWinchM1.SpeedRamp.Current
   📥 PresetCmd   : TRUE le cycle où un preset (homing) doit être appliqué (PresettTrigCmd = 2)
   📥 PresetValue : valeur brute à charger lors du preset
   📥 SpeedScaleFactor : multiplicateur de vitesse simulation (confort de test
      banc uniquement, sans rapport avec une calibration réelle). Défaut 1.0 = comportement
      d'origine. Câblé sur GVL_Simulation.TstEncoderSpeedFactor (réglable à chaud, sans recompiler).
   📤 RawPosOut   : position brute simulée (UDINT), à aiguiller à la place de la valeur
      EtherCAT réelle quand le device n'est pas Operational (voir PRG_02_Encoders.st)
   `RawPos` en `VAR_IN_OUT`, référencé depuis `GVL_PERSISTENT`
      (même pattern que `Calib` dans `FB_Encoder_Homing`) — `PERSISTENT` n'est valide que sur du
      `VAR_GLOBAL` en CODESYS, pas sur une variable locale de FB. Un vrai codeur absolu physique
      conserve son comptage brut même à travers un reset FROID (indépendant de l'automate).
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Sim_Encoder) ===

FUNCTION_BLOCK PUBLIC FB_Sim_Encoder
VAR_INPUT
    Enable           : BOOL;   (* --> [CMD] Active la simulation *)
    RelayFwd         : BOOL;   (* --> [HW] Sens commandé avant *)
    RelayRev         : BOOL;   (* --> [HW] Sens commandé arrière *)
    SpeedRefPct      : REAL;   (* --> [CMD] Vitesse rampée courante (%) *)
    PresetCmd        : BOOL;   (* --> [CMD] Applique un preset (homing) *)
    PresetValue      : UDINT;   (* --> [CFG] Valeur brute à charger au preset *)
    SpeedScaleFactor : REAL := 1.0;   (* --> [CFG] Confort de test, voir bandeau ci-dessus *)
    TestOffsetCmd    : BOOL;          (* --> [TST] Front montant = applique TestOffsetPts (test banc) *)
    TestOffsetPts    : DINT := 0;     (* --> [TST] Décalage signé à appliquer (points bruts) *)
END_VAR
VAR_OUTPUT
    RawPosOut   : UDINT;   (* <-- [DIAG] Position brute simulée *)
END_VAR
VAR_IN_OUT
    RawPos      : UDINT;   (* <-> [BUS] Référence _SimEncoderRawPosM1/M2 (survit au reset froid) *)
END_VAR
VAR
    Increment      : UDINT;              (* . [LOC] Évite de dupliquer le calcul 2x *)
    TestOffsetEdge : R_TRIG;             (* . [LOC] Front TestOffsetCmd *)
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Encoder) ===

{region "§1 Gate"}
IF NOT Enable THEN
    RawPosOut := RawPos;
    RETURN;
END_IF;
{endregion}

{region "§2 Injection test"}
// Injection test banc : VRAI saut de position (comme un glissement réel),
// pour tester Concept 1 / Méca E ET le rattrapage joystick (voir GVL_Simulation bandeau).
TestOffsetEdge(CLK := TestOffsetCmd);
IF TestOffsetEdge.Q THEN
    RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) + TestOffsetPts);
END_IF;
{endregion}

{region "§3 Comptage"}
Increment := REAL_TO_UDINT(SpeedRefPct * 0.1 * SpeedScaleFactor);

IF PresetCmd THEN
    RawPos := PresetValue;
ELSIF RelayFwd THEN
    RawPos := RawPos + Increment;
ELSIF RelayRev THEN
    IF RawPos >= Increment THEN
        RawPos := RawPos - Increment;
    ELSE
        RawPos := 0;
    END_IF;
END_IF;
{endregion}

{region "§4 Sortie"}
RawPosOut := RawPos;
{endregion}

(* ============================================================================
   🧪 FB_EncoderValidation — Suite PLC Encoder/Homing nominale
   ============================================================================
   T25 : validation du flux nominal M1/M2 en simulation.
   Le Homing unitaire MAINT_N2 reste volontairement hors périmètre.

   Cette suite est ciblée par Cmd.RunSuite = SuiteEncoder. Elle n'est pas
   ajoutée à RunAll tant que le flux Homing unitaire n'est pas spécifié.
   Chaque étape possède une limite de temps locale ; aucune attente implicite.
   ============================================================================ *)

FUNCTION_BLOCK PUBLIC FB_EncoderValidation
VAR_INPUT
    Start       : BOOL;
    Abort       : BOOL;
    CaseId      : INT; // 0=tous ; 1..2=cas ciblé
END_VAR
VAR_OUTPUT
    Busy            : BOOL;
    Done            : BOOL;
    AnyFailed       : BOOL;
    SimGateOk       : BOOL;
    ActiveStimulusId : INT;
    StepElapsed     : TIME;
    Report          : ST_TestSuiteReport;
    TerminalState   : E_TestTerminalState;
    ConfigError     : BOOL;
    ConfigErrorStepId : INT;
    ConfigErrorCheckIdx : INT;
    ErrorCode       : INT;
    ErrorMessage    : STRING(160);
END_VAR
VAR
    StartPrev       : BOOL;
    ResetIssued     : BOOL;
    Step            : INT;
    CurrentCaseId   : INT;
    StepStarted     : BOOL;
    StepTimer       : TON;
    StepLimit       : TIME;
    StepFailed      : BOOL;
    StepPassed      : BOOL;
    M1HomePulse     : BOOL;
    M2HomePulse     : BOOL;
    Index           : INT;
END_VAR

// Gate simulation : une suite non exécutable se termine explicitement.
SimGateOk := GVL_Simulation.SimulationModeActive
          AND NOT GVL_Simulation.BusEncoderM1IsReal
          AND NOT GVL_Simulation.BusEncoderM2IsReal;

// Valeurs par défaut de commande : aucun front ne reste actif hors étape dédiée.
M1HomePulse := FALSE;
M2HomePulse := FALSE;
ActiveStimulusId := 0;

IF Abort THEN
    GVL_IHM.M1TreuilRetenue.Cmd.BtnHome := FALSE;
    GVL_IHM.M2TreuilBenne.Cmd.BtnHome := FALSE;
    Busy := FALSE;
    Done := TRUE;
    AnyFailed := TRUE;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_ABORTED;
    Report.Aborted := TRUE;
    Report.AnyFailed := TRUE;
    Report.TerminalState := TerminalState;
    Report.FailureSummary := 'Encoder/Homing : ABORTED';
    RETURN;
END_IF;

// Démarrage sur front : rapport réinitialisé et mode de maintenance demandé.
IF Start AND NOT StartPrev AND NOT Busy THEN
    StartPrev := TRUE;
    Busy := TRUE;
    Done := FALSE;
    AnyFailed := FALSE;
    ConfigError := FALSE;
    ErrorCode := 0;
    ErrorMessage := '';
    TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    IF CaseId < 0 OR CaseId > 2 THEN
        Busy := FALSE;
        Done := TRUE;
        AnyFailed := TRUE;
        ConfigError := TRUE;
        ErrorCode := 3002;
        ErrorMessage := 'Encoder/Homing CaseId invalide';
        TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        Report.TerminalState := TerminalState;
        Report.AnyFailed := TRUE;
        Report.ErrorCode := ErrorCode;
        Report.ErrorMessage := ErrorMessage;
        RETURN;
    END_IF;
    IF CaseId = 2 THEN Step := 20; ELSE Step := 10; END_IF;
    Report.Name := 'Encoder/Homing Validation';
    Report.InProgress := TRUE;
    Report.AllPassed := FALSE;
    Report.AnyFailed := FALSE;
    Report.Aborted := FALSE;
    Report.TerminalState := TerminalState;
    Report.ErrorCode := 0;
    Report.ErrorMessage := '';
    Report.FailureSummary := '';
    Report.CurrentStepId := Step;
    Report.CurrentCaseId := SEL(Step >= 20, 2, 1);
    Report.Duration := T#0s;
    Report.RunCounter := Report.RunCounter + 1;
    FOR Index := 1 TO GVL_PLC_Tests_Const.MaxSteps DO
        Report.Steps[Index].Executed := FALSE;
        Report.Steps[Index].Passed := FALSE;
        Report.Steps[Index].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Steps[Index].Duration := T#0s;
    END_FOR;
    FOR Index := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        Report.Cases[Index].Executed := FALSE;
        Report.Cases[Index].Ok := FALSE;
        Report.Cases[Index].FailedStepId := 0;
        Report.Cases[Index].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Cases[Index].Duration := T#0s;
    END_FOR;
    StepStarted := FALSE;
    ResetIssued := FALSE;
ELSIF NOT Start THEN
    StartPrev := FALSE;
END_IF;

IF NOT Busy THEN
    RETURN;
END_IF;

StepElapsed := StepElapsed + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
Report.Duration := Report.Duration + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
Report.CurrentStepId := Step;
// 🧭 Mapping rapport : étapes 10/11 = TC-E1 ; étapes 20/21/22 = TC-E2.
CurrentCaseId := SEL(Step >= 20, 2, 1);
Report.CurrentCaseId := CurrentCaseId;

IF NOT StepStarted THEN
    StepStarted := TRUE;
    StepElapsed := T#0s;
    CASE Step OF
        10: StepLimit := T#2s;
        11: StepLimit := T#2s;
        20: StepLimit := T#2s;
        21: StepLimit := T#2s;
        22: StepLimit := T#10s;
    ELSE
        ConfigError := TRUE;
        ConfigErrorStepId := Step;
        ErrorCode := 3001;
        ErrorMessage := 'Encoder/Homing étape inconnue';
        StepLimit := T#0s;
    END_CASE;
END_IF;

StepTimer(IN := TRUE, PT := StepLimit);

CASE Step OF
    // TC-E1 : gate et interface IHM nominale accessibles.
    10:
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.MAINT_N2;
        IF NOT SimGateOk THEN
            StepFailed := TRUE;
            ErrorCode := 3003;
            ErrorMessage := 'Gate simulation codeurs inactif';
        ELSIF NOT GVL_IHM.M1TreuilRetenue.State.HomingError
           AND NOT GVL_IHM.M2TreuilBenne.State.HomingError THEN
            StepPassed := TRUE;
            Step := 11;
            StepStarted := FALSE;
        END_IF;

    // TC-E1 : vérifier que le rapport IHM des deux treuils existe avant commande.
    11:
        IF (GVL_IHM.M1TreuilRetenue.State.HomingState >= E_State.DISABLED)
           AND (GVL_IHM.M2TreuilBenne.State.HomingState >= E_State.DISABLED) THEN
            StepPassed := TRUE;
            Step := 0;
        END_IF;

    // TC-E2 : fronts BtnHome indépendants, envoyés simultanément.
    20:
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.MAINT_N2;
        IF NOT SimGateOk THEN
            StepFailed := TRUE;
            ErrorCode := 3003;
            ErrorMessage := 'Gate simulation codeurs inactif';
        ELSE
            StepPassed := TRUE;
            Step := 21;
            StepStarted := FALSE;
        END_IF;

    21:
        M1HomePulse := TRUE;
        M2HomePulse := TRUE;
        GVL_IHM.M1TreuilRetenue.Cmd.BtnHome := M1HomePulse;
        GVL_IHM.M2TreuilBenne.Cmd.BtnHome := M2HomePulse;
        StepPassed := TRUE;
        Step := 22;
        StepStarted := FALSE;

    // TC-E2 : aucune attente infinie : les deux instances doivent finir ou déclarer une erreur.
    22:
        GVL_IHM.M1TreuilRetenue.Cmd.BtnHome := FALSE;
        GVL_IHM.M2TreuilBenne.Cmd.BtnHome := FALSE;
        IF (GVL_IHM.M1TreuilRetenue.State.HomingDone OR GVL_IHM.M1TreuilRetenue.State.Homed)
           AND (GVL_IHM.M2TreuilBenne.State.HomingDone OR GVL_IHM.M2TreuilBenne.State.Homed) THEN
            StepPassed := TRUE;
            Step := 0;
        ELSIF GVL_IHM.M1TreuilRetenue.State.HomingError OR GVL_IHM.M2TreuilBenne.State.HomingError THEN
            StepFailed := TRUE;
        END_IF;
END_CASE;

// Verdict local de l'étape : PASS, FAIL ou TIMEOUT contrôlé.
IF StepPassed OR StepFailed OR StepTimer.Q THEN
    IF StepPassed THEN
        Report.Steps[Report.CurrentStepId].Passed := TRUE;
        Report.Steps[Report.CurrentStepId].FailReason := E_TestFailReason.FAIL_NONE;
    ELSE
        Report.Steps[Report.CurrentStepId].Passed := FALSE;
        Report.Steps[Report.CurrentStepId].FailReason := SEL(StepFailed, E_TestFailReason.FAIL_TIMEOUT, E_TestFailReason.FAIL_CHECK);
        AnyFailed := TRUE;
    END_IF;
    Report.Steps[Report.CurrentStepId].Executed := TRUE;
    Report.Steps[Report.CurrentStepId].Duration := StepElapsed;
    Report.ErrorCode := ErrorCode;
    Report.ErrorMessage := ErrorMessage;
    // Un échec ou un timeout termine immédiatement la suite : aucune étape
    // suivante ne doit laisser le banc attendre un signal devenu impossible.
    IF NOT StepPassed THEN
        Step := 0;
    END_IF;
    StepPassed := FALSE;
    StepFailed := FALSE;
    StepTimer(IN := FALSE, PT := StepLimit);
    StepElapsed := T#0s;
    IF Step = 0 THEN
        Busy := FALSE;
        Done := TRUE;
        Report.InProgress := FALSE;
        Report.AnyFailed := AnyFailed;
        Report.AllPassed := NOT AnyFailed;
        Report.TerminalState := SEL(AnyFailed, E_TestTerminalState.TEST_TERMINAL_DONE, E_TestTerminalState.TEST_TERMINAL_FAILED);
        TerminalState := Report.TerminalState;
        IF CurrentCaseId = 1 THEN
            Report.Cases[CurrentCaseId].Name := 'TC-E1 Interface Homing nominale';
        ELSE
            Report.Cases[CurrentCaseId].Name := 'TC-E2 Commandes Home M1/M2';
        END_IF;
        Report.Cases[CurrentCaseId].Executed := TRUE;
        Report.Cases[CurrentCaseId].Ok := NOT AnyFailed;
        Report.Cases[CurrentCaseId].FailedStepId := 0;
        Report.Cases[CurrentCaseId].FailReason := E_TestFailReason.FAIL_NONE;
        IF AnyFailed THEN
            Report.Cases[CurrentCaseId].FailedStepId := Report.CurrentStepId;
            Report.Cases[CurrentCaseId].FailReason := E_TestFailReason.FAIL_CHECK;
        END_IF;
        Report.Cases[CurrentCaseId].Duration := Report.Duration;
        IF AnyFailed THEN Report.FailureSummary := 'Encoder/Homing : échec ou timeout'; END_IF;
    ELSE
        StepStarted := FALSE;
    END_IF;
END_IF;

// Limite globale de sécurité de la suite : 30 s maximum.
IF Report.Duration >= T#30s AND Busy THEN
    GVL_IHM.M1TreuilRetenue.Cmd.BtnHome := FALSE;
    GVL_IHM.M2TreuilBenne.Cmd.BtnHome := FALSE;
    Busy := FALSE;
    Done := TRUE;
    AnyFailed := TRUE;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_WATCHDOG_TIMEOUT;
    Report.InProgress := FALSE;
    Report.AnyFailed := TRUE;
    Report.AllPassed := FALSE;
    Report.TerminalState := TerminalState;
    Report.ErrorCode := 3002;
    Report.ErrorMessage := 'Watchdog Encoder/Homing expire';
    Report.FailureSummary := Report.ErrorMessage;
END_IF;

