TEST 'Gate : Enable=FALSE colle le frein immediatement (securite positive)'
    fb(ENABLE := FALSE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_FALSE(fb.READY, 'Enable=FALSE : FB non pret');
    ASSERT_FALSE(fb.BRAKECMD, 'Enable=FALSE : frein colle (BrakeCmd=FALSE) quelle que soit la demande de mouvement');
END_TEST

TEST 'Sequence ouverture : le frein ne s ouvre qu apres DelayMagnetise+DelayContactClose (400ms)'
    (* Bypass du controle contacteur : ce test se concentre sur le seul timing de magnetisation *)
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_FALSE(fb.BRAKECMD, 't=0 : magnetisation demarre, frein encore colle');
    ASSERT_EQ(fb.STATUS.STATE, E_STATE.BUSY, 'sequence en cours -> BUSY');

    ADVANCE_TIME(399000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_FALSE(fb.BRAKECMD, 't=399ms < 400ms requis : toujours colle');

    ADVANCE_TIME(2000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.BRAKECMD, 't=401ms >= 400ms : magnetisation acquise, frein relache');
    ASSERT_EQ(fb.STATUS.STATE, E_STATE.DONE, 'sequence terminee -> DONE');
    ASSERT_TRUE(fb.BRAKECOMMANDOPENCONFIRMED, 'bypass actif : confirmation = image de BrakeCmd');
END_TEST

TEST 'Comportement actuel : fermeture immediate sans attendre DelayMotorDecel (TonDecel jamais cable)'
    (* A VERIFIER intentionnellement : DelayMotorDecel/TonDecel sont declares et documentes
       ("Delai deceleration avant collage frein") mais TonDecel.IN est TOUJOURS force a FALSE
       dans FB_Brake.st (§1/§3) -- aucune temporisation n est reellement appliquee avant que le
       frein ne colle. Ce test documente le comportement REEL actuel (immediat), pas une exigence
       validee -- a confirmer avec l utilisateur si une temporisation etait pourtant voulue. *)
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ADVANCE_TIME(401000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.BRAKECMD, 'precondition : frein ouvert');

    (* mouvement arrete : meme scan, frein colle instantanement -- DelayMotorDecel (500ms) ignore *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := FALSE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_FALSE(fb.BRAKECMD, 'MovementRequested retombe : frein colle DES CE SCAN, aucun delai observe');
    ASSERT_EQ(fb.STATUS.STATE, E_STATE.READY, 'retour a READY immediat');
END_TEST

TEST 'Double verification contacteur : StuckClosed si le retour ne confirme jamais l ouverture'
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ADVANCE_TIME(401000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.BRAKECMD, 'magnetisation acquise : commande ouverture emise (ContactorFeedback ne confirme pas encore)');

    (* 1s de plus (FeedbackTimeout) : le retour n a jamais confirme -> defaut *)
    ADVANCE_TIME(1000000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.CONTACTORCHECK.STUCKCLOSED, 'commande ouverture emise mais jamais confirmee -> StuckClosed');
    ASSERT_TRUE(fb.STATUS.ERROR, 'defaut visible sur Status.Error');
    ASSERT_EQ(fb.STATUS.ERRORID, 16#0001, 'bit0 : incoherence retour contacteur');
    ASSERT_FALSE(fb.BRAKECMD, 'sortie sure sur defaut : BrakeCmd force a FALSE malgre la sequence terminee');
END_TEST

TEST 'Reset n acquitte le defaut contacteur que si la cause (retour) a reellement disparu'
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ADVANCE_TIME(401000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ADVANCE_TIME(1000000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.STATUS.ERROR, 'precondition : defaut StuckClosed actif');

    (* la cause disparait (le retour confirme enfin), mais SANS Reset : le defaut reste affiche *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := TRUE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.STATUS.ERROR, 'cause disparue mais pas acquittee : le defaut reste affiche (pas d auto-effacement)');

    (* front Reset, cause deja disparue : acquitte *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := TRUE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := TRUE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_FALSE(fb.STATUS.ERROR, 'Reset avec cause disparue (retour coherent) : defaut acquitte');
    ASSERT_TRUE(fb.BRAKECMD, 'plus de defaut : frein a nouveau relache (mouvement toujours demande)');
END_TEST

(* ═══════════════════════════════════════════════════════════════
   🩺 FB_Acquisition_Preflight — Verdict passif machine arrêtée
   📄 Doc : ARCHIVES/Doc/AUDITS/PreLivraison/TASKS/TASK_D1_Preflight_et_Symetrie_Winch_v1.0.md
   🔒 Observateur pur : aucun SafeStop, PowerCutOff ou ordre machine.
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK FB_Acquisition_Preflight
VAR_INPUT
    Execute : BOOL;
    MachineIsStill : BOOL;
    M1BrakeApplied, M2BrakeApplied, M3BrakeApplied : BOOL;
    M1ContactorsReleased, M2ContactorsReleased, M1ThermalOk, M2ThermalOk : BOOL;
    BrakeThermalOk, PhaseRotationOk, SlackCableTensioned, M3SensorWordIncoherent : BOOL;
    EmergencyChainClosed, PowerContactorEngaged, EncoderM1Operational, EncoderM2Operational : BOOL;
    HomedM1, HomedM2, M1PositionInBounds, M2PositionInBounds : BOOL;
END_VAR
VAR_OUTPUT
    PreflightOk : BOOL;
    PreflightDone : BOOL;
    PreflightBusy : BOOL;
    PreflightErrorId : WORD;
END_VAR
VAR
    ExecuteEdge : R_TRIG;
    BootPending : BOOL := TRUE;
    RequestPending : BOOL;
END_VAR

ExecuteEdge(CLK := Execute);
RequestPending := RequestPending OR ExecuteEdge.Q OR BootPending;
PreflightBusy := RequestPending AND NOT MachineIsStill;
IF NOT MachineIsStill THEN PreflightDone := FALSE; RETURN; END_IF;
IF NOT RequestPending THEN RETURN; END_IF;

PreflightErrorId := 0;
(* bit0..2 frein M1/M2/M3 serré; bit3..4 contacteurs M1/M2 retombés;
   bit5..6 thermique M1/M2 OK; bit7 thermique frein OK; bit8 phases OK;
   bit9 câble M2 tendu; bit10 mot M3 cohérent; bit11 contacteur sans chaîne;
   bit12..13 codeur M1/M2 opérationnel; bit14..15 homé et position bornée M1/M2. *)
IF NOT M1BrakeApplied THEN PreflightErrorId := PreflightErrorId OR 16#0001; END_IF;
IF NOT M2BrakeApplied THEN PreflightErrorId := PreflightErrorId OR 16#0002; END_IF;
IF NOT M3BrakeApplied THEN PreflightErrorId := PreflightErrorId OR 16#0004; END_IF;
IF NOT M1ContactorsReleased THEN PreflightErrorId := PreflightErrorId OR 16#0008; END_IF;
IF NOT M2ContactorsReleased THEN PreflightErrorId := PreflightErrorId OR 16#0010; END_IF;
IF NOT M1ThermalOk THEN PreflightErrorId := PreflightErrorId OR 16#0020; END_IF;
IF NOT M2ThermalOk THEN PreflightErrorId := PreflightErrorId OR 16#0040; END_IF;
IF NOT BrakeThermalOk THEN PreflightErrorId := PreflightErrorId OR 16#0080; END_IF;
IF NOT PhaseRotationOk THEN PreflightErrorId := PreflightErrorId OR 16#0100; END_IF;
IF NOT SlackCableTensioned THEN PreflightErrorId := PreflightErrorId OR 16#0200; END_IF;
IF M3SensorWordIncoherent THEN PreflightErrorId := PreflightErrorId OR 16#0400; END_IF;
IF PowerContactorEngaged AND NOT EmergencyChainClosed THEN PreflightErrorId := PreflightErrorId OR 16#0800; END_IF;
IF NOT EncoderM1Operational THEN PreflightErrorId := PreflightErrorId OR 16#1000; END_IF;
IF NOT EncoderM2Operational THEN PreflightErrorId := PreflightErrorId OR 16#2000; END_IF;
IF NOT HomedM1 OR NOT M1PositionInBounds THEN PreflightErrorId := PreflightErrorId OR 16#4000; END_IF;
IF NOT HomedM2 OR NOT M2PositionInBounds THEN PreflightErrorId := PreflightErrorId OR 16#8000; END_IF;
PreflightOk := (PreflightErrorId = 0); PreflightDone := TRUE; BootPending := FALSE; RequestPending := FALSE;

(* ═══════════════════════════════════════════════════════════════
   🩺 FB_Acquisition_Preflight — Verdict passif machine arrêtée
   📄 Doc : ARCHIVES/Doc/AUDITS/PreLivraison/TASKS/TASK_D1_Preflight_et_Symetrie_Winch_v1.0.md
   🔒 Observateur pur : aucun SafeStop, PowerCutOff ou ordre machine.
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK FB_Acquisition_Preflight
VAR_INPUT
    Execute : BOOL;
    MachineIsStill : BOOL;
    M1BrakeApplied, M2BrakeApplied, M3BrakeApplied : BOOL;
    M1ContactorsReleased, M2ContactorsReleased, M1ThermalOk, M2ThermalOk : BOOL;
    BrakeThermalOk, PhaseRotationOk, SlackCableTensioned, M3SensorWordIncoherent : BOOL;
    EmergencyChainClosed, PowerContactorEngaged, EncoderM1Operational, EncoderM2Operational : BOOL;
    HomedM1, HomedM2, M1PositionInBounds, M2PositionInBounds : BOOL;
END_VAR
VAR_OUTPUT
    PreflightOk : BOOL;
    PreflightDone : BOOL;
    PreflightBusy : BOOL;
    PreflightErrorId : WORD;
END_VAR
VAR
    ExecuteEdge : R_TRIG;
    BootPending : BOOL := TRUE;
    RequestPending : BOOL;
END_VAR

ExecuteEdge(CLK := Execute);
RequestPending := RequestPending OR ExecuteEdge.Q OR BootPending;
PreflightBusy := RequestPending AND NOT MachineIsStill;
IF NOT MachineIsStill THEN PreflightDone := FALSE; RETURN; END_IF;
IF NOT RequestPending THEN RETURN; END_IF;

PreflightErrorId := 0;
(* bit0..2 frein M1/M2/M3 serré; bit3..4 contacteurs M1/M2 retombés;
   bit5..6 thermique M1/M2 OK; bit7 thermique frein OK; bit8 phases OK;
   bit9 câble M2 tendu; bit10 mot M3 cohérent; bit11 contacteur sans chaîne;
   bit12..13 codeur M1/M2 opérationnel; bit14..15 homé et position bornée M1/M2. *)
IF NOT M1BrakeApplied THEN PreflightErrorId := PreflightErrorId OR 16#0001; END_IF;
IF NOT M2BrakeApplied THEN PreflightErrorId := PreflightErrorId OR 16#0002; END_IF;
IF NOT M3BrakeApplied THEN PreflightErrorId := PreflightErrorId OR 16#0004; END_IF;
IF NOT M1ContactorsReleased THEN PreflightErrorId := PreflightErrorId OR 16#0008; END_IF;
IF NOT M2ContactorsReleased THEN PreflightErrorId := PreflightErrorId OR 16#0010; END_IF;
IF NOT M1ThermalOk THEN PreflightErrorId := PreflightErrorId OR 16#0020; END_IF;
IF NOT M2ThermalOk THEN PreflightErrorId := PreflightErrorId OR 16#0040; END_IF;
IF NOT BrakeThermalOk THEN PreflightErrorId := PreflightErrorId OR 16#0080; END_IF;
IF NOT PhaseRotationOk THEN PreflightErrorId := PreflightErrorId OR 16#0100; END_IF;
IF NOT SlackCableTensioned THEN PreflightErrorId := PreflightErrorId OR 16#0200; END_IF;
IF M3SensorWordIncoherent THEN PreflightErrorId := PreflightErrorId OR 16#0400; END_IF;
IF PowerContactorEngaged AND NOT EmergencyChainClosed THEN PreflightErrorId := PreflightErrorId OR 16#0800; END_IF;
IF NOT EncoderM1Operational THEN PreflightErrorId := PreflightErrorId OR 16#1000; END_IF;
IF NOT EncoderM2Operational THEN PreflightErrorId := PreflightErrorId OR 16#2000; END_IF;
IF NOT HomedM1 OR NOT M1PositionInBounds THEN PreflightErrorId := PreflightErrorId OR 16#4000; END_IF;
IF NOT HomedM2 OR NOT M2PositionInBounds THEN PreflightErrorId := PreflightErrorId OR 16#8000; END_IF;
PreflightOk := (PreflightErrorId = 0); PreflightDone := TRUE; BootPending := FALSE; RequestPending := FALSE;

(* ═══════════════════════════════════════════════════════════════
   🛡️ FB_Safety_EmergencyManagementLogic — Décision & Séquencement
   ───────────────────────────────────────────────────────────────
   📄 Rôle : Gère la machine d'état d'auto-test et de réarmement de
      la boucle d'arrêt d'urgence. Produit les consignes logiques
      et les bus d'état/diagnostic.
   🔒 Polarité maintien : MaintainA/B_Cmd (TRUE = voie saine).
   🛡️ Pattern Cause/Ack (§9 STD) : Reset non conditionné, interlock sur Cause brute,
      affichage IHM (ErrorId) avec debounce court + Ack.
   ═══════════════════════════════════════════════════════════════
    📄 Docs : DOC/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md §3.4/§3.4bis
              DOC/CODE_QUALITY_STANDARDS.md §9 (pattern Cause/Ack)
              DOC/AF_Partie-03_Contrats_Composants_v2.0.md
*)

FUNCTION_BLOCK PUBLIC FB_Safety_EmergencyManagementLogic
VAR_INPUT
    Enable              : BOOL;        // Active la surveillance
    Reset               : BOOL;        // Front acquittement défauts
    ArmRequest          : BOOL;        // Demande de réarmement (BtnEmergencyArming)
    EmergencyChainClosed      : BOOL;        // Retour physique boucle d'urgence amont contacteur
    PowerContactorEngaged     : BOOL;        // Confirmation contacteur de puissance principal
    PowerCutOffRequest  : BOOL;        // Requête de coupure logique issue des métiers
    BtnEmergencyCutOff  : BOOL;        // Commande d'ouverture d'urgence depuis l'IHM
END_VAR
VAR_OUTPUT
    Error               : BOOL;
    ErrorId             : WORD;        // bit0: RedundancyTestFailed (affiché), bit1: EmergencyArmingFailed (affiché)
    Cmd                 : ST_Safety_Emergency_InternalCmd; // Structure de commande logique produite

    ArmingSeqStep       : INT;         // Étape de diagnostic : 0=IDLE, 1=TestA, 2=RestoreA, 3=TestB, 4=RestoreB, 5=Pulse, 6=Confirm
    RedundancyTestFailed: BOOL;        // 🩹 Affiché = Cause lissée OR NOT Ack (pattern §3.4bis) — pour IHM/diag
    EmergencyArmingFailed: BOOL;       // 🩹 Affiché = Cause lissée OR NOT Ack (pattern §3.4bis) — pour IHM/diag
    EmergencyArmingLockoutActive : BOOL; // Verrouillage temporel de 5s entre les essais

    // 🆕 Bus State/Diag internes — repris par le composite pour les DUT publics
    Armable             : BOOL;        // 🟢 Réarmement possible maintenant
    ArmingBusy          : BOOL;        // ⏳ Séquence ou lockout en cours
    StartupFail         : BOOL;        // 🔴 Autotest démarche échoué
END_VAR
VAR CONSTANT
    // [CST] Temporisations normatives de securite AU (fixes, non modifiables RETAIN/IHM)
    CST_TestDuration         : TIME := T#200ms;  // Duree auto-test canal A ou B
    CST_ArmingPulseDuration  : TIME := T#1s;     // Duree impulsion rearmement contacteur
    CST_ArmingConfirmTimeout : TIME := T#2s;     // Timeout confirmation engagement contacteur
    CST_ArmingLockout        : TIME := T#5s;     // Duree verrouillage anti-reessai apres echec
    CST_FaultDisplayDebounce : TIME := T#200ms;  // 🩹 Anti-clignotement affichage IHM uniquement (§9 STD) — jamais sur l'action
END_VAR
VAR
    ResetEdge           : R_TRIG;
    ArmReqEdge          : R_TRIG;
    EnableRising        : R_TRIG;
    ForceTestA          : BOOL;
    ForceTestB          : BOOL;
    TonTestA            : TON;
    TonRestoreA         : TON;
    TonTestB            : TON;
    TonRestoreB         : TON;
    TonArmingPulse      : TON;
    TonArmingConfirm    : TON;
    TonArmingLockout    : TON;

    // 🆕 Autotest démarrage
    StartupCheckDone    : BOOL;        // TRUE = autotest passé, attente réarmement
    StartupCheckOK      : BOOL;        // Résultat autotest (latche le temps du front)

    // 🩹 Pattern Cause/Ack (§3.4bis AF01, §9 STD) — Reset jamais conditionné
    RedundancyTestFailedCause : BOOL;        // Latch brut : canal collé détecté à l'auto-test
    RedundancyTestFailedAck   : BOOL := TRUE; // Accusé opérateur — TRUE = pas d'alarme à afficher
    RedundancyCauseEdge       : R_TRIG;       // Détecte une NOUVELLE occurrence de la cause
    TonRedundancyDisplay      : TON;          // Debounce affichage IHM uniquement

    EmergencyArmingFailedCause : BOOL;        // Latch brut : contacteur non confirmé sous 2s
    EmergencyArmingFailedAck   : BOOL := TRUE; // Accusé opérateur — TRUE = pas d'alarme à afficher
    ArmingFailedCauseEdge      : R_TRIG;       // Détecte une NOUVELLE occurrence de la cause
    TonArmingFailedDisplay     : TON;          // Debounce affichage IHM uniquement
END_VAR

// === IMPLEMENTATION ===

// 🔄 Fronts
EnableRising(CLK := Enable);
ResetEdge(CLK := Reset);
ArmReqEdge(CLK := ArmRequest);

// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    Error := FALSE;
    ErrorId := 16#0000;
    Cmd.MaintainA_Cmd := FALSE;
    Cmd.MaintainB_Cmd := FALSE;
    Cmd.ArmPulse_Cmd := FALSE;
    ArmingSeqStep := 0;
    RedundancyTestFailed := FALSE;
    EmergencyArmingFailed := FALSE;
    EmergencyArmingLockoutActive := FALSE;
    ForceTestA := FALSE;
    ForceTestB := FALSE;
    Armable := FALSE;
    ArmingBusy := FALSE;
    StartupFail := FALSE;
    StartupCheckDone := FALSE;
    StartupCheckOK := FALSE;
    // 🩹 Neutralisation = coupure surveillance, pas un defaut : Cause et Ack repartent propres
    RedundancyTestFailedCause := FALSE;
    RedundancyTestFailedAck := TRUE;
    EmergencyArmingFailedCause := FALSE;
    EmergencyArmingFailedAck := TRUE;
    TonTestA(IN := FALSE);
    TonRestoreA(IN := FALSE);
    TonTestB(IN := FALSE);
    TonRestoreB(IN := FALSE);
    TonArmingPulse(IN := FALSE);
    TonArmingConfirm(IN := FALSE);
    TonArmingLockout(IN := FALSE);
    TonRedundancyDisplay(IN := FALSE);
    TonArmingFailedDisplay(IN := FALSE);
    RETURN;
END_IF;

// 🏁 2. AUTOTEST DÉMARRAGE (§5.4 AF01)
// Vérifications synchrones 1 cycle au premier passage Enable=TRUE
IF EnableRising.Q THEN
    StartupCheckDone := FALSE;
END_IF;

IF NOT StartupCheckDone THEN
    // Exécute les 4 contrôles en 1 cycle
    StartupCheckOK := EmergencyChainClosed          // 1. Boucle AU fermée
                      AND NOT PowerContactorEngaged // 2. Contacteur au repos
                      AND (ArmingSeqStep = 0);      // 4. Pas de séquence résiduelle
    StartupCheckDone := TRUE;
    StartupFail := NOT StartupCheckOK;
    IF NOT StartupCheckOK THEN
        ErrorId := 16#0008; // bit3 = startup autotest fail
        Error := TRUE;
    END_IF;
    RETURN; // 1 cycle pour laisser le temps aux entrées de se stabiliser
END_IF;

// 🔍 3. ACQUITTEMENT DES DÉFAUTS (pattern Cause/Ack — §3.4bis AF01, §9 STD)
// ⚠️ Reset TOUJOURS effectif, efface l'affichage (Ack:=TRUE) et réinitialise Cause:=FALSE
// pour permettre une nouvelle tentative d'armement sans blocage IHM. Si le défaut persiste,
// la nouvelle tentative re-latchera Cause:=TRUE et Ack:=FALSE (TC-P01-009).
IF ResetEdge.Q THEN
    RedundancyTestFailedAck := TRUE;
    EmergencyArmingFailedAck := TRUE;
    RedundancyTestFailedCause := FALSE;
    EmergencyArmingFailedCause := FALSE;
    StartupFail := FALSE;
    ErrorId := 16#0000;
END_IF;

// 🚦 4. DÉCLENCHEMENT DE LA SÉQUENCE DE SÉCURITÉ
// 🩹 Une nouvelle tentative repart d'une Cause propre : si le probleme persiste, il sera
// re-latche des le prochain echec (RedundancyCauseEdge/ArmingFailedCauseEdge -> Ack remis a FALSE,
// TC-P01-009). Ceci prouve par le run reel que la cause a disparu, pas juste un Reset optimiste.
IF ArmReqEdge.Q AND (ArmingSeqStep = 0) AND EmergencyChainClosed 
   AND NOT EmergencyArmingLockoutActive 
   AND NOT PowerContactorEngaged THEN
    ArmingSeqStep := 1;
    RedundancyTestFailedCause := FALSE;
    EmergencyArmingFailedCause := FALSE;
END_IF;

// ⏱️ Étape 1 : Coupe canal A seul, vérifie que la boucle tombe
TonTestA(IN := (ArmingSeqStep = 1), PT := CST_TestDuration);
IF ArmingSeqStep = 1 THEN
    ForceTestA := TRUE;
    IF TonTestA.Q THEN
        ForceTestA := FALSE;
        IF EmergencyChainClosed THEN
            RedundancyTestFailedCause := TRUE;
            ArmingSeqStep := 0;
        ELSE
            ArmingSeqStep := 2;
        END_IF;
    END_IF;
ELSE
    ForceTestA := FALSE;
END_IF;

// ⏱️ Étape 2 : Restaure A, attend le retour sain de la boucle amont
TonRestoreA(IN := (ArmingSeqStep = 2), PT := CST_TestDuration);
IF (ArmingSeqStep = 2) AND TonRestoreA.Q THEN
    IF EmergencyChainClosed THEN
        ArmingSeqStep := 3;
    ELSE
        ArmingSeqStep := 0;
    END_IF;
END_IF;

// ⏱️ Étape 3 : Coupe canal B seul, vérifie que la boucle tombe
TonTestB(IN := (ArmingSeqStep = 3), PT := CST_TestDuration);
IF ArmingSeqStep = 3 THEN
    ForceTestB := TRUE;
    IF TonTestB.Q THEN
        ForceTestB := FALSE;
        IF EmergencyChainClosed THEN
            RedundancyTestFailedCause := TRUE;
            ArmingSeqStep := 0;
        ELSE
            ArmingSeqStep := 4;
        END_IF;
    END_IF;
ELSE
    ForceTestB := FALSE;
END_IF;

// ⏱️ Étape 4 : Restaure B, attend le retour sain de la boucle amont
TonRestoreB(IN := (ArmingSeqStep = 4), PT := CST_TestDuration);
IF (ArmingSeqStep = 4) AND TonRestoreB.Q THEN
    IF EmergencyChainClosed THEN
        ArmingSeqStep := 5;
    ELSE
        ArmingSeqStep := 0;
    END_IF;
END_IF;

// ⏱️ Étape 5 : Les 2 canaux validés -> impulsion réarmement physique (1s)
TonArmingPulse(IN := (ArmingSeqStep = 5), PT := CST_ArmingPulseDuration);
Cmd.ArmPulse_Cmd := (ArmingSeqStep = 5);
IF (ArmingSeqStep = 5) AND TonArmingPulse.Q THEN
    ArmingSeqStep := 6;
END_IF;

// ⏱️ Étape 6 : Attente confirmation contacteur principal (2s max)
TonArmingConfirm(IN := (ArmingSeqStep = 6), PT := CST_ArmingConfirmTimeout);
IF ArmingSeqStep = 6 THEN
    IF PowerContactorEngaged THEN
        ArmingSeqStep := 0;
        EmergencyArmingLockoutActive := FALSE;
    ELSIF TonArmingConfirm.Q THEN
        EmergencyArmingFailedCause := TRUE;
        ArmingSeqStep := 0;
        EmergencyArmingLockoutActive := TRUE;
    END_IF;
END_IF;

// ⏱️ Séquence de verrouillage temporel (5s)
TonArmingLockout(IN := EmergencyArmingLockoutActive, PT := CST_ArmingLockout);
IF TonArmingLockout.Q THEN
    EmergencyArmingLockoutActive := FALSE;
END_IF;

// 🆕 3bis. PATTERN CAUSE/ACK — détection ré-apparition + acquittement (§3.4bis AF01, §9 STD)
// L'interlock sécurité (ci-dessous, arbitrage Cmd/Armable) utilise TOUJOURS la Cause brute,
// jamais l'Ack : l'acquittement opérateur n'ouvre jamais un interlock de sécurité.
RedundancyCauseEdge(CLK := RedundancyTestFailedCause);
IF RedundancyCauseEdge.Q THEN
    RedundancyTestFailedAck := FALSE; // nouvelle occurrence -> ré-alarme, ré-acquittement requis
END_IF;

ArmingFailedCauseEdge(CLK := EmergencyArmingFailedCause);
IF ArmingFailedCauseEdge.Q THEN
    EmergencyArmingFailedAck := FALSE;
END_IF;

// 📤 5. GÉNÉRATION DES CONSIGNES LOGIQUES — basées sur la Cause brute (jamais sur l'Ack)
Cmd.MaintainA_Cmd := NOT PowerCutOffRequest AND NOT ForceTestA AND NOT BtnEmergencyCutOff AND NOT RedundancyTestFailedCause;
Cmd.MaintainB_Cmd := NOT PowerCutOffRequest AND NOT ForceTestB AND NOT BtnEmergencyCutOff AND NOT RedundancyTestFailedCause;
// ArmPulse_Cmd déjà positionné à l'étape 5 ci-dessus (garder FALSE hors étape 5)
IF ArmingSeqStep <> 5 THEN
    Cmd.ArmPulse_Cmd := FALSE;
END_IF;

// 🚦 6. ÉTATS PUBLICS (repris par le composite dans State/Diag) — interlock sur Cause brute
Armable := EmergencyChainClosed
           AND (ArmingSeqStep = 0)
           AND NOT EmergencyArmingLockoutActive
           AND NOT RedundancyTestFailedCause
           AND NOT PowerContactorEngaged;

ArmingBusy := (ArmingSeqStep <> 0) OR EmergencyArmingLockoutActive;

// 📤 7. AFFICHAGE IHM — debounce anti-clignotement (Cause lissée) OR NOT Ack (§9 STD)
// ⚠️ Uniquement pour l'affichage : l'action de sécurité ci-dessus (§5/§6) reste instantanée
// sur la Cause brute, jamais retardée par ce debounce.
TonRedundancyDisplay(IN := RedundancyTestFailedCause, PT := CST_FaultDisplayDebounce);
RedundancyTestFailed := TonRedundancyDisplay.Q OR NOT RedundancyTestFailedAck;

TonArmingFailedDisplay(IN := EmergencyArmingFailedCause, PT := CST_FaultDisplayDebounce);
EmergencyArmingFailed := TonArmingFailedDisplay.Q OR NOT EmergencyArmingFailedAck;

// 📤 8. SYNTHÈSE DES ERREURS (bitfield affiché, basé sur RedundancyTestFailed/EmergencyArmingFailed affichés)
ErrorId := 16#0000;
IF RedundancyTestFailed THEN
    ErrorId := ErrorId OR 16#0001;
END_IF;
IF EmergencyArmingFailed THEN
    ErrorId := ErrorId OR 16#0002;
END_IF;
// bit3 (16#0008) = StartupFail, positionné au §2 si autotest échoué
// — ne pas l'effacer ici (reset explicite requis)

Error := (ErrorId <> 16#0000);

(* ═══════════════════════════════════════════════════════════════════════════════
   🔍 FB_Encoder_SpeedMonitor — Détection de variation brusque de vitesse câble
   ═══════════════════════════════════════════════════════════════════════════════
   📄 Brique standard de diagnostic — aucun pilotage moteur, aucun SafeStop.
   🎯 Compare deux mesures successives de vitesse linéaire câble en m/s.
   🧩 Le seuil et la durée de confirmation sont fournis par l'appelant :
      aucun réglage métier n'est figé dans cette brique.
   🛡️ Une variation confirmée pose ErrorId bit0. Le défaut reste mémorisé
      jusqu'à disparition de la cause et acquittement par front Reset.
   ═══════════════════════════════════════════════════════════════════════════════
   📄 Docs : DOC/AF_Partie-09_Fonction_Encoder_v2.1.md
*)

FUNCTION_BLOCK PUBLIC FB_Encoder_SpeedMonitor
VAR_INPUT
    Enable                     : BOOL;        // Autorise la surveillance
    Reset                      : BOOL;        // Acquittement par front
    PowerContactorEngaged            : BOOL;        // Contexte sécurité global valide
    Mode                       : E_Mode;      // Contexte de fonctionnement
    SpeedMps                   : REAL;        // Vitesse linéaire absolue mesurée (m/s)
    SpeedVariationThresholdMps : REAL;        // Variation minimale à surveiller (m/s)
    SpeedVariationTimeout      : TIME;        // Durée minimale de confirmation
    SpeedStabilityTimeout      : TIME;        // Durée sans variation avant vitesse stable
END_VAR
VAR_OUTPUT
    Ready                  : BOOL;
    Busy                   : BOOL;
    Done                   : BOOL;
    Error                  : BOOL;
    ErrorId                : WORD;        // bit0 : variation vitesse confirmée
    State                  : E_State;
    StateAtError           : E_State;
    SpeedDeltaMps          : REAL;        // Écart absolu entre deux mesures (m/s)
    SpeedVariationDetected : BOOL;        // Seuil dépassé sur le cycle courant
    SpeedVariationConfirmed: BOOL;        // Seuil dépassé pendant la durée requise
    SpeedStable            : BOOL;        // Vitesse stable pendant SpeedStabilityTimeout
END_VAR
VAR
    ResetEdge          : R_TRIG;
    ErrorEdge          : R_TRIG;
    VariationTimer     : TON;
    StabilityTimer     : TON;
    PreviousSpeedMps   : REAL;
    HasPreviousSpeed   : BOOL;
    VariationActive    : BOOL;
END_VAR

// 🛑 1. GATE — désactivation ou AU non réarmé : aucune alarme persistante.
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE;
    Busy := FALSE;
    Done := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    State := E_State.DISABLED;
    SpeedDeltaMps := 0.0;
    SpeedVariationDetected := FALSE;
    SpeedVariationConfirmed := FALSE;
    SpeedStable := FALSE;
    VariationActive := FALSE;
    HasPreviousSpeed := FALSE;
    VariationTimer(IN := FALSE, PT := SpeedVariationTimeout);
    StabilityTimer(IN := FALSE, PT := SpeedStabilityTimeout);
    RETURN;
END_IF;

Ready := TRUE;
Busy := FALSE;
Done := FALSE;
State := E_State.READY;

// 🔑 2. RESET FRONT — l'acquittement n'efface le défaut que si la cause a disparu.
ResetEdge(CLK := Reset);

// 📏 3. CALCUL DE L'ÉCART DE VITESSE — première mesure utilisée comme référence.
IF NOT HasPreviousSpeed THEN
    PreviousSpeedMps := SpeedMps;
    HasPreviousSpeed := TRUE;
    SpeedDeltaMps := 0.0;
ELSE
    SpeedDeltaMps := ABS(SpeedMps - PreviousSpeedMps);
    PreviousSpeedMps := SpeedMps;
END_IF;

// 🔍 4. DÉTECTION BRUTE + FILTRE TEMPOREL — pas de déclenchement si la durée vaut zéro.
VariationActive := HasPreviousSpeed
                   AND (SpeedVariationThresholdMps >= 0.0)
                   AND (SpeedVariationTimeout > T#0ms)
                   AND (SpeedDeltaMps > SpeedVariationThresholdMps);
SpeedVariationDetected := VariationActive;

VariationTimer(IN := VariationActive, PT := SpeedVariationTimeout);
SpeedVariationConfirmed := VariationTimer.Q;
StabilityTimer(IN := HasPreviousSpeed AND NOT VariationActive AND (SpeedStabilityTimeout > T#0ms), PT := SpeedStabilityTimeout);
SpeedStable := StabilityTimer.Q;

IF SpeedVariationConfirmed THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q AND NOT VariationActive THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 📤 5. SORTIES D'ÉTAT — diagnostic standard, aucune commande mouvement.
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

SETUP
VAR
    fb : FB_RAMP;
END_VAR
END_SETUP

TEST 'Accel : consigne progresse par pas de AccelRate*CycleTimeS vers la cible'
    fb(TARGET := 100.0, ACCELRATE := 50.0, DECELRATE := 200.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 5.0, 0.001, 'pas 1 : 0 -> 5.0 (50%/s * 0.1s), s eloigne de zero donc AccelRate');

    fb(TARGET := 100.0, ACCELRATE := 50.0, DECELRATE := 200.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 10.0, 0.001, 'pas 2 : 5.0 -> 10.0, meme taux tant que la cible n est pas atteinte');
END_TEST

TEST 'Decel : retour vers zero utilise DecelRate (taux different d Accel)'
    (* monte a 40% avec Accel *)
    fb(TARGET := 40.0, ACCELRATE := 50.0, DECELRATE := 10.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 5.0, 0.001, 'montee : AccelRate (50%/s)');
    fb(TARGET := 40.0, ACCELRATE := 50.0, DECELRATE := 10.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 10.0, 0.001, 'montee : toujours AccelRate, cible pas encore atteinte');

    (* cible ramenee a 0 : retour vers zero -> DecelRate, taux bien plus faible ici *)
    fb(TARGET := 0.0, ACCELRATE := 50.0, DECELRATE := 10.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 9.0, 0.001, 'retour vers zero : DecelRate (10%/s), pas de 1.0 seulement -- pas AccelRate');
END_TEST

TEST 'Atteinte de la cible : la rampe s arrete pile dessus, pas de depassement'
    fb(TARGET := 3.0, ACCELRATE := 50.0, DECELRATE := 200.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 3.0, 0.001, 'le pas (5.0) depasserait la cible (3.0) : clampe exactement dessus, pas de depassement');

    fb(TARGET := 3.0, ACCELRATE := 50.0, DECELRATE := 200.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 3.0, 0.001, 'cible deja atteinte : reste stable, aucune oscillation autour de la cible');
END_TEST

TEST 'Garde-fou : une valeur Current deja hors plage (etat corrompu) reste bornee a +/-100'
    (* Simule un etat interne deja corrompu au-dela de la plage normalisee -- le FB doit se
       proteger lui-meme, pas seulement empecher d y entrer *)
    fb(TARGET := 500.0, ACCELRATE := 1000.0, DECELRATE := 1000.0, CYCLETIMES := 1.0);
    ASSERT_NEAR(fb.CURRENT, 100.0, 0.001, 'Target hors plage (500) et grand pas (1000%/s) : Current ne depasse jamais +100');
END_TEST

SETUP
VAR
    fb : FB_BRAKE;
END_VAR
END_SETUP

TEST 'Gate : Enable=FALSE colle le frein immediatement (securite positive)'
    fb(ENABLE := FALSE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_FALSE(fb.READY, 'Enable=FALSE : FB non pret');
    ASSERT_FALSE(fb.BRAKECMD, 'Enable=FALSE : frein colle (BrakeCmd=FALSE) quelle que soit la demande de mouvement');
END_TEST

TEST 'Sequence ouverture : le frein ne s ouvre qu apres DelayMagnetise+DelayContactClose (400ms)'
    (* Bypass du controle contacteur : ce test se concentre sur le seul timing de magnetisation *)
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_FALSE(fb.BRAKECMD, 't=0 : magnetisation demarre, frein encore colle');
    ASSERT_EQ(fb.STATUS.STATE, E_STATE.BUSY, 'sequence en cours -> BUSY');

    ADVANCE_TIME(399000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_FALSE(fb.BRAKECMD, 't=399ms < 400ms requis : toujours colle');

    ADVANCE_TIME(2000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.BRAKECMD, 't=401ms >= 400ms : magnetisation acquise, frein relache');
    ASSERT_EQ(fb.STATUS.STATE, E_STATE.DONE, 'sequence terminee -> DONE');
    ASSERT_TRUE(fb.BRAKECOMMANDOPENCONFIRMED, 'bypass actif : confirmation = image de BrakeCmd');
END_TEST

TEST 'Comportement actuel : fermeture immediate sans attendre DelayMotorDecel (TonDecel jamais cable)'
    (* A VERIFIER intentionnellement : DelayMotorDecel/TonDecel sont declares et documentes
       ("Delai deceleration avant collage frein") mais TonDecel.IN est TOUJOURS force a FALSE
       dans FB_Brake.st (§1/§3) -- aucune temporisation n est reellement appliquee avant que le
       frein ne colle. Ce test documente le comportement REEL actuel (immediat), pas une exigence
       validee -- a confirmer avec l utilisateur si une temporisation etait pourtant voulue. *)
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ADVANCE_TIME(401000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.BRAKECMD, 'precondition : frein ouvert');

    (* mouvement arrete : meme scan, frein colle instantanement -- DelayMotorDecel (500ms) ignore *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := FALSE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_FALSE(fb.BRAKECMD, 'MovementRequested retombe : frein colle DES CE SCAN, aucun delai observe');
    ASSERT_EQ(fb.STATUS.STATE, E_STATE.READY, 'retour a READY immediat');
END_TEST

TEST 'Double verification contacteur : StuckClosed si le retour ne confirme jamais l ouverture'
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ADVANCE_TIME(401000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.BRAKECMD, 'magnetisation acquise : commande ouverture emise (ContactorFeedback ne confirme pas encore)');

    (* 1s de plus (FeedbackTimeout) : le retour n a jamais confirme -> defaut *)
    ADVANCE_TIME(1000000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.CONTACTORCHECK.STUCKCLOSED, 'commande ouverture emise mais jamais confirmee -> StuckClosed');
    ASSERT_TRUE(fb.STATUS.ERROR, 'defaut visible sur Status.Error');
    ASSERT_EQ(fb.STATUS.ERRORID, 16#0001, 'bit0 : incoherence retour contacteur');
    ASSERT_FALSE(fb.BRAKECMD, 'sortie sure sur defaut : BrakeCmd force a FALSE malgre la sequence terminee');
END_TEST

TEST 'Reset n acquitte le defaut contacteur que si la cause (retour) a reellement disparu'
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ADVANCE_TIME(401000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ADVANCE_TIME(1000000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.STATUS.ERROR, 'precondition : defaut StuckClosed actif');

    (* la cause disparait (le retour confirme enfin), mais SANS Reset : le defaut reste affiche *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := TRUE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.STATUS.ERROR, 'cause disparue mais pas acquittee : le defaut reste affiche (pas d auto-effacement)');

    (* front Reset, cause deja disparue : acquitte *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := TRUE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := TRUE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_FALSE(fb.STATUS.ERROR, 'Reset avec cause disparue (retour coherent) : defaut acquitte');
    ASSERT_TRUE(fb.BRAKECMD, 'plus de defaut : frein a nouveau relache (mouvement toujours demande)');
END_TEST

SETUP
VAR
    fb : FB_JOYSTICK;
    nx : INT := 5000;
    ny : INT := 5000;
    diagOk : ST_DIAG_DEVICE;
    diagDown : ST_DIAG_DEVICE;
END_VAR
END_SETUP

TEST 'TC-P08-001 Perte bus CAN pendant un mouvement arme neutralise, desarme et leve Error (auto-efface au retour)'
    diagDown.ONLINE := FALSE; diagDown.OPERATIONAL := FALSE; diagDown.ERROR := FALSE;
    diagDown.ERRORID := 0; diagDown.STATE := E_DIAG_STATE.INIT; diagDown.STATEATERROR := E_DIAG_STATE.DISABLED;
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;
    nx := 5000; ny := 5000;

    (* arme le geste au neutre, bus sain *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ADVANCE_TIME(110000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, 'precondition : geste arme');

    (* deplace le joystick : mouvement actif, bus toujours sain *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 60.0, 0.01, 'mouvement actif : consigne non nulle (RawX=8000, Neutral=5000)');
    ASSERT_EQ(fb.AXISCMDX.DIRECTION, 1, 'sens avant pendant le mouvement');
    ASSERT_NEAR(fb.AXISCMDY.SPEEDREF, 0.0, 0.01, 'RawY au neutre : axe Y reste a 0, aucun couplage entre les axes');
    ASSERT_EQ(fb.AXISCMDY.DIRECTION, 0, 'axe Y au neutre : Direction=0');

    (* perte du bus CAN EN PLEIN MOUVEMENT : neutralisation immediate + desarmement *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagDown, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.READY, 'bus CAN non operationnel doit bloquer Ready');
    ASSERT_TRUE(fb.ERROR, 'perte de comm doit lever Error (AF08)');
    ASSERT_EQ(fb.ERRORID, 16#0004, 'bit2 : HW/bus non operationnel');
    ASSERT_FALSE(fb.AXISCMDX.ENABLE, 'sorties axe X neutralisees des la perte du bus, meme en plein mouvement');
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 0.0, 0.01, 'consigne X coupee immediatement, pas de decel progressive');
    ASSERT_FALSE(fb.AXISCMDY.ENABLE, 'sorties axe Y aussi neutralisees (gate global, pas seulement l axe en mouvement)');
    ASSERT_NEAR(fb.AXISCMDY.SPEEDREF, 0.0, 0.01, 'consigne Y aussi coupee');
    ASSERT_FALSE(fb.DEADMANARMED, 'le geste est desarme par la perte du bus (AF08 TC-P08-001)');

    (* bus revient : pas de rearmement automatique, nouvel appui conscient exige *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.READY, 'bus revenu : FB de nouveau pret');
    ASSERT_FALSE(fb.ERROR, 'bus revenu : Error auto-effacee sans geste operateur (categorie Info/Warning, pas un Fault a acquitter)');
    ASSERT_EQ(fb.ERRORID, 0, 'bit2 efface automatiquement');
    ASSERT_FALSE(fb.DEADMANARMED, 'pas de rearmement automatique au retour du bus : nouvel appui conscient exige');
END_TEST

TEST 'TC-P08-002 Maintien DeadmanArmHoldTime : arme si tenu 100ms, annule si relache avant'
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;

    (* baseline : neutre, bouton relache *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'baseline : bouton relache, pas arme');

    (* front bouton : demarre le maintien, pas encore arme *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'front bouton seul ne doit pas armer immediatement (maintien requis)');

    (* 50ms plus tard : maintien pas termine -- l operateur bouge DEJA l axe X seul (Y reste
       neutre) pendant l attente : aucune commande ne doit partir tant que ce n est pas arme *)
    ADVANCE_TIME(50000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, '50ms < DeadmanArmHoldTime (100ms) : pas encore arme');
    ASSERT_NEAR(fb.CMDXVAL, 0.0, 0.01, 'consigne interne X (CmdXVal) forcee a 0 : pas encore arme');
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 0.0, 0.01, 'axe X seul pousse (RawX=8000, RawY neutre) mais pas encore arme : aucune commande ne part');

    (* 20ms de plus (toujours < 100ms) : cette fois l axe Y seul est pousse (X revient au
       neutre) -- meme preuve, isolee sur l autre axe *)
    ADVANCE_TIME(20000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 2000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, '70ms < DeadmanArmHoldTime (100ms) : toujours pas arme');
    ASSERT_NEAR(fb.CMDYVAL, 0.0, 0.01, 'consigne interne Y (CmdYVal) forcee a 0 : pas encore arme');
    ASSERT_NEAR(fb.AXISCMDY.SPEEDREF, 0.0, 0.01, 'axe Y seul pousse (RawY=2000, RawX neutre) mais pas encore arme : aucune commande ne part');

    (* relache a 50ms, avant la fin des 100ms de maintien : annule la tentative *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'relachement avant la fin du maintien annule la tentative');

    (* le bouton reste relache PENDANT 1s ENTIERE, manche pousse a fond (RawX=8000) tout du
       long : aucun armement differe, et surtout aucune commande de mouvement ne demarre,
       meme apres une longue attente sur une position hors neutre *)
    ADVANCE_TIME(1000000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'pas d armement differe sur une tentative deja annulee, meme apres 1s (nouvel appui conscient exige)');
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 0.0, 0.01, 'manche a fond depuis 1s mais jamais arme : toujours aucune commande de mouvement');

    (* nouveau front + maintien complet (110ms) : l armement redevient possible normalement *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ADVANCE_TIME(110000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, '110ms >= DeadmanArmHoldTime (100ms) : geste arme');
END_TEST

TEST 'TC-P08-004 Delai de grace protege l armement au neutre, puis le neutre prolonge desarme apres la grace'
