(* =======================================================================
   🔌 FB_Encoder_Abs — Acquisition codeur absolu (accès bus EtherCAT)
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Accès bus EtherCAT, extraction positions brutes et séquence de Preset SDO
   🔒 Polarité : EncoderAvailable=TRUE si communication bus et esclave OK
   🔌 Architecture : Module d'acquisition codeur absolu
   📄 Doc métier : DOC/AF/AF_Partie-09_Fonction_Encoder_v2.1.md
   ======================================================================= *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Encoder_Abs) ===

FUNCTION_BLOCK PUBLIC FB_Encoder_Abs
VAR_INPUT
    // === COMMANDES & AUTORISATIONS ===
    Enable              : BOOL;        // --> [CMD] Autorisation generale FB (TRUE=Autorise)
    Reset               : BOOL;        // --> [CMD] Acquittement defaut (front montant)
    PresetRequest       : BOOL;        // --> [CMD] Demande de preset (front montant)

    // === BUS ETHERCAT & CAPTEUR HW ===
    RawPosIn            : UDINT;       // --> [HW]  Position brute EtherCAT
    AlarmsIn            : UINT;        // --> [HW]  Codes alarmes bruts EtherCAT
    WarningsIn          : UINT;        // --> [HW]  Codes avertissements bruts EtherCAT
    SlaveOperational    : BOOL;        // --> [HW]  Statut esclave EtherCAT operationnel

    // === PARAMETRES & REGLAGES ===
    PointsPerRev        : UDINT := 8192; // --> [CFG] Resolution codeur (pts/tour)
    PresetValue         : UDINT;       // --> [CFG] Valeur cible de preset
    PresetTimeout       : TIME := T#2s;// --> [CFG] Temporisation max attente preset
    PresetTolerancePts  : UDINT := 10; // --> [CFG] Tolerance relecture post-preset (pts)
END_VAR
VAR_OUTPUT
    // === ETATS IEC & SYNOPTIQUE ===
    Ready               : BOOL;        // <-- [STAT] FB pret a fonctionner
    // 🧩 Statut transverse (forme cible) — regroupe Busy/Done/Error/ErrorId/State/StateAtError.
    // ErrorId bit0: "Com", bit1: "Preset Timeout".
    Status              : ST_FbStatus;

    // === MESURES & DONNEES CODEUR ===
    RawPos              : UDINT;       // <-- [DIAG] Position brute gelee si non disponible
    EncoderAvailable    : BOOL;        // <-- [STAT] Codeur operationnel et disponible
    AngleRaw            : UINT;        // <-- [DIAG] Angle brut sur un tour (MOD PointsPerRev)
    TurnCount           : UDINT;       // <-- [DIAG] Nombre de tours bruts (RawPos / PointsPerRev)

    // === COMMANDES & ECHANGE BUS ETHERCAT ===
    PresetAck           : BOOL;        // <-- [STAT] Pulse confirmation preset reussi
    PresetNak           : BOOL;        // <-- [STAT] Pulse refus / timeout preset
    PresetTriggerCmd    : WORD;        // <-- [ACT]  Ordre declenchement preset vers PDO Rx
    CodeSeqTriggerCmd   : WORD;        // <-- [ACT]  Ordre sequence code vers PDO Rx
    PresetValueOut      : UDINT;       // <-- [ACT]  Valeur de preset transmise au PDO Rx
END_VAR
VAR
    // === DETECTEURS DE FRONT ===
    ResetEdge           : R_TRIG;      // . [LOC] Detecteur front montant Reset
    ErrorEdge           : R_TRIG;      // . [LOC] Detecteur front montant Error
    PresetReqEdge       : R_TRIG;      // . [LOC] Detecteur front montant PresetRequest

    // === TEMPORISATEURS INTERNES ===
    PresetTimer         : TON;         // . [LOC] Temporisateur timeout sequence preset
    PresetTimerVisual   : TON;         // . [LOC] Temporisateur maintien visuel impulsion (500ms)

    // === VARIABLES INTERNES DE CALCUL & ETAT ===
    PresetSeqStep       : INT;         // . [LOC] Etape sequence preset (0:IDLE, 1:PULSE/WAIT)
    RawDiff             : DINT;        // . [LOC] Ecart signe entre RawPos et PresetValueOut
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Abs) ===

{region "§1 Gate"}
// 🛑 1. GATE
IF NOT Enable THEN
    EncoderAvailable := FALSE;
    Status.State := E_State.DISABLED;
    Ready := FALSE; Status.Busy := FALSE; Status.Done := FALSE;
    PresetTriggerCmd := 16#0000; CodeSeqTriggerCmd := 16#0000; PresetValueOut := 0;
    PresetSeqStep := 0;
    PresetTimer(IN := FALSE, PT := PresetTimeout);
    PresetTimerVisual(IN := FALSE, PT := T#500MS);
    RETURN;
END_IF;

Ready := TRUE;
Status.State := E_State.READY;
{endregion}

{region "§2 Reset front"}
// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);
{endregion}

{region "§3 Diagnostic bus et alarme"}
// 🔍 3. DIAGNOSTIC BUS / ALARME
IF (AlarmsIn <> 0) OR NOT SlaveOperational THEN
    Status.ErrorId := Status.ErrorId OR 16#0001;
ELSE
    Status.ErrorId := Status.ErrorId AND 16#FFFE; (* Auto-clearing dès que le bus et l'esclave sont OK *)
END_IF;
EncoderAvailable := (Status.ErrorId AND 16#0001) = 0;
{endregion}

{region "§4 Lecture position"}
// 📥 4. LECTURE POSITION — GELER SUR DOUTE (Partie10 §6)
// Si EncoderAvailable=FALSE : RawPos/AngleRaw/TurnCount conservent leur dernière valeur (pas de RETURN
// global ici pour ne pas geler aussi la séquence preset/l'état — seule la lecture est gelée).
IF EncoderAvailable THEN
    RawPos := RawPosIn;   // Sens de comptage géré côté codeur (CoE 6000h bit0, startup parameter CODESYS) — voir Partie10 §3bis. Plus de calcul ici.
    AngleRaw := UDINT_TO_UINT(RawPos MOD PointsPerRev);
    TurnCount := RawPos / PointsPerRev;
END_IF;
{endregion}

{region "§5 Séquence preset"}
// 🔧 5. SÉQUENCE PRESET (écriture bus)
// PresetTriggerCmd := 2 déclenche le référencement à PresetValue (valeur de commande, pas un
// masque de bits). CodeSeqTriggerCmd : rôle non identifié — laissé à 0, PAS piloté tant que sa
// fonction n'est pas confirmée. Ne jamais lui donner une valeur arbitraire.
PresetReqEdge(CLK := PresetRequest);
PresetAck := FALSE; PresetNak := FALSE; // pulses 1 cycle uniquement
CodeSeqTriggerCmd := 16#0000;           // non piloté — rôle inconnu, voir note ci-dessus
CASE PresetSeqStep OF
    0: // IDLE
        PresetTriggerCmd := 0;
        IF PresetReqEdge.Q AND EncoderAvailable THEN
            PresetValueOut := PresetValue;
            PresetSeqStep := 1;
            PresetTimer(IN := TRUE, PT := PresetTimeout);
        END_IF;
    1: // Déclenchement preset (laissé actif pendant 0.5s pour confort visuel en simulation/bus)
        PresetTriggerCmd := 2;   // Référence le codeur à PresetValueOut
        RawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(PresetValueOut);
        IF ABS(RawDiff) <= UDINT_TO_DINT(PresetTolerancePts) THEN
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := TRUE, PT := T#500MS);
            IF PresetTimerVisual.Q THEN
                PresetTriggerCmd := 0;
                PresetAck := TRUE;
                PresetSeqStep := 0;
                PresetTimerVisual(IN := FALSE, PT := T#500MS);
            END_IF;
        ELSIF PresetTimer.Q THEN
            PresetTriggerCmd := 0;
            PresetNak := TRUE;
            Status.ErrorId := Status.ErrorId OR 16#0002;
            PresetSeqStep := 0;
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := FALSE, PT := T#500MS);
        END_IF;
END_CASE;
IF ResetEdge.Q AND (PresetSeqStep = 0) THEN
    Status.ErrorId := Status.ErrorId AND 16#FFFD;
END_IF;
{endregion}

{region "§6 Error et StateAtError"}
// 🧾 6. ERROR / STATEATERROR
Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;

Status.Busy := (PresetSeqStep <> 0);
Status.Done := PresetAck;
{endregion}

(* ═══════════════════════════════════════════════════════════════
   🌊 FB_DiveSearch — Assistance plongée et recherche du fond Kobold
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF_Partie-04_Mode_SemiAuto_Sequenceur_v2.0.md §3ter
   🛡️ Sécurité : T81/T82. Jamais de descente assistée sans séquence 0→1→0 valide.
   🧩 Responsabilité : qualifie le Kobold et autorise uniquement la descente cohérente.
   🔌 Interface : intention de descente + mesures → autorisation + fond validé.
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK FB_DiveSearch
VAR_INPUT
    Enable                 : BOOL;
    Reset                  : BOOL;
    PowerContactorEngaged        : BOOL;
    Mode                   : E_Mode;
    MotionRequestActive    : BOOL; (* Intention déjà arbitrée en amont *)
    MotionDirection        : INT;  (* -1 = descente *)
    BucketIsOpen           : BOOL;
    KoboldImmersed         : BOOL; (* FALSE hors eau/fond ; TRUE immergé *)
    M1Position_M           : REAL;
    M2Position_M           : REAL;
    PositionsValid         : BOOL;
    DiveStartMin_M         : REAL;
    ImmersionUpper_M       : REAL;
    ImmersionLower_M       : REAL;
END_VAR
VAR_OUTPUT
    Ready                  : BOOL;
    Busy                   : BOOL;
    Done                   : BOOL;
    Error                  : BOOL;
    ErrorId                : WORD; (* bit0: préconditions, bit1: séquence Kobold invalide, bit2: configuration seuils invalide *)
    State                  : E_State;
    StateAtError           : E_State;
    DiveState              : E_DiveSearchState;
    DescendPermit          : BOOL; (* Autorise uniquement la demande de descente active *)
    KoboldMeasureEnable    : BOOL;
    BottomTouchConfirmed   : BOOL;
    OperatorActionId       : WORD;
    OperatorAction         : STRING(120);
END_VAR
VAR
    ResetEdge              : R_TRIG;
    KoboldRiseEdge         : R_TRIG;
    KoboldFallEdge         : F_TRIG;
    ImmersionConfirmed     : BOOL;
    ErrorCausePresent      : BOOL;
END_VAR

IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    DescendPermit := FALSE; KoboldMeasureEnable := FALSE;
    BottomTouchConfirmed := FALSE;
    State := E_State.DISABLED;
    StateAtError := E_State.DISABLED;
    DiveState := E_DiveSearchState.WAIT_PRECONDITIONS;
    OperatorActionId := 0; OperatorAction := '';
    ImmersionConfirmed := FALSE;
    RETURN;
END_IF;

ResetEdge(CLK := Reset);
KoboldRiseEdge(CLK := KoboldImmersed);
KoboldFallEdge(CLK := KoboldImmersed);

ErrorCausePresent := (DiveStartMin_M < ImmersionUpper_M)
                  OR (ImmersionUpper_M <= ImmersionLower_M);
IF ErrorCausePresent THEN
    ErrorId := ErrorId OR 16#0004;
END_IF;

(* Reset = front + causes disparues ; aucun redémarrage automatique. *)
IF ResetEdge.Q AND NOT ErrorCausePresent AND NOT KoboldImmersed AND NOT MotionRequestActive THEN
    ErrorId := 16#0000;
    ImmersionConfirmed := FALSE;
    BottomTouchConfirmed := FALSE;
    StateAtError := E_State.DISABLED;
    DiveState := E_DiveSearchState.WAIT_PRECONDITIONS;
END_IF;

DescendPermit := FALSE; KoboldMeasureEnable := FALSE;
Ready := FALSE; Busy := FALSE; Done := FALSE;
OperatorActionId := 0; OperatorAction := '';

IF ErrorId <> 16#0000 THEN
    State := E_State.READY;
    DiveState := E_DiveSearchState.ERROR_HOLD;
    OperatorActionId := 16#0180;
    OperatorAction := 'Vérifier les conditions puis réarmer avant une nouvelle plongée.';
ELSE
    CASE DiveState OF
        E_DiveSearchState.WAIT_PRECONDITIONS:
            State := E_State.INIT;
            IF NOT BucketIsOpen OR NOT PositionsValid OR KoboldImmersed
               OR (M1Position_M < DiveStartMin_M) OR (M2Position_M < DiveStartMin_M) THEN
                OperatorActionId := 16#0100;
                OperatorAction := 'Vérifier les conditions initiales de plongée.';
            ELSE
                DiveState := E_DiveSearchState.READY_TO_DESCEND;
            END_IF;

        E_DiveSearchState.READY_TO_DESCEND:
            State := E_State.READY;
            Ready := TRUE;
            OperatorActionId := 16#0101;
            OperatorAction := 'Demander une descente pour rechercher le fond.';
            IF MotionRequestActive AND (MotionDirection = -1) THEN
                DiveState := E_DiveSearchState.SEARCHING_IMMERSION;
            END_IF;

        E_DiveSearchState.SEARCHING_IMMERSION:
            State := E_State.BUSY;
            Busy := TRUE;
            DescendPermit := MotionRequestActive AND (MotionDirection = -1);
            KoboldMeasureEnable := TRUE;
            OperatorActionId := 16#0102;
            OperatorAction := 'Maintenir la descente : recherche immersion Kobold.';
            IF KoboldRiseEdge.Q THEN
                IF (M1Position_M <= ImmersionUpper_M) AND (M1Position_M >= ImmersionLower_M)
                   AND (M2Position_M <= ImmersionUpper_M) AND (M2Position_M >= ImmersionLower_M) THEN
                    ImmersionConfirmed := TRUE;
                    DiveState := E_DiveSearchState.SEARCHING_BOTTOM;
                ELSE
                    ErrorId := ErrorId OR 16#0002;
                    StateAtError := State;
                END_IF;
            ELSIF (M1Position_M < ImmersionLower_M) OR (M2Position_M < ImmersionLower_M) THEN
                ErrorId := ErrorId OR 16#0002;
                StateAtError := State;
            END_IF;

        E_DiveSearchState.SEARCHING_BOTTOM:
            State := E_State.BUSY;
            Busy := TRUE;
            DescendPermit := MotionRequestActive AND (MotionDirection = -1);
            KoboldMeasureEnable := TRUE;
            OperatorActionId := 16#0103;
            OperatorAction := 'Maintenir la descente : immersion validée, recherche du fond.';
            IF KoboldFallEdge.Q AND ImmersionConfirmed THEN
                BottomTouchConfirmed := TRUE;
                ImmersionConfirmed := FALSE;
                DiveState := E_DiveSearchState.BOTTOM_CONFIRMED;
            END_IF;

        E_DiveSearchState.BOTTOM_CONFIRMED:
            State := E_State.DONE;
            Done := TRUE;
            OperatorActionId := 16#0104;
            OperatorAction := 'Fond détecté : demander la fermeture ou l extraction.';

        E_DiveSearchState.ERROR_HOLD:
            State := E_State.READY;
    END_CASE;
END_IF;

Error := (ErrorId <> 16#0000);

// ═══════════════════════════════════════════════════════════════
// 🧪 ST_TestCaseConfig — Configuration d'un cas de test
// ═══════════════════════════════════════════════════════════════

TYPE ST_TestCaseConfig :
STRUCT
    Name      : STRING(32);          // Libellé (ex. 'TC-01 Armement nominal')
    FirstStep : INT;                 // Première étape (SETUP) du cas de test
END_STRUCT
END_TYPE

SETUP
VAR
    fb : FB_RAMP;
END_VAR
END_SETUP

TEST 'Accel : consigne progresse par pas de AccelRate*CycleTimeS vers la cible'
    fb(TARGET := 100.0, ACCELRATE := 50.0, DECELRATE := 200.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 5.0, 0.001, 'pas 1 : 0 -> 5.0 (50%/s * 0.1s), s eloigne de zero donc AccelRate');

    fb(TARGET := 100.0, ACCELRATE := 50.0, DECELRATE := 200.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 10.0, 0.001, 'pas 2 : 5.0 -> 10.0, meme taux tant que la cible n est pas atteinte');
END_TEST

TEST 'Decel : retour vers zero utilise DecelRate (taux different d Accel)'
    (* monte a 40% avec Accel *)
    fb(TARGET := 40.0, ACCELRATE := 50.0, DECELRATE := 10.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 5.0, 0.001, 'montee : AccelRate (50%/s)');
    fb(TARGET := 40.0, ACCELRATE := 50.0, DECELRATE := 10.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 10.0, 0.001, 'montee : toujours AccelRate, cible pas encore atteinte');

    (* cible ramenee a 0 : retour vers zero -> DecelRate, taux bien plus faible ici *)
    fb(TARGET := 0.0, ACCELRATE := 50.0, DECELRATE := 10.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 9.0, 0.001, 'retour vers zero : DecelRate (10%/s), pas de 1.0 seulement -- pas AccelRate');
END_TEST

TEST 'Atteinte de la cible : la rampe s arrete pile dessus, pas de depassement'
    fb(TARGET := 3.0, ACCELRATE := 50.0, DECELRATE := 200.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 3.0, 0.001, 'le pas (5.0) depasserait la cible (3.0) : clampe exactement dessus, pas de depassement');

    fb(TARGET := 3.0, ACCELRATE := 50.0, DECELRATE := 200.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 3.0, 0.001, 'cible deja atteinte : reste stable, aucune oscillation autour de la cible');
END_TEST

TEST 'Garde-fou : une valeur Current deja hors plage (etat corrompu) reste bornee a +/-100'
    (* Simule un etat interne deja corrompu au-dela de la plage normalisee -- le FB doit se
       proteger lui-meme, pas seulement empecher d y entrer *)
    fb(TARGET := 500.0, ACCELRATE := 1000.0, DECELRATE := 1000.0, CYCLETIMES := 1.0);
    ASSERT_NEAR(fb.CURRENT, 100.0, 0.001, 'Target hors plage (500) et grand pas (1000%/s) : Current ne depasse jamais +100');
END_TEST

// ═══════════════════════════════════════════════════════════════
// 🧪 FB_TranslationReportFinalizer — Rapport incrémental Translation
// ───────────────────────────────────────────────────────────────
// 🎯 Responsabilité UNIQUE : enregistrer les verdicts réels et finaliser
//    un rapport borné. Aucun parcours du graphe de transitions.
// ═══════════════════════════════════════════════════════════════

FUNCTION_BLOCK PUBLIC FB_TranslationReportFinalizer
VAR_INPUT
    RunStart        : BOOL;
    RequestedCaseId : INT;
    Busy            : BOOL;
    StepVerdict         : BOOL;
    StepId              : INT;
    StepCaseId          : INT;
    StepPassed          : BOOL;
    StepFailReason      : E_TestFailReason;
    StepFailedCheckIdx  : INT;
    StepDuration        : TIME;
    StepObservedBool    : BOOL;
    StepObservedDint    : DINT;
    StepObservedReal    : REAL;
    Finalize       : BOOL;
    TerminalState  : E_TestTerminalState;
    ErrorCode      : INT;
    ErrorMessage   : STRING(160);
END_VAR
VAR_IN_OUT
    StepTable : ARRAY[1..GVL_PLC_Tests_Const.MaxSteps]     OF ST_TestStepConfig;
    CaseTable : ARRAY[1..GVL_PLC_Tests_Const.MaxTestCases] OF ST_TestCaseConfig;
    Report    : ST_TestSuiteReport;
    Result    : ST_TranslationTestResult;
END_VAR
VAR
    Idx             : INT;
    CaseIdx         : INT;
    CasesTotalLocal : INT;
    CasesPassedLocal: INT;
    CasesFailedLocal: INT;
    FirstFailedCase : INT;
    ReasonText      : STRING(20);
    EntryText       : STRING(80);
END_VAR
// === IMPLEMENTATION ===
IF RunStart THEN
    Report.Name := 'Translation Validation';
    Report.InProgress := TRUE;
    Report.AllPassed := FALSE;
    Report.AnyFailed := FALSE;
    Report.Aborted := FALSE;
    Report.TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    Report.ErrorCode := 0;
    Report.ErrorMessage := '';
    Report.FailedTestCase := 0;
    Report.FailureSummary := '';
    Report.CurrentStepId := 0;
    Report.CurrentCaseId := 0;
    Report.Duration := T#0s;
    Report.RunCounter := Report.RunCounter + 1;
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxSteps DO
        Report.Steps[Idx].Executed := FALSE;
        Report.Steps[Idx].Passed := FALSE;
        Report.Steps[Idx].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Steps[Idx].FailedCheckIdx := 0;
        Report.Steps[Idx].FailedInvariantId := 0;
        Report.Steps[Idx].Duration := T#0s;
    END_FOR;
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        Report.Cases[Idx].Name := CaseTable[Idx].Name;
        Report.Cases[Idx].Executed := FALSE;
        Report.Cases[Idx].Ok := FALSE;
        Report.Cases[Idx].FailedStepId := 0;
        Report.Cases[Idx].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Cases[Idx].Duration := T#0s;
    END_FOR;
    Result.TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    Result.RequestedCaseId := RequestedCaseId;
    Result.ExecutedCaseId := 0;
    Result.AllPassed := FALSE;
    Result.AnyFailed := FALSE;
    Result.FailedCaseId := 0;
    Result.FailedCaseName := '';
    Result.FailReason := E_TestFailReason.FAIL_NONE;
    Result.ErrorCode := 0;
    Result.ErrorMessage := '';
    Result.CasesTotal := 0;
    Result.CasesPassed := 0;
    Result.CasesFailed := 0;
    Result.Duration := T#0s;
    Result.RunCounter := Report.RunCounter;
END_IF;

IF Busy THEN
    Report.Duration := Report.Duration + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
END_IF;

// 🧾 Agrégation incrémentale : validation séparée avant toute indexation.
IF StepVerdict THEN
    IF StepId < 1 OR StepId > GVL_PLC_Tests_Const.MaxSteps THEN
        Report.ErrorCode := 1050;
        Report.ErrorMessage := 'Verdict StepId hors limites';
        Report.AnyFailed := TRUE;
        RETURN;
    END_IF;
    Report.Steps[StepId].Executed := TRUE;
    Report.Steps[StepId].Passed := StepPassed;
    Report.Steps[StepId].FailReason := StepFailReason;
    Report.Steps[StepId].FailedCheckIdx := StepFailedCheckIdx;
    Report.Steps[StepId].Duration := StepDuration;
    Report.Steps[StepId].ObservedBool := StepObservedBool;
    Report.Steps[StepId].ObservedDint := StepObservedDint;
    Report.Steps[StepId].ObservedReal := StepObservedReal;
    Report.CurrentStepId := StepId;
    Report.CurrentCaseId := StepCaseId;

    IF StepCaseId >= 1 THEN
        IF StepCaseId <= GVL_PLC_Tests_Const.MaxTestCases THEN
        IF NOT Report.Cases[StepCaseId].Executed THEN
            Report.Cases[StepCaseId].Executed := TRUE;
            Report.Cases[StepCaseId].Ok := TRUE;
        END_IF;
        Report.Cases[StepCaseId].Duration := Report.Cases[StepCaseId].Duration + StepDuration;
        IF NOT StepPassed THEN
            Report.Cases[StepCaseId].Ok := FALSE;
            IF Report.Cases[StepCaseId].FailedStepId = 0 THEN
                Report.Cases[StepCaseId].FailedStepId := StepId;
                Report.Cases[StepCaseId].FailReason := StepFailReason;
            END_IF;
        END_IF;
        ELSE
            Report.ErrorCode := 1051;
            Report.ErrorMessage := 'Verdict CaseId hors limites';
            Report.AnyFailed := TRUE;
        END_IF;
    ELSE
        Report.ErrorCode := 1051;
        Report.ErrorMessage := 'Verdict CaseId hors limites';
        Report.AnyFailed := TRUE;
    END_IF;
END_IF;

IF Finalize THEN
    Report.InProgress := FALSE;
    Report.TerminalState := TerminalState;
    Report.ErrorCode := ErrorCode;
    Report.ErrorMessage := ErrorMessage;
    Report.Aborted := (TerminalState = E_TestTerminalState.TEST_TERMINAL_ABORTED);
    CasesTotalLocal := 0;
    CasesPassedLocal := 0;
    CasesFailedLocal := 0;
    FirstFailedCase := 0;
    Report.FailureSummary := '';

    FOR CaseIdx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        IF Report.Cases[CaseIdx].Executed THEN
            CasesTotalLocal := CasesTotalLocal + 1;
            IF Report.Cases[CaseIdx].Ok THEN
                CasesPassedLocal := CasesPassedLocal + 1;
            ELSE
                CasesFailedLocal := CasesFailedLocal + 1;
                IF FirstFailedCase = 0 THEN FirstFailedCase := CaseIdx; END_IF;
                CASE Report.Cases[CaseIdx].FailReason OF
                    E_TestFailReason.FAIL_TIMEOUT: ReasonText := 'FAIL_TIMEOUT';
                    E_TestFailReason.FAIL_CHECK: ReasonText := 'FAIL_CHECK';
                    E_TestFailReason.FAIL_INVARIANT: ReasonText := 'FAIL_INVARIANT';
                    E_TestFailReason.FAIL_WINDOW_EARLY: ReasonText := 'FAIL_WINDOW_EARLY';
                    E_TestFailReason.FAIL_ABORTED: ReasonText := 'FAIL_ABORTED';
                ELSE ReasonText := 'FAIL_NONE';
                END_CASE;
                EntryText := CONCAT(Report.Cases[CaseIdx].Name, ' (step ');
                EntryText := CONCAT(EntryText, INT_TO_STRING(Report.Cases[CaseIdx].FailedStepId));
                EntryText := CONCAT(EntryText, '): ');
                EntryText := CONCAT(EntryText, ReasonText);
                IF Report.FailureSummary = '' THEN
                    Report.FailureSummary := EntryText;
                ELSE
                    Report.FailureSummary := CONCAT(Report.FailureSummary, ' | ');
                    Report.FailureSummary := CONCAT(Report.FailureSummary, EntryText);
                END_IF;
            END_IF;
        END_IF;
    END_FOR;

    Report.AllPassed := (TerminalState = E_TestTerminalState.TEST_TERMINAL_DONE)
                     AND (CasesTotalLocal > 0)
                     AND (CasesFailedLocal = 0);
    Report.AnyFailed := NOT Report.AllPassed;
    Report.FailedTestCase := FirstFailedCase;

    Result.TerminalState := TerminalState;
    Result.RequestedCaseId := RequestedCaseId;
    Result.ExecutedCaseId := Report.CurrentCaseId;
    Result.AllPassed := Report.AllPassed;
    Result.AnyFailed := Report.AnyFailed;
    Result.FailedCaseId := FirstFailedCase;
    IF FirstFailedCase > 0 THEN
        Result.FailedCaseName := Report.Cases[FirstFailedCase].Name;
        Result.FailReason := Report.Cases[FirstFailedCase].FailReason;
    ELSE
        Result.FailedCaseName := '';
        Result.FailReason := E_TestFailReason.FAIL_NONE;
    END_IF;
    Result.ErrorCode := ErrorCode;
    Result.ErrorMessage := ErrorMessage;
    Result.CasesTotal := CasesTotalLocal;
    Result.CasesPassed := CasesPassedLocal;
    Result.CasesFailed := CasesFailedLocal;
    Result.Duration := Report.Duration;
    Result.RunCounter := Report.RunCounter;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   📤 PRG_06_Outputs_LD — Écriture des SORTIES physiques (PROGRAMME LADDER)
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF_Partie-06_Acquisition_Qualification_IO_v2.1.md §5
   ⚙️ Exécuté par la tâche PLC en position 6 (après PRG_05_Translation).
   📄 Converti automatiquement en Ladder Diagram (<LD>) dans CODESYS.
   🛡️ LOT_STRUCTURE_INTERLOCKS_LD (2026-08) : barrières finales M1/M2/M3
