    StepTable[StepB6ReverseJoy].StimulusId := 11;
    StepTable[StepB6ReverseJoy].CheckIdx[1] := 22;
    StepTable[StepB6ReverseJoy].CheckIdx[2] := 23;
    StepTable[StepB6ReverseJoy].TimeoutPT := T#5s;
    StepTable[StepB6ReverseJoy].NextOnPass := StepB6Teardown;
    StepTable[StepB6ReverseJoy].NextOnFail := StepB6Teardown;
    StepTable[StepB6ReverseJoy].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB6Teardown].Name := 'Tcb6 Teardown';
    StepTable[StepB6Teardown].CaseId := 6;
    StepTable[StepB6Teardown].StimulusId := 1;
    StepTable[StepB6Teardown].CheckIdx[1] := 1;
    StepTable[StepB6Teardown].TimeoutPT := T#12s;
    StepTable[StepB6Teardown].NextOnPass := 0;
    StepTable[StepB6Teardown].NextOnFail := 0;
    StepTable[StepB6Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    TableReady := TRUE;
END_IF;

// 3. 📥 ACQUIRE
ProbeBool[SigHealthyIdle] := NOT instBucket.Error
                             AND NOT _BucketState.StateIncoherent;

ProbeBool[SigBucketBusy]   := instBucket.Busy;
ProbeBool[SigBucketDone]    := instBucket.Done;
ProbeBool[SigBucketError]   := instBucket.Error;
ProbeBool[SigM1SlipDetected] := instBucket.M1SlipDetected;
ProbeBool[SigM1SafeStop]    := PRG_03_Safety.instSafetyWinchM1.SafeStop;
ProbeBool[SigM1PowerCutOff] := PRG_03_Safety.instSafetyWinchM1.PowerCutOff;
ProbeBool[SigBucketIsOpen]  := _BucketState.IsOpen;
ProbeBool[SigBucketIsClosed] := _BucketState.IsClosed;
ProbeBool[SigM2StartStop]   := instBucket.M2_StartStop;
ProbeBool[SigM2ForceSlowSpeed] := instBucket.M2_ForceSlowSpeed;

ProbeDint[SigBucketErrorId] := WORD_TO_DINT(instBucket.ErrorId);
ProbeDint[SigM2Direction]   := INT_TO_DINT(instBucket.M2_Direction);
ProbeDint[SigSafetyM1ErrorId] := WORD_TO_DINT(PRG_03_Safety.instSafetyWinchM1.ErrorId);

ProbeReal[SigActiveOffsetM]   := instBucket.ActiveOffsetM;
ProbeReal[SigRemainingTravelM] := instBucket.RemainingTravelM;
ProbeReal[SigM2CablePos]      := PRG_02_Encoders.instEncoderScaleM2.CablePosM;
ProbeReal[SigM2TopLimit]       := instWinchM2.TopLimitM;

// 4. ⚙️ MOTEUR
Sequencer(
    Start := Start,
    Abort := Abort,
    CaseId := CaseId,
    StepTable := StepTable,
    CheckTable := CheckTable,
    CaseTable := CaseTable,
    InvariantTable := InvariantTable,
    ProbeBool := ProbeBool,
    ProbeDint := ProbeDint,
    ProbeReal := ProbeReal,
    Report := Report,
    Busy => Busy,
    Done => Done,
    AnyFailed => AnyFailed,
    TerminalState => TerminalState,
    ConfigError => ConfigError,
    ConfigErrorStepId => ConfigErrorStepId,
    ConfigErrorCheckIdx => ConfigErrorCheckIdx,
    ErrorCode => ErrorCode,
    ErrorMessage => ErrorMessage,
    ActiveStimulusId => ActiveStimulusId,
    StepElapsed => StepElapsed
);

// 5. ⚡ STIMULI
CASE ActiveStimulusId OF
    0: // 🔓 Neutre
        CmdOpen_IHM := FALSE;
        CmdClose_IHM := FALSE;
        JoystickY_StartStop := FALSE;
        JoystickY_Direction := 0;
        ConfirmOpenPosition := FALSE;
        HomedM1 := TRUE;
        InhibitM1 := FALSE;
        GVL_PLC_Tests.OverrideM1Slip := FALSE;
        GVL_PLC_Tests.OverrideM1SlipCritical := FALSE;
        GVL_PLC_Tests.OverrideM2Stuck := FALSE;
        GVL_PLC_Tests.OverrideM2BootDrift := FALSE;

    1: // Reset & Saine
        CmdOpen_IHM := FALSE;
        CmdClose_IHM := FALSE;
        JoystickY_StartStop := FALSE;
        ConfirmOpenPosition := TRUE; // Forcer état sain
        HomedM1 := TRUE;
        InhibitM1 := FALSE;
        GVL_PLC_Tests.OverrideM1Slip := FALSE;
        GVL_PLC_Tests.OverrideM1SlipCritical := FALSE;
        GVL_PLC_Tests.OverrideM2Stuck := FALSE;
        GVL_PLC_Tests.OverrideM2BootDrift := FALSE;

    2: // Fermeture Nominale
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := 1;
        ConfirmOpenPosition := FALSE;
        HomedM1 := TRUE;

    3: // Glissement Modéré M1
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := 1;
        GVL_PLC_Tests.OverrideM1Slip := TRUE;

    4: // Glissement Critique M1
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := 1;
        GVL_PLC_Tests.OverrideM1SlipCritical := TRUE;

    5: // Fermeture nominale (TC-B3)
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := 1;
        ConfirmOpenPosition := FALSE;

    6: // Boot Incohérent
        GVL_PLC_Tests.OverrideM2BootDrift := TRUE;
        CmdOpen_IHM := FALSE;
        CmdClose_IHM := FALSE;
        JoystickY_StartStop := FALSE;

    7: // Recalage manuel
        ConfirmOpenPosition := TRUE;
        CmdOpen_IHM := FALSE;
        CmdClose_IHM := FALSE;
        JoystickY_StartStop := FALSE;

    8: // Perte Homing
        HomedM1 := FALSE;
        CmdClose_IHM := FALSE;
        CmdOpen_IHM := FALSE;

    9: // Inhibition M1 + Mouvement
        InhibitM1 := TRUE;
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := 1;
        GVL_PLC_Tests.OverrideM1Slip := TRUE;

    10: // Relâchement Homme-Mort
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := FALSE;
        JoystickY_Direction := 1;

    11: // Commande opposée
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := -1;
END_CASE;

// Liaison IHM / Métier
IF Busy THEN
    instBucket.CmdOpen_IHM := CmdOpen_IHM;
    instBucket.CmdClose_IHM := CmdClose_IHM;
    instBucket.JoystickY_StartStop := JoystickY_StartStop;
    instBucket.JoystickY_Direction := JoystickY_Direction;
    instBucket.ConfirmOpenPosition := ConfirmOpenPosition;
    instBucket.HomedM1 := HomedM1;
    instBucket.InhibitM1 := InhibitM1;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   🌉 FB_CfgPersistBridge_BucketCfg — Pont persistance générique pour ST_BucketCfg
   ───────────────────────────────────────────────────────────────
   🎯 Voir FB_CfgPersistBridge_SyncCfg.st (Lot 3a) pour la logique de référence — identique,
   seul le type ST_BucketCfg change. La copie struct-à-struct gère aussi le sous-struct imbriqué
   Config : ST_BucketConfig automatiquement (pas de traitement spécial nécessaire).
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK FB_CfgPersistBridge_BucketCfg
VAR_IN_OUT
    Hmi     : ST_BucketCfg; (* 🖥️ ex. GVL_IHM.M2TreuilBenne.Bucket.Cfg *)
    Persist : ST_BucketCfg; (* 💾 ex. GVL_PERSISTENT._BucketCfgPersist *)
END_VAR
VAR_OUTPUT
    JustRestored : BOOL;
END_VAR

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   🪜 FB_SpeedStep — Décodeur palier → 4 contacteurs (1 par treuil)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-10_Fonction_Winch_v2.0.md §2, §6
   📄 Audit P0.2 : AUDIT_Winch_v1.0 (archivé) §2.2
   📥 SpeedRefPct    : consigne 0..100 % (déjà rampée en amont, ABS)
   📥 Table          : ST_SpeedStepTable propre AU TREUIL appelant
                        (M1 et M2 ont chacune la leur — pas de table globale)
   📥 MaxStepNumber  : plafond palier (1..5), borné et validé ici
   📤 Contactor1..4  : état de chaque contacteur de vitesse (BOOL individuel,
                        lu directement dans `Table.P<palier>R<relais>`)
   📤 StepNumber     : n° palier courant (0 = arrêt, 1..5)
   📤 ConfigError    : TRUE si table invalide ou MaxStepNumber hors bornes
   📤 ConfigErrorId  : WORD bitfield (bit0 = config invalide)
   🧩 Réutilisation lib Util (Partie3 §0) : HYSTERESIS pour la sélection
      de palier anti-battement — AUCUN seuil "maison" recalculé.
   ⚠️ CORRECTIF interface HYSTERESIS (2026-07-01) : `Util` 3.5.19.0 expose
      `HYSTERESIS(IN, HIGH, LOW : INT → OUT : BOOL)` (TRUE si IN < LOW,
      FALSE si IN > HIGH, maintien entre les deux) — `SpeedRefPct` (REAL)
      est converti en INT (`REAL_TO_INT`) avant appel.
   ⚠️ ÉVOLUTION (retour terrain 2026-07-01) : `StepMask` (BYTE packé) est
      remplacé par 4 sorties BOOL individuelles, lues directement dans la
      table (`P<palier>R<relais>`) — plus de bit-extraction côté FB_Winch,
      paramétrage un contacteur à la fois pendant la mise en service.
   ⚠️ Brique réduite (Partie3 §1bis) : pas d'Enable/Reset/ErrorId/State
      au sens "FB métier" — c'est un décodeur pur, composé À L'INTÉRIEUR de
      FB_Winch, qui porte lui la sécurité/le contrat complet.
      ➕ MAIS on ajoute 2 sorties locales `ConfigError` + `ConfigErrorId`
      pour signaler une table de config invalide (P0.2 audit).
   🆕 AJOUT (2026-07-03quinquies, spec descente/couple) : `MaxStepNumber` plafonne
      le palier atteignable (défaut 5 = comportement inchangé). Sert à `FB_Winch`
      pour limiter la vitesse en descente (charge entraînante, pas besoin d'aller
      vite) SANS changer la logique de décodage elle-même — juste un plafond
      appliqué APRÈS la sélection par hystérésis, avant la lecture de la table.
   🛡️ CORRECTIF P0.2 (2026-07-21) :
      - Bornage `MaxStepNumber` ∈ [1..5] dès l'entrée
      - Validation table : seuils croissants 0..100 %, hystérésis > 0,
        contacteurs cohérents (au moins 1 par palier 2..MaxStepNumber ; palier 1 tout FALSE autorisé)
      - Sortie `ConfigError` / `ConfigErrorId` (bit0 = table invalide)
      - Forçage sorties sûres (contacteurs FALSE, StepNumber=0) si erreur config
      - Reset sur front (R_TRIG) + cause disparue (conforme Partie 3 §5)
   ════════════════════════════════════════════════════════════════ *)

{attribute 'qualified_only'}
{attribute 'hide_all_locals'}

// === DECLARATION (à coller dans la partie déclaration du POU FB_SpeedStep) ===

FUNCTION_BLOCK PUBLIC FB_SpeedStep
VAR_INPUT
    Enable            : BOOL;               // Piloté par FB_Winch : FALSE = treuil à l'arrêt (palier 0)
    SpeedRefPct       : REAL;                // Consigne vitesse 0..100 % (déjà rampée par FB_Winch)
    Table             : ST_SpeedStepTable;   // Table des 5 paliers (contacteurs + seuils), propre à CE treuil
    HystMargin        : REAL := 2.0;         // Marge anti-battement (%) autour de chaque seuil
    MaxStepNumber     : INT := 5;            // 🆕 Plafond palier atteignable (1..5) — 5 = pas de restriction
    MeasuredSpeedBand : INT := 0;            // Bande vitesse réelle validée (0 = inconnue)
    SpeedGuardEnable  : BOOL := FALSE;       // 🛡️ Garde-fou palier activable après validation terrain
    SpeedGuardReady   : BOOL := FALSE;       // 🟢 Vitesse stable et conditions de passage validées
END_VAR
VAR_OUTPUT
    Contactor1        : BOOL;   // Contacteur de vitesse 1 pour le palier courant
    Contactor2        : BOOL;   // Contacteur de vitesse 2 pour le palier courant
    Contactor3        : BOOL;   // Contacteur de vitesse 3 pour le palier courant
    Contactor4        : BOOL;   // Contacteur de vitesse 4 pour le palier courant
    StepNumber        : INT;    // N° palier courant (0 = arrêt, 1..5)
    SpeedGuardLimited : BOOL;   // TRUE si le garde-fou a limité le palier demandé
    ConfigError       : BOOL;   // 🛡️ Miroir de ConfigErrorId <> 0 (config table invalide)
    ConfigErrorId     : WORD;   // 🛡️ Bitfield config : bit0 = table invalide (seuils, hyst, contacteurs)
END_VAR
VAR
    SpeedRefInt       : INT;          // Consigne convertie en INT (interface HYSTERESIS)
    Hyst1             : HYSTERESIS;   // 🧱 Lib Util — transition palier 1→2
    Hyst2             : HYSTERESIS;   // 🧱 Lib Util — transition palier 2→3
    Hyst3             : HYSTERESIS;   // 🧱 Lib Util — transition palier 3→4
    Hyst4             : HYSTERESIS;   // 🧱 Lib Util — transition palier 4→5

    // 🛡️ Validation config locale (P0.2 audit)
    _ConfigValid      : BOOL;         // Résultat validation table + MaxStepNumber
    _ConfigValidPrev  : BOOL;         // Mémoire cycle précédent pour détection front
    _ConfigErrorTrig  : R_TRIG;       // Front montant erreur config (pour reset)
    _ConfigErrorIdInt : WORD;         // Accumulateur interne défauts config
    _MaxStepClamped   : INT;          // MaxStepNumber borné [1..5]
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_SpeedStep) ===

// ─────────────────────────────────────────────────────────────────────────
// 🛡️ 0. VALIDATION CONFIGURATION (P0.2) — exécutée CHAQUE cycle pour détecter
//    toute corruption IHM/PERSISTENT, même siEnable=FALSE (sorties sûres forcée)
// ─────────────────────────────────────────────────────────────────────────

// 🔧 Bornage systématique MaxStepNumber ∈ [1..5]
IF MaxStepNumber < 1 THEN
    _MaxStepClamped := 1;
ELSIF MaxStepNumber > 5 THEN
    _MaxStepClamped := 5;
ELSE
    _MaxStepClamped := MaxStepNumber;
END_IF;

// 🔍 Validation table ST_SpeedStepTable
// Critères (Partie 9 §2 + audit P0.2) :
// 1. Seuils croissants stricts : StepThreshold_Pct[1] < [2] < [3] < [4] < [5]
// 2. Seuils dans [0..100] %
// 3. HystMargin > 0
// 4. Pour chaque palier 2.._MaxStepClamped : au moins 1 contacteur TRUE (cohérence câblage)
//    Le palier 1 peut légitimement avoir les 4 contacteurs FALSE : résistances rotoriques
//    toutes insérées = vitesse minimale. On ne valide pas les paliers jamais atteignables.
_ConfigValid := TRUE;
_ConfigErrorIdInt := 16#0000;

// Critère 1 : seuils croissants
IF NOT (Table.StepThreshold_Pct[1] < Table.StepThreshold_Pct[2] AND
        Table.StepThreshold_Pct[2] < Table.StepThreshold_Pct[3] AND
        Table.StepThreshold_Pct[3] < Table.StepThreshold_Pct[4] AND
        Table.StepThreshold_Pct[4] < Table.StepThreshold_Pct[5]) THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;  // bit0
END_IF;

// Critère 2 : seuils dans [0..100]
IF (Table.StepThreshold_Pct[1] < 0.0) OR (Table.StepThreshold_Pct[5] > 100.0) THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
END_IF;

// Critère 3 : hystérésis > 0
IF HystMargin <= 0.0 THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
END_IF;

// Critère 4 : cohérence contacteurs par palier (seulement jusqu'au plafond actif)
IF _ConfigValid THEN
    // Palier 1 : les 4 sorties FALSE sont une configuration valide de vitesse minimale.
    // Palier 2
    IF _MaxStepClamped >= 2 THEN
        IF NOT (Table.P2R1 OR Table.P2R2 OR Table.P2R3 OR Table.P2R4) THEN
            _ConfigValid := FALSE;
            _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
        END_IF;
    END_IF;
    // Palier 3
    IF _MaxStepClamped >= 3 THEN
        IF NOT (Table.P3R1 OR Table.P3R2 OR Table.P3R3 OR Table.P3R4) THEN
            _ConfigValid := FALSE;
            _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
        END_IF;
    END_IF;
    // Palier 4
    IF _MaxStepClamped >= 4 THEN
        IF NOT (Table.P4R1 OR Table.P4R2 OR Table.P4R3 OR Table.P4R4) THEN
            _ConfigValid := FALSE;
            _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
        END_IF;
    END_IF;
    // Palier 5
    IF _MaxStepClamped >= 5 THEN
        IF NOT (Table.P5R1 OR Table.P5R2 OR Table.P5R3 OR Table.P5R4) THEN
            _ConfigValid := FALSE;
            _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
        END_IF;
    END_IF;
END_IF;

// 🛡️ Gestion erreur config : front montant + reset sur front Reset (cause disparue)
// Note : pas d'entrée Reset dédiée (brique réduite) → on réarme quand config redevient valide
//        (front descendant de _ConfigValid). Conforme Partie 3 §5 : cause disparue + front.
_ConfigErrorTrig(CLK := NOT _ConfigValid);  // Front montant = apparition erreur

// Mémoire erreur config : reste TRUE tant que config invalide OU pas de réarmement
// Réarmement = front montant de _ConfigValid (cause disparue) — détecté via _ConfigValidPrev
IF _ConfigErrorTrig.Q THEN
    // Nouvelle erreur : on la mémorise
    _ConfigValidPrev := FALSE;  // Force détection front montant au cycle suivant si redevient valide
ELSIF _ConfigValid AND NOT _ConfigValidPrev THEN
    // Config redevenue valide : front montant → on efface l'erreur (reset sur front)
    _ConfigValidPrev := TRUE;
ELSIF NOT _ConfigValid THEN
    _ConfigValidPrev := FALSE;
END_IF;

// Sorties erreur config (miroir standard Partie 3)
ConfigErrorId := _ConfigErrorIdInt;
ConfigError   := (ConfigErrorId <> 16#0000);

// ─────────────────────────────────────────────────────────────────────────
// 🛑 1. GATE — Enable FALSE OU config invalide = palier 0, sorties sûres
// ─────────────────────────────────────────────────────────────────────────
IF (NOT Enable) OR (NOT _ConfigValid) THEN
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    StepNumber := 0;
    SpeedGuardLimited := FALSE;
    RETURN;
END_IF;

// ─────────────────────────────────────────────────────────────────────────
// 🪜 2. SÉLECTION DU PALIER (HYSTERESIS lib Util : IN/HIGH/LOW → OUT)
//    OUT = TRUE tant que IN < LOW (régime "bas") ; OUT bascule à FALSE une fois
//    IN > HIGH (régime "haut" confirmé) ; maintien entre LOW et HIGH (anti-battement).
//    => NOT Hyst_n.OUT = "on a franchi le seuil n vers le haut" (palier n+1 atteint).
// ─────────────────────────────────────────────────────────────────────────
SpeedRefInt := REAL_TO_INT(SpeedRefPct);

Hyst1(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[1] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[1] - HystMargin));
Hyst2(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[2] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[2] - HystMargin));
Hyst3(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[3] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[3] - HystMargin));
Hyst4(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[4] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[4] - HystMargin));

StepNumber := 1;                          // Palier mini dès qu'Enable est actif
IF NOT Hyst1.OUT THEN StepNumber := 2; END_IF;
IF NOT Hyst2.OUT THEN StepNumber := 3; END_IF;
IF NOT Hyst3.OUT THEN StepNumber := 4; END_IF;
IF NOT Hyst4.OUT THEN StepNumber := 5; END_IF;

// ─────────────────────────────────────────────────────────────────────────
// 🆕 2bis. PLAFOND (2026-07-03quinquies) — appliqué APRÈS la sélection hystérésis,
// AVANT la lecture table : le 0..100% de la consigne peut réclamer le palier 5,
// mais ne dépassera jamais _MaxStepClamped (ex. limitation couple en descente)
// ─────────────────────────────────────────────────────────────────────────
IF StepNumber > _MaxStepClamped THEN
    StepNumber := _MaxStepClamped;
END_IF;

// ─────────────────────────────────────────────────────────────────────────
// 🛡️ 2ter. GARDE-FOU VITESSE RÉELLE — limite uniquement la consigne de palier.
// Si la vitesse n'est pas validée stable, seul le palier 1 reste autorisé.
// ─────────────────────────────────────────────────────────────────────────
SpeedGuardLimited := FALSE;
IF SpeedGuardEnable THEN
    IF NOT SpeedGuardReady THEN
        IF StepNumber > 1 THEN
            StepNumber := 1;
            SpeedGuardLimited := TRUE;
        END_IF;
    ELSIF (MeasuredSpeedBand >= 1) AND (MeasuredSpeedBand <= 5) AND (StepNumber > MeasuredSpeedBand) THEN
        StepNumber := MeasuredSpeedBand;
        SpeedGuardLimited := TRUE;
    END_IF;
END_IF;

// ─────────────────────────────────────────────────────────────────────────
// 📤 3. CONTACTEURS — lus dans la table (donnée, jamais codé en dur)
//    CASE couvre explicitement 0..5 : StepNumber=0 → tous FALSE (sécurité)
// ─────────────────────────────────────────────────────────────────────────
CASE StepNumber OF
    0:  // Arrêt / config invalide / Enable=FALSE — sécurité positive
        Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    1:  Contactor1 := Table.P1R1; Contactor2 := Table.P1R2; Contactor3 := Table.P1R3; Contactor4 := Table.P1R4;
    2:  Contactor1 := Table.P2R1; Contactor2 := Table.P2R2; Contactor3 := Table.P2R3; Contactor4 := Table.P2R4;
    3:  Contactor1 := Table.P3R1; Contactor2 := Table.P3R2; Contactor3 := Table.P3R3; Contactor4 := Table.P3R4;
    4:  Contactor1 := Table.P4R1; Contactor2 := Table.P4R2; Contactor3 := Table.P4R3; Contactor4 := Table.P4R4;
    5:  Contactor1 := Table.P5R1; Contactor2 := Table.P5R2; Contactor3 := Table.P5R3; Contactor4 := Table.P5R4;
ELSE
    // Défense en profondeur : valeur StepNumber inattendue → sécurité
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    StepNumber := 0;
END_CASE;

(* ═══════════════════════════════════════════════════════════════
   📝 NOTE D'APPLICATION MANUELLE CODESYS 3.5
   ═══════════════════════════════════════════════════════════════
   1. Ouvrir le POU FB_SpeedStep dans l'arborescence CODESYS (dossier TREUILS)
   2. Copier la partie DECLARATION (lignes 33-58) dans la zone VAR_INPUT/VAR_OUTPUT/VAR
   3. Copier la partie IMPLEMENTATION (lignes 61 à fin) dans le corps ST
   4. Vérifier que la librairie `Util` est référencée (HYSTERESIS, R_TRIG)
   5. Rebuild (F11) → 0 erreur attendue
   6. Vérifier dans FB_Winch que l'instance SpeedStep compile toujours
      (interface compatible : nouvelles sorties ConfigError/ConfigErrorId ajoutées,
       entrées/sorties existantes inchangées)
   ═══════════════════════════════════════════════════════════════ *)

(* ═══════════════════════════════════════════════════════════════
   🧪 GVL_Simulation — Variables et stimuli de simulation (Banc d'essai)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-13_Fonction_Simulation_v2.0.md
   📄 Lot L6 : Refonte à 5 flags principaux (1 bit maître + 4 domaines)
   🎯 Polarité positive : TRUE = simulé, FALSE = réel (par défaut).
   ═══════════════════════════════════════════════════════════════ *)

{attribute 'qualified_only'}
VAR_GLOBAL
    // 🔑 Bit maître — rien n'est simulé si FALSE (machine réelle)
    SimulationModeActive        : BOOL := FALSE;

    // 🌐 Activation par domaine (simulé si SimulationModeActive AND Sim<Domaine>Active)
    SimWinchActive              : BOOL := FALSE; // M1+M2 : codeurs, contacteurs, freins, thermiques, capteur haut, câble tendu
    SimTranslationActive        : BOOL := FALSE; // AC600 : StatusWord/fréquence, 5 capteurs, frein M3
    SimOperatorActive           : BOOL := FALSE; // Joystick : bus CANopen + RawX/RawY/Button
    SimMachineActive            : BOOL := FALSE; // Chaîne AU, contacteur puissance, réarmement, phases, thermiques freins/hydraulique, Kobold

    // 🖐️ Stimuli de banc — ENTRÉES du modèle, jamais des forçages du programme
    SimM3SensorsWordActive      : BOOL := FALSE;
    SimM3SensorsWord            : BYTE := 16#01;

    SimJoystickRawX             : INT := 5000;
    SimJoystickRawY             : INT := 5000;
    SimJoystickRawButton        : BOOL := FALSE;

    SimKoboldContactValue       : BOOL := FALSE;
    SimEncoderSpeedFactor       : REAL := 1.0;   // ⚠️ Remis à 1.0 (défaut nominal)

    SimSyncDeviationInjectM1    : BOOL := FALSE;
    SimSyncDeviationInjectM2    : BOOL := FALSE;
    SimSyncDeviationOffset_M    : REAL := 0.5;
END_VAR

(* ═══════════════════════════════════════════════════════════════
   🧪 FB_BucketValidation — Suite de test Bucket (Séquenceur)
   ───────────────────────────────────────────────────────────────
   🎯 Valide la sécurité mécanique (Méca C), les timeouts et le
      référencement du bucket selon AF Partie 12 & 14.
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_BucketValidation
VAR_INPUT
    Start                      : BOOL;        // Commande de démarrage des tests
    Abort                      : BOOL;        // Commande d'abandon
    CaseId                     : INT;         // 0=tous ; 1..6=cas ciblé
    instBucket                 : REFERENCE TO FB_Bucket;    // 🆕 Instance benne à tester
    instWinchM2                : REFERENCE TO FB_Winch;     // 🆕 Instance treuil M2 à tester
END_VAR
VAR_OUTPUT
    Busy                       : BOOL;
    Done                       : BOOL;
    AnyFailed                  : BOOL;
    SimGateOk                  : BOOL;        // Indique si la simulation est autorisée
    ActiveStimulusId           : INT;
    StepElapsed                : TIME;
    Report                     : ST_TestSuiteReport;
    TerminalState              : E_TestTerminalState;
    ConfigError                : BOOL;
    ConfigErrorStepId          : INT;
    ConfigErrorCheckIdx        : INT;
    ErrorCode                  : INT;
    ErrorMessage               : STRING(160);
END_VAR
VAR CONSTANT
    // 🏷️ Index des sondes (Sémantique AF P14 §7.2)
    SigHealthyIdle              : INT := 1;
    SigBucketBusy               : INT := 2;
    SigBucketDone               : INT := 3;
    SigBucketError              : INT := 4;
    SigM1SlipDetected           : INT := 5;
    SigM1SafeStop               : INT := 6;
    SigM1PowerCutOff            : INT := 7;
    SigBucketIsOpen             : INT := 8;
    SigBucketIsClosed           : INT := 9;
    SigM2StartStop              : INT := 10;
    SigM2ForceSlowSpeed         : INT := 11;

    SigBucketErrorId            : INT := 1;
    SigM2Direction              : INT := 2;
    SigSafetyM1ErrorId          : INT := 3;

    SigActiveOffsetM            : INT := 1;
    SigRemainingTravelM         : INT := 2;
    SigM2CablePos               : INT := 3;
    SigM2TopLimit               : INT := 4;

    // 🪜 Index des étapes (Séquenceur)
    // TC-B1 : Glissement Modéré
    StepB1Setup                 : INT := 10;
    StepB1Trigger               : INT := 11;
    StepB1Slip                   : INT := 12;
    StepB1Teardown               : INT := 19;

    // TC-B2 : Glissement Critique
    StepB2Setup                 : INT := 20;
    StepB2Trigger               : INT := 21;
    StepB2CriticalSlip           : INT := 22;
    StepB2Teardown               : INT := 29;

    // TC-B3 : Butée Haute Dynamique
    StepB3Setup                 : INT := 30;
    StepB3CheckOpenLimit         : INT := 31;
    StepB3CloseAction            : INT := 32;
    StepB3CheckClosedLimit       : INT := 33;
    StepB3Teardown               : INT := 39;

    // TC-B4 : Cohérence Boot
    StepB4Setup                 : INT := 40;
    StepB4BootIncoherent         : INT := 41;
    StepB4Recalage               : INT := 42;
    StepB4Teardown               : INT := 49;

    // TC-B5 : Homing & Inhibition
    StepB5Setup                 : INT := 50;
    StepB5LostHoming             : INT := 51;
    StepB5RestoreHoming          : INT := 52;
    StepB5InhibitM1              : INT := 53;
    StepB5Teardown               : INT := 59;

    // TC-B6 : Homme-Mort & Recul
    StepB6Setup                 : INT := 60;
    StepB6StartMove              : INT := 61;
    StepB6ReleaseJoy             : INT := 62;
    StepB6ReverseJoy             : INT := 63;
    StepB6Teardown               : INT := 69;
END_VAR
VAR
    // ⚙️ Moteur unique
    Sequencer                  : FB_TestSequencer;

    // 📋 Tables de configuration
    StepTable                  : ARRAY[1..GVL_PLC_Tests_Const.MaxSteps]      OF ST_TestStepConfig;
    CheckTable                 : ARRAY[1..GVL_PLC_Tests_Const.MaxChecks]     OF ST_TestCheckConfig;
    CaseTable                  : ARRAY[1..GVL_PLC_Tests_Const.MaxTestCases]  OF ST_TestCaseConfig;
    InvariantTable             : ARRAY[1..GVL_PLC_Tests_Const.MaxInvariants] OF ST_TestInvariantConfig;

    // 📥 Banque de sondes
    ProbeBool                  : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeBool]  OF BOOL;
    ProbeDint                  : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeDint]  OF DINT;
    ProbeReal                  : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeReal]  OF REAL;

    // 🛠️ Configuration initialisée
    TableReady                 : BOOL := FALSE;

    // ⚡ Commandes de stimuli internes
    CmdOpen_IHM                : BOOL;
    CmdClose_IHM               : BOOL;
    JoystickY_StartStop        : BOOL;
    JoystickY_Direction        : INT;
    ConfirmOpenPosition        : BOOL;
    HomedM1                    : BOOL := TRUE;
    InhibitM1                  : BOOL;
END_VAR

// === IMPLEMENTATION ===

// 1. 🛡️ GATE
IF NOT GVL_Simulation.SimulationModeActive THEN
    Sequencer(Start := FALSE, Abort := TRUE, CaseId := CaseId,
              StepTable := StepTable, CheckTable := CheckTable, CaseTable := CaseTable, InvariantTable := InvariantTable,
              ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal, Report := Report);

    SimGateOk := FALSE;
    RETURN;
END_IF;

// Gate spécifique Bucket : refuse si M1 ou M2 sont en simulation réelle (Sûreté)
SimGateOk := NOT GVL_Simulation.BusEncoderM1IsReal AND NOT GVL_Simulation.BusEncoderM2IsReal;

// 🔧 REX 2026-07-17 : garde-fou REFERENCE TO — PRG_00_Inputs (qui appelle cette suite via
// FB_PLC_Tests_Management) s'exécute AVANT PRG_06_WinchControl dans l'ordre du scan (00 avant 06).
// GVL_Simulation.LinkBucket/LinkWinchM2 ne sont assignés qu'en fin de PRG_06_WinchControl -> au tout
// premier scan, ces références sont encore invalides. Déréférencer instBucket.xxx sans ce garde
// provoquait une EXCEPTION RUNTIME CODESYS (accès référence invalide) au démarrage de la simulation.
IF NOT __ISVALIDREF(instBucket) OR NOT __ISVALIDREF(instWinchM2) THEN
    Busy := FALSE;
    RETURN;
END_IF;

// 2. 📋 TABLES
IF NOT TableReady THEN
    Report.Name := 'Bucket Validation';

    // Cas de tests
    CaseTable[1].Name := 'TC-B1 Glissement Modéré';
    CaseTable[1].FirstStep := StepB1Setup;

    CaseTable[2].Name := 'TC-B2 Glissement Critique';
    CaseTable[2].FirstStep := StepB2Setup;

    CaseTable[3].Name := 'TC-B3 Butée Haute Dynamique';
    CaseTable[3].FirstStep := StepB3Setup;

    CaseTable[4].Name := 'TC-B4 Cohérence Boot';
    CaseTable[4].FirstStep := StepB4Setup;

    CaseTable[5].Name := 'TC-B5 Homing & Inhibition';
    CaseTable[5].FirstStep := StepB5Setup;

    CaseTable[6].Name := 'TC-B6 Homme-Mort & Recul';
    CaseTable[6].FirstStep := StepB6Setup;

    // ─────────────────────────────────────────────────────────────
    // CONFIGURATION DES CHECKS
    // ─────────────────────────────────────────────────────────────
    // Chk 1: Attente état sain
    CheckTable[1].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[1].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[1].ProbeIdx := SigHealthyIdle;
    CheckTable[1].ExpectedBool := TRUE;

    // Chk 2: Bucket Busy
    CheckTable[2].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[2].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[2].ProbeIdx := SigBucketBusy;
    CheckTable[2].ExpectedBool := TRUE;

    // Chk 3: Glissement M1 détecté
    CheckTable[3].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[3].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[3].ProbeIdx := SigM1SlipDetected;
    CheckTable[3].ExpectedBool := TRUE;

    // Chk 4: Bit ErrorId 4 levé (16#0010)
    CheckTable[4].Kind := E_TestCheckKind.WORD_MASK_ALL;
    CheckTable[4].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[4].ProbeIdx := SigBucketErrorId;
    CheckTable[4].Mask := 16#0010;

    // Chk 5: Coupure immédiate M2
    CheckTable[5].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[5].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[5].ProbeIdx := SigM2StartStop;
    CheckTable[5].ExpectedBool := FALSE;

    // Chk 6: SafeStop M1 activé
    CheckTable[6].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[6].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[6].ProbeIdx := SigM1SafeStop;
    CheckTable[6].ExpectedBool := TRUE;

    // Chk 7: PowerCutOff M1 NON activé (Couche 1 seulement)
    CheckTable[7].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[7].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[7].ProbeIdx := SigM1PowerCutOff;
    CheckTable[7].ExpectedBool := FALSE;

    // Chk 8: PowerCutOff M1 activé (Couche 2)
    CheckTable[8].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[8].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[8].ProbeIdx := SigM1PowerCutOff;
    CheckTable[8].ExpectedBool := TRUE;

    // Chk 9: Défaut Safety M1 Bit 9 (16#0200)
    CheckTable[9].Kind := E_TestCheckKind.WORD_MASK_ALL;
    CheckTable[9].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[9].ProbeIdx := SigSafetyM1ErrorId;
    CheckTable[9].Mask := 16#0200;

    // Chk 10: limite haute d'exploitation standard (8,0 m)
    CheckTable[10].Kind := E_TestCheckKind.REAL_IN_RANGE;
    CheckTable[10].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[10].ProbeIdx := SigM2TopLimit;
    CheckTable[10].RealMin := 8.0;
    CheckTable[10].RealMax := 8.1;

    // Chk 11: Bucket fermé mémorisé
    CheckTable[11].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[11].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[11].ProbeIdx := SigBucketIsClosed;
    CheckTable[11].ExpectedBool := TRUE;

    // Chk 12: limite haute décalée par la benne fermée (+10 m → 18 m)
    CheckTable[12].Kind := E_TestCheckKind.REAL_IN_RANGE;
    CheckTable[12].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[12].ProbeIdx := SigM2TopLimit;
    CheckTable[12].RealMin := 18.0;
    CheckTable[12].RealMax := 18.1;

    // Chk 13: Erreur Bucket active
    CheckTable[13].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[13].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[13].ProbeIdx := SigBucketError;
    CheckTable[13].ExpectedBool := TRUE;

    // Chk 14: Bit ErrorId 1 levé (Incohérence boot)
    CheckTable[14].Kind := E_TestCheckKind.WORD_MASK_ALL;
    CheckTable[14].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[14].ProbeIdx := SigBucketErrorId;
    CheckTable[14].Mask := 16#0002;

    // Chk 15: États mémorisés forcés à FALSE
    CheckTable[15].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[15].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[15].ProbeIdx := SigBucketIsOpen;
    CheckTable[15].ExpectedBool := FALSE;

    // Chk 16: Idem pour IsClosed
    CheckTable[16].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[16].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[16].ProbeIdx := SigBucketIsClosed;
    CheckTable[16].ExpectedBool := FALSE;

    // Chk 17: Bucket ouvert mémorisé après recalage
    CheckTable[17].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[17].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[17].ProbeIdx := SigBucketIsOpen;
    CheckTable[17].ExpectedBool := TRUE;

    // Chk 18: Bit ErrorId 3 levé (Non référencé)
    CheckTable[18].Kind := E_TestCheckKind.WORD_MASK_ALL;
    CheckTable[18].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[18].ProbeIdx := SigBucketErrorId;
    CheckTable[18].Mask := 16#0008;

    // Chk 19: Bucket non opérationnel
    CheckTable[19].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[19].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[19].ProbeIdx := SigHealthyIdle;
    CheckTable[19].ExpectedBool := FALSE;

    // Chk 20: Glissement M1 ignoré pendant inhibition
    CheckTable[20].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[20].Mode := E_TestCheckMode.CHECK_NEVER_DURING;
    CheckTable[20].ProbeIdx := SigM1SlipDetected;
    CheckTable[20].ExpectedBool := TRUE;

    // Chk 21: Mouvement terminé
    CheckTable[21].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[21].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[21].ProbeIdx := SigBucketDone;
    CheckTable[21].ExpectedBool := TRUE;

    // Chk 22: Direction M2 = -1 (Déroulage)
    CheckTable[22].Kind := E_TestCheckKind.DINT_EQUAL;
    CheckTable[22].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[22].ProbeIdx := SigM2Direction;
    CheckTable[22].ExpectedDint := -1;

    // Chk 23: M2 ne dépasse pas la position de départ (Sonde Real)
    CheckTable[23].Kind := E_TestCheckKind.REAL_IN_RANGE;
    CheckTable[23].Mode := E_TestCheckMode.CHECK_NEVER_DURING;
    CheckTable[23].ProbeIdx := SigM2CablePos;
    CheckTable[23].RealMin := 0.0; // Valeur relative simulée ici
    CheckTable[23].RealMax := 0.1;

    // ─────────────────────────────────────────────────────────────
    // CONFIGURATION DES ÉTAPES (StepTable)
    // ─────────────────────────────────────────────────────────────
    // TC-B1 : Glissement Modéré
    StepTable[StepB1Setup].Name := 'Tcb1 Setup saine';
    StepTable[StepB1Setup].CaseId := 1;
    StepTable[StepB1Setup].StimulusId := 1;
    StepTable[StepB1Setup].CheckIdx[1] := 1;
    StepTable[StepB1Setup].TimeoutPT := T#12s;
    StepTable[StepB1Setup].NextOnPass := StepB1Trigger;
    StepTable[StepB1Setup].NextOnFail := StepB1Teardown;
    StepTable[StepB1Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB1Trigger].Name := 'Tcb1 Trigger fermeture';
    StepTable[StepB1Trigger].CaseId := 1;
    StepTable[StepB1Trigger].StimulusId := 2;
    StepTable[StepB1Trigger].CheckIdx[1] := 2;
    StepTable[StepB1Trigger].TimeoutPT := T#5s;
    StepTable[StepB1Trigger].NextOnPass := StepB1Slip;
    StepTable[StepB1Trigger].NextOnFail := StepB1Teardown;
    StepTable[StepB1Trigger].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB1Slip].Name := 'Tcb1 Detection glissement';
    StepTable[StepB1Slip].CaseId := 1;
    StepTable[StepB1Slip].StimulusId := 3;
    StepTable[StepB1Slip].CheckIdx[1] := 3;
    StepTable[StepB1Slip].CheckIdx[2] := 5;
    StepTable[StepB1Slip].CheckIdx[3] := 6;
    StepTable[StepB1Slip].CheckIdx[4] := 7;
    StepTable[StepB1Slip].TimeoutPT := T#2s;
    StepTable[StepB1Slip].NextOnPass := StepB1Teardown;
    StepTable[StepB1Slip].NextOnFail := StepB1Teardown;
    StepTable[StepB1Slip].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB1Teardown].Name := 'Tcb1 Teardown';
    StepTable[StepB1Teardown].CaseId := 1;
    StepTable[StepB1Teardown].StimulusId := 1;
    StepTable[StepB1Teardown].CheckIdx[1] := 1;
    StepTable[StepB1Teardown].TimeoutPT := T#12s;
    StepTable[StepB1Teardown].NextOnPass := StepB2Setup;
    StepTable[StepB1Teardown].NextOnFail := StepB2Setup;
    StepTable[StepB1Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    // TC-B2 : Glissement Critique
    StepTable[StepB2Setup].Name := 'Tcb2 Setup saine';
    StepTable[StepB2Setup].CaseId := 2;
    StepTable[StepB2Setup].StimulusId := 1;
    StepTable[StepB2Setup].CheckIdx[1] := 1;
    StepTable[StepB2Setup].TimeoutPT := T#12s;
    StepTable[StepB2Setup].NextOnPass := StepB2Trigger;
    StepTable[StepB2Setup].NextOnFail := StepB2Teardown;
    StepTable[StepB2Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB2Trigger].Name := 'Tcb2 Trigger fermeture';
    StepTable[StepB2Trigger].CaseId := 2;
    StepTable[StepB2Trigger].StimulusId := 2;
    StepTable[StepB2Trigger].CheckIdx[1] := 2;
    StepTable[StepB2Trigger].TimeoutPT := T#5s;
    StepTable[StepB2Trigger].NextOnPass := StepB2CriticalSlip;
    StepTable[StepB2Trigger].NextOnFail := StepB2Teardown;
    StepTable[StepB2Trigger].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB2CriticalSlip].Name := 'Tcb2 Escalade PowerCutOff';
    StepTable[StepB2CriticalSlip].CaseId := 2;
    StepTable[StepB2CriticalSlip].StimulusId := 4;
    StepTable[StepB2CriticalSlip].CheckIdx[1] := 3;
    StepTable[StepB2CriticalSlip].CheckIdx[2] := 8;
    StepTable[StepB2CriticalSlip].CheckIdx[3] := 9;
    StepTable[StepB2CriticalSlip].TimeoutPT := T#2s;
    StepTable[StepB2CriticalSlip].NextOnPass := StepB2Teardown;
    StepTable[StepB2CriticalSlip].NextOnFail := StepB2Teardown;
    StepTable[StepB2CriticalSlip].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB2Teardown].Name := 'Tcb2 Teardown';
    StepTable[StepB2Teardown].CaseId := 2;
    StepTable[StepB2Teardown].StimulusId := 1;
    StepTable[StepB2Teardown].CheckIdx[1] := 1;
    StepTable[StepB2Teardown].TimeoutPT := T#12s;
    StepTable[StepB2Teardown].NextOnPass := StepB3Setup;
    StepTable[StepB2Teardown].NextOnFail := StepB3Setup;
    StepTable[StepB2Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    // TC-B3 : Butée Haute Dynamique
    StepTable[StepB3Setup].Name := 'Tcb3 Setup saine';
    StepTable[StepB3Setup].CaseId := 3;
    StepTable[StepB3Setup].StimulusId := 1;
    StepTable[StepB3Setup].CheckIdx[1] := 1;
    StepTable[StepB3Setup].TimeoutPT := T#12s;
    StepTable[StepB3Setup].NextOnPass := StepB3CheckOpenLimit;
    StepTable[StepB3Setup].NextOnFail := StepB3Teardown;
    StepTable[StepB3Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB3CheckOpenLimit].Name := 'Tcb3 Verif Limite Standard';
    StepTable[StepB3CheckOpenLimit].CaseId := 3;
    StepTable[StepB3CheckOpenLimit].StimulusId := 0;
    StepTable[StepB3CheckOpenLimit].CheckIdx[1] := 10;
    StepTable[StepB3CheckOpenLimit].TimeoutPT := T#1s;
    StepTable[StepB3CheckOpenLimit].NextOnPass := StepB3CloseAction;
    StepTable[StepB3CheckOpenLimit].NextOnFail := StepB3Teardown;
    StepTable[StepB3CheckOpenLimit].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB3CloseAction].Name := 'Tcb3 Mouvement Fermeture';
    StepTable[StepB3CloseAction].CaseId := 3;
    StepTable[StepB3CloseAction].StimulusId := 5;
    StepTable[StepB3CloseAction].CheckIdx[1] := 11;
    StepTable[StepB3CloseAction].TimeoutPT := T#15s;
    StepTable[StepB3CloseAction].NextOnPass := StepB3CheckClosedLimit;
    StepTable[StepB3CloseAction].NextOnFail := StepB3Teardown;
    StepTable[StepB3CloseAction].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB3CheckClosedLimit].Name := 'Tcb3 Verif Limite Decalee';
    StepTable[StepB3CheckClosedLimit].CaseId := 3;
    StepTable[StepB3CheckClosedLimit].StimulusId := 0;
    StepTable[StepB3CheckClosedLimit].CheckIdx[1] := 12;
    StepTable[StepB3CheckClosedLimit].TimeoutPT := T#1s;
    StepTable[StepB3CheckClosedLimit].NextOnPass := StepB3Teardown;
    StepTable[StepB3CheckClosedLimit].NextOnFail := StepB3Teardown;
    StepTable[StepB3CheckClosedLimit].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB3Teardown].Name := 'Tcb3 Teardown';
    StepTable[StepB3Teardown].CaseId := 3;
    StepTable[StepB3Teardown].StimulusId := 1;
    StepTable[StepB3Teardown].CheckIdx[1] := 1;
    StepTable[StepB3Teardown].TimeoutPT := T#12s;
    StepTable[StepB3Teardown].NextOnPass := StepB4Setup;
    StepTable[StepB3Teardown].NextOnFail := StepB4Setup;
    StepTable[StepB3Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    // TC-B4 : Cohérence Boot
    StepTable[StepB4Setup].Name := 'Tcb4 Setup saine';
    StepTable[StepB4Setup].CaseId := 4;
    StepTable[StepB4Setup].StimulusId := 1;
    StepTable[StepB4Setup].CheckIdx[1] := 1;
    StepTable[StepB4Setup].TimeoutPT := T#12s;
    StepTable[StepB4Setup].NextOnPass := StepB4BootIncoherent;
    StepTable[StepB4Setup].NextOnFail := StepB4Teardown;
    StepTable[StepB4Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB4BootIncoherent].Name := 'Tcb4 Injection Drift Boot';
    StepTable[StepB4BootIncoherent].CaseId := 4;
    StepTable[StepB4BootIncoherent].StimulusId := 6;
    StepTable[StepB4BootIncoherent].CheckIdx[1] := 13;
    StepTable[StepB4BootIncoherent].CheckIdx[2] := 14;
    StepTable[StepB4BootIncoherent].CheckIdx[3] := 15;
    StepTable[StepB4BootIncoherent].CheckIdx[4] := 16;
    StepTable[StepB4BootIncoherent].TimeoutPT := T#2s;
    StepTable[StepB4BootIncoherent].NextOnPass := StepB4Recalage;
    StepTable[StepB4BootIncoherent].NextOnFail := StepB4Teardown;
    StepTable[StepB4BootIncoherent].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB4Recalage].Name := 'Tcb4 Recalage Manuel';
    StepTable[StepB4Recalage].CaseId := 4;
    StepTable[StepB4Recalage].StimulusId := 7;
    StepTable[StepB4Recalage].CheckIdx[1] := 17;
    StepTable[StepB4Recalage].CheckIdx[2] := 1;
    StepTable[StepB4Recalage].TimeoutPT := T#2s;
    StepTable[StepB4Recalage].NextOnPass := StepB4Teardown;
    StepTable[StepB4Recalage].NextOnFail := StepB4Teardown;
    StepTable[StepB4Recalage].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB4Teardown].Name := 'Tcb4 Teardown';
    StepTable[StepB4Teardown].CaseId := 4;
    StepTable[StepB4Teardown].StimulusId := 1;
    StepTable[StepB4Teardown].CheckIdx[1] := 1;
    StepTable[StepB4Teardown].TimeoutPT := T#12s;
    StepTable[StepB4Teardown].NextOnPass := StepB5Setup;
    StepTable[StepB4Teardown].NextOnFail := StepB5Setup;
    StepTable[StepB4Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    // TC-B5 : Homing & Inhibition
    StepTable[StepB5Setup].Name := 'Tcb5 Setup saine';
    StepTable[StepB5Setup].CaseId := 5;
    StepTable[StepB5Setup].StimulusId := 1;
    StepTable[StepB5Setup].CheckIdx[1] := 1;
    StepTable[StepB5Setup].TimeoutPT := T#12s;
    StepTable[StepB5Setup].NextOnPass := StepB5LostHoming;
    StepTable[StepB5Setup].NextOnFail := StepB5Teardown;
    StepTable[StepB5Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB5LostHoming].Name := 'Tcb5 Perte Homing';
    StepTable[StepB5LostHoming].CaseId := 5;
    StepTable[StepB5LostHoming].StimulusId := 8;
    StepTable[StepB5LostHoming].CheckIdx[1] := 18;
    StepTable[StepB5LostHoming].CheckIdx[2] := 19;
    StepTable[StepB5LostHoming].TimeoutPT := T#2s;
    StepTable[StepB5LostHoming].NextOnPass := StepB5RestoreHoming;
    StepTable[StepB5LostHoming].NextOnFail := StepB5Teardown;
    StepTable[StepB5LostHoming].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB5RestoreHoming].Name := 'Tcb5 Rétablissement Homing';
    StepTable[StepB5RestoreHoming].CaseId := 5;
    StepTable[StepB5RestoreHoming].StimulusId := 1; // (Force HomedM1 := TRUE via Reset/Saine)
    StepTable[StepB5RestoreHoming].CheckIdx[1] := 1;
    StepTable[StepB5RestoreHoming].TimeoutPT := T#12s;
    StepTable[StepB5RestoreHoming].NextOnPass := StepB5InhibitM1;
    StepTable[StepB5RestoreHoming].NextOnFail := StepB5Teardown;
    StepTable[StepB5RestoreHoming].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB5InhibitM1].Name := 'Tcb5 Inhibition M1';
    StepTable[StepB5InhibitM1].CaseId := 5;
    StepTable[StepB5InhibitM1].StimulusId := 9;
    StepTable[StepB5InhibitM1].CheckIdx[1] := 20;
    StepTable[StepB5InhibitM1].CheckIdx[2] := 21;
    StepTable[StepB5InhibitM1].TimeoutPT := T#15s;
    StepTable[StepB5InhibitM1].NextOnPass := StepB5Teardown;
    StepTable[StepB5InhibitM1].NextOnFail := StepB5Teardown;
    StepTable[StepB5InhibitM1].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB5Teardown].Name := 'Tcb5 Teardown';
    StepTable[StepB5Teardown].CaseId := 5;
    StepTable[StepB5Teardown].StimulusId := 1;
    StepTable[StepB5Teardown].CheckIdx[1] := 1;
    StepTable[StepB5Teardown].TimeoutPT := T#12s;
    StepTable[StepB5Teardown].NextOnPass := StepB6Setup;
    StepTable[StepB5Teardown].NextOnFail := StepB6Setup;
    StepTable[StepB5Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    // TC-B6 : Homme-Mort & Recul
    StepTable[StepB6Setup].Name := 'Tcb6 Setup saine';
    StepTable[StepB6Setup].CaseId := 6;
    StepTable[StepB6Setup].StimulusId := 1;
    StepTable[StepB6Setup].CheckIdx[1] := 1;
    StepTable[StepB6Setup].TimeoutPT := T#12s;
    StepTable[StepB6Setup].NextOnPass := StepB6StartMove;
    StepTable[StepB6Setup].NextOnFail := StepB6Teardown;
    StepTable[StepB6Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB6StartMove].Name := 'Tcb6 Lancement Mouvement';
    StepTable[StepB6StartMove].CaseId := 6;
    StepTable[StepB6StartMove].StimulusId := 2;
    StepTable[StepB6StartMove].CheckIdx[1] := 2;
    StepTable[StepB6StartMove].TimeoutPT := T#5s;
    StepTable[StepB6StartMove].NextOnPass := StepB6ReleaseJoy;
    StepTable[StepB6StartMove].NextOnFail := StepB6Teardown;
    StepTable[StepB6StartMove].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB6ReleaseJoy].Name := 'Tcb6 Relâchement Homme-Mort';
    StepTable[StepB6ReleaseJoy].CaseId := 6;
    StepTable[StepB6ReleaseJoy].StimulusId := 10;
    StepTable[StepB6ReleaseJoy].CheckIdx[1] := 5;
    StepTable[StepB6ReleaseJoy].TimeoutPT := T#1s;
    StepTable[StepB6ReleaseJoy].NextOnPass := StepB6ReverseJoy;
    StepTable[StepB6ReleaseJoy].NextOnFail := StepB6Teardown;
    StepTable[StepB6ReleaseJoy].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB6ReverseJoy].Name := 'Tcb6 Commande Opposée';
    StepTable[StepB6ReverseJoy].CaseId := 6;
    StepTable[StepB6ReverseJoy].StimulusId := 11;
    StepTable[StepB6ReverseJoy].CheckIdx[1] := 22;
    StepTable[StepB6ReverseJoy].CheckIdx[2] := 23;
    StepTable[StepB6ReverseJoy].TimeoutPT := T#5s;
    StepTable[StepB6ReverseJoy].NextOnPass := StepB6Teardown;
    StepTable[StepB6ReverseJoy].NextOnFail := StepB6Teardown;
    StepTable[StepB6ReverseJoy].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB6Teardown].Name := 'Tcb6 Teardown';
    StepTable[StepB6Teardown].CaseId := 6;
    StepTable[StepB6Teardown].StimulusId := 1;
    StepTable[StepB6Teardown].CheckIdx[1] := 1;
    StepTable[StepB6Teardown].TimeoutPT := T#12s;
    StepTable[StepB6Teardown].NextOnPass := 0;
    StepTable[StepB6Teardown].NextOnFail := 0;
    StepTable[StepB6Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    TableReady := TRUE;
END_IF;

// 3. 📥 ACQUIRE
ProbeBool[SigHealthyIdle] := NOT instBucket.Error
                             AND NOT _BucketState.StateIncoherent;

ProbeBool[SigBucketBusy]   := instBucket.Busy;
ProbeBool[SigBucketDone]    := instBucket.Done;
ProbeBool[SigBucketError]   := instBucket.Error;
ProbeBool[SigM1SlipDetected] := instBucket.M1SlipDetected;
ProbeBool[SigM1SafeStop]    := PRG_03_Safety.instSafetyWinchM1.SafeStop;
ProbeBool[SigM1PowerCutOff] := PRG_03_Safety.instSafetyWinchM1.PowerCutOff;
ProbeBool[SigBucketIsOpen]  := _BucketState.IsOpen;
ProbeBool[SigBucketIsClosed] := _BucketState.IsClosed;
ProbeBool[SigM2StartStop]   := instBucket.M2_StartStop;
ProbeBool[SigM2ForceSlowSpeed] := instBucket.M2_ForceSlowSpeed;

ProbeDint[SigBucketErrorId] := WORD_TO_DINT(instBucket.ErrorId);
ProbeDint[SigM2Direction]   := INT_TO_DINT(instBucket.M2_Direction);
ProbeDint[SigSafetyM1ErrorId] := WORD_TO_DINT(PRG_03_Safety.instSafetyWinchM1.ErrorId);

ProbeReal[SigActiveOffsetM]   := instBucket.ActiveOffsetM;
ProbeReal[SigRemainingTravelM] := instBucket.RemainingTravelM;
ProbeReal[SigM2CablePos]      := PRG_02_Encoders.instEncoderScaleM2.CablePosM;
ProbeReal[SigM2TopLimit]       := instWinchM2.TopLimitM;

// 4. ⚙️ MOTEUR
Sequencer(
    Start := Start,
    Abort := Abort,
    CaseId := CaseId,
    StepTable := StepTable,
    CheckTable := CheckTable,
    CaseTable := CaseTable,
    InvariantTable := InvariantTable,
    ProbeBool := ProbeBool,
    ProbeDint := ProbeDint,
    ProbeReal := ProbeReal,
    Report := Report,
    Busy => Busy,
    Done => Done,
    AnyFailed => AnyFailed,
    TerminalState => TerminalState,
    ConfigError => ConfigError,
    ConfigErrorStepId => ConfigErrorStepId,
    ConfigErrorCheckIdx => ConfigErrorCheckIdx,
    ErrorCode => ErrorCode,
    ErrorMessage => ErrorMessage,
    ActiveStimulusId => ActiveStimulusId,
    StepElapsed => StepElapsed
);

// 5. ⚡ STIMULI
CASE ActiveStimulusId OF
    0: // 🔓 Neutre
        CmdOpen_IHM := FALSE;
        CmdClose_IHM := FALSE;
        JoystickY_StartStop := FALSE;
        JoystickY_Direction := 0;
        ConfirmOpenPosition := FALSE;
        HomedM1 := TRUE;
        InhibitM1 := FALSE;
        GVL_PLC_Tests.OverrideM1Slip := FALSE;
        GVL_PLC_Tests.OverrideM1SlipCritical := FALSE;
        GVL_PLC_Tests.OverrideM2Stuck := FALSE;
        GVL_PLC_Tests.OverrideM2BootDrift := FALSE;

    1: // Reset & Saine
        CmdOpen_IHM := FALSE;
        CmdClose_IHM := FALSE;
        JoystickY_StartStop := FALSE;
        ConfirmOpenPosition := TRUE; // Forcer état sain
        HomedM1 := TRUE;
        InhibitM1 := FALSE;
        GVL_PLC_Tests.OverrideM1Slip := FALSE;
        GVL_PLC_Tests.OverrideM1SlipCritical := FALSE;
        GVL_PLC_Tests.OverrideM2Stuck := FALSE;
        GVL_PLC_Tests.OverrideM2BootDrift := FALSE;

    2: // Fermeture Nominale
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := 1;
        ConfirmOpenPosition := FALSE;
        HomedM1 := TRUE;

    3: // Glissement Modéré M1
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := 1;
        GVL_PLC_Tests.OverrideM1Slip := TRUE;

    4: // Glissement Critique M1
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := 1;
        GVL_PLC_Tests.OverrideM1SlipCritical := TRUE;

    5: // Fermeture nominale (TC-B3)
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := 1;
        ConfirmOpenPosition := FALSE;

    6: // Boot Incohérent
        GVL_PLC_Tests.OverrideM2BootDrift := TRUE;
        CmdOpen_IHM := FALSE;
        CmdClose_IHM := FALSE;
        JoystickY_StartStop := FALSE;

    7: // Recalage manuel
        ConfirmOpenPosition := TRUE;
        CmdOpen_IHM := FALSE;
        CmdClose_IHM := FALSE;
        JoystickY_StartStop := FALSE;

    8: // Perte Homing
        HomedM1 := FALSE;
        CmdClose_IHM := FALSE;
        CmdOpen_IHM := FALSE;

    9: // Inhibition M1 + Mouvement
        InhibitM1 := TRUE;
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := 1;
        GVL_PLC_Tests.OverrideM1Slip := TRUE;

    10: // Relâchement Homme-Mort
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := FALSE;
        JoystickY_Direction := 1;

    11: // Commande opposée
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := -1;
END_CASE;

// Liaison IHM / Métier
IF Busy THEN
    instBucket.CmdOpen_IHM := CmdOpen_IHM;
    instBucket.CmdClose_IHM := CmdClose_IHM;
    instBucket.JoystickY_StartStop := JoystickY_StartStop;
    instBucket.JoystickY_Direction := JoystickY_Direction;
    instBucket.ConfirmOpenPosition := ConfirmOpenPosition;
    instBucket.HomedM1 := HomedM1;
    instBucket.InhibitM1 := InhibitM1;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   📡 FB_Diag_CanOpen — Diagnostic bus CANopen / Joystick
   ───────────────────────────────────────────────────────────────
   📄 Docs : DOC/AF_Partie-02_Architecture_Programme_v3.1.md
              DOC/AF_Partie-06_Acquisition_Qualification_IO_v2.1.md §3
   🎯 Rôle : Décide Online/Operational et publie ST_Diag_Device.
      Distinction explicite dans State :
      - INIT       : pas encore online (ni réel, ni bypass)
      - SIMULATED  : bypass actif (simulation ou bypass réseau IHM)
      - READY      : bus réellement online
      - ERROR      : défaut détecté
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK PUBLIC FB_Diag_CanOpen
VAR_INPUT
    Enable          : BOOL;        (* Active la surveillance CAN *)
    Reset           : BOOL;        (* Front d'acquittement des défauts *)
    CANbusStateRaw          : INT;          (* Valeur brute CANbus.GetBusState() (2 = ACTIVE) *)
    DeviceJoystickStateRaw  : DEVICE_STATE; (* Valeur brute JOY1.GetDeviceState() *)
    SimBypassActive         : BOOL;         (* TRUE = simulation active pour ce device *)
    NetworkBypassActive     : BOOL;         (* TRUE = bypass réseau global IHM *)
END_VAR
VAR_OUTPUT
    Ready           : BOOL;        (* Logique de surveillance active *)
    Busy            : BOOL;        (* Non utilisé (conformité interface) *)
    Done            : BOOL;        (* Non utilisé *)
    Error           : BOOL;        (* Présence anomalie de communication *)
    ErrorId         : WORD;        (* Code défaut global résumé *)
    State           : E_Diag_State; (* Phase courante (INIT/SIMULATED/READY/ERROR) *)
    StateAtError    : E_Diag_State; (* Phase figée à l'apparition de l'erreur *)
    DeviceCanOpenMaster : ST_Diag_Device;  (* Diagnostics bus CANopen *)
    DeviceJoystick  : ST_Diag_Device;  (* Diagnostics esclave Joystick *)
    (* Miroirs bruts lisibles directement sur l'instance *)
    CANbusStateRawOut         : INT;
    DeviceJoystickStateRawOut : DEVICE_STATE;
END_VAR
VAR
    ResetEdge       : R_TRIG;      (* Détecteur front de reset *)
    CANbusOnlineReal         : BOOL; (* Bus réellement actif, hors tout bypass *)
    DeviceJoystickOnlineReal : BOOL; (* Joystick réellement RUNNING, hors tout bypass *)
    BypassActive             : BOOL; (* Simulation OU bypass réseau IHM *)
    CANbusOnlineEff          : BOOL; (* Online effectif (réel OU bypass) *)
    DeviceJoystickOnlineEff  : BOOL; (* Operational effectif (réel OU bypass) *)
END_VAR

// 🛑 1. GATE : Désactivation logique si Enable = FALSE
IF NOT Enable THEN
    Ready := FALSE;
    State := E_Diag_State.DISABLED;
    DeviceJoystick.State := E_Diag_State.DISABLED;
    DeviceJoystick.Online := FALSE;
    DeviceJoystick.Operational := FALSE;
    DeviceJoystick.Error := FALSE;
    DeviceJoystick.ErrorId := 16#0000;
    DeviceCanOpenMaster.State := E_Diag_State.DISABLED;
    DeviceCanOpenMaster.Online := FALSE;
    DeviceCanOpenMaster.Operational := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    CANbusStateRawOut := CANbusStateRaw;
    DeviceJoystickStateRawOut := DeviceJoystickStateRaw;
    RETURN;
END_IF;

Ready := TRUE;

// 🧮 2. INTERPRÉTATION DES VALEURS BRUTES
CANbusOnlineReal         := (CANbusStateRaw = 2);
DeviceJoystickOnlineReal := (DeviceJoystickStateRaw = DEVICE_STATE.RUNNING);
BypassActive             := SimBypassActive OR NetworkBypassActive;
CANbusOnlineEff          := CANbusOnlineReal OR BypassActive;
DeviceJoystickOnlineEff  := DeviceJoystickOnlineReal OR BypassActive;

// 🔑 3. RESET FRONT — Efface les défauts si la cause a disparu
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    IF (CANbusOnlineEff AND DeviceJoystickOnlineEff) THEN
        DeviceJoystick.ErrorId := 16#0000;
        StateAtError := E_Diag_State.DISABLED;
    END_IF;
END_IF;

// 🔍 4. DIAGNOSTIC JOYSTICK
// Bit 0 : Perte de communication CAN
IF NOT CANbusOnlineEff THEN
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId OR 16#0001;  (* Perte liaison CAN joystick *)
    DeviceJoystick.Online := FALSE;
ELSE
    DeviceJoystick.Online := TRUE;
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId AND 16#FFFE; (* Effacement auto si la liaison revient *)
END_IF;

// Bit 1 : Mode non-opérationnel (esclave CANopen en pré-op ou défaut)
IF NOT DeviceJoystickOnlineEff THEN
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId OR 16#0002;  (* Joystick pas opérationnel *)
    DeviceJoystick.Operational := FALSE;
ELSE
    DeviceJoystick.Operational := TRUE;
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId AND 16#FFFD; (* Effacement auto dès que RUNNING *)
END_IF;

// 🚦 5. MACHINE D'ÉTAT JOYSTICK
IF DeviceJoystick.ErrorId <> 0 THEN
    DeviceJoystick.State := E_Diag_State.ERROR;
    IF StateAtError = E_Diag_State.DISABLED THEN
        StateAtError := State;
    END_IF;
ELSIF NOT (DeviceJoystick.Online AND DeviceJoystick.Operational) THEN
    DeviceJoystick.State := E_Diag_State.INIT;
ELSIF BypassActive AND NOT (CANbusOnlineReal AND DeviceJoystickOnlineReal) THEN
    DeviceJoystick.State := E_Diag_State.SIMULATED;
ELSE
    DeviceJoystick.State := E_Diag_State.READY;
END_IF;

State := DeviceJoystick.State;

// 📤 6. SORTIES GLOBALES
DeviceJoystick.Error := (DeviceJoystick.ErrorId <> 0);
Error := DeviceJoystick.Error;
ErrorId := DeviceJoystick.ErrorId;

DeviceCanOpenMaster.Operational := CANbusOnlineEff;
DeviceCanOpenMaster.Online := CANbusOnlineEff;

IF NOT CANbusOnlineEff THEN
    DeviceCanOpenMaster.State := E_Diag_State.INIT;
ELSIF BypassActive AND NOT CANbusOnlineReal THEN
    DeviceCanOpenMaster.State := E_Diag_State.SIMULATED;
ELSE
    DeviceCanOpenMaster.State := E_Diag_State.READY;
END_IF;

// Miroirs bruts, toujours à jour
CANbusStateRawOut := CANbusStateRaw;
DeviceJoystickStateRawOut := DeviceJoystickStateRaw;

// Briques génériques pour conformité standard
Busy := FALSE;
Done := FALSE;

(* ═══════════════════════════════════════════════════════════════
   📤 PRG_06_Outputs_Staging_LD — Barrière finale staging (PROGRAMME LADDER)
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF_Partie-06_Acquisition_Qualification_IO_v2.0.md §5
   ⚠️ Staging M5 : NON appelée par la MainTask ; PRG_10_Outputs_LD reste active.
   ✅ Reçoit les demandes PowerCutOff publiques en VAR_INPUT pour le basculement atomique.
   📄 Converti automatiquement en Ladder Diagram (<LD>) dans CODESYS.
   ═══════════════════════════════════════════════════════════════ *)

PROGRAM PRG_06_Outputs_Staging_LD
VAR_INPUT
    // 🛡️ Contrat public de coupure : TRUE = le procédé demande la coupure puissance.
    // Ces entrées ne sont pas encore raccordées : la page staging n'est pas exécutée.
    PowerCutOffWinchM1Request       : BOOL;
