// ═══════════════════════════════════════════════════════════════
// 🧪 FB_TranslationTestFixture — Précondition Translation M3
// ───────────────────────────────────────────────────────────────
// 🎯 Responsabilité UNIQUE : décider si un Start est recevable
//    (Niveaux 1/2 de la défense en profondeur, AF_Partie-14 §7.3.3) :
//    simulation active + aucune E/S M3 recâblée réelle. Ne fait AUCUNE
//    attente d'état sain (ça reste la responsabilité de l'étape SETUP
//    de chaque cas, via FB_TranslationStepExecutor — §7.3.5).
// 🔒 Un refus ici est TOUJOURS explicite (PRECONDITION_FAILED),
//    jamais un silence (audit v1.0 C3).
// ═══════════════════════════════════════════════════════════════

FUNCTION_BLOCK PUBLIC FB_TranslationTestFixture
VAR_INPUT
    CheckRequested        : BOOL; // Front : nouvelle vérification demandée (sur Start suite)
    SimulationModeActive  : BOOL;
    SimGateOk             : BOOL; // Niveau 2 : aucune E/S M3 (*IsReal) incompatible
END_VAR
VAR_OUTPUT
    FixturePassed  : BOOL;
    FixtureFailed  : BOOL;
    FailReason     : STRING(120);
END_VAR
VAR
    CheckTrig : R_TRIG;
END_VAR
// === IMPLEMENTATION ===
CheckTrig(CLK := CheckRequested);

IF CheckTrig.Q THEN
    IF NOT SimulationModeActive THEN
        FixturePassed := FALSE;
        FixtureFailed := TRUE;
        FailReason := 'Simulation non active (GVL_Simulation.SimulationModeActive=FALSE)';
    ELSIF NOT SimGateOk THEN
        FixturePassed := FALSE;
        FixtureFailed := TRUE;
        FailReason := 'E/S M3 recablees reelles (*IsReal) incompatibles avec le banc de test';
    ELSE
        FixturePassed := TRUE;
        FixtureFailed := FALSE;
        FailReason := '';
    END_IF;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   ⚖️ FB_WinchSync — Surveillance d'écart M1/M2 (M1: moteur de retenue, M2: moteur Benne — squelette liaisons — pas de correction)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-10_Fonction_Winch_v2.0.md §9
   🔌 FB STANDARD (Partie3 §1bis) : pas un FB de mouvement, pas de StartStop/SafeStop —
      1 seule instance (surveille les 2 treuils, pas 1 par treuil comme FB_Safety_Winch).
   🎯 PÉRIMÈTRE CE LOT (squelette de liaisons, décisions Partie9 §9 déjà actées) :
      - Calcule `DeltaPosM = |CablePosM1 - CablePosM2|` (fiable seulement si les 2 treuils
        sont homés — sinon 0.0, pas de comparaison).
      - `SyncActive` selon `Mode` : MAINT_N1 = imposée (non désactivable, sécurité
        maintenue) ; MAINT_N2 = activable/désactivable via `SyncEnable` (FB_Modes, 🔧 REX
        2026-07-08 : ex-`OverrideSync` inversé) ; MANUEL/SEMI_AUTO = active par défaut.
      - `SyncWarn` = AVERTISSEMENT IHM SEULEMENT (Partie5 §6, comme `SyncWarn`/
        `ForceImbalance` cités en exemple) — **PAS de SafeStop** : aucune correction de
        vitesse n'existe aujourd'hui côté FB_Winch (pas d'entrée dédiée), donc rien à
        piloter automatiquement ce lot. Surveillance visuelle opérateur en attendant.
   🔴 HORS PÉRIMÈTRE CE LOT : régulation/correction active de l'écart (nécessiterait une
      entrée de correction sur FB_Winch, pas encore conçue) — squelette de surveillance
      uniquement, comme demandé (« même s'il n'est pas complet à l'intérieur »).

   🔧 REX 2026-07-08 (5) — incident terrain : écart mineur transitoire (0.24m, mécanique,
      coast-down différentiel M1/M2 à l'arrêt réel — normal et inévitable) déclenchait bit0
      et bloquait le mouvement dans les DEUX sens (régression, déblocage possible seulement
      via Reset+MAINT_N2+SyncEnable=FALSE). Root cause : phénomène mécanique, pas un bug du
      couplage croisé logiciel (bit1). Deux correctifs :
      1) `SignedDeltaPosM` (nouvelle sortie, calculé AVANT le ABS() de `DeltaPosM`) : signe
         positif = M1 "plus haut" que M2, négatif = M2 plus haut. Consommé par PRG_06 pour
         arbitrer DIRECTIONNELLEMENT le blocage bit0 — seul le sens qui AGGRAVE l'écart reste
         bloqué, l'autre sens (qui le réduit) reste autorisé. Méca E (FB_Safety_Winch, écart
         critique 2.0m) et bit1 restent le filet réel si l'écart continue de dériver.
      2) Filtre temporel `DeviationTimer` (même pattern que `MismatchTimer` bit1) sur bit0,
         800ms 🔧 théorique à ajuster sur site — absorbe le transitoire mécanique normal
         d'arrêt (~900ms de temporisations frein cumulées M1+M2).
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_WinchSync) ===

FUNCTION_BLOCK PUBLIC FB_WinchSync
VAR_INPUT
    Enable          : BOOL;        // Standard — Partie5 §2 : FB_WinchSync.Enable := SyncEnable (câblage PRG_MAIN)
    Reset           : BOOL;        // Acquittement défaut (front)
    PowerContactorEngaged : BOOL;        // Standard
    Mode            : E_Mode;      // Arbitre SyncActive (voir en-tête)
    CablePosM1      : REAL;        // Sortie FB_Encoder_Scale M1
    CablePosM2      : REAL;        // Sortie FB_Encoder_Scale M2
    HomedM1         : BOOL;        // Sortie FB_Encoder_Homing M1
    HomedM2         : BOOL;        // Sortie FB_Encoder_Homing M2
    SyncEnable      : BOOL;        // 🔧 REX 2026-07-08 : ex-OverrideSync inversé — Sortie FB_Modes, TRUE=synchro voulue
    CfgSyncToleranceM  : REAL := 0.10; // RETAIN site (PRG_MAIN) — écart max toléré avant SyncWarn
    ActiveOffsetM   : REAL := 0.0; // 🪣 Offset cible appliqué (ex: benne fermé/ouvert)
    
    // 🆕 Signaux de commande réels des treuils (pour contrôle de cohérence)
    RelayFwdM1      : BOOL;
    RelayFwdM2      : BOOL;
    RelayRevM1      : BOOL;
    RelayRevM2      : BOOL;
    Contactor1_M1   : BOOL;
    Contactor1_M2   : BOOL;
    Contactor2_M1   : BOOL;
    Contactor2_M2   : BOOL;
    Contactor3_M1   : BOOL;
    Contactor3_M2   : BOOL;
    Contactor4_M1   : BOOL;
    Contactor4_M2   : BOOL;
    // 🌐 Bypass Global : force ErrorId = 0, ignore toute erreur de synchro
    BypassGlobal    : BOOL := FALSE;
END_VAR
VAR_OUTPUT
    Ready           : BOOL;
    Busy            : BOOL;
    Done            : BOOL;
    Error           : BOOL;
    ErrorId         : WORD;        // bit0: "Écart synchronisme trop important" - écart hors tolérance (SyncActive uniquement) ; bit1: "Incohérence commande synchro" - incohérence de commande (sens/paliers différents)
    State           : E_State;
    StateAtError    : E_State;
    DeltaPosM       : REAL;        // |CablePosM1 - CablePosM2|, 0.0 si pas les 2 homés
    SignedDeltaPosM : REAL;        // 🆕 REX 2026-07-08 (5) : signé, > 0 = M1 plus haut que M2 — pour arbitrage directionnel PRG_06
    SyncActive      : BOOL;        // Surveillance imposée/activable selon Mode (voir en-tête)
    SyncWarn        : BOOL;        // ⚠️ Avertissement IHM uniquement (Partie5 §6) — PAS de SafeStop
END_VAR
VAR
    ResetEdge       : R_TRIG;
    ErrorEdge       : R_TRIG;
    MismatchActive  : BOOL;        // 🆕 Indique une discordance active de commande
    MismatchTimer   : TON;         // 🆕 Filtre temporel pour éviter les faux déclenchements transitoires
    DeviationActive : BOOL;        // 🆕 REX 2026-07-08 (5) : écart hors tolérance actif (avant filtre)
    DeviationTimer  : TON;         // 🆕 REX 2026-07-08 (5) : filtre temporel bit0, même pattern que MismatchTimer
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_WinchSync) ===

// 🛑 1. GATE
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    State := E_State.DISABLED;
    DeltaPosM := 0.0;
    SyncActive := FALSE;
    SyncWarn := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🌐 BYPASS GLOBAL : force ErrorId = 0 et ignore toute la surveillance synchro
IF BypassGlobal THEN
    ErrorId := 16#0000;
END_IF;

// 🎚️ 3. SyncActive SELON MODE (Partie9 §9, décisions actées 2026-07-02)
CASE Mode OF
    E_Mode.MAINT_N1:
        SyncActive := TRUE;                  // Imposée, non désactivable (sécurité maintenue N1)
    E_Mode.MAINT_N2:
        SyncActive := SyncEnable;             // 🔧 REX 2026-07-08 : ex-NOT OverrideSync, polarité déjà positive
    ELSE
        SyncActive := TRUE;                  // MANUEL/SEMI_AUTO : pas de logique dédiée (FB_Cycle absent), actif par prudence
END_CASE;

// 📏 4. ÉCART M1/M2 — calculé en continu si les 2 treuils sont homés (même si BypassGlobal est actif)
IF HomedM1 AND HomedM2 THEN
    SignedDeltaPosM := CablePosM1 - CablePosM2 + ActiveOffsetM;
    DeltaPosM := ABS(SignedDeltaPosM);
ELSE
    SignedDeltaPosM := 0.0;
    DeltaPosM := 0.0;
END_IF;

// 🌐 BYPASS GLOBAL : si actif, on saute TOUTE la logique d'erreur/surveillance
IF NOT BypassGlobal THEN

// 🔍 5. DÉTECTION ÉCART HORS TOLÉRANCE — bit0
// 🔧 REX 2026-07-08 (5) : filtre temporel (même pattern que MismatchTimer bit1) — absorbe le
// transitoire mécanique normal d'arrêt (coast-down différentiel M1/M2), évite le blocage
// intempestif constaté sur incident terrain (0.24m transitoire).
DeviationActive := SyncActive AND HomedM1 AND HomedM2 AND (DeltaPosM > CfgSyncToleranceM);
DeviationTimer(IN := DeviationActive, PT := T#800ms);  // 🔧 théorique, à ajuster sur site — absorbe le transitoire mécanique normal d'arrêt (coast-down différentiel M1/M2)
IF DeviationTimer.Q THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q AND NOT DeviationActive THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 🔍 5bis. COHÉRENCE DES COMMANDES SÉCURITÉ — bit1
// Vérifie que les commandes envoyées aux deux treuils sont identiques (sens et contacteurs)
// Filtre de 500ms pour tolérer les transitions et rampes.
MismatchActive := SyncActive AND (
    (RelayFwdM1 <> RelayFwdM2) OR
    (RelayRevM1 <> RelayRevM2) OR
    (Contactor1_M1 <> Contactor1_M2) OR
    (Contactor2_M1 <> Contactor2_M2) OR
    (Contactor3_M1 <> Contactor3_M2) OR
    (Contactor4_M1 <> Contactor4_M2)
);

MismatchTimer(IN := MismatchActive, PT := T#500ms);

IF MismatchTimer.Q THEN
    ErrorId := ErrorId OR 16#0002;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFD;
END_IF; // fin du IF MismatchActive

END_IF; // fin IF NOT BypassGlobal

// 📤 6. SORTIES ÉTAT
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

SyncWarn := Error;   // ⚠️ IHM uniquement — voir en-tête, pas de SafeStop
Busy := FALSE;
Done := FALSE;

// ═══════════════════════════════════════════════════════════════
// 🧪 FB_TranslationValidation — Suite de test Translation M3
// ───────────────────────────────────────────────────────────────
// 📄 Doc métier : DOC/AF_Partie-11_Fonction_Translation_v1.9.md
// 🎯 Valide les surveillances de sécurité de FB_Safety_Translation :
//    TC-T1 Fin de course extrême, TC-T2 Méca B (incohérence à l'arrêt),
//    TC-T3 Méca A (mouvement non commandé), TC-T4 les 6 mots valides +
//    limites extrêmes, TC-T5 incohérence mot capteurs (SafeStop+PowerCutOff),
//    TC-T6 ralentissement PV (instance FB_Translation isolée).
// 🆕 Tranche verticale NEUVE (2026-07-22, audit DOC/AUDITS/TEST_FRAMEWORK_AUDIT_v1.0.md) :
//    moteur dédié, composé d'objets à responsabilité unique sous CORE/ —
//    N'INSTANCIE NI FB_TestSequencer NI les anciennes BRICKS
//    (FB_TestCheck/FB_Timeout/FB_TestStimulus/...). Les autres suites
//    (Safety/Bucket/Encoder/Modes/Heartbeat) restent inchangées sur
//    l'ancien moteur générique.
//      - FB_TranslationTestPlan          : tables déclaratives + validation
//      - FB_TranslationStepExecutor      : exécution étape/check + cantonnement de cas
//      - FB_TranslationTestRuntime       : cycle de vie (Start -> Fixture -> Executor -> Finalize)
//      - FB_TranslationTestFixture       : précondition (gate Niveau 1/2, PRECONDITION_FAILED explicite)
//      - FB_TranslationTestCleanup       : neutralité (source de vérité unique)
//      - FB_TranslationReportFinalizer   : rapport existant (ST_TestSuiteReport) + résultat plat (ST_TranslationTestResult)
// 🔒 API publique : Start / Abort / CaseId (0=toutes les cases, 1..6=case
//    ciblée) — JAMAIS de FirstStepId exposé (audit v1.0 C2).
// 🔑 Les index de sondes (Sig*) sont possédés ICI (ce fichier), transmis en
//    VAR_INPUT à FB_TranslationTestPlan à chaque appel — aucun accès
//    croisé "instPlan.SigXxx" en retour.
// ⚠️ Hors périmètre (non testé ici, nécessiterait des overrides
//    supplémentaires sur les diagnostics bus) : bit0 (perte Joystick
//    CANopen), bit1 (perte com EtherCAT variateur), bit2 (rotation
//    de phases), bit3 (thermique frein commun).
// ═══════════════════════════════════════════════════════════════

FUNCTION_BLOCK PUBLIC FB_TranslationValidation
VAR_INPUT
    Start   : BOOL; // Commande de démarrage
    Abort   : BOOL; // Commande d'abandon
    CaseId  : INT;  // 0 = toutes les cases (1..6) ; 1..6 = case ciblée uniquement
END_VAR
VAR_OUTPUT
    Busy                : BOOL;
    Done                : BOOL;
    AnyFailed           : BOOL;
    SimGateOk           : BOOL;        // Indique si la simulation est autorisée (Niveau 1/2)
    ActiveStimulusId    : INT;
    StepElapsed         : TIME;
    Report              : ST_TestSuiteReport;      // 📊 Rapport existant — compat GVL_PLC_Tests/IHM/manager
    Result              : ST_TranslationTestResult; // 📋 Résultat plat clair — nouveau
    TerminalState       : E_TestTerminalState;
    ConfigError         : BOOL;
    ConfigErrorStepId   : INT;
    ConfigErrorCheckIdx : INT;
    ErrorCode           : INT;
    ErrorMessage        : STRING(160);
END_VAR
VAR CONSTANT
    // 🏷️ Index des sondes — source de vérité UNIQUE, transmis à instPlan
    // en VAR_INPUT (jamais lus en retour via une instance).
    SigHealthyIdle          : INT := 1;
    SigLimitSwitchError     : INT := 2;
    SigPowerCutOff          : INT := 3;
    SigErrorIdT1NoParasite  : INT := 4;
    SigMecaBError           : INT := 5;
    SigErrorIdT2NoParasite  : INT := 6;
    SigMecaAError           : INT := 7;
    SigErrorIdT3NoParasite  : INT := 8;
    SigDecoderIncoherent    : INT := 9;
    SigLimitFwd             : INT := 10;
    SigLimitRev             : INT := 11;
    SigSensorIncoherentErr  : INT := 12;
    SigErrorIdT5NoParasite  : INT := 13; // DINT
    SigSlowdownFreqHz       : INT := 14; // REAL
END_VAR
VAR
    // 🧩 Objets CORE — composition, responsabilité unique chacun
    instPlan    : FB_TranslationTestPlan;
    instRuntime : FB_TranslationTestRuntime;
    instCleanup : FB_TranslationTestCleanup;

    // 📋 Tables déclaratives — possédées ici, construites par instPlan
    StepTable  : ARRAY[1..GVL_PLC_Tests_Const.MaxSteps]      OF ST_TestStepConfig;
    CheckTable : ARRAY[1..GVL_PLC_Tests_Const.MaxChecks]     OF ST_TestCheckConfig;
    CaseTable  : ARRAY[1..GVL_PLC_Tests_Const.MaxTestCases]  OF ST_TestCaseConfig;

    // 📥 Banque de sondes
    ProbeBool : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeBool] OF BOOL;
    ProbeDint : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeDint] OF DINT;
    ProbeReal : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeReal] OF REAL;

    // 🆕 TC-T6 — instance ISOLÉE de FB_Translation (pas l'instance machine réelle
    // instTranslationM3) pour tester le ralentissement PV en pilotant Direction/StartStop/SpeedRefPct
    // directement, sans dépendre de l'arbitrage Mode de PRG_07_TranslationControl.
    instTranslationUnderTest : FB_Translation;
    UnderTestDirection       : INT;
    UnderTestStartStop       : BOOL;
    UnderTestSlowdownSensor  : BOOL;
    ResetFaults              : BOOL;
    NeutralConfirmedPrevious : BOOL; // Retour cleanup du scan précédent vers le runtime
END_VAR
// === IMPLEMENTATION ===

// 1. 🛡️ GATE Niveau 1/2 — calculé en continu (lu par le manager Niveau 3, même hors Busy)
// Refuse si un des équipements M3 est déjà recâblé réel.
SimGateOk := NOT GVL_Simulation.SensorTranslationPositionIsReal
         AND NOT GVL_Simulation.SensorM3ContactorFeedbackIsReal
         AND NOT GVL_Simulation.BusVariateurM3IsReal;

// 2. 📋 PLAN — construction (une fois) + validation ; les index de sondes
//    sont transmis ICI, jamais relus depuis l'instance.
instPlan(
    SigHealthyIdle := SigHealthyIdle, SigLimitSwitchError := SigLimitSwitchError,
    SigPowerCutOff := SigPowerCutOff, SigErrorIdT1NoParasite := SigErrorIdT1NoParasite,
    SigMecaBError := SigMecaBError, SigErrorIdT2NoParasite := SigErrorIdT2NoParasite,
    SigMecaAError := SigMecaAError, SigErrorIdT3NoParasite := SigErrorIdT3NoParasite,
    SigDecoderIncoherent := SigDecoderIncoherent, SigLimitFwd := SigLimitFwd,
    SigLimitRev := SigLimitRev, SigSensorIncoherentErr := SigSensorIncoherentErr,
    SigErrorIdT5NoParasite := SigErrorIdT5NoParasite, SigSlowdownFreqHz := SigSlowdownFreqHz,
    StepTable := StepTable, CheckTable := CheckTable, CaseTable := CaseTable
);

// 3. 📥 ACQUIRE — sondes réelles + instance isolée TC-T6 (pilotée par le
//    stimulus décidé au scan précédent, cf. §5 STIMULI)
ProbeBool[SigHealthyIdle]      := NOT PRG_03_Safety.instSafetyTranslationM3.Error;
ProbeBool[SigLimitSwitchError] := PRG_03_Safety.instSafetyTranslationM3.ErrorLimitSwitch;
ProbeBool[SigPowerCutOff]      := PRG_03_Safety.instSafetyTranslationM3.PowerCutOff;
ProbeDint[SigErrorIdT1NoParasite] := WORD_TO_DINT(PRG_03_Safety.instSafetyTranslationM3.ErrorId);
ProbeBool[SigMecaBError]       := PRG_03_Safety.instSafetyTranslationM3.ErrorMecaB;
ProbeDint[SigErrorIdT2NoParasite] := WORD_TO_DINT(PRG_03_Safety.instSafetyTranslationM3.ErrorId);
ProbeBool[SigMecaAError]       := PRG_03_Safety.instSafetyTranslationM3.ErrorMecaA;
ProbeDint[SigErrorIdT3NoParasite] := WORD_TO_DINT(PRG_03_Safety.instSafetyTranslationM3.ErrorId);
ProbeBool[SigDecoderIncoherent]   := PRG_00_Inputs.instPositionDecoder.Incoherent;
ProbeBool[SigLimitFwd]            := PRG_00_Inputs.instPositionDecoder.LimitSwitchFwd;
ProbeBool[SigLimitRev]            := PRG_00_Inputs.instPositionDecoder.LimitSwitchRev;
ProbeBool[SigSensorIncoherentErr] := PRG_03_Safety.instSafetyTranslationM3.ErrorSensorIncoherent;
ProbeDint[SigErrorIdT5NoParasite] := WORD_TO_DINT(PRG_03_Safety.instSafetyTranslationM3.ErrorId);

instTranslationUnderTest(
    Enable := TRUE, Reset := ResetFaults, EmergencyStopOk := TRUE, Mode := E_Mode.MAINT_N1,
    StartStop := UnderTestStartStop, SafeStop := FALSE,
    Direction := UnderTestDirection, SpeedRefPct := 100.0,
    PositionSensorTarget := FALSE, SlowdownSensor := UnderTestSlowdownSensor,
    LimitSwitchFwd := FALSE, LimitSwitchRev := FALSE,
    DriveStatusWord := 0, DriveActualFreqHz := 0.0,
    BypassContactorCheck := TRUE, BrakeFeedback := FALSE
);
ProbeReal[SigSlowdownFreqHz] := instTranslationUnderTest.DriveFreqRefHz;

// 4. ♻️ RUNTIME — cycle de vie complet (Fixture -> Executor -> Finalize)
instRuntime(
    Start := Start, Abort := Abort, CaseId := CaseId,
    PlanConfigError := instPlan.ConfigError,
    PlanConfigErrorStepId := instPlan.ConfigErrorStepId,
    PlanConfigErrorCheckIdx := instPlan.ConfigErrorCheckIdx,
    PlanConfigErrorMessage := instPlan.ConfigErrorMessage,
    SimulationModeActive := GVL_Simulation.SimulationModeActive,
    SimGateOk := SimGateOk,
    NeutralConfirmed := NeutralConfirmedPrevious,
    StepTable := StepTable, CheckTable := CheckTable, CaseTable := CaseTable,
    ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal,
    Report := Report, Result := Result,
    Busy => Busy, Done => Done, AnyFailed => AnyFailed,
    ActiveStimulusId => ActiveStimulusId, StepElapsed => StepElapsed,
    TerminalState => TerminalState, ConfigError => ConfigError,
    ConfigErrorStepId => ConfigErrorStepId, ConfigErrorCheckIdx => ConfigErrorCheckIdx,
    ErrorCode => ErrorCode, ErrorMessage => ErrorMessage
);

// 5. ⚡ STIMULI — vecteur complet : neutre d'abord, surcharge ensuite.
//    Aucun champ ne dépend de la branche ou du scan précédent.
GVL_PLC_Tests.OverrideM3AtTremie := FALSE;
GVL_PLC_Tests.OverrideM3BrakeStuckOpen := FALSE;
GVL_PLC_Tests.OverrideM3PhantomFreq := FALSE;
GVL_PLC_Tests.OverrideM3SensorsWordActive := FALSE;
GVL_PLC_Tests.OverrideM3SensorsWord := 0;
UnderTestDirection := 0;
UnderTestStartStop := FALSE;
UnderTestSlowdownSensor := FALSE;
ResetFaults := FALSE;

IF NOT instRuntime.CleanupRequest THEN
    CASE ActiveStimulusId OF
        1: ResetFaults := TRUE; // Setup/teardown : reset sur front externe conditionné
        2: GVL_PLC_Tests.OverrideM3AtTremie := TRUE;
        3: GVL_PLC_Tests.OverrideM3BrakeStuckOpen := TRUE;
        4: GVL_PLC_Tests.OverrideM3PhantomFreq := TRUE;
        5: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#11111;
        6: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#01111;
        7: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#00111;
        8: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#00011;
        9: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#00001;
        10: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#00000;
        11: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#10101;
        12: UnderTestDirection := 1; UnderTestStartStop := TRUE;
        13: UnderTestDirection := 1; UnderTestStartStop := TRUE; UnderTestSlowdownSensor := TRUE;
    END_CASE;
END_IF;

// 🧹 Confirmation calculée APRÈS écriture du vecteur neutre ; consommée
// par le runtime au scan suivant pour garantir la propagation cyclique.
instCleanup(Apply := instRuntime.CleanupRequest);
NeutralConfirmedPrevious := instCleanup.NeutralConfirmed
    AND NOT GVL_PLC_Tests.OverrideM3AtTremie
    AND NOT GVL_PLC_Tests.OverrideM3BrakeStuckOpen
    AND NOT GVL_PLC_Tests.OverrideM3PhantomFreq
    AND NOT GVL_PLC_Tests.OverrideM3SensorsWordActive
    AND (GVL_PLC_Tests.OverrideM3SensorsWord = 0)
    AND (UnderTestDirection = 0)
    AND NOT UnderTestStartStop
    AND NOT UnderTestSlowdownSensor
    AND NOT ResetFaults;

// Recopie IHM/métier — reset partagé avec la suite Safety (même domaine
// "sécurité/métier", voir PRG_09_Supervision.FaultMachineReset_IHM), sans
// conflit car les suites s'exécutent toujours de façon mutuellement exclusive
// (FB_PLC_Tests_Management n'active qu'une suite à la fois).
IF Busy THEN
    GVL_IHM.Modes.Cmd.BtnFaultReset := ResetFaults;
END_IF;

SETUP
VAR
    fb : FB_SAFETY_EMERGENCYMANAGEMENT;
END_VAR
END_SETUP

TEST 'TC-P01-008 PowerCutOffRequest coupe A et B sans armer'
    (* scan 1 : autotest demarrage (1 cycle, boucle saine, contacteur repos) *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);

    (* scan 2 : regime etabli, maintien sain attendu -- +1 cycle automate (10ms) *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'hors defaut, canal A doit etre maintenu');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'hors defaut, canal B doit etre maintenu');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'pas de sequence en cours');

    (* scan 3 : coupure demandee par un metier (Winch/Translation) -- +1 cycle automate *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := TRUE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'PowerCutOffRequest doit couper le canal A');
    ASSERT_FALSE(fb.MAINTAINB_RQ, 'PowerCutOffRequest doit couper le canal B');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'PowerCutOffRequest ne doit jamais declencher une sequence armement');
END_TEST

TEST 'TC-P01-006 canal colle bloque le reamement (echec auto-test)'
    (* scans 1-2 : demarrage + regime etabli, sain *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);

    (* front ArmRequest -> ArmingSeqStep passe a 1 (TestA), boucle encore saine ce scan -- +1 cycle *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'front ArmRequest doit lancer TestA (step 1)');

    (* 200ms plus tard : le canal A est cense etre coupe, mais la boucle reste fermee -> collage *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.ERROR, 'canal colle doit lever une erreur (RedundancyTestFailed)');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'echec auto-test doit ramener la sequence a IDLE');
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'un canal colle bloque aussi le maintien normal (interlock sur Cause brute)');
END_TEST

TEST 'TC-P01-004/009 Reset acquitte l affichage mais re-alarme si la cause persiste'
    (* reproduit l etat "canal colle" de TC-P01-006 -- setup independant, propre a ce test *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.ERROR, 'precondition : canal colle doit avoir leve une erreur');

    (* Reset : doit acquitter l affichage sans redemarrage auto (TC-P01-004) -- +1 cycle *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := TRUE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_FALSE(fb.ERROR, 'Reset doit effacer l affichage du defaut');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'Reset seul ne relance jamais de sequence (pas de redemarrage auto)');

    (* nouvel essai : cause toujours presente (canal toujours colle) -> doit re-alarmer (TC-P01-009) -- +1 cycle *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'un nouveau front ArmRequest doit relancer TestA');

    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.ERROR, 'cause persistante doit re-alarmer au nouvel essai, meme apres Reset');
END_TEST

(* TC-P01-002 est classee SITE+AUTO dans l AF (mixte). Ce test ne couvre QUE la partie AUTO
   (commande logicielle) : preuve qu un seul canal est coupe a la fois et que le FB interprete
   correctement le retour de boucle fourni en entree. Il ne peut PAS prouver que la coupure
   physique de MaintainA/B_RQ ouvre reellement la boucle materielle -- ca reste une verification
   SITE, sur l automate reel, jamais automatisable en logiciel. *)
TEST 'TC-P01-002 (partie AUTO) chaque canal est commande independamment, l autre reste maintenu'
    (* demarrage + regime etabli, sain *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'hors defaut, canal A maintenu');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'hors defaut, canal B maintenu');

    (* front ArmRequest -> TestA (step 1) : SEUL le canal A doit se couper *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'front doit lancer TestA');
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'TestA : canal A seul doit se couper');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'TestA : canal B ne doit PAS etre affecte');

    (* 200ms plus tard : la boucle reagit reellement a la coupure de A (preuve physique reelle) *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := FALSE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 2, 'TestA reussi (boucle a reagi) -> RestoreA');
    ASSERT_FALSE(fb.ERROR, 'pas de defaut si le canal reagit correctement au test');
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'canal A restaure immediatement apres son test');

    (* 200ms plus tard : boucle refermee (A restaure) -> passage a TestB (step 3) *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 3, 'RestoreA reussi -> TestB');
    ASSERT_FALSE(fb.MAINTAINB_RQ, 'TestB : canal B seul doit se couper');
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'TestB : canal A ne doit PAS etre affecte');

    (* 200ms plus tard : boucle reagit a la coupure de B *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := FALSE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 4, 'TestB reussi -> RestoreB');
    ASSERT_FALSE(fb.ERROR, 'pas de defaut si le canal B reagit correctement au test');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'canal B restaure immediatement apres son test');
END_TEST

