(* ═══════════════════════════════════════════════════════════════
   🧲 FB_Encoder_Abs — Acquisition codeur absolu (accès bus EtherCAT)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-09_Fonction_Encoder_v2.1.md §3/§6
                   DOC/AF_Partie-03_Contrats_Composants_v2.1.md
   🎯 Accès bus EtherCAT, statut esclave, extraction positions brutes
      et séquence de Preset SDO (PresetTriggerCmd := 2).
   🧊 Principe « geler sur doute » (§6) : RawPos/AngleRaw/TurnCount
      conservent leur dernière valeur valide si EncoderAvailable = FALSE.
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Encoder_Abs) ===

FUNCTION_BLOCK PUBLIC FB_Encoder_Abs
VAR_INPUT
    Enable              : BOOL;        // Standard
    Reset               : BOOL;        // Acquittement défaut (front)
    PowerContactorEngaged     : BOOL;        // Standard
    Mode                : E_Mode;      // Standard (contexte, pas encore exploité ce lot)
    RawPosIn            : UDINT;       // Brut EtherCAT (ex. COD1_PosValue, %ID)
    AlarmsIn            : UINT;        // Brut EtherCAT (ex. COD1_Alarms)
    WarningsIn          : UINT;        // Brut EtherCAT (ex. COD1_Warnings) — informatif seulement
    SlaveOperational    : BOOL;        // FB_Diag_Ethercat — esclave EtherCAT opérationnel
    PointsPerRev        : UDINT := 8192;  // Résolution codeur confirmée (Partie10 §3.3)
    PresetRequest       : BOOL;        // Front — piloté par FB_Encoder_Homing via PRG_02_Encoders
    PresetValue         : UDINT;       // Cible brute — piloté par FB_Encoder_Homing (stub 0 ce lot)
    PresetTimeout       : TIME := T#2s;
    PresetTolerancePts  : UDINT := 10; // Tolérance relecture post-preset
END_VAR
VAR_OUTPUT
    Ready               : BOOL;
    Busy                : BOOL;
    Done                : BOOL;
    Error               : BOOL;
    ErrorId             : WORD;        // bit0: "Défaut communication codeur" - alarme/bus codeur ; bit1: "Erreur référencement (timeout)" - preset refusé/timeout
    State               : E_State;
    StateAtError        : E_State;
    RawPos              : UDINT;       // Position brute — GELÉE si EncoderAvailable=FALSE
    EncoderAvailable    : BOOL;
    AngleRaw            : UINT;        // Informatif maintenance : RawPos MOD PointsPerRev
    TurnCount           : UDINT;       // Informatif maintenance : RawPos / PointsPerRev
    PresetAck           : BOOL;        // Pulse 1 cycle — écriture confirmée
    PresetNak           : BOOL;        // Pulse 1 cycle — écriture refusée/timeout
    PresetTriggerCmd    : WORD;        // → à câbler sur COD_PresettTrigCmd (RxPDO)
    CodeSeqTriggerCmd   : WORD;        // → à câbler sur COD_CodeSeqTrigCmd (RxPDO)
    PresetValueOut      : UDINT;       // → à câbler sur COD_PresetValue (RxPDO)
END_VAR
VAR
    ResetEdge           : R_TRIG;
    ErrorEdge           : R_TRIG;
    PresetReqEdge       : R_TRIG;
    PresetTimer         : TON;
    PresetSeqStep       : INT;         // 0=IDLE, 1=pulse CodeSeq, 2=pulse Trig, 3=attente confirmation
    RawDiff             : DINT;
    PresetTimerVisual   : TON;         // Timer pour laisser le temps de voir l'impulsion (1.5s)
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Abs) ===

// 🛑 1. GATE
IF NOT Enable THEN
    EncoderAvailable := FALSE;
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    PresetTriggerCmd := 16#0000; CodeSeqTriggerCmd := 16#0000; PresetValueOut := 0;
    PresetSeqStep := 0;
    PresetTimer(IN := FALSE, PT := PresetTimeout);
    PresetTimerVisual(IN := FALSE, PT := T#500MS);
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🔍 3. DIAGNOSTIC BUS / ALARME
IF (AlarmsIn <> 0) OR NOT SlaveOperational THEN
    ErrorId := ErrorId OR 16#0001;
ELSE
    ErrorId := ErrorId AND 16#FFFE; (* Auto-clearing dès que le bus et l'esclave sont OK *)
END_IF;
EncoderAvailable := (ErrorId AND 16#0001) = 0;

// 📥 4. LECTURE POSITION — GELER SUR DOUTE (Partie10 §6)
// Si EncoderAvailable=FALSE : RawPos/AngleRaw/TurnCount conservent leur dernière valeur (pas de RETURN
// global ici pour ne pas geler aussi la séquence preset/l'état — seule la lecture est gelée).
IF EncoderAvailable THEN
    RawPos := RawPosIn;   // 🔧 2026-07-03 : sens de comptage géré côté codeur (CoE 6000h bit0,
                          // startup parameter CODESYS) — voir Partie10 §3bis. Plus de calcul ici.
    AngleRaw := UDINT_TO_UINT(RawPos MOD PointsPerRev);
    TurnCount := RawPos / PointsPerRev;
END_IF;

// 🔧 5. SÉQUENCE PRESET (écriture bus)
// ✅ Confirmé terrain (2026-07-02) : PresettTrigCmd := 2 déclenche le référencement à
//    PresetValue (valeur de commande, pas un masque de bits — corrige l'hypothèse initiale).
// 🔴 CodeSeqTrigCmd : rôle NON identifié (même par l'utilisateur/terrain) — laissé à 0,
//    PAS piloté tant que sa fonction n'est pas confirmée (fiche technique ou essai dédié).
//    Ne jamais lui donner une valeur arbitraire "au cas où".
PresetReqEdge(CLK := PresetRequest);
PresetAck := FALSE; PresetNak := FALSE; // pulses 1 cycle uniquement
CodeSeqTriggerCmd := 16#0000;           // 🔴 non piloté — rôle inconnu, voir note ci-dessus
CASE PresetSeqStep OF
    0: // IDLE
        PresetTriggerCmd := 0;
        IF PresetReqEdge.Q AND EncoderAvailable THEN
            PresetValueOut := PresetValue;
            PresetSeqStep := 1;
            PresetTimer(IN := TRUE, PT := PresetTimeout);
        END_IF;
    1: // Déclenchement preset (laissé actif pendant 0.5s pour confort visuel en simulation/bus)
        PresetTriggerCmd := 2;   // ✅ Valeur confirmée terrain — référence le codeur à PresetValueOut
        RawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(PresetValueOut);
        IF ABS(RawDiff) <= UDINT_TO_DINT(PresetTolerancePts) THEN
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := TRUE, PT := T#500MS);
            IF PresetTimerVisual.Q THEN
                PresetTriggerCmd := 0;
                PresetAck := TRUE;
                PresetSeqStep := 0;
                PresetTimerVisual(IN := FALSE, PT := T#500MS);
            END_IF;
        ELSIF PresetTimer.Q THEN
            PresetTriggerCmd := 0;
            PresetNak := TRUE;
            ErrorId := ErrorId OR 16#0002;
            PresetSeqStep := 0;
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := FALSE, PT := T#500MS);
        END_IF;
END_CASE;
IF ResetEdge.Q AND (PresetSeqStep = 0) THEN
    ErrorId := ErrorId AND 16#FFFD;
END_IF;

// 🧾 6. ERROR / STATEATERROR
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

Busy := (PresetSeqStep <> 0);
Done := PresetAck;

(* ═══════════════════════════════════════════════════════════════
   💾 GVL_BypassRetain — Variables RETAIN pour les bypass de mise en service
   ───────────────────────────────────────────────────────────────
   🔒 Survit au Warm Restart (CPU Stop/Start) mais PAS au Download.
   🎯 Utilisé uniquement lors de la mise en service / débogage.
   ═══════════════════════════════════════════════════════════════ *)
VAR_GLOBAL RETAIN

    // 🌐 Bypass Global Translation M3 (FB_Safety_Translation + FB_Translation)
    BypassTranslationGlobal     : BOOL := FALSE;
    // 🌐 Bypass Global Treuil M1 (FB_Safety_Winch + FB_Winch)
    BypassWinchM1Global         : BOOL := FALSE;
    // 🌐 Bypass Global Treuil M2 (FB_Safety_Winch + FB_Winch)
    BypassWinchM2Global         : BOOL := FALSE;
    // 🌐 Bypass Global Synchro M1/M2 (FB_WinchSync)
    BypassSyncGlobal            : BOOL := FALSE;
    // 🌐 Bypass Global Réseau CAN/EtherCAT (force Online)
    BypassNetworkGlobal         : BOOL := FALSE;
    // 🌐 Bypass Global Benne (FB_Bucket)
    BypassBucketGlobal          : BOOL := FALSE;

END_VAR

(* ═══════════════════════════════════════════════════════════════
   📡 FB_Diag_CanOpen — Diagnostic bus CANopen / Joystick
   ───────────────────────────────────────────────────────────────
   📄 Docs : DOC/AF_Partie-02_Architecture_Programme_v3.1.md
              DOC/AF_Partie-06_Acquisition_Qualification_IO_v2.1.md §3
   🎯 Rôle : Décide Online/Operational et publie ST_Diag_Device.
      Distinction explicite dans State :
      - INIT       : pas encore online (ni réel, ni bypass)
      - SIMULATED  : bypass actif (simulation ou bypass réseau IHM)
      - READY      : bus réellement online
      - ERROR      : défaut détecté
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK PUBLIC FB_Diag_CanOpen
VAR_INPUT
    Enable          : BOOL;        (* Active la surveillance CAN *)
    Reset           : BOOL;        (* Front d'acquittement des défauts *)
    CANbusStateRaw          : INT;          (* Valeur brute CANbus.GetBusState() (2 = ACTIVE) *)
    DeviceJoystickStateRaw  : DEVICE_STATE; (* Valeur brute JOY1.GetDeviceState() *)
    SimBypassActive         : BOOL;         (* TRUE = simulation active pour ce device *)
    NetworkBypassActive     : BOOL;         (* TRUE = bypass réseau global IHM *)
END_VAR
VAR_OUTPUT
    Ready           : BOOL;        (* Logique de surveillance active *)
    Busy            : BOOL;        (* Non utilisé (conformité interface) *)
    Done            : BOOL;        (* Non utilisé *)
    Error           : BOOL;        (* Présence anomalie de communication *)
    ErrorId         : WORD;        (* Code défaut global résumé *)
    State           : E_Diag_State; (* Phase courante (INIT/SIMULATED/READY/ERROR) *)
    StateAtError    : E_Diag_State; (* Phase figée à l'apparition de l'erreur *)
    DeviceCanOpenMaster : ST_Diag_Device;  (* Diagnostics bus CANopen *)
    DeviceJoystick  : ST_Diag_Device;  (* Diagnostics esclave Joystick *)
    (* Miroirs bruts lisibles directement sur l'instance *)
    CANbusStateRawOut         : INT;
    DeviceJoystickStateRawOut : DEVICE_STATE;
END_VAR
VAR
    ResetEdge       : R_TRIG;      (* Détecteur front de reset *)
    CANbusOnlineReal         : BOOL; (* Bus réellement actif, hors tout bypass *)
    DeviceJoystickOnlineReal : BOOL; (* Joystick réellement RUNNING, hors tout bypass *)
    BypassActive             : BOOL; (* Simulation OU bypass réseau IHM *)
    CANbusOnlineEff          : BOOL; (* Online effectif (réel OU bypass) *)
    DeviceJoystickOnlineEff  : BOOL; (* Operational effectif (réel OU bypass) *)
END_VAR

// 🛑 1. GATE : Désactivation logique si Enable = FALSE
IF NOT Enable THEN
    Ready := FALSE;
    State := E_Diag_State.DISABLED;
    DeviceJoystick.State := E_Diag_State.DISABLED;
    DeviceJoystick.Online := FALSE;
    DeviceJoystick.Operational := FALSE;
    DeviceJoystick.Error := FALSE;
    DeviceJoystick.ErrorId := 16#0000;
    DeviceCanOpenMaster.State := E_Diag_State.DISABLED;
    DeviceCanOpenMaster.Online := FALSE;
    DeviceCanOpenMaster.Operational := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    CANbusStateRawOut := CANbusStateRaw;
    DeviceJoystickStateRawOut := DeviceJoystickStateRaw;
    RETURN;
END_IF;

Ready := TRUE;

// 🧮 2. INTERPRÉTATION DES VALEURS BRUTES
CANbusOnlineReal         := (CANbusStateRaw = 2);
DeviceJoystickOnlineReal := (DeviceJoystickStateRaw = DEVICE_STATE.RUNNING);
BypassActive             := SimBypassActive OR NetworkBypassActive;
CANbusOnlineEff          := CANbusOnlineReal OR BypassActive;
DeviceJoystickOnlineEff  := DeviceJoystickOnlineReal OR BypassActive;

// 🔑 3. RESET FRONT — Efface les défauts si la cause a disparu
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    IF (CANbusOnlineEff AND DeviceJoystickOnlineEff) THEN
        DeviceJoystick.ErrorId := 16#0000;
        StateAtError := E_Diag_State.DISABLED;
    END_IF;
END_IF;

// 🔍 4. DIAGNOSTIC JOYSTICK
// Bit 0 : Perte de communication CAN
IF NOT CANbusOnlineEff THEN
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId OR 16#0001;  (* Perte liaison CAN joystick *)
    DeviceJoystick.Online := FALSE;
ELSE
    DeviceJoystick.Online := TRUE;
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId AND 16#FFFE; (* Effacement auto si la liaison revient *)
END_IF;

// Bit 1 : Mode non-opérationnel (esclave CANopen en pré-op ou défaut)
IF NOT DeviceJoystickOnlineEff THEN
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId OR 16#0002;  (* Joystick pas opérationnel *)
    DeviceJoystick.Operational := FALSE;
ELSE
    DeviceJoystick.Operational := TRUE;
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId AND 16#FFFD; (* Effacement auto dès que RUNNING *)
END_IF;

// 🚦 5. MACHINE D'ÉTAT JOYSTICK
IF DeviceJoystick.ErrorId <> 0 THEN
    DeviceJoystick.State := E_Diag_State.ERROR;
    IF StateAtError = E_Diag_State.DISABLED THEN
        StateAtError := State;
    END_IF;
ELSIF NOT (DeviceJoystick.Online AND DeviceJoystick.Operational) THEN
    DeviceJoystick.State := E_Diag_State.INIT;
ELSIF BypassActive AND NOT (CANbusOnlineReal AND DeviceJoystickOnlineReal) THEN
    DeviceJoystick.State := E_Diag_State.SIMULATED;
ELSE
    DeviceJoystick.State := E_Diag_State.READY;
END_IF;

State := DeviceJoystick.State;

// 📤 6. SORTIES GLOBALES
DeviceJoystick.Error := (DeviceJoystick.ErrorId <> 0);
Error := DeviceJoystick.Error;
ErrorId := DeviceJoystick.ErrorId;

DeviceCanOpenMaster.Operational := CANbusOnlineEff;
DeviceCanOpenMaster.Online := CANbusOnlineEff;

IF NOT CANbusOnlineEff THEN
    DeviceCanOpenMaster.State := E_Diag_State.INIT;
ELSIF BypassActive AND NOT CANbusOnlineReal THEN
    DeviceCanOpenMaster.State := E_Diag_State.SIMULATED;
ELSE
    DeviceCanOpenMaster.State := E_Diag_State.READY;
END_IF;

// Miroirs bruts, toujours à jour
CANbusStateRawOut := CANbusStateRaw;
DeviceJoystickStateRawOut := DeviceJoystickStateRaw;

// Briques génériques pour conformité standard
Busy := FALSE;
Done := FALSE;

(* ═══════════════════════════════════════════════════════════════
   ↔️ FB_Translation_PositionDecoder — Décodage mot capteurs M3 (5 positions)
   ───────────────────────────────────────────────────────────────
    📄 Doc métier : DOC/AF_Partie-02_Architecture_Programme_v3.0.md §3
   🧩 Brique réduite (Partie3 §1bis) : pure logique combinatoire, pas de
      StartStop/Enable/Reset/Mode — décode 5 capteurs TOR (Trémie|PV|P2|P1|
      Maintenance) en mot de progression, dérive les 2 limites extrêmes et
      détecte toute combinaison incohérente (défense en profondeur M3).
   🎯 Mot valide : progression monotone de 11111 (extrême Trémie) à 00000
      (extrême Maintenance) : 11111→01111→00111→00011→00001→00000.
      Tout autre mot = incohérence câblage/mécanique (capteur collé/HS).
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Translation_PositionDecoder
VAR_INPUT
    SensorTremie      : BOOL;   // Capteur extrême gauche (Trémie)
    SensorPV          : BOOL;   // Capteur pré-ralentissement avant Trémie (Point de Vitesse)
    SensorP2          : BOOL;   // Capteur zone de travail P2
    SensorP1          : BOOL;   // Capteur zone de travail P1
    SensorMaintenance : BOOL;   // Capteur extrême droite (Maintenance, accès MAINT_N2 uniquement)
END_VAR
VAR_OUTPUT
    LimitSwitchFwd    : BOOL;   // Extrême Trémie confirmé (mot = 11111)
    LimitSwitchRev    : BOOL;   // Extrême Maintenance confirmé (mot = 00000)
    Incoherent        : BOOL;   // Mot hors des 6 combinaisons valides -> défaut sécurité (SafeStop+PowerCutOff, voir FB_Safety_Translation)
    SensorsWord       : BYTE;   // Diagnostic (bit4=Trémie, bit3=PV, bit2=P2, bit1=P1, bit0=Maintenance)

    // 🆕 Exposition des positions individuelles pour consommation par les programmes aval (migration PRG_00_Inputs)
    TranslationPosTremie      : BOOL;   // TRUE = capteur Trémie actif
    TranslationPosPV          : BOOL;   // TRUE = capteur PV actif
    TranslationPosP2          : BOOL;   // TRUE = capteur P2 actif
    TranslationPosP1          : BOOL;   // TRUE = capteur P1 actif
    TranslationPosMaintenance : BOOL;   // TRUE = capteur Maintenance actif
END_VAR

// === IMPLEMENTATION ===

// 🧾 Assemblage du mot (bit4=Trémie ... bit0=Maintenance, ordre doc AF_Partie-02 §3bis)
SensorsWord := 0;
IF SensorTremie      THEN SensorsWord := SensorsWord OR 16#10; END_IF;
IF SensorPV          THEN SensorsWord := SensorsWord OR 16#08; END_IF;
IF SensorP2          THEN SensorsWord := SensorsWord OR 16#04; END_IF;
IF SensorP1          THEN SensorsWord := SensorsWord OR 16#02; END_IF;
IF SensorMaintenance THEN SensorsWord := SensorsWord OR 16#01; END_IF;

// 🎯 Les 6 combinaisons valides (progression monotone décroissante Trémie→Maintenance)
CASE SensorsWord OF
    2#11111, 2#01111, 2#00111, 2#00011, 2#00001, 2#00000:
        Incoherent := FALSE;
    ELSE
        Incoherent := TRUE;
END_CASE;

// 🚧 Limites extrêmes — uniquement sur mot valide (évite un Fdc fantôme déclenché par une incohérence)
LimitSwitchFwd := (NOT Incoherent) AND (SensorsWord = 2#11111);
LimitSwitchRev := (NOT Incoherent) AND (SensorsWord = 2#00000);

// 🆕 Reprise des capteurs de position pour les consommateurs legacy (passthrough, identique à l'entrée filtrée)
TranslationPosTremie      := SensorTremie;
TranslationPosPV          := SensorPV;
TranslationPosP2          := SensorP2;
TranslationPosP1          := SensorP1;
TranslationPosMaintenance := SensorMaintenance;

