(* =======================================================================
   🔌 FB_Encoder_Abs — Acquisition codeur absolu (accès bus EtherCAT)
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Accès bus EtherCAT, extraction positions brutes et séquence de Preset SDO
   🔒 Polarité : EncoderAvailable=TRUE si communication bus et esclave OK
   🔌 Architecture : Module d'acquisition codeur absolu
   📄 Doc métier : DOC/AF/AF_Partie-09_Fonction_Encoder_v2.1.md
   ======================================================================= *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Encoder_Abs) ===

FUNCTION_BLOCK PUBLIC FB_Encoder_Abs
VAR_INPUT
    // === COMMANDES & AUTORISATIONS ===
    Enable              : BOOL;        // --> [CMD] Autorisation generale FB (TRUE=Autorise)
    Reset               : BOOL;        // --> [CMD] Acquittement defaut (front montant)
    PresetRequest       : BOOL;        // --> [CMD] Demande de preset (front montant)

    // === CONTEXTE & ETAT PUISSANCE ===
    PowerContactorEngaged     : BOOL;  // --> [HW]  Ligne puissance enclenchee
    Mode                : E_Mode;      // --> [CMD] Mode d'exploitation actif

    // === BUS ETHERCAT & CAPTEUR HW ===
    RawPosIn            : UDINT;       // --> [HW]  Position brute EtherCAT
    AlarmsIn            : UINT;        // --> [HW]  Codes alarmes bruts EtherCAT
    WarningsIn          : UINT;        // --> [HW]  Codes avertissements bruts EtherCAT
    SlaveOperational    : BOOL;        // --> [HW]  Statut esclave EtherCAT operationnel

    // === PARAMETRES & REGLAGES ===
    PointsPerRev        : UDINT := 8192; // --> [CFG] Resolution codeur (pts/tour)
    PresetValue         : UDINT;       // --> [CFG] Valeur cible de preset
    PresetTimeout       : TIME := T#2s;// --> [CFG] Temporisation max attente preset
    PresetTolerancePts  : UDINT := 10; // --> [CFG] Tolerance relecture post-preset (pts)
END_VAR
VAR_OUTPUT
    // === ETATS IEC & SYNOPTIQUE ===
    Ready               : BOOL;        // <-- [STAT] FB pret a fonctionner
    Busy                : BOOL;        // <-- [STAT] Sequence de preset en cours
    Done                : BOOL;        // <-- [STAT] Preset effectue avec succes
    Error               : BOOL;        // <-- [STAT] Synthese defaut (ErrorId <> 0)
    ErrorId             : WORD;        // <-- [DIAG] Code defaut (bit0: Com, bit1: Preset Timeout)
    State               : E_State;     // <-- [STAT] Etat courant du FB
    StateAtError        : E_State;     // <-- [DIAG] Etat courant lors du dernier defaut

    // === MESURES & DONNEES CODEUR ===
    RawPos              : UDINT;       // <-- [DIAG] Position brute gelee si non disponible
    EncoderAvailable    : BOOL;        // <-- [STAT] Codeur operationnel et disponible
    AngleRaw            : UINT;        // <-- [DIAG] Angle brut sur un tour (MOD PointsPerRev)
    TurnCount           : UDINT;       // <-- [DIAG] Nombre de tours bruts (RawPos / PointsPerRev)

    // === COMMANDES & ECHANGE BUS ETHERCAT ===
    PresetAck           : BOOL;        // <-- [STAT] Pulse confirmation preset reussi
    PresetNak           : BOOL;        // <-- [STAT] Pulse refus / timeout preset
    PresetTriggerCmd    : WORD;        // <-- [ACT]  Ordre declenchement preset vers PDO Rx
    CodeSeqTriggerCmd   : WORD;        // <-- [ACT]  Ordre sequence code vers PDO Rx
    PresetValueOut      : UDINT;       // <-- [ACT]  Valeur de preset transmise au PDO Rx
END_VAR
VAR
    // === DETECTEURS DE FRONT ===
    ResetEdge           : R_TRIG;      // . [LOC] Detecteur front montant Reset
    ErrorEdge           : R_TRIG;      // . [LOC] Detecteur front montant Error
    PresetReqEdge       : R_TRIG;      // . [LOC] Detecteur front montant PresetRequest

    // === TEMPORISATEURS INTERNES ===
    PresetTimer         : TON;         // . [LOC] Temporisateur timeout sequence preset
    PresetTimerVisual   : TON;         // . [LOC] Temporisateur maintien visuel impulsion (500ms)

    // === VARIABLES INTERNES DE CALCUL & ETAT ===
    PresetSeqStep       : INT;         // . [LOC] Etape sequence preset (0:IDLE, 1:PULSE/WAIT)
    RawDiff             : DINT;        // . [LOC] Ecart signe entre RawPos et PresetValueOut
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Abs) ===

{region "§1 Gate"}
// 🛑 1. GATE
IF NOT Enable THEN
    EncoderAvailable := FALSE;
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    PresetTriggerCmd := 16#0000; CodeSeqTriggerCmd := 16#0000; PresetValueOut := 0;
    PresetSeqStep := 0;
    PresetTimer(IN := FALSE, PT := PresetTimeout);
    PresetTimerVisual(IN := FALSE, PT := T#500MS);
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;
{endregion}

{region "§2 Reset front"}
// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);
{endregion}

{region "§3 Diagnostic bus et alarme"}
// 🔍 3. DIAGNOSTIC BUS / ALARME
IF (AlarmsIn <> 0) OR NOT SlaveOperational THEN
    ErrorId := ErrorId OR 16#0001;
ELSE
    ErrorId := ErrorId AND 16#FFFE; (* Auto-clearing dès que le bus et l'esclave sont OK *)
END_IF;
EncoderAvailable := (ErrorId AND 16#0001) = 0;
{endregion}

{region "§4 Lecture position"}
// 📥 4. LECTURE POSITION — GELER SUR DOUTE (Partie10 §6)
// Si EncoderAvailable=FALSE : RawPos/AngleRaw/TurnCount conservent leur dernière valeur (pas de RETURN
// global ici pour ne pas geler aussi la séquence preset/l'état — seule la lecture est gelée).
IF EncoderAvailable THEN
    RawPos := RawPosIn;   // Sens de comptage géré côté codeur (CoE 6000h bit0, startup parameter CODESYS) — voir Partie10 §3bis. Plus de calcul ici.
    AngleRaw := UDINT_TO_UINT(RawPos MOD PointsPerRev);
    TurnCount := RawPos / PointsPerRev;
END_IF;
{endregion}

{region "§5 Séquence preset"}
// 🔧 5. SÉQUENCE PRESET (écriture bus)
// PresetTriggerCmd := 2 déclenche le référencement à PresetValue (valeur de commande, pas un
// masque de bits). CodeSeqTriggerCmd : rôle non identifié — laissé à 0, PAS piloté tant que sa
// fonction n'est pas confirmée. Ne jamais lui donner une valeur arbitraire.
PresetReqEdge(CLK := PresetRequest);
PresetAck := FALSE; PresetNak := FALSE; // pulses 1 cycle uniquement
CodeSeqTriggerCmd := 16#0000;           // non piloté — rôle inconnu, voir note ci-dessus
CASE PresetSeqStep OF
    0: // IDLE
        PresetTriggerCmd := 0;
        IF PresetReqEdge.Q AND EncoderAvailable THEN
            PresetValueOut := PresetValue;
            PresetSeqStep := 1;
            PresetTimer(IN := TRUE, PT := PresetTimeout);
        END_IF;
    1: // Déclenchement preset (laissé actif pendant 0.5s pour confort visuel en simulation/bus)
        PresetTriggerCmd := 2;   // Référence le codeur à PresetValueOut
        RawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(PresetValueOut);
        IF ABS(RawDiff) <= UDINT_TO_DINT(PresetTolerancePts) THEN
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := TRUE, PT := T#500MS);
            IF PresetTimerVisual.Q THEN
                PresetTriggerCmd := 0;
                PresetAck := TRUE;
                PresetSeqStep := 0;
                PresetTimerVisual(IN := FALSE, PT := T#500MS);
            END_IF;
        ELSIF PresetTimer.Q THEN
            PresetTriggerCmd := 0;
            PresetNak := TRUE;
            ErrorId := ErrorId OR 16#0002;
            PresetSeqStep := 0;
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := FALSE, PT := T#500MS);
        END_IF;
END_CASE;
IF ResetEdge.Q AND (PresetSeqStep = 0) THEN
    ErrorId := ErrorId AND 16#FFFD;
END_IF;
{endregion}

{region "§6 Error et StateAtError"}
// 🧾 6. ERROR / STATEATERROR
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

Busy := (PresetSeqStep <> 0);
Done := PresetAck;
{endregion}

(* ═══════════════════════════════════════════════════════════════
   🧪 FB_Sim_Encoder — Simulation physique d'un codeur absolu de treuil
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF/AF_Partie-13_Fonction_Simulation_v2.3.md
   🧩 Brique réduite (Partie3 §1bis, "briques E/S & diagnostics") : pas de contrat
      Enable/Reset/Error complet, pas de StartStop/SafeStop — outil de banc, pas
      du métier machine.
   🎯 Rôle : fait "compter" un codeur absolu comme si le treuil tournait
      réellement, à partir des relais de sens commandés et du palier de vitesse courant.
   📥 Enable      : simulation active (SimulationModeActive AND NOT BusEncoderMxIsReal)
   📥 RelayFwd/RelayRev : sens commandé (contacteurs de sens du treuil)
   📥 StepNumber  : palier vitesse courant (1..5) — ex. instWinchM1.StepNumber
      Vitesse = interpolation linéaire : palier 1 → MinSpeedMps (1 m/s), palier 5 → MaxSpeedMps (2 m/s).
   📥 PresetCmd   : TRUE le cycle où un preset (homing) doit être appliqué (PresettTrigCmd = 2)
   📥 PresetValue : valeur brute à charger lors du preset
   📥 SpeedScaleFactor : facteur fin de confort (réglable à chaud, sans recompiler). Défaut 1.0 = vitesse
      réelle telle que définie par MinSpeedMps/MaxSpeedMps/PointsPerRev/CableM_PerRev/CycleTimeS.
   📤 RawPosOut   : position brute simulée (UDINT), à aiguiller à la place de la valeur
      EtherCAT réelle quand le device n'est pas Operational (voir PRG_02_Encoders.st)
   `RawPos` en `VAR_IN_OUT`, référencé depuis `GVL_PERSISTENT`
      (même pattern que `Calib` dans `FB_Encoder_Homing`) — `PERSISTENT` n'est valide que sur du
      `VAR_GLOBAL` en CODESYS, pas sur une variable locale de FB. Un vrai codeur absolu physique
      conserve son comptage brut même à travers un reset FROID (indépendant de l'automate).
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Sim_Encoder) ===

FUNCTION_BLOCK PUBLIC FB_Sim_Encoder
VAR_INPUT
    Enable           : BOOL;   (* --> [CMD] Active la simulation *)
    RelayFwd         : BOOL;   (* --> [HW] Sens commandé avant *)
    RelayRev         : BOOL;   (* --> [HW] Sens commandé arrière *)
    StepNumber       : INT;    (* --> [CMD] Palier vitesse courant (1..5, 0 = arrêt) *)
    PresetCmd        : BOOL;   (* --> [CMD] Applique un preset (homing) *)
    PresetValue      : UDINT;   (* --> [CFG] Valeur brute à charger au preset *)
    SpeedScaleFactor : REAL := 1.0;   (* --> [CFG] Facteur fin de confort (défaut 1.0) *)
    PresetLatencyCycles : INT := 3;   (* --> [CFG] Nb cycles automate avant application du preset (referencement non instantane) *)
    TestOffsetCmd    : BOOL;          (* --> [TST] Front montant = applique TestOffsetPts (test banc) *)
    TestOffsetPts    : DINT := 0;     (* --> [TST] Décalage signé à appliquer (points bruts) *)
    // 📐 Paramètres physiques du treuil (mêmes valeurs que FB_Encoder_Scale) + vitesse réelle.
    // Vitesse simulée = interpolation linéaire du palier : palier 1 → MinSpeedMps, palier 5 → MaxSpeedMps.
    MinSpeedMps      : REAL := 1.0;    (* --> [CFG] Vitesse palier 1 (m/s) *)
    MaxSpeedMps      : REAL := 2.0;    (* --> [CFG] Vitesse palier 5 (m/s) *)
    PointsPerRev     : UDINT := 8192;  (* --> [CFG] Résolution codeur (pts/tour) *)
    CableM_PerRev    : REAL := 2.0;    (* --> [CFG] Développement câble (m/tour) *)
    CycleTimeS       : REAL := 0.010;  (* --> [CFG] Période tâche PLC (s) — MainTask 10 ms *)
END_VAR
VAR_OUTPUT
    RawPosOut   : UDINT;   (* <-- [DIAG] Position brute simulée *)
END_VAR
VAR_IN_OUT
    RawPos      : UDINT;   (* <-> [BUS] Référence _SimEncoderRawPosM1/M2 (survit au reset froid) *)
END_VAR
VAR
    Increment      : UDINT;              (* . [LOC] Points ajoutés par cycle *)
    EffStep        : INT;               (* . [LOC] Pas borné (>= 1) *)
    SpeedMps       : REAL;              (* . [LOC] Vitesse simulée (m/s) *)
    TestOffsetEdge : R_TRIG;             (* . [LOC] Front TestOffsetCmd *)
    PresetEdge     : R_TRIG;             (* . [LOC] Front montant PresetCmd *)
    PresetPending  : BOOL;               (* . [LOC] Preset en attente d'application (latence) *)
    PresetCount    : INT;                (* . [LOC] Compteur cycles de latence restants *)
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Encoder) ===

{region "§1 Gate"}
IF NOT Enable THEN
    RawPosOut := RawPos;
    RETURN;
END_IF;
{endregion}

{region "§2 Injection test"}
// Injection test banc : VRAI saut de position (comme un glissement réel),
// pour tester Concept 1 / Méca E ET le rattrapage joystick (voir GVL_Simulation bandeau).
TestOffsetEdge(CLK := TestOffsetCmd);
IF TestOffsetEdge.Q THEN
    RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) + TestOffsetPts);
END_IF;
{endregion}

{region "§3 Comptage"}
// 🎚️ Vitesse simulée = interpolation linéaire du palier (palier 1 → MinSpeedMps, palier 5 → MaxSpeedMps),
// pas par pas de (Max−Min)/4. Palier 0 (arrêt) ramène au palier 1 mais aucun mouvement n'est
// appliqué tant que RelayFwd/RelayRev = FALSE (section plus bas).
EffStep  := MAX(StepNumber, 1);
SpeedMps := MinSpeedMps + (INT_TO_REAL(EffStep) - 1.0) * ((MaxSpeedMps - MinSpeedMps) / 4.0);
// Points par cycle = vitesse (m/s) × points par mètre × période tâche (s) × facteur confort.
Increment := REAL_TO_UDINT(SpeedMps * (UDINT_TO_REAL(PointsPerRev) / CableM_PerRev) * CycleTimeS * SpeedScaleFactor);

// Front du preset : lance la latence de referencement (le codeur réel n'est pas
// instantane — il met PresetLatencyCycles cycles a se re-referencer apres le front).
PresetEdge(CLK := PresetCmd);
IF PresetEdge.Q THEN
    PresetPending := TRUE;
    PresetCount := PresetLatencyCycles;
END_IF;

// Pendant l'attente, la position brute est conservee (le codeur n'a pas encore re-reference).
// Le mouvement est gelé pendant la latence, comme un codeur réel en cours de referencement.
IF PresetPending THEN
    IF PresetCount > 0 THEN
        PresetCount := PresetCount - 1;
    ELSE
        // Latence écoulée : applique la valeur cible du preset.
        RawPos := PresetValue;
        PresetPending := FALSE;
    END_IF;
ELSIF RelayFwd THEN
    RawPos := RawPos + Increment;
ELSIF RelayRev THEN
    IF RawPos >= Increment THEN
        RawPos := RawPos - Increment;
    ELSE
        RawPos := 0;
    END_IF;
END_IF;
{endregion}

{region "§4 Sortie"}
RawPosOut := RawPos;
{endregion}

(* ═══════════════════════════════════════════════════════════════
   🛡️ FB_Safety_Translation — Bloc Safety pour le Translation M3 (EtherCAT)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF/AF_Partie-11_Fonction_Translation_v2.2.md
   Rôle : Surveillance joystick, bus EtherCAT, rotation de phases,
      thermique frein commun, Méca A (vitesse non commandée à l'arrêt),
      Méca B (frein/variateur en mouvement à l'arrêt), et Fdc extrêmes.
   🎯 Invariant : les défauts de communication (bits 0/1/2) ne coupent
      jamais la puissance amont (SafeStop seul) ; seuls les défauts
      physiques (bits 3..7) déclenchent PowerCutOff.
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Safety_Translation
VAR_INPUT
    Enable              : BOOL;        // --> [CMD] Active la surveillance
    Reset               : BOOL;        // --> [CMD] Front acquittement défauts
    PowerContactorEngaged     : BOOL;        // --> [SAFE] Chaîne AU réarmée + conditions globales OK
    Mode                : E_Mode;      // --> [CMD] Mode courant
    JoystickOnline      : BOOL;        // --> [HW] instDiagCanOpen.DeviceJoystick.Online
    JoystickOperational : BOOL;        // --> [HW] instDiagCanOpen.DeviceJoystick.Operational
    HeartbeatIhmOk      : BOOL;        // --> [HW] IHM↔PLC : TRUE après front post-boot, FALSE = perte communication opérateur
    PhaseRotationOk     : BOOL;        // --> [HW] PRG_02_Acquisition.HwIn.Machine.PhaseRotationOk_DI (TRUE = OK)
    BrakeThermalFeedback: BOOL;        // --> [HW] Thermique frein commun M1/M2/M3 (NC, TRUE = surchauffe/perte)

    // 🔌 Spécifique EtherCAT & Capteurs réels
    DriveOnline         : BOOL;        // --> [HW] Status diagnostic communication EtherCAT (Online)
    DriveOperational    : BOOL;        // --> [HW] Status diagnostic communication EtherCAT (Operational)
    DriveStatusWord     : WORD;        // --> [HW] Mot d'état variateur AC600
    DriveActualFreqHz   : REAL;        // --> [HW] Vitesse réelle variateur (Hz)
    BrakeFeedback       : BOOL;        // --> [HW] Retour d'état bobine frein (TRUE = ouvert/desserré)
    BrakeCmd            : BOOL;        // --> [HW] Commande frein
    Direction           : INT;         // --> [CMD] Direction commandée
    LimitSwitchFwd      : BOOL;        // --> [HW] Fin de course extrême avant
    LimitSwitchRev      : BOOL;        // --> [HW] Fin de course extrême arrière
    SensorWordIncoherent: BOOL;        // --> [HW] Mot des 5 capteurs position hors combinaisons valides (FB_Translation_PositionDecoder.Incoherent)

    // 🔧 Bypass des surveillances (GVL_IHM.TranslationM3.Bypass)
    BypassGlobal          : BOOL := FALSE;   // --> [TST] Bypass GLOBAL : ignore TOUTES les surveillances ci-dessous (prioritaire)
    BypassOperatorComm    : BOOL := FALSE;   // --> [TST] Bypass perte communication opérateur
    BypassDriveComm       : BOOL := FALSE;   // --> [TST] Bypass perte communication drive
    BypassPhaseRotation   : BOOL := FALSE;   // --> [TST] Bypass défaut rotation phases
    BypassBrakeThermal    : BOOL := FALSE;   // --> [TST] Bypass surchauffe frein
    BypassMecaB           : BOOL := FALSE;   // --> [TST] Bypass Méca B
    BypassMecaA           : BOOL := FALSE;   // --> [TST] Bypass Méca A
    BypassLimitSwitch     : BOOL := FALSE;   // --> [TST] Bypass butées extrêmes
    BypassSensorIncoherent: BOOL := FALSE;   // --> [TST] Bypass incohérence mot capteurs
    BypassSafety          : BOOL := FALSE;   // --> [TST] Bypass groupé PowerCutOff (BrakeThermal/MecaB/MecaA/LimitSwitch/SensorIncoherent)
    BypassProcess         : BOOL := FALSE;   // --> [TST] Bypass groupé SafeStop seul (OperatorComm/DriveComm/PhaseRotation/ContactorFeedback)
END_VAR
VAR_OUTPUT
    Ready               : BOOL;   // <-- [STAT] FB prêt (sortie libre, hors ST_FbStatus)
    // 🧩 Statut transverse (forme cible) — regroupe Busy/Done/Error/ErrorId/State/StateAtError.
    // ErrorId bit0: "Perte communication opérateur" - joystick CAN ou heartbeat IHM absent ; bit1: "Perte communication EtherCAT" - perte com EtherCAT ; bit2: "Défaut Rotation Phases" - rotation phases ; bit3: "Surchauffe Frein Translation" - thermique frein ; bit4: "Absence confirmation arrêt (Méca B)" - Méca B (incohérence arrêt) ; bit5: "Mouvement non commandé (Méca A)" - Méca A (mouvement non commandé) ; bit6: "Limite extrême Translation atteinte" - Fdc extrême atteint ; bit7: "Incohérence mot capteurs position" - combinaison des 5 capteurs Trémie/PV/P2/P1/Maintenance hors table valide
    Status              : ST_FbStatus;
    SafeStop            : BOOL;        // <-- [ACT] Décélération rapide (PLC)
    PowerCutOff         : BOOL;        // <-- [ACT] Coup de poing / coupure puissance amont
    ErrorOperatorComm   : BOOL;        // <-- [DIAG] Perte communication opérateur : joystick CAN ou heartbeat IHM (bit0)
    ErrorDriveComm      : BOOL;        // <-- [DIAG] Perte communication EtherCAT variateur (bit1)
    ErrorPhaseRotation  : BOOL;        // <-- [DIAG] Mauvaise rotation de phases (bit2)
    ErrorBrakeThermal   : BOOL;        // <-- [DIAG] Surchauffe thermique frein commun (bit3)
    ErrorMecaB          : BOOL;        // <-- [DIAG] Absence confirmation arrêt (Méca B - bit4)
    ErrorMecaA          : BOOL;        // <-- [DIAG] Mouvement non commandé (Méca A - bit5)
    ErrorLimitSwitch    : BOOL;        // <-- [DIAG] Limite extrême Translation atteinte (bit6)
    ErrorSensorIncoherent: BOOL;       // <-- [DIAG] Incohérence mot capteurs position (bit7)
END_VAR
VAR
    ResetEdge           : R_TRIG;   // . [LOC] Front Reset
    ErrorEdge           : R_TRIG;   // . [LOC] Front Erreur
    TonMecaB            : TON;         // . [LOC] Sécurité à l'arrêt (Méca B)
    TonMecaA            : TON;         // . [LOC] Sécurité mouvement non commandé (Méca A)
    TonLimitSwitchOverrun : TON;       // . [LOC] Surveillance poussée anormale / escalade fin de course
    OverrunCondition    : BOOL;   // . [LOC] Condition escalade fin de course
    PostRampTimeout     : TIME := T#3S;   // . [LOC] Délai Méca B
    UncommandedActiveB  : BOOL;   // . [LOC] Méca B active
    UncommandedActiveA  : BOOL;   // . [LOC] Méca A active
    FirstScanDone       : BOOL;   // . [LOC] Initialisation premier scan
    TonStartupWarmup    : TON;         // . [LOC] Inhibition 3s au boot + effacement auto coms
END_VAR

// === IMPLEMENTATION ===

{region "§1 Gate neutralisation"}
// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    // 🛡️ Status.ErrorId conservé : la cause du dernier défaut reste visible IHM.
    // Status.Error en miroir de cette cause ; les sorties restent fail-safe (lignes ci-dessous).
    Status.Error := (Status.ErrorId <> 16#0000);
    SafeStop := FALSE;
    PowerCutOff := FALSE;
    ErrorOperatorComm := FALSE;
    ErrorDriveComm := FALSE;
    ErrorPhaseRotation := FALSE;
    ErrorBrakeThermal := FALSE;
    ErrorMecaB := FALSE;
    ErrorMecaA := FALSE;
    ErrorLimitSwitch := FALSE;
    ErrorSensorIncoherent := FALSE;
    TonMecaB(IN := FALSE);
    TonMecaA(IN := FALSE);
    TonLimitSwitchOverrun(IN := FALSE);
    TonStartupWarmup(IN := FALSE);
    Status.State := E_State.DISABLED;
    Status.Busy := FALSE; Status.Done := FALSE; Ready := FALSE;
    RETURN;
END_IF;

{endregion}

{region "§1bis Initialisation et bypass global"}
Ready := TRUE;
ResetEdge(CLK := Reset);

// 🧹 Initialisation au premier scan : purge des résidus RAM d'un Online Change / Warm Start et évitement des alarmes transitoires
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    Status.ErrorId := 16#0000;
    RETURN;
END_IF;

// 🌐 BYPASS GLOBAL : si actif → force Status.ErrorId = 0 et saute toutes les vérifications
// (les bits d'erreur resteraient coincés si on ne les nettoie pas)
IF BypassGlobal THEN
    Status.ErrorId := 16#0000;
    TonMecaB(IN := FALSE);
    TonMecaA(IN := FALSE);
END_IF;

{endregion}

{region "§2 Diagnostics et protections translation"}
// ⚠️ ResetEdge doit être traité même si bypass actif, pour que le reset IHM fonctionne.
// On ne l'exécute que si on n'est PAS en bypass global (sinon ErrorId déjà à 0).
IF NOT BypassGlobal THEN
    // ⏱️ Temporisation 3s de mise en route des bus de terrain au boot (EtherCAT / CANopen / Modbus IHM)
    TonStartupWarmup(IN := Enable, PT := T#3s);

    // 🔍 2. PERTE COMMUNICATION OPÉRATEUR (bit0) — joystick CAN ou heartbeat IHM.
    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassOperatorComm) THEN
        IF (NOT JoystickOnline OR NOT JoystickOperational OR NOT HeartbeatIhmOk) THEN
            Status.ErrorId := Status.ErrorId OR 16#0001;
        ELSE
            Status.ErrorId := Status.ErrorId AND 16#FFFE; (* Effacement auto si la com repasse saine *)
        END_IF;
    ELSIF NOT TonStartupWarmup.Q THEN
        Status.ErrorId := Status.ErrorId AND 16#FFFE; (* Inhibition pendant l'initialisation boot *)
    END_IF;
    IF ResetEdge.Q THEN Status.ErrorId := Status.ErrorId AND 16#FFFE; END_IF;

    // 🔍 2bis. PERTE ETHERCAT VARIATEUR M3 (bit1)
    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassDriveComm) THEN
        IF (NOT DriveOnline OR NOT DriveOperational) THEN
            Status.ErrorId := Status.ErrorId OR 16#0002;
        ELSE
            Status.ErrorId := Status.ErrorId AND 16#FFFD; (* Effacement auto si l'EtherCAT variateur M3 repasse sain *)
        END_IF;
    ELSIF NOT TonStartupWarmup.Q THEN
        Status.ErrorId := Status.ErrorId AND 16#FFFD; (* Inhibition pendant l'initialisation boot *)
    END_IF;
    IF ResetEdge.Q THEN Status.ErrorId := Status.ErrorId AND 16#FFFD; END_IF;

    // 🔍 3. MAUVAISE ROTATION DE PHASE (bit2)
    IF NOT (BypassProcess OR BypassPhaseRotation) THEN
        IF NOT PhaseRotationOk THEN
            Status.ErrorId := Status.ErrorId OR 16#0004;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN Status.ErrorId := Status.ErrorId AND 16#FFFB; END_IF;

    // 🔍 3ter. THERMIQUE FREIN COMMUN M1/M2/M3 (bit3)
    IF NOT (BypassSafety OR BypassBrakeThermal) THEN
        IF BrakeThermalFeedback THEN
            Status.ErrorId := Status.ErrorId OR 16#0008;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN Status.ErrorId := Status.ErrorId AND 16#FFF7; END_IF;

    // 🔍 3quater. INCOHÉRENCE À L'ARRÊT (Méca B — bit4)
    IF NOT (BypassSafety OR BypassMecaB) THEN
        IF NOT HeartbeatIhmOk THEN
            UncommandedActiveB := (ABS(DriveActualFreqHz) > 0.5) OR DriveStatusWord.0 OR BrakeFeedback;
        ELSIF (Direction = 0) AND NOT BrakeCmd THEN
            UncommandedActiveB := DriveStatusWord.0 OR BrakeFeedback;
        ELSE
            UncommandedActiveB := FALSE;
        END_IF;
        TonMecaB(IN := UncommandedActiveB, PT := PostRampTimeout);
        IF TonMecaB.Q THEN Status.ErrorId := Status.ErrorId OR 16#0010; END_IF;
    ELSE
        TonMecaB(IN := FALSE);
    END_IF;
    IF ResetEdge.Q THEN Status.ErrorId := Status.ErrorId AND 16#FFEF; END_IF;

    // 🔍 3quinquies. MOUVEMENT NON COMMANDÉ (Méca A — bit5)
    IF NOT (BypassSafety OR BypassMecaA) THEN
        IF (Direction = 0) AND NOT BrakeCmd THEN
            UncommandedActiveA := ABS(DriveActualFreqHz) > 0.5;
        ELSE
            UncommandedActiveA := FALSE;
        END_IF;
        TonMecaA(IN := UncommandedActiveA, PT := T#1S);
        IF TonMecaA.Q THEN Status.ErrorId := Status.ErrorId OR 16#0020; END_IF;
    ELSE
        TonMecaA(IN := FALSE);
    END_IF;
    IF ResetEdge.Q THEN Status.ErrorId := Status.ErrorId AND 16#FFDF; END_IF;

    // 🔍 3sexies. SURVEILLANCE ESCALADE FIN DE COURSE (bit6)
    IF (BypassSafety OR BypassLimitSwitch) THEN
        // Nettoie le bit 6 résiduel (posé avant activation du bypass)
        Status.ErrorId := Status.ErrorId AND 16#FFBF;
        TonLimitSwitchOverrun(IN := FALSE);
    ELSE
        // 🧱 L'erreur 64 (escalade / poussée anormale en butée) ne s'active QUE SI :
        // 1. On est sur le capteur Trémie (LimitSwitchFwd) ET qu'on continue d'insister en Marche Avant (Direction = 1) avec vitesse/commande variateur active.
        // 2. OU qu'on est sur le capteur Maintenance (LimitSwitchRev) ET qu'on continue d'insister en Marche Arrière (Direction = -1) avec vitesse/commande variateur active.
        OverrunCondition := (LimitSwitchFwd AND (Direction = 1) AND (ABS(DriveActualFreqHz) > 0.5 OR DriveStatusWord.0))
                         OR (LimitSwitchRev AND (Direction = -1) AND (ABS(DriveActualFreqHz) > 0.5 OR DriveStatusWord.0));

        TonLimitSwitchOverrun(IN := OverrunCondition, PT := T#1S500MS);

        IF TonLimitSwitchOverrun.Q THEN
            Status.ErrorId := Status.ErrorId OR 16#0040; // Défaut escalade confirmé (coupure puissance amont)
        ELSE
            // Si la poussée dans le mauvais sens cesse (ou si on repart en arrière), le défaut s'auto-efface
            Status.ErrorId := Status.ErrorId AND 16#FFBF;
        END_IF;
    END_IF;

    // 🔍 3septies. INCOHÉRENCE MOT CAPTEURS POSITION (bit7)
    IF (BypassSafety OR BypassSensorIncoherent) THEN
        // Nettoye le bit 7 résiduel
        Status.ErrorId := Status.ErrorId AND 16#FF7F;
    ELSE
        IF SensorWordIncoherent THEN
            Status.ErrorId := Status.ErrorId OR 16#0080;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN Status.ErrorId := Status.ErrorId AND 16#FF7F; END_IF;

END_IF; // fin IF NOT BypassGlobal

{endregion}

{region "§4 Arbitrage sorties et etat"}
// 📤 4. ARBITRAGE DES SORTIES MAÎTRESSES
Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;

SafeStop := Status.Error OR NOT PowerContactorEngaged;

// PowerCutOff actif si thermique frein (bit3), incohérence arrêt (bit4),
// mouvement non commandé (bit5), dépassement de fin de course (bit6),
// ou incohérence mot capteurs position (bit7)
PowerCutOff := (Status.ErrorId AND 16#00F8) <> 16#0000;

// Décapsulage du bitfield Status.ErrorId pour l'IHM
ErrorOperatorComm   := (Status.ErrorId AND 16#0001) <> 16#0000;
ErrorDriveComm      := (Status.ErrorId AND 16#0002) <> 16#0000;
ErrorPhaseRotation  := (Status.ErrorId AND 16#0004) <> 16#0000;
ErrorBrakeThermal   := (Status.ErrorId AND 16#0008) <> 16#0000;
ErrorMecaB          := (Status.ErrorId AND 16#0010) <> 16#0000;
ErrorMecaA          := (Status.ErrorId AND 16#0020) <> 16#0000;
ErrorLimitSwitch    := (Status.ErrorId AND 16#0040) <> 16#0000;
ErrorSensorIncoherent := (Status.ErrorId AND 16#0080) <> 16#0000;

Status.Busy := FALSE;
Status.Done := FALSE;

// 🚦 5. STATE MACHINE (phase diagnostic)
Status.State := E_State.READY;


{endregion}

