(* =======================================================================
   📏 FB_SyncDeviation — Comparateur d'ecart position M1/M2 (pur)
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Signaler l'ecart de position entre M1 et M2 sur 2 seuils
      (Warn = signaler / Fault = critique). Comparateur PUR : il signale,
      il ne decide pas de ralentir ni d'arreter — le consommateur decide.
   🔌 Interface : Bloc de surveillance transverse (1 instance)
   🧬 Responsabilite : n'interprete PAS l'etat benne. Il reçoit ActiveOffsetM
      deja resolu (calcul offset-selon-etat-benne = FB_Bucket/HoldOffset).
   🔒 Polarite : SyncDeviationWarn/Fault = TRUE si ecart hors seuil.
   📄 Doc : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_SyncDeviation
VAR_INPUT
    // === COMMANDES ET CONSIGNES ===
    Enable                          : BOOL;                           // --> [CMD] Validation surveillance globale
    Reset                           : BOOL;                           // --> [CMD] Acquittement defaut sur front
    SyncEnable                      : BOOL;                           // --> [CMD] Autorisation utilisateur synchro

    // === MESURES ET ETATS CODEURS ===
    CablePosM1                      : REAL;                           // --> [HW] Position cable treuil M1 (m)
    CablePosM2                      : REAL;                           // --> [HW] Position cable treuil M2 (m)
    HomedAndReliableM1              : BOOL;                           // --> [STAT] Gate fiable M1 (FB_EncoderReliability)
    HomedAndReliableM2              : BOOL;                           // --> [STAT] Gate fiable M2 (FB_EncoderReliability)

    // === REGLAGES ET CONFIGURATION ===
    CfgSyncToleranceM               : REAL := 0.10;                   // --> [CFG] Seuil 1 (Warn) — ecart max avant alerte (m)
    CfgSyncCriticalToleranceM       : REAL := 0.50;                   // --> [CFG] Seuil 2 (Fault) — ecart critique (m)
    ActiveOffsetM                   : REAL := 0.0;                    // --> [CFG] Offset cible RESOLU (ex: benne)

    // === BYPASSES ET SIMULATION ===
    BypassGlobal                    : BOOL := FALSE;                  // --> [TST] Neutralise la surveillance ecart
END_VAR
VAR_OUTPUT
    // === MESURES ET DIAGNOSTICS DE SYNCHRO ===
    DeltaPosM                       : REAL;                           // <-- [DIAG] Ecart absolu position |M1 - M2| (m)
    SignedDeltaPosM                 : REAL;                           // <-- [DIAG] Ecart signe position (M1 - M2) (m)
    SyncDeviationWarn               : BOOL;                           // <-- [DIAG] Seuil 1 depasse : signaler / forcer palier 1
    SyncDeviationFault              : BOOL;                           // <-- [SAFE] Seuil 2 depasse : ecart critique (block signal)
END_VAR
VAR
    // === DETECTEURS ET TIMERS INTERNES ===
    ResetEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Reset
    DeviationFaultTimer            : TON;                            // . [LOC] Tempo filtrage transitoire ecart (seuil 2)

    // === VARIABLES LOCALES INTERNES ===
    WarnActive                      : BOOL;                           // . [LOC] Ecart hors seuil 1 actif
    FaultActive                     : BOOL;                           // . [LOC] Ecart hors seuil 2 actif
    WarnLatched                     : BOOL;                           // . [LOC] Latch ecart seuil 1 (degrada palier 1 stable)
END_VAR

{region "§1 Gate neutralisation"}
// 🛑 1. GATE
IF NOT Enable THEN
    DeltaPosM := 0.0; SignedDeltaPosM := 0.0;
    SyncDeviationWarn := FALSE; SyncDeviationFault := FALSE;
    WarnLatched := FALSE;
    RETURN;
END_IF;
ResetEdge(CLK := Reset);
{endregion}

{region "§2 Calcul ecart"}
// 📏 2. ÉCART M1/M2 — calculé en continu si les 2 treuils sont fiables (HomedAndReliable)
IF HomedAndReliableM1 AND HomedAndReliableM2 THEN
    SignedDeltaPosM := CablePosM1 - CablePosM2 + ActiveOffsetM;
    DeltaPosM := ABS(SignedDeltaPosM);
ELSE
    SignedDeltaPosM := 0.0;
    DeltaPosM := 0.0;
END_IF;
{endregion}

{region "§3 Surveillance ecart 2 seuils"}
// 🔍 3. SURVEILLANCE ECART — 2 seuils (Warn/Fault).
// Warn (seuil 1) = INSTANTANE + LATCH : degrade le palier 1 des que l'ecart depasse,
// sans retard temporel ni oscillation (fidele a l'ancien SyncDegradedStep1).
// Fault (seuil 2) = filtre temporel pour le transitoire mecanique d'arret.
IF NOT BypassGlobal THEN
    WarnActive  := SyncEnable AND HomedAndReliableM1 AND HomedAndReliableM2 AND (DeltaPosM > CfgSyncToleranceM);
    FaultActive := SyncEnable AND HomedAndReliableM1 AND HomedAndReliableM2 AND (DeltaPosM > CfgSyncCriticalToleranceM);

    // Latch Warn : reste actif tant que la cause persiste OU que Reset n'a pas ete demande
    IF WarnActive THEN
        WarnLatched := TRUE;
    ELSIF ResetEdge.Q AND NOT WarnActive THEN
        WarnLatched := FALSE;
    END_IF;
    SyncDeviationWarn := WarnActive OR WarnLatched;

    DeviationFaultTimer(IN := FaultActive, PT := T#800ms);
    SyncDeviationFault := DeviationFaultTimer.Q;
ELSE
    SyncDeviationWarn := FALSE;
    SyncDeviationFault := FALSE;
    WarnLatched := FALSE;
END_IF;
{endregion}

// 🧪 Gravité d'un événement du banc de test
TYPE E_TestEventSeverity :
(
    TEST_EVENT_INFO    := 0,
    TEST_EVENT_WARNING := 1,
    TEST_EVENT_ERROR   := 2
);
END_TYPE

(* ═══════════════════════════════════════════════════════════════
   🧪 PRG_AU_TestBench — Programme principal de test chaîne AU
   ───────────────────────────────────────────────────────────────
   📄 Ordonnance les étages Acquisition → Outputs dans l'ordre
      correct (même flux que MainTask réelle).
   🎮 Pilotage via Watch CODESYS :
      GVL_IHM_AU.Cmd.BtnEmergencyArming  = TRUE  → lance réarmement
      GVL_IHM_AU.Cmd.BtnFaultReset       = TRUE  → acquitte défauts
      GVL_IHM_AU.Cmd.BtnEmergencyCutOff  = TRUE  → coupure IHM
      GVL_Simulation_AU.SimContactorEngaged = TRUE → simule retour contacteur
      GVL_Simulation_AU.SimPowerCutOffReq   = TRUE → simule coupure métier
   👁️ Observation :
      PRG_AU_Outputs_LD.ArmingSeqStep    → étape séquence (0..6)
      PRG_AU_Outputs_LD.PowerKeepAlive_A_RQ → état maintien A
      PRG_AU_Outputs_LD.EmergencyArming_RQ  → pulse réarmement
      PRG_AU_Outputs_LD.ErrorId          → erreurs/locks
   ═══════════════════════════════════════════════════════════════
    📄 Docs : DOC/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md
              DOC/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md
*)

PROGRAM PRG_AU_TestBench
VAR_OUTPUT
    // 🩺 Synthèse lisible pour Watch
    StepLabel           : STRING;
    MaintainA           : BOOL;
    MaintainB           : BOOL;
    ArmPulse            : BOOL;
    Step                : INT;
    ErrorId             : WORD;
    RedundancyFailed    : BOOL;
    ArmFailed           : BOOL;
    Lockout             : BOOL;
    ChainOk             : BOOL;
    ContactorOk         : BOOL;
    Armable             : BOOL;
END_VAR

// === IMPLEMENTATION ===

// 🔄 1. Acquisition des entrées (simulées)
PRG_AU_Acquisition();

// 📤 2. Traitement et sorties (composite + Q)
PRG_AU_Outputs_LD();

// 🩺 Synthèse Watch — lecture des sorties scalaires (pattern PRG_10_Outputs_LD)
MaintainA        := PRG_AU_Outputs_LD.PowerKeepAlive_A_RQ;
MaintainB        := PRG_AU_Outputs_LD.PowerKeepAlive_B_RQ;
ArmPulse         := PRG_AU_Outputs_LD.EmergencyArming_RQ;
Step             := PRG_AU_Outputs_LD.ArmingSeqStep;
ErrorId          := PRG_AU_Outputs_LD.ErrorId;
RedundancyFailed := PRG_AU_Outputs_LD.RedundancyTestFailed;
ArmFailed        := PRG_AU_Outputs_LD.EmergencyArmingFailed;
Lockout          := PRG_AU_Outputs_LD.EmergencyArmingLockoutActive;
ChainOk          := PRG_AU_Outputs_LD.ChainOk;
ContactorOk      := PRG_AU_Outputs_LD.ContactorOk;
Armable          := PRG_AU_Outputs_LD.Armable;

// 📤 Publication IHM — l'opérateur voit ces retours sur son écran
// [IHM] Publication dans la structure d'etat IHM (lue par la visu operateur)
GVL_IHM_AU.State.ChainOk              := ChainOk;
GVL_IHM_AU.State.ContactorOk          := ContactorOk;
GVL_IHM_AU.State.Armable              := Armable;
GVL_IHM_AU.State.ArmingBusy           := PRG_AU_Outputs_LD.ArmingBusy;
GVL_IHM_AU.State.RedundancyTestFailed := RedundancyFailed;
GVL_IHM_AU.State.ArmingFailed         := ArmFailed;
GVL_IHM_AU.State.LockoutActive        := Lockout;
GVL_IHM_AU.State.Step                 := Step;
GVL_IHM_AU.State.Error                := PRG_AU_Outputs_LD.Error;
GVL_IHM_AU.State.ErrorId              := ErrorId;
GVL_IHM_AU.State.PowerCutOffActive    := GVL_Simulation_AU.SimPowerCutOffReq;

CASE Step OF
    0: StepLabel := 'IDLE (attente armement)';
    1: StepLabel := 'TestA (coupe A)';
    2: StepLabel := 'RestoreA (rétablit A)';
    3: StepLabel := 'TestB (coupe B)';
    4: StepLabel := 'RestoreB (rétablit B)';
    5: StepLabel := 'Pulse (armement 1s)';
    6: StepLabel := 'Confirm (attente contacteur)';
ELSE
    StepLabel := 'ERREUR';
END_CASE;

(* ═══════════════════════════════════════════════════════════════
   ⚙️ ST_BucketHMI — Données d'échange IHM pour la benne (M2)
   ───────────────────────────────────────────────────────────────
   📄 Structuration en Cmd / State / Cfg / Bypass (2026-07-23), homogène avec ST_WinchHMI.
   ═══════════════════════════════════════════════════════════════ *)
TYPE ST_BucketHMI :
STRUCT
    Cmd    : ST_BucketCmd;
    State  : ST_BucketHMIState;
    Cfg    : ST_BucketCfg;
    Bypass : ST_BypassBucket;
END_STRUCT
END_TYPE

SETUP
VAR
    fb : FB_SAFETY_EMERGENCYMANAGEMENT;
END_VAR
END_SETUP

(* TC-P01-002 est classee SITE+AUTO dans l AF (mixte). Ce test ne couvre QUE la partie AUTO
   (commande logicielle) : preuve qu un seul canal est coupe a la fois et que le FB interprete
   correctement le retour de boucle fourni en entree. Il ne peut PAS prouver que la coupure
   physique de MaintainA/B_RQ ouvre reellement la boucle materielle -- ca reste une verification
   SITE, sur l automate reel, jamais automatisable en logiciel. *)
TEST 'TC-P01-002 (partie AUTO) chaque canal est commande independamment, l autre reste maintenu'
    (* demarrage + regime etabli, sain *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'hors defaut, canal A maintenu');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'hors defaut, canal B maintenu');

    (* front ArmRequest -> TestA (step 1) : SEUL le canal A doit se couper *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'front doit lancer TestA');
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'TestA : canal A seul doit se couper');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'TestA : canal B ne doit PAS etre affecte');

    (* 200ms plus tard : la boucle reagit reellement a la coupure de A (preuve physique reelle) *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := FALSE, POWERCONTACTORENGAGED := FALSE);
