VAR
    fb : FB_CYCLETIME;
END_VAR
END_SETUP

TEST 'probe'
    fb(DEFAULTVALUES := 0.004);
    ADVANCE_TIME(10000000);
    fb(DEFAULTVALUES := 0.004);
    ASSERT_TRUE(TRUE, 'probe only');
END_TEST

(* =======================================================================
   🛡️ FB_Encoder_Safety — Bornage physique & surveillance cohérence
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Bornage physique absolu [-99; +99]m et relais d'incohérence redémarrage
   🔒 Polarité : EncoderIncoherent=TRUE en cas de hors bornes ou HomingSuspect
   🛡️ Sécurité : Verrouillage de la position câble sûre
   📄 Doc métier : DOC/AF/AF_Partie-09_Fonction_Encoder_v2.1.md
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_Encoder_Safety
VAR_INPUT
    // === COMMANDES & AUTORISATIONS ===
    Enable                : BOOL;        // --> [CMD] Autorisation generale FB (TRUE=Autorise)
    Reset                 : BOOL;        // --> [CMD] Acquittement defaut (front montant)

    // === MESURES & ALERTE HOMING ===
    CablePosM             : REAL;        // --> [HW]  Position calculee (m, sortie FB_Encoder_Scale)
    HomingSuspect         : BOOL;        // --> [SAFE] Alerte incoherence redemarrage (FB_Encoder_Homing)

    // === REGLAGES & BORNES PHYSIQUES ===
    PositionMinM          : REAL := -99.0; // --> [CFG] Plafond bornage physique bas (m)
    PositionMaxM          : REAL := 99.0;  // --> [CFG] Plafond bornage physique haut (m)

    // === TESTS & BYPASS ===
    BypassGlobal          : BOOL := FALSE; // --> [TST] Neutralisation defaut de bornage pour mise en service
END_VAR
VAR_OUTPUT
    // === ETATS IEC & SYNOPTIQUE ===
    Ready                 : BOOL;        // <-- [STAT] FB pret a fonctionner
    // 🧩 Statut transverse (forme cible) — regroupe Busy/Done/Error/ErrorId/State/StateAtError.
    // ErrorId bit0: "Bornes", bit1: "Boot suspect".
    Status                : ST_FbStatus;

    // === MESURES SURE & SECURITE ===
    CablePosMSafe         : REAL;        // <-- [DIAG] Position cable instantanee transmise (m)
    EncoderIncoherent     : BOOL;        // <-- [SAFE] Incoherence ou hors bornes (TRUE = defaut)
END_VAR
VAR
    // === DETECTEURS DE FRONT ===
    ResetEdge             : R_TRIG;      // . [LOC] Detecteur front montant Reset
    ErrorEdge             : R_TRIG;      // . [LOC] Detecteur front montant Error
END_VAR

{region "§1 Gate"}
// 🛑 1. GATE
IF NOT Enable THEN
    Ready := FALSE; Status.Busy := FALSE; Status.Done := FALSE;
    Status.State := E_State.DISABLED;
    CablePosMSafe := CablePosM;
    EncoderIncoherent := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
Status.State := E_State.READY;
{endregion}

{region "§2 Reset front"}
// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);
{endregion}

{region "§3 Bypass global"}
// 🌐 3. BYPASS GLOBAL
IF BypassGlobal THEN
    Status.ErrorId := 16#0000;
END_IF;
{endregion}

{region "§4 Surveillance bornage"}
// 🔍 4. SURVEILLANCE BORNAGE PHYSIQUE ABSOLU (bit0)
IF NOT BypassGlobal AND ((CablePosM < PositionMinM) OR (CablePosM > PositionMaxM)) THEN
    Status.ErrorId := Status.ErrorId OR 16#0001;
ELSE
    Status.ErrorId := Status.ErrorId AND 16#FFFE; (* Auto-clearing dès retour dans la plage *)
END_IF;
{endregion}

{region "§5 Relais incohérence redémarrage"}
// 🔍 5. RELAIS INCOHÉRENCE REDÉMARRAGE (bit1)
IF NOT BypassGlobal THEN
    IF HomingSuspect THEN
        Status.ErrorId := Status.ErrorId OR 16#0002;
    ELSE
        Status.ErrorId := Status.ErrorId AND 16#FFFD;
    END_IF;
END_IF;
{endregion}

{region "§6 Transmission mesure"}
// 📏 6. TRANSMISSION DE LA MESURE (Toujours réelle, non figée)
CablePosMSafe := CablePosM;
{endregion}

{region "§7 Sorties état et sécurité"}
// 📤 7. SORTIES ÉTAT & SÉCURITÉ
Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;

EncoderIncoherent := Status.Error;
Status.Busy := FALSE;
Status.Done := FALSE;
{endregion}

(* ═══════════════════════════════════════════════════════════════
   🛡️ FB_Safety_EmergencyManagementLogic — Décision & Séquencement
   ───────────────────────────────────────────────────────────────
   📄 Rôle : Gère la machine d'état d'auto-test et de réarmement de
      la boucle d'arrêt d'urgence. Produit les consignes logiques.
   ═══════════════════════════════════════════════════════════════
    📄 Docs : DOC/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md ; DOC/AF_Partie-03_Contrats_Composants_v2.0.md
*)

FUNCTION_BLOCK PUBLIC FB_Safety_EmergencyManagementLogic
VAR_INPUT
    Enable              : BOOL;        // Active la surveillance
    Reset               : BOOL;        // Front acquittement défauts
    ArmRequest          : BOOL;        // Demande de réarmement (BtnEmergencyArming)
    EmergencyChainClosed      : BOOL;        // Retour physique boucle d'urgence amont contacteur
    PowerContactorEngaged     : BOOL;        // Confirmation contacteur de puissance principal
    PowerCutOffRequest  : BOOL;        // Requête de coupure logique issue des métiers
    BtnEmergencyCutOff  : BOOL;        // Commande d'ouverture d'urgence depuis l'IHM
END_VAR
VAR_OUTPUT
    Error               : BOOL;
    ErrorId             : WORD;        // bit0: RedundancyTestFailed, bit1: EmergencyArmingFailed
    Cmd                 : ST_Safety_Emergency_InternalCmd; // Structure de commande logique produite
    
    ArmingSeqStep       : INT;         // Étape de diagnostic : 0=IDLE, 1=TestA, 2=RestoreA, 3=TestB, 4=RestoreB, 5=Pulse, 6=Confirm
    RedundancyTestFailed: BOOL;        // Canal A ou B resté collé/shunté détecté à l'auto-test
    EmergencyArmingFailed: BOOL;       // Contacteur de puissance n'a pas confirmé l'armement
    EmergencyArmingLockoutActive : BOOL; // Verrouillage temporel de 5s entre les essais
END_VAR
VAR
    ResetEdge           : R_TRIG;
    ArmReqEdge          : R_TRIG;
    ForceTestA          : BOOL;
    ForceTestB          : BOOL;
    TonTestA            : TON;
    TonRestoreA         : TON;
    TonTestB            : TON;
    TonRestoreB         : TON;
    TonArmingPulse      : TON;
    TonArmingConfirm    : TON;
    TonArmingLockout    : TON;
END_VAR

// === IMPLEMENTATION ===

// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    Error := FALSE;
    ErrorId := 16#0000;
    Cmd.PowerCutOff_A_Cmd := FALSE;
    Cmd.PowerCutOff_B_Cmd := FALSE;
    Cmd.EmergencyArming_Cmd := FALSE;
    ArmingSeqStep := 0;
    RedundancyTestFailed := FALSE;
    EmergencyArmingFailed := FALSE;
    EmergencyArmingLockoutActive := FALSE;
    ForceTestA := FALSE;
    ForceTestB := FALSE;
    TonTestA(IN := FALSE);
    TonRestoreA(IN := FALSE);
    TonTestB(IN := FALSE);
    TonRestoreB(IN := FALSE);
    TonArmingPulse(IN := FALSE);
    TonArmingConfirm(IN := FALSE);
    TonArmingLockout(IN := FALSE);
    RETURN;
END_IF;

ResetEdge(CLK := Reset);
ArmReqEdge(CLK := ArmRequest);

// 🔍 2. ACQUITTEMENT DES DÉFAUTS
IF ResetEdge.Q THEN
    RedundancyTestFailed := FALSE;
    IF PowerContactorEngaged THEN
        EmergencyArmingFailed := FALSE;
    END_IF;
END_IF;

// 🚦 3. DÉCLENCHEMENT DE LA SÉQUENCE DE SÉCURITÉ
IF ArmReqEdge.Q AND (ArmingSeqStep = 0) AND EmergencyChainClosed 
   AND NOT EmergencyArmingLockoutActive 
   AND NOT PowerContactorEngaged THEN
    ArmingSeqStep := 1;
END_IF;

// ⏱️ Étape 1 : Coupe canal A seul, vérifie que la boucle tombe
TonTestA(IN := (ArmingSeqStep = 1), PT := T#200ms);
IF ArmingSeqStep = 1 THEN
    ForceTestA := TRUE;
    IF TonTestA.Q THEN
        ForceTestA := FALSE;
        IF EmergencyChainClosed THEN
            RedundancyTestFailed := TRUE;
            ArmingSeqStep := 0;
        ELSE
            ArmingSeqStep := 2;
        END_IF;
    END_IF;
ELSE
    ForceTestA := FALSE;
END_IF;

// ⏱️ Étape 2 : Restaure A, attend le retour sain de la boucle amont
TonRestoreA(IN := (ArmingSeqStep = 2), PT := T#200ms);
IF (ArmingSeqStep = 2) AND TonRestoreA.Q THEN
    IF EmergencyChainClosed THEN
        ArmingSeqStep := 3;
    ELSE
        ArmingSeqStep := 0;
    END_IF;
END_IF;

// ⏱️ Étape 3 : Coupe canal B seul, vérifie que la boucle tombe
TonTestB(IN := (ArmingSeqStep = 3), PT := T#200ms);
IF ArmingSeqStep = 3 THEN
    ForceTestB := TRUE;
    IF TonTestB.Q THEN
        ForceTestB := FALSE;
        IF EmergencyChainClosed THEN
            RedundancyTestFailed := TRUE;
            ArmingSeqStep := 0;
        ELSE
            ArmingSeqStep := 4;
        END_IF;
    END_IF;
ELSE
    ForceTestB := FALSE;
END_IF;

// ⏱️ Étape 4 : Restaure B, attend le retour sain de la boucle amont
TonRestoreB(IN := (ArmingSeqStep = 4), PT := T#200ms);
IF (ArmingSeqStep = 4) AND TonRestoreB.Q THEN
    IF EmergencyChainClosed THEN
        ArmingSeqStep := 5;
    ELSE
        ArmingSeqStep := 0;
    END_IF;
END_IF;

// ⏱️ Étape 5 : Les 2 canaux validés -> impulsion réarmement physique (1s)
TonArmingPulse(IN := (ArmingSeqStep = 5), PT := T#1s);
Cmd.EmergencyArming_Cmd := (ArmingSeqStep = 5);
IF (ArmingSeqStep = 5) AND TonArmingPulse.Q THEN
    ArmingSeqStep := 6;
END_IF;

// ⏱️ Étape 6 : Attente confirmation contacteur principal (2s max)
TonArmingConfirm(IN := (ArmingSeqStep = 6), PT := T#2s);
IF ArmingSeqStep = 6 THEN
    IF PowerContactorEngaged THEN
        ArmingSeqStep := 0;
        EmergencyArmingLockoutActive := FALSE;
    ELSIF TonArmingConfirm.Q THEN
        EmergencyArmingFailed := TRUE;
        ArmingSeqStep := 0;
        EmergencyArmingLockoutActive := TRUE;
    END_IF;
END_IF;

// ⏱️ Séquence de verrouillage temporel (5s)
TonArmingLockout(IN := EmergencyArmingLockoutActive, PT := T#5s);
IF TonArmingLockout.Q THEN
    EmergencyArmingLockoutActive := FALSE;
END_IF;

// 📤 4. GÉNÉRATION DES CONSIGNES LOGIQUES
Cmd.PowerCutOff_A_Cmd := NOT PowerCutOffRequest AND NOT ForceTestA AND NOT BtnEmergencyCutOff AND NOT RedundancyTestFailed;
Cmd.PowerCutOff_B_Cmd := NOT PowerCutOffRequest AND NOT ForceTestB AND NOT BtnEmergencyCutOff AND NOT RedundancyTestFailed;

// 📤 5. SYNTHÈSE DES ERREURS
ErrorId := 16#0000;
IF RedundancyTestFailed THEN
    ErrorId := ErrorId OR 16#0001;
END_IF;
IF EmergencyArmingFailed THEN
    ErrorId := ErrorId OR 16#0002;
END_IF;

Error := (ErrorId <> 16#0000);

(* ═══════════════════════════════════════════════════════════════
   🕵️♂️ FB_TroubleshootingView — Mise en forme lecture seule pour dépannage
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF/AF_Partie-14_Fonction_Troubleshooting/FB_TroubleshootingView_v1.2.md
   🔗 Producteur unique de GVL_Troubleshooting.* — instancié UNE SEULE FOIS,
      dans PRG_07_Supervision, après §3 Projections IHM.
   🔒 Lecture seule stricte : aucune VAR_OUTPUT de commande, aucun calcul métier,
      aucune fusion de source — pure recopie de faits déjà publiés ailleurs.
   ⚠️ WinchM2 est typé ST_WinchBenneHMI (pas ST_WinchHMI comme WinchM1) : ce lot
      (LOT_TROUBLESHOOTING_VIEW_ET_WINCHHMI) a introduit ST_WinchBenneHMI pour porter
      Bucket côté M2 uniquement (GVL_IHM.M2TreuilBenne) — adaptation du port fiche §3
      nécessaire suite à AC5 (Bucket retiré de ST_WinchHMI commun M1/M2).
   Écriture GVL directe : seule exception au principe "pas de GVL comme bus de
      commande" (AF_Partie-03 §5) — GVL_Troubleshooting n'est jamais relue par un FB
      métier, uniquement par Watch CODESYS / export SCADA dépannage (fiche §3/§7).
   ⚠️ Idx201_JoystickSelected (ContexteMachineGlobal) lit GVL_IHM.Modes.Cmd.TglJoystickMaster
      directement (variable globale IEC 61131-3, visible sans passage par VAR_INPUT) — ce
      port n'est pas dans la table fiche §3 mais le producteur exact est documenté fiche §5.1.
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK PUBLIC FB_TroubleshootingView
VAR_INPUT
    Enable                   : BOOL; (* --> [CMD] TRUE en permanence — fiche §3, aucune condition de scan *)

    (* 📡 PRG_02_Acquisition *)
    HwIn                     : ST_HardwareImage;   (* --> [HW] Image entrées qualifiées *)
    HwReal                   : ST_HardwareImage;   (* --> [HW] Image entrées réelles *)
    InputModuleFault         : BOOL;   (* --> [HW] Défaut module d'entrée *)
    LocalDigitalIoOk         : BOOL; (* --> [HW] Mirroir Network.InputModules — pas de champ ST_Chain* dédié ce lot *)
    Vh0800EndOk              : BOOL; (* --> [HW] idem *)
    Vh0808EtpOk              : BOOL; (* --> [HW] idem *)

    (* 🎚️ PRG_03_Modes_Cycle *)
    Auth                     : ST_Modes_Autorisations;   (* --> [SAFE] Autorisations machine *)

    (* 🛗 PRG_04_Treuils_Benne — demandes publiques déjà arbitrées *)
    M1LogicRequestSpeedRef_Pct : REAL;   (* --> [CMD] Consigne vitesse M1 *)
    M1LogicRequestDirection    : INT;   (* --> [CMD] Sens M1 *)
    M2LogicRequestSpeedRef_Pct : REAL;   (* --> [CMD] Consigne vitesse M2 *)
    M2LogicRequestDirection    : INT;   (* --> [CMD] Sens M2 *)
    CoupledUserRequestDirection : INT;   (* --> [CMD] Direction couplée *)
    CoupledUserRequestActive    : BOOL;   (* --> [CMD] Demande couplée active *)
    CycleAutoBusy                : BOOL;   (* --> [HW] Cycle auto actif *)
    CycleM1SpeedRef_Pct          : REAL;   (* --> [CMD] Consigne cycle M1 *)
    CycleM2SpeedRef_Pct          : REAL;   (* --> [CMD] Consigne cycle M2 *)
    CycleBucketOpen              : BOOL;   (* --> [HW] Benne ouverte cycle *)
    CycleTargetPosition          : INT;   (* --> [CMD] Cible cycle *)

    (* 🎭 GVL_Simulation *)
    SimulationModeActive     : BOOL;   (* --> [TST] Mode simulation *)
    SimWinchActive           : BOOL;   (* --> [TST] Sim treuils *)
    SimTranslationActive     : BOOL;   (* --> [TST] Sim translation *)
    SimOperatorActive        : BOOL;   (* --> [TST] Sim opérateur *)
    SimSafetyActive          : BOOL;   (* --> [TST] Sim sécurité *)

    (* 🛗 GVL_IHM — images publiques déjà produites *)
    WinchM1                  : ST_WinchHMI;      (* --> [HW] GVL_IHM.M1TreuilRetenue *)
    WinchM2                  : ST_WinchBenneHMI; (* --> [HW] GVL_IHM.M2TreuilBenne — porte Bucket *)
    Sync                     : ST_SyncHMI;       (* --> [HW] GVL_IHM.M1M2Sync *)
    Translation              : ST_TranslationHMI;(* --> [HW] GVL_IHM.TranslationM3 *)
    Commun                   : ST_CommunHMI;     (* --> [HW] GVL_IHM.Commun *)
    Network                  : ST_NetworkDiagHMI;(* --> [HW] GVL_IHM.Network *)
    DredgingAssist           : ST_DredgingAssistHMI; (* --> [HW] GVL_IHM.DredgingAssist *)
    JoystickHMI              : ST_JoystickHMI;   (* --> [HW] GVL_IHM.JOY1Joystick *)

    (* 🛡️ Sorties publiques AU produites par PRG_06_Outputs_LD *)
    EmergencyState           : ST_Safety_Emergency_State;   (* --> [SAFE] État AU *)
    EmergencyDiag            : ST_Safety_Emergency_Diag;   (* --> [SAFE] Diagnostic AU *)
    PowerCutOffActive        : BOOL;   (* --> [SAFE] Coupure puissance *)
    ArmingPulseActive        : BOOL;   (* --> [SAFE] Impulsion réarmement *)
    MaintainAActive          : BOOL;   (* --> [SAFE] Maintien canal A *)
    MaintainBActive          : BOOL;   (* --> [SAFE] Maintien canal B *)

    (* 🔄 Séquenceur de cycle semi-automatique *)
    CycleReady               : BOOL;   (* --> [STAT] Séquenceur prêt *)
    CycleDone                : BOOL;   (* --> [STAT] Séquenceur terminé *)
    CycleError               : BOOL;   (* --> [STAT] Séquenceur en erreur *)
    CycleErrorId             : WORD;   (* --> [DIAG] Code erreur séquenceur *)
    CycleStep                : E_CycleStep; (* --> [STAT] Étape courante *)
    CycleStepStr             : STRING(40);  (* --> [STAT] Libellé étape *)
