(* ═══════════════════════════════════════════════════════════════
   🧪 FB_SimBench — Enveloppe unique de simulation pour banc d'essai
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-13_Fonction_Simulation_v2.0.md
   📄 Lot L6 (Rebranchement du banc de simulation derrière HwIn)
   
   🎯 Rôle : Compose les 4 blocs de modèle de simulation existants :
      - FB_Sim_Encoder (instM1, instM2)
      - FB_Sim_Translation (instTranslation)
      - FB_Sim_Joystick (instJoystick)
      - FB_Sim_Safety (instSafety)
   
   🔒 Brique réduite : 0 lecture de variable globale en interne.
      Toutes les entrées (commandes, stimuli, HwReal) sont passées en paramètres.
   
   🔴 RÈGLES SÉCURITÉ ET POLARITÉ :
      - Modèle frein M1/M2/M3 : M1_BrakeIsOpen_DI := M1_BrakeCmd (1 = OUVERT).
        Ne JAMAIS faire NOT BrakeCmd ! (P1 Lot L6).
      - Retours contacteurs M1/M2 : 1 = tous retombés (TRUE quand RelayFwd=0 et RelayRev=0).
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_SimBench
VAR_INPUT
    Enable                     : BOOL;             // Activation globale (GVL_Simulation.SimulationModeActive)

    // ── Commandes issues de l'automate (Scan N-1 / PRG_07 / PRG_10) ──────────
    M1_RelayFwd                : BOOL;
    M1_RelayRev                : BOOL;
    // 🔧 REX 2026-07-27 : les 4 contacteurs de palier participent au retour unique
    // « tous contacteurs retombés » — sans eux, le modèle annonce l'arrêt alors qu'un
    // palier est encore engagé (fausse condition d'armement Méca A).
    M1_SpeedContactor_1        : BOOL;
    M1_SpeedContactor_2        : BOOL;
    M1_SpeedContactor_3        : BOOL;
    M1_SpeedContactor_4        : BOOL;
    M1_SpeedRefPct             : REAL;
    M1_PresetTriggerCmd        : WORD;
    M1_PresetValueOut          : UDINT;
    M1_BrakeCmd                : BOOL;             // TRUE = commande desserrage frein M1

    M2_RelayFwd                : BOOL;
    M2_RelayRev                : BOOL;
    M2_SpeedContactor_1        : BOOL;   // 🔧 REX 2026-07-27 : idem M1, voir ci-dessus
    M2_SpeedContactor_2        : BOOL;
    M2_SpeedContactor_3        : BOOL;
    M2_SpeedContactor_4        : BOOL;
    M2_SpeedRefPct             : REAL;
    M2_PresetTriggerCmd        : WORD;
    M2_PresetValueOut          : UDINT;
    M2_BrakeCmd                : BOOL;             // TRUE = commande desserrage frein M2

    M3_Direction               : INT;              // 1 = Avant, -1 = Arrière, 0 = Arrêt
    M3_SpeedRefPct             : REAL;
    M3_BrakeCmd                : BOOL;             // TRUE = commande desserrage frein M3
    M3_TargetNum               : INT;              // Cible sélectionnée (0..4)

    PowerKeepAlive_A           : BOOL;             // TRUE = relais A maintenu sagement par le PLC
    PowerKeepAlive_B           : BOOL;             // TRUE = relais B maintenu sagement par le PLC
    EmergencyArming_RQ         : BOOL;             // Impulsion de réarmement puissance

    // ── Stimuli & Paramètres de banc ─────────────────────────────────────────
    SimEncoderSpeedFactor      : REAL := 1.0;
    SimSyncDeviationInjectM1   : BOOL := FALSE;
    SimSyncDeviationInjectM2   : BOOL := FALSE;
    SimSyncDeviationOffset_M   : REAL := 0.5;

    SimM3SensorsWordActive     : BOOL := FALSE;
    SimM3SensorsWord           : BYTE := 16#01;

    SimJoystickRawX            : INT := 5000;
    SimJoystickRawY            : INT := 5000;
    SimJoystickRawButton       : BOOL := FALSE;

    SimKoboldContactValue      : BOOL := FALSE;
    BtnEmergencyStop           : BOOL := FALSE;    // Simulation appui coup-de-poing AU

    // ── Image réelle fallback ────────────────────────────────────────────────
    HwReal                     : ST_HardwareImage;
END_VAR

VAR_OUTPUT
    Winch                      : ST_HwWinch;
    Translation                : ST_HwTranslation;
    Operator                   : ST_HwOperator;
    Machine                    : ST_HwMachine;
END_VAR

VAR_IN_OUT
    RawPosM1                   : UDINT;            // Mémoire _SimEncoderRawPosM1 dans GVL_PERSISTENT
    RawPosM2                   : UDINT;            // Mémoire _SimEncoderRawPosM2 dans GVL_PERSISTENT
END_VAR

VAR
    // Modèles sous-jacents
    instSimEncoderM1           : FB_Sim_Encoder;
    instSimEncoderM2           : FB_Sim_Encoder;
    instSimTranslation         : FB_Sim_Translation;
    instSimJoystick            : FB_Sim_Joystick;
    instSimSafety              : FB_Sim_Safety;

    // Calculs internes
    M1_PresetCmd               : BOOL;
    M2_PresetCmd               : BOOL;
    M1_OffsetPts               : DINT;
    M2_OffsetPts               : DINT;

    M3_RelayFwd                : BOOL;
    M3_RelayRev                : BOOL;

    M3_ActualFreqHz            : UINT;
    M3_StatusWordSim           : WORD;
END_VAR

// === IMPLEMENTATION ===

IF NOT Enable THEN
    Winch       := HwReal.Winch;
    Translation := HwReal.Translation;
    Operator    := HwReal.Operator;
    Machine     := HwReal.Machine;
    RETURN;
END_IF;


// ── 1. MODÈLE TREUILS (M1 + M2) ─────────────────────────────────────────────
// Presets codeurs : déclenchés si PresetTriggerCmd = 2
M1_PresetCmd := (M1_PresetTriggerCmd = 2);
M2_PresetCmd := (M2_PresetTriggerCmd = 2);

// Conversions d'injection d'écart synchro (0.5m -> points codeur avec 8192 pts/tour, 2m/tour)
// 1m = 4096 points codeur.
M1_OffsetPts := REAL_TO_DINT(SimSyncDeviationOffset_M * 4096.0);
M2_OffsetPts := REAL_TO_DINT(SimSyncDeviationOffset_M * 4096.0);

// Instance modèle codeur M1
instSimEncoderM1(
    Enable           := TRUE,
    RelayFwd         := M1_RelayFwd,
    RelayRev         := M1_RelayRev,
    SpeedRefPct      := M1_SpeedRefPct,
    PresetCmd        := M1_PresetCmd,
    PresetValue      := M1_PresetValueOut,
    SpeedScaleFactor := SimEncoderSpeedFactor,
    TestOffsetCmd    := SimSyncDeviationInjectM1,
    TestOffsetPts    := M1_OffsetPts,
    RawPos           := RawPosM1
);

// Instance modèle codeur M2
instSimEncoderM2(
    Enable           := TRUE,
    RelayFwd         := M2_RelayFwd,
    RelayRev         := M2_RelayRev,
    SpeedRefPct      := M2_SpeedRefPct,
    PresetCmd        := M2_PresetCmd,
    PresetValue      := M2_PresetValueOut,
    SpeedScaleFactor := SimEncoderSpeedFactor,
    TestOffsetCmd    := SimSyncDeviationInjectM2,
    TestOffsetPts    := M2_OffsetPts,
    RawPos           := RawPosM2
);

// Recopie structures Winch simulées :
// 🛑 POLARITÉ DE FREIN SIMULÉ (P1 Lot L6) : 1 = contacteur commandé = frein OUVERT.
// Câblage réel : DI = 1 ⟺ frein OUVERT. Le modèle produit donc M1_BrakeIsOpen_DI := M1_BrakeCmd !
Winch.M1_BrakeIsOpen_DI        := M1_BrakeCmd;
// 🔧 REX 2026-07-27 : retour UNIQUE « tous contacteurs retombés » = sens ET vitesse.
// Omettre les paliers ferait croire à l'arrêt pendant les transitoires → Méca A armée à tort.
Winch.M1_ContactorsReleased_DI := NOT (M1_RelayFwd OR M1_RelayRev
                                    OR M1_SpeedContactor_1 OR M1_SpeedContactor_2
                                    OR M1_SpeedContactor_3 OR M1_SpeedContactor_4);
Winch.M1_ThermalOk_DI          := TRUE; // Sauf panne simulée

Winch.M2_BrakeIsOpen_DI        := M2_BrakeCmd;
Winch.M2_ContactorsReleased_DI := NOT (M2_RelayFwd OR M2_RelayRev
                                    OR M2_SpeedContactor_1 OR M2_SpeedContactor_2
                                    OR M2_SpeedContactor_3 OR M2_SpeedContactor_4);
Winch.M2_ThermalOk_DI          := TRUE;

Winch.M1M2_TopPositionFree_DI  := TRUE; // Butée libre au repos en simu
Winch.M2_TensionedCable_DI     := TRUE; // Câble tendu en simu

Winch.COD1_PosValue            := instSimEncoderM1.RawPosOut;
Winch.COD1_Alarms              := 0;
Winch.COD1_Warnings            := 0;
Winch.COD1_DeviceState         := 4; // DEVICE_STATE RUNNING = 4 (bus OK)

Winch.COD2_PosValue            := instSimEncoderM2.RawPosOut;
Winch.COD2_Alarms              := 0;
Winch.COD2_Warnings            := 0;
Winch.COD2_DeviceState         := 4; // DEVICE_STATE RUNNING = 4


// ── 2. MODÈLE TRANSLATION M3 (AC600) ─────────────────────────────────────────
M3_RelayFwd := (M3_Direction = 1);
M3_RelayRev := (M3_Direction = -1);

instSimTranslation(
    Enable      := TRUE,
    TargetNum   := M3_TargetNum,
    RelayFwd    := M3_RelayFwd,
    RelayRev    := M3_RelayRev,
    TravelTimeS := 8.0,
    PVLeadTimeS := 2.0
);

// Remplissage capteurs de position M3 :
IF SimM3SensorsWordActive THEN
    Translation.M3_PosTremie_DI      := SimM3SensorsWord.0;
    Translation.M3_PosPV_DI          := SimM3SensorsWord.1;
    Translation.M3_PosP2_DI          := SimM3SensorsWord.2;
    Translation.M3_PosP1_DI          := SimM3SensorsWord.3;
    Translation.M3_PosMaintenance_DI := SimM3SensorsWord.4;
ELSE
    Translation.M3_PosTremie_DI      := instSimTranslation.PosTremie;
    Translation.M3_PosPV_DI          := instSimTranslation.PosPV;
    Translation.M3_PosP2_DI          := instSimTranslation.PosP2;
    Translation.M3_PosP1_DI          := instSimTranslation.PosP1;
    Translation.M3_PosMaintenance_DI := instSimTranslation.PosMaintenance;
END_IF;

// Polarité frein M3 (1 = OUVERT)
Translation.M3_BrakeIsOpen_DI    := M3_BrakeCmd;

// 🆕 T96 : thermique moteur/variateur AC600 — pas de panne simulée, toujours OK (comme Winch.M1/M2_ThermalOk_DI)
Translation.M3_ThermalFeedback_DI := TRUE;

// Simulation StatusWord AC600 : Bit 0 (Power Ready) = 1, Bit 7 (Comm Ready) = 1 -> 16#0081
IF (M3_Direction <> 0) THEN
    M3_StatusWordSim := 16#0087; // + Operating/Running
    M3_ActualFreqHz  := REAL_TO_UINT(M3_SpeedRefPct * 50.0); // 50.0 Hz à 100% (x100 -> 5000)
ELSE
    M3_StatusWordSim := 16#0081;
    M3_ActualFreqHz  := 0;
END_IF;

Translation.M3_StatusWord        := M3_StatusWordSim;
Translation.M3_ActualFrequencyHz := M3_ActualFreqHz;
Translation.AC600_DeviceState    := 4; // DEVICE_STATE RUNNING = 4


// ── 3. MODÈLE OPÉRATEUR / JOYSTICK ───────────────────────────────────────────
instSimJoystick(
    Enable     := TRUE,
    NeutralRaw := 5000,
    MaxRaw     := 10000
);

// Permet aux stimuli de banc de surcharger le retour du joystick si spécifié :
IF SimJoystickRawX <> 5000 THEN
    Operator.JoyXRaw_ANA1 := SimJoystickRawX;
ELSE
    Operator.JoyXRaw_ANA1 := instSimJoystick.RawX;
END_IF;

IF SimJoystickRawY <> 5000 THEN
    Operator.JoyYRaw_ANA2 := SimJoystickRawY;
ELSE
    Operator.JoyYRaw_ANA2 := instSimJoystick.RawY;
END_IF;

IF SimJoystickRawButton THEN
    Operator.JoyBtnRaw := TRUE;
ELSE
    Operator.JoyBtnRaw := instSimJoystick.RawButton;
END_IF;

Operator.CanBusState      := 2; // CANbusState 2 = ACTIVE (confirmé terrain)
Operator.JOY1_DeviceState := 4; // DEVICE_STATE RUNNING = 4


// ── 4. MODÈLE SÉCURITÉ & COMMUNS MACHINE ─────────────────────────────────────
instSimSafety(
    Enable           := TRUE,
    PowerCutOff_A    := PowerKeepAlive_A,
    PowerCutOff_B    := PowerKeepAlive_B,
    EmergencyArming  := EmergencyArming_RQ,
    BtnEmergencyStop := BtnEmergencyStop
);

Machine.PowerContactorEngaged_DI   := instSimSafety.SimContactorOk;
Machine.EmergencyChainClosed_DI    := instSimSafety.SimChainOk;
Machine.PhaseRotationOk_DI         := TRUE;
Machine.BrakeThermalOk_DI          := TRUE;
Machine.M1_M2_KoboldContactFond_DI := SimKoboldContactValue;
Machine.HydraulicThermalOk_DI      := TRUE;

(* ═══════════════════════════════════════════════════════════════
   🧠 FB_Hmi_BannerFormatter — Formateur du bandeau d'information IHM
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF/AF_Partie-07_Interface_IHM_v2.0.md §4
   🎯 Responsabilité : assemble les 4 textes du bandeau et expose
      la cause observable du blocage courant, sans piloter la machine.
   🛡️ Sécurité : priorité AU/puissance, SafeStop, puis interlocks métier.
      L'anti-clignotement est délégué à FB_AntiFlickerText (AF-07 §4.3).
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK PUBLIC FB_Hmi_BannerFormatter
VAR_INPUT
    Enable               : BOOL := TRUE;   // --> [CMD] Active le formateur
    SimulationModeActive : BOOL;   // --> [TST] Mode simulation actif
    CurrentMode          : E_Mode;   // --> [CMD] Mode courant
    BothAxesCoupled      : BOOL;   // --> [HW] Treuils M1/M2 couplés
    WinchSelected        : INT; // --> [CMD] 1 = M1, 2 = M2

    // 🔄 Cycle & sous-cycles
    CycleStep            : E_CycleStep;   // --> [HW] Étape cycle
    CycleStateStr        : STRING(80);   // --> [HW] Libellé détaillé de l'étape cycle (FB_Cycle.CycleStateStr)
    CycleErrorId         : WORD;   // --> [DIAG] Code défaut cycle (FB_Cycle.ErrorId) — notifié à STABILIZING
    CycleStepAtError     : E_CycleStep;   // --> [DIAG] Dernière étape avant le défaut (FB_Cycle.CycleStepAtError)
    DiveState            : E_DiveSearchState;   // --> [HW] État plongée
    ExtractionState      : E_ExtractionSequenceState;   // --> [HW] État extraction
    HomingActive         : BOOL;   // --> [HW] Référencement en cours
    HomingStepM1         : INT;   // --> [HW] Étape homing M1
    HomingStepM2         : INT;   // --> [HW] Étape homing M2

    // 🛡️ Dérogations & particularités
    BypassGlobalActive   : BOOL;   // --> [TST] Bypass global
    BypassWinchM1Active  : BOOL;   // --> [TST] Bypass treuil M1
    BypassWinchM2Active  : BOOL;   // --> [TST] Bypass treuil M2
    BypassTranslation    : BOOL;   // --> [TST] Bypass translation
    BypassSyncActive     : BOOL;   // --> [TST] Bypass synchro
    SyncDegradedActive   : BOOL;   // --> [TST] Synchro bridée
    LegalLimitReached    : BOOL;   // --> [SAFE] Limite légale atteinte

    // 🎮 Sécurité, causes et intention de direction
    EmergencyChainClosed : BOOL;   // --> [SAFE] Chaîne AU fermée
    PowerContactorEngaged: BOOL;   // --> [SAFE] Contacteur puissance
    PowerCutOffActiveAny : BOOL;   // --> [SAFE] Coupure puissance active
    SafeStopActive       : BOOL; // --> [SAFE] Agrégat M1/M2 par OR — tout SafeStop affiché (bandeau conservateur)
    DescendPermit        : BOOL; // --> [SAFE] Agrégat M1/M2 par AND
    AscentPermit         : BOOL; // --> [SAFE] Agrégat M1/M2 par AND
    BucketIsOpen         : BOOL;   // --> [HW] Benne ouverte
    DiveActive           : BOOL;   // --> [HW] Plongée active
    TopLimitReached      : BOOL; // --> [SAFE] Agrégat M1/M2 par OR — toute limite haute affichée
    CoupledUserRequestDirection : INT;   // --> [CMD] Direction demandée couplée
    M1LogicRequestDirection     : INT;   // --> [CMD] Direction logique M1
    M2LogicRequestDirection     : INT;   // --> [CMD] Direction logique M2
    CycleRequestDirection      : INT;   // --> [CMD] Direction cycle
    DeadmanArmed         : BOOL;   // --> [SAFE] Homme-mort armé
    JoystickAtNeutral    : BOOL;   // --> [HW] Joystick au neutre
    CycleAutoBusy        : BOOL;   // --> [HW] Cycle auto actif
END_VAR
VAR_OUTPUT
    Banner               : ST_HmiBanner;   // <-- [STAT] Bandeau IHM assemblé
END_VAR
VAR
    PrefixContext        : STRING(20);   // . [LOC] Préfixe RÉEL/SIMU
    ModeStr              : STRING(30);   // . [LOC] Libellé mode
    CouplingStr          : STRING(30);   // . [LOC] Libellé couplage
    CurrentDirection     : INT;   // . [LOC] Direction courante
    DirectionBlocked     : BOOL; // . [LOC] Interlock métier : mouvement demandé mais permit absent
    AnyBypassActive      : BOOL;   // . [LOC] Au moins un bypass actif
    CriticalActionActive : BOOL; // . [LOC] Défaut/interlock critique : affiché immédiatement (sans maintien)
    SpecialConditionCandidate : STRING(120);   // . [LOC] Texte condition spéciale
    OperatorActionCandidate   : STRING(120);   // . [LOC] Texte action opérateur
    StepAtErrorStr            : STRING(40);   // . [LOC] Libellé de l'étape d'origine du défaut
    AntiFlickSpecial     : FB_AntiFlickerText; // * [INST] §3 Condition spéciale (warning → maintenu)
    AntiFlickOperator    : FB_AntiFlickerText; // * [INST] §4 Action opérateur (critique → direct, warning → maintenu)
END_VAR
VAR CONSTANT
    CST_BannerHoldTime   : TIME := T#500ms; // . [LOC] Anti-clignotement warnings/états (AF-07 §4.3)
END_VAR

IF NOT Enable THEN
    Banner.GlobalContextText     := '';
    Banner.SequenceProgressText  := '';
    Banner.SpecialConditionText  := '';
    Banner.OperatorActionText    := '';
    RETURN;
END_IF;

{region "§1 Contexte global"}
// ═══════════════════════════════════════════════════════════════
// 1. CONTEXTE GLOBAL — aucun numéro d'étape ici
// Format (AF-07 §4.1) : [RÉEL/SIMU] [MODE] [COUPLAGE]
// ═══════════════════════════════════════════════════════════════
IF SimulationModeActive THEN
    PrefixContext := '[SIMULATION] ';
ELSE
    PrefixContext := '[RÉEL] ';
END_IF;

CASE CurrentMode OF
    E_Mode.DISABLE:  ModeStr := '[DÉSACTIVÉ]';
    E_Mode.MAINT_N1: ModeStr := '[MAINT_N1]';
    E_Mode.MAINT_N2: ModeStr := '[MAINT_N2]';
    E_Mode.SEMI_AUTO: ModeStr := '[SEMI-AUTO]';
ELSE
    ModeStr := '[MODE INCONNU]';
END_CASE;

IF CurrentMode = E_Mode.SEMI_AUTO THEN
    CouplingStr := ' [CYCLE AUTO]';
ELSIF BothAxesCoupled THEN
    CouplingStr := ' [M1+M2 COUPLÉS]';
ELSIF WinchSelected = 1 THEN
    CouplingStr := ' [M1 SEUL]';
ELSIF WinchSelected = 2 THEN
    CouplingStr := ' [M2 SEUL]';
ELSE
    CouplingStr := ' [AUCUN AXE]';
END_IF;
Banner.GlobalContextText := CONCAT(CONCAT(PrefixContext, ModeStr), CouplingStr);
{endregion}

{region "§2 Progression"}
// ═══════════════════════════════════════════════════════════════
// 2. PROGRESSION — le numéro et l'étape restent exclusivement ici
// Format (AF-07 §4.1) : Macro: <Cycle> > Sous-cycle: <Étape>
// ═══════════════════════════════════════════════════════════════
IF HomingActive THEN
    IF HomingStepM1 > 0 THEN
        Banner.SequenceProgressText := 'Homing: INDEX HAUT M1';
    ELSIF HomingStepM2 > 0 THEN
        Banner.SequenceProgressText := 'Homing: INDEX HAUT M2';
    ELSE
        Banner.SequenceProgressText := 'Homing: ATTENTE CAPTEUR HAUT';
    END_IF;
ELSIF CurrentMode = E_Mode.SEMI_AUTO THEN
    // Détail de l'étape (FB_Cycle.CycleStateStr) prioritaire ; label court en fallback.
    IF CycleStateStr <> '' THEN
        Banner.SequenceProgressText := CONCAT('Cycle: ', CycleStateStr);
    ELSE
        CASE CycleStep OF
            E_CycleStep.X0_PREPARATION: Banner.SequenceProgressText := 'Cycle: PRÉPARATION';
            E_CycleStep.X1_HOMING: Banner.SequenceProgressText := 'Cycle: RÉFÉRENCEMENT';
            E_CycleStep.X2_WORK_POS_SELECT: Banner.SequenceProgressText := 'Cycle: POSITION TRAVAIL';
            E_CycleStep.X3_OPEN_BUCKET: Banner.SequenceProgressText := 'Cycle: OUVERTURE BENNE';
            E_CycleStep.X4_DESCEND_OPEN:
                IF DiveState = E_DiveSearchState.SEARCHING_IMMERSION THEN
                    Banner.SequenceProgressText := 'Cycle: DESCENTE > IMMERSION';
                ELSIF DiveState = E_DiveSearchState.SEARCHING_BOTTOM THEN
                    Banner.SequenceProgressText := 'Cycle: DESCENTE > RECHERCHE FOND';
                ELSIF DiveState = E_DiveSearchState.BOTTOM_CONFIRMED THEN
                    Banner.SequenceProgressText := 'Cycle: DESCENTE > FOND CONFIRMÉ';
                ELSE
                    Banner.SequenceProgressText := 'Cycle: DESCENTE BENNE OUVERTE';
                END_IF;
            E_CycleStep.X5_BOTTOM_CONFIRMED: Banner.SequenceProgressText := 'Cycle: FOND CONFIRMÉ';
            E_CycleStep.X6_CLOSE_BUCKET: Banner.SequenceProgressText := 'Cycle: FERMETURE BENNE';
            E_CycleStep.X7_CTRL_ASCENT: Banner.SequenceProgressText := 'Cycle: ARRACHAGE / MONTÉE LENTE';
            E_CycleStep.X8_ASCENT_LOADED: Banner.SequenceProgressText := 'Cycle: REMONTÉE CHARGÉE';
            E_CycleStep.X9_DRAIN_PAUSE: Banner.SequenceProgressText := 'Cycle: ÉGOUTTAGE';
            E_CycleStep.X10_TRANSLATE_DUMP: Banner.SequenceProgressText := 'Cycle: TRANSLATION TRÉMIE';
            E_CycleStep.X11_OPEN_DUMP: Banner.SequenceProgressText := 'Cycle: VIDAGE BENNE';
            E_CycleStep.X13_DONE_SYNC: Banner.SequenceProgressText := 'Cycle: TERMINÉ';
            E_CycleStep.STABILIZING: Banner.SequenceProgressText := 'Cycle: STABILISATION';
        ELSE
            Banner.SequenceProgressText := 'Cycle: ÉTAPE EN COURS';
        END_CASE;
    END_IF;
ELSIF CurrentMode = E_Mode.MAINT_N1 OR CurrentMode = E_Mode.MAINT_N2 THEN
    Banner.SequenceProgressText := 'Manuel: PILOTAGE DIRECT';
ELSE
    Banner.SequenceProgressText := 'Machine: ARRÊTÉE';
END_IF;
{endregion}

{region "§3 Condition spéciale"}
// ═══════════════════════════════════════════════════════════════
// 3. CONDITION SPÉCIALE — un seul indicateur bypass/dérogation
// Format (AF-07 §4.1) : ATTENTION: <Dérogation / Bridage / Alerte>
// 🧊 Warning → maintenu min (anti-clignotement), jamais critique.
// ⚠️ La simulation n'est PAS un bypass : elle n'apparaît que dans le
//    contexte global (champ 1), jamais ici.
// ═══════════════════════════════════════════════════════════════
AnyBypassActive := BypassGlobalActive
                OR BypassWinchM1Active
                OR BypassWinchM2Active
                OR BypassTranslation
                OR BypassSyncActive;
IF AnyBypassActive THEN
    SpecialConditionCandidate := 'ATTENTION: Bypass actif';
ELSIF SyncDegradedActive THEN
    SpecialConditionCandidate := 'ATTENTION: Synchro bridée';
ELSIF LegalLimitReached THEN
    SpecialConditionCandidate := 'ATTENTION: Limite légale';
ELSE
    SpecialConditionCandidate := '';
END_IF;

AntiFlickSpecial(NewText := SpecialConditionCandidate, ForceInstant := FALSE, HoldTime := CST_BannerHoldTime);
Banner.SpecialConditionText := AntiFlickSpecial.Text;
{endregion}

{region "§4 Action opérateur"}
// ═══════════════════════════════════════════════════════════════
// 4. ACTION — cause fixe, sécurité d'abord, sans rotation
// Format (AF-07 §4.1) : [ORGANE] <Action physique> > <Fin>
// 🧊 Défauts (AU/puissance/SafeStop) + interlock DirectionBlocked
//    → affichés immédiatement (ForceInstant=TRUE) ; les autres états
//    → maintenus min (anti-clignotement).
// ═══════════════════════════════════════════════════════════════
IF CurrentMode = E_Mode.SEMI_AUTO THEN
    CurrentDirection := CycleRequestDirection;
ELSIF BothAxesCoupled THEN
    CurrentDirection := CoupledUserRequestDirection;
ELSIF WinchSelected = 1 THEN
    CurrentDirection := M1LogicRequestDirection;
ELSIF WinchSelected = 2 THEN
    CurrentDirection := M2LogicRequestDirection;
ELSE
    CurrentDirection := 0;
END_IF;

DirectionBlocked := (CurrentDirection < 0 AND NOT DescendPermit)
                OR (CurrentDirection > 0 AND NOT AscentPermit);

IF NOT EmergencyChainClosed OR NOT PowerContactorEngaged OR PowerCutOffActiveAny THEN
    OperatorActionCandidate := '[PUPITRE] Réarmer AU et puissance';
ELSIF SafeStopActive THEN
    OperatorActionCandidate := '[PUPITRE] Acquitter SafeStop';
ELSIF DirectionBlocked THEN
    IF CurrentDirection < 0 THEN
        OperatorActionCandidate := '[TREUIL] Descente interdite';
    ELSE
        OperatorActionCandidate := '[TREUIL] Montée interdite';
    END_IF;
ELSIF CurrentMode = E_Mode.SEMI_AUTO THEN
    // Guidance par étape du cycle (AF-07 §4.1) — ne masque jamais un défaut
    // (priorités AU/puissance/SafeStop/DirectionBlocked ci-dessus dominent).
    CASE CycleStep OF
        E_CycleStep.X0_PREPARATION:
            OperatorActionCandidate := '[IHM/JOYSTICK] Démarrer le cycle (bouton Start ou homme-mort)';
        E_CycleStep.X1_HOMING:
            OperatorActionCandidate := '[IHM] Attendre référencement codeurs';
        E_CycleStep.X2_WORK_POS_SELECT:
            OperatorActionCandidate := '[IHM] Sélectionner position travail';
        E_CycleStep.X3_OPEN_BUCKET:
            OperatorActionCandidate := '[IHM] Ouverture benne en cours';
        E_CycleStep.X4_DESCEND_OPEN:
            OperatorActionCandidate := '[JOYSTICK] Descendre benne ouverte > Attendre contact fond';
        E_CycleStep.X5_BOTTOM_CONFIRMED:
            OperatorActionCandidate := '[IHM] Fond confirmé - remontée';
        E_CycleStep.X6_CLOSE_BUCKET:
            OperatorActionCandidate := '[IHM] Fermeture benne en cours';
        E_CycleStep.X7_CTRL_ASCENT:
            OperatorActionCandidate := '[JOYSTICK] Remontée lente de contrôle';
        E_CycleStep.X8_ASCENT_LOADED:
            OperatorActionCandidate := '[IHM] Remontée en charge';
        E_CycleStep.X9_DRAIN_PAUSE:
            OperatorActionCandidate := '[IHM] Attendre égouttage';
        E_CycleStep.X10_TRANSLATE_DUMP:
            OperatorActionCandidate := '[JOYSTICK] Déplacer vers trémie';
        E_CycleStep.X11_OPEN_DUMP:
            OperatorActionCandidate := '[IHM] Vidage benne';
        E_CycleStep.X13_DONE_SYNC:
            OperatorActionCandidate := '[IHM] Cycle terminé';
        E_CycleStep.STABILIZING:
            // Libellé de l'étape d'origine du défaut (CycleStepAtError).
            CASE CycleStepAtError OF
                E_CycleStep.X0_PREPARATION: StepAtErrorStr := 'X0 (préparation)';
                E_CycleStep.X1_HOMING: StepAtErrorStr := 'X1 (référencement)';
                E_CycleStep.X2_WORK_POS_SELECT: StepAtErrorStr := 'X2 (sélection position)';
                E_CycleStep.X3_OPEN_BUCKET: StepAtErrorStr := 'X3 (ouverture benne)';
                E_CycleStep.X4_DESCEND_OPEN: StepAtErrorStr := 'X4 (descente)';
                E_CycleStep.X5_BOTTOM_CONFIRMED: StepAtErrorStr := 'X5 (fond confirmé)';
                E_CycleStep.X6_CLOSE_BUCKET: StepAtErrorStr := 'X6 (fermeture benne)';
                E_CycleStep.X7_CTRL_ASCENT: StepAtErrorStr := 'X7 (remontée contrôle)';
                E_CycleStep.X8_ASCENT_LOADED: StepAtErrorStr := 'X8 (remontée chargée)';
                E_CycleStep.X9_DRAIN_PAUSE: StepAtErrorStr := 'X9 (égouttage)';
                E_CycleStep.X10_TRANSLATE_DUMP: StepAtErrorStr := 'X10 (translation trémie)';
                E_CycleStep.X11_OPEN_DUMP: StepAtErrorStr := 'X11 (vidage benne)';
                E_CycleStep.X13_DONE_SYNC: StepAtErrorStr := 'X13 (cycle terminé)';
                E_CycleStep.STABILIZING: StepAtErrorStr := 'X14 (stabilisation)';
                ELSE
                    StepAtErrorStr := '?';
            END_CASE;
            // Message compact : ID défaut (ErrorId) + étape d'origine + acquitter.
            // Le détail de la cause est consultable dans le dépannage (GVL_Troubleshooting).
            OperatorActionCandidate := CONCAT('[PUPITRE] Défaut #', CONCAT(WORD_TO_STRING(CycleErrorId), CONCAT(' (étape ', CONCAT(StepAtErrorStr, ') - acquitter'))));
        ELSE
            OperatorActionCandidate := '[IHM] Cycle en cours...';
    END_CASE;
ELSIF DiveActive AND CurrentDirection < 0 THEN
    OperatorActionCandidate := '[TREUIL] Attendre fin du Dive';
ELSIF NOT BucketIsOpen AND CurrentDirection < 0 THEN
    OperatorActionCandidate := '[BENNE] Ouvrir la benne';
ELSIF TopLimitReached AND CurrentDirection > 0 THEN
    OperatorActionCandidate := '[TREUIL] Limite haute';
ELSIF NOT DeadmanArmed THEN
    OperatorActionCandidate := '[JOYSTICK] Appuyer homme-mort au neutre';
ELSIF CurrentMode = E_Mode.DISABLE THEN
    OperatorActionCandidate := '[IHM] Sélectionner un mode';
ELSIF JoystickAtNeutral THEN
    OperatorActionCandidate := '[JOYSTICK] Armé - actionner axe';
ELSE
    OperatorActionCandidate := '[JOYSTICK] Déplacement en cours';
END_IF;

// Interlock = mouvement demandé mais permit absent : c'est une cause
// sécurité (blocage de mouvement) → affichage IMMÉDIAT, comme un défaut.
CriticalActionActive := (NOT EmergencyChainClosed OR NOT PowerContactorEngaged
                     OR PowerCutOffActiveAny OR SafeStopActive OR DirectionBlocked);

AntiFlickOperator(NewText := OperatorActionCandidate, ForceInstant := CriticalActionActive, HoldTime := CST_BannerHoldTime);
Banner.OperatorActionText := AntiFlickOperator.Text;
{endregion}

(* =======================================================================
   ⚙️ FB_CycleTime — Mesure du temps de cycle réel de la tâche
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Calcul du dt réel entre deux exécutions successives
   ⚙️ Calcul : Delta horloge système TIME() converti en secondes
   📄 Doc métier : DOC/AF/AF_Partie-03_Contrats_Composants_v2.1.md
   ======================================================================= *)
FUNCTION_BLOCK FB_CycleTime
VAR_INPUT
    // === REGLAGES DE SECOURS ===
    DefaultValueS           : REAL := 0.004;      // --> [CFG] Valeur de secours par defaut (ex: 4ms = 0.004s)
END_VAR
VAR_OUTPUT
    // === MESURE ET DIAGNOSTIC ===
    CycleTimeS              : REAL;               // <-- [DIAG] Temps ecoule reel calcule (secondes)
END_VAR
VAR
    // === HORLOGE ET MEMOIRE TEMPORELLE ===
    TimeCurrent             : TIME;               // . [LOC] Temps systeme actuel
    TimeLast                : TIME;               // . [LOC] Empreinte de temps du cycle precedent
    DeltaTimeMs             : UDINT;              // . [LOC] Ecart brut calcule (ms)
    InitDone                : BOOL;               // . [LOC] Drapeau d'initialisation du premier cycle
END_VAR

{region "§1 Acquisition temps"}
// 1. ACQUISITION DU TEMPS SYSTÈME
TimeCurrent := TIME();
{endregion}

{region "§2 Initialisation"}
// 2. INITIALISATION UNIQUE AU PREMIER CYCLE
IF NOT InitDone THEN
    TimeLast := TimeCurrent;
    InitDone := TRUE;
    CycleTimeS := DefaultValueS;
    RETURN;
END_IF;
{endregion}

{region "§3 Calcul delta"}
// 3. CALCUL DU DELTA EN MILLISECONDES
DeltaTimeMs := TIME_TO_UDINT(TimeCurrent - TimeLast);
{endregion}

{region "§4 Conversion et secours"}
// 4. CONVERSION ET CHARGE DE SECOURS
IF DeltaTimeMs > 0 THEN
    CycleTimeS := UDINT_TO_REAL(DeltaTimeMs) / 1000.0;
ELSE
    CycleTimeS := DefaultValueS;
END_IF;
{endregion}

{region "§5 Archivage"}
// 5. ARCHIVAGE POUR LE PROCHAIN CYCLE
TimeLast := TimeCurrent;
{endregion}

(* ═══════════════════════════════════════════════════════════════
   🪨 ST_DredgingAssistHMI — Échange IHM assistants prélèvement
   ═══════════════════════════════════════════════════════════════ *)
TYPE ST_DredgingAssistHMI :
STRUCT
    Cmd   : ST_DredgingAssistCmd;
    Cfg   : ST_DredgingAssistCfg;
    State : ST_DredgingAssistState;
END_STRUCT
END_TYPE

(* =======================================================================
   ⚙️ FB_Encoder_Homing — Référencement codeur nominal ou unitaire
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Séquence de référencement nominal (capteur haut) ou unitaire (MAINT_N2)
   🔒 Polarité : Homed=TRUE dès qu'un référencement valide est enregistré
   🔌 Architecture : Expose ST_Encoder_Calib en VAR_IN_OUT
   📄 Doc métier : DOC/AF/AF_Partie-09_Fonction_Encoder_v2.1.md
   ======================================================================= *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Encoder_Homing) ===

FUNCTION_BLOCK PUBLIC FB_Encoder_Homing
VAR_INPUT
    // === COMMANDES & AUTORISATIONS ===
    Enable                 : BOOL;        // --> [CMD] Autorisation generale FB (TRUE=Autorise)
    Reset                  : BOOL;        // --> [CMD] Acquittement defaut (front montant)
    Home                   : BOOL;        // --> [CMD] Demande de referencement (front)
    HomingPermit           : BOOL;        // --> [CMD] Autorisation de homer (calculee par le caller)
    BtnConfirmCoherence    : BOOL;        // --> [CMD] Levee de doute d'incoherence au boot (front)

    // === CIBLES & CONFIGURATION HOMING ===
    CfgHomingTargetM       : REAL;        // --> [CFG] Cible libre homing unitaire (m)
    UseDynamicTarget       : BOOL := FALSE; // --> [CFG] Activation cible dynamique
    DynamicHomingTargetM   : REAL := 0.0; // --> [CFG] Cible dynamique de referencement (m)
    CfgTopSensorPosM       : REAL := 8.5; // --> [CFG] Cible homing nominal capteur haut (m)

    // === RETOURS HW & CAPTEURS ===
    TopPositionSensor      : BOOL;        // --> [HW]  Capteur physique position haute unique
    FwdRevSpeedFeedbackOff : BOOL;        // --> [HW]  Contacteurs sens et vitesse retombes
    BrakeFeedback          : BOOL;        // --> [HW]  Contacteur frein ouvert/desserre

    // === MESURES & RETOURS FB CODEUR ABSOLU ===
    RawPos                 : UDINT;       // --> [HW]  Position brute codeur (sortie FB_Encoder_Abs)
    EncoderAvailable       : BOOL;        // --> [HW]  Codeur absolu disponible et valide
    PresetAck              : BOOL;        // --> [HW]  Pulse confirmation ecriture preset reussie
    PresetNak              : BOOL;        // --> [HW]  Pulse echec / timeout ecriture preset

    // === CARACTERISTIQUES MECANIQUES & BUS ===
    PointsPerRev           : UDINT := 8192; // --> [CFG] Resolution codeur (pts/tour)
    MultiTurnRevsMax       : UDINT := 4096; // --> [CFG] Capacite multitour max codeur (tours)
    CableM_PerRev          : REAL := 2.0;   // --> [CFG] Perimetre tambour / developpement cable (m/tour)

    // === TESTS & BYPASS ===
    BypassGlobal           : BOOL := FALSE; // --> [TST] Neutralisation securites pour mise en service
END_VAR
VAR_OUTPUT
    // === ETATS IEC & SYNOPTIQUE ===
    Ready                  : BOOL;        // <-- [STAT] FB pret a fonctionner
    // 🧩 Statut transverse (forme cible) — regroupe Busy/Done/Error/ErrorId/State/StateAtError.
    // ErrorId : masque de bits de défaut (bit0: mode, bit1: treuil, bit4: cible, bit5: preset, bit9: incoherence boot).
    Status                 : ST_FbStatus;

    // === COMMANDES VERS FB_ENCODER_ABS ===
    PresetRequest          : BOOL;        // <-- [ACT]  Pulse demande d'ecriture preset SDO
    PresetValue            : UDINT;       // <-- [ACT]  Valeur de cible brute pour preset SDO

    // === RESULTATS & MEMOIRE CALIBRATION ===
    Homed                  : BOOL;        // <-- [STAT] Codeur pagine et referencie
    HomingSuspect          : BOOL;        // <-- [DIAG] Incoherence redemarrage a lever
    HomingRefRaw           : UDINT;       // <-- [DIAG] Offset de reference brut calcule
END_VAR
VAR_IN_OUT
    // === STRUCTURE DE CALIBRATION PERSISTANTE ===
    Calib                  : ST_Encoder_Calib; // <-> [BUS] Structure de calibration RETAIN
END_VAR
VAR
    // === DETECTEURS DE FRONT ===
    ResetEdge              : R_TRIG;      // . [LOC] Detecteur front montant Reset
    ErrorEdge              : R_TRIG;      // . [LOC] Detecteur front montant Error
    HomeEdge               : R_TRIG;      // . [LOC] Detecteur front montant Home
    ConfirmCoherenceEdge   : R_TRIG;      // . [LOC] Detecteur front montant BtnConfirmCoherence
    TopSensorEdge          : R_TRIG;      // . [LOC] Detecteur front montant TopPositionSensor
    DynamicTargetEdge      : R_TRIG;      // . [LOC] Detecteur front montant UseDynamicTarget

    // === ETATS & DRAPEAUX INTERNES ===
    InitDone               : BOOL;        // . [LOC] Controle incoherence boot effectue
    ArretConfirme          : BOOL;        // . [LOC] Condition d'arret moteur confirmee
    HomingModeOk           : BOOL;        // . [LOC] Mode de fonctionnement valide pour homing
    NominalHomingTrigger   : BOOL;        // . [LOC] Condition de declenchement homing nominal
    UnitaryHomingTrigger   : BOOL;        // . [LOC] Condition de declenchement homing unitaire
    DynamicHomingTrigger   : BOOL;        // . [LOC] Condition de declenchement homing dynamique
    HomingTrigger          : BOOL;        // . [LOC] Synthese declenchement homing

    // === VARIABLES DE CALCUL ===
    TargetPoints           : DINT;        // . [LOC] Ecart cible converti en points
    TargetPositionM        : REAL;        // . [LOC] Cible retenue en metres
    RawDiffRestart         : DINT;        // . [LOC] Ecart brut de position au redemarrage
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Homing) ===

{region "§1 Gate neutralisation"}
// 🛑 1. GATE — neutralisation ; on continue toutefois d'exposer le dernier état RETAIN connu
// (FB_Encoder_Scale a besoin de HomingRefRaw même si ce FB est désactivé)
// PowerContactorEngaged retiré du GATE (le codeur 24V / EtherCAT peut être homé disjoncteurs coupés)
IF NOT Enable THEN
    PresetRequest := FALSE;
    PresetValue := 0;
    Status.State := E_State.DISABLED;
    Ready := FALSE; Status.Busy := FALSE; Status.Done := FALSE;
    InitDone := FALSE;   // Force un nouveau contrôle §3.7 à la prochaine activation
    Homed := Calib.Homed;
    HomingSuspect := Calib.HomingSuspect;
    HomingRefRaw := Calib.HomingRefRaw;
    RETURN;
END_IF;

Ready := TRUE;

{endregion}

{region "§2 Fronts et coherence demarrage"}
// 🔑 2. FRONTS
ResetEdge(CLK := Reset);
HomeEdge(CLK := Home);
ConfirmCoherenceEdge(CLK := BtnConfirmCoherence);

// 🔍 3. COHÉRENCE AU REDÉMARRAGE (§3.7) — une fois par session Enable, dès que le codeur répond
IF NOT InitDone THEN
    Status.State := E_State.INIT;
    IF EncoderAvailable THEN
        RawDiffRestart := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(Calib.LastKnownRawPos);
        IF Calib.Homed AND (ABS(RawDiffRestart) > UDINT_TO_DINT(Calib.RestartCoherenceTolerancePts)) THEN
            Calib.HomingSuspect := TRUE;
            Status.ErrorId := Status.ErrorId OR 16#0200;   // bit9 : incohérence codeur au redémarrage
        END_IF;
        InitDone := TRUE;
    END_IF;
ELSE
    IF Status.State = E_State.INIT THEN Status.State := E_State.READY; END_IF;
END_IF;

{endregion}

{region "§3 Confirmation coherence et demande homing"}
// ✅ 4. LEVÉE DU DOUTE (BtnConfirmCoherence, §3.7) — indépendant du Reset générique
IF ConfirmCoherenceEdge.Q AND HomingPermit THEN
    Calib.HomingSuspect := FALSE;
    Status.ErrorId := Status.ErrorId AND 16#FDFF;   // efface bit9
END_IF;

PresetRequest := FALSE;
TopSensorEdge(CLK := TopPositionSensor);
DynamicTargetEdge(CLK := UseDynamicTarget);

// Gates rejetées = Warning auto-effaçable (§9/TC-P03-007), pas un Fault : recalculées à
// chaque scan, jamais latchées, aucun Reset requis pour les effacer.
Status.ErrorId := Status.ErrorId AND 16#FFEC;   // efface bits 0/1/4 (garde bit5, bit9 — inchangés)

HomingModeOk := HomingPermit;

IF HomeEdge.Q AND NOT HomingModeOk THEN
    Status.ErrorId := Status.ErrorId OR 16#0001;   // bit0 : homing non autorise
END_IF;

// Nominal : capture AU FRONT du capteur haut, pas après arrêt confirmé — AscentPermit
// (FB_Safety_Winch) coupe déjà la montée indépendamment dès que TopPositionSensor est actif ;
// attendre l'arrêt casserait la répétabilité recherchée à vitesse d'accostage constante.
// Couvre les deux cas : Home déjà maintenu quand le capteur déclenche, ou capteur déjà actif
// quand Home est pressé.
NominalHomingTrigger := HomingModeOk AND NOT UseDynamicTarget
                         AND ((Home AND TopSensorEdge.Q) OR (HomeEdge.Q AND TopPositionSensor));

// Unitaire : cible libre (CfgHomingTargetM), déclenchée par la demande (front).
UnitaryHomingTrigger := HomingModeOk AND NOT UseDynamicTarget AND HomeEdge.Q;

// Dynamique (benne) : HomingModeOk vérifié ici en défense.
DynamicHomingTrigger := HomingModeOk AND (DynamicTargetEdge.Q OR (UseDynamicTarget AND HomeEdge.Q));

HomingTrigger := NominalHomingTrigger OR UnitaryHomingTrigger OR DynamicHomingTrigger;

IF HomingTrigger THEN
    IF UseDynamicTarget THEN
        TargetPositionM := DynamicHomingTargetM;
    ELSIF NominalHomingTrigger THEN
        TargetPositionM := CfgTopSensorPosM;
    ELSE
        TargetPositionM := CfgHomingTargetM;
    END_IF;

    // Bornage obligatoire avant écriture (CODE_QUALITY_STANDARDS §6) — toute cible, quelle
    // que soit son origine (config, calcul benne, capteur haut), est vérifiée dans la plage
    // physique documentée [-99;+99] m avant d'être gravée dans la référence codeur.
    IF (TargetPositionM < -99.0) OR (TargetPositionM > 99.0) THEN
        Status.ErrorId := Status.ErrorId OR 16#0010;   // bit4 : cible hors plage, homing refusé
    ELSE
        TargetPoints := REAL_TO_DINT(TargetPositionM * UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
        Calib.HomingRefRaw := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) - TargetPoints);
        Calib.Homed := TRUE;
        Calib.HomingSuspect := FALSE;
        Calib.LastKnownRawPos := RawPos;
        HomingRefRaw := Calib.HomingRefRaw;
        Homed := TRUE;
        HomingSuspect := FALSE;
        Status.Done := TRUE;
        Status.ErrorId := 16#0000;
        Status.State := E_State.READY;

        // Envoi de la demande de Preset SDO au matériel : la valeur brute injectee
        // correspond a la cible (calcul inverse) pour que CablePosM = cible.
        PresetValue := DINT_TO_UDINT(UDINT_TO_DINT(Calib.HomingRefRaw) + TargetPoints);
        PresetRequest := TRUE;
    END_IF;
END_IF;

{endregion}

{region "§4 Suivi SDO reset et sorties etat"}
// ⏳ 6. SUIVI DE LA SÉQUENCE SDO OPTIONNELLE
IF Status.State = E_State.BUSY THEN
    IF PresetAck THEN
        Status.Done := TRUE;
        Status.State := E_State.READY;
        // Un homing réussi efface l'intégralité de ErrorId
        Status.ErrorId := 16#0000;
    ELSIF PresetNak THEN
        Status.ErrorId := Status.ErrorId OR 16#0020;        // bit5 : preset refusé/timeout (voir FB_Encoder_Abs)
        Status.State := E_State.READY;
    END_IF;
END_IF;

// 🧾 7. RESET (front) — efface les bits « dernière tentative rejetée » (pas de cause persistante
// à revérifier ici : le prochain Home réévalue toutes les conditions de zéro, voir §5)
IF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFC0;   // efface bits 0..5 (garde bit9, levé seulement par BtnConfirmCoherence/Home)
END_IF;

// 📤 8. SORTIES ÉTAT
Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;

// Mise à jour continue du point brut valide connu (hors séquence de homing elle-même)
IF EncoderAvailable AND (Status.State <> E_State.BUSY) THEN
    Calib.LastKnownRawPos := RawPos;
END_IF;

Status.Busy := (Status.State = E_State.BUSY);
Homed := Calib.Homed AND NOT Calib.HomingSuspect; // Perd l'état homed si suspect (démarrage ou fonctionnement), restauré après BtnConfirmCoherence
HomingSuspect := Calib.HomingSuspect;
HomingRefRaw := Calib.HomingRefRaw;

{endregion}

(* ═══════════════════════════════════════════════════════════════
   🧪 PRG_Test_FinalBrakePowerInterlock — Tests PLC préparés Lot 3A
   ───────────────────────────────────────────────────────────────
   ⚠️ Non exécuté : appeler uniquement dans un projet de test CODESYS.
   ⏱️ Les temporisations sont celles réelles des FB. Les résultats restent
      des preuves préparées, pas une exécution CODESYS déclarée.
   🏗️ Précondition statique : les instances production sont exclusivement dans
      PRG_10_Outputs_LD ; ce test unitaire compose les FB directement.
   ═══════════════════════════════════════════════════════════════ *)
PROGRAM PRG_Test_FinalBrakePowerInterlock
VAR
    InterlockM1 : FB_WinchOutputInterlock_LD;
    InterlockM2 : FB_WinchOutputInterlock_LD;
    InterlockM3 : FB_TranslationOutputInterlock_LD;
    ScenarioStep : INT;
    ResetRequest : BOOL;
    EnableRequest : BOOL := TRUE;
    PowerContactorEngagedRequest : BOOL := TRUE;
    SafeStopRequest : BOOL;
    BrakeConfirmed : BOOL;
    ContactorsReleased : BOOL;
    RequestedStepM1 : INT;
    RequestedStepM2 : INT;
    RequestedContactorM1_1 : BOOL;
    RequestedContactorM1_2 : BOOL;
    RequestedContactorM1_3 : BOOL;
    RequestedContactorM1_4 : BOOL;
    RequestedContactorM2_1 : BOOL;
    RequestedContactorM2_2 : BOOL;
    RequestedContactorM2_3 : BOOL;
    RequestedContactorM2_4 : BOOL;
    M2TableMappingPreservedOk : BOOL;
    RequestedDriveControlWord : WORD := 0;
    ScenarioDone : BOOL;
    ScenarioFailed : BOOL;

    M1BrakeTimeoutOk : BOOL;
    M1EnableLatchHeldOk : BOOL;
    M1EmergencyStopLatchHeldOk : BOOL;
    M1EnableRecoveryOk : BOOL;
    M1EmergencyStopRecoveryOk : BOOL;
    M1ResetOk : BOOL;
    M1StepProgressionOk : BOOL := TRUE;
    M1TransitionViolation : BOOL;
    M1PreviousAuthorizedStep : INT;

    M2BrakeTimeoutOk : BOOL;
    M2EnableLatchHeldOk : BOOL;
    M2EmergencyStopLatchHeldOk : BOOL;
    M2FeedbackOffWaitOk : BOOL;
    M2RestartDelayOk : BOOL;
    StopGateOk : BOOL := TRUE;

    M3BrakeGateOk : BOOL;
    M3BrakeTimeoutOk : BOOL;
    M3EnableLatchHeldOk : BOOL;
    M3EmergencyStopLatchHeldOk : BOOL;
    M3ResetWordOk : BOOL;
    M3PostResetHeldOk : BOOL;
    M3RestartAfterNewRequestOk : BOOL;
    M3EnableGateOk : BOOL;
    M3EmergencyStopGateOk : BOOL;
    M3SafeStopRampOk : BOOL;

    // Test end-to-end FB_Winch : la temporisation métier T#1s500ms reste
    // distincte du filet final T#1s250ms de FB_WinchOutputInterlock_LD.
    WinchBusiness : FB_Winch;
    WinchBusinessTable : ST_SpeedStepTable;
    WinchBusinessPreviousStep : INT;
    WinchBusinessTransitionViolation : BOOL;
    WinchBusinessDelayObserved : BOOL;
    WinchBusinessTestPassed : BOOL;

    // Chaîne réelle M3 : FB_Translation produit la rampe, puis l'interlock _LD
    // applique la frontière finale. Ce scénario n'injecte jamais une fréquence.
    TranslationIntegration : FB_Translation;
    TranslationIntegrationInterlock : FB_TranslationOutputInterlock_LD;
    TranslationIntegrationSafeStop : BOOL;
    TranslationIntegrationInitialFreqHz : REAL;
    TranslationIntegrationRampObservedOk : BOOL;
    TranslationIntegrationFinalFollowOk : BOOL;
END_VAR

// ── FB_Winch : temporisation métier réelle T#1s500ms ───────────────────
// Table cumulative minimale valide pour faire atteindre le palier 5 en test.
WinchBusinessTable.P1R1 := FALSE; WinchBusinessTable.P1R2 := FALSE;
WinchBusinessTable.P1R3 := FALSE; WinchBusinessTable.P1R4 := FALSE;
WinchBusinessTable.P2R1 := TRUE;  WinchBusinessTable.P2R2 := FALSE;
WinchBusinessTable.P2R3 := FALSE; WinchBusinessTable.P2R4 := FALSE;
WinchBusinessTable.P3R1 := TRUE;  WinchBusinessTable.P3R2 := TRUE;
WinchBusinessTable.P3R3 := FALSE; WinchBusinessTable.P3R4 := FALSE;
WinchBusinessTable.P4R1 := TRUE;  WinchBusinessTable.P4R2 := TRUE;
WinchBusinessTable.P4R3 := TRUE;  WinchBusinessTable.P4R4 := FALSE;
WinchBusinessTable.P5R1 := TRUE;  WinchBusinessTable.P5R2 := TRUE;
WinchBusinessTable.P5R3 := TRUE;  WinchBusinessTable.P5R4 := TRUE;
WinchBusinessTable.StepThreshold_Pct := [10.0, 20.0, 30.0, 40.0, 100.0];
WinchBusiness(
    Enable := TRUE, Reset := FALSE, PowerContactorEngaged := TRUE, Mode := E_Mode.MAINT_N1,
    StartStop := TRUE, SafeStop := FALSE, ForbidDescent := FALSE, ForbidAscent := FALSE,
    Direction := 1, SpeedRefPct := 100.0, SpeedStepTable := WinchBusinessTable,
    FwdRevSpeedFeedbackOff := TRUE, BrakeFeedback := FALSE,
    BypassContactorCheck := TRUE, BypassGlobal := FALSE,
    Homed := TRUE, HomingSuspect := FALSE, CablePosM := 0.0
);
IF WinchBusiness.StepNumber <> WinchBusinessPreviousStep THEN
    IF (WinchBusiness.StepNumber <> (WinchBusinessPreviousStep + 1))
       OR (WinchBusiness.BusinessStepDelayElapsed < T#1s500ms) THEN
        WinchBusinessTransitionViolation := TRUE;
    END_IF;
    WinchBusinessPreviousStep := WinchBusiness.StepNumber;
END_IF;
IF (WinchBusiness.RequestedStep > WinchBusiness.StepNumber)
   AND (WinchBusiness.BusinessStepDelayElapsed >= T#1s500ms) THEN
    WinchBusinessDelayObserved := TRUE;
END_IF;
WinchBusinessTestPassed := (WinchBusiness.StepNumber = 5)
                           AND WinchBusinessDelayObserved
                           AND NOT WinchBusinessTransitionViolation;

// Les trois interlocks sont appelés chaque cycle. La machine de scénario
// modifie uniquement les entrées pour rendre les transitions observables.
InterlockM1(
    Enable := EnableRequest,
    Reset := ResetRequest,
    PowerContactorEngaged := PowerContactorEngagedRequest,
    SafeStop := SafeStopRequest,
    BrakeReleaseRequest := (RequestedStepM1 > 0),
    BrakeCommandOpenConfirmed := BrakeConfirmed,
    FwdRevSpeedFeedbackOff := ContactorsReleased,
    RequestedRelayFwd := TRUE,
    RequestedRelayRev := FALSE,
    RequestedContactor1 := RequestedContactorM1_1,
    RequestedContactor2 := RequestedContactorM1_2,
    RequestedContactor3 := RequestedContactorM1_3,
    RequestedContactor4 := RequestedContactorM1_4,
    RequestedStep := RequestedStepM1
);
InterlockM2(
    Enable := EnableRequest,
    Reset := ResetRequest,
    PowerContactorEngaged := PowerContactorEngagedRequest,
    SafeStop := SafeStopRequest,
    BrakeReleaseRequest := (RequestedStepM2 > 0),
    BrakeCommandOpenConfirmed := BrakeConfirmed,
    FwdRevSpeedFeedbackOff := ContactorsReleased,
    RequestedRelayFwd := TRUE,
    RequestedRelayRev := FALSE,
    RequestedContactor1 := RequestedContactorM2_1,
    RequestedContactor2 := RequestedContactorM2_2,
    RequestedContactor3 := RequestedContactorM2_3,
    RequestedContactor4 := RequestedContactorM2_4,
    RequestedStep := RequestedStepM2
);
// Le mapping contacteurs reste celui produit par FB_Winch. Cas volontairement
// non cumulatif M2 : seul R4 est demandé au palier 2 (ex. table Benne dynamique).
// L'interlock doit le transmettre à l'identique dès que le palier est autorisé.

InterlockM3(
    Enable := EnableRequest,
    Reset := ResetRequest,
    PowerContactorEngaged := PowerContactorEngagedRequest,
    SafeStop := SafeStopRequest,
    BrakeReleaseRequest := (RequestedDriveControlWord = 1) OR (RequestedDriveControlWord = 2),
    BrakeCommandOpenConfirmed := BrakeConfirmed,
    // IEC SEL(G, IN0, IN1) : G=FALSE → demande normale (1), G=TRUE → reset AC600 (7).
    RequestedDriveControlWord := SEL((ScenarioStep = 95) OR (ScenarioStep = 96), RequestedDriveControlWord, 7),
    RequestedDriveFreqHz := 20.0
);

// Intégration réelle M3 : production par FB_Translation, puis filtre final _LD.
TranslationIntegration(
    Enable := TRUE, Reset := FALSE, PowerContactorEngaged := TRUE, Mode := E_Mode.MAINT_N1,
    StartStop := (ScenarioStep >= 110) AND (ScenarioStep < 130),
    SafeStop := TranslationIntegrationSafeStop, Direction := 1, SpeedRefPct := 50.0,
    PositionSensorTarget := FALSE, SlowdownSensor := FALSE,
    LimitSwitchFwd := FALSE, LimitSwitchRev := FALSE,
    DriveStatusWord := 16#0000, DriveActualFreqHz := 0.0,
    BypassContactorCheck := TRUE, BypassLimitSwitch := FALSE, BrakeFeedback := FALSE,
    CfgRampAccelRate := 100.0, CfgRampDecelNormalRate := 100.0, CfgRampDecelFastRate := 1000.0,
    DriveFreqScaleMaxHz := 60.0
);
TranslationIntegrationInterlock(
    Enable := TRUE, Reset := FALSE, PowerContactorEngaged := TRUE,
    SafeStop := TranslationIntegrationSafeStop,
    BrakeReleaseRequest := TranslationIntegration.BrakeReleaseRequest,
    BrakeCommandOpenConfirmed := TranslationIntegration.BrakeReleaseRequest,
    RequestedDriveControlWord := TranslationIntegration.RequestedDriveControlWord,
    RequestedDriveFreqHz := TranslationIntegration.RequestedDriveFreqHz
);

// Chaque hausse M1 doit être adjacente et ne peut apparaître qu'après T#1s250ms.
// StepDelayElapsed est capturé par l'interlock au scan exact de la transition.
IF (RequestedStepM1 = 5) AND (InterlockM1.AuthorizedStep <> M1PreviousAuthorizedStep) THEN
    IF (InterlockM1.AuthorizedStep <> (M1PreviousAuthorizedStep + 1))
       OR (InterlockM1.StepDelayElapsed < T#1s250ms) THEN
        M1TransitionViolation := TRUE;
    END_IF;
    M1PreviousAuthorizedStep := InterlockM1.AuthorizedStep;
END_IF;

ResetRequest := FALSE;
CASE ScenarioStep OF
    0: // Initialisation : frein serré, retours contacteurs retombés.
        BrakeConfirmed := FALSE;
        ContactorsReleased := TRUE;
        RequestedStepM1 := 0;
        RequestedStepM2 := 0;
        RequestedContactorM1_1 := FALSE; RequestedContactorM1_2 := FALSE;
        RequestedContactorM1_3 := FALSE; RequestedContactorM1_4 := FALSE;
        RequestedContactorM2_1 := FALSE; RequestedContactorM2_2 := FALSE;
        RequestedContactorM2_3 := FALSE; RequestedContactorM2_4 := FALSE;
        RequestedDriveControlWord := 0;
        ScenarioStep := 10;

    10: // M1/M2 : absence confirmation >500ms → défauts mémorisés, puissance nulle.
        RequestedStepM1 := 1;
        RequestedStepM2 := 1;
        RequestedContactorM1_1 := FALSE; // Palier 1 sans contacteur : table métier valide.
        RequestedContactorM2_1 := FALSE; RequestedContactorM2_2 := FALSE;
        RequestedContactorM2_3 := FALSE; RequestedContactorM2_4 := FALSE;
        IF InterlockM1.Error AND InterlockM2.Error THEN
            M1BrakeTimeoutOk := NOT InterlockM1.BrakeCmd AND (InterlockM1.AuthorizedStep = 0);
            M2BrakeTimeoutOk := NOT InterlockM2.BrakeCmd AND (InterlockM2.AuthorizedStep = 0);
            // Cas 1 : Enable retombe PENDANT les deux latch timeout.
            EnableRequest := FALSE;
            ScenarioStep := 11;
        END_IF;

    11: // Les deux latch timeout survivent à Enable=FALSE ; sorties strictement nulles.
        M1EnableLatchHeldOk := InterlockM1.Error AND InterlockM1.RestartInhibit
                               AND NOT InterlockM1.BrakeCmd AND (InterlockM1.AuthorizedStep = 0);
        M2EnableLatchHeldOk := InterlockM2.Error AND InterlockM2.RestartInhibit
                               AND NOT InterlockM2.BrakeCmd AND (InterlockM2.AuthorizedStep = 0);
        EnableRequest := TRUE;
        PowerContactorEngagedRequest := FALSE;
        ScenarioStep := 12;

    12: // Cas 2 séparé : les deux latch timeout survivent à PowerContactorEngaged=FALSE.
        M1EmergencyStopLatchHeldOk := InterlockM1.Error AND InterlockM1.RestartInhibit
                                      AND NOT InterlockM1.BrakeCmd AND (InterlockM1.AuthorizedStep = 0);
        M2EmergencyStopLatchHeldOk := InterlockM2.Error AND InterlockM2.RestartInhibit
                                      AND NOT InterlockM2.BrakeCmd AND (InterlockM2.AuthorizedStep = 0);
        PowerContactorEngagedRequest := TRUE;
        BrakeConfirmed := TRUE; // Cause disparue seulement après les deux gates.
        RequestedStepM1 := 0;
        RequestedStepM2 := 0;
        ScenarioStep := 20;

    20: // Front Reset conscient M1 après disparition de cause.
        ResetRequest := TRUE;
        ScenarioStep := 21;
    21: // Demande zéro obligatoire après Reset, puis vérification interlock toujours inhibé.
        M1ResetOk := NOT InterlockM1.Error;
        RequestedStepM1 := 0;
        M1EnableRecoveryOk := InterlockM1.RestartInhibit AND NOT InterlockM1.BrakeCmd;
        M1PreviousAuthorizedStep := InterlockM1.AuthorizedStep;
        ScenarioStep := 22;
    22: // Nouvelle demande distincte : Enable rétabli, retombée + T#900ms recommencent.
        RequestedStepM1 := 5;
        M1EmergencyStopRecoveryOk := InterlockM1.RestartInhibit OR (InterlockM1.AuthorizedStep = 0);
        ScenarioStep := 30;

    30: // M1 : capture chaque transition 0→1→2→3→4→5.
        IF InterlockM1.AuthorizedStep = 5 THEN
            M1StepProgressionOk := NOT M1TransitionViolation;
            RequestedStepM1 := 0;
            ContactorsReleased := FALSE;
            ScenarioStep := 40;
        END_IF;

    40: // M2 : retour NON retombé → attente explicite, aucun redémarrage.
        RequestedStepM2 := 2;
        // Cas table spécifique M2 : P2 = R4 seul, non cumulatif.
        RequestedContactorM2_1 := FALSE; RequestedContactorM2_2 := FALSE;
        RequestedContactorM2_3 := FALSE; RequestedContactorM2_4 := TRUE;
        M2FeedbackOffWaitOk := (InterlockM2.AuthorizedStep = 0)
                                AND NOT ContactorsReleased;
        ContactorsReleased := TRUE;
        ScenarioStep := 50;

    50: // M2 : après retour retombé, l'autorisation ne vient qu'après T#900ms.
        IF InterlockM2.AuthorizedStep = 2 THEN
            M2RestartDelayOk := M2FeedbackOffWaitOk
                                 AND (InterlockM2.RestartDelayElapsed >= T#900ms);
            M2TableMappingPreservedOk := NOT InterlockM2.Contactor1
                                         AND NOT InterlockM2.Contactor2
                                         AND NOT InterlockM2.Contactor3
                                         AND InterlockM2.Contactor4;
            RequestedStepM2 := 0;
            RequestedContactorM2_4 := FALSE;
            ScenarioStep := 60;
        END_IF;

    60: // Enable coupe immédiatement puissance/frein.
        EnableRequest := FALSE;
        ScenarioStep := 61;
    61:
        StopGateOk := StopGateOk AND NOT InterlockM1.BrakeCmd AND NOT InterlockM2.BrakeCmd
                      AND (InterlockM1.AuthorizedStep = 0) AND (InterlockM2.AuthorizedStep = 0);
        EnableRequest := TRUE;
        PowerContactorEngagedRequest := FALSE;
        ScenarioStep := 62;
    62: // PowerContactorEngaged coupe immédiatement puissance/frein.
        StopGateOk := StopGateOk AND NOT InterlockM1.BrakeCmd AND NOT InterlockM2.BrakeCmd
                      AND (InterlockM1.AuthorizedStep = 0) AND (InterlockM2.AuthorizedStep = 0);
        PowerContactorEngagedRequest := TRUE;
        SafeStopRequest := TRUE;
        ScenarioStep := 63;
    63: // SafeStop ne coupe pas l'interlock : la rampe rapide reste métier.
        // Ici la demande est déjà nulle : les sorties restent donc nulles sans exception _LD.
        StopGateOk := StopGateOk AND (InterlockM1.AuthorizedStep = 0) AND (InterlockM2.AuthorizedStep = 0);
        SafeStopRequest := FALSE;
        BrakeConfirmed := FALSE;
        RequestedDriveControlWord := 1; // Demande normale de marche M3.
        ScenarioStep := 90;

    90: // M3 : aucune fréquence/couple après pré-magnétisation sans confirmation.
        M3BrakeGateOk := (InterlockM3.DriveControlWord = 0) AND (InterlockM3.DriveFreqRefHz = 0.0);
        IF InterlockM3.Error THEN
            M3BrakeTimeoutOk := NOT InterlockM3.BrakeCmd AND InterlockM3.RestartInhibit;
            // Timeout M3 : les deux gates durs suivants ne doivent jamais masquer Error.
            EnableRequest := FALSE;
            ScenarioStep := 91;
        END_IF;

    91: // Timeout M3 persiste pendant Enable=FALSE, sorties sûres.
        M3EnableLatchHeldOk := InterlockM3.Error AND InterlockM3.RestartInhibit
                               AND (InterlockM3.DriveControlWord = 0)
                               AND (InterlockM3.DriveFreqRefHz = 0.0) AND NOT InterlockM3.BrakeCmd;
        EnableRequest := TRUE;
        PowerContactorEngagedRequest := FALSE;
        ScenarioStep := 92;

    92: // Timeout M3 persiste pendant PowerContactorEngaged=FALSE, sorties sûres.
        M3EmergencyStopLatchHeldOk := InterlockM3.Error AND InterlockM3.RestartInhibit
                                      AND (InterlockM3.DriveControlWord = 0)
                                      AND (InterlockM3.DriveFreqRefHz = 0.0) AND NOT InterlockM3.BrakeCmd;
        PowerContactorEngagedRequest := TRUE;
        BrakeConfirmed := TRUE; // Cause disparue après les deux gates.
        ScenarioStep := 95;

    95: // Reset variateur : SEL force word 7, fréquence toujours nulle.
        ResetRequest := TRUE;
        ScenarioStep := 96;
    96:
        M3ResetWordOk := (InterlockM3.DriveControlWord = 7) AND (InterlockM3.DriveFreqRefHz = 0.0);
        RequestedDriveControlWord := 1; // Demande maintenue : doit rester inhibée.
        ScenarioStep := 97;
    97:
        M3PostResetHeldOk := InterlockM3.RestartInhibit
                              AND (InterlockM3.DriveControlWord = 0)
                              AND (InterlockM3.DriveFreqRefHz = 0.0);
        RequestedDriveControlWord := 0; // Neutre explicite obligatoire.
        ScenarioStep := 98;
    98:
        RequestedDriveControlWord := 1; // Nouvelle demande après neutre.
        ScenarioStep := 99;
    99:
        M3RestartAfterNewRequestOk := NOT InterlockM3.RestartInhibit
                                      AND (InterlockM3.DriveControlWord = 1)
                                      AND (InterlockM3.DriveFreqRefHz > 0.0);
        EnableRequest := FALSE;
        ScenarioStep := 100;
    100: // M3 Enable=FALSE : mot, fréquence et frein en position sûre.
        M3EnableGateOk := (InterlockM3.DriveControlWord = 0)
                           AND (InterlockM3.DriveFreqRefHz = 0.0)
                           AND NOT InterlockM3.BrakeCmd;
        EnableRequest := TRUE;
        PowerContactorEngagedRequest := FALSE;
        ScenarioStep := 101;
    101: // M3 PowerContactorEngaged=FALSE : mot, fréquence et frein en position sûre.
        M3EmergencyStopGateOk := (InterlockM3.DriveControlWord = 0)
                                  AND (InterlockM3.DriveFreqRefHz = 0.0)
                                  AND NOT InterlockM3.BrakeCmd;
        PowerContactorEngagedRequest := TRUE;
        ScenarioStep := 110;

    110: // FB_Translation réel : attendre une fréquence amont et finale non nulles.
        IF TranslationIntegrationInterlock.DriveFreqRefHz > 0.0 THEN
            TranslationIntegrationInitialFreqHz := TranslationIntegrationInterlock.DriveFreqRefHz;
            TranslationIntegrationSafeStop := TRUE;
            ScenarioStep := 111;
        END_IF;
    111: // SafeStop : la rampe rapide est produite amont, la frontière _LD la suit.
        IF (TranslationIntegration.RequestedDriveFreqHz > 0.0)
           AND (TranslationIntegration.RequestedDriveFreqHz < TranslationIntegrationInitialFreqHz)
           AND (TranslationIntegrationInterlock.DriveFreqRefHz = TranslationIntegration.RequestedDriveFreqHz)
           AND ((TranslationIntegrationInterlock.DriveControlWord = 1)
                OR (TranslationIntegrationInterlock.DriveControlWord = 0)) THEN
            TranslationIntegrationRampObservedOk := TRUE;
        END_IF;
        IF TranslationIntegration.RequestedDriveFreqHz = 0.0 THEN
            TranslationIntegrationFinalFollowOk := (TranslationIntegrationInterlock.DriveControlWord = 0)
                                                   AND (TranslationIntegrationInterlock.DriveFreqRefHz = 0.0);
            TranslationIntegrationSafeStop := FALSE;
            ScenarioStep := 120;
        END_IF;
    120: // La durée du test métier dépend des TON réels : attendre le palier 5.
        IF WinchBusinessTestPassed THEN
            ScenarioDone := M1BrakeTimeoutOk AND M1ResetOk AND M1StepProgressionOk
                            AND M1EnableLatchHeldOk AND M1EmergencyStopLatchHeldOk
                            AND M1EnableRecoveryOk AND M1EmergencyStopRecoveryOk
                            AND M2BrakeTimeoutOk AND M2EnableLatchHeldOk AND M2EmergencyStopLatchHeldOk
                            AND M2FeedbackOffWaitOk AND M2RestartDelayOk AND M2TableMappingPreservedOk AND StopGateOk
                            AND M3BrakeGateOk AND M3BrakeTimeoutOk
                            AND M3EnableLatchHeldOk AND M3EmergencyStopLatchHeldOk AND M3ResetWordOk
                            AND M3PostResetHeldOk AND M3RestartAfterNewRequestOk
                            AND M3EnableGateOk AND M3EmergencyStopGateOk
                            AND TranslationIntegrationRampObservedOk AND TranslationIntegrationFinalFollowOk
                            AND WinchBusinessTestPassed;
            ScenarioFailed := NOT ScenarioDone;
        END_IF;
ELSE
    ScenarioFailed := TRUE;
END_CASE

(* ═══════════════════════════════════════════════════════════════
   🧪 FB_Sim_Joystick — Simulation des entrées brutes joystick (bus CAN hors ligne)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF/AF_Partie-13_Fonction_Simulation_v2.3.md
   🧩 Brique réduite (Partie3 §1bis) : outil de banc, pas du métier machine.
   🎯 Rôle : remplace l'ancien bypass homme-mort codé en dur dans `FB_Joystick`
      (`GVL_DEBUG.DBG_DeadmanBypass_TEST`, qui forçait `DeadmanArmed` en
      permanence — un vrai contournement de sécurité). Ici, on simule les
      ENTRÉES BRUTES du capteur (`RawX`/`RawY`/`RawButton`) : le homme-mort réel
      de `FB_Joystick` reste pleinement actif et doit toujours être "actionné"
      (forcer `RawButton` en instance CODESYS) pour armer — comportement
      métier testé pour de vrai, pas contourné.
   📥 Enable        : simulation active (SimulationModeActive AND NOT BusJoystickSignalIsReal) — granularité
       séparée du bus CANopen (BusJoystickIsReal, voir GVL_Simulation)
   📥 NeutralRaw    : valeur brute simulée au repos (voir GVL_Simulation.TstJoystickForceNeutralRaw)
   📥 MaxRaw        : valeur brute simulée à fond (voir GVL_Simulation.TstJoystickForceMaxRaw)
   📤 RawX/RawY     : forçables en instance CODESYS (par défaut = NeutralRaw, repos)
   📤 RawButton     : forçable en instance CODESYS (par défaut = FALSE, relâché)
   💡 Note d'application : en vue instance CODESYS, forcer `RawX`/`RawY` à `MaxRaw` (ou une
      valeur intermédiaire) pour simuler un débattement, et `RawButton` à `TRUE` pour simuler
      l'appui homme-mort — exactement comme on forcerait le vrai capteur.
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Sim_Joystick) ===

FUNCTION_BLOCK PUBLIC FB_Sim_Joystick
VAR_INPUT
    Enable      : BOOL;   (* --> [CMD] Active la simulation *)
    NeutralRaw  : INT := 5000;   (* --> [CFG] Valeur brute au repos *)
    MaxRaw      : INT := 10000;   (* --> [CFG] Valeur brute à fond *)
END_VAR
VAR_OUTPUT
    RawX        : INT;   (* <-- [DIAG] Forçable en instance CODESYS (repos = NeutralRaw) *)
    RawY        : INT;   (* <-- [DIAG] Forçable en instance CODESYS (repos = NeutralRaw) *)
    RawButton   : BOOL;  (* <-- [DIAG] Forçable en instance CODESYS (repos = FALSE) *)
END_VAR
VAR
    FirstCycle  : BOOL := TRUE;   (* . [LOC] Initialisation au neutre *)
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Joystick) ===

{region "§1 Gate"}
// 🔑 Initialise au neutre au premier cycle uniquement — ensuite RawX/RawY/RawButton
// restent forçables librement en instance CODESYS (un Force n'est jamais écrasé par TRUE,
// mais une simple écriture cyclique l'écraserait — donc pas de ré-assignation continue ici).
IF NOT Enable THEN
    FirstCycle := TRUE;
    RETURN;
END_IF;
{endregion}

{region "§2 Initialisation neutre"}
IF FirstCycle THEN
    RawX := NeutralRaw;
    RawY := NeutralRaw;
    RawButton := FALSE;
    FirstCycle := FALSE;
END_IF;
{endregion}

(* ═══════════════════════════════════════════════════════════════
   🧪 FB_Sim_Translation — Progression capteurs simulés M3
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Produit les cinq capteurs de position M3 par progression continue
      de Trémie vers Maintenance. Le modèle ne publie que les six mots valides
      de FB_Translation_PositionDecoder : 11111 → 01111 → 00111 → 00011 →
      00001 → 00000.
   📏 Convention : PositionProgress en mètres, 0 m = Trémie … 30 m = Maintenance.
      Distances NON-linéaires : Trémie(0)→PV(5)=5 m, PV(5)→P2(15)=10 m,
      P2(15)→P1(20)=5 m, P1(20)→Maintenance(30)=10 m.
   🔒 Le modèle est une source d'entrée confinée derrière HwIn ; il ne pilote
      aucune sortie réelle. Un override manuel valide est appliqué par
      FB_SimBench, pas par ce FB.
   📄 Docs : DOC/AF/AF_Partie-13_Fonction_Simulation_v2.3.md
             DOC/AF/AF_Partie-11_Fonction_Translation_v2.2.md
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Sim_Translation
VAR_INPUT
    Enable          : BOOL;              (* --> [CMD] TRUE = modèle actif *)
    Direction       : INT;               (* --> [CMD] +1 = vers Trémie ; -1 = vers Maintenance ; 0 = maintien position *)
    SpeedRefPct     : REAL;              (* --> [CMD] Magnitude commande 0..100 %, bornée avant calcul *)
    FullTravelTimeS : REAL := 8.0;       (* --> [CFG] Temps complet Trémie→Maintenance à 100 %, simulation seulement *)
END_VAR
VAR_OUTPUT
    PosTremie      : BOOL;               (* <-- [STAT] Bit4 du mot capteurs *)
    PosPV          : BOOL;               (* <-- [STAT] Bit3 du mot capteurs *)
    PosP2          : BOOL;               (* <-- [STAT] Bit2 du mot capteurs (point matériel PVP2) *)
    PosP1          : BOOL;               (* <-- [STAT] Bit1 du mot capteurs *)
    PosMaintenance : BOOL;               (* <-- [STAT] Bit0 du mot capteurs *)
END_VAR
VAR
    instCycleTime              : FB_CycleTime;   (* * [INST] Mesure temps de cycle *)
    PositionProgress           : REAL;   (* . [LOC] 0 m=Trémie ... 30 m=Maintenance *)
    SpeedPctBounded            : REAL;   (* . [LOC] Vitesse bornée *)
    PositionIncrement          : REAL;   (* . [LOC] Incrément de progression *)
    Initialized                : BOOL := FALSE;   (* . [LOC] Initialisation *)
END_VAR
VAR CONSTANT
    // 📏 Positions réelles des 5 capteurs (mètres) — convention 0 m=Trémie, 30 m=Maintenance.
    // Distances NON-linéaires : 0→5 (PV), 5→15 (P2), 15→20 (P1), 20→30 (Maintenance).
    CST_PositionAtTremie       : REAL := 0.0;
    CST_PositionAtPV           : REAL := 5.0;
    CST_PositionAtP2           : REAL := 15.0;
    CST_PositionAtP1           : REAL := 20.0;
    CST_PositionAtMaintenance  : REAL := 30.0;
    CST_TotalDistanceM         : REAL := 30.0; // Distance totale Trémie→Maintenance (m)
    CST_MinFullTravelTimeS     : REAL := 0.1; // Protection division : modèle sans dynamique sous ce seuil
END_VAR

// === IMPLEMENTATION ===

{region "§1 Gate"}
IF NOT Enable THEN
    // Prochain démarrage déterministe sur la Trémie (0 m), pour un état de départ propre.
    PositionProgress := CST_PositionAtTremie;
    Initialized := FALSE;
    PosTremie := FALSE;
    PosPV := FALSE;
    PosP2 := FALSE;
    PosP1 := FALSE;
    PosMaintenance := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Initialisation"}
IF NOT Initialized THEN
    PositionProgress := CST_PositionAtTremie;
    Initialized := TRUE;
END_IF;
{endregion}

{region "§3 Progression"}
instCycleTime(DefaultValueS := 0.010);
SpeedPctBounded := LIMIT(0.0, ABS(SpeedRefPct), 100.0);

// Une vitesse à 100 % parcourt les 30 m (Trémie→Maintenance) pendant FullTravelTimeS.
// Direction sémantique : +1 réduit la progression vers Trémie ; -1 l'augmente vers Maintenance.
IF FullTravelTimeS >= CST_MinFullTravelTimeS THEN
    PositionIncrement := (SpeedPctBounded / 100.0)
                         * (CST_TotalDistanceM / FullTravelTimeS)
                         * instCycleTime.CycleTimeS;
ELSE
    PositionIncrement := 0.0;
END_IF;

IF Direction = 1 THEN
    PositionProgress := MAX(CST_PositionAtTremie, PositionProgress - PositionIncrement);
ELSIF Direction = -1 THEN
    PositionProgress := MIN(CST_PositionAtMaintenance, PositionProgress + PositionIncrement);
END_IF;
{endregion}

{region "§4 Publication capteurs"}
// Réinitialisation explicite : aucune valeur transitoire héritée d'une zone précédente.
PosTremie := FALSE;
PosPV := FALSE;
PosP2 := FALSE;
PosP1 := FALSE;
PosMaintenance := FALSE;

// Chaque intervalle correspond à un seul mot thermomètre valide.
IF PositionProgress <= CST_PositionAtTremie THEN
    PosTremie := TRUE;
    PosPV := TRUE;
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF PositionProgress <= CST_PositionAtPV THEN
    PosPV := TRUE;
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF PositionProgress <= CST_PositionAtP2 THEN
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF PositionProgress <= CST_PositionAtP1 THEN
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF PositionProgress < CST_PositionAtMaintenance THEN
    PosMaintenance := TRUE;
END_IF;
{endregion}

SETUP
VAR
    fb : FB_SAFETY_EMERGENCYMANAGEMENT;
END_VAR
END_SETUP

(* TC-P01-002 est classee SITE+AUTO dans l AF (mixte). Ce test ne couvre QUE la partie AUTO
   (commande logicielle) : preuve qu un seul canal est coupe a la fois et que le FB interprete
   correctement le retour de boucle fourni en entree. Il ne peut PAS prouver que la coupure
   physique de MaintainA/B_RQ ouvre reellement la boucle materielle -- ca reste une verification
   SITE, sur l automate reel, jamais automatisable en logiciel. *)
TEST 'TC-P01-002 (partie AUTO) chaque canal est commande independamment, l autre reste maintenu'
    (* demarrage + regime etabli, sain *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'hors defaut, canal A maintenu');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'hors defaut, canal B maintenu');

    (* front ArmRequest -> TestA (step 1) : SEUL le canal A doit se couper *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'front doit lancer TestA');
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'TestA : canal A seul doit se couper');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'TestA : canal B ne doit PAS etre affecte');

    (* 200ms plus tard : la boucle reagit reellement a la coupure de A (preuve physique reelle) *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := FALSE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 2, 'TestA reussi (boucle a reagi) -> RestoreA');
    ASSERT_FALSE(fb.ERROR, 'pas de defaut si le canal reagit correctement au test');
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'canal A restaure immediatement apres son test');

    (* 200ms plus tard : boucle refermee (A restaure) -> passage a TestB (step 3) *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 3, 'RestoreA reussi -> TestB');
    ASSERT_FALSE(fb.MAINTAINB_RQ, 'TestB : canal B seul doit se couper');
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'TestB : canal A ne doit PAS etre affecte');

    (* 200ms plus tard : boucle reagit a la coupure de B *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := FALSE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 4, 'TestB reussi -> RestoreB');
    ASSERT_FALSE(fb.ERROR, 'pas de defaut si le canal B reagit correctement au test');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'canal B restaure immediatement apres son test');
END_TEST

