(* =======================================================================
   ⚙️ FB_Encoder_Scale — Mise à l'échelle points → mètres (1 par treuil)
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Calcul de la position câble en mètres par conversion arithmétique signée
   🔒 Polarité : CablePosM signée (+ enroulé, - sous l'eau)
   🔌 Architecture : Convertisseur de mesure unitaire par treuil
   📄 Doc métier : DOC/AF/AF_Partie-09_Fonction_Encoder_v2.1.md
   ======================================================================= *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Encoder_Scale) ===

FUNCTION_BLOCK PUBLIC FB_Encoder_Scale
VAR_INPUT
    // === DONNEES ENTREE & REFERENCES BRUTES ===
    RawPos          : UDINT;       // --> [HW]  Position brute codeur (sortie FB_Encoder_Abs, gelee sur doute)
    HomingRefRaw    : UDINT;       // --> [CFG] Reference brute figee au dernier homing (ST_Encoder_Calib)

    // === PARAMETRES & RATIOS DE CONVERSION ===
    CableM_PerRev   : REAL := 2.0; // --> [CFG] Developpement cable par tour tambour (m/tour)
    PointsPerRev    : UDINT := 8192;// --> [CFG] Resolution codeur (pts/tour)
END_VAR
VAR_OUTPUT
    // === MESURE CONVERTIE ===
    CablePosM       : REAL;        // <-- [DIAG] Position cable en metres (+ enroule, - sous l'eau)
END_VAR
VAR
    // === CALCULS INTERNES ===
    RawDiff         : DINT;        // . [LOC] Ecart signe RawPos - HomingRefRaw
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Scale) ===

// 🧮 Écart signé sûr : conversion DINT AVANT soustraction (§3.1) — jamais l'inverse
RawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(HomingRefRaw);

// 📏 Formule fixe points → mètres (Partie10 §2), garde division par zéro
IF PointsPerRev > 0 THEN
    CablePosM := DINT_TO_REAL(RawDiff) * (CableM_PerRev / UDINT_TO_REAL(PointsPerRev));
ELSE
    CablePosM := 0.0;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   🌉 FB_CfgPersistBridge_DredgingAssistCfg — Pont IHM/persistance prélèvement
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK FB_CfgPersistBridge_DredgingAssistCfg
VAR_IN_OUT
    Hmi     : ST_DredgingAssistCfg;
    Persist : ST_DredgingAssistCfg;
END_VAR
VAR_OUTPUT
    JustRestored : BOOL;
END_VAR

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   ⚙️ FB_Translation — Directeur de l'axe transversal M3 (variateur AC600)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF/AF_Partie-11_Fonction_Translation_v2.2.md
   🔌 FB DE MOUVEMENT : porte StartStop + SafeStop en plus de l'interface
      standard. Précédence Enable > SafeStop > StartStop.
   Pilotage exclusivement ETHERCAT nominal (mot de commande, consigne fréquence).
   🧩 Compose FB_Brake (réutilisé TEL QUEL depuis COMMUN).
   🎯 Invariant : toute inversion de sens force la cible de rampe à 0.0 tant que le
      changement de sens est en attente, pour garantir le croisement du seuil d'arrêt
      qui autorise l'interlock de changement de sens (§5).
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Translation
VAR_INPUT
    Enable                      : BOOL;        // --> [CMD] Active le FB. FALSE = neutralisation totale (sorties coupées)
    Reset                       : BOOL;        // --> [CMD] Acquittement défaut (front)
    PowerContactorEngaged             : BOOL;        // --> [SAFE] Chaîne AU réarmée + conditions globales OK
    Mode                        : E_Mode;      // --> [CMD] Mode courant
    StartStop                   : BOOL;        // --> [CMD] TRUE = rampe accélération, FALSE = rampe décélération NORMALE
    SafeStop                    : BOOL;        // --> [SAFE] Sortie FB_Safety_Translation : TRUE = rampe décélération RAPIDE (Enable maintenu)
    Direction                   : INT;         // --> [CMD] -1 = Rev, 0 = Neutre, +1 = Fwd (source d'autorité du sens)
    SpeedRefPct                 : REAL;        // --> [CMD] Magnitude de la consigne (de 0 à 100%)
    PositionSensorTarget        : BOOL;        // --> [HW] Capteur position cible courante
    // 3 capteurs déclencheurs de ralentissement, un cran avant chaque cible
    // (même principe que PV→Trémie, généralisé — voir §4bis dans le corps ST)
    SlowdownSensorTremie         : BOOL;        // --> [HW] Capteur PV — ralentissement avant Trémie (Direction=1)
    SlowdownSensorMaintenance    : BOOL;        // --> [HW] Capteur P1 — ralentissement avant Maintenance (Direction=-1)
    SlowdownSensorP1             : BOOL;        // --> [HW] Capteur P2 — ralentissement avant P1 (Direction=-1, arrêt propre pour travail)
    LimitSwitchFwd              : BOOL;        // --> [HW] Fin de course extrême avant
    LimitSwitchRev              : BOOL;        // --> [HW] Fin de course extrême arrière

    // 🔌 Spécifique ETHERCAT (image process EtherCAT, rafraîchie par EtherCatTask 4ms)
    DriveStatusWord              : WORD;       // --> [HW] Mot d'état AC600 lu depuis l'image d'entrée EtherCAT
    DriveActualFreqHz            : REAL;       // --> [HW] Fréquence réelle mesurée (Hz)

    BypassContactorCheck         : BOOL;       // --> [TST] TRUE = désactive StuckClosed/StuckOpen pour le frein (simulation)
    BypassLimitSwitch            : BOOL;       // --> [TST] TRUE = ignore les fins de course extrêmes
    BrakeFeedback                : BOOL;       // --> [HW] Retour physique direct : TRUE = frein OUVERT (desserré)
    // Compense le câblage moteur (U/V inversés) — UNIQUEMENT sur le mot de commande variateur
    // en sortie (§5bis). Direction/CommandedDirection reste partout ailleurs le sens SÉMANTIQUE
    // réel (+1 = physiquement vers Trémie), pour rester apparié aux vrais capteurs
    // (LimitSwitchFwd/Rev, SlowdownSensorXxx) quel que soit le câblage.
    InvertDriveDirection          : BOOL;

    // Réglages rampe (RETAIN)
    CfgRampAccelRate                : REAL := 20.0;    // --> [CFG] %/s — accélération
    CfgRampDecelNormalRate          : REAL := 40.0;    // --> [CFG] %/s — décélération normale
    CfgRampDecelFastRate            : REAL := 100.0;   // --> [CFG] %/s — décélération RAPIDE
    DirectionInterlockDelay      : TIME := T#200ms; // --> [CFG] Délai avant d'autoriser un changement de sens à l'arrêt

    // Réglages ETHERCAT uniquement (RETAIN)
    ApproachSpeedTremieHz        : REAL := 10.0;    // --> [CFG] Vitesse réduite d'approche Trémie en Hz (piloté par SlowdownSensorTremie)
    ApproachSpeedMaintenanceHz   : REAL := 10.0;    // --> [CFG] Vitesse réduite d'approche Maintenance en Hz (piloté par SlowdownSensorMaintenance)
    ApproachSpeedP1Hz            : REAL := 10.0;    // --> [CFG] Vitesse réduite d'approche P1 en Hz (piloté par SlowdownSensorP1)
    DriveFreqScaleMaxHz          : REAL := 60.0;    // --> [CFG] Échelle 0..100 % → MaxHz (câblé depuis _TranslationMaxFreq_Hz par PRG_07 — defaut 60.0 si non raccordé)

    // Réglages communs
    CaptorDebounce                : TIME := T#100ms; // --> [CFG] Filtrage capteur de position cible
    BrakeDelayContactClose        : TIME := T#100ms; // --> [CFG] Voir FB_Brake
    BrakeDelayMagnetise           : TIME := T#300ms; // --> [CFG] Voir FB_Brake
    BrakeDelayMotorDecel          : TIME := T#500ms; // --> [CFG] Voir FB_Brake
    BrakeFeedbackTimeout          : TIME := T#300ms; // --> [CFG] Strictement sous watchdog final 500 ms
END_VAR
VAR_OUTPUT
    Ready               : BOOL;   // <-- [STAT] FB prêt (sortie libre, hors ST_FbStatus)
    // 🧩 Statut transverse (forme cible) — regroupe Busy/Done/Error/ErrorId/State/StateAtError.
    // ErrorId bit0: "Défaut frein Translation" ; bit3: "Défaut variateur AC600" ; bit6: "Limite extrême".
    Status              : ST_FbStatus;
    TargetReached        : BOOL;       // <-- [STAT] Capteur position cible
    RequestedDriveControlWord : WORD; // <-- [ACT] Demande métier AC600, arbitrée par FB_TranslationOutputInterlock
    RequestedDriveFreqHz      : REAL; // <-- [ACT] Demande métier fréquence, arbitrée par FB_TranslationOutputInterlock
    BrakeReleaseRequest       : BOOL; // <-- [ACT] Demande métier desserrage, issue de FB_Brake
    BrakeCommandOpenConfirmed : BOOL; // <-- [STAT] TRUE = frein ouvert = commande ouverture confirmée (depuis FB_Brake)
    BrakeContactorCheck  : ST_ContactorCheck; // <-- [DIAG] Diag contacteur frein
END_VAR
VAR
    Brake                : FB_Brake;       // * [INST] Séquence frein
    CycleTimeCalc        : FB_CycleTime;   // * [INST] Mesure temps de cycle
    SpeedRamp             : FB_Ramp;       // * [INST] Rampe de vitesse logicielle (PLC)
    ResetEdge            : R_TRIG;   // . [LOC] Front Reset
    ErrorEdge            : R_TRIG;   // . [LOC] Front Erreur
    DirectionChangeDelay : TON;            // . [LOC] Interlock changement de sens
    CommandedDirection   : INT;            // . [LOC] Sens réellement appliqué
    DirectionChangePending : BOOL;         // . [LOC] Force la rampe à 0 pendant une inversion de sens en attente
    PhysicalDriveDirection : INT;          // . [LOC] CommandedDirection compensé câblage (InvertDriveDirection) — UNIQUEMENT pour le mot de commande variateur, jamais pour l'appariement capteur
    RampTargetPct        : REAL;   // . [LOC] Cible rampe en %
    CaptorDebounceTon     : TON;    // . [LOC] Debounce capteur cible
    ArrivalEdge            : R_TRIG;   // . [LOC] Front arrivée sur capteur
    DirectionAtArrival     : INT;    // . [LOC] Sens d'arrivée mémorisé
    ArrivalLock             : BOOL;        // . [LOC] Arrêt exact sur capteur cible
    MovementRequested      : BOOL;         // . [LOC] Pilote FB_Brake
    FirstScanDone          : BOOL;   // . [LOC] Initialisation premier scan
    // Garde-fou watchdog : DriveActualFreqHz est un passthrough EtherCAT sans contrôle de fraîcheur.
    // Si la communication variateur se fige sur une dernière valeur ≥1.0 Hz, plus rien ne referme
    // le frein tant que ce garde-fou n'existe pas — même si SafeStop a déjà ramené la rampe théorique
    // à 0. Force le relâchement du frein 2s après la fin de la rampe théorique, quoi que dise
    // DriveActualFreqHz.
    TonBrakeRealFreqTimeout : TON;
END_VAR

// === IMPLEMENTATION ===

{region "§1 Gate et initialisation"}
// 🛑 1. GATE (Enable / PowerContactorEngaged) — neutralisation totale, sorties sûres
IF NOT Enable OR NOT PowerContactorEngaged THEN
    RequestedDriveControlWord := 0; RequestedDriveFreqHz := 0.0;

    Brake(Enable := FALSE, Reset := FALSE, MovementRequested := FALSE, ContactorFeedback := BrakeFeedback,
          DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
          DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout);
    BrakeReleaseRequest := Brake.BrakeCmd;
    BrakeCommandOpenConfirmed := Brake.BrakeCommandOpenConfirmed;
    BrakeContactorCheck := Brake.ContactorCheck;

    CommandedDirection := 0;
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    SpeedRamp(Target := 0.0, AccelRate := CfgRampAccelRate, DecelRate := CfgRampDecelFastRate, CycleTimeS := CycleTimeCalc.CycleTimeS);

    ArrivalLock := FALSE;

    Status.State := E_State.DISABLED;
    Ready := FALSE; Status.Busy := FALSE; Status.Done := FALSE;
    RETURN;
END_IF;

// 🧹 Initialisation au premier scan : purge des résidus RAM d'un Online Change / Warm Start et évitement des alarmes transitoires
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    Status.ErrorId := 16#0000;
    RETURN;
END_IF;

{endregion}

{region "§2 Acquisition commandes et position cible"}
Ready := TRUE;
CycleTimeCalc(DefaultValueS := 0.010);   // MainTask = 10 ms

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 📡 3. CAPTEUR POSITION CIBLE (debounce)
CaptorDebounceTon(IN := PositionSensorTarget, PT := CaptorDebounce);
TargetReached := CaptorDebounceTon.Q;

{endregion}

{region "§4 Consigne vitesse ralentissement verrou arrivee"}
// ⚙️ 4. CORE — arbitrage rampe : Enable > SafeStop > StartStop
// DirectionChangePending FORCE la cible à 0.0 dès qu'une inversion de sens est en attente —
// sans cela, la cible suit la magnitude joystick en continu et ne croise jamais le seuil
// d'arrêt (0.1%) qui autorise l'interlock §5 à basculer CommandedDirection. Une inversion
// plus rapide que la décélération réelle bloquerait indéfiniment le mouvement dans l'ancien sens.
DirectionChangePending := (Direction <> CommandedDirection) AND (CommandedDirection <> 0);

RampTargetPct := 0.0;
IF NOT SafeStop AND StartStop AND NOT DirectionChangePending THEN
    // Si butée fin de course extrême atteinte dans le sens de marche demandé, consigne forcée à 0
    // 🌐 BypassLimitSwitch = TRUE → ignore cette protection
    IF NOT BypassLimitSwitch AND ((Direction = 1 AND LimitSwitchFwd) OR (Direction = -1 AND LimitSwitchRev)) THEN
        RampTargetPct := 0.0;
    ELSE
        RampTargetPct := ABS(SpeedRefPct);
        // 🎚️ Consigne minimale joystick (1.0 Hz) : si un mouvement est demandé (SpeedRefPct > 0.0), la consigne est au moins égale à 1.0 Hz
        IF RampTargetPct > 0.0 THEN
            RampTargetPct := MAX(RampTargetPct, (1.0 / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
        END_IF;
    END_IF;
END_IF;

// ⏱️ 4bis. RALENTISSEMENT AUTO À L'APPROCHE (piloté par capteur)
// Chaque capteur "un cran avant" la cible finale déclenche SA propre vitesse réduite, dans SON
// sens de marche uniquement — le ralentissement ne se déclenche qu'à l'approche de sa cible :
//   PV       + Direction=1  → approche Trémie
//   P1       + Direction=-1 → approche Maintenance
//   P2       + Direction=-1 → approche P1 (arrêt propre pour travail)
IF (Direction = 1) AND SlowdownSensorTremie THEN
    RampTargetPct := LIMIT(0.0, RampTargetPct, (ApproachSpeedTremieHz / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
END_IF;
IF (Direction = -1) AND SlowdownSensorMaintenance THEN
    RampTargetPct := LIMIT(0.0, RampTargetPct, (ApproachSpeedMaintenanceHz / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
END_IF;
IF (Direction = -1) AND SlowdownSensorP1 THEN
    RampTargetPct := LIMIT(0.0, RampTargetPct, (ApproachSpeedP1Hz / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
END_IF;

// 🎯 4ter. VERROUILLAGE ANTI-REBONDS SENS EN BUTÉE (Trémie, P1, Maintenance, Fdc extrêmes)
// Dès qu'on touche un capteur d'arrêt (TargetReached, débounce 100ms) OU un fin de course dur
// (LimitSwitchFwd/Rev, §5bis — immédiat, non débounce, mais toute activation même brève arme le
// même verrou), le sens d'arrivée (DirectionAtArrival) est MÉMORISÉ et BLOQUÉ. Toute activation,
// même un instant, arme DirectionAtArrival comme un TargetReached — un Fdc qui s'ouvre quelques ms
// pendant le freinage ne doit pas laisser la rampe (encore haute en interne) revenir en sortie.
ArrivalEdge(CLK := TargetReached
                 OR (LimitSwitchFwd AND (CommandedDirection = 1))
                 OR (LimitSwitchRev AND (CommandedDirection = -1)));
IF ArrivalEdge.Q THEN
    DirectionAtArrival := CommandedDirection;
END_IF;

// Un retour au neutre, même SOUTENU (>100ms), ne doit JAMAIS lever le verrou — seul un vrai
// changement de sens (dégagement volontaire, sans ambiguïté) le fait. Sinon, un neutre 100ms+
// puis un réappui dans le MÊME sens (le capteur/Fdc restant au niveau haut en continu,
// TargetReached ne montre plus de front) contournerait le verrou et M3 repartirait vers la butée.
// On doit repartir dans l'AUTRE sens, jamais juste relâcher-réappuyer pareil. Instantané, jamais
// retardé (le dégagement doit rester rapide).
IF (Direction = DirectionAtArrival * (-1)) OR ResetEdge.Q OR (NOT TargetReached AND NOT LimitSwitchFwd AND NOT LimitSwitchRev) THEN
    DirectionAtArrival := 0;
END_IF;

// Bloque la consigne à 0 tant que l'ordre demande d'insister dans le sens d'arrivée verrouillé
ArrivalLock := (DirectionAtArrival <> 0) AND (Direction = DirectionAtArrival);
IF ArrivalLock THEN
    RampTargetPct := 0.0;
END_IF;

SpeedRamp(Target := RampTargetPct,
          AccelRate := CfgRampAccelRate,
          DecelRate := SEL(SafeStop, CfgRampDecelNormalRate, CfgRampDecelFastRate),
          CycleTimeS := CycleTimeCalc.CycleTimeS);

{endregion}

{region "§5 Interlock changement sens"}
// 🔒 5. INTERLOCK CHANGEMENT DE SENS — jamais Fwd+Rev simultanés (vitesse confirmée nulle)
IF Direction <> CommandedDirection THEN
    IF CommandedDirection = 0 AND Direction <> 0 THEN
        CommandedDirection := Direction;
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    ELSIF ABS(SpeedRamp.Current) < 0.1 THEN
        DirectionChangeDelay(IN := TRUE, PT := DirectionInterlockDelay);
        IF DirectionChangeDelay.Q THEN
            CommandedDirection := Direction;
            DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
        END_IF;
    ELSE
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    END_IF;
ELSE
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
END_IF;

{endregion}

{region "§5bis Commande variateur et protections fin course"}
// 🛑 Pilotage du frein : le mouvement est considéré actif tant que la consigne est supérieure à 0.1%
// OU que la fréquence réelle mesurée du variateur M3 est >= 1.0 Hz.
// Le frein de parking ne serre QUE lorsque la fréquence réelle variateur chute sous 1.0 Hz !
// Borné par un garde-fou 2s — DriveActualFreqHz n'a aucun contrôle de fraîcheur EtherCAT ; si la
// communication se fige sur une valeur ≥1.0 Hz (perte réseau en mouvement), rien d'autre en aval
// ne referme le frein (FB_TranslationOutputInterlock ignore volontairement SafeStop par
// conception). Le garde-fou force la fermeture du frein 2s après la fin de la rampe THÉORIQUE, quoi
// que dise la mesure réelle — combine attente réelle (évite un serrage sur arbre encore tournant)
// et certitude de fermeture (n'attend jamais indéfiniment).
TonBrakeRealFreqTimeout(IN := NOT ((CommandedDirection <> 0) AND (ABS(SpeedRamp.Current) > 0.1)), PT := T#2s);
MovementRequested := ((CommandedDirection <> 0) AND (ABS(SpeedRamp.Current) > 0.1))
                     OR (ABS(DriveActualFreqHz) >= 1.0 AND NOT TonBrakeRealFreqTimeout.Q);

// 🔀 5bis. SORTIE PHYSIQUE (ETHERCAT)
RequestedDriveFreqHz := (ABS(SpeedRamp.Current) / 100.0) * DriveFreqScaleMaxHz;

// Compensation câblage moteur appliquée ICI SEULEMENT, sur le mot de commande —
// CommandedDirection (sécurité/capteurs juste au-dessus, §4/§4bis/§4ter) reste le sens réel.
PhysicalDriveDirection := SEL(InvertDriveDirection, CommandedDirection, CommandedDirection * (-1));

// Pilotage nominal Given Command 1 (0x3101) :
// 0: None, 1: Forward, 2: Reverse, 7: Reset
IF Reset THEN
    RequestedDriveControlWord := 7; // Reset défaut variateur
ELSIF Status.Error THEN
    RequestedDriveControlWord := 0; // Arrêt sur défaut
ELSIF MovementRequested THEN
    IF PhysicalDriveDirection = 1 THEN
        RequestedDriveControlWord := 1; // Marche avant
    ELSIF PhysicalDriveDirection = -1 THEN
        RequestedDriveControlWord := 2; // Marche arrière
    ELSE
        RequestedDriveControlWord := 0;
    END_IF;
ELSE
    RequestedDriveControlWord := 0;
END_IF;

// Sécurité : si Fdc extrême atteint dans le sens de marche, coupure commande immédiate (sans rampe ni couple)
// 🌐 BypassLimitSwitch = TRUE → ignore cette protection (test/mise en service)
IF NOT BypassLimitSwitch AND ((CommandedDirection = 1 AND LimitSwitchFwd) OR (CommandedDirection = -1 AND LimitSwitchRev)) THEN
    RequestedDriveControlWord := 0;
    RequestedDriveFreqHz := 0.0;
    SpeedRamp(Target := 0.0, AccelRate := 0.0, DecelRate := 100000.0, CycleTimeS := 1.0);
END_IF;

{endregion}

{region "§6 Commande frein"}
// 🛑 6. FREIN (composé, réutilisé tel quel)
Brake(Enable := TRUE, Reset := Reset, MovementRequested := MovementRequested,
      ContactorFeedback := BrakeFeedback,
      DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
      DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout,
      BypassContactorCheck := BypassContactorCheck);
BrakeReleaseRequest := Brake.BrakeCmd;
BrakeCommandOpenConfirmed := Brake.BrakeCommandOpenConfirmed;
BrakeContactorCheck := Brake.ContactorCheck;

// 🛡️ FB_Translation ne décide plus la frontière finale : il expose uniquement
// ses demandes métier. SafeStop est déjà appliqué dans la rampe rapide §4 : tant que
// la vitesse ne vaut pas zéro, la demande et le desserrage suivent la décélération.
// FB_TranslationOutputInterlock ne doit jamais transformer SafeStop en coupure sèche.

{endregion}

{region "§7 Diagnostic etat et repli defaut"}
// 🧾 7. ERRORID (bitfield, cumul)
IF Brake.Status.Error THEN
    Status.ErrorId := Status.ErrorId OR 16#0001;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFFE;
END_IF;

// Défaut variateur (bit3) : lu via EtherCAT (DriveStatusWord.4)
IF DriveStatusWord.4 THEN
    Status.ErrorId := Status.ErrorId OR 16#0008;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFF7;
END_IF;

// 🚧 Défaut fin de course extrême (bit6) — si bypassé, on NETTOIE le bit résiduel
IF BypassLimitSwitch THEN
    Status.ErrorId := Status.ErrorId AND 16#FFBF;   // Nettoie le bit 6 (évite résidu d'avant activation)
ELSE
    // Activé UNIQUEMENT en cas de tentative d'avancer vers la butée active (libéré si dégagement en sens inverse)
    IF (CommandedDirection = 1 AND LimitSwitchFwd) OR (CommandedDirection = -1 AND LimitSwitchRev) THEN
        Status.ErrorId := Status.ErrorId OR 16#0040;
    ELSE
        Status.ErrorId := Status.ErrorId AND 16#FFBF;
    END_IF;
END_IF;

Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;

// 🚦 8. STATE MACHINE (phase)
IF (NOT StartStop OR SafeStop) AND ABS(SpeedRamp.Current) > 0.1 THEN
    Status.State := E_State.STOPPING;
ELSIF ABS(SpeedRamp.Current) > 0.1 THEN
    Status.State := E_State.BUSY;
ELSE
    Status.State := E_State.READY;
END_IF;

Status.Busy := (Status.State = E_State.BUSY) OR (Status.State = E_State.STOPPING);
Status.Done := FALSE;

// 🛡️ 9. SORTIE SÛRE SUR DÉFAUT
IF Status.Error THEN
    RequestedDriveControlWord := 0; RequestedDriveFreqHz := 0.0;
    BrakeReleaseRequest := FALSE;
END_IF;

{endregion}

(* ═══════════════════════════════════════════════════════════════
   🔄 PRG_05_Cycle — Séquenceur du Cycle Automatique / Semi-Auto (Grafcet)
   ───────────────────────────────────────────────────────────────
   ⚙️ Exécuté par la tâche PLC en position 5.
   ✅ Gère la machine d'état principale de dragage (FB_Cycle).
   ═══════════════════════════════════════════════════════════════
   📄 Docs : DOC/AF_Partie-04_Mode_SemiAuto_Sequenceur_v2.0.md
*)

PROGRAM PRG_05_Cycle
VAR
    // Instance du séquenceur automatique
    instCycle           : FB_Cycle;

    // Commandes issues de la supervision (IHM)
    CmdStartCycle_IHM   : BOOL;         // Lancement cycle automatique
    CmdPauseCycle_IHM   : BOOL;         // Pause cycle automatique
    CmdAbortCycle_IHM   : BOOL;         // Abandon / arrêt cycle automatique
    CmdResetCycle_IHM   : BOOL;         // 🔧 REX 2026-07-07 : reset dédié FB_Cycle, jamais mélangé au reset défauts général

    // Paramètres cibles réglés par l'opérateur
    SetDepthM        : REAL := -12.5; // Profondeur de dragage cible (mètres, négative)
    SetOffsetM       : REAL := 1.5;  // Décalage cible de fermeture du benne (mètres)
    CycleMotionPermit    : BOOL;        // Homme-mort + axe Y actif
    // 🧪 T43 — paramètres provisoirement désactivés ; à définir avec T45.
    SpeedMismatchThresholdMps : REAL := 0.0;
    SpeedMismatchTimeout      : TIME := T#0ms;
END_VAR

// === IMPLEMENTATION (corps du PROGRAM PRG_05_Cycle) ===

// 🕹️ Interface unique de commande cycle depuis GVL_IHM.
CmdStartCycle_IHM := GVL_IHM.Cycle.Cmd.BtnStart;
CmdPauseCycle_IHM := GVL_IHM.Cycle.Cmd.BtnPause;
CmdAbortCycle_IHM := GVL_IHM.Cycle.Cmd.BtnAbort;
CmdResetCycle_IHM := GVL_IHM.Cycle.Cmd.BtnReset;
SetDepthM      := GVL_IHM.Cycle.Cfg.SetDepth_M;
SetOffsetM     := GVL_IHM.Cycle.Cfg.SetOffset_M;
CycleMotionPermit := PRG_01_Diagnostics.instJoystick.DeadmanArmed
                     AND PRG_01_Diagnostics.instJoystick.AxisCmdY.StartStop;

// Appel du séquenceur de cycle principal avec tous ses raccordements
instCycle(
    // 🔧 REX 2026-07-19 : suppression IHM_MANU — Mode=SEMI_AUTO suffit seul (les modes
    // sont mutuellement exclusifs dans FB_Modes, plus besoin d'un flag ManuActive séparé).
    Enable              := (PRG_MODES_CFC.Auth.Mode = E_Mode.SEMI_AUTO),
    CycleMotionPermit   := CycleMotionPermit,
    HeartbeatIhmOk      := PRG_01_Diagnostics.instIhmHeartbeat.HeartbeatIhmOk,
    Reset               := CmdResetCycle_IHM,
    PowerContactorEngaged     := PRG_01_Inputs_LD.PowerContactorEngaged,

    StartCycle          := CmdStartCycle_IHM,
    PauseCycle          := CmdPauseCycle_IHM,
    AbortCycle          := CmdAbortCycle_IHM,

    SetDepthM        := SetDepthM,
    SetOffsetM       := SetOffsetM,
    SelectedTargetNum_IHM := GVL_IHM.TranslationM3.Cmd.SelTarget,

    // Retour dédié Kobold — distinct du mou de câble.
    KoboldContactFond   := PRG_01_Inputs_LD.KoboldContactFond,
    LimitLegalReached   := GVL_IHM.Commun.LimitLegalReached,
    LimitLegalDepthM    := GVL_IHM.Commun.Cfg.LimitLegalDepthMinAllowed_M,
    WinchSyncError      := PRG_TREUILS_CFC.instWinchSync.Error,
    WinchSyncDeltaM     := PRG_TREUILS_CFC.instWinchSync.DeltaPosM,
    M1_CablePosM        := PRG_02_Encoders.instEncoderScaleM1.CablePosM,
    M2_CablePosM        := PRG_02_Encoders.instEncoderScaleM2.CablePosM,
    M1_MeasuredSpeedMps := PRG_02_Encoders.M1MeasuredSpeed_Mps,
    M2_MeasuredSpeedMps := PRG_02_Encoders.M2MeasuredSpeed_Mps,
    SpeedMismatchThresholdMps := SpeedMismatchThresholdMps,
    SpeedMismatchTimeout      := SpeedMismatchTimeout,
    CableLimitM1AscentM       := _WinchM1CfgPersist.CfgCableLimitAscent_M,

    // Position translation — 🆕 REX 2026-07-18 : Fosse1/Fosse2 renommés P1/P2 (AF_Partie-02 v2.12 §3bis)
    Translation_At_P1       := PRG_02_Acquisition_CFC.TranslationPosP1,
    Translation_At_P2       := PRG_02_Acquisition_CFC.TranslationPosP2,
    Translation_At_Maintenance := PRG_02_Acquisition_CFC.TranslationPosMaintenance,
    Translation_At_Tremie   := PRG_02_Acquisition_CFC.TranslationPosTremie,
    Translation_Busy        := PRG_TRANSLATION_CFC.instTranslationM3.Busy,
    Translation_Done        := PRG_TRANSLATION_CFC.instTranslationM3.Done,

    // Mouvements mâchoires benne (gérés par instBucket)
    Benne_Busy        := PRG_TREUILS_CFC.instBucket.Busy,
    Benne_Done        := PRG_TREUILS_CFC.instBucket.Done,
    Benne_IsOpen      := _BucketState.IsOpen,
    Benne_IsClosed    := _BucketState.IsClosed
);

GVL_IHM.Cycle.State.SpeedMismatch_Mps       := instCycle.SpeedMismatchMps;
GVL_IHM.Cycle.State.SpeedMismatchActive     := instCycle.SpeedMismatchActive;
GVL_IHM.Cycle.State.SpeedMismatchConfirmed  := instCycle.SpeedMismatchConfirmed;

// 🧹 Les commandes restent impulsionnelles même si GVL_IHM est RETAIN.
GVL_IHM.Cycle.Cmd.BtnStart := FALSE;
GVL_IHM.Cycle.Cmd.BtnPause := FALSE;
GVL_IHM.Cycle.Cmd.BtnAbort := FALSE;
GVL_IHM.Cycle.Cmd.BtnReset := FALSE;

END_PROGRAM

(* ═══════════════════════════════════════════════════════════════
   🪣 FB_Bucket — Commande d'ouverture/fermeture du benne
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-10_Fonction_Winch/FB_Bucket_v1.0.md
   🔌 Conforme au contrat FB standard (Partie3 §1bis).
   ⚠️ REX 2026-07-07 : inversion du sens moteur M2 constatée sur site
      (ré-câblage/relabel %Q0.0 et %Q0.3) → ENROULAGE M2 (Direction=+1)
      FERME désormais le benne, DEROULAGE M2 (Direction=-1) l'OUVRE
      (c'était l'inverse avant). Voir DOC/AF_Partie-10_Fonction_Winch/FB_Bucket_v1.0.md §REX.
   ⚠️ REX 2026-07-07 (2) : ajout du garde-fou HomedM1/HomedM2 — CablePosM1/M2
      ne sont fiables que si les codeurs absolus sont référencés (Partie10).
      Sans ça, une position aberrante (codeur non homé) pourrait faire
      mémoriser un IsOpen/IsClosed faux dès l'entrée en BUSY.
   🔧 REX 2026-07-07 (3) : Méca C couche 1 (bit4) — M1 DOIT rester immobile pendant
      que M2 bouge seul. Si M1 glisse de plus de M1SlipToleranceM (1.0 m) pendant
      BUSY → SevereError (coupe M2 via le mécanisme existant) + sortie dédiée
      M1SlipDetected (à consommer côté PRG_TREUILS_CFC pour forcer SafeStop
      sur M1 spécifiquement — FB_Bucket ne pilote pas M1). Couche de secours si
      cette couche ne suffit pas : voir FB_Safety_Winch bit9 (tolérance 2.0 m,
      escalade PowerCutOff).
   🆕 REX 2026-07-08 (mise en service, demande utilisateur) :
      - `ConfirmOpenPosition` : bouton IHM dédié de RÉFÉRENCEMENT du benne en position ouverte
        (mise en service). Action de CONFIRMATION pure (aucun mouvement) — mémorise
        BucketState.IsOpen directement, à utiliser juste après le référencement des codeurs
        M1/M2 (les 2 à la même valeur, benne physiquement ouvert vérifié par l'opérateur —
        voir DOC/AF_Partie-09_Fonction_Encoder_v2.1.md "flux nominal, benne ouvert").
        Remplace le contournement précédent (un BtnOpen qui se terminait par coïncidence car la
        cible était déjà atteinte) par une action explicite et auditable. Même principe que
        `BtnConfirmCoherence` dans FB_Encoder_Homing (front, gardée par Mode MAINT_N1/N2).
   🆕 REX 2026-07-08 (audit sécurité, demande utilisateur) :
      - `M1_Busy`/`M2_Busy` : la demande d'ouverture/fermeture n'est acceptée (mémorisation
        `CloseReq`/`OpenReq` + transition vers BUSY) QUE si les deux treuils sont à l'arrêt —
        tous modes. Avant ce correctif, rien ne le garantissait ; un mouvement manuel sur M1
        pouvait "traverser" l'armement du benne (trou détecté par audit automatisme/IHM).
      - Sens inverse borné pendant BUSY : l'opérateur peut désormais pousser le joystick dans
        le sens opposé au sens principal (recul/annulation partielle), mais UNIQUEMENT jusqu'à
        la position M2 mémorisée au démarrage de la demande (`M2StartPosM`) — jamais au-delà
        (pas de réouverture/refermeture complète depuis ce sens inverse).
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Bucket
VAR_INPUT
    Enable              : BOOL;             // Activation générale
    Reset               : BOOL;             // Acquittement défauts (front)
    PowerContactorEngaged     : BOOL;             // Condition d'arrêt d'urgence
    Mode                : E_Mode;           // Mode de marche machine
    CmdOpen_IHM         : BOOL;             // Demande d'ouverture depuis l'IHM
    CmdClose_IHM        : BOOL;             // Demande de fermeture depuis l'IHM
    MotionRequestActive : BOOL;             // Intention mouvement déjà arbitrée (joystick ou boutons IHM)
    MotionDirection     : INT;              // Sens arbitré : 1=montée, -1=descente
    CablePosM1          : REAL;             // Position réelle câble treuil M1 (mètres)
    CablePosM2          : REAL;             // Position réelle câble treuil M2 (mètres)
    HomedM1             : BOOL;             // Codeur M1 référencé (instHomingM1.Homed) — REX 2026-07-07
    HomedM2             : BOOL;             // Codeur M2 référencé (instHomingM2.Homed) — REX 2026-07-07
    Config              : ST_BucketConfig; // Configuration (RETAIN site)
    CfgTimeoutDuration     : TIME := T#30s;    // Timeout de mouvement configurable
    M1SlipToleranceM    : REAL := 1.0;      // 🔧 REX 2026-07-07 : tolérance glissement M1 pendant Busy (m)
    M1_Busy             : BOOL;             // 🆕 REX 2026-07-08 : instWinchM1.Busy — doit être à l'arrêt pour armer une demande
    M2_Busy             : BOOL;             // 🆕 REX 2026-07-08 : instWinchM2.Busy — doit être à l'arrêt pour armer une demande
     ConfirmOpenPosition : BOOL;             // 🆕 REX 2026-07-08 : bouton IHM référencement benne ouvert (front, mise en service — voir bandeau)
     ConfirmClosePosition : BOOL;            // 🆕 REX 2026-07-08 : bouton IHM référencement benne fermé (front, mise en service)
     InhibitM1           : BOOL;             // 🆕 REX 2026-07-08 : M1 est inhibé
     InhibitM2           : BOOL;             // 🆕 REX 2026-07-08 : M2 est inhibé
     BypassGlobal        : BOOL := FALSE;    // 🌐 TRUE = force ErrorId=0, ignore toutes les erreurs benne
 END_VAR
VAR_OUTPUT
    Ready               : BOOL;             // FB prêt à fonctionner
    Busy                : BOOL;             // Mouvement en cours
    Done                : BOOL;             // Mouvement terminé avec succès
    Error               : BOOL;             // Présence d'un défaut
    ErrorId             : WORD;             // bit0: "Timeout mouvement benne" - Timeout mouvement, bit1: "Incohérence position benne" - Incohérence boot, bit2: "Limites placement benne dépassées" - Limites dépassées, bit3: "Codeur(s) benne non référencé(s)" - Codeur(s) M1/M2 non référencé(s), bit4: "Glissement M1 détecté" - Glissement M1 pendant Busy
    M1SlipDetected      : BOOL;             // 🔧 REX 2026-07-07 : à consommer côté PRG_TREUILS_CFC (force SafeStop M1)
    CloseReq            : BOOL;             // 🆕 REX 2026-07-08 : demande de fermeture mémorisée — image IHM (FALSE = pas de demande active
                                             // ou objectif atteint/retour position départ ; TRUE = demande armée ou mouvement en cours)
    OpenReq             : BOOL;             // 🆕 REX 2026-07-08 : demande d'ouverture mémorisée — même principe
    State               : E_State;          // État opérationnel du FB
    StateAtError        : E_State;          // État lors de l'apparition de l'erreur
    ActiveOffsetM       : REAL;             // Décalage cible à injecter dans FB_WinchSync
    M2_StartStop        : BOOL;             // Sortie consigne StartStop vers Winch M2
    M2_Direction        : INT;              // Sortie consigne Direction vers Winch M2
    M2_ForceSlowSpeed   : BOOL;             // TRUE = Bloque les contacteurs de vitesse de M2
    RemainingTravelM    : REAL;             // 🔧 REX 2026-07-07 : distance restante avant cible (m, toujours
                                             // positive, décroît vers 0) — 0.0 hors mouvement (READY/DONE)
END_VAR
VAR_IN_OUT
    BucketState        : ST_BucketState;  // État physique du benne mémorisé (RETAIN)
END_VAR
VAR
    FirstCycle          : BOOL := TRUE;     // Drapeau de premier cycle API
    ResetEdge           : R_TRIG;           // Détecteur de front montant Reset
    ErrorEdge           : R_TRIG;           // Détecteur de front montant Error
    TonTimeout          : TON;              // Temporisateur de timeout de mouvement
    SevereError         : BOOL;             // Erreur grave nécessitant l'arrêt
    MaxAllowedOffset    : REAL;             // Offset max calculé dynamiquement
    BusyEdge            : R_TRIG;           // 🔧 REX 2026-07-07 — détecte l'entrée en Busy (arme la réf. M1)
    M1RefPosM           : REAL;             // 🔧 REX 2026-07-07 — position M1 mémorisée à l'entrée en Busy
    M2StartPosM         : REAL;             // 🆕 REX 2026-07-08 — position M2 mémorisée à l'entrée en Busy (borne le recul autorisé)
    WasOpenAtStart      : BOOL;             // 🆕 REX 2026-07-08 — état IsOpen mémorisé à l'entrée en Busy (restauré si recul complet)
    WasClosedAtStart    : BOOL;             // 🆕 REX 2026-07-08 — état IsClosed mémorisé à l'entrée en Busy (restauré si recul complet)
    LeftStartSinceArm   : BOOL;             // 🆕 REX 2026-07-08 — a réellement quitté la position de départ (évite un retour instantané au 1er cycle Busy)
    ConfirmOpenEdge     : R_TRIG;           // 🆕 REX 2026-07-08 — détecteur de front ConfirmOpenPosition
    ConfirmCloseEdge    : R_TRIG;           // 🆕 REX 2026-07-08 — détecteur de front ConfirmClosePosition
END_VAR

// 🛑 1. GATE DE SÉCURITÉ
IF NOT Enable OR NOT PowerContactorEngaged THEN
    IF (State = E_State.BUSY) OR CloseReq OR OpenReq THEN
        BucketState.StateIncoherent := TRUE;
    END_IF;
    Ready := FALSE;
    Busy := FALSE;
    Done := FALSE;
    M2_StartStop := FALSE;
    M2_Direction := 0;
    M2_ForceSlowSpeed := FALSE;
    State := E_State.DISABLED;
    M1SlipDetected := FALSE; // 🔧 REX 2026-07-07
    // Les requêtes internes sont réinitialisées
    CloseReq := FALSE;
    OpenReq := FALSE;
    RETURN;
END_IF;

// 🟢 ÉTAT INITIAL READY SI DISABLED PRÉCÉDEMMENT
IF State = E_State.DISABLED THEN
    State := E_State.READY;
END_IF;

// 🔑 2. GESTION DU RESET (FRONT MONTANT)
ResetEdge(CLK := Reset);

// 🌐 BYPASS GLOBAL : force ErrorId = 0 (ignore toutes les erreurs benne)
IF BypassGlobal THEN
    ErrorId := 16#0000;
END_IF;

IF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFA; // Efface les bits 0 et 2 (Timeout, Limites)
END_IF;

// 📏 3. DÉTECTION D'INCOHÉRENCE AU BOOT (PREMIER CYCLE API)
IF FirstCycle THEN
    FirstCycle := FALSE;
    IF Config.CoherenceLimitM > 0.01 THEN
        IF BucketState.IsOpen AND NOT BucketState.IsClosed THEN
            IF ABS(CablePosM2 - BucketState.LastPosM2Open) > Config.CoherenceLimitM THEN
                BucketState.StateIncoherent := TRUE;
            END_IF;
        ELSIF BucketState.IsClosed AND NOT BucketState.IsOpen THEN
            IF ABS(CablePosM2 - BucketState.LastPosM2Close) > Config.CoherenceLimitM THEN
                BucketState.StateIncoherent := TRUE;
            END_IF;
        ELSE
            // Si l'état n'a jamais été initialisé (les deux FALSE/TRUE), on signale une incohérence
            BucketState.StateIncoherent := TRUE;
        END_IF;
    ELSE
        // Limite non configurée ou invalide, par précaution on force l'incohérence
        BucketState.StateIncoherent := TRUE;
    END_IF;
END_IF;

// Met à jour le bit1 d'erreur si incohérence détectée
IF BucketState.StateIncoherent THEN
    ErrorId := ErrorId OR 16#0002;
    // 🆕 REX 2026-07-08 : Force l'état inconnu (ni ouvert ni fermé) si incohérence active
    BucketState.IsOpen := FALSE;
    BucketState.IsClosed := FALSE;
ELSE
    ErrorId := ErrorId AND 16#FFFD;
END_IF;

// 🧲 3bis. GARDE-FOU CODEURS NON RÉFÉRENCÉS (bit 3) — REX 2026-07-07
// CablePosM1/CablePosM2 ne sont fiables que si le homing (Partie10) a été fait sur les 2 treuils.
// Continu (pas de front Reset) : se lève/efface tout seul selon l'état réel du homing.
IF NOT HomedM1 OR NOT HomedM2 THEN
    ErrorId := ErrorId OR 16#0008;
ELSE
    ErrorId := ErrorId AND 16#FFF7;
END_IF;

// 🆕 3bis-bis. CONFIRMATION MANUELLE POSITION OUVERTE (mise en service, REX 2026-07-08) — voir bandeau
// Action de CONFIRMATION pure (aucun mouvement, ne pilote pas M2) : mémorise BucketState.IsOpen
// directement, à utiliser juste après le référencement des codeurs (M1=M2, benne physiquement
// ouvert vérifié par l'opérateur). Gardée comme BtnConfirmCoherence (FB_Encoder_Homing) : front,
// MAINT_N1/N2 uniquement, codeurs déjà référencés, treuils à l'arrêt (pas de séquence en cours).
ConfirmOpenEdge(CLK := ConfirmOpenPosition);
IF ConfirmOpenEdge.Q
   AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2)
   AND NOT M1_Busy AND NOT M2_Busy THEN
    BucketState.IsOpen := TRUE;
    BucketState.IsClosed := FALSE;
    BucketState.LastPosM2Open := CablePosM2;
    BucketState.LastPosM2Close := CablePosM2 - Config.OffsetOpenM + Config.OffsetCloseM; // 🆕 Initialisation théorique cohérente avec les offsets configurés
    BucketState.StateIncoherent := FALSE;
    ErrorId := 16#0000;             // 🆕 REX 2026-07-08 : Réinitialisation complète des défauts benne lors du référencement manuel
    CloseReq := FALSE;              // 🆕 REX 2026-07-08 : Reset des demandes en attente pour éviter les démarrages intempestifs
    OpenReq := FALSE;
END_IF;

// 🆕 3bis-ter. CONFIRMATION MANUELLE POSITION FERMÉE (mise en service, REX 2026-07-08)
// Même principe que ConfirmOpenPosition, mais pour initialiser le benne comme FERMÉ.
ConfirmCloseEdge(CLK := ConfirmClosePosition);
IF ConfirmCloseEdge.Q
   AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2)
   AND NOT M1_Busy AND NOT M2_Busy THEN
    BucketState.IsOpen := FALSE;
    BucketState.IsClosed := TRUE;
    BucketState.LastPosM2Close := CablePosM2;
    BucketState.LastPosM2Open := CablePosM2 - Config.OffsetCloseM + Config.OffsetOpenM; // 🆕 Initialisation théorique cohérente avec les offsets configurés
    BucketState.StateIncoherent := FALSE;
    ErrorId := 16#0000;             // 🆕 REX 2026-07-08 : Réinitialisation complète des défauts benne lors du référencement manuel
    CloseReq := FALSE;              // 🆕 REX 2026-07-08 : Reset des demandes en attente pour éviter les démarrages intempestifs
    OpenReq := FALSE;
END_IF;

// 🆕 3bis-quater. DÉTECTION AUTOMATIQUE EN CONTINU (REX 2026-08-07, demande client) : contrairement
// aux 2 blocs ConfirmXxx ci-dessus (action MANUELLE ponctuelle), ceci recalcule IsOpen/IsClosed en
// PERMANENCE dès que les positions correspondent à un état connu -- sans bouton, sans mode MAINT
// requis. Nécessaire car les séquencements automatiques (PRG_04, "descente uniquement benne
// ouverte") s'appuient sur BucketState.IsOpen/IsClosed : si les positions convergent SANS passer
// par une séquence FB_Bucket commandée (ex. recalage manuel en pilotage unitaire, ou positions
// déjà alignées au premier boot), l'état restait bloqué à FALSE indéfiniment sans action opérateur
// -- bloquant en pratique une fois le séquencement auto en place. Actif uniquement à l'arrêt
// (NOT M1_Busy/M2_Busy), hors séquence benne en cours (State <> BUSY, où IsOpen/IsClosed sont
// volontairement forcés à FALSE par BusyEdge ci-dessus -- ne rentre jamais en conflit), codeurs
// référencés. Réutilise la tolérance déjà existante Config.CoherenceLimitM -- pas de nouveau seuil.
IF (State <> E_State.BUSY) AND NOT M1_Busy AND NOT M2_Busy AND HomedM1 AND HomedM2
   AND (Config.CoherenceLimitM > 0.01) THEN
    IF ABS((CablePosM2 - CablePosM1) - Config.OffsetOpenM) <= Config.CoherenceLimitM THEN
        IF NOT BucketState.IsOpen THEN
            BucketState.IsOpen := TRUE;
            BucketState.IsClosed := FALSE;
            BucketState.LastPosM2Open := CablePosM2;
            BucketState.StateIncoherent := FALSE;
        END_IF;
    ELSIF ABS((CablePosM2 - CablePosM1) - Config.OffsetCloseM) <= Config.CoherenceLimitM THEN
        IF NOT BucketState.IsClosed THEN
            BucketState.IsClosed := TRUE;
            BucketState.IsOpen := FALSE;
            BucketState.LastPosM2Close := CablePosM2;
            BucketState.StateIncoherent := FALSE;
        END_IF;
    // 🔴🔧 REX 2026-08-07 (21) — retour terrain, BUG CONFIRMÉ : IsOpen/IsClosed restait figé sur
    // sa dernière valeur mémorisée quand la position s'éloignait des DEUX fenêtres (aucune des 2
    // IF/ELSIF ci-dessus ne match) -- ex. jog unitaire M2 loin de la position ouverte/fermée sans
    // repasser par instBucket. L'IHM affichait "ouvert" alors que la position réelle n'avait plus
    // rien à voir. Corrigé : hors des 2 fenêtres connues, l'état devient explicitement inconnu.
    ELSE
        IF BucketState.IsOpen OR BucketState.IsClosed THEN
            BucketState.IsOpen := FALSE;
            BucketState.IsClosed := FALSE;
            BucketState.StateIncoherent := TRUE;
        END_IF;
    END_IF;
END_IF;

// 🔍 3ter. MÉCA C COUCHE 1 — GLISSEMENT M1 PENDANT BUSY (bit4) — REX 2026-07-07
// M1 doit rester immobile pendant que M2 bouge seul. Référence prise à l'entrée en Busy.
BusyEdge(CLK := (State = E_State.BUSY));
IF BusyEdge.Q THEN
    M1RefPosM := CablePosM1;
    M2StartPosM := CablePosM2;   // 🆕 REX 2026-07-08 — borne le recul autorisé (voir §6 CASE BUSY)
    // 🆕 REX 2026-07-08 (demande utilisateur) : mémorise l'état d'origine (restauré si recul complet
    // jusqu'à M2StartPosM, voir §6 CASE BUSY) puis passe en position transitoire dès le démarrage du
    // mouvement — ni ouvert ni fermé pendant le trajet, quel que soit l'état mémorisé avant.
    WasOpenAtStart := BucketState.IsOpen;
    WasClosedAtStart := BucketState.IsClosed;
    LeftStartSinceArm := FALSE;
    BucketState.IsOpen := FALSE;
    BucketState.IsClosed := FALSE;
END_IF;

IF (State = E_State.BUSY) AND (ABS(CablePosM1 - M1RefPosM) > M1SlipToleranceM) AND NOT InhibitM1 THEN
    ErrorId := ErrorId OR 16#0010;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFEF;
END_IF;
M1SlipDetected := (ErrorId AND 16#0010) <> 16#0000;

// 🚨 4. SURVEILLANCE DES LIMITES DE PLACEMENT (Limites dépassées - bit 2)
// On s'assure que l'écart réel M1/M2 ne dépasse pas les offsets de configuration + marge de sécurité de 1m
MaxAllowedOffset := MAX(ABS(Config.OffsetOpenM), ABS(Config.OffsetCloseM)) + 1.0;
IF (ABS(CablePosM1 - CablePosM2) > MaxAllowedOffset) AND NOT InhibitM1 AND NOT InhibitM2 THEN
    ErrorId := ErrorId OR 16#0004;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFB;
END_IF;

// ⏲️ 5. SURVEILLANCE TIMEOUT MOUVEMENT (bit 0)
// Déclenche si le mouvement actif (M2_StartStop = TRUE) dure plus longtemps que le timeout
TonTimeout(IN := (State = E_State.BUSY AND M2_StartStop), PT := CfgTimeoutDuration);
IF TonTimeout.Q THEN
    ErrorId := ErrorId OR 16#0001;
END_IF;

// ❌ Évaluation des erreurs graves (Timeout, Limites dépassées, Codeur(s) non référencé(s), ou Glissement M1)
SevereError := (ErrorId AND 16#001D) <> 16#0000;

IF SevereError THEN
    IF (State = E_State.BUSY) OR CloseReq OR OpenReq THEN
        BucketState.StateIncoherent := TRUE;
    END_IF;
    M2_StartStop := FALSE;
    M2_Direction := 0;
    M2_ForceSlowSpeed := FALSE;
    CloseReq := FALSE;
    OpenReq := FALSE;
    // On repasse en READY et attend un Reset
    State := E_State.READY;
END_IF;

// 🎛️ 6. MACHINE À ÉTATS DE COMMANDE
CASE State OF
    E_State.READY:
        Ready := TRUE;
        Busy := FALSE;
        Done := FALSE;
        M2_StartStop := FALSE;
        M2_Direction := 0;
        M2_ForceSlowSpeed := FALSE;
        RemainingTravelM := 0.0; // 🔧 REX 2026-07-07 : pas de mouvement en cours

        // 🆕 REX 2026-07-08 : demande benne acceptée UNIQUEMENT si M1 ET M2 sont à l'arrêt (tous
        // modes) — évite qu'un mouvement en cours sur l'un des deux treuils "traverse" l'armement
        // du benne (audit sécurité). Ni mémorisation de la requête, ni démarrage tant que ce
        // n'est pas vrai — l'opérateur doit refaire la demande une fois les treuils arrêtés.
        IF NOT M1_Busy AND NOT M2_Busy THEN
            // Mémorisation des requêtes IHM (l'une annule l'autre)
            IF CmdClose_IHM AND NOT SevereError THEN
                CloseReq := TRUE;
                OpenReq := FALSE;
            ELSIF CmdOpen_IHM AND NOT SevereError THEN
                OpenReq := TRUE;
                CloseReq := FALSE;
            END_IF;

            // Condition d'activation du mouvement (Requête IHM + Validation Joystick dans le bon sens)
            // ⚠️ REX 2026-07-07 : sens inversés (enroulage ferme désormais, déroulage ouvre)
            IF CloseReq AND MotionRequestActive AND (MotionDirection = 1) THEN
                State := E_State.BUSY;
            ELSIF OpenReq AND MotionRequestActive AND (MotionDirection = -1) THEN
                State := E_State.BUSY;
            END_IF;
        END_IF;

    E_State.BUSY:
        Ready := TRUE;
        Busy := TRUE;
        Done := FALSE;
        M2_ForceSlowSpeed := TRUE; // Vitesse lente forcée sans contacteurs

        // 📏 REX 2026-07-07 : distance restante avant cible, pour affichage IHM (aiguille/jauge)
        // Toujours positive, décroît vers 0 à mesure que M2 approche la cible.
        IF CloseReq THEN
            RemainingTravelM := MAX(0.0, (CablePosM1 + Config.OffsetCloseM) - CablePosM2);
        ELSIF OpenReq THEN
            RemainingTravelM := MAX(0.0, CablePosM2 - (CablePosM1 + Config.OffsetOpenM));
        ELSE
            RemainingTravelM := 0.0;
        END_IF;

        // Interlock Homme-mort joystick
        // 🆕 REX 2026-07-08 : sens inverse autorisé (recul/annulation partielle) pendant CloseReq/
        // OpenReq, mais BORNÉ à la position de départ (M2StartPosM, mémorisée à l'entrée en Busy) —
        // ne permet jamais de dépasser cette position dans le sens opposé au sens principal.
        IF NOT MotionRequestActive THEN
            // Si relâchement de l'intention opérateur, arrêt temporaire du mouvement.
            M2_StartStop := FALSE;
            M2_Direction := 0;
        ELSIF CloseReq THEN
            IF (MotionDirection = 1) THEN
                // Sens principal (fermeture) : M2 enroule (monte) — REX 2026-07-07
                M2_StartStop := TRUE;
                M2_Direction := 1;
            ELSIF (MotionDirection = -1) AND (CablePosM2 > M2StartPosM) THEN
                // Sens inverse : recul autorisé UNIQUEMENT tant qu'on n'est pas revenu à la position
                // de départ (pas au-delà, donc pas de ré-ouverture complète depuis ici)
                M2_StartStop := TRUE;
                M2_Direction := -1;
            ELSE
                // Mauvais sens, ou position de départ déjà atteinte en reculant : arrêt
                M2_StartStop := FALSE;
                M2_Direction := 0;
            END_IF;
        ELSIF OpenReq THEN
            IF (MotionDirection = -1) THEN
                // Sens principal (ouverture) : M2 déroule (descend) — REX 2026-07-07
                M2_StartStop := TRUE;
                M2_Direction := -1;
            ELSIF (MotionDirection = 1) AND (CablePosM2 < M2StartPosM) THEN
                // Sens inverse : recul autorisé UNIQUEMENT tant qu'on n'est pas revenu à la position
                // de départ (pas au-delà, donc pas de re-fermeture complète depuis ici)
                M2_StartStop := TRUE;
                M2_Direction := 1;
            ELSE
                M2_StartStop := FALSE;
                M2_Direction := 0;
            END_IF;
        ELSE
            M2_StartStop := FALSE;
            M2_Direction := 0;
        END_IF;

        // 🆕 REX 2026-07-08 : détecte qu'on a réellement quitté la position de départ (évite que le
        // test de retour ci-dessous ne se déclenche instantanément au 1er cycle de Busy, où
        // CablePosM2 = M2StartPosM par définition).
        IF (CloseReq AND (CablePosM2 > M2StartPosM)) OR (OpenReq AND (CablePosM2 < M2StartPosM)) THEN
            LeftStartSinceArm := TRUE;
        END_IF;

        // Condition d'arrêt automatique de la fermeture
        IF CloseReq THEN
            // 🔴🔧 REX 2026-08-07 (20) — retour terrain : inertie mécanique (M2 continue sur sa
            // lancée après StartStop:=FALSE) faisait dépasser la cible réelle. Coupe la commande
            // CloseAnticipationM avant OffsetCloseM -- le coast-down amène l'arrêt réel près du
            // vrai offset au lieu de le dépasser.
            IF CablePosM2 >= (CablePosM1 + Config.OffsetCloseM - Config.CloseAnticipationM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                // Mémorisation de l'état physique fermé
                BucketState.IsOpen := FALSE;
                BucketState.IsClosed := TRUE;
                BucketState.LastPosM2Close := CablePosM2;
                BucketState.StateIncoherent := FALSE; // recalage réussi

                CloseReq := FALSE;
                State := E_State.DONE;
            // 🆕 REX 2026-07-08 (demande utilisateur) : recul complet jusqu'à la position de départ —
            // restaure l'état d'origine (physiquement, on est revenu là où on a commencé)
            ELSIF LeftStartSinceArm AND (CablePosM2 <= M2StartPosM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                BucketState.IsOpen := WasOpenAtStart;
                BucketState.IsClosed := WasClosedAtStart;

                CloseReq := FALSE;
                State := E_State.DONE;
            END_IF;
        END_IF;

        // Condition d'arrêt automatique de l'ouverture
        IF OpenReq THEN
            // 🔴🔧 REX 2026-08-07 (20) — retour terrain : même logique que la fermeture ci-dessus,
            // inertie différente en ouverture (OpenAnticipationM distinct).
            IF CablePosM2 <= (CablePosM1 + Config.OffsetOpenM + Config.OpenAnticipationM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                // Mémorisation de l'état physique ouvert
                BucketState.IsOpen := TRUE;
                BucketState.IsClosed := FALSE;
                BucketState.LastPosM2Open := CablePosM2;
                BucketState.StateIncoherent := FALSE; // recalage réussi

                OpenReq := FALSE;
                State := E_State.DONE;
            // 🆕 REX 2026-07-08 (demande utilisateur) : recul complet jusqu'à la position de départ —
            // restaure l'état d'origine (physiquement, on est revenu là où on a commencé)
            ELSIF LeftStartSinceArm AND (CablePosM2 >= M2StartPosM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                BucketState.IsOpen := WasOpenAtStart;
                BucketState.IsClosed := WasClosedAtStart;

                OpenReq := FALSE;
                State := E_State.DONE;
            END_IF;
        END_IF;

    E_State.DONE:
        Ready := TRUE;
        Busy := FALSE;
        Done := TRUE;
        M2_StartStop := FALSE;
        M2_Direction := 0;
        M2_ForceSlowSpeed := FALSE;
        RemainingTravelM := 0.0; // 🔧 REX 2026-07-07 : cible atteinte

        // Attente du relâchement de la validation joystick pour repasser à READY
        IF NOT MotionRequestActive THEN
            State := E_State.READY;
        END_IF;
END_CASE;

// 📤 7. GESTION DES SORTIES D'ÉTAT GLOBALES
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// Détermination de l'offset actif pour le synchronisme de FB_WinchSync ET pour l'affichage IHM
// (M2PositionCorrected, côté PRG_SUPERVISION_CFC).
// 🔧 REX 2026-07-08 : ajout de CloseReq/OpenReq (pas seulement IsClosed/IsOpen, qui sont FALSE
// pendant TOUT le trajet depuis le REX du 2026-07-08 sur l'état transitoire) — sinon
// ActiveOffsetM restait figé sur OffsetOpenM (défaut) pendant le trajet entier d'une fermeture,
// donc M2PositionCorrected = CablePosM2 brut tout du long, avec un saut brutal uniquement à
// l'arrivée (constat terrain) au lieu de converger progressivement vers M1 pendant l'enroulage.
IF State = E_State.BUSY THEN
    // 🔧 REX 2026-07-08 : pendant le déplacement, l'offset actif suit la différence réelle
    // de câble (M2 - M1) afin que la position corrigée de M2 reste stable (égale à M1, cad la hauteur du benne)
    // sans à-coup, tandis que le câble brut de M2 montre son enroulement.
    ActiveOffsetM := CablePosM2 - CablePosM1;
ELSIF CloseReq OR BucketState.IsClosed THEN
    ActiveOffsetM := Config.OffsetCloseM;
ELSE
    // Par défaut, ou en cours/état d'ouverture, on applique l'offset ouvert
    ActiveOffsetM := Config.OffsetOpenM;
END_IF;

(* =======================================================================
   🛡️ FB_Safety_Winch — Surveillance et sécurité d'un treuil (M1 / M2)
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Protection machine, surveillance codeurs, dérives et interlocks
   📄 Doc métier : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md
   🔒 Sécurité : Gestion des autorisations SafeStop, PowerCutOff et permis
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_Safety_Winch
VAR_INPUT
    // === COMMANDES ET ETATS GENERAL ===
    Enable                          : BOOL;                           // --> [CMD] Active la surveillance globale FB
    Reset                           : BOOL;                           // --> [CMD] Front acquittement defauts
    Mode                            : E_Mode;                         // --> [CMD] Mode d'exploitation actif
    SyncEnable                      : BOOL;                           // --> [CMD] Validation synchronisation treuils
    Direction                       : INT;                            // --> [CMD] Consigne active de direction (-1/0/+1)
    MovementCommanded               : BOOL;                           // --> [CMD] Au moins un contacteur de sens commande

    // === ETATS SECOURS ET HARDWARE ===
    PowerContactorEngaged           : BOOL;                           // --> [SAFE] Chaine AU rearmee + puissance OK
    JoystickOnline                  : BOOL;                           // --> [HW] Statut bus CAN Joystick Online
    JoystickOperational             : BOOL;                           // --> [HW] Statut bus CAN Joystick Operational
    HeartbeatIhmOk                  : BOOL;                           // --> [HW] Communication IHM-PLC valide
    EncoderAvailable                : BOOL;                           // --> [HW] Codeur disponible pour ce treuil
    ThermalFeedback                 : BOOL;                           // --> [HW] Retour thermique moteur (NC)
    BrakeThermalFeedback            : BOOL;                           // --> [HW] Retour thermique frein (NC)
    SlackCableDetected              : BOOL;                           // --> [HW] Delecteur mou de cable (NC)
    PhaseRotationOk                 : BOOL;                           // --> [HW] Sens de rotation des phases OK
    TopPositionSensor               : BOOL;                           // --> [HW] Capteur fin de course haut (NC)
    FwdRevSpeedFeedbackOff          : BOOL;                           // --> [HW] Feedback retombe tous contacteurs
    BrakeFeedback                   : BOOL;                           // --> [HW] Feedback frein ouvert
    JoystickYNeutral                : BOOL;                           // --> [HW] Joystick au neutre
    BenneHoldStillActive            : BOOL;                           // --> [HW] Maintien fixe M1 actif pendant benne
    BenneBusy                       : BOOL;                           // --> [HW] Cycle benne actif sur l'autre treuil
    OtherWinchInhibited             : BOOL;                           // --> [HW] Autre treuil inhibe (maintenance)

    // === REGLAGES ET LIMITES SÉCURITÉ ===
    InReferencingMode               : BOOL;                           // --> [CFG] Treuil en cours de homing
    CablePosM                       : REAL;                           // --> [CFG] Position actuelle cable (m)
    CfgCableLimitDescentM           : REAL;                           // --> [CFG] Limite basse physique descente (m)
    LimitLegalReached               : BOOL;                           // --> [CFG] Limite legale de profondeur atteinte
    Homed                           : BOOL;                           // --> [CFG] Treuil reference
    HomingSuspect                   : BOOL;                           // --> [CFG] Referencement suspect
    TopLimitM                       : REAL;                           // --> [CFG] Position limite haute active (m)
    UncommandedSpeedThresholdMps    : REAL := 0.02;                   // --> [CFG] Seuil vitesse non commandee Meca A (m/s)
    UncommandedDriftToleranceM      : REAL := 2.0;                    // --> [CFG] Tolerance derive position Meca A (m)
    PostRampTimeout                 : TIME := T#3s;                   // --> [CFG] Delai attente retombee contacteurs/frein Meca B
    BenneSlipToleranceM             : REAL := 2.0;                    // --> [CFG] Tolerance glissement M1 pendant benne (m)
    ExpectedOtherWinchPosM          : REAL;                           // --> [CFG] Position attendue de l'autre treuil (m)
    CriticalSyncToleranceM          : REAL := 2.5;                    // --> [CFG] Tolerance ecart critique synchro (m)
    MovementSpeedThresholdMps       : REAL := 0.02;                   // --> [CFG] Seuil vitesse mesurable (m/s)
    MeasuredSpeedMps                : REAL;                           // --> [CFG] Mesure absolue vitesse (m/s)
    MeasuredSpeedSignedMps          : REAL;                           // --> [CFG] Mesure signee vitesse (m/s)
    MeasuredSpeedValid              : BOOL;                           // --> [CFG] Mesure vitesse valide
    OppositeDirectionTimeout        : TIME := T#500ms;                // --> [CFG] Delai confirmation sens oppose
    NoMovementTimeout               : TIME := T#3s;                   // --> [CFG] Delai confirmation absence mouvement

    // === BYPASSES ET SIMULATION ===
    EncoderFaultBypass              : BOOL;                           // --> [TST] Bypass defaut codeur
    BypassGlobal                    : BOOL := FALSE;                  // --> [TST] Force ErrorId=0 global
    BypassSafety                    : BOOL := FALSE;                  // --> [TST] Bypass groupe PowerCutOff
    BypassProcess                   : BOOL := FALSE;                  // --> [TST] Bypass groupe SafeStop/Permit
    BypassTopLimitSwitch            : BOOL := FALSE;                  // --> [TST] Bypass individuel fin de course haut capteur
    BypassTopLimitSoftware          : BOOL := FALSE;                  // --> [TST] Bypass individuel fin de course haut logiciel
    BypassCableLimitSwitch          : BOOL := FALSE;                  // --> [TST] Bypass individuel limite basse cable
    BypassLimitLegal                : BOOL := FALSE;                  // --> [TST] Bypass individuel limite legale
    BypassOperatorComm              : BOOL := FALSE;                  // --> [TST] Bypass perte com operateur
    BypassPhaseRotation             : BOOL := FALSE;                  // --> [TST] Bypass defaut rotation phases
    BypassBrakeThermal              : BOOL := FALSE;                  // --> [TST] Bypass surchauffe frein
    BypassMotorThermal              : BOOL := FALSE;                  // --> [TST] Bypass surchauffe moteur
    BypassMecaA                     : BOOL := FALSE;                  // --> [TST] Bypass Meca A
    BypassMecaB                     : BOOL := FALSE;                  // --> [TST] Bypass Meca B
    BypassMecaC                     : BOOL := FALSE;                  // --> [TST] Bypass Meca C
    BypassMecaD                     : BOOL := FALSE;                  // --> [TST] Bypass Meca D
    BypassMecaE                     : BOOL := FALSE;                  // --> [TST] Bypass Meca E
END_VAR
VAR_OUTPUT
    // === ETATS IEC ET SYNOPTIQUE ===
    Ready                           : BOOL;                           // <-- [STAT] FB pret a fonctionner
    Busy                            : BOOL;                           // <-- [STAT] Traitement securite en cours
    Done                            : BOOL;                           // <-- [STAT] Action terminee
    Error                           : BOOL;                           // <-- [STAT] Synthese defaut
    ErrorId                         : WORD;                           // <-- [DIAG] Code erreur bitmask (0..15)
    State                           : E_State;                        // <-- [STAT] Etat courant machine d'etat FB
    StateAtError                    : E_State;                        // <-- [DIAG] Etat memorise lors du dernier defaut

    // === SORTIES DE SÉCURITÉ ET AUTORISATIONS ===
    SafeStop                        : BOOL;                           // <-- [SAFE] Arret rapide 2 sens (Enable maintenu)
    DescendPermit                   : BOOL;                           // <-- [SAFE] Permis de descente autorise
    AscentPermit                    : BOOL;                           // <-- [SAFE] Permis de montee autorise
    PowerCutOff                     : BOOL;                           // <-- [SAFE] Coupure puissance amont

    // === DIAGNOSTICS ET MESURES ===
    MecaADriftM                     : REAL;                           // <-- [DIAG] Derive mesuree Meca A (m)
    MecaCDriftM                     : REAL;                           // <-- [DIAG] Derive mesuree Meca C (m)
    MecaBElapsedTime                : TIME;                           // <-- [DIAG] Ecoule confirmation contacteurs/frein
END_VAR
VAR
    // === SOUS-INSTANCES FB ===
    DriftGuardA                     : FB_DriftGuard;                  // * [INST] Surveillance derive Meca A
    DriftGuardC                     : FB_DriftGuard;                  // * [INST] Surveillance derive Meca C

    // === DETECTEURS ET TIMERS INTERNES ===
    ResetEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Reset
    ErrorEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Erreur
    TonMecaB                        : TON;                            // . [LOC] Tempo confirmation arret Meca B
    TonMecaD                        : TON;                            // . [LOC] Tempo arret fin de course haut Meca D
    TonMecaE                        : TON;                            // . [LOC] Tempo confirmation arret synchro Meca E
    TonOppositeDirection            : TON;                            // . [LOC] Tempo confirmation sens oppose
    TonNoMovement                   : TON;                            // . [LOC] Tempo confirmation absence mouvement
    TonStartupWarmup                : TON;                            // . [LOC] Tempo masquage transitoire au boot

    // === VARIABLES LOCALES INTERNES ===
    FirstScanDone                   : BOOL;                           // . [LOC] Premier cycle effectue
    MecaB_NoOperatorCmd             : BOOL;                           // . [LOC] Absence commande operateur
    LastInReferencingMode           : BOOL;                           // . [LOC] Memorisation etat homing precedent
    OppositeDirectionActive         : BOOL;                           // . [LOC] Sens oppose confirme actif
    EncoderAvailableEffective       : BOOL;                           // . [LOC] Codeur valide ou bypass effectif
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Safety_Winch) ===

{region "§1 Gate neutralisation"}
// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    Ready := FALSE;
    Busy := FALSE;
    Done := FALSE;
    SafeStop := TRUE;
    DescendPermit := FALSE; // 🛡️ Fail-Safe : aucun mouvement permis si Safety désactivé
    AscentPermit := FALSE;  // 🛡️ Fail-Safe : aucun mouvement permis si Safety désactivé
    PowerCutOff := FALSE;
    State := E_State.DISABLED;
    Error := FALSE;
    ErrorId := 16#0000;
    // Force le réarmement (WasArmed→FALSE) via FB_DriftGuard.
    DriftGuardA(Arm := FALSE, PositionM := CablePosM, ToleranceM := UncommandedDriftToleranceM);
    DriftGuardC(Arm := FALSE, PositionM := CablePosM, ToleranceM := BenneSlipToleranceM);
    TonMecaB(IN := FALSE);
    TonMecaD(IN := FALSE);
    TonMecaE(IN := FALSE);
    TonOppositeDirection(IN := FALSE);
    TonNoMovement(IN := FALSE);
    TonStartupWarmup(IN := FALSE);
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;

{endregion}

{region "§2 Initialisation et bypass global"}
// Détecte la fin du référencement pour éviter le pic de vitesse au cycle de transition (offset appliqué)
IF LastInReferencingMode AND NOT InReferencingMode THEN
    DriftGuardA(Arm := FALSE, PositionM := CablePosM, ToleranceM := UncommandedDriftToleranceM);
END_IF;
LastInReferencingMode := InReferencingMode;

// Si le contacteur de puissance est ouvert (PowerContactorEngaged = FALSE), on force les sorties de sécurité
// mais on ne fait pas de RETURN pour permettre le diagnostic et l'acquittement (Reset) des défauts.
IF NOT PowerContactorEngaged THEN
    DriftGuardA(Arm := FALSE, PositionM := CablePosM, ToleranceM := UncommandedDriftToleranceM);
    DriftGuardC(Arm := FALSE, PositionM := CablePosM, ToleranceM := BenneSlipToleranceM);
END_IF;

// 🔑 2. RESET FRONT — efface le bit dont la cause a disparu
ResetEdge(CLK := Reset);

// 🧹 Initialisation au premier scan : évitement des alarmes transitoires au démarrage
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

// 🌐 BYPASS GLOBAL : si TRUE, on force ErrorId = 0 ET on saute toute la logique de sécurité
IF BypassGlobal THEN
    ErrorId := 16#0000;
    TonMecaB(IN := FALSE);
    TonMecaD(IN := FALSE);
    TonOppositeDirection(IN := FALSE);
    TonMecaE(IN := FALSE);
END_IF;

{endregion}

{region "§3 Protections immediates position"}
// 🔍 3sexties. FIN DE COURSE HAUT / CAPTEUR DE POSITION HAUTE (anti-débordement) — bit5
// ⚠️ Convention NAMING_CONVENTION.md : TopPositionSensor TRUE = sain/non atteint (NF), FALSE =
// position haute réellement atteinte (contact ouvert). Si la position haute EST atteinte
// (TopPositionSensor=FALSE), qu'on n'est pas en phase de référencement (homing), ET qu'on
// commande un mouvement vers le haut (Direction > 0), alors on lève le défaut.
// SORTI du bloc "IF NOT BypassGlobal" ci-dessous — même doctrine que le blocage réel (§4) :
// BypassGlobal M1/M2 ne doit masquer NI le mouvement NI l'alarme IHM de ces 2 fins de course
// physiques. Seuls BypassProcess (groupé, conscient) ou BypassTopLimitSwitch (individuel)
// peuvent encore éteindre CETTE alarme — exactement comme tous les autres bypass individuels du
// fichier (une alarme ne s'éteint QUE si on a explicitement demandé à ignorer CETTE protection
// précise, jamais via le bypass global qui vise le reste du domaine : Méca A-E, thermique, phase,
// comm, sync, codeur).
IF NOT (BypassProcess OR BypassTopLimitSwitch) AND NOT TopPositionSensor AND NOT InReferencingMode AND (Direction > 0) THEN
    ErrorId := ErrorId OR 16#0020;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFDF;
END_IF;

// 🔍 3septies. LONGUEUR MAX DE CÂBLE (profondeur max autorisée) — bit6
// Sécurité active hors référencement. Si la position de câble descend sous la limite basse
// physique (CablePosM <= CfgCableLimitDescentM), alors on interdit uniquement la descente.
// SORTI du bloc "IF NOT BypassGlobal" — même doctrine que bit5 ci-dessus.
IF NOT (BypassProcess OR BypassCableLimitSwitch) AND (CfgCableLimitDescentM < 0.0) AND (CablePosM <= CfgCableLimitDescentM) AND NOT InReferencingMode THEN
    ErrorId := ErrorId OR 16#0040;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFBF;
END_IF;

{endregion}

{region "§4 Diagnostics et protections treuil"}
// 🔍 3. DIAGNOSTIC DU DOMAINE TREUIL (uniquement si bypass global désactivé)
IF NOT BypassGlobal THEN

    // ⏱️ Temporisation 3s de mise en route des bus de terrain au boot (CANopen / Modbus IHM)
    TonStartupWarmup(IN := Enable, PT := T#3s);

    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassOperatorComm) THEN
        IF (NOT JoystickOnline OR NOT JoystickOperational OR NOT HeartbeatIhmOk) THEN
            ErrorId := ErrorId OR 16#0001;       // Perte communication opérateur : joystick CAN ou heartbeat IHM absent
        ELSE
            ErrorId := ErrorId AND 16#FFFE;      // Effacement auto si la com repasse saine
        END_IF;
    ELSIF NOT TonStartupWarmup.Q THEN
        ErrorId := ErrorId AND 16#FFFE;          // Inhibition pendant l'initialisation boot
    END_IF;
    IF ResetEdge.Q THEN
        ErrorId := ErrorId AND 16#FFFE;
    END_IF;

// 🔍 3bis. PERTE CODEUR DE CE TREUIL
// Le fonctionnement sans codeur reste interdit par défaut.
// Le bypass est individuel, maintenu consciemment depuis l'IHM et strictement limité à MAINT_N2.
// Il ne masque aucun autre défaut du treuil et n'agit jamais sur l'autre instance.
EncoderAvailableEffective := EncoderAvailable
                             OR BypassGlobal
                             OR ((EncoderFaultBypass OR BypassProcess) AND (Mode = E_Mode.MAINT_N2));
IF NOT EncoderAvailableEffective THEN
    ErrorId := ErrorId OR 16#0002;
ELSE
    ErrorId := ErrorId AND 16#FFFD; (* Effacement auto si le codeur est dispo OU bypassé *)
END_IF;

// 🔍 3ter. SURCHAUFFE MOTEUR — bit2, participe au SafeStop total
// ET BypassMotorThermal — même doctrine que BypassBrakeThermal (§3sexies-ter),
// bypass dédié plutôt que de dépendre uniquement du bypass groupé BypassSafety.
IF NOT (BypassSafety OR BypassMotorThermal) AND ThermalFeedback THEN
    ErrorId := ErrorId OR 16#0004;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFB;
END_IF;

// 🔍 3quater. MOU DE CÂBLE (physiquement sur tambour M2, câblé sur les 2 instances Safety)
// Mode NORMAL (SyncEnable=TRUE) → SafeStop M1+M2 (bit3 inclus dans SafeStop)
// Mode RÉCUPÉRATION (SyncEnable=FALSE) → DescendPermit uniquement (descente interdite pour ne pas dérouler, montée OK pour retendre/fermer)
IF NOT BypassProcess AND SlackCableDetected THEN
    ErrorId := ErrorId OR 16#0008;
ELSIF ResetEdge.Q AND NOT SlackCableDetected THEN
    ErrorId := ErrorId AND 16#FFF7;
END_IF;

// 🔍 3quinquies. ROTATION DE PHASE —
// bit4, participe au SafeStop total (sens moteur potentiellement inversé, danger 2 sens).
IF NOT (BypassProcess OR BypassPhaseRotation) AND NOT PhaseRotationOk THEN
    ErrorId := ErrorId OR 16#0010;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFEF;
END_IF;

// 🔍 3octies. MÉCA A — MOUVEMENT NON COMMANDÉ GÉNÉRAL — bit7
// Armé quand tout est physiquement confirmé coupé (contacteurs + frein). Si dérive ou vitesse
// détectée pendant que c'est armé → roue libre / frein insuffisant.
// La chaîne codeur produit la mesure ; ce bloc safety la surveille seulement.
DriftGuardA(
    Arm        := MeasuredSpeedValid AND FwdRevSpeedFeedbackOff AND NOT BrakeFeedback AND NOT InReferencingMode,
    PositionM  := CablePosM,
    ToleranceM := UncommandedDriftToleranceM
);
MecaADriftM := DriftGuardA.DriftM;   // Diagnostic IHM

IF NOT (BypassSafety OR BypassMecaA) AND MeasuredSpeedValid AND (DriftGuardA.Violation OR (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback AND NOT InReferencingMode AND (MeasuredSpeedMps > UncommandedSpeedThresholdMps))) THEN
    ErrorId := ErrorId OR 16#0080;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FF7F;
END_IF;

// 🔍 3nonies. MÉCA B — PILOTAGE ACTIF SANS COMMANDE OPÉRATEUR — bit8
// Indépendant de FB_Winch (défense en profondeur). Perte CAN (bit0) OU joystick au neutre ;
// si les contacteurs OU LE FREIN ne confirment pas être retombés/serrés dans PostRampTimeout, défaut.
// Un frein qui ne confirme pas son engagement dans ce délai est tout aussi dangereux qu'un
// contacteur qui ne retombe pas (risque de mouvement/roue libre non détecté).
MecaB_NoOperatorCmd := (NOT JoystickOnline) OR (NOT JoystickOperational)
                       OR (NOT HeartbeatIhmOk) OR JoystickYNeutral;
TonMecaB(IN := NOT (BypassSafety OR BypassMecaB) AND MecaB_NoOperatorCmd AND NOT (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback), PT := PostRampTimeout);
MecaBElapsedTime := TonMecaB.ET;   // Diagnostic IHM
IF TonMecaB.Q THEN
    ErrorId := ErrorId OR 16#0100;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FEFF;
END_IF;

// 🔍 3decies. MÉCA C — GLISSEMENT M1 PENDANT BENNE, ESCALADE — bit9
// Armé UNIQUEMENT pour l'instance M1 (BenneHoldStillActive câblé sur instBucket.Busy côté M1
// seulement, toujours FALSE côté M2). Tolérance plus large que celle de FB_Bucket (1.0 m) —
// n'intervient que si la couche Benne (SafeStop M1 seul) n'a pas suffi.
// Dérive surveillée via FB_DriftGuard.
DriftGuardC(
    Arm        := NOT (BypassSafety OR BypassMecaC) AND BenneHoldStillActive,
    PositionM  := CablePosM,
    ToleranceM := BenneSlipToleranceM
);
MecaCDriftM := DriftGuardC.DriftM;   // Diagnostic IHM

IF DriftGuardC.Violation THEN
    ErrorId := ErrorId OR 16#0200;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FDFF;
END_IF;

// 🔍 3undecies. THERMIQUE FREIN COMMUN M1/M2/M3 — bit10
// Signal commun (1 seul fil, câblé identiquement sur les 3 instances Safety) : sa perte peut
// signifier qu'un frein colle instantanément (frein à manque de courant) → SafeStop ET
// PowerCutOff (voir bandeau en-tête).
IF NOT (BypassSafety OR BypassBrakeThermal) AND BrakeThermalFeedback THEN
    ErrorId := ErrorId OR 16#0400;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FBFF;
END_IF;

// 🔍 3duodecies. MÉCA D — ARRIVÉE CAPTEUR HAUT HORS RÉFÉRENCEMENT — bit11
// Complète le bit5 (AscentPermit immédiat) : arme la MÊME condition (capteur haut atteint, hors
// homing) mais avec un délai de confirmation, comme Méca B. Si les contacteurs ET le frein ne
// confirment pas être retombés/serrés dans PostRampTimeout après l'arrivée au capteur → défaut
// → SafeStop ET PowerCutOff (la coupure AscentPermit seule ne suffit pas à arrêter réellement
// le treuil : roue libre ou contacteur/frein défaillant).
TonMecaD(
    IN := NOT (BypassSafety OR BypassMecaD) AND ((((NOT TopPositionSensor AND NOT InReferencingMode) 
            OR (Homed AND NOT HomingSuspect AND (CablePosM >= (TopLimitM + 0.10))))
           AND (Direction >= 0)) // Neutralise la butée haute en descente (Direction = -1)
          AND NOT (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback)), 
    PT := PostRampTimeout
);
IF TonMecaD.Q THEN
    ErrorId := ErrorId OR 16#0800;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#F7FF;
END_IF;

// 🔍 3terdecies. MÉCA E — ÉCART SYNCHRO M1/M2 CRITIQUE — bits 12/13
// Couche INDÉPENDANTE de FB_WinchSync (écart mineur, 1er niveau) — défense en profondeur pour un
// écart VRAIMENT important. ExpectedOtherWinchPosM est DÉJÀ corrigé de l'offset benne actif par
// l'appelant : comparaison directe valable que le benne soit ouvert, fermé, ou absent du calcul.
// Suppression pendant BenneBusy (trajet actif = écart transitoire normal, pas un défaut),
// InReferencingMode (position pas fiable pendant homing) et OtherWinchInhibited (l'autre treuil
// en maintenance a une position figée, non comparable).
// Bit12 : détection → SafeStop immédiat. Bit13 : escalade si pas confirmé arrêté → PowerCutOff.
IF NOT (BypassProcess OR BypassMecaE) AND SyncEnable AND NOT BenneBusy AND NOT InReferencingMode AND NOT OtherWinchInhibited
   AND (ABS(CablePosM - ExpectedOtherWinchPosM) > CriticalSyncToleranceM) THEN
    ErrorId := ErrorId OR 16#1000;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#EFFF;
END_IF;

TonMecaE(IN := NOT (BypassSafety OR BypassMecaE) AND (((ErrorId AND 16#1000) <> 16#0000) AND NOT (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback)),
         PT := PostRampTimeout);
IF TonMecaE.Q THEN
    ErrorId := ErrorId OR 16#2000;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#DFFF;
END_IF;

// 🔍 3quaterdecies — SENS RÉEL OPPOSÉ À LA COMMANDE (bit14)
// Le signe de la vitesse câble est comparé à la direction commandée uniquement pendant un
// mouvement effectivement demandé. La temporisation filtre bruit codeur et inversion transitoire.
OppositeDirectionActive := NOT BypassProcess AND MeasuredSpeedValid AND (MovementCommanded AND NOT InReferencingMode
    AND (((Direction > 0) AND (MeasuredSpeedSignedMps < -MovementSpeedThresholdMps))
      OR ((Direction < 0) AND (MeasuredSpeedSignedMps > MovementSpeedThresholdMps))));
TonOppositeDirection(IN := OppositeDirectionActive, PT := OppositeDirectionTimeout);
IF TonOppositeDirection.Q THEN
    ErrorId := ErrorId OR 16#4000;
ELSIF ResetEdge.Q AND NOT OppositeDirectionActive THEN
    ErrorId := ErrorId AND 16#BFFF;
END_IF;

// ⏱️ 3quindecies — ABSENCE DE MOUVEMENT MALGRÉ COMMANDE (bit15)
// Détecte charge coincée, contacteur inefficace ou chaîne mécanique non entraînée. SafeStop seul :
// aucun retour ne justifie une coupure puissance brutale immédiate ; l'escalade reste matérielle.
TonNoMovement(
    IN := NOT BypassProcess AND MeasuredSpeedValid AND (MovementCommanded AND NOT InReferencingMode
          AND (ABS(MeasuredSpeedSignedMps) < MovementSpeedThresholdMps)),
    PT := NoMovementTimeout
);
IF TonNoMovement.Q THEN
    ErrorId := ErrorId OR 16#8000;
ELSIF ResetEdge.Q AND (NOT MeasuredSpeedValid OR NOT MovementCommanded OR (ABS(MeasuredSpeedSignedMps) >= MovementSpeedThresholdMps)) THEN
    ErrorId := ErrorId AND 16#7FFF;
END_IF;

END_IF; // fin IF NOT BypassGlobal

{endregion}

{region "§5 Arbitrage sorties securite"}
// 📤 4. ARBITRAGE DES SORTIES MAÎTRESSES
Error := (ErrorId <> 16#0000);       // 🧭 Partie3 §4 : miroir de TOUT le domaine, y compris mou de câble (visible IHM)
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// 🟧 SafeStop : bits 0/1/2/3/4 (joystick, codeur, thermique moteur, MOU CÂBLE, phases) + 7/8/9
// (Méca A/B/C) + 10 (thermique frein commun) + 11 (Méca D) + 12/13 (Méca E, écart synchro critique) ou si contacteur coupé
IF NOT PowerContactorEngaged THEN
    SafeStop := TRUE;
ELSIF NOT SyncEnable THEN
    SafeStop := (ErrorId AND 16#FF97) <> 16#0000;   // bit3 exclu → SafeStop normal sans mou câble
ELSE
    SafeStop := (ErrorId AND 16#FF9F) <> 16#0000;   // bit3 inclus → SafeStop complet avec mou câble
END_IF;

// ⬇️ DescendPermit : TRUE = descente autorisée (pas de limite basse, pas de mou câble en mode récup, contacteur engagé)
// Polarité positive Fail-Safe (TRUE = mouvement autorisé).
DescendPermit := NOT (
    (((ErrorId AND 16#0040) <> 16#0000 OR NOT PowerContactorEngaged) AND NOT (BypassGlobal OR BypassCableLimitSwitch))
    OR (((CfgCableLimitDescentM < 0.0) AND (CablePosM <= CfgCableLimitDescentM) AND NOT InReferencingMode) AND NOT BypassCableLimitSwitch)
    OR (LimitLegalReached AND NOT (BypassProcess OR BypassLimitLegal))
    OR (((ErrorId AND 16#0008) <> 16#0000 AND NOT SyncEnable) AND NOT (BypassProcess OR BypassGlobal))
);

// ⬆️ AscentPermit : TRUE = montée autorisée (pas de fin course haut, pas de dépassement position)
// Polarité positive Fail-Safe (TRUE = mouvement autorisé).
AscentPermit := NOT (
    (((ErrorId AND 16#0020) <> 16#0000
    OR (NOT TopPositionSensor AND NOT InReferencingMode))
    AND NOT BypassTopLimitSwitch)
    OR ((Homed AND NOT HomingSuspect AND NOT InReferencingMode AND (CablePosM >= TopLimitM)) AND NOT BypassTopLimitSoftware)
);

// PowerCutOff — bits 7/8/9 (Méca A/B/C, voir bandeau en-tête).
// Coupure puissance amont : les contacteurs locaux sont déjà confirmés coupés/insuffisants,
// SafeStop seul ne sert à rien dans ces 3 cas précis.
// bit2 (surchauffe/perte thermique MOTEUR) et bit10 (surchauffe/perte thermique FREIN commun) :
// un frein à manque de courant peut coller instantanément sur perte de son retour thermique ;
// une rampe SafeStop seule ne protège pas la mécanique dans ce cas, coupure puissance immédiate
// nécessaire. Même raisonnement appliqué au thermique moteur par cohérence/défense en profondeur.
// bit11 (Méca D, capteur haut) : même raisonnement que Méca A/B — contacteurs/frein déjà censés
// être coupés (AscentPermit immédiat sur capteur), une confirmation manquante après délai signifie
// que la coupure locale n'a pas suffi.
// bit13 (Méca E escalade) : PAS bit12 seul (détection immédiate = SafeStop uniquement ;
// PowerCutOff seulement si l'arrêt n'est pas confirmé après délai).
PowerCutOff := (ErrorId AND 16#2F84) <> 16#0000;

// Busy, Done non utilisés mais présents pour conformité (comme FB_Diag_CanOpen)
Busy := FALSE;
Done := FALSE;

{endregion}

(* ═══════════════════════════════════════════════════════════════
   🛡️ FB_Safety_Translation — Bloc Safety pour le Translation M3 (EtherCAT)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : ARCHIVES/Doc/AF_Partie-11_Fonction_Translation_v2.0.md
   🔁 Rôle : Surveillance joystick, bus EtherCAT, rotation de phases, 
      thermique frein commun, Méca A (vitesse non commandée à l'arrêt), 
      Méca B (frein/variateur en mouvement à l'arrêt), et Fdc extrêmes.
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Safety_Translation
VAR_INPUT
    Enable              : BOOL;        // Active la surveillance
    Reset               : BOOL;        // Front acquittement défauts
    PowerContactorEngaged     : BOOL;        // Chaîne AU réarmée + conditions globales OK
    Mode                : E_Mode;      // Mode courant
    JoystickOnline      : BOOL;        // instDiagCanOpen.DeviceJoystick.Online
    JoystickOperational : BOOL;        // instDiagCanOpen.DeviceJoystick.Operational
    HeartbeatIhmOk      : BOOL;        // 💓 IHM↔PLC : TRUE après front post-boot, FALSE = perte communication opérateur
    PhaseRotationOk     : BOOL;        // PRG_02_Acquisition.HwIn.Machine.PhaseRotationOk_DI (TRUE = OK)
    BrakeThermalFeedback: BOOL;        // Thermique frein commun M1/M2/M3 (NC, TRUE = surchauffe/perte)

    // 🔌 Spécifique EtherCAT & Capteurs réels
    DriveOnline         : BOOL;        // Status diagnostic communication EtherCAT (Online)
    DriveOperational    : BOOL;        // Status diagnostic communication EtherCAT (Operational)
    DriveStatusWord     : WORD;        // Mot d'état variateur AC600
    DriveActualFreqHz   : REAL;        // Vitesse réelle variateur (Hz)
    BrakeFeedback       : BOOL;        // Retour d'état bobine frein (TRUE = ouvert/desserré — révocation 2026-08-03)
    BrakeCmd            : BOOL;        // Commande frein
    Direction           : INT;         // Direction commandée
    LimitSwitchFwd      : BOOL;        // Fin de course extrême avant
    LimitSwitchRev      : BOOL;        // Fin de course extrême arrière
    SensorWordIncoherent: BOOL;        // 🆕 REX 2026-07-18 : mot des 5 capteurs position hors combinaisons valides (FB_Translation_PositionDecoder.Incoherent)

    // 🔧 Bypass des surveillances (GVL_IHM.TranslationM3.Bypass)
    BypassGlobal          : BOOL := FALSE;   // 🌐 Bypass GLOBAL : ignore TOUTES les surveillances ci-dessous (prioritaire)
    BypassOperatorComm    : BOOL := FALSE;   // 🎮 Bypass perte communication opérateur
    BypassDriveComm       : BOOL := FALSE;   // 📡 Bypass perte communication drive
    BypassPhaseRotation   : BOOL := FALSE;   // ⚡ Bypass défaut rotation phases
    BypassBrakeThermal    : BOOL := FALSE;   // 🌡️ Bypass surchauffe frein
    BypassMecaB           : BOOL := FALSE;   // 🛑 Bypass Méca B
    BypassMecaA           : BOOL := FALSE;   // 🔄 Bypass Méca A
    BypassLimitSwitch     : BOOL := FALSE;   // 🚧 Bypass butées extrêmes
    BypassSensorIncoherent: BOOL := FALSE;   // 🧭 Bypass incohérence mot capteurs
    BypassSafety          : BOOL := FALSE;   // 🛡️ Bypass groupé PowerCutOff (BrakeThermal/MecaB/MecaA/LimitSwitch/SensorIncoherent)
    BypassProcess         : BOOL := FALSE;   // ⚙️ Bypass groupé SafeStop seul (OperatorComm/DriveComm/PhaseRotation/ContactorFeedback)
END_VAR
VAR_OUTPUT
    Ready               : BOOL;
    Busy                : BOOL;
    Done                : BOOL;
    Error               : BOOL;
    ErrorId             : WORD;        // bit0: "Perte communication opérateur" - joystick CAN ou heartbeat IHM absent ; bit1: "Perte communication EtherCAT" - perte com EtherCAT ; bit2: "Défaut Rotation Phases" - rotation phases ; bit3: "Surchauffe Frein Translation" - thermique frein ; bit4: "Absence confirmation arrêt (Méca B)" - Méca B (incohérence arrêt) ; bit5: "Mouvement non commandé (Méca A)" - Méca A (mouvement non commandé) ; bit6: "Limite extrême Translation atteinte" - Fdc extrême atteint ; bit7: "Incohérence mot capteurs position" - combinaison des 5 capteurs Trémie/PV/P2/P1/Maintenance hors table valide
    State               : E_State;
    StateAtError        : E_State;
    SafeStop            : BOOL;        // 🟧 Décélération rapide (PLC)
    PowerCutOff         : BOOL;        // 🧨 Coup de poing / coupure puissance amont
    ErrorOperatorComm   : BOOL;        // 🎮 Perte communication opérateur : joystick CAN ou heartbeat IHM (bit0)
    ErrorDriveComm      : BOOL;        // 📡 Perte communication EtherCAT variateur (bit1)
    ErrorPhaseRotation  : BOOL;        // ⚡ Mauvaise rotation de phases (bit2)
    ErrorBrakeThermal   : BOOL;        // 🌡️ Surchauffe thermique frein commun (bit3)
    ErrorMecaB          : BOOL;        // 🛑 Absence confirmation arrêt (Méca B - bit4)
    ErrorMecaA          : BOOL;        // 🔄 Mouvement non commandé (Méca A - bit5)
    ErrorLimitSwitch    : BOOL;        // 🚧 Limite extrême Translation atteinte (bit6)
    ErrorSensorIncoherent: BOOL;       // 🧭 Incohérence mot capteurs position (bit7)
END_VAR
VAR
    ResetEdge           : R_TRIG;
    ErrorEdge           : R_TRIG;
    TonMecaB            : TON;         // Sécurité à l'arrêt (Méca B)
    TonMecaA            : TON;         // Sécurité mouvement non commandé (Méca A)
    TonLimitSwitchOverrun : TON;       // 🆕 Surveillance poussée anormale / escalade fin de course
    OverrunCondition    : BOOL;
    PostRampTimeout     : TIME := T#3S;
    UncommandedActiveB  : BOOL;
    UncommandedActiveA  : BOOL;
    FirstScanDone       : BOOL;
    TonStartupWarmup    : TON;         // ⏱️ Inhibition 3s au boot + effacement auto coms
END_VAR

// === IMPLEMENTATION ===

// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    Error := FALSE;
    ErrorId := 16#0000;
    SafeStop := FALSE;
    PowerCutOff := FALSE;
    ErrorOperatorComm := FALSE;
    ErrorDriveComm := FALSE;
    ErrorPhaseRotation := FALSE;
    ErrorBrakeThermal := FALSE;
    ErrorMecaB := FALSE;
    ErrorMecaA := FALSE;
    ErrorLimitSwitch := FALSE;
    ErrorSensorIncoherent := FALSE;
    TonMecaB(IN := FALSE);
    TonMecaA(IN := FALSE);
    TonLimitSwitchOverrun(IN := FALSE);
    TonStartupWarmup(IN := FALSE);
    State := E_State.DISABLED;
    Busy := FALSE; Done := FALSE; Ready := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
ResetEdge(CLK := Reset);

// 🧹 Initialisation au premier scan : purge des résidus RAM d'un Online Change / Warm Start et évitement des alarmes transitoires
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

// 🌐 BYPASS GLOBAL : si actif → force ErrorId = 0 et saute toutes les vérifications
// (les bits d'erreur resteraient coincés si on ne les nettoie pas)
IF BypassGlobal THEN
    ErrorId := 16#0000;
    TonMecaB(IN := FALSE);
    TonMecaA(IN := FALSE);
END_IF;

// ⚠️ ResetEdge doit être traité même si bypass actif, pour que le reset IHM fonctionne.
// On ne l'exécute que si on n'est PAS en bypass global (sinon ErrorId déjà à 0).
IF NOT BypassGlobal THEN
    // ⏱️ Temporisation 3s de mise en route des bus de terrain au boot (EtherCAT / CANopen / Modbus IHM)
    TonStartupWarmup(IN := Enable, PT := T#3s);

    // 🔍 2. PERTE COMMUNICATION OPÉRATEUR (bit0) — joystick CAN ou heartbeat IHM.
    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassOperatorComm) THEN
        IF (NOT JoystickOnline OR NOT JoystickOperational OR NOT HeartbeatIhmOk) THEN
            ErrorId := ErrorId OR 16#0001;
        ELSE
            ErrorId := ErrorId AND 16#FFFE; (* Effacement auto si la com repasse saine *)
        END_IF;
    ELSIF NOT TonStartupWarmup.Q THEN
        ErrorId := ErrorId AND 16#FFFE; (* Inhibition pendant l'initialisation boot *)
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFFE; END_IF;

    // 🔍 2bis. PERTE ETHERCAT VARIATEUR M3 (bit1)
    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassDriveComm) THEN
        IF (NOT DriveOnline OR NOT DriveOperational) THEN
            ErrorId := ErrorId OR 16#0002;
        ELSE
            ErrorId := ErrorId AND 16#FFFD; (* Effacement auto si l'EtherCAT variateur M3 repasse sain *)
        END_IF;
    ELSIF NOT TonStartupWarmup.Q THEN
        ErrorId := ErrorId AND 16#FFFD; (* Inhibition pendant l'initialisation boot *)
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFFD; END_IF;

    // 🔍 3. MAUVAISE ROTATION DE PHASE (bit2)
    IF NOT (BypassProcess OR BypassPhaseRotation) THEN
        IF NOT PhaseRotationOk THEN
            ErrorId := ErrorId OR 16#0004;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFFB; END_IF;

    // 🔍 3ter. THERMIQUE FREIN COMMUN M1/M2/M3 (bit3)
    IF NOT (BypassSafety OR BypassBrakeThermal) THEN
        IF BrakeThermalFeedback THEN
            ErrorId := ErrorId OR 16#0008;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFF7; END_IF;

    // 🔍 3quater. INCOHÉRENCE À L'ARRÊT (Méca B — bit4)
    IF NOT (BypassSafety OR BypassMecaB) THEN
        IF NOT HeartbeatIhmOk THEN
            UncommandedActiveB := (ABS(DriveActualFreqHz) > 0.5) OR DriveStatusWord.0 OR BrakeFeedback;
        ELSIF (Direction = 0) AND NOT BrakeCmd THEN
            UncommandedActiveB := DriveStatusWord.0 OR BrakeFeedback;
        ELSE
            UncommandedActiveB := FALSE;
        END_IF;
        TonMecaB(IN := UncommandedActiveB, PT := PostRampTimeout);
        IF TonMecaB.Q THEN ErrorId := ErrorId OR 16#0010; END_IF;
    ELSE
        TonMecaB(IN := FALSE);
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFEF; END_IF;

    // 🔍 3quinquies. MOUVEMENT NON COMMANDÉ (Méca A — bit5)
    IF NOT (BypassSafety OR BypassMecaA) THEN
        IF (Direction = 0) AND NOT BrakeCmd THEN
            UncommandedActiveA := ABS(DriveActualFreqHz) > 0.5;
        ELSE
            UncommandedActiveA := FALSE;
        END_IF;
        TonMecaA(IN := UncommandedActiveA, PT := T#1S);
        IF TonMecaA.Q THEN ErrorId := ErrorId OR 16#0020; END_IF;
    ELSE
        TonMecaA(IN := FALSE);
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFDF; END_IF;

    // 🔍 3sexies. SURVEILLANCE ESCALADE FIN DE COURSE (bit6)
    IF (BypassSafety OR BypassLimitSwitch) THEN
        // Nettoie le bit 6 résiduel (posé avant activation du bypass)
        ErrorId := ErrorId AND 16#FFBF;
        TonLimitSwitchOverrun(IN := FALSE);
    ELSE
        // 🧱 L'erreur 64 (escalade / poussée anormale en butée) ne s'active QUE SI :
        // 1. On est sur le capteur Trémie (LimitSwitchFwd) ET qu'on continue d'insister en Marche Avant (Direction = 1) avec vitesse/commande variateur active.
        // 2. OU qu'on est sur le capteur Maintenance (LimitSwitchRev) ET qu'on continue d'insister en Marche Arrière (Direction = -1) avec vitesse/commande variateur active.
        OverrunCondition := (LimitSwitchFwd AND (Direction = 1) AND (ABS(DriveActualFreqHz) > 0.5 OR DriveStatusWord.0))
                         OR (LimitSwitchRev AND (Direction = -1) AND (ABS(DriveActualFreqHz) > 0.5 OR DriveStatusWord.0));

        TonLimitSwitchOverrun(IN := OverrunCondition, PT := T#1S500MS);

        IF TonLimitSwitchOverrun.Q THEN
            ErrorId := ErrorId OR 16#0040; // Défaut escalade confirmé (coupure puissance amont)
        ELSE
            // Si la poussée dans le mauvais sens cesse (ou si on repart en arrière), le défaut s'auto-efface
            ErrorId := ErrorId AND 16#FFBF;
        END_IF;
    END_IF;

    // 🔍 3septies. INCOHÉRENCE MOT CAPTEURS POSITION (bit7)
    IF (BypassSafety OR BypassSensorIncoherent) THEN
        // Nettoye le bit 7 résiduel
        ErrorId := ErrorId AND 16#FF7F;
    ELSE
        IF SensorWordIncoherent THEN
            ErrorId := ErrorId OR 16#0080;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FF7F; END_IF;

END_IF; // fin IF NOT BypassGlobal

// 📤 4. ARBITRAGE DES SORTIES MAÎTRESSES
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

SafeStop := Error OR NOT PowerContactorEngaged;

// PowerCutOff actif si thermique frein (bit3), incohérence arrêt (bit4),
// mouvement non commandé (bit5), dépassement de fin de course (bit6),
// ou incohérence mot capteurs position (bit7)
PowerCutOff := (ErrorId AND 16#00F8) <> 16#0000;

// Décapsulage du bitfield ErrorId pour l'IHM
ErrorOperatorComm   := (ErrorId AND 16#0001) <> 16#0000;
ErrorDriveComm      := (ErrorId AND 16#0002) <> 16#0000;
ErrorPhaseRotation  := (ErrorId AND 16#0004) <> 16#0000;
ErrorBrakeThermal   := (ErrorId AND 16#0008) <> 16#0000;
ErrorMecaB          := (ErrorId AND 16#0010) <> 16#0000;
ErrorMecaA          := (ErrorId AND 16#0020) <> 16#0000;
ErrorLimitSwitch    := (ErrorId AND 16#0040) <> 16#0000;
ErrorSensorIncoherent := (ErrorId AND 16#0080) <> 16#0000;

Busy := FALSE;
Done := FALSE;

// 🚦 5. STATE MACHINE (phase diagnostic)
State := E_State.READY;

(* =======================================================================
   📊 FB_Acquisition_Preflight — Verdict passif machine arrêtée
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Verdict passif de qualification E/S machine arrêtée (16 contrôles)
   🔒 Polarité : Observateur pur (aucun SafeStop, PowerCutOff ou ordre machine)
   📄 Doc métier : DOC/AF/AF_Partie-06_Acquisition_Qualification_IO_v2.3.md §6
   ======================================================================= *)
FUNCTION_BLOCK FB_Acquisition_Preflight
VAR_INPUT
    // === COMMANDES & ETATS MACHINE ===
    Execute                 : BOOL; // --> [CMD] Lancement du verdict (front montant)
    MachineIsStill          : BOOL; // --> [HW]  Machine a l'arret complet (vitesse nulle)

    // === ETATS FREINS & CONTACTEURS ===
    M1BrakeApplied          : BOOL; // --> [HW]  Frein M1 serre
    M2BrakeApplied          : BOOL; // --> [HW]  Frein M2 serre
    M3BrakeApplied          : BOOL; // --> [HW]  Frein M3 serre
    M1ContactorsReleased    : BOOL; // --> [HW]  Contacteurs M1 retombes
    M2ContactorsReleased    : BOOL; // --> [HW]  Contacteurs M2 retombes

    // === PROTECTION THERMIQUE & RESEAU ===
    M1ThermalOk             : BOOL; // --> [HW]  Thermique moteur M1 OK
    M2ThermalOk             : BOOL; // --> [HW]  Thermique moteur M2 OK
    BrakeThermalOk          : BOOL; // --> [HW]  Thermique freins OK
    PhaseRotationOk         : BOOL; // --> [HW]  Ordre des phases reseau OK

    // === CAPTEURS & CHAINE DE SECURITE ===
    SlackCableTensioned     : BOOL; // --> [HW]  Cable M2 tendu (anti-mou)
    M3SensorWordIncoherent  : BOOL; // --> [HW]  Incoherence mot capteurs M3
    EmergencyChainClosed    : BOOL; // --> [SAFE] Chaine d'arret d'urgence fermee
    PowerContactorEngaged   : BOOL; // --> [HW]  Contacteur de puissance enclenche

    // === CODEURS & HOMING ===
    EncoderM1Operational    : BOOL; // --> [HW]  Codeur M1 operationnel
    EncoderM2Operational    : BOOL; // --> [HW]  Codeur M2 operationnel
    HomedM1                 : BOOL; // --> [HW]  Homing M1 effectue
    HomedM2                 : BOOL; // --> [HW]  Homing M2 effectue
    M1PositionInBounds      : BOOL; // --> [HW]  Position M1 dans les bornes
    M2PositionInBounds      : BOOL; // --> [HW]  Position M2 dans les bornes
END_VAR
VAR_OUTPUT
    // === ETATS ET DIAGNOSTIC ===
    PreflightOk             : BOOL; // <-- [STAT] Verdict preflight OK (aucun defaut)
    PreflightDone           : BOOL; // <-- [STAT] Verdict preflight termine
    PreflightBusy           : BOOL; // <-- [STAT] Diagnostic preflight en cours
    PreflightErrorId        : WORD; // <-- [DIAG] Masque de defauts preflight (16 bits)
END_VAR
VAR
    // === TRIGGERS & ETATS INTERNES ===
    ExecuteEdge             : R_TRIG;       // . [LOC] Trigger front montant Execute
    BootPending             : BOOL := TRUE; // . [LOC] Demande preflight initiale au demarrage
    RequestPending          : BOOL;         // . [LOC] Demande de verdict en attente
END_VAR

{region "§1 Gate et demande"}
ExecuteEdge(CLK := Execute);
RequestPending := RequestPending OR ExecuteEdge.Q OR BootPending;
PreflightBusy := RequestPending AND NOT MachineIsStill;
IF NOT MachineIsStill THEN PreflightDone := FALSE; RETURN; END_IF;
IF NOT RequestPending THEN RETURN; END_IF;
{endregion}

{region "§2 Calcul verdict"}
PreflightErrorId := 0;
(* bit0..2 frein M1/M2/M3 serré; bit3..4 contacteurs M1/M2 retombés;
   bit5..6 thermique M1/M2 OK; bit7 thermique frein OK; bit8 phases OK;
   bit9 câble M2 tendu; bit10 mot M3 cohérent; bit11 contacteur sans chaîne;
   bit12..13 codeur M1/M2 opérationnel; bit14..15 homé et position bornée M1/M2. *)
IF NOT M1BrakeApplied THEN PreflightErrorId := PreflightErrorId OR 16#0001; END_IF;
IF NOT M2BrakeApplied THEN PreflightErrorId := PreflightErrorId OR 16#0002; END_IF;
IF NOT M3BrakeApplied THEN PreflightErrorId := PreflightErrorId OR 16#0004; END_IF;
IF NOT M1ContactorsReleased THEN PreflightErrorId := PreflightErrorId OR 16#0008; END_IF;
IF NOT M2ContactorsReleased THEN PreflightErrorId := PreflightErrorId OR 16#0010; END_IF;
IF NOT M1ThermalOk THEN PreflightErrorId := PreflightErrorId OR 16#0020; END_IF;
IF NOT M2ThermalOk THEN PreflightErrorId := PreflightErrorId OR 16#0040; END_IF;
IF NOT BrakeThermalOk THEN PreflightErrorId := PreflightErrorId OR 16#0080; END_IF;
IF NOT PhaseRotationOk THEN PreflightErrorId := PreflightErrorId OR 16#0100; END_IF;
IF NOT SlackCableTensioned THEN PreflightErrorId := PreflightErrorId OR 16#0200; END_IF;
IF M3SensorWordIncoherent THEN PreflightErrorId := PreflightErrorId OR 16#0400; END_IF;
IF PowerContactorEngaged AND NOT EmergencyChainClosed THEN PreflightErrorId := PreflightErrorId OR 16#0800; END_IF;
IF NOT EncoderM1Operational THEN PreflightErrorId := PreflightErrorId OR 16#1000; END_IF;
IF NOT EncoderM2Operational THEN PreflightErrorId := PreflightErrorId OR 16#2000; END_IF;
IF NOT HomedM1 OR NOT M1PositionInBounds THEN PreflightErrorId := PreflightErrorId OR 16#4000; END_IF;
IF NOT HomedM2 OR NOT M2PositionInBounds THEN PreflightErrorId := PreflightErrorId OR 16#8000; END_IF;
{endregion}

{region "§3 Sortie"}
PreflightOk := (PreflightErrorId = 0); PreflightDone := TRUE; BootPending := FALSE; RequestPending := FALSE;
{endregion}

SETUP
VAR
    fb : FB_JOYSTICK;
    nx : INT := 5000;
    ny : INT := 5000;
    diagOk : ST_DIAG_DEVICE;
    diagDown : ST_DIAG_DEVICE;
END_VAR
END_SETUP

TEST 'TC-P08-001 Perte bus CAN pendant un mouvement arme neutralise et desarme, sans lever Error'
    diagDown.ONLINE := FALSE; diagDown.OPERATIONAL := FALSE; diagDown.ERROR := FALSE;
    diagDown.ERRORID := 0; diagDown.STATE := E_DIAG_STATE.INIT; diagDown.STATEATERROR := E_DIAG_STATE.DISABLED;
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;
    nx := 5000; ny := 5000;

    (* arme le geste au neutre, bus sain *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ADVANCE_TIME(110000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, 'precondition : geste arme');

    (* deplace le joystick : mouvement actif, bus toujours sain *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 60.0, 0.01, 'mouvement actif : consigne non nulle (RawX=8000, Neutral=5000)');
    ASSERT_EQ(fb.AXISCMDX.DIRECTION, 1, 'sens avant pendant le mouvement');

    (* perte du bus CAN EN PLEIN MOUVEMENT : neutralisation immediate + desarmement *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagDown, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.READY, 'bus CAN non operationnel doit bloquer Ready');
    ASSERT_FALSE(fb.ERROR, 'un bus down est un GATE de securite, PAS une Error diagnostiquee (pas de bit ErrorId leve ici)');
    ASSERT_FALSE(fb.AXISCMDX.ENABLE, 'sorties axe neutralisees des la perte du bus, meme en plein mouvement');
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 0.0, 0.01, 'consigne coupee immediatement, pas de decel progressive');
    ASSERT_FALSE(fb.DEADMANARMED, 'le geste est desarme par la perte du bus (AF08 TC-P08-001)');

    (* bus revient : pas de rearmement automatique, nouvel appui conscient exige *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.READY, 'bus revenu : FB de nouveau pret');
    ASSERT_FALSE(fb.DEADMANARMED, 'pas de rearmement automatique au retour du bus : nouvel appui conscient exige');
END_TEST

TEST 'TC-P08-002 Appui maintenu 100ms arme le geste (DeadmanArmHoldTime)'
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;

    (* baseline : neutre, bouton relache *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'baseline : bouton relache, pas arme');

    (* front bouton : demarre le maintien, pas encore arme *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'front bouton seul ne doit pas armer immediatement (maintien requis)');

    (* 50ms plus tard : maintien pas termine *)
    ADVANCE_TIME(50000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, '50ms < DeadmanArmHoldTime (100ms) : pas encore arme');

    (* 60ms de plus (total 110ms) : maintien termine -> arme *)
    ADVANCE_TIME(60000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, '110ms >= DeadmanArmHoldTime (100ms) : geste arme');
END_TEST

TEST 'TC-P08-003 Relachement du bouton avant fin du maintien annule la tentative armement'
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;

    (* front bouton : demarre le maintien *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
