(* ═══════════════════════════════════════════════════════════════
   ↔️ FB_TranslationRuntimeGate — Préconditions d'appel FB_Translation
   ───────────────────────────────────────────────────────────────
   📄 Migration M4 : extrait les expressions booléennes/SEL de la page
      historique pour conserver un CFC XML sans calcul inline.
   🔒 Le retour de desserrage est lu à N-1 via FB_TranslationFeedbackMemory,
      identique à l'auto-référence historique instTranslationM3.BrakeReleaseRequest.
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_TranslationRuntimeGate
VAR_INPUT
    MachineEnable                 : BOOL;
    Mode                          : E_Mode;
    BypassContactorFeedback       : BOOL;
    BrakeFeedback                 : BOOL;
    PreviousBrakeReleaseRequest   : BOOL;
END_VAR
VAR_OUTPUT
    Enable                        : BOOL;
    BrakeFeedbackForTranslation   : BOOL;
END_VAR

Enable := MachineEnable AND (Mode <> E_Mode.DISABLE);

IF BypassContactorFeedback THEN
    BrakeFeedbackForTranslation := PreviousBrakeReleaseRequest;
ELSE
    BrakeFeedbackForTranslation := BrakeFeedback;
END_IF;

(* ═══════════════════════════════════════════════════════════════════════════════
   📊 FB_WinchLoadEstimator — Estimation empirique de charge treuil
   ═══════════════════════════════════════════════════════════════════════════════
   🧩 Brique de diagnostic/information, sans commande moteur et sans SafeStop.
   🎯 Croise le palier commandé et la bande de vitesse mesurée pour lire une
      estimation dans ST_WinchLoadEstimateTable.
   ⚠️ La table doit être explicitement marquée IsConfigured : sinon la sortie
      reste à 0 % et Configured reste FALSE.
   ═══════════════════════════════════════════════════════════════════════════════
   📄 Docs : DOC/AF_Partie-10_Fonction_Winch_v2.0.md
*)

FUNCTION_BLOCK PUBLIC FB_WinchLoadEstimator
VAR_INPUT
    Enable             : BOOL;
    Reset              : BOOL;
    PowerContactorEngaged    : BOOL;
    Mode               : E_Mode;
    ActiveSpeedStep    : INT;                       // Palier commandé 0..5
    MeasuredSpeedMps   : REAL;                      // Vitesse câble absolue
    MeasuredSpeedSignedMps : REAL;                  // Vitesse signée : positive = montée, négative = descente
    SpeedConfig        : ST_WinchSpeedConfig;       // Plages vitesse mesurée
    LoadTable          : ST_WinchLoadEstimateTable;// Table empirique 5x5
END_VAR
VAR_OUTPUT
    Ready              : BOOL;
    Busy               : BOOL;
    Done               : BOOL;
    Error              : BOOL;
    ErrorId            : WORD;                     // bit0 : entrée/table invalide
    State              : E_State;
    StateAtError       : E_State;
    SpeedBand          : INT;                      // Bande vitesse courante 0..5
    EstimatedLoadPct   : REAL;                     // Estimation informative 0..100 %
    Configured         : BOOL;                     // TRUE si table explicitement validée
    Ascending          : BOOL;                     // TRUE uniquement pendant une montée mesurée
END_VAR
VAR
    ResetEdge          : R_TRIG;
    ErrorEdge          : R_TRIG;
    PreviousSpeedBand  : INT;
    HasPreviousBand    : BOOL;
    SelectedLoadPct    : REAL;
END_VAR

// 🛑 1. GATE — aucune estimation lorsque le bloc est désactivé ou l'AU absent.
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE;
    Busy := FALSE;
    Done := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    State := E_State.DISABLED;
    SpeedBand := 0;
    EstimatedLoadPct := 0.0;
    Configured := FALSE;
    Ascending := FALSE;
    HasPreviousBand := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
Busy := FALSE;
Done := FALSE;
State := E_State.READY;
ResetEdge(CLK := Reset);
Configured := LoadTable.IsConfigured;
// 📈 WINCH-CORE-01 : l'estimation de charge n'a de sens qu'en montée.
// La bande de vitesse reste calculée pour le diagnostic et le garde-fou de palier,
// mais EstimatedLoadPct est forcée à zéro à l'arrêt et en descente.
Ascending := (MeasuredSpeedSignedMps > 0.0);

// 📏 2. CLASSEMENT DE LA VITESSE — hystérésis autour des 4 frontières.
IF (MeasuredSpeedMps < 0.0) OR (SpeedConfig.MaxMeasuredSpeedMps <= 0.0) THEN
    ErrorId := ErrorId OR 16#0001;
    SpeedBand := 0;
ELSIF NOT HasPreviousBand THEN
    IF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[1] THEN
        PreviousSpeedBand := 1;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[2] THEN
        PreviousSpeedBand := 2;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[3] THEN
        PreviousSpeedBand := 3;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[4] THEN
        PreviousSpeedBand := 4;
    ELSE
        PreviousSpeedBand := 5;
    END_IF;
    HasPreviousBand := TRUE;
    SpeedBand := PreviousSpeedBand;
ELSE
    // 🔒 Valider l'état mémorisé avant toute indexation dynamique.
    IF PreviousSpeedBand < 1 OR PreviousSpeedBand > 5 THEN
        PreviousSpeedBand := 1;
        ErrorId := ErrorId OR 16#0001;
    END_IF;

    // CODESYS ne garantit pas le court-circuit des expressions AND :
    // chaque borne est donc testée dans une branche séparée avant accès.
    IF PreviousSpeedBand < 5 THEN
        IF MeasuredSpeedMps > (SpeedConfig.SpeedBandMaxMps[PreviousSpeedBand]
                               + SpeedConfig.SpeedBandHysteresisMps) THEN
            PreviousSpeedBand := PreviousSpeedBand + 1;
        END_IF;
    END_IF;
    IF PreviousSpeedBand > 1 THEN
        IF MeasuredSpeedMps < (SpeedConfig.SpeedBandMaxMps[PreviousSpeedBand - 1]
                               - SpeedConfig.SpeedBandHysteresisMps) THEN
            PreviousSpeedBand := PreviousSpeedBand - 1;
        END_IF;
    END_IF;
    SpeedBand := PreviousSpeedBand;
END_IF;

// 📊 3. LECTURE TABLE — bornes séparées avant l'accès au tableau 5x5.
EstimatedLoadPct := 0.0;
IF Configured THEN
    IF Ascending THEN
        IF ActiveSpeedStep >= 1 THEN
            IF ActiveSpeedStep <= 5 THEN
                IF SpeedBand >= 1 THEN
                    IF SpeedBand <= 5 THEN
                        SelectedLoadPct := LoadTable.LoadPctByStepAndSpeedBand[ActiveSpeedStep][SpeedBand];
                        IF (SelectedLoadPct < 0.0) OR (SelectedLoadPct > 100.0) THEN
                            ErrorId := ErrorId OR 16#0001;
                        ELSE
                            EstimatedLoadPct := SelectedLoadPct;
                        END_IF;
                    END_IF;
                END_IF;
            END_IF;
        END_IF;
    END_IF;
END_IF;

// 📤 4. SORTIES D'ÉTAT ET ACQUITTEMENT.
IF ResetEdge.Q AND (ErrorId <> 16#0000) AND (MeasuredSpeedMps >= 0.0) THEN
    ErrorId := 16#0000;
END_IF;
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   🔘 FB_ResetAggregation — Producteur unique du niveau Reset IHM
   ───────────────────────────────────────────────────────────────
   📄 Contrat : ST_ResetCommand
   🛡️ Agrège uniquement les quatre boutons existants. Il ne détecte
      pas de front et ne réarme rien : les consommateurs conservent
      leur R_TRIG local, conformément à la règle Reset = front.
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK FB_ResetAggregation
VAR_INPUT
    BtnFaultReset : BOOL;
    BtnResetM1 : BOOL;
    BtnResetM2 : BOOL;
    BtnResetBucket : BOOL;
END_VAR
VAR_OUTPUT
    Cmd : ST_ResetCommand;
END_VAR

Cmd.CmdReset := BtnFaultReset OR BtnResetM1 OR BtnResetM2 OR BtnResetBucket;

(* =======================================================================
   💾 FB_CfgPersistBridge_TranslationCfg — Pont persistance pour ST_TranslationCfg
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Restauration et synchronisation bidirectionnelle IHM / Persist
   💾 Persistance : Transfert GVL_PERSISTENT <-> GVL_IHM sur Initialized
   📄 Doc métier : DOC/AF/AF_Partie-11_Fonction_Translation_v2.2.md
   ======================================================================= *)
FUNCTION_BLOCK FB_CfgPersistBridge_TranslationCfg
VAR_OUTPUT
    // === ETATS RESTAURATION ===
    JustRestored            : BOOL;               // <-- [STAT] Vrai sur le cycle de restauration initiale
END_VAR
VAR_IN_OUT
    // === BUS CONFIGURATION ET PERSISTANCE ===
    Hmi                     : ST_TranslationCfg;  // <-> [BUS] Structure de configuration IHM
    Persist                 : ST_TranslationCfg;  // <-> [BUS] Structure de configuration persistante
END_VAR

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   ↔️ FB_TranslationCfcExpressions — Expressions extraites du CFC
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : porter les trois expressions booléennes du câblage
      historique dans un FB ST, afin que la page CFC XML ne comporte
      que des blocs et des fils.

   🔒 Conservation : chaque sortie est l'expression legacy à l'identique.
   Aucun accès sortie physique, aucune décision de sécurité nouvelle.
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK FB_TranslationCfcExpressions
VAR_INPUT
    BrakeThermalFeedback       : BOOL;
    BypassContactorFeedback    : BOOL;
    BypassGlobal               : BOOL;
    BypassLimitSwitch          : BOOL;
END_VAR
VAR_OUTPUT
    BrakeThermalOk                 : BOOL;
    BypassContactorFeedbackEffective : BOOL;
    BypassLimitSwitchEffective       : BOOL;
END_VAR

BrakeThermalOk := NOT BrakeThermalFeedback;
BypassContactorFeedbackEffective := BypassContactorFeedback OR BypassGlobal;
BypassLimitSwitchEffective := BypassGlobal OR BypassLimitSwitch;

SETUP
VAR
    fb : FB_JOYSTICK;
    nx : INT := 5000;
    ny : INT := 5000;
    diagOk : ST_DIAG_DEVICE;
    diagDown : ST_DIAG_DEVICE;
END_VAR
END_SETUP

TEST 'TC-P08-001 Perte bus CAN pendant un mouvement arme neutralise et desarme, sans lever Error'
    diagDown.ONLINE := FALSE; diagDown.OPERATIONAL := FALSE; diagDown.ERROR := FALSE;
    diagDown.ERRORID := 0; diagDown.STATE := E_DIAG_STATE.INIT; diagDown.STATEATERROR := E_DIAG_STATE.DISABLED;
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;
    nx := 5000; ny := 5000;

    (* arme le geste au neutre, bus sain *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ADVANCE_TIME(110000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, 'precondition : geste arme');

    (* deplace le joystick : mouvement actif, bus toujours sain *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 60.0, 0.01, 'mouvement actif : consigne non nulle (RawX=8000, Neutral=5000)');
    ASSERT_EQ(fb.AXISCMDX.DIRECTION, 1, 'sens avant pendant le mouvement');

    (* perte du bus CAN EN PLEIN MOUVEMENT : neutralisation immediate + desarmement *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagDown, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.READY, 'bus CAN non operationnel doit bloquer Ready');
    ASSERT_FALSE(fb.ERROR, 'un bus down est un GATE de securite, PAS une Error diagnostiquee (pas de bit ErrorId leve ici)');
    ASSERT_FALSE(fb.AXISCMDX.ENABLE, 'sorties axe neutralisees des la perte du bus, meme en plein mouvement');
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 0.0, 0.01, 'consigne coupee immediatement, pas de decel progressive');
    ASSERT_FALSE(fb.DEADMANARMED, 'le geste est desarme par la perte du bus (AF08 TC-P08-001)');

    (* bus revient : pas de rearmement automatique, nouvel appui conscient exige *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.READY, 'bus revenu : FB de nouveau pret');
    ASSERT_FALSE(fb.DEADMANARMED, 'pas de rearmement automatique au retour du bus : nouvel appui conscient exige');
END_TEST

TEST 'TC-P08-002 Appui maintenu 100ms arme le geste (DeadmanArmHoldTime)'
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;

    (* baseline : neutre, bouton relache *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'baseline : bouton relache, pas arme');

    (* front bouton : demarre le maintien, pas encore arme *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'front bouton seul ne doit pas armer immediatement (maintien requis)');

    (* 50ms plus tard : maintien pas termine *)
    ADVANCE_TIME(50000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, '50ms < DeadmanArmHoldTime (100ms) : pas encore arme');

    (* 60ms de plus (total 110ms) : maintien termine -> arme *)
    ADVANCE_TIME(60000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, '110ms >= DeadmanArmHoldTime (100ms) : geste arme');
END_TEST

TEST 'TC-P08-003 Relachement du bouton avant fin du maintien annule la tentative armement'
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;

    (* front bouton : demarre le maintien *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);

    (* relache a 50ms, avant la fin des 100ms de maintien *)
    ADVANCE_TIME(50000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'relachement avant la fin du maintien annule la tentative');

    (* le bouton reste relache : meme 100ms plus tard, aucun armement differe *)
    ADVANCE_TIME(100000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'pas d armement differe sur une tentative deja annulee (nouvel appui conscient exige)');

    (* nouveau front + maintien complet : l armement redevient possible normalement *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ADVANCE_TIME(110000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, 'un nouvel appui complet doit toujours pouvoir armer');
END_TEST

TEST 'TC-P08-004 Delai de grace protege l armement au neutre, puis le neutre prolonge desarme apres la grace'
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;

    (* nx/ny fixes explicitement a 5000 avant CHAQUE appel : STruCpp ne re-copie PAS la sortie
       VAR_IN_OUT vers la variable de test entre deux appels fb() (limite outillage constatee,
       round-trip IN_OUT absent -- cf. README). Sans ce forcage, NeutralXMem retomberait a 0
       (valeur SETUP jamais appliquee non plus) des le 2e scan, et AtNeutral resterait FALSE. *)
    nx := 5000; ny := 5000;

    (* arme le geste au neutre *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ADVANCE_TIME(110000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, 'precondition : geste arme');

    (* bouton relache, reste au neutre : 500ms plus tard (largement > NeutralHoldTime seul 100ms) mais < grace (3s) *)
    ADVANCE_TIME(500000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, 'la grace (3s) protege l armement malgre un neutre deja tenu bien plus longtemps que NeutralHoldTime seul (evite le REX terrain : desarmement 100-200ms apres l armement)');

    (* 2.6s de plus (total 3.1s depuis l armement) : la grace vient de s ecouler ce scan meme --
       NeutralHoldTimer ne fait que DEMARRER (son IN passe a TRUE ce scan), pas encore Q *)
    ADVANCE_TIME(2600000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, 'grace tout juste ecoulee : NeutralHoldTimer demarre seulement ce scan (pas encore ecoule)');

    (* 100ms de plus (NeutralHoldTime ecoule depuis la fin de la grace) : desarme *)
    ADVANCE_TIME(100000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'grace ecoulee (3s) + neutre tenu (NeutralHoldTime) : desarmement');
END_TEST

