FUNCTION_BLOCK FB_TestStimulus
VAR_INPUT
    Config     : ST_TestStimAnalogConfig;
    Start      : BOOL;
    Abort      : BOOL;
END_VAR
VAR_OUTPUT
    OutBool    : BOOL;
    OutReal    : REAL;
    OutActive  : BOOL;
    Done       : BOOL;
END_VAR
VAR
    StartTrig   : R_TRIG;
    Timer       : TON;
    SeqTimer    : TON;
    Ramp        : RAMP_REAL;
    ActiveIndex : INT;
    Running     : BOOL;
    Rate        : REAL;
END_VAR
// === IMPLEMENTATION ===
StartTrig(CLK := Start);

// Gestion de l'arrêt ou de l'inactivité
IF Abort OR (NOT Running AND NOT StartTrig.Q) THEN
    Running := FALSE;
    OutActive := FALSE;
    OutBool := FALSE;
    OutReal := 0.0;
    Done := FALSE;
    Timer(IN := FALSE);
    SeqTimer(IN := FALSE);
    Ramp(RESET := TRUE, IN := 0.0);
    RETURN;
END_IF;

// Lancement sur front montant de Start
IF StartTrig.Q THEN
    Running := TRUE;
    Done := FALSE;
    OutActive := TRUE;
    ActiveIndex := 1;
    Timer(IN := FALSE);
    SeqTimer(IN := FALSE);
    
    CASE Config.Kind OF
        E_TestStimKind.STIM_PULSE_BOOL:
            OutBool := TRUE;
            Timer(IN := TRUE, PT := Config.PulsePT);
            
        E_TestStimKind.STIM_RAMP_REAL:
            Ramp(RESET := TRUE, IN := Config.StartReal);
            IF Config.RampPT > T#0s THEN
                // Calcul de la vitesse par seconde
                Rate := ABS(Config.TargetReal - Config.StartReal) / (TIME_TO_REAL(Config.RampPT) / 1000.0);
            ELSE
                Rate := ABS(Config.TargetReal - Config.StartReal);
            END_IF;
            Timer(IN := TRUE, PT := Config.RampPT);
            
        E_TestStimKind.STIM_SEQUENCE_REAL:
            IF Config.SeqCount >= 1 THEN
                OutReal := Config.SeqValues[1];
                SeqTimer(IN := TRUE, PT := Config.SeqDwellPT);
            ELSE
                Running := FALSE;
                OutActive := FALSE;
                Done := TRUE;
            END_IF;
    END_CASE;
END_IF;

// Éxecution logique quand le stimulus tourne
IF Running THEN
    CASE Config.Kind OF
        E_TestStimKind.STIM_PULSE_BOOL:
            Timer();
            IF Timer.Q THEN
                OutBool := FALSE;
                Running := FALSE;
                OutActive := FALSE;
                Done := TRUE;
                Timer(IN := FALSE);
            END_IF;
            
        E_TestStimKind.STIM_RAMP_REAL:
            Timer();
            Ramp(RESET := FALSE, IN := Config.TargetReal, ASCEND := Rate, DESCEND := Rate, TIMEBASE := T#1s);
            OutReal := Ramp.OUT;
            IF Timer.Q THEN
                OutReal := Config.TargetReal; // Assure la valeur cible exacte à la fin
                Running := FALSE;
                OutActive := FALSE;
                Done := TRUE;
                Timer(IN := FALSE);
            END_IF;
            
        E_TestStimKind.STIM_SEQUENCE_REAL:
            SeqTimer();
            IF SeqTimer.Q THEN
                SeqTimer(IN := FALSE);
                ActiveIndex := ActiveIndex + 1;
                IF ActiveIndex > Config.SeqCount OR ActiveIndex > GVL_PLC_Tests_Const.MaxSeqValues THEN
                    Running := FALSE;
                    OutActive := FALSE;
                    Done := TRUE;
                ELSE
                    OutReal := Config.SeqValues[ActiveIndex];
                    SeqTimer(IN := TRUE, PT := Config.SeqDwellPT);
                END_IF;
            END_IF;
    END_CASE;
END_IF;

(* =======================================================================
   💾 FB_CfgPersistBridge_CycleCfg — Pont persistance pour ST_CycleCfg
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Restauration et synchronisation bidirectionnelle IHM / Persist
   💾 Persistance : Transfert GVL_PERSISTENT <-> GVL_IHM sur Initialized
   📄 Doc métier : DOC/AF/AF_Partie-03_Contrats_Composants_v2.1.md §3
   ======================================================================= *)
FUNCTION_BLOCK FB_CfgPersistBridge_CycleCfg
VAR_OUTPUT
    // === ETATS RESTAURATION ===
    JustRestored            : BOOL;               // <-- [STAT] Vrai sur le cycle de restauration initiale
END_VAR
VAR_IN_OUT
    // === BUS CONFIGURATION ET PERSISTANCE ===
    Hmi                     : ST_CycleCfg;        // <-> [BUS] Structure de configuration IHM
    Persist                 : ST_CycleCfg;        // <-> [BUS] Structure de configuration persistante
END_VAR

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   🧪 FB_Sim_Translation — Progression capteurs simulés M3
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Produit les cinq capteurs de position M3 par progression continue
      de Trémie vers Maintenance. Le modèle ne publie que les six mots valides
      de FB_Translation_PositionDecoder : 11111 → 01111 → 00111 → 00011 →
      00001 → 00000.
   🔒 Le modèle est une source d'entrée confinée derrière HwIn ; il ne pilote
      aucune sortie réelle. Un override manuel valide est appliqué par
      FB_SimBench, pas par ce FB.
   📄 Docs : DOC/AF/AF_Partie-13_Fonction_Simulation_v2.3.md
             DOC/AF/AF_Partie-11_Fonction_Translation_v2.2.md
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Sim_Translation
VAR_INPUT
    Enable          : BOOL;              (* --> [CMD] TRUE = modèle actif *)
    Direction       : INT;               (* --> [CMD] +1 = vers Trémie ; -1 = vers Maintenance ; 0 = maintien position *)
    SpeedRefPct     : REAL;              (* --> [CMD] Magnitude commande 0..100 %, bornée avant calcul *)
    FullTravelTimeS : REAL := 8.0;       (* --> [CFG] Temps complet Trémie→Maintenance à 100 %, simulation seulement *)
END_VAR
VAR_OUTPUT
    PosTremie      : BOOL;               (* <-- [STAT] Bit4 du mot capteurs *)
    PosPV          : BOOL;               (* <-- [STAT] Bit3 du mot capteurs *)
    PosP2          : BOOL;               (* <-- [STAT] Bit2 du mot capteurs (point matériel PVP2) *)
    PosP1          : BOOL;               (* <-- [STAT] Bit1 du mot capteurs *)
    PosMaintenance : BOOL;               (* <-- [STAT] Bit0 du mot capteurs *)
END_VAR
VAR
    instCycleTime              : FB_CycleTime;   (* * [INST] Mesure temps de cycle *)
    PositionProgress           : REAL;   (* . [LOC] 0=Trémie ... 5=Maintenance *)
    SpeedPctBounded            : REAL;   (* . [LOC] Vitesse bornée *)
    PositionIncrement          : REAL;   (* . [LOC] Incrément de progression *)
    Initialized                : BOOL := FALSE;   (* . [LOC] Initialisation *)
END_VAR
VAR CONSTANT
    CST_PositionAtTremie       : REAL := 0.0;
    CST_PositionAtPV           : REAL := 1.0;
    CST_PositionAtP2           : REAL := 2.0;
    CST_PositionAtP1           : REAL := 3.0;
    CST_PositionAtMaintenance  : REAL := 5.0;
    CST_PositionSegmentCount   : REAL := 5.0;
    CST_MinFullTravelTimeS     : REAL := 0.1; // Protection division : modèle sans dynamique sous ce seuil
END_VAR

// === IMPLEMENTATION ===

{region "§1 Gate"}
IF NOT Enable THEN
    // Prochain démarrage déterministe sur P2, comme l'ancien modèle de banc.
    PositionProgress := CST_PositionAtP2;
    Initialized := FALSE;
    PosTremie := FALSE;
    PosPV := FALSE;
    PosP2 := FALSE;
    PosP1 := FALSE;
    PosMaintenance := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Initialisation"}
IF NOT Initialized THEN
    PositionProgress := CST_PositionAtP2;
    Initialized := TRUE;
END_IF;
{endregion}

{region "§3 Progression"}
instCycleTime(DefaultValueS := 0.010);
SpeedPctBounded := LIMIT(0.0, ABS(SpeedRefPct), 100.0);

// Une vitesse à 100 % parcourt les cinq segments uniformes pendant FullTravelTimeS.
// Direction sémantique : +1 réduit la progression vers Trémie ; -1 l'augmente vers Maintenance.
IF FullTravelTimeS >= CST_MinFullTravelTimeS THEN
    PositionIncrement := (SpeedPctBounded / 100.0)
                         * (CST_PositionSegmentCount / FullTravelTimeS)
                         * instCycleTime.CycleTimeS;
ELSE
    PositionIncrement := 0.0;
END_IF;

IF Direction = 1 THEN
    PositionProgress := MAX(CST_PositionAtTremie, PositionProgress - PositionIncrement);
ELSIF Direction = -1 THEN
    PositionProgress := MIN(CST_PositionAtMaintenance, PositionProgress + PositionIncrement);
END_IF;
{endregion}

{region "§4 Publication capteurs"}
// Réinitialisation explicite : aucune valeur transitoire héritée d'une zone précédente.
PosTremie := FALSE;
PosPV := FALSE;
PosP2 := FALSE;
PosP1 := FALSE;
PosMaintenance := FALSE;

// Chaque intervalle correspond à un seul mot thermomètre valide.
IF PositionProgress <= CST_PositionAtTremie THEN
    PosTremie := TRUE;
    PosPV := TRUE;
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF PositionProgress <= CST_PositionAtPV THEN
    PosPV := TRUE;
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF PositionProgress <= CST_PositionAtP2 THEN
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF PositionProgress <= CST_PositionAtP1 THEN
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF PositionProgress < CST_PositionAtMaintenance THEN
    PosMaintenance := TRUE;
END_IF;
{endregion}

(* =======================================================================
   ⚙️ FB_Encoder_Homing — Référencement codeur nominal ou unitaire
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Séquence de référencement nominal (capteur haut) ou unitaire (MAINT_N2)
   🔒 Polarité : Homed=TRUE dès qu'un référencement valide est enregistré
   🔌 Architecture : Expose ST_Encoder_Calib en VAR_IN_OUT
   📄 Doc métier : DOC/AF/AF_Partie-09_Fonction_Encoder_v2.1.md
   ======================================================================= *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Encoder_Homing) ===

FUNCTION_BLOCK PUBLIC FB_Encoder_Homing
VAR_INPUT
    // === COMMANDES & AUTORISATIONS ===
    Enable                 : BOOL;        // --> [CMD] Autorisation generale FB (TRUE=Autorise)
    Reset                  : BOOL;        // --> [CMD] Acquittement defaut (front montant)
    Home                   : BOOL;        // --> [CMD] Demande de referencement (front)
    BtnConfirmCoherence    : BOOL;        // --> [CMD] Levee de doute d'incoherence au boot (front)

    // === CONTEXTE & MODES ===
    PowerContactorEngaged  : BOOL;        // --> [HW]  Ligne puissance enclenchee
    Mode                   : E_Mode;      // --> [CMD] Mode d'exploitation actif (MAINT_N1/N2 requis)
    UnitaryMode            : BOOL;        // --> [CMD] Mode unitaire a cible libre (MAINT_N2)
    WinchSelected          : BOOL;        // --> [CMD] Instance est le treuil selectionne

    // === CIBLES & CONFIGURATION HOMING ===
    CfgHomingTargetM       : REAL;        // --> [CFG] Cible libre homing unitaire (m)
    UseDynamicTarget       : BOOL := FALSE; // --> [CFG] Activation cible dynamique
    DynamicHomingTargetM   : REAL := 0.0; // --> [CFG] Cible dynamique de referencement (m)
    CfgTopSensorPosM       : REAL := 8.5; // --> [CFG] Cible homing nominal capteur haut (m)

    // === RETOURS HW & CAPTEURS ===
    TopPositionSensor      : BOOL;        // --> [HW]  Capteur physique position haute unique
    FwdRevSpeedFeedbackOff : BOOL;        // --> [HW]  Contacteurs sens et vitesse retombes
    BrakeFeedback          : BOOL;        // --> [HW]  Contacteur frein ouvert/desserre

    // === MESURES & RETOURS FB CODEUR ABSOLU ===
    RawPos                 : UDINT;       // --> [HW]  Position brute codeur (sortie FB_Encoder_Abs)
    EncoderAvailable       : BOOL;        // --> [HW]  Codeur absolu disponible et valide
    PresetAck              : BOOL;        // --> [HW]  Pulse confirmation ecriture preset reussie
    PresetNak              : BOOL;        // --> [HW]  Pulse echec / timeout ecriture preset

    // === CARACTERISTIQUES MECANIQUES & BUS ===
    PointsPerRev           : UDINT := 8192; // --> [CFG] Resolution codeur (pts/tour)
    MultiTurnRevsMax       : UDINT := 4096; // --> [CFG] Capacite multitour max codeur (tours)
    CableM_PerRev          : REAL := 2.0;   // --> [CFG] Perimetre tambour / developpement cable (m/tour)

    // === TESTS & BYPASS ===
    BypassGlobal           : BOOL := FALSE; // --> [TST] Neutralisation securites pour mise en service
END_VAR
VAR_OUTPUT
    // === ETATS IEC & SYNOPTIQUE ===
    Ready                  : BOOL;        // <-- [STAT] FB pret a fonctionner
    Busy                   : BOOL;        // <-- [STAT] Sequence SDO preset en cours
    Done                   : BOOL;        // <-- [STAT] Referencement effectue avec succes
    Error                  : BOOL;        // <-- [STAT] Synthese defaut (ErrorId <> 0)
    ErrorId                : WORD;        // <-- [DIAG] Masque de bits de defaut
    State                  : E_State;     // <-- [STAT] Etat courant du FB
    StateAtError           : E_State;     // <-- [DIAG] Etat courant lors du dernier defaut

    // === COMMANDES VERS FB_ENCODER_ABS ===
    PresetRequest          : BOOL;        // <-- [ACT]  Pulse demande d'ecriture preset SDO
    PresetValue            : UDINT;       // <-- [ACT]  Valeur de cible brute pour preset SDO

    // === RESULTATS & MEMOIRE CALIBRATION ===
    Homed                  : BOOL;        // <-- [STAT] Codeur pagine et referencie
    HomingSuspect          : BOOL;        // <-- [DIAG] Incoherence redemarrage a lever
    HomingRefRaw           : UDINT;       // <-- [DIAG] Offset de reference brut calcule
END_VAR
VAR_IN_OUT
    // === STRUCTURE DE CALIBRATION PERSISTANTE ===
    Calib                  : ST_Encoder_Calib; // <-> [BUS] Structure de calibration RETAIN
END_VAR
VAR
    // === DETECTEURS DE FRONT ===
    ResetEdge              : R_TRIG;      // . [LOC] Detecteur front montant Reset
    ErrorEdge              : R_TRIG;      // . [LOC] Detecteur front montant Error
    HomeEdge               : R_TRIG;      // . [LOC] Detecteur front montant Home
    ConfirmCoherenceEdge   : R_TRIG;      // . [LOC] Detecteur front montant BtnConfirmCoherence
    TopSensorEdge          : R_TRIG;      // . [LOC] Detecteur front montant TopPositionSensor
    DynamicTargetEdge      : R_TRIG;      // . [LOC] Detecteur front montant UseDynamicTarget

    // === ETATS & DRAPEAUX INTERNES ===
    InitDone               : BOOL;        // . [LOC] Controle incoherence boot effectue
    ArretConfirme          : BOOL;        // . [LOC] Condition d'arret moteur confirmee
    HomingModeOk           : BOOL;        // . [LOC] Mode de fonctionnement valide pour homing
    NominalHomingTrigger   : BOOL;        // . [LOC] Condition de declenchement homing nominal
    UnitaryHomingTrigger   : BOOL;        // . [LOC] Condition de declenchement homing unitaire
    DynamicHomingTrigger   : BOOL;        // . [LOC] Condition de declenchement homing dynamique
    HomingTrigger          : BOOL;        // . [LOC] Synthese declenchement homing

    // === VARIABLES DE CALCUL ===
    PresetValueCalc        : UDINT;       // . [LOC] Valeur cible de preset (centre plage)
    TargetPoints           : DINT;        // . [LOC] Ecart cible converti en points
    TargetPositionM        : REAL;        // . [LOC] Cible retenue en metres
    RawDiffRestart         : DINT;        // . [LOC] Ecart brut de position au redemarrage
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Homing) ===

{region "§1 Gate neutralisation"}
// 🛑 1. GATE — neutralisation ; on continue toutefois d'exposer le dernier état RETAIN connu
// (FB_Encoder_Scale a besoin de HomingRefRaw même si ce FB est désactivé)
// PowerContactorEngaged retiré du GATE (le codeur 24V / EtherCAT peut être homé disjoncteurs coupés)
IF NOT Enable THEN
    PresetRequest := FALSE;
    PresetValue := 0;
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    InitDone := FALSE;   // Force un nouveau contrôle §3.7 à la prochaine activation
    Homed := Calib.Homed;
    HomingSuspect := Calib.HomingSuspect;
    HomingRefRaw := Calib.HomingRefRaw;
    RETURN;
END_IF;

Ready := TRUE;

{endregion}

{region "§2 Fronts et coherence demarrage"}
// 🔑 2. FRONTS
ResetEdge(CLK := Reset);
HomeEdge(CLK := Home);
ConfirmCoherenceEdge(CLK := BtnConfirmCoherence);

// 🔍 3. COHÉRENCE AU REDÉMARRAGE (§3.7) — une fois par session Enable, dès que le codeur répond
IF NOT InitDone THEN
    State := E_State.INIT;
    IF EncoderAvailable THEN
        RawDiffRestart := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(Calib.LastKnownRawPos);
        IF Calib.Homed AND (ABS(RawDiffRestart) > UDINT_TO_DINT(Calib.RestartCoherenceTolerancePts)) THEN
            Calib.HomingSuspect := TRUE;
            ErrorId := ErrorId OR 16#0200;   // bit9 : incohérence codeur au redémarrage
        END_IF;
        InitDone := TRUE;
    END_IF;
ELSE
    IF State = E_State.INIT THEN State := E_State.READY; END_IF;
END_IF;

{endregion}

{region "§3 Confirmation coherence et demande homing"}
// ✅ 4. LEVÉE DU DOUTE (BtnConfirmCoherence, §3.7) — indépendant du Reset générique
IF ConfirmCoherenceEdge.Q AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2) THEN
    Calib.HomingSuspect := FALSE;
    ErrorId := ErrorId AND 16#FDFF;   // efface bit9
END_IF;

PresetRequest := FALSE;
TopSensorEdge(CLK := TopPositionSensor);
DynamicTargetEdge(CLK := UseDynamicTarget);

// Gates rejetées = Warning auto-effaçable (§9/TC-P03-007), pas un Fault : recalculées à
// chaque scan, jamais latchées, aucun Reset requis pour les effacer.
ErrorId := ErrorId AND 16#FFEC;   // efface bits 0/1/4 (garde bit5, bit9 — inchangés)

HomingModeOk := (Mode = E_Mode.MAINT_N1) OR (Mode = E_Mode.MAINT_N2);

IF HomeEdge.Q AND NOT HomingModeOk THEN
    ErrorId := ErrorId OR 16#0001;   // bit0 : Mode non autorisé (hors MAINT_N1/N2)
END_IF;
IF HomeEdge.Q AND UnitaryMode AND NOT WinchSelected THEN
    ErrorId := ErrorId OR 16#0002;   // bit1 : mauvais treuil sélectionné (flux unitaire)
END_IF;

// Nominal : capture AU FRONT du capteur haut, pas après arrêt confirmé — AscentPermit
// (FB_Safety_Winch) coupe déjà la montée indépendamment dès que TopPositionSensor est actif ;
// attendre l'arrêt casserait la répétabilité recherchée à vitesse d'accostage constante.
// Couvre les deux cas : Home déjà maintenu quand le capteur déclenche, ou capteur déjà actif
// quand Home est pressé.
NominalHomingTrigger := HomingModeOk AND NOT UseDynamicTarget AND NOT UnitaryMode
                         AND ((Home AND TopSensorEdge.Q) OR (HomeEdge.Q AND TopPositionSensor));

// Unitaire (MAINT_N2 déjà garanti par UnitaryMode en amont, PRG_02_Acquisition) : bon treuil.
UnitaryHomingTrigger := HomingModeOk AND UnitaryMode AND WinchSelected AND HomeEdge.Q;

// Dynamique (benne) : Mode + arrêt confirmé (M1/M2 non Busy) déjà gardés à l'appel via
// M2BucketRefRequested (PRG_02_Acquisition.st) — HomingModeOk reste vérifié ici en défense.
DynamicHomingTrigger := HomingModeOk AND (DynamicTargetEdge.Q OR (UseDynamicTarget AND HomeEdge.Q));

HomingTrigger := NominalHomingTrigger OR UnitaryHomingTrigger OR DynamicHomingTrigger;

IF HomingTrigger THEN
    IF UseDynamicTarget THEN
        TargetPositionM := DynamicHomingTargetM;
    ELSIF UnitaryMode THEN
        TargetPositionM := CfgHomingTargetM;
    ELSE
        TargetPositionM := CfgTopSensorPosM;
    END_IF;

    // Bornage obligatoire avant écriture (CODE_QUALITY_STANDARDS §6) — toute cible, quelle
    // que soit son origine (config, calcul benne, capteur haut), est vérifiée dans la plage
    // physique documentée [-99;+99] m avant d'être gravée dans la référence codeur.
    IF (TargetPositionM < -99.0) OR (TargetPositionM > 99.0) THEN
        ErrorId := ErrorId OR 16#0010;   // bit4 : cible hors plage, homing refusé
    ELSE
        TargetPoints := REAL_TO_DINT(TargetPositionM * UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
        Calib.HomingRefRaw := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) - TargetPoints);
        Calib.Homed := TRUE;
        Calib.HomingSuspect := FALSE;
        Calib.LastKnownRawPos := RawPos;
        HomingRefRaw := Calib.HomingRefRaw;
        Homed := TRUE;
        HomingSuspect := FALSE;
        Done := TRUE;
        ErrorId := 16#0000;
        State := E_State.READY;

        // Envoi parallèle de la demande de Preset SDO au matériel s'il est disponible
        PresetValueCalc := (PointsPerRev * MultiTurnRevsMax) / 2;
        PresetValue := PresetValueCalc;
        PresetRequest := TRUE;
    END_IF;
END_IF;

{endregion}

{region "§4 Suivi SDO reset et sorties etat"}
// ⏳ 6. SUIVI DE LA SÉQUENCE SDO OPTIONNELLE
IF State = E_State.BUSY THEN
    IF PresetAck THEN
        Done := TRUE;
        State := E_State.READY;
        // Un homing réussi efface l'intégralité de ErrorId
        ErrorId := 16#0000;
    ELSIF PresetNak THEN
        ErrorId := ErrorId OR 16#0020;        // bit5 : preset refusé/timeout (voir FB_Encoder_Abs)
        State := E_State.READY;
    END_IF;
END_IF;

// 🧾 7. RESET (front) — efface les bits « dernière tentative rejetée » (pas de cause persistante
// à revérifier ici : le prochain Home réévalue toutes les conditions de zéro, voir §5)
IF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFC0;   // efface bits 0..5 (garde bit9, levé seulement par BtnConfirmCoherence/Home)
END_IF;

// 📤 8. SORTIES ÉTAT
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// Mise à jour continue du point brut valide connu (hors séquence de homing elle-même)
IF EncoderAvailable AND (State <> E_State.BUSY) THEN
    Calib.LastKnownRawPos := RawPos;
END_IF;

Busy := (State = E_State.BUSY);
Homed := Calib.Homed AND NOT Calib.HomingSuspect; // Perd l'état homed si suspect (démarrage ou fonctionnement), restauré après BtnConfirmCoherence
HomingSuspect := Calib.HomingSuspect;
HomingRefRaw := Calib.HomingRefRaw;

{endregion}

(* ═══════════════════════════════════════════════════════════════
   ⚙️ FB_Translation — Directeur de l'axe transversal M3 (variateur AC600)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF/AF_Partie-11_Fonction_Translation_v2.2.md
   🔌 FB DE MOUVEMENT : porte StartStop + SafeStop en plus de l'interface
      standard. Précédence Enable > SafeStop > StartStop.
   Pilotage exclusivement ETHERCAT nominal (mot de commande, consigne fréquence).
   🧩 Compose FB_Brake (réutilisé TEL QUEL depuis COMMUN).
   🎯 Invariant : toute inversion de sens force la cible de rampe à 0.0 tant que le
      changement de sens est en attente, pour garantir le croisement du seuil d'arrêt
      qui autorise l'interlock de changement de sens (§5).
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Translation
VAR_INPUT
    Enable                      : BOOL;        // --> [CMD] Active le FB. FALSE = neutralisation totale (sorties coupées)
    Reset                       : BOOL;        // --> [CMD] Acquittement défaut (front)
    PowerContactorEngaged             : BOOL;        // --> [SAFE] Chaîne AU réarmée + conditions globales OK
    Mode                        : E_Mode;      // --> [CMD] Mode courant
    StartStop                   : BOOL;        // --> [CMD] TRUE = rampe accélération, FALSE = rampe décélération NORMALE
    SafeStop                    : BOOL;        // --> [SAFE] Sortie FB_Safety_Translation : TRUE = rampe décélération RAPIDE (Enable maintenu)
    Direction                   : INT;         // --> [CMD] -1 = Rev, 0 = Neutre, +1 = Fwd (source d'autorité du sens)
    SpeedRefPct                 : REAL;        // --> [CMD] Magnitude de la consigne (de 0 à 100%)
    PositionSensorTarget        : BOOL;        // --> [HW] Capteur position cible courante
    // 3 capteurs déclencheurs de ralentissement, un cran avant chaque cible
    // (même principe que PV→Trémie, généralisé — voir §4bis dans le corps ST)
    SlowdownSensorTremie         : BOOL;        // --> [HW] Capteur PV — ralentissement avant Trémie (Direction=1)
    SlowdownSensorMaintenance    : BOOL;        // --> [HW] Capteur P1 — ralentissement avant Maintenance (Direction=-1)
    SlowdownSensorP1             : BOOL;        // --> [HW] Capteur P2 — ralentissement avant P1 (Direction=-1, arrêt propre pour travail)
    LimitSwitchFwd              : BOOL;        // --> [HW] Fin de course extrême avant
    LimitSwitchRev              : BOOL;        // --> [HW] Fin de course extrême arrière

    // 🔌 Spécifique ETHERCAT (image process EtherCAT, rafraîchie par EtherCatTask 4ms)
    DriveStatusWord              : WORD;       // --> [HW] Mot d'état AC600 lu depuis l'image d'entrée EtherCAT
    DriveActualFreqHz            : REAL;       // --> [HW] Fréquence réelle mesurée (Hz)

    BypassContactorCheck         : BOOL;       // --> [TST] TRUE = désactive StuckClosed/StuckOpen pour le frein (simulation)
    BypassLimitSwitch            : BOOL;       // --> [TST] TRUE = ignore les fins de course extrêmes
    BrakeFeedback                : BOOL;       // --> [HW] Retour physique direct : TRUE = frein OUVERT (desserré)
    // Compense le câblage moteur (U/V inversés) — UNIQUEMENT sur le mot de commande variateur
    // en sortie (§5bis). Direction/CommandedDirection reste partout ailleurs le sens SÉMANTIQUE
    // réel (+1 = physiquement vers Trémie), pour rester apparié aux vrais capteurs
    // (LimitSwitchFwd/Rev, SlowdownSensorXxx) quel que soit le câblage.
    InvertDriveDirection          : BOOL;

    // Réglages rampe (RETAIN)
    CfgRampAccelRate                : REAL := 20.0;    // --> [CFG] %/s — accélération
    CfgRampDecelNormalRate          : REAL := 40.0;    // --> [CFG] %/s — décélération normale
    CfgRampDecelFastRate            : REAL := 100.0;   // --> [CFG] %/s — décélération RAPIDE
    DirectionInterlockDelay      : TIME := T#200ms; // --> [CFG] Délai avant d'autoriser un changement de sens à l'arrêt

    // Réglages ETHERCAT uniquement (RETAIN)
    ApproachSpeedTremieHz        : REAL := 10.0;    // --> [CFG] Vitesse réduite d'approche Trémie en Hz (piloté par SlowdownSensorTremie)
    ApproachSpeedMaintenanceHz   : REAL := 10.0;    // --> [CFG] Vitesse réduite d'approche Maintenance en Hz (piloté par SlowdownSensorMaintenance)
    ApproachSpeedP1Hz            : REAL := 10.0;    // --> [CFG] Vitesse réduite d'approche P1 en Hz (piloté par SlowdownSensorP1)
    DriveFreqScaleMaxHz          : REAL := 60.0;    // --> [CFG] Échelle 0..100 % → MaxHz (câblé depuis _TranslationMaxFreq_Hz par PRG_07 — defaut 60.0 si non raccordé)

    // Réglages communs
    CaptorDebounce                : TIME := T#100ms; // --> [CFG] Filtrage capteur de position cible
    BrakeDelayContactClose        : TIME := T#100ms; // --> [CFG] Voir FB_Brake
    BrakeDelayMagnetise           : TIME := T#300ms; // --> [CFG] Voir FB_Brake
    BrakeDelayMotorDecel          : TIME := T#500ms; // --> [CFG] Voir FB_Brake
    BrakeFeedbackTimeout          : TIME := T#300ms; // --> [CFG] Strictement sous watchdog final 500 ms
END_VAR
VAR_OUTPUT
    Ready               : BOOL;   // <-- [STAT] FB prêt
    Busy                : BOOL;   // <-- [STAT] FB occupé
    Done                : BOOL;   // <-- [STAT] Action terminée
    Error               : BOOL;   // <-- [STAT] Synthèse défaut
    ErrorId             : WORD;        // <-- [DIAG] bit0: "Défaut frein Translation" - Brake.Error ; bit3: "Défaut variateur AC600" - défaut variateur (DriveStatusWord.4) ; bit6: "Limite extrême Translation atteinte" - Fdc extrême atteint
    State               : E_State;   // <-- [STAT] Etat courant
    StateAtError        : E_State;   // <-- [DIAG] Etat mémorisé au dernier défaut
    TargetReached        : BOOL;       // <-- [STAT] Capteur position cible
    RequestedDriveControlWord : WORD; // <-- [ACT] Demande métier AC600, arbitrée par FB_TranslationOutputInterlock_LD
    RequestedDriveFreqHz      : REAL; // <-- [ACT] Demande métier fréquence, arbitrée par FB_TranslationOutputInterlock_LD
    BrakeReleaseRequest       : BOOL; // <-- [ACT] Demande métier desserrage, issue de FB_Brake
    BrakeCommandOpenConfirmed : BOOL; // <-- [STAT] TRUE = frein ouvert = commande ouverture confirmée (depuis FB_Brake)
    BrakeContactorCheck  : ST_ContactorCheck; // <-- [DIAG] Diag contacteur frein
END_VAR
VAR
    Brake                : FB_Brake;       // * [INST] Séquence frein
    CycleTimeCalc        : FB_CycleTime;   // * [INST] Mesure temps de cycle
    SpeedRamp             : FB_Ramp;       // * [INST] Rampe de vitesse logicielle (PLC)
    ResetEdge            : R_TRIG;   // . [LOC] Front Reset
    ErrorEdge            : R_TRIG;   // . [LOC] Front Erreur
    DirectionChangeDelay : TON;            // . [LOC] Interlock changement de sens
    CommandedDirection   : INT;            // . [LOC] Sens réellement appliqué
    DirectionChangePending : BOOL;         // . [LOC] Force la rampe à 0 pendant une inversion de sens en attente
    PhysicalDriveDirection : INT;          // . [LOC] CommandedDirection compensé câblage (InvertDriveDirection) — UNIQUEMENT pour le mot de commande variateur, jamais pour l'appariement capteur
    RampTargetPct        : REAL;   // . [LOC] Cible rampe en %
    CaptorDebounceTon     : TON;    // . [LOC] Debounce capteur cible
    ArrivalEdge            : R_TRIG;   // . [LOC] Front arrivée sur capteur
    DirectionAtArrival     : INT;    // . [LOC] Sens d'arrivée mémorisé
    ArrivalLock             : BOOL;        // . [LOC] Arrêt exact sur capteur cible
    MovementRequested      : BOOL;         // . [LOC] Pilote FB_Brake
    FirstScanDone          : BOOL;   // . [LOC] Initialisation premier scan
    // Garde-fou watchdog : DriveActualFreqHz est un passthrough EtherCAT sans contrôle de fraîcheur.
    // Si la communication variateur se fige sur une dernière valeur ≥1.0 Hz, plus rien ne referme
    // le frein tant que ce garde-fou n'existe pas — même si SafeStop a déjà ramené la rampe théorique
    // à 0. Force le relâchement du frein 2s après la fin de la rampe théorique, quoi que dise
    // DriveActualFreqHz.
    TonBrakeRealFreqTimeout : TON;
END_VAR

// === IMPLEMENTATION ===

{region "§1 Gate et initialisation"}
// 🛑 1. GATE (Enable / PowerContactorEngaged) — neutralisation totale, sorties sûres
IF NOT Enable OR NOT PowerContactorEngaged THEN
    RequestedDriveControlWord := 0; RequestedDriveFreqHz := 0.0;

    Brake(Enable := FALSE, Reset := FALSE, MovementRequested := FALSE, ContactorFeedback := BrakeFeedback,
          DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
          DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout);
    BrakeReleaseRequest := Brake.BrakeCmd;
    BrakeCommandOpenConfirmed := Brake.BrakeCommandOpenConfirmed;
    BrakeContactorCheck := Brake.ContactorCheck;

    CommandedDirection := 0;
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    SpeedRamp(Target := 0.0, AccelRate := CfgRampAccelRate, DecelRate := CfgRampDecelFastRate, CycleTimeS := CycleTimeCalc.CycleTimeS);

    ArrivalLock := FALSE;

    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    RETURN;
END_IF;

// 🧹 Initialisation au premier scan : purge des résidus RAM d'un Online Change / Warm Start et évitement des alarmes transitoires
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

{endregion}

{region "§2 Acquisition commandes et position cible"}
Ready := TRUE;
CycleTimeCalc(DefaultValueS := 0.010);   // MainTask = 10 ms

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 📡 3. CAPTEUR POSITION CIBLE (debounce)
CaptorDebounceTon(IN := PositionSensorTarget, PT := CaptorDebounce);
TargetReached := CaptorDebounceTon.Q;

{endregion}

{region "§4 Consigne vitesse ralentissement verrou arrivee"}
// ⚙️ 4. CORE — arbitrage rampe : Enable > SafeStop > StartStop
// DirectionChangePending FORCE la cible à 0.0 dès qu'une inversion de sens est en attente —
// sans cela, la cible suit la magnitude joystick en continu et ne croise jamais le seuil
// d'arrêt (0.1%) qui autorise l'interlock §5 à basculer CommandedDirection. Une inversion
// plus rapide que la décélération réelle bloquerait indéfiniment le mouvement dans l'ancien sens.
DirectionChangePending := (Direction <> CommandedDirection) AND (CommandedDirection <> 0);

RampTargetPct := 0.0;
IF NOT SafeStop AND StartStop AND NOT DirectionChangePending THEN
    // Si butée fin de course extrême atteinte dans le sens de marche demandé, consigne forcée à 0
    // 🌐 BypassLimitSwitch = TRUE → ignore cette protection
    IF NOT BypassLimitSwitch AND ((Direction = 1 AND LimitSwitchFwd) OR (Direction = -1 AND LimitSwitchRev)) THEN
        RampTargetPct := 0.0;
    ELSE
        RampTargetPct := ABS(SpeedRefPct);
        // 🎚️ Consigne minimale joystick (1.0 Hz) : si un mouvement est demandé (SpeedRefPct > 0.0), la consigne est au moins égale à 1.0 Hz
        IF RampTargetPct > 0.0 THEN
            RampTargetPct := MAX(RampTargetPct, (1.0 / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
        END_IF;
    END_IF;
END_IF;

// ⏱️ 4bis. RALENTISSEMENT AUTO À L'APPROCHE (piloté par capteur)
// Chaque capteur "un cran avant" la cible finale déclenche SA propre vitesse réduite, dans SON
// sens de marche uniquement — le ralentissement ne se déclenche qu'à l'approche de sa cible :
//   PV       + Direction=1  → approche Trémie
//   P1       + Direction=-1 → approche Maintenance
//   P2       + Direction=-1 → approche P1 (arrêt propre pour travail)
IF (Direction = 1) AND SlowdownSensorTremie THEN
    RampTargetPct := LIMIT(0.0, RampTargetPct, (ApproachSpeedTremieHz / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
END_IF;
IF (Direction = -1) AND SlowdownSensorMaintenance THEN
    RampTargetPct := LIMIT(0.0, RampTargetPct, (ApproachSpeedMaintenanceHz / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
END_IF;
IF (Direction = -1) AND SlowdownSensorP1 THEN
    RampTargetPct := LIMIT(0.0, RampTargetPct, (ApproachSpeedP1Hz / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
END_IF;

// 🎯 4ter. VERROUILLAGE ANTI-REBONDS SENS EN BUTÉE (Trémie, P1, Maintenance, Fdc extrêmes)
// Dès qu'on touche un capteur d'arrêt (TargetReached, débounce 100ms) OU un fin de course dur
// (LimitSwitchFwd/Rev, §5bis — immédiat, non débounce, mais toute activation même brève arme le
// même verrou), le sens d'arrivée (DirectionAtArrival) est MÉMORISÉ et BLOQUÉ. Toute activation,
// même un instant, arme DirectionAtArrival comme un TargetReached — un Fdc qui s'ouvre quelques ms
// pendant le freinage ne doit pas laisser la rampe (encore haute en interne) revenir en sortie.
ArrivalEdge(CLK := TargetReached
                 OR (LimitSwitchFwd AND (CommandedDirection = 1))
                 OR (LimitSwitchRev AND (CommandedDirection = -1)));
IF ArrivalEdge.Q THEN
    DirectionAtArrival := CommandedDirection;
END_IF;

// Un retour au neutre, même SOUTENU (>100ms), ne doit JAMAIS lever le verrou — seul un vrai
// changement de sens (dégagement volontaire, sans ambiguïté) le fait. Sinon, un neutre 100ms+
// puis un réappui dans le MÊME sens (le capteur/Fdc restant au niveau haut en continu,
// TargetReached ne montre plus de front) contournerait le verrou et M3 repartirait vers la butée.
// On doit repartir dans l'AUTRE sens, jamais juste relâcher-réappuyer pareil. Instantané, jamais
// retardé (le dégagement doit rester rapide).
IF (Direction = DirectionAtArrival * (-1)) OR ResetEdge.Q OR (NOT TargetReached AND NOT LimitSwitchFwd AND NOT LimitSwitchRev) THEN
    DirectionAtArrival := 0;
END_IF;

// Bloque la consigne à 0 tant que l'ordre demande d'insister dans le sens d'arrivée verrouillé
ArrivalLock := (DirectionAtArrival <> 0) AND (Direction = DirectionAtArrival);
IF ArrivalLock THEN
    RampTargetPct := 0.0;
END_IF;

SpeedRamp(Target := RampTargetPct,
          AccelRate := CfgRampAccelRate,
          DecelRate := SEL(SafeStop, CfgRampDecelNormalRate, CfgRampDecelFastRate),
          CycleTimeS := CycleTimeCalc.CycleTimeS);

{endregion}

{region "§5 Interlock changement sens"}
// 🔒 5. INTERLOCK CHANGEMENT DE SENS — jamais Fwd+Rev simultanés (vitesse confirmée nulle)
IF Direction <> CommandedDirection THEN
    IF CommandedDirection = 0 AND Direction <> 0 THEN
        CommandedDirection := Direction;
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    ELSIF ABS(SpeedRamp.Current) < 0.1 THEN
        DirectionChangeDelay(IN := TRUE, PT := DirectionInterlockDelay);
        IF DirectionChangeDelay.Q THEN
            CommandedDirection := Direction;
            DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
        END_IF;
    ELSE
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    END_IF;
ELSE
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
END_IF;

{endregion}

{region "§5bis Commande variateur et protections fin course"}
// 🛑 Pilotage du frein : le mouvement est considéré actif tant que la consigne est supérieure à 0.1%
// OU que la fréquence réelle mesurée du variateur M3 est >= 1.0 Hz.
// Le frein de parking ne serre QUE lorsque la fréquence réelle variateur chute sous 1.0 Hz !
// Borné par un garde-fou 2s — DriveActualFreqHz n'a aucun contrôle de fraîcheur EtherCAT ; si la
// communication se fige sur une valeur ≥1.0 Hz (perte réseau en mouvement), rien d'autre en aval
// ne referme le frein (FB_TranslationOutputInterlock_LD ignore volontairement SafeStop par
// conception). Le garde-fou force la fermeture du frein 2s après la fin de la rampe THÉORIQUE, quoi
// que dise la mesure réelle — combine attente réelle (évite un serrage sur arbre encore tournant)
// et certitude de fermeture (n'attend jamais indéfiniment).
TonBrakeRealFreqTimeout(IN := NOT ((CommandedDirection <> 0) AND (ABS(SpeedRamp.Current) > 0.1)), PT := T#2s);
MovementRequested := ((CommandedDirection <> 0) AND (ABS(SpeedRamp.Current) > 0.1))
                     OR (ABS(DriveActualFreqHz) >= 1.0 AND NOT TonBrakeRealFreqTimeout.Q);

// 🔀 5bis. SORTIE PHYSIQUE (ETHERCAT)
RequestedDriveFreqHz := (ABS(SpeedRamp.Current) / 100.0) * DriveFreqScaleMaxHz;

// Compensation câblage moteur appliquée ICI SEULEMENT, sur le mot de commande —
// CommandedDirection (sécurité/capteurs juste au-dessus, §4/§4bis/§4ter) reste le sens réel.
PhysicalDriveDirection := SEL(InvertDriveDirection, CommandedDirection, CommandedDirection * (-1));

// Pilotage nominal Given Command 1 (0x3101) :
// 0: None, 1: Forward, 2: Reverse, 7: Reset
IF Reset THEN
    RequestedDriveControlWord := 7; // Reset défaut variateur
ELSIF Error THEN
    RequestedDriveControlWord := 0; // Arrêt sur défaut
ELSIF MovementRequested THEN
    IF PhysicalDriveDirection = 1 THEN
        RequestedDriveControlWord := 1; // Marche avant
    ELSIF PhysicalDriveDirection = -1 THEN
        RequestedDriveControlWord := 2; // Marche arrière
    ELSE
        RequestedDriveControlWord := 0;
    END_IF;
ELSE
    RequestedDriveControlWord := 0;
END_IF;

// Sécurité : si Fdc extrême atteint dans le sens de marche, coupure commande immédiate (sans rampe ni couple)
// 🌐 BypassLimitSwitch = TRUE → ignore cette protection (test/mise en service)
IF NOT BypassLimitSwitch AND ((CommandedDirection = 1 AND LimitSwitchFwd) OR (CommandedDirection = -1 AND LimitSwitchRev)) THEN
    RequestedDriveControlWord := 0;
    RequestedDriveFreqHz := 0.0;
    SpeedRamp(Target := 0.0, AccelRate := 0.0, DecelRate := 100000.0, CycleTimeS := 1.0);
END_IF;

{endregion}

{region "§6 Commande frein"}
// 🛑 6. FREIN (composé, réutilisé tel quel)
Brake(Enable := TRUE, Reset := Reset, MovementRequested := MovementRequested,
      ContactorFeedback := BrakeFeedback,
      DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
      DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout,
      BypassContactorCheck := BypassContactorCheck);
BrakeReleaseRequest := Brake.BrakeCmd;
BrakeCommandOpenConfirmed := Brake.BrakeCommandOpenConfirmed;
BrakeContactorCheck := Brake.ContactorCheck;

// 🛡️ FB_Translation ne décide plus la frontière finale : il expose uniquement
// ses demandes métier. SafeStop est déjà appliqué dans la rampe rapide §4 : tant que
// la vitesse ne vaut pas zéro, la demande et le desserrage suivent la décélération.
// FB_TranslationOutputInterlock_LD ne doit jamais transformer SafeStop en coupure sèche.

{endregion}

{region "§7 Diagnostic etat et repli defaut"}
// 🧾 7. ERRORID (bitfield, cumul)
IF Brake.Error THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// Défaut variateur (bit3) : lu via EtherCAT (DriveStatusWord.4)
IF DriveStatusWord.4 THEN
    ErrorId := ErrorId OR 16#0008;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFF7;
END_IF;

// 🚧 Défaut fin de course extrême (bit6) — si bypassé, on NETTOIE le bit résiduel
IF BypassLimitSwitch THEN
    ErrorId := ErrorId AND 16#FFBF;   // Nettoie le bit 6 (évite résidu d'avant activation)
ELSE
    // Activé UNIQUEMENT en cas de tentative d'avancer DANS la butée active (libéré si dégagement en sens inverse)
    IF (CommandedDirection = 1 AND LimitSwitchFwd) OR (CommandedDirection = -1 AND LimitSwitchRev) THEN
        ErrorId := ErrorId OR 16#0040;
    ELSE
        ErrorId := ErrorId AND 16#FFBF;
    END_IF;
END_IF;

Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// 🚦 8. STATE MACHINE (phase)
IF (NOT StartStop OR SafeStop) AND ABS(SpeedRamp.Current) > 0.1 THEN
    State := E_State.STOPPING;
ELSIF ABS(SpeedRamp.Current) > 0.1 THEN
    State := E_State.BUSY;
ELSE
    State := E_State.READY;
END_IF;

Busy := (State = E_State.BUSY) OR (State = E_State.STOPPING);
Done := FALSE;

// 🛡️ 9. SORTIE SÛRE SUR DÉFAUT
IF Error THEN
    RequestedDriveControlWord := 0; RequestedDriveFreqHz := 0.0;
    BrakeReleaseRequest := FALSE;
END_IF;

{endregion}

// ═══════════════════════════════════════════════════════════════
// 🧪 FB_TranslationValidation — Suite de test Translation M3
// ───────────────────────────────────────────────────────────────
// 📄 Doc métier : DOC/AF_Partie-11_Fonction_Translation_v1.9.md
// 🎯 Valide les surveillances de sécurité de FB_Safety_Translation :
//    TC-T1 Fin de course extrême, TC-T2 Méca B (incohérence à l'arrêt),
//    TC-T3 Méca A (mouvement non commandé), TC-T4 les 6 mots valides +
//    limites extrêmes, TC-T5 incohérence mot capteurs (SafeStop+PowerCutOff),
//    TC-T6 ralentissement PV (instance FB_Translation isolée).
// 🆕 Tranche verticale NEUVE (2026-07-22, audit DOC/AUDITS/TEST_FRAMEWORK_AUDIT_v1.0.md) :
//    moteur dédié, composé d'objets à responsabilité unique sous CORE/ —
//    N'INSTANCIE NI FB_TestSequencer NI les anciennes BRICKS
//    (FB_TestCheck/FB_Timeout/FB_TestStimulus/...). Les autres suites
//    (Safety/Bucket/Encoder/Modes/Heartbeat) restent inchangées sur
//    l'ancien moteur générique.
//      - FB_TranslationTestPlan          : tables déclaratives + validation
//      - FB_TranslationStepExecutor      : exécution étape/check + cantonnement de cas
//      - FB_TranslationTestRuntime       : cycle de vie (Start -> Fixture -> Executor -> Finalize)
//      - FB_TranslationTestFixture       : précondition (gate Niveau 1/2, PRECONDITION_FAILED explicite)
//      - FB_TranslationTestCleanup       : neutralité (source de vérité unique)
//      - FB_TranslationReportFinalizer   : rapport existant (ST_TestSuiteReport) + résultat plat (ST_TranslationTestResult)
// 🔒 API publique : Start / Abort / CaseId (0=toutes les cases, 1..6=case
//    ciblée) — JAMAIS de FirstStepId exposé (audit v1.0 C2).
// 🔑 Les index de sondes (Sig*) sont possédés ICI (ce fichier), transmis en
//    VAR_INPUT à FB_TranslationTestPlan à chaque appel — aucun accès
//    croisé "instPlan.SigXxx" en retour.
// ⚠️ Hors périmètre (non testé ici, nécessiterait des overrides
//    supplémentaires sur les diagnostics bus) : bit0 (perte Joystick
//    CANopen), bit1 (perte com EtherCAT variateur), bit2 (rotation
//    de phases), bit3 (thermique frein commun).
// ═══════════════════════════════════════════════════════════════

FUNCTION_BLOCK PUBLIC FB_TranslationValidation
VAR_INPUT
    Start   : BOOL; // Commande de démarrage
    Abort   : BOOL; // Commande d'abandon
    CaseId  : INT;  // 0 = toutes les cases (1..6) ; 1..6 = case ciblée uniquement
END_VAR
VAR_OUTPUT
    Busy                : BOOL;
    Done                : BOOL;
    AnyFailed           : BOOL;
    SimGateOk           : BOOL;        // Indique si la simulation est autorisée (Niveau 1/2)
    ActiveStimulusId    : INT;
    StepElapsed         : TIME;
    Report              : ST_TestSuiteReport;      // 📊 Rapport existant — compat GVL_PLC_Tests/IHM/manager
    Result              : ST_TranslationTestResult; // 📋 Résultat plat clair — nouveau
    TerminalState       : E_TestTerminalState;
    ConfigError         : BOOL;
    ConfigErrorStepId   : INT;
    ConfigErrorCheckIdx : INT;
    ErrorCode           : INT;
    ErrorMessage        : STRING(160);
END_VAR
VAR CONSTANT
    // 🏷️ Index des sondes — source de vérité UNIQUE, transmis à instPlan
    // en VAR_INPUT (jamais lus en retour via une instance).
    SigHealthyIdle          : INT := 1;
    SigLimitSwitchError     : INT := 2;
    SigPowerCutOff          : INT := 3;
    SigErrorIdT1NoParasite  : INT := 4;
    SigMecaBError           : INT := 5;
    SigErrorIdT2NoParasite  : INT := 6;
    SigMecaAError           : INT := 7;
    SigErrorIdT3NoParasite  : INT := 8;
    SigDecoderIncoherent    : INT := 9;
    SigLimitFwd             : INT := 10;
    SigLimitRev             : INT := 11;
    SigSensorIncoherentErr  : INT := 12;
    SigErrorIdT5NoParasite  : INT := 13; // DINT
    SigSlowdownFreqHz       : INT := 14; // REAL
END_VAR
VAR
    // 🧩 Objets CORE — composition, responsabilité unique chacun
    instPlan    : FB_TranslationTestPlan;
    instRuntime : FB_TranslationTestRuntime;
    instCleanup : FB_TranslationTestCleanup;

    // 📋 Tables déclaratives — possédées ici, construites par instPlan
    StepTable  : ARRAY[1..GVL_PLC_Tests_Const.MaxSteps]      OF ST_TestStepConfig;
    CheckTable : ARRAY[1..GVL_PLC_Tests_Const.MaxChecks]     OF ST_TestCheckConfig;
    CaseTable  : ARRAY[1..GVL_PLC_Tests_Const.MaxTestCases]  OF ST_TestCaseConfig;

    // 📥 Banque de sondes
    ProbeBool : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeBool] OF BOOL;
    ProbeDint : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeDint] OF DINT;
    ProbeReal : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeReal] OF REAL;

    // 🆕 TC-T6 — instance ISOLÉE de FB_Translation (pas l'instance machine réelle
    // instTranslationM3) pour tester le ralentissement PV en pilotant Direction/StartStop/SpeedRefPct
    // directement, sans dépendre de l'arbitrage Mode de PRG_07_TranslationControl.
    instTranslationUnderTest : FB_Translation;
    UnderTestDirection       : INT;
    UnderTestStartStop       : BOOL;
    UnderTestSlowdownSensor  : BOOL;
    ResetFaults              : BOOL;
    NeutralConfirmedPrevious : BOOL; // Retour cleanup du scan précédent vers le runtime
END_VAR
// === IMPLEMENTATION ===

// 1. 🛡️ GATE Niveau 1/2 — calculé en continu (lu par le manager Niveau 3, même hors Busy)
// Refuse si un des équipements M3 est déjà recâblé réel.
SimGateOk := NOT GVL_Simulation.SensorTranslationPositionIsReal
         AND NOT GVL_Simulation.SensorM3ContactorFeedbackIsReal
         AND NOT GVL_Simulation.BusVariateurM3IsReal;

// 2. 📋 PLAN — construction (une fois) + validation ; les index de sondes
//    sont transmis ICI, jamais relus depuis l'instance.
instPlan(
    SigHealthyIdle := SigHealthyIdle, SigLimitSwitchError := SigLimitSwitchError,
    SigPowerCutOff := SigPowerCutOff, SigErrorIdT1NoParasite := SigErrorIdT1NoParasite,
    SigMecaBError := SigMecaBError, SigErrorIdT2NoParasite := SigErrorIdT2NoParasite,
    SigMecaAError := SigMecaAError, SigErrorIdT3NoParasite := SigErrorIdT3NoParasite,
    SigDecoderIncoherent := SigDecoderIncoherent, SigLimitFwd := SigLimitFwd,
    SigLimitRev := SigLimitRev, SigSensorIncoherentErr := SigSensorIncoherentErr,
    SigErrorIdT5NoParasite := SigErrorIdT5NoParasite, SigSlowdownFreqHz := SigSlowdownFreqHz,
    StepTable := StepTable, CheckTable := CheckTable, CaseTable := CaseTable
);

// 3. 📥 ACQUIRE — sondes réelles + instance isolée TC-T6 (pilotée par le
//    stimulus décidé au scan précédent, cf. §5 STIMULI)
ProbeBool[SigHealthyIdle]      := NOT PRG_03_Safety.instSafetyTranslationM3.Error;
ProbeBool[SigLimitSwitchError] := PRG_03_Safety.instSafetyTranslationM3.ErrorLimitSwitch;
ProbeBool[SigPowerCutOff]      := PRG_03_Safety.instSafetyTranslationM3.PowerCutOff;
ProbeDint[SigErrorIdT1NoParasite] := WORD_TO_DINT(PRG_03_Safety.instSafetyTranslationM3.ErrorId);
ProbeBool[SigMecaBError]       := PRG_03_Safety.instSafetyTranslationM3.ErrorMecaB;
ProbeDint[SigErrorIdT2NoParasite] := WORD_TO_DINT(PRG_03_Safety.instSafetyTranslationM3.ErrorId);
ProbeBool[SigMecaAError]       := PRG_03_Safety.instSafetyTranslationM3.ErrorMecaA;
ProbeDint[SigErrorIdT3NoParasite] := WORD_TO_DINT(PRG_03_Safety.instSafetyTranslationM3.ErrorId);
ProbeBool[SigDecoderIncoherent]   := PRG_00_Inputs.instPositionDecoder.Incoherent;
ProbeBool[SigLimitFwd]            := PRG_00_Inputs.instPositionDecoder.LimitSwitchFwd;
ProbeBool[SigLimitRev]            := PRG_00_Inputs.instPositionDecoder.LimitSwitchRev;
ProbeBool[SigSensorIncoherentErr] := PRG_03_Safety.instSafetyTranslationM3.ErrorSensorIncoherent;
ProbeDint[SigErrorIdT5NoParasite] := WORD_TO_DINT(PRG_03_Safety.instSafetyTranslationM3.ErrorId);

instTranslationUnderTest(
    Enable := TRUE, Reset := ResetFaults, EmergencyStopOk := TRUE, Mode := E_Mode.MAINT_N1,
    StartStop := UnderTestStartStop, SafeStop := FALSE,
    Direction := UnderTestDirection, SpeedRefPct := 100.0,
    PositionSensorTarget := FALSE, SlowdownSensor := UnderTestSlowdownSensor,
    LimitSwitchFwd := FALSE, LimitSwitchRev := FALSE,
    DriveStatusWord := 0, DriveActualFreqHz := 0.0,
    BypassContactorCheck := TRUE, BrakeFeedback := FALSE
);
ProbeReal[SigSlowdownFreqHz] := instTranslationUnderTest.DriveFreqRefHz;

// 4. ♻️ RUNTIME — cycle de vie complet (Fixture -> Executor -> Finalize)
instRuntime(
    Start := Start, Abort := Abort, CaseId := CaseId,
    PlanConfigError := instPlan.ConfigError,
    PlanConfigErrorStepId := instPlan.ConfigErrorStepId,
    PlanConfigErrorCheckIdx := instPlan.ConfigErrorCheckIdx,
    PlanConfigErrorMessage := instPlan.ConfigErrorMessage,
    SimulationModeActive := GVL_Simulation.SimulationModeActive,
    SimGateOk := SimGateOk,
    NeutralConfirmed := NeutralConfirmedPrevious,
    StepTable := StepTable, CheckTable := CheckTable, CaseTable := CaseTable,
    ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal,
    Report := Report, Result := Result,
    Busy => Busy, Done => Done, AnyFailed => AnyFailed,
    ActiveStimulusId => ActiveStimulusId, StepElapsed => StepElapsed,
    TerminalState => TerminalState, ConfigError => ConfigError,
    ConfigErrorStepId => ConfigErrorStepId, ConfigErrorCheckIdx => ConfigErrorCheckIdx,
    ErrorCode => ErrorCode, ErrorMessage => ErrorMessage
);

// 5. ⚡ STIMULI — vecteur complet : neutre d'abord, surcharge ensuite.
//    Aucun champ ne dépend de la branche ou du scan précédent.
GVL_PLC_Tests.OverrideM3AtTremie := FALSE;
GVL_PLC_Tests.OverrideM3BrakeStuckOpen := FALSE;
GVL_PLC_Tests.OverrideM3PhantomFreq := FALSE;
GVL_PLC_Tests.OverrideM3SensorsWordActive := FALSE;
GVL_PLC_Tests.OverrideM3SensorsWord := 0;
UnderTestDirection := 0;
UnderTestStartStop := FALSE;
UnderTestSlowdownSensor := FALSE;
ResetFaults := FALSE;

IF NOT instRuntime.CleanupRequest THEN
    CASE ActiveStimulusId OF
        1: ResetFaults := TRUE; // Setup/teardown : reset sur front externe conditionné
        2: GVL_PLC_Tests.OverrideM3AtTremie := TRUE;
        3: GVL_PLC_Tests.OverrideM3BrakeStuckOpen := TRUE;
        4: GVL_PLC_Tests.OverrideM3PhantomFreq := TRUE;
        5: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#11111;
        6: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#01111;
        7: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#00111;
        8: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#00011;
        9: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#00001;
        10: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#00000;
        11: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#10101;
        12: UnderTestDirection := 1; UnderTestStartStop := TRUE;
        13: UnderTestDirection := 1; UnderTestStartStop := TRUE; UnderTestSlowdownSensor := TRUE;
    END_CASE;
END_IF;

// 🧹 Confirmation calculée APRÈS écriture du vecteur neutre ; consommée
// par le runtime au scan suivant pour garantir la propagation cyclique.
instCleanup(Apply := instRuntime.CleanupRequest);
NeutralConfirmedPrevious := instCleanup.NeutralConfirmed
    AND NOT GVL_PLC_Tests.OverrideM3AtTremie
    AND NOT GVL_PLC_Tests.OverrideM3BrakeStuckOpen
    AND NOT GVL_PLC_Tests.OverrideM3PhantomFreq
    AND NOT GVL_PLC_Tests.OverrideM3SensorsWordActive
    AND (GVL_PLC_Tests.OverrideM3SensorsWord = 0)
    AND (UnderTestDirection = 0)
    AND NOT UnderTestStartStop
    AND NOT UnderTestSlowdownSensor
    AND NOT ResetFaults;

// Recopie IHM/métier — reset partagé avec la suite Safety (même domaine
// "sécurité/métier", voir PRG_09_Supervision.FaultMachineReset_IHM), sans
// conflit car les suites s'exécutent toujours de façon mutuellement exclusive
// (FB_PLC_Tests_Management n'active qu'une suite à la fois).
IF Busy THEN
    GVL_IHM.Modes.Cmd.BtnFaultReset := ResetFaults;
END_IF;

// ═══════════════════════════════════════════════════════════════
// 🧪 FB_TranslationTestRuntime — Cycle de vie protégé Translation M3
// ───────────────────────────────────────────────────────────────
// 🎯 Responsabilité UNIQUE : posséder le lifecycle atomique du run :
//    IDLE → RUN → CLEANUP → WAIT_NEUTRAL → VERIFY → TERMINAL.
// 🔒 Aucun terminal n'est publié avant neutralité confirmée.
// ═══════════════════════════════════════════════════════════════

FUNCTION_BLOCK PUBLIC FB_TranslationTestRuntime
VAR_INPUT
    Start   : BOOL;
    Abort   : BOOL;
    CaseId  : INT;
    PlanConfigError         : BOOL;
    PlanConfigErrorStepId   : INT;
    PlanConfigErrorCheckIdx : INT;
    PlanConfigErrorMessage  : STRING(160);
    SimulationModeActive    : BOOL;
    SimGateOk               : BOOL;
    NeutralConfirmed        : BOOL; // Neutralité réellement appliquée au scan précédent
    WatchdogLimitMs         : DINT := 180000; // Paramétrable pour autotest du framework
    CleanupTimeoutScans     : INT := 20;      // Délai max de confirmation du neutre
END_VAR
VAR_IN_OUT
    StepTable  : ARRAY[1..GVL_PLC_Tests_Const.MaxSteps]      OF ST_TestStepConfig;
    CheckTable : ARRAY[1..GVL_PLC_Tests_Const.MaxChecks]     OF ST_TestCheckConfig;
    CaseTable  : ARRAY[1..GVL_PLC_Tests_Const.MaxTestCases]  OF ST_TestCaseConfig;
    ProbeBool  : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeBool]  OF BOOL;
    ProbeDint  : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeDint]  OF DINT;
    ProbeReal  : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeReal]  OF REAL;
    Report     : ST_TestSuiteReport;
    Result     : ST_TranslationTestResult;
END_VAR
VAR_OUTPUT
    Busy                : BOOL;
    Done                : BOOL;
    AnyFailed           : BOOL;
    ActiveStimulusId    : INT;
    StepElapsed         : TIME;
    TerminalState       : E_TestTerminalState;
    ConfigError         : BOOL;
    ConfigErrorStepId   : INT;
    ConfigErrorCheckIdx : INT;
    ErrorCode           : INT;
    ErrorMessage        : STRING(160);
    StartRejected       : BOOL; // Impulsion : Start reçu hors IDLE/TERMINAL
    CleanupRequest      : BOOL; // Niveau : imposer le vecteur neutre complet
END_VAR
VAR CONSTANT
    RuntimeIdle        : INT := 0;
    RuntimeRun         : INT := 10;
    RuntimeCleanup     : INT := 20;
    RuntimeWaitNeutral : INT := 30;
    RuntimeVerify      : INT := 40;
    RuntimeTerminal    : INT := 50;
END_VAR
VAR
    instFixture   : FB_TranslationTestFixture;
    instExecutor  : FB_TranslationStepExecutor;
    instFinalizer : FB_TranslationReportFinalizer;
    StartTrig     : R_TRIG;
    RuntimeState  : INT := 0;
    ExecutorStart : BOOL;
    ExecutorAbort : BOOL;
    RunStartPulse : BOOL;
    FinalizePulse : BOOL;
    PendingTerminalState : E_TestTerminalState;
    PendingErrorCode     : INT;
    PendingErrorMessage  : STRING(160);
    SuiteElapsed         : TIME;
    NeutralWaitScans     : INT;
    CleanupElapsedScans  : INT;
END_VAR
// === IMPLEMENTATION ===
StartTrig(CLK := Start);
StartRejected := FALSE;
ExecutorStart := FALSE;
ExecutorAbort := FALSE;
RunStartPulse := FALSE;
FinalizePulse := FALSE;
CleanupRequest := (RuntimeState = RuntimeCleanup)
               OR (RuntimeState = RuntimeWaitNeutral)
               OR (RuntimeState = RuntimeVerify);

// 🎮 Un Start pendant un run/cleanup est refusé sans modifier le run actif.
IF StartTrig.Q AND RuntimeState <> RuntimeIdle AND RuntimeState <> RuntimeTerminal THEN
    StartRejected := TRUE;
END_IF;

// 🚪 Fixture appelée CHAQUE scan : son R_TRIG interne est ainsi toujours réarmé.
instFixture(CheckRequested := StartTrig.Q,
            SimulationModeActive := SimulationModeActive,
            SimGateOk := SimGateOk);

// 🟢 Nouveau run accepté depuis IDLE ou TERMINAL.
IF StartTrig.Q AND (RuntimeState = RuntimeIdle OR RuntimeState = RuntimeTerminal) THEN
    RunStartPulse := TRUE;
    Done := FALSE;
    SuiteElapsed := T#0s;
    NeutralWaitScans := 0;
    CleanupElapsedScans := 0;
    PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    PendingErrorCode := 0;
    PendingErrorMessage := '';

    IF PlanConfigError THEN
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        PendingErrorCode := 1002;
        PendingErrorMessage := CONCAT('Table invalide : ', PlanConfigErrorMessage);
        RuntimeState := RuntimeCleanup;
    ELSIF CaseId < 0 OR CaseId > 6 THEN
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        PendingErrorCode := 1001;
        PendingErrorMessage := 'CaseId invalide (attendu 0..6)';
        RuntimeState := RuntimeCleanup;
    ELSIF instFixture.FixtureFailed THEN
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_PRECONDITION_FAILED;
        PendingErrorCode := 1010;
        PendingErrorMessage := CONCAT('PRECONDITION_FAILED : ', instFixture.FailReason);
        RuntimeState := RuntimeCleanup;
    ELSE
        ExecutorStart := TRUE;
        RuntimeState := RuntimeRun;
    END_IF;
END_IF;

// 🛡️ Causes de sortie du RUN : watchdog > gate perdue > abort opérateur.
IF RuntimeState = RuntimeRun THEN
    SuiteElapsed := SuiteElapsed + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
    IF SuiteElapsed >= DINT_TO_TIME(WatchdogLimitMs) THEN
        ExecutorAbort := TRUE;
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_WATCHDOG_TIMEOUT;
        PendingErrorCode := 1020;
        PendingErrorMessage := 'Watchdog suite Translation expire';
    ELSIF NOT SimulationModeActive OR NOT SimGateOk THEN
        ExecutorAbort := TRUE;
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_PRECONDITION_FAILED;
        PendingErrorCode := 1011;
        PendingErrorMessage := 'Gate Translation perdue pendant le run';
    ELSIF Abort THEN
        ExecutorAbort := TRUE;
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_ABORTED;
        PendingErrorCode := 1030;
        PendingErrorMessage := 'Abandon operateur';
    END_IF;
END_IF;

// 🪜 L'exécuteur ne possède que les étapes, jamais le terminal public.
instExecutor(
    Start := ExecutorStart,
    Abort := ExecutorAbort,
    CaseId := CaseId,
    StepTable := StepTable,
    CheckTable := CheckTable,
    CaseTable := CaseTable,
    ProbeBool := ProbeBool,
    ProbeDint := ProbeDint,
    ProbeReal := ProbeReal
);

IF RuntimeState = RuntimeRun AND instExecutor.RunDone THEN
    IF PendingTerminalState = E_TestTerminalState.TEST_TERMINAL_NONE THEN
        PendingTerminalState := instExecutor.TerminalState;
        IF instExecutor.ConfigError THEN
            PendingErrorCode := 1003;
            PendingErrorMessage := 'Garde-fou runtime : transition invalide';
        END_IF;
    END_IF;
    RuntimeState := RuntimeCleanup;
    NeutralWaitScans := 0;
END_IF;

// 🧹 Tous les chemins imposent au moins deux scans complets au neutre.
IF RuntimeState = RuntimeCleanup THEN
    CleanupRequest := TRUE;
    NeutralWaitScans := 0;
    CleanupElapsedScans := 0;
    RuntimeState := RuntimeWaitNeutral;
ELSIF RuntimeState = RuntimeWaitNeutral THEN
    CleanupRequest := TRUE;
    NeutralWaitScans := NeutralWaitScans + 1;
    CleanupElapsedScans := CleanupElapsedScans + 1;
    IF NeutralWaitScans >= 2 THEN
        RuntimeState := RuntimeVerify;
    END_IF;
ELSIF RuntimeState = RuntimeVerify THEN
    CleanupRequest := TRUE;
    CleanupElapsedScans := CleanupElapsedScans + 1;
    IF NeutralConfirmed THEN
        FinalizePulse := TRUE;
        RuntimeState := RuntimeTerminal;
        Done := TRUE;
    ELSIF CleanupElapsedScans >= CleanupTimeoutScans THEN
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        PendingErrorCode := 1040;
        PendingErrorMessage := 'Cleanup Translation non confirme';
        FinalizePulse := TRUE;
        RuntimeState := RuntimeTerminal;
        Done := TRUE;
    END_IF;
END_IF;

// 📊 Le rapport consomme directement chaque verdict, même consécutif.
instFinalizer(
    RunStart := RunStartPulse,
    RequestedCaseId := CaseId,
    Busy := (RuntimeState = RuntimeRun),
    StepVerdict := instExecutor.StepVerdict,
    StepId := instExecutor.VerdictStepId,
    StepCaseId := instExecutor.VerdictCaseId,
    StepPassed := instExecutor.VerdictPassed,
    StepFailReason := instExecutor.VerdictFailReason,
    StepFailedCheckIdx := instExecutor.VerdictFailedCheckIdx,
    StepDuration := instExecutor.VerdictDuration,
    StepObservedBool := instExecutor.VerdictObservedBool,
    StepObservedDint := instExecutor.VerdictObservedDint,
    StepObservedReal := instExecutor.VerdictObservedReal,
    Finalize := FinalizePulse,
    TerminalState := PendingTerminalState,
    ErrorCode := PendingErrorCode,
    ErrorMessage := PendingErrorMessage,
    StepTable := StepTable,
    CaseTable := CaseTable,
    Report := Report,
    Result := Result
);

// 📤 Publication : Busy inclut cleanup ; aucun stimulus métier hors RUN.
Busy := (RuntimeState = RuntimeRun)
     OR (RuntimeState = RuntimeCleanup)
     OR (RuntimeState = RuntimeWaitNeutral)
     OR (RuntimeState = RuntimeVerify);
IF RuntimeState = RuntimeRun THEN
    ActiveStimulusId := instExecutor.ActiveStimulusId;
ELSE
    ActiveStimulusId := 0;
END_IF;
StepElapsed := instExecutor.StepElapsed;
TerminalState := Result.TerminalState;
AnyFailed := Result.AnyFailed;
ConfigError := PlanConfigError OR instExecutor.ConfigError;
IF PlanConfigError THEN
    ConfigErrorStepId := PlanConfigErrorStepId;
    ConfigErrorCheckIdx := PlanConfigErrorCheckIdx;
ELSE
    ConfigErrorStepId := instExecutor.ConfigErrorStepId;
    ConfigErrorCheckIdx := 0;
END_IF;
ErrorCode := Result.ErrorCode;
ErrorMessage := Result.ErrorMessage;

(* ═══════════════════════════════════════════════════════════════
   📥 PRG_INPUTS_LD — Affichage qualifié des entrées TOR (PROGRAMME LADDER)
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF_Partie-06_Acquisition_Qualification_IO_v2.0.md §2
   🎨 Rôle : conditionner les 19 E/S TOR retenues du traçage legacy via FB_Input.
              Aucune décision métier (SafeStop, mode, commande) n'est prise ici.
   🔗 Dépendances : PRG_02_Acquisition_CFC produit HwIn ; consommateurs = Safety/Modes/Cycle/Supervision.
   ═══════════════════════════════════════════════════════════════ *)

PROGRAM PRG_01_Inputs_LD

VAR_INPUT
    HwIn : ST_HardwareImage;    (* Image matérielle qualifiée produite par PRG_02_Acquisition_CFC *)
END_VAR

VAR_OUTPUT
    // ── [PUISSANCE & SÉCURITÉ COMMUNE] ─────────────────────────────────────────────────────
    PowerContactorEngaged   : BOOL := TRUE;   (* TRUE = contacteur de puissance engagé / portail maître OK *)
    EmergencyChainClosed    : BOOL := TRUE;   (* TRUE = boucle AU fermée (coup-de-poing + contact PLC) *)
    PhaseRotationOk         : BOOL := TRUE;   (* TRUE = rotation des phases électriques correcte *)
    BrakeThermalFeedback    : BOOL := TRUE;   (* TRUE = thermique freins M1/M2/M3 commun OK *)

    // ── [TREUILS M1 / M2] ─────────────────────────────────────────────────────────────────
    TopPositionSensor       : BOOL := TRUE;   (* TRUE = fin de course haut M1/M2 libre / non atteinte *)
    SlackCableSwitch        : BOOL := TRUE;   (* TRUE = câble M2 tendu / capteur mou non déclenché *)
    M1FwdRevSpeedFeedbackOff: BOOL := TRUE;   (* TRUE = tous contacteurs M1 retombés / aucun collage *)
    M1ThermalFeedback       : BOOL := TRUE;   (* TRUE = thermique moteur M1 OK *)
    M1BrakeFeedback         : BOOL := TRUE;   (* TRUE = frein M1 OUVERT (desserré) — polarité physique directe *)
    M2FwdRevSpeedFeedbackOff: BOOL := TRUE;   (* TRUE = tous contacteurs M2 retombés / aucun collage *)
    M2ThermalFeedback       : BOOL := TRUE;   (* TRUE = thermique moteur M2 OK *)
    M2BrakeFeedback         : BOOL := TRUE;   (* TRUE = frein M2 OUVERT (desserré) — polarité physique directe *)

    // ── [KOBOLD FOND] ──────────────────────────────────────────────────────────────────────
    KoboldContactFond       : BOOL;           (* TRUE = détecteur de fond Kobold en contact *)

    // ── [TRANSLATION M3] ───────────────────────────────────────────────────────────────────
    TranslationPosTremie       : BOOL;       (* TRUE = translation en position Trémie *)
    TranslationPosPV           : BOOL;       (* TRUE = translation en zone pré-ralentissement PV *)
    TranslationPosP2           : BOOL;       (* TRUE = translation en position P2 *)
    TranslationPosP1           : BOOL;       (* TRUE = translation en position P1 *)
    TranslationPosMaintenance  : BOOL;       (* TRUE = translation en position Maintenance *)
    M3BrakeFeedback            : BOOL := TRUE;   (* TRUE = frein M3 OUVERT (desserré) — polarité physique directe *)

END_VAR

VAR
    // ── [Instances de qualification FB_Input] ───────────────────────────────────────────────
    instPowerContactorEngaged     : FB_Input;
    instEmergencyChainClosed      : FB_Input;
    instTopPositionSensor         : FB_Input;
    instSlackCableSwitch          : FB_Input;
    instKoboldContactFond         : FB_Input;
    instCtrlPhaseRotation         : FB_Input;
    instBrakeThermalFeedback      : FB_Input;
    instM1FwdRevSpeedFeedbackOff  : FB_Input;
