FUNCTION_BLOCK FB_TestSequencer
VAR_INPUT
    Start       : BOOL;              // Front : lance la suite
    Abort       : BOOL;              // Niveau : arrêt immédiat propre
    CaseId      : INT;               // 0=tous ; 1..MaxTestCases=cas ciblé
END_VAR
VAR_IN_OUT                           // 🔗 zéro copie
    StepTable      : ARRAY[1..GVL_PLC_Tests_Const.MaxSteps]      OF ST_TestStepConfig;
    CheckTable     : ARRAY[1..GVL_PLC_Tests_Const.MaxChecks]     OF ST_TestCheckConfig;
    CaseTable      : ARRAY[1..GVL_PLC_Tests_Const.MaxTestCases]  OF ST_TestCaseConfig;
    InvariantTable : ARRAY[1..GVL_PLC_Tests_Const.MaxInvariants] OF ST_TestInvariantConfig;
    ProbeBool      : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeBool]  OF BOOL;
    ProbeDint      : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeDint]  OF DINT;
    ProbeReal      : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeReal]  OF REAL;
    Report         : ST_TestSuiteReport;
END_VAR
VAR_OUTPUT
    Busy                : BOOL;
    Done                : BOOL;
    AnyFailed           : BOOL;
    ConfigError         : BOOL;      // 🔒 Table invalide -> refus de lancer
    ConfigErrorStepId   : INT;
    ConfigErrorCheckIdx : INT;
    TerminalState       : E_TestTerminalState;
    ErrorCode           : INT;
    ErrorMessage        : STRING(160);
    CurrentStepId       : INT;
    ActiveStimulusId    : INT;       // ⚡ consommé par le domaine
    StepElapsed         : TIME;      // Pour l'IHM
END_VAR
VAR
    StartTrig           : R_TRIG;
    StepTimer           : TON;
    DwellTimer          : TON;
    Checks              : ARRAY[1..GVL_PLC_Tests_Const.MaxChecksPerStep] OF FB_TestCheck;
    InvChecks           : ARRAY[1..GVL_PLC_Tests_Const.MaxInvariants]    OF FB_TestCheck;
    InvArmed            : ARRAY[1..GVL_PLC_Tests_Const.MaxInvariants]    OF BOOL;
    
    // Variables de contrôle internes
    StepStarted         : BOOL;
    CurrentCaseId       : INT;
    Idx                 : INT;
    Jdx                 : INT;
    Kdx                 : INT;
    Valid               : BOOL;

    // 🔧 REX : locaux remontés depuis des blocs VAR imbriqués dans le corps
    AllChecksPassed     : BOOL;
    AnyCheckFailed      : BOOL;
    FailedCheckIdxLocal : INT;
    FailReasonLocal     : E_TestFailReason;
    ObsBoolLocal        : BOOL;
    ObsDintLocal        : DINT;
    ObsRealLocal        : REAL;
    NeverDuringPassed   : BOOL;
    SuiteAllPassed      : BOOL;
    FirstFailedCase     : INT;
    CaseIdx             : INT;
    CaseStartStep       : INT;
    CaseStep            : INT;
    CaseWalkCount       : INT;
    CaseOk              : BOOL;
    CaseExecuted        : BOOL;
    CaseFailedStep      : INT;
    CaseDuration        : TIME;
    CaseFailReason      : E_TestFailReason;

    // 🏷️ Construction de Report.FailureSummary (1 ligne lisible, tous les cas en échec)
    ReasonText          : STRING(20);
    EntryText           : STRING(80);
    FirstStepLocal      : INT;
    RequestedCaseId     : INT;
END_VAR
// === IMPLEMENTATION ===
StartTrig(CLK := Start);

// 1. Validation de la configuration sur front de Start
IF StartTrig.Q THEN
    ConfigError := FALSE;
    ConfigErrorStepId := 0;
    ConfigErrorCheckIdx := 0;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    ErrorCode := 0;
    ErrorMessage := '';

    // 🛡️ Résolution interne CaseId → première étape, jamais d'étape exposée.
    RequestedCaseId := CaseId;
    IF CaseId < 0 OR CaseId > GVL_PLC_Tests_Const.MaxTestCases THEN
        ConfigError := TRUE;
        ConfigErrorStepId := CaseId;
        ErrorCode := 1001;
        ErrorMessage := 'CaseId hors limites';
        FirstStepLocal := 0;
    ELSIF CaseId = 0 THEN
        FirstStepLocal := CaseTable[1].FirstStep;
    ELSE
        FirstStepLocal := CaseTable[CaseId].FirstStep;
    END_IF;
    IF NOT ConfigError THEN
        IF FirstStepLocal < 1 OR FirstStepLocal > GVL_PLC_Tests_Const.MaxSteps THEN
            ConfigError := TRUE;
            ConfigErrorStepId := FirstStepLocal;
            ErrorCode := 1001;
            ErrorMessage := 'CaseTable.FirstStep hors limites';
        END_IF;
    END_IF;
    
    // Validation des étapes
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxSteps DO
        IF StepTable[Idx].CaseId > 0 THEN
            // Vérification des NextOn
            IF StepTable[Idx].NextOnPass < 0 OR StepTable[Idx].NextOnPass > GVL_PLC_Tests_Const.MaxSteps THEN
                ConfigError := TRUE;
                ConfigErrorStepId := Idx;
            ELSIF StepTable[Idx].NextOnFail < 0 OR StepTable[Idx].NextOnFail > GVL_PLC_Tests_Const.MaxSteps THEN
                ConfigError := TRUE;
                ConfigErrorStepId := Idx;
            END_IF;
            
            // Vérification du Timeout
            IF StepTable[Idx].TimeoutPT <= T#0s THEN
                // Sauf si tous les checks de cette étape sont NEVER_DURING, mais restons stricts : TimeoutPT requis
                ConfigError := TRUE;
                ConfigErrorStepId := Idx;
            END_IF;
            
            // Vérification des Checks indexés par l'étape
            FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
                Kdx := StepTable[Idx].CheckIdx[Jdx];
                IF Kdx > 0 THEN
                    IF Kdx > GVL_PLC_Tests_Const.MaxChecks THEN
                        ConfigError := TRUE;
                        ConfigErrorStepId := Idx;
                        ConfigErrorCheckIdx := Kdx;
                    ELSE
                        // Validation de la sonde associée au check
                        CASE CheckTable[Kdx].Kind OF
                            E_TestCheckKind.BOOL_EQUAL, E_TestCheckKind.BOOL_RISING, E_TestCheckKind.BOOL_FALLING:
                                IF CheckTable[Kdx].ProbeIdx < 1 OR CheckTable[Kdx].ProbeIdx > GVL_PLC_Tests_Const.MaxProbeBool THEN
                                    ConfigError := TRUE;
                                    ConfigErrorStepId := Idx;
                                    ConfigErrorCheckIdx := Kdx;
                                END_IF;
                            E_TestCheckKind.DINT_EQUAL, E_TestCheckKind.DINT_NOT_EQUAL, E_TestCheckKind.DINT_IN_RANGE,
                            E_TestCheckKind.WORD_MASK_ALL, E_TestCheckKind.WORD_MASK_ANY, E_TestCheckKind.WORD_MASK_NONE:
                                IF CheckTable[Kdx].ProbeIdx < 1 OR CheckTable[Kdx].ProbeIdx > GVL_PLC_Tests_Const.MaxProbeDint THEN
                                    ConfigError := TRUE;
                                    ConfigErrorStepId := Idx;
                                    ConfigErrorCheckIdx := Kdx;
                                END_IF;
                            E_TestCheckKind.REAL_IN_RANGE:
                                IF CheckTable[Kdx].ProbeIdx < 1 OR CheckTable[Kdx].ProbeIdx > GVL_PLC_Tests_Const.MaxProbeReal THEN
                                    ConfigError := TRUE;
                                    ConfigErrorStepId := Idx;
                                    ConfigErrorCheckIdx := Kdx;
                                END_IF;
                        END_CASE;
                    END_IF;
                END_IF;
            END_FOR;
        END_IF;
    END_FOR;
    
    // 🛡️ ConfigError doit toujours produire Done + un état terminal.
    IF ConfigError THEN
        Busy := FALSE;
        Done := TRUE;
        AnyFailed := TRUE;
        ActiveStimulusId := 0;
        CurrentStepId := 0;
        StepElapsed := T#0s;
        TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        Report.InProgress := FALSE;
        Report.RunCounter := Report.RunCounter + 1;
        Report.AllPassed := FALSE;
        Report.AnyFailed := TRUE;
        Report.Aborted := FALSE;
        Report.TerminalState := TerminalState;
        IF ErrorCode = 0 THEN
            ErrorCode := 1002;
            ErrorMessage := 'Table de test invalide';
        END_IF;
        Report.ErrorCode := ErrorCode;
        Report.ErrorMessage := ErrorMessage;
        Report.FailureSummary := CONCAT('CONFIG_ERROR step ', INT_TO_STRING(ConfigErrorStepId));
        RETURN;
    END_IF;
END_IF;

// 2. Abort (Niveau, priorité absolue)
IF Abort THEN
    IF Busy THEN
        Report.InProgress := FALSE;
        Report.Aborted := TRUE;
        Report.AnyFailed := TRUE;
        
        // Enregistrement de l'échec de l'étape courante
        IF CurrentStepId >= 1 AND CurrentStepId <= GVL_PLC_Tests_Const.MaxSteps THEN
            Report.Steps[CurrentStepId].Executed := TRUE;
            Report.Steps[CurrentStepId].Passed := FALSE;
            Report.Steps[CurrentStepId].FailReason := E_TestFailReason.FAIL_ABORTED;
            Report.Steps[CurrentStepId].Duration := StepElapsed;
        END_IF;
        
        // Échec du cas de test en cours
        IF CurrentCaseId >= 1 AND CurrentCaseId <= GVL_PLC_Tests_Const.MaxTestCases THEN
            Report.Cases[CurrentCaseId].Ok := FALSE;
            Report.Cases[CurrentCaseId].FailReason := E_TestFailReason.FAIL_ABORTED;
        END_IF;
        
        Busy := FALSE;
        Done := TRUE;
        AnyFailed := TRUE;
        TerminalState := E_TestTerminalState.TEST_TERMINAL_ABORTED;
        Report.TerminalState := TerminalState;
    END_IF;
    ActiveStimulusId := 0;
    StepStarted := FALSE;
    RETURN;
END_IF;

// 3. Démarrage de la suite
IF StartTrig.Q AND NOT ConfigError THEN
    Busy := TRUE;
    Done := FALSE;
    AnyFailed := FALSE;
    CurrentStepId := FirstStepLocal;
    StepStarted := FALSE;
    
    // RAZ Rapport
    Report.InProgress := TRUE;
    Report.AllPassed := FALSE;
    Report.AnyFailed := FALSE;
    Report.Aborted := FALSE;
    Report.TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    Report.ErrorCode := 0;
    Report.ErrorMessage := '';
    Report.FailedTestCase := 0;
    Report.CurrentStepId := FirstStepLocal;
    IF CurrentStepId >= 1 AND CurrentStepId <= GVL_PLC_Tests_Const.MaxSteps THEN
        Report.CurrentCaseId := StepTable[CurrentStepId].CaseId;
    ELSE
        Report.CurrentCaseId := 0;
    END_IF;
    Report.Duration := T#0s;
    Report.RunCounter := Report.RunCounter + 1;
    
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxSteps DO
        Report.Steps[Idx].Executed := FALSE;
        Report.Steps[Idx].Passed := FALSE;
        Report.Steps[Idx].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Steps[Idx].FailedCheckIdx := 0;
        Report.Steps[Idx].FailedInvariantId := 0;
        Report.Steps[Idx].Duration := T#0s;
    END_FOR;
    
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        Report.Cases[Idx].Executed := FALSE;
        Report.Cases[Idx].Ok := FALSE;
        Report.Cases[Idx].FailedStepId := 0;
        Report.Cases[Idx].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Cases[Idx].Duration := T#0s;
    END_FOR;
    
    // RAZ Invariants
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxInvariants DO
        InvArmed[Idx] := FALSE;
    END_FOR;
END_IF;

// 4. Moteur d'exécution principal
IF Busy THEN
    // Incrément de la durée globale du run
    Report.Duration := Report.Duration + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
    
    // Vérification des bornes de l'étape courante (0 est valide et désigne la fin)
    IF CurrentStepId <> 0 AND (CurrentStepId < 1 OR CurrentStepId > GVL_PLC_Tests_Const.MaxSteps) THEN
        Busy := FALSE;
        Done := TRUE;
        AnyFailed := TRUE;
        ActiveStimulusId := 0;
        ConfigError := TRUE;
        ConfigErrorStepId := CurrentStepId;
        ErrorCode := 1003;
        ErrorMessage := 'Etape courante hors limites';
        TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        Report.InProgress := FALSE;
        Report.AnyFailed := TRUE;
        Report.TerminalState := TerminalState;
        Report.ErrorCode := ErrorCode;
        Report.ErrorMessage := ErrorMessage;
        Report.FailureSummary := ErrorMessage;
        RETURN;
    END_IF;
    
    // 🔒 Fin automatique dès qu'un run ciblé tenterait d'entrer dans le cas suivant.
    IF CurrentStepId > 0 AND RequestedCaseId > 0 THEN
        IF StepTable[CurrentStepId].CaseId <> RequestedCaseId THEN
            CurrentStepId := 0;
            ActiveStimulusId := 0;
            StepStarted := FALSE;
        END_IF;
    END_IF;

    IF CurrentStepId > 0 THEN
    CurrentCaseId := StepTable[CurrentStepId].CaseId;
    ActiveStimulusId := StepTable[CurrentStepId].StimulusId;
    Report.CurrentStepId := CurrentStepId;
    Report.CurrentCaseId := CurrentCaseId;
    
    IF NOT StepStarted THEN
        StepStarted := TRUE;
        StepElapsed := T#0s;
        DwellTimer(IN := FALSE);
        StepTimer(IN := FALSE);
        
        // Gestion de l'armement/désarmement des invariants
        FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxInvariants DO
            IF InvariantTable[Idx].ArmAtStepId = CurrentStepId THEN
                InvArmed[Idx] := TRUE;
            END_IF;
            IF InvariantTable[Idx].DisarmAtStepId = CurrentStepId THEN
                InvArmed[Idx] := FALSE;
            END_IF;
        END_FOR;
    END_IF;
    
    // Incrément de la durée de l'étape courante
    StepElapsed := StepElapsed + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
    
    // 4.1 Évaluation des invariants actifs
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxInvariants DO
        IF InvArmed[Idx] THEN
            InvChecks[Idx](Config := InvariantTable[Idx].Check, Evaluate := TRUE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);
            IF InvChecks[Idx].Failed THEN
                // Violation d'invariant -> Transition en échec immédiat
                Report.Steps[CurrentStepId].Executed := TRUE;
                Report.Steps[CurrentStepId].Passed := FALSE;
                Report.Steps[CurrentStepId].FailReason := E_TestFailReason.FAIL_INVARIANT;
                Report.Steps[CurrentStepId].FailedInvariantId := Idx;
                Report.Steps[CurrentStepId].Duration := StepElapsed;
                Report.Steps[CurrentStepId].ObservedBool := InvChecks[Idx].ObservedBool;
                Report.Steps[CurrentStepId].ObservedDint := InvChecks[Idx].ObservedDint;
                Report.Steps[CurrentStepId].ObservedReal := InvChecks[Idx].ObservedReal;
                
                // Désactivation de l'évaluation
                InvChecks[Idx](Config := InvariantTable[Idx].Check, Evaluate := FALSE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);
                
                // Transition
                IF StepTable[CurrentStepId].FailAction = E_TestFailAction.FAIL_ABORT_SUITE THEN
                    Busy := FALSE;
                    Done := TRUE;
                    AnyFailed := TRUE;
                    ActiveStimulusId := 0;
                ELSE
                    CurrentStepId := StepTable[CurrentStepId].NextOnFail;
                    StepStarted := FALSE;
                END_IF;
                RETURN;
            END_IF;
        END_IF;
    END_FOR;
    
    // 4.2 Gestion de la temporisation de Dwell
    DwellTimer(IN := TRUE, PT := StepTable[CurrentStepId].DwellPT);
    IF NOT DwellTimer.Q THEN
        // En attente du Dwell, pas d'évaluation des checks d'étape
        FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
            Checks[Jdx](Evaluate := FALSE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);
        END_FOR;
        RETURN;
    END_IF;
    
    // 4.3 Évaluation des checks d'étape
    AllChecksPassed     := TRUE;
    AnyCheckFailed      := FALSE;
    FailedCheckIdxLocal := 0;
    FailReasonLocal     := E_TestFailReason.FAIL_NONE;
    ObsBoolLocal        := FALSE;
    ObsDintLocal        := 0;
    ObsRealLocal        := 0.0;

    FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
        Kdx := StepTable[CurrentStepId].CheckIdx[Jdx];
        IF Kdx < 0 OR Kdx > GVL_PLC_Tests_Const.MaxChecks THEN
            ConfigError := TRUE;
            ConfigErrorStepId := CurrentStepId;
            ConfigErrorCheckIdx := Kdx;
            ErrorCode := 1006;
            ErrorMessage := 'CheckIdx runtime hors limites';
            Busy := FALSE;
            Done := TRUE;
            AnyFailed := TRUE;
            ActiveStimulusId := 0;
            TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
            RETURN;
        END_IF;
        IF Kdx > 0 THEN
            Checks[Jdx](Config := CheckTable[Kdx], Evaluate := TRUE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);
            
            IF Checks[Jdx].Failed THEN
                AnyCheckFailed := TRUE;
                FailedCheckIdxLocal := Kdx;
                FailReasonLocal := Checks[Jdx].FailReason;
                ObsBoolLocal := Checks[Jdx].ObservedBool;
                ObsDintLocal := Checks[Jdx].ObservedDint;
                ObsRealLocal := Checks[Jdx].ObservedReal;
            ELSIF Checks[Jdx].Pending THEN
                AllChecksPassed := FALSE;
            END_IF;
        END_IF;
    END_FOR;
    
    // 4.4 Prise de verdict
    IF AnyCheckFailed THEN
        // Échec sur un check d'étape
        Report.Steps[CurrentStepId].Executed := TRUE;
        Report.Steps[CurrentStepId].Passed := FALSE;
        Report.Steps[CurrentStepId].FailReason := FailReasonLocal;
        Report.Steps[CurrentStepId].FailedCheckIdx := FailedCheckIdxLocal;
        Report.Steps[CurrentStepId].Duration := StepElapsed;
        Report.Steps[CurrentStepId].ObservedBool := ObsBoolLocal;
        Report.Steps[CurrentStepId].ObservedDint := ObsDintLocal;
        Report.Steps[CurrentStepId].ObservedReal := ObsRealLocal;
        
        // Reset checks
        FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
            Checks[Jdx](Evaluate := FALSE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);
        END_FOR;
        
        IF StepTable[CurrentStepId].FailAction = E_TestFailAction.FAIL_ABORT_SUITE THEN
            Busy := FALSE;
            Done := TRUE;
            AnyFailed := TRUE;
            ActiveStimulusId := 0;
        ELSE
            CurrentStepId := StepTable[CurrentStepId].NextOnFail;
            StepStarted := FALSE;
        END_IF;
        RETURN;
    END_IF;
    
    StepTimer(IN := TRUE, PT := StepTable[CurrentStepId].TimeoutPT);
    
    IF AllChecksPassed THEN
        // Succès précoce (vérification MinPT)
        IF StepElapsed < StepTable[CurrentStepId].MinPT THEN
            // Réaction trop rapide = Échec
            Report.Steps[CurrentStepId].Executed := TRUE;
            Report.Steps[CurrentStepId].Passed := FALSE;
            Report.Steps[CurrentStepId].FailReason := E_TestFailReason.FAIL_WINDOW_EARLY;
            Report.Steps[CurrentStepId].Duration := StepElapsed;
            
            // Reset checks
            FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
                Checks[Jdx](Evaluate := FALSE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);
            END_FOR;
            
            IF StepTable[CurrentStepId].FailAction = E_TestFailAction.FAIL_ABORT_SUITE THEN
                Busy := FALSE;
                Done := TRUE;
                AnyFailed := TRUE;
                ActiveStimulusId := 0;
            ELSE
                CurrentStepId := StepTable[CurrentStepId].NextOnFail;
                StepStarted := FALSE;
            END_IF;
        ELSE
            // Validation étape OK
            Report.Steps[CurrentStepId].Executed := TRUE;
            Report.Steps[CurrentStepId].Passed := TRUE;
            Report.Steps[CurrentStepId].Duration := StepElapsed;
            
            // Prendre snapshot du premier check s'il existe
            IF StepTable[CurrentStepId].CheckIdx[1] > 0 THEN
                Report.Steps[CurrentStepId].ObservedBool := Checks[1].ObservedBool;
                Report.Steps[CurrentStepId].ObservedDint := Checks[1].ObservedDint;
                Report.Steps[CurrentStepId].ObservedReal := Checks[1].ObservedReal;
            END_IF;
            
            // Reset checks
            FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
                Checks[Jdx](Evaluate := FALSE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);
            END_FOR;
            
            CurrentStepId := StepTable[CurrentStepId].NextOnPass;
            StepStarted := FALSE;
        END_IF;
        RETURN;
    END_IF;
    
    // Gestion du timeout d'étape
    IF StepTimer.Q THEN
        // Si timeout expiré, vérifions si des checks NEVER_DURING sont en attente
        NeverDuringPassed := TRUE;
        FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
            Kdx := StepTable[CurrentStepId].CheckIdx[Jdx];
            IF Kdx < 0 OR Kdx > GVL_PLC_Tests_Const.MaxChecks THEN
                ConfigError := TRUE;
                ConfigErrorStepId := CurrentStepId;
                ConfigErrorCheckIdx := Kdx;
                ErrorCode := 1006;
                ErrorMessage := 'CheckIdx timeout hors limites';
                Busy := FALSE;
                Done := TRUE;
                AnyFailed := TRUE;
                ActiveStimulusId := 0;
                TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
                RETURN;
            END_IF;
            IF Kdx > 0 THEN
                IF CheckTable[Kdx].Mode = E_TestCheckMode.CHECK_NEVER_DURING THEN
                    // Jamais violé pendant toute la fenêtre
                    Checks[Jdx](Evaluate := FALSE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);
                ELSE
                    // Les autres modes auraient dû passer avant le timeout
                    NeverDuringPassed := FALSE;
                END_IF;
            END_IF;
        END_FOR;
        
        IF NeverDuringPassed THEN
            // Succès par non-violation
            Report.Steps[CurrentStepId].Executed := TRUE;
            Report.Steps[CurrentStepId].Passed := TRUE;
            Report.Steps[CurrentStepId].Duration := StepElapsed;
            
            CurrentStepId := StepTable[CurrentStepId].NextOnPass;
            StepStarted := FALSE;
        ELSE
            // Timeout classique de l'étape
            Report.Steps[CurrentStepId].Executed := TRUE;
            Report.Steps[CurrentStepId].Passed := FALSE;
            Report.Steps[CurrentStepId].FailReason := E_TestFailReason.FAIL_TIMEOUT;
            Report.Steps[CurrentStepId].Duration := StepElapsed;
            
            IF StepTable[CurrentStepId].FailAction = E_TestFailAction.FAIL_ABORT_SUITE THEN
                Busy := FALSE;
                Done := TRUE;
                AnyFailed := TRUE;
                ActiveStimulusId := 0;
            ELSE
                CurrentStepId := StepTable[CurrentStepId].NextOnFail;
                StepStarted := FALSE;
            END_IF;
        END_IF;
        
        // Reset checks
        FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
            Checks[Jdx](Evaluate := FALSE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);
        END_FOR;
    END_IF;
    END_IF;
END_IF;

// 5. Agrégation des résultats en fin de suite (CurrentStepId = 0)
IF Busy AND CurrentStepId = 0 THEN
    Busy := FALSE;
    Done := TRUE;
    ActiveStimulusId := 0;
    Report.InProgress := FALSE;
    
    // Agrégation des cas de test
    SuiteAllPassed  := TRUE;
    FirstFailedCase := 0;

    FOR CaseIdx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        CaseStartStep := CaseTable[CaseIdx].FirstStep;
        IF CaseStartStep > 0 THEN
            CaseOk := TRUE;
            CaseExecuted := FALSE;
            CaseFailedStep := 0;
            CaseDuration := T#0s;
            CaseFailReason := E_TestFailReason.FAIL_NONE;
            
            // 🔒 Parcours borné et index validé AVANT déréférencement.
            // CODESYS peut évaluer StepTable[CaseStep] même si CaseStep=0
            // dans une condition composée : ancienne version = Access Violation CPU.
            CaseStep := CaseStartStep;
            FOR CaseWalkCount := 1 TO GVL_PLC_Tests_Const.MaxSteps DO
                IF CaseStep = 0 THEN
                    EXIT;
                END_IF;
                IF CaseStep < 1 OR CaseStep > GVL_PLC_Tests_Const.MaxSteps THEN
                    ConfigError := TRUE;
                    ConfigErrorStepId := CaseStep;
                    ErrorCode := 1004;
                    ErrorMessage := 'Agregation : etape hors limites';
                    CaseOk := FALSE;
                    EXIT;
                END_IF;
                IF StepTable[CaseStep].CaseId <> CaseIdx THEN
                    EXIT;
                END_IF;

                IF Report.Steps[CaseStep].Executed THEN
                    CaseExecuted := TRUE;
                    CaseDuration := CaseDuration + Report.Steps[CaseStep].Duration;
                    IF NOT Report.Steps[CaseStep].Passed THEN
                        CaseOk := FALSE;
                        CaseFailedStep := CaseStep;
                        CaseFailReason := Report.Steps[CaseStep].FailReason;
                        CaseStep := StepTable[CaseStep].NextOnFail;
                    ELSE
                        CaseStep := StepTable[CaseStep].NextOnPass;
                    END_IF;
                ELSE
                    CaseStep := StepTable[CaseStep].NextOnPass;
                END_IF;
            END_FOR;
            IF CaseStep <> 0 AND CaseWalkCount > GVL_PLC_Tests_Const.MaxSteps THEN
                ConfigError := TRUE;
                ConfigErrorStepId := CaseStep;
                ErrorCode := 1005;
                ErrorMessage := 'Agregation : cycle de transitions';
                CaseOk := FALSE;
            END_IF;
            
            Report.Cases[CaseIdx].Name := CaseTable[CaseIdx].Name; // 🏷️ Lisible directement en Watch, sans chercher l'index
            Report.Cases[CaseIdx].Executed := CaseExecuted;
            Report.Cases[CaseIdx].Ok := CaseExecuted AND CaseOk;
            Report.Cases[CaseIdx].FailedStepId := CaseFailedStep;
            Report.Cases[CaseIdx].FailReason := CaseFailReason;
            Report.Cases[CaseIdx].Duration := CaseDuration;
            
            IF CaseExecuted AND NOT CaseOk THEN
                SuiteAllPassed := FALSE;
                IF FirstFailedCase = 0 THEN
                    FirstFailedCase := CaseIdx;
                END_IF;
            END_IF;
        END_IF;
    END_FOR;
    
    Report.AllPassed := SuiteAllPassed;
    Report.AnyFailed := NOT SuiteAllPassed;
    Report.FailedTestCase := FirstFailedCase;
    AnyFailed := NOT SuiteAllPassed;
    IF SuiteAllPassed THEN
        TerminalState := E_TestTerminalState.TEST_TERMINAL_DONE;
    ELSE
        TerminalState := E_TestTerminalState.TEST_TERMINAL_FAILED;
    END_IF;
    Report.TerminalState := TerminalState;
    Report.ErrorCode := ErrorCode;
    Report.ErrorMessage := ErrorMessage;

    // 🏷️ Résumé texte de TOUS les cas en échec (pas juste le premier) — évite de
    // parcourir Cases[] un par un en Watch (demande utilisateur 2026-07-16)
    Report.FailureSummary := '';
    FOR CaseIdx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        IF Report.Cases[CaseIdx].Executed AND NOT Report.Cases[CaseIdx].Ok THEN
            CASE Report.Cases[CaseIdx].FailReason OF
                E_TestFailReason.FAIL_TIMEOUT:      ReasonText := 'FAIL_TIMEOUT';
                E_TestFailReason.FAIL_CHECK:        ReasonText := 'FAIL_CHECK';
                E_TestFailReason.FAIL_INVARIANT:    ReasonText := 'FAIL_INVARIANT';
                E_TestFailReason.FAIL_WINDOW_EARLY: ReasonText := 'FAIL_WINDOW_EARLY';
                E_TestFailReason.FAIL_ABORTED:      ReasonText := 'FAIL_ABORTED';
            ELSE
                ReasonText := 'FAIL_NONE';
            END_CASE;

            EntryText := CONCAT(Report.Cases[CaseIdx].Name, ' (step ');
            EntryText := CONCAT(EntryText, INT_TO_STRING(Report.Cases[CaseIdx].FailedStepId));
            EntryText := CONCAT(EntryText, '): ');
            EntryText := CONCAT(EntryText, ReasonText);

            IF Report.FailureSummary = '' THEN
                Report.FailureSummary := EntryText;
            ELSE
                Report.FailureSummary := CONCAT(Report.FailureSummary, ' | ');
                Report.FailureSummary := CONCAT(Report.FailureSummary, EntryText);
            END_IF;
        END_IF;
    END_FOR;
END_IF;

SETUP
VAR
    fb : FB_CYCLETIME;
END_VAR
END_SETUP

TEST 'Premier cycle retourne la valeur de secours (pas de dt mesurable)'
    fb(DEFAULTVALUES := 0.004);
    ASSERT_NEAR(fb.CYCLETIMES, 0.004, 0.0001, 'premier appel : aucun dt reel disponible, DefaultValueS renvoye tel quel');
END_TEST

TEST 'Cycle suivant calcule le dt reel ecoule (ms->s)'
    fb(DEFAULTVALUES := 0.004);
    ADVANCE_TIME(10000000);
    fb(DEFAULTVALUES := 0.004);
    ASSERT_NEAR(fb.CYCLETIMES, 0.01, 0.0001, '10ms ecoulees entre les 2 appels -> 0.01s calcule (pas la valeur de secours)');

    ADVANCE_TIME(25000000);
    fb(DEFAULTVALUES := 0.004);
    ASSERT_NEAR(fb.CYCLETIMES, 0.025, 0.0001, 'dt variable d un cycle a l autre correctement mesure (25ms)');
END_TEST

(* =======================================================================
   🕹️ FB_Joystick — Acquisition & conditionnement du geste opérateur
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Acquisition 2 axes Hall + bouton homme-mort normatif.
             Pipeline par axe : FB_AxisScale -> Homme-Mort -> ST_Joystick_AxisCmd.
   🔒 Sécurité : Armement homme-mort par maintien au neutre.
                 Désarmement sur neutre prolongé, changement mode ou fin benne.
   📤 Sorties : AxisCmdX/Y, signaux de diagnostic et miroirs maintenance.
   📄 Doc métier : DOC/AF/AF_Partie-08_Fonction_Joystick_v2.0.md
   ======================================================================= *)

FUNCTION_BLOCK FB_Joystick
VAR_INPUT
    // === PERMIS SÉCURITÉ & ETATS SYSTEME ===
    Enable                    : BOOL;       // --> [CMD]  Active la logique du bloc (TRUE=Autorise)
    Reset                     : BOOL;       // --> [CMD]  Acquittement defaut
    Mode                      : E_Mode;     // --> [SAFE] Changement de mode desarme l'homme-mort
    BenneBusy                 : BOOL;       // --> [SAFE] Fin de cycle benne (front descendant) desarme l'homme-mort
    PreserveArmingAfterBucket : BOOL;       // --> [SAFE] Maintien armement pendant fermeture ExtractionSequence

    // === ACQUISITION MATERIELLE & DIAGNOSTIC ===
    BusCanOpenOP              : ST_Diag_Device; // --> [HW]   Etat presence noeud CAN
    JoystickOP                : ST_Diag_Device; // --> [HW]   Mode esclave CANopen actif
    RawX                      : INT;        // --> [HW]   Valeur brute axe X (0..10000)
    RawY                      : INT;        // --> [HW]   Valeur brute axe Y (0..10000)
    RawButton                 : BOOL;       // --> [HW]   Etat brut bouton homme-mort

    // === COMMANDES OPÉRATEUR & CALIBRATION ===
    BtnCalibrate              : BOOL;       // --> [CMD]  Demande de recalage neutre

    // === REGLAGES & CONFIGURATION ===
    InvertX                   : BOOL := FALSE;   // --> [CFG]  Inversion sens de l'axe X
    InvertY                   : BOOL := FALSE;   // --> [CFG]  Inversion sens de l'axe Y
    DeadbandRaw               : INT := 300;      // --> [CFG]  Zone morte en points ADC bruts (0..10000)
    NeutralHoldTime           : TIME := T#100MS; // --> [CFG]  Maintien continu au neutre avant desarmement
    DeadmanArmHoldTime        : TIME := T#100MS; // --> [CFG]  Appui continu bouton requis pour armer
    DeadmanArmGraceTime       : TIME := T#3S;    // --> [CFG]  Delai de grace post-armement avant desarmement neutre
    RawOutOfRangeMargin       : INT := 500;      // --> [CFG]  Marge tolerance ADC autour des bornes nominales [0..10000] avant defaut capteur (AF08 §5bis)
END_VAR
VAR_OUTPUT
    // === ETATS IEC & SYNOPTIQUE ===
    Ready                     : BOOL;       // <-- [STAT] FB pret a fonctionner
    Busy                      : BOOL;       // <-- [STAT] Traitement en cours
    Done                      : BOOL;       // <-- [STAT] Donnees valides disponibles
    Button                    : BOOL;       // <-- [STAT] Bouton homme-mort filtre

    // === DIAGNOSTIC & ANOMALIES ===
    Error                     : BOOL;       // <-- [DIAG] Presence anomalie (miroir Status.Error)
    ErrorId                   : WORD;       // <-- [DIAG] Bit0: Echec calibration Joystick (RawX/Y hors plage)
    Status                    : ST_FbStatus; // <-- [STAT] Statut standard complet (socle FB_FbStatus)

    // === CONSIGNES AXES NORMALISEES ===
    AxisCmdX                  : ST_Joystick_AxisCmd; // <-- [ACT]  Sortie normalisee axe X
    AxisCmdY                  : ST_Joystick_AxisCmd; // <-- [ACT]  Sortie normalisee axe Y

    // === MESURES & MIROIRS MAINTENANCE ===
    NeutralXAct               : INT;        // <-- [STAT] Point neutre X actuel pour IHM/Test
    NeutralYAct               : INT;        // <-- [STAT] Point neutre Y actuel pour IHM/Test
    SpeedXPct                 : REAL;       // <-- [STAT] Consigne vitesse axe X signee (-100..+100 %), miroir AxisCmdX.SpeedRef
    DirectionX                : INT;        // <-- [STAT] Sens axe X (-1=Rev/0=Neutre/+1=Fwd), miroir AxisCmdX.Direction
    SpeedYPct                 : REAL;       // <-- [STAT] Consigne vitesse axe Y signee (-100..+100 %), miroir AxisCmdY.SpeedRef
    DirectionY                : INT;        // <-- [STAT] Sens axe Y (-1=Rev/0=Neutre/+1=Fwd), miroir AxisCmdY.Direction
    DeadmanArmed              : BOOL;       // <-- [STAT] Geste arme (bouton appuye au neutre) - IHM/diagnostic
    AtNeutral                 : BOOL;       // <-- [STAT] TRUE si les 2 axes sont en zone morte (position centrale)
END_VAR
VAR_IN_OUT
    // === RETENTION & CALIBRATION PERSISTANTE ===
    NeutralXMem               : INT;        // <-> [BUS]  Point neutre X persistant global
    NeutralYMem               : INT;        // <-> [BUS]  Point neutre Y persistant global
END_VAR
VAR
    // === SOUS-INSTANCES FB & TIMERS ===
    ScaleX                    : FB_AxisScale;        // * [INST] Normalisation et zone morte axe X
    ScaleY                    : FB_AxisScale;        // * [INST] Normalisation et zone morte axe Y
    ResetEdge                 : R_TRIG;              // * [INST] Detecteur front montant Reset
    DeadmanEdge               : R_TRIG;              // * [INST] Detecteur front montant Bouton homme-mort
    NeutralHoldTimer          : TON;                 // * [INST] Temporisation maintien au neutre
    DeadmanArmTimer           : TON;                 // * [INST] Temporisation maintien bouton armement
    DeadmanArmGraceTimer      : TON;                 // * [INST] Temporisation delai de grace post-armement
    BenneBusyFallEdge         : F_TRIG;              // * [INST] Detecteur front descendant Fin de cycle benne

    // === VARIABLES LOCALES INTERNES ===
    CmdXVal                   : REAL;                // . [LOC]  Consigne axe X calculee apres filtrage/homme-mort
    CmdYVal                   : REAL;                // . [LOC]  Consigne axe Y calculee apres filtrage/homme-mort
    LastCalibrate             : BOOL;                // . [LOC]  Memorisation etat precedent bouton calibration
    DeadmanArmPending         : BOOL;                // . [LOC]  Armement en cours d'attente de la tempo maintien
    LastMode                  : E_Mode;              // . [LOC]  Memorisation mode scan precedent pour detection changement
    RawOutOfRange             : BOOL;                // . [LOC]  Surveillance capteur continue (AF08 §5bis) : RawX/RawY hors plage nominale+marge
    ErrorIdCause              : WORD;                // . [LOC]  Cause brute agrégée alimentant le socle FB_FbStatus
    WarningMask               : WORD;                // . [LOC]  Masque des erreurs classées WARNING (bit=1) ; bit=0 -> FAULT à acquitter
    instFbStatus              : FB_FbStatus;         // * [INST] Socle de statut standard (forme cible)
    JoystickErrorTexts        : ARRAY[0..15] OF STRING;  // . [LOC] Textes IHM des erreurs joystick (par bit)
    JoystickWarningTexts      : ARRAY[0..15] OF STRING;  // . [LOC] Textes IHM des warnings joystick (par bit)
END_VAR

{region "§1 Gate securite"}
// 🛑 1. GATE (Sécurités et coupures prioritaires)
IF NOT Enable OR NOT BusCanOpenOP.Operational OR NOT JoystickOP.Operational THEN
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    AxisCmdX.Enable := FALSE; AxisCmdX.StartStop := FALSE; AxisCmdX.SpeedRef := 0.0; AxisCmdX.Direction := 0;
    AxisCmdY.Enable := FALSE; AxisCmdY.StartStop := FALSE; AxisCmdY.SpeedRef := 0.0; AxisCmdY.Direction := 0;
    SpeedXPct := 0.0; DirectionX := 0;
    SpeedYPct := 0.0; DirectionY := 0;
    Button := FALSE;
    AtNeutral := TRUE;
    DeadmanArmed := FALSE;
    DeadmanArmPending := FALSE;
    NeutralHoldTimer(IN := FALSE, PT := NeutralHoldTime);
    DeadmanArmTimer(IN := FALSE, PT := DeadmanArmHoldTime);
    DeadmanArmGraceTimer(IN := FALSE, PT := DeadmanArmGraceTime);
    NeutralXAct := NeutralXMem;
    NeutralYAct := NeutralYMem;
    LastMode := Mode;   // Pas de faux changement détecté à la réactivation
    // 🔎 AF08 §3 : perte bus CAN / device non-opérationnel -> ErrorId bit2 (16#0004),
    // Info/Warning auto-effacé dès le retour (pas un Fault à acquitter).
    // Distingué du gate générique (Enable/PowerContactor) qui, lui, ne lève pas d'erreur.
    IF NOT BusCanOpenOP.Operational OR NOT JoystickOP.Operational THEN
        ErrorId := ErrorId OR 16#0004;
        Error := TRUE;   // le gate RETURN avant le calcul "Error := (ErrorId<>0)" -> forçage explicite
    END_IF;
    RETURN;
END_IF;

Ready := TRUE; Busy := TRUE;

{endregion}

{region "§2 Reset acquisition timing et bouton"}
// 🔑 2. RESET DÉFAUT (front + cause disparue, Partie3 §5)
ResetEdge(CLK := Reset);
IF ResetEdge.Q AND (RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000) THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 📥 3. ACQUISITION TIMING & BOUTON
Button := RawButton;

// 🔎 AF08 §3 : dès le retour du bus CAN / device opérationnel, le bit2 (perte HW/bus)
// s'auto-efface (Info/Warning, pas un Fault à acquitter). Ne touche pas aux autres bits.
IF BusCanOpenOP.Operational AND JoystickOP.Operational THEN
    ErrorId := ErrorId AND 16#FFFB;
END_IF;

{endregion}

{region "§3 Calibration et mise a echelle"}
// 🎯 4. CALIBRATION DYNAMIQUE (Zone RETAIN)
IF BtnCalibrate AND NOT LastCalibrate THEN
    IF RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000 THEN
        NeutralXMem := RawX;
        NeutralYMem := RawY;
    ELSE
        // Un seul bit pour une seule cause (Partie3 §3)
        ErrorId := ErrorId OR 16#0001;
    END_IF;
END_IF;
Error := (ErrorId <> 16#0000);
LastCalibrate := BtnCalibrate;

// 🧮 4bis. MISE À L'ÉCHELLE (avant homme-mort — le neutre s'évalue sur les 2 axes déjà deadbandés)
ScaleX(RawIn := RawX, Neutral := NeutralXMem, DeadbandRaw := DeadbandRaw);
ScaleY(RawIn := RawY, Neutral := NeutralYMem, DeadbandRaw := DeadbandRaw);
AtNeutral := (ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0);   // IHM/diagnostic — position centrale (zone morte)

// 🛡️ 4ter. SURVEILLANCE CAPTEUR CONTINUE (AF08 §5bis) — défaut hors plage ADC.
// Évaluée à CHAQUE scan (pas seulement au front BtnCalibrate). Si RawX OU RawY sort de la
// plage nominale [0..10000] + marge de tolérance, confiance perdue dans TOUT le geste :
// neutralisation des 2 axes + ErrorId bit1 (16#0002). Cause brute évaluée en continu
// (interlock toujours sur la cause, jamais sur l'acquittement) → ré-alarme auto si persistante.
RawOutOfRange := (RawX < (0 - RawOutOfRangeMargin))
              OR (RawX > (10000 + RawOutOfRangeMargin))
              OR (RawY < (0 - RawOutOfRangeMargin))
              OR (RawY > (10000 + RawOutOfRangeMargin));
IF RawOutOfRange THEN
    ErrorId := ErrorId OR 16#0002;
ELSE
    ErrorId := ErrorId AND 16#FFFD;
END_IF;
Error := (ErrorId <> 16#0000);

{endregion}

{region "§4 Desarmements changement mode et fin benne"}
// 4ter-bis. CHANGEMENT DE MODE : désarme le homme-mort dès que Mode change
// (MAINT_N1/N2/SEMI_AUTO/AUTO). Évite qu'une commande en cours traverse le changement
// de mode et soit réinterprétée soudainement. Repassage par le neutre + nouvel appui exigé.
IF Mode <> LastMode THEN
    DeadmanArmed := FALSE;
    DeadmanArmPending := FALSE;   // Nouvel appui exigé après changement de mode
END_IF;
LastMode := Mode;

// 4ter-ter. FIN DE CYCLE BENNE : désarmement général pour qu'une fermeture manuelle
// ne démarre jamais M1/M2 par surprise. Exception : ExtractionSequence garde l'armement
// pendant sa fermeture (enchaînement palier 1 sous ses propres interlocks synchro/position).
BenneBusyFallEdge(CLK := BenneBusy);
IF BenneBusyFallEdge.Q AND NOT PreserveArmingAfterBucket THEN
    DeadmanArmed := FALSE;
    DeadmanArmPending := FALSE;   // Nouvel appui exigé après fin de cycle benne
END_IF;

{endregion}

{region "§5 Armement homme mort"}
// 4ter. BOUTON HOMME-MORT — armement par MAINTIEN (DeadmanArmHoldTime), indépendant de la
// position des axes pendant l'appui.
// Armement par MAINTIEN (DeadmanArmHoldTime), indépendant de la position des axes pendant
// l'appui : appui (front) → maintien 100 ms → armé, quelle que soit la position des axes durant
// ce maintien. Relâchement AVANT la fin du maintien = tentative annulée (DeadmanArmPending
// retombe), un nouvel appui (front) est requis — pas d'armement différé "surprise" sur un appui
// prolongé après un désarmement (mode/benne/neutre). Sûr même si le joystick est déjà hors zone
// morte à la fin du maintien : les rampes d'accel/décel restent gérées par les FB aval
// (FB_Winch/FB_Translation), donc pas de démarrage brutal possible côté ce FB.
DeadmanEdge(CLK := RawButton);
IF DeadmanEdge.Q THEN
    DeadmanArmPending := TRUE;
END_IF;
IF NOT RawButton THEN
    DeadmanArmPending := FALSE;
END_IF;

// 🛡️ SÉCURITÉ C4 (ISO 13849) : armement STRICTEMENT conditionné par DeadmanArmPending.
// Tout désarmement (changement de mode, fin de cycle benne, passage neutre prolongé)
// efface DeadmanArmPending et EXIGE un nouvel appui conscient (front montant de RawButton).
DeadmanArmTimer(IN := DeadmanArmPending AND NOT DeadmanArmed, PT := DeadmanArmHoldTime);
IF DeadmanArmTimer.Q THEN
    DeadmanArmed := TRUE;
    DeadmanArmPending := FALSE;
END_IF;

// ⏱️ 4bis. GESTION DU DÉSARMEMENT PAR MAINTIEN AU NEUTRE
DeadmanArmGraceTimer(IN := DeadmanArmed, PT := DeadmanArmGraceTime);
NeutralHoldTimer(IN := DeadmanArmed AND AtNeutral AND DeadmanArmGraceTimer.Q,
                 PT := NeutralHoldTime);
IF NeutralHoldTimer.Q THEN
    DeadmanArmed := FALSE;      // Neutre maintenu après la grâce = désarmement
END_IF;

{endregion}

{region "§6 Pipeline axe X"}
// 🕹️ 5. PIPELINE TRAITEMENT — AXE X
// Pas de filtre : le joystick est stable et ne doit pas être ralenti (décision 2026-08-22).
// Inversion de sens appliquée directement sur la sortie normalisée.
// Consigne forcée à 0.0 tant que le geste n'est pas armé (homme-mort)
// OU si le capteur est hors plage (RawOutOfRange) : confiance perdue dans tout le geste.
IF InvertX THEN
    CmdXVal := SEL(DeadmanArmed AND NOT RawOutOfRange, 0.0, -ScaleX.OutPct);
ELSE
    CmdXVal := SEL(DeadmanArmed AND NOT RawOutOfRange, 0.0, ScaleX.OutPct);
END_IF;

// Mapping Sortie Standardisée Axe X
AxisCmdX.Enable := NOT RawOutOfRange;
AxisCmdX.SpeedRef := CmdXVal;
AxisCmdX.StartStop := (ABS(CmdXVal) > 0.1);

IF CmdXVal > 0.1 THEN
    AxisCmdX.Direction := 1;
ELSIF CmdXVal < -0.1 THEN
    AxisCmdX.Direction := -1;
ELSE
    AxisCmdX.Direction := 0;
    AxisCmdX.SpeedRef := 0.0;
END_IF;

// Miroirs maintenance
SpeedXPct := AxisCmdX.SpeedRef;
DirectionX := AxisCmdX.Direction;

{endregion}

{region "§7 Pipeline axe Y et sorties"}
// 🕹️ 6. PIPELINE TRAITEMENT — AXE Y
// Pas de filtre : le joystick est stable et ne doit pas être ralenti (décision 2026-08-22).
// Inversion de sens appliquée directement sur la sortie normalisée.
// Consigne forcée à 0.0 tant que le geste n'est pas armé (homme-mort)
// OU si le capteur est hors plage (RawOutOfRange) : confiance perdue dans tout le geste.
IF InvertY THEN
    CmdYVal := SEL(DeadmanArmed AND NOT RawOutOfRange, 0.0, -ScaleY.OutPct);
ELSE
    CmdYVal := SEL(DeadmanArmed AND NOT RawOutOfRange, 0.0, ScaleY.OutPct);
END_IF;

// Mapping Sortie Standardisée Axe Y
AxisCmdY.Enable := NOT RawOutOfRange;
AxisCmdY.SpeedRef := CmdYVal;
AxisCmdY.StartStop := (ABS(CmdYVal) > 0.1);

IF CmdYVal > 0.1 THEN
    AxisCmdY.Direction := 1;
ELSIF CmdYVal < -0.1 THEN
    AxisCmdY.Direction := -1;
ELSE
    AxisCmdY.Direction := 0;
    AxisCmdY.SpeedRef := 0.0;
END_IF;

// Miroirs maintenance
SpeedYPct := AxisCmdY.SpeedRef;
DirectionY := AxisCmdY.Direction;

// 📤 7. VALIDATION DES SORTIES ÉTAT
NeutralXAct := NeutralXMem;
NeutralYAct := NeutralYMem;
Done := NOT Error;

// 🧩 SOCLE DE STATUT STANDARD (forme cible) — remplit Status : ST_FbStatus
// Le joystick produit ErrorId (bit0 calib, bit1 capteur, bit2 bus). On le passe au socle
// qui classe : WarningMask bit=1 → warning auto, bit=0 → fault à acquitter.
// Joystick : bit0 (calib) = FAULT à acquitter ; bit1 (capteur) + bit2 (bus) = WARNING auto.
WarningMask := 16#0006;   // bits 1+2 = warning (auto-effacés) ; bit0 = fault
ErrorIdCause := ErrorId;

// Textes IHM (par bit) — stockés dans des tableaux locaux
JoystickErrorTexts[0] := 'Echec calibration joystick (RawX/Y hors zone)';
JoystickErrorTexts[1] := 'Capteur joystick hors plage ADC';
JoystickErrorTexts[2] := 'Perte liaison bus CAN joystick';
JoystickWarningTexts[1] := 'Capteur joystick hors plage ADC (warning)';
JoystickWarningTexts[2] := 'Perte liaison bus CAN joystick (warning)';

instFbStatus(Enable := Enable, Reset := Reset,
             ErrorIdCause := ErrorIdCause, WarningMask := WarningMask,
             ErrorTexts := JoystickErrorTexts, WarningTexts := JoystickWarningTexts,
             RotatePeriod := T#1S);
Status := instFbStatus.Status;
Error := Status.Error;      // miroir (source de vérité = socle)
ErrorId := Status.ErrorId;    // miroir
Ready := NOT Error;

{endregion}

(* ═══════════════════════════════════════════════════════════════
   ↔️ FB_TranslationArbiter — Arbitrage des consignes M3
   ───────────────────────────────────────────────────────────────
   📄 Migration M4 : extrait sans changement la logique de page de
      PRG_TRANSLATION_CFC.st afin que le CFC natif ne porte aucun IF/CASE.
   🔒 Ce FB ne commande aucun actionneur : il produit uniquement la demande
      arbitrée consommée par FB_Translation.
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_TranslationArbiter
VAR_INPUT
    Mode                         : E_Mode;
    AutoStart                    : BOOL;
    AutoTarget                   : INT;
    DeadmanArmed                 : BOOL;
    AxisCmd                      : ST_Joystick_AxisCmd;
    MaintenancePositioning       : BOOL;
    MaintenanceTarget            : INT;
    BtnFwd                       : BOOL;
    BtnRev                       : BOOL;
    TglJoystickMaster            : BOOL;
    SetFreqHz                    : REAL;
    BypassGlobal                 : BOOL;
    InvertDirection              : BOOL;
    MaintenanceM3TargetEnable    : BOOL;
    PosTremie                    : BOOL;
    PosP2                        : BOOL;
    PosP1                        : BOOL;
    PosMaintenance               : BOOL;
    AutoSpeedCapPct              : REAL;
    TranslationMaxFreqHz         : REAL;
END_VAR
VAR_OUTPUT
    StartStop                    : BOOL;
    Direction                    : INT;
    SpeedRefPct                  : REAL;
    PositionSensorTarget         : BOOL;
    PositioningActive            : BOOL;
    SelectedTarget               : INT;
END_VAR
VAR
    FreqPct                      : REAL;
END_VAR

(* ── Arbitrage sources Semi-auto / Maintenance / conduite manuelle ── *)
IF Mode = E_Mode.SEMI_AUTO THEN
    PositioningActive := TRUE;
    SelectedTarget := AutoTarget;
    StartStop := AutoStart AND DeadmanArmed AND AxisCmd.StartStop;
    SpeedRefPct := ABS(AxisCmd.SpeedRef);
    IF SpeedRefPct > AutoSpeedCapPct THEN
        SpeedRefPct := AutoSpeedCapPct;
    END_IF;

    IF SelectedTarget = 1 THEN
        Direction := 1;
    ELSE
        Direction := -1;
    END_IF;
ELSIF (Mode = E_Mode.MAINT_N1) OR (Mode = E_Mode.MAINT_N2) THEN
    PositioningActive := MaintenancePositioning;
    IF PositioningActive THEN
        SelectedTarget := MaintenanceTarget;
    ELSE
        SelectedTarget := 0;
    END_IF;

    IF (NOT TglJoystickMaster) AND BtnFwd THEN
        Direction := 1;
    ELSIF (NOT TglJoystickMaster) AND BtnRev THEN
        Direction := -1;
    ELSIF TglJoystickMaster THEN
        Direction := AxisCmd.Direction;
    ELSE
        Direction := 0;
    END_IF;

    StartStop := (Direction <> 0)
                 AND (DeadmanArmed OR BypassGlobal)
                 AND ((NOT TglJoystickMaster) OR AxisCmd.StartStop);

    IF SetFreqHz > 0.0 THEN
        FreqPct := (SetFreqHz / TranslationMaxFreqHz) * 100.0;
    ELSE
        FreqPct := 30.0;
    END_IF;

    IF TglJoystickMaster THEN
        SpeedRefPct := (ABS(AxisCmd.SpeedRef) / 100.0) * FreqPct;
    ELSE
        SpeedRefPct := FreqPct;
    END_IF;
ELSE
    PositioningActive := FALSE;
    SelectedTarget := MaintenanceTarget;
    StartStop := AxisCmd.StartStop;
    Direction := AxisCmd.Direction;
    SpeedRefPct := AxisCmd.SpeedRef;
END_IF;

(* ── Gardes conservation : inversion, borne vitesse, MAINT_N2 et cible ── *)
IF InvertDirection THEN
    Direction := Direction * (-1);
END_IF;

SpeedRefPct := ABS(SpeedRefPct);
IF SpeedRefPct > 100.0 THEN
    SpeedRefPct := 100.0;
END_IF;

IF (SelectedTarget = 4) AND (NOT MaintenanceM3TargetEnable) THEN
    SelectedTarget := 0;
END_IF;

CASE SelectedTarget OF
    1: PositionSensorTarget := PosTremie;
    2: PositionSensorTarget := PosP2;
    3: PositionSensorTarget := PosP1;
    4: PositionSensorTarget := PosMaintenance;
ELSE
    PositionSensorTarget := FALSE;
END_CASE;

(* ═══════════════════════════════════════════════════════════════
   ⚖️ FB_WinchSync — Surveillance d'écart M1/M2 (M1: moteur de retenue, M2: moteur Benne — squelette liaisons — pas de correction)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-10_Fonction_Winch_v2.0.md §9
   🔌 FB STANDARD (Partie3 §1bis) : pas un FB de mouvement, pas de StartStop/SafeStop —
      1 seule instance (surveille les 2 treuils, pas 1 par treuil comme FB_Safety_Winch).
   🎯 PÉRIMÈTRE CE LOT (squelette de liaisons, décisions Partie9 §9 déjà actées) :
      - Calcule `DeltaPosM = |CablePosM1 - CablePosM2|` (fiable seulement si les 2 treuils
        sont homés — sinon 0.0, pas de comparaison).
      - `SyncActive` selon `Mode` : MAINT_N1 = imposée (non désactivable, sécurité
        maintenue) ; MAINT_N2 = activable/désactivable via `SyncEnable` (FB_Modes, 🔧 REX
        2026-07-08 : ex-`OverrideSync` inversé) ; MANUEL/SEMI_AUTO = active par défaut.
      - `SyncWarn` = AVERTISSEMENT IHM SEULEMENT (Partie5 §6, comme `SyncWarn`/
        `ForceImbalance` cités en exemple) — **PAS de SafeStop** : aucune correction de
        vitesse n'existe aujourd'hui côté FB_Winch (pas d'entrée dédiée), donc rien à
        piloter automatiquement ce lot. Surveillance visuelle opérateur en attendant.
   🔴 HORS PÉRIMÈTRE CE LOT : régulation/correction active de l'écart (nécessiterait une
      entrée de correction sur FB_Winch, pas encore conçue) — squelette de surveillance
      uniquement, comme demandé (« même s'il n'est pas complet à l'intérieur »).

   🔧 REX 2026-07-08 (5) — incident terrain : écart mineur transitoire (0.24m, mécanique,
      coast-down différentiel M1/M2 à l'arrêt réel — normal et inévitable) déclenchait bit0
      et bloquait le mouvement dans les DEUX sens (régression, déblocage possible seulement
      via Reset+MAINT_N2+SyncEnable=FALSE). Root cause : phénomène mécanique, pas un bug du
      couplage croisé logiciel (bit1). Deux correctifs :
      1) `SignedDeltaPosM` (nouvelle sortie, calculé AVANT le ABS() de `DeltaPosM`) : signe
         positif = M1 "plus haut" que M2, négatif = M2 plus haut. Consommé par PRG_06 pour
         arbitrer DIRECTIONNELLEMENT le blocage bit0 — seul le sens qui AGGRAVE l'écart reste
         bloqué, l'autre sens (qui le réduit) reste autorisé. Méca E (FB_Safety_Winch, écart
         critique 2.0m) et bit1 restent le filet réel si l'écart continue de dériver.
      2) Filtre temporel `DeviationTimer` (même pattern que `MismatchTimer` bit1) sur bit0,
         800ms 🔧 théorique à ajuster sur site — absorbe le transitoire mécanique normal
         d'arrêt (~900ms de temporisations frein cumulées M1+M2).
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_WinchSync) ===

FUNCTION_BLOCK PUBLIC FB_WinchSync
VAR_INPUT
    Enable          : BOOL;        // Standard — Partie5 §2 : FB_WinchSync.Enable := SyncEnable (câblage PRG_MAIN)
    Reset           : BOOL;        // Acquittement défaut (front)
    PowerContactorEngaged : BOOL;        // Standard
    Mode            : E_Mode;      // Arbitre SyncActive (voir en-tête)
    CablePosM1      : REAL;        // Sortie FB_Encoder_Scale M1
    CablePosM2      : REAL;        // Sortie FB_Encoder_Scale M2
    HomedM1         : BOOL;        // Sortie FB_Encoder_Homing M1
    HomedM2         : BOOL;        // Sortie FB_Encoder_Homing M2
    SyncEnable      : BOOL;        // 🔧 REX 2026-07-08 : ex-OverrideSync inversé — Sortie FB_Modes, TRUE=synchro voulue
    CfgSyncToleranceM  : REAL := 0.10; // RETAIN site (PRG_MAIN) — écart max toléré avant SyncWarn
    ActiveOffsetM   : REAL := 0.0; // 🪣 Offset cible appliqué (ex: benne fermé/ouvert)
    
    // 🆕 Signaux de commande réels des treuils (pour contrôle de cohérence)
    RelayFwdM1      : BOOL;
    RelayFwdM2      : BOOL;
    RelayRevM1      : BOOL;
    RelayRevM2      : BOOL;
    Contactor1_M1   : BOOL;
    Contactor1_M2   : BOOL;
    Contactor2_M1   : BOOL;
    Contactor2_M2   : BOOL;
    Contactor3_M1   : BOOL;
    Contactor3_M2   : BOOL;
    Contactor4_M1   : BOOL;
    Contactor4_M2   : BOOL;
    // 🌐 Bypass Global : force ErrorId = 0, ignore toute erreur de synchro
    BypassGlobal    : BOOL := FALSE;
END_VAR
VAR_OUTPUT
    Ready           : BOOL;
    Busy            : BOOL;
    Done            : BOOL;
    Error           : BOOL;
    ErrorId         : WORD;        // bit0: "Écart synchronisme trop important" - écart hors tolérance (SyncActive uniquement) ; bit1: "Incohérence commande synchro" - incohérence de commande (sens/paliers différents)
    State           : E_State;
    StateAtError    : E_State;
    DeltaPosM       : REAL;        // |CablePosM1 - CablePosM2|, 0.0 si pas les 2 homés
    SignedDeltaPosM : REAL;        // 🆕 REX 2026-07-08 (5) : signé, > 0 = M1 plus haut que M2 — pour arbitrage directionnel PRG_06
    SyncActive      : BOOL;        // Surveillance imposée/activable selon Mode (voir en-tête)
    SyncWarn        : BOOL;        // ⚠️ Avertissement IHM uniquement (Partie5 §6) — PAS de SafeStop
END_VAR
VAR
    ResetEdge       : R_TRIG;
    ErrorEdge       : R_TRIG;
    MismatchActive  : BOOL;        // 🆕 Indique une discordance active de commande
    MismatchTimer   : TON;         // 🆕 Filtre temporel pour éviter les faux déclenchements transitoires
    DeviationActive : BOOL;        // 🆕 REX 2026-07-08 (5) : écart hors tolérance actif (avant filtre)
    DeviationTimer  : TON;         // 🆕 REX 2026-07-08 (5) : filtre temporel bit0, même pattern que MismatchTimer
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_WinchSync) ===

// 🛑 1. GATE
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    State := E_State.DISABLED;
    DeltaPosM := 0.0;
    SyncActive := FALSE;
    SyncWarn := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🌐 BYPASS GLOBAL : force ErrorId = 0 et ignore toute la surveillance synchro
IF BypassGlobal THEN
    ErrorId := 16#0000;
END_IF;

// 🎚️ 3. SyncActive SELON MODE (Partie9 §9, décisions actées 2026-07-02)
CASE Mode OF
    E_Mode.MAINT_N1:
        SyncActive := TRUE;                  // Imposée, non désactivable (sécurité maintenue N1)
    E_Mode.MAINT_N2:
        SyncActive := SyncEnable;             // 🔧 REX 2026-07-08 : ex-NOT OverrideSync, polarité déjà positive
    ELSE
        SyncActive := TRUE;                  // MANUEL/SEMI_AUTO : pas de logique dédiée (FB_Cycle absent), actif par prudence
END_CASE;

// 📏 4. ÉCART M1/M2 — calculé en continu si les 2 treuils sont homés (même si BypassGlobal est actif)
IF HomedM1 AND HomedM2 THEN
    SignedDeltaPosM := CablePosM1 - CablePosM2 + ActiveOffsetM;
    DeltaPosM := ABS(SignedDeltaPosM);
ELSE
    SignedDeltaPosM := 0.0;
    DeltaPosM := 0.0;
END_IF;

// 🌐 BYPASS GLOBAL : si actif, on saute TOUTE la logique d'erreur/surveillance
IF NOT BypassGlobal THEN

// 🔍 5. DÉTECTION ÉCART HORS TOLÉRANCE — bit0
// 🔧 REX 2026-07-08 (5) : filtre temporel (même pattern que MismatchTimer bit1) — absorbe le
// transitoire mécanique normal d'arrêt (coast-down différentiel M1/M2), évite le blocage
// intempestif constaté sur incident terrain (0.24m transitoire).
DeviationActive := SyncActive AND HomedM1 AND HomedM2 AND (DeltaPosM > CfgSyncToleranceM);
DeviationTimer(IN := DeviationActive, PT := T#800ms);  // 🔧 théorique, à ajuster sur site — absorbe le transitoire mécanique normal d'arrêt (coast-down différentiel M1/M2)
IF DeviationTimer.Q THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q AND NOT DeviationActive THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 🔍 5bis. COHÉRENCE DES COMMANDES SÉCURITÉ — bit1
// Vérifie que les commandes envoyées aux deux treuils sont identiques (sens et contacteurs)
// Filtre de 500ms pour tolérer les transitions et rampes.
MismatchActive := SyncActive AND (
    (RelayFwdM1 <> RelayFwdM2) OR
    (RelayRevM1 <> RelayRevM2) OR
    (Contactor1_M1 <> Contactor1_M2) OR
    (Contactor2_M1 <> Contactor2_M2) OR
    (Contactor3_M1 <> Contactor3_M2) OR
    (Contactor4_M1 <> Contactor4_M2)
);

MismatchTimer(IN := MismatchActive, PT := T#500ms);

IF MismatchTimer.Q THEN
    ErrorId := ErrorId OR 16#0002;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFD;
END_IF; // fin du IF MismatchActive

END_IF; // fin IF NOT BypassGlobal

// 📤 6. SORTIES ÉTAT
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

SyncWarn := Error;   // ⚠️ IHM uniquement — voir en-tête, pas de SafeStop
Busy := FALSE;
Done := FALSE;

