       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ADVANCE_TIME(110000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, 'precondition : geste arme');

    (* RawX=9000 (au-dela du neutre 5000, hors zone morte) : OutPct = (9000-5000)/(10000-5000)*100 = 80% *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 9000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 80.0, 0.01, 'RawX=9000 : proportionnel, 80% -- pas seulement correct aux bornes 0/10000');
    ASSERT_EQ(fb.AXISCMDX.DIRECTION, 1, 'sens avant coherent');
    ASSERT_NEAR(fb.AXISCMDY.SPEEDREF, 0.0, 0.01, 'RawY toujours au neutre : axe Y inchange');

    (* RawY=300 (en-deca du neutre 5000, hors zone morte) : OutPct = (300-5000)/5000*100 = -94% *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 300, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_NEAR(fb.AXISCMDY.SPEEDREF, -94.0, 0.01, 'RawY=300 : proportionnel, -94% -- pas seulement correct aux bornes 0/10000');
    ASSERT_EQ(fb.AXISCMDY.DIRECTION, -1, 'sens arriere coherent');
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 0.0, 0.01, 'RawX revenu au neutre : axe X inchange');
END_TEST

(* =======================================================================
   ⚖️ FB_WinchSync — Coordonnateur synchro M1/M2 (1 instance)
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Coordonner les 2 blocs de surveillance synchro :
      - FB_SyncDeviation  (ecart codeurs M1/M2, 2 seuils Warn/Fault)
      - FB_SyncContactor  (coherence commandes/contacteurs)
      et produire SyncActive (autorisation de couplage) + le statut
      transverse d'ensemble pour les consommateurs (PRG_04/PRG_07/IHM).
   🧬 Responsabilite : coordination + autorisation de couplage. L'ecart
      codeur vit dans FB_SyncDeviation, la coherence contacteurs dans
      FB_SyncContactor. Ce bloc NE calcule PAS l'ecart lui-meme.
   🔒 SyncActive : autorisation de couplage (anti-telescopage), independante
      de l'erreur — le probleme est porte par SyncDeviationWarn/Fault.
   📄 Doc : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_WinchSync
VAR_INPUT
    // === COMMANDES ET CONSIGNES ===
    Enable                          : BOOL;                           // --> [CMD] Validation surveillance globale
    Reset                           : BOOL;                           // --> [CMD] Acquittement defaut sur front
    Mode                            : E_Mode;                         // --> [CMD] Mode courant pour arbitrage SyncActive
    SyncEnable                      : BOOL;                           // --> [CMD] Autorisation utilisateur synchro

    // === MESURES ET ETATS CODEURS ===
    CablePosM1                      : REAL;                           // --> [HW] Position cable treuil M1 (m)
    CablePosM2                      : REAL;                           // --> [HW] Position cable treuil M2 (m)
    HomedAndReliableM1              : BOOL;                           // --> [STAT] Gate fiable M1 (FB_EncoderReliability)
    HomedAndReliableM2              : BOOL;                           // --> [STAT] Gate fiable M2 (FB_EncoderReliability)

    // === REGLAGES ET CONFIGURATION ===
    CfgSyncToleranceM               : REAL := 0.10;                   // --> [CFG] Seuil 1 (Warn) — ecart max avant alerte (m)
    CfgSyncCriticalToleranceM       : REAL := 0.50;                   // --> [CFG] Seuil 2 (Fault) — ecart critique (m)
    ActiveOffsetM                   : REAL := 0.0;                    // --> [CFG] Offset cible RESOLU (ex: benne)

    // === COMMANDES ET FEEDBACKS ACTIONS ===
    RelayFwdM1                      : BOOL;                           // --> [HW] Feedback/Ordre montee M1
    RelayFwdM2                      : BOOL;                           // --> [HW] Feedback/Ordre montee M2
    RelayRevM1                      : BOOL;                           // --> [HW] Feedback/Ordre descente M1
    RelayRevM2                      : BOOL;                           // --> [HW] Feedback/Ordre descente M2
    Contactor1_M1                   : BOOL;                           // --> [HW] Contacteur palier 1 M1
    Contactor1_M2                   : BOOL;                           // --> [HW] Contacteur palier 1 M2
    Contactor2_M1                   : BOOL;                           // --> [HW] Contacteur palier 2 M1
    Contactor2_M2                   : BOOL;                           // --> [HW] Contacteur palier 2 M2
    Contactor3_M1                   : BOOL;                           // --> [HW] Contacteur palier 3 M1
    Contactor3_M2                   : BOOL;                           // --> [HW] Contacteur palier 3 M2
    Contactor4_M1                   : BOOL;                           // --> [HW] Contacteur palier 4 M1
    Contactor4_M2                   : BOOL;                           // --> [HW] Contacteur palier 4 M2

    // === BYPASSES ET SIMULATION ===
    BypassGlobal                    : BOOL := FALSE;                  // --> [TST] Force ErrorId=0 global
END_VAR
VAR_OUTPUT
    // === ETATS IEC ET SYNOPTIQUE ===
    Ready                           : BOOL;                           // <-- [STAT] FB pret a fonctionner
    // ErrorId : <-- [DIAG] bitmask (bit0: ecart Warn, bit1: discordance contacteurs, bit2: ecart Fault)
    Status                          : ST_FbStatus;                    // <-- [STAT] Statut FB groupe (Busy/Done/Error/State/StateAtError)

    // === MESURES ET DIAGNOSTICS DE SYNCHRO ===
    DeltaPosM                       : REAL;                           // <-- [DIAG] Ecart absolu position |M1 - M2| (m)
    SignedDeltaPosM                 : REAL;                           // <-- [DIAG] Ecart signe position (M1 - M2) (m)
    SyncActive                      : BOOL;                           // <-- [STAT] Statut synchro active selon mode
    SyncWarn                        : BOOL;                           // <-- [DIAG] Avertissement IHM (Warn ou discordance)
    SyncDeviationWarn               : BOOL;                           // <-- [DIAG] Ecart seuil 1 depasse (force palier 1)
    SyncDeviationFault              : BOOL;                           // <-- [SAFE] Ecart seuil 2 critique (block signal)
END_VAR
VAR
    // === DETECTEURS ET TIMERS INTERNES ===
    ResetEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Reset
    ErrorEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Erreur

    // === SOUS-INSTANCES FB ===
    instDeviation                   : FB_SyncDeviation;               // * [INST] Comparateur ecart codeurs (pur)
    instContactor                   : FB_SyncContactor;               // * [INST] Coherence commandes/contacteurs
END_VAR

{region "§1 Gate neutralisation"}
// 🛑 1. GATE
IF NOT Enable THEN
    Ready := FALSE; Status.Busy := FALSE; Status.Done := FALSE;
    Status.State := E_State.DISABLED;
    DeltaPosM := 0.0; SignedDeltaPosM := 0.0;
    SyncActive := FALSE;
    SyncWarn := FALSE; SyncDeviationWarn := FALSE; SyncDeviationFault := FALSE;
    Status.Error := FALSE; Status.ErrorId := 16#0000;
    RETURN;
END_IF;
Ready := TRUE;
Status.State := E_State.READY;
{endregion}

{region "§2 Activation synchro"}
// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🌐 BYPASS GLOBAL : force ErrorId = 0 et ignore toute la surveillance synchro
IF BypassGlobal THEN
    Status.ErrorId := 16#0000;
END_IF;

// 🎚️ 3. SyncActive SELON MODE (Partie9 §9) — autorisation de couplage, independante de l'erreur
CASE Mode OF
    E_Mode.MAINT_N1:
        SyncActive := TRUE;                  // Imposée, non désactivable (sécurité maintenue N1)
    E_Mode.MAINT_N2:
        SyncActive := SyncEnable;             // Polarité positive (TRUE = synchro active)
    ELSE
        SyncActive := TRUE;                  // MANUEL/SEMI_AUTO : actif par prudence
END_CASE;
{endregion}

{region "§3 Sous-blocs deviation et contacteurs"}
// 📏 4. ÉCART CODEURS (FB_SyncDeviation) + COHERENCE CONTACTEURS (FB_SyncContactor)
instDeviation(
    Enable               := Enable,
    Reset                := Reset,
    SyncEnable           := SyncActive,
    CablePosM1           := CablePosM1,
    CablePosM2           := CablePosM2,
    HomedAndReliableM1   := HomedAndReliableM1,
    HomedAndReliableM2   := HomedAndReliableM2,
    CfgSyncToleranceM    := CfgSyncToleranceM,
    CfgSyncCriticalToleranceM := CfgSyncCriticalToleranceM,
    ActiveOffsetM        := ActiveOffsetM,
    BypassGlobal         := BypassGlobal
);
DeltaPosM := instDeviation.DeltaPosM;
SignedDeltaPosM := instDeviation.SignedDeltaPosM;
SyncDeviationWarn := instDeviation.SyncDeviationWarn;
SyncDeviationFault := instDeviation.SyncDeviationFault;

instContactor(
    Enable          := Enable,
    Reset           := Reset,
    SyncEnable      := SyncActive,
    RelayFwdM1      := RelayFwdM1,
    RelayFwdM2      := RelayFwdM2,
    RelayRevM1      := RelayRevM1,
    RelayRevM2      := RelayRevM2,
    Contactor1_M1   := Contactor1_M1,
    Contactor1_M2   := Contactor1_M2,
    Contactor2_M1   := Contactor2_M1,
    Contactor2_M2   := Contactor2_M2,
    Contactor3_M1   := Contactor3_M1,
    Contactor3_M2   := Contactor3_M2,
    Contactor4_M1   := Contactor4_M1,
    Contactor4_M2   := Contactor4_M2,
    BypassGlobal    := BypassGlobal
);
{endregion}

{region "§4 Synthese statut"}
// 📤 5. SYNTHESE STATUT — consommateurs (PRG_04/PRG_07/IHM) lisent ce Status
IF NOT BypassGlobal THEN
    // bit0 : ecart seuil 1 (Warn) — force palier 1
    IF instDeviation.SyncDeviationWarn THEN
        Status.ErrorId := Status.ErrorId OR 16#0001;
    ELSIF ResetEdge.Q AND NOT instDeviation.SyncDeviationWarn THEN
        Status.ErrorId := Status.ErrorId AND 16#FFFE;
    END_IF;
    // bit1 : discordance contacteurs
    IF instContactor.ContactorMismatch THEN
        Status.ErrorId := Status.ErrorId OR 16#0002;
    ELSIF ResetEdge.Q THEN
        Status.ErrorId := Status.ErrorId AND 16#FFFD;
    END_IF;
    // bit2 : ecart seuil 2 (Fault) — critique
    IF instDeviation.SyncDeviationFault THEN
        Status.ErrorId := Status.ErrorId OR 16#0004;
    ELSIF ResetEdge.Q AND NOT instDeviation.SyncDeviationFault THEN
        Status.ErrorId := Status.ErrorId AND 16#FFFB;
    END_IF;
ELSE
    Status.ErrorId := 16#0000;
END_IF;

Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;

SyncWarn := Status.Error;   // ⚠️ IHM uniquement — pas de SafeStop
Status.Busy := FALSE;
Status.Done := FALSE;
{endregion}

(* ═══════════════════════════════════════════════════════════════
   ↔️ PRG_TRANSLATION_CFC — Pilotage de la Translation Translation M3
   ───────────────────────────────────────────────────────────────
   ⚙️ Exécuté par la tâche PLC en position 7.
   ✅ Arbitre entre les commandes Manuelles (Joystick) et Automatiques (PRG_05_Cycle).
   ═══════════════════════════════════════════════════════════════
   📄 Docs : DOC/AF_Partie-11_Fonction_Translation_v2.0.md
*)

PROGRAM PRG_TRANSLATION_CFC
VAR_OUTPUT
    // 🛡️ Demande brute explicite, consommée par PRG_10_Outputs_LD.
    // PRG_07 ne produit jamais un PDO/frein M3 autorisé.
    TranslationFinalInterlockRequest : ST_TranslationFinalInterlockRequest;
END_VAR
VAR
    instTranslationM3           : FB_Translation;

    // Commandes arbitrées après sélection Manuel/Auto
    M3_StartStop_Active     : BOOL;
    M3_Direction_Active     : INT;
    M3_SpeedRef_Active      : REAL;
    M3_PositioningActive    : BOOL;
    M3_PositionSensorTarget : BOOL;

    // Target active (HMI en manuel, instCycle en auto) — 0=Aucun, 1=Trémie, 2=P2, 3=P1,
    // 4=Maintenance. PV n'est JAMAIS une cible sélectionnable (point de ralentissement seul).
    SelTarget       : INT;

// 🆕 Commande maintenance depuis ST_TranslationHMI (GVL_IHM.TranslationM3).
// L'objet Translation ne dépend plus de IHM_MANU pour ses commandes M3.
    FreqPct                 : REAL; // Conversion SetFreqHz (Hz) → % pleine échelle pour SpeedRefPct
END_VAR

// === IMPLEMENTATION (corps du PROGRAM PRG_TRANSLATION_CFC) ===

// ── 0. DÉCODAGE MOT CAPTEURS (exécuté en position 0 dans PRG_00_Inputs) ──────

// ── 1. ARBITRAGE DU SÉLECTEUR DE CIBLE ET DE LA DIRECTION ──────────────────
IF PRG_MODES_CFC.Auth.Mode = E_Mode.SEMI_AUTO THEN
    // Mode Auto/Semi-Auto : Consigne issue du séquenceur de cycle
    M3_PositioningActive  := TRUE;
    SelTarget    := PRG_05_Cycle.instCycle.TranslationCmd.Target;
    // 🛡️ SEMI_AUTO reste conditionné par l'homme-mort : relâchement = arrêt,
    // nouvelle sollicitation valide = reprise à l'étape courante.
    M3_StartStop_Active  := PRG_05_Cycle.instCycle.TranslationCmd.Start
                            AND PRG_01_Diagnostics.instJoystick.DeadmanArmed
                            AND PRG_01_Diagnostics.instJoystick.AxisCmdX.StartStop;
    M3_SpeedRef_Active   := MIN(_TranslationAutoSpeedCap_Pct,
                                ABS(PRG_01_Diagnostics.instJoystick.AxisCmdX.SpeedRef));

    // Détermination automatique du sens de marche selon la cible :
    // - Trémie (cible 1) = Marche Avant (Direction := 1)
    // - P2/P1/Maintenance (cibles 2/3/4) = Marche Arrière (Direction := -1)
    IF SelTarget = 1 THEN
        M3_Direction_Active := 1;
    ELSE
        M3_Direction_Active := -1;
    END_IF;
// ── 1bis. MAINT_N1/N2 — 2ᵉ source d'arbitrage (mirroir PRG_TREUILS_CFC §1/§2) ──
// 🔧 REX 2026-07-19 : ex-libellé "IHM_MANU" (bypass supprimé) — cette branche est désormais
// gatée par Mode (MAINT_N1/N2), pas par un flag ManuActive séparé.
// 🆕 REX 2026-07-16 : remplace l'ex-bypass direct M3_CommandWord dans PRG_10_Outputs_LD — M3 est
// désormais piloté par la MÊME instance instTranslationM3 (FB_Translation) qu'en Auto, avec la
// rampe accel/décel et l'interlock changement de sens natifs, sous surveillance réelle de
// FB_Safety_Translation (voir PRG_SAFETY_CFC, Enable désormais inconditionnel).
ELSIF (PRG_MODES_CFC.Auth.Mode = E_Mode.MAINT_N1)
   OR (PRG_MODES_CFC.Auth.Mode = E_Mode.MAINT_N2) THEN
    // 🛠️ Maintenance N1/N2 : sous-mode explicite IHM.
    // SelPositioning=FALSE : jog libre, aucun capteur n'arrête hors fins de course.
    // SelPositioning=TRUE : le capteur de SelTarget arrête le mouvement.
    M3_PositioningActive := GVL_IHM.TranslationM3.Cmd.SelPositioning;
    SelTarget := SEL(M3_PositioningActive,
                             0,
                             StubTranslationPositionSelect_IHM);

    IF NOT GVL_IHM.TranslationM3.Cmd.TglJoystickMaster AND GVL_IHM.TranslationM3.Cmd.BtnFwd THEN
        M3_Direction_Active := 1;   // → Trémie (+1)
    ELSIF NOT GVL_IHM.TranslationM3.Cmd.TglJoystickMaster AND GVL_IHM.TranslationM3.Cmd.BtnRev THEN
        M3_Direction_Active := -1;  // → Maintenance (-1)
    ELSIF GVL_IHM.TranslationM3.Cmd.TglJoystickMaster THEN
        M3_Direction_Active := PRG_01_Diagnostics.instJoystick.AxisCmdX.Direction;
    ELSE
        // Boutons sélectionnés sans BtnFwd/BtnRev : jamais de reprise joystick implicite.
        M3_Direction_Active := 0;
    END_IF;
    // 🛡️ REX 2026-07-19 (revue mission IHM_MANU) : DeadmanArmed exigé même en pilotage boutons
    // IHM (BtnFwd/BtnRev), pas seulement en pilotage joystick — sinon les boutons IHM
    // permettaient un mouvement M3 sans homme-mort (écart relevé par la revue de sécurité).
    // 🌐 Bypass.Global = TRUE → ignore la condition homme-mort (test/simulation)
    M3_StartStop_Active := (M3_Direction_Active <> 0)
                           AND (PRG_01_Diagnostics.instJoystick.DeadmanArmed
                                OR GVL_IHM.TranslationM3.Bypass.Global)
                           AND (NOT GVL_IHM.TranslationM3.Cmd.TglJoystickMaster
                                OR PRG_01_Diagnostics.instJoystick.AxisCmdX.StartStop);

    // 🎯 Vitesse : conserve GVL_IHM.TranslationM3.Cmd.SetFreq_Hz (consigne Hz réglable opérateur,
    // limitée par PRG_10_Outputs_LD à _TranslationMaxFreq_Hz) comme cible pleine échelle — identique
    // pour boutons HMI ET joystick (reproduit exactement l'ex-bypass PRG_10_Outputs_LD, ex-lignes
    // 250-251/271-272 : SetFreqHz = 100%, déflexion joystick = % de cette cible). Convertie en
    // pourcentage car SpeedRefPct (entrée FB_Translation) est une échelle 0-100%, pas des Hz.
    // 🔧 Si SetFreq_Hz = 0 (pas configuré), on utilise une vitesse par défaut de 30%.
    FreqPct := SEL(GVL_IHM.TranslationM3.Cmd.SetFreq_Hz > 0.0,
                  (GVL_IHM.TranslationM3.Cmd.SetFreq_Hz / _TranslationMaxFreq_Hz) * 100.0,
                  30.0); // défaut 30% si SetFreq_Hz non renseigné
    M3_SpeedRef_Active := SEL(GVL_IHM.TranslationM3.Cmd.TglJoystickMaster,
                              FreqPct,
                              (ABS(PRG_01_Diagnostics.instJoystick.AxisCmdX.SpeedRef) / 100.0) * FreqPct);
ELSE
    // Mode Manuel/Maintenance : Consignes issues du Joystick et sélecteur HMI
    M3_PositioningActive := FALSE;
    SelTarget    := StubTranslationPositionSelect_IHM;
    M3_StartStop_Active  := PRG_01_Diagnostics.instJoystick.AxisCmdX.StartStop;
    M3_Direction_Active  := PRG_01_Diagnostics.instJoystick.AxisCmdX.Direction;
    M3_SpeedRef_Active   := PRG_01_Diagnostics.instJoystick.AxisCmdX.SpeedRef;
END_IF;

// 🔄 Inversion de sens IHM (mise en service)
IF GVL_IHM.TranslationM3.Cmd.InvertDirection THEN
    M3_Direction_Active := M3_Direction_Active * (-1);
END_IF;

// 🛡️ Limitation finale M3 : toute source de commande (joystick, IHM ou cycle) arrive
// au variateur dans la plage physique autorisée 0..100 %. Ce garde-fou complète
// les limitations de FB_AxisScale/FB_Ramp et ne remplace pas la chaîne Safety.
M3_SpeedRef_Active := LIMIT(0.0, ABS(M3_SpeedRef_Active), 100.0);

// 🆕 REX 2026-07-18 : cible Maintenance (4) bloquée hors MAINT_N2 (AF_Partie-02 v2.12 §3bis) —
// arbitrage centralisé dans FB_Modes (aucun re-test de Mode ici), refuse toute cible si interdite.
IF (SelTarget = 4) AND NOT PRG_MODES_CFC.Auth.MaintenanceM3TargetEnable THEN
    SelTarget := 0;
END_IF;

// Câblage du capteur de butée de la cible sélectionnée (PV exclu : jamais une cible d'arrêt)
CASE SelTarget OF
    1: M3_PositionSensorTarget := PRG_02_Acquisition_CFC.TranslationPosTremie;
    2: M3_PositionSensorTarget := PRG_02_Acquisition_CFC.TranslationPosP2;
    3: M3_PositionSensorTarget := PRG_02_Acquisition_CFC.TranslationPosP1;
    4: M3_PositionSensorTarget := PRG_02_Acquisition_CFC.TranslationPosMaintenance;
ELSE
    M3_PositionSensorTarget := FALSE;   // Aucun capteur visé
END_CASE;

// ── 2. EXÉCUTION DU PILOTAGE DU TRANSLATION M3 ──────────────────────────────
instTranslationM3(
    Enable                  := PRG_TREUILS_CFC.StubMachineEnableN1
                               AND (PRG_MODES_CFC.Auth.Mode <> E_Mode.DISABLE), // 🔧 WINCH-CORE-01 : DISABLE neutralise M3
    Reset                   := PRG_SUPERVISION_CFC.FaultMachineReset_IHM,
    PowerContactorEngaged         := PRG_01_Inputs_LD.PowerContactorEngaged,
    Mode                    := PRG_MODES_CFC.Auth.Mode,
    StartStop               := M3_StartStop_Active,
    SafeStop                := PRG_SAFETY_CFC.instSafetyTranslationM3.SafeStop,
    Direction               := M3_Direction_Active,
    SpeedRefPct             := M3_SpeedRef_Active,
    PositionSensorTarget    := M3_PositionSensorTarget,
    SlowdownSensor          := PRG_02_Acquisition_CFC.TranslationPosPV, // 🆕 remplace ApproachTime (timer) — ralentissement avant Trémie uniquement
    LimitSwitchFwd          := PRG_02_Acquisition_CFC.M3_LimitSwitchFwd, // 🆕 dérivé du mot capteurs (extrême Trémie, mot=11111)
    LimitSwitchRev          := PRG_02_Acquisition_CFC.M3_LimitSwitchRev, // 🆕 dérivé du mot capteurs (extrême Maintenance, mot=00000)
    DriveStatusWord         := PRG_02_Acquisition_CFC.M3_StatusWord_Filtered,
    DriveActualFreqHz       := UINT_TO_REAL(PRG_02_Acquisition_CFC.M3_ActualFrequencyHz_Filtered) / 100.0,
    CfgRampAccelRate           := _TranslationRampAccelRate_Pct,      // 🔧 PERSISTENT depuis GVL_PERSISTENT
    CfgRampDecelNormalRate     := _TranslationRampDecelNormal_Pct,    // 🔧 idem
    CfgRampDecelFastRate       := _TranslationRampDecelFast_Pct,      // 🔧 idem
    DriveFreqScaleMaxHz     := _TranslationMaxFreq_Hz,             // 🔧 source unique depuis PERSISTENT
    BrakeFeedback           := SEL(GVL_IHM.TranslationM3.Bypass.ContactorFeedback OR GVL_IHM.TranslationM3.Bypass.Global, PRG_01_Inputs_LD.M3BrakeFeedback, instTranslationM3.BrakeReleaseRequest),
    BypassContactorCheck    := GVL_IHM.TranslationM3.Bypass.Global,
    BypassLimitSwitch       := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.LimitSwitch
);

// 🛡️ Publication demande brute M3 vers PRG_10_Outputs_LD.
// Ordre MainTask requis : PRG_07 avant PRG_10. SafeStop reste traité par
// FB_Translation (rampe rapide) et n'est jamais une coupure sèche ici.
TranslationFinalInterlockRequest.Enable := PRG_TREUILS_CFC.StubMachineEnableN1;
TranslationFinalInterlockRequest.Reset := PRG_SUPERVISION_CFC.FaultMachineReset_IHM;
TranslationFinalInterlockRequest.PowerContactorEngaged := PRG_01_Inputs_LD.PowerContactorEngaged;
TranslationFinalInterlockRequest.SafeStop := PRG_SAFETY_CFC.instSafetyTranslationM3.SafeStop;
TranslationFinalInterlockRequest.BrakeReleaseRequest := instTranslationM3.BrakeReleaseRequest;
TranslationFinalInterlockRequest.BrakeCommandOpenConfirmed := PRG_TRANSLATION_CFC.instTranslationM3.BrakeCommandOpenConfirmed;
TranslationFinalInterlockRequest.RequestedDriveControlWord := instTranslationM3.RequestedDriveControlWord;
TranslationFinalInterlockRequest.RequestedDriveFreqHz := instTranslationM3.RequestedDriveFreqHz;

