(* =======================================================================
   📊 FB_Diag_IhmHeartbeat — Surveillance bidirectionnelle Heartbeat IHM/PLC
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Surveillance toggle IHM, generation toggle PLC et diagnostic timeout
   🛡️ Protection : FB de diagnostic autonome (sans action directe sur AU)
   📄 Doc métier : DOC/AF/AF_Partie-12_Fonction_Diagnostic_v1.0.md
   ======================================================================= *)
FUNCTION_BLOCK PUBLIC FB_Diag_IhmHeartbeat
VAR_INPUT
    // === COMMANDES & REGLAGES ===
    Enable                      : BOOL;         // --> [CMD] Active la surveillance (FALSE = IHM invalide)
    TglHeartbeatIhm             : BOOL;         // --> [HW]  Toggle IHM, inversion attendue toutes les 500 ms
    IhmTimeout                  : TIME := T#2s; // --> [CFG] Absence maximale de front IHM
    PlcTogglePeriod             : TIME := T#500ms; // --> [CFG] Periode du clignotant PLC
END_VAR
VAR_OUTPUT
    // === ETATS & DIAGNOSTICS IHM ===
    HeartbeatIhmOk              : BOOL;         // <-- [STAT] TRUE apres front IHM post-boot et avant timeout
    HeartbeatIhmTimeout         : BOOL;         // <-- [DIAG] TRUE = aucun front IHM depuis IhmTimeout
    TglHeartbeatPlc             : BOOL;         // <-- [STAT] Clignotant PLC a superviser cote IHM
    TimeSinceIhmEdge            : TIME;         // <-- [DIAG] Temps ecoule depuis le dernier front IHM
END_VAR
VAR
    // === SOUS-INSTANCES FB ===
    IhmTimeoutTon               : TON;          // * [INST] Timer de surveillance timeout IHM
    PlcToggleTon                : TON;          // * [INST] Timer clignotant heartbeat PLC

    // === CALCULS ET ETATS INTERNES ===
    LastIhmToggle               : BOOL;         // . [LOC]  Memoire du dernier etat toggle IHM
    IhmEdgeSeen                 : BOOL;         // . [LOC]  Verrou front vu (interdit RETAIN au boot)
    IhmEdgeDetected             : BOOL;         // . [LOC]  Front de changement toggle IHM detecte
END_VAR

// === IMPLEMENTATION ===

{region "§1 Gate"}
// 🛑 Sans Enable, aucune valeur mémorisée ne peut déclarer l'IHM valide.
IF NOT Enable THEN
    HeartbeatIhmOk := FALSE;
    HeartbeatIhmTimeout := TRUE;
    TglHeartbeatPlc := FALSE;
    TimeSinceIhmEdge := T#0s;
    LastIhmToggle := TglHeartbeatIhm;
    IhmEdgeSeen := FALSE;
    IhmTimeoutTon(IN := FALSE, PT := IhmTimeout);
    PlcToggleTon(IN := FALSE, PT := PlcTogglePeriod);
    RETURN;
END_IF;
{endregion}

{region "§2 Front IHM"}
// 📥 Front par comparaison : l'IHM écrit un BOOL toggle, pas une impulsion courte.
IhmEdgeDetected := (TglHeartbeatIhm <> LastIhmToggle);
LastIhmToggle := TglHeartbeatIhm;
IF IhmEdgeDetected THEN
    IhmEdgeSeen := TRUE;
END_IF;
{endregion}

{region "§3 Timeout IHM"}
// ⏱️ Le timer repart à chaque front. Au boot, il atteint le timeout au bout de IhmTimeout.
// HeartbeatIhmOk reste TRUE tant que le timeout n'est pas expiré (boot propre sans alarme au scan 1).
IhmTimeoutTon(IN := NOT IhmEdgeDetected, PT := IhmTimeout);
TimeSinceIhmEdge := IhmTimeoutTon.ET;
HeartbeatIhmTimeout := IhmTimeoutTon.Q;
HeartbeatIhmOk := NOT HeartbeatIhmTimeout;
{endregion}

{region "§4 Clignotant PLC"}
// 💡 Clignotant PLC indépendant : information de vie pour l'IHM, jamais signal Signal Safety autonome.
PlcToggleTon(IN := NOT PlcToggleTon.Q, PT := PlcTogglePeriod);
IF PlcToggleTon.Q THEN
    TglHeartbeatPlc := NOT TglHeartbeatPlc;
END_IF;
{endregion}

FUNCTION_BLOCK FB_TestStopwatch
VAR_INPUT
    Arm             : BOOL;
    StartEvent      : BOOL;
    StopEvent       : BOOL;
    ExpectedMinMs   : DINT;
    ExpectedMaxMs   : DINT;
END_VAR
VAR_OUTPUT
    ElapsedMs       : DINT;
    Done            : BOOL;
    InWindow        : BOOL;
END_VAR
VAR
    StartTrig       : R_TRIG;
    StopTrig        : R_TRIG;
    Running         : BOOL;
    CycleCount      : UDINT;
END_VAR
// === IMPLEMENTATION ===
StartTrig(CLK := StartEvent);
StopTrig(CLK := StopEvent);

IF NOT Arm THEN
    Running := FALSE;
    Done := FALSE;
    InWindow := FALSE;
    ElapsedMs := 0;
    CycleCount := 0;
    RETURN;
END_IF;

IF StartTrig.Q AND NOT Running AND NOT Done THEN
    Running := TRUE;
    CycleCount := 0;
END_IF;

IF Running THEN
    // Incrémente le compteur de cycles
    CycleCount := CycleCount + 1;
    ElapsedMs := UDINT_TO_DINT(CycleCount * INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
    
    IF StopTrig.Q THEN
        Running := FALSE;
        Done := TRUE;
        InWindow := (ElapsedMs >= ExpectedMinMs AND ElapsedMs <= ExpectedMaxMs);
    END_IF;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   ⛏️ FB_ExtractionSequence — Fermeture benne et remontée assistée
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF_Partie-04_Mode_SemiAuto_Sequenceur_v2.0.md §3ter
   🛡️ Sécurité : aucune remontée assistée sans fond confirmé ; palier 1 au contrôle.
   🧩 Responsabilité : séquence métier, jamais commande directe de contacteur.
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK FB_ExtractionSequence
VAR_INPUT
    Enable                     : BOOL;
    Reset                      : BOOL;
    PowerContactorEngaged            : BOOL;
    Mode                       : E_Mode;
    MotionRequestActive        : BOOL;
    MotionDirection            : INT; (* +1 = montée *)
    BottomPositionConfirmed    : BOOL;
    BucketIsClosed             : BOOL;
    BucketBusy                 : BOOL;
    BucketError                : BOOL;
    WinchSyncError             : BOOL;
    M1Position_M               : REAL;
    M2Position_M               : REAL;
    M1MeasuredSpeedValid       : BOOL;
    M2MeasuredSpeedValid       : BOOL;
    PositionsValid             : BOOL;
    ControlAscentDistance_M    : REAL;
END_VAR
VAR_OUTPUT
    Ready                      : BOOL;
    Busy                       : BOOL;
    Done                       : BOOL;
    Error                      : BOOL;
    ErrorId                    : WORD; (* bit0: fond absent, bit1: fermeture, bit2: contrôle remontée, bit3: configuration *)
    State                      : E_State;
    StateAtError               : E_State;
    ExtractionState            : E_ExtractionSequenceState;
    BucketCloseRequest         : BOOL;
    AscentPermit               : BOOL;
    ForceMinSpeedStep          : BOOL;
    BottomConfirmationConsumed : BOOL;
    OperatorActionId           : WORD;
    OperatorAction             : STRING(120);
END_VAR
VAR
    ResetEdge                  : R_TRIG;
    ControlStartM1Position_M   : REAL;
    ControlStartM2Position_M   : REAL;
    ErrorCausePresent          : BOOL;
END_VAR

IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    BucketCloseRequest := FALSE; AscentPermit := FALSE; ForceMinSpeedStep := FALSE;
    BottomConfirmationConsumed := FALSE;
    State := E_State.DISABLED;
    StateAtError := E_State.DISABLED;
    ExtractionState := E_ExtractionSequenceState.WAIT_BOTTOM_CONFIRMATION;
    OperatorActionId := 0; OperatorAction := '';
    RETURN;
END_IF;

ResetEdge(CLK := Reset);
ErrorCausePresent := (ControlAscentDistance_M <= 0.0);
IF ErrorCausePresent THEN
    ErrorId := ErrorId OR 16#0008;
END_IF;
IF ResetEdge.Q AND NOT ErrorCausePresent AND NOT MotionRequestActive THEN
    ErrorId := 16#0000;
    StateAtError := E_State.DISABLED;
    ExtractionState := E_ExtractionSequenceState.WAIT_BOTTOM_CONFIRMATION;
END_IF;

Ready := FALSE; Busy := FALSE; Done := FALSE;
BucketCloseRequest := FALSE; AscentPermit := FALSE; ForceMinSpeedStep := FALSE;
BottomConfirmationConsumed := FALSE;
OperatorActionId := 0; OperatorAction := '';

IF ErrorId <> 16#0000 THEN
    State := E_State.READY;
    ExtractionState := E_ExtractionSequenceState.ERROR_HOLD;
    OperatorActionId := 16#0280;
    OperatorAction := 'Vérifier la benne et les treuils puis réarmer avant de reprendre.';
ELSE
    CASE ExtractionState OF
        E_ExtractionSequenceState.WAIT_BOTTOM_CONFIRMATION:
            State := E_State.INIT;
            IF BottomPositionConfirmed THEN
                ExtractionState := E_ExtractionSequenceState.READY_TO_CLOSE;
            ELSE
                OperatorActionId := 16#0200;
                OperatorAction := 'Confirmer que la benne est posée au fond avant extraction.';
            END_IF;

        E_ExtractionSequenceState.READY_TO_CLOSE:
            State := E_State.READY;
            Ready := TRUE;
            OperatorActionId := 16#0201;
            OperatorAction := 'Demander la montée pour fermer la benne.';
            IF MotionRequestActive AND (MotionDirection = 1) THEN
                BottomConfirmationConsumed := TRUE;
                ExtractionState := E_ExtractionSequenceState.CLOSING_BUCKET;
            END_IF;

        E_ExtractionSequenceState.CLOSING_BUCKET:
            State := E_State.BUSY;
            Busy := TRUE;
            BucketCloseRequest := MotionRequestActive AND (MotionDirection = 1);
            OperatorActionId := 16#0202;
            OperatorAction := 'Maintenir la montée : fermeture de la benne en cours.';
            IF BucketError THEN
                ErrorId := ErrorId OR 16#0002;
                StateAtError := State;
            ELSIF BucketIsClosed AND NOT BucketBusy THEN
                ControlStartM1Position_M := M1Position_M;
                ControlStartM2Position_M := M2Position_M;
                ExtractionState := E_ExtractionSequenceState.CONTROL_ASCENT;
            END_IF;

        E_ExtractionSequenceState.CONTROL_ASCENT:
            State := E_State.BUSY;
            Busy := TRUE;
            AscentPermit := MotionRequestActive AND (MotionDirection = 1);
            ForceMinSpeedStep := TRUE;
            OperatorActionId := 16#0203;
            OperatorAction := 'Maintenir la montée : contrôle charge au palier minimal.';
            IF WinchSyncError OR NOT PositionsValid OR NOT M1MeasuredSpeedValid OR NOT M2MeasuredSpeedValid THEN
                ErrorId := ErrorId OR 16#0004;
                StateAtError := State;
            ELSIF (M1Position_M >= (ControlStartM1Position_M + ControlAscentDistance_M))
               AND (M2Position_M >= (ControlStartM2Position_M + ControlAscentDistance_M)) THEN
                ExtractionState := E_ExtractionSequenceState.NOMINAL_ASCENT;
            END_IF;

        E_ExtractionSequenceState.NOMINAL_ASCENT:
            State := E_State.BUSY;
            Busy := TRUE;
            AscentPermit := MotionRequestActive AND (MotionDirection = 1);
            OperatorActionId := 16#0204;
            OperatorAction := 'Maintenir la montée : extraction en cours.';
            IF WinchSyncError OR NOT PositionsValid THEN
                ErrorId := ErrorId OR 16#0004;
                StateAtError := State;
            END_IF;

        E_ExtractionSequenceState.ERROR_HOLD:
            State := E_State.READY;
    END_CASE;
END_IF;

Error := (ErrorId <> 16#0000);

(* =======================================================================
   💾 FB_CfgPersistBridge_CommunCfg — Pont persistance pour ST_CommunCfg
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Restauration et synchronisation bidirectionnelle IHM / Persist
   💾 Persistance : Transfert GVL_PERSISTENT <-> GVL_IHM sur Initialized
   📄 Doc métier : DOC/AF/AF_Partie-03_Contrats_Composants_v2.1.md §3
   ======================================================================= *)
FUNCTION_BLOCK FB_CfgPersistBridge_CommunCfg
VAR_OUTPUT
    // === ETATS RESTAURATION ===
    JustRestored            : BOOL;               // <-- [STAT] Vrai sur le cycle de restauration initiale
END_VAR
VAR_IN_OUT
    // === BUS CONFIGURATION ET PERSISTANCE ===
    Hmi                     : ST_CommunCfg;       // <-> [BUS] Structure de configuration IHM
    Persist                 : ST_CommunCfg;       // <-> [BUS] Structure de configuration persistante
END_VAR

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   🛡️ FB_Safety_EmergencyManagementLogic — Décision & Séquencement
   ───────────────────────────────────────────────────────────────
   📄 Rôle : Gère la machine d'état d'auto-test et de réarmement de
      la boucle d'arrêt d'urgence. Produit les consignes logiques.
   ═══════════════════════════════════════════════════════════════
    📄 Docs : DOC/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md ; DOC/AF_Partie-03_Contrats_Composants_v2.0.md
*)

FUNCTION_BLOCK PUBLIC FB_Safety_EmergencyManagementLogic
VAR_INPUT
    Enable              : BOOL;        // Active la surveillance
    Reset               : BOOL;        // Front acquittement défauts
    ArmRequest          : BOOL;        // Demande de réarmement (BtnEmergencyArming)
    EmergencyChainClosed      : BOOL;        // Retour physique boucle d'urgence amont contacteur
    PowerContactorEngaged     : BOOL;        // Confirmation contacteur de puissance principal
    PowerCutOffRequest  : BOOL;        // Requête de coupure logique issue des métiers
    BtnEmergencyCutOff  : BOOL;        // Commande d'ouverture d'urgence depuis l'IHM
END_VAR
VAR_OUTPUT
    Error               : BOOL;
    ErrorId             : WORD;        // bit0: RedundancyTestFailed, bit1: EmergencyArmingFailed
    Cmd                 : ST_Safety_Emergency_InternalCmd; // Structure de commande logique produite
    
    ArmingSeqStep       : INT;         // Étape de diagnostic : 0=IDLE, 1=TestA, 2=RestoreA, 3=TestB, 4=RestoreB, 5=Pulse, 6=Confirm
    RedundancyTestFailed: BOOL;        // Canal A ou B resté collé/shunté détecté à l'auto-test
    EmergencyArmingFailed: BOOL;       // Contacteur de puissance n'a pas confirmé l'armement
    EmergencyArmingLockoutActive : BOOL; // Verrouillage temporel de 5s entre les essais
END_VAR
VAR
    ResetEdge           : R_TRIG;
    ArmReqEdge          : R_TRIG;
    ForceTestA          : BOOL;
    ForceTestB          : BOOL;
    TonTestA            : TON;
    TonRestoreA         : TON;
    TonTestB            : TON;
    TonRestoreB         : TON;
    TonArmingPulse      : TON;
    TonArmingConfirm    : TON;
    TonArmingLockout    : TON;
END_VAR

// === IMPLEMENTATION ===

// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    Error := FALSE;
    ErrorId := 16#0000;
    Cmd.PowerCutOff_A_Cmd := FALSE;
    Cmd.PowerCutOff_B_Cmd := FALSE;
    Cmd.EmergencyArming_Cmd := FALSE;
    ArmingSeqStep := 0;
    RedundancyTestFailed := FALSE;
    EmergencyArmingFailed := FALSE;
    EmergencyArmingLockoutActive := FALSE;
    ForceTestA := FALSE;
    ForceTestB := FALSE;
    TonTestA(IN := FALSE);
    TonRestoreA(IN := FALSE);
    TonTestB(IN := FALSE);
    TonRestoreB(IN := FALSE);
    TonArmingPulse(IN := FALSE);
    TonArmingConfirm(IN := FALSE);
    TonArmingLockout(IN := FALSE);
    RETURN;
END_IF;

ResetEdge(CLK := Reset);
ArmReqEdge(CLK := ArmRequest);

// 🔍 2. ACQUITTEMENT DES DÉFAUTS
IF ResetEdge.Q THEN
    RedundancyTestFailed := FALSE;
    IF PowerContactorEngaged THEN
        EmergencyArmingFailed := FALSE;
    END_IF;
END_IF;

// 🚦 3. DÉCLENCHEMENT DE LA SÉQUENCE DE SÉCURITÉ
IF ArmReqEdge.Q AND (ArmingSeqStep = 0) AND EmergencyChainClosed 
   AND NOT EmergencyArmingLockoutActive 
   AND NOT PowerContactorEngaged THEN
    ArmingSeqStep := 1;
END_IF;

// ⏱️ Étape 1 : Coupe canal A seul, vérifie que la boucle tombe
TonTestA(IN := (ArmingSeqStep = 1), PT := T#200ms);
IF ArmingSeqStep = 1 THEN
    ForceTestA := TRUE;
    IF TonTestA.Q THEN
        ForceTestA := FALSE;
        IF EmergencyChainClosed THEN
            RedundancyTestFailed := TRUE;
            ArmingSeqStep := 0;
        ELSE
            ArmingSeqStep := 2;
        END_IF;
    END_IF;
ELSE
    ForceTestA := FALSE;
END_IF;

// ⏱️ Étape 2 : Restaure A, attend le retour sain de la boucle amont
TonRestoreA(IN := (ArmingSeqStep = 2), PT := T#200ms);
IF (ArmingSeqStep = 2) AND TonRestoreA.Q THEN
    IF EmergencyChainClosed THEN
        ArmingSeqStep := 3;
    ELSE
        ArmingSeqStep := 0;
    END_IF;
END_IF;

// ⏱️ Étape 3 : Coupe canal B seul, vérifie que la boucle tombe
TonTestB(IN := (ArmingSeqStep = 3), PT := T#200ms);
IF ArmingSeqStep = 3 THEN
    ForceTestB := TRUE;
    IF TonTestB.Q THEN
        ForceTestB := FALSE;
        IF EmergencyChainClosed THEN
            RedundancyTestFailed := TRUE;
            ArmingSeqStep := 0;
        ELSE
            ArmingSeqStep := 4;
        END_IF;
    END_IF;
ELSE
    ForceTestB := FALSE;
END_IF;

// ⏱️ Étape 4 : Restaure B, attend le retour sain de la boucle amont
TonRestoreB(IN := (ArmingSeqStep = 4), PT := T#200ms);
IF (ArmingSeqStep = 4) AND TonRestoreB.Q THEN
    IF EmergencyChainClosed THEN
        ArmingSeqStep := 5;
    ELSE
        ArmingSeqStep := 0;
    END_IF;
END_IF;

// ⏱️ Étape 5 : Les 2 canaux validés -> impulsion réarmement physique (1s)
TonArmingPulse(IN := (ArmingSeqStep = 5), PT := T#1s);
Cmd.EmergencyArming_Cmd := (ArmingSeqStep = 5);
IF (ArmingSeqStep = 5) AND TonArmingPulse.Q THEN
    ArmingSeqStep := 6;
END_IF;

// ⏱️ Étape 6 : Attente confirmation contacteur principal (2s max)
TonArmingConfirm(IN := (ArmingSeqStep = 6), PT := T#2s);
IF ArmingSeqStep = 6 THEN
    IF PowerContactorEngaged THEN
        ArmingSeqStep := 0;
        EmergencyArmingLockoutActive := FALSE;
    ELSIF TonArmingConfirm.Q THEN
        EmergencyArmingFailed := TRUE;
        ArmingSeqStep := 0;
        EmergencyArmingLockoutActive := TRUE;
    END_IF;
END_IF;

// ⏱️ Séquence de verrouillage temporel (5s)
TonArmingLockout(IN := EmergencyArmingLockoutActive, PT := T#5s);
IF TonArmingLockout.Q THEN
    EmergencyArmingLockoutActive := FALSE;
END_IF;

// 📤 4. GÉNÉRATION DES CONSIGNES LOGIQUES
Cmd.PowerCutOff_A_Cmd := NOT PowerCutOffRequest AND NOT ForceTestA AND NOT BtnEmergencyCutOff AND NOT RedundancyTestFailed;
Cmd.PowerCutOff_B_Cmd := NOT PowerCutOffRequest AND NOT ForceTestB AND NOT BtnEmergencyCutOff AND NOT RedundancyTestFailed;

// 📤 5. SYNTHÈSE DES ERREURS
ErrorId := 16#0000;
IF RedundancyTestFailed THEN
    ErrorId := ErrorId OR 16#0001;
END_IF;
IF EmergencyArmingFailed THEN
    ErrorId := ErrorId OR 16#0002;
END_IF;

Error := (ErrorId <> 16#0000);

SETUP
VAR
    fb : FB_SAFETY_EMERGENCYMANAGEMENT;
END_VAR
END_SETUP

TEST 'TC-P01-008 PowerCutOffRequest coupe A et B sans armer'
    (* scan 1 : autotest demarrage (1 cycle, boucle saine, contacteur repos) *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);

    (* scan 2 : regime etabli, maintien sain attendu -- +1 cycle automate (10ms) *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'hors defaut, canal A doit etre maintenu');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'hors defaut, canal B doit etre maintenu');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'pas de sequence en cours');

    (* scan 3 : coupure demandee par un metier (Winch/Translation) -- +1 cycle automate *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := TRUE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'PowerCutOffRequest doit couper le canal A');
    ASSERT_FALSE(fb.MAINTAINB_RQ, 'PowerCutOffRequest doit couper le canal B');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'PowerCutOffRequest ne doit jamais declencher une sequence armement');
END_TEST

TEST 'TC-P01-006 canal colle bloque le reamement (echec auto-test)'
    (* scans 1-2 : demarrage + regime etabli, sain *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);

    (* front ArmRequest -> ArmingSeqStep passe a 1 (TestA), boucle encore saine ce scan -- +1 cycle *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'front ArmRequest doit lancer TestA (step 1)');

    (* 200ms plus tard : le canal A est cense etre coupe, mais la boucle reste fermee -> collage *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.ERROR, 'canal colle doit lever une erreur (RedundancyTestFailed)');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'echec auto-test doit ramener la sequence a IDLE');
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'un canal colle bloque aussi le maintien normal (interlock sur Cause brute)');
END_TEST

TEST 'TC-P01-004/009 Reset acquitte l affichage mais re-alarme si la cause persiste'
    (* reproduit l etat "canal colle" de TC-P01-006 -- setup independant, propre a ce test *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.ERROR, 'precondition : canal colle doit avoir leve une erreur');

    (* Reset : doit acquitter l affichage sans redemarrage auto (TC-P01-004) -- +1 cycle *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := TRUE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_FALSE(fb.ERROR, 'Reset doit effacer l affichage du defaut');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'Reset seul ne relance jamais de sequence (pas de redemarrage auto)');

    (* nouvel essai : cause toujours presente (canal toujours colle) -> doit re-alarmer (TC-P01-009) -- +1 cycle *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'un nouveau front ArmRequest doit relancer TestA');

    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.ERROR, 'cause persistante doit re-alarmer au nouvel essai, meme apres Reset');
END_TEST

(* TC-P01-002 est classee SITE+AUTO dans l AF (mixte). Ce test ne couvre QUE la partie AUTO
   (commande logicielle) : preuve qu un seul canal est coupe a la fois et que le FB interprete
   correctement le retour de boucle fourni en entree. Il ne peut PAS prouver que la coupure
   physique de MaintainA/B_RQ ouvre reellement la boucle materielle -- ca reste une verification
   SITE, sur l automate reel, jamais automatisable en logiciel. *)
TEST 'TC-P01-002 (partie AUTO) chaque canal est commande independamment, l autre reste maintenu'
    (* demarrage + regime etabli, sain *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'hors defaut, canal A maintenu');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'hors defaut, canal B maintenu');

    (* front ArmRequest -> TestA (step 1) : SEUL le canal A doit se couper *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'front doit lancer TestA');
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'TestA : canal A seul doit se couper');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'TestA : canal B ne doit PAS etre affecte');

    (* 200ms plus tard : la boucle reagit reellement a la coupure de A (preuve physique reelle) *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := FALSE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 2, 'TestA reussi (boucle a reagi) -> RestoreA');
    ASSERT_FALSE(fb.ERROR, 'pas de defaut si le canal reagit correctement au test');
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'canal A restaure immediatement apres son test');

    (* 200ms plus tard : boucle refermee (A restaure) -> passage a TestB (step 3) *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 3, 'RestoreA reussi -> TestB');
    ASSERT_FALSE(fb.MAINTAINB_RQ, 'TestB : canal B seul doit se couper');
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'TestB : canal A ne doit PAS etre affecte');

    (* 200ms plus tard : boucle reagit a la coupure de B *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := FALSE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 4, 'TestB reussi -> RestoreB');
    ASSERT_FALSE(fb.ERROR, 'pas de defaut si le canal B reagit correctement au test');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'canal B restaure immediatement apres son test');
END_TEST

