(* =======================================================================
   📊 FB_Diag_CanOpen — Diagnostic bus CANopen & Esclave Joystick
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Surveillance bus CANopen master et esclave Joystick (Online/Op)
   🔌 Architecture : Publication ST_Diag_Device & E_Diag_State
   📄 Doc métier : DOC/AF/AF_Partie-12_Fonction_Diagnostic_v1.0.md
   ======================================================================= *)
FUNCTION_BLOCK PUBLIC FB_Diag_CanOpen
VAR_INPUT
    // === COMMANDES & CONTROLE ===
    Enable                      : BOOL;         // --> [CMD] Active la surveillance CAN
    Reset                       : BOOL;         // --> [CMD] Front d'acquittement des defauts

    // === ETATS BRUTS MATERIEL ===
    CANbusStateRaw              : INT;          // --> [HW]  Valeur brute CANbus.GetBusState() (2 = ACTIVE)
    DeviceJoystickStateRaw      : DEVICE_STATE; // --> [HW]  Valeur brute JOY1.GetDeviceState()

    // === BYPASS & SIMULATION ===
    SimBypassActive             : BOOL;         // --> [TST] TRUE = simulation active pour ce device
    NetworkBypassActive         : BOOL;         // --> [TST] TRUE = bypass reseau global IHM
END_VAR
VAR_OUTPUT
    // === ETATS IEC & CONFORMITE ===
    Ready                       : BOOL;         // <-- [STAT] Logique de surveillance active
    Busy                        : BOOL;         // <-- [STAT] Non utilise (conformite interface)
    Done                        : BOOL;         // <-- [STAT] Non utilise
    State                       : E_Diag_State; // <-- [STAT] Phase courante (INIT/SIMULATED/READY/ERROR)

    // === DIAGNOSTICS & ALARMES ===
    Error                       : BOOL;         // <-- [DIAG] Presence anomalie de communication
    ErrorId                     : WORD;         // <-- [DIAG] Code defaut global resume
    StateAtError                : E_Diag_State; // <-- [DIAG] Phase figee a l'apparition de l'erreur
    DeviceCanOpenMaster         : ST_Diag_Device; // <-- [DIAG] Diagnostics bus CANopen
    DeviceJoystick              : ST_Diag_Device; // <-- [DIAG] Diagnostics esclave Joystick

    // === MIROIRS BRUTS MATERIEL ===
    CANbusStateRawOut           : INT;          // <-- [DIAG] Miroir brut status CANbus
    DeviceJoystickStateRawOut   : DEVICE_STATE; // <-- [DIAG] Miroir brut status Joystick
END_VAR
VAR
    // === SOUS-INSTANCES FB ===
    ResetEdge                   : R_TRIG;       // * [INST] Detecteur front de reset

    // === CALCULS ET ETATS INTERNES ===
    CANbusOnlineReal            : BOOL;         // . [LOC]  Bus reellement actif, hors tout bypass
    DeviceJoystickOnlineReal    : BOOL;         // . [LOC]  Joystick reellement RUNNING, hors tout bypass
    BypassActive                : BOOL;         // . [LOC]  Simulation OU bypass reseau IHM
    CANbusOnlineEff             : BOOL;         // . [LOC]  Online effectif (reel OU bypass)
    DeviceJoystickOnlineEff     : BOOL;         // . [LOC]  Operational effectif (reel OU bypass)
END_VAR

{region "§1 Gate"}
// 🛑 1. GATE : Désactivation logique si Enable = FALSE
IF NOT Enable THEN
    Ready := FALSE;
    State := E_Diag_State.DISABLED;
    DeviceJoystick.State := E_Diag_State.DISABLED;
    DeviceJoystick.Online := FALSE;
    DeviceJoystick.Operational := FALSE;
    DeviceJoystick.Error := FALSE;
    DeviceJoystick.ErrorId := 16#0000;
    DeviceCanOpenMaster.State := E_Diag_State.DISABLED;
    DeviceCanOpenMaster.Online := FALSE;
    DeviceCanOpenMaster.Operational := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    CANbusStateRawOut := CANbusStateRaw;
    DeviceJoystickStateRawOut := DeviceJoystickStateRaw;
    RETURN;
END_IF;

Ready := TRUE;
{endregion}

{region "§2 Interprétation valeurs brutes"}
// 🧮 2. INTERPRÉTATION DES VALEURS BRUTES
CANbusOnlineReal         := (CANbusStateRaw = 2);
DeviceJoystickOnlineReal := (DeviceJoystickStateRaw = DEVICE_STATE.RUNNING);
BypassActive             := SimBypassActive OR NetworkBypassActive;
CANbusOnlineEff          := CANbusOnlineReal OR BypassActive;
DeviceJoystickOnlineEff  := DeviceJoystickOnlineReal OR BypassActive;
{endregion}

{region "§3 Reset front"}
// 🔑 3. RESET FRONT — Efface les défauts si la cause a disparu
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    IF (CANbusOnlineEff AND DeviceJoystickOnlineEff) THEN
        DeviceJoystick.ErrorId := 16#0000;
        StateAtError := E_Diag_State.DISABLED;
    END_IF;
END_IF;
{endregion}

{region "§4 Diagnostic joystick"}
// 🔍 4. DIAGNOSTIC JOYSTICK
// Bit 0 : Perte de communication CAN
IF NOT CANbusOnlineEff THEN
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId OR 16#0001;  (* Perte liaison CAN joystick *)
ELSE
    DeviceJoystick.Online := TRUE;
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId AND 16#FFFE; (* Effacement auto si la liaison revient *)
END_IF;

// Bit 1 : Mode non-opérationnel (esclave CANopen en pré-op ou défaut)
IF NOT DeviceJoystickOnlineEff THEN
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId OR 16#0002;  (* Joystick pas opérationnel *)
    DeviceJoystick.Operational := FALSE;
ELSE
    DeviceJoystick.Operational := TRUE;
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId AND 16#FFFD; (* Effacement auto dès que RUNNING *)
END_IF;
{endregion}

{region "§5 Machine etat joystick"}
// 🚦 5. MACHINE D'ÉTAT JOYSTICK
IF DeviceJoystick.ErrorId <> 0 THEN
    DeviceJoystick.State := E_Diag_State.ERROR;
    IF StateAtError = E_Diag_State.DISABLED THEN
        StateAtError := State;
    END_IF;
ELSIF NOT (DeviceJoystick.Online AND DeviceJoystick.Operational) THEN
    DeviceJoystick.State := E_Diag_State.INIT;
ELSIF BypassActive AND NOT (CANbusOnlineReal AND DeviceJoystickOnlineReal) THEN
    DeviceJoystick.State := E_Diag_State.SIMULATED;
ELSE
    DeviceJoystick.State := E_Diag_State.READY;
END_IF;

State := DeviceJoystick.State;
{endregion}

{region "§6 Sorties globales"}
// 📤 6. SORTIES GLOBALES
DeviceJoystick.Error := (DeviceJoystick.ErrorId <> 0);
Error := DeviceJoystick.Error;
ErrorId := DeviceJoystick.ErrorId;

DeviceCanOpenMaster.Operational := CANbusOnlineEff;
DeviceCanOpenMaster.Online := CANbusOnlineEff;

IF NOT CANbusOnlineEff THEN
    DeviceCanOpenMaster.State := E_Diag_State.INIT;
ELSIF BypassActive AND NOT CANbusOnlineReal THEN
    DeviceCanOpenMaster.State := E_Diag_State.SIMULATED;
ELSE
    DeviceCanOpenMaster.State := E_Diag_State.READY;
END_IF;

// Miroirs bruts, toujours à jour
CANbusStateRawOut := CANbusStateRaw;
DeviceJoystickStateRawOut := DeviceJoystickStateRaw;

// Briques génériques pour conformité standard
Busy := FALSE;
Done := FALSE;
{endregion}

(* ═══════════════════════════════════════════════════════════════
   🪝 FB_Winch — Directeur d'un treuil individuel (M1: moteur de retenue / M2: moteur Benne — instance par treuil)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-10_Fonction_Winch_v2.0.md
   🔌 FB DE MOUVEMENT (Partie3 §1bis) : porte StartStop + SafeStop en
      plus de l'interface standard. Précédence Enable > SafeStop > StartStop.
   🧩 Compose FB_SpeedStep (décodage palier). 🆕 2026-08-06 (retrait FB_Brake, demande
      client) : le frein n'est plus géré ici — FB_Winch ne produit plus aucune sortie
      frein. La commande frein est désormais un couplage DIRECT sur RelayFwd/RelayRev,
      calculé dans FB_WinchOutputInterlock_LD puis câblé au grand jour dans
      PRG_06_Outputs_LD (voir bandeaux de ces deux fichiers). FB_Brake reste utilisé
      tel quel pour Translation (M3), non touché par ce lot.
   📤 Sorties physiques : RelayFwd/RelayRev (contacteurs de sens),
      Contactor1..4 (contacteurs de vitesse) — à câbler manuellement sur les
      canaux Q réels (I/O Mapping CODESYS). Le frein n'est plus une sortie de ce FB.
   🔒 Interlock changement de sens : jamais Fwd et Rev simultanément.
      ⚠️ CORRECTIF (retour terrain 2026-07-01) : neutre↔un sens = immédiat ;
      seule une inversion DIRECTE Fwd↔Rev exige la vitesse confirmée nulle
      (l'ancienne version exigeait l'arrêt confirmé même pour le tout
      premier engagement, ce qui bloquait `CommandedDirection` à 0 en
      permanence — voir §3bis dans le corps ST pour le détail).
   ⚠️ ÉVOLUTION (retour terrain 2026-07-01) : `Contactor1..4` sont désormais
      lus directement dans `FB_SpeedStep` (table `P<palier>R<relais>`),
      plus de masque `BYTE` intermédiaire ni de bit-extraction ici.
   ⚠️ CORRECTIF (retour terrain 2026-07-02) : une inversion de sens PLUS
      RAPIDE que le temps de décélération réel pouvait bloquer
      indéfiniment `CommandedDirection` (le treuil ne s'arrêtait jamais,
      continuait dans l'ancien sens) — la cible de rampe suivait la
      magnitude joystick en continu, sans garantie de croiser le seuil
      d'arrêt. Corrigé : `DirectionChangePending` FORCE désormais la
      cible à 0.0 dès qu'un changement de sens est en attente, de façon
      déterministe et indépendante du joystick (voir §3 dans le corps ST).
   🔴 Ce lot (M1 seul, Maintenance N1, test banc) : pas de dépendance
      codeur. SafeStop vient de FB_Safety_Winch (perte joystick/CAN
      uniquement pour l'instant — voir CODE/TREUILS/FB_Safety_Winch.st).
   🆕 AJOUT (2026-07-02, retour terrain — détecteur mou de câble) : nouvelle
      entrée `ForbidDescent` (sortie dédiée FB_Safety_Winch, DISTINCTE de
      `SafeStop`). ⚠️ ÉVOLUTION D72 (2026-07-03vicies, voir plus bas) :
      `RelayFwd` (montée) toujours piloté normalement, mais `ForbidDescent`
      déclenche maintenant une vraie décélération rapide dès qu'on n'est PAS
      en train de remonter — voir DOC/AF_Partie-10_Fonction_Winch_v2.0.md §4ter pour le contexte
      d'origine, et l'entrée D72 ci-dessous pour le comportement actuel.
   🆕 AJOUT (2026-07-03quinquies, retour terrain — limitation couple en descente) :
      nouveau paramètre `CfgMaxStepDescente` (défaut 2). En descente
      (`CommandedDirection = -1`), le palier atteignable par `FB_SpeedStep` est
      plafonné à cette valeur MÊME à consigne joystick 100% — la charge est
      entraînante en descente (image de couple, pas besoin d'aller vite). En
      montée, les 5 paliers normaux restent inchangés (`MaxStepNumber := 5`).
      Ne change PAS la logique de décodage (voir FB_SpeedStep.st), juste le
      plafond fourni selon le sens.
   🔧 CORRECTIF (2026-07-03vicies, demande utilisateur, AUDIT D72) : `ForbidDescent`
      (mou de câble) intègre désormais une VRAIE décélération rapide (comme `SafeStop`)
      via `EffectiveSafeStop`, au lieu d'un simple masquage brut de `RelayRev`. INHIBÉ
      quand `CommandedDirection = 1` (montée/enroulement en cours) : l'opérateur peut
      librement remonter pour reprendre le mou, sans déclencher de décélération. Le
      masquage `RelayRev := FALSE` sur `ForbidDescent` reste EN PLUS, inconditionnel
      (filet de sécurité direct, indépendant de la rampe).
   🔴🔧 REX 2026-07-07 : NOUVELLE DONNÉE TERRAIN — `ContactorFeedbackFwd`/`ContactorFeedbackRev`
      (retour individuel par sens) SUPPRIMÉS côté matériel, remplacés par UN SEUL retour par
      treuil (`FwdRevSpeedFeedbackOff` = "tous contacteurs sens+vitesse retombés"). Conséquences :
      - `FwdContactorCheck`/`RevContactorCheck` (2 diagnostics séparés) fusionnés en UN seul
        `ContactorsCheck` (`ST_ContactorCheck`) — on ne sait plus DIRE lequel est resté collé.
      - Détection **StuckClosed uniquement**, vérifiée **seulement à l'arrêt commandé** (tous
        relais/contacteurs à FALSE) : si `FwdRevSpeedFeedbackOff` ne repasse pas à `TRUE` dans le
        délai `ContactorFeedbackTimeout`, défaut "contacteur(s) collé(s)" global (bit1 `ErrorId`).
      - `StuckOpen` n'a plus de sens (pas de confirmation individuelle par sens quand un
        mouvement est commandé) — `ContactorsCheck.StuckOpen` reste toujours `FALSE`, gardé
        uniquement pour la compatibilité de type `ST_ContactorCheck` (partagé avec `BrakeContactorCheck`).
      - Bit2 `ErrorId` (ex-RevContactorCheck) est désormais **libre/inutilisé**.
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Winch
VAR_INPUT
    Enable                  : BOOL;
    Reset                   : BOOL;
    PowerContactorEngaged         : BOOL;
    Mode                    : E_Mode;
    StartStop               : BOOL;
    SafeStop                : BOOL;
    ForbidDescent           : BOOL;
    ForbidAscent            : BOOL;
    Direction               : INT;
    SpeedRefPct             : REAL;
    SpeedStepTable          : ST_SpeedStepTable;
    CfgMaxStepDescente         : INT := 3;    // 🆕 Plafond palier en descente (CommandedDirection=-1) — couple, pas vitesse — 🔧 REX 2026-07-08 : défaut relevé à 3
    MaxStepAscent           : INT := 5;    // 🆕 REX 2026-07-15 (9) : Plafond palier en montée (CommandedDirection=1) — 5 = pas de restriction
                                             // (valeur fixe Auto ET Manuel, voir PRG_TREUILS_CFC).
    HomingApproachActive    : BOOL;        // 🆕 REX 2026-07-08 : Limite la vitesse au palier 1 en montée (approche capteur haut)
    FwdRevSpeedFeedbackOff  : BOOL;   // 🔧 REX 2026-07-07 : retour unique "tous contacteurs sens+vitesse
                                       // retombés" (remplace ContactorFeedbackFwd/Rev)
    BypassContactorCheck    : BOOL;   // 🧪 TRUE = désactive StuckClosed (axe simulé,
                                       // voir GVL_Simulation.SensorMxContactorFeedbackIsReal — TOUJOURS FALSE réel)
    BypassGlobal            : BOOL;   // 🌐 TRUE = force ErrorId=0, ignore toutes les erreurs du FB
    SpeedStepHystMargin     : REAL := 2.0;
    // 🆕 2026-08-06 (décision validée, retour terrain) : rampe %/s (CfgRampAccelRate/
    // DecelNormalRate/DecelFastRate, FB_Ramp) RETIRÉE — remplacée par une temporisation FIXE
    // par palier, asymétrique montée/descente. Cible documentée
    // DOC/AF_Partie-10_Fonction_Winch_v2.0.md §6.2 (montée en charge = plus prudente, descente
    // sans effort = plus rapide).
    // 🆕 2026-08-06 (simplification demandée) : interlock changement de sens asymétrique —
    // descente sans effort (pas de charge résistante, réengagement rapide), montée = charge en
    // traction (délai plus long). La temporisation par palier se DÉDUIT de cet interlock
    // (+100ms) plutôt que d'être un réglage séparé — garantit par construction qu'elle reste
    // toujours au-dessus, jamais besoin de les tenir synchronisés à la main.
    DirectionInterlockDelayDescent : TIME := T#400ms;  // Réengagement en descente (CommandedDirection=-1)
    DirectionInterlockDelayAscent  : TIME := T#900ms;  // Réengagement en montée (CommandedDirection=1)
    ContactorFeedbackTimeout: TIME := T#500ms;
    Homed                   : BOOL;             // 🆕 État de référencement du treuil
    HomingSuspect           : BOOL;             // 🆕 REX 2026-07-08 : Incertitude/doute sur le référencement (§3.7)
    CablePosM               : REAL;             // 🆕 Position actuelle du câble en mètres
    TopLimitM               : REAL := 8.5;      // 🆕 Position limite haute active (cible homing, m) — ancre le ralentissement
    BottomLimitM            : REAL := -20.0;    // 🆕 Position limite basse active (m)
    CfgSlowdownDistanceM       : REAL := 1.0;      // 🆕 Distance d'approche avant limite pour ralentir (m)
    CfgSlowdownMaxStep         : INT := 1;         // 🆕 2026-08-07 : Plafond palier dans la zone de ralentissement (1..5, défaut 1 = vitesse mini)
    MeasuredSpeedBand       : INT := 0;         // 🛡️ Bande vitesse réelle validée
    SpeedGuardEnable        : BOOL := FALSE;   // 🛡️ Activation garde-fou changement de palier
    SpeedGuardReady         : BOOL := FALSE;   // 🟢 Conditions de stabilité validées
END_VAR
VAR_OUTPUT
    Ready               : BOOL;
    Busy                : BOOL;
    Done                : BOOL;
    Error               : BOOL;
    ErrorId             : WORD; // bit0: frein ; bit1: contacteur(s) collé(s) ; bit2: configuration FB_SpeedStep invalide
    State               : E_State;
    StateAtError        : E_State;
    RelayFwd            : BOOL;
    RelayRev            : BOOL;
    Contactor1          : BOOL;
    Contactor2          : BOOL;
    Contactor3          : BOOL;
    Contactor4          : BOOL;
    RequestedStep       : INT;             // Palier brut calculé par FB_SpeedStep avant tempo métier
    StepNumber          : INT;             // Palier métier temporisé, transmis à l'interlock final
    BusinessStepDelayElapsed : TIME;       // Écoulé de la tempo métier (EffectiveStepDelay, asymétrique montée/descente)
    SpeedGuardLimited   : BOOL;
    ContactorsCheck     : ST_ContactorCheck;  // 🔧 REX 2026-07-07 : fusion Fwd+Rev (StuckOpen toujours FALSE, voir bandeau)
    InTopSlowdownZone    : BOOL;   // 🆕 2026-08-07 : diagnostic — palier plafonné à 1 (approche limite haute)
    InBottomSlowdownZone : BOOL;   // 🆕 2026-08-07 : diagnostic — palier plafonné à 1 (approche limite basse)
    CommandedDirection  : INT;     // 🆕 2026-08-07 : diagnostic — sens interne mémorisé (déclaration déplacée depuis VAR, aucun changement de logique)
    DirectionChangeDelayElapsed : TIME; // 🆕 2026-08-07 : diagnostic — écoulé de DirectionChangeDelay (miroir, retour terrain délai montée)
    DirectionChangePending : BOOL; // 🆕 2026-08-07 : diagnostic — déclaration déplacée depuis VAR (GATE 2sexies : doit accompagner CommandedDirection), aucun changement de logique
END_VAR
VAR
    SpeedStep           : FB_SpeedStep;
    CycleTimeCalc       : FB_CycleTime;
    // 🆕 2026-08-06 : SpeedRamp (FB_Ramp) retiré — RampTargetPct alimente directement
    // FB_SpeedStep, la progressivité vient de la temporisation par palier (StepDelay ci-dessous).
    ResetEdge           : R_TRIG;
    ErrorEdge           : R_TRIG;
    DirectionChangeDelay: TON;
    EffectiveDirectionInterlockDelay : TIME; // 🆕 2026-08-06 : DirectionInterlockDelayDescent/Ascent selon le sens ENTRANT (Direction)
    EffectiveStepDelay  : TIME; // 🆕 2026-08-06 : déduit d'EffectiveDirectionInterlockDelay + T#100ms
    TonContactorsDropped: TON;   // 🔧 REX 2026-07-07 : remplace TonFwdFeedback/TonRevFeedback
    BusinessStepDelay    : TON;   // 🪜 Tempo métier nominale entre hausses de palier
    AllContactorsCommandedOff : BOOL; // 🔧 REX 2026-07-07
    RampTargetPct       : REAL;
    EffectiveSafeStop   : BOOL;   // 🆕 2026-07-03vicies — SafeStop réel OU (ForbidDescent hors montée)
    ActiveMaxStep       : INT;    // 🆕 REX 2026-07-08 : Limite dynamique du pas de vitesse
    FirstScanDone       : BOOL;
END_VAR

IF NOT Enable OR NOT PowerContactorEngaged THEN
    RelayFwd := FALSE; RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    SpeedStep(Enable := FALSE, SpeedRefPct := 0.0, Table := SpeedStepTable, HystMargin := SpeedStepHystMargin);
    RequestedStep := SpeedStep.StepNumber;
    StepNumber := 0;
    BusinessStepDelay(IN := FALSE, PT := T#1s500ms);
    BusinessStepDelayElapsed := T#0ms;
    CommandedDirection := 0;
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelayAscent);
    DirectionChangeDelayElapsed := T#0ms;
    InTopSlowdownZone := FALSE;
    InBottomSlowdownZone := FALSE;
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

// 🧹 Initialisation au premier scan : purge des résidus RAM d'un Online Change / Warm Start et évitement des alarmes transitoires
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    ErrorId := 16#0000;
    StepNumber := 0;
    RequestedStep := 0;
    BusinessStepDelay(IN := FALSE, PT := T#1s500ms);
    BusinessStepDelayElapsed := T#0ms;
    RETURN;
END_IF;

Ready := TRUE;
CycleTimeCalc(DefaultValueS := 0.010);

ResetEdge(CLK := Reset);

DirectionChangePending := (Direction <> CommandedDirection) AND (CommandedDirection <> 0);

// 🆕 Mou de câble (ForbidDescent) et Fin de course haut (ForbidAscent) intégrés à une VRAIE
// décélération rapide (comme SafeStop) :
// - ForbidDescent est INHIBÉ si CommandedDirection = 1 (montée libre pour reprendre le mou)
// - ForbidAscent est INHIBÉ si CommandedDirection = -1 (descente libre pour dégager le câble)
EffectiveSafeStop := SafeStop 
                     OR (ForbidDescent AND (CommandedDirection <> 1))
                     OR (ForbidAscent AND (CommandedDirection <> -1));

RampTargetPct := 0.0;
IF NOT EffectiveSafeStop AND StartStop AND NOT DirectionChangePending THEN
    RampTargetPct := ABS(SpeedRefPct);
END_IF;

// 🆕 RALENTISSEMENT AUTOMATIQUE SUR BORDURES (si référencé et non suspect) — permet d'approcher
// les fins de course / limites en vitesse lente de façon progressive.
// 🔧 2026-08-07 (demande client) : ancien plafond RampTargetPct en % (CfgSlowSpeedPct) remplacé
// par un plafond palier direct (ActiveMaxStep := 1, ci-dessous, même mécanisme que
// CfgMaxStepDescente/MaxStepAscent) — un treuil ne connaît que 5 paliers de contacteurs, pas une
// vitesse continue ; palier 1 = tous contacteurs de vitesse relâchés = vitesse minimale, sans
// dépendre d'un % qui doit rester sous le 1er seuil de la table pour produire le même effet.
InTopSlowdownZone := Homed AND NOT HomingSuspect
                      AND ((CommandedDirection = 1) OR (Direction = 1))
                      AND (CablePosM >= (TopLimitM - CfgSlowdownDistanceM));
InBottomSlowdownZone := Homed AND NOT HomingSuspect
                         AND ((CommandedDirection = -1) OR (Direction = -1))
                         AND (CablePosM <= (BottomLimitM + CfgSlowdownDistanceM));

// 🆕 2026-08-06 : délai asymétrique selon le sens ENTRANT (Direction) — descente sans effort
// (câble mou/gravité favorable) réengage plus vite que montée (charge en traction). La tempo
// palier se DÉDUIT de cet interlock (+100ms) : jamais besoin de resynchroniser deux réglages.
IF Direction = -1 THEN
    EffectiveDirectionInterlockDelay := DirectionInterlockDelayDescent;
ELSE
    EffectiveDirectionInterlockDelay := DirectionInterlockDelayAscent;
END_IF;
EffectiveStepDelay := EffectiveDirectionInterlockDelay + T#100ms;

IF Direction <> CommandedDirection THEN
    // 🆕 2026-08-07 (retour terrain) : démarrage depuis le neutre/arrêt (CommandedDirection = 0)
    // prise en compte IMMÉDIATE (0ms), pas de tempo interlock.
    // L'interlock DirectionChangeDelay (400ms descente / 900ms montée) ne s'applique QU'EN CAS
    // d'inversion active de sens en mouvement (ex: de -1 vers +1 direct).
    IF CommandedDirection = 0 THEN
        CommandedDirection := Direction;
        DirectionChangeDelay(IN := FALSE, PT := EffectiveDirectionInterlockDelay);
    ELSIF StepNumber = 0 THEN
        DirectionChangeDelay(IN := TRUE, PT := EffectiveDirectionInterlockDelay);
        IF DirectionChangeDelay.Q THEN
            CommandedDirection := Direction;
            DirectionChangeDelay(IN := FALSE, PT := EffectiveDirectionInterlockDelay);
        END_IF;
    ELSE
        DirectionChangeDelay(IN := FALSE, PT := EffectiveDirectionInterlockDelay);
    END_IF;
ELSE
    DirectionChangeDelay(IN := FALSE, PT := EffectiveDirectionInterlockDelay);
END_IF;
DirectionChangeDelayElapsed := DirectionChangeDelay.ET; // 🆕 2026-08-07 : diagnostic, miroir pur

// 🆕 Plafond dynamique de palier (CfgMaxStepDescente en descente, Palier 1 si non référencé ou douteux,
// Palier 1 en approche homing, MaxStepAscent en montée normale — 🔧 REX 2026-07-15 (9))
IF NOT Homed OR HomingSuspect THEN
    // 🆕 Bypass.Global = TRUE → pas de limitation, on applique la règle normale
    IF BypassGlobal THEN
        ActiveMaxStep := SEL(CommandedDirection = -1, MaxStepAscent, CfgMaxStepDescente);
    ELSE
        ActiveMaxStep := 1;
    END_IF;
ELSIF CommandedDirection = -1 THEN
    ActiveMaxStep := CfgMaxStepDescente;
ELSIF (CommandedDirection = 1) AND HomingApproachActive THEN
    ActiveMaxStep := 1;
ELSIF CommandedDirection = 1 THEN
    ActiveMaxStep := MaxStepAscent;
ELSE
    ActiveMaxStep := 5;
END_IF;

// 🆕 2026-08-07 : ralentissement sur bordure (voir plus haut) — remplace l'ancien plafond en %
// par un plafond palier direct (CfgSlowdownMaxStep, défaut 1 = vitesse mini, réglable IHM),
// appliqué APRÈS le calcul normal ci-dessus via MIN (ne peut qu'abaisser, jamais relever le
// plafond déjà décidé par ailleurs — ex. CfgMaxStepDescente déjà plus restrictif).
IF InTopSlowdownZone OR InBottomSlowdownZone THEN
    ActiveMaxStep := MIN(ActiveMaxStep, CfgSlowdownMaxStep);
END_IF;

SpeedStep(Enable := (RampTargetPct > 0.1), SpeedRefPct := RampTargetPct,
          Table := SpeedStepTable, HystMargin := SpeedStepHystMargin,
          MaxStepNumber := ActiveMaxStep,
          MeasuredSpeedBand := MeasuredSpeedBand,
          SpeedGuardEnable := SpeedGuardEnable,
          SpeedGuardReady := SpeedGuardReady);
// 🪜 Tempo métier nominale : le décollage initial de StepNumber=0 vers 1 est IMMÉDIAT (0ms).
// Toute hausse ultérieure (1->2->3) exige EffectiveStepDelay (interlock + 100ms) et progresse par pas adjacents.
// Toute baisse reste immédiate pour ne jamais retarder un arrêt/safety.
RequestedStep := SpeedStep.StepNumber;
IF RequestedStep > StepNumber THEN
    IF StepNumber = 0 THEN
        StepNumber := 1;
        BusinessStepDelay(IN := FALSE, PT := EffectiveStepDelay);
        BusinessStepDelayElapsed := T#0ms;
    ELSE
        BusinessStepDelay(IN := TRUE, PT := EffectiveStepDelay);
        BusinessStepDelayElapsed := BusinessStepDelay.ET;
        IF BusinessStepDelay.Q THEN
            StepNumber := StepNumber + 1;
            BusinessStepDelay(IN := FALSE, PT := EffectiveStepDelay);
        END_IF;
    END_IF;
ELSE
    BusinessStepDelay(IN := FALSE, PT := EffectiveStepDelay);
    BusinessStepDelayElapsed := BusinessStepDelay.ET;
    StepNumber := RequestedStep;
END_IF;
SpeedGuardLimited := SpeedStep.SpeedGuardLimited;

// Les sorties métier suivent le palier temporisé. FB_Winch/SpeedStepTable reste
// propriétaire unique des combinaisons, y compris les mappings M2 Benne dynamiques.
// FB_WinchOutputInterlock_LD ne fait qu'autoriser ou masquer ces quatre demandes.
CASE StepNumber OF
    1:
        Contactor1 := SpeedStepTable.P1R1; Contactor2 := SpeedStepTable.P1R2;
        Contactor3 := SpeedStepTable.P1R3; Contactor4 := SpeedStepTable.P1R4;
    2:
        Contactor1 := SpeedStepTable.P2R1; Contactor2 := SpeedStepTable.P2R2;
        Contactor3 := SpeedStepTable.P2R3; Contactor4 := SpeedStepTable.P2R4;
    3:
        Contactor1 := SpeedStepTable.P3R1; Contactor2 := SpeedStepTable.P3R2;
        Contactor3 := SpeedStepTable.P3R3; Contactor4 := SpeedStepTable.P3R4;
    4:
        Contactor1 := SpeedStepTable.P4R1; Contactor2 := SpeedStepTable.P4R2;
        Contactor3 := SpeedStepTable.P4R3; Contactor4 := SpeedStepTable.P4R4;
    5:
        Contactor1 := SpeedStepTable.P5R1; Contactor2 := SpeedStepTable.P5R2;
        Contactor3 := SpeedStepTable.P5R3; Contactor4 := SpeedStepTable.P5R4;
ELSE
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
END_CASE;

// 🆕 2026-08-06 (retour terrain) : coupure INSTANTANÉE de tous les contacteurs de vitesse dès
// que l'opérateur relâche le joystick (Direction=0) — ne pas attendre la fin de la rampe de
// décélération. Avant ce correctif, StepNumber suivait la rampe (décélération progressive),
// gardant les contacteurs de vitesse engagés plusieurs secondes après l'ordre d'arrêt.
IF Direction = 0 THEN
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
END_IF;

// Le sens et la pré-magnétisation suivent la demande brute ; le palier métier
// temporisé reste seul transmis à l'interlock final pour autoriser la puissance.
// 🆕 2026-08-06 (retour terrain) : ET Direction=1/-1 (demande OPÉRATEUR brute, pas
// CommandedDirection qui reste au dernier sens jusqu'à la retombée de la rampe) — coupure
// instantanée du contacteur de sens dès le relâchement du joystick, même sécurité que ci-dessus.
// 🆕 2026-08-06 (retrait FB_Brake, demande client) : plus de terme BrakeSafetyOk — le frein
// n'est plus une condition d'engagement des relais de sens, c'est l'inverse (voir
// FB_WinchOutputInterlock_LD §6 : BrakeCmd := RelayFwd OR RelayRev, calculé APRÈS ces relais).
RelayFwd := (Direction = 1) AND (CommandedDirection = 1) AND (RequestedStep > 0);
RelayRev := (Direction = -1) AND (CommandedDirection = -1) AND (RequestedStep > 0);

IF ForbidDescent THEN
    RelayRev := FALSE;
END_IF;

IF ForbidAscent THEN
    RelayFwd := FALSE;
END_IF;

// 🔧 REX 2026-07-07 : vérification UNIQUEMENT à l'arrêt commandé (plus de détail par sens —
// voir bandeau en-tête). AllContactorsCommandedOff = tout ce que FB_Winch commande est à FALSE.
AllContactorsCommandedOff := (NOT RelayFwd) AND (NOT RelayRev)
                             AND (NOT Contactor1) AND (NOT Contactor2) AND (NOT Contactor3) AND (NOT Contactor4);

ContactorsCheck.Command  := NOT AllContactorsCommandedOff;   // TRUE = au moins un contacteur commandé
ContactorsCheck.Feedback := NOT FwdRevSpeedFeedbackOff;      // TRUE = au moins un contacteur pas retombé
TonContactorsDropped(IN := AllContactorsCommandedOff AND NOT FwdRevSpeedFeedbackOff, PT := ContactorFeedbackTimeout);
IF TonContactorsDropped.Q THEN
    ContactorsCheck.StuckClosed := TRUE;
ELSIF ResetEdge.Q THEN
    ContactorsCheck.StuckClosed := FALSE;
END_IF;
ContactorsCheck.StuckOpen := FALSE; // Non applicable avec ce retour (pas de confirmation par sens, voir bandeau)

// 🌐 BYPASS GLOBAL : force ErrorId = 0 et saute toute la logique d'erreur
IF BypassGlobal THEN
    ErrorId := 16#0000;
END_IF;

IF NOT BypassGlobal THEN
// 🆕 2026-08-06 (retrait FB_Brake) : bit0 ErrorId libre — le frein n'est plus surveillé
// ici, sa cohérence commande/retour vit désormais dans FB_WinchOutputInterlock_LD (BrakeFeedback).

// 🧪 Simulation (GVL_Simulation.SensorMxContactorFeedbackIsReal, passé par l'appelant via
// BypassContactorCheck) — sans contacteurs réels câblés/cohérents en essai, StuckClosed
// se déclenche à tort et bloque RelayFwd/RelayRev (voir Error plus bas).
// 🔧 REX 2026-07-07 : bit2 (ex-RevContactorCheck) libre/inutilisé, fusionné dans bit1.
IF NOT BypassContactorCheck THEN
    IF ContactorsCheck.StuckClosed THEN
        ErrorId := ErrorId OR 16#0002;
    ELSIF ResetEdge.Q THEN
        ErrorId := ErrorId AND 16#FFFD;
    END_IF;
ELSE
    ErrorId := ErrorId AND 16#FFFD;   // Bypass actif : efface/maintient à 0 le bit1
END_IF;

// 🪜 WINCH-CORE-01 : remonte le défaut de configuration interne de FB_SpeedStep.
// Le bit reste mémorisé après correction de la table ; cause disparue + nouveau front Reset
// sont obligatoires avant de rendre le treuil disponible, conformément à Partie 3 §5.
IF SpeedStep.ConfigError THEN
    ErrorId := ErrorId OR 16#0004;    // bit2 = table/plafond/hystérésis invalide
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFB;
END_IF;

END_IF; // fin IF NOT BypassGlobal

Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

IF (NOT StartStop OR EffectiveSafeStop OR DirectionChangePending) AND StepNumber > 0 THEN
    State := E_State.STOPPING;
ELSIF StepNumber > 0 THEN
    State := E_State.BUSY;
ELSE
    State := E_State.READY;
END_IF;

Busy := (State = E_State.BUSY) OR (State = E_State.STOPPING);
Done := FALSE;

IF Error THEN
    RelayFwd := FALSE;
    RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
END_IF;

(* =======================================================================
   📊 FB_Encoder_SpeedMonitor — Détection variation brusque vitesse câble
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Surveillance et détection de variation brusque de vitesse câble
   🔒 Polarité : SpeedVariationConfirmed=TRUE si variation > seuil pendant timeout
   📊 Diagnostic : Brique de surveillance diagnostic sans actionneur direct
   📄 Doc métier : DOC/AF/AF_Partie-09_Fonction_Encoder_v2.1.md
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_Encoder_SpeedMonitor
VAR_INPUT
    // === COMMANDES & AUTORISATIONS ===
    Enable                     : BOOL;        // --> [CMD] Autorisation generale FB (TRUE=Autorise)
    Reset                      : BOOL;        // --> [CMD] Acquittement defaut (front montant)

    // === CONTEXTE & ETAT PUISSANCE ===
    PowerContactorEngaged      : BOOL;        // --> [HW]  Ligne puissance enclenchee
    Mode                       : E_Mode;      // --> [CMD] Mode d'exploitation actif

    // === MESURES & CONSIGNES SURVEILLANCE ===
    SpeedMps                   : REAL;        // --> [HW]  Vitesse lineaire absolue mesuree (m/s)
    SpeedVariationThresholdMps : REAL;        // --> [CFG] Seuil de variation minimale a surveiller (m/s)
    SpeedVariationTimeout      : TIME;        // --> [CFG] Duree minimale de confirmation variation
    SpeedStabilityTimeout      : TIME;        // --> [CFG] Duree sans variation avant vitesse stable
END_VAR
VAR_OUTPUT
    // === ETATS IEC & SYNOPTIQUE ===
    Ready                  : BOOL;        // <-- [STAT] FB pret a fonctionner
    // 🧩 Statut transverse (forme cible) — regroupe Busy/Done/Error/ErrorId/State/StateAtError.
    // ErrorId bit0: "variation vitesse confirmée".
    Status                 : ST_FbStatus;

    // === RESULTATS & MESURES DIAGNOSTIC ===
    SpeedDeltaMps          : REAL;        // <-- [DIAG] Ecart absolu entre deux mesures (m/s)
    SpeedVariationDetected : BOOL;        // <-- [DIAG] Seuil depasse sur le cycle courant
    SpeedVariationConfirmed: BOOL;        // <-- [DIAG] Seuil depasse pendant la duree requise
    SpeedStable            : BOOL;        // <-- [STAT] Vitesse stable pendant SpeedStabilityTimeout
END_VAR
VAR
    // === DETECTEURS DE FRONT ===
    ResetEdge              : R_TRIG;      // . [LOC] Detecteur front montant Reset
    ErrorEdge              : R_TRIG;      // . [LOC] Detecteur front montant Error

    // === TEMPORISATEURS INTERNES ===
    VariationTimer         : TON;         // . [LOC] Temporisateur de confirmation de variation
    StabilityTimer         : TON;         // . [LOC] Temporisateur de confirmation de stabilite

    // === VARIABLES ET MEMOIRES INTERNES ===
    PreviousSpeedMps       : REAL;        // . [LOC] Vitesse mesuree au cycle precedent (m/s)
    HasPreviousSpeed       : BOOL;        // . [LOC] Premiere mesure enregistree
    VariationActive        : BOOL;        // . [LOC] Condition de depassement de seuil active
END_VAR

{region "§1 Gate"}
// 🛑 1. GATE — désactivation ou AU non réarmé : aucune alarme persistante.
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE;
    Status.Busy := FALSE;
    Status.Done := FALSE;
    Status.Error := FALSE;
    Status.ErrorId := 16#0000;
    Status.State := E_State.DISABLED;
    SpeedDeltaMps := 0.0;
    SpeedVariationDetected := FALSE;
    SpeedVariationConfirmed := FALSE;
    SpeedStable := FALSE;
    VariationActive := FALSE;
    HasPreviousSpeed := FALSE;
    VariationTimer(IN := FALSE, PT := SpeedVariationTimeout);
    StabilityTimer(IN := FALSE, PT := SpeedStabilityTimeout);
    RETURN;
END_IF;

Ready := TRUE;
Status.Busy := FALSE;
Status.Done := FALSE;
Status.State := E_State.READY;
{endregion}

{region "§2 Reset front"}
// 🔑 2. RESET FRONT — l'acquittement n'efface le défaut que si la cause a disparu.
ResetEdge(CLK := Reset);
{endregion}

{region "§3 Calcul écart vitesse"}
// 📏 3. CALCUL DE L'ÉCART DE VITESSE — première mesure utilisée comme référence.
IF NOT HasPreviousSpeed THEN
    PreviousSpeedMps := SpeedMps;
    HasPreviousSpeed := TRUE;
    SpeedDeltaMps := 0.0;
ELSE
    SpeedDeltaMps := ABS(SpeedMps - PreviousSpeedMps);
    PreviousSpeedMps := SpeedMps;
END_IF;
{endregion}

{region "§4 Détection et filtre temporel"}
// 🔍 4. DÉTECTION BRUTE + FILTRE TEMPOREL — pas de déclenchement si la durée vaut zéro.
VariationActive := HasPreviousSpeed
                   AND (SpeedVariationThresholdMps >= 0.0)
                   AND (SpeedVariationTimeout > T#0ms)
                   AND (SpeedDeltaMps > SpeedVariationThresholdMps);
SpeedVariationDetected := VariationActive;

VariationTimer(IN := VariationActive, PT := SpeedVariationTimeout);
SpeedVariationConfirmed := VariationTimer.Q;
StabilityTimer(IN := HasPreviousSpeed AND NOT VariationActive AND (SpeedStabilityTimeout > T#0ms), PT := SpeedStabilityTimeout);
SpeedStable := StabilityTimer.Q;

IF SpeedVariationConfirmed THEN
    Status.ErrorId := Status.ErrorId OR 16#0001;
ELSIF ResetEdge.Q AND NOT VariationActive THEN
    Status.ErrorId := Status.ErrorId AND 16#FFFE;
END_IF;
{endregion}

{region "§5 Sorties état"}
// 📤 5. SORTIES D'ÉTAT — diagnostic standard, aucune commande mouvement.
Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;
{endregion}

(* =======================================================================
   ⚖️ FB_Winch_Symmetry — Mesure passive M1/M2
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Observateur de symétrie et de synchronisme des treuils M1/M2
   📄 Doc métier : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md
   🔒 Observateur pur : Aucune ecriture de commande, securite ou mouvement
   ======================================================================= *)

FUNCTION_BLOCK FB_Winch_Symmetry
VAR_INPUT
    // === COMMANDES ET CONSIGNES ===
    Reset                           : BOOL;                           // --> [CMD] Reinitialisation des mesures sur front
    M1CommandActive                 : BOOL;                           // --> [CMD] Commande active sur treuil M1
    M2CommandActive                 : BOOL;                           // --> [CMD] Commande active sur treuil M2
    M1Direction                     : INT;                            // --> [CMD] Sens commande M1 (-1/0/+1)
    M2Direction                     : INT;                            // --> [CMD] Sens commande M2 (-1/0/+1)

    // === FEEDBACKS HARWARE ET FREINS ===
    M1BrakeCmd                      : BOOL;                           // --> [HW] Ordre ouverture frein M1
    M2BrakeCmd                      : BOOL;                           // --> [HW] Ordre ouverture frein M2
    M1BrakeApplied                  : BOOL;                           // --> [HW] Etat frein M1 serre
    M2BrakeApplied                  : BOOL;                           // --> [HW] Etat frein M2 serre

    // === MESURES POSITIONS ET VITESSES ===
    M1Position_M                    : REAL;                           // --> [HW] Position mesuree M1 (m)
    M2Position_M                    : REAL;                           // --> [HW] Position mesuree M2 (m)
    M1Speed_Mps                     : REAL;                           // --> [HW] Vitesse mesuree M1 (m/s)
    M2Speed_Mps                     : REAL;                           // --> [HW] Vitesse mesuree M2 (m/s)
    SyncDeviation_M                 : REAL;                           // --> [HW] Ecart instantane synchro (m)

    // === CONFIGURATION ===
    Config                          : ST_Winch_SymmetryCfg;           // --> [CFG] Configuration des seuils de symetrie
END_VAR
VAR_OUTPUT
    // === ETATS IEC ET SYNOPTIQUE ===
    SymmetryOk                      : BOOL;                           // <-- [STAT] Symetrie globale conforme aux criteres
    SymmetryValid                   : BOOL;                           // <-- [STAT] Mesure de symetrie valide et calculee
END_VAR
VAR_IN_OUT
    // === STRUCTURES DE DONNÉES PARTAGÉES ===
    Data                            : ST_Winch_SymmetryData;          // <-> [BUS] Donnees de mesures de symetrie
END_VAR
VAR
    // === SOUS-INSTANCES FB ===
    ResetEdge                       : R_TRIG;                         // * [INST] Detecteur front reinitialisation
    CycleTime                       : FB_CycleTime;                   // * [INST] Calcul du temps de cycle

    // === TIMERS INTERNES ===
    CommandTon                      : TON;                            // . [LOC] Tempo qualification commande stable
    MotionTimer                     : TON;                            // . [LOC] Chronometre de mouvement
    StopTimer                       : TON;                            // . [LOC] Chronometre d'arret

    // === VARIABLES LOCALES CALCULÉES ===
    Comparable                      : BOOL;                           // . [LOC] Conditions de comparaison remplies
    Qualified                       : BOOL;                           // . [LOC] Phase de mesure qualifiee
    PreviousQualified               : BOOL;                           // . [LOC] Etat qualifie cycle precedent
    Stopping                        : BOOL;                           // . [LOC] Phase d'arret en cours
    StartCapturedM1                 : BOOL;                           // . [LOC] Top depart capture M1
    StartCapturedM2                 : BOOL;                           // . [LOC] Top depart capture M2
    StopCapturedM1                  : BOOL;                           // . [LOC] Top arret capture M1
    StopCapturedM2                  : BOOL;                           // . [LOC] Top arret capture M2
    StartMsM1                       : UDINT;                          // . [LOC] Horodatage d'ouverture M1 (ms)
    StartMsM2                       : UDINT;                          // . [LOC] Horodatage d'ouverture M2 (ms)
    ReleaseMsM1                     : UDINT;                          // . [LOC] Temps de desserrage frein M1 (ms)
    ReleaseMsM2                     : UDINT;                          // . [LOC] Temps de desserrage frein M2 (ms)
    ApplyMsM1                       : UDINT;                          // . [LOC] Temps de serrage frein M1 (ms)
    ApplyMsM2                       : UDINT;                          // . [LOC] Temps de serrage frein M2 (ms)
    StopMsM1                        : UDINT;                          // . [LOC] Horodatage d'arret M1 (ms)
    StopMsM2                        : UDINT;                          // . [LOC] Horodatage d'arret M2 (ms)
    StopStartM1_M                   : REAL;                           // . [LOC] Position debut d'arret M1 (m)
    StopStartM2_M                   : REAL;                           // . [LOC] Position debut d'arret M2 (m)
END_VAR

{region "§1 Reset et qualification"}
CycleTime(DefaultValueS := 0.010); ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN Data.DeltaStartDelay_Ms:=0; Data.DeltaBrakeReleaseTime_Ms:=0; Data.DeltaBrakeApplyTime_Ms:=0; Data.DeltaStopDistance_Mm:=0; Data.DeltaStopTime_Ms:=0; Data.MaxSyncDeviation_M:=0.0; END_IF;
Comparable := M1CommandActive AND M2CommandActive AND (M1Direction = M2Direction) AND (M1Direction <> 0);
CommandTon(IN := Comparable, PT := UDINT_TO_TIME(Config.MinimumCommandTime_Ms));
Qualified := CommandTon.Q AND (M1Speed_Mps >= Config.MinimumSpeed_Mps) AND (M2Speed_Mps >= Config.MinimumSpeed_Mps);
MotionTimer(IN := Comparable, PT := T#1h);
StopTimer(IN := Stopping, PT := T#1h);
IF NOT Comparable THEN StartCapturedM1:=FALSE; StartCapturedM2:=FALSE; ReleaseMsM1:=0; ReleaseMsM2:=0; ApplyMsM1:=0; ApplyMsM2:=0; END_IF;
IF Comparable AND (M1Speed_Mps >= Config.MinimumSpeed_Mps) AND NOT StartCapturedM1 THEN StartMsM1:=TIME_TO_UDINT(MotionTimer.ET); StartCapturedM1:=TRUE; END_IF;
IF Comparable AND (M2Speed_Mps >= Config.MinimumSpeed_Mps) AND NOT StartCapturedM2 THEN StartMsM2:=TIME_TO_UDINT(MotionTimer.ET); StartCapturedM2:=TRUE; END_IF;
{endregion}

{region "§2 Mesure symétrie"}
IF Qualified THEN
    IF M1BrakeCmd AND M1BrakeApplied THEN ReleaseMsM1 := ReleaseMsM1 + REAL_TO_UDINT(CycleTime.CycleTimeS * 1000.0); END_IF;
    IF M2BrakeCmd AND M2BrakeApplied THEN ReleaseMsM2 := ReleaseMsM2 + REAL_TO_UDINT(CycleTime.CycleTimeS * 1000.0); END_IF;
    IF NOT M1BrakeCmd AND NOT M1BrakeApplied THEN ApplyMsM1 := ApplyMsM1 + REAL_TO_UDINT(CycleTime.CycleTimeS * 1000.0); END_IF;
    IF NOT M2BrakeCmd AND NOT M2BrakeApplied THEN ApplyMsM2 := ApplyMsM2 + REAL_TO_UDINT(CycleTime.CycleTimeS * 1000.0); END_IF;
    IF SyncDeviation_M > Data.MaxSyncDeviation_M THEN Data.MaxSyncDeviation_M := SyncDeviation_M; END_IF;
END_IF;
IF PreviousQualified AND NOT Comparable THEN Stopping:=TRUE; StopCapturedM1:=FALSE; StopCapturedM2:=FALSE; StopStartM1_M:=M1Position_M; StopStartM2_M:=M2Position_M; END_IF;
IF Stopping THEN
    IF (M1Speed_Mps < Config.MinimumSpeed_Mps) AND NOT StopCapturedM1 THEN StopMsM1:=TIME_TO_UDINT(StopTimer.ET); StopCapturedM1:=TRUE; END_IF;
    IF (M2Speed_Mps < Config.MinimumSpeed_Mps) AND NOT StopCapturedM2 THEN StopMsM2:=TIME_TO_UDINT(StopTimer.ET); StopCapturedM2:=TRUE; END_IF;
    IF StopCapturedM1 AND StopCapturedM2 THEN
        Data.DeltaStartDelay_Ms := ABS(UDINT_TO_DINT(StartMsM1)-UDINT_TO_DINT(StartMsM2));
        Data.DeltaBrakeReleaseTime_Ms := ABS(UDINT_TO_DINT(ReleaseMsM1)-UDINT_TO_DINT(ReleaseMsM2));
        Data.DeltaBrakeApplyTime_Ms := ABS(UDINT_TO_DINT(ApplyMsM1)-UDINT_TO_DINT(ApplyMsM2));
        Data.DeltaStopDistance_Mm := REAL_TO_UDINT(ABS(ABS(M1Position_M-StopStartM1_M)-ABS(M2Position_M-StopStartM2_M))*1000.0);
        Data.DeltaStopTime_Ms := ABS(UDINT_TO_DINT(StopMsM1)-UDINT_TO_DINT(StopMsM2)); Stopping:=FALSE; SymmetryValid:=TRUE;
    END_IF;
END_IF;
{endregion}

{region "§3 Sortie"}
SymmetryOk := SymmetryValid AND (Data.DeltaStartDelay_Ms<=Config.DeltaStartDelay_Ms) AND (Data.DeltaBrakeReleaseTime_Ms<=Config.DeltaBrakeReleaseTime_Ms) AND (Data.DeltaBrakeApplyTime_Ms<=Config.DeltaBrakeApplyTime_Ms) AND (Data.DeltaStopDistance_Mm<=Config.DeltaStopDistance_Mm) AND (Data.DeltaStopTime_Ms<=Config.DeltaStopTime_Ms);
PreviousQualified := Qualified;
{endregion}

SETUP
VAR
    fb : FB_JOYSTICK;
    nx : INT := 5000;
    ny : INT := 5000;
    diagOk : ST_DIAG_DEVICE;
    diagDown : ST_DIAG_DEVICE;
END_VAR
END_SETUP

TEST 'Bus non operationnel neutralise les sorties sans lever Error'
    diagDown.ONLINE := FALSE; diagDown.OPERATIONAL := FALSE; diagDown.ERROR := FALSE;
    diagDown.ERRORID := 0; diagDown.STATE := E_DIAG_STATE.INIT; diagDown.STATEATERROR := E_DIAG_STATE.DISABLED;
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;

    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagDown, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);

    ASSERT_FALSE(fb.READY, 'bus CAN non operationnel doit bloquer Ready');
    ASSERT_FALSE(fb.ERROR, 'un bus down est un GATE de securite, PAS une Error diagnostiquee (pas de bit ErrorId leve ici)');
    ASSERT_FALSE(fb.AXISCMDX.ENABLE, 'sorties axe neutralisees si non operationnel');
END_TEST

TEST 'Reset acquitte une erreur de calibration seulement si la cause a disparu'
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;

    (* RawX/RawY hors zone neutre valide (2000..8000) + front BtnCalibrate *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 9500, RAWY := 9500, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);

    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 9500, RAWY := 9500, RAWBUTTON := FALSE, BTNCALIBRATE := TRUE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);

    ASSERT_TRUE(fb.ERROR, 'calibration hors zone doit lever Error');

    (* Reset alors que la cause est toujours presente (axes toujours hors zone) : ne doit PAS acquitter *)
    fb(ENABLE := TRUE, RESET := TRUE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 9500, RAWY := 9500, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);

    ASSERT_TRUE(fb.ERROR, 'Reset ne doit PAS acquitter tant que les axes restent hors zone (cause toujours presente)');

    (* Reset retombe (front consomme) ; axes reviennent en zone ; nouveau front Reset : doit acquitter *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);

    fb(ENABLE := TRUE, RESET := TRUE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);

    ASSERT_FALSE(fb.ERROR, 'front Reset avec axes revenus en zone valide doit acquitter (cause disparue + appui conscient)');
END_TEST

(* ═══════════════════════════════════════════════════════════════
   🧪 FB_Sim_Encoder — Simulation physique d'un codeur absolu de treuil
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-13_Fonction_Simulation_v2.1.md
   🧩 Brique réduite (Partie3 §1bis, "briques E/S & diagnostics") : pas de contrat
      Enable/Reset/Error complet, pas de StartStop/SafeStop — outil de banc, pas
      du métier machine.
   🎯 Rôle : fait "compter" un codeur absolu comme si le treuil tournait
      réellement, à partir des relais de sens commandés et de la vitesse rampée
      courante. Extraction PURE de la logique déjà en place dans
      `PRG_02_Encoders.st` (bloc "SIMULATION SUR BANC DE TEST") — aucun
      changement de comportement, juste la dissociation en FB dédié.
   📥 Enable      : simulation active (SimulationModeActive AND NOT BusEncoderMxIsReal)
   📥 RelayFwd/RelayRev : sens commandé (contacteurs de sens du treuil)
   📥 SpeedRefPct : vitesse rampée courante (magnitude, %) — ex. instWinchM1.SpeedRamp.Current
   📥 PresetCmd   : TRUE le cycle où un preset (homing) doit être appliqué (PresettTrigCmd = 2)
   📥 PresetValue : valeur brute à charger lors du preset
   📥 SpeedScaleFactor : 🔧 REX 2026-07-07 — multiplicateur de vitesse simulation (confort de test
      banc uniquement, sans rapport avec une calibration réelle). Défaut 1.0 = comportement
      d'origine. Câblé sur GVL_Simulation.TstEncoderSpeedFactor (réglable à chaud, sans recompiler).
   📤 RawPosOut   : position brute simulée (UDINT), à aiguiller à la place de la valeur
      EtherCAT réelle quand le device n'est pas Operational (voir PRG_02_Encoders.st)
   🔧 REX 2026-07-08 : `RawPos` déplacé en `VAR_IN_OUT`, référencé depuis `GVL_PERSISTENT`
      (même pattern que `Calib` dans `FB_Encoder_Homing`) — `PERSISTENT` n'est valide que sur du
      `VAR_GLOBAL` en CODESYS, pas sur une variable locale de FB (tenté en `VAR RETAIN` puis
      `VAR PERSISTENT RETAIN` locaux, aucun des deux ne convient). Un vrai codeur absolu physique
      conserve son comptage brut même à travers un reset FROID (indépendant de l'automate) —
      il fallait donc bien du PERSISTENT RETAIN réel, regroupé avec le reste dans GVL_PERSISTENT.
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Sim_Encoder) ===

FUNCTION_BLOCK PUBLIC FB_Sim_Encoder
VAR_INPUT
    Enable           : BOOL;
    RelayFwd         : BOOL;
    RelayRev         : BOOL;
    SpeedRefPct      : REAL;
    PresetCmd        : BOOL;
    PresetValue      : UDINT;
    SpeedScaleFactor : REAL := 1.0;   // 🔧 REX 2026-07-07 — confort de test, voir bandeau ci-dessus
    TestOffsetCmd    : BOOL;          // 🆕 REX 2026-07-08 (4) — front montant = applique TestOffsetPts (test banc)
    TestOffsetPts    : DINT := 0;     // 🆕 REX 2026-07-08 (4) — décalage signé à appliquer (points bruts)
END_VAR
VAR_OUTPUT
    RawPosOut   : UDINT;
END_VAR
VAR_IN_OUT
    RawPos      : UDINT;   // 🔧 REX 2026-07-08 : référence _SimEncoderRawPosM1/M2 (survit au reset froid)
END_VAR
VAR
    Increment      : UDINT;              // 🔧 REX 2026-07-07 — évite de dupliquer le calcul 2x
    TestOffsetEdge : R_TRIG;             // 🆕 REX 2026-07-08 (4)
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Encoder) ===

IF NOT Enable THEN
    RawPosOut := RawPos;
    RETURN;
END_IF;

// 🆕 REX 2026-07-08 (4) — injection test banc : VRAI saut de position (comme un glissement réel),
// pour tester Concept 1 / Méca E ET le rattrapage joystick (voir GVL_Simulation bandeau).
TestOffsetEdge(CLK := TestOffsetCmd);
IF TestOffsetEdge.Q THEN
    RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) + TestOffsetPts);
END_IF;

Increment := REAL_TO_UDINT(SpeedRefPct * 0.1 * SpeedScaleFactor);

IF PresetCmd THEN
    RawPos := PresetValue;
ELSIF RelayFwd THEN
    RawPos := RawPos + Increment;
ELSIF RelayRev THEN
    IF RawPos >= Increment THEN
        RawPos := RawPos - Increment;
    ELSE
        RawPos := 0;
    END_IF;
END_IF;

RawPosOut := RawPos;

(* ═══════════════════════════════════════════════════════════════
   🪝 FB_TreuilsBenneStagingProjection — Publication staging M3
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : publier explicitement les résultats safety M1/M2 déjà
      calculés par le POU legacy, sans produire de commande ni sortie.

   🔒 Staging uniquement : ce FB est appelé par PRG_04_Treuils_Benne_CFC,
      qui n'est pas inscrit dans MainTask. Il ne remplace pas FB_Safety_Winch
      et ne crée donc aucun second écrivain actif de SafeStop/PowerCutOff.

   📄 Réfs : RU_C4_ARCHITECTURE_PROCEDES, registre A-11.
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK FB_TreuilsBenneStagingProjection
VAR_INPUT
    LegacyM1SafeStop     : BOOL;
    LegacyM1PowerCutOff  : BOOL;
    LegacyM2SafeStop     : BOOL;
    LegacyM2PowerCutOff  : BOOL;
END_VAR
VAR_OUTPUT
    M1SafeStop           : BOOL;
    M1PowerCutOff        : BOOL;
    M2SafeStop           : BOOL;
    M2PowerCutOff        : BOOL;
END_VAR

(* Copie volontairement exacte des observations legacy : aucun arbitrage ici. *)
M1SafeStop := LegacyM1SafeStop;
M1PowerCutOff := LegacyM1PowerCutOff;
M2SafeStop := LegacyM2SafeStop;
M2PowerCutOff := LegacyM2PowerCutOff;

