(* ═══════════════════════════════════════════════════════════════
   🛡️ FB_Safety_EmergencyManagement — Bloc Safety Composite (Parent)
   ───────────────────────────────────────────────────────────────
   📄 Rôle : Bloc de sécurité principal de la boucle d'arrêt d'urgence.
   🧩 Encapsule la Logique (FB_Safety_EmergencyManagementLogic) et le 
      Pilote Physique (FB_Safety_EmergencyManagementOutput) par composition.
   ═══════════════════════════════════════════════════════════════
    📄 Docs : DOC/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md ; DOC/AF_Partie-03_Contrats_Composants_v2.0.md
*)

FUNCTION_BLOCK PUBLIC FB_Safety_EmergencyManagement
VAR_INPUT
    Enable              : BOOL;        // Active la surveillance
    Reset               : BOOL;        // Front acquittement défauts
    ArmRequest          : BOOL;        // Demande de réarmement (BtnEmergencyArming)
    EmergencyChainClosed      : BOOL;        // Retour physique boucle d'urgence amont contacteur
    PowerContactorEngaged     : BOOL;        // Confirmation contacteur de puissance principal
    PowerCutOffRequest  : BOOL;        // Requête de coupure logique issue des métiers
    BtnEmergencyCutOff  : BOOL;        // Commande d'ouverture d'urgence depuis l'IHM
END_VAR
VAR_OUTPUT
    Ready               : BOOL;
    Busy                : BOOL;
    Done                : BOOL;
    Error               : BOOL;
    ErrorId             : WORD;        // bit0: RedundancyTestFailed, bit1: EmergencyArmingFailed
    
    PowerCutOff_A_RQ    : BOOL;        // Sortie de pilotage canal A (maintenu à TRUE, fail-safe)
    PowerCutOff_B_RQ    : BOOL;        // Sortie de pilotage canal B (maintenu à TRUE, fail-safe)
    EmergencyArming_RQ  : BOOL;        // Impulsion réarmement physique (1s)
    
    ArmingSeqStep       : INT;         // Étape de diagnostic : 0=IDLE, 1=TestA, 2=RestoreA, 3=TestB, 4=RestoreB, 5=Pulse, 6=Confirm
    RedundancyTestFailed: BOOL;        // Canal A ou B resté collé/shunté détecté à l'auto-test
    EmergencyArmingFailed: BOOL;       // Contacteur de puissance n'a pas confirmé l'armement
    EmergencyArmingLockoutActive : BOOL; // Verrouillage temporel de 5s entre les essais
END_VAR
VAR
    // 🧱 Composition interne des sous-blocs
    Logic               : FB_Safety_EmergencyManagementLogic;
    Output              : FB_Safety_EmergencyManagementOutput;
END_VAR

// === IMPLEMENTATION ===

// 🛑 1. Appels des instances internes
Logic(
    Enable := Enable,
    Reset := Reset,
    ArmRequest := ArmRequest,
    EmergencyChainClosed := EmergencyChainClosed,
    PowerContactorEngaged := PowerContactorEngaged,
    PowerCutOffRequest := PowerCutOffRequest,
    BtnEmergencyCutOff := BtnEmergencyCutOff
);

Output(
    Enable := Enable,
    Cmd := Logic.Cmd
);

// 📤 2. Propagation des signaux vers les sorties du bloc parent
Ready := Enable;
Busy  := (Logic.ArmingSeqStep <> 0);
Done  := PowerContactorEngaged;
Error := Logic.Error;
ErrorId := Logic.ErrorId;

PowerCutOff_A_RQ   := Output.PowerCutOff_A_RQ;
PowerCutOff_B_RQ   := Output.PowerCutOff_B_RQ;
EmergencyArming_RQ := Output.EmergencyArming_RQ;

ArmingSeqStep                := Logic.ArmingSeqStep;
RedundancyTestFailed         := Logic.RedundancyTestFailed;
EmergencyArmingFailed        := Logic.EmergencyArmingFailed;
EmergencyArmingLockoutActive := Logic.EmergencyArmingLockoutActive;

(* ═══════════════════════════════════════════════════════════════
   🔄 FB_Cycle — Séquenceur du Cycle Automatique (Grafcet de dragage)
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF_Partie-04_Mode_SemiAuto_Sequenceur_v2.0.md
   🔌 Conforme au contrat FB standard (Partie3 §1bis).
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK FB_Cycle
VAR_INPUT
    Enable                  : BOOL;         // Activation générale du séquenceur
    Reset                   : BOOL;         // Acquittement défaut (front)
    PowerContactorEngaged   : BOOL;         // Chaîne de sécurité OK
    CycleMotionPermit       : BOOL;         // Homme-mort + joystick actif
    HeartbeatIhmOk          : BOOL;         // 💓 IHM↔PLC valide ; FALSE = repli cycle obligatoire

    // Commandes opérateur
    StartCycle              : BOOL;         // Demande lancement / reprise cycle (IHM)
    PauseCycle              : BOOL;         // Demande pause temporaire (IHM)
    AbortCycle              : BOOL;         // Demande abandon cycle (IHM)

    // Cibles et paramètres
    SetDepthM               : REAL;         // Profondeur de consigne (négative)
    SetOffsetM              : REAL;         // Écart de fermeture benne cible
    SelectedTargetNum_IHM   : INT;          // Cible sélectionnée (2=P2, 3=P1)

    // Feedbacks physique & matériel
    KoboldContactFond       : BOOL;         // Retour dédié Kobold : TRUE = contact fond détecté
    LimitLegalReached       : BOOL;         // Limite légale atteinte (descente interdite)
    LimitLegalDepthM        : REAL;         // Profondeur légale minimale autorisée
    WinchSyncError          : BOOL;         // Désynchronisme bloquant M1/M2
    WinchSyncDeltaM         : REAL;         // Écart codeurs M1/M2 pour diagnostic
    M1_CablePosM            : REAL;         // Position câble treuil M1 (recalée)
    M2_CablePosM            : REAL;         // Position câble treuil M2 (recalée)
    M1_MeasuredSpeedMps     : REAL;         // Vitesse linéaire mesurée M1 (m/s)
    M2_MeasuredSpeedMps     : REAL;         // Vitesse linéaire mesurée M2 (m/s)
    SpeedMismatchThresholdMps : REAL;       // Seuil écart vitesse ; 0 = contrôle désactivé
    SpeedMismatchTimeout    : TIME;         // Durée de confirmation ; 0 = contrôle désactivé
    CableLimitM1AscentM     : REAL;         // Limite haute d'exploitation M1 ; seuil de fin ASCENDING_LOADED

    // Feedbacks Translation M3
    Translation_At_P1           : BOOL;     // Capteur position P1 (ex-Fosse1)
    Translation_At_P2           : BOOL;     // Capteur position P2 (ex-Fosse2)
    Translation_At_Maintenance  : BOOL;     // Capteur fin de course maintenance
    Translation_At_Tremie       : BOOL;     // Capteur fin de course trémie
    Translation_Busy            : BOOL;     // Mouvement translation en cours
    Translation_Done            : BOOL;     // Cible translation atteinte

    // Feedbacks Benne
    Benne_Busy              : BOOL;         // Mouvement mâchoires benne en cours
    Benne_Done              : BOOL;         // Mouvement ouverture/fermeture terminé
    Benne_IsOpen            : BOOL;         // Benne mécaniquement ouvert mémorisé
    Benne_IsClosed          : BOOL;         // Benne mécaniquement fermé mémorisé
END_VAR
VAR_OUTPUT
    Ready                   : BOOL;         // Séquenceur disponible
    Busy                    : BOOL;         // Cycle automatique actif
    Done                    : BOOL;         // Cycle automatique complété
    Error                   : BOOL;         // Défaut cycle
    ErrorId                 : WORD;         // bit0: Timeout/limite, bit1: désynchronisme, bit2: cible invalide, bit3: stabilisation impossible, bit4: écart vitesse, bit5: perte heartbeat
    SpeedMismatchMps        : REAL;         // Écart absolu vitesse M1/M2 (m/s)
    SpeedMismatchActive     : BOOL;         // Seuil vitesse dépassé sur le cycle courant
    SpeedMismatchConfirmed  : BOOL;         // Écart vitesse confirmé pendant SpeedMismatchTimeout

    // Commandes structurées (demandes de mouvement)
    WinchM1Cmd              : ST_WinchCmdDemand;        // Demande treuil M1
    WinchM2Cmd              : ST_WinchCmdDemand;        // Demande treuil M2
    TranslationCmd          : ST_TranslationCmdDemand;  // Demande translation M3
    BucketCmd               : ST_BucketCmdDemand;       // Demande benne

    // Métadonnées d'affichage IHM
    CycleStep               : E_CycleStep;  // Étape active du Grafcet
    CycleStateStr           : STRING(80);   // Libellé en clair de l'étape
END_VAR
VAR
    ResetEdge               : R_TRIG;
    StartEdge               : R_TRIG;
    PauseEdge               : R_TRIG;
    AbortEdge               : R_TRIG;

    // Séquencement
    State                   : E_CycleStep := E_CycleStep.INIT;
    SavedState              : E_CycleStep := E_CycleStep.INIT;
    IsPaused                : BOOL := FALSE;

    // Mémorisations et Timers
    TouchPositionM          : REAL;         // Position M1 mémorisée lors du contact fond
    RaiseTargetM            : REAL;         // Profondeur de remontée mémorisée
    DrainingTimer           : TON;          // Temporisateur de vidage (égouttage)
    StabilizationTimer      : TON;          // Temporisation maximale de remontée lente après fermeture
    SpeedMismatchTimer      : TON;          // Confirmation temporelle écart de vitesse M1/M2
    SelectedWorkTarget      : INT;          // Cible de travail mémorisée (2=P2 ou 3=P1)

    // Paramètres internes
    CtrlAscentDistM         : REAL := 2.0;      // Distance de remontée lente de contrôle
    CtrlAscentToleranceM    : REAL := 0.25;     // Écart maximal admis entre les deux codeurs
    CtrlAscentTimeout       : TIME := T#30s;    // Temps maximal pour atteindre la zone de stabilisation
    DrainingTime            : TIME := T#5s;     // Temps d'égouttage par défaut
END_VAR

// === IMPLEMENTATION ===

// 🛑 1. GATES DE SÉCURITÉ ET BLOCAGE
IF NOT Enable OR NOT PowerContactorEngaged THEN
    WinchM1Cmd.StartStop   := FALSE;
    WinchM1Cmd.Direction   := 0;
    WinchM1Cmd.SpeedPct    := 0.0;

    WinchM2Cmd.StartStop   := FALSE;
    WinchM2Cmd.Direction   := 0;
    WinchM2Cmd.SpeedPct    := 0.0;

    TranslationCmd.Start   := FALSE;
    TranslationCmd.Target  := 0;

    BucketCmd.Open         := FALSE;
    BucketCmd.Close        := FALSE;
    BucketCmd.KoboldContactorCmd := FALSE;

    State                := E_CycleStep.INIT;
    CycleStep            := E_CycleStep.INIT;
    CycleStateStr        := 'ARRÊT : SÉCURITÉ ABSENTE OU AUTO DÉSACTIVÉ';
    Ready                := FALSE;
    Busy                 := FALSE;
    Done                 := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
ResetEdge(CLK := Reset);
StartEdge(CLK := StartCycle);
PauseEdge(CLK := PauseCycle);
AbortEdge(CLK := AbortCycle);

// ⏱️ T36 — surveillance indépendante de la remontée lente : un codeur bloqué
// ne doit jamais laisser le cycle attendre indéfiniment.
StabilizationTimer(IN := (State = E_CycleStep.CTRL_ASCENDING), PT := CtrlAscentTimeout);

// 📏 T43 — comparaison vitesse réelle M1/M2.
SpeedMismatchMps := ABS(M1_MeasuredSpeedMps - M2_MeasuredSpeedMps);
SpeedMismatchActive := (State = E_CycleStep.CTRL_ASCENDING)
                       AND CycleMotionPermit
                       AND (SpeedMismatchThresholdMps > 0.0)
                       AND (SpeedMismatchTimeout > T#0ms)
                       AND (SpeedMismatchMps > SpeedMismatchThresholdMps);
SpeedMismatchTimer(IN := SpeedMismatchActive, PT := SpeedMismatchTimeout);
SpeedMismatchConfirmed := SpeedMismatchTimer.Q;

IF ResetEdge.Q THEN
    Error := FALSE;
    ErrorId := 16#0000;
    IsPaused := FALSE;
    SavedState := E_CycleStep.INIT;
    IF State = E_CycleStep.ERROR_HOLD THEN
        State := E_CycleStep.INIT;
    END_IF;
END_IF;

// 💓 Perte IHM : repli mémorisé. La reconnexion seule ne relance jamais le cycle.
IF NOT HeartbeatIhmOk AND State <> E_CycleStep.ERROR_HOLD THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0020;
    State := E_CycleStep.ERROR_HOLD;
END_IF;

// Défaut de synchronisme : arrêt sûr et acquittement obligatoire.
IF WinchSyncError AND State <> E_CycleStep.ERROR_HOLD THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0002;
    State := E_CycleStep.ERROR_HOLD;
END_IF;

// 🛡️ T43 — écart de vitesse confirmé : arrêt du cycle et ERROR_HOLD.
IF SpeedMismatchConfirmed AND State <> E_CycleStep.ERROR_HOLD THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0010;
    State := E_CycleStep.ERROR_HOLD;
END_IF;

// Gestion de la Pause
IF PauseEdge.Q AND Busy AND NOT IsPaused THEN
    IsPaused := TRUE;
    SavedState := State;
    State := E_CycleStep.ERROR_HOLD; // Fige les mouvements
ELSIF StartEdge.Q AND IsPaused THEN
    IsPaused := FALSE;
    State := SavedState; // Reprise à l'étape sauvegardée
END_IF;

// Gestion de l'Abandon
IF AbortEdge.Q THEN
    IsPaused := FALSE;
    State := E_CycleStep.INIT;
END_IF;

// 🔁 2. LOGIQUE DU SÉQUENCEUR (Machine d'état)
CASE State OF

    E_CycleStep.INIT:
        CycleStep := E_CycleStep.INIT;
        CycleStateStr := 'VÉRIFICATION COHÉRENCE SYSTÈME';

        WinchM1Cmd.StartStop := FALSE;
        WinchM1Cmd.Direction := 0;
        WinchM1Cmd.SpeedPct  := 0.0;

        WinchM2Cmd.StartStop := FALSE;
        WinchM2Cmd.Direction := 0;
        WinchM2Cmd.SpeedPct  := 0.0;

        TranslationCmd.Start := FALSE;
        TranslationCmd.Target := 0;

        BucketCmd.Open  := FALSE;
        BucketCmd.Close := FALSE;
        BucketCmd.KoboldContactorCmd := FALSE;

        Busy  := FALSE;
        Done  := FALSE;

        // Transition si système sain et réarmé (front reset ou démarrage)
        IF StartEdge.Q THEN
            State := E_CycleStep.WORK_POS_SELECT;
        END_IF;

    E_CycleStep.WORK_POS_SELECT:
        CycleStep := E_CycleStep.WORK_POS_SELECT;
        CycleStateStr := 'SÉLECTION POSITION TRAVAIL (FOSSE 1 / 2)';
        Busy := TRUE;

        // Choix cible — P2/P1 (cibles 2/3)
        IF (SelectedTargetNum_IHM <> 2) AND (SelectedTargetNum_IHM <> 3) THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0004;
            State := E_CycleStep.ERROR_HOLD;
        ELSIF SelectedTargetNum_IHM = 2 OR SelectedTargetNum_IHM = 3 THEN
            SelectedWorkTarget := SelectedTargetNum_IHM;
            TranslationCmd.Target := SelectedWorkTarget;
            TranslationCmd.Start := CycleMotionPermit;

            // Attente positionnement translation
            IF CycleMotionPermit AND ((SelectedWorkTarget = 2 AND Translation_At_P2)
               OR (SelectedWorkTarget = 3 AND Translation_At_P1)) THEN
                TranslationCmd.Start := FALSE;
                State := E_CycleStep.DESCENDING_OPEN;
            END_IF;
        END_IF;

    E_CycleStep.DESCENDING_OPEN:
        CycleStep := E_CycleStep.DESCENDING_OPEN;
        CycleStateStr := 'PLONGÉE BENNE OUVERT';

        // M1 et M2 descendent ensemble (synchro gérée en aval)
        WinchM1Cmd.StartStop := TRUE;
        WinchM1Cmd.Direction := -1;
        WinchM1Cmd.SpeedPct  := 50.0;

        WinchM2Cmd.StartStop := TRUE;
        WinchM2Cmd.Direction := -1;
        WinchM2Cmd.SpeedPct  := 50.0;

        BucketCmd.KoboldContactorCmd := TRUE;

        // Transition uniquement sur le retour dédié Kobold.
        IF CycleMotionPermit AND KoboldContactFond THEN
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            BucketCmd.KoboldContactorCmd := FALSE;
            TouchPositionM := M1_CablePosM;
            IF LimitLegalDepthM < -0.01 THEN
                RaiseTargetM := MAX(TouchPositionM + 0.5, LimitLegalDepthM + 0.5);
            ELSE
                RaiseTargetM := TouchPositionM + 0.5;
            END_IF;
            State := E_CycleStep.BOTTOM_TOUCH_WAIT;
        ELSIF LimitLegalReached THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0001;
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            BucketCmd.KoboldContactorCmd := FALSE;
            State := E_CycleStep.ERROR_HOLD;
        END_IF;

    E_CycleStep.BOTTOM_TOUCH_WAIT:
        CycleStep := E_CycleStep.BOTTOM_TOUCH_WAIT;
        CycleStateStr := 'REMONTÉE SÉCURISÉE APRÈS CONTACT FOND';

        WinchM1Cmd.StartStop := TRUE;
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct := 20.0;

        WinchM2Cmd.StartStop := TRUE;
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct := 20.0;

        // Les deux treuils restent synchronisés jusqu'au-dessus de la limite légale.
        IF CycleMotionPermit AND (M1_CablePosM >= RaiseTargetM) AND (M2_CablePosM >= RaiseTargetM) THEN
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            State := E_CycleStep.SYNCHRO_ADJUST;
        END_IF;

    E_CycleStep.SYNCHRO_ADJUST:
        CycleStep := E_CycleStep.SYNCHRO_ADJUST;
        CycleStateStr := 'FERMETURE DU GODET / EXCAVATION';

        WinchM1Cmd.StartStop := FALSE;

        // Déclenchement fermeture benne
        BucketCmd.Close := TRUE;

        // Transition si benne fermé avec succès
        IF CycleMotionPermit AND Benne_Done AND Benne_IsClosed THEN
            BucketCmd.Close := FALSE;
            State := E_CycleStep.CTRL_ASCENDING;
        END_IF;

    E_CycleStep.CTRL_ASCENDING:
        CycleStep := E_CycleStep.CTRL_ASCENDING;
        CycleStateStr := 'REMONTÉE LENTE DE CONTRÔLE';

        // M1 et M2 montent lentement en synchro
        WinchM1Cmd.StartStop := TRUE;
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct  := 20.0;

        WinchM2Cmd.StartStop := TRUE;
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct  := 20.0;

        // Contrôle des deux codeurs
        IF WinchSyncError OR (ABS(M1_CablePosM - M2_CablePosM) > CtrlAscentToleranceM) THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0008;
            State := E_CycleStep.ERROR_HOLD;
        ELSIF CycleMotionPermit
           AND (M1_CablePosM >= (TouchPositionM + CtrlAscentDistM))
           AND (M2_CablePosM >= (TouchPositionM + CtrlAscentDistM))
           AND (ABS(M1_CablePosM - M2_CablePosM) <= CtrlAscentToleranceM) THEN
            State := E_CycleStep.ASCENDING_LOADED;
        ELSIF StabilizationTimer.Q THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0008;
            State := E_CycleStep.ERROR_HOLD;
        END_IF;

    E_CycleStep.ASCENDING_LOADED:
        CycleStep := E_CycleStep.ASCENDING_LOADED;
        CycleStateStr := 'REMONTÉE EN CHARGE';

        WinchM1Cmd.StartStop := TRUE;
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct  := 70.0;

        WinchM2Cmd.StartStop := TRUE;
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct  := 70.0;

        // Transition alignée sur la limite haute d'exploitation
        IF CycleMotionPermit AND M1_CablePosM >= CableLimitM1AscentM THEN
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            State := E_CycleStep.DRAINING_PAUSE;
        END_IF;

    E_CycleStep.DRAINING_PAUSE:
        CycleStep := E_CycleStep.DRAINING_PAUSE;
        CycleStateStr := 'ÉGOUTTAGE DU GODET EN COURS';

        WinchM1Cmd.StartStop := FALSE;
        WinchM2Cmd.StartStop := FALSE;

        DrainingTimer(IN := TRUE, PT := DrainingTime);
        IF CycleMotionPermit AND DrainingTimer.Q THEN
            DrainingTimer(IN := FALSE);
            State := E_CycleStep.TRANSLATION_MOVE;
        END_IF;

    E_CycleStep.TRANSLATION_MOVE:
        CycleStep := E_CycleStep.TRANSLATION_MOVE;
        CycleStateStr := 'DÉPLACEMENT VERS TRÉMIE DE VIDANGE';

        TranslationCmd.Target := 1; // Trémie
        TranslationCmd.Start := TRUE;

        // Transition si translation arrivé à la trémie
        IF CycleMotionPermit AND Translation_At_Tremie THEN
            TranslationCmd.Start := FALSE;
            State := E_CycleStep.DESCENDING_OPEN_DUMP;
        END_IF;

    E_CycleStep.DESCENDING_OPEN_DUMP:
        CycleStep := E_CycleStep.DESCENDING_OPEN_DUMP;
        CycleStateStr := 'VIDANGE / OUVERTURE DU GODET';

        BucketCmd.Open := TRUE;

        // Transition si benne ouvert avec succès
        IF CycleMotionPermit AND Benne_Done AND Benne_IsOpen THEN
            BucketCmd.Open := FALSE;
            State := E_CycleStep.RETURN_WORK_POS;
        END_IF;

    E_CycleStep.RETURN_WORK_POS:
        CycleStep := E_CycleStep.RETURN_WORK_POS;
        CycleStateStr := 'RETOUR VERS FOSSE DE TRAVAIL';

        TranslationCmd.Target := SelectedWorkTarget;
        TranslationCmd.Start := TRUE;

        // Transition si translation de retour sur sa position de travail
        IF CycleMotionPermit AND ((SelectedWorkTarget = 2 AND Translation_At_P2)
           OR (SelectedWorkTarget = 3 AND Translation_At_P1)) THEN
            TranslationCmd.Start := FALSE;
            State := E_CycleStep.READY;
        END_IF;

    E_CycleStep.READY:
        CycleStep := E_CycleStep.READY;
        CycleStateStr := 'CYCLE AUTOMATIQUE COMPLÉTÉ - PRÊT';

        WinchM1Cmd.StartStop := FALSE;
        WinchM2Cmd.StartStop := FALSE;
        TranslationCmd.Start := FALSE;
        Done  := TRUE;
        Busy  := FALSE;

        // Rebouclage manuel ou auto sur Start
        IF StartEdge.Q THEN
            Done := FALSE;
            State := E_CycleStep.DESCENDING_OPEN;
        END_IF;

    E_CycleStep.ERROR_HOLD:
        CycleStep := E_CycleStep.ERROR_HOLD;
        CycleStateStr := 'CYCLE SUSPENDU (PAUSE OU ARRÊT DE SÉCURITÉ)';

        WinchM1Cmd.StartStop := FALSE;
        WinchM2Cmd.StartStop := FALSE;
        TranslationCmd.Start := FALSE;

        BucketCmd.Open  := FALSE;
        BucketCmd.Close := FALSE;

END_CASE;

// 🛑 Relâchement homme-mort : aucune demande d'actionneur ne reste active.
// L'étape est mémorisée et reprend au prochain appui valide.
IF Busy AND NOT CycleMotionPermit THEN
    WinchM1Cmd.StartStop := FALSE;
    WinchM2Cmd.StartStop := FALSE;
    TranslationCmd.Start := FALSE;
    BucketCmd.Open := FALSE;
    BucketCmd.Close := FALSE;
    BucketCmd.KoboldContactorCmd := FALSE;
END_IF;

END_FUNCTION_BLOCK

(* =======================================================================
   🪣 FB_Bucket — Commande d'ouverture et de fermeture du benne
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Pilotage synchrone et séquencement d'ouverture/fermeture benne
   📄 Doc métier : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md
   🔌 Interface : FB standard (Partie3 §1bis)
   🔒 Sécurité : Surveillance du glissement M1 et interlocks de mouvement
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_Bucket
VAR_INPUT
    // === COMMANDES ET ETATS GENERAL ===
    Enable                          : BOOL;                           // --> [CMD] Autorisation generale FB
    Reset                           : BOOL;                           // --> [CMD] Acquittement defauts sur front
    Mode                            : E_Mode;                         // --> [CMD] Mode de marche machine
    CmdOpen_IHM                     : BOOL;                           // --> [CMD] Demande ouverture depuis IHM
    CmdClose_IHM                    : BOOL;                           // --> [CMD] Demande fermeture depuis IHM
    MotionRequestActive             : BOOL;                           // --> [CMD] Intention mouvement arbitree
    MotionDirection                 : INT;                            // --> [CMD] Sens arbitre (1: montee, -1: descente)
    ConfirmOpenPosition             : BOOL;                           // --> [CMD] Bouton IHM confirmation benne ouvert
    ConfirmClosePosition            : BOOL;                           // --> [CMD] Bouton IHM confirmation benne ferme

    // === SECOURS ET HARDWARE ===
    PowerContactorEngaged           : BOOL;                           // --> [SAFE] Condition d'arret d'urgence / puissance
    CablePosM1                      : REAL;                           // --> [HW] Position reelle cable treuil M1 (m)
    CablePosM2                      : REAL;                           // --> [HW] Position reelle cable treuil M2 (m)
    HomedM1                         : BOOL;                           // --> [HW] Codeur M1 reference
    HomedM2                         : BOOL;                           // --> [HW] Codeur M2 reference
    M1_Busy                         : BOOL;                           // --> [HW] Treuil M1 en mouvement (Busy)
    M2_Busy                         : BOOL;                           // --> [HW] Treuil M2 en mouvement (Busy)
    InhibitM1                       : BOOL;                           // --> [HW] Treuil M1 inhibe
    InhibitM2                       : BOOL;                           // --> [HW] Treuil M2 inhibe

    // === REGLAGES ET CONFIGURATION ===
    Config                          : ST_BucketConfig;                // --> [CFG] Configuration parametres benne
    CfgTimeoutDuration              : TIME := T#60s;                  // --> [CFG] Timeout de mouvement configurable
    M1SlipToleranceM                : REAL := 1.0;                    // --> [CFG] Tolerance glissement M1 pendant Busy (m)

    // === BYPASSES ET SIMULATION ===
    BypassGlobal                    : BOOL := FALSE;                  // --> [TST] Force ErrorId=0 global
END_VAR
VAR_OUTPUT
    // === ETATS IEC ET SYNOPTIQUE ===
    Ready                           : BOOL;                           // <-- [STAT] FB pret a fonctionner
    Status                          : ST_FbStatus;                    // <-- [FB] Statut complet (Busy/Done/Error/ErrorId/State/StateAtError)

    // === DEMANDES ET ORDRES ACTIONNEURS ===
    CloseReq                        : BOOL;                           // <-- [STAT] Demande de fermeture memorisee
    OpenReq                         : BOOL;                           // <-- [STAT] Demande d'ouverture memorisee
    M2_StartStop                    : BOOL;                           // <-- [ACT] Ordre StartStop vers Winch M2
    M2_Direction                    : INT;                            // <-- [ACT] Ordre Direction vers Winch M2
    M2_ForceSlowSpeed               : BOOL;                           // <-- [ACT] Forcage vitesse lente sur M2

    // === DIAGNOSTICS ET MESURES ===
    M1SlipDetected                  : BOOL;                           // <-- [DIAG] Glissement M1 detecte
    ActiveOffsetM                   : REAL;                           // <-- [DIAG] Decalage cible pour FB_WinchSync
    DeltaPosition_M                 : REAL;                           // <-- [DIAG] Ecart reel signe M2 - M1 (m)
    RemainingTravelM                : REAL;                           // <-- [DIAG] Distance restante avant cible (m)
END_VAR
VAR_IN_OUT
    // === STRUCTURES DE DONNÉES PARTAGÉES ===
    BucketState                     : ST_BucketState;                 // <-> [BUS] Etat physique memorise du benne
END_VAR
VAR
    // === DETECTEURS ET TIMERS INTERNES ===
    ResetEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Reset
    ErrorEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Erreur
    BusyEdge                        : R_TRIG;                         // . [LOC] Detecteur entree en etat Busy
    ConfirmOpenEdge                 : R_TRIG;                         // . [LOC] Detecteur front confirmation ouverture
    ConfirmCloseEdge                : R_TRIG;                         // . [LOC] Detecteur front confirmation fermeture
    TonTimeout                      : TON;                            // . [LOC] Temporisateur timeout de mouvement

    // === VARIABLES LOCALES CALCULÉES ===
    FirstCycle                      : BOOL := TRUE;                  // . [LOC] Drapeau de premier cycle API
    SevereError                     : BOOL;                           // . [LOC] Erreur grave necessitant arret
    MaxAllowedOffset                : REAL;                           // . [LOC] Offset max calcule dynamiquement
    M1RefPosM                       : REAL;                           // . [LOC] Position M1 memorisee a l'entree Busy
    M2StartPosM                     : REAL;                           // . [LOC] Position M2 memorisee a l'entree Busy
    WasOpenAtStart                  : BOOL;                           // . [LOC] Etat IsOpen memorise a l'entree Busy
    WasClosedAtStart                : BOOL;                           // . [LOC] Etat IsClosed memorise a l'entree Busy
    LeftStartSinceArm               : BOOL;                           // . [LOC] Quitte position de depart
    HoldOffsetM                     : REAL;                           // . [LOC] Ecart reel mémorise (gel en position intermediaire)
END_VAR

{region "§1 Gate securite"}
// 🛑 1. GATE DE SÉCURITÉ
IF NOT Enable OR NOT PowerContactorEngaged THEN
    IF (Status.State = E_State.BUSY) OR CloseReq OR OpenReq THEN
        BucketState.StateIncoherent := TRUE;
    END_IF;
    Ready := FALSE;
    Status.Busy := FALSE;
    Status.Done := FALSE;
    M2_StartStop := FALSE;
    M2_Direction := 0;
    M2_ForceSlowSpeed := FALSE;
    Status.State := E_State.DISABLED;
    M1SlipDetected := FALSE;
    // Les requêtes internes sont réinitialisées
    CloseReq := FALSE;
    OpenReq := FALSE;
    RETURN;
END_IF;

// 🟢 ÉTAT INITIAL READY SI DISABLED PRÉCÉDEMMENT
IF Status.State = E_State.DISABLED THEN
    Status.State := E_State.READY;
END_IF;

{endregion}

{region "§2 Reset et bypass"}
// 🔑 2. GESTION DU RESET (FRONT MONTANT)
ResetEdge(CLK := Reset);

// 🌐 BYPASS GLOBAL : force ErrorId = 0 (ignore toutes les erreurs benne)
IF BypassGlobal THEN
    Status.ErrorId := 16#0000;
END_IF;

IF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFFA; // Efface les bits 0 et 2 (Timeout, Limites)
END_IF;

{endregion}

{region "§3 Coherence et etat mecanique benne"}
// 📏 3. DÉTECTION D'INCOHÉRENCE AU BOOT (PREMIER CYCLE API)
IF FirstCycle THEN
    FirstCycle := FALSE;
    IF Config.CoherenceLimitM > 0.01 THEN
        IF BucketState.IsOpen AND NOT BucketState.IsClosed THEN
            IF ABS(CablePosM2 - BucketState.LastPosM2Open) > Config.CoherenceLimitM THEN
                BucketState.StateIncoherent := TRUE;
            END_IF;
        ELSIF BucketState.IsClosed AND NOT BucketState.IsOpen THEN
            IF ABS(CablePosM2 - BucketState.LastPosM2Close) > Config.CoherenceLimitM THEN
                BucketState.StateIncoherent := TRUE;
            END_IF;
        ELSE
            // Si l'état n'a jamais été initialisé (les deux FALSE/TRUE), on signale une incohérence
            BucketState.StateIncoherent := TRUE;
        END_IF;
    ELSE
        // Limite non configurée ou invalide, par précaution on force l'incohérence
        BucketState.StateIncoherent := TRUE;
    END_IF;
END_IF;

// Met à jour le bit1 d'erreur si incohérence détectée
IF BucketState.StateIncoherent THEN
    Status.ErrorId := Status.ErrorId OR 16#0002;
    // Force l'état inconnu (ni ouvert ni fermé) si incohérence active
    BucketState.IsOpen := FALSE;
    BucketState.IsClosed := FALSE;
ELSE
    Status.ErrorId := Status.ErrorId AND 16#FFFD;
END_IF;

// 🧲 3bis. GARDE-FOU CODEURS NON RÉFÉRENCÉS (bit 3)
// CablePosM1/CablePosM2 ne sont fiables que si le homing (Partie10) a été fait sur les 2 treuils.
// Continu (pas de front Reset) : se lève/efface tout seul selon l'état réel du homing.
IF NOT HomedM1 OR NOT HomedM2 THEN
    Status.ErrorId := Status.ErrorId OR 16#0008;
ELSE
    Status.ErrorId := Status.ErrorId AND 16#FFF7;
END_IF;

// 3bis-bis. CONFIRMATION MANUELLE POSITION OUVERTE — voir bandeau
// Action de CONFIRMATION (aucun mouvement, ne pilote pas M2) : acquitte les défauts et réinitialise
// les demandes. L'état IsOpen/IsClosed reste STRICTEMENT évalué en continu (§3bis-quater) selon la position codeur réelle.
ConfirmOpenEdge(CLK := ConfirmOpenPosition);
IF ConfirmOpenEdge.Q
   AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2)
   AND NOT M1_Busy AND NOT M2_Busy THEN
    BucketState.LastPosM2Open := CablePosM2;
    BucketState.LastPosM2Close := CablePosM2 - Config.OffsetOpenM + Config.OffsetCloseM;
    Status.ErrorId := 16#0000;      // Réinitialisation complète des défauts benne lors du référencement manuel
    CloseReq := FALSE;              // Reset des demandes en attente pour éviter les démarrages intempestifs
    OpenReq := FALSE;
END_IF;

// 3bis-ter. CONFIRMATION MANUELLE POSITION FERMÉE
// Même principe que ConfirmOpenPosition pour acquitter et réinitialiser.
ConfirmCloseEdge(CLK := ConfirmClosePosition);
IF ConfirmCloseEdge.Q
   AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2)
   AND NOT M1_Busy AND NOT M2_Busy THEN
    BucketState.LastPosM2Close := CablePosM2;
    BucketState.LastPosM2Open := CablePosM2 - Config.OffsetCloseM + Config.OffsetOpenM;
    Status.ErrorId := 16#0000;      // Réinitialisation complète des défauts benne lors du référencement manuel
    CloseReq := FALSE;              // Reset des demandes en attente pour éviter les démarrages intempestifs
    OpenReq := FALSE;
END_IF;

// 3bis-quater. DÉTECTION AUTOMATIQUE EN CONTINU (5 ZONES CLAIRES OPÉRATEUR) :
// Recalcule IsOpen, IsClosed, TooOpen, TooClosed, IsIntermediate en PERMANENCE à partir de
// l'écart réel Delta = CablePosM2 - CablePosM1 et de la tolérance Config.CoherenceLimitM.
// Actif à l'arrêt (NOT M1_Busy/M2_Busy), hors séquence active (State <> BUSY), codeurs référencés.
IF (Status.State <> E_State.BUSY) AND NOT M1_Busy AND NOT M2_Busy AND HomedM1 AND HomedM2
   AND (Config.CoherenceLimitM > 0.01) THEN

    // 1. Zone Benne Ouverte (Delta proche de OffsetOpenM)
    IF ABS((CablePosM2 - CablePosM1) - Config.OffsetOpenM) <= Config.CoherenceLimitM THEN
        BucketState.IsOpen := TRUE;
        BucketState.IsClosed := FALSE;
        BucketState.TooOpen := FALSE;
        BucketState.TooClosed := FALSE;
        BucketState.IsIntermediate := FALSE;
        BucketState.LastPosM2Open := CablePosM2;
        BucketState.StateIncoherent := FALSE;

    // 2. Zone Benne Fermée (Delta proche de OffsetCloseM)
    ELSIF ABS((CablePosM2 - CablePosM1) - Config.OffsetCloseM) <= Config.CoherenceLimitM THEN
        BucketState.IsClosed := TRUE;
        BucketState.IsOpen := FALSE;
        BucketState.TooOpen := FALSE;
        BucketState.TooClosed := FALSE;
        BucketState.IsIntermediate := FALSE;
        BucketState.LastPosM2Close := CablePosM2;
        BucketState.StateIncoherent := FALSE;

    // 3. Zone Trop Ouvert (Dépassement en ouverture : Delta < OffsetOpenM - Tolerance)
    ELSIF (CablePosM2 - CablePosM1) < (Config.OffsetOpenM - Config.CoherenceLimitM) THEN
        BucketState.IsOpen := FALSE;
        BucketState.IsClosed := FALSE;
        BucketState.TooOpen := TRUE;
        BucketState.TooClosed := FALSE;
        BucketState.IsIntermediate := FALSE;
        BucketState.StateIncoherent := TRUE;

    // 4. Zone Trop Fermé (Dépassement en fermeture : Delta > OffsetCloseM + Tolerance)
    ELSIF (CablePosM2 - CablePosM1) > (Config.OffsetCloseM + Config.CoherenceLimitM) THEN
        BucketState.IsOpen := FALSE;
        BucketState.IsClosed := FALSE;
        BucketState.TooOpen := FALSE;
        BucketState.TooClosed := TRUE;
        BucketState.IsIntermediate := FALSE;
        BucketState.StateIncoherent := TRUE;

    // 5. Zone Intermédiaire / Entrebâillée (entre OffsetOpenM + Tol et OffsetCloseM - Tol)
    ELSE
        BucketState.IsOpen := FALSE;
        BucketState.IsClosed := FALSE;
        BucketState.TooOpen := FALSE;
        BucketState.TooClosed := FALSE;
        BucketState.IsIntermediate := TRUE;
        BucketState.StateIncoherent := FALSE;
    END_IF;
END_IF;

// 🔍 3ter. MÉCA C COUCHE 1 — GLISSEMENT M1 PENDANT BUSY (bit4)
// M1 doit rester immobile pendant que M2 bouge seul. Référence prise à l'entrée en Busy.
BusyEdge(CLK := (Status.State = E_State.BUSY));
IF BusyEdge.Q THEN
    M1RefPosM := CablePosM1;
    M2StartPosM := CablePosM2;   // Borne le recul autorisé (voir §6 CASE BUSY)
    // Mémorise l'état d'origine (restauré si recul complet jusqu'à M2StartPosM, voir §6 CASE BUSY)
    // puis passe en position transitoire dès le démarrage du mouvement — ni ouvert ni fermé pendant
    // le trajet, quel que soit l'état mémorisé avant.
    WasOpenAtStart := BucketState.IsOpen;
    WasClosedAtStart := BucketState.IsClosed;
    LeftStartSinceArm := FALSE;
    BucketState.IsOpen := FALSE;
    BucketState.IsClosed := FALSE;
END_IF;

IF (Status.State = E_State.BUSY) AND (ABS(CablePosM1 - M1RefPosM) > M1SlipToleranceM) AND NOT InhibitM1 THEN
    Status.ErrorId := Status.ErrorId OR 16#0010;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFEF;
END_IF;
M1SlipDetected := (Status.ErrorId AND 16#0010) <> 16#0000;

{endregion}

{region "§4 Surveillance limites timeout et arret"}
// 🚨 4. SURVEILLANCE DES LIMITES DE PLACEMENT (Limites dépassées - bit 2)
// On s'assure que l'écart réel M1/M2 ne dépasse pas les offsets de configuration + marge de sécurité de 1m
MaxAllowedOffset := MAX(ABS(Config.OffsetOpenM), ABS(Config.OffsetCloseM)) + 1.0;
IF (ABS(CablePosM1 - CablePosM2) > MaxAllowedOffset) AND NOT InhibitM1 AND NOT InhibitM2 THEN
    Status.ErrorId := Status.ErrorId OR 16#0004;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFFB;
END_IF;

// ⏲️ 5. SURVEILLANCE TIMEOUT MOUVEMENT (bit 0)
// Déclenche si le mouvement actif (M2_StartStop = TRUE) dure plus longtemps que le timeout
TonTimeout(IN := (Status.State = E_State.BUSY AND M2_StartStop), PT := CfgTimeoutDuration);
IF TonTimeout.Q THEN
    Status.ErrorId := Status.ErrorId OR 16#0001;
END_IF;

// ❌ Évaluation des erreurs graves (Timeout, Limites dépassées, Codeur(s) non référencé(s), ou Glissement M1)
SevereError := (Status.ErrorId AND 16#001D) <> 16#0000;

IF SevereError THEN
    IF (Status.State = E_State.BUSY) OR CloseReq OR OpenReq THEN
        BucketState.StateIncoherent := TRUE;
    END_IF;
    M2_StartStop := FALSE;
    M2_Direction := 0;
    M2_ForceSlowSpeed := FALSE;
    CloseReq := FALSE;
    OpenReq := FALSE;
    // On repasse en READY et attend un Reset
    Status.State := E_State.READY;
END_IF;

{endregion}

{region "§5 Machine etat commande"}
// 🎛️ 6. MACHINE À ÉTATS DE COMMANDE
CASE Status.State OF
    E_State.READY:
        Ready := TRUE;
        Status.Busy := FALSE;
        Status.Done := FALSE;
        M2_StartStop := FALSE;
        M2_Direction := 0;
        M2_ForceSlowSpeed := FALSE;
        RemainingTravelM := 0.0; // Pas de mouvement en cours

        // Demande benne acceptée UNIQUEMENT si M1 ET M2 sont à l'arrêt (tous
        // modes) — évite qu'un mouvement en cours sur l'un des deux treuils "traverse" l'armement
        // du benne. Ni mémorisation de la requête, ni démarrage tant que ce
        // n'est pas vrai — l'opérateur doit refaire la demande une fois les treuils arrêtés.
        IF NOT M1_Busy AND NOT M2_Busy THEN
            // Mémorisation des requêtes IHM (l'une annule l'autre)
            IF CmdClose_IHM AND NOT SevereError THEN
                CloseReq := TRUE;
                OpenReq := FALSE;
            ELSIF CmdOpen_IHM AND NOT SevereError THEN
                OpenReq := TRUE;
                CloseReq := FALSE;
            END_IF;

            // Condition d'activation du mouvement (Requête IHM + Validation Joystick dans le bon sens)
            // Sens inversés (enroulage ferme, déroulage ouvre)
            IF CloseReq AND MotionRequestActive AND (MotionDirection = 1) THEN
                Status.State := E_State.BUSY;
            ELSIF OpenReq AND MotionRequestActive AND (MotionDirection = -1) THEN
                Status.State := E_State.BUSY;
            END_IF;
        END_IF;

    E_State.BUSY:
        Ready := TRUE;
        Status.Busy := TRUE;
        Status.Done := FALSE;
        M2_ForceSlowSpeed := TRUE; // Vitesse lente forcée sans contacteurs

        // Distance restante avant cible, pour affichage IHM (aiguille/jauge)
        // Toujours positive, décroît vers 0 à mesure que M2 approche la cible.
        IF CloseReq THEN
            RemainingTravelM := MAX(0.0, (CablePosM1 + Config.OffsetCloseM) - CablePosM2);
        ELSIF OpenReq THEN
            RemainingTravelM := MAX(0.0, CablePosM2 - (CablePosM1 + Config.OffsetOpenM));
        ELSE
            RemainingTravelM := 0.0;
        END_IF;

        // Interlock Homme-mort joystick
        // Sens inverse autorisé (recul/annulation partielle) pendant CloseReq/OpenReq, mais BORNÉ
        // à la position de départ (M2StartPosM, mémorisée à l'entrée en Busy) — ne permet jamais de
        // dépasser cette position dans le sens opposé au sens principal.
        IF NOT MotionRequestActive THEN
            // Si relâchement de l'intention opérateur, arrêt temporaire du mouvement.
            M2_StartStop := FALSE;
            M2_Direction := 0;
        ELSIF CloseReq THEN
            IF (MotionDirection = 1) THEN
                // Sens principal (fermeture) : M2 enroule (monte)
                M2_StartStop := TRUE;
                M2_Direction := 1;
            ELSIF (MotionDirection = -1) AND (CablePosM2 > M2StartPosM) THEN
                // Sens inverse : recul autorisé UNIQUEMENT tant qu'on n'est pas revenu à la position
                // de départ (pas au-delà, donc pas de ré-ouverture complète depuis ici)
                M2_StartStop := TRUE;
                M2_Direction := -1;
            ELSE
                // Mauvais sens, ou position de départ déjà atteinte en reculant : arrêt
                M2_StartStop := FALSE;
                M2_Direction := 0;
            END_IF;
        ELSIF OpenReq THEN
            IF (MotionDirection = -1) THEN
                // Sens principal (ouverture) : M2 déroule (descend)
                M2_StartStop := TRUE;
                M2_Direction := -1;
            ELSIF (MotionDirection = 1) AND (CablePosM2 < M2StartPosM) THEN
                // Sens inverse : recul autorisé UNIQUEMENT tant qu'on n'est pas revenu à la position
                // de départ (pas au-delà, donc pas de re-fermeture complète depuis ici)
                M2_StartStop := TRUE;
                M2_Direction := 1;
            ELSE
                M2_StartStop := FALSE;
                M2_Direction := 0;
            END_IF;
        ELSE
            M2_StartStop := FALSE;
            M2_Direction := 0;
        END_IF;

        // Détecte qu'on a réellement quitté la position de départ (évite que le test de retour
        // ci-dessous ne se déclenche instantanément au 1er cycle de Busy, où CablePosM2 =
        // M2StartPosM par définition).
        IF (CloseReq AND (CablePosM2 > M2StartPosM)) OR (OpenReq AND (CablePosM2 < M2StartPosM)) THEN
            LeftStartSinceArm := TRUE;
        END_IF;

        // Condition d'arrêt automatique de la fermeture
        IF CloseReq THEN
            // Compense l'inertie mécanique (coast-down) : coupe la commande
            // CloseAnticipationM avant OffsetCloseM pour amener l'arrêt réel près du
            // vrai offset au lieu de le dépasser.
            IF CablePosM2 >= (CablePosM1 + Config.OffsetCloseM - Config.CloseAnticipationM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                // Mémorisation de l'état physique fermé
                BucketState.IsOpen := FALSE;
                BucketState.IsClosed := TRUE;
                BucketState.LastPosM2Close := CablePosM2;
                BucketState.StateIncoherent := FALSE; // recalage réussi

                CloseReq := FALSE;
                Status.State := E_State.DONE;
            // Recul complet jusqu'à la position de départ — restaure l'état d'origine
            // (physiquement, on est revenu là où on a commencé)
            ELSIF LeftStartSinceArm AND (CablePosM2 <= M2StartPosM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                BucketState.IsOpen := WasOpenAtStart;
                BucketState.IsClosed := WasClosedAtStart;

                CloseReq := FALSE;
                Status.State := E_State.DONE;
            END_IF;
        END_IF;

        // Condition d'arrêt automatique de l'ouverture
        IF OpenReq THEN
            // Même logique que la fermeture ci-dessus, inertie différente en ouverture
            // (OpenAnticipationM distinct).
            IF CablePosM2 <= (CablePosM1 + Config.OffsetOpenM + Config.OpenAnticipationM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                // Mémorisation de l'état physique ouvert
                BucketState.IsOpen := TRUE;
                BucketState.IsClosed := FALSE;
                BucketState.LastPosM2Open := CablePosM2;
                BucketState.StateIncoherent := FALSE; // recalage réussi

                OpenReq := FALSE;
                Status.State := E_State.DONE;
            // Recul complet jusqu'à la position de départ — restaure l'état d'origine
            // (physiquement, on est revenu là où on a commencé)
            ELSIF LeftStartSinceArm AND (CablePosM2 >= M2StartPosM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                BucketState.IsOpen := WasOpenAtStart;
                BucketState.IsClosed := WasClosedAtStart;

                OpenReq := FALSE;
                Status.State := E_State.DONE;
            END_IF;
        END_IF;

    E_State.DONE:
        Ready := TRUE;
        Status.Busy := FALSE;
        Status.Done := TRUE;
        M2_StartStop := FALSE;
        M2_Direction := 0;
        M2_ForceSlowSpeed := FALSE;
        RemainingTravelM := 0.0; // Cible atteinte

        // Attente du relâchement de la validation joystick pour repasser à READY
        IF NOT MotionRequestActive THEN
            Status.State := E_State.READY;
        END_IF;
END_CASE;

// 📤 7. GESTION DES SORTIES D'ÉTAT GLOBALES
Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;

// Calcul continu de l'écart réel signé M2 - M1 pour l'affichage IHM et l'aide au pilotage
DeltaPosition_M := CablePosM2 - CablePosM1;

// Détermination de l'offset actif pour le synchronisme de FB_WinchSync ET pour l'affichage IHM
// (M2PositionCorrected, côté PRG_SUPERVISION_CFC).
// CloseReq/OpenReq sont pris en compte (pas seulement IsClosed/IsOpen, qui sont FALSE pendant
// TOUT le trajet depuis l'état transitoire) pour que la position corrigée de M2 converge
// progressivement vers M1 pendant l'enroulage.
IF Status.State = E_State.BUSY THEN
    // Pendant le déplacement, l'offset actif suit la différence réelle de câble (M2 - M1) afin que
    // la position corrigée de M2 reste stable (égale à M1, cad la hauteur du benne) sans à-coup,
    // tandis que le câble brut de M2 montre son enroulement.
    ActiveOffsetM := CablePosM2 - CablePosM1;
    HoldOffsetM := ActiveOffsetM;   // Mémorise l'écart réel pour le gel en position intermédiaire
ELSIF CloseReq OR BucketState.IsClosed THEN
    ActiveOffsetM := Config.OffsetCloseM;
    HoldOffsetM := ActiveOffsetM;
ELSIF OpenReq OR BucketState.IsOpen THEN
    ActiveOffsetM := Config.OffsetOpenM;
    HoldOffsetM := ActiveOffsetM;
ELSE
    // Position intermédiaire non référencée : gèle l'écart réel mémorisé (HoldOffsetM) au lieu de
    // sauter vers la config. Évite l'à-coup sur la position corrigée M2 / la synchro.
    ActiveOffsetM := HoldOffsetM;
END_IF;

{endregion}

(* ═══════════════════════════════════════════════════════════════
   🛡️ FB_WinchOutputInterlock_LD — Barrière finale frein / puissance M1 ou M2
   ───────────────────────────────────────────────────────────────
   📥 Commandes métier déjà calculées par FB_Winch.
   📤 Producteur unique des commandes finales vers PRG_06_Outputs_LD.
   🔒 Le retour (`BrakeFeedback`) confirme le contacteur/bobine de desserrage ;
      il ne mesure pas mécaniquement le frein.
   ⏱️ Watchdog fixe 500 ms après demande effective de desserrage.
   🔧 REX 2026-08-05 : Reset du watchdog frein reconstruit en pattern Cause/Ack
      (CODE_QUALITY_STANDARDS §9) — plus jamais conditionné par un état externe
      instantané (audit sécurité M3, même classe que l'incident EmergencyArmingFailed).
   🆕 REX 2026-08-06 (retrait FB_Brake, demande client) : plus de séquence temporisée
      frein — le frein n'est plus qu'un consommateur direct de RelayFwd/RelayRev
      (`BrakeCmd := RelayFwd OR RelayRev`, câblé au grand jour dans PRG_06_Outputs_LD
      à partir des DQ RelayFwd/RelayRev). Aucun risque d'écart frein/mouvement : le
      frein SUIT structurellement le contacteur de sens, il ne peut jamais en diverger
      puisque c'est la MÊME variable qui pilote les deux. `FB_Brake` reste utilisé tel
      quel pour Translation (M3) — non touché par ce lot.
   🔧 REX 2026-08-06bis (review croisée Codex) : le watchdog frein a d'abord été armé sur
      `RequestedRelayFwd OR RequestedRelayRev` (demande BRUTE, disponible tôt dans le scan)
      — bug réel trouvé : cette demande brute passe à TRUE dès l'appui joystick, alors que
      `RelayFwd`/`RelayRev` FINAUX (§5) restent à FALSE jusqu'à T#1000ms (retombée +
      `RestartDelay`, voir §4). Le watchdog (seuil 500ms) se déclenchait donc À TORT sur
      quasiment CHAQUE redémarrage normal. Corrigé : le watchdog est désormais armé sur
      `BrakeCmd` (§6, calculé APRÈS §5 — la valeur réellement et définitivement commandée),
      jamais sur une demande amont non encore autorisée. Conséquence acceptée : le bit0
      `ErrorId` (et donc `Error`) n'est mis à jour qu'après le calcul de `BrakeCmd`, donc lu
      par §3/§5 avec un retard d'UN scan (~10ms) sur une nouvelle occurrence de défaut —
      négligeable face au budget 500ms du watchdog, et strictement nécessaire pour éviter
      les faux déclenchements.
   🔴🔧 REX 2026-08-07 — RestartDelay COMPTAIT SANS ATTENDRE LE FREIN PHYSIQUE (audit croisé,
      demande client) : un lot précédent avait fait démarrer le décompte 1500ms sur `NOT
      MotorRequest` seul (relâchement joystick, instantané), perdant la dépendance à
      `BrakeFeedback` (retombée physique bobine/mâchoires, ~200-300ms mécaniques après la
      commande). Un redémarrage pouvait donc être autorisé alors que le frein n'était pas
      encore réellement fermé au moment où le décompte a commencé. Corrigé (§4) :
      `NOT BrakeFeedback` réintégré en ET avec `NOT MotorRequest` — le décompte ne
      démarre/continue que si les deux conditions (moteur non demandé ET frein physiquement
      fermé) sont vraies. Comportement "purge pendant la pause" conservé.
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_WinchOutputInterlock_LD
VAR_INPUT
    Enable                       : BOOL;
    Reset                        : BOOL;
    PowerContactorEngaged              : BOOL;
    SafeStop                     : BOOL; // 🔧 REX 2026-08-05 (audit sécurité) : volontairement non lu ci-dessous —
                                          // SafeStop est une rampe rapide gérée en amont par FB_Winch
                                          // (Enable maintenu, AGENTS.md "SafeStop = rampe rapide"). Cette barrière
                                          // ne coupe qu'après la retombée effective de la demande à zéro, sauf
                                          // gate dur/timeout/défaut final (§5) — couper ici immédiatement sur
                                          // SafeStop dupliquerait la rampe en un arrêt brutal, contraire au
                                          // comportement spécifié. Entrée conservée pour interface standard
                                          // complète (AF_Partie-03 §1bis), pas un oubli.
    BrakeFeedback                : BOOL; // 🆕 2026-08-06 : retour PHYSIQUE brut du contacteur/bobine frein
                                          // (PRG_02_Acquisition.HwIn.Winch.Mx_BrakeIsOpen_DI), câblé DIRECTEMENT
                                          // depuis PRG_04 — remplace BrakeReleaseRequest/BrakeCommandOpenConfirmed
                                          // (FB_Brake retiré du treuil, voir bandeau). TRUE = frein ouvert/relâché.
    FwdRevSpeedFeedbackOff       : BOOL;
    RequestedRelayFwd            : BOOL;
    RequestedRelayRev            : BOOL;
    RequestedContactor1          : BOOL; // Mapping métier FB_Winch / SpeedStepTable
    RequestedContactor2          : BOOL; // Mapping métier FB_Winch / SpeedStepTable
    RequestedContactor3          : BOOL; // Mapping métier FB_Winch / SpeedStepTable
    RequestedContactor4          : BOOL; // Mapping métier FB_Winch / SpeedStepTable
    RequestedStep                : INT;
END_VAR
VAR_OUTPUT
    Ready                        : BOOL;
    Busy                         : BOOL;
    Done                         : BOOL;
    Error                        : BOOL;
    ErrorId                      : WORD; // bit0 : absence confirmation contacteur desserrage > 500 ms
    State                        : E_WinchFinalInterlockState;
    StateAtError                 : E_WinchFinalInterlockState;
    Reason                       : E_WinchFinalInterlockReason;
    AuthorizedStep               : INT;
    RelayFwd                     : BOOL;
    RelayRev                     : BOOL;
    Contactor1                   : BOOL;
    Contactor2                   : BOOL;
    Contactor3                   : BOOL;
    Contactor4                   : BOOL;
    BrakeCmd                     : BOOL; // 🆕 2026-08-06 : dérivé UNIQUEMENT de RelayFwd OR RelayRev (fin §5) —
                                          // plus de FB_Brake, plus de gate ContactorEngaged/anti-retombée séparée.
    BrakeTimeoutElapsed          : TIME;
    RestartInhibit               : BOOL; // TRUE : timeout acquitté mais neutre/nouvelle demande exigés
    RestartDelayElapsed          : TIME;
    StepDelayElapsed             : TIME;
END_VAR
VAR
    ResetEdge                    : R_TRIG;
    ErrorEdge                    : R_TRIG;
    BrakeTimeout                 : TON;
    StepDelay                    : TON;
    RestartDelay                 : TON;
    RestartRequired              : BOOL;
    ResetRequired                : BOOL; // Timeout : front Reset conscient obligatoire
    NeutralRequestSeen           : BOOL; // Demande moteur zéro observée après acquittement
    RequestedStepClamped         : INT;
    StepDelayTarget              : INT;  // Cible mémorisée : tout changement annule le temps en cours
    MotorRequest                 : BOOL;
    // 🔧 REX 2026-08-05 : pattern Cause/Ack (CODE_QUALITY_STANDARDS §9) — voir §6bis ci-dessous
    BrakeTimeoutCause             : BOOL;
    BrakeTimeoutAck               : BOOL := TRUE;
    BrakeTimeoutCauseEdge         : R_TRIG;
END_VAR

// ── 1. FRONT RESET AVANT GATE ───────────────────────────────────────────
// Le front est échantillonné même pendant Enable/AU faux : un Reset maintenu
// pendant une gate ne devient jamais un faux acquittement au retour.
ResetEdge(CLK := Reset);

// ── 2. GATE : neutralisation sûre ───────────────────────────────────────
// ErrorId, RestartInhibit et ResetRequired ne sont jamais effacés par une perte
// Enable/AU : celle-ci coupe uniquement les sorties. Le retour exige toujours un
// acquittement conscient puis une nouvelle demande opérateur.
IF NOT Enable OR NOT PowerContactorEngaged THEN
    BrakeTimeout(IN := FALSE, PT := T#500ms);
    StepDelay(IN := FALSE, PT := T#1s250ms);
    RestartDelay(IN := FALSE, PT := T#1000ms);
    RelayFwd := FALSE; RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    BrakeCmd := FALSE; AuthorizedStep := 0;
    BrakeTimeoutElapsed := T#0ms; RestartDelayElapsed := T#0ms; StepDelayElapsed := T#0ms;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    Error := (ErrorId <> 16#0000);
    State := E_WinchFinalInterlockState.DISABLED;
    RestartRequired := TRUE;
    RETURN;
END_IF;

RequestedStepClamped := LIMIT(0, RequestedStep, 5);
// SafeStop reste une rampe rapide du FB_Winch (Enable maintenu, Partie 3 §1bis).
// La demande métier reste donc autorisée ici pendant la décélération ; l'interlock
// ne coupe qu'après sa retombée effective à zéro, sauf gate dur ou défaut final.
MotorRequest := (RequestedStepClamped > 0) AND (RequestedRelayFwd XOR RequestedRelayRev);

// ── 2bis. Arbitrage Error/ErrorId AVANT §3/§5 ────────────────────────────
// ErrorId bit0 (défaut frein) est mis à jour en FIN de scan (§6bis, après BrakeCmd) —
// la valeur lue ici est donc celle de la fin du scan PRÉCÉDENT (retard d'un scan sur une
// nouvelle occurrence, ~10ms, négligeable face au budget 500ms du watchdog). Voir bandeau.
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// ── 3. Réarmement anti-redémarrage automatique ──────────────────────────
// Après timeout : cause disparue + front Reset, puis demande moteur à zéro,
// puis nouvelle demande distincte. La retombée + T#1000ms sera ensuite refaite.
IF RestartInhibit AND NOT Error AND NOT ResetRequired AND NOT ResetEdge.Q THEN
    IF NOT MotorRequest THEN
        NeutralRequestSeen := TRUE;
        RestartRequired := TRUE;
    ELSIF NeutralRequestSeen AND MotorRequest THEN
        RestartInhibit := FALSE;
        NeutralRequestSeen := FALSE;
        RestartRequired := TRUE;
        Reason := E_WinchFinalInterlockReason.NONE;
    END_IF;
END_IF;

// ── 4. Mémorisation de l'arrêt : temporisation d'anti-redémarrage chaud ──────────
// 🆕 2026-08-07 (retour terrain) : la temporisation RestartDelay (1500ms) s'arme à
// l'arrêt du mouvement (NOT MotorRequest) et s'écoule pendant la pause à l'arrêt (au lieu
// de repartir de zéro à chaque nouvel appui) — permet un redémarrage instantané si la pause
// dépasse 1.5s.
// 🔧 REX 2026-08-07 (2) (audit croisé, demande client "sécuriser avec l'info frein") : la
// version ci-dessus comptait dès `NOT MotorRequest` (relâchement joystick, INSTANTANÉ) sans
// attendre la retombée PHYSIQUE du frein (`NOT BrakeFeedback` = bobine retombée, mâchoires
// serrées — ~200-300ms mécaniques après la commande). Un nouveau départ pouvait donc être
// autorisé après 1500ms décomptés dès le relâchement, alors que le frein n'était même pas
// encore complètement fermé au début du décompte — la protection perdait son sens (protéger
// le moteur/frein d'un réengagement trop rapide après un arrêt RÉELLEMENT confirmé). Corrigé :
// `NOT BrakeFeedback` réintégré en ET — le décompte ne démarre/continue que si le moteur n'est
// plus demandé ET que le frein est physiquement confirmé fermé. Garde le comportement "purge
// pendant la pause" (RestartRequired ne s'arme qu'à NOT MotorRequest, indépendant de la tempo).
IF NOT MotorRequest THEN
    RestartRequired := TRUE;
END_IF;
RestartDelay(IN := RestartRequired AND NOT MotorRequest AND NOT BrakeFeedback AND NOT RestartInhibit, PT := T#1500ms);
RestartDelayElapsed := RestartDelay.ET;
IF RestartDelay.Q THEN
    RestartRequired := FALSE;
END_IF;

// ── 5. Autorisation moteur ────────────────────────────────────────────────
RelayFwd := FALSE; RelayRev := FALSE;
Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
Busy := FALSE; Done := FALSE; Ready := NOT Error;

IF Error THEN
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    State := E_WinchFinalInterlockState.FAULT;
ELSIF RestartInhibit THEN
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    Reason := E_WinchFinalInterlockReason.RESTART_INHIBITED;
    State := E_WinchFinalInterlockState.FAULT;
ELSIF NOT MotorRequest THEN
    // Toute annulation de demande annule la temporisation de hausse en cours.
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    State := E_WinchFinalInterlockState.READY;
ELSIF RestartRequired THEN
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    State := E_WinchFinalInterlockState.WAIT_RESTART_DELAY;
    Busy := TRUE;
ELSE
    // ⚡ Progression de palier directe : la temporisation (tempo palier) est gérée
    // par le métier (FB_Winch). La barrière finale transmet directement la consigne
    // sans micro-coupure des contacteurs.
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := RequestedStepClamped;

    IF (AuthorizedStep > 0) OR (RequestedStepClamped > 0) THEN
        RelayFwd := RequestedRelayFwd;
        RelayRev := RequestedRelayRev;
        Contactor1 := RequestedContactor1;
        Contactor2 := RequestedContactor2;
        Contactor3 := RequestedContactor3;
        Contactor4 := RequestedContactor4;
    END_IF;

    IF NOT BrakeFeedback THEN
        State := E_WinchFinalInterlockState.WAIT_BRAKE_COMMAND_CONFIRMATION;
        Busy := TRUE;
    ELSE
        State := E_WinchFinalInterlockState.READY;
    END_IF;
END_IF;

// ── 6. Commande frein — couplage direct (demande client 2026-08-06) ────────
// 🆕 BrakeCmd suit STRUCTURELLEMENT RelayFwd/RelayRev, calculé APRÈS leur
// finalisation ci-dessus (§5) : il hérite donc automatiquement de toutes leurs
// conditions de sécurité (Error, RestartInhibit, RestartRequired, MotorRequest)
// sans avoir à les répéter. Aucun risque d'écart frein/mouvement possible : le
// frein ne PEUT pas être commandé ouvert sans qu'un des deux relais de sens le
// soit aussi, puisque c'est la même expression. PRG_06_Outputs_LD recalcule la
// MÊME expression indépendamment sur les DQ finaux (M1RelayFwd OR M1RelayRev)
// pour piloter physiquement la bobine — ce BrakeCmd ici sert de miroir/diagnostic
// (State, IHM) mais n'est plus câblé sur la sortie physique (voir PRG_06 §2).
BrakeCmd := RelayFwd OR RelayRev;

// ── 6bis. Watchdog frein : uniquement sur la commande RÉELLEMENT FINALE ────
// 🔧 REX 2026-08-06bis (review croisée) : armé sur BrakeCmd (fin §5/§6), JAMAIS sur
// RequestedRelayFwd/Rev (demande amont pas encore autorisée par le state-machine
// §5 — RestartRequired peut la retenir jusqu'à T#1000ms, largement > le seuil 500ms
// ci-dessous, ce qui déclenchait un faux défaut à quasiment CHAQUE redémarrage normal).
BrakeTimeout(IN := BrakeCmd AND NOT BrakeFeedback AND NOT RestartInhibit, PT := T#500ms);
BrakeTimeoutElapsed := BrakeTimeout.ET;
IF BrakeTimeout.Q THEN
    BrakeTimeoutCause := TRUE;
ELSIF BrakeFeedback THEN
    BrakeTimeoutCause := FALSE;   // cause réellement disparue (retour desserrage confirmé)
END_IF;
BrakeTimeoutCauseEdge(CLK := BrakeTimeoutCause);
IF BrakeTimeoutCauseEdge.Q THEN
    BrakeTimeoutAck := FALSE;    // nouvelle occurrence -> ré-alarme, ack remis à zéro
    RestartInhibit := TRUE;
    ResetRequired := TRUE;
    NeutralRequestSeen := FALSE;
    RestartRequired := TRUE;
    Reason := E_WinchFinalInterlockReason.BRAKE_COMMAND_NOT_CONFIRMED;
END_IF;
IF ResetEdge.Q THEN
    BrakeTimeoutAck := TRUE;     // toujours effectif, sans condition externe
    ResetRequired := FALSE;
END_IF;
IF BrakeTimeoutCause OR NOT BrakeTimeoutAck THEN
    ErrorId := ErrorId OR 16#0001;
ELSE
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   ⚙️ ST_BucketHMI — Données d'échange IHM pour la benne (M2)
   ───────────────────────────────────────────────────────────────
   📄 Structuration en Cmd / State / Cfg / Bypass (2026-07-23), homogène avec ST_WinchHMI.
   ═══════════════════════════════════════════════════════════════ *)
TYPE ST_BucketHMI :
STRUCT
    Cmd    : ST_BucketCmd;
    State  : ST_BucketHMIState;
    Cfg    : ST_BucketCfg;
    Bypass : ST_BypassBucket;
END_STRUCT
END_TYPE

(* ═══════════════════════════════════════════════════════════════
   🛡️ FB_Safety_EmergencyManagement — Bloc Safety Composite (Parent)
   ───────────────────────────────────────────────────────────────
   📄 Rôle : Bloc de sécurité principal de la boucle d'arrêt d'urgence.
   🧩 Encapsule la Logique (FB_Safety_EmergencyManagementLogic) et le
      Pilote Physique (FB_Safety_EmergencyManagementOutput) par composition.
   📤 Produit les bus publics ST_Safety_Emergency_State et ST_Safety_Emergency_Diag
      en sortie, consommés par Supervision et Troubleshooting.
   🔒 Sorties physiques MaintainA/B_RQ en polarité maintien (TRUE = voie saine).
   ═══════════════════════════════════════════════════════════════
    📄 Docs : DOC/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md
              DOC/AF_Partie-03_Contrats_Composants_v2.1.md
*)

FUNCTION_BLOCK PUBLIC FB_Safety_EmergencyManagement
VAR_INPUT
    Enable              : BOOL;        // Active la surveillance
    Reset               : BOOL;        // Front acquittement défauts
    ArmRequest          : BOOL;        // Demande de réarmement (BtnEmergencyArming)
    EmergencyChainClosed      : BOOL;        // Retour physique boucle d'urgence amont contacteur
    PowerContactorEngaged     : BOOL;        // Confirmation contacteur de puissance principal
    PowerCutOffRequest  : BOOL;        // Requête de coupure logique issue des métiers
    BtnEmergencyCutOff  : BOOL;        // Commande d'ouverture d'urgence depuis l'IHM
END_VAR
VAR_OUTPUT
    Ready               : BOOL;
    Busy                : BOOL;
    Done                : BOOL;
    Error               : BOOL;
    ErrorId             : WORD;        // bit0: RedundancyTestFailed, bit1: EmergencyArmingFailed, bit3: StartupFail

    // ⚡ Sorties physiques (polarité maintien explicite)
    MaintainA_RQ        : BOOL;        // Sortie de pilotage canal A (TRUE = voie maintenue, FALSE = coupure)
    MaintainB_RQ        : BOOL;        // Sortie de pilotage canal B (TRUE = voie maintenue, FALSE = coupure)
    ArmPulse_RQ         : BOOL;        // Impulsion réarmement physique (1s)

    // 🚦 Bus d'état public (AF §8.2)
    State               : ST_Safety_Emergency_State; // ChainOk, ContactorOk, Step, Armable, ArmingBusy
    Diag                : ST_Safety_Emergency_Diag;  // Error, ErrorId, Redundancy, ArmFailed, Lockout

    // 🩺 Diagnostics scalaires (rétrocompatibilité PRG_10/GVL_Global)
    ArmingSeqStep                : INT;
    RedundancyTestFailed         : BOOL;
    EmergencyArmingFailed        : BOOL;
    EmergencyArmingLockoutActive : BOOL;
END_VAR
VAR
    // 🧱 Composition interne des sous-blocs
    Logic               : FB_Safety_EmergencyManagementLogic;
    Output              : FB_Safety_EmergencyManagementOutput;
END_VAR

// === IMPLEMENTATION ===

// 🛑 1. Appels des instances internes
Logic(
    Enable := Enable,
    Reset := Reset,
    ArmRequest := ArmRequest,
    EmergencyChainClosed := EmergencyChainClosed,
    PowerContactorEngaged := PowerContactorEngaged,
    PowerCutOffRequest := PowerCutOffRequest,
    BtnEmergencyCutOff := BtnEmergencyCutOff
);

Output(
    Enable := Enable,
    Cmd := Logic.Cmd,
    ChainOk := EmergencyChainClosed,
    ContactorOk := PowerContactorEngaged,
    ArmingStep := Logic.ArmingSeqStep,
    Armable := Logic.Armable,
    ArmingBusy := Logic.ArmingBusy,
    Error := Logic.Error,
    ErrorId := Logic.ErrorId,
    RedundancyTestFailed := Logic.RedundancyTestFailed,
    ArmFailed := Logic.EmergencyArmingFailed,
    LockoutActive := Logic.EmergencyArmingLockoutActive
);

// 📤 2. Propagation des signaux vers les sorties du bloc parent
Ready := Enable AND NOT Logic.StartupFail;
Busy  := (Logic.ArmingSeqStep <> 0) OR Logic.EmergencyArmingLockoutActive;
Done  := PowerContactorEngaged;
Error := Logic.Error;
ErrorId := Logic.ErrorId;

// ⚡ Sorties physiques
MaintainA_RQ   := Output.MaintainA_RQ;
MaintainB_RQ   := Output.MaintainB_RQ;
ArmPulse_RQ    := Output.ArmPulse_RQ;

// 🚦 Bus publics
State := Output.State;
Diag  := Output.Diag;

// 🩺 Diagnostics scalaires (rétrocompatibilité)
ArmingSeqStep                := Logic.ArmingSeqStep;
RedundancyTestFailed         := Logic.RedundancyTestFailed;
EmergencyArmingFailed        := Logic.EmergencyArmingFailed;
EmergencyArmingLockoutActive := Logic.EmergencyArmingLockoutActive;

(* =======================================================================
   📐 FB_DriftGuard — Détection de dérive de position sous armement
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Capture position de référence et détection de dérive anormale
   📄 Doc métier : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md
   🔌 Interface : Brique interne de sécurité (compose FB_Safety_Winch)
   🔒 Sécurité : Détection de mouvement non commandé et glissement
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_DriftGuard
VAR_INPUT
    // === COMMANDES ET SEUILS ===
    Arm                             : BOOL;                           // --> [CMD] Condition d'armement de la surveillance
    PositionM                       : REAL;                           // --> [HW] Position courante a surveiller (m)
    ToleranceM                      : REAL;                           // --> [CFG] Tolerance de derive maximale autorisee (m)
END_VAR
VAR_OUTPUT
    // === MESURES ET ETATS ===
    RefPosM                         : REAL;                           // <-- [DIAG] Position de reference capturee a l'armement (m)
    DriftM                          : REAL;                           // <-- [DIAG] Derive absolue courante (m)
    Violation                       : BOOL;                           // <-- [STAT] Alarme derive maximale depassee
END_VAR
VAR
    // === VARIABLES LOCALES INTERNES ===
    WasArmed                        : BOOL;                           // . [LOC] Memoire etat armement cycle precedent
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_DriftGuard) ===

IF Arm THEN
    IF NOT WasArmed THEN
        RefPosM := PositionM;   // Capture au 1er cycle armé uniquement
        WasArmed := TRUE;
    END_IF;
    DriftM := ABS(PositionM - RefPosM);
    Violation := DriftM > ToleranceM;
ELSE
    WasArmed := FALSE;
    DriftM := 0.0;
    Violation := FALSE;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   🪜 FB_SpeedStep — Décodeur palier → 4 contacteurs (1 par treuil)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-10_Fonction_Winch_v2.0.md §2, §6
   📄 Audit P0.2 : AUDIT_Winch_v1.0 (archivé) §2.2
   📥 SpeedRefPct    : consigne 0..100 % (déjà rampée en amont, ABS)
   📥 Table          : ST_SpeedStepTable propre AU TREUIL appelant
                        (M1 et M2 ont chacune la leur — pas de table globale)
   📥 MaxStepNumber  : plafond palier (1..5), borné et validé ici
   📤 Contactor1..4  : état de chaque contacteur de vitesse (BOOL individuel,
                        lu directement dans `Table.P<palier>R<relais>`)
   📤 StepNumber     : n° palier courant (0 = arrêt, 1..5)
   📤 ConfigError    : TRUE si table invalide ou MaxStepNumber hors bornes
   📤 ConfigErrorId  : WORD bitfield (bit0 = config invalide)
   🧩 Réutilisation lib Util (Partie3 §0) : HYSTERESIS pour la sélection
      de palier anti-battement — AUCUN seuil "maison" recalculé.
   ⚠️ CORRECTIF interface HYSTERESIS (2026-07-01) : `Util` 3.5.19.0 expose
      `HYSTERESIS(IN, HIGH, LOW : INT → OUT : BOOL)` (TRUE si IN < LOW,
      FALSE si IN > HIGH, maintien entre les deux) — `SpeedRefPct` (REAL)
      est converti en INT (`REAL_TO_INT`) avant appel.
   ⚠️ ÉVOLUTION (retour terrain 2026-07-01) : `StepMask` (BYTE packé) est
      remplacé par 4 sorties BOOL individuelles, lues directement dans la
      table (`P<palier>R<relais>`) — plus de bit-extraction côté FB_Winch,
      paramétrage un contacteur à la fois pendant la mise en service.
   ⚠️ Brique réduite (Partie3 §1bis) : pas d'Enable/Reset/ErrorId/State
      au sens "FB métier" — c'est un décodeur pur, composé À L'INTÉRIEUR de
      FB_Winch, qui porte lui la sécurité/le contrat complet.
      ➕ MAIS on ajoute 2 sorties locales `ConfigError` + `ConfigErrorId`
      pour signaler une table de config invalide (P0.2 audit).
   🆕 AJOUT (2026-07-03quinquies, spec descente/couple) : `MaxStepNumber` plafonne
      le palier atteignable (défaut 5 = comportement inchangé). Sert à `FB_Winch`
      pour limiter la vitesse en descente (charge entraînante, pas besoin d'aller
      vite) SANS changer la logique de décodage elle-même — juste un plafond
      appliqué APRÈS la sélection par hystérésis, avant la lecture de la table.
   🛡️ CORRECTIF P0.2 (2026-07-21) :
      - Bornage `MaxStepNumber` ∈ [1..5] dès l'entrée
      - Validation table : seuils croissants 0..100 %, hystérésis > 0,
        contacteurs cohérents (au moins 1 par palier 2..MaxStepNumber ; palier 1 tout FALSE autorisé)
      - Sortie `ConfigError` / `ConfigErrorId` (bit0 = table invalide)
      - Forçage sorties sûres (contacteurs FALSE, StepNumber=0) si erreur config
      - Reset sur front (R_TRIG) + cause disparue (conforme Partie 3 §5)
   ════════════════════════════════════════════════════════════════ *)

{attribute 'qualified_only'}
{attribute 'hide_all_locals'}

// === DECLARATION (à coller dans la partie déclaration du POU FB_SpeedStep) ===

FUNCTION_BLOCK PUBLIC FB_SpeedStep
VAR_INPUT
    Enable            : BOOL;               // Piloté par FB_Winch : FALSE = treuil à l'arrêt (palier 0)
    SpeedRefPct       : REAL;                // Consigne vitesse 0..100 % (déjà rampée par FB_Winch)
    Table             : ST_SpeedStepTable;   // Table des 5 paliers (contacteurs + seuils), propre à CE treuil
    HystMargin        : REAL := 2.0;         // Marge anti-battement (%) autour de chaque seuil
    MaxStepNumber     : INT := 5;            // 🆕 Plafond palier atteignable (1..5) — 5 = pas de restriction
    MeasuredSpeedBand : INT := 0;            // Bande vitesse réelle validée (0 = inconnue)
    SpeedGuardEnable  : BOOL := FALSE;       // 🛡️ Garde-fou palier activable après validation terrain
    SpeedGuardReady   : BOOL := FALSE;       // 🟢 Vitesse stable et conditions de passage validées
END_VAR
VAR_OUTPUT
    Contactor1        : BOOL;   // Contacteur de vitesse 1 pour le palier courant
    Contactor2        : BOOL;   // Contacteur de vitesse 2 pour le palier courant
    Contactor3        : BOOL;   // Contacteur de vitesse 3 pour le palier courant
    Contactor4        : BOOL;   // Contacteur de vitesse 4 pour le palier courant
    StepNumber        : INT;    // N° palier courant (0 = arrêt, 1..5)
    SpeedGuardLimited : BOOL;   // TRUE si le garde-fou a limité le palier demandé
    ConfigError       : BOOL;   // 🛡️ Miroir de ConfigErrorId <> 0 (config table invalide)
    ConfigErrorId     : WORD;   // 🛡️ Bitfield config : bit0 = table invalide (seuils, hyst, contacteurs)
END_VAR
VAR
    SpeedRefInt       : INT;          // Consigne convertie en INT (interface HYSTERESIS)
    Hyst1             : HYSTERESIS;   // 🧱 Lib Util — transition palier 1→2
    Hyst2             : HYSTERESIS;   // 🧱 Lib Util — transition palier 2→3
    Hyst3             : HYSTERESIS;   // 🧱 Lib Util — transition palier 3→4
    Hyst4             : HYSTERESIS;   // 🧱 Lib Util — transition palier 4→5

    // 🛡️ Validation config locale (P0.2 audit)
    _ConfigValid      : BOOL;         // Résultat validation table + MaxStepNumber
    _ConfigValidPrev  : BOOL;         // Mémoire cycle précédent pour détection front
    _ConfigErrorTrig  : R_TRIG;       // Front montant erreur config (pour reset)
    _ConfigErrorIdInt : WORD;         // Accumulateur interne défauts config
    _MaxStepClamped   : INT;          // MaxStepNumber borné [1..5]
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_SpeedStep) ===

// ─────────────────────────────────────────────────────────────────────────
// 🛡️ 0. VALIDATION CONFIGURATION (P0.2) — exécutée CHAQUE cycle pour détecter
//    toute corruption IHM/PERSISTENT, même siEnable=FALSE (sorties sûres forcée)
// ─────────────────────────────────────────────────────────────────────────

// 🔧 Bornage systématique MaxStepNumber ∈ [1..5]
IF MaxStepNumber < 1 THEN
    _MaxStepClamped := 1;
ELSIF MaxStepNumber > 5 THEN
    _MaxStepClamped := 5;
ELSE
    _MaxStepClamped := MaxStepNumber;
END_IF;

// 🔍 Validation table ST_SpeedStepTable
// Critères (Partie 9 §2 + audit P0.2) :
// 1. Seuils croissants stricts : StepThreshold_Pct[1] < [2] < [3] < [4] < [5]
// 2. Seuils dans [0..100] %
// 3. HystMargin > 0
// 4. Pour chaque palier 2.._MaxStepClamped : au moins 1 contacteur TRUE (cohérence câblage)
//    Le palier 1 peut légitimement avoir les 4 contacteurs FALSE : résistances rotoriques
//    toutes insérées = vitesse minimale. On ne valide pas les paliers jamais atteignables.
_ConfigValid := TRUE;
_ConfigErrorIdInt := 16#0000;

// Critère 1 : seuils croissants
IF NOT (Table.StepThreshold_Pct[1] < Table.StepThreshold_Pct[2] AND
        Table.StepThreshold_Pct[2] < Table.StepThreshold_Pct[3] AND
        Table.StepThreshold_Pct[3] < Table.StepThreshold_Pct[4] AND
        Table.StepThreshold_Pct[4] < Table.StepThreshold_Pct[5]) THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;  // bit0
END_IF;

// Critère 2 : seuils dans [0..100]
IF (Table.StepThreshold_Pct[1] < 0.0) OR (Table.StepThreshold_Pct[5] > 100.0) THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
END_IF;

// Critère 3 : hystérésis > 0
IF HystMargin <= 0.0 THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
END_IF;

// Critère 4 : cohérence contacteurs par palier (seulement jusqu'au plafond actif)
IF _ConfigValid THEN
    // Palier 1 : les 4 sorties FALSE sont une configuration valide de vitesse minimale.
    // Palier 2
    IF _MaxStepClamped >= 2 THEN
        IF NOT (Table.P2R1 OR Table.P2R2 OR Table.P2R3 OR Table.P2R4) THEN
            _ConfigValid := FALSE;
            _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
        END_IF;
    END_IF;
    // Palier 3
    IF _MaxStepClamped >= 3 THEN
        IF NOT (Table.P3R1 OR Table.P3R2 OR Table.P3R3 OR Table.P3R4) THEN
            _ConfigValid := FALSE;
            _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
        END_IF;
    END_IF;
    // Palier 4
    IF _MaxStepClamped >= 4 THEN
        IF NOT (Table.P4R1 OR Table.P4R2 OR Table.P4R3 OR Table.P4R4) THEN
            _ConfigValid := FALSE;
            _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
        END_IF;
    END_IF;
    // Palier 5
    IF _MaxStepClamped >= 5 THEN
        IF NOT (Table.P5R1 OR Table.P5R2 OR Table.P5R3 OR Table.P5R4) THEN
            _ConfigValid := FALSE;
            _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
        END_IF;
    END_IF;
END_IF;

// 🛡️ Gestion erreur config : front montant + reset sur front Reset (cause disparue)
// Note : pas d'entrée Reset dédiée (brique réduite) → on réarme quand config redevient valide
//        (front descendant de _ConfigValid). Conforme Partie 3 §5 : cause disparue + front.
_ConfigErrorTrig(CLK := NOT _ConfigValid);  // Front montant = apparition erreur

// Mémoire erreur config : reste TRUE tant que config invalide OU pas de réarmement
// Réarmement = front montant de _ConfigValid (cause disparue) — détecté via _ConfigValidPrev
IF _ConfigErrorTrig.Q THEN
    // Nouvelle erreur : on la mémorise
    _ConfigValidPrev := FALSE;  // Force détection front montant au cycle suivant si redevient valide
ELSIF _ConfigValid AND NOT _ConfigValidPrev THEN
    // Config redevenue valide : front montant → on efface l'erreur (reset sur front)
    _ConfigValidPrev := TRUE;
ELSIF NOT _ConfigValid THEN
    _ConfigValidPrev := FALSE;
END_IF;

// Sorties erreur config (miroir standard Partie 3)
ConfigErrorId := _ConfigErrorIdInt;
ConfigError   := (ConfigErrorId <> 16#0000);

// ─────────────────────────────────────────────────────────────────────────
// 🛑 1. GATE — Enable FALSE OU config invalide = palier 0, sorties sûres
// ─────────────────────────────────────────────────────────────────────────
IF (NOT Enable) OR (NOT _ConfigValid) THEN
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    StepNumber := 0;
    SpeedGuardLimited := FALSE;
    RETURN;
END_IF;

// ─────────────────────────────────────────────────────────────────────────
// 🪜 2. SÉLECTION DU PALIER (HYSTERESIS lib Util : IN/HIGH/LOW → OUT)
//    OUT = TRUE tant que IN < LOW (régime "bas") ; OUT bascule à FALSE une fois
//    IN > HIGH (régime "haut" confirmé) ; maintien entre LOW et HIGH (anti-battement).
//    => NOT Hyst_n.OUT = "on a franchi le seuil n vers le haut" (palier n+1 atteint).
// ─────────────────────────────────────────────────────────────────────────
SpeedRefInt := REAL_TO_INT(SpeedRefPct);

Hyst1(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[1] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[1] - HystMargin));
Hyst2(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[2] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[2] - HystMargin));
Hyst3(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[3] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[3] - HystMargin));
Hyst4(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[4] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[4] - HystMargin));

StepNumber := 1;                          // Palier mini dès qu'Enable est actif
IF NOT Hyst1.OUT THEN StepNumber := 2; END_IF;
IF NOT Hyst2.OUT THEN StepNumber := 3; END_IF;
IF NOT Hyst3.OUT THEN StepNumber := 4; END_IF;
IF NOT Hyst4.OUT THEN StepNumber := 5; END_IF;

// ─────────────────────────────────────────────────────────────────────────
// 🆕 2bis. PLAFOND (2026-07-03quinquies) — appliqué APRÈS la sélection hystérésis,
// AVANT la lecture table : le 0..100% de la consigne peut réclamer le palier 5,
// mais ne dépassera jamais _MaxStepClamped (ex. limitation couple en descente)
// ─────────────────────────────────────────────────────────────────────────
IF StepNumber > _MaxStepClamped THEN
    StepNumber := _MaxStepClamped;
END_IF;

// ─────────────────────────────────────────────────────────────────────────
// 🛡️ 2ter. GARDE-FOU VITESSE RÉELLE — limite uniquement la consigne de palier.
// Si la vitesse n'est pas validée stable, seul le palier 1 reste autorisé.
// ─────────────────────────────────────────────────────────────────────────
SpeedGuardLimited := FALSE;
IF SpeedGuardEnable THEN
    IF NOT SpeedGuardReady THEN
        IF StepNumber > 1 THEN
            StepNumber := 1;
            SpeedGuardLimited := TRUE;
        END_IF;
    ELSIF (MeasuredSpeedBand >= 1) AND (MeasuredSpeedBand <= 5) AND (StepNumber > MeasuredSpeedBand) THEN
        StepNumber := MeasuredSpeedBand;
        SpeedGuardLimited := TRUE;
    END_IF;
END_IF;

// ─────────────────────────────────────────────────────────────────────────
// 📤 3. CONTACTEURS — lus dans la table (donnée, jamais codé en dur)
//    CASE couvre explicitement 0..5 : StepNumber=0 → tous FALSE (sécurité)
// ─────────────────────────────────────────────────────────────────────────
CASE StepNumber OF
    0:  // Arrêt / config invalide / Enable=FALSE — sécurité positive
        Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    1:  Contactor1 := Table.P1R1; Contactor2 := Table.P1R2; Contactor3 := Table.P1R3; Contactor4 := Table.P1R4;
    2:  Contactor1 := Table.P2R1; Contactor2 := Table.P2R2; Contactor3 := Table.P2R3; Contactor4 := Table.P2R4;
    3:  Contactor1 := Table.P3R1; Contactor2 := Table.P3R2; Contactor3 := Table.P3R3; Contactor4 := Table.P3R4;
    4:  Contactor1 := Table.P4R1; Contactor2 := Table.P4R2; Contactor3 := Table.P4R3; Contactor4 := Table.P4R4;
    5:  Contactor1 := Table.P5R1; Contactor2 := Table.P5R2; Contactor3 := Table.P5R3; Contactor4 := Table.P5R4;
ELSE
    // Défense en profondeur : valeur StepNumber inattendue → sécurité
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    StepNumber := 0;
END_CASE;

(* ═══════════════════════════════════════════════════════════════
   📝 NOTE D'APPLICATION MANUELLE CODESYS 3.5
   ═══════════════════════════════════════════════════════════════
   1. Ouvrir le POU FB_SpeedStep dans l'arborescence CODESYS (dossier TREUILS)
   2. Copier la partie DECLARATION (lignes 33-58) dans la zone VAR_INPUT/VAR_OUTPUT/VAR
   3. Copier la partie IMPLEMENTATION (lignes 61 à fin) dans le corps ST
