TEST 'TC-P01-008 PowerCutOffRequest coupe A et B sans armer'
    (* scan 1 : autotest demarrage (1 cycle, boucle saine, contacteur repos) *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);

    (* scan 2 : regime etabli, maintien sain attendu -- +1 cycle automate (10ms) *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'hors defaut, canal A doit etre maintenu');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'hors defaut, canal B doit etre maintenu');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'pas de sequence en cours');

    (* scan 3 : coupure demandee par un metier (Winch/Translation) -- +1 cycle automate *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := TRUE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'PowerCutOffRequest doit couper le canal A');
    ASSERT_FALSE(fb.MAINTAINB_RQ, 'PowerCutOffRequest doit couper le canal B');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'PowerCutOffRequest ne doit jamais declencher une sequence armement');
END_TEST

TEST 'TC-P01-006 echec auto-test (canal colle) + TC-P01-004/009 Reset et re-latch'
    (* scans 1-2 : demarrage + regime etabli, sain *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);

    (* front ArmRequest -> ArmingSeqStep passe a 1 (TestA), boucle encore saine ce scan -- +1 cycle *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'front ArmRequest doit lancer TestA (step 1)');

    (* 200ms plus tard : le canal A est cense etre coupe, mais la boucle reste fermee -> collage *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.ERROR, 'canal colle doit lever une erreur (RedundancyTestFailed)');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'echec auto-test doit ramener la sequence a IDLE');
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'un canal colle bloque aussi le maintien normal (interlock sur Cause brute)');

    (* Reset : doit acquitter l affichage sans redemarrage auto (TC-P01-004) -- +1 cycle *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := TRUE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_FALSE(fb.ERROR, 'Reset doit effacer l affichage du defaut');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'Reset seul ne relance jamais de sequence (pas de redemarrage auto)');

    (* nouvel essai : cause toujours presente (canal toujours colle) -> doit re-alarmer (TC-P01-009) -- +1 cycle *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'un nouveau front ArmRequest doit relancer TestA');

    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.ERROR, 'cause persistante doit re-alarmer au nouvel essai, meme apres Reset');
END_TEST

(* ═══════════════════════════════════════════════════════════════
   🧲 FB_Encoder_Abs — Acquisition codeur absolu (accès bus EtherCAT)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-09_Fonction_Encoder_v2.1.md §3/§6
                   DOC/AF_Partie-03_Contrats_Composants_v2.1.md
   🎯 Accès bus EtherCAT, statut esclave, extraction positions brutes
      et séquence de Preset SDO (PresetTriggerCmd := 2).
   🧊 Principe « geler sur doute » (§6) : RawPos/AngleRaw/TurnCount
      conservent leur dernière valeur valide si EncoderAvailable = FALSE.
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Encoder_Abs) ===

FUNCTION_BLOCK PUBLIC FB_Encoder_Abs
VAR_INPUT
    Enable              : BOOL;        // Standard
    Reset               : BOOL;        // Acquittement défaut (front)
    PowerContactorEngaged     : BOOL;        // Standard
    Mode                : E_Mode;      // Standard (contexte, pas encore exploité ce lot)
    RawPosIn            : UDINT;       // Brut EtherCAT (ex. COD1_PosValue, %ID)
    AlarmsIn            : UINT;        // Brut EtherCAT (ex. COD1_Alarms)
    WarningsIn          : UINT;        // Brut EtherCAT (ex. COD1_Warnings) — informatif seulement
    SlaveOperational    : BOOL;        // FB_Diag_Ethercat — esclave EtherCAT opérationnel
    PointsPerRev        : UDINT := 8192;  // Résolution codeur confirmée (Partie10 §3.3)
    PresetRequest       : BOOL;        // Front — piloté par FB_Encoder_Homing via PRG_02_Encoders
    PresetValue         : UDINT;       // Cible brute — piloté par FB_Encoder_Homing (stub 0 ce lot)
    PresetTimeout       : TIME := T#2s;
    PresetTolerancePts  : UDINT := 10; // Tolérance relecture post-preset
END_VAR
VAR_OUTPUT
    Ready               : BOOL;
    Busy                : BOOL;
    Done                : BOOL;
    Error               : BOOL;
    ErrorId             : WORD;        // bit0: "Défaut communication codeur" - alarme/bus codeur ; bit1: "Erreur référencement (timeout)" - preset refusé/timeout
    State               : E_State;
    StateAtError        : E_State;
    RawPos              : UDINT;       // Position brute — GELÉE si EncoderAvailable=FALSE
    EncoderAvailable    : BOOL;
    AngleRaw            : UINT;        // Informatif maintenance : RawPos MOD PointsPerRev
    TurnCount           : UDINT;       // Informatif maintenance : RawPos / PointsPerRev
    PresetAck           : BOOL;        // Pulse 1 cycle — écriture confirmée
    PresetNak           : BOOL;        // Pulse 1 cycle — écriture refusée/timeout
    PresetTriggerCmd    : WORD;        // → à câbler sur COD_PresettTrigCmd (RxPDO)
    CodeSeqTriggerCmd   : WORD;        // → à câbler sur COD_CodeSeqTrigCmd (RxPDO)
    PresetValueOut      : UDINT;       // → à câbler sur COD_PresetValue (RxPDO)
END_VAR
VAR
    ResetEdge           : R_TRIG;
    ErrorEdge           : R_TRIG;
    PresetReqEdge       : R_TRIG;
    PresetTimer         : TON;
    PresetSeqStep       : INT;         // 0=IDLE, 1=pulse CodeSeq, 2=pulse Trig, 3=attente confirmation
    RawDiff             : DINT;
    PresetTimerVisual   : TON;         // Timer pour laisser le temps de voir l'impulsion (1.5s)
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Abs) ===

// 🛑 1. GATE
IF NOT Enable THEN
    EncoderAvailable := FALSE;
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    PresetTriggerCmd := 16#0000; CodeSeqTriggerCmd := 16#0000; PresetValueOut := 0;
    PresetSeqStep := 0;
    PresetTimer(IN := FALSE, PT := PresetTimeout);
    PresetTimerVisual(IN := FALSE, PT := T#500MS);
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🔍 3. DIAGNOSTIC BUS / ALARME
IF (AlarmsIn <> 0) OR NOT SlaveOperational THEN
    ErrorId := ErrorId OR 16#0001;
ELSE
    ErrorId := ErrorId AND 16#FFFE; (* Auto-clearing dès que le bus et l'esclave sont OK *)
END_IF;
EncoderAvailable := (ErrorId AND 16#0001) = 0;

// 📥 4. LECTURE POSITION — GELER SUR DOUTE (Partie10 §6)
// Si EncoderAvailable=FALSE : RawPos/AngleRaw/TurnCount conservent leur dernière valeur (pas de RETURN
// global ici pour ne pas geler aussi la séquence preset/l'état — seule la lecture est gelée).
IF EncoderAvailable THEN
    RawPos := RawPosIn;   // 🔧 2026-07-03 : sens de comptage géré côté codeur (CoE 6000h bit0,
                          // startup parameter CODESYS) — voir Partie10 §3bis. Plus de calcul ici.
    AngleRaw := UDINT_TO_UINT(RawPos MOD PointsPerRev);
    TurnCount := RawPos / PointsPerRev;
END_IF;

// 🔧 5. SÉQUENCE PRESET (écriture bus)
// ✅ Confirmé terrain (2026-07-02) : PresettTrigCmd := 2 déclenche le référencement à
//    PresetValue (valeur de commande, pas un masque de bits — corrige l'hypothèse initiale).
// 🔴 CodeSeqTrigCmd : rôle NON identifié (même par l'utilisateur/terrain) — laissé à 0,
//    PAS piloté tant que sa fonction n'est pas confirmée (fiche technique ou essai dédié).
//    Ne jamais lui donner une valeur arbitraire "au cas où".
PresetReqEdge(CLK := PresetRequest);
PresetAck := FALSE; PresetNak := FALSE; // pulses 1 cycle uniquement
CodeSeqTriggerCmd := 16#0000;           // 🔴 non piloté — rôle inconnu, voir note ci-dessus
CASE PresetSeqStep OF
    0: // IDLE
        PresetTriggerCmd := 0;
        IF PresetReqEdge.Q AND EncoderAvailable THEN
            PresetValueOut := PresetValue;
            PresetSeqStep := 1;
            PresetTimer(IN := TRUE, PT := PresetTimeout);
        END_IF;
    1: // Déclenchement preset (laissé actif pendant 0.5s pour confort visuel en simulation/bus)
        PresetTriggerCmd := 2;   // ✅ Valeur confirmée terrain — référence le codeur à PresetValueOut
        RawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(PresetValueOut);
        IF ABS(RawDiff) <= UDINT_TO_DINT(PresetTolerancePts) THEN
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := TRUE, PT := T#500MS);
            IF PresetTimerVisual.Q THEN
                PresetTriggerCmd := 0;
                PresetAck := TRUE;
                PresetSeqStep := 0;
                PresetTimerVisual(IN := FALSE, PT := T#500MS);
            END_IF;
        ELSIF PresetTimer.Q THEN
            PresetTriggerCmd := 0;
            PresetNak := TRUE;
            ErrorId := ErrorId OR 16#0002;
            PresetSeqStep := 0;
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := FALSE, PT := T#500MS);
        END_IF;
END_CASE;
IF ResetEdge.Q AND (PresetSeqStep = 0) THEN
    ErrorId := ErrorId AND 16#FFFD;
END_IF;

// 🧾 6. ERROR / STATEATERROR
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

Busy := (PresetSeqStep <> 0);
Done := PresetAck;

FUNCTION_BLOCK PUBLIC FB_SafetyValidation
VAR_INPUT
    Start                      : BOOL;        // Commande de démarrage des tests
    Abort                      : BOOL;        // Commande d'abandon
    CaseId                     : INT;         // 0=tous ; 1..3=cas ciblé
END_VAR
VAR_OUTPUT
    Busy                       : BOOL;
    Done                       : BOOL;
    AnyFailed                  : BOOL;
    SimGateOk                  : BOOL;        // Indique si la simulation est autorisée
    ActiveStimulusId           : INT;
    StepElapsed                : TIME;
    Report                     : ST_TestSuiteReport;
    TerminalState              : E_TestTerminalState;
    ConfigError                : BOOL;
    ConfigErrorStepId          : INT;
    ConfigErrorCheckIdx        : INT;
    ErrorCode                  : INT;
    ErrorMessage               : STRING(160);
END_VAR
VAR CONSTANT
    // 🏷️ Index des sondes
    SigHealthyIdle                  : INT := 1;
    SigEmergencyStopOk              : INT := 2;
    SigArmingSeqStep                : INT := 3;
    SigPowerCutOffAny               : INT := 4;
    SigRedundancyFailed             : INT := 5;
    SigEmergencyArmingFailed        : INT := 6;
    SigEmergencyArmingLockoutActive : INT := 7;
    SigStopwatchMs                  : INT := 8;
    SigErrorId                      : INT := 9;
    SigOrderABOk                    : INT := 10; // ✅ Chk gagné #3 (§7.4.2) : canal A coupé avant canal B
    SigEdgeCountOk                  : INT := 11; // ✅ Chk gagné #4 (§7.4.2) : exactement 2 chutes EmergencyChain

    // 🪜 Index des étapes
    StepTc01Setup                   : INT := 10;
    StepTc01Arm                     : INT := 11;
    StepTc01Confirm                 : INT := 14;
    StepTc01Trip                    : INT := 15;
    StepTc01Instant                 : INT := 16;
    StepTc01Latch                   : INT := 17;
    StepTc01Teardown                : INT := 19;

    StepTc02Setup                   : INT := 20;
    StepTc02Redundancy              : INT := 21;
    StepTc02Teardown                : INT := 29;

    StepTc03Setup                   : INT := 30;
    StepTc03ResetRelease            : INT := 31;
    StepTc03LockoutWindow           : INT := 32;
    StepTc03LockoutEnd              : INT := 34;
    StepTc03PostReArm               : INT := 35;
    StepTc03Teardown                : INT := 39;
END_VAR
VAR
    // ⚙️ Moteur unique
    Sequencer                  : FB_TestSequencer;

    // 📋 Tables de configuration
    StepTable                  : ARRAY[1..GVL_PLC_Tests_Const.MaxSteps]      OF ST_TestStepConfig;
    CheckTable                 : ARRAY[1..GVL_PLC_Tests_Const.MaxChecks]     OF ST_TestCheckConfig;
    CaseTable                  : ARRAY[1..GVL_PLC_Tests_Const.MaxTestCases]  OF ST_TestCaseConfig;
    InvariantTable             : ARRAY[1..GVL_PLC_Tests_Const.MaxInvariants] OF ST_TestInvariantConfig;

    // 📥 Banque de sondes
    ProbeBool                  : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeBool]  OF BOOL;
    ProbeDint                  : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeDint]  OF DINT;
    ProbeReal                  : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeReal]  OF REAL;

    // 🛠️ Configuration initialisée
    TableReady                 : BOOL := FALSE;

    // 🛠️ Instruments de mesure
    instStopwatch              : FB_TestStopwatch;
    instOrderAB                : FB_TestEventOrder;  // ✅ Chk gagné #3 : canal A avant canal B
    instEdgeCountChain         : FB_TestEdgeCounter;  // ✅ Chk gagné #4 : exactement 2 chutes

    // ⚡ Commandes de stimuli affectées dans le CASE
    ArmRequest                 : BOOL;
    ResetFaults                : BOOL;
END_VAR
// === IMPLEMENTATION ===
// 1. 🛡️ GATE
IF NOT GVL_Simulation.SimulationModeActive THEN
    // Abort interne immédiat
    Sequencer(Start := FALSE, Abort := TRUE, CaseId := CaseId,
              StepTable := StepTable, CheckTable := CheckTable, CaseTable := CaseTable, InvariantTable := InvariantTable,
              ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal, Report := Report);
              
    GVL_PLC_Tests.OverrideChainTrue := FALSE;
    GVL_PLC_Tests.OverrideChainFalse := FALSE;
    GVL_PLC_Tests.OverrideContactorFalse := FALSE;
    ArmRequest := FALSE;
    ResetFaults := FALSE;
    SimGateOk := FALSE;
    RETURN;
END_IF;

// La chaîne d'urgence physique ne doit pas être en mode simulation réelle active (sécurité matérielle)
SimGateOk := NOT GVL_Simulation.SensorEmergencyStopChainIsReal;

// 2. 📋 TABLES (Remplissage déclaratif unique)
IF NOT TableReady THEN
    Report.Name := 'Safety Validation'; // 🏷️ Identifie la suite (SuiteSafetyValidation) sans ambiguïté

    // Cas de tests
    CaseTable[1].Name := 'TC-01 Armement nominal';
    CaseTable[1].FirstStep := StepTc01Setup;

    CaseTable[2].Name := 'TC-02 Redondance';
    CaseTable[2].FirstStep := StepTc02Setup;

    CaseTable[3].Name := 'TC-03 Lockout temporel';
    CaseTable[3].FirstStep := StepTc03Setup;

    // ─────────────────────────────────────────────────────────────
    // 🛡️ INVARIANT DE NON-RÉGRESSION (§7.5.4) — verrouille le correctif du défaut connu
    // (EmergencyArmingLockoutActive posé aussi sur la branche succès). Armé DÈS la
    // confirmation d'armement TC-01, désarmé à l'entrée de TC-02 (portée = le case TC-01
    // uniquement — TC-03 active volontairement le lockout, il ne doit pas être vu comme
    // une violation, d'où le désarmement avant d'y arriver).
    // ─────────────────────────────────────────────────────────────
    InvariantTable[1].Check.Kind := E_TestCheckKind.BOOL_EQUAL;
    InvariantTable[1].Check.ProbeIdx := SigEmergencyArmingLockoutActive;
    InvariantTable[1].Check.ExpectedBool := FALSE;
    InvariantTable[1].ArmAtStepId := StepTc01Confirm;
    InvariantTable[1].DisarmAtStepId := StepTc02Setup;

    // ─────────────────────────────────────────────────────────────
    // CONFIGURATION DES CHECKS (CheckTable)
    // ─────────────────────────────────────────────────────────────
    // Chk 1: Attente état sain (HealthyIdle = TRUE)
    CheckTable[1].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[1].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[1].ProbeIdx := SigHealthyIdle;
    CheckTable[1].ExpectedBool := TRUE;

    // Chk 2: Attente armement étape 5
    CheckTable[2].Kind := E_TestCheckKind.DINT_EQUAL;
    CheckTable[2].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[2].ProbeIdx := SigArmingSeqStep;
    CheckTable[2].ExpectedDint := 5;

    // Chk 3: Attente front montant de confirmation AU
    CheckTable[3].Kind := E_TestCheckKind.BOOL_RISING;
    CheckTable[3].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL; // Sera déclenché sur front
    CheckTable[3].ProbeIdx := SigEmergencyStopOk;

    // Chk 4: Fin de l'impulsion (étape 0)
    CheckTable[4].Kind := E_TestCheckKind.DINT_EQUAL;
    CheckTable[4].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[4].ProbeIdx := SigArmingSeqStep;
    CheckTable[4].ExpectedDint := 0;

    // Chk 5: Confirmation AU Ok
    CheckTable[5].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[5].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[5].ProbeIdx := SigEmergencyStopOk;
    CheckTable[5].ExpectedBool := TRUE;

    // Chk 6: Coupure franche (PowerCutOff = TRUE)
    // 🔧 REX 2026-07-17 : CHECK_INSTANT n'évalue qu'une fois, au front montant d'Evaluate
    // (voir FB_TestCheck.st) -- soit le tout 1er scan de l'étape Trip, AVANT que PRG_00_Inputs
    // applique le override OverrideContactorFalse (appliqué APRÈS l'appel instTestsManagement()
    // dans PRG_00_Inputs.st). Le check voyait donc systématiquement la valeur d'avant le trigger.
    // CHECK_WAIT_UNTIL retente chaque scan -> tolère ce décalage d'1 scan structurel.
    CheckTable[6].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[6].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[6].ProbeIdx := SigPowerCutOffAny;
    CheckTable[6].ExpectedBool := TRUE;

    // Chk 7: AU désactivé
    CheckTable[7].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[7].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[7].ProbeIdx := SigEmergencyStopOk;
    CheckTable[7].ExpectedBool := FALSE;

    // Chk 8: Maintien de la coupure (Latch) avec stabilité 500ms
    CheckTable[8].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[8].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[8].ProbeIdx := SigPowerCutOffAny;
    CheckTable[8].ExpectedBool := TRUE;
    CheckTable[8].StablePT := T#500ms;

    // Chk 9: Détection défaut de redondance
    CheckTable[9].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[9].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[9].ProbeIdx := SigRedundancyFailed;
    CheckTable[9].ExpectedBool := TRUE;

    // Chk 10: Fin réarmement (étape 0) après défaut
    CheckTable[10].Kind := E_TestCheckKind.DINT_EQUAL;
    CheckTable[10].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[10].ProbeIdx := SigArmingSeqStep;
    CheckTable[10].ExpectedDint := 0;

    // Chk 11: Temps de réaction dans la fenêtre [180ms, 260ms]
    CheckTable[11].Kind := E_TestCheckKind.REAL_IN_RANGE;
    CheckTable[11].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[11].ProbeIdx := SigStopwatchMs;
    CheckTable[11].RealMin := 180.0;
    CheckTable[11].RealMax := 260.0;

    // Chk 12: Pas d'erreur parasite (sauf bit 0)
    CheckTable[12].Kind := E_TestCheckKind.WORD_MASK_NONE;
    CheckTable[12].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[12].ProbeIdx := SigErrorId;
    CheckTable[12].Mask := NOT 16#0001; // Tout sauf bit de redondance

    // Chk 13: Échec armement (EmergencyArmingFailed = TRUE)
    CheckTable[13].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[13].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[13].ProbeIdx := SigEmergencyArmingFailed;
    CheckTable[13].ExpectedBool := TRUE;

    // Chk 14: Verrouillage actif (Lockout = TRUE)
    CheckTable[14].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[14].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[14].ProbeIdx := SigEmergencyArmingLockoutActive;
    CheckTable[14].ExpectedBool := TRUE;

    // Chk 15: Interdiction de démarrer pendant Lockout
    CheckTable[15].Kind := E_TestCheckKind.DINT_NOT_EQUAL;
    CheckTable[15].Mode := E_TestCheckMode.CHECK_NEVER_DURING;
    CheckTable[15].ProbeIdx := SigArmingSeqStep;
    CheckTable[15].ExpectedDint := 0;

    // Chk 16: Fin du verrouillage
    CheckTable[16].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[16].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[16].ProbeIdx := SigEmergencyArmingLockoutActive;
    CheckTable[16].ExpectedBool := FALSE;

    // Chk 17: ✅ Chk gagné #3 (§7.4.2) — canal A coupé AVANT canal B pendant l'auto-test
    CheckTable[17].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[17].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[17].ProbeIdx := SigOrderABOk;
    CheckTable[17].ExpectedBool := TRUE;

    // Chk 18: ✅ Chk gagné #4 (§7.4.2) — exactement 2 chutes d'EmergencyChain (1 par canal testé)
    CheckTable[18].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[18].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[18].ProbeIdx := SigEdgeCountOk;
    CheckTable[18].ExpectedBool := TRUE;

    // ─────────────────────────────────────────────────────────────
    // CONFIGURATION DES ÉTAPES (StepTable)
    // ─────────────────────────────────────────────────────────────
    // --- SCÉNARIO 1 ---
    StepTable[StepTc01Setup].Name := 'TC01 Setup saine';
    StepTable[StepTc01Setup].CaseId := 1;
    StepTable[StepTc01Setup].StimulusId := 1; // Reset défauts
    StepTable[StepTc01Setup].CheckIdx[1] := 1;
    StepTable[StepTc01Setup].TimeoutPT := T#12s;
    StepTable[StepTc01Setup].NextOnPass := StepTc01Arm;
    StepTable[StepTc01Setup].NextOnFail := StepTc01Teardown;
    StepTable[StepTc01Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc01Arm].Name := 'TC01 Armement seq';
    StepTable[StepTc01Arm].CaseId := 1;
    StepTable[StepTc01Arm].StimulusId := 2; // ArmRequest := TRUE
    StepTable[StepTc01Arm].CheckIdx[1] := 2;
    StepTable[StepTc01Arm].CheckIdx[2] := 3;
    StepTable[StepTc01Arm].CheckIdx[3] := 17; // ✅ Chk gagné #3 : ordre A avant B
    StepTable[StepTc01Arm].CheckIdx[4] := 18; // ✅ Chk gagné #4 : exactement 2 chutes
    StepTable[StepTc01Arm].TimeoutPT := T#10s;
    StepTable[StepTc01Arm].NextOnPass := StepTc01Confirm;
    StepTable[StepTc01Arm].NextOnFail := StepTc01Teardown;
    StepTable[StepTc01Arm].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc01Confirm].Name := 'TC01 Confirm armé';
    StepTable[StepTc01Confirm].CaseId := 1;
    StepTable[StepTc01Confirm].StimulusId := 0; // Relâcher bouton
    StepTable[StepTc01Confirm].CheckIdx[1] := 4;
    StepTable[StepTc01Confirm].CheckIdx[2] := 5;
    StepTable[StepTc01Confirm].TimeoutPT := T#10s;
    StepTable[StepTc01Confirm].NextOnPass := StepTc01Trip;
    StepTable[StepTc01Confirm].NextOnFail := StepTc01Teardown;
    StepTable[StepTc01Confirm].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc01Trip].Name := 'TC01 Trip urg AU';
    StepTable[StepTc01Trip].CaseId := 1;
    StepTable[StepTc01Trip].StimulusId := 3; // AU simulé (OverrideChainFalse := TRUE)
    StepTable[StepTc01Trip].CheckIdx[1] := 6;
    StepTable[StepTc01Trip].TimeoutPT := T#10s;
    StepTable[StepTc01Trip].NextOnPass := StepTc01Instant;
    StepTable[StepTc01Trip].NextOnFail := StepTc01Teardown;
    StepTable[StepTc01Trip].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc01Instant].Name := 'TC01 Coupure inst';
    StepTable[StepTc01Instant].CaseId := 1;
    StepTable[StepTc01Instant].StimulusId := 3; // Reste appuyé
    StepTable[StepTc01Instant].CheckIdx[1] := 7;
    StepTable[StepTc01Instant].TimeoutPT := T#10s;
    StepTable[StepTc01Instant].NextOnPass := StepTc01Latch;
    StepTable[StepTc01Instant].NextOnFail := StepTc01Teardown;
    StepTable[StepTc01Instant].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc01Latch].Name := 'TC01 Auto-maintien';
    StepTable[StepTc01Latch].CaseId := 1;
    StepTable[StepTc01Latch].StimulusId := 0; // Relâcher AU
    StepTable[StepTc01Latch].CheckIdx[1] := 8; // Stable 500ms
    StepTable[StepTc01Latch].TimeoutPT := T#10s;
    StepTable[StepTc01Latch].NextOnPass := StepTc02Setup; // Cas suivant
    StepTable[StepTc01Latch].NextOnFail := StepTc01Teardown;
    StepTable[StepTc01Latch].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc01Teardown].Name := 'TC01 Teardown';
    StepTable[StepTc01Teardown].CaseId := 1;
    StepTable[StepTc01Teardown].StimulusId := 1; // Nettoyage & Reset
    StepTable[StepTc01Teardown].CheckIdx[1] := 1;
    StepTable[StepTc01Teardown].TimeoutPT := T#12s;
    StepTable[StepTc01Teardown].NextOnPass := StepTc02Setup;
    StepTable[StepTc01Teardown].NextOnFail := StepTc02Setup;
    StepTable[StepTc01Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    // --- SCÉNARIO 2 ---
    StepTable[StepTc02Setup].Name := 'TC02 Setup saine';
    StepTable[StepTc02Setup].CaseId := 2;
    StepTable[StepTc02Setup].StimulusId := 1;
    StepTable[StepTc02Setup].CheckIdx[1] := 1;
    StepTable[StepTc02Setup].TimeoutPT := T#12s;
    StepTable[StepTc02Setup].NextOnPass := StepTc02Redundancy;
    StepTable[StepTc02Setup].NextOnFail := StepTc02Teardown;
    StepTable[StepTc02Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc02Redundancy].Name := 'TC02 Defaut redond';
    StepTable[StepTc02Redundancy].CaseId := 2;
    StepTable[StepTc02Redundancy].StimulusId := 4; // Contact soudé (OverrideChainTrue := TRUE) + Arm
    StepTable[StepTc02Redundancy].CheckIdx[1] := 9;  // RedundancyFailed := TRUE
    StepTable[StepTc02Redundancy].CheckIdx[2] := 10; // ArmingSeqStep := 0
    StepTable[StepTc02Redundancy].CheckIdx[3] := 11; // Durée dans [180ms, 260ms]
    StepTable[StepTc02Redundancy].CheckIdx[4] := 12; // Pas d'erreur parasite
    StepTable[StepTc02Redundancy].TimeoutPT := T#10s;
    StepTable[StepTc02Redundancy].NextOnPass := StepTc02Teardown;
    StepTable[StepTc02Redundancy].NextOnFail := StepTc02Teardown;
    StepTable[StepTc02Redundancy].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc02Teardown].Name := 'TC02 Teardown';
    StepTable[StepTc02Teardown].CaseId := 2;
    StepTable[StepTc02Teardown].StimulusId := 1;
    StepTable[StepTc02Teardown].CheckIdx[1] := 1;
    StepTable[StepTc02Teardown].TimeoutPT := T#12s;
    StepTable[StepTc02Teardown].NextOnPass := StepTc03Setup;
    StepTable[StepTc02Teardown].NextOnFail := StepTc03Setup;
    StepTable[StepTc02Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    // --- SCÉNARIO 3 ---
    StepTable[StepTc03Setup].Name := 'TC03 Reset initial';
    StepTable[StepTc03Setup].CaseId := 3;
    StepTable[StepTc03Setup].StimulusId := 9; // Reset seul, aucune demande d'armement
    StepTable[StepTc03Setup].CheckIdx[1] := 1;
    StepTable[StepTc03Setup].TimeoutPT := T#3s;
    StepTable[StepTc03Setup].NextOnPass := StepTc03ResetRelease;
    StepTable[StepTc03Setup].NextOnFail := StepTc03Teardown;
    StepTable[StepTc03Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc03ResetRelease].Name := 'TC03 Front arm panne';
    StepTable[StepTc03ResetRelease].CaseId := 3;
    StepTable[StepTc03ResetRelease].StimulusId := 5; // Reset relâché + contacteur bloqué + front Arm
    StepTable[StepTc03ResetRelease].CheckIdx[1] := 13;
    StepTable[StepTc03ResetRelease].CheckIdx[2] := 14;
    StepTable[StepTc03ResetRelease].TimeoutPT := T#10s;
    StepTable[StepTc03ResetRelease].NextOnPass := StepTc03LockoutWindow;
    StepTable[StepTc03ResetRelease].NextOnFail := StepTc03Teardown;
    StepTable[StepTc03ResetRelease].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc03LockoutWindow].Name := 'TC03 Lockout cmd ign';
    StepTable[StepTc03LockoutWindow].CaseId := 3;
    StepTable[StepTc03LockoutWindow].StimulusId := 6; // Force armement pendant lockout
    StepTable[StepTc03LockoutWindow].CheckIdx[1] := 15; // ArmingSeqStep reste à 0 (NEVER_DURING)
    StepTable[StepTc03LockoutWindow].TimeoutPT := T#4800ms;
    StepTable[StepTc03LockoutWindow].NextOnPass := StepTc03LockoutEnd;
    StepTable[StepTc03LockoutWindow].NextOnFail := StepTc03Teardown;
    StepTable[StepTc03LockoutWindow].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc03LockoutEnd].Name := 'TC03 Attente fin lockout';
    StepTable[StepTc03LockoutEnd].CaseId := 3;
    StepTable[StepTc03LockoutEnd].StimulusId := 7; // Relâcher contacteur
    StepTable[StepTc03LockoutEnd].CheckIdx[1] := 16; // LockoutActive := FALSE
    StepTable[StepTc03LockoutEnd].TimeoutPT := T#2s;
    StepTable[StepTc03LockoutEnd].NextOnPass := StepTc03PostReArm;
    StepTable[StepTc03LockoutEnd].NextOnFail := StepTc03Teardown;
    StepTable[StepTc03LockoutEnd].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc03PostReArm].Name := 'TC03 Re-armement nominal';
    StepTable[StepTc03PostReArm].CaseId := 3;
    StepTable[StepTc03PostReArm].StimulusId := 8; // Armement nominal après fin lockout
    StepTable[StepTc03PostReArm].CheckIdx[1] := 5; // EmergencyStopOk := TRUE
    StepTable[StepTc03PostReArm].TimeoutPT := T#5s;
    StepTable[StepTc03PostReArm].NextOnPass := 0; // Fin de la suite
    StepTable[StepTc03PostReArm].NextOnFail := StepTc03Teardown;
    StepTable[StepTc03PostReArm].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc03Teardown].Name := 'TC03 Teardown';
    StepTable[StepTc03Teardown].CaseId := 3;
    StepTable[StepTc03Teardown].StimulusId := 1;
    StepTable[StepTc03Teardown].CheckIdx[1] := 1;
    StepTable[StepTc03Teardown].TimeoutPT := T#12s;
    StepTable[StepTc03Teardown].NextOnPass := 0;
    StepTable[StepTc03Teardown].NextOnFail := 0;
    StepTable[StepTc03Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    TableReady := TRUE;
END_IF;

// 3. 📥 ACQUIRE
ProbeBool[SigHealthyIdle] := NOT PRG_10_Outputs.instSafetyEmergencyManagement.RedundancyTestFailed AND 
                             NOT PRG_10_Outputs.instSafetyEmergencyManagement.EmergencyArmingFailed AND
                             NOT PRG_10_Outputs.instSafetyEmergencyManagement.EmergencyArmingLockoutActive;

ProbeBool[SigEmergencyStopOk] := PRG_00_Inputs.EmergencyStopOk;
ProbeDint[SigArmingSeqStep] := PRG_10_Outputs.instSafetyEmergencyManagement.ArmingSeqStep;
ProbeBool[SigPowerCutOffAny] := NOT PRG_00_Inputs.EmergencyStopOk;
ProbeBool[SigRedundancyFailed] := PRG_10_Outputs.instSafetyEmergencyManagement.RedundancyTestFailed;
ProbeBool[SigEmergencyArmingFailed] := PRG_10_Outputs.instSafetyEmergencyManagement.EmergencyArmingFailed;
ProbeBool[SigEmergencyArmingLockoutActive] := PRG_10_Outputs.instSafetyEmergencyManagement.EmergencyArmingLockoutActive;
ProbeReal[SigStopwatchMs] := DINT_TO_REAL(instStopwatch.ElapsedMs);
ProbeDint[SigErrorId] := WORD_TO_DINT(PRG_10_Outputs.instSafetyEmergencyManagement.ErrorId);
ProbeBool[SigOrderABOk] := instOrderAB.OrderOk;
ProbeBool[SigEdgeCountOk] := instEdgeCountChain.InRange;

// Liaison des instruments de mesure
instStopwatch(
    Arm := (Sequencer.ActiveStimulusId = 4),
    StartEvent := (PRG_10_Outputs.instSafetyEmergencyManagement.ArmingSeqStep = 1),
    StopEvent := PRG_10_Outputs.instSafetyEmergencyManagement.RedundancyTestFailed,
    ExpectedMinMs := 180,
    ExpectedMaxMs := 260
);

// ✅ Chk gagné #3 : canal A coupé avant canal B (armé pendant tout l'auto-test TC-01,
// stimulus 2 = demande d'armement). EventA/B = front montant de "NOT PowerCutOff_X_RQ",
// c'est-à-dire le moment où le canal RETOMBE (auto-test ForceTestA/B de la Logic).
instOrderAB(
    Arm := (Sequencer.ActiveStimulusId = 2),
    EventA := NOT PowerCutOff_A_RQ,
    EventB := NOT PowerCutOff_B_RQ,
    TimeoutPT := T#10s
);

// ✅ Chk gagné #4 : exactement 2 chutes d'EmergencyChain pendant le même auto-test
// (1 pour le test canal A, 1 pour le test canal B — 3 = rebond, 1 = canal non testé)
instEdgeCountChain(
    Arm := (Sequencer.ActiveStimulusId = 2),
    Signal := PRG_00_Inputs.EmergencyChain,
    CountRising := FALSE,
    ExpectedMin := 2,
    ExpectedMax := 2
);

// 4. ⚙️ MOTEUR
Sequencer(
    Start := Start,
    Abort := Abort,
    CaseId := CaseId,
    StepTable := StepTable,
    CheckTable := CheckTable,
    CaseTable := CaseTable,
    InvariantTable := InvariantTable,
    ProbeBool := ProbeBool,
    ProbeDint := ProbeDint,
    ProbeReal := ProbeReal,
    Report := Report,
    Busy => Busy,
    Done => Done,
    AnyFailed => AnyFailed,
    TerminalState => TerminalState,
    ConfigError => ConfigError,
    ConfigErrorStepId => ConfigErrorStepId,
    ConfigErrorCheckIdx => ConfigErrorCheckIdx,
    ErrorCode => ErrorCode,
    ErrorMessage => ErrorMessage,
    ActiveStimulusId => ActiveStimulusId,
    StepElapsed => StepElapsed
);

// 5. ⚡ STIMULI
CASE ActiveStimulusId OF
    0: // 🔓 Neutre (tout relâché)
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := FALSE;
        ArmRequest := FALSE;
        ResetFaults := FALSE;

    1: // Reset défauts, attente saine
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := FALSE;
        ArmRequest := FALSE;
        ResetFaults := TRUE;

    2: // TC-01 : Demande d'armement nominal
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := FALSE;
        ArmRequest := TRUE;
        ResetFaults := FALSE;

    3: // TC-01 : Coupure franche (AU pressé)
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := TRUE;
        // 🔧 REX 2026-07-16 : OverrideChainFalse seul a 1 scan de retard (instSimSafety lu
        // AVANT instTestsManagement() dans PRG_00_Inputs.st) — incompatible avec le check 6
        // en CHECK_INSTANT. OverrideContactorFalse force EmergencyStopOk directement et
        // tardivement (après instTestsManagement()) → effet le même scan.
        GVL_PLC_Tests.OverrideContactorFalse := TRUE;
        ArmRequest := FALSE;
        ResetFaults := FALSE;

    4: // TC-02 : Contact soudé canal A (OverrideChainTrue) + Armement
        GVL_PLC_Tests.OverrideChainTrue := TRUE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := FALSE;
        ArmRequest := TRUE;
        ResetFaults := FALSE;

    5: // TC-03 : contacteur bloqué ouvert + front d'armement, reset relâché
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := TRUE;
        ArmRequest := TRUE;
        ResetFaults := FALSE;

    6: // TC-03 : Tentative armement pendant lockout
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := TRUE;
        ArmRequest := TRUE;
        ResetFaults := FALSE;

    7: // TC-03 : Relâchement contacteur bloqueur + reset
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := FALSE;
        ArmRequest := FALSE;
        ResetFaults := TRUE;

    8: // TC-03 : Réarmement nominal post-lockout
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := FALSE;
        ArmRequest := TRUE;
        ResetFaults := FALSE;

    9: // TC-03 : reset initial seul, front distinct de l'armement
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := FALSE;
        ArmRequest := FALSE;
        ResetFaults := TRUE;
END_CASE;

// Recopie IHM/métier
IF Busy THEN
    GVL_IHM.Modes.Cmd.BtnEmergencyArming := ArmRequest;
    GVL_IHM.Modes.Cmd.BtnFaultReset  := ResetFaults;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   📡 FB_AcquisitionRouter — Sélecteur atomique Réel / Simulé
   ───────────────────────────────────────────────────────────────
   📄 AF06 §2, AF13 §2
   🎯 Reprend strictement le comportement d'aiguillage historique :
      un domaine entier est réel ou simulé, jamais un mélange.
   🛡️ Ce FB ne qualifie ni polarité, ni safety, ni autorisation.
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK FB_AcquisitionRouter
VAR_INPUT
    HwReal : ST_HardwareImage;
    HwSim : ST_HardwareImage;
    SimulationModeActive : BOOL;
    SimWinchActive : BOOL;
    SimTranslationActive : BOOL;
    SimOperatorActive : BOOL;
    SimMachineActive : BOOL;
END_VAR
VAR_OUTPUT
    HwIn : ST_HardwareImage;
    WinchInputSourceChanged : BOOL;
END_VAR
VAR
    WinchInputSourceSimulated : BOOL;
    PreviousWinchInputSourceSimulated : BOOL;
    WinchInputSourceInitialized : BOOL;
END_VAR

(* Le premier cycle mémorise la source sans générer de faux front. *)
WinchInputSourceSimulated := SimulationModeActive AND SimWinchActive;
IF NOT WinchInputSourceInitialized THEN
    PreviousWinchInputSourceSimulated := WinchInputSourceSimulated;
    WinchInputSourceInitialized := TRUE;
    WinchInputSourceChanged := FALSE;
ELSE
    WinchInputSourceChanged := WinchInputSourceSimulated <> PreviousWinchInputSourceSimulated;
    PreviousWinchInputSourceSimulated := WinchInputSourceSimulated;
END_IF;

(* Sélection atomique par domaine : aucune fusion réel/simulation. *)
IF WinchInputSourceSimulated THEN
    HwIn.Winch := HwSim.Winch;
ELSE
    HwIn.Winch := HwReal.Winch;
END_IF;

IF SimulationModeActive AND SimTranslationActive THEN
    HwIn.Translation := HwSim.Translation;
ELSE
    HwIn.Translation := HwReal.Translation;
END_IF;

IF SimulationModeActive AND SimOperatorActive THEN
    HwIn.Operator := HwSim.Operator;
ELSE
    HwIn.Operator := HwReal.Operator;
END_IF;

IF SimulationModeActive AND SimMachineActive THEN
    HwIn.Machine := HwSim.Machine;
ELSE
    HwIn.Machine := HwReal.Machine;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   🔄 FB_CycleIhmBridge — Frontière IHM du séquenceur Cycle
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF_Partie-04_Mode_SemiAuto_Sequenceur_v2.0.md §1/3
   🎯 Rôle : transforme les commandes IHM impulsionnelles et les réglages
      Cycle en entrées explicites du FB_Cycle.
   🛡️ Sécurité : l'homme-mort ne mémorise aucune permission; son relâchement
      force CycleMotionPermit à FALSE. Ce FB ne produit aucune sortie physique.
   🧩 Dépendances : ST_CycleCmd, E_Mode, FB_Cycle.
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK FB_CycleIhmBridge
VAR_INPUT
    Mode                : E_Mode; (* Mode déjà arbitré par FB_Modes *)
    DeadmanArmed        : BOOL;   (* TRUE = homme-mort armé *)
    AxisCmdYStartStop   : BOOL;   (* TRUE = intention verticale maintenue *)
    SetDepthM           : REAL;   (* m, consigne IHM de profondeur *)
    SetOffsetM          : REAL;   (* m, consigne IHM fermeture benne *)
    SelectedTargetNum   : INT;    (* 2=P2, 3=P1 *)
END_VAR
VAR_IN_OUT
    CycleCmd            : ST_CycleCmd; (* Commandes IHM consommées sur ce scan *)
END_VAR
VAR_OUTPUT
    CycleEnable                 : BOOL; (* TRUE seulement en SEMI_AUTO *)
    CycleMotionPermit           : BOOL; (* homme-mort + intention verticale présents *)
    StartCycle                  : BOOL; (* impulsion Start consommée *)
    PauseCycle                  : BOOL; (* impulsion Pause consommée *)
    AbortCycle                  : BOOL; (* impulsion Abort consommée *)
    ResetCycle                  : BOOL; (* impulsion Reset Cycle, distincte défaut machine *)
    SetDepthMOut                : REAL; (* m *)
    SetOffsetMOut               : REAL; (* m *)
    SelectedTargetNumOut        : INT;  (* 2=P2, 3=P1 *)
    SpeedMismatchThresholdMps   : REAL; (* m/s; 0 = surveillance non configurée *)
    SpeedMismatchTimeout        : TIME; (* 0 = surveillance non configurée *)
END_VAR
VAR CONSTANT
    CST_SpeedMismatchThresholdMps : REAL := 0.0;  (* T43 provisoirement désactivé *)
    CST_SpeedMismatchTimeout      : TIME := T#0ms; (* T43 provisoirement désactivé *)
END_VAR

// 🎚️ Les Modes autorisent; ce bridge ne porte aucune interdiction métier.
CycleEnable := (Mode = E_Mode.SEMI_AUTO);

// 🕹️ L'homme-mort reste une intention maintenue, jamais une autorisation mémorisée.
CycleMotionPermit := DeadmanArmed AND AxisCmdYStartStop;

// 🔘 Capture avant remise à zéro : GVL_IHM est RETAIN et doit donc rester impulsionnelle.
StartCycle := CycleCmd.BtnStart;
PauseCycle := CycleCmd.BtnPause;
AbortCycle := CycleCmd.BtnAbort;
ResetCycle := CycleCmd.BtnReset;

SetDepthMOut := SetDepthM;
SetOffsetMOut := SetOffsetM;
SelectedTargetNumOut := SelectedTargetNum;
SpeedMismatchThresholdMps := CST_SpeedMismatchThresholdMps;
SpeedMismatchTimeout := CST_SpeedMismatchTimeout;

// 🧹 Une commande IHM est consommée une fois, sans modifier l'état ni l'étape Cycle.
CycleCmd.BtnStart := FALSE;
CycleCmd.BtnPause := FALSE;
CycleCmd.BtnAbort := FALSE;
CycleCmd.BtnReset := FALSE;

(* ═══════════════════════════════════════════════════════════════
   🛡️ FB_Safety_EmergencyManagementLogic — Décision & Séquencement
   ───────────────────────────────────────────────────────────────
   📄 Rôle : Gère la machine d'état d'auto-test et de réarmement de
      la boucle d'arrêt d'urgence. Produit les consignes logiques
      et les bus d'état/diagnostic.
   🔒 Polarité maintien : MaintainA/B_Cmd (TRUE = voie saine).
   🛡️ Pattern Cause/Ack (§9 STD) : Reset non conditionné, interlock sur Cause brute,
      affichage IHM (ErrorId) avec debounce court + Ack.
   ═══════════════════════════════════════════════════════════════
    📄 Docs : DOC/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md §3.4/§3.4bis
              DOC/CODE_QUALITY_STANDARDS.md §9 (pattern Cause/Ack)
              DOC/AF_Partie-03_Contrats_Composants_v2.1.md
*)

FUNCTION_BLOCK PUBLIC FB_Safety_EmergencyManagementLogic
VAR_INPUT
    Enable              : BOOL;        // Active la surveillance
    Reset               : BOOL;        // Front acquittement défauts
    ArmRequest          : BOOL;        // Demande de réarmement (BtnEmergencyArming)
    EmergencyChainClosed      : BOOL;        // Retour physique boucle d'urgence amont contacteur
    PowerContactorEngaged     : BOOL;        // Confirmation contacteur de puissance principal
    PowerCutOffRequest  : BOOL;        // Requête de coupure logique issue des métiers
    BtnEmergencyCutOff  : BOOL;        // Commande d'ouverture d'urgence depuis l'IHM
END_VAR
VAR_OUTPUT
    Error               : BOOL;
    ErrorId             : WORD;        // bit0: RedundancyTestFailed (affiché), bit1: EmergencyArmingFailed (affiché)
    Cmd                 : ST_Safety_Emergency_InternalCmd; // Structure de commande logique produite

    ArmingSeqStep       : INT;         // Étape de diagnostic : 0=IDLE, 1=TestA, 2=RestoreA, 3=TestB, 4=RestoreB, 5=Pulse, 6=Confirm
    RedundancyTestFailed: BOOL;        // 🩹 Affiché = Cause lissée OR NOT Ack (pattern §3.4bis) — pour IHM/diag
    EmergencyArmingFailed: BOOL;       // 🩹 Affiché = Cause lissée OR NOT Ack (pattern §3.4bis) — pour IHM/diag
    EmergencyArmingLockoutActive : BOOL; // Verrouillage temporel de 5s entre les essais

    // 🆕 Bus State/Diag internes — repris par le composite pour les DUT publics
    Armable             : BOOL;        // 🟢 Réarmement possible maintenant
    ArmingBusy          : BOOL;        // ⏳ Séquence ou lockout en cours
    StartupFail         : BOOL;        // 🔴 Autotest démarche échoué
END_VAR
VAR CONSTANT
    // [CST] Temporisations normatives de securite AU (fixes, non modifiables RETAIN/IHM)
    CST_TestDuration         : TIME := T#200ms;  // Duree auto-test canal A ou B
    CST_ArmingPulseDuration  : TIME := T#1s;     // Duree impulsion rearmement contacteur
    CST_ArmingConfirmTimeout : TIME := T#2s;     // Timeout confirmation engagement contacteur
    CST_ArmingLockout        : TIME := T#5s;     // Duree verrouillage anti-reessai apres echec
    CST_FaultDisplayDebounce : TIME := T#200ms;  // 🩹 Anti-clignotement affichage IHM uniquement (§9 STD) — jamais sur l'action
END_VAR
VAR
    ResetEdge           : R_TRIG;
    ArmReqEdge          : R_TRIG;
    EnableRising        : R_TRIG;
    ForceTestA          : BOOL;
    ForceTestB          : BOOL;
    TonTestA            : TON;
    TonRestoreA         : TON;
    TonTestB            : TON;
    TonRestoreB         : TON;
    TonArmingPulse      : TON;
    TonArmingConfirm    : TON;
    TonArmingLockout    : TON;

    // 🆕 Autotest démarrage
    StartupCheckDone    : BOOL;        // TRUE = autotest passé, attente réarmement
    StartupCheckOK      : BOOL;        // Résultat autotest (latche le temps du front)

    // 🩹 Pattern Cause/Ack (§3.4bis AF01, §9 STD) — Reset jamais conditionné
    RedundancyTestFailedCause : BOOL;        // Latch brut : canal collé détecté à l'auto-test
    RedundancyTestFailedAck   : BOOL := TRUE; // Accusé opérateur — TRUE = pas d'alarme à afficher
    RedundancyCauseEdge       : R_TRIG;       // Détecte une NOUVELLE occurrence de la cause
    TonRedundancyDisplay      : TON;          // Debounce affichage IHM uniquement

    EmergencyArmingFailedCause : BOOL;        // Latch brut : contacteur non confirmé sous 2s
    EmergencyArmingFailedAck   : BOOL := TRUE; // Accusé opérateur — TRUE = pas d'alarme à afficher
    ArmingFailedCauseEdge      : R_TRIG;       // Détecte une NOUVELLE occurrence de la cause
    TonArmingFailedDisplay     : TON;          // Debounce affichage IHM uniquement
END_VAR

// === IMPLEMENTATION ===

// 🔄 Fronts
EnableRising(CLK := Enable);
ResetEdge(CLK := Reset);
ArmReqEdge(CLK := ArmRequest);

// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    Error := FALSE;
    ErrorId := 16#0000;
    Cmd.MaintainA_Cmd := FALSE;
    Cmd.MaintainB_Cmd := FALSE;
    Cmd.ArmPulse_Cmd := FALSE;
    ArmingSeqStep := 0;
    RedundancyTestFailed := FALSE;
    EmergencyArmingFailed := FALSE;
    EmergencyArmingLockoutActive := FALSE;
    ForceTestA := FALSE;
    ForceTestB := FALSE;
    Armable := FALSE;
    ArmingBusy := FALSE;
    StartupFail := FALSE;
    StartupCheckDone := FALSE;
    StartupCheckOK := FALSE;
    // 🩹 Neutralisation = coupure surveillance, pas un defaut : Cause et Ack repartent propres
    RedundancyTestFailedCause := FALSE;
    RedundancyTestFailedAck := TRUE;
    EmergencyArmingFailedCause := FALSE;
    EmergencyArmingFailedAck := TRUE;
    TonTestA(IN := FALSE);
    TonRestoreA(IN := FALSE);
    TonTestB(IN := FALSE);
    TonRestoreB(IN := FALSE);
    TonArmingPulse(IN := FALSE);
    TonArmingConfirm(IN := FALSE);
    TonArmingLockout(IN := FALSE);
    TonRedundancyDisplay(IN := FALSE);
    TonArmingFailedDisplay(IN := FALSE);
    RETURN;
END_IF;

// 🏁 2. AUTOTEST DÉMARRAGE (§5.4 AF01)
// Vérifications synchrones 1 cycle au premier passage Enable=TRUE
IF EnableRising.Q THEN
    StartupCheckDone := FALSE;
END_IF;

IF NOT StartupCheckDone THEN
    // Exécute les 4 contrôles en 1 cycle
    StartupCheckOK := EmergencyChainClosed          // 1. Boucle AU fermée
                      AND NOT PowerContactorEngaged // 2. Contacteur au repos
                      AND (ArmingSeqStep = 0);      // 4. Pas de séquence résiduelle
    StartupCheckDone := TRUE;
    StartupFail := NOT StartupCheckOK;
    IF NOT StartupCheckOK THEN
        ErrorId := 16#0008; // bit3 = startup autotest fail
        Error := TRUE;
    END_IF;
    RETURN; // 1 cycle pour laisser le temps aux entrées de se stabiliser
END_IF;

// 🔍 3. ACQUITTEMENT DES DÉFAUTS (pattern Cause/Ack — §3.4bis AF01, §9 STD)
// ⚠️ Reset TOUJOURS effectif, efface l'affichage (Ack:=TRUE) et réinitialise Cause:=FALSE
// pour permettre une nouvelle tentative d'armement sans blocage IHM. Si le défaut persiste,
// la nouvelle tentative re-latchera Cause:=TRUE et Ack:=FALSE (TC-P01-009).
IF ResetEdge.Q THEN
    RedundancyTestFailedAck := TRUE;
    EmergencyArmingFailedAck := TRUE;
    RedundancyTestFailedCause := FALSE;
    EmergencyArmingFailedCause := FALSE;
    StartupFail := FALSE;
    ErrorId := 16#0000;
END_IF;

// 🚦 4. DÉCLENCHEMENT DE LA SÉQUENCE DE SÉCURITÉ
// 🩹 Une nouvelle tentative repart d'une Cause propre : si le probleme persiste, il sera
// re-latche des le prochain echec (RedundancyCauseEdge/ArmingFailedCauseEdge -> Ack remis a FALSE,
// TC-P01-009). Ceci prouve par le run reel que la cause a disparu, pas juste un Reset optimiste.
IF ArmReqEdge.Q AND (ArmingSeqStep = 0) AND EmergencyChainClosed 
   AND NOT EmergencyArmingLockoutActive 
   AND NOT PowerContactorEngaged THEN
    ArmingSeqStep := 1;
    RedundancyTestFailedCause := FALSE;
    EmergencyArmingFailedCause := FALSE;
END_IF;

// ⏱️ Étape 1 : Coupe canal A seul, vérifie que la boucle tombe
TonTestA(IN := (ArmingSeqStep = 1), PT := CST_TestDuration);
IF ArmingSeqStep = 1 THEN
    ForceTestA := TRUE;
    IF TonTestA.Q THEN
        ForceTestA := FALSE;
        IF EmergencyChainClosed THEN
            RedundancyTestFailedCause := TRUE;
            ArmingSeqStep := 0;
        ELSE
            ArmingSeqStep := 2;
        END_IF;
    END_IF;
ELSE
    ForceTestA := FALSE;
END_IF;

// ⏱️ Étape 2 : Restaure A, attend le retour sain de la boucle amont
TonRestoreA(IN := (ArmingSeqStep = 2), PT := CST_TestDuration);
IF (ArmingSeqStep = 2) AND TonRestoreA.Q THEN
    IF EmergencyChainClosed THEN
        ArmingSeqStep := 3;
    ELSE
        ArmingSeqStep := 0;
    END_IF;
END_IF;

// ⏱️ Étape 3 : Coupe canal B seul, vérifie que la boucle tombe
TonTestB(IN := (ArmingSeqStep = 3), PT := CST_TestDuration);
IF ArmingSeqStep = 3 THEN
    ForceTestB := TRUE;
    IF TonTestB.Q THEN
        ForceTestB := FALSE;
        IF EmergencyChainClosed THEN
            RedundancyTestFailedCause := TRUE;
            ArmingSeqStep := 0;
        ELSE
            ArmingSeqStep := 4;
        END_IF;
    END_IF;
ELSE
    ForceTestB := FALSE;
END_IF;

// ⏱️ Étape 4 : Restaure B, attend le retour sain de la boucle amont
TonRestoreB(IN := (ArmingSeqStep = 4), PT := CST_TestDuration);
IF (ArmingSeqStep = 4) AND TonRestoreB.Q THEN
    IF EmergencyChainClosed THEN
        ArmingSeqStep := 5;
    ELSE
        ArmingSeqStep := 0;
    END_IF;
END_IF;

// ⏱️ Étape 5 : Les 2 canaux validés -> impulsion réarmement physique (1s)
TonArmingPulse(IN := (ArmingSeqStep = 5), PT := CST_ArmingPulseDuration);
Cmd.ArmPulse_Cmd := (ArmingSeqStep = 5);
IF (ArmingSeqStep = 5) AND TonArmingPulse.Q THEN
    ArmingSeqStep := 6;
END_IF;

// ⏱️ Étape 6 : Attente confirmation contacteur principal (2s max)
TonArmingConfirm(IN := (ArmingSeqStep = 6), PT := CST_ArmingConfirmTimeout);
IF ArmingSeqStep = 6 THEN
    IF PowerContactorEngaged THEN
        ArmingSeqStep := 0;
        EmergencyArmingLockoutActive := FALSE;
    ELSIF TonArmingConfirm.Q THEN
        EmergencyArmingFailedCause := TRUE;
        ArmingSeqStep := 0;
        EmergencyArmingLockoutActive := TRUE;
    END_IF;
END_IF;

// ⏱️ Séquence de verrouillage temporel (5s)
TonArmingLockout(IN := EmergencyArmingLockoutActive, PT := CST_ArmingLockout);
IF TonArmingLockout.Q THEN
    EmergencyArmingLockoutActive := FALSE;
END_IF;

// 🆕 3bis. PATTERN CAUSE/ACK — détection ré-apparition + acquittement (§3.4bis AF01, §9 STD)
// L'interlock sécurité (ci-dessous, arbitrage Cmd/Armable) utilise TOUJOURS la Cause brute,
// jamais l'Ack : l'acquittement opérateur n'ouvre jamais un interlock de sécurité.
RedundancyCauseEdge(CLK := RedundancyTestFailedCause);
IF RedundancyCauseEdge.Q THEN
    RedundancyTestFailedAck := FALSE; // nouvelle occurrence -> ré-alarme, ré-acquittement requis
END_IF;

ArmingFailedCauseEdge(CLK := EmergencyArmingFailedCause);
IF ArmingFailedCauseEdge.Q THEN
    EmergencyArmingFailedAck := FALSE;
END_IF;

// 📤 5. GÉNÉRATION DES CONSIGNES LOGIQUES — basées sur la Cause brute (jamais sur l'Ack)
Cmd.MaintainA_Cmd := NOT PowerCutOffRequest AND NOT ForceTestA AND NOT BtnEmergencyCutOff AND NOT RedundancyTestFailedCause;
Cmd.MaintainB_Cmd := NOT PowerCutOffRequest AND NOT ForceTestB AND NOT BtnEmergencyCutOff AND NOT RedundancyTestFailedCause;
// ArmPulse_Cmd déjà positionné à l'étape 5 ci-dessus (garder FALSE hors étape 5)
IF ArmingSeqStep <> 5 THEN
    Cmd.ArmPulse_Cmd := FALSE;
END_IF;

// 🚦 6. ÉTATS PUBLICS (repris par le composite dans State/Diag) — interlock sur Cause brute
Armable := EmergencyChainClosed
           AND (ArmingSeqStep = 0)
           AND NOT EmergencyArmingLockoutActive
           AND NOT RedundancyTestFailedCause
           AND NOT PowerContactorEngaged;

ArmingBusy := (ArmingSeqStep <> 0) OR EmergencyArmingLockoutActive;

// 📤 7. AFFICHAGE IHM — debounce anti-clignotement (Cause lissée) OR NOT Ack (§9 STD)
// ⚠️ Uniquement pour l'affichage : l'action de sécurité ci-dessus (§5/§6) reste instantanée
// sur la Cause brute, jamais retardée par ce debounce.
TonRedundancyDisplay(IN := RedundancyTestFailedCause, PT := CST_FaultDisplayDebounce);
RedundancyTestFailed := TonRedundancyDisplay.Q OR NOT RedundancyTestFailedAck;

TonArmingFailedDisplay(IN := EmergencyArmingFailedCause, PT := CST_FaultDisplayDebounce);
EmergencyArmingFailed := TonArmingFailedDisplay.Q OR NOT EmergencyArmingFailedAck;

// 📤 8. SYNTHÈSE DES ERREURS (bitfield affiché, basé sur RedundancyTestFailed/EmergencyArmingFailed affichés)
ErrorId := 16#0000;
IF RedundancyTestFailed THEN
    ErrorId := ErrorId OR 16#0001;
END_IF;
IF EmergencyArmingFailed THEN
    ErrorId := ErrorId OR 16#0002;
END_IF;
// bit3 (16#0008) = StartupFail, positionné au §2 si autotest échoué
// — ne pas l'effacer ici (reset explicite requis)

Error := (ErrorId <> 16#0000);

(* ═══════════════════════════════════════════════════════════════
   📡 PRG_ACQUISITION_CFC — Acquisition brute, simulation et aiguillage HwIn
   ───────────────────────────────────────────────────────────────
   📄 Docs : DOC/AF_Partie-06_Acquisition_Qualification_IO_v2.0.md §2 ;
            DOC/AF_Partie-13_Fonction_Simulation_v2.0.md
   ⚙️ Version ST temporaire pour validation (cible CFC).
   🎯 Rôle unique : produire l'image matérielle HwIn consommée par le reste
      du programme. Aucune décision métier (SafeStop, mode, commande) ici.
   🔗 Producteur unique de HwIn ; consommateurs = PRG_INPUTS_LD et suivants.
   ═══════════════════════════════════════════════════════════════ *)

PROGRAM PRG_ACQUISITION_CFC

VAR_OUTPUT
    HwReal                   : ST_HardwareImage;  (* Image matérielle brute lue sur le terrain *)
    HwSim                    : ST_HardwareImage;  (* Image produite par le banc de simulation *)
    HwIn                     : ST_HardwareImage;  (* Image aiguillée réel/simulé *)
    WinchInputSourceChanged  : BOOL;              (* Pulse 1 cycle sur bascule réel/simulé domaine Winch *)

    // 🆕 Migration PRG_00_Inputs : positions Translation M3 exposées en sortie de programme
    TranslationPosTremie      : BOOL;   (* TRUE = translation en position Trémie *)
    TranslationPosPV          : BOOL;   (* TRUE = translation en zone pré-ralentissement PV *)
    TranslationPosP2          : BOOL;   (* TRUE = translation en position P2 *)
    TranslationPosP1          : BOOL;   (* TRUE = translation en position P1 *)
    TranslationPosMaintenance : BOOL;   (* TRUE = translation en position Maintenance *)

    // 🆕 Migration PRG_00_Inputs : retours variateur M3 filtrés (PT1 T#0MS = recopie legacy)
    M3_StatusWord_Filtered        : UINT;
    M3_ActualFrequencyHz_Filtered : UINT;
END_VAR

VAR
    (* ── Instances de traitement complexes ── *)
    instSimBench             : FB_SimBench;
    instJoystick             : FB_Joystick;
    instEncoderAbsM1         : FB_Encoder_Abs;
    instEncoderScaleM1       : FB_Encoder_Scale;
    instHomingM1             : FB_Encoder_Homing;
    instEncoderAbsM2         : FB_Encoder_Abs;
    instEncoderScaleM2       : FB_Encoder_Scale;
    instHomingM2             : FB_Encoder_Homing;
    instPosDecoderM3         : FB_Translation_PositionDecoder;

    (* ── Filtrage des retours variateur M3 (migration PRG_00_Inputs) ── *)
    instCycleTimeAcq            : FB_CycleTime;
    instFilterM3StatusWord      : FB_Filter_PT1;
    instFilterM3ActualFreqHz      : FB_Filter_PT1;

    (* ── Mémoire de la source Winch (front bascule réel/simulé) ── *)
    WinchInputSourceSimulated            : BOOL;
    PreviousWinchInputSourceSimulated    : BOOL;
    WinchInputSourceInitialized          : BOOL;
END_VAR

// === IMPLEMENTATION ===

// ─── §0 MATÉRIEL ──► HwReal (Acquisition brute unique) ─────────────────────────

// Winch M1 / M2 et codeurs
HwReal.Winch.M1_ContactorsReleased_DI := M1_ContactorsReleased_DI;
