(* ═══════════════════════════════════════════════════════════════
   🧪 FB_Sim_Translation — Simulation dynamique du trajet translation M3 (temps de parcours)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-13_Fonction_Simulation_v2.0.md
   🧩 Brique réduite (Partie3 §1bis) : outil de banc, pas du métier machine.
   🎯 Rôle : remplace le forçage manuel du capteur de position cible en vue
      instance CODESYS (voir `GVL_Translation_M3_Stub.st`, doc Partie11 §9bis) par
      une simulation par temps de parcours : le translation "arrive" à la cible
      sélectionnée (`TargetNum`) après `TravelTimeS` secondes de commande
      continue dans le bon sens (`RelayFwd`/`RelayRev`). Non prioritaire
      (M3 translation) — treuils/benne/codeurs sont la priorité de ce lot.
   📥 Enable      : simulation active (SimulationModeActive AND NOT SensorTranslationPositionIsReal)
   📥 TargetNum   : cible sélectionnée (0=Aucun, 1=Trémie, 2=P2, 3=P1, 4=Maintenance)
                    — réutilise `GVL_Translation_M3_Stub.StubTranslationPositionSelect_IHM`
                    — 🆕 REX 2026-07-18 : PV n'est JAMAIS une cible sélectionnable (point de
                    ralentissement uniquement, pas d'arrêt), voir AF_Partie-02 v2.12 §3bis
   📥 RelayFwd/RelayRev : sens déduit du mot de commande EtherCAT M3
   📥 TravelTimeS : temps de trajet simulé (s) — défaut 8.0 (fourchette 5-10s validée
                    utilisateur, pas de donnée réelle pour calibrer plus précisément)
   📥 PVLeadTimeS : durée (s) avant la fin du trajet Trémie où PV s'active (approche)
   📤 PosTremie/PosPV/PosP2/PosP1/PosMaintenance : TRUE quand la cible (ou le point de
      ralentissement PV) correspondante est atteinte — à OR'er sur le `InputRaw` du capteur
      réel correspondant (PRG_01_Inputs_LD).
   ⏱️ Changement de cible (`TargetNum`) → trajet remis à zéro (redémarre du début).
      Relais retombés (ni Fwd ni Rev) → progression mise EN PAUSE (pas remise à zéro).
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Sim_Translation) ===

FUNCTION_BLOCK PUBLIC FB_Sim_Translation
VAR_INPUT
    Enable      : BOOL;
    TargetNum   : INT;
    RelayFwd    : BOOL;
    RelayRev    : BOOL;
    TravelTimeS : REAL := 8.0;
    PVLeadTimeS : REAL := 2.0;
END_VAR
VAR_OUTPUT
    PosTremie      : BOOL;
    PosPV          : BOOL;
    PosP2          : BOOL;
    PosP1          : BOOL;
    PosMaintenance : BOOL;
END_VAR
VAR
    CycleTimeCalc   : FB_CycleTime;   // 📚 Réutilisation — pas de recalcul maison du temps de cycle
    ElapsedS        : REAL;
    LastTargetNum   : INT;
    TargetChanged   : BOOL;
    Reached         : BOOL;
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Translation) ===

IF NOT Enable THEN
    ElapsedS := 0.0;
    LastTargetNum := TargetNum;
    PosTremie := FALSE; PosPV := FALSE; PosP2 := FALSE; PosP1 := FALSE; PosMaintenance := FALSE;
    RETURN;
END_IF;

CycleTimeCalc(DefaultValueS := 0.010);

// 🔁 Changement de cible = nouveau trajet, on repart de zéro
TargetChanged := (TargetNum <> LastTargetNum);
LastTargetNum := TargetNum;
IF TargetChanged THEN
    ElapsedS := 0.0;
END_IF;

// ⏱️ Progression du trajet UNIQUEMENT si un relais de sens est actif (mouvement réel demandé) ;
// à l'arrêt, la progression reste EN PAUSE (pas remise à zéro).
IF (RelayFwd OR RelayRev) AND (ElapsedS < TravelTimeS) THEN
    ElapsedS := ElapsedS + CycleTimeCalc.CycleTimeS;
    IF ElapsedS > TravelTimeS THEN
        ElapsedS := TravelTimeS;
    END_IF;
END_IF;

Reached := (ElapsedS >= TravelTimeS);

// 🆕 REX 2026-07-18 : les capteurs sont codés par progression monotone.
// La simulation doit donc produire un mot valide à chaque instant, et non
// uniquement activer le capteur de la cible. Le mot est :
//   11111 Trémie | 01111 PV | 00111 P2 | 00011 P1 | 00001 approche Maintenance | 00000 Maintenance.
// 🔧 REX 2026-07-21 : au repos / boot (TargetNum = 0), la position neutre par défaut
// est positionnée sur P2 (00111) pour éviter d'être par défaut sur le fin de course extrême Maintenance (00000).
PosTremie := FALSE;
PosPV := FALSE;

IF TargetNum = 0 THEN
    // Position neutre par défaut au boot (P2 = 00111) — évite le fin de course extrême arrière au démarrage
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF TargetNum = 1 THEN
    // Trajet vers Trémie : PV puis Trémie, avec les trois capteurs de droite actifs.
    PosP2 := FALSE; PosP1 := FALSE; PosMaintenance := FALSE;
    IF ElapsedS >= (TravelTimeS - PVLeadTimeS) THEN
        PosPV := TRUE;
        PosP2 := TRUE;
        PosP1 := TRUE;
        PosMaintenance := TRUE;
    END_IF;
    IF Reached THEN
        PosTremie := TRUE;
    END_IF;
ELSIF TargetNum = 2 THEN
    // P2 = 00111
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF TargetNum = 3 THEN
    // P1 = 00011
    PosP2 := FALSE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF TargetNum = 4 THEN
    // Maintenance = 00000 : PosMaintenance reste FALSE pour respecter le codage.
    PosP2 := FALSE;
    PosP1 := FALSE;
    PosMaintenance := FALSE;
ELSE
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
END_IF;

(* =======================================================================
   📊 FB_WinchLoadEstimator — Estimation empirique de charge treuil
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Estimation informative de la charge par croisement palier/vitesse
   📄 Doc métier : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md
   🔌 Interface : Brique de diagnostic/mesure (1 instance par treuil)
   🔒 Sécurité : Aucune commande moteur ni action sur SafeStop (information IHM)
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_WinchLoadEstimator
VAR_INPUT
    // === COMMANDES ET CONSIGNES ===
    Enable                          : BOOL;                           // --> [CMD] Autorisation generale FB
    Reset                           : BOOL;                           // --> [CMD] Acquittement defaut sur front
    Mode                            : E_Mode;                         // --> [CMD] Mode d'exploitation actif
    ActiveSpeedStep                 : INT;                            // --> [CMD] Palier commande actif (0..5)

    // === SECOURS ET HARDWARE ===
    PowerContactorEngaged           : BOOL;                           // --> [SAFE] Chaine AU rearmee et puissance OK
    MeasuredSpeedMps                : REAL;                           // --> [HW] Vitesse cable absolue (m/s)
    MeasuredSpeedSignedMps          : REAL;                           // --> [HW] Vitesse signee (+: montee, -: descente) (m/s)

    // === REGLAGES ET TABLES ===
    SpeedConfig                     : ST_WinchSpeedConfig;            // --> [CFG] Configuration des plages de vitesse
    LoadTable                       : ST_WinchLoadEstimateTable;      // --> [CFG] Table empirique d'estimation 5x5
END_VAR
VAR_OUTPUT
    // === ETATS IEC ET SYNOPTIQUE ===
    Ready                           : BOOL;                           // <-- [STAT] FB pret a fonctionner
    // 🧩 Statut transverse (forme cible) — regroupe Busy/Done/Error/ErrorId/State/StateAtError.
    // ErrorId bit0: "entrée/table invalide".
    Status                          : ST_FbStatus;

    // === DIAGNOSTICS ET ESTIMATIONS ===
    SpeedBand                       : INT;                            // <-- [DIAG] Bande de vitesse courante (0..5)
    EstimatedLoadPct                : REAL;                           // <-- [DIAG] Estimation de charge (0..100%)
    Configured                      : BOOL;                           // <-- [STAT] Table explicitement validee
    Ascending                       : BOOL;                           // <-- [STAT] Montee effective mesuree en cours
END_VAR
VAR
    // === DETECTEURS ET TIMERS INTERNES ===
    ResetEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Reset
    ErrorEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Erreur

    // === VARIABLES LOCALES CALCULÉES ===
    PreviousSpeedBand               : INT;                            // . [LOC] Memoire bande de vitesse cycle precedent
    HasPreviousBand                 : BOOL;                           // . [LOC] Indicateur premiere bande memorisee
    SelectedLoadPct                 : REAL;                           // . [LOC] Valeur de charge extraite de la table
END_VAR

{region "§1 Gate"}
// 🛑 1. GATE — aucune estimation lorsque le bloc est désactivé ou l'AU absent.
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE;
    Status.Busy := FALSE;
    Status.Done := FALSE;
    Status.Error := FALSE;
    Status.ErrorId := 16#0000;
    Status.State := E_State.DISABLED;
    SpeedBand := 0;
    EstimatedLoadPct := 0.0;
    Configured := FALSE;
    Ascending := FALSE;
    HasPreviousBand := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
Status.Busy := FALSE;
Status.Done := FALSE;
Status.State := E_State.READY;
ResetEdge(CLK := Reset);
Configured := LoadTable.IsConfigured;
// 📈 L'estimation de charge n'a de sens qu'en montée.
// La bande de vitesse reste calculée pour le diagnostic et le garde-fou de palier,
// mais EstimatedLoadPct est forcée à zéro à l'arrêt et en descente.
Ascending := (MeasuredSpeedSignedMps > 0.0);
{endregion}

{region "§2 Classement vitesse"}
// 📏 2. CLASSEMENT DE LA VITESSE — hystérésis autour des 4 frontières.
IF (MeasuredSpeedMps < 0.0) OR (SpeedConfig.MaxMeasuredSpeedMps <= 0.0) THEN
    Status.ErrorId := Status.ErrorId OR 16#0001;
    SpeedBand := 0;
ELSIF NOT HasPreviousBand THEN
    IF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[1] THEN
        PreviousSpeedBand := 1;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[2] THEN
        PreviousSpeedBand := 2;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[3] THEN
        PreviousSpeedBand := 3;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[4] THEN
        PreviousSpeedBand := 4;
    ELSE
        PreviousSpeedBand := 5;
    END_IF;
    HasPreviousBand := TRUE;
    SpeedBand := PreviousSpeedBand;
ELSE
    // 🔒 Valider l'état mémorisé avant toute indexation dynamique.
    IF PreviousSpeedBand < 1 OR PreviousSpeedBand > 5 THEN
        PreviousSpeedBand := 1;
        Status.ErrorId := Status.ErrorId OR 16#0001;
    END_IF;

    // CODESYS ne garantit pas le court-circuit des expressions AND :
    // chaque borne est donc testée dans une branche séparée avant accès.
    IF PreviousSpeedBand < 5 THEN
        IF MeasuredSpeedMps > (SpeedConfig.SpeedBandMaxMps[PreviousSpeedBand]
                               + SpeedConfig.SpeedBandHysteresisMps) THEN
            PreviousSpeedBand := PreviousSpeedBand + 1;
        END_IF;
    END_IF;
    IF PreviousSpeedBand > 1 THEN
        IF MeasuredSpeedMps < (SpeedConfig.SpeedBandMaxMps[PreviousSpeedBand - 1]
                               - SpeedConfig.SpeedBandHysteresisMps) THEN
            PreviousSpeedBand := PreviousSpeedBand - 1;
        END_IF;
    END_IF;
    SpeedBand := PreviousSpeedBand;
END_IF;
{endregion}

{region "§3 Lecture table"}
// 📊 3. LECTURE TABLE — bornes séparées avant l'accès au tableau 5x5.
EstimatedLoadPct := 0.0;
IF Configured THEN
    IF Ascending THEN
        IF ActiveSpeedStep >= 1 THEN
            IF ActiveSpeedStep <= 5 THEN
                IF SpeedBand >= 1 THEN
                    IF SpeedBand <= 5 THEN
                        SelectedLoadPct := LoadTable.LoadPctByStepAndSpeedBand[ActiveSpeedStep][SpeedBand];
                        IF (SelectedLoadPct < 0.0) OR (SelectedLoadPct > 100.0) THEN
                            Status.ErrorId := Status.ErrorId OR 16#0001;
                        ELSE
                            EstimatedLoadPct := SelectedLoadPct;
                        END_IF;
                    END_IF;
                END_IF;
            END_IF;
        END_IF;
    END_IF;
END_IF;
{endregion}

{region "§4 Sorties et acquittement"}
// 📤 4. SORTIES D'ÉTAT ET ACQUITTEMENT.
IF ResetEdge.Q AND (Status.ErrorId <> 16#0000) AND (MeasuredSpeedMps >= 0.0) THEN
    Status.ErrorId := 16#0000;
END_IF;
Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;
{endregion}

(* =======================================================================
   🛡️ FB_Brake — Séquence frein à manque de courant (temps physiques)
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Gestion temporisée ouverture/fermeture frein à manque de courant
   🔒 Polarité : Sécurité positive (BrakeCmd=FALSE = frein collé au repos)
   🔌 Interface : Double vérification retour contacteur (ST_ContactorCheck)
   📄 Doc métier : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md §3
   ======================================================================= *)
FUNCTION_BLOCK PUBLIC FB_Brake
VAR_INPUT
    // === COMMANDES ET CONSIGNES ===
    Enable                  : BOOL;               // --> [CMD]  Autorisation generale (FALSE = frein colle)
    Reset                   : BOOL;               // --> [CMD]  Acquittement defaut (front)
    MovementRequested       : BOOL;               // --> [CMD]  Demande de mouvement (sens+palier actifs)

    // === RETOURS MATERIELS & SIMULATION ===
    ContactorFeedback       : BOOL;               // --> [HW]   Retour contacteur frein (TRUE = relache/ouvert)
    BypassContactorCheck    : BOOL;               // --> [TST]  Bypass controle contacteur (simu)

    // === TEMPORISATIONS ET REGLAGES ===
    DelayContactClose       : TIME := T#100ms;    // --> [CFG]  Temps de fermeture contacteur de puissance
    DelayMagnetise          : TIME := T#300ms;    // --> [CFG]  Delai magnetisation moteur avant ouverture frein
    DelayMotorDecel         : TIME := T#500ms;    // --> [CFG]  Delai deceleration avant collage frein
    FeedbackTimeout         : TIME := T#1s;       // --> [CFG]  Delai max coherence commande/retour frein
END_VAR
VAR_OUTPUT
    // === ETATS IEC & DERIVATION ===
    Ready                   : BOOL;               // <-- [STAT] FB pret a fonctionner
    // 🧩 Statut transverse (forme cible) — regroupe Busy/Done/Error/ErrorId/State/StateAtError.
    // ErrorId bit0: "incoherence retour contacteur".
    Status                  : ST_FbStatus;

    // === COMMANDES ET CONFIRMATIONS ===
    BrakeCmd                : BOOL;               // <-- [ACT]  Commande bobine frein (TRUE = relache/ouvert)
    BrakeCommandOpenConfirmed : BOOL;            // <-- [STAT] Confirmation ouverture frein pour verrous
    ContactorCheck          : ST_ContactorCheck;  // <-- [DIAG] Diagnostic detaille retour contacteur
END_VAR
VAR
    // === TRIGGERS ET DETECTION FRONTS ===
    ResetEdge               : R_TRIG;             // . [LOC]  Detecteur front acquittement
    ErrorEdge               : R_TRIG;             // . [LOC]  Detecteur front apparition defaut
    BypassEdge              : R_TRIG;             // . [LOC]  Detecteur front activation bypass

    // === TEMPORISATEURS INTERNES ===
    TonMagnetise            : TON;                // . [LOC]  Temporisation avant relachement frein
    TonDecel                : TON;                // . [LOC]  Temporisation avant collage frein
    TonFeedback             : TON;                // . [LOC]  Timeout de coherence commande/retour
END_VAR

{region "§1 Gate"}
// 🛑 1. GATE — pas d'Enable = frein collé (sécurité positive), aucune temporisation en cours
IF NOT Enable THEN
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    BrakeCmd := FALSE;
    Status.State := E_State.DISABLED;
    Ready := FALSE; Status.Busy := FALSE; Status.Done := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
{endregion}

{region "§2 Reset et fronts"}
// 🔑 2. RESET FRONT — efface le bit dont la cause a disparu
ResetEdge(CLK := Reset);
BypassEdge(CLK := BypassContactorCheck);
{endregion}

{region "§3 Séquence temporisée"}
// 🛠️ 3. SÉQUENCE TEMPORISÉE (démarrage vs arrêt)
IF MovementRequested THEN
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    TonMagnetise(IN := TRUE, PT := DelayMagnetise + DelayContactClose);
    IF TonMagnetise.Q THEN
        BrakeCmd := TRUE;              // ✅ Contacteur + magnétisation acquis → relâche
        Status.State := E_State.DONE;
    ELSE
        BrakeCmd := FALSE;             // ⏳ Encore collé pendant la magnétisation
        Status.State := E_State.BUSY;
    END_IF;
ELSE
    // Sécurité positive : fermeture immédiate du frein (collé) dès que les contacteurs de sens s'ouvrent
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    BrakeCmd := FALSE;                 // Fermeture immédiate
    Status.State := E_State.READY;
END_IF;

Status.Busy := (Status.State = E_State.BUSY);
Status.Done := (Status.State = E_State.DONE);
{endregion}

{region "§4 Double vérification contacteur"}
// 🔍 4. DOUBLE VÉRIFICATION RETOUR CONTACTEUR (ST_ContactorCheck)
ContactorCheck.Command := BrakeCmd;
ContactorCheck.Feedback := ContactorFeedback;

// ContactorFeedback est dans le MÊME sens que BrakeCmd (TRUE = relâché = frein ouvert).
// En marche saine les deux sont ÉGAUX → c'est leur DIFFÉRENCE qui signale l'incohérence
// (contacteur collé). Le test compare donc `<>`.
TonFeedback(IN := (BrakeCmd <> ContactorFeedback), PT := FeedbackTimeout);
IF NOT BypassContactorCheck THEN
    IF TonFeedback.Q THEN
        ContactorCheck.StuckClosed := (BrakeCmd AND NOT ContactorFeedback);            // relâche commandée (BrakeCmd=TRUE), frein reste serré (ContactorFeedback=FALSE)
        ContactorCheck.StuckOpen   := (NOT BrakeCmd AND ContactorFeedback);             // serrage commandé (BrakeCmd=FALSE), frein reste ouvert (ContactorFeedback=TRUE)
        Status.ErrorId := Status.ErrorId OR 16#0001;
    ELSIF ResetEdge.Q THEN
        ContactorCheck.StuckClosed := FALSE;
        ContactorCheck.StuckOpen   := FALSE;
        Status.ErrorId := Status.ErrorId AND 16#FFFE;
    END_IF;
ELSE
    ContactorCheck.StuckClosed := FALSE;
    ContactorCheck.StuckOpen   := FALSE;
    Status.ErrorId := Status.ErrorId AND 16#FFFE;   // Bypass actif : efface/maintient à 0 le bit 0
    IF BypassEdge.Q THEN
        Status.StateAtError := E_State.DISABLED; // Front activation bypass : débloque l'état figé
    END_IF;
END_IF;

{endregion}

{region "§5 Arbitrage error"}
// 🧾 5. ARBITRAGE ERROR / STATEATERROR (figé jusqu'à acquittement)
Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;
{endregion}

{region "§6 Sortie sûre"}
// 🛡️ 6. SORTIE SÛRE SUR DÉFAUT
IF Status.Error THEN
    BrakeCmd := FALSE;
END_IF;
{endregion}

{region "§7 Confirmation ouverture"}
// 📤 7. CONFIRMATION OUVERTURE FREIN (même sens que ContactorFeedback, ou image de BrakeCmd si BypassContactorCheck=TRUE)
IF BypassContactorCheck THEN
    BrakeCommandOpenConfirmed := BrakeCmd;
ELSE
    BrakeCommandOpenConfirmed := ContactorFeedback;  (* TRUE = frein ouvert = desserrage confirmé *)
END_IF;
{endregion}

(* ═══════════════════════════════════════════════════════════════
   🛡️ FB_Safety_EmergencyManagementLogic — Décision & Séquencement
   ───────────────────────────────────────────────────────────────
   📄 Rôle : Gère la machine d'état d'auto-test et de réarmement de
      la boucle d'arrêt d'urgence. Produit les consignes logiques
      et les bus d'état/diagnostic.
   🔒 Polarité maintien : MaintainA/B_Cmd (TRUE = voie saine).
   🛡️ Pattern Cause/Ack (§9 STD) : Reset non conditionné, interlock sur Cause brute,
      affichage IHM (ErrorId) avec debounce court + Ack.
   ═══════════════════════════════════════════════════════════════
    📄 Docs : DOC/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md §3.4/§3.4bis
              DOC/CODE_QUALITY_STANDARDS.md §9 (pattern Cause/Ack)
              DOC/AF_Partie-03_Contrats_Composants_v2.1.md
*)

FUNCTION_BLOCK PUBLIC FB_Safety_EmergencyManagementLogic
VAR_INPUT
    Enable              : BOOL;        // Active la surveillance
    Reset               : BOOL;        // Front acquittement défauts
    ArmRequest          : BOOL;        // Demande de réarmement (BtnEmergencyArming)
    EmergencyChainClosed      : BOOL;        // Retour physique boucle d'urgence amont contacteur
    PowerContactorEngaged     : BOOL;        // Confirmation contacteur de puissance principal
    PowerCutOffRequest  : BOOL;        // Requête de coupure logique issue des métiers
    BtnEmergencyCutOff  : BOOL;        // Commande d'ouverture d'urgence depuis l'IHM
END_VAR
VAR_OUTPUT
    Error               : BOOL;
    ErrorId             : WORD;        // bit0: RedundancyTestFailed (affiché), bit1: EmergencyArmingFailed (affiché)
    Cmd                 : ST_Safety_Emergency_InternalCmd; // Structure de commande logique produite

    ArmingSeqStep       : INT;         // Étape de diagnostic : 0=IDLE, 1=TestA, 2=RestoreA, 3=TestB, 4=RestoreB, 5=Pulse, 6=Confirm
    RedundancyTestFailed: BOOL;        // 🩹 Affiché = Cause lissée OR NOT Ack (pattern §3.4bis) — pour IHM/diag
    EmergencyArmingFailed: BOOL;       // 🩹 Affiché = Cause lissée OR NOT Ack (pattern §3.4bis) — pour IHM/diag
    EmergencyArmingLockoutActive : BOOL; // Verrouillage temporel de 5s entre les essais

    // 🆕 Bus State/Diag internes — repris par le composite pour les DUT publics
    Armable             : BOOL;        // 🟢 Réarmement possible maintenant
    ArmingBusy          : BOOL;        // ⏳ Séquence ou lockout en cours
    StartupFail         : BOOL;        // 🔴 Autotest démarche échoué
END_VAR
VAR CONSTANT
    // [CST] Temporisations normatives de securite AU (fixes, non modifiables RETAIN/IHM)
    CST_TestDuration         : TIME := T#200ms;  // Duree auto-test canal A ou B
    CST_ArmingPulseDuration  : TIME := T#1s;     // Duree impulsion rearmement contacteur
    CST_ArmingConfirmTimeout : TIME := T#2s;     // Timeout confirmation engagement contacteur
    CST_ArmingLockout        : TIME := T#5s;     // Duree verrouillage anti-reessai apres echec
    CST_FaultDisplayDebounce : TIME := T#200ms;  // 🩹 Anti-clignotement affichage IHM uniquement (§9 STD) — jamais sur l'action
END_VAR
VAR
    ResetEdge           : R_TRIG;
    ArmReqEdge          : R_TRIG;
    EnableRising        : R_TRIG;
    ForceTestA          : BOOL;
    ForceTestB          : BOOL;
    TonTestA            : TON;
    TonRestoreA         : TON;
    TonTestB            : TON;
    TonRestoreB         : TON;
    TonArmingPulse      : TON;
    TonArmingConfirm    : TON;
    TonArmingLockout    : TON;

    // 🆕 Autotest démarrage
    StartupCheckDone    : BOOL;        // TRUE = autotest passé, attente réarmement
    StartupCheckOK      : BOOL;        // Résultat autotest (latche le temps du front)

    // 🩹 Pattern Cause/Ack (§3.4bis AF01, §9 STD) — Reset jamais conditionné
    RedundancyTestFailedCause : BOOL;        // Latch brut : canal collé détecté à l'auto-test
    RedundancyTestFailedAck   : BOOL := TRUE; // Accusé opérateur — TRUE = pas d'alarme à afficher
    RedundancyCauseEdge       : R_TRIG;       // Détecte une NOUVELLE occurrence de la cause
    TonRedundancyDisplay      : TON;          // Debounce affichage IHM uniquement

    EmergencyArmingFailedCause : BOOL;        // Latch brut : contacteur non confirmé sous 2s
    EmergencyArmingFailedAck   : BOOL := TRUE; // Accusé opérateur — TRUE = pas d'alarme à afficher
    ArmingFailedCauseEdge      : R_TRIG;       // Détecte une NOUVELLE occurrence de la cause
    TonArmingFailedDisplay     : TON;          // Debounce affichage IHM uniquement
END_VAR

// === IMPLEMENTATION ===

// 🔄 Fronts
EnableRising(CLK := Enable);
ResetEdge(CLK := Reset);
ArmReqEdge(CLK := ArmRequest);

// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    Error := FALSE;
    ErrorId := 16#0000;
    Cmd.MaintainA_Cmd := FALSE;
    Cmd.MaintainB_Cmd := FALSE;
    Cmd.ArmPulse_Cmd := FALSE;
    ArmingSeqStep := 0;
    RedundancyTestFailed := FALSE;
    EmergencyArmingFailed := FALSE;
    EmergencyArmingLockoutActive := FALSE;
    ForceTestA := FALSE;
    ForceTestB := FALSE;
    Armable := FALSE;
    ArmingBusy := FALSE;
    StartupFail := FALSE;
    StartupCheckDone := FALSE;
    StartupCheckOK := FALSE;
    // 🩹 Neutralisation = coupure surveillance, pas un defaut : Cause et Ack repartent propres
    RedundancyTestFailedCause := FALSE;
    RedundancyTestFailedAck := TRUE;
    EmergencyArmingFailedCause := FALSE;
    EmergencyArmingFailedAck := TRUE;
    TonTestA(IN := FALSE);
    TonRestoreA(IN := FALSE);
    TonTestB(IN := FALSE);
    TonRestoreB(IN := FALSE);
    TonArmingPulse(IN := FALSE);
    TonArmingConfirm(IN := FALSE);
    TonArmingLockout(IN := FALSE);
    TonRedundancyDisplay(IN := FALSE);
    TonArmingFailedDisplay(IN := FALSE);
    RETURN;
END_IF;

// 🏁 2. AUTOTEST DÉMARRAGE (§5.4 AF01)
// Vérifications synchrones 1 cycle au premier passage Enable=TRUE
IF EnableRising.Q THEN
    StartupCheckDone := FALSE;
END_IF;

IF NOT StartupCheckDone THEN
    // Exécute les 4 contrôles en 1 cycle
    StartupCheckOK := EmergencyChainClosed          // 1. Boucle AU fermée
                      AND NOT PowerContactorEngaged // 2. Contacteur au repos
                      AND (ArmingSeqStep = 0);      // 4. Pas de séquence résiduelle
    StartupCheckDone := TRUE;
    StartupFail := NOT StartupCheckOK;
    IF NOT StartupCheckOK THEN
        ErrorId := 16#0008; // bit3 = startup autotest fail
        Error := TRUE;
    END_IF;
    RETURN; // 1 cycle pour laisser le temps aux entrées de se stabiliser
END_IF;

// 🔍 3. ACQUITTEMENT DES DÉFAUTS (pattern Cause/Ack — §3.4bis AF01, §9 STD)
// ⚠️ Reset TOUJOURS effectif, efface l'affichage (Ack:=TRUE) et réinitialise Cause:=FALSE
// pour permettre une nouvelle tentative d'armement sans blocage IHM. Si le défaut persiste,
// la nouvelle tentative re-latchera Cause:=TRUE et Ack:=FALSE (TC-P01-009).
IF ResetEdge.Q THEN
    RedundancyTestFailedAck := TRUE;
    EmergencyArmingFailedAck := TRUE;
    RedundancyTestFailedCause := FALSE;
    EmergencyArmingFailedCause := FALSE;
    StartupFail := FALSE;
    ErrorId := 16#0000;
END_IF;

// 🚦 4. DÉCLENCHEMENT DE LA SÉQUENCE DE SÉCURITÉ
// 🩹 Une nouvelle tentative repart d'une Cause propre : si le probleme persiste, il sera
// re-latche des le prochain echec (RedundancyCauseEdge/ArmingFailedCauseEdge -> Ack remis a FALSE,
// TC-P01-009). Ceci prouve par le run reel que la cause a disparu, pas juste un Reset optimiste.
IF ArmReqEdge.Q AND (ArmingSeqStep = 0) AND EmergencyChainClosed 
   AND NOT EmergencyArmingLockoutActive 
   AND NOT PowerContactorEngaged THEN
    ArmingSeqStep := 1;
    RedundancyTestFailedCause := FALSE;
    EmergencyArmingFailedCause := FALSE;
END_IF;

// ⏱️ Étape 1 : Coupe canal A seul, vérifie que la boucle tombe
TonTestA(IN := (ArmingSeqStep = 1), PT := CST_TestDuration);
IF ArmingSeqStep = 1 THEN
    ForceTestA := TRUE;
    IF TonTestA.Q THEN
        ForceTestA := FALSE;
        IF EmergencyChainClosed THEN
            RedundancyTestFailedCause := TRUE;
            ArmingSeqStep := 0;
        ELSE
            ArmingSeqStep := 2;
        END_IF;
    END_IF;
ELSE
    ForceTestA := FALSE;
END_IF;

// ⏱️ Étape 2 : Restaure A, attend le retour sain de la boucle amont
TonRestoreA(IN := (ArmingSeqStep = 2), PT := CST_TestDuration);
IF (ArmingSeqStep = 2) AND TonRestoreA.Q THEN
    IF EmergencyChainClosed THEN
        ArmingSeqStep := 3;
    ELSE
        ArmingSeqStep := 0;
    END_IF;
END_IF;

// ⏱️ Étape 3 : Coupe canal B seul, vérifie que la boucle tombe
TonTestB(IN := (ArmingSeqStep = 3), PT := CST_TestDuration);
IF ArmingSeqStep = 3 THEN
    ForceTestB := TRUE;
    IF TonTestB.Q THEN
        ForceTestB := FALSE;
        IF EmergencyChainClosed THEN
            RedundancyTestFailedCause := TRUE;
            ArmingSeqStep := 0;
        ELSE
            ArmingSeqStep := 4;
        END_IF;
    END_IF;
ELSE
    ForceTestB := FALSE;
END_IF;

// ⏱️ Étape 4 : Restaure B, attend le retour sain de la boucle amont
TonRestoreB(IN := (ArmingSeqStep = 4), PT := CST_TestDuration);
IF (ArmingSeqStep = 4) AND TonRestoreB.Q THEN
    IF EmergencyChainClosed THEN
        ArmingSeqStep := 5;
    ELSE
        ArmingSeqStep := 0;
    END_IF;
END_IF;

// ⏱️ Étape 5 : Les 2 canaux validés -> impulsion réarmement physique (1s)
TonArmingPulse(IN := (ArmingSeqStep = 5), PT := CST_ArmingPulseDuration);
Cmd.ArmPulse_Cmd := (ArmingSeqStep = 5);
IF (ArmingSeqStep = 5) AND TonArmingPulse.Q THEN
    ArmingSeqStep := 6;
END_IF;

// ⏱️ Étape 6 : Attente confirmation contacteur principal (2s max)
TonArmingConfirm(IN := (ArmingSeqStep = 6), PT := CST_ArmingConfirmTimeout);
IF ArmingSeqStep = 6 THEN
    IF PowerContactorEngaged THEN
        ArmingSeqStep := 0;
        EmergencyArmingLockoutActive := FALSE;
    ELSIF TonArmingConfirm.Q THEN
        EmergencyArmingFailedCause := TRUE;
        ArmingSeqStep := 0;
        EmergencyArmingLockoutActive := TRUE;
    END_IF;
END_IF;

// ⏱️ Séquence de verrouillage temporel (5s)
TonArmingLockout(IN := EmergencyArmingLockoutActive, PT := CST_ArmingLockout);
IF TonArmingLockout.Q THEN
    EmergencyArmingLockoutActive := FALSE;
END_IF;

// 🆕 3bis. PATTERN CAUSE/ACK — détection ré-apparition + acquittement (§3.4bis AF01, §9 STD)
// L'interlock sécurité (ci-dessous, arbitrage Cmd/Armable) utilise TOUJOURS la Cause brute,
// jamais l'Ack : l'acquittement opérateur n'ouvre jamais un interlock de sécurité.
RedundancyCauseEdge(CLK := RedundancyTestFailedCause);
IF RedundancyCauseEdge.Q THEN
    RedundancyTestFailedAck := FALSE; // nouvelle occurrence -> ré-alarme, ré-acquittement requis
END_IF;

ArmingFailedCauseEdge(CLK := EmergencyArmingFailedCause);
IF ArmingFailedCauseEdge.Q THEN
    EmergencyArmingFailedAck := FALSE;
END_IF;

// 📤 5. GÉNÉRATION DES CONSIGNES LOGIQUES — basées sur la Cause brute (jamais sur l'Ack)
Cmd.MaintainA_Cmd := NOT PowerCutOffRequest AND NOT ForceTestA AND NOT BtnEmergencyCutOff AND NOT RedundancyTestFailedCause;
Cmd.MaintainB_Cmd := NOT PowerCutOffRequest AND NOT ForceTestB AND NOT BtnEmergencyCutOff AND NOT RedundancyTestFailedCause;
// ArmPulse_Cmd déjà positionné à l'étape 5 ci-dessus (garder FALSE hors étape 5)
IF ArmingSeqStep <> 5 THEN
    Cmd.ArmPulse_Cmd := FALSE;
END_IF;

// 🚦 6. ÉTATS PUBLICS (repris par le composite dans State/Diag) — interlock sur Cause brute
Armable := EmergencyChainClosed
           AND (ArmingSeqStep = 0)
           AND NOT EmergencyArmingLockoutActive
           AND NOT RedundancyTestFailedCause
           AND NOT PowerContactorEngaged;

ArmingBusy := (ArmingSeqStep <> 0) OR EmergencyArmingLockoutActive;

// 📤 7. AFFICHAGE IHM — debounce anti-clignotement (Cause lissée) OR NOT Ack (§9 STD)
// ⚠️ Uniquement pour l'affichage : l'action de sécurité ci-dessus (§5/§6) reste instantanée
// sur la Cause brute, jamais retardée par ce debounce.
TonRedundancyDisplay(IN := RedundancyTestFailedCause, PT := CST_FaultDisplayDebounce);
RedundancyTestFailed := TonRedundancyDisplay.Q OR NOT RedundancyTestFailedAck;

TonArmingFailedDisplay(IN := EmergencyArmingFailedCause, PT := CST_FaultDisplayDebounce);
EmergencyArmingFailed := TonArmingFailedDisplay.Q OR NOT EmergencyArmingFailedAck;

// 📤 8. SYNTHÈSE DES ERREURS (bitfield affiché, basé sur RedundancyTestFailed/EmergencyArmingFailed affichés)
ErrorId := 16#0000;
IF RedundancyTestFailed THEN
    ErrorId := ErrorId OR 16#0001;
END_IF;
IF EmergencyArmingFailed THEN
    ErrorId := ErrorId OR 16#0002;
END_IF;
// bit3 (16#0008) = StartupFail, positionné au §2 si autotest échoué
// — ne pas l'effacer ici (reset explicite requis)

Error := (ErrorId <> 16#0000);

(* =======================================================================
   ⚖️ FB_WinchSync — Surveillance de synchro M1/M2 (sans correction)
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Calcul d'écart de position entre M1 et M2 et contrôle de cohérence
   📄 Doc métier : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md
   🔌 Interface : FB standard de surveillance transverse (1 instance)
   🔒 Sécurité : Génération d'avertissement et détection de discordances
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_WinchSync
VAR_INPUT
    // === COMMANDES ET CONSIGNES ===
    Enable                          : BOOL;                           // --> [CMD] Validation surveillance globale
    Reset                           : BOOL;                           // --> [CMD] Acquittement defaut sur front
    Mode                            : E_Mode;                         // --> [CMD] Mode courant pour arbitrage SyncActive
    SyncEnable                      : BOOL;                           // --> [CMD] Autorisation utilisateur synchro

    // === SECOURS ET HARDWARE ===
    PowerContactorEngaged           : BOOL;                           // --> [SAFE] Puissance contacteur ligne engagee

    // === MESURES ET ETATS CODEURS ===
    CablePosM1                      : REAL;                           // --> [HW] Position cable treuil M1 (m)
    CablePosM2                      : REAL;                           // --> [HW] Position cable treuil M2 (m)
    HomedM1                         : BOOL;                           // --> [HW] Treuil M1 reference
    HomedM2                         : BOOL;                           // --> [HW] Treuil M2 reference

    // === REGLAGES ET CONFIGURATION ===
    CfgSyncToleranceM               : REAL := 0.10;                   // --> [CFG] Ecart max tolere avant alerte (m)
    ActiveOffsetM                   : REAL := 0.0;                    // --> [CFG] Offset cible applique (ex: benne)

    // === COMMANDES ET FEEDBACKS ACTIONS ===
    RelayFwdM1                      : BOOL;                           // --> [HW] Feedback/Ordre montee M1
    RelayFwdM2                      : BOOL;                           // --> [HW] Feedback/Ordre montee M2
    RelayRevM1                      : BOOL;                           // --> [HW] Feedback/Ordre descente M1
    RelayRevM2                      : BOOL;                           // --> [HW] Feedback/Ordre descente M2
    Contactor1_M1                   : BOOL;                           // --> [HW] Contacteur palier 1 M1
    Contactor1_M2                   : BOOL;                           // --> [HW] Contacteur palier 1 M2
    Contactor2_M1                   : BOOL;                           // --> [HW] Contacteur palier 2 M1
    Contactor2_M2                   : BOOL;                           // --> [HW] Contacteur palier 2 M2
    Contactor3_M1                   : BOOL;                           // --> [HW] Contacteur palier 3 M1
    Contactor3_M2                   : BOOL;                           // --> [HW] Contacteur palier 3 M2
    Contactor4_M1                   : BOOL;                           // --> [HW] Contacteur palier 4 M1
    Contactor4_M2                   : BOOL;                           // --> [HW] Contacteur palier 4 M2

    // === BYPASSES ET SIMULATION ===
    BypassGlobal                    : BOOL := FALSE;                  // --> [TST] Force ErrorId=0 global
END_VAR
VAR_OUTPUT
    // === ETATS IEC ET SYNOPTIQUE ===
    Ready                           : BOOL;                           // <-- [STAT] FB pret a fonctionner
    Busy                            : BOOL;                           // <-- [STAT] Traitement en cours
    Done                            : BOOL;                           // <-- [STAT] Action terminee
    Error                           : BOOL;                           // <-- [STAT] Synthese defaut
    ErrorId                         : WORD;                           // <-- [DIAG] Code erreur bitmask (bit0: ecart, bit1: incoherence)
    State                           : E_State;                        // <-- [STAT] Etat courant machine d'etat FB
    StateAtError                    : E_State;                        // <-- [DIAG] Etat memorise lors du dernier defaut

    // === MESURES ET DIAGNOSTICS DE SYNCHRO ===
    DeltaPosM                       : REAL;                           // <-- [DIAG] Ecart absolu position |M1 - M2| (m)
    SignedDeltaPosM                 : REAL;                           // <-- [DIAG] Ecart signe position (M1 - M2) (m)
    SyncActive                      : BOOL;                           // <-- [STAT] Statut synchro active selon mode
    SyncWarn                        : BOOL;                           // <-- [DIAG] Avertissement IHM ecart tolere depasse
    SyncDegradedStep1               : BOOL;                           // <-- [DIAG] Forcage palier 1 sur ecart modere
END_VAR
VAR
    // === DETECTEURS ET TIMERS INTERNES ===
    ResetEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Reset
    ErrorEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Erreur
    MismatchTimer                   : TON;                            // . [LOC] Tempo filtrage incoherence commande
    DeviationTimer                  : TON;                            // . [LOC] Tempo filtrage transitoire ecart

    // === VARIABLES LOCALES INTERNES ===
    MismatchActive                  : BOOL;                           // . [LOC] Discordance commande active
    DeviationActive                 : BOOL;                           // . [LOC] Ecart position hors tolerance actif
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_WinchSync) ===

{region "§1 Gate neutralisation"}
// 🛑 1. GATE
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    State := E_State.DISABLED;
    DeltaPosM := 0.0;
    SyncActive := FALSE;
    SyncWarn := FALSE;
    SyncDegradedStep1 := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

{endregion}

{region "§2 Initialisation et activation synchro"}
Ready := TRUE;
State := E_State.READY;

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🌐 BYPASS GLOBAL : force ErrorId = 0 et ignore toute la surveillance synchro
IF BypassGlobal THEN
    ErrorId := 16#0000;
END_IF;

// 🎚️ 3. SyncActive SELON MODE (Partie9 §9)
CASE Mode OF
    E_Mode.MAINT_N1:
        SyncActive := TRUE;                  // Imposée, non désactivable (sécurité maintenue N1)
    E_Mode.MAINT_N2:
        SyncActive := SyncEnable;             // Polarité positive (TRUE = synchro active)
    ELSE
        SyncActive := TRUE;                  // MANUEL/SEMI_AUTO : pas de logique dédiée (FB_Cycle absent), actif par prudence
END_CASE;

{endregion}

{region "§3 Calcul ecart position"}
// 📏 4. ÉCART M1/M2 — calculé en continu si les 2 treuils sont homés (même si BypassGlobal est actif)
IF HomedM1 AND HomedM2 THEN
    SignedDeltaPosM := CablePosM1 - CablePosM2 + ActiveOffsetM;
    DeltaPosM := ABS(SignedDeltaPosM);
ELSE
    SignedDeltaPosM := 0.0;
    DeltaPosM := 0.0;
END_IF;

{endregion}

{region "§4 Surveillance synchronisme"}
// 🌐 BYPASS GLOBAL : si actif, on saute TOUTE la logique d'erreur/surveillance
IF NOT BypassGlobal THEN

// 🔍 5. DÉTECTION ÉCART HORS TOLÉRANCE — bit0
// Filtre temporel (même pattern que MismatchTimer bit1) — absorbe le transitoire mécanique
// normal d'arrêt (coast-down différentiel M1/M2), évite le blocage intempestif.
// Si écart > CfgSyncToleranceM -> alarme d'écart (SyncWarn / bit0) et dégradation en vitesse
// lente Palier 1 (SyncDegradedStep1). L'arrêt brutal SafeStop est réservé à l'écart critique
// Méca E (> CriticalSyncToleranceM).
DeviationActive := SyncActive AND HomedM1 AND HomedM2 AND (DeltaPosM > CfgSyncToleranceM);
DeviationTimer(IN := DeviationActive, PT := T#800ms);  // 🔧 théorique, à ajuster sur site — absorbe le transitoire mécanique normal d'arrêt (coast-down différentiel M1/M2)
IF DeviationTimer.Q THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q AND NOT DeviationActive THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 🐢 Dégradation au Palier 1 dès que l'écart dépasse la tolérance (sans attendre le SafeStop)
SyncDegradedStep1 := SyncActive AND HomedM1 AND HomedM2 AND ((DeltaPosM > CfgSyncToleranceM) OR ((ErrorId AND 16#0001) <> 16#0000));

// 🔍 5bis. COHÉRENCE DES COMMANDES SÉCURITÉ — bit1
// Vérifie que les commandes envoyées aux deux treuils sont identiques (sens et contacteurs)
// Filtre de 500ms pour tolérer les transitions et rampes.
MismatchActive := SyncActive AND (
    (RelayFwdM1 <> RelayFwdM2) OR
    (RelayRevM1 <> RelayRevM2) OR
    (Contactor1_M1 <> Contactor1_M2) OR
    (Contactor2_M1 <> Contactor2_M2) OR
    (Contactor3_M1 <> Contactor3_M2) OR
    (Contactor4_M1 <> Contactor4_M2)
);

MismatchTimer(IN := MismatchActive, PT := T#500ms);

IF MismatchTimer.Q THEN
    ErrorId := ErrorId OR 16#0002;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFD;
END_IF; // fin du IF MismatchActive

ELSE
    SyncDegradedStep1 := FALSE;
END_IF; // fin IF NOT BypassGlobal

{endregion}

{region "§5 Etats et diagnostic"}
// 📤 6. SORTIES ÉTAT
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

SyncWarn := Error;   // ⚠️ IHM uniquement — voir en-tête, pas de SafeStop
Busy := FALSE;
Done := FALSE;

{endregion}

(* =======================================================================
   🪜 FB_SpeedStep — Décodeur palier vitesse vers contacteurs
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Décodage consigne vitesse 0..100% en paliers et pilotage contacteurs
   📄 Doc métier : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md
   🔌 Interface : Décodeur interne (compose FB_Winch)
   🔒 Sécurité : Validation configuration table et anti-battement hysteresis
   ======================================================================= *)

{attribute 'qualified_only'}
{attribute 'hide_all_locals'}

// === DECLARATION (à coller dans la partie déclaration du POU FB_SpeedStep) ===

FUNCTION_BLOCK PUBLIC FB_SpeedStep
VAR_INPUT
    // === COMMANDES ET CONSIGNES ===
    Enable                          : BOOL;                           // --> [CMD] Pilotage actif (FALSE = palier 0 / arret)
    SpeedRefPct                     : REAL;                           // --> [CMD] Consigne vitesse 0..100%

    // === REGLAGES ET CONFIGURATION ===
    Table                           : ST_SpeedStepTable;              // --> [CFG] Table des 5 paliers propre au treuil
    HystMargin                      : REAL := 2.0;                    // --> [CFG] Marge anti-battement (%)
    MaxStepNumber                   : INT := 5;                       // --> [CFG] Plafond palier atteignable (1..5)

    // === MESURES ET GARDE-FOUS ===
    MeasuredSpeedBand               : INT := 0;                       // --> [HW] Bande vitesse reelle validee
    SpeedGuardEnable                : BOOL := FALSE;                  // --> [HW] Garde-fou palier activable
    SpeedGuardReady                 : BOOL := FALSE;                  // --> [HW] Conditions de passage validees
END_VAR
VAR_OUTPUT
    // === ETATS IEC ET SYNOPTIQUE ===
    StepNumber                      : INT;                            // <-- [STAT] Numero de palier courant (0..5)

    // === ORDRES ACTIONNEURS (CONTACTEURS) ===
    Contactor1                      : BOOL;                           // <-- [ACT] Ordre contacteur vitesse palier 1
    Contactor2                      : BOOL;                           // <-- [ACT] Ordre contacteur vitesse palier 2
    Contactor3                      : BOOL;                           // <-- [ACT] Ordre contacteur vitesse palier 3
    Contactor4                      : BOOL;                           // <-- [ACT] Ordre contacteur vitesse palier 4

    // === DIAGNOSTICS ET ERREURS ===
    SpeedGuardLimited               : BOOL;                           // <-- [DIAG] Statut limitation par garde-fou
    ConfigError                     : BOOL;                           // <-- [DIAG] Synthese erreur configuration
    ConfigErrorId                   : WORD;                           // <-- [DIAG] Bitfield erreur configuration
END_VAR
VAR
    // === SOUS-INSTANCES FB ===
    Hyst1                           : HYSTERESIS;                     // * [INST] Transition palier 1 vers 2
    Hyst2                           : HYSTERESIS;                     // * [INST] Transition palier 2 vers 3
    Hyst3                           : HYSTERESIS;                     // * [INST] Transition palier 3 vers 4
    Hyst4                           : HYSTERESIS;                     // * [INST] Transition palier 4 vers 5
    _ConfigErrorTrig                : R_TRIG;                         // * [INST] Front montant erreur configuration

    // === VARIABLES LOCALES INTERNES ===
    SpeedRefInt                     : INT;                            // . [LOC] Consigne convertie en INT pour Hysteresis
    _ConfigValid                    : BOOL;                           // . [LOC] Resultat validation table et MaxStep
    _ConfigValidPrev                : BOOL;                           // . [LOC] Memoire cycle precedent validation
    _ConfigErrorIdInt               : WORD;                           // . [LOC] Accumulateur interne defauts config
    _MaxStepClamped                 : INT;                            // . [LOC] MaxStepNumber borne dans [1..5]
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_SpeedStep) ===

{region "§0 Validation configuration"}
// ─────────────────────────────────────────────────────────────────────────
// 🛡️ 0. VALIDATION CONFIGURATION (P0.2) — exécutée CHAQUE cycle pour détecter
//    toute corruption IHM/PERSISTENT, même siEnable=FALSE (sorties sûres forcée)
// ─────────────────────────────────────────────────────────────────────────

// 🔧 Bornage systématique MaxStepNumber ∈ [1..5]
IF MaxStepNumber < 1 THEN
    _MaxStepClamped := 1;
ELSIF MaxStepNumber > 5 THEN
    _MaxStepClamped := 5;
ELSE
    _MaxStepClamped := MaxStepNumber;
END_IF;

// 🔍 Validation table ST_SpeedStepTable
// Critères (Partie 9 §2) :
// 1. Seuils croissants stricts : StepThreshold_Pct[1] < [2] < [3] < [4] < [5]
// 2. Seuils dans [0..100] %
// 3. HystMargin > 0
// 4. Pour chaque palier 2.._MaxStepClamped : au moins 1 contacteur TRUE (cohérence câblage)
//    Le palier 1 peut légitimement avoir les 4 contacteurs FALSE : résistances rotoriques
//    toutes insérées = vitesse minimale. On ne valide pas les paliers jamais atteignables.
_ConfigValid := TRUE;
_ConfigErrorIdInt := 16#0000;

// Critère 1 : seuils croissants
IF NOT (Table.StepThreshold_Pct[1] < Table.StepThreshold_Pct[2] AND
        Table.StepThreshold_Pct[2] < Table.StepThreshold_Pct[3] AND
        Table.StepThreshold_Pct[3] < Table.StepThreshold_Pct[4] AND
        Table.StepThreshold_Pct[4] < Table.StepThreshold_Pct[5]) THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;  // bit0
END_IF;

// Critère 2 : seuils dans [0..100]
IF (Table.StepThreshold_Pct[1] < 0.0) OR (Table.StepThreshold_Pct[5] > 100.0) THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
END_IF;

// Critère 3 : hystérésis > 0
IF HystMargin <= 0.0 THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
END_IF;

// Critère 4 : cohérence contacteurs par palier (seulement jusqu'au plafond actif)
IF _ConfigValid THEN
    // Palier 1 : les 4 sorties FALSE sont une configuration valide de vitesse minimale.
    // Palier 2
    IF _MaxStepClamped >= 2 THEN
        IF NOT (Table.P2R1 OR Table.P2R2 OR Table.P2R3 OR Table.P2R4) THEN
            _ConfigValid := FALSE;
            _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
        END_IF;
    END_IF;
    // Palier 3
    IF _MaxStepClamped >= 3 THEN
        IF NOT (Table.P3R1 OR Table.P3R2 OR Table.P3R3 OR Table.P3R4) THEN
            _ConfigValid := FALSE;
            _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
        END_IF;
    END_IF;
    // Palier 4
    IF _MaxStepClamped >= 4 THEN
        IF NOT (Table.P4R1 OR Table.P4R2 OR Table.P4R3 OR Table.P4R4) THEN
            _ConfigValid := FALSE;
            _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
        END_IF;
    END_IF;
    // Palier 5
    IF _MaxStepClamped >= 5 THEN
        IF NOT (Table.P5R1 OR Table.P5R2 OR Table.P5R3 OR Table.P5R4) THEN
            _ConfigValid := FALSE;
            _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
        END_IF;
    END_IF;
END_IF;

// 🛡️ Gestion erreur config : front montant + reset sur front Reset (cause disparue)
// Note : pas d'entrée Reset dédiée (brique réduite) → on réarme quand config redevient valide
//        (front descendant de _ConfigValid). Conforme Partie 3 §5 : cause disparue + front.
_ConfigErrorTrig(CLK := NOT _ConfigValid);  // Front montant = apparition erreur

// Mémoire erreur config : reste TRUE tant que config invalide OU pas de réarmement
// Réarmement = front montant de _ConfigValid (cause disparue) — détecté via _ConfigValidPrev
IF _ConfigErrorTrig.Q THEN
    // Nouvelle erreur : on la mémorise
    _ConfigValidPrev := FALSE;  // Force détection front montant au cycle suivant si redevient valide
ELSIF _ConfigValid AND NOT _ConfigValidPrev THEN
    // Config redevenue valide : front montant → on efface l'erreur (reset sur front)
    _ConfigValidPrev := TRUE;
ELSIF NOT _ConfigValid THEN
    _ConfigValidPrev := FALSE;
END_IF;

// Sorties erreur config (miroir standard Partie 3)
ConfigErrorId := _ConfigErrorIdInt;
ConfigError   := (ConfigErrorId <> 16#0000);
{endregion}

{region "§1 Gate"}
// ─────────────────────────────────────────────────────────────────────────
// 🛑 1. GATE — Enable FALSE OU config invalide = palier 0, sorties sûres
// ─────────────────────────────────────────────────────────────────────────
IF (NOT Enable) OR (NOT _ConfigValid) THEN
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    StepNumber := 0;
    SpeedGuardLimited := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Sélection palier"}
// ─────────────────────────────────────────────────────────────────────────
// 🪜 2. SÉLECTION DU PALIER (HYSTERESIS lib Util : IN/HIGH/LOW → OUT)
//    OUT = TRUE tant que IN < LOW (régime "bas") ; OUT bascule à FALSE une fois
//    IN > HIGH (régime "haut" confirmé) ; maintien entre LOW et HIGH (anti-battement).
//    => NOT Hyst_n.OUT = "on a franchi le seuil n vers le haut" (palier n+1 atteint).
// ─────────────────────────────────────────────────────────────────────────
SpeedRefInt := REAL_TO_INT(SpeedRefPct);

Hyst1(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[1] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[1] - HystMargin));
Hyst2(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[2] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[2] - HystMargin));
Hyst3(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[3] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[3] - HystMargin));
Hyst4(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[4] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[4] - HystMargin));

StepNumber := 1;                          // Palier mini dès qu'Enable est actif
IF NOT Hyst1.OUT THEN StepNumber := 2; END_IF;
IF NOT Hyst2.OUT THEN StepNumber := 3; END_IF;
IF NOT Hyst3.OUT THEN StepNumber := 4; END_IF;
IF NOT Hyst4.OUT THEN StepNumber := 5; END_IF;

// ─────────────────────────────────────────────────────────────────────────
// 2bis. PLAFOND — appliqué APRÈS la sélection hystérésis,
// AVANT la lecture table : le 0..100% de la consigne peut réclamer le palier 5,
// mais ne dépassera jamais _MaxStepClamped (ex. limitation couple en descente)
// ─────────────────────────────────────────────────────────────────────────
IF StepNumber > _MaxStepClamped THEN
    StepNumber := _MaxStepClamped;
END_IF;
{endregion}

{region "§2ter Garde-fou vitesse"}
// ─────────────────────────────────────────────────────────────────────────
// 🛡️ 2ter. GARDE-FOU VITESSE RÉELLE — limite uniquement la consigne de palier.
// Si la vitesse n'est pas validée stable, seul le palier 1 reste autorisé.
// ─────────────────────────────────────────────────────────────────────────
SpeedGuardLimited := FALSE;
IF SpeedGuardEnable THEN
    IF NOT SpeedGuardReady THEN
        IF StepNumber > 1 THEN
            StepNumber := 1;
            SpeedGuardLimited := TRUE;
        END_IF;
    ELSIF (MeasuredSpeedBand >= 1) AND (MeasuredSpeedBand <= 5) AND (StepNumber > MeasuredSpeedBand) THEN
        StepNumber := MeasuredSpeedBand;
        SpeedGuardLimited := TRUE;
    END_IF;
END_IF;
{endregion}

{region "§3 Contacteurs"}
// ─────────────────────────────────────────────────────────────────────────
// 📤 3. CONTACTEURS — lus dans la table (donnée, jamais codé en dur)
//    CASE couvre explicitement 0..5 : StepNumber=0 → tous FALSE (sécurité)
// ─────────────────────────────────────────────────────────────────────────
CASE StepNumber OF
    0:  // Arrêt / config invalide / Enable=FALSE — sécurité positive
        Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    1:  Contactor1 := Table.P1R1; Contactor2 := Table.P1R2; Contactor3 := Table.P1R3; Contactor4 := Table.P1R4;
    2:  Contactor1 := Table.P2R1; Contactor2 := Table.P2R2; Contactor3 := Table.P2R3; Contactor4 := Table.P2R4;
    3:  Contactor1 := Table.P3R1; Contactor2 := Table.P3R2; Contactor3 := Table.P3R3; Contactor4 := Table.P3R4;
    4:  Contactor1 := Table.P4R1; Contactor2 := Table.P4R2; Contactor3 := Table.P4R3; Contactor4 := Table.P4R4;
    5:  Contactor1 := Table.P5R1; Contactor2 := Table.P5R2; Contactor3 := Table.P5R3; Contactor4 := Table.P5R4;
ELSE
    // Défense en profondeur : valeur StepNumber inattendue → sécurité
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    StepNumber := 0;
END_CASE;
{endregion}

