       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);

    ASSERT_FALSE(fb.ERROR, 'front Reset avec axes revenus en zone valide doit acquitter (cause disparue + appui conscient)');
END_TEST

(* ═══════════════════════════════════════════════════════════════
   🧪 FB_SimBench — Enveloppe unique de simulation pour banc d'essai
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-13_Fonction_Simulation_v2.1.md
   📄 Lot L6 (Rebranchement du banc de simulation derrière HwIn)
   
   🎯 Rôle : Compose les 4 blocs de modèle de simulation existants :
      - FB_Sim_Encoder (instM1, instM2)
      - FB_Sim_Translation (instTranslation)
      - FB_Sim_Joystick (instJoystick)
      - FB_Sim_Safety (instSafety)
   
   🔒 Brique réduite : 0 lecture de variable globale en interne.
      Toutes les entrées (commandes, stimuli, HwReal) sont passées en paramètres.
   
   🔴 RÈGLES SÉCURITÉ ET POLARITÉ :
      - Modèle frein M1/M2/M3 : M1_BrakeIsOpen_DI := M1_BrakeCmd (1 = OUVERT).
        Ne JAMAIS faire NOT BrakeCmd ! (P1 Lot L6).
      - Retours contacteurs M1/M2 : 1 = tous retombés (TRUE quand RelayFwd=0 et RelayRev=0).
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_SimBench
VAR_INPUT
    Enable                     : BOOL;             // Activation globale (GVL_Simulation.SimulationModeActive)

    // ── Commandes issues de l'automate (Scan N-1 / PRG_07 / PRG_10) ──────────
    M1_RelayFwd                : BOOL;
    M1_RelayRev                : BOOL;
    // 🔧 REX 2026-07-27 : les 4 contacteurs de palier participent au retour unique
    // « tous contacteurs retombés » — sans eux, le modèle annonce l'arrêt alors qu'un
    // palier est encore engagé (fausse condition d'armement Méca A).
    M1_SpeedContactor_1        : BOOL;
    M1_SpeedContactor_2        : BOOL;
    M1_SpeedContactor_3        : BOOL;
    M1_SpeedContactor_4        : BOOL;
    M1_SpeedRefPct             : REAL;
    M1_PresetTriggerCmd        : WORD;
    M1_PresetValueOut          : UDINT;
    M1_BrakeCmd                : BOOL;             // TRUE = commande desserrage frein M1

    M2_RelayFwd                : BOOL;
    M2_RelayRev                : BOOL;
    M2_SpeedContactor_1        : BOOL;   // 🔧 REX 2026-07-27 : idem M1, voir ci-dessus
    M2_SpeedContactor_2        : BOOL;
    M2_SpeedContactor_3        : BOOL;
    M2_SpeedContactor_4        : BOOL;
    M2_SpeedRefPct             : REAL;
    M2_PresetTriggerCmd        : WORD;
    M2_PresetValueOut          : UDINT;
    M2_BrakeCmd                : BOOL;             // TRUE = commande desserrage frein M2

    M3_Direction               : INT;              // 1 = Avant, -1 = Arrière, 0 = Arrêt
    M3_SpeedRefPct             : REAL;
    M3_BrakeCmd                : BOOL;             // TRUE = commande desserrage frein M3
    M3_TargetNum               : INT;              // Cible sélectionnée (0..4)

    PowerKeepAlive_A           : BOOL;             // TRUE = relais A maintenu sagement par le PLC
    PowerKeepAlive_B           : BOOL;             // TRUE = relais B maintenu sagement par le PLC
    EmergencyArming_RQ         : BOOL;             // Impulsion de réarmement puissance

    // ── Stimuli & Paramètres de banc ─────────────────────────────────────────
    SimEncoderSpeedFactor      : REAL := 1.0;
    SimSyncDeviationInjectM1   : BOOL := FALSE;
    SimSyncDeviationInjectM2   : BOOL := FALSE;
    SimSyncDeviationOffset_M   : REAL := 0.5;

    SimM3SensorsWordActive     : BOOL := FALSE;
    SimM3SensorsWord           : BYTE := 16#01;

    SimJoystickRawX            : INT := 5000;
    SimJoystickRawY            : INT := 5000;
    SimJoystickRawButton       : BOOL := FALSE;

    SimKoboldContactValue      : BOOL := FALSE;
    BtnEmergencyStop           : BOOL := FALSE;    // Simulation appui coup-de-poing AU

    // ── Image réelle fallback ────────────────────────────────────────────────
    HwReal                     : ST_HardwareImage;
END_VAR

VAR_OUTPUT
    Winch                      : ST_HwWinch;
    Translation                : ST_HwTranslation;
    Operator                   : ST_HwOperator;
    Machine                    : ST_HwMachine;
END_VAR

VAR_IN_OUT
    RawPosM1                   : UDINT;            // Mémoire _SimEncoderRawPosM1 dans GVL_PERSISTENT
    RawPosM2                   : UDINT;            // Mémoire _SimEncoderRawPosM2 dans GVL_PERSISTENT
END_VAR

VAR
    // Modèles sous-jacents
    instSimEncoderM1           : FB_Sim_Encoder;
    instSimEncoderM2           : FB_Sim_Encoder;
    instSimTranslation         : FB_Sim_Translation;
    instSimJoystick            : FB_Sim_Joystick;
    instSimSafety              : FB_Sim_Safety;

    // Calculs internes
    M1_PresetCmd               : BOOL;
    M2_PresetCmd               : BOOL;
    M1_OffsetPts               : DINT;
    M2_OffsetPts               : DINT;

    M3_RelayFwd                : BOOL;
    M3_RelayRev                : BOOL;

    M3_ActualFreqHz            : UINT;
    M3_StatusWordSim           : WORD;
END_VAR

// === IMPLEMENTATION ===

IF NOT Enable THEN
    Winch       := HwReal.Winch;
    Translation := HwReal.Translation;
    Operator    := HwReal.Operator;
    Machine     := HwReal.Machine;
    RETURN;
END_IF;


// ── 1. MODÈLE TREUILS (M1 + M2) ─────────────────────────────────────────────
// Presets codeurs : déclenchés si PresetTriggerCmd = 2
M1_PresetCmd := (M1_PresetTriggerCmd = 2);
M2_PresetCmd := (M2_PresetTriggerCmd = 2);

// Conversions d'injection d'écart synchro (0.5m -> points codeur avec 8192 pts/tour, 2m/tour)
// 1m = 4096 points codeur.
M1_OffsetPts := REAL_TO_DINT(SimSyncDeviationOffset_M * 4096.0);
M2_OffsetPts := REAL_TO_DINT(SimSyncDeviationOffset_M * 4096.0);

// Instance modèle codeur M1
instSimEncoderM1(
    Enable           := TRUE,
    RelayFwd         := M1_RelayFwd,
    RelayRev         := M1_RelayRev,
    SpeedRefPct      := M1_SpeedRefPct,
    PresetCmd        := M1_PresetCmd,
    PresetValue      := M1_PresetValueOut,
    SpeedScaleFactor := SimEncoderSpeedFactor,
    TestOffsetCmd    := SimSyncDeviationInjectM1,
    TestOffsetPts    := M1_OffsetPts,
    RawPos           := RawPosM1
);

// Instance modèle codeur M2
instSimEncoderM2(
    Enable           := TRUE,
    RelayFwd         := M2_RelayFwd,
    RelayRev         := M2_RelayRev,
    SpeedRefPct      := M2_SpeedRefPct,
    PresetCmd        := M2_PresetCmd,
    PresetValue      := M2_PresetValueOut,
    SpeedScaleFactor := SimEncoderSpeedFactor,
    TestOffsetCmd    := SimSyncDeviationInjectM2,
    TestOffsetPts    := M2_OffsetPts,
    RawPos           := RawPosM2
);

// Recopie structures Winch simulées :
// 🛑 POLARITÉ DE FREIN SIMULÉ (P1 Lot L6) : 1 = contacteur commandé = frein OUVERT.
// Câblage réel : DI = 1 ⟺ frein OUVERT. Le modèle produit donc M1_BrakeIsOpen_DI := M1_BrakeCmd !
Winch.M1_BrakeIsOpen_DI        := M1_BrakeCmd;
// 🔧 REX 2026-07-27 : retour UNIQUE « tous contacteurs retombés » = sens ET vitesse.
// Omettre les paliers ferait croire à l'arrêt pendant les transitoires → Méca A armée à tort.
Winch.M1_ContactorsReleased_DI := NOT (M1_RelayFwd OR M1_RelayRev
                                    OR M1_SpeedContactor_1 OR M1_SpeedContactor_2
                                    OR M1_SpeedContactor_3 OR M1_SpeedContactor_4);
Winch.M1_ThermalOk_DI          := TRUE; // Sauf panne simulée

Winch.M2_BrakeIsOpen_DI        := M2_BrakeCmd;
Winch.M2_ContactorsReleased_DI := NOT (M2_RelayFwd OR M2_RelayRev
                                    OR M2_SpeedContactor_1 OR M2_SpeedContactor_2
                                    OR M2_SpeedContactor_3 OR M2_SpeedContactor_4);
Winch.M2_ThermalOk_DI          := TRUE;

Winch.M1M2_TopPositionFree_DI  := TRUE; // Butée libre au repos en simu
Winch.M2_TensionedCable_DI     := TRUE; // Câble tendu en simu

Winch.COD1_PosValue            := instSimEncoderM1.RawPosOut;
Winch.COD1_Alarms              := 0;
Winch.COD1_Warnings            := 0;
Winch.COD1_DeviceState         := 4; // DEVICE_STATE RUNNING = 4 (bus OK)

Winch.COD2_PosValue            := instSimEncoderM2.RawPosOut;
Winch.COD2_Alarms              := 0;
Winch.COD2_Warnings            := 0;
Winch.COD2_DeviceState         := 4; // DEVICE_STATE RUNNING = 4


// ── 2. MODÈLE TRANSLATION M3 (AC600) ─────────────────────────────────────────
M3_RelayFwd := (M3_Direction = 1);
M3_RelayRev := (M3_Direction = -1);

instSimTranslation(
    Enable      := TRUE,
    TargetNum   := M3_TargetNum,
    RelayFwd    := M3_RelayFwd,
    RelayRev    := M3_RelayRev,
    TravelTimeS := 8.0,
    PVLeadTimeS := 2.0
);

// Remplissage capteurs de position M3 :
IF SimM3SensorsWordActive THEN
    Translation.M3_PosTremie_DI      := SimM3SensorsWord.0;
    Translation.M3_PosPV_DI          := SimM3SensorsWord.1;
    Translation.M3_PosP2_DI          := SimM3SensorsWord.2;
    Translation.M3_PosP1_DI          := SimM3SensorsWord.3;
    Translation.M3_PosMaintenance_DI := SimM3SensorsWord.4;
ELSE
    Translation.M3_PosTremie_DI      := instSimTranslation.PosTremie;
    Translation.M3_PosPV_DI          := instSimTranslation.PosPV;
    Translation.M3_PosP2_DI          := instSimTranslation.PosP2;
    Translation.M3_PosP1_DI          := instSimTranslation.PosP1;
    Translation.M3_PosMaintenance_DI := instSimTranslation.PosMaintenance;
END_IF;

// Polarité frein M3 (1 = OUVERT)
Translation.M3_BrakeIsOpen_DI    := M3_BrakeCmd;

// 🆕 T96 : thermique moteur/variateur AC600 — pas de panne simulée, toujours OK (comme Winch.M1/M2_ThermalOk_DI)
Translation.M3_ThermalOK_DI      := TRUE;

// Simulation StatusWord AC600 : Bit 0 (Power Ready) = 1, Bit 7 (Comm Ready) = 1 -> 16#0081
IF (M3_Direction <> 0) THEN
    M3_StatusWordSim := 16#0087; // + Operating/Running
    M3_ActualFreqHz  := REAL_TO_UINT(M3_SpeedRefPct * 50.0); // 50.0 Hz à 100% (x100 -> 5000)
ELSE
    M3_StatusWordSim := 16#0081;
    M3_ActualFreqHz  := 0;
END_IF;

Translation.M3_StatusWord        := M3_StatusWordSim;
Translation.M3_ActualFrequencyHz := M3_ActualFreqHz;
Translation.AC600_DeviceState    := 4; // DEVICE_STATE RUNNING = 4


// ── 3. MODÈLE OPÉRATEUR / JOYSTICK ───────────────────────────────────────────
instSimJoystick(
    Enable     := TRUE,
    NeutralRaw := 5000,
    MaxRaw     := 10000
);

// Permet aux stimuli de banc de surcharger le retour du joystick si spécifié :
IF SimJoystickRawX <> 5000 THEN
    Operator.JoyXRaw_ANA1 := SimJoystickRawX;
ELSE
    Operator.JoyXRaw_ANA1 := instSimJoystick.RawX;
END_IF;

IF SimJoystickRawY <> 5000 THEN
    Operator.JoyYRaw_ANA2 := SimJoystickRawY;
ELSE
    Operator.JoyYRaw_ANA2 := instSimJoystick.RawY;
END_IF;

IF SimJoystickRawButton THEN
    Operator.JoyBtnRaw := TRUE;
ELSE
    Operator.JoyBtnRaw := instSimJoystick.RawButton;
END_IF;

Operator.CanBusState      := 2; // CANbusState 2 = ACTIVE (confirmé terrain)
Operator.JOY1_DeviceState := 4; // DEVICE_STATE RUNNING = 4


// ── 4. MODÈLE SÉCURITÉ & COMMUNS MACHINE ─────────────────────────────────────
instSimSafety(
    Enable           := TRUE,
    PowerCutOff_A    := PowerKeepAlive_A,
    PowerCutOff_B    := PowerKeepAlive_B,
    EmergencyArming  := EmergencyArming_RQ,
    BtnEmergencyStop := BtnEmergencyStop
);

Machine.PowerContactorEngaged_DI   := instSimSafety.SimContactorOk;
Machine.EmergencyChainClosed_DI    := instSimSafety.SimChainOk;
Machine.PhaseRotationOk_DI         := TRUE;
Machine.BrakeThermalOk_DI          := TRUE;
Machine.M1_M2_KoboldContactFond_DI := SimKoboldContactValue;
Machine.HydraulicThermalOk_DI      := TRUE;

(* ═══════════════════════════════════════════════════════════════
   ↔️ FB_Translation — Directeur de l'axe transversal M3 (variateur AC600)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : ARCHIVES/Doc/AF_Partie-11_Fonction_Translation_v2.0.md
   🔌 FB DE MOUVEMENT : porte StartStop + SafeStop en plus de l'interface
      standard. Précédence Enable > SafeStop > StartStop.
   📡 Pilotage exclusivement ETHERCAT nominal (mot de commande, consigne fréquence).
   🧩 Compose FB_Brake (réutilisé TEL QUEL depuis COMMUN).
   ⚠️ CORRECTIF (retour terrain 2026-08-05) : une inversion de sens PLUS RAPIDE que le
      temps de décélération réel bloquait indéfiniment `CommandedDirection` (la translation
      ne s'arrêtait jamais, continuait dans l'ancien sens) — la cible de rampe suivait la
      magnitude joystick en continu, sans garantie de croiser le seuil d'arrêt qui
      autorise l'interlock changement de sens (§5). Même bug déjà corrigé sur `FB_Winch`
      (REX 2026-07-02), jamais porté ici. Corrigé : `DirectionChangePending` FORCE
      désormais la cible à 0.0 dès qu'un changement de sens est en attente, de façon
      déterministe et indépendante du joystick (voir §4 dans le corps ST).
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Translation
VAR_INPUT
    Enable                      : BOOL;        // Active le FB. FALSE = neutralisation totale (sorties coupées)
    Reset                       : BOOL;        // Acquittement défaut (front)
    PowerContactorEngaged             : BOOL;        // Chaîne AU réarmée + conditions globales OK
    Mode                        : E_Mode;      // Mode courant
    StartStop                   : BOOL;        // TRUE = rampe accélération, FALSE = rampe décélération NORMALE
    SafeStop                    : BOOL;        // Sortie FB_Safety_Translation : TRUE = rampe décélération RAPIDE (Enable maintenu)
    Direction                   : INT;         // -1 = Rev, 0 = Neutre, +1 = Fwd (source d'autorité du sens)
    SpeedRefPct                 : REAL;        // Magnitude de la consigne (de 0 à 100%)
    PositionSensorTarget        : BOOL;        // Capteur position cible courante
    // 🆕 2026-08-06 : 3 capteurs déclencheurs de ralentissement, un cran avant chaque cible
    // (même principe que PV→Trémie, généralisé — voir §4bis dans le corps ST)
    SlowdownSensorTremie         : BOOL;        // Capteur PV — ralentissement avant Trémie (Direction=1)
    SlowdownSensorMaintenance    : BOOL;        // Capteur P1 — ralentissement avant Maintenance (Direction=-1)
    SlowdownSensorP1             : BOOL;        // Capteur P2 — ralentissement avant P1 (Direction=-1, arrêt propre pour travail)
    LimitSwitchFwd              : BOOL;        // Fin de course extrême avant
    LimitSwitchRev              : BOOL;        // Fin de course extrême arrière

    // 🔌 Spécifique ETHERCAT (image process EtherCAT, rafraîchie par EtherCatTask 4ms)
    DriveStatusWord              : WORD;       // Mot d'état AC600 lu depuis l'image d'entrée EtherCAT
    DriveActualFreqHz            : REAL;       // Fréquence réelle mesurée (Hz)

    BypassContactorCheck         : BOOL;       // 🧪 TRUE = désactive StuckClosed/StuckOpen pour le frein (simulation)
    BypassLimitSwitch            : BOOL;       // 🚧 TRUE = ignore les fins de course extrêmes
    BrakeFeedback                : BOOL;       // Retour physique direct : TRUE = frein OUVERT (desserré)
    // 🆕 2026-08-06 (retour terrain, REX câblage) : compense le câblage moteur (U/V inversés) —
    // UNIQUEMENT sur le mot de commande variateur en sortie (§5bis). Direction/CommandedDirection
    // reste partout ailleurs le sens SÉMANTIQUE réel (+1 = physiquement vers Trémie), pour rester
    // apparié aux vrais capteurs (LimitSwitchFwd/Rev, SlowdownSensorXxx) quel que soit le câblage.
    // ⚠️ AVANT ce correctif, l'inversion était appliquée en amont (PRG_05, sur M3_Direction_Active
    // lui-même) : avec le câblage réel de la machine, ça désaccordait TOUTE la logique sécurité/
    // ralentissement appariée aux capteurs physiques (seule la coupure dure indépendante du sens,
    // §0bis PRG_05, arrêtait encore la machine — le verrou d'arrivée logiciel ne s'armait jamais).
    InvertDriveDirection          : BOOL;

    // Réglages rampe (RETAIN)
    CfgRampAccelRate                : REAL := 20.0;    // %/s — accélération
    CfgRampDecelNormalRate          : REAL := 40.0;    // %/s — décélération normale
    CfgRampDecelFastRate            : REAL := 100.0;   // %/s — décélération RAPIDE
    DirectionInterlockDelay      : TIME := T#200ms; // Délai avant d'autoriser un changement de sens à l'arrêt

    // Réglages ETHERCAT uniquement (RETAIN)
    ApproachSpeedTremieHz        : REAL := 10.0;    // Vitesse réduite d'approche Trémie en Hz (piloté par SlowdownSensorTremie)
    ApproachSpeedMaintenanceHz   : REAL := 10.0;    // Vitesse réduite d'approche Maintenance en Hz (piloté par SlowdownSensorMaintenance)
    ApproachSpeedP1Hz            : REAL := 10.0;    // Vitesse réduite d'approche P1 en Hz (piloté par SlowdownSensorP1)
    DriveFreqScaleMaxHz          : REAL := 60.0;    // Échelle 0..100 % → MaxHz (câblé depuis _TranslationMaxFreq_Hz par PRG_07 — defaut 60.0 si non raccordé)

    // Réglages communs
    CaptorDebounce                : TIME := T#100ms; // Filtrage capteur de position cible
    BrakeDelayContactClose        : TIME := T#100ms; // Voir FB_Brake
    BrakeDelayMagnetise           : TIME := T#300ms; // Voir FB_Brake
    BrakeDelayMotorDecel          : TIME := T#500ms; // Voir FB_Brake
    BrakeFeedbackTimeout          : TIME := T#300ms; // Strictement sous watchdog final 500 ms
END_VAR
VAR_OUTPUT
    Ready               : BOOL;
    Busy                : BOOL;
    Done                : BOOL;
    Error               : BOOL;
    ErrorId             : WORD;        // bit0: "Défaut frein Translation" - Brake.Error ; bit3: "Défaut variateur AC600" - défaut variateur (DriveStatusWord.4) ; bit6: "Limite extrême Translation atteinte" - Fdc extrême atteint
    State               : E_State;
    StateAtError        : E_State;
    TargetReached        : BOOL;       // Capteur position cible
    RequestedDriveControlWord : WORD; // Demande métier AC600, arbitrée par FB_TranslationOutputInterlock_LD
    RequestedDriveFreqHz      : REAL; // Demande métier fréquence, arbitrée par FB_TranslationOutputInterlock_LD
    BrakeReleaseRequest       : BOOL; // Demande métier desserrage, issue de FB_Brake
    BrakeCommandOpenConfirmed : BOOL; // TRUE = frein ouvert = commande ouverture confirmée (depuis FB_Brake)
    BrakeContactorCheck  : ST_ContactorCheck; // Diag contacteur frein
END_VAR
VAR
    Brake                : FB_Brake;       // Séquence frein
    CycleTimeCalc        : FB_CycleTime;
    SpeedRamp             : FB_Ramp;       // Rampe de vitesse logicielle (PLC)
    ResetEdge            : R_TRIG;
    ErrorEdge            : R_TRIG;
    DirectionChangeDelay : TON;            // Interlock changement de sens
    CommandedDirection   : INT;            // Sens réellement appliqué
    DirectionChangePending : BOOL;         // 🆕 2026-08-05 : force la rampe à 0 pendant une inversion de sens en attente
    PhysicalDriveDirection : INT;          // 🆕 2026-08-06 : CommandedDirection compensé câblage (InvertDriveDirection) — UNIQUEMENT pour le mot de commande variateur, jamais pour l'appariement capteur
    RampTargetPct        : REAL;
    CaptorDebounceTon     : TON;
    ArrivalEdge            : R_TRIG;
    DirectionAtArrival     : INT;
    ArrivalLock             : BOOL;        // Arrêt exact sur capteur cible
    MovementRequested      : BOOL;         // Pilote FB_Brake
    FirstScanDone          : BOOL;
    // 🆕 2026-08-06 (revue sécurité) : garde-fou watchdog — DriveActualFreqHz est un passthrough
    // EtherCAT SANS contrôle de fraîcheur (PRG_02_Acquisition, TimeConst=0ms). Si la comm variateur
    // se fige (perte EtherCAT) sur une dernière valeur ≥1.0 Hz, plus rien ne referme le frein tant
    // que ce garde-fou n'existe pas — même si SafeStop a déjà ramené la rampe théorique à 0. Force
    // le relâchement du frein 2s après la fin de la rampe théorique, quoi que dise DriveActualFreqHz.
    TonBrakeRealFreqTimeout : TON;
END_VAR

// === IMPLEMENTATION ===

// 🛑 1. GATE (Enable / PowerContactorEngaged) — neutralisation totale, sorties sûres
IF NOT Enable OR NOT PowerContactorEngaged THEN
    RequestedDriveControlWord := 0; RequestedDriveFreqHz := 0.0;

    Brake(Enable := FALSE, Reset := FALSE, MovementRequested := FALSE, ContactorFeedback := BrakeFeedback,
          DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
          DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout);
    BrakeReleaseRequest := Brake.BrakeCmd;
    BrakeCommandOpenConfirmed := Brake.BrakeCommandOpenConfirmed;
    BrakeContactorCheck := Brake.ContactorCheck;

    CommandedDirection := 0;
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    SpeedRamp(Target := 0.0, AccelRate := CfgRampAccelRate, DecelRate := CfgRampDecelFastRate, CycleTimeS := CycleTimeCalc.CycleTimeS);

    ArrivalLock := FALSE;

    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    RETURN;
END_IF;

// 🧹 Initialisation au premier scan : purge des résidus RAM d'un Online Change / Warm Start et évitement des alarmes transitoires
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;
CycleTimeCalc(DefaultValueS := 0.010);   // MainTask = 10 ms

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 📡 3. CAPTEUR POSITION CIBLE (debounce)
CaptorDebounceTon(IN := PositionSensorTarget, PT := CaptorDebounce);
TargetReached := CaptorDebounceTon.Q;

// ⚙️ 4. CORE — arbitrage rampe : Enable > SafeStop > StartStop
// 🆕 2026-08-05 : DirectionChangePending FORCE la cible à 0.0 dès qu'une inversion de
// sens est en attente — sans ça, la cible suit la magnitude joystick en continu et ne
// croise jamais le seuil d'arrêt (0.1%) qui autorise l'interlock §5 à basculer
// CommandedDirection. Une inversion plus rapide que la décélération réelle bloquait donc
// indéfiniment le mouvement dans l'ancien sens (même bug que FB_Winch, REX 2026-07-02).
DirectionChangePending := (Direction <> CommandedDirection) AND (CommandedDirection <> 0);

RampTargetPct := 0.0;
IF NOT SafeStop AND StartStop AND NOT DirectionChangePending THEN
    // Si butée fin de course extrême atteinte dans le sens de marche demandé, consigne forcée à 0
    // 🌐 BypassLimitSwitch = TRUE → ignore cette protection
    IF NOT BypassLimitSwitch AND ((Direction = 1 AND LimitSwitchFwd) OR (Direction = -1 AND LimitSwitchRev)) THEN
        RampTargetPct := 0.0;
    ELSE
        RampTargetPct := ABS(SpeedRefPct);
        // 🎚️ Consigne minimale joystick (1.0 Hz) : si un mouvement est demandé (SpeedRefPct > 0.0), la consigne est au moins égale à 1.0 Hz
        IF RampTargetPct > 0.0 THEN
            RampTargetPct := MAX(RampTargetPct, (1.0 / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
        END_IF;
    END_IF;
END_IF;

// ⏱️ 4bis. RALENTISSEMENT AUTO À L'APPROCHE (piloté par capteur, remplace le timer)
// 🔧 REX 2026-07-18 : ApproachTime (timer générique, toute direction confondue) remplacé par un
// capteur dédié qui ne déclenche le ralentissement QU'à l'approche de sa cible, jamais l'inverse.
// 🆕 2026-08-06 : généralisé à 3 paires capteur/cible indépendantes — chaque capteur "un cran
// avant" la cible finale déclenche SA propre vitesse réduite, dans SON sens de marche uniquement :
//   PV       + Direction=1  → approche Trémie
//   P1       + Direction=-1 → approche Maintenance
//   P2       + Direction=-1 → approche P1 (arrêt propre pour travail)
IF (Direction = 1) AND SlowdownSensorTremie THEN
    RampTargetPct := LIMIT(0.0, RampTargetPct, (ApproachSpeedTremieHz / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
END_IF;
IF (Direction = -1) AND SlowdownSensorMaintenance THEN
    RampTargetPct := LIMIT(0.0, RampTargetPct, (ApproachSpeedMaintenanceHz / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
END_IF;
IF (Direction = -1) AND SlowdownSensorP1 THEN
    RampTargetPct := LIMIT(0.0, RampTargetPct, (ApproachSpeedP1Hz / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
END_IF;

// 🎯 4ter. VERROUILLAGE ANTI-REBONDS SENS EN BUTÉE (Trémie, P1, Maintenance, Fdc extrêmes)
// 🆕 2026-08-06 (retour terrain + revue) : élargi à P1 (arrêt travail), pas seulement les 2
// extrémités. Dès qu'on touche un capteur d'arrêt (TargetReached, débounce 100ms) OU un fin de
// course dur (LimitSwitchFwd/Rev, §5bis — immédiat, non débounce, mais toute activation même
// brève arme le même verrou), le sens d'arrivée (DirectionAtArrival) est MÉMORISÉ et BLOQUÉ.
// 🔧 REX 2026-08-06 (revue) : LimitSwitchFwd/Rev ne passaient PAS par ce verrou — un Fdc qui
// s'ouvre quelques ms pendant le freinage laissait le §5bis relâcher SA coupure directe sans que
// rien ne prenne le relais, la rampe (encore haute en interne) revenait en sortie -> ré-accélération.
// Désormais toute activation, même un instant, arme DirectionAtArrival comme un TargetReached.
ArrivalEdge(CLK := TargetReached
                 OR (LimitSwitchFwd AND (CommandedDirection = 1))
                 OR (LimitSwitchRev AND (CommandedDirection = -1)));
IF ArrivalEdge.Q THEN
    DirectionAtArrival := CommandedDirection;
END_IF;

// 🔧 REX 2026-08-06 (revue) : un retour au neutre, même SOUTENU (>100ms), ne doit JAMAIS lever
// le verrou — seul un vrai changement de sens (dégagement volontaire, sans ambiguïté) le fait.
// Sinon : neutre 100ms+ puis réappui dans le MÊME sens (le capteur/Fdc étant resté au niveau
// haut en continu, TargetReached ne montre plus de front) contournait le verrou et M3 repartait
// vers la butée. Conforme à la demande d'origine : "on doit repartir dans l'AUTRE sens", jamais
// juste relâcher-réappuyer pareil. Instantané, jamais retardé (le dégagement doit rester rapide).
IF (Direction = DirectionAtArrival * (-1)) OR ResetEdge.Q OR (NOT TargetReached AND NOT LimitSwitchFwd AND NOT LimitSwitchRev) THEN
    DirectionAtArrival := 0;
END_IF;

// Bloque la consigne à 0 tant que l'ordre demande d'insister dans le sens d'arrivée verrouillé
ArrivalLock := (DirectionAtArrival <> 0) AND (Direction = DirectionAtArrival);
IF ArrivalLock THEN
    RampTargetPct := 0.0;
END_IF;

SpeedRamp(Target := RampTargetPct,
          AccelRate := CfgRampAccelRate,
          DecelRate := SEL(SafeStop, CfgRampDecelNormalRate, CfgRampDecelFastRate),
          CycleTimeS := CycleTimeCalc.CycleTimeS);

// 🔒 5. INTERLOCK CHANGEMENT DE SENS — jamais Fwd+Rev simultanés (vitesse confirmée nulle)
IF Direction <> CommandedDirection THEN
    IF CommandedDirection = 0 AND Direction <> 0 THEN
        CommandedDirection := Direction;
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    ELSIF ABS(SpeedRamp.Current) < 0.1 THEN
        DirectionChangeDelay(IN := TRUE, PT := DirectionInterlockDelay);
        IF DirectionChangeDelay.Q THEN
            CommandedDirection := Direction;
            DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
        END_IF;
    ELSE
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    END_IF;
ELSE
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
END_IF;

// 🛑 Pilotage du frein : le mouvement est considéré actif tant que la consigne est supérieure à 0.1%
// OU que la fréquence réelle mesurée du variateur M3 est >= 1.0 Hz.
// Le frein de parking ne serre QUE lorsque la fréquence réelle variateur chute sous 1.0 Hz !
// 🆕 2026-08-06 (revue sécurité) : borné par un garde-fou 2s — DriveActualFreqHz n'a aucun
// contrôle de fraîcheur EtherCAT ; si la comm se fige sur une valeur ≥1.0 Hz (perte réseau en
// mouvement), rien d'autre en aval ne referme le frein (FB_TranslationOutputInterlock_LD ignore
// volontairement SafeStop par conception). Le garde-fou force la fermeture du frein 2s après la
// fin de la rampe THÉORIQUE, quoi que dise la mesure réelle — combine attente réelle (évite un
// serrage sur arbre encore tournant) et certitude de fermeture (n'attend jamais indéfiniment).
TonBrakeRealFreqTimeout(IN := NOT ((CommandedDirection <> 0) AND (ABS(SpeedRamp.Current) > 0.1)), PT := T#2s);
MovementRequested := ((CommandedDirection <> 0) AND (ABS(SpeedRamp.Current) > 0.1))
                     OR (ABS(DriveActualFreqHz) >= 1.0 AND NOT TonBrakeRealFreqTimeout.Q);

// 🔀 5bis. SORTIE PHYSIQUE (ETHERCAT)
RequestedDriveFreqHz := (ABS(SpeedRamp.Current) / 100.0) * DriveFreqScaleMaxHz;

// 🆕 2026-08-06 : compensation câblage moteur appliquée ICI SEULEMENT, sur le mot de commande —
// CommandedDirection (sécurité/capteurs juste au-dessus, §4/§4bis/§4ter) reste le sens réel.
PhysicalDriveDirection := SEL(InvertDriveDirection, CommandedDirection, CommandedDirection * (-1));

// Pilotage nominal Given Command 1 (0x3101) :
// 0: None, 1: Forward, 2: Reverse, 7: Reset
IF Reset THEN
    RequestedDriveControlWord := 7; // Reset défaut variateur
ELSIF Error THEN
    RequestedDriveControlWord := 0; // Arrêt sur défaut
ELSIF MovementRequested THEN
    IF PhysicalDriveDirection = 1 THEN
        RequestedDriveControlWord := 1; // Marche avant
    ELSIF PhysicalDriveDirection = -1 THEN
        RequestedDriveControlWord := 2; // Marche arrière
    ELSE
        RequestedDriveControlWord := 0;
    END_IF;
ELSE
    RequestedDriveControlWord := 0;
END_IF;

// Sécurité : si Fdc extrême atteint dans le sens de marche, coupure commande immédiate (sans rampe ni couple)
// 🌐 BypassLimitSwitch = TRUE → ignore cette protection (test/mise en service)
IF NOT BypassLimitSwitch AND ((CommandedDirection = 1 AND LimitSwitchFwd) OR (CommandedDirection = -1 AND LimitSwitchRev)) THEN
    RequestedDriveControlWord := 0;
    RequestedDriveFreqHz := 0.0;
    SpeedRamp(Target := 0.0, AccelRate := 0.0, DecelRate := 100000.0, CycleTimeS := 1.0);
END_IF;

// 🛑 6. FREIN (composé, réutilisé tel quel)
Brake(Enable := TRUE, Reset := Reset, MovementRequested := MovementRequested,
      ContactorFeedback := BrakeFeedback,
      DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
      DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout,
      BypassContactorCheck := BypassContactorCheck);
BrakeReleaseRequest := Brake.BrakeCmd;
BrakeCommandOpenConfirmed := Brake.BrakeCommandOpenConfirmed;
BrakeContactorCheck := Brake.ContactorCheck;

// 🛡️ FB_Translation ne décide plus la frontière finale : il expose uniquement
// ses demandes métier. SafeStop est déjà appliqué dans la rampe rapide §4 : tant que
// la vitesse ne vaut pas zéro, la demande et le desserrage suivent la décélération.
// FB_TranslationOutputInterlock_LD ne doit jamais transformer SafeStop en coupure sèche.

// 🧾 7. ERRORID (bitfield, cumul)
IF Brake.Error THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// Défaut variateur (bit3) : lu via EtherCAT (DriveStatusWord.4)
IF DriveStatusWord.4 THEN
    ErrorId := ErrorId OR 16#0008;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFF7;
END_IF;

// 🚧 Défaut fin de course extrême (bit6) — si bypassé, on NETTOIE le bit résiduel
IF BypassLimitSwitch THEN
    ErrorId := ErrorId AND 16#FFBF;   // Nettoie le bit 6 (évite résidu d'avant activation)
ELSE
    // Activé UNIQUEMENT en cas de tentative d'avancer DANS la butée active (libéré si dégagement en sens inverse)
    IF (CommandedDirection = 1 AND LimitSwitchFwd) OR (CommandedDirection = -1 AND LimitSwitchRev) THEN
        ErrorId := ErrorId OR 16#0040;
    ELSE
        ErrorId := ErrorId AND 16#FFBF;
    END_IF;
END_IF;

Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// 🚦 8. STATE MACHINE (phase)
IF (NOT StartStop OR SafeStop) AND ABS(SpeedRamp.Current) > 0.1 THEN
    State := E_State.STOPPING;
ELSIF ABS(SpeedRamp.Current) > 0.1 THEN
    State := E_State.BUSY;
ELSE
    State := E_State.READY;
END_IF;

Busy := (State = E_State.BUSY) OR (State = E_State.STOPPING);
Done := FALSE;

// 🛡️ 9. SORTIE SÛRE SUR DÉFAUT
IF Error THEN
    RequestedDriveControlWord := 0; RequestedDriveFreqHz := 0.0;
    BrakeReleaseRequest := FALSE;
END_IF;

(* =======================================================================
   🪝 FB_Winch — Directeur d'un treuil individuel (M1 / M2)
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Pilotage d'un treuil individuel (contacteurs de sens et de vitesse)
   📄 Doc métier : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md
   🔌 Interface : FB de mouvement (Enable, SafeStop, StartStop)
   🔒 Sécurité : Interlock inversion de sens et gestion des autorisations
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_Winch
VAR_INPUT
    // === COMMANDES ET CONSIGNES ===
    Enable                          : BOOL;                           // --> [CMD] Autorisation generale FB (TRUE=Autorise)
    Reset                           : BOOL;                           // --> [CMD] Acquittement defaut (front)
    StartStop                       : BOOL;                           // --> [CMD] Ordre de marche/arret mouvement
    Direction                       : INT;                            // --> [CMD] Sens demande (-1: Descente, 0: Stop, 1: Montee)
    SpeedRefPct                     : REAL;                           // --> [CMD] Consigne vitesse % (0.0 a 100.0)
    Mode                            : E_Mode;                         // --> [CMD] Mode d'exploitation actif

    // === SECOURS ET PERMIS DE SÉCURITÉ ===
    SafeStop                        : BOOL;                           // --> [SAFE] Arret rapide de securite
    DescendPermit                   : BOOL := TRUE;                  // --> [SAFE] Permis de descente (mou de cable)
    AscentPermit                    : BOOL := TRUE;                  // --> [SAFE] Permis de montee (fin de course haut)
    PowerContactorEngaged           : BOOL;                           // --> [SAFE] Statut contacteur de ligne / puissance

    // === REGLAGES ET CONFIGURATION ===
    SpeedStepTable                  : ST_SpeedStepTable;              // --> [CFG] Table de seuils des paliers de vitesse
    CfgMaxStepDescente              : INT := 3;                       // --> [CFG] Plafond palier en descente (1..5)
    MaxStepAscent                   : INT := 5;                       // --> [CFG] Plafond palier en montee (1..5)
    HomingApproachActive            : BOOL;                           // --> [CFG] Vitesse limitee au palier 1 (approche homing)
    SpeedStepHystMargin             : REAL := 2.0;                    // --> [CFG] Marge d'hysteresis palier (%)
    DirectionInterlockDelayDescent  : TIME := T#400ms;                // --> [CFG] Delai interlock changement de sens descente
    DirectionInterlockDelayAscent   : TIME := T#900ms;                // --> [CFG] Delai interlock changement de sens montee
    ContactorFeedbackTimeout        : TIME := T#500ms;                // --> [CFG] Delai d'attente retombee des contacteurs
    TopLimitM                       : REAL := 8.5;                    // --> [CFG] Position limite haute active (m)
    BottomLimitM                    : REAL := -20.0;                  // --> [CFG] Position limite basse active (m)
    CfgSlowdownDistanceM            : REAL := 1.0;                    // --> [CFG] Distance d'approche avant limite pour ralentir (m)
    CfgSlowdownMaxStep              : INT := 1;                       // --> [CFG] Plafond palier dans zone de ralentissement (1..5)

    // === MESURES ET FEEDBACKS SENSORS ===
    FwdRevSpeedFeedbackOff          : BOOL;                           // --> [HW] Retour unique contacteurs sens+vitesse retombes
    Homed                           : BOOL;                           // --> [HW] Statut treuil reference
    HomingSuspect                   : BOOL;                           // --> [HW] Incertitude / doute sur le referencement
    CablePosM                       : REAL;                           // --> [HW] Position actuelle du cable (m)
    MeasuredSpeedBand               : INT := 0;                       // --> [HW] Bande vitesse reelle validee
    SpeedGuardEnable                : BOOL := FALSE;                  // --> [HW] Activation garde-fou changement de palier
    SpeedGuardReady                 : BOOL := FALSE;                  // --> [HW] Conditions de stabilite validees

    // === BYPASSES ET SIMULATION ===
    BypassContactorCheck            : BOOL;                           // --> [TST] Bypass diagnostic contacteurs (simu)
    BypassGlobal                    : BOOL;                           // --> [TST] Force ErrorId=0, ignore erreurs
END_VAR
VAR_OUTPUT
    // === ETATS IEC ET SYNOPTIQUE ===
    Ready                           : BOOL;                           // <-- [STAT] FB pret a fonctionner
    // 🧩 Statut transverse (forme cible) — regroupe Busy/Done/Error/ErrorId/State/StateAtError.
    // Code erreur bitmask.
    Status                          : ST_FbStatus;

    // === ORDRES ACTIONNEURS (CONTACTEURS) ===
    RelayFwd                        : BOOL;                           // <-- [ACT] Ordre contacteur sens montee
    RelayRev                        : BOOL;                           // <-- [ACT] Ordre contacteur sens descente
    Contactor1                      : BOOL;                           // <-- [ACT] Ordre contacteur vitesse palier 1
    Contactor2                      : BOOL;                           // <-- [ACT] Ordre contacteur vitesse palier 2
    Contactor3                      : BOOL;                           // <-- [ACT] Ordre contacteur vitesse palier 3
    Contactor4                      : BOOL;                           // <-- [ACT] Ordre contacteur vitesse palier 4

    // === DIAGNOSTICS ET MESURES ===
    RequestedStep                   : INT;                            // <-- [DIAG] Palier brut calcule par SpeedStep
    StepNumber                      : INT;                            // <-- [DIAG] Palier metier temporise actif
    BusinessStepDelayElapsed        : TIME;                           // <-- [DIAG] Ecoule tempo metier palier
    SpeedGuardLimited               : BOOL;                           // <-- [DIAG] Statut limitation par garde-fou
    ContactorsCheck                 : ST_ContactorCheck;              // <-- [DIAG] Diagnostic concorde contacteurs
    InTopSlowdownZone               : BOOL;                           // <-- [DIAG] Zone de ralentissement haut active
    InBottomSlowdownZone            : BOOL;                           // <-- [DIAG] Zone de ralentissement bas active
    CommandedDirection              : INT;                            // <-- [DIAG] Sens interne memorise
    DirectionChangeDelayElapsed     : TIME;                           // <-- [DIAG] Ecoule delai changement de sens
    DirectionChangePending          : BOOL;                           // <-- [DIAG] Changement de sens en attente
END_VAR
VAR
    // === SOUS-INSTANCES FB ===
    SpeedStep                       : FB_SpeedStep;                   // * [INST] Decodage paliers vitesse
    CycleTimeCalc                   : FB_CycleTime;                   // * [INST] Calcul temps de cycle

    // === DETECTEURS ET TIMERS INTERNES ===
    ResetEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Reset
    ErrorEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Erreur
    DirectionChangeDelay            : TON;                            // . [LOC] Temporisation changement de sens
    TonContactorsDropped            : TON;                            // . [LOC] Temporisation retombee contacteurs
    BusinessStepDelay               : TON;                            // . [LOC] Temporisation hausse de palier

    // === VARIABLES LOCALES CALCULÉES ===
    EffectiveDirectionInterlockDelay: TIME;                           // . [LOC] Delai interlock effectif selon sens
    EffectiveStepDelay              : TIME;                           // . [LOC] Delai palier effectif selon sens
    AllContactorsCommandedOff       : BOOL;                           // . [LOC] Tous contacteurs commandes a FALSE
    RampTargetPct                   : REAL;                           // . [LOC] Consigne cible envoyee au SpeedStep
    EffectiveSafeStop               : BOOL;                           // . [LOC] SafeStop effectif incluant permis
    ActiveMaxStep                   : INT;                            // . [LOC] Plafond palier actif dynamique
    FirstScanDone                   : BOOL;                           // . [LOC] Indicateur premier cycle passe
END_VAR

{region "§1 Gate et initialisation"}
IF NOT Enable OR NOT PowerContactorEngaged THEN
    RelayFwd := FALSE; RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    SpeedStep(Enable := FALSE, SpeedRefPct := 0.0, Table := SpeedStepTable, HystMargin := SpeedStepHystMargin);
    RequestedStep := SpeedStep.StepNumber;
    StepNumber := 0;
    BusinessStepDelay(IN := FALSE, PT := T#1s500ms);
    BusinessStepDelayElapsed := T#0ms;
    CommandedDirection := 0;
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelayAscent);
    DirectionChangeDelayElapsed := T#0ms;
    InTopSlowdownZone := FALSE;
    InBottomSlowdownZone := FALSE;
    Status.State := E_State.DISABLED;
    Ready := FALSE; Status.Busy := FALSE; Status.Done := FALSE;
    Status.Error := FALSE;
    Status.ErrorId := 16#0000;
    RETURN;
END_IF;

// 🧹 Initialisation au premier scan : évitement des alarmes transitoires au démarrage
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    Status.ErrorId := 16#0000;
    StepNumber := 0;
    RequestedStep := 0;
    BusinessStepDelay(IN := FALSE, PT := T#1s500ms);
    BusinessStepDelayElapsed := T#0ms;
    RETURN;
END_IF;

{endregion}

{region "§2 Preparation commande et limites vitesse"}
Ready := TRUE;
CycleTimeCalc(DefaultValueS := 0.010);

ResetEdge(CLK := Reset);

DirectionChangePending := (Direction <> CommandedDirection) AND (CommandedDirection <> 0);

// Mou de câble / limite basse (DescendPermit=FALSE) et Fin de course haut (AscentPermit=FALSE)
// intégrés à une VRAIE décélération rapide (comme SafeStop) :
// - NOT DescendPermit est INHIBÉ si CommandedDirection = 1 (montée libre pour reprendre le mou)
// - NOT AscentPermit est INHIBÉ si CommandedDirection = -1 (descente libre pour dégager le câble)
EffectiveSafeStop := SafeStop 
                     OR (NOT DescendPermit AND (CommandedDirection <> 1))
                     OR (NOT AscentPermit AND (CommandedDirection <> -1));

RampTargetPct := 0.0;
IF NOT EffectiveSafeStop AND StartStop AND NOT DirectionChangePending THEN
    RampTargetPct := ABS(SpeedRefPct);
END_IF;

// RALENTISSEMENT AUTOMATIQUE SUR BORDURES (si référencé et non suspect) — permet d'approcher
// les fins de course / limites en vitesse lente de façon progressive.
// Plafond palier direct (ActiveMaxStep := 1, ci-dessous, même mécanisme que
// CfgMaxStepDescente/MaxStepAscent) — un treuil ne connaît que 5 paliers de contacteurs, pas une
// vitesse continue ; palier 1 = tous contacteurs de vitesse relâchés = vitesse minimale, sans
// dépendre d'un % qui doit rester sous le 1er seuil de la table pour produire le même effet.
InTopSlowdownZone := Homed AND NOT HomingSuspect
                      AND ((CommandedDirection = 1) OR (Direction = 1))
                      AND (CablePosM >= (TopLimitM - CfgSlowdownDistanceM));
InBottomSlowdownZone := Homed AND NOT HomingSuspect
                         AND ((CommandedDirection = -1) OR (Direction = -1))
                         AND (CablePosM <= (BottomLimitM + CfgSlowdownDistanceM));

// Délai asymétrique selon le sens ENTRANT (Direction) — descente sans effort
// (câble mou/gravité favorable) réengage plus vite que montée (charge en traction). La tempo
// palier se DÉDUIT de cet interlock (+100ms) : jamais besoin de resynchroniser deux réglages.
IF Direction = -1 THEN
    EffectiveDirectionInterlockDelay := DirectionInterlockDelayDescent;
ELSE
    EffectiveDirectionInterlockDelay := DirectionInterlockDelayAscent;
END_IF;
EffectiveStepDelay := EffectiveDirectionInterlockDelay + T#100ms;

IF Direction <> CommandedDirection THEN
    // Démarrage depuis le neutre/arrêt (CommandedDirection = 0) pris en compte IMMÉDIATE (0ms),
    // pas de tempo interlock. L'interlock DirectionChangeDelay (400ms descente / 900ms montée) ne
    // s'applique QU'EN CAS d'inversion active de sens en mouvement (ex: de -1 vers +1 direct).
    IF CommandedDirection = 0 THEN
        CommandedDirection := Direction;
        DirectionChangeDelay(IN := FALSE, PT := EffectiveDirectionInterlockDelay);
    ELSIF StepNumber = 0 THEN
        DirectionChangeDelay(IN := TRUE, PT := EffectiveDirectionInterlockDelay);
        IF DirectionChangeDelay.Q THEN
            CommandedDirection := Direction;
            DirectionChangeDelay(IN := FALSE, PT := EffectiveDirectionInterlockDelay);
        END_IF;
    ELSE
        DirectionChangeDelay(IN := FALSE, PT := EffectiveDirectionInterlockDelay);
    END_IF;
ELSE
    DirectionChangeDelay(IN := FALSE, PT := EffectiveDirectionInterlockDelay);
END_IF;
DirectionChangeDelayElapsed := DirectionChangeDelay.ET; // Diagnostic, miroir pur

// Plafond dynamique de palier (CfgMaxStepDescente en descente, Palier 1 si non référencé ou douteux,
// Palier 1 en approche homing, MaxStepAscent en montée normale)
IF NOT Homed OR HomingSuspect THEN
    // Bypass.Global = TRUE → pas de limitation, on applique la règle normale
    IF BypassGlobal THEN
        ActiveMaxStep := SEL(CommandedDirection = -1, MaxStepAscent, CfgMaxStepDescente);
    ELSE
        ActiveMaxStep := 1;
    END_IF;
ELSIF CommandedDirection = -1 THEN
    ActiveMaxStep := CfgMaxStepDescente;
ELSIF (CommandedDirection = 1) AND HomingApproachActive THEN
    ActiveMaxStep := 1;
ELSIF CommandedDirection = 1 THEN
    ActiveMaxStep := MaxStepAscent;
ELSE
    ActiveMaxStep := 5;
END_IF;

// Ralentissement sur bordure (voir plus haut) — plafond palier direct (CfgSlowdownMaxStep,
// défaut 1 = vitesse mini, réglable IHM), appliqué APRÈS le calcul normal ci-dessus via MIN
// (ne peut qu'abaisser, jamais relever le plafond déjà décidé par ailleurs — ex.
// CfgMaxStepDescente déjà plus restrictif).
IF InTopSlowdownZone OR InBottomSlowdownZone THEN
    ActiveMaxStep := MIN(ActiveMaxStep, CfgSlowdownMaxStep);
END_IF;

{endregion}

{region "§3 Selection et temporisation paliers"}
SpeedStep(Enable := (RampTargetPct > 0.1), SpeedRefPct := RampTargetPct,
          Table := SpeedStepTable, HystMargin := SpeedStepHystMargin,
          MaxStepNumber := ActiveMaxStep,
          MeasuredSpeedBand := MeasuredSpeedBand,
          SpeedGuardEnable := SpeedGuardEnable,
          SpeedGuardReady := SpeedGuardReady);
// 🪜 Tempo métier nominale : le décollage initial de StepNumber=0 vers 1 est IMMÉDIAT (0ms).
// Toute hausse ultérieure (1->2->3) exige EffectiveStepDelay (interlock + 100ms) et progresse par pas adjacents.
// Toute baisse reste immédiate pour ne jamais retarder un arrêt/safety.
RequestedStep := SpeedStep.StepNumber;
IF RequestedStep > StepNumber THEN
    IF StepNumber = 0 THEN
        StepNumber := 1;
        BusinessStepDelay(IN := FALSE, PT := EffectiveStepDelay);
        BusinessStepDelayElapsed := T#0ms;
    ELSE
        BusinessStepDelay(IN := TRUE, PT := EffectiveStepDelay);
        BusinessStepDelayElapsed := BusinessStepDelay.ET;
        IF BusinessStepDelay.Q THEN
            StepNumber := StepNumber + 1;
            BusinessStepDelay(IN := FALSE, PT := EffectiveStepDelay);
        END_IF;
    END_IF;
ELSE
    BusinessStepDelay(IN := FALSE, PT := EffectiveStepDelay);
    BusinessStepDelayElapsed := BusinessStepDelay.ET;
    StepNumber := RequestedStep;
END_IF;
SpeedGuardLimited := SpeedStep.SpeedGuardLimited;

{endregion}

{region "§4 Commandes contacteurs et sens"}
// Les sorties métier suivent le palier temporisé. FB_Winch/SpeedStepTable reste
// propriétaire unique des combinaisons, y compris les mappings M2 Benne dynamiques.
// FB_WinchOutputInterlock ne fait qu'autoriser ou masquer ces quatre demandes.
CASE StepNumber OF
    1:
        Contactor1 := SpeedStepTable.P1R1; Contactor2 := SpeedStepTable.P1R2;
        Contactor3 := SpeedStepTable.P1R3; Contactor4 := SpeedStepTable.P1R4;
    2:
        Contactor1 := SpeedStepTable.P2R1; Contactor2 := SpeedStepTable.P2R2;
        Contactor3 := SpeedStepTable.P2R3; Contactor4 := SpeedStepTable.P2R4;
    3:
        Contactor1 := SpeedStepTable.P3R1; Contactor2 := SpeedStepTable.P3R2;
        Contactor3 := SpeedStepTable.P3R3; Contactor4 := SpeedStepTable.P3R4;
    4:
        Contactor1 := SpeedStepTable.P4R1; Contactor2 := SpeedStepTable.P4R2;
        Contactor3 := SpeedStepTable.P4R3; Contactor4 := SpeedStepTable.P4R4;
    5:
        Contactor1 := SpeedStepTable.P5R1; Contactor2 := SpeedStepTable.P5R2;
        Contactor3 := SpeedStepTable.P5R3; Contactor4 := SpeedStepTable.P5R4;
ELSE
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
END_CASE;

// Coupure INSTANTANÉE de tous les contacteurs de vitesse dès que l'opérateur relâche le
// joystick (Direction=0) — ne pas attendre la fin de la rampe de décélération. Sinon,
// StepNumber suivrait la rampe (décélération progressive), gardant les contacteurs de vitesse
// engagés plusieurs secondes après l'ordre d'arrêt.
IF Direction = 0 THEN
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
END_IF;

// Le sens et la pré-magnétisation suivent la demande brute ; le palier métier
// temporisé reste seul transmis à l'interlock final pour autoriser la puissance.
// ET Direction=1/-1 (demande OPÉRATEUR brute, pas CommandedDirection qui reste au dernier sens
// jusqu'à la retombée de la rampe) — coupure instantanée du contacteur de sens dès le
// relâchement du joystick, même sécurité que ci-dessus.
// Le frein n'est pas une condition d'engagement des relais de sens : c'est l'inverse
// (voir FB_WinchOutputInterlock §6 : BrakeCmd := RelayFwd OR RelayRev, calculé APRÈS ces relais).
RelayFwd := (Direction = 1) AND (CommandedDirection = 1) AND (RequestedStep > 0);
RelayRev := (Direction = -1) AND (CommandedDirection = -1) AND (RequestedStep > 0);

IF NOT DescendPermit THEN
    RelayRev := FALSE;
END_IF;

IF NOT AscentPermit THEN
    RelayFwd := FALSE;
END_IF;

// Vérification UNIQUEMENT à l'arrêt commandé (voir bandeau en-tête).
// AllContactorsCommandedOff = tout ce que FB_Winch commande est à FALSE.
AllContactorsCommandedOff := (NOT RelayFwd) AND (NOT RelayRev)
                             AND (NOT Contactor1) AND (NOT Contactor2) AND (NOT Contactor3) AND (NOT Contactor4);

ContactorsCheck.Command  := NOT AllContactorsCommandedOff;   // TRUE = au moins un contacteur commandé
ContactorsCheck.Feedback := NOT FwdRevSpeedFeedbackOff;      // TRUE = au moins un contacteur pas retombé
TonContactorsDropped(IN := AllContactorsCommandedOff AND NOT FwdRevSpeedFeedbackOff, PT := ContactorFeedbackTimeout);
IF TonContactorsDropped.Q THEN
    ContactorsCheck.StuckClosed := TRUE;
ELSIF ResetEdge.Q THEN
    ContactorsCheck.StuckClosed := FALSE;
END_IF;
ContactorsCheck.StuckOpen := FALSE; // Non applicable avec ce retour (pas de confirmation par sens, voir bandeau)

{endregion}

{region "§5 Diagnostic contacteurs et configuration"}
// 🌐 BYPASS GLOBAL : force ErrorId = 0 et saute toute la logique d'erreur
IF BypassGlobal THEN
    Status.ErrorId := 16#0000;
END_IF;

IF NOT BypassGlobal THEN
// bit0 ErrorId libre — la cohérence commande/retour du frein est surveillée dans
// FB_WinchOutputInterlock (BrakeFeedback).

// 🧪 Simulation (GVL_Simulation.SensorMxContactorFeedbackIsReal, passé par l'appelant via
// BypassContactorCheck) — sans contacteurs réels câblés/cohérents en essai, StuckClosed
// se déclenche à tort et bloque RelayFwd/RelayRev (voir Error plus bas).
// bit2 libre/inutilisé.
IF NOT BypassContactorCheck THEN
    IF ContactorsCheck.StuckClosed THEN
        Status.ErrorId := Status.ErrorId OR 16#0002;
    ELSIF ResetEdge.Q THEN
        Status.ErrorId := Status.ErrorId AND 16#FFFD;
    END_IF;
ELSE
    Status.ErrorId := Status.ErrorId AND 16#FFFD;   // Bypass actif : efface/maintient à 0 le bit1
END_IF;

// 🪜 Remonte le défaut de configuration interne de FB_SpeedStep.
// Le bit reste mémorisé après correction de la table ; cause disparue + nouveau front Reset
// sont obligatoires avant de rendre le treuil disponible, conformément à Partie 3 §5.
IF SpeedStep.ConfigError THEN
    Status.ErrorId := Status.ErrorId OR 16#0004;    // bit2 = table/plafond/hystérésis invalide
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFFB;
END_IF;

END_IF; // fin IF NOT BypassGlobal

{endregion}

{region "§6 Etats et repli defaut"}
Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;

IF (NOT StartStop OR EffectiveSafeStop OR DirectionChangePending) AND StepNumber > 0 THEN
    Status.State := E_State.STOPPING;
ELSIF StepNumber > 0 THEN
    Status.State := E_State.BUSY;
ELSE
    Status.State := E_State.READY;
END_IF;

Status.Busy := (Status.State = E_State.BUSY) OR (Status.State = E_State.STOPPING);
Status.Done := FALSE;

IF Status.Error THEN
    RelayFwd := FALSE;
    RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
END_IF;

{endregion}

SETUP
VAR
    fb : FB_RAMP;
END_VAR
END_SETUP

TEST 'Accel : consigne progresse par pas de AccelRate*CycleTimeS vers la cible'
    fb(TARGET := 100.0, ACCELRATE := 50.0, DECELRATE := 200.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 5.0, 0.001, 'pas 1 : 0 -> 5.0 (50%/s * 0.1s), s eloigne de zero donc AccelRate');

    fb(TARGET := 100.0, ACCELRATE := 50.0, DECELRATE := 200.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 10.0, 0.001, 'pas 2 : 5.0 -> 10.0, meme taux tant que la cible n est pas atteinte');
END_TEST

TEST 'Decel : retour vers zero utilise DecelRate (taux different d Accel)'
    (* monte a 40% avec Accel *)
    fb(TARGET := 40.0, ACCELRATE := 50.0, DECELRATE := 10.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 5.0, 0.001, 'montee : AccelRate (50%/s)');
    fb(TARGET := 40.0, ACCELRATE := 50.0, DECELRATE := 10.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 10.0, 0.001, 'montee : toujours AccelRate, cible pas encore atteinte');

    (* cible ramenee a 0 : retour vers zero -> DecelRate, taux bien plus faible ici *)
    fb(TARGET := 0.0, ACCELRATE := 50.0, DECELRATE := 10.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 9.0, 0.001, 'retour vers zero : DecelRate (10%/s), pas de 1.0 seulement -- pas AccelRate');
END_TEST

TEST 'Atteinte de la cible : la rampe s arrete pile dessus, pas de depassement'
    fb(TARGET := 3.0, ACCELRATE := 50.0, DECELRATE := 200.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 3.0, 0.001, 'le pas (5.0) depasserait la cible (3.0) : clampe exactement dessus, pas de depassement');

    fb(TARGET := 3.0, ACCELRATE := 50.0, DECELRATE := 200.0, CYCLETIMES := 0.1);
    ASSERT_NEAR(fb.CURRENT, 3.0, 0.001, 'cible deja atteinte : reste stable, aucune oscillation autour de la cible');
END_TEST

TEST 'Garde-fou : une valeur Current deja hors plage (etat corrompu) reste bornee a +/-100'
    (* Simule un etat interne deja corrompu au-dela de la plage normalisee -- le FB doit se
       proteger lui-meme, pas seulement empecher d y entrer *)
    fb(TARGET := 500.0, ACCELRATE := 1000.0, DECELRATE := 1000.0, CYCLETIMES := 1.0);
    ASSERT_NEAR(fb.CURRENT, 100.0, 0.001, 'Target hors plage (500) et grand pas (1000%/s) : Current ne depasse jamais +100');
END_TEST

(* ═══════════════════════════════════════════════════════════════
   ↔️ FB_Translation — Directeur de l'axe transversal M3 (variateur AC600)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-11_Fonction_Translation_v2.0.md
   🔌 FB DE MOUVEMENT : porte StartStop + SafeStop en plus de l'interface
      standard. Précédence Enable > SafeStop > StartStop.
   📡 Pilotage exclusivement ETHERCAT nominal (mot de commande, consigne fréquence).
   🧩 Compose FB_Brake (réutilisé TEL QUEL depuis COMMUN).
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Translation
VAR_INPUT
    Enable                      : BOOL;        // Active le FB. FALSE = neutralisation totale (sorties coupées)
    Reset                       : BOOL;        // Acquittement défaut (front)
    PowerContactorEngaged             : BOOL;        // Chaîne AU réarmée + conditions globales OK
    Mode                        : E_Mode;      // Mode courant
    StartStop                   : BOOL;        // TRUE = rampe accélération, FALSE = rampe décélération NORMALE
    SafeStop                    : BOOL;        // Sortie FB_Safety_Translation : TRUE = rampe décélération RAPIDE (Enable maintenu)
    Direction                   : INT;         // -1 = Rev, 0 = Neutre, +1 = Fwd (source d'autorité du sens)
    SpeedRefPct                 : REAL;        // Magnitude de la consigne (de 0 à 100%)
    PositionSensorTarget        : BOOL;        // Capteur position cible courante
    SlowdownSensor              : BOOL;        // 🆕 REX 2026-07-18 : capteur PV — ralentissement avant Trémie (remplace ApproachTime)
    LimitSwitchFwd              : BOOL;        // Fin de course extrême avant
    LimitSwitchRev              : BOOL;        // Fin de course extrême arrière

    // 🔌 Spécifique ETHERCAT (image process EtherCAT, rafraîchie par EtherCatTask 4ms)
    DriveStatusWord              : WORD;       // Mot d'état AC600 lu depuis l'image d'entrée EtherCAT
    DriveActualFreqHz            : REAL;       // Fréquence réelle mesurée (Hz)

    BypassContactorCheck         : BOOL;       // 🧪 TRUE = désactive StuckClosed/StuckOpen pour le frein (simulation)
    BypassLimitSwitch            : BOOL;       // 🚧 TRUE = ignore les fins de course extrêmes
    BrakeFeedback                : BOOL;       // Retour physique direct : TRUE = frein OUVERT (desserré)

    // Réglages rampe (RETAIN)
    CfgRampAccelRate                : REAL := 20.0;    // %/s — accélération
    CfgRampDecelNormalRate          : REAL := 40.0;    // %/s — décélération normale
    CfgRampDecelFastRate            : REAL := 100.0;   // %/s — décélération RAPIDE
    DirectionInterlockDelay      : TIME := T#200ms; // Délai avant d'autoriser un changement de sens à l'arrêt

    // Réglages ETHERCAT uniquement (RETAIN)
    ApproachSpeedPct             : REAL := 20.0;    // Vitesse réduite d'approche (piloté par SlowdownSensor/PV)
    DriveFreqScaleMaxHz          : REAL := 60.0;    // Échelle 0..100 % → MaxHz (câblé depuis _TranslationMaxFreq_Hz par PRG_07 — defaut 60.0 si non raccordé)

    // Réglages communs
    CaptorDebounce                : TIME := T#100ms; // Filtrage capteur de position cible
    BrakeDelayContactClose        : TIME := T#100ms; // Voir FB_Brake
    BrakeDelayMagnetise           : TIME := T#300ms; // Voir FB_Brake
    BrakeDelayMotorDecel          : TIME := T#500ms; // Voir FB_Brake
    BrakeFeedbackTimeout          : TIME := T#300ms; // Strictement sous watchdog final 500 ms
END_VAR
VAR_OUTPUT
    Ready               : BOOL;
    Busy                : BOOL;
    Done                : BOOL;
    Error               : BOOL;
    ErrorId             : WORD;        // bit0: "Défaut frein Translation" - Brake.Error ; bit3: "Défaut variateur AC600" - défaut variateur (DriveStatusWord.4) ; bit6: "Limite extrême Translation atteinte" - Fdc extrême atteint
    State               : E_State;
    StateAtError        : E_State;
    TargetReached        : BOOL;       // Capteur position cible
    RequestedDriveControlWord : WORD; // Demande métier AC600, arbitrée par FB_TranslationOutputInterlock_LD
    RequestedDriveFreqHz      : REAL; // Demande métier fréquence, arbitrée par FB_TranslationOutputInterlock_LD
    BrakeReleaseRequest       : BOOL; // Demande métier desserrage, issue de FB_Brake
    BrakeCommandOpenConfirmed : BOOL; // TRUE = frein ouvert = commande ouverture confirmée (depuis FB_Brake)
    BrakeContactorCheck  : ST_ContactorCheck; // Diag contacteur frein
END_VAR
VAR
    Brake                : FB_Brake;       // Séquence frein
    CycleTimeCalc        : FB_CycleTime;
    SpeedRamp             : FB_Ramp;       // Rampe de vitesse logicielle (PLC)
    ResetEdge            : R_TRIG;
    ErrorEdge            : R_TRIG;
    DirectionChangeDelay : TON;            // Interlock changement de sens
    CommandedDirection   : INT;            // Sens réellement appliqué
    RampTargetPct        : REAL;
    CaptorDebounceTon     : TON;
    ArrivalEdge            : R_TRIG;
    DirectionAtArrival     : INT;
    ArrivalLock             : BOOL;        // Arrêt exact sur capteur cible
    MovementRequested      : BOOL;         // Pilote FB_Brake
    FirstScanDone          : BOOL;
END_VAR

// === IMPLEMENTATION ===

// 🛑 1. GATE (Enable / PowerContactorEngaged) — neutralisation totale, sorties sûres
IF NOT Enable OR NOT PowerContactorEngaged THEN
    RequestedDriveControlWord := 0; RequestedDriveFreqHz := 0.0;

    Brake(Enable := FALSE, Reset := FALSE, MovementRequested := FALSE, ContactorFeedback := BrakeFeedback,
          DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
          DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout);
    BrakeReleaseRequest := Brake.BrakeCmd;
    BrakeCommandOpenConfirmed := Brake.BrakeCommandOpenConfirmed;
    BrakeContactorCheck := Brake.ContactorCheck;

    CommandedDirection := 0;
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    SpeedRamp(Target := 0.0, AccelRate := CfgRampAccelRate, DecelRate := CfgRampDecelFastRate, CycleTimeS := CycleTimeCalc.CycleTimeS);

    ArrivalLock := FALSE;

    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    RETURN;
END_IF;

// 🧹 Initialisation au premier scan : purge des résidus RAM d'un Online Change / Warm Start et évitement des alarmes transitoires
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;
CycleTimeCalc(DefaultValueS := 0.010);   // MainTask = 10 ms

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 📡 3. CAPTEUR POSITION CIBLE (debounce)
CaptorDebounceTon(IN := PositionSensorTarget, PT := CaptorDebounce);
TargetReached := CaptorDebounceTon.Q;

// ⚙️ 4. CORE — arbitrage rampe : Enable > SafeStop > StartStop
RampTargetPct := 0.0;
IF NOT SafeStop AND StartStop THEN
    // Si butée fin de course extrême atteinte dans le sens de marche demandé, consigne forcée à 0
    // 🌐 BypassLimitSwitch = TRUE → ignore cette protection
    IF NOT BypassLimitSwitch AND ((Direction = 1 AND LimitSwitchFwd) OR (Direction = -1 AND LimitSwitchRev)) THEN
        RampTargetPct := 0.0;
    ELSE
        RampTargetPct := ABS(SpeedRefPct);
    END_IF;
END_IF;

// ⏱️ 4bis. RALENTISSEMENT AUTO À L'APPROCHE (piloté par capteur PV, remplace le timer)
// 🔧 REX 2026-07-18 : ApproachTime (timer générique, toute direction confondue) remplacé par un
// capteur dédié (SlowdownSensor = PV) qui ne déclenche le ralentissement QU'à l'approche de
// Trémie (Direction=1) — décision client (AF_Partie-02 v2.12 §3bis) : PV n'assure le
// ralentissement qu'avant Trémie, jamais dans le sens Maintenance.
IF (Direction = 1) AND SlowdownSensor THEN
    RampTargetPct := LIMIT(0.0, RampTargetPct, ApproachSpeedPct);
END_IF;

// 🎯 4ter. ARRÊT EXACT SUR CAPTEUR (verrouille le sens tant que le capteur cible reste actif)
ArrivalEdge(CLK := TargetReached);
IF ArrivalEdge.Q THEN
    DirectionAtArrival := CommandedDirection;
END_IF;
ArrivalLock := TargetReached AND (Direction = DirectionAtArrival) AND (DirectionAtArrival <> 0);
IF ArrivalLock THEN
    RampTargetPct := 0.0;
END_IF;

SpeedRamp(Target := RampTargetPct,
          AccelRate := CfgRampAccelRate,
          DecelRate := SEL(SafeStop, CfgRampDecelNormalRate, CfgRampDecelFastRate),
          CycleTimeS := CycleTimeCalc.CycleTimeS);

// 🔒 5. INTERLOCK CHANGEMENT DE SENS — jamais Fwd+Rev simultanés (vitesse confirmée nulle)
IF Direction <> CommandedDirection THEN
    IF CommandedDirection = 0 AND Direction <> 0 THEN
        CommandedDirection := Direction;
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    ELSIF ABS(SpeedRamp.Current) < 0.1 THEN
        DirectionChangeDelay(IN := TRUE, PT := DirectionInterlockDelay);
        IF DirectionChangeDelay.Q THEN
            CommandedDirection := Direction;
            DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
        END_IF;
    ELSE
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    END_IF;
ELSE
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
END_IF;

MovementRequested := (CommandedDirection <> 0) AND (ABS(SpeedRamp.Current) > 0.1);

// 🔀 5bis. SORTIE PHYSIQUE (ETHERCAT)
RequestedDriveFreqHz := (ABS(SpeedRamp.Current) / 100.0) * DriveFreqScaleMaxHz;

// Pilotage nominal Given Command 1 (0x3101) :
// 0: None, 1: Forward, 2: Reverse, 7: Reset
IF Reset THEN
    RequestedDriveControlWord := 7; // Reset défaut variateur
ELSIF Error THEN
    RequestedDriveControlWord := 0; // Arrêt sur défaut
ELSIF MovementRequested THEN
    IF CommandedDirection = 1 THEN
        RequestedDriveControlWord := 1; // Marche avant
    ELSIF CommandedDirection = -1 THEN
        RequestedDriveControlWord := 2; // Marche arrière
    ELSE
        RequestedDriveControlWord := 0;
    END_IF;
ELSE
    RequestedDriveControlWord := 0;
END_IF;

// Sécurité : si Fdc extrême atteint dans le sens de marche, coupure commande immédiate (sans rampe ni couple)
// 🌐 BypassLimitSwitch = TRUE → ignore cette protection (test/mise en service)
IF NOT BypassLimitSwitch AND ((CommandedDirection = 1 AND LimitSwitchFwd) OR (CommandedDirection = -1 AND LimitSwitchRev)) THEN
    RequestedDriveControlWord := 0;
    RequestedDriveFreqHz := 0.0;
    SpeedRamp(Target := 0.0, AccelRate := 0.0, DecelRate := 100000.0, CycleTimeS := 1.0);
END_IF;

// 🛑 6. FREIN (composé, réutilisé tel quel)
Brake(Enable := TRUE, Reset := Reset, MovementRequested := MovementRequested,
      ContactorFeedback := BrakeFeedback,
      DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
      DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout,
      BypassContactorCheck := BypassContactorCheck);
BrakeReleaseRequest := Brake.BrakeCmd;
BrakeCommandOpenConfirmed := Brake.BrakeCommandOpenConfirmed;
BrakeContactorCheck := Brake.ContactorCheck;

// 🛡️ FB_Translation ne décide plus la frontière finale : il expose uniquement
// ses demandes métier. SafeStop est déjà appliqué dans la rampe rapide §4 : tant que
// la vitesse ne vaut pas zéro, la demande et le desserrage suivent la décélération.
// FB_TranslationOutputInterlock_LD ne doit jamais transformer SafeStop en coupure sèche.

// 🧾 7. ERRORID (bitfield, cumul)
IF Brake.Error THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// Défaut variateur (bit3) : lu via EtherCAT (DriveStatusWord.4)
IF DriveStatusWord.4 THEN
    ErrorId := ErrorId OR 16#0008;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFF7;
END_IF;

// 🚧 Défaut fin de course extrême (bit6) — si bypassé, on NETTOIE le bit résiduel
IF BypassLimitSwitch THEN
    ErrorId := ErrorId AND 16#FFBF;   // Nettoie le bit 6 (évite résidu d'avant activation)
ELSE
    IF LimitSwitchFwd OR LimitSwitchRev THEN
        ErrorId := ErrorId OR 16#0040;
    END_IF;
END_IF;
IF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFBF;   // Reset normal (complémentaire)
END_IF;

Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// 🚦 8. STATE MACHINE (phase)
IF (NOT StartStop OR SafeStop) AND ABS(SpeedRamp.Current) > 0.1 THEN
    State := E_State.STOPPING;
ELSIF ABS(SpeedRamp.Current) > 0.1 THEN
    State := E_State.BUSY;
ELSE
    State := E_State.READY;
END_IF;

Busy := (State = E_State.BUSY) OR (State = E_State.STOPPING);
Done := FALSE;

// 🛡️ 9. SORTIE SÛRE SUR DÉFAUT
IF Error THEN
    RequestedDriveControlWord := 0; RequestedDriveFreqHz := 0.0;
    BrakeReleaseRequest := FALSE;
END_IF;

(* =======================================================================
   ⚙️ FB_Cycle — Séquenceur du cycle automatique (Grafcet de dragage)
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Automate de cycle automatique de dragage (X0 à X13 + STABILIZING)
   🔒 Sécurité : Gating par mode et homme-mort, repli STABILIZING sur défaut
   🔌 Interface : Demandes de mouvements (treuils, translation, benne)
   📄 Doc métier : DOC/AF/AF_Partie-04_Mode_SemiAuto_Sequenceur_v2.1.md
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_Cycle
VAR_INPUT
    // === COMMANDES & AUTORISATIONS ===
    Enable                  : BOOL;         // --> [CMD] Activation generale du sequenceur
    Reset                   : BOOL;         // --> [CMD] Acquittement defaut (front)
    PowerContactorEngaged   : BOOL;         // --> [SAFE] Chaine de securite OK
    Mode                    : E_Mode;       // --> [CMD] Mode arbitre (SEMI_AUTO pour instance cycle)
    CycleMotionPermit       : BOOL;         // --> [CMD] Manche deflecte (non centre)
    DeadmanArmed            : BOOL;         // --> [CMD] Appui homme-mort (fenetre 3 s)
    HeartbeatIhmOk          : BOOL;         // --> [SAFE] IHM<->PLC valide

    // === COMMANDES OPERATEUR ===
    StartCycle              : BOOL;         // --> [CMD] Demande lancement / reprise (IHM)
    AbortCycle              : BOOL;         // --> [CMD] Demande abandon (IHM)

    // === CIBLES ET CONFIGURATION ===
    SelTarget               : INT;          // --> [CFG] Cible selectionnee (1=Tremie, 2=P2, 3=P1, 4=Maintenance)
    SetDepthM               : REAL;         // --> [CFG] Profondeur de consigne (negative)
    SetOffsetM              : REAL;         // --> [CFG] Ecart de fermeture benne cible

    // === FEEDBACKS CAPTEURS & MATERIEL ===
    KoboldContactFond       : BOOL;         // --> [HW] Retour dedie Kobold : TRUE = contact fond
    LimitLegalReached       : BOOL;         // --> [SAFE] Limite legale atteinte (descente interdite)
    LimitLegalDepthM        : REAL;         // --> [CFG] Profondeur legale minimale autorisee
    WinchSyncError          : BOOL;         // --> [SAFE] Desynchronisme bloquant M1/M2
    WinchSyncDeltaM         : REAL;         // --> [HW] Ecart codeurs M1/M2 pour diagnostic
    M1_CablePosM            : REAL;         // --> [HW] Position cable treuil M1 (recalee)
    M2_CablePosM            : REAL;         // --> [HW] Position cable treuil M2 (recalee)
    M1_MeasuredSpeedMps     : REAL;         // --> [HW] Vitesse lineaire mesuree M1 (m/s)
    M2_MeasuredSpeedMps     : REAL;         // --> [HW] Vitesse lineaire mesuree M2 (m/s)
    SpeedMismatchThresholdMps : REAL;       // --> [CFG] Seuil ecart vitesse ; 0 = controle desactive
    SpeedMismatchTimeout    : TIME;         // --> [CFG] Duree de confirmation ; 0 = controle desactive
    CableLimitM1AscentM     : REAL;         // --> [CFG] Limite haute d'exploitation M1

    // === FEEDBACKS TRANSLATION M3 ===
    Translation_At_P1           : BOOL;     // --> [HW] Capteur position P1 (arret travail)
    Translation_At_Tremie       : BOOL;     // --> [HW] Capteur fin de course tremie
    Translation_At_Maintenance : BOOL;     // --> [HW] Capteur fin de course maintenance
    Translation_Busy            : BOOL;     // --> [HW] Mouvement translation en cours
    Translation_Done            : BOOL;     // --> [HW] Cible translation atteinte

    // === FEEDBACKS BENNE ===
    Benne_Busy              : BOOL;         // --> [HW] Mouvement machoires benne en cours
    Benne_Done              : BOOL;         // --> [HW] Mouvement ouverture/fermeture termine
    Benne_IsOpen            : BOOL;         // --> [HW] Benne mecaniquement ouverte memorisee
    Benne_IsClosed          : BOOL;         // --> [HW] Benne mecaniquement fermee memorisee
    Benne_IsRoughlyClosed   : BOOL;         // --> [HW] Benne a peu pres fermee (tolerance matiere)

    // === REFERENCEMENT CODEURS ===
    HomedM1                 : BOOL;         // --> [HW] Codeur M1 reference
    HomedM2                 : BOOL;         // --> [HW] Codeur M2 reference
    TopPositionSensor       : BOOL;         // --> [HW] Capteur position haute (referencement)
    HomingRequest           : BOOL;         // --> [CMD] Demande de referencement (front)
END_VAR
VAR_OUTPUT
    // === ETATS IEC & DEFECTUOSITES ===
    Ready                   : BOOL;         // <-- [STAT] Sequenceur disponible
    Busy                    : BOOL;         // <-- [STAT] Cycle automatique actif
    Done                    : BOOL;         // <-- [STAT] Cycle automatique complete
    Error                   : BOOL;         // <-- [STAT] Defaut cycle
    ErrorId                 : WORD;         // <-- [DIAG] Code erreur bitmask
    SpeedMismatchMps        : REAL;         // <-- [DIAG] Ecart absolu vitesse M1/M2 (m/s)
    SpeedMismatchActive     : BOOL;         // <-- [DIAG] Seuil vitesse depasse sur cycle courant
    SpeedMismatchConfirmed  : BOOL;         // <-- [DIAG] Ecart vitesse confirme pendant timeout

    // === ORDRES ACTIONNEURS (COMMANDES STRUCTUREES) ===
    WinchM1Cmd              : ST_WinchCmdDemand;        // <-- [ACT] Demande treuil M1
    WinchM2Cmd              : ST_WinchCmdDemand;        // <-- [ACT] Demande treuil M2
    TranslationCmd          : ST_TranslationCmdDemand;  // <-- [ACT] Demande translation M3
    BucketCmd               : ST_BucketCmdDemand;       // <-- [ACT] Demande benne

    // === METADONNEES & SYNOPTIQUE ===
    CycleStep               : E_CycleStep;  // <-- [STAT] Etape active du Grafcet
    CycleStateStr           : STRING(80);   // <-- [STAT] Libelle en clair de l'etape
    CycleStepAtError        : E_CycleStep;  // <-- [DIAG] Etape specifique au moment du defaut
END_VAR
VAR_IN_OUT
    // === STRUCTURES PARTAGEES & COMPTEURS ===
    SampleCount             : INT;          // <-> [BUS] Compteur de prelevements (RETAIN)
END_VAR
VAR
    // === DETECTEURS DE FRONTS ===
    ResetEdge               : R_TRIG;       // . [LOC] Detecteur front montant Reset
    StartEdge               : R_TRIG;       // . [LOC] Detecteur front montant StartCycle
    DeadmanArmedEdge        : R_TRIG;       // . [LOC] Detecteur front montant DeadmanArmed (demarrage joystick)
    AbortEdge               : R_TRIG;       // . [LOC] Detecteur front montant AbortCycle
    ErrorEdge               : R_TRIG;       // . [LOC] Detecteur front montant Error

    // === ETATS INTERNES ===
    State                   : E_CycleStep := E_CycleStep.X0_PREPARATION; // . [LOC] Etape courante machine d'etat
    SavedState              : E_CycleStep := E_CycleStep.X0_PREPARATION; // . [LOC] Etape memorisee

    // === MEMORISATIONS & REGISTRES INTERNES ===
    TouchPositionM          : REAL;         // . [LOC] Position M1 memorisee lors du contact fond
    RaiseTargetM            : REAL;         // . [LOC] Profondeur de remontee memorisee
    SelectedWorkTarget      : INT;          // . [LOC] Cible de travail memorisee

    // === TEMPORISATEURS INTERNES ===
    DrainingTimer           : TON;          // . [LOC] Temporisateur de vidage (egouttage)
    StabilizationTimer      : TON;          // . [LOC] Temporisation maximale de remontee lente
    SpeedMismatchTimer      : TON;          // . [LOC] Confirmation temporelle ecart de vitesse
    StepMaxTimer            : TON;          // . [LOC] Tempo max d'etape

    // === CONSTANTES & CONFIGURATIONS INTERNES ===
    CtrlAscentDistM         : REAL := 2.0;      // . [LOC] Distance de remontee lente de controle
    CtrlAscentToleranceM    : REAL := 0.25;     // . [LOC] Ecart maximal admis entre codeurs
    CtrlAscentTimeout       : TIME := T#30s;    // . [LOC] Temps max pour zone de stabilisation
    DrainingTime            : TIME := T#5s;     // . [LOC] Temps d'egouttage par defaut
    StepMaxTimeout          : TIME := T#60s;    // . [LOC] Tempo max d'etape
END_VAR

// === IMPLEMENTATION ===

{region "§1 Gate securite"}
// 🛑 1. GATES DE SÉCURITÉ ET BLOCAGE (R8)
IF NOT Enable OR NOT PowerContactorEngaged THEN
    WinchM1Cmd.StartStop   := FALSE;
    WinchM1Cmd.Direction   := 0;
    WinchM1Cmd.SpeedPct    := 0.0;

    WinchM2Cmd.StartStop   := FALSE;
    WinchM2Cmd.Direction   := 0;
    WinchM2Cmd.SpeedPct    := 0.0;

    TranslationCmd.Start   := FALSE;
    TranslationCmd.Target  := 0;

    BucketCmd.Open         := FALSE;
    BucketCmd.Close        := FALSE;
    BucketCmd.KoboldContactorCmd := FALSE;

    State                := E_CycleStep.X0_PREPARATION;   // retour à la PREMIÈRE étape (R8)
    CycleStep            := E_CycleStep.X0_PREPARATION;
    CycleStateStr        := 'X0 - Désactivé : sécurité absente ou auto désactivé';
    Ready                := FALSE;
    Busy                 := FALSE;
    Done                 := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Preparation surveillance et commandes cycle"}
Ready := TRUE;
ResetEdge(CLK := Reset);
StartEdge(CLK := StartCycle);
DeadmanArmedEdge(CLK := DeadmanArmed);
AbortEdge(CLK := AbortCycle);
ErrorEdge(CLK := Error);

// 🧊 R9 — capture l'étape spécifique AVANT la bascule vers STABILIZING
IF ErrorEdge.Q THEN
    CycleStepAtError := State;
END_IF;

// ⏱️ Surveillance indépendante de la remontée lente
StabilizationTimer(IN := (State = E_CycleStep.X7_CTRL_ASCENT), PT := CtrlAscentTimeout);

// 📏 Comparaison vitesse réelle M1/M2
SpeedMismatchMps := ABS(M1_MeasuredSpeedMps - M2_MeasuredSpeedMps);
SpeedMismatchActive := (State = E_CycleStep.X7_CTRL_ASCENT)
                       AND CycleMotionPermit
                       AND (SpeedMismatchThresholdMps > 0.0)
                       AND (SpeedMismatchTimeout > T#0ms)
                       AND (SpeedMismatchMps > SpeedMismatchThresholdMps);
SpeedMismatchTimer(IN := SpeedMismatchActive, PT := SpeedMismatchTimeout);
SpeedMismatchConfirmed := SpeedMismatchTimer.Q;

// Tempo max d'étape (R5) — lancée SEULEMENT si pilotage joystick actif (pas de défaut au repos)
StepMaxTimer(IN := CycleMotionPermit AND (State <> E_CycleStep.X0_PREPARATION)
                  AND (State <> E_CycleStep.X13_DONE_SYNC)
                  AND (State <> E_CycleStep.STABILIZING),
             PT := StepMaxTimeout);

IF ResetEdge.Q THEN
    Error := FALSE;
    ErrorId := 16#0000;
    SavedState := E_CycleStep.X0_PREPARATION;
    IF State = E_CycleStep.STABILIZING THEN
        State := E_CycleStep.X0_PREPARATION;
    END_IF;
END_IF;

// 💓 Perte IHM : repli mémorisé. La reconnexion seule ne relance jamais le cycle.
IF NOT HeartbeatIhmOk AND State <> E_CycleStep.STABILIZING THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0020;
    State := E_CycleStep.STABILIZING;
END_IF;

// Défaut de synchronisme : arrêt sûr et acquittement obligatoire.
IF WinchSyncError AND State <> E_CycleStep.STABILIZING THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0002;
    State := E_CycleStep.STABILIZING;
END_IF;

// 🛡️ Écart de vitesse confirmé : arrêt du cycle et STABILIZING.
IF SpeedMismatchConfirmed AND State <> E_CycleStep.STABILIZING THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0010;
    State := E_CycleStep.STABILIZING;
END_IF;

// Tempo max d'étape dépassée (blocage probable) → défaut
IF StepMaxTimer.Q AND State <> E_CycleStep.STABILIZING THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0040;
    State := E_CycleStep.STABILIZING;
END_IF;

// Gestion de l'Abandon (D3 — pas de Pause)
IF AbortEdge.Q THEN
    State := E_CycleStep.X0_PREPARATION;
END_IF;
{endregion}

{region "§3 Machine etat cycle automatique"}
// 🔁 2. LOGIQUE DU SÉQUENCEUR (Machine d'état) — CASE sur enum unique (R1)
CASE State OF

    E_CycleStep.X0_PREPARATION:
        CycleStep := E_CycleStep.X0_PREPARATION;
        CycleStateStr := 'X0 - Vérification cohérence système';
        WinchM1Cmd.StartStop := FALSE; WinchM1Cmd.Direction := 0; WinchM1Cmd.SpeedPct := 0.0;
        WinchM2Cmd.StartStop := FALSE; WinchM2Cmd.Direction := 0; WinchM2Cmd.SpeedPct := 0.0;
        TranslationCmd.Start := FALSE; TranslationCmd.Target := 0;
        BucketCmd.Open := FALSE; BucketCmd.Close := FALSE; BucketCmd.KoboldContactorCmd := FALSE;
        Busy := FALSE; Done := FALSE;

        // Transition si système sain et réarmé (front reset ou démarrage).
        // 🔫 D2 : démarrage par bouton IHM (StartEdge) OU armement homme-mort joystick
        // (DeadmanArmedEdge) — l'opérateur peut lancer depuis l'IHM ou le joystick.
        // La continuité des mouvements ne dépend que de CycleMotionPermit (manche défléchi).
        IF StartEdge.Q OR DeadmanArmedEdge.Q THEN
            State := E_CycleStep.X1_HOMING;
        END_IF;

    E_CycleStep.X1_HOMING:
        CycleStep := E_CycleStep.X1_HOMING;
        CycleStateStr := 'X1 - Référencement codeurs (vitesses lentes)';
        Busy := TRUE;

        // Vitesses lentes pour chercher capteur top + référencement
        IF NOT HomedM1 OR NOT HomedM2 THEN
            WinchM1Cmd.StartStop := CycleMotionPermit;
            WinchM1Cmd.Direction := 1;   // montée lente vers capteur top
            WinchM1Cmd.SpeedPct := 10.0;
            WinchM2Cmd.StartStop := CycleMotionPermit;
            WinchM2Cmd.Direction := 1;
            WinchM2Cmd.SpeedPct := 10.0;
            IF HomingRequest THEN
                // déclenche le référencement (via FB_Encoder_Homing en aval)
                State := E_CycleStep.X2_WORK_POS_SELECT;
            END_IF;
        ELSE
            // déjà homé → passe vite
            State := E_CycleStep.X2_WORK_POS_SELECT;
        END_IF;

    E_CycleStep.X2_WORK_POS_SELECT:
        CycleStep := E_CycleStep.X2_WORK_POS_SELECT;
        CycleStateStr := 'X2 - Sélection position travail';
        Busy := TRUE;

        // Destinations sélectionnables : Trémie(1), P1(3), Maintenance(4).
        // P2(2) n'est PAS une destination — capteur de passage en petite vitesse (PV).
        // Si aucune cible valide n'est sélectionnée, on ATTEND à X2 (pas de défaut) :
        // l'opérateur choisit la position de travail via l'IHM (SelTarget).
        IF (SelTarget = 1) OR (SelTarget = 3) OR (SelTarget = 4) THEN
            SelectedWorkTarget := SelTarget;
            TranslationCmd.Target := SelTarget;
            TranslationCmd.Start := CycleMotionPermit;
            // Arrivée à la cible (Trémie/P1/Maintenance) — capteurs PV/PVP2/P2 = ralentissement
            IF CycleMotionPermit AND (
                (SelTarget = 1 AND Translation_At_Tremie) OR
                (SelTarget = 3 AND Translation_At_P1) OR
                (SelTarget = 4 AND Translation_At_Maintenance)) THEN
                TranslationCmd.Start := FALSE;
                State := E_CycleStep.X3_OPEN_BUCKET;
            END_IF;
        END_IF;

    E_CycleStep.X3_OPEN_BUCKET:
        CycleStep := E_CycleStep.X3_OPEN_BUCKET;
        CycleStateStr := 'X3 - Ouverture benne';
        Busy := TRUE;

        // Ouverture benne ; si déjà ouverte → passe vite
        IF Benne_IsOpen THEN
            State := E_CycleStep.X4_DESCEND_OPEN;
        ELSE
            BucketCmd.Open := CycleMotionPermit;
            IF CycleMotionPermit AND Benne_Done AND Benne_IsOpen THEN
                BucketCmd.Open := FALSE;
                State := E_CycleStep.X4_DESCEND_OPEN;
            END_IF;
        END_IF;

    E_CycleStep.X4_DESCEND_OPEN:
        CycleStep := E_CycleStep.X4_DESCEND_OPEN;
        CycleStateStr := 'X4 - Plongée benne ouverte (synchro)';

        // M1 et M2 descendent ensemble (synchro gérée en aval)
        WinchM1Cmd.StartStop := CycleMotionPermit;
        WinchM1Cmd.Direction := -1;
        WinchM1Cmd.SpeedPct  := 50.0;
        WinchM2Cmd.StartStop := CycleMotionPermit;
        WinchM2Cmd.Direction := -1;
        WinchM2Cmd.SpeedPct  := 50.0;
        BucketCmd.KoboldContactorCmd := TRUE;

        // Transition uniquement sur le retour dédié Kobold.
        IF CycleMotionPermit AND KoboldContactFond THEN
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            BucketCmd.KoboldContactorCmd := FALSE;
            TouchPositionM := M1_CablePosM;
            IF LimitLegalDepthM < -0.01 THEN
                RaiseTargetM := MAX(TouchPositionM + 0.5, LimitLegalDepthM + 0.5);
            ELSE
                RaiseTargetM := TouchPositionM + 0.5;
            END_IF;
            State := E_CycleStep.X5_BOTTOM_CONFIRMED;
        ELSIF LimitLegalReached THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0001;
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            BucketCmd.KoboldContactorCmd := FALSE;
            State := E_CycleStep.STABILIZING;
        END_IF;

    E_CycleStep.X5_BOTTOM_CONFIRMED:
        CycleStep := E_CycleStep.X5_BOTTOM_CONFIRMED;
        CycleStateStr := 'X5 - Fond confirmé : remontée sécurisée';

        WinchM1Cmd.StartStop := CycleMotionPermit;
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct := 20.0;
        WinchM2Cmd.StartStop := CycleMotionPermit;
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct := 20.0;

        // Les deux treuils restent synchronisés jusqu'au-dessus de la limite légale.
        IF CycleMotionPermit AND (M1_CablePosM >= RaiseTargetM) AND (M2_CablePosM >= RaiseTargetM) THEN
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            State := E_CycleStep.X6_CLOSE_BUCKET;
        END_IF;

    E_CycleStep.X6_CLOSE_BUCKET:
        CycleStep := E_CycleStep.X6_CLOSE_BUCKET;
        CycleStateStr := 'X6 - Fermeture benne (tolérance à peu près fermé)';

        WinchM1Cmd.StartStop := FALSE;
        BucketCmd.Close := TRUE;

        // Tolérance : si benne « à peu près fermée » (matière/objet), on remonte et on contrôle
        IF CycleMotionPermit AND (Benne_Done AND (Benne_IsClosed OR Benne_IsRoughlyClosed)) THEN
            BucketCmd.Close := FALSE;
            State := E_CycleStep.X7_CTRL_ASCENT;
        END_IF;

    E_CycleStep.X7_CTRL_ASCENT:
        CycleStep := E_CycleStep.X7_CTRL_ASCENT;
        CycleStateStr := 'X7 - Remontée lente de contrôle';

        WinchM1Cmd.StartStop := CycleMotionPermit;
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct  := 20.0;
        WinchM2Cmd.StartStop := CycleMotionPermit;
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct  := 20.0;

        // Contrôle des deux codeurs
        IF WinchSyncError OR (ABS(M1_CablePosM - M2_CablePosM) > CtrlAscentToleranceM) THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0008;
            State := E_CycleStep.STABILIZING;
        ELSIF CycleMotionPermit
           AND (M1_CablePosM >= (TouchPositionM + CtrlAscentDistM))
           AND (M2_CablePosM >= (TouchPositionM + CtrlAscentDistM))
           AND (ABS(M1_CablePosM - M2_CablePosM) <= CtrlAscentToleranceM) THEN
            State := E_CycleStep.X8_ASCENT_LOADED;
        ELSIF StabilizationTimer.Q THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0008;
            State := E_CycleStep.STABILIZING;
        END_IF;

    E_CycleStep.X8_ASCENT_LOADED:
        CycleStep := E_CycleStep.X8_ASCENT_LOADED;
        CycleStateStr := 'X8 - Remontée en charge';

        WinchM1Cmd.StartStop := CycleMotionPermit;
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct  := 70.0;
        WinchM2Cmd.StartStop := CycleMotionPermit;
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct  := 70.0;

        // Transition alignée sur la limite haute d'exploitation
        IF CycleMotionPermit AND M1_CablePosM >= CableLimitM1AscentM THEN
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            State := E_CycleStep.X9_DRAIN_PAUSE;
        END_IF;

    E_CycleStep.X9_DRAIN_PAUSE:
        CycleStep := E_CycleStep.X9_DRAIN_PAUSE;
        CycleStateStr := 'X9 - Égouttage du godet en cours';
        WinchM1Cmd.StartStop := FALSE;
        WinchM2Cmd.StartStop := FALSE;

        DrainingTimer(IN := TRUE, PT := DrainingTime);
        // Temps écoulé affiché IHM (CycleStateStr + champ dédié)
        IF CycleMotionPermit AND DrainingTimer.Q THEN
            DrainingTimer(IN := FALSE);
            State := E_CycleStep.X10_TRANSLATE_DUMP;
        END_IF;

    E_CycleStep.X10_TRANSLATE_DUMP:
        CycleStep := E_CycleStep.X10_TRANSLATE_DUMP;
        CycleStateStr := 'X10 - Déplacement vers trémie (grille/crible libres)';

        TranslationCmd.Target := 1; // Trémie
        TranslationCmd.Start := CycleMotionPermit;

        // Avertissement IHM : grille abaissée/libre, crible libre pour réceptionner la charge
        // (porté par CycleStateStr + OperatorAction côté supervision)

        // Transition si translation arrivé à la trémie
        IF CycleMotionPermit AND Translation_At_Tremie THEN
            TranslationCmd.Start := FALSE;
            State := E_CycleStep.X11_OPEN_DUMP;
        END_IF;

    E_CycleStep.X11_OPEN_DUMP:
        CycleStep := E_CycleStep.X11_OPEN_DUMP;
        CycleStateStr := 'X11 - Vidange / ouverture du godet (montée possible, descente ouvre)';

        // Montée possible (treuils vers le haut) ; descente fait ouvrir la benne.
        // Montée : on laisse l'opérateur remonter les 2 treuils en synchro si besoin.
        WinchM1Cmd.StartStop := CycleMotionPermit AND (WinchM1Cmd.Direction = 1);
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct  := 20.0;
        WinchM2Cmd.StartStop := CycleMotionPermit AND (WinchM2Cmd.Direction = 1);
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct  := 20.0;

        // Descente → ouverture benne (vidage)
        BucketCmd.Open := CycleMotionPermit AND (WinchM1Cmd.Direction = -1);

        // Contrôle convoyeurs par MESSAGE utilisateur (pas encore câblé) :
        // CycleStateStr + OperatorAction côté supervision demandent de vérifier
        // que les convoyeurs sont en route avant/au lâcher.
        IF CycleMotionPermit AND Benne_Done AND Benne_IsOpen THEN
            BucketCmd.Open := FALSE;
            State := E_CycleStep.X13_DONE_SYNC;
        END_IF;

    E_CycleStep.X13_DONE_SYNC:
        CycleStep := E_CycleStep.X13_DONE_SYNC;
        CycleStateStr := 'X13 - Cycle automatique complété - prêt';
        WinchM1Cmd.StartStop := FALSE;
        WinchM2Cmd.StartStop := FALSE;
        TranslationCmd.Start := FALSE;
        Done := TRUE;
        Busy := FALSE;

        // Compteur de prélèvements (RETAIN, Q3bis) — compte inconditionnellement
        SampleCount := SampleCount + 1;

        // Rebouclage sur X0_PREPARATION (trémie, treuils hauts) — pas de retour P1
        IF StartEdge.Q THEN
            Done := FALSE;
            State := E_CycleStep.X0_PREPARATION;
        END_IF;

    E_CycleStep.STABILIZING:
        CycleStep := E_CycleStep.STABILIZING;
        CycleStateStr := 'X14 - Cycle en attente / stabilisation (STAB)';
        WinchM1Cmd.StartStop := FALSE;
        WinchM2Cmd.StartStop := FALSE;
        TranslationCmd.Start := FALSE;
        BucketCmd.Open := FALSE;
        BucketCmd.Close := FALSE;

END_CASE;
{endregion}

{region "§4 Repli homme mort"}
// 🛑 Relâchement du manche (retour au centre) : aucune demande d'actionneur ne reste active.
// L'étape est mémorisée et reprend au prochain appui valide (D2).
IF Busy AND NOT CycleMotionPermit THEN
    WinchM1Cmd.StartStop := FALSE;
    WinchM2Cmd.StartStop := FALSE;
    TranslationCmd.Start := FALSE;
    BucketCmd.Open := FALSE;
    BucketCmd.Close := FALSE;
    BucketCmd.KoboldContactorCmd := FALSE;
END_IF;
{endregion}

END_FUNCTION_BLOCK

TYPE ST_WinchSymmetryHMI :
STRUCT
    BtnReset : BOOL;
    SymmetryOk : BOOL;
    SymmetryValid : BOOL;
    DeltaStartDelay_Ms : UDINT;
    DeltaBrakeReleaseTime_Ms : UDINT;
    DeltaBrakeApplyTime_Ms : UDINT;
    DeltaStopDistance_M : REAL;
    DeltaStopTime_Ms : UDINT;
    MaxSyncDeviation_M : REAL;
END_STRUCT
END_TYPE

(* ═══════════════════════════════════════════════════════════════
   ST_CommunCfg — Configuration des paramètres communs machine
   ═══════════════════════════════════════════════════════════════ *)
TYPE ST_CommunCfg :
STRUCT
    // Blocage instantané à 0m : sans défaut explicite,
    // ce champ vaut 0.0 tant qu'il n'a pas été réglé côté IHM -- "CablePosM <= 0.0" se déclenche
    // dès la position de référence, avant tout réglage réel de la cote légale. Défaut -999.0
    // (jamais atteint en pratique) : LimitLegalEnabled=TRUE sans réglage ne bloque plus rien par
    // erreur -- il faut régler la vraie cote pour que la protection devienne active.
    LimitLegalDepthMinAllowed_M : REAL := -999.0; (* 📐 Cote min de dragage autorisée (m, négatif) *)
    LimitLegalEnabled           : BOOL; (* 🟢 Activation de la limite légale *)
    SelHomingApproachEnable     : BOOL; (* 🔌 Case IHM : autorise le dépassement butée haute pour homing (si MAINT_N2) *)
    WinchMaxStepDescente        : INT := 3;     (* 🛑 Limitation palier vitesse en descente (1..5), commun M1/M2 *)
    WinchMaxStepAscent          : INT := 5;     (* 🚀 Limitation palier vitesse en montée (1..5), commun M1/M2 *)
    WinchSlowdownDistance_M     : REAL := 1.0;  (* 📏 Distance avant limite pour enclencher le ralentissement (m), commun M1/M2 *)
    // : WinchSlowSpeed_Pct (%) retiré — un treuil ne connaît que des paliers (1..5),
    // pas une vitesse continue.
    WinchSlowdownMaxStep        : INT := 1;     (* : Plafond palier dans la zone de ralentissement (1..5), commun M1/M2 *)
    CfgCableLimitAscent_M       : REAL := 7.5;  (* 📐 Limite haute d'exploitation NORMALE (m), commun M1/M2 *)
    TglEnableKoboldAutoStopDescent : BOOL := FALSE; (* : Arrêt auto descente sur détection fond Kobold (pilotage normal) *)
    // Coupe-circuit d'urgence pour le séquencement auto benne.
    // Défaut FALSE = mouvement M1/M2 synchro jamais
    // gouverné par instBucket.Busy sauf action MANUELLE benne/DumpAtTremie/ExtractionSequence).
    TglEnableCoupledBucketSequencing : BOOL := FALSE;
    Initialized                 : BOOL := FALSE; (* 🚦 flag restauration boot *)
END_STRUCT
END_TYPE

(* =======================================================================
   ⚙️ FB_Ramp — Rampe d'accélération et décélération asymétrique
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Limitation de variation anti-à-coups (%/s) sur signal analogique
   🔒 Polarité : Distingue l'éloignement de zéro (Accel) et le retour à zéro (Decel)
   📄 Doc métier : DOC/AF/AF_Partie-08_Fonction_Joystick_v2.0.md §2
   ======================================================================= *)
FUNCTION_BLOCK FB_Ramp
VAR_INPUT
    // === CONSIGNES ET TAUX DE RAMPE ===
    Target                  : REAL;               // --> [CMD] Valeur cible visee (-100.0..+100.0 %)
    AccelRate               : REAL;               // --> [CFG] Taux d'acceleration (%/s)
    DecelRate               : REAL;               // --> [CFG] Taux de deceleration (%/s)
    CycleTimeS              : REAL;               // --> [CFG] Temps de cycle reel en secondes (dt)
END_VAR
VAR_OUTPUT
    // === VALEUR RAMPEE ===
    Current                 : REAL;               // <-- [STAT] Valeur courante amortie (-100.0..+100.0 %)
END_VAR
VAR
    // === CALCULS INTERNES ===
    StepX                   : REAL;               // . [LOC] Pas de variation pour le cycle courant
    TargetLimited           : REAL;               // . [LOC] Cible bornee a [-100.0, +100.0]
END_VAR

// Détection du comportement (Accélération vs Décélération)
// Classification par CÔTÉ DE ZÉRO + sens de déplacement, plus par signe brut de Target seul
// (robuste à une traversée de zéro rapide).
// 🛡️ Garde-fou : la rampe ne sort jamais de la plage normalisée ±100 %.
TargetLimited := LIMIT(-100.0, Target, 100.0);
Current := LIMIT(-100.0, Current, 100.0);

IF (Current >= 0.0 AND TargetLimited >= Current) OR (Current <= 0.0 AND TargetLimited <= Current) THEN
    StepX := AccelRate * CycleTimeS; // S'éloigne du zéro (reste du même côté, va plus loin)
ELSE
    StepX := DecelRate * CycleTimeS; // Retourne vers zéro, ou le traverse vers l'autre signe
END_IF;

// Application de la rampe
IF Current < TargetLimited THEN
    Current := Current + StepX;
    IF Current > TargetLimited THEN Current := TargetLimited; END_IF;
ELSIF Current > TargetLimited THEN
    Current := Current - StepX;
    IF Current < TargetLimited THEN Current := TargetLimited; END_IF;
END_IF;

// 🛡️ Limitation finale : même une valeur d'état déjà corrompue reste bornée.
Current := LIMIT(-100.0, Current, 100.0);

(* =======================================================================
   ⚙️ FB_Encoder_Scale — Mise à l'échelle points → mètres (1 par treuil)
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Calcul de la position câble en mètres par conversion arithmétique signée
   🔒 Polarité : CablePosM signée (+ enroulé, - sous l'eau)
   🔌 Architecture : Convertisseur de mesure unitaire par treuil
   📄 Doc métier : DOC/AF/AF_Partie-09_Fonction_Encoder_v2.1.md
   ======================================================================= *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Encoder_Scale) ===

FUNCTION_BLOCK PUBLIC FB_Encoder_Scale
VAR_INPUT
    // === DONNEES ENTREE & REFERENCES BRUTES ===
    RawPos          : UDINT;       // --> [HW]  Position brute codeur (sortie FB_Encoder_Abs, gelee sur doute)
    HomingRefRaw    : UDINT;       // --> [CFG] Reference brute figee au dernier homing (ST_Encoder_Calib)

    // === PARAMETRES & RATIOS DE CONVERSION ===
    CableM_PerRev   : REAL := 2.0; // --> [CFG] Developpement cable par tour tambour (m/tour)
    PointsPerRev    : UDINT := 8192;// --> [CFG] Resolution codeur (pts/tour)
END_VAR
VAR_OUTPUT
    // === MESURE CONVERTIE ===
    CablePosM       : REAL;        // <-- [DIAG] Position cable en metres (+ enroule, - sous l'eau)
END_VAR
VAR
    // === CALCULS INTERNES ===
    RawDiff         : DINT;        // . [LOC] Ecart signe RawPos - HomingRefRaw
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Scale) ===

// 🧮 Écart signé sûr : conversion DINT AVANT soustraction (§3.1) — jamais l'inverse
RawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(HomingRefRaw);

// 📏 Formule fixe points → mètres (Partie10 §2), garde division par zéro
IF PointsPerRev > 0 THEN
    CablePosM := DINT_TO_REAL(RawDiff) * (CableM_PerRev / UDINT_TO_REAL(PointsPerRev));
ELSE
    CablePosM := 0.0;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   🔘 FB_ResetAggregation — Producteur unique du niveau Reset IHM
   ───────────────────────────────────────────────────────────────
   📄 Contrat : ST_ResetCommand
   🛡️ Agrège uniquement les quatre boutons existants. Il ne détecte
      pas de front et ne réarme rien : les consommateurs conservent
      leur R_TRIG local, conformément à la règle Reset = front.
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK FB_ResetAggregation
VAR_INPUT
    BtnFaultReset : BOOL;
    BtnResetM1 : BOOL;
    BtnResetM2 : BOOL;
    BtnResetBucket : BOOL;
END_VAR
VAR_OUTPUT
    Cmd : ST_ResetCommand;
END_VAR

Cmd.CmdReset := BtnFaultReset OR BtnResetM1 OR BtnResetM2 OR BtnResetBucket;

(* ═══════════════════════════════════════════════════════════════
   ↔️ FB_Translation_PositionEstimator — Estimateur de Position Continue M3
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-11_Fonction_Translation_v2.1.md §3
   🎯 Rôle : Calculer par odométrie (intégration temporelle vitesse/fréquence Hz * sens)
      la position estimée continue en mètres (0.0 m à la Maintenance -> +X m à la Trémie),
      avec re-calage absolu automatique instantané sur le franchissement des 5 capteurs fixes.
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Translation_PositionEstimator
VAR_INPUT
    Enable               : BOOL;   (* Active le calcul *)
    Reset                : BOOL;   (* Front d'acquittement / réinitialisation *)
    DriveActualFreqHz    : REAL;   (* Fréquence réelle variateur en Hz (ex: 5.0 Hz) *)
    Direction            : INT;    (* Sens effectif : +1 = Fwd (vers Trémie), -1 = Rev (vers Maint), 0 = Arrêt *)
    
    (* 5 Capteurs de position fixes *)
    SensorMaintenance    : BOOL;   (* Capteur 0 : Maintenance (0.0 m) *)
    SensorP1             : BOOL;   (* Capteur 1 : P1 (ex: 6.0 m) *)
    SensorP2             : BOOL;   (* Capteur 2 : P2 (ex: 14.0 m) *)
    SensorPV             : BOOL;   (* Capteur 3 : PV (ex: 21.0 m) *)
    SensorTremie         : BOOL;   (* Capteur 4 : Trémie (ex: 25.0 m) *)

    (* Positions de référence calibrées (mètres) depuis GVL_PERSISTENT *)
    PosMaintenanceM      : REAL := 0.0;
    PosP1M               : REAL := 6.0;
    PosP2M               : REAL := 14.0;
    PosPVM               : REAL := 21.0;
    PosTremieM           : REAL := 25.0;

    (* Gain de vitesse : mètres parcourus par Hz par seconde (ex: 50 Hz = 0.416 m/s => Gain = 0.008333 m/Hz.s) *)
    GainMetersPerHzSec   : REAL := 0.008333;

    (* 🆕 2026-08-06 : reprise après reboot — l'appelant recopie en continu PositionEstimatedM/
       Initialized vers GVL_PERSISTENT (pas de bridge dédié, simple recopie comme _TranslationSetFreq_Hz)
       et réinjecte ici au redémarrage, pour ne pas perdre l'estimation odométrique à chaque coupure. *)
    PersistedPositionM   : REAL := 0.0;
    PersistedInitialized : BOOL := FALSE;
END_VAR

VAR_OUTPUT
    PositionEstimatedM   : REAL;   (* Position continue estimée en mètres *)
    Initialized          : BOOL;   (* 🆕 exposé pour recopie persistante côté appelant *)
    Recalibrated         : BOOL;   (* Pulse 1 cycle lors d'un recalage sur capteur *)
    RecalibratedSensorId : INT;    (* 0=Maint, 1=P1, 2=P2, 3=PV, 4=Trémie, -1=Aucun *)
END_VAR

VAR
    TrigTremie           : R_TRIG;
    TrigPV                : R_TRIG;
    TrigP2                : R_TRIG;
    TrigP1                : R_TRIG;
    TrigMaintenance       : R_TRIG;
    CycleTimeCalc         : FB_CycleTime;
    ColdStart             : BOOL := TRUE;  // 🆕 seed unique depuis Persisted* au premier scan utile
END_VAR

// === IMPLEMENTATION ===

IF NOT Enable THEN
    Recalibrated := FALSE;
    RecalibratedSensorId := -1;
    RETURN;
END_IF;

IF ColdStart THEN
    PositionEstimatedM := PersistedPositionM;
    Initialized := PersistedInitialized;
    ColdStart := FALSE;
END_IF;

CycleTimeCalc(DefaultValueS := 0.010);
Recalibrated := FALSE;

// 1. Détection des fronts montants sur franchissement des capteurs fixes
TrigTremie(CLK := SensorTremie);
TrigPV(CLK := SensorPV);
TrigP2(CLK := SensorP2);
TrigP1(CLK := SensorP1);
TrigMaintenance(CLK := SensorMaintenance);

// 2. Recalage absolu prioritaire sur contact capteur
IF TrigMaintenance.Q THEN
    PositionEstimatedM := PosMaintenanceM;
    Recalibrated := TRUE;
    RecalibratedSensorId := 0;
ELSIF TrigP1.Q THEN
    PositionEstimatedM := PosP1M;
    Recalibrated := TRUE;
    RecalibratedSensorId := 1;
ELSIF TrigP2.Q THEN
    PositionEstimatedM := PosP2M;
    Recalibrated := TRUE;
    RecalibratedSensorId := 2;
ELSIF TrigPV.Q THEN
    PositionEstimatedM := PosPVM;
    Recalibrated := TRUE;
    RecalibratedSensorId := 3;
ELSIF TrigTremie.Q THEN
    PositionEstimatedM := PosTremieM;
    Recalibrated := TRUE;
    RecalibratedSensorId := 4;
ELSE
    // Initialisation au tout premier démarrage sur le premier capteur actif vu
    IF NOT Initialized THEN
        IF SensorTremie THEN PositionEstimatedM := PosTremieM; Initialized := TRUE;
        ELSIF SensorPV THEN PositionEstimatedM := PosPVM; Initialized := TRUE;
        ELSIF SensorP2 THEN PositionEstimatedM := PosP2M; Initialized := TRUE;
        ELSIF SensorP1 THEN PositionEstimatedM := PosP1M; Initialized := TRUE;
        ELSIF SensorMaintenance THEN PositionEstimatedM := PosMaintenanceM; Initialized := TRUE;
        END_IF;
    END_IF;

    // 3. Intégration temporelle continue (Odométrie cycle par cycle)
    // dX = Direction * (FreqHz * Gain) * dt
    IF Direction <> 0 AND DriveActualFreqHz > 0.1 THEN
        PositionEstimatedM := PositionEstimatedM + (INT_TO_REAL(Direction) * DriveActualFreqHz * GainMetersPerHzSec * CycleTimeCalc.CycleTimeS);
    END_IF;
END_IF;

// Bornage de sécurité pour éviter la dérive infinie hors rail
PositionEstimatedM := LIMIT(PosMaintenanceM - 0.5, PositionEstimatedM, PosTremieM + 0.5);

