(* =======================================================================
   ⚙️ FB_Encoder_Homing — Référencement codeur nominal ou unitaire
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Séquence de référencement nominal (capteur haut) ou unitaire (MAINT_N2)
   🔒 Polarité : Homed=TRUE dès qu'un référencement valide est enregistré
   🔌 Architecture : Expose ST_Encoder_Calib en VAR_IN_OUT
   📄 Doc métier : DOC/AF/AF_Partie-09_Fonction_Encoder_v2.1.md
   ======================================================================= *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Encoder_Homing) ===

FUNCTION_BLOCK PUBLIC FB_Encoder_Homing
VAR_INPUT
    // === COMMANDES & AUTORISATIONS ===
    Enable                 : BOOL;        // --> [CMD] Autorisation generale FB (TRUE=Autorise)
    Reset                  : BOOL;        // --> [CMD] Acquittement defaut (front montant)
    Home                   : BOOL;        // --> [CMD] Demande de referencement (front)
    HomingPermit           : BOOL;        // --> [CMD] Autorisation de homer (calculee par le caller)
    BtnConfirmCoherence    : BOOL;        // --> [CMD] Levee de doute d'incoherence au boot (front)

    // === CIBLES & CONFIGURATION HOMING ===
    CfgHomingTargetM       : REAL;        // --> [CFG] Cible libre homing unitaire (m)
    UseDynamicTarget       : BOOL := FALSE; // --> [CFG] Activation cible dynamique
    DynamicHomingTargetM   : REAL := 0.0; // --> [CFG] Cible dynamique de referencement (m)
    CfgTopSensorPosM       : REAL := 8.5; // --> [CFG] Cible homing nominal capteur haut (m)

    // === RETOURS HW & CAPTEURS ===
    TopPositionSensor      : BOOL;        // --> [HW]  Capteur physique position haute unique
    FwdRevSpeedFeedbackOff : BOOL;        // --> [HW]  Contacteurs sens et vitesse retombes
    BrakeFeedback          : BOOL;        // --> [HW]  Contacteur frein ouvert/desserre

    // === MESURES & RETOURS FB CODEUR ABSOLU ===
    RawPos                 : UDINT;       // --> [HW]  Position brute codeur (sortie FB_Encoder_Abs)
    EncoderAvailable       : BOOL;        // --> [HW]  Codeur absolu disponible et valide
    PresetAck              : BOOL;        // --> [HW]  Pulse confirmation ecriture preset reussie
    PresetNak              : BOOL;        // --> [HW]  Pulse echec / timeout ecriture preset

    // === CARACTERISTIQUES MECANIQUES & BUS ===
    PointsPerRev           : UDINT := 8192; // --> [CFG] Resolution codeur (pts/tour)
    MultiTurnRevsMax       : UDINT := 4096; // --> [CFG] Capacite multitour max codeur (tours)
    CableM_PerRev          : REAL := 2.0;   // --> [CFG] Perimetre tambour / developpement cable (m/tour)

    // === TESTS & BYPASS ===
    BypassGlobal           : BOOL := FALSE; // --> [TST] Neutralisation securites pour mise en service
END_VAR
VAR_OUTPUT
    // === ETATS IEC & SYNOPTIQUE ===
    Ready                  : BOOL;        // <-- [STAT] FB pret a fonctionner
    // 🧩 Statut transverse (forme cible) — regroupe Busy/Done/Error/ErrorId/State/StateAtError.
    // ErrorId : masque de bits de défaut (bit0: mode, bit1: treuil, bit4: cible, bit5: preset, bit9: incoherence boot).
    Status                 : ST_FbStatus;

    // === COMMANDES VERS FB_ENCODER_ABS ===
    PresetRequest          : BOOL;        // <-- [ACT]  Pulse demande d'ecriture preset SDO
    PresetValue            : UDINT;       // <-- [ACT]  Valeur de cible brute pour preset SDO

    // === RESULTATS & MEMOIRE CALIBRATION ===
    Homed                  : BOOL;        // <-- [STAT] Codeur pagine et referencie
    HomingSuspect          : BOOL;        // <-- [DIAG] Incoherence redemarrage a lever
    HomingRefRaw           : UDINT;       // <-- [DIAG] Offset de reference brut calcule
END_VAR
VAR_IN_OUT
    // === STRUCTURE DE CALIBRATION PERSISTANTE ===
    Calib                  : ST_Encoder_Calib; // <-> [BUS] Structure de calibration RETAIN
END_VAR
VAR
    // === DETECTEURS DE FRONT ===
    ResetEdge              : R_TRIG;      // . [LOC] Detecteur front montant Reset
    ErrorEdge              : R_TRIG;      // . [LOC] Detecteur front montant Error
    HomeEdge               : R_TRIG;      // . [LOC] Detecteur front montant Home
    ConfirmCoherenceEdge   : R_TRIG;      // . [LOC] Detecteur front montant BtnConfirmCoherence
    TopSensorEdge          : R_TRIG;      // . [LOC] Detecteur front montant TopPositionSensor
    DynamicTargetEdge      : R_TRIG;      // . [LOC] Detecteur front montant UseDynamicTarget

    // === ETATS & DRAPEAUX INTERNES ===
    InitDone               : BOOL;        // . [LOC] Controle incoherence boot effectue
    ArretConfirme          : BOOL;        // . [LOC] Condition d'arret moteur confirmee
    HomingModeOk           : BOOL;        // . [LOC] Mode de fonctionnement valide pour homing
    NominalHomingTrigger   : BOOL;        // . [LOC] Condition de declenchement homing nominal
    UnitaryHomingTrigger   : BOOL;        // . [LOC] Condition de declenchement homing unitaire
    DynamicHomingTrigger   : BOOL;        // . [LOC] Condition de declenchement homing dynamique
    HomingTrigger          : BOOL;        // . [LOC] Synthese declenchement homing

    // === VARIABLES DE CALCUL ===
    TargetPoints           : DINT;        // . [LOC] Ecart cible converti en points
    TargetPositionM        : REAL;        // . [LOC] Cible retenue en metres
    RawDiffRestart         : DINT;        // . [LOC] Ecart brut de position au redemarrage
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Homing) ===

{region "§1 Gate neutralisation"}
// 🛑 1. GATE — neutralisation ; on continue toutefois d'exposer le dernier état RETAIN connu
// (FB_Encoder_Scale a besoin de HomingRefRaw même si ce FB est désactivé)
// PowerContactorEngaged retiré du GATE (le codeur 24V / EtherCAT peut être homé disjoncteurs coupés)
IF NOT Enable THEN
    PresetRequest := FALSE;
    PresetValue := 0;
    Status.State := E_State.DISABLED;
    Ready := FALSE; Status.Busy := FALSE; Status.Done := FALSE;
    InitDone := FALSE;   // Force un nouveau contrôle §3.7 à la prochaine activation
    Homed := Calib.Homed;
    HomingSuspect := Calib.HomingSuspect;
    HomingRefRaw := Calib.HomingRefRaw;
    RETURN;
END_IF;

Ready := TRUE;

{endregion}

{region "§2 Fronts et coherence demarrage"}
// 🔑 2. FRONTS
ResetEdge(CLK := Reset);
HomeEdge(CLK := Home);
ConfirmCoherenceEdge(CLK := BtnConfirmCoherence);

// 🔍 3. COHÉRENCE AU REDÉMARRAGE (§3.7) — une fois par session Enable, dès que le codeur répond
IF NOT InitDone THEN
    Status.State := E_State.INIT;
    IF EncoderAvailable THEN
        RawDiffRestart := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(Calib.LastKnownRawPos);
        IF Calib.Homed AND (ABS(RawDiffRestart) > UDINT_TO_DINT(Calib.RestartCoherenceTolerancePts)) THEN
            Calib.HomingSuspect := TRUE;
            Status.ErrorId := Status.ErrorId OR 16#0200;   // bit9 : incohérence codeur au redémarrage
        END_IF;
        InitDone := TRUE;
    END_IF;
ELSE
    IF Status.State = E_State.INIT THEN Status.State := E_State.READY; END_IF;
END_IF;

{endregion}

{region "§3 Confirmation coherence et demande homing"}
// ✅ 4. LEVÉE DU DOUTE (BtnConfirmCoherence, §3.7) — indépendant du Reset générique
IF ConfirmCoherenceEdge.Q AND HomingPermit THEN
    Calib.HomingSuspect := FALSE;
    Status.ErrorId := Status.ErrorId AND 16#FDFF;   // efface bit9
END_IF;

PresetRequest := FALSE;
TopSensorEdge(CLK := TopPositionSensor);
DynamicTargetEdge(CLK := UseDynamicTarget);

// Gates rejetées = Warning auto-effaçable (§9/TC-P03-007), pas un Fault : recalculées à
// chaque scan, jamais latchées, aucun Reset requis pour les effacer.
Status.ErrorId := Status.ErrorId AND 16#FFEC;   // efface bits 0/1/4 (garde bit5, bit9 — inchangés)

HomingModeOk := HomingPermit;

IF HomeEdge.Q AND NOT HomingModeOk THEN
    Status.ErrorId := Status.ErrorId OR 16#0001;   // bit0 : homing non autorise
END_IF;

// Nominal : capture AU FRONT du capteur haut, pas après arrêt confirmé — AscentPermit
// (FB_Safety_Winch) coupe déjà la montée indépendamment dès que TopPositionSensor est actif ;
// attendre l'arrêt casserait la répétabilité recherchée à vitesse d'accostage constante.
// Couvre les deux cas : Home déjà maintenu quand le capteur déclenche, ou capteur déjà actif
// quand Home est pressé.
NominalHomingTrigger := HomingModeOk AND NOT UseDynamicTarget
                         AND ((Home AND TopSensorEdge.Q) OR (HomeEdge.Q AND TopPositionSensor));

// Unitaire : cible libre (CfgHomingTargetM), déclenchée par la demande (front).
UnitaryHomingTrigger := HomingModeOk AND NOT UseDynamicTarget AND HomeEdge.Q;

// Dynamique (benne) : HomingModeOk vérifié ici en défense.
DynamicHomingTrigger := HomingModeOk AND (DynamicTargetEdge.Q OR (UseDynamicTarget AND HomeEdge.Q));

HomingTrigger := NominalHomingTrigger OR UnitaryHomingTrigger OR DynamicHomingTrigger;

IF HomingTrigger THEN
    IF UseDynamicTarget THEN
        TargetPositionM := DynamicHomingTargetM;
    ELSIF NominalHomingTrigger THEN
        TargetPositionM := CfgTopSensorPosM;
    ELSE
        TargetPositionM := CfgHomingTargetM;
    END_IF;

    // Bornage obligatoire avant écriture (CODE_QUALITY_STANDARDS §6) — toute cible, quelle
    // que soit son origine (config, calcul benne, capteur haut), est vérifiée dans la plage
    // physique documentée [-99;+99] m avant d'être gravée dans la référence codeur.
    IF (TargetPositionM < -99.0) OR (TargetPositionM > 99.0) THEN
        Status.ErrorId := Status.ErrorId OR 16#0010;   // bit4 : cible hors plage, homing refusé
    ELSE
        TargetPoints := REAL_TO_DINT(TargetPositionM * UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
        Calib.HomingRefRaw := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) - TargetPoints);
        Calib.Homed := TRUE;
        Calib.HomingSuspect := FALSE;
        Calib.LastKnownRawPos := RawPos;
        HomingRefRaw := Calib.HomingRefRaw;
        Homed := TRUE;
        HomingSuspect := FALSE;
        Status.Done := TRUE;
        Status.ErrorId := 16#0000;
        Status.State := E_State.READY;

        // Envoi de la demande de Preset SDO au matériel : la valeur brute injectee
        // correspond a la cible (calcul inverse) pour que CablePosM = cible.
        PresetValue := DINT_TO_UDINT(UDINT_TO_DINT(Calib.HomingRefRaw) + TargetPoints);
        PresetRequest := TRUE;
    END_IF;
END_IF;

{endregion}

{region "§4 Suivi SDO reset et sorties etat"}
// ⏳ 6. SUIVI DE LA SÉQUENCE SDO OPTIONNELLE
IF Status.State = E_State.BUSY THEN
    IF PresetAck THEN
        Status.Done := TRUE;
        Status.State := E_State.READY;
        // Un homing réussi efface l'intégralité de ErrorId
        Status.ErrorId := 16#0000;
    ELSIF PresetNak THEN
        Status.ErrorId := Status.ErrorId OR 16#0020;        // bit5 : preset refusé/timeout (voir FB_Encoder_Abs)
        Status.State := E_State.READY;
    END_IF;
END_IF;

// 🧾 7. RESET (front) — efface les bits « dernière tentative rejetée » (pas de cause persistante
// à revérifier ici : le prochain Home réévalue toutes les conditions de zéro, voir §5)
IF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFC0;   // efface bits 0..5 (garde bit9, levé seulement par BtnConfirmCoherence/Home)
END_IF;

// 📤 8. SORTIES ÉTAT
Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;

// Mise à jour continue du point brut valide connu (hors séquence de homing elle-même)
IF EncoderAvailable AND (Status.State <> E_State.BUSY) THEN
    Calib.LastKnownRawPos := RawPos;
END_IF;

Status.Busy := (Status.State = E_State.BUSY);
Homed := Calib.Homed AND NOT Calib.HomingSuspect; // Perd l'état homed si suspect (démarrage ou fonctionnement), restauré après BtnConfirmCoherence
HomingSuspect := Calib.HomingSuspect;
HomingRefRaw := Calib.HomingRefRaw;

{endregion}

TYPE ST_Winch_SymmetryCfg :
STRUCT
    DeltaStartDelay_Ms : UDINT := 100;
    DeltaBrakeReleaseTime_Ms : UDINT := 100;
    DeltaBrakeApplyTime_Ms : UDINT := 100;
    DeltaStopDistance_Mm : UDINT := 100;
    DeltaStopTime_Ms : UDINT := 200;
    MinimumCommandTime_Ms : UDINT := 1000;
    MinimumSpeed_Mps : REAL := 0.05;
END_STRUCT
END_TYPE

SETUP
VAR
    fb : FB_BRAKE;
END_VAR
END_SETUP

TEST 'Gate : Enable=FALSE colle le frein immediatement (securite positive)'
    fb(ENABLE := FALSE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_FALSE(fb.READY, 'Enable=FALSE : FB non pret');
    ASSERT_FALSE(fb.BRAKECMD, 'Enable=FALSE : frein colle (BrakeCmd=FALSE) quelle que soit la demande de mouvement');
END_TEST

TEST 'Sequence ouverture : le frein ne s ouvre qu apres DelayMagnetise+DelayContactClose (400ms)'
    (* Bypass du controle contacteur : ce test se concentre sur le seul timing de magnetisation *)
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_FALSE(fb.BRAKECMD, 't=0 : magnetisation demarre, frein encore colle');
    ASSERT_EQ(fb.STATUS.STATE, E_STATE.BUSY, 'sequence en cours -> BUSY');

    ADVANCE_TIME(399000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_FALSE(fb.BRAKECMD, 't=399ms < 400ms requis : toujours colle');

    ADVANCE_TIME(2000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.BRAKECMD, 't=401ms >= 400ms : magnetisation acquise, frein relache');
    ASSERT_EQ(fb.STATUS.STATE, E_STATE.DONE, 'sequence terminee -> DONE');
    ASSERT_TRUE(fb.BRAKECOMMANDOPENCONFIRMED, 'bypass actif : confirmation = image de BrakeCmd');
END_TEST

TEST 'Comportement actuel : fermeture immediate sans attendre DelayMotorDecel (TonDecel jamais cable)'
    (* A VERIFIER intentionnellement : DelayMotorDecel/TonDecel sont declares et documentes
       ("Delai deceleration avant collage frein") mais TonDecel.IN est TOUJOURS force a FALSE
       dans FB_Brake.st (§1/§3) -- aucune temporisation n est reellement appliquee avant que le
       frein ne colle. Ce test documente le comportement REEL actuel (immediat), pas une exigence
       validee -- a confirmer avec l utilisateur si une temporisation etait pourtant voulue. *)
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ADVANCE_TIME(401000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.BRAKECMD, 'precondition : frein ouvert');

    (* mouvement arrete : meme scan, frein colle instantanement -- DelayMotorDecel (500ms) ignore *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := FALSE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := TRUE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_FALSE(fb.BRAKECMD, 'MovementRequested retombe : frein colle DES CE SCAN, aucun delai observe');
    ASSERT_EQ(fb.STATUS.STATE, E_STATE.READY, 'retour a READY immediat');
END_TEST

TEST 'Double verification contacteur : StuckClosed si le retour ne confirme jamais l ouverture'
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ADVANCE_TIME(401000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.BRAKECMD, 'magnetisation acquise : commande ouverture emise (ContactorFeedback ne confirme pas encore)');

    (* 1s de plus (FeedbackTimeout) : le retour n a jamais confirme -> defaut *)
    ADVANCE_TIME(1000000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.CONTACTORCHECK.STUCKCLOSED, 'commande ouverture emise mais jamais confirmee -> StuckClosed');
    ASSERT_TRUE(fb.STATUS.ERROR, 'defaut visible sur Status.Error');
    ASSERT_EQ(fb.STATUS.ERRORID, 16#0001, 'bit0 : incoherence retour contacteur');
    ASSERT_FALSE(fb.BRAKECMD, 'sortie sure sur defaut : BrakeCmd force a FALSE malgre la sequence terminee');
END_TEST

TEST 'Reset n acquitte le defaut contacteur que si la cause (retour) a reellement disparu'
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ADVANCE_TIME(401000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ADVANCE_TIME(1000000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := FALSE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.STATUS.ERROR, 'precondition : defaut StuckClosed actif');

    (* la cause disparait (le retour confirme enfin), mais SANS Reset : le defaut reste affiche *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := TRUE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_TRUE(fb.STATUS.ERROR, 'cause disparue mais pas acquittee : le defaut reste affiche (pas d auto-effacement)');

    (* front Reset, cause deja disparue : acquitte *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := TRUE, MOVEMENTREQUESTED := TRUE,
       CONTACTORFEEDBACK := TRUE, BYPASSCONTACTORCHECK := FALSE,
       DELAYCONTACTCLOSE := T#100MS, DELAYMAGNETISE := T#300MS,
       DELAYMOTORDECEL := T#500MS, FEEDBACKTIMEOUT := T#1S);
    ASSERT_FALSE(fb.STATUS.ERROR, 'Reset avec cause disparue (retour coherent) : defaut acquitte');
    ASSERT_TRUE(fb.BRAKECMD, 'plus de defaut : frein a nouveau relache (mouvement toujours demande)');
END_TEST

(* ═══════════════════════════════════════════════════════════════
   ↔️ PRG_05_Translation — Pilotage de la Translation M3
   ───────────────────────────────────────────────────────────────
   ⚙️ Exécuté par la tâche PLC en position 5 (après PRG_04_Treuils_Benne).
   ✅ Arbitre entre les commandes Manuelles (Joystick) et Automatiques (PRG_03_Modes_Cycle).
   📄 Docs : DOC/AF_Partie-11_Fonction_Translation_v2.1.md
   🛡️ Sécurité : instSafetyTranslationM3 (FB_Safety_Translation) câblée en parallèle
      de instTranslationM3 depuis le 2026-08-05 (lot M4) — SafeStop/PowerCutOff réels.
   ═══════════════════════════════════════════════════════════════ *)

PROGRAM PRG_05_Translation

VAR_OUTPUT
    TranslationFinalInterlockRequest : ST_TranslationFinalInterlockRequest;
    TranslationStateHMI : ST_TranslationState;
    TranslationSafetyHMI : ST_SafetyTranslation;
END_VAR

VAR
    instTranslationM3           : FB_Translation;
    instSafetyTranslationM3     : FB_Safety_Translation;
    instPosEstimatorM3          : FB_Translation_PositionEstimator;

    M3_StartStop_Active     : BOOL;
    M3_Direction_Active     : INT;
    M3_SpeedRef_Active      : REAL;
    M3_PositioningActive    : BOOL;
    M3_PositionSensorTarget : BOOL;

    SelTarget       : INT;
    FreqPct                 : REAL;

    M3_SafeStop_Active      : BOOL; // Cause historique : InputModuleFault (AF06 §3bis)
    M3_SafeStop_Aggregate   : BOOL; // 🛡️ SafeStop réellement appliqué au mouvement = InputModuleFault OR safety M3 (8 mécanismes)

    M3_HeightInterlockOk    : BOOL; // 🆕 2026-08-06 : TRUE = M1 ET M2 au-dessus de la hauteur mini (ou bypass actif)
    M3_LimitSwitchRevEffective : BOOL; // 🆕 2026-08-06 : coupure dure §5bis — bascule sur P1 si Maintenance interdite
    M3_LimitSwitchFwdStable : BOOL; // 🆕 2026-08-06 : verrou bistable Fdc Trémie (mémorisé stable contre les rebonds)
    M3_LimitSwitchRevStable : BOOL; // 🆕 2026-08-06 : verrou bistable Fdc Maintenance/P1 (mémorisé stable contre les rebonds)

    // 🆕 2026-08-06 : verrous bistables des positions cibles (§0quater) — PositionDecoder n'émet
    // plus qu'un front transitoire par capteur (REX décalage came), mémorisé ici jusqu'à dégagement.
    M3_AtTremieStable      : BOOL;
    M3_AtPVStable          : BOOL;
    M3_AtP2Stable          : BOOL;
    M3_AtP1Stable          : BOOL;
    M3_AtMaintenanceStable : BOOL;

    // 🆕 2026-08-06 (retour terrain, design opérateur) : libération du verrou §0quater sur
    // MOUVEMENT CONFIRMÉ soutenu (fréquence réelle mesurée, pas juste une consigne de sens),
    // pendant une durée mini avant de considérer qu'on a vraiment quitté le point — pas un
    // changement de sens instantané (perdu à cause d'InvertDirection) ni un timer fixe
    // indépendant du mouvement réel (rebond capteur mal filtré).
    TonM3ConfirmedMoving : TON;
    M3_ConfirmedMoving   : BOOL;
END_VAR

// === 🚧 §0 INTERLOCK HAUTEUR M1/M2 (retour terrain, risque collision translation) ===
// PRG_02_Acquisition s'exécute avant ce POU dans la MainTask (rang 01 < 05) : lecture
// du même scan, aucun retard. Bypass = maintenance consciente, doctrine ST_BypassTranslation.
// ⚠️ Revue 2026-08-06 : une position encodeur incohérente (hors plage OU homing suspect,
// FB_Encoder_Safety) ne doit PAS pouvoir se lire comme "≥ seuil" par accident — fail-safe :
// hauteur non confirmée = interlock actif (comme une hauteur insuffisante), sauf bypass.
// 🔒 Décision 2026-08-06 : Bypass.Global NE lève PLUS cet interlock (contrairement aux autres
// causes de l'axe M3) — risque de collision jugé trop grave pour être levé par un bypass
// générique. Seul Bypass.MinHeight (dédié, conscient) lève l'anti-collision hauteur.
M3_HeightInterlockOk := GVL_IHM.TranslationM3.Bypass.MinHeight
                        OR (NOT PRG_02_Acquisition.M1_EncoderIncoherent
                            AND NOT PRG_02_Acquisition.M2_EncoderIncoherent
                            AND (PRG_02_Acquisition.CablePosM1 >= GVL_PERSISTENT._TranslationMinHeightM1M2_M)
                            AND (PRG_02_Acquisition.CablePosM2 >= GVL_PERSISTENT._TranslationMinHeightM1M2_M));
TranslationStateHMI.HeightInterlockBlocking := NOT M3_HeightInterlockOk;

// === 🚧 §0bis COUPURE DURE (LimitSwitchRev) — bascule sur P1 si Maintenance interdite ===
// 🆕 2026-08-06 (retour terrain) : LimitSwitchFwd/Rev protègent nativement Trémie/Maintenance
// (§5bis FB_Translation : coupure immédiate, sans rampe, dès que CommandedDirection insiste
// dans l'extrémité). P1/P2 n'ont aucune protection dure équivalente — seul le verrou souple
// (arrival-lock) les couvre. Quand Maintenance est interdite, la coupure dure doit protéger
// P1 comme si c'était l'extrémité réelle : mot 00001 (P1=0 ET Maintenance=1), UN CRAN AVANT
// la vraie extrémité Maintenance (00000) — backup si le verrou souple a déjà échoué à arrêter
// avant P1, garde la machine hors de la zone interdite plutôt que d'attendre le vrai fond.
M3_LimitSwitchRevEffective := SEL(PRG_03_Modes_Cycle.Auth.MaintenanceM3TargetEnable,
                                   NOT PRG_02_Acquisition.TranslationPosP1 AND PRG_02_Acquisition.TranslationPosMaintenance,
                                   PRG_02_Acquisition.M3_LimitSwitchRev);

// 🔒 §0ter STABILISATION BISTABLE FINS DE COURSE EXTRÊMES (Trémie & Maintenance/P1)
// Maintient la détection stable à 1 même si le capteur physique vibre ou saute brièvement.
// Se libère uniquement sur un mouvement effectif dans le SENS INVERSE (dégagement).
IF PRG_02_Acquisition.M3_LimitSwitchFwd THEN
    M3_LimitSwitchFwdStable := TRUE;
ELSIF M3_Direction_Active = -1 THEN
    M3_LimitSwitchFwdStable := FALSE;
END_IF;

IF M3_LimitSwitchRevEffective THEN
    M3_LimitSwitchRevStable := TRUE;
ELSIF M3_Direction_Active = 1 OR (PRG_03_Modes_Cycle.Auth.MaintenanceM3TargetEnable AND NOT PRG_02_Acquisition.M3_LimitSwitchRev) THEN
    M3_LimitSwitchRevStable := FALSE;
END_IF;

// 🔒 §0quater MÉMORISATION DU DERNIER POINT ATTEINT (front → jeton unique, retour terrain)
// PositionDecoder n'émet qu'un front transitoire (1 cycle) par capteur, montant OU descendant
// SELON LE SENS (REX décalage came, voir FB_Translation_PositionDecoder.st) — mémorisé ici pour
// tenir le niveau nécessaire au débounce (100ms) + verrou anti-rebond (§4ter DirectionAtArrival)
// de FB_Translation, et pour l'affichage IHM. MUTUELLEMENT EXCLUSIFS : un nouveau front RAZ tous
// les autres (jeton "dernier point franchi" unique). 🆕 2026-08-06 (design opérateur) : libéré
// (RAZ complet) UNIQUEMENT sur mouvement CONFIRMÉ (fréquence réelle mesurée, pas juste la consigne
// de sens) soutenu ≥1.5s — pas un rebond capteur ni un changement de sens instantané.
M3_ConfirmedMoving := (UINT_TO_REAL(PRG_02_Acquisition.M3_ActualFrequencyHz_Filtered) / 100.0) > 0.5;
TonM3ConfirmedMoving(IN := M3_ConfirmedMoving, PT := T#1s500ms);

IF PRG_02_Acquisition.TranslationAtTremie THEN
    M3_AtTremieStable := TRUE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF PRG_02_Acquisition.TranslationAtPV THEN
    M3_AtPVStable := TRUE; M3_AtTremieStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF PRG_02_Acquisition.TranslationAtP2 THEN
    M3_AtP2Stable := TRUE; M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF PRG_02_Acquisition.TranslationAtP1 THEN
    M3_AtP1Stable := TRUE; M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF PRG_02_Acquisition.TranslationAtMaintenance THEN
    M3_AtMaintenanceStable := TRUE; M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE;
ELSIF TonM3ConfirmedMoving.Q THEN
    // Mouvement réel confirmé ≥1.5s sans nouveau front : on a vraiment quitté le dernier point.
    M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
END_IF;

// === 🔀 §1 ARBITRAGE DU SÉLECTEUR DE CIBLE ET DE LA DIRECTION ===

IF PRG_03_Modes_Cycle.Auth.Mode = E_Mode.SEMI_AUTO THEN
    // ⚠️ T106 : SelTarget forcé à 0 et jamais réarbitré par un séquenceur (FB_Cycle n'est pas
    // instancié — audit M3 2026-08-05) → M3_StartStop_Active reste FALSE en pratique. Le
    // AND PRG_02_Acquisition.JoystickDeadmanArmed exigé par AF08 §6 devra être ajouté ici
    // au moment où le cycle SEMI_AUTO M3 sera réellement câblé, pas avant (rien à protéger
    // aujourd'hui, ne pas figer une condition sur du code mort).
    M3_PositioningActive  := TRUE;
    SelTarget    := 0;
    M3_StartStop_Active  := FALSE;
    M3_SpeedRef_Active   := 0.0;

    IF SelTarget = 1 THEN
        M3_Direction_Active := 1;
    ELSE
        M3_Direction_Active := -1;
    END_IF;
ELSIF (PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N1)
   OR (PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N2) THEN
    M3_PositioningActive := GVL_IHM.TranslationM3.Cmd.SelPositioning;
    SelTarget := 0;

    IF NOT GVL_IHM.Modes.Cmd.TglJoystickMaster AND GVL_IHM.TranslationM3.Cmd.BtnFwd THEN
        M3_Direction_Active := 1;
    ELSIF NOT GVL_IHM.Modes.Cmd.TglJoystickMaster AND GVL_IHM.TranslationM3.Cmd.BtnRev THEN
        M3_Direction_Active := -1;
    ELSIF GVL_IHM.Modes.Cmd.TglJoystickMaster THEN
        M3_Direction_Active := PRG_02_Acquisition.JoystickDirectionX;
    ELSE
        M3_Direction_Active := 0;
    END_IF;

    // 🔫 T106 (audit M3 2026-08-05) : homme-mort exigé même pour boutons IHM en MAINT_N1/N2
    // (AF_Partie-08 §6, AF_Partie-11 §4.2) — pas seulement pour un pilotage joystick réel.
    // 🔀 2026-08-06 : TglJoystickMaster consolidé — un seul switch machine (GVL_IHM.Modes.Cmd),
    // plus de doublon par axe (ex GVL_IHM.TranslationM3.Cmd.TglJoystickMaster, supprimé).
    M3_StartStop_Active := (M3_Direction_Active <> 0)
                           AND (GVL_IHM.TranslationM3.Bypass.Global
                                OR NOT GVL_IHM.Modes.Cmd.TglJoystickMaster
                                OR GVL_IHM.Modes.Cmd.TglJoystickMaster)
                           AND PRG_02_Acquisition.JoystickDeadmanArmed
                           AND M3_HeightInterlockOk; // 🆕 2026-08-06 : hauteur mini M1/M2 (risque collision)

    FreqPct := SEL(GVL_IHM.TranslationM3.Cmd.SetFreq_Hz > 0.0,
                  100.0,
                  (GVL_IHM.TranslationM3.Cmd.SetFreq_Hz / SEL(GVL_PERSISTENT._TranslationMaxFreq_Hz > 0.0, 50.0, GVL_PERSISTENT._TranslationMaxFreq_Hz)) * 100.0);
    // 🕹️ Si TglJoystickMaster (global) = TRUE, le manche (0..100%) est mis à l'échelle sur la consigne SetFreq_Hz (ou 100% si non renseignée).
    M3_SpeedRef_Active := SEL(GVL_IHM.Modes.Cmd.TglJoystickMaster,
                              FreqPct,
                              (PRG_02_Acquisition.JoystickSpeedPctX / 100.0) * FreqPct);
ELSE
    M3_PositioningActive := FALSE;
    SelTarget    := 0;
    M3_StartStop_Active  := FALSE;
    M3_Direction_Active  := 0;
    M3_SpeedRef_Active   := 0.0;
END_IF;

// 🆕 2026-08-06 (retour terrain, REX câblage) : InvertDirection NE s'applique PLUS ici. Appliqué
// en amont sur M3_Direction_Active, il désaccordait TOUTE la logique sécurité/ralentissement
// appariée aux vrais capteurs physiques (LimitSwitchFwd/Rev, SlowdownSensorXxx, verrous §0quater)
// dès que le câblage moteur réel l'exigeait à TRUE — seule la coupure dure indépendante du sens
// (§0bis) arrêtait encore la machine, le verrou d'arrivée logiciel ne s'armait jamais. Compensation
// déplacée dans FB_Translation (InvertDriveDirection), appliquée UNIQUEMENT au mot de commande
// variateur en sortie — M3_Direction_Active reste partout le sens sémantique réel.

M3_SpeedRef_Active := LIMIT(0.0, ABS(M3_SpeedRef_Active), 100.0);

IF (SelTarget = 4) AND NOT PRG_03_Modes_Cycle.Auth.MaintenanceM3TargetEnable THEN
    SelTarget := 0;
END_IF;

// 🩺 InputModuleFault (AF06 §3bis) : un module DI TOR hors service rend indisponibles
// les retours frein/thermique/positions du VH_0808ETP/VH_0800END portant M3 — rampe rapide.
M3_SafeStop_Active := PRG_02_Acquisition.InputModuleFault;

// 🆕 2026-08-06 (retour terrain, anti-rebond arrêt) : SelTarget reste à 0 en mode manuel
// (MAINT_N1/N2, T106 — aucun séquenceur SEMI_AUTO ne le réarbitre à ce jour), donc la CASE
// ci-dessous tombait toujours en ELSE=FALSE et le verrou anti-rebond §4ter de FB_Translation
// (DirectionAtArrival) ne s'armait jamais en usage réel. Repli explicite hors sélection
// SEMI_AUTO : n'importe quel des 3 points d'arrêt (Trémie/P1/Maintenance) arme le verrou.
// 🆕 2026-08-06 : mot EXACT (TranslationAtXxx), pas le cumulatif (TranslationPosXxx) — front
// franc à l'arrivée quel que soit le sens de venue (voir FB_Translation_PositionDecoder.st).
CASE SelTarget OF
    1: M3_PositionSensorTarget := M3_AtTremieStable;
    2: M3_PositionSensorTarget := M3_AtP2Stable;
    3: M3_PositionSensorTarget := M3_AtP1Stable;
    4: M3_PositionSensorTarget := M3_AtMaintenanceStable;
ELSE
    IF M3_Direction_Active = 1 THEN
        // En Marche Avant (+1 vers Trémie) : seule Trémie est le point d'arrêt automatique
        M3_PositionSensorTarget := M3_AtTremieStable;
    ELSIF M3_Direction_Active = -1 THEN
        // En Marche Arrière (-1 vers Maintenance) :
        // - Si Maintenance autorisée -> arrêt sur Maintenance
        // - Si Maintenance interdite -> arrêt sur P1
        // 🆕 2026-08-06 : réactivé — le retrait d'urgence précédent était dû à AtP1 armé sur le
        // front du capteur P2 (zone d'approche) au lieu du capteur P1 lui-même (franchissement
        // réel du point). Corrigé dans FB_Translation_PositionDecoder.st (front du capteur propre).
        IF PRG_03_Modes_Cycle.Auth.MaintenanceM3TargetEnable THEN
            M3_PositionSensorTarget := M3_AtMaintenanceStable;
        ELSE
            M3_PositionSensorTarget := M3_AtP1Stable;
        END_IF;
    ELSE
        M3_PositionSensorTarget := FALSE;
    END_IF;
END_CASE;


// === 🛡️ §1bis SÉCURITÉ M3 (FB_Safety_Translation, câblée en parallèle visible) ===
// ⚠️ Ordre d'appel volontaire : la safety lit ici le BrakeReleaseRequest et le
// BrakeCmd du SCAN PRÉCÉDENT d'instTranslationM3 (elle est appelée avant), exactement
// le même retard d'un scan que documenté en AF_Partie-11 §5 alerte 4 pour l'ancien
// code CFC — non éliminé par ce lot (nécessite la fusion CFC complète, lot M4 migration
// 7 POU, hors périmètre). Bénin : BrakeReleaseRequest ne change pas plus vite qu'un
// scan MainTask 10 ms sur une commande frein.
instSafetyTranslationM3(
    Enable                  := (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.DISABLE),
    Reset                   := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                    := PRG_03_Modes_Cycle.Auth.Mode,
    JoystickOnline          := PRG_07_Supervision.instDiagCanOpen.DeviceJoystick.Online,
    JoystickOperational     := PRG_07_Supervision.instDiagCanOpen.DeviceJoystick.Operational,
    HeartbeatIhmOk          := GVL_IHM.Commun.HeartbeatIhmOk,
    PhaseRotationOk         := PRG_02_Acquisition.HwIn.Machine.PhaseRotationOk_DI,
    BrakeThermalFeedback    := NOT PRG_02_Acquisition.HwIn.Machine.BrakeThermalOk_DI,
    DriveOnline             := PRG_07_Supervision.instDiagEthercat.DeviceVariateur.Online,
    DriveOperational        := PRG_07_Supervision.instDiagEthercat.DeviceVariateur.Operational,
    DriveStatusWord         := PRG_02_Acquisition.M3_StatusWord_Filtered,
    DriveActualFreqHz       := UINT_TO_REAL(PRG_02_Acquisition.M3_ActualFrequencyHz_Filtered) / 100.0,
    BrakeFeedback           := SEL(GVL_IHM.TranslationM3.Bypass.ContactorFeedback OR GVL_IHM.TranslationM3.Bypass.Global, PRG_02_Acquisition.HwIn.Translation.M3_BrakeIsOpen_DI, instTranslationM3.BrakeReleaseRequest),
    BrakeCmd                := instTranslationM3.BrakeReleaseRequest,
    Direction               := M3_Direction_Active,
    LimitSwitchFwd          := M3_LimitSwitchFwdStable,
    LimitSwitchRev          := M3_LimitSwitchRevStable,
    SensorWordIncoherent    := PRG_02_Acquisition.M3_SensorWordIncoherent,
    BypassGlobal            := GVL_IHM.TranslationM3.Bypass.Global,
    BypassOperatorComm      := GVL_IHM.TranslationM3.Bypass.OperatorComm,
    BypassDriveComm         := GVL_IHM.TranslationM3.Bypass.DriveComm,
    BypassPhaseRotation     := GVL_IHM.TranslationM3.Bypass.PhaseRotation,
    BypassBrakeThermal      := GVL_IHM.TranslationM3.Bypass.BrakeThermal,
    BypassMecaB             := GVL_IHM.TranslationM3.Bypass.MecaB,
    BypassMecaA             := GVL_IHM.TranslationM3.Bypass.MecaA,
    BypassLimitSwitch       := GVL_IHM.TranslationM3.Bypass.LimitSwitch,
    BypassSensorIncoherent  := GVL_IHM.TranslationM3.Bypass.SensorIncoherent,
    BypassSafety            := GVL_IHM.TranslationM3.Bypass.Safety,
    BypassProcess           := GVL_IHM.TranslationM3.Bypass.Process
);

// SafeStop réellement appliqué au mouvement = agrégat InputModuleFault (historique)
// OR safety M3 (8 mécanismes) — aucune des deux causes ne doit être perdue.
M3_SafeStop_Aggregate := M3_SafeStop_Active OR instSafetyTranslationM3.SafeStop;

// === ⚙️ §2 EXÉCUTION PILOTAGE TRANSLATION M3 ===

instTranslationM3(
    Enable                  := (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.DISABLE),
    Reset                   := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                    := PRG_03_Modes_Cycle.Auth.Mode,
    StartStop               := M3_StartStop_Active,
    SafeStop                := M3_SafeStop_Aggregate,
    Direction               := M3_Direction_Active,
    InvertDriveDirection    := GVL_IHM.TranslationM3.Cmd.InvertDirection,
    SpeedRefPct             := M3_SpeedRef_Active,
    PositionSensorTarget    := M3_PositionSensorTarget,
    SlowdownSensorTremie       := PRG_02_Acquisition.TranslationPosPV,
    // 🆕 2026-08-06 (retour terrain, URGENT, correction d'une erreur de calcul du commit précédent) :
    // les 5 capteurs forment un code thermomètre cumulatif depuis la Trémie (voir
    // FB_Translation_PositionDecoder.st). Chaque zone est délimitée par "capteur PRÉCÉDENT retombé
    // à 0" ET "capteur de la zone encore à 1" — zone P2→P1 = NOT PosP2 AND PosP1 (mot 00011) ;
    // zone P1→Maintenance = NOT PosP1 AND PosMaintenance (mot 00001). Zones mutuellement exclusives,
    // chacune sa propre vitesse d'approche (CfgApproachSpeedP1_Hz / CfgApproachSpeedMaintenance_Hz).
    SlowdownSensorMaintenance  := (NOT PRG_02_Acquisition.TranslationPosP1) AND PRG_02_Acquisition.TranslationPosMaintenance,
    // 🆕 2026-08-06 (design opérateur) : ralentissement P2→P1 UNIQUEMENT si P1 est un vrai point
    // d'arrêt (zone Maintenance NON autorisée). Zone Maintenance autorisée -> 100% vitesse jusqu'à
    // P1, ralentissement seulement après (zone P1→Maintenance, SlowdownSensorMaintenance ci-dessus).
    SlowdownSensorP1           := (NOT PRG_02_Acquisition.TranslationPosP2) AND PRG_02_Acquisition.TranslationPosP1
                                   AND NOT PRG_03_Modes_Cycle.Auth.MaintenanceM3TargetEnable,
    LimitSwitchFwd          := M3_LimitSwitchFwdStable,
    LimitSwitchRev          := M3_LimitSwitchRevStable,
    DriveStatusWord         := PRG_02_Acquisition.M3_StatusWord_Filtered,
    DriveActualFreqHz       := UINT_TO_REAL(PRG_02_Acquisition.M3_ActualFrequencyHz_Filtered) / 100.0,
    CfgRampAccelRate        := _TranslationRampAccelRate_Pct,
    CfgRampDecelNormalRate  := _TranslationRampDecelNormal_Pct,
    CfgRampDecelFastRate    := _TranslationRampDecelFast_Pct,
    ApproachSpeedTremieHz       := GVL_IHM.TranslationM3.Cfg.CfgApproachSpeedTremie_Hz,
    ApproachSpeedMaintenanceHz  := GVL_IHM.TranslationM3.Cfg.CfgApproachSpeedMaintenance_Hz,
    ApproachSpeedP1Hz           := GVL_IHM.TranslationM3.Cfg.CfgApproachSpeedP1_Hz,
    DriveFreqScaleMaxHz     := _TranslationMaxFreq_Hz,
    BrakeFeedback           := SEL(GVL_IHM.TranslationM3.Bypass.ContactorFeedback OR GVL_IHM.TranslationM3.Bypass.Global, PRG_02_Acquisition.HwIn.Translation.M3_BrakeIsOpen_DI, instTranslationM3.BrakeReleaseRequest),
    BypassContactorCheck    := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.ContactorFeedback,
    BypassLimitSwitch       := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.LimitSwitch
);

// 📐 Estimateur de position continue M3 (odométrie + recalage 5 capteurs)
instPosEstimatorM3(
    Enable               := (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.DISABLE),
    Reset                := PRG_07_Supervision.FaultMachineReset_IHM,
    DriveActualFreqHz    := TO_REAL(PRG_02_Acquisition.M3_ActualFrequencyHz_Filtered) / 100.0,
    Direction            := M3_Direction_Active,
    SensorMaintenance    := PRG_02_Acquisition.TranslationPosMaintenance,
    SensorP1             := PRG_02_Acquisition.TranslationPosP1,
    SensorP2             := PRG_02_Acquisition.TranslationPosP2,
    SensorPV             := PRG_02_Acquisition.TranslationPosPV,
    SensorTremie         := PRG_02_Acquisition.TranslationPosTremie,
    PosMaintenanceM      := GVL_PERSISTENT._TranslationPosMaintenance_M,
    PosP1M               := GVL_PERSISTENT._TranslationPosP1_M,
    PosP2M               := GVL_PERSISTENT._TranslationPosP2_M,
    PosPVM               := GVL_PERSISTENT._TranslationPosPV_M,
    PosTremieM           := GVL_PERSISTENT._TranslationPosTremie_M,
    GainMetersPerHzSec   := GVL_PERSISTENT._TranslationGainMetersPerHzSec,
    PersistedPositionM   := GVL_PERSISTENT._TranslationPosEstimated_M,
    PersistedInitialized := GVL_PERSISTENT._TranslationPosEstimatedInitialized
);
// 🆕 Recopie continue (reprise après reboot, doctrine _TranslationSetFreq_Hz) — pas de bridge dédié.
GVL_PERSISTENT._TranslationPosEstimated_M := instPosEstimatorM3.PositionEstimatedM;
GVL_PERSISTENT._TranslationPosEstimatedInitialized := instPosEstimatorM3.Initialized;


// === 📤 §3 PUBLICATION DEMANDE BRUTE TRANSLATION ===

TranslationFinalInterlockRequest.Enable := (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.DISABLE);
TranslationFinalInterlockRequest.Reset := PRG_07_Supervision.FaultMachineReset_IHM;
TranslationFinalInterlockRequest.PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI;
TranslationFinalInterlockRequest.SafeStop := M3_SafeStop_Aggregate;
TranslationFinalInterlockRequest.PowerCutOff := instSafetyTranslationM3.PowerCutOff;
TranslationFinalInterlockRequest.BrakeReleaseRequest := instTranslationM3.BrakeReleaseRequest;
TranslationFinalInterlockRequest.BrakeCommandOpenConfirmed := instTranslationM3.BrakeCommandOpenConfirmed;
TranslationFinalInterlockRequest.RequestedDriveControlWord := instTranslationM3.RequestedDriveControlWord;
TranslationFinalInterlockRequest.RequestedDriveFreqHz := instTranslationM3.RequestedDriveFreqHz;

