WinchM2SafetyHMI.ForbidAscent := ForbidAscentM2_Active;
WinchM2SafetyHMI.ForbidDescent := ForbidDescentM2_Active;
WinchM2SafetyHMI.SlackCable := NOT PRG_02_Acquisition.HwIn.Winch.M2_TensionedCable_DI;
WinchM2SafetyHMI.ThermalFault := NOT PRG_02_Acquisition.HwIn.Winch.M2_ThermalOk_DI;
WinchM2SafetyHMI.PowerCutOff := instSafetyWinchM2.PowerCutOff;
WinchM2SafetyHMI.BrakeTimeoutFault := (PRG_06_Outputs_LD.instWinchOutputInterlockM2.ErrorId AND 16#0001) <> 0;
WinchM2SafetyHMI.CableOutOfBoundsFault := (PRG_02_Acquisition.instEncoderSafetyM2.ErrorId AND 16#0001) <> 0;
WinchM2SafetyHMI.Error := instWinchM2.Error OR instSafetyWinchM2.Error;
WinchM2SafetyHMI.ErrorId := instWinchM2.ErrorId;

SyncStateHMI.DeltaPos_M := instWinchSync.SignedDeltaPosM;
SyncStateHMI.SyncActive := instWinchSync.SyncActive;
SyncStateHMI.SyncWarn := instWinchSync.SyncWarn;
SyncStateHMI.Ready := instWinchSync.Ready;
SyncStateHMI.Error := instWinchSync.Error;
SyncStateHMI.ErrorId := instWinchSync.ErrorId;
SyncStateHMI.FBState := instWinchSync.State;

BucketStateHMI.MechState := _BucketState;
BucketStateHMI.FBState := instBucket.State;
BucketStateHMI.ActiveOffset_M := instBucket.ActiveOffsetM;
BucketStateHMI.M2StartStop := instBucket.M2_StartStop;
BucketStateHMI.M2Direction := instBucket.M2_Direction;
BucketStateHMI.M2ForceSlowSpeed := instBucket.M2_ForceSlowSpeed;
BucketStateHMI.M2PositionCorrected := PRG_02_Acquisition.CablePosM2 - instBucket.ActiveOffsetM;
BucketStateHMI.Ready := instBucket.Ready;
BucketStateHMI.Busy := instBucket.Busy;
BucketStateHMI.Done := instBucket.Done;
BucketStateHMI.Error := instBucket.Error;
BucketStateHMI.ErrorId := instBucket.ErrorId;
BucketStateHMI.RemainingTravel_M := instBucket.RemainingTravelM;
BucketStateHMI.CloseActive := instBucket.CloseReq;
BucketStateHMI.OpenActive := instBucket.OpenReq;
// 🔧 2026-08-07 : corrigé -- pointait sur DumpAtTremieBucketOpenArmed (mauvais signal, deviné
// par l'agent Fiche 02 avant que la Fiche 01 ne soit committée). Reflète maintenant le vrai
// séquencement auto Fiche 01 : occupé sur une ouverture/fermeture qu'IL a armée, ou en phase
// vitesse contrôlée post-fermeture.
BucketStateHMI.AutoBucketSeqActive := (instBucket.Busy AND (CoupledDiveBucketOpenArmed OR CoupledAscentBucketCloseArmed)) OR ControlAscentActive;
BucketStateHMI.CoupledDiveOpenArmed := CoupledDiveBucketOpenArmed;
BucketStateHMI.CoupledAscentCloseArmed := CoupledAscentBucketCloseArmed;
BucketStateHMI.ControlAscentActive := ControlAscentActive;
BucketStateHMI.CoupledMotionBlockedByBucket := CoupledMotionBlockedByBucket;
GVL_IHM.Commun.KoboldImmersionConfirmed := KoboldImmersionConfirmed;
GVL_IHM.Commun.KoboldBottomTouchLatched := KoboldBottomTouchLatched;

END_PROGRAM

FUNCTION_BLOCK PUBLIC FB_PLC_Tests_Management
VAR_INPUT
    instBucket                : REFERENCE TO FB_Bucket;     // 🆕 Instance benne (pour FB_BucketValidation)
    instWinchM2               : REFERENCE TO FB_Winch;      // 🆕 Instance treuil M2 (pour FB_BucketValidation)
END_VAR
VAR
    // 🧱 Instances de test (1 par suite — ajouter une suite = 1 instance + 1 branche CASE,
    // voir AF_Partie-14 §7.3.4)
    instSafetyValidation      : FB_SafetyValidation;
    instTranslationValidation : FB_TranslationValidation;
    instBucketValidation      : FB_BucketValidation;
    instEncoderValidation     : FB_EncoderValidation;
    instModesValidation       : FB_ModesValidation;
    instHeartbeatValidation   : FB_HeartbeatValidation;
    instSupervisionValidation : FB_SupervisionValidation;

    // Triggers pour IHM tactiles
    RunAllTrig           : R_TRIG;
    AbortTrig            : R_TRIG;
    ClearReportTrig      : R_TRIG;

    // Variables de commande internes
    StartSafety          : BOOL;
    AbortSafety          : BOOL;
    RequestedCaseSafety  : INT;
    StartTranslation     : BOOL;
    AbortTranslation     : BOOL;
    RequestedCaseTranslation : INT; // 🆕 2026-07-22 : CaseId direct (0=toutes,1..6) — JAMAIS de FirstStepId (audit v1.0 C2)
    StartBucket           : BOOL;
    AbortBucket           : BOOL;
    RequestedCaseBucket   : INT;
    StartEncoder          : BOOL;
    AbortEncoder          : BOOL;
    RequestedCaseEncoder  : INT;
    StartModes            : BOOL;
    AbortModes            : BOOL;
    RequestedCaseModes    : INT;
    StartHeartbeat        : BOOL;
    AbortHeartbeat        : BOOL;
    RequestedCaseHeartbeat : INT;
    StartSupervision       : BOOL;
    AbortSupervision       : BOOL;
    RequestedCaseSupervision : INT;
    StartFramework        : BOOL;
    FrameworkScanCount    : INT;

    // 🔗 Enchaînement multi-suites (CmdRunAll) — 2026-07-16 : ajout Translation puis Bucket
    ChainMode            : BOOL;  // TRUE = run déclenché par RunAll, enchaîne Safety PUIS Translation PUIS Bucket
    CurrentSuiteIdx      : INT;   // Suite active/dernière active (GVL_PLC_Tests_Const.SuiteSafety/SuiteTranslation/SuiteBucket)
    FinalAborted         : BOOL;
    FinalAnyFailed       : BOOL;
    SuiteElapsed         : TIME;
    SuiteWatchdogExpired : BOOL;
    LastLoggedSafetyRun  : UDINT;
    LastLoggedTranslationRun : UDINT;
    LastLoggedBucketRun  : UDINT;
    LastLoggedHeartbeatRun : UDINT;
    LastLoggedSupervisionRun : UDINT;
    EventIdx             : INT;

    // Compteurs pour progression IHM
    Idx                  : INT;
    PassedCount          : INT;
    FailedCount          : INT;
    TotalCount           : INT;

    // 💓 Gestion du clignotant HMI
    LastStepId           : INT := 0;
    PulseCounter         : INT := 0;
    CycleCounter         : INT := 0;
END_VAR
// === IMPLEMENTATION ===
// 1. Détection des commandes HMI
RunAllTrig(CLK := GVL_PLC_Tests.Cmd.RunAll);
AbortTrig(CLK := GVL_PLC_Tests.Cmd.Abort);
ClearReportTrig(CLK := GVL_PLC_Tests.Cmd.ClearReport);

// Remise à zéro des boutons poussoirs HMI
// 🔧 REX 2026-07-16 (demande utilisateur) : CmdRunAll n'est PAS remis à FALSE ici (contrairement
// à l'ancien CmdRunTests, pulse consommé au scan suivant) — il reste TRUE tout le temps du run,
// pratique pour observer en Watch/forçage CODESYS, et ne retombe qu'au Done (cf. CASE ci-dessous).
// R_TRIG garantit qu'un niveau maintenu ne redéclenche pas un 2e run.
IF GVL_PLC_Tests.Cmd.Abort THEN
    GVL_PLC_Tests.Cmd.Abort := FALSE;
END_IF;
IF GVL_PLC_Tests.Cmd.ClearReport THEN
    GVL_PLC_Tests.Cmd.ClearReport := FALSE;
END_IF;

// 2. Machine d'états principale
CASE GVL_PLC_Tests.Status.RunState OF

    // 🔧 REX 2026-07-16 (demande utilisateur) : PASSED/FAILED/ABORTED sont FIGÉS ici (pattern
    // StateAtError, P3 §4) — sans ça, l'état ne durait qu'1 scan (10ms) avant de retomber tout
    // seul à IDLE, invisible en Watch CODESYS. On ne quitte cet état que sur nouveau Start
    // (relance direct un run) ou CmdClearReport (acquittement explicite → retour IDLE).
    E_TestRunState.TESTRUN_IDLE, E_TestRunState.TESTRUN_PASSED, E_TestRunState.TESTRUN_FAILED, E_TestRunState.TESTRUN_ABORTED:
        StartSafety := FALSE;
        AbortSafety := FALSE;
        StartTranslation := FALSE;
        AbortTranslation := FALSE;
        StartBucket := FALSE;
        AbortBucket := FALSE;
        StartEncoder := FALSE;
        AbortEncoder := FALSE;
        StartModes := FALSE;
        AbortModes := FALSE;
        StartHeartbeat := FALSE;
        AbortHeartbeat := FALSE;
        StartSupervision := FALSE;
        AbortSupervision := FALSE;
        StartFramework := FALSE;
        SuiteElapsed := T#0s;
        SuiteWatchdogExpired := FALSE;

        // 🧪 RunAll prioritaire : démarre une campagne complète depuis Safety.
        IF RunAllTrig.Q THEN
            ChainMode := TRUE;
            CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteSafety;
            RequestedCaseSafety := 0;
            RequestedCaseTranslation := 0;
            RequestedCaseBucket := 0;
            RequestedCaseEncoder := 0;
            RequestedCaseModes := 0;
            RequestedCaseHeartbeat := 0;
            RequestedCaseSupervision := 0;
            FinalAborted := FALSE;
            FinalAnyFailed := FALSE;
            GVL_PLC_Tests.Cmd.RunSuite := 0;
            GVL_PLC_Tests.Cmd.RunCase := 0;
            GVL_PLC_Tests.Status.FailureSummary := '';
            StartSafety := TRUE;
            GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_RUNNING;
        // Normalisation des commandes unitaires vers RunSuite.
        ELSIF GVL_PLC_Tests.Cmd.RunSafety THEN
            GVL_PLC_Tests.Cmd.RunSuite := GVL_PLC_Tests_Const.SuiteSafety;
            GVL_PLC_Tests.Cmd.RunSafety := FALSE;
        ELSIF GVL_PLC_Tests.Cmd.RunTranslation THEN
            GVL_PLC_Tests.Cmd.RunSuite := GVL_PLC_Tests_Const.SuiteTranslation;
            GVL_PLC_Tests.Cmd.RunTranslation := FALSE;
        ELSIF GVL_PLC_Tests.Cmd.RunBucket THEN
            GVL_PLC_Tests.Cmd.RunSuite := GVL_PLC_Tests_Const.SuiteBucket;
            GVL_PLC_Tests.Cmd.RunBucket := FALSE;
        ELSIF GVL_PLC_Tests.Cmd.RunEncoder THEN
            GVL_PLC_Tests.Cmd.RunSuite := GVL_PLC_Tests_Const.SuiteEncoder;
            GVL_PLC_Tests.Cmd.RunEncoder := FALSE;
        ELSIF GVL_PLC_Tests.Cmd.RunModes THEN
            GVL_PLC_Tests.Cmd.RunSuite := GVL_PLC_Tests_Const.SuiteModes;
            GVL_PLC_Tests.Cmd.RunModes := FALSE;
        ELSIF GVL_PLC_Tests.Cmd.RunHeartbeat THEN
            GVL_PLC_Tests.Cmd.RunSuite := GVL_PLC_Tests_Const.SuiteHeartbeat;
            GVL_PLC_Tests.Cmd.RunHeartbeat := FALSE;
        ELSIF GVL_PLC_Tests.Cmd.RunSupervision THEN
            GVL_PLC_Tests.Cmd.RunSuite := GVL_PLC_Tests_Const.SuiteSupervision;
            GVL_PLC_Tests.Cmd.RunSupervision := FALSE;
        ELSIF GVL_PLC_Tests.Cmd.RunFramework THEN
            StartFramework := TRUE;
            GVL_PLC_Tests.Cmd.RunFramework := FALSE;
        END_IF;

        // Démarrage d'une suite ciblée (Safety)
        IF GVL_PLC_Tests.Cmd.RunSuite = GVL_PLC_Tests_Const.SuiteSafety THEN
            IF GVL_Simulation.SimulationModeActive AND instSafetyValidation.SimGateOk THEN
                ChainMode := FALSE;
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteSafety;
                StartSafety := TRUE;
                RequestedCaseSafety := GVL_PLC_Tests.Cmd.RunCase;
                GVL_PLC_Tests.Status.FailureSummary := ''; // 🔄 RAZ à chaque nouveau run
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_RUNNING;
            END_IF;
            GVL_PLC_Tests.Cmd.RunSuite := 0;
            GVL_PLC_Tests.Cmd.RunCase := 0;

        // Démarrage d'une suite ciblée (Translation)
        // 🆕 2026-07-22 : CaseId transmis TEL QUEL (0=toutes,1..6) — le manager ne
        // connaît plus aucun détail interne d'étape (audit v1.0 C2). Refus de
        // gate désormais explicite PRECONDITION_FAILED, jamais silencieux (C3).
        ELSIF GVL_PLC_Tests.Cmd.RunSuite = GVL_PLC_Tests_Const.SuiteTranslation THEN
            // La suite possède seule sa fixture : même un refus produit un rapport neuf
            // PRECONDITION_FAILED, jamais un Status correct avec un ancien rapport.
            ChainMode := FALSE;
            CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteTranslation;
            StartTranslation := TRUE;
            RequestedCaseTranslation := GVL_PLC_Tests.Cmd.RunCase;
            GVL_PLC_Tests.Status.FailureSummary := '';
            GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_RUNNING;
            GVL_PLC_Tests.Cmd.RunSuite := 0;
            GVL_PLC_Tests.Cmd.RunCase := 0;

        // Démarrage d'une suite ciblée (Bucket)
        ELSIF GVL_PLC_Tests.Cmd.RunSuite = GVL_PLC_Tests_Const.SuiteBucket THEN
            IF GVL_Simulation.SimulationModeActive AND instBucketValidation.SimGateOk THEN
                ChainMode := FALSE;
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteBucket;
                StartBucket := TRUE;
                RequestedCaseBucket := GVL_PLC_Tests.Cmd.RunCase;
                GVL_PLC_Tests.Status.FailureSummary := ''; // 🔄 RAZ à chaque nouveau run
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_RUNNING;
            END_IF;
            GVL_PLC_Tests.Cmd.RunSuite := 0;
            GVL_PLC_Tests.Cmd.RunCase := 0;

        // Démarrage d'une suite ciblée (Codeurs/Homing nominal)
        ELSIF GVL_PLC_Tests.Cmd.RunSuite = GVL_PLC_Tests_Const.SuiteEncoder THEN
            IF GVL_Simulation.SimulationModeActive AND instEncoderValidation.SimGateOk THEN
                ChainMode := FALSE;
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteEncoder;
                StartEncoder := TRUE;
                RequestedCaseEncoder := GVL_PLC_Tests.Cmd.RunCase;
                GVL_PLC_Tests.Status.FailureSummary := '';
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_RUNNING;
            END_IF;
            GVL_PLC_Tests.Cmd.RunSuite := 0;
            GVL_PLC_Tests.Cmd.RunCase := 0;

        // Démarrage d'une suite ciblée (Modes/Homme-mort, post-suppression IHM_MANU)
        ELSIF GVL_PLC_Tests.Cmd.RunSuite = GVL_PLC_Tests_Const.SuiteModes THEN
            IF GVL_Simulation.SimulationModeActive AND instModesValidation.SimGateOk THEN
                ChainMode := FALSE;
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteModes;
                StartModes := TRUE;
                RequestedCaseModes := GVL_PLC_Tests.Cmd.RunCase;
                GVL_PLC_Tests.Status.FailureSummary := '';
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_RUNNING;
            END_IF;
            GVL_PLC_Tests.Cmd.RunSuite := 0;
            GVL_PLC_Tests.Cmd.RunCase := 0;

        // Démarrage suite Heartbeat IHM↔PLC.
        ELSIF GVL_PLC_Tests.Cmd.RunSuite = GVL_PLC_Tests_Const.SuiteHeartbeat THEN
            IF GVL_Simulation.SimulationModeActive
               AND NOT GVL_Simulation.SensorM1ContactorFeedbackIsReal
               AND NOT GVL_Simulation.SensorM2ContactorFeedbackIsReal THEN
                ChainMode := FALSE;
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteHeartbeat;
                StartHeartbeat := TRUE;
                RequestedCaseHeartbeat := GVL_PLC_Tests.Cmd.RunCase;
                GVL_PLC_Tests.Status.FailureSummary := '';
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_RUNNING;
            END_IF;
            GVL_PLC_Tests.Cmd.RunSuite := 0;
            GVL_PLC_Tests.Cmd.RunCase := 0;

        // Démarrage suite Supervision/Persistance config : autonome, sans simulation matérielle.
        ELSIF GVL_PLC_Tests.Cmd.RunSuite = GVL_PLC_Tests_Const.SuiteSupervision THEN
            ChainMode := FALSE;
            CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteSupervision;
            StartSupervision := TRUE;
            RequestedCaseSupervision := GVL_PLC_Tests.Cmd.RunCase;
            GVL_PLC_Tests.Status.FailureSummary := '';
            GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_RUNNING;
            GVL_PLC_Tests.Cmd.RunSuite := 0;
            GVL_PLC_Tests.Cmd.RunCase := 0;
        END_IF;

        // 🧪 Smoke test géré directement ici : aucune instance/table/runtime.
        IF StartFramework THEN
            ChainMode := FALSE;
            FrameworkScanCount := 0;
            GVL_PLC_Tests.FrameworkResult.InProgress := TRUE;
            GVL_PLC_Tests.FrameworkResult.AllPassed := FALSE;
            GVL_PLC_Tests.FrameworkResult.AnyFailed := FALSE;
            GVL_PLC_Tests.FrameworkResult.CurrentTestId := 1;
            GVL_PLC_Tests.FrameworkResult.FailedTestId := 0;
            GVL_PLC_Tests.FrameworkResult.TestsPassed := 0;
            GVL_PLC_Tests.FrameworkResult.TestsFailed := 0;
            GVL_PLC_Tests.FrameworkResult.ErrorMessage := '';
            GVL_PLC_Tests.FrameworkResult.RunCounter := GVL_PLC_Tests.FrameworkResult.RunCounter + 1;
            GVL_PLC_Tests.Status.FailureSummary := '';
            CurrentSuiteIdx := 7;
            GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_RUNNING;
        END_IF;

        // Commande d'effacement du rapport — acquittement explicite, retour à IDLE
        IF ClearReportTrig.Q THEN
            // La réinitialisation des rapports Steps[]/Cases[] est gérée par le moteur
            // au démarrage du run suivant ; ici on remet juste les compteurs IHM et on
            // libère l'état figé PASSED/FAILED/ABORTED.
            GVL_PLC_Tests.Status.CasesTotal := 0;
            GVL_PLC_Tests.Status.CasesPassed := 0;
            GVL_PLC_Tests.Status.CasesFailed := 0;
            GVL_PLC_Tests.Status.FailureSummary := '';
            GVL_PLC_Tests.EventCount := 0;
            GVL_PLC_Tests.EventSequence := 0;
            GVL_PLC_Tests.EventOverflow := FALSE;
            GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_IDLE;
        END_IF;

    E_TestRunState.TESTRUN_RUNNING:
        // Annulation des impulsions de départ
        StartSafety := FALSE;
        StartTranslation := FALSE;
        StartBucket := FALSE;
        StartEncoder := FALSE;
        StartModes := FALSE;
        StartHeartbeat := FALSE;
        StartSupervision := FALSE;
        StartFramework := FALSE;

        // 🧪 Smoke framework natif : 3 scans, sans appeler aucun moteur de test.
        IF CurrentSuiteIdx = 7 THEN
            FrameworkScanCount := FrameworkScanCount + 1;
            IF FrameworkScanCount >= 3 THEN
                GVL_PLC_Tests.FrameworkResult.InProgress := FALSE;
                GVL_PLC_Tests.FrameworkResult.AllPassed := TRUE;
                GVL_PLC_Tests.FrameworkResult.AnyFailed := FALSE;
                GVL_PLC_Tests.FrameworkResult.TestsPassed := 1;
                GVL_PLC_Tests.FrameworkResult.TestsFailed := 0;
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_PASSED;
            END_IF;
        END_IF;

        // 🛡️ Aucun orchestrateur ne doit attendre Done indéfiniment.
        SuiteElapsed := SuiteElapsed + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
        GVL_PLC_Tests.Status.SuiteElapsed := SuiteElapsed;
        IF SuiteElapsed >= DINT_TO_TIME(GVL_PLC_Tests_Const.MaxSuiteDurationMs) THEN
            SuiteWatchdogExpired := TRUE;
            GVL_PLC_Tests.Status.SuiteWatchdogExpired := TRUE;
            IF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteSafety THEN
                AbortSafety := TRUE;
            ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteTranslation THEN
                AbortTranslation := TRUE;
            ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteEncoder THEN
                AbortEncoder := TRUE;
            ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteModes THEN
                AbortModes := TRUE;
            ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteHeartbeat THEN
                AbortHeartbeat := TRUE;
            ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteSupervision THEN
                AbortSupervision := TRUE;
            ELSE
                AbortBucket := TRUE;
            END_IF;
        END_IF;

        // Abandon propre ou perte du mode Simulation — coupe la suite active
        IF AbortTrig.Q OR ((NOT GVL_Simulation.SimulationModeActive) AND (CurrentSuiteIdx <> GVL_PLC_Tests_Const.SuiteSupervision)) THEN
            AbortSafety := TRUE;
            AbortTranslation := TRUE;
            AbortBucket := TRUE;
            AbortEncoder := TRUE;
            AbortModes := TRUE;
            AbortHeartbeat := TRUE;
            AbortSupervision := TRUE;
        END_IF;

        // Surveillance de la fin d'exécution — Safety d'abord
        IF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteSafety AND instSafetyValidation.Done THEN
            AbortSafety := FALSE;
            IF instSafetyValidation.TerminalState <> E_TestTerminalState.TEST_TERMINAL_DONE AND instSafetyValidation.Report.RunCounter <> LastLoggedSafetyRun THEN
                LastLoggedSafetyRun := instSafetyValidation.Report.RunCounter;
                GVL_PLC_Tests.EventSequence := GVL_PLC_Tests.EventSequence + 1;
                IF GVL_PLC_Tests.EventCount < GVL_PLC_Tests_Const.MaxTestEvents THEN
                    GVL_PLC_Tests.EventCount := GVL_PLC_Tests.EventCount + 1;
                ELSE
                    GVL_PLC_Tests.EventOverflow := TRUE;
                END_IF;
                EventIdx := UDINT_TO_INT(GVL_PLC_Tests.EventSequence MOD INT_TO_UDINT(GVL_PLC_Tests_Const.MaxTestEvents)) + 1;
                GVL_PLC_Tests.EventLog[EventIdx].Sequence := GVL_PLC_Tests.EventSequence;
                GVL_PLC_Tests.EventLog[EventIdx].Severity := E_TestEventSeverity.TEST_EVENT_ERROR;
                GVL_PLC_Tests.EventLog[EventIdx].SuiteId := GVL_PLC_Tests_Const.SuiteSafety;
                GVL_PLC_Tests.EventLog[EventIdx].CaseId := instSafetyValidation.Report.CurrentCaseId;
                GVL_PLC_Tests.EventLog[EventIdx].StepId := instSafetyValidation.Report.CurrentStepId;
                GVL_PLC_Tests.EventLog[EventIdx].Code := instSafetyValidation.ErrorCode;
                GVL_PLC_Tests.EventLog[EventIdx].Message := instSafetyValidation.ErrorMessage;
            END_IF;
            IF ChainMode AND (NOT instSafetyValidation.Report.Aborted OR SuiteWatchdogExpired) AND instTranslationValidation.SimGateOk THEN
                // 🔗 Enchaîne vers Translation (continue même si Safety a échoué — logique
                // FAIL_CONTINUE déjà appliquée au niveau des cases/steps, voir §7.3.4)
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteTranslation;
                SuiteElapsed := T#0s;
                StartTranslation := TRUE;
                RequestedCaseTranslation := 0; // Enchaînement RunAll -> toutes les cases Translation
            ELSIF ChainMode AND NOT instSafetyValidation.Report.Aborted AND NOT instTranslationValidation.SimGateOk THEN
                // 🔧 REX 2026-07-16 : bug trouvé — le chaînage sautait la vérification SimGateOk
                // (le démarrage ciblé Cmd.RunSuite=2 la faisait, pas celui-ci). Sans ce garde-fou,
                // Translation démarrait quand même avec FB_Safety_Translation.Enable=FALSE
                // (ManuActive actif) → 3 timeouts silencieux, aucun défaut jamais détectable.
                GVL_PLC_Tests.Cmd.RunAll := FALSE;
                ChainMode := FALSE; // 🔒 Évite d'agréger un rapport Translation périmé (suite jamais lancée ce run)
                IF instSafetyValidation.Report.FailureSummary = '' THEN
                    GVL_PLC_Tests.Status.FailureSummary := 'Translation NON TESTEE (SimGateOk=FALSE — vérifier SimulationModeActive et les E/S M3 non réelles)';
                ELSE
                    GVL_PLC_Tests.Status.FailureSummary := CONCAT(instSafetyValidation.Report.FailureSummary, ' || Translation NON TESTEE (SimGateOk=FALSE — vérifier SimulationModeActive et les E/S M3 non réelles)');
                END_IF;
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_ABORTED;
            ELSE
                FinalAborted := instSafetyValidation.Report.Aborted;
                FinalAnyFailed := instSafetyValidation.AnyFailed;
                GVL_PLC_Tests.Cmd.RunAll := FALSE; // 🔧 Retombe ICI (Done atteint), pas au démarrage
                GVL_PLC_Tests.Status.FailureSummary := instSafetyValidation.Report.FailureSummary;
                IF FinalAborted THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_ABORTED;
                ELSIF FinalAnyFailed THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_FAILED;
                ELSE
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_PASSED;
                END_IF;
            END_IF;

        // Surveillance de la fin d'exécution — Translation (ciblée ou enchaînée après Safety)
        ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteTranslation AND instTranslationValidation.Done THEN
            AbortTranslation := FALSE;
            IF instTranslationValidation.TerminalState <> E_TestTerminalState.TEST_TERMINAL_DONE AND instTranslationValidation.Report.RunCounter <> LastLoggedTranslationRun THEN
                LastLoggedTranslationRun := instTranslationValidation.Report.RunCounter;
                GVL_PLC_Tests.EventSequence := GVL_PLC_Tests.EventSequence + 1;
                IF GVL_PLC_Tests.EventCount < GVL_PLC_Tests_Const.MaxTestEvents THEN
                    GVL_PLC_Tests.EventCount := GVL_PLC_Tests.EventCount + 1;
                ELSE
                    GVL_PLC_Tests.EventOverflow := TRUE;
                END_IF;
                EventIdx := UDINT_TO_INT(GVL_PLC_Tests.EventSequence MOD INT_TO_UDINT(GVL_PLC_Tests_Const.MaxTestEvents)) + 1;
                GVL_PLC_Tests.EventLog[EventIdx].Sequence := GVL_PLC_Tests.EventSequence;
                GVL_PLC_Tests.EventLog[EventIdx].Severity := E_TestEventSeverity.TEST_EVENT_ERROR;
                GVL_PLC_Tests.EventLog[EventIdx].SuiteId := GVL_PLC_Tests_Const.SuiteTranslation;
                GVL_PLC_Tests.EventLog[EventIdx].CaseId := instTranslationValidation.Report.CurrentCaseId;
                GVL_PLC_Tests.EventLog[EventIdx].StepId := instTranslationValidation.Report.CurrentStepId;
                GVL_PLC_Tests.EventLog[EventIdx].Code := instTranslationValidation.ErrorCode;
                GVL_PLC_Tests.EventLog[EventIdx].Message := instTranslationValidation.ErrorMessage;
            END_IF;
            IF ChainMode AND (NOT instTranslationValidation.Report.Aborted OR SuiteWatchdogExpired) AND instBucketValidation.SimGateOk THEN
                // 🔗 Enchaîne vers Bucket (2026-07-16 : 3e maillon Safety→Translation→Bucket)
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteBucket;
                SuiteElapsed := T#0s;
                StartBucket := TRUE;
                RequestedCaseBucket := 0;
            ELSIF ChainMode AND NOT instTranslationValidation.Report.Aborted AND NOT instBucketValidation.SimGateOk THEN
                // Même garde-fou que Safety→Translation : Bucket ne doit jamais démarrer sans son
                // SimGateOk (refuse si M1/M2 en simulation réelle, voir FB_BucketValidation §1).
                GVL_PLC_Tests.Cmd.RunAll := FALSE;
                ChainMode := FALSE; // 🔒 Évite d'agréger un rapport Bucket périmé (suite jamais lancée ce run)
                IF instSafetyValidation.Report.FailureSummary = '' AND instTranslationValidation.Report.FailureSummary = '' THEN
                    GVL_PLC_Tests.Status.FailureSummary := 'Bucket NON TESTEE (SimGateOk=FALSE — verifier simulation reelle M1/M2)';
                ELSIF instTranslationValidation.Report.FailureSummary = '' THEN
                    GVL_PLC_Tests.Status.FailureSummary := CONCAT(instSafetyValidation.Report.FailureSummary, ' || Bucket NON TESTEE (SimGateOk=FALSE — verifier simulation reelle M1/M2)');
                ELSE
                    GVL_PLC_Tests.Status.FailureSummary := CONCAT(instTranslationValidation.Report.FailureSummary, ' || Bucket NON TESTEE (SimGateOk=FALSE — verifier simulation reelle M1/M2)');
                END_IF;
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_ABORTED;
            ELSE
                // Soit run ciblé (pas de chaînage), soit chaînage interrompu (Translation.Aborted)
                IF ChainMode THEN
                    FinalAborted := instSafetyValidation.Report.Aborted OR instTranslationValidation.Report.Aborted;
                    FinalAnyFailed := instSafetyValidation.AnyFailed OR instTranslationValidation.AnyFailed;
                    IF instSafetyValidation.Report.FailureSummary <> '' AND instTranslationValidation.Report.FailureSummary <> '' THEN
                        GVL_PLC_Tests.Status.FailureSummary := CONCAT(instSafetyValidation.Report.FailureSummary, CONCAT(' || ', instTranslationValidation.Report.FailureSummary));
                    ELSIF instSafetyValidation.Report.FailureSummary <> '' THEN
                        GVL_PLC_Tests.Status.FailureSummary := instSafetyValidation.Report.FailureSummary;
                    ELSE
                        GVL_PLC_Tests.Status.FailureSummary := instTranslationValidation.Report.FailureSummary;
                    END_IF;
                ELSE
                    FinalAborted := instTranslationValidation.Report.Aborted;
                    FinalAnyFailed := instTranslationValidation.AnyFailed;
                    GVL_PLC_Tests.Status.FailureSummary := instTranslationValidation.Report.FailureSummary;
                END_IF;
                GVL_PLC_Tests.Cmd.RunAll := FALSE; // 🔧 Retombe ICI (Done atteint), pas au démarrage
                IF FinalAborted THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_ABORTED;
                ELSIF FinalAnyFailed THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_FAILED;
                ELSE
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_PASSED;
                END_IF;
            END_IF;

        // Surveillance de la fin d'exécution — Bucket (ciblée, ou dernier maillon de la chaîne)
        ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteBucket AND instBucketValidation.Done THEN
            AbortBucket := FALSE;
            IF instBucketValidation.TerminalState <> E_TestTerminalState.TEST_TERMINAL_DONE AND instBucketValidation.Report.RunCounter <> LastLoggedBucketRun THEN
                LastLoggedBucketRun := instBucketValidation.Report.RunCounter;
                GVL_PLC_Tests.EventSequence := GVL_PLC_Tests.EventSequence + 1;
                IF GVL_PLC_Tests.EventCount < GVL_PLC_Tests_Const.MaxTestEvents THEN
                    GVL_PLC_Tests.EventCount := GVL_PLC_Tests.EventCount + 1;
                ELSE
                    GVL_PLC_Tests.EventOverflow := TRUE;
                END_IF;
                EventIdx := UDINT_TO_INT(GVL_PLC_Tests.EventSequence MOD INT_TO_UDINT(GVL_PLC_Tests_Const.MaxTestEvents)) + 1;
                GVL_PLC_Tests.EventLog[EventIdx].Sequence := GVL_PLC_Tests.EventSequence;
                GVL_PLC_Tests.EventLog[EventIdx].Severity := E_TestEventSeverity.TEST_EVENT_ERROR;
                GVL_PLC_Tests.EventLog[EventIdx].SuiteId := GVL_PLC_Tests_Const.SuiteBucket;
                GVL_PLC_Tests.EventLog[EventIdx].CaseId := instBucketValidation.Report.CurrentCaseId;
                GVL_PLC_Tests.EventLog[EventIdx].StepId := instBucketValidation.Report.CurrentStepId;
                GVL_PLC_Tests.EventLog[EventIdx].Code := instBucketValidation.ErrorCode;
                GVL_PLC_Tests.EventLog[EventIdx].Message := instBucketValidation.ErrorMessage;
            END_IF;
            IF ChainMode THEN
                // Campagne complète : Bucket terminé → Encoder.
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteEncoder;
                SuiteElapsed := T#0s;
                StartEncoder := TRUE;
                RequestedCaseEncoder := 0;
                // Conserve les verdicts précédents pour le verdict final.
                FinalAborted := FinalAborted OR instSafetyValidation.Report.Aborted OR instTranslationValidation.Report.Aborted OR instBucketValidation.Report.Aborted;
                FinalAnyFailed := FinalAnyFailed OR instSafetyValidation.AnyFailed OR instTranslationValidation.AnyFailed OR instBucketValidation.AnyFailed;
                // 🏷️ Combine jusqu'à 3 résumés intermédiaires.
                GVL_PLC_Tests.Status.FailureSummary := '';
                IF instSafetyValidation.Report.FailureSummary <> '' THEN
                    GVL_PLC_Tests.Status.FailureSummary := instSafetyValidation.Report.FailureSummary;
                END_IF;
                IF instTranslationValidation.Report.FailureSummary <> '' THEN
                    IF GVL_PLC_Tests.Status.FailureSummary <> '' THEN
                        GVL_PLC_Tests.Status.FailureSummary := CONCAT(GVL_PLC_Tests.Status.FailureSummary, CONCAT(' || ', instTranslationValidation.Report.FailureSummary));
                    ELSE
                        GVL_PLC_Tests.Status.FailureSummary := instTranslationValidation.Report.FailureSummary;
                    END_IF;
                END_IF;
                IF instBucketValidation.Report.FailureSummary <> '' THEN
                    IF GVL_PLC_Tests.Status.FailureSummary <> '' THEN
                        GVL_PLC_Tests.Status.FailureSummary := CONCAT(GVL_PLC_Tests.Status.FailureSummary, CONCAT(' || ', instBucketValidation.Report.FailureSummary));
                    ELSE
                        GVL_PLC_Tests.Status.FailureSummary := instBucketValidation.Report.FailureSummary;
                    END_IF;
                END_IF;
            ELSE
                FinalAborted := instBucketValidation.Report.Aborted;
                FinalAnyFailed := instBucketValidation.AnyFailed;
                GVL_PLC_Tests.Status.FailureSummary := instBucketValidation.Report.FailureSummary;
                GVL_PLC_Tests.Cmd.RunAll := FALSE;
                IF FinalAborted THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_ABORTED;
                ELSIF FinalAnyFailed THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_FAILED;
                ELSE
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_PASSED;
                END_IF;
            END_IF;
        ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteHeartbeat AND instHeartbeatValidation.Done THEN
            AbortHeartbeat := FALSE;
            FinalAborted := FinalAborted OR instHeartbeatValidation.Report.Aborted;
            FinalAnyFailed := FinalAnyFailed OR instHeartbeatValidation.AnyFailed;
            IF instHeartbeatValidation.Report.FailureSummary <> '' THEN
                IF GVL_PLC_Tests.Status.FailureSummary <> '' THEN
                    GVL_PLC_Tests.Status.FailureSummary := CONCAT(GVL_PLC_Tests.Status.FailureSummary, CONCAT(' || ', instHeartbeatValidation.Report.FailureSummary));
                ELSE
                    GVL_PLC_Tests.Status.FailureSummary := instHeartbeatValidation.Report.FailureSummary;
                END_IF;
            END_IF;
            // ChainMode reste mémorisé au terminal pour agréger toute la campagne.
            // Le prochain lancement ciblé le remet explicitement à FALSE.
            GVL_PLC_Tests.Cmd.RunAll := FALSE;
            IF FinalAborted THEN
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_ABORTED;
            ELSIF FinalAnyFailed THEN
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_FAILED;
            ELSE
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_PASSED;
            END_IF;
        ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteEncoder AND instEncoderValidation.Done THEN
            AbortEncoder := FALSE;
            IF ChainMode THEN
                FinalAborted := FinalAborted OR instEncoderValidation.Report.Aborted;
                FinalAnyFailed := FinalAnyFailed OR instEncoderValidation.AnyFailed;
                IF instEncoderValidation.Report.FailureSummary <> '' THEN
                    IF GVL_PLC_Tests.Status.FailureSummary <> '' THEN
                        GVL_PLC_Tests.Status.FailureSummary := CONCAT(GVL_PLC_Tests.Status.FailureSummary, CONCAT(' || ', instEncoderValidation.Report.FailureSummary));
                    ELSE
                        GVL_PLC_Tests.Status.FailureSummary := instEncoderValidation.Report.FailureSummary;
                    END_IF;
                END_IF;
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteModes;
                SuiteElapsed := T#0s;
                StartModes := TRUE;
                RequestedCaseModes := 0;
            ELSE
                FinalAborted := instEncoderValidation.Report.Aborted;
                FinalAnyFailed := instEncoderValidation.AnyFailed;
                GVL_PLC_Tests.Status.FailureSummary := instEncoderValidation.Report.FailureSummary;
            END_IF;
            IF SuiteWatchdogExpired THEN
                GVL_PLC_Tests.Status.FailureSummary := 'Watchdog suite Encoder/Homing expire';
                FinalAborted := FALSE;
                FinalAnyFailed := TRUE;
            END_IF;
            IF NOT ChainMode THEN
                IF FinalAborted THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_ABORTED;
                ELSIF FinalAnyFailed THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_FAILED;
                ELSE
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_PASSED;
                END_IF;
            END_IF;
        ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteModes AND instModesValidation.Done THEN
            AbortModes := FALSE;
            IF ChainMode THEN
                FinalAborted := FinalAborted OR instModesValidation.Report.Aborted;
                FinalAnyFailed := FinalAnyFailed OR instModesValidation.AnyFailed;
                IF instModesValidation.Report.FailureSummary <> '' THEN
                    IF GVL_PLC_Tests.Status.FailureSummary <> '' THEN
                        GVL_PLC_Tests.Status.FailureSummary := CONCAT(GVL_PLC_Tests.Status.FailureSummary, CONCAT(' || ', instModesValidation.Report.FailureSummary));
                    ELSE
                        GVL_PLC_Tests.Status.FailureSummary := instModesValidation.Report.FailureSummary;
                    END_IF;
                END_IF;
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteHeartbeat;
                SuiteElapsed := T#0s;
                StartHeartbeat := TRUE;
                RequestedCaseHeartbeat := 0;
            ELSE
                FinalAborted := instModesValidation.Report.Aborted;
                FinalAnyFailed := instModesValidation.AnyFailed;
                GVL_PLC_Tests.Status.FailureSummary := instModesValidation.Report.FailureSummary;
            END_IF;
            IF SuiteWatchdogExpired THEN
                GVL_PLC_Tests.Status.FailureSummary := 'Watchdog suite Modes/Homme-mort expire';
                FinalAborted := FALSE;
                FinalAnyFailed := TRUE;
            END_IF;
            IF NOT ChainMode THEN
                IF FinalAborted THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_ABORTED;
                ELSIF FinalAnyFailed THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_FAILED;
                ELSE
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_PASSED;
                END_IF;
            END_IF;
        ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteSupervision AND instSupervisionValidation.Done THEN
            AbortSupervision := FALSE;
            IF instSupervisionValidation.TerminalState <> E_TestTerminalState.TEST_TERMINAL_DONE AND instSupervisionValidation.Report.RunCounter <> LastLoggedSupervisionRun THEN
                LastLoggedSupervisionRun := instSupervisionValidation.Report.RunCounter;
                GVL_PLC_Tests.EventSequence := GVL_PLC_Tests.EventSequence + 1;
                IF GVL_PLC_Tests.EventCount < GVL_PLC_Tests_Const.MaxTestEvents THEN
                    GVL_PLC_Tests.EventCount := GVL_PLC_Tests.EventCount + 1;
                ELSE
                    GVL_PLC_Tests.EventOverflow := TRUE;
                END_IF;
                EventIdx := UDINT_TO_INT(GVL_PLC_Tests.EventSequence MOD INT_TO_UDINT(GVL_PLC_Tests_Const.MaxTestEvents)) + 1;
                GVL_PLC_Tests.EventLog[EventIdx].Sequence := GVL_PLC_Tests.EventSequence;
                GVL_PLC_Tests.EventLog[EventIdx].Severity := E_TestEventSeverity.TEST_EVENT_ERROR;
                GVL_PLC_Tests.EventLog[EventIdx].SuiteId := GVL_PLC_Tests_Const.SuiteSupervision;
                GVL_PLC_Tests.EventLog[EventIdx].CaseId := instSupervisionValidation.Report.CurrentCaseId;
                GVL_PLC_Tests.EventLog[EventIdx].StepId := instSupervisionValidation.Report.CurrentStepId;
                GVL_PLC_Tests.EventLog[EventIdx].Code := instSupervisionValidation.ErrorCode;
                GVL_PLC_Tests.EventLog[EventIdx].Message := instSupervisionValidation.ErrorMessage;
            END_IF;
            FinalAborted := instSupervisionValidation.Report.Aborted;
            FinalAnyFailed := instSupervisionValidation.AnyFailed;
            GVL_PLC_Tests.Status.FailureSummary := instSupervisionValidation.Report.FailureSummary;
            IF FinalAborted THEN
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_ABORTED;
            ELSIF FinalAnyFailed THEN
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_FAILED;
            ELSE
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_PASSED;
            END_IF;
        END_IF;

END_CASE;

// 3. Appel des instances de suites
instSafetyValidation(Start := StartSafety, Abort := AbortSafety, CaseId := RequestedCaseSafety);
instTranslationValidation(Start := StartTranslation, Abort := AbortTranslation, CaseId := RequestedCaseTranslation);
instBucketValidation(Start := StartBucket, Abort := AbortBucket, CaseId := RequestedCaseBucket, instBucket := instBucket, instWinchM2 := instWinchM2);
instEncoderValidation(Start := StartEncoder, Abort := AbortEncoder, CaseId := RequestedCaseEncoder);
instModesValidation(Start := StartModes, Abort := AbortModes, CaseId := RequestedCaseModes);
instHeartbeatValidation(Start := StartHeartbeat, Abort := AbortHeartbeat, CaseId := RequestedCaseHeartbeat);
instSupervisionValidation(Start := StartSupervision, Abort := AbortSupervision, CaseId := RequestedCaseSupervision);

// 4. Centralisation et recopie vers GVL_PLC_Tests
GVL_PLC_Tests.Status.SimulationActive := GVL_Simulation.SimulationModeActive;
GVL_PLC_Tests.Status.SuiteWatchdogExpired := SuiteWatchdogExpired;
GVL_PLC_Tests.SuiteSafetyValidation := instSafetyValidation.Report;
GVL_PLC_Tests.SuiteTranslationValidation := instTranslationValidation.Report;
GVL_PLC_Tests.SuiteTranslationResult := instTranslationValidation.Result; // 🆕 Résultat plat clair
GVL_PLC_Tests.SuiteBucketValidation := instBucketValidation.Report;
GVL_PLC_Tests.SuiteEncoderValidation := instEncoderValidation.Report;
GVL_PLC_Tests.SuiteModesValidation := instModesValidation.Report;
GVL_PLC_Tests.SuiteHeartbeatValidation := instHeartbeatValidation.Report;
GVL_PLC_Tests.SuiteSupervisionValidation := instSupervisionValidation.Report;

// 5. Mise à jour des indicateurs de progression IHM
IF GVL_PLC_Tests.Status.RunState = E_TestRunState.TESTRUN_RUNNING THEN
    GVL_PLC_Tests.Status.ActiveSuiteId := CurrentSuiteIdx;
    // 🧪 L'autotest framework a sa propre progression : ne jamais afficher
    // le rapport Safety résiduel lorsque CurrentSuiteIdx=7.
    IF CurrentSuiteIdx = 7 THEN
        GVL_PLC_Tests.Status.ActiveSuiteName := 'Framework Validation';
        GVL_PLC_Tests.Status.ActiveCaseId := GVL_PLC_Tests.FrameworkResult.CurrentTestId;
        GVL_PLC_Tests.Status.ActiveStepId := GVL_PLC_Tests.FrameworkResult.CurrentTestId;
        GVL_PLC_Tests.Status.StepElapsed := T#0s;
        GVL_PLC_Tests.Status.TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
        GVL_PLC_Tests.Status.ErrorCode := GVL_PLC_Tests.FrameworkResult.FailedTestId;
        GVL_PLC_Tests.Status.ErrorMessage := GVL_PLC_Tests.FrameworkResult.ErrorMessage;
    ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteTranslation THEN
        GVL_PLC_Tests.Status.ActiveSuiteName := instTranslationValidation.Report.Name;
        GVL_PLC_Tests.Status.ActiveCaseId := instTranslationValidation.Report.CurrentCaseId;
        GVL_PLC_Tests.Status.ActiveStepId := instTranslationValidation.Report.CurrentStepId;
        GVL_PLC_Tests.Status.StepElapsed := instTranslationValidation.StepElapsed;
        GVL_PLC_Tests.Status.TerminalState := instTranslationValidation.TerminalState;
        GVL_PLC_Tests.Status.ErrorCode := instTranslationValidation.ErrorCode;
        GVL_PLC_Tests.Status.ErrorMessage := instTranslationValidation.ErrorMessage;
    ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteBucket THEN
        GVL_PLC_Tests.Status.ActiveSuiteName := instBucketValidation.Report.Name;
        GVL_PLC_Tests.Status.ActiveCaseId := instBucketValidation.Report.CurrentCaseId;
        GVL_PLC_Tests.Status.ActiveStepId := instBucketValidation.Report.CurrentStepId;
        GVL_PLC_Tests.Status.StepElapsed := instBucketValidation.StepElapsed;
        GVL_PLC_Tests.Status.TerminalState := instBucketValidation.TerminalState;
        GVL_PLC_Tests.Status.ErrorCode := instBucketValidation.ErrorCode;
        GVL_PLC_Tests.Status.ErrorMessage := instBucketValidation.ErrorMessage;
    ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteEncoder THEN
        GVL_PLC_Tests.Status.ActiveSuiteName := instEncoderValidation.Report.Name;
        GVL_PLC_Tests.Status.ActiveCaseId := instEncoderValidation.Report.CurrentCaseId;
        GVL_PLC_Tests.Status.ActiveStepId := instEncoderValidation.Report.CurrentStepId;
        GVL_PLC_Tests.Status.StepElapsed := instEncoderValidation.StepElapsed;
        GVL_PLC_Tests.Status.TerminalState := instEncoderValidation.TerminalState;
        GVL_PLC_Tests.Status.ErrorCode := instEncoderValidation.ErrorCode;
        GVL_PLC_Tests.Status.ErrorMessage := instEncoderValidation.ErrorMessage;
    ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteHeartbeat THEN
        GVL_PLC_Tests.Status.ActiveSuiteName := instHeartbeatValidation.Report.Name;
        GVL_PLC_Tests.Status.ActiveCaseId := instHeartbeatValidation.Report.CurrentCaseId;
        GVL_PLC_Tests.Status.ActiveStepId := instHeartbeatValidation.Report.CurrentStepId;
        GVL_PLC_Tests.Status.StepElapsed := instHeartbeatValidation.StepElapsed;
        GVL_PLC_Tests.Status.TerminalState := instHeartbeatValidation.TerminalState;
        GVL_PLC_Tests.Status.ErrorCode := instHeartbeatValidation.ErrorCode;
        GVL_PLC_Tests.Status.ErrorMessage := instHeartbeatValidation.ErrorMessage;
    ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteSupervision THEN
        GVL_PLC_Tests.Status.ActiveSuiteName := instSupervisionValidation.Report.Name;
        GVL_PLC_Tests.Status.ActiveCaseId := instSupervisionValidation.Report.CurrentCaseId;
        GVL_PLC_Tests.Status.ActiveStepId := instSupervisionValidation.Report.CurrentStepId;
        GVL_PLC_Tests.Status.StepElapsed := instSupervisionValidation.StepElapsed;
        GVL_PLC_Tests.Status.TerminalState := instSupervisionValidation.TerminalState;
        GVL_PLC_Tests.Status.ErrorCode := instSupervisionValidation.ErrorCode;
        GVL_PLC_Tests.Status.ErrorMessage := instSupervisionValidation.ErrorMessage;
    ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteModes THEN
        GVL_PLC_Tests.Status.ActiveSuiteName := instModesValidation.Report.Name;
        GVL_PLC_Tests.Status.ActiveCaseId := instModesValidation.Report.CurrentCaseId;
        GVL_PLC_Tests.Status.ActiveStepId := instModesValidation.Report.CurrentStepId;
        GVL_PLC_Tests.Status.StepElapsed := instModesValidation.StepElapsed;
        GVL_PLC_Tests.Status.TerminalState := instModesValidation.TerminalState;
        GVL_PLC_Tests.Status.ErrorCode := instModesValidation.ErrorCode;
        GVL_PLC_Tests.Status.ErrorMessage := instModesValidation.ErrorMessage;
    ELSE
        GVL_PLC_Tests.Status.ActiveSuiteName := instSafetyValidation.Report.Name;
        GVL_PLC_Tests.Status.ActiveCaseId := instSafetyValidation.Report.CurrentCaseId;
        GVL_PLC_Tests.Status.ActiveStepId := instSafetyValidation.Report.CurrentStepId;
        GVL_PLC_Tests.Status.StepElapsed := instSafetyValidation.StepElapsed;
        GVL_PLC_Tests.Status.TerminalState := instSafetyValidation.TerminalState;
        GVL_PLC_Tests.Status.ErrorCode := instSafetyValidation.ErrorCode;
        GVL_PLC_Tests.Status.ErrorMessage := instSafetyValidation.ErrorMessage;
    END_IF;
ELSE
    GVL_PLC_Tests.Status.ActiveSuiteId := 0;
    GVL_PLC_Tests.Status.ActiveSuiteName := '';
    GVL_PLC_Tests.Status.ActiveCaseId := 0;
    GVL_PLC_Tests.Status.ActiveCaseName := '';
    GVL_PLC_Tests.Status.ActiveStepId := 0;
    GVL_PLC_Tests.Status.ActiveStepName := '';
    GVL_PLC_Tests.Status.StepElapsed := T#0s;
    GVL_PLC_Tests.Status.StepTimeoutPT := T#0s;
END_IF;

// Agrégation globale des compteurs de cas de tests — seules les suites réellement
// exécutées CE run comptent (ChainMode = les deux ; sinon seule CurrentSuiteIdx)
// pour ne jamais compter les restes d'un run ciblé précédent sur l'autre suite.
PassedCount := 0;
FailedCount := 0;
TotalCount := 0;

IF ChainMode OR CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteSafety THEN
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        IF instSafetyValidation.Report.Cases[Idx].Executed THEN
            TotalCount := TotalCount + 1;
            IF instSafetyValidation.Report.Cases[Idx].Ok THEN
                PassedCount := PassedCount + 1;
            ELSE
                FailedCount := FailedCount + 1;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

IF ChainMode OR CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteTranslation THEN
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        IF instTranslationValidation.Report.Cases[Idx].Executed THEN
            TotalCount := TotalCount + 1;
            IF instTranslationValidation.Report.Cases[Idx].Ok THEN
                PassedCount := PassedCount + 1;
            ELSE
                FailedCount := FailedCount + 1;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

IF ChainMode OR CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteBucket THEN
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        IF instBucketValidation.Report.Cases[Idx].Executed THEN
            TotalCount := TotalCount + 1;
            IF instBucketValidation.Report.Cases[Idx].Ok THEN
                PassedCount := PassedCount + 1;
            ELSE
                FailedCount := FailedCount + 1;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

IF ChainMode OR CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteEncoder THEN
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        IF instEncoderValidation.Report.Cases[Idx].Executed THEN
            TotalCount := TotalCount + 1;
            IF instEncoderValidation.Report.Cases[Idx].Ok THEN
                PassedCount := PassedCount + 1;
            ELSE
                FailedCount := FailedCount + 1;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

IF ChainMode OR CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteModes THEN
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        IF instModesValidation.Report.Cases[Idx].Executed THEN
            TotalCount := TotalCount + 1;
            IF instModesValidation.Report.Cases[Idx].Ok THEN
                PassedCount := PassedCount + 1;
            ELSE
                FailedCount := FailedCount + 1;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

IF ChainMode OR CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteHeartbeat THEN
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        IF instHeartbeatValidation.Report.Cases[Idx].Executed THEN
            TotalCount := TotalCount + 1;
            IF instHeartbeatValidation.Report.Cases[Idx].Ok THEN
                PassedCount := PassedCount + 1;
            ELSE
                FailedCount := FailedCount + 1;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

IF ChainMode OR CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteSupervision THEN
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        IF instSupervisionValidation.Report.Cases[Idx].Executed THEN
            TotalCount := TotalCount + 1;
            IF instSupervisionValidation.Report.Cases[Idx].Ok THEN
                PassedCount := PassedCount + 1;
            ELSE
                FailedCount := FailedCount + 1;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

GVL_PLC_Tests.Status.CasesTotal := TotalCount;
GVL_PLC_Tests.Status.CasesPassed := PassedCount;
GVL_PLC_Tests.Status.CasesFailed := FailedCount;

// 💓 Logique du Clignotant visuel d'activité (Heartbeat — Triple clignotement réactif)
IF GVL_PLC_Tests.Status.RunState = E_TestRunState.TESTRUN_RUNNING THEN
    // 1. Détection d'un changement de step réel -> Armement du triple clignotement
    IF GVL_PLC_Tests.Status.ActiveStepId <> LastStepId AND PulseCounter = 0 THEN
        PulseCounter := 1;
        CycleCounter := 0;
        GVL_PLC_Tests.Status.Heartbeat := TRUE;
        LastStepId := GVL_PLC_Tests.Status.ActiveStepId;
    END_IF;

    // 2. Gestion du cycle de clignotement (100ms ON / 100ms OFF x3)
    IF PulseCounter > 0 THEN
        CycleCounter := CycleCounter + 1;
        IF CycleCounter >= 10 THEN
            CycleCounter := 0;
            PulseCounter := PulseCounter + 1;
            IF PulseCounter <= 6 THEN
                // Impulsions impaires = TRUE, paires = FALSE
                GVL_PLC_Tests.Status.Heartbeat := (PulseCounter MOD 2 <> 0);
            ELSE
                // Fin du triple clignotement -> retour à l'état éteint
                PulseCounter := 0;
                GVL_PLC_Tests.Status.Heartbeat := FALSE;
            END_IF;
        END_IF;
    END_IF;
ELSE
    // Forcer à FALSE quand le runner est au repos
    GVL_PLC_Tests.Status.Heartbeat := FALSE;
    LastStepId := 0;
    PulseCounter := 0;
    CycleCounter := 0;
END_IF;

(* =======================================================================
   📊 FB_WinchLoadEstimator — Estimation empirique de charge treuil
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Estimation informative de la charge par croisement palier/vitesse
   📄 Doc métier : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md
   🔌 Interface : Brique de diagnostic/mesure (1 instance par treuil)
   🔒 Sécurité : Aucune commande moteur ni action sur SafeStop (information IHM)
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_WinchLoadEstimator
VAR_INPUT
    // === COMMANDES ET CONSIGNES ===
    Enable                          : BOOL;                           // --> [CMD] Autorisation generale FB
    Reset                           : BOOL;                           // --> [CMD] Acquittement defaut sur front
    Mode                            : E_Mode;                         // --> [CMD] Mode d'exploitation actif
    ActiveSpeedStep                 : INT;                            // --> [CMD] Palier commande actif (0..5)

    // === SECOURS ET HARDWARE ===
    PowerContactorEngaged           : BOOL;                           // --> [SAFE] Chaine AU rearmee et puissance OK
    MeasuredSpeedMps                : REAL;                           // --> [HW] Vitesse cable absolue (m/s)
    MeasuredSpeedSignedMps          : REAL;                           // --> [HW] Vitesse signee (+: montee, -: descente) (m/s)

    // === REGLAGES ET TABLES ===
    SpeedConfig                     : ST_WinchSpeedConfig;            // --> [CFG] Configuration des plages de vitesse
    LoadTable                       : ST_WinchLoadEstimateTable;      // --> [CFG] Table empirique d'estimation 5x5
END_VAR
VAR_OUTPUT
    // === ETATS IEC ET SYNOPTIQUE ===
    Ready                           : BOOL;                           // <-- [STAT] FB pret a fonctionner
    Busy                            : BOOL;                           // <-- [STAT] Traitement en cours
    Done                            : BOOL;                           // <-- [STAT] Action terminee
    Error                           : BOOL;                           // <-- [STAT] Synthese defaut
    ErrorId                         : WORD;                           // <-- [DIAG] Code erreur (bit0: entree/table invalide)
    State                           : E_State;                        // <-- [STAT] Etat courant machine d'etat FB
    StateAtError                    : E_State;                        // <-- [DIAG] Etat memorise lors du dernier defaut

    // === DIAGNOSTICS ET ESTIMATIONS ===
    SpeedBand                       : INT;                            // <-- [DIAG] Bande de vitesse courante (0..5)
    EstimatedLoadPct                : REAL;                           // <-- [DIAG] Estimation de charge (0..100%)
    Configured                      : BOOL;                           // <-- [STAT] Table explicitement validee
    Ascending                       : BOOL;                           // <-- [STAT] Montee effective mesuree en cours
END_VAR
VAR
    // === DETECTEURS ET TIMERS INTERNES ===
    ResetEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Reset
    ErrorEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Erreur

    // === VARIABLES LOCALES CALCULÉES ===
    PreviousSpeedBand               : INT;                            // . [LOC] Memoire bande de vitesse cycle precedent
    HasPreviousBand                 : BOOL;                           // . [LOC] Indicateur premiere bande memorisee
    SelectedLoadPct                 : REAL;                           // . [LOC] Valeur de charge extraite de la table
END_VAR

{region "§1 Gate"}
// 🛑 1. GATE — aucune estimation lorsque le bloc est désactivé ou l'AU absent.
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE;
    Busy := FALSE;
    Done := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    State := E_State.DISABLED;
    SpeedBand := 0;
    EstimatedLoadPct := 0.0;
    Configured := FALSE;
    Ascending := FALSE;
    HasPreviousBand := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
Busy := FALSE;
Done := FALSE;
State := E_State.READY;
ResetEdge(CLK := Reset);
Configured := LoadTable.IsConfigured;
// 📈 L'estimation de charge n'a de sens qu'en montée.
// La bande de vitesse reste calculée pour le diagnostic et le garde-fou de palier,
// mais EstimatedLoadPct est forcée à zéro à l'arrêt et en descente.
Ascending := (MeasuredSpeedSignedMps > 0.0);
{endregion}

{region "§2 Classement vitesse"}
// 📏 2. CLASSEMENT DE LA VITESSE — hystérésis autour des 4 frontières.
IF (MeasuredSpeedMps < 0.0) OR (SpeedConfig.MaxMeasuredSpeedMps <= 0.0) THEN
    ErrorId := ErrorId OR 16#0001;
    SpeedBand := 0;
ELSIF NOT HasPreviousBand THEN
    IF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[1] THEN
        PreviousSpeedBand := 1;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[2] THEN
        PreviousSpeedBand := 2;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[3] THEN
        PreviousSpeedBand := 3;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[4] THEN
        PreviousSpeedBand := 4;
    ELSE
        PreviousSpeedBand := 5;
    END_IF;
    HasPreviousBand := TRUE;
    SpeedBand := PreviousSpeedBand;
ELSE
    // 🔒 Valider l'état mémorisé avant toute indexation dynamique.
    IF PreviousSpeedBand < 1 OR PreviousSpeedBand > 5 THEN
        PreviousSpeedBand := 1;
        ErrorId := ErrorId OR 16#0001;
    END_IF;

    // CODESYS ne garantit pas le court-circuit des expressions AND :
    // chaque borne est donc testée dans une branche séparée avant accès.
    IF PreviousSpeedBand < 5 THEN
        IF MeasuredSpeedMps > (SpeedConfig.SpeedBandMaxMps[PreviousSpeedBand]
                               + SpeedConfig.SpeedBandHysteresisMps) THEN
            PreviousSpeedBand := PreviousSpeedBand + 1;
        END_IF;
    END_IF;
    IF PreviousSpeedBand > 1 THEN
        IF MeasuredSpeedMps < (SpeedConfig.SpeedBandMaxMps[PreviousSpeedBand - 1]
                               - SpeedConfig.SpeedBandHysteresisMps) THEN
            PreviousSpeedBand := PreviousSpeedBand - 1;
        END_IF;
    END_IF;
    SpeedBand := PreviousSpeedBand;
END_IF;
{endregion}

{region "§3 Lecture table"}
// 📊 3. LECTURE TABLE — bornes séparées avant l'accès au tableau 5x5.
EstimatedLoadPct := 0.0;
IF Configured THEN
    IF Ascending THEN
        IF ActiveSpeedStep >= 1 THEN
            IF ActiveSpeedStep <= 5 THEN
                IF SpeedBand >= 1 THEN
                    IF SpeedBand <= 5 THEN
                        SelectedLoadPct := LoadTable.LoadPctByStepAndSpeedBand[ActiveSpeedStep][SpeedBand];
                        IF (SelectedLoadPct < 0.0) OR (SelectedLoadPct > 100.0) THEN
                            ErrorId := ErrorId OR 16#0001;
                        ELSE
                            EstimatedLoadPct := SelectedLoadPct;
                        END_IF;
                    END_IF;
                END_IF;
            END_IF;
        END_IF;
    END_IF;
END_IF;
{endregion}

{region "§4 Sorties et acquittement"}
// 📤 4. SORTIES D'ÉTAT ET ACQUITTEMENT.
IF ResetEdge.Q AND (ErrorId <> 16#0000) AND (MeasuredSpeedMps >= 0.0) THEN
    ErrorId := 16#0000;
END_IF;
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;
{endregion}

(* ============================================================================
   🧪 FB_SupervisionValidation — Suite PLC Persistance Config (chantier ConfigPersistence)
   ============================================================================
   🎯 Rôle : valide le mécanisme générique FB_CfgPersistBridge_<Type> (restauration
      PERSISTENT->IHM au boot, sauvegarde continue IHM->PERSISTENT, alarme
      ConfigRestoredFromPersistent) en profondeur sur M1M2Sync (le plus simple), puis
      un balayage de couverture léger (lecture seule, sans risque) des 5 autres domaines
      à pont générique, puis un test dédié pour Translation (pattern manuel, pas de pont).
   📄 Couvre (TASK_CONTEXT_CONFIG-PERSIST-01.yaml, T65) :
      TC-CP1 : Restauration PERSISTENT->IHM quand Initialized=FALSE (M1M2Sync)
      TC-CP2 : Alarme ConfigRestoredFromPersistent ne s'éteint QUE sur front BtnAckConfigRestored
      TC-CP3 : Sauvegarde continue IHM->PERSISTENT stable après restauration (pas de corruption)
      TC-CP4 : Balayage de couverture (lecture seule) — Cycle/Commun/Bucket/WinchM1/WinchM2
               ont chacun Cfg.Initialized=TRUE en fonctionnement normal
      TC-CP5 : Translation.Cmd.SetFreq_Hz (pattern manuel, pas de pont générique) — même
               restauration/alarme que TC-CP1, Lot 4 requis
   ⚠️ TC-CP1/CP2/CP3/CP5 forcent des variables GVL_PERSISTENT réelles (Sync, Translation) —
      sauvegardées au démarrage du test, restaurées dans les 3 chemins de sortie (fin normale,
      Abort, watchdog). Ne JAMAIS retirer cette sauvegarde/restauration.
   🧩 Même moteur allégé (CASE direct) que FB_ModesValidation — pas de StepTable/CheckTable.
   ============================================================================ *)

FUNCTION_BLOCK PUBLIC FB_SupervisionValidation
VAR_INPUT
    Start       : BOOL;
    Abort       : BOOL;
    CaseId      : INT; // 0=tous ; 1..5=cas ciblé
END_VAR
VAR_OUTPUT
    Busy              : BOOL;
    Done              : BOOL;
    AnyFailed         : BOOL;
    StepElapsed       : TIME;
    Report            : ST_TestSuiteReport;
    TerminalState     : E_TestTerminalState;
    ConfigError       : BOOL;
    ConfigErrorStepId : INT;
    ErrorCode         : INT;
    ErrorMessage      : STRING(160);
END_VAR
VAR
    StartPrev       : BOOL;
    Step            : INT;
    CurrentCaseId   : INT;
    RequestedCaseId : INT;
    StepStarted     : BOOL;
    StepTimer       : TON;
    StepLimit       : TIME;
    StepFailed      : BOOL;
    StepPassed      : BOOL;
    Index           : INT;

    // 🛡️ Sauvegardes obligatoires (voir §0/§1) — restaurées dans les 3 chemins de sortie.
    BackupSyncTolerance          : REAL;
    BackupSyncInitialized        : BOOL;
    BackupTranslationFreq        : REAL;
    BackupTranslationInitialized : BOOL;
END_VAR

// === IMPLEMENTATION ===

IF Abort THEN
    // 🛡️ Restauration obligatoire AVANT de sortir (voir §0).
    _SyncCfgPersist.CfgSyncTolerance_M := BackupSyncTolerance;
    GVL_IHM.M1M2Sync.Cfg.CfgSyncTolerance_M := BackupSyncTolerance;
    GVL_IHM.M1M2Sync.Cfg.Initialized := BackupSyncInitialized;
    _TranslationSetFreq_Hz := BackupTranslationFreq;
    GVL_IHM.TranslationM3.Cmd.SetFreq_Hz := BackupTranslationFreq;
    GVL_IHM.TranslationM3.Cmd.Initialized := BackupTranslationInitialized;
    GVL_IHM.Commun.ConfigRestoredFromPersistent := FALSE;
    GVL_IHM.Commun.BtnAckConfigRestored := FALSE;
    Busy := FALSE;
    Done := TRUE;
    AnyFailed := TRUE;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_ABORTED;
    Report.Aborted := TRUE;
    Report.AnyFailed := TRUE;
    Report.TerminalState := TerminalState;
    Report.FailureSummary := 'Supervision/Persistance : ABORTED';
    RETURN;
END_IF;

IF Start AND NOT StartPrev AND NOT Busy THEN
    StartPrev := TRUE;
    Busy := TRUE;
    Done := FALSE;
    AnyFailed := FALSE;
    ConfigError := FALSE;
    ErrorCode := 0;
    ErrorMessage := '';
    TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    IF CaseId < 0 OR CaseId > 5 THEN
        Busy := FALSE;
        Done := TRUE;
        AnyFailed := TRUE;
        ConfigError := TRUE;
        ErrorCode := 6001;
        ErrorMessage := 'Supervision CaseId invalide';
        TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        Report.TerminalState := TerminalState;
        Report.AnyFailed := TRUE;
        Report.ErrorCode := ErrorCode;
        Report.ErrorMessage := ErrorMessage;
        RETURN;
    END_IF;
    RequestedCaseId := CaseId;

    // 🛡️ Sauvegarde obligatoire AVANT toute modification (voir §0) — toujours faite, quel que
    // soit le cas demandé, pour rester sûr quel que soit le chemin de sortie emprunté.
    BackupSyncTolerance          := _SyncCfgPersist.CfgSyncTolerance_M;
    BackupSyncInitialized        := GVL_IHM.M1M2Sync.Cfg.Initialized;
    BackupTranslationFreq        := _TranslationSetFreq_Hz;
    BackupTranslationInitialized := GVL_IHM.TranslationM3.Cmd.Initialized;

    CASE RequestedCaseId OF
        1: Step := 10;
        2: Step := 20;
        3: Step := 30;
        4: Step := 40;
        5: Step := 50;
    ELSE
        Step := 10; // run all, démarre à TC-CP1
    END_CASE;
    Report.Name := 'Supervision / Persistance Config Validation';
    Report.InProgress := TRUE;
    Report.AllPassed := FALSE;
    Report.AnyFailed := FALSE;
    Report.Aborted := FALSE;
    Report.TerminalState := TerminalState;
    Report.ErrorCode := 0;
    Report.ErrorMessage := '';
    Report.FailureSummary := '';
    Report.CurrentStepId := Step;
    Report.Duration := T#0s;
    Report.RunCounter := Report.RunCounter + 1;
    FOR Index := 1 TO GVL_PLC_Tests_Const.MaxSteps DO
        Report.Steps[Index].Executed := FALSE;
        Report.Steps[Index].Passed := FALSE;
        Report.Steps[Index].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Steps[Index].Duration := T#0s;
    END_FOR;
    FOR Index := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        Report.Cases[Index].Executed := FALSE;
        Report.Cases[Index].Ok := FALSE;
        Report.Cases[Index].FailedStepId := 0;
        Report.Cases[Index].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Cases[Index].Duration := T#0s;
    END_FOR;
    StepStarted := FALSE;
ELSIF NOT Start THEN
    StartPrev := FALSE;
END_IF;

IF NOT Busy THEN
    RETURN;
END_IF;

StepElapsed := StepElapsed + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
Report.Duration := Report.Duration + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
Report.CurrentStepId := Step;
CurrentCaseId := (Step / 10);
Report.CurrentCaseId := CurrentCaseId;

IF NOT StepStarted THEN
    StepStarted := TRUE;
    StepElapsed := T#0s;
    CASE Step OF
        10: StepLimit := T#200MS;
        11: StepLimit := T#500MS;
        20: StepLimit := T#200MS;
        21: StepLimit := T#500MS;
        22: StepLimit := T#500MS;
        23: StepLimit := T#500MS;
        30: StepLimit := T#200MS;
        31: StepLimit := T#500MS;
        40, 41, 42, 43, 44: StepLimit := T#2S; // généreux : la vraie machine a pu booter juste avant ce test
        50: StepLimit := T#200MS;
        51: StepLimit := T#500MS;
        52: StepLimit := T#1S;
    ELSE
        ConfigError := TRUE;
        ConfigErrorStepId := Step;
        ErrorCode := 6002;
        ErrorMessage := 'Supervision étape inconnue';
        StepLimit := T#0s;
    END_CASE;
END_IF;

StepTimer(IN := TRUE, PT := StepLimit);

CASE Step OF
    // ─────────── TC-CP1 : Restauration PERSISTENT->IHM (M1M2Sync) ───────────
    10:
        // Arrange : valeur PERSISTENT sentinelle distincte du défaut réel (0.25), IHM au défaut
        // struct (0.0) + Initialized:=FALSE -> déclenche la restauration au prochain passage du
        // pont réel (PRG_09_Supervision.instCfgPersistBridgeSync, tourne chaque scan MainTask).
        _SyncCfgPersist.CfgSyncTolerance_M := 0.42;
        GVL_IHM.M1M2Sync.Cfg.CfgSyncTolerance_M := 0.0;
        GVL_IHM.M1M2Sync.Cfg.Initialized := FALSE;
        StepPassed := TRUE;
        Step := 11;
        StepStarted := FALSE;

    11:
        // Assert : Hmi restauré depuis Persist, Initialized repassé TRUE.
        IF (GVL_IHM.M1M2Sync.Cfg.CfgSyncTolerance_M = 0.42) AND GVL_IHM.M1M2Sync.Cfg.Initialized THEN
            StepPassed := TRUE;
            IF RequestedCaseId = 1 THEN Step := 0; ELSE Step := 20; END_IF;
            StepStarted := FALSE;
        END_IF;

    // ─────────── TC-CP2 : Alarme ConfigRestoredFromPersistent, doctrine reset=front ───────────
    20:
        // Arrange autonome : TC-CP2 doit aussi être exécutable seul (CaseId=2),
        // sans dépendre de la sentinelle créée par TC-CP1.
        _SyncCfgPersist.CfgSyncTolerance_M := 0.42;
        GVL_IHM.M1M2Sync.Cfg.CfgSyncTolerance_M := 0.0;
        GVL_IHM.M1M2Sync.Cfg.Initialized := FALSE; // déclenche restauration + alarme
        StepPassed := TRUE;
        Step := 21;
        StepStarted := FALSE;

    21:
        IF GVL_IHM.Commun.ConfigRestoredFromPersistent THEN
            StepPassed := TRUE;
            Step := 22;
            StepStarted := FALSE;
        END_IF;

    22:
        // L'alarme ne doit JAMAIS s'éteindre seule (doctrine reset=front, REX 2026-07-23).
        IF StepElapsed >= T#200MS THEN
            IF GVL_IHM.Commun.ConfigRestoredFromPersistent THEN
                StepPassed := TRUE;
                Step := 23;
                StepStarted := FALSE;
            ELSE
                StepFailed := TRUE; // régression doctrine reset=front
            END_IF;
        END_IF;

    23:
        // Acquittement par front opérateur.
        GVL_IHM.Commun.BtnAckConfigRestored := TRUE;
        IF NOT GVL_IHM.Commun.ConfigRestoredFromPersistent THEN
            GVL_IHM.Commun.BtnAckConfigRestored := FALSE;
            StepPassed := TRUE;
            IF RequestedCaseId = 2 THEN Step := 0; ELSE Step := 30; END_IF;
            StepStarted := FALSE;
        END_IF;

    // ─────────── TC-CP3 : Sauvegarde continue stable (pas de corruption) ───────────
    30:
        // Arrange autonome : TC-CP3 doit aussi être exécutable seul (CaseId=3).
        _SyncCfgPersist.CfgSyncTolerance_M := 0.42;
        GVL_IHM.M1M2Sync.Cfg.CfgSyncTolerance_M := 0.0;
        GVL_IHM.M1M2Sync.Cfg.Initialized := FALSE;
        StepPassed := TRUE;
        Step := 31;
        StepStarted := FALSE;

    31:
        IF StepElapsed >= T#200MS THEN
            IF (_SyncCfgPersist.CfgSyncTolerance_M = 0.42)
               AND (GVL_IHM.M1M2Sync.Cfg.CfgSyncTolerance_M = 0.42)
               AND GVL_IHM.M1M2Sync.Cfg.Initialized THEN
                StepPassed := TRUE;
                IF RequestedCaseId = 3 THEN Step := 0; ELSE Step := 40; END_IF;
                StepStarted := FALSE;
            ELSE
                StepFailed := TRUE; // Persist ou Hmi a dérivé -> corruption
            END_IF;
        END_IF;

    // ─────────── TC-CP4 : Balayage de couverture (lecture seule, sans risque) ───────────
    40:
        IF GVL_IHM.Cycle.Cfg.Initialized THEN
            StepPassed := TRUE; Step := 41; StepStarted := FALSE;
        END_IF;

    41:
        IF GVL_IHM.Commun.Cfg.Initialized THEN
            StepPassed := TRUE; Step := 42; StepStarted := FALSE;
        END_IF;

    42:
        IF GVL_IHM.M2TreuilBenne.Bucket.Cfg.Initialized THEN
            StepPassed := TRUE; Step := 43; StepStarted := FALSE;
        END_IF;

    43:
        IF GVL_IHM.M1TreuilRetenue.Cfg.Initialized THEN
            StepPassed := TRUE; Step := 44; StepStarted := FALSE;
        END_IF;

    44:
        IF GVL_IHM.M2TreuilBenne.Cfg.Initialized THEN
            StepPassed := TRUE;
            IF RequestedCaseId = 4 THEN Step := 0; ELSE Step := 50; END_IF;
            StepStarted := FALSE;
        END_IF;

    // ─────────── TC-CP5 : Translation SetFreq_Hz (pattern manuel, Lot 4 requis) ───────────
    50:
        _TranslationSetFreq_Hz := 12.5; // valeur sentinelle distincte du défaut réel (0.0)
        GVL_IHM.TranslationM3.Cmd.SetFreq_Hz := 0.0;
        GVL_IHM.TranslationM3.Cmd.Initialized := FALSE;
        StepPassed := TRUE;
        Step := 51;
        StepStarted := FALSE;

    51:
        IF (GVL_IHM.TranslationM3.Cmd.SetFreq_Hz = 12.5) AND GVL_IHM.TranslationM3.Cmd.Initialized THEN
            StepPassed := TRUE;
            Step := 52;
            StepStarted := FALSE;
        END_IF;

    52:
        // 🐛 Fix 2026-07-24 (échec réel constaté à l'exécution CODESYS) : l'ancien garde-fou externe
        // "IF ConfigRestoredFromPersistent THEN" pouvait sauter la détection de succès si l'alarme
        // s'éteignait (front BtnAckConfigRestored traité par PRG_09_Supervision) avant le scan suivant
        // de ce test -> blocage jusqu'au timeout. Vérification inconditionnelle, alignée sur TC-CP2 (23).
        GVL_IHM.Commun.BtnAckConfigRestored := TRUE;
        IF NOT GVL_IHM.Commun.ConfigRestoredFromPersistent THEN
            GVL_IHM.Commun.BtnAckConfigRestored := FALSE;
            StepPassed := TRUE;
            Step := 0;
            StepStarted := FALSE;
        END_IF;
END_CASE;

// Verdict local de l'étape : PASS, FAIL ou TIMEOUT contrôlé.
IF StepPassed OR StepFailed OR StepTimer.Q THEN
    IF StepPassed THEN
        Report.Steps[Report.CurrentStepId].Passed := TRUE;
        Report.Steps[Report.CurrentStepId].FailReason := E_TestFailReason.FAIL_NONE;
    ELSE
        Report.Steps[Report.CurrentStepId].Passed := FALSE;
        Report.Steps[Report.CurrentStepId].FailReason := SEL(StepFailed, E_TestFailReason.FAIL_TIMEOUT, E_TestFailReason.FAIL_CHECK);
        AnyFailed := TRUE;
    END_IF;
    Report.Steps[Report.CurrentStepId].Executed := TRUE;
    Report.Steps[Report.CurrentStepId].Duration := StepElapsed;
    IF NOT StepPassed THEN
        Step := 0; // Échec ou timeout = fin immédiate.
    END_IF;
    StepPassed := FALSE;
    StepFailed := FALSE;
    StepTimer(IN := FALSE, PT := StepLimit);
    StepElapsed := T#0s;
    IF Step = 0 THEN
        // 🛡️ Restauration obligatoire AVANT de sortir (voir §0) — fin normale ou échec/timeout.
        _SyncCfgPersist.CfgSyncTolerance_M := BackupSyncTolerance;
        GVL_IHM.M1M2Sync.Cfg.CfgSyncTolerance_M := BackupSyncTolerance;
        GVL_IHM.M1M2Sync.Cfg.Initialized := BackupSyncInitialized;
        _TranslationSetFreq_Hz := BackupTranslationFreq;
        GVL_IHM.TranslationM3.Cmd.SetFreq_Hz := BackupTranslationFreq;
        GVL_IHM.TranslationM3.Cmd.Initialized := BackupTranslationInitialized;
        GVL_IHM.Commun.ConfigRestoredFromPersistent := FALSE;
        GVL_IHM.Commun.BtnAckConfigRestored := FALSE;
        Busy := FALSE;
        Done := TRUE;
        Report.InProgress := FALSE;
        Report.AnyFailed := AnyFailed;
        Report.AllPassed := NOT AnyFailed;
        Report.TerminalState := SEL(AnyFailed, E_TestTerminalState.TEST_TERMINAL_DONE, E_TestTerminalState.TEST_TERMINAL_FAILED);
        TerminalState := Report.TerminalState;
        Report.Cases[1].Name := 'TC-CP1..CP5 Persistance Config';
        Report.Cases[1].Executed := TRUE;
        Report.Cases[1].Ok := NOT AnyFailed;
        Report.Cases[1].FailedStepId := 0;
        Report.Cases[1].FailReason := E_TestFailReason.FAIL_NONE;
        IF AnyFailed THEN
            Report.Cases[1].FailedStepId := Report.CurrentStepId;
            Report.Cases[1].FailReason := E_TestFailReason.FAIL_CHECK;
            Report.FailureSummary := CONCAT('Supervision/Persistance : échec étape ', INT_TO_STRING(Report.CurrentStepId));
        END_IF;
        Report.Cases[1].Duration := Report.Duration;
    ELSE
        StepStarted := FALSE;
    END_IF;
END_IF;

// Limite globale de sécurité de la suite : 90 s maximum.
IF Report.Duration >= T#90s AND Busy THEN
    // 🛡️ Restauration obligatoire AVANT de sortir (voir §0) — watchdog.
    _SyncCfgPersist.CfgSyncTolerance_M := BackupSyncTolerance;
    GVL_IHM.M1M2Sync.Cfg.CfgSyncTolerance_M := BackupSyncTolerance;
    GVL_IHM.M1M2Sync.Cfg.Initialized := BackupSyncInitialized;
    _TranslationSetFreq_Hz := BackupTranslationFreq;
    GVL_IHM.TranslationM3.Cmd.SetFreq_Hz := BackupTranslationFreq;
    GVL_IHM.TranslationM3.Cmd.Initialized := BackupTranslationInitialized;
    GVL_IHM.Commun.ConfigRestoredFromPersistent := FALSE;
    GVL_IHM.Commun.BtnAckConfigRestored := FALSE;
    Busy := FALSE;
    Done := TRUE;
    AnyFailed := TRUE;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_WATCHDOG_TIMEOUT;
    Report.InProgress := FALSE;
    Report.AnyFailed := TRUE;
    Report.AllPassed := FALSE;
    Report.TerminalState := TerminalState;
    Report.ErrorCode := 6003;
    Report.ErrorMessage := 'Watchdog Supervision/Persistance expiré';
    Report.FailureSummary := Report.ErrorMessage;
END_IF;

(* 🛡️ Raisons mémorisées de la barrière finale frein/puissance treuil. *)
{attribute 'qualified_only'}
TYPE E_WinchFinalInterlockReason :
(
    NONE := 0,
    BRAKE_COMMAND_NOT_CONFIRMED := 1,
    RESTART_INHIBITED := 2
);
END_TYPE

(* ═══════════════════════════════════════════════════════════════
   🛡️ FB_TranslationOutputInterlock_LD — Barrière finale frein / AC600 M3
   ───────────────────────────────────────────────────────────────
   📥 Reçoit exclusivement les demandes métier de FB_Translation.
   📤 Produit seul les commandes AC600 et frein vers PRG_10_Outputs_LD.
   🔒 BrakeCommandOpenConfirmed confirme le contacteur/bobine de desserrage,
      jamais la position mécanique du frein.
   ⏱️ Watchdog fixe T#500ms, démarré uniquement par BrakeReleaseRequest.
   🔑 Après timeout, RestartInhibit exige : Reset avec cause disparue,
      demande neutre explicite (mot 0), puis nouvelle demande 1 ou 2.
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_TranslationOutputInterlock_LD
VAR_INPUT
    Enable                       : BOOL;
    Reset                        : BOOL;
    PowerContactorEngaged              : BOOL;
    SafeStop                     : BOOL;
    BrakeReleaseRequest          : BOOL;
    BrakeCommandOpenConfirmed    : BOOL;
    RequestedDriveControlWord    : WORD; // 0=None, 1=Fwd, 2=Rev, 7=Reset AC600
    RequestedDriveFreqHz         : REAL;
END_VAR
VAR_OUTPUT
    Ready                        : BOOL;
    Busy                         : BOOL;
    Done                         : BOOL;
    Error                        : BOOL;
    ErrorId                      : WORD; // bit0 : absence confirmation contacteur desserrage > 500 ms
    State                        : E_State;
    StateAtError                 : E_State;
    Reason                       : E_TranslationFinalInterlockReason;
    BrakeTimeoutElapsed          : TIME;
    RestartInhibit               : BOOL; // TRUE : neutralisation puis nouvelle demande exigées après défaut
    DriveControlWord             : WORD;
    DriveFreqRefHz               : REAL;
    BrakeCmd                     : BOOL;
END_VAR
VAR
    ResetEdge                    : R_TRIG;
    ErrorEdge                    : R_TRIG;
    BrakeTimeout                 : TON;
    MovementRequested            : BOOL;
    NeutralRequestSeen           : BOOL;
    ResetRequired                : BOOL; // Timeout : front Reset obligatoire avant toute nouvelle marche
END_VAR

// ── 1. FRONT RESET AVANT GATE ───────────────────────────────────────────
// Le front est échantillonné même pendant Enable/AU faux. Un Reset maintenu
// durant une gate ne peut donc jamais devenir un faux acquittement au retour.
ResetEdge(CLK := Reset);

// RestartInhibit et ResetRequired sont volontairement conservés : un changement
// Enable/AU ne doit jamais réautoriser automatiquement le mouvement après timeout.
IF NOT Enable OR NOT PowerContactorEngaged THEN
    BrakeTimeout(IN := FALSE, PT := T#500ms);
    DriveControlWord := 0;
    DriveFreqRefHz := 0.0;
    BrakeCmd := FALSE;
    BrakeTimeoutElapsed := T#0ms;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    // ErrorId reste publiquement visible même hors Enable/AU : une retombée de gate
    // ne doit jamais masquer un timeout mémorisé ni remplacer l'acquittement conscient.
    Error := (ErrorId <> 16#0000);
    State := E_State.DISABLED;
    Reason := E_TranslationFinalInterlockReason.NONE;
    RETURN;
END_IF;

MovementRequested := (RequestedDriveControlWord = 1) OR (RequestedDriveControlWord = 2);

// ── 2. Watchdog : exclusivement après ordre effectif de desserrage ──────
// Pendant RestartInhibit, BrakeCmd reste coupé : l'ordre amont n'est donc plus
// effectif et le watchdog ne doit pas créer une nouvelle faute en boucle.
BrakeTimeout(IN := BrakeReleaseRequest AND NOT BrakeCommandOpenConfirmed
                   AND NOT RestartInhibit, PT := T#500ms);
BrakeTimeoutElapsed := BrakeTimeout.ET;
IF BrakeTimeout.Q THEN
    ErrorId := ErrorId OR 16#0001;
    RestartInhibit := TRUE;
    ResetRequired := TRUE;
    NeutralRequestSeen := FALSE;
    Reason := E_TranslationFinalInterlockReason.BRAKE_COMMAND_NOT_CONFIRMED;
ELSIF ResetEdge.Q AND BrakeCommandOpenConfirmed THEN
    ErrorId := ErrorId AND 16#FFFE;
    ResetRequired := FALSE;
END_IF;

Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// ── 3. Réarmement anti-redémarrage automatique ──────────────────────────
// Le mot 7 est un reset AC600, pas un neutre opérateur : il reste autorisé avec
// fréquence nulle mais ne solde pas RestartInhibit. Seul le mot 0, vu APRÈS
// disparition de la cause et front Reset, autorise ensuite une nouvelle demande.
IF RestartInhibit AND NOT Error AND NOT ResetRequired AND NOT ResetEdge.Q THEN
    IF RequestedDriveControlWord = 0 THEN
        NeutralRequestSeen := TRUE;
    ELSIF NeutralRequestSeen AND MovementRequested THEN
        RestartInhibit := FALSE;
        NeutralRequestSeen := FALSE;
    END_IF;
END_IF;

// ── 4. Décision finale : zéro couple utile sans confirmation frein ──────
DriveControlWord := 0;
DriveFreqRefHz := 0.0;
// SafeStop est traité en amont par FB_Translation : rampe rapide avec Enable
// maintenu. La commande/frein suivent cette rampe jusqu'à demande nulle ; seul
// un gate dur, timeout ou défaut final impose ici la coupure immédiate.
BrakeCmd := BrakeReleaseRequest AND NOT Error AND NOT RestartInhibit;
Ready := NOT Error AND NOT RestartInhibit;
Busy := FALSE;
Done := FALSE;
State := E_State.READY;

IF Error THEN
    BrakeCmd := FALSE;
    State := E_State.DISABLED;
ELSIF RequestedDriveControlWord = 7 THEN
    // Reset AC600 préservé, toujours sans consigne fréquence ni couple utile.
    DriveControlWord := 7;
ELSIF RestartInhibit THEN
    Reason := E_TranslationFinalInterlockReason.RESTART_INHIBITED;
    State := E_State.INIT;
ELSIF MovementRequested THEN
    // Double condition obligatoire : ordre effectif de desserrage ET confirmation
    // contacteur/bobine. Une confirmation résiduelle seule ne peut jamais autoriser
    // couple ou fréquence AC600.
    IF BrakeReleaseRequest AND BrakeCommandOpenConfirmed THEN
        DriveControlWord := RequestedDriveControlWord;
        DriveFreqRefHz := MAX(0.0, RequestedDriveFreqHz);
        Busy := TRUE;
        State := E_State.BUSY;
    ELSE
        Busy := TRUE;
        State := E_State.INIT;
    END_IF;
END_IF;

(* =======================================================================
   ⚙️ FB_Encoder_SpeedMeasure — Mesure de vitesse câble horodatée
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Calcul de la vitesse absolue et signée sur fenêtre glissante horodatée
   🔒 Polarité : Valid=TRUE après 6 échantillons couvrant au moins 50ms
   📄 Doc métier : DOC/AF/AF_Partie-09_Fonction_Encoder_v2.1.md
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_Encoder_SpeedMeasure
VAR_INPUT
    // === COMMANDES & AUTORISATIONS ===
    Enable              : BOOL;        // --> [CMD] Autorisation generale FB (TRUE=Autorise)
    Reset               : BOOL;        // --> [CMD] Purge immediate de l'historique (front montant)

    // === MESURE SURES EN ENTREE ===
    Position_M          : REAL;        // --> [HW]  Position cable sure en metres (FB_Encoder_Safety)
    PositionValid       : BOOL;        // --> [SAFE] Validite de la chaine codeur
END_VAR
VAR_OUTPUT
    // === VITESSE CALCULÉE & VALIDITE ===
    Speed_Mps           : REAL;        // <-- [DIAG] Vitesse absolue sur la fenetre glissante (m/s)
    SignedSpeed_Mps     : REAL;        // <-- [DIAG] Vitesse signee (+ montee, - descente) (m/s)
    Valid               : BOOL;        // <-- [STAT] Vitesse valide (6 ech. sur 50 ms)
END_VAR
VAR
    // === HISTORIQUE & ECHANTILLONS ===
    Positions_M         : ARRAY[0..5] OF REAL; // . [LOC] Tableau des 6 positions enregistrees
    Timestamps          : ARRAY[0..5] OF TIME; // . [LOC] Horodatage associe aux 6 positions

    // === HORODATAGE & TEMPORISATION ===
    CurrentTimestamp    : TIME;        // . [LOC] Horodatage courant du cycle
    LastTimestamp       : TIME;        // . [LOC] Horodatage de l'echantillon precedent
    ElapsedSinceSample  : TIME;        // . [LOC] Temps ecoule depuis le dernier echantillon
    WindowElapsed       : TIME;        // . [LOC] Temps total ecoule sur la fenetre de mesure

    // === COMPTEURS & ETATS INTERNES ===
    CollectedSamples    : INT;         // . [LOC] Nombre d'echantillons collectes dans la fenetre
    Index               : INT;         // . [LOC] Index de boucle de decalage
    TimestampInitialized: BOOL;        // . [LOC] Indicateur d'initialisation du premier horodatage
END_VAR
VAR CONSTANT
    // === PARAMETRES DE LA FENETRE GLISSANTE ===
    WindowTime          : TIME := T#50MS; // Fenetre glissante de mesure
    SamplePeriod        : TIME := T#10MS; // Periode minimale entre deux echantillons
    SampleCount         : INT := 6;       // Nombre total d'echantillons requis
END_VAR

{region "§1 Horodatage et purge"}
// ⏱️ Horodatage natif : le calcul utilise le temps réellement écoulé, jamais un cycle supposé.
CurrentTimestamp := TIME();

// Purge des six positions sur rupture de confiance : aucune source antérieure ne peut contaminer la mesure.
IF NOT Enable OR Reset OR NOT PositionValid THEN
    Speed_Mps := 0.0;
    SignedSpeed_Mps := 0.0;
    Valid := FALSE;
    CollectedSamples := 0;
    TimestampInitialized := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Première position"}
// 🕒 Première position de la nouvelle fenêtre.
IF NOT TimestampInitialized THEN
    Positions_M[0] := Position_M;
    Timestamps[0] := CurrentTimestamp;
    LastTimestamp := CurrentTimestamp;
    CollectedSamples := 1;
    TimestampInitialized := TRUE;
    Speed_Mps := 0.0;
    SignedSpeed_Mps := 0.0;
    Valid := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§3 Rebouclage TIME"}
// 🛡️ Rebouclage de TIME détecté localement : purge sans réutiliser le delta aberrant.
IF CurrentTimestamp < LastTimestamp THEN
    Positions_M[0] := Position_M;
    Timestamps[0] := CurrentTimestamp;
    LastTimestamp := CurrentTimestamp;
    CollectedSamples := 1;
    Speed_Mps := 0.0;
    SignedSpeed_Mps := 0.0;
    Valid := FALSE;
    RETURN;
END_IF;

ElapsedSinceSample := CurrentTimestamp - LastTimestamp;

// 🛡️ Delta nul : aucune division et aucun doublon d'échantillon.
IF ElapsedSinceSample <= T#0MS THEN
    RETURN;
END_IF;
{endregion}

{region "§4 Collecte échantillons"}
// 📥 Six positions espacées d'au moins 10 ms donnent cinq intervalles sur la fenêtre interne de 50 ms.
IF ElapsedSinceSample >= SamplePeriod THEN
    LastTimestamp := CurrentTimestamp;

    IF CollectedSamples < SampleCount THEN
        Positions_M[CollectedSamples] := Position_M;
        Timestamps[CollectedSamples] := CurrentTimestamp;
        CollectedSamples := CollectedSamples + 1;
    ELSE
        FOR Index := 0 TO 4 DO
            Positions_M[Index] := Positions_M[Index + 1];
            Timestamps[Index] := Timestamps[Index + 1];
        END_FOR;
        Positions_M[5] := Position_M;
        Timestamps[5] := CurrentTimestamp;
    END_IF;
{endregion}

{region "§5 Calcul vitesse"}
    IF CollectedSamples = SampleCount THEN
        // 🛡️ Ordre temporel et durée minimale contrôlés avant toute conversion/division.
        IF Timestamps[5] >= Timestamps[0] THEN
            WindowElapsed := Timestamps[5] - Timestamps[0];
            IF WindowElapsed >= WindowTime THEN
                SignedSpeed_Mps := (Positions_M[5] - Positions_M[0])
                                   / (UDINT_TO_REAL(TIME_TO_UDINT(WindowElapsed)) / 1000.0);
                Speed_Mps := ABS(SignedSpeed_Mps);
                Valid := TRUE;
            ELSE
                Speed_Mps := 0.0;
                SignedSpeed_Mps := 0.0;
                Valid := FALSE;
            END_IF;
        ELSE
            Speed_Mps := 0.0;
            SignedSpeed_Mps := 0.0;
            Valid := FALSE;
            CollectedSamples := 0;
            TimestampInitialized := FALSE;
        END_IF;
    END_IF;
END_IF;
{endregion}

(* ═══════════════════════════════════════════════════════════════
   📡 PRG_01_Diagnostics — États bus de terrain et Joystick (PROGRAMME)
   ───────────────────────────────────────────────────────────────
   ⚙️ Exécuté par la tâche PLC en position 1.
   ═══════════════════════════════════════════════════════════════
   📄 Docs : DOC/AF_Partie-02_Architecture_Programme_v3.0.md ; DOC/AF_Partie-08_Fonction_Joystick_v2.0.md
*)

PROGRAM PRG_01_Diagnostics
VAR
    instDiagCanOpen  : FB_Diag_CanOpen;       // Diagnostic CAN/Joystick
    instDiagEthercat : FB_Diag_Ethercat;      // Diagnostic EtherCAT (3 devices)
    instJoystick    : FB_Joystick;          // Traitement joystick (calib/filtre/rampe)
    instIhmHeartbeat : FB_Diag_IhmHeartbeat;      // 💓 Surveillance IHM↔PLC, consommée par PRG_SAFETY_CFC

    // 🆕 REX 2026-07-24 (demande utilisateur, mise en service) : capture UNIQUE par cycle des
    // valeurs brutes bus (évite d'appeler GetBusState()/GetDeviceState() deux fois par device).
    // 📄 Lot L5 : données remises dans HwIn par PRG_00 §0.
    RawCanBusState    : INT;          // CANbus.GetBusState() brut
    RawJoystickState  : DEVICE_STATE; // JOY1_JOYSTICK_MCB560_CO4201A.GetDeviceState() brut
    RawVariateurState : DEVICE_STATE; // AC600_ECAT_Drive.GetDeviceState() brut
    RawEncoderM1State : DEVICE_STATE; // COD1_CODEUR.GetDeviceState() brut
    RawEncoderM2State : DEVICE_STATE; // COD2_CODEUR.GetDeviceState() brut
END_VAR

// === IMPLEMENTATION (corps du PROGRAM PRG_01_Diagnostics) ===


// 🔧 REX 2026-07-24 (demande utilisateur, mise en service) : REFONTE — PRG_01 lit les valeurs brutes bus
// depuis l'image matérielle HwIn produite par PRG_02_Acquisition_CFC.
// C'est FB_Diag_CanOpen/FB_Diag_Ethercat qui décident désormais seuls Online/Operational/State
// (distinction INIT normal / SIMULATED bypass / READY réel / ERROR — voir en-tête de ces FB).
RawCanBusState    := PRG_02_Acquisition_CFC.HwIn.Operator.CanBusState;
RawJoystickState  := PRG_02_Acquisition_CFC.HwIn.Operator.JOY1_DeviceState;
RawVariateurState := PRG_02_Acquisition_CFC.HwIn.Translation.AC600_DeviceState;
RawEncoderM1State := PRG_02_Acquisition_CFC.HwIn.Winch.COD1_DeviceState;
RawEncoderM2State := PRG_02_Acquisition_CFC.HwIn.Winch.COD2_DeviceState;

// 1. Diagnostics CANopen — 🆕 REX 2026-07-08 : gardé par BusJoystickIsReal UNIQUEMENT (bus/nœud),
// indépendant de BusJoystickSignalIsReal (signal brut ci-dessus) — granularité séparée.
instDiagCanOpen(
    Enable := TRUE,
    Reset := PRG_SUPERVISION_CFC.FaultMachineReset_IHM,
    CANbusStateRaw := RawCanBusState,
    DeviceJoystickStateRaw := RawJoystickState,
    SimBypassActive := FALSE,
    NetworkBypassActive := GVL_IHM.Network.Bypass.Global
);

// 2. Diagnostics EtherCAT (variateur + 2 codeurs)
instDiagEthercat(
    Enable := TRUE,
    Reset := PRG_SUPERVISION_CFC.FaultMachineReset_IHM,          // 🔑 Bouton général machine
    DeviceVariateurStateRaw := RawVariateurState,
    DeviceVariateurSimBypass := FALSE,
    DeviceEncoderM1StateRaw := RawEncoderM1State,
    DeviceEncoderM1SimBypass := FALSE,
    DeviceEncoderM2StateRaw := RawEncoderM2State,
    DeviceEncoderM2SimBypass := FALSE,
    NetworkBypassActive := GVL_IHM.Network.Bypass.Global
);

// 💓 2bis. Heartbeat IHM↔PLC (Fix CK6 : secours BlinkClock si IhmHeartbeat bypassé ou pas d'IHM)
instIhmHeartbeat(
    Enable := TRUE,
    TglHeartbeatIhm := SEL(GVL_IHM.Network.Bypass.IhmHeartbeat OR GVL_IHM.Network.Bypass.Global,
                           GVL_IHM.Commun.TglHeartbeatIhm,
                           GVL_Global.BlinkClock),
    IhmTimeout := T#2s,
    PlcTogglePeriod := T#500ms
);

// 3. Acquisition Joystick — RawX/RawY/RawButton lus depuis PRG_02_Acquisition_CFC.HwIn.Operator
instJoystick(
    Enable              := TRUE,
    PowerContactorEngaged     := PRG_01_Inputs_LD.PowerContactorEngaged,
    Reset               := PRG_SUPERVISION_CFC.FaultMachineReset_IHM,
    Mode                := PRG_MODES_CFC.Auth.Mode,  // 🆕 REX 2026-07-08 : désarme le homme-mort au changement de mode
    BenneBusy         := PRG_TREUILS_CFC.instBucket.Busy,
    PreserveArmingAfterBucket := PRG_TREUILS_CFC.instExtractionSequence.Busy
                                  AND (PRG_TREUILS_CFC.instExtractionSequence.ExtractionState = E_ExtractionSequenceState.CLOSING_BUCKET),
    NeutralXMem         := _JoystickNeutralX,
    NeutralYMem         := _JoystickNeutralY,
    BusCanOpenOP        := instDiagCanOpen.DeviceCanOpenMaster,
    JoystickOP          := instDiagCanOpen.DeviceJoystick,
    RawX                := PRG_02_Acquisition_CFC.HwIn.Operator.JoyXRaw_ANA1,
    RawY                := PRG_02_Acquisition_CFC.HwIn.Operator.JoyYRaw_ANA2,
    RawButton           := PRG_02_Acquisition_CFC.HwIn.Operator.JoyBtnRaw,
    BtnCalibrate           := GVL_IHM.JOY1Joystick.Cmd.BtnCalibrate,
    InvertX             := _JoystickInvertX,       // depuis GVL_PERSISTENT
    InvertY             := _JoystickInvertY,       // idem
    Deadband            := _JoystickDeadband_Pct,  // depuis GVL_PERSISTENT
    FilterTime          := _JoystickFilterTime,    // idem
    // 🛡️ Délais de sécurité Homme-Mort : réordonnés aux valeurs réelles de production (10s / 500ms)
    DeadmanRearmTimeout := T#10S,
    NeutralHoldTime     := T#500MS
);

SETUP
VAR
    fb : FB_JOYSTICK;
    nx : INT := 5000;
    ny : INT := 5000;
    diagOk : ST_DIAG_DEVICE;
    diagDown : ST_DIAG_DEVICE;
END_VAR
END_SETUP

TEST 'TC-P08-001 Perte bus CAN pendant un mouvement arme neutralise, desarme et leve Error (auto-efface au retour)'
    diagDown.ONLINE := FALSE; diagDown.OPERATIONAL := FALSE; diagDown.ERROR := FALSE;
    diagDown.ERRORID := 0; diagDown.STATE := E_DIAG_STATE.INIT; diagDown.STATEATERROR := E_DIAG_STATE.DISABLED;
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;
    nx := 5000; ny := 5000;

    (* arme le geste au neutre, bus sain *)
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ADVANCE_TIME(110000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, 'precondition : geste arme');

    (* deplace le joystick : mouvement actif, bus toujours sain *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 60.0, 0.01, 'mouvement actif : consigne non nulle (RawX=8000, Neutral=5000)');
    ASSERT_EQ(fb.AXISCMDX.DIRECTION, 1, 'sens avant pendant le mouvement');
    ASSERT_NEAR(fb.AXISCMDY.SPEEDREF, 0.0, 0.01, 'RawY au neutre : axe Y reste a 0, aucun couplage entre les axes');
    ASSERT_EQ(fb.AXISCMDY.DIRECTION, 0, 'axe Y au neutre : Direction=0');

    (* perte du bus CAN EN PLEIN MOUVEMENT : neutralisation immediate + desarmement *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagDown, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.READY, 'bus CAN non operationnel doit bloquer Ready');
    ASSERT_TRUE(fb.ERROR, 'perte de comm doit lever Error (AF08)');
    ASSERT_EQ(fb.ERRORID, 16#0004, 'bit2 : HW/bus non operationnel');
    ASSERT_FALSE(fb.AXISCMDX.ENABLE, 'sorties axe X neutralisees des la perte du bus, meme en plein mouvement');
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 0.0, 0.01, 'consigne X coupee immediatement, pas de decel progressive');
    ASSERT_FALSE(fb.AXISCMDY.ENABLE, 'sorties axe Y aussi neutralisees (gate global, pas seulement l axe en mouvement)');
    ASSERT_NEAR(fb.AXISCMDY.SPEEDREF, 0.0, 0.01, 'consigne Y aussi coupee');
    ASSERT_FALSE(fb.DEADMANARMED, 'le geste est desarme par la perte du bus (AF08 TC-P08-001)');

    (* bus revient : pas de rearmement automatique, nouvel appui conscient exige *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.READY, 'bus revenu : FB de nouveau pret');
    ASSERT_FALSE(fb.ERROR, 'bus revenu : Error auto-effacee sans geste operateur (categorie Info/Warning, pas un Fault a acquitter)');
    ASSERT_EQ(fb.ERRORID, 0, 'bit2 efface automatiquement');
    ASSERT_FALSE(fb.DEADMANARMED, 'pas de rearmement automatique au retour du bus : nouvel appui conscient exige');
END_TEST

TEST 'TC-P08-002 Maintien DeadmanArmHoldTime : arme si tenu 100ms, annule si relache avant'
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;

    (* baseline : neutre, bouton relache *)
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'baseline : bouton relache, pas arme');

    (* front bouton : demarre le maintien, pas encore arme *)
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'front bouton seul ne doit pas armer immediatement (maintien requis)');

    (* 50ms plus tard : maintien pas termine -- l operateur bouge DEJA l axe X seul (Y reste
       neutre) pendant l attente : aucune commande ne doit partir tant que ce n est pas arme *)
    ADVANCE_TIME(50000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, '50ms < DeadmanArmHoldTime (100ms) : pas encore arme');
    ASSERT_NEAR(fb.CMDXVAL, 0.0, 0.01, 'consigne interne X (CmdXVal) forcee a 0 : pas encore arme');
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 0.0, 0.01, 'axe X seul pousse (RawX=8000, RawY neutre) mais pas encore arme : aucune commande ne part');

    (* 20ms de plus (toujours < 100ms) : cette fois l axe Y seul est pousse (X revient au
       neutre) -- meme preuve, isolee sur l autre axe *)
    ADVANCE_TIME(20000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 2000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, '70ms < DeadmanArmHoldTime (100ms) : toujours pas arme');
    ASSERT_NEAR(fb.CMDYVAL, 0.0, 0.01, 'consigne interne Y (CmdYVal) forcee a 0 : pas encore arme');
    ASSERT_NEAR(fb.AXISCMDY.SPEEDREF, 0.0, 0.01, 'axe Y seul pousse (RawY=2000, RawX neutre) mais pas encore arme : aucune commande ne part');

    (* relache a 50ms, avant la fin des 100ms de maintien : annule la tentative *)
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'relachement avant la fin du maintien annule la tentative');

    (* le bouton reste relache PENDANT 1s ENTIERE, manche pousse a fond (RawX=8000) tout du
       long : aucun armement differe, et surtout aucune commande de mouvement ne demarre,
       meme apres une longue attente sur une position hors neutre *)
    ADVANCE_TIME(1000000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'pas d armement differe sur une tentative deja annulee, meme apres 1s (nouvel appui conscient exige)');
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 0.0, 0.01, 'manche a fond depuis 1s mais jamais arme : toujours aucune commande de mouvement');

    (* nouveau front + maintien complet (110ms) : l armement redevient possible normalement *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ADVANCE_TIME(110000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, '110ms >= DeadmanArmHoldTime (100ms) : geste arme');
END_TEST

TEST 'TC-P08-004 Delai de grace protege l armement au neutre, puis le neutre prolonge desarme apres la grace'
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;

    (* nx/ny fixes explicitement a 5000 avant CHAQUE appel : STruCpp ne re-copie PAS la sortie
       VAR_IN_OUT vers la variable de test entre deux appels fb() (limite outillage constatee,
       round-trip IN_OUT absent -- cf. README). Sans ce forcage, NeutralXMem retomberait a 0
       (valeur SETUP jamais appliquee non plus) des le 2e scan, et AtNeutral resterait FALSE. *)
    nx := 5000; ny := 5000;

    (* arme le geste au neutre *)
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ADVANCE_TIME(110000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, 'precondition : geste arme');

    (* bouton relache, reste au neutre : 500ms plus tard (largement > NeutralHoldTime seul 100ms) mais < grace (3s) *)
    ADVANCE_TIME(500000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, 'la grace (3s) protege l armement malgre un neutre deja tenu bien plus longtemps que NeutralHoldTime seul (evite le REX terrain : desarmement 100-200ms apres l armement)');

    (* 2.6s de plus (total 3.1s depuis l armement) : la grace vient de s ecouler ce scan meme --
       NeutralHoldTimer ne fait que DEMARRER (son IN passe a TRUE ce scan), pas encore Q *)
    ADVANCE_TIME(2600000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, 'grace tout juste ecoulee : NeutralHoldTimer demarre seulement ce scan (pas encore ecoule)');

    (* 100ms de plus (NeutralHoldTime ecoule depuis la fin de la grace) : desarme *)
    ADVANCE_TIME(100000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'grace ecoulee (3s) + neutre tenu (NeutralHoldTime) : desarmement');
END_TEST

