// ═══════════════════════════════════════════════════════════════
// 🧪 FB_TranslationTestFixture — Précondition Translation M3
// ───────────────────────────────────────────────────────────────
// 🎯 Responsabilité UNIQUE : décider si un Start est recevable
//    (Niveaux 1/2 de la défense en profondeur, AF_Partie-14 §7.3.3) :
//    simulation active + aucune E/S M3 recâblée réelle. Ne fait AUCUNE
//    attente d'état sain (ça reste la responsabilité de l'étape SETUP
//    de chaque cas, via FB_TranslationStepExecutor — §7.3.5).
// 🔒 Un refus ici est TOUJOURS explicite (PRECONDITION_FAILED),
//    jamais un silence (audit v1.0 C3).
// ═══════════════════════════════════════════════════════════════

FUNCTION_BLOCK PUBLIC FB_TranslationTestFixture
VAR_INPUT
    CheckRequested        : BOOL; // Front : nouvelle vérification demandée (sur Start suite)
    SimulationModeActive  : BOOL;
    SimGateOk             : BOOL; // Niveau 2 : aucune E/S M3 (*IsReal) incompatible
END_VAR
VAR_OUTPUT
    FixturePassed  : BOOL;
    FixtureFailed  : BOOL;
    FailReason     : STRING(120);
END_VAR
VAR
    CheckTrig : R_TRIG;
END_VAR
// === IMPLEMENTATION ===
CheckTrig(CLK := CheckRequested);

IF CheckTrig.Q THEN
    IF NOT SimulationModeActive THEN
        FixturePassed := FALSE;
        FixtureFailed := TRUE;
        FailReason := 'Simulation non active (GVL_Simulation.SimulationModeActive=FALSE)';
    ELSIF NOT SimGateOk THEN
        FixturePassed := FALSE;
        FixtureFailed := TRUE;
        FailReason := 'E/S M3 recablees reelles (*IsReal) incompatibles avec le banc de test';
    ELSE
        FixturePassed := TRUE;
        FixtureFailed := FALSE;
        FailReason := '';
    END_IF;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   📥 FB_Input — Entrée TOR conditionnée (brique réduite)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-06_Acquisition_Qualification_IO_v2.1.md §1
   🧭 Interface RÉDUITE (Partie3 §1bis) : pas de contrat FB standard
      complet (pas d'Enable/StartStop/Mode/State/StateAtError) — brique
      de conditionnement bas niveau, à instancier en tableau (§3) ou
      composée directement dans un FB métier.
   🔁 Rôle : inversion NO/NC, filtrage anti-rebond, diagnostic voie/carte.
   ✅ TRANCHÉ 2026-08-04 : diagnostic carte disponible au niveau MODULE (pas canal) via
      `GetDeviceState()` sur les 3 supports DI (`Local_Digital_IO`, `VH_0800END`, `VH_0808ETP`).
      `ChannelOk` reste à sa valeur par défaut `TRUE` (pas de source par canal individuel
      disponible matériellement) — le diagnostic module est porté séparément par
      `PRG_02_Acquisition` (voir AF06 §3bis), pas par cette brique. Limitation assumée,
      pas un oubli : documentation à revoir si un module diagnostiquant chaque canal est
      installé.
      Intégration dans Winch/Translation : composition directe dans `PRG_04`/`PRG_05` via
      `InputModuleFault` → `SafeStop`, pas de FB_IO générique séparé.
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Input) ===

FUNCTION_BLOCK PUBLIC FB_Input
VAR_INPUT
    InputRaw    : BOOL;         // Signal brut carte d'entrée
    InvertLogic : BOOL;         // TRUE = NC (logique inversée)
    FilterTime  : TIME;         // Tempo anti-rebond (filtrage)
    ChannelOk   : BOOL := TRUE; // Diag voie/carte OK (§4) — TRUE par défaut si pas de diag dispo
END_VAR
VAR_OUTPUT
    State : BOOL;         // Signal conditionné, prêt à l'emploi
    Error       : BOOL;         // Voie en défaut (ChannelOk faux)
    ErrorId     : WORD;         // bit0: "Défaut matériel entrée (Carte HS)" - voie/carte HS
END_VAR
VAR
    FilterTon     : TON;
    ValueRaw      : BOOL;
    FirstScanDone : BOOL;
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Input) ===

// 1. Inversion NO/NC
ValueRaw := InputRaw XOR InvertLogic;

// 2. Initialisation premier scan & Filtrage anti-rebond
// Au premier scan post-boot, State prend directement la valeur saine brute sans attendre le délai de 20ms,
// ce qui évite d'émettre des fausses alarmes transitoires au démarrage de l'automate.
IF NOT FirstScanDone THEN
    State := ValueRaw;
    FirstScanDone := TRUE;
ELSE
    FilterTon(IN := (ValueRaw <> State), PT := FilterTime);
    IF FilterTon.Q THEN
        State := ValueRaw;   // Une fois à jour, IN redevient FALSE au cycle suivant (ValueRaw=State)
    END_IF;
END_IF;

// 3. Diagnostic voie/carte
IF NOT ChannelOk THEN
    ErrorId := ErrorId OR 16#0001;
    // State conserve sa dernière valeur (hold) — le consommateur décide l'état sûr via Error.
    // FB_Input ne force pas State : il ne connaît pas l'état sûr du signal.
ELSE
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

Error := (ErrorId <> 16#0000);

(* ═══════════════════════════════════════════════════════════════
   🛡️ FB_Safety_EmergencyManagement — Bloc Safety Composite (Parent)
   ───────────────────────────────────────────────────────────────
   📄 Rôle : Bloc de sécurité principal de la boucle d'arrêt d'urgence.
   🧩 Encapsule la Logique (FB_Safety_EmergencyManagementLogic) et le
      Pilote Physique (FB_Safety_EmergencyManagementOutput) par composition.
   📤 Produit les bus publics ST_Safety_Emergency_State et ST_Safety_Emergency_Diag
      en sortie, consommés par Supervision et Troubleshooting.
   🔒 Sorties physiques MaintainA/B_RQ en polarité maintien (TRUE = voie saine).
   ═══════════════════════════════════════════════════════════════
    📄 Docs : DOC/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md
              DOC/AF_Partie-03_Contrats_Composants_v2.1.md
*)

FUNCTION_BLOCK PUBLIC FB_Safety_EmergencyManagement
VAR_INPUT
    Enable              : BOOL;        // Active la surveillance
    Reset               : BOOL;        // Front acquittement défauts
    ArmRequest          : BOOL;        // Demande de réarmement (BtnEmergencyArming)
    EmergencyChainClosed      : BOOL;        // Retour physique boucle d'urgence amont contacteur
    PowerContactorEngaged     : BOOL;        // Confirmation contacteur de puissance principal
    PowerCutOffRequest  : BOOL;        // Requête de coupure logique issue des métiers
    BtnEmergencyCutOff  : BOOL;        // Commande d'ouverture d'urgence depuis l'IHM
END_VAR
VAR_OUTPUT
    Ready               : BOOL;
    Busy                : BOOL;
    Done                : BOOL;
    Error               : BOOL;
    ErrorId             : WORD;        // bit0: RedundancyTestFailed, bit1: EmergencyArmingFailed, bit3: StartupFail

    // ⚡ Sorties physiques (polarité maintien explicite)
    MaintainA_RQ        : BOOL;        // Sortie de pilotage canal A (TRUE = voie maintenue, FALSE = coupure)
    MaintainB_RQ        : BOOL;        // Sortie de pilotage canal B (TRUE = voie maintenue, FALSE = coupure)
    ArmPulse_RQ         : BOOL;        // Impulsion réarmement physique (1s)

    // 🚦 Bus d'état public (AF §8.2)
    State               : ST_Safety_Emergency_State; // ChainOk, ContactorOk, Step, Armable, ArmingBusy
    Diag                : ST_Safety_Emergency_Diag;  // Error, ErrorId, Redundancy, ArmFailed, Lockout

    // 🩺 Diagnostics scalaires (rétrocompatibilité PRG_10/GVL_Global)
    ArmingSeqStep                : INT;
    RedundancyTestFailed         : BOOL;
    EmergencyArmingFailed        : BOOL;
    EmergencyArmingLockoutActive : BOOL;
END_VAR
VAR
    // 🧱 Composition interne des sous-blocs
    Logic               : FB_Safety_EmergencyManagementLogic;
    Output              : FB_Safety_EmergencyManagementOutput;
END_VAR

// === IMPLEMENTATION ===

// 🛑 1. Appels des instances internes
Logic(
    Enable := Enable,
    Reset := Reset,
    ArmRequest := ArmRequest,
    EmergencyChainClosed := EmergencyChainClosed,
    PowerContactorEngaged := PowerContactorEngaged,
    PowerCutOffRequest := PowerCutOffRequest,
    BtnEmergencyCutOff := BtnEmergencyCutOff
);

Output(
    Enable := Enable,
    Cmd := Logic.Cmd,
    ChainOk := EmergencyChainClosed,
    ContactorOk := PowerContactorEngaged,
    ArmingStep := Logic.ArmingSeqStep,
    Armable := Logic.Armable,
    ArmingBusy := Logic.ArmingBusy,
    Error := Logic.Error,
    ErrorId := Logic.ErrorId,
    RedundancyTestFailed := Logic.RedundancyTestFailed,
    ArmFailed := Logic.EmergencyArmingFailed,
    LockoutActive := Logic.EmergencyArmingLockoutActive
);

// 📤 2. Propagation des signaux vers les sorties du bloc parent
Ready := Enable AND NOT Logic.StartupFail;
Busy  := (Logic.ArmingSeqStep <> 0) OR Logic.EmergencyArmingLockoutActive;
Done  := PowerContactorEngaged;
Error := Logic.Error;
ErrorId := Logic.ErrorId;

// ⚡ Sorties physiques
MaintainA_RQ   := Output.MaintainA_RQ;
MaintainB_RQ   := Output.MaintainB_RQ;
ArmPulse_RQ    := Output.ArmPulse_RQ;

// 🚦 Bus publics
State := Output.State;
Diag  := Output.Diag;

// 🩺 Diagnostics scalaires (rétrocompatibilité)
ArmingSeqStep                := Logic.ArmingSeqStep;
RedundancyTestFailed         := Logic.RedundancyTestFailed;
EmergencyArmingFailed        := Logic.EmergencyArmingFailed;
EmergencyArmingLockoutActive := Logic.EmergencyArmingLockoutActive;

(* ═══════════════════════════════════════════════════════════════
   🕵️♂️ FB_TroubleshootingView — Mise en forme lecture seule pour dépannage
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF/AF_Partie-14_Fonction_Troubleshooting/FB_TroubleshootingView_v1.2.md
   🔗 Producteur unique de GVL_Troubleshooting.* — instancié UNE SEULE FOIS,
