    // — Séquence réarmement AU (voir DOC/AF/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md §5)
    BtnEmergencyArming : BOOL;   (* 🎮 Commande IHM réarmement contacteur puissance (front) — PAS de réarmement automatique *)
    BtnEmergencyCutOff : BOOL;   (* 🎮 Commande IHM coupure d'urgence puissance amont (arrêt à distance) *)

    // Sélection treuil au joystick, arbitrée par FB_Modes (0=couplé nominal, 1/2 unitaires MAINT_N2 uniquement)
    SelJoystickWinch   : INT := 0; (* 🕹️ 0=M1+M2 couplés (nominal), 1=M1 seul, 2=M2 seul — unitaires MAINT_N2 uniquement *)

    // — bascule UNIQUEMENT la SOURCE du signal StartStop/Direction/
    // SpeedRefPct (joystick vs boutons IHM) — SelJoystickWinch ci-dessus reste l'unique autorité de
    // sélection treuil (M1/M2/Couplé), appliquée IDENTIQUEMENT quelle que soit la source.
    // 🔀 Switch machine unique — pilote aussi Translation M3.
    TglJoystickMaster  : BOOL := TRUE; (* 🕹️ TRUE (défaut) = joystick pilote Winch M1/M2 ET Translation M3 ; FALSE = boutons IHM (BtnUp/BtnDown, BtnFwd/BtnRev) *)
END_STRUCT
END_TYPE

(* ═══════════════════════════════════════════════════════════════
   🪜 ST_SpeedStepTable — Table des paliers de vitesse (1 par treuil)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-10_Fonction_Winch_v2.0.md
   🎛️ Table INDÉPENDANTE par treuil (M1 et M2 ont chacun la leur).
   ⚠️ ÉVOLUTION (retour terrain 2026-07-01, remplace le masque BYTE
      packé de la 1ère version) : chaque contacteur de vitesse de
      chaque palier est un BOOL nommé individuellement
      `P<palier>R<relais>` (ex. `P1R1`, `P3R2`) — paramétrable un par
      un pendant la mise en service (visible/modifiable directement
      dans la vue instance CODESYS), sans manipuler un masque binaire
      packé. `P` = Palier, `R` = Relais (contacteur de vitesse 1..4).
   L'ordre d'actionnement n'est pas implicite : il est défini ICI,
   dans les données, pas codé en dur dans la logique (FB_SpeedStep).
   ═══════════════════════════════════════════════════════════════ *)

TYPE ST_SpeedStepTable :
STRUCT
    // Palier 1 (vitesse la plus faible)
    P1R1 : BOOL;
    P1R2 : BOOL;
    P1R3 : BOOL;
    P1R4 : BOOL;
    // Palier 2
    P2R1 : BOOL;
    P2R2 : BOOL;
    P2R3 : BOOL;
    P2R4 : BOOL;
    // Palier 3
    P3R1 : BOOL;
    P3R2 : BOOL;
    P3R3 : BOOL;
    P3R4 : BOOL;
    // Palier 4
    P4R1 : BOOL;
    P4R2 : BOOL;
    P4R3 : BOOL;
    P4R4 : BOOL;
    // Palier 5 (vitesse la plus élevée)
    P5R1 : BOOL;
    P5R2 : BOOL;
    P5R3 : BOOL;
    P5R4 : BOOL;
    // Seuils de changement de palier (%), utilisés par paires successives (HYSTERESIS)
    // Seul StepThreshold_Pct[1..4] est consommé par FB_SpeedStep (transitions palier1→2..4→5)
    StepThreshold_Pct : ARRAY[1..5] OF REAL;
END_STRUCT
END_TYPE

(* ═══════════════════════════════════════════════════════════════
   📤 PRG_06_Outputs_Staging_LD — Barrière finale staging (PROGRAMME LADDER)
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF_Partie-06_Acquisition_Qualification_IO_v2.0.md §5
   ⚠️ Staging M5 : NON appelée par la MainTask ; PRG_10_Outputs_LD reste active.
   ✅ Reçoit les demandes PowerCutOff publiques en VAR_INPUT pour le basculement atomique.
   📄 Converti automatiquement en Ladder Diagram (<LD>) dans CODESYS.
   ═══════════════════════════════════════════════════════════════ *)

PROGRAM PRG_06_Outputs_Staging_LD
VAR_INPUT
    // 🛡️ Contrat public de coupure : TRUE = le procédé demande la coupure puissance.
    // Ces entrées ne sont pas encore raccordées : la page staging n'est pas exécutée.
    PowerCutOffWinchM1Request       : BOOL;
    PowerCutOffWinchM2Request       : BOOL;
    PowerCutOffTranslationM3Request : BOOL;
    PowerCutOffEmergencyRequest     : BOOL;
END_VAR
VAR_OUTPUT
    // ── [COMMANDES FINALES LECTURE SEULE] ─────────────────────────────────────────────────
    M1RelayFwd        : BOOL;
    M1RelayRev        : BOOL;
    M1SpeedContactor1 : BOOL;
    M1SpeedContactor2 : BOOL;
    M1SpeedContactor3 : BOOL;
    M1SpeedContactor4 : BOOL;
    M1BrakeCmd        : BOOL;
    M2RelayFwd        : BOOL;
    M2RelayRev        : BOOL;
    M2SpeedContactor1 : BOOL;
    M2SpeedContactor2 : BOOL;
    M2SpeedContactor3 : BOOL;
    M2SpeedContactor4 : BOOL;
    M2BrakeCmd        : BOOL;
    TranslationBrakeCmd : BOOL;
    PowerKeepAlive_A_RQ : BOOL;
    PowerKeepAlive_B_RQ : BOOL;
    EmergencyArming_RQ  : BOOL;
    EmergencyArmingPulseActive   : BOOL;
    EmergencyArmingLockoutActive: BOOL;
    ArmingSeqStep                : INT;
    RedundancyTestFailed         : BOOL;
    EmergencyArmingFailed        : BOOL;
END_VAR
VAR
    // 🛡️ Frontières finales stateful, appelées UNE fois par scan au plus près
    // des Q/PDO lorsque le staging sera basculé. Les demandes PowerCutOff entrent
    // alors par les quatre VAR_INPUT publics ci-dessus; les demandes mouvement
    // legacy sont conservées ici uniquement pour preuve de conservation.
    instWinchOutputInterlockM1_LD : FB_WinchOutputInterlock_LD;
    instWinchOutputInterlockM2_LD : FB_WinchOutputInterlock_LD;
    instTranslationOutputInterlock_LD : FB_TranslationOutputInterlock_LD;
    instSafetyEmergencyManagement : FB_Safety_EmergencyManagement;
    PowerCutOffReq : BOOL;
END_VAR

// === IMPLEMENTATION ===

// === [BARRIÈRES FINALES M1 / M2 / M3] ===
// PRG_06/PRG_07 produisent uniquement les demandes brutes publiques ci-dessous.
// Les trois instances sont les uniques producteurs des commandes autorisées.
// Aucun mapping C1..C4 n'est reconstruit : FB_Winch / SpeedStepTable demeure propriétaire.
instWinchOutputInterlockM1_LD(
    Enable := PRG_TREUILS_CFC.WinchM1FinalInterlockRequest.Enable,
    Reset := PRG_TREUILS_CFC.WinchM1FinalInterlockRequest.Reset,
    PowerContactorEngaged := PRG_TREUILS_CFC.WinchM1FinalInterlockRequest.PowerContactorEngaged,
    SafeStop := PRG_TREUILS_CFC.WinchM1FinalInterlockRequest.SafeStop,
    BrakeReleaseRequest := PRG_TREUILS_CFC.WinchM1FinalInterlockRequest.BrakeReleaseRequest,
    BrakeCommandOpenConfirmed := PRG_TREUILS_CFC.WinchM1FinalInterlockRequest.BrakeCommandOpenConfirmed,
    FwdRevSpeedFeedbackOff := PRG_TREUILS_CFC.WinchM1FinalInterlockRequest.FwdRevSpeedFeedbackOff,
    RequestedRelayFwd := PRG_TREUILS_CFC.WinchM1FinalInterlockRequest.RequestedRelayFwd,
    RequestedRelayRev := PRG_TREUILS_CFC.WinchM1FinalInterlockRequest.RequestedRelayRev,
    RequestedContactor1 := PRG_TREUILS_CFC.WinchM1FinalInterlockRequest.RequestedContactor1,
    RequestedContactor2 := PRG_TREUILS_CFC.WinchM1FinalInterlockRequest.RequestedContactor2,
    RequestedContactor3 := PRG_TREUILS_CFC.WinchM1FinalInterlockRequest.RequestedContactor3,
    RequestedContactor4 := PRG_TREUILS_CFC.WinchM1FinalInterlockRequest.RequestedContactor4,
    RequestedStep := PRG_TREUILS_CFC.WinchM1FinalInterlockRequest.RequestedStep
);
instWinchOutputInterlockM2_LD(
    Enable := PRG_TREUILS_CFC.WinchM2FinalInterlockRequest.Enable,
    Reset := PRG_TREUILS_CFC.WinchM2FinalInterlockRequest.Reset,
    PowerContactorEngaged := PRG_TREUILS_CFC.WinchM2FinalInterlockRequest.PowerContactorEngaged,
    SafeStop := PRG_TREUILS_CFC.WinchM2FinalInterlockRequest.SafeStop,
    BrakeReleaseRequest := PRG_TREUILS_CFC.WinchM2FinalInterlockRequest.BrakeReleaseRequest,
    BrakeCommandOpenConfirmed := PRG_TREUILS_CFC.WinchM2FinalInterlockRequest.BrakeCommandOpenConfirmed,
    FwdRevSpeedFeedbackOff := PRG_TREUILS_CFC.WinchM2FinalInterlockRequest.FwdRevSpeedFeedbackOff,
    RequestedRelayFwd := PRG_TREUILS_CFC.WinchM2FinalInterlockRequest.RequestedRelayFwd,
    RequestedRelayRev := PRG_TREUILS_CFC.WinchM2FinalInterlockRequest.RequestedRelayRev,
    RequestedContactor1 := PRG_TREUILS_CFC.WinchM2FinalInterlockRequest.RequestedContactor1,
    RequestedContactor2 := PRG_TREUILS_CFC.WinchM2FinalInterlockRequest.RequestedContactor2,
    RequestedContactor3 := PRG_TREUILS_CFC.WinchM2FinalInterlockRequest.RequestedContactor3,
    RequestedContactor4 := PRG_TREUILS_CFC.WinchM2FinalInterlockRequest.RequestedContactor4,
    RequestedStep := PRG_TREUILS_CFC.WinchM2FinalInterlockRequest.RequestedStep
);
instTranslationOutputInterlock_LD(
    Enable := PRG_TRANSLATION_CFC.TranslationFinalInterlockRequest.Enable,
    Reset := PRG_TRANSLATION_CFC.TranslationFinalInterlockRequest.Reset,
    PowerContactorEngaged := PRG_TRANSLATION_CFC.TranslationFinalInterlockRequest.PowerContactorEngaged,
    SafeStop := PRG_TRANSLATION_CFC.TranslationFinalInterlockRequest.SafeStop,
    BrakeReleaseRequest := PRG_TRANSLATION_CFC.TranslationFinalInterlockRequest.BrakeReleaseRequest,
    BrakeCommandOpenConfirmed := PRG_TRANSLATION_CFC.TranslationFinalInterlockRequest.BrakeCommandOpenConfirmed,
    RequestedDriveControlWord := PRG_TRANSLATION_CFC.TranslationFinalInterlockRequest.RequestedDriveControlWord,
    RequestedDriveFreqHz := PRG_TRANSLATION_CFC.TranslationFinalInterlockRequest.RequestedDriveFreqHz
);

// === [Q M1 / M2] ===
M1RelayFwd := instWinchOutputInterlockM1_LD.RelayFwd;
M1RelayRev := instWinchOutputInterlockM1_LD.RelayRev;
M1SpeedContactor1 := instWinchOutputInterlockM1_LD.Contactor1;
M1SpeedContactor2 := instWinchOutputInterlockM1_LD.Contactor2;
M1SpeedContactor3 := instWinchOutputInterlockM1_LD.Contactor3;
M1SpeedContactor4 := instWinchOutputInterlockM1_LD.Contactor4;
M1BrakeCmd := instWinchOutputInterlockM1_LD.BrakeCmd;
M1_RelayFwd_Up_DQ := M1RelayFwd;
M1_RelayRev_Down_DQ := M1RelayRev;
M1_SpeedContactor_1_DQ := M1SpeedContactor1;
M1_SpeedContactor_2_DQ := M1SpeedContactor2;
M1_SpeedContactor_3_DQ := M1SpeedContactor3;
M1_SpeedContactor_4_DQ := M1SpeedContactor4;
M1_BrakeRelease_RQ := M1BrakeCmd;

M2RelayFwd := instWinchOutputInterlockM2_LD.RelayFwd;
M2RelayRev := instWinchOutputInterlockM2_LD.RelayRev;
M2SpeedContactor1 := instWinchOutputInterlockM2_LD.Contactor1;
M2SpeedContactor2 := instWinchOutputInterlockM2_LD.Contactor2;
M2SpeedContactor3 := instWinchOutputInterlockM2_LD.Contactor3;
M2SpeedContactor4 := instWinchOutputInterlockM2_LD.Contactor4;
M2BrakeCmd := instWinchOutputInterlockM2_LD.BrakeCmd;
M2_RelayFwd_Up_Close_DQ := M2RelayFwd;
M2_RelayRev_Down_Open_DQ := M2RelayRev;
M2_SpeedContactor_1_DQ := M2SpeedContactor1;
M2_SpeedContactor_2_DQ := M2SpeedContactor2;
M2_SpeedContactor_3_DQ := M2SpeedContactor3;
M2_SpeedContactor_4_DQ := M2SpeedContactor4;
M2_BrakeRelease_RQ := M2BrakeCmd;

// === [PDO M3 + KOBOLD] ===
TranslationBrakeCmd := instTranslationOutputInterlock_LD.BrakeCmd;
M3_BrakeRelease_RQ := TranslationBrakeCmd;
M3_CommandWord := instTranslationOutputInterlock_LD.DriveControlWord;
M3_SetpointFrequencyHz := REAL_TO_UINT(instTranslationOutputInterlock_LD.DriveFreqRefHz * 100.0);
M1_M2_KoboldMeasureEnable_DQ := PRG_TREUILS_CFC.KoboldContactorCmdArbitrated
                                AND PRG_INPUTS_LD.PowerContactorEngaged
                                AND PRG_INPUTS_LD.EmergencyChainClosed;

// === [SÉCURITÉ & COUPURE PUISSANCE AMONT] ===
// Boucle de sécurité et séquencement d'armement général.

// Demande de coupure de puissance
// Chaque demande est indépendante : aucune disponibilité de procédé ne la masque.
// La chaîne AU physique reste un chemin matériel indépendant via EmergencyChainClosed.
PowerCutOffReq := PowerCutOffWinchM1Request
                  OR PowerCutOffWinchM2Request
                  OR PowerCutOffTranslationM3Request
                  OR PowerCutOffEmergencyRequest;

// Gestionnaire d'arrêt d'urgence et de réarmement
instSafetyEmergencyManagement(
    Enable := TRUE,
    Reset := PRG_SUPERVISION_CFC.FaultMachineReset_IHM,
    ArmRequest := GVL_IHM.Modes.Cmd.BtnEmergencyArming,
    EmergencyChainClosed := PRG_INPUTS_LD.EmergencyChainClosed,
    PowerContactorEngaged := PRG_INPUTS_LD.PowerContactorEngaged,
    PowerCutOffRequest := PowerCutOffReq,
    BtnEmergencyCutOff := GVL_IHM.Modes.Cmd.BtnEmergencyCutOff
);

// Affectation des sorties de réarmement et maintien puissance
PowerKeepAlive_A_RQ := instSafetyEmergencyManagement.MaintainA_RQ;
PowerKeepAlive_B_RQ := instSafetyEmergencyManagement.MaintainB_RQ;
EmergencyArming_RQ := instSafetyEmergencyManagement.ArmPulse_RQ;

EmergencyArmingPulseActive := instSafetyEmergencyManagement.ArmPulse_RQ;
EmergencyArmingLockoutActive := instSafetyEmergencyManagement.Diag.LockoutActive;
ArmingSeqStep := instSafetyEmergencyManagement.State.Step;
RedundancyTestFailed := instSafetyEmergencyManagement.Diag.RedundancyTestFailed;
EmergencyArmingFailed := instSafetyEmergencyManagement.Diag.ArmFailed;

// ── [PUBLICATION DANS GVL_GLOBAL POUR LECTURE PAR LES AUTRES POU] ─────────────────
GVL_Global.M1RelayFwd                    := M1RelayFwd;
GVL_Global.M1RelayRev                    := M1RelayRev;
GVL_Global.M1SpeedContactor1             := M1SpeedContactor1;
GVL_Global.M1SpeedContactor2             := M1SpeedContactor2;
GVL_Global.M1SpeedContactor3             := M1SpeedContactor3;
GVL_Global.M1SpeedContactor4             := M1SpeedContactor4;
GVL_Global.M1BrakeCmd                    := M1BrakeCmd;
GVL_Global.M2RelayFwd                    := M2RelayFwd;
GVL_Global.M2RelayRev                    := M2RelayRev;
GVL_Global.M2SpeedContactor1             := M2SpeedContactor1;
GVL_Global.M2SpeedContactor2             := M2SpeedContactor2;
GVL_Global.M2SpeedContactor3             := M2SpeedContactor3;
GVL_Global.M2SpeedContactor4             := M2SpeedContactor4;
GVL_Global.M2BrakeCmd                    := M2BrakeCmd;
GVL_Global.TranslationBrakeCmd           := TranslationBrakeCmd;
GVL_Global.EmergencyArmingPulseActive   := EmergencyArmingPulseActive;
GVL_Global.EmergencyArmingLockoutActive := EmergencyArmingLockoutActive;
GVL_Global.ArmingSeqStep                := ArmingSeqStep;

GVL_Global.instWinchOutputInterlockM1_LD     := instWinchOutputInterlockM1_LD;
GVL_Global.instWinchOutputInterlockM2_LD     := instWinchOutputInterlockM2_LD;
GVL_Global.instTranslationOutputInterlock_LD := instTranslationOutputInterlock_LD;

(* =======================================================================
   📏 FB_SyncDeviation — Comparateur d'ecart position M1/M2 (pur)
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Signaler l'ecart de position entre M1 et M2 sur 2 seuils
      (Warn = signaler / Fault = critique). Comparateur PUR : il signale,
      il ne decide pas de ralentir ni d'arreter — le consommateur decide.
   🔌 Interface : Bloc de surveillance transverse (1 instance)
   🧬 Responsabilite : n'interprete PAS l'etat benne. Il reçoit ActiveOffsetM
      deja resolu (calcul offset-selon-etat-benne = FB_Bucket/HoldOffset).
   🔒 Polarite : SyncDeviationWarn/Fault = TRUE si ecart hors seuil.
   📄 Doc : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_SyncDeviation
VAR_INPUT
    // === COMMANDES ET CONSIGNES ===
    Enable                          : BOOL;                           // --> [CMD] Validation surveillance globale
    Reset                           : BOOL;                           // --> [CMD] Acquittement defaut sur front
    SyncEnable                      : BOOL;                           // --> [CMD] Autorisation utilisateur synchro

    // === MESURES ET ETATS CODEURS ===
    CablePosM1                      : REAL;                           // --> [HW] Position cable treuil M1 (m)
    CablePosM2                      : REAL;                           // --> [HW] Position cable treuil M2 (m)
    HomedAndReliableM1              : BOOL;                           // --> [STAT] Gate fiable M1 (FB_EncoderReliability)
    HomedAndReliableM2              : BOOL;                           // --> [STAT] Gate fiable M2 (FB_EncoderReliability)

    // === REGLAGES ET CONFIGURATION ===
    CfgSyncToleranceM               : REAL := 0.10;                   // --> [CFG] Seuil 1 (Warn) — ecart max avant alerte (m)
    CfgSyncCriticalToleranceM       : REAL := 0.50;                   // --> [CFG] Seuil 2 (Fault) — ecart critique (m)
    ActiveOffsetM                   : REAL := 0.0;                    // --> [CFG] Offset cible RESOLU (ex: benne)

    // === BYPASSES ET SIMULATION ===
    BypassGlobal                    : BOOL := FALSE;                  // --> [TST] Neutralise la surveillance ecart
END_VAR
VAR_OUTPUT
    // === MESURES ET DIAGNOSTICS DE SYNCHRO ===
    DeltaPosM                       : REAL;                           // <-- [DIAG] Ecart absolu position |M1 - M2| (m)
    SignedDeltaPosM                 : REAL;                           // <-- [DIAG] Ecart signe position (M1 - M2) (m)
    SyncDeviationWarn               : BOOL;                           // <-- [DIAG] Seuil 1 depasse : signaler / forcer palier 1
    SyncDeviationFault              : BOOL;                           // <-- [SAFE] Seuil 2 depasse : ecart critique (block signal)
END_VAR
VAR
    // === DETECTEURS ET TIMERS INTERNES ===
    ResetEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Reset
    DeviationFaultTimer            : TON;                            // . [LOC] Tempo filtrage transitoire ecart (seuil 2)

    // === VARIABLES LOCALES INTERNES ===
    WarnActive                      : BOOL;                           // . [LOC] Ecart hors seuil 1 actif
    FaultActive                     : BOOL;                           // . [LOC] Ecart hors seuil 2 actif
    WarnLatched                     : BOOL;                           // . [LOC] Latch ecart seuil 1 (degrada palier 1 stable)
END_VAR

{region "§1 Gate neutralisation"}
// 🛑 1. GATE
IF NOT Enable THEN
    DeltaPosM := 0.0; SignedDeltaPosM := 0.0;
    SyncDeviationWarn := FALSE; SyncDeviationFault := FALSE;
    WarnLatched := FALSE;
    RETURN;
END_IF;
ResetEdge(CLK := Reset);
{endregion}

{region "§2 Calcul ecart"}
// 📏 2. ÉCART M1/M2 — calculé en continu si les 2 treuils sont fiables (HomedAndReliable)
IF HomedAndReliableM1 AND HomedAndReliableM2 THEN
    SignedDeltaPosM := CablePosM1 - CablePosM2 + ActiveOffsetM;
    DeltaPosM := ABS(SignedDeltaPosM);
ELSE
    SignedDeltaPosM := 0.0;
    DeltaPosM := 0.0;
END_IF;
{endregion}

{region "§3 Surveillance ecart 2 seuils"}
// 🔍 3. SURVEILLANCE ECART — 2 seuils (Warn/Fault).
// Warn (seuil 1) = INSTANTANE + LATCH : degrade le palier 1 des que l'ecart depasse,
// sans retard temporel ni oscillation (fidele a l'ancien SyncDegradedStep1).
// Fault (seuil 2) = filtre temporel pour le transitoire mecanique d'arret.
IF NOT BypassGlobal THEN
    WarnActive  := SyncEnable AND HomedAndReliableM1 AND HomedAndReliableM2 AND (DeltaPosM > CfgSyncToleranceM);
    FaultActive := SyncEnable AND HomedAndReliableM1 AND HomedAndReliableM2 AND (DeltaPosM > CfgSyncCriticalToleranceM);

    // Latch Warn : reste actif tant que la cause persiste OU que Reset n'a pas ete demande
    IF WarnActive THEN
        WarnLatched := TRUE;
    ELSIF ResetEdge.Q AND NOT WarnActive THEN
        WarnLatched := FALSE;
    END_IF;
    SyncDeviationWarn := WarnActive OR WarnLatched;

    DeviationFaultTimer(IN := FaultActive, PT := T#800ms);
    SyncDeviationFault := DeviationFaultTimer.Q;
ELSE
    SyncDeviationWarn := FALSE;
    SyncDeviationFault := FALSE;
    WarnLatched := FALSE;
END_IF;
{endregion}

SETUP
VAR
    fb : FB_JOYSTICK;
    nx : INT := 5000;
    ny : INT := 5000;
    diagOk : ST_DIAG_DEVICE;
    diagDown : ST_DIAG_DEVICE;
END_VAR
END_SETUP

TEST 'TC-P08-001 Perte bus CAN pendant un mouvement arme neutralise, desarme et leve Error (auto-efface au retour)'
    diagDown.ONLINE := FALSE; diagDown.OPERATIONAL := FALSE; diagDown.ERROR := FALSE;
    diagDown.ERRORID := 0; diagDown.STATE := E_DIAG_STATE.INIT; diagDown.STATEATERROR := E_DIAG_STATE.DISABLED;
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;
    nx := 5000; ny := 5000;

    (* arme le geste au neutre, bus sain *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ADVANCE_TIME(110000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, 'precondition : geste arme');

    (* deplace le joystick : mouvement actif, bus toujours sain *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 60.0, 0.01, 'mouvement actif : consigne non nulle (RawX=8000, Neutral=5000)');
    ASSERT_EQ(fb.AXISCMDX.DIRECTION, 1, 'sens avant pendant le mouvement');
    ASSERT_NEAR(fb.AXISCMDY.SPEEDREF, 0.0, 0.01, 'RawY au neutre : axe Y reste a 0, aucun couplage entre les axes');
    ASSERT_EQ(fb.AXISCMDY.DIRECTION, 0, 'axe Y au neutre : Direction=0');

    (* perte du bus CAN EN PLEIN MOUVEMENT : neutralisation immediate + desarmement *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagDown, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.READY, 'bus CAN non operationnel doit bloquer Ready');
    ASSERT_TRUE(fb.ERROR, 'perte de comm doit lever Error (AF08)');
    ASSERT_EQ(fb.ERRORID, 16#0004, 'bit2 : HW/bus non operationnel');
    ASSERT_FALSE(fb.AXISCMDX.ENABLE, 'sorties axe X neutralisees des la perte du bus, meme en plein mouvement');
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 0.0, 0.01, 'consigne X coupee immediatement, pas de decel progressive');
    ASSERT_FALSE(fb.AXISCMDY.ENABLE, 'sorties axe Y aussi neutralisees (gate global, pas seulement l axe en mouvement)');
    ASSERT_NEAR(fb.AXISCMDY.SPEEDREF, 0.0, 0.01, 'consigne Y aussi coupee');
    ASSERT_FALSE(fb.DEADMANARMED, 'le geste est desarme par la perte du bus (AF08 TC-P08-001)');

    (* bus revient : pas de rearmement automatique, nouvel appui conscient exige *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.READY, 'bus revenu : FB de nouveau pret');
    ASSERT_FALSE(fb.ERROR, 'bus revenu : Error auto-effacee sans geste operateur (categorie Info/Warning, pas un Fault a acquitter)');
    ASSERT_EQ(fb.ERRORID, 0, 'bit2 efface automatiquement');
    ASSERT_FALSE(fb.DEADMANARMED, 'pas de rearmement automatique au retour du bus : nouvel appui conscient exige');
END_TEST

TEST 'TC-P08-002 Maintien DeadmanArmHoldTime : arme si tenu 100ms, annule si relache avant'
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
