    M3_TargetNum             := GVL_IHM.TranslationM3.Cmd.SelTarget,
    // 🧪 Chaîne AU sim = image des Q physiques (scan N-1, comme le terrain).
    // ❌ Ne pas brancher Pulse/Lockout/BtnArming : ça court-circuite le FB Emergency.
    PowerKeepAlive_A         := PowerKeepAlive_A_RQ,
    PowerKeepAlive_B         := PowerKeepAlive_B_RQ,
    EmergencyArming_RQ       := EmergencyArming_RQ,
    SimEncoderSpeedFactor    := GVL_Simulation.SimEncoderSpeedFactor,
    SimSyncDeviationInjectM1 := GVL_Simulation.SimSyncDeviationInjectM1,
    SimSyncDeviationInjectM2 := GVL_Simulation.SimSyncDeviationInjectM2,
    SimSyncDeviationOffset_M := GVL_Simulation.SimSyncDeviationOffset_M,
    SimM3SensorsWordActive   := GVL_Simulation.SimM3SensorsWordActive,
    SimM3SensorsWord         := GVL_Simulation.SimM3SensorsWord,
    SimJoystickRawX          := GVL_Simulation.SimJoystickRawX,
    SimJoystickRawY          := GVL_Simulation.SimJoystickRawY,
    SimJoystickRawButton     := GVL_Simulation.SimJoystickRawButton,
    SimKoboldContactValue    := GVL_Simulation.SimKoboldContactValue,
    BtnEmergencyStop         := GVL_IHM.Modes.Cmd.BtnEmergencyCutOff,
    HwReal                   := HwReal,
    RawPosM1                 := _SimEncoderRawPosM1,
    RawPosM2                 := _SimEncoderRawPosM2
);

// 🧪 Image du banc exposée pour lecture côte à côte ; aucune logique métier ne lit HwSim.
HwSim.Winch       := instSimBench.Winch;
HwSim.Translation := instSimBench.Translation;
HwSim.Operator    := instSimBench.Operator;
HwSim.Machine     := instSimBench.Machine;

// 🔄 Source Winch atomique + pulse générique. Au boot, la source initiale est mémorisée sans faux pulse.
WinchInputSourceSimulated := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimWinchActive;
IF NOT WinchInputSourceInitialized THEN
    PreviousWinchInputSourceSimulated := WinchInputSourceSimulated;
    WinchInputSourceInitialized := TRUE;
    WinchInputSourceChanged := FALSE;
ELSE
    WinchInputSourceChanged := (WinchInputSourceSimulated <> PreviousWinchInputSourceSimulated);
    PreviousWinchInputSourceSimulated := WinchInputSourceSimulated;
END_IF;

IF WinchInputSourceSimulated
    THEN HwIn.Winch := instSimBench.Winch;             ELSE HwIn.Winch := HwReal.Winch;             END_IF;
IF GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimTranslationActive
    THEN HwIn.Translation := instSimBench.Translation; ELSE HwIn.Translation := HwReal.Translation; END_IF;
IF GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimOperatorActive
    THEN HwIn.Operator := instSimBench.Operator;       ELSE HwIn.Operator := HwReal.Operator;       END_IF;
IF GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimMachineActive
    THEN HwIn.Machine := instSimBench.Machine;         ELSE HwIn.Machine := HwReal.Machine;         END_IF;


// ─── §1 HwIn ──► FB_Input ──► VAR_OUTPUT (Conditionnement des entrées) ───────

//  🔌 HwIn.Machine.PowerContactorEngaged_DI ····· câblage réel : 1 = contacteur puissance engagé
//         └─►[ instPowerContactorEngaged 🔩 ]         ← filtre anti-rebond 20 ms
//                └─► PowerContactorEngaged ··········· [BLOQUE] TRUE = puissance présente ✅ (portail maître)
//                       └─► PRG_01..11 · FB_Safety_* · FB_Cycle · FB_Winch
instPowerContactorEngaged(InputRaw := HwIn.Machine.PowerContactorEngaged_DI, FilterTime := T#20MS);
PowerContactorEngaged := instPowerContactorEngaged.State;

//  🔌 HwIn.Machine.EmergencyChainClosed_DI ······ câblage réel : 1 = boucle AU fermée
//         └─►[ instEmergencyChainClosed 🔩 ]          ← filtre anti-rebond 20 ms
//                └─► EmergencyChainClosed ············ [BLOQUE] TRUE = boucle AU saine ✅ (précondition armement)
//                       └─► PRG_03_Safety · PRG_06_WinchControl · PRG_11_Troubleshooting
instEmergencyChainClosed(InputRaw := HwIn.Machine.EmergencyChainClosed_DI, FilterTime := T#20MS);
EmergencyChainClosed := instEmergencyChainClosed.State;

//  🔌 HwIn.Winch.M2_TensionedCable_DI ··········· câblage réel : 1 = câble tendu (NC)
//         └─►[ instSlackCableSwitch 🔩 ]        ← filtre anti-rebond 20 ms
//                └─► SlackCableSwitch ·········· [BLOQUE] TRUE = câble tendu ✅ | FALSE = mou 🔴→ForbidDescent M2
//                       └─► PRG_03_Safety (instSafetyWinchM1/M2) · PRG_11_Troubleshooting
instSlackCableSwitch(InputRaw := HwIn.Winch.M2_TensionedCable_DI, FilterTime := T#20MS);
SlackCableSwitch := instSlackCableSwitch.State;

//  🔌 HwIn.Machine.M1_M2_KoboldContactFond_DI ·· câblage réel : 1 = contact fond détecté (NO)
//         └─►[ instKoboldContactFond 🔩 ]       ← filtre anti-rebond 20 ms
//                └─► KoboldContactFond ········· [BLOQUE] TRUE = fond touché ✅ → cycle figé BOTTOM_TOUCH_WAIT
//                       └─► PRG_05_Cycle (instCycle) · PRG_09_Supervision
instKoboldContactFond(InputRaw := HwIn.Machine.M1_M2_KoboldContactFond_DI, FilterTime := T#20MS);
KoboldContactFond := instKoboldContactFond.State;

//  🔌 HwIn.Winch.M1M2_TopPositionFree_DI ········ câblage réel : 1 = fin de course libre (NC)
//         └─►[ instTopPositionSensor 🔩 ]       ← filtre anti-rebond 20 ms
//                └─► TopPositionSensor ········· [BLOQUE] TRUE = libre ✅ | FALSE = butée haute 🔴→ForbidAscent M1+M2
//                       └─► PRG_02_Encoders (instHomingM1/M2) · PRG_03_Safety
instTopPositionSensor(InputRaw := HwIn.Winch.M1M2_TopPositionFree_DI, FilterTime := T#20MS);
TopPositionSensor := instTopPositionSensor.State;

//  🔌 HwIn.Machine.PhaseRotationOk_DI ··········· câblage réel : 1 = rotation phases correcte (NC)
//         └─►[ instCtrlPhaseRotation 🔩 ]       ← filtre anti-rebond 20 ms
//                └─► PhaseRotationOk ··········· [ESCAL.] TRUE = phases OK ✅ | FALSE = inversées 🔴→SafeStop 3 axes
//                       └─► PRG_03_Safety (instSafetyWinchM1/M2/TranslationM3)
instCtrlPhaseRotation(InputRaw := HwIn.Machine.PhaseRotationOk_DI, FilterTime := T#20MS);
PhaseRotationOk := instCtrlPhaseRotation.State;

//  🔌 HwIn.Machine.BrakeThermalOk_DI ············ câblage réel : 1 = temp. freins OK (NC, commun M1/M2/M3)
//         └─►[ instBrakeThermalFeedback 🔩 ]    ← filtre anti-rebond 20 ms
//                └─► BrakeThermalFeedback ····· [ESCAL.] TRUE = temp OK ✅ | FALSE = surchauffe 🔴→SafeStop+PowerCutOff
//                       └─► PRG_03_Safety (instSafetyWinchM1/M2/TranslationM3)
instBrakeThermalFeedback(InputRaw := HwIn.Machine.BrakeThermalOk_DI, FilterTime := T#20MS);
BrakeThermalFeedback := instBrakeThermalFeedback.State;

// 🪝 TREUIL M1
//  🔌 HwIn.Winch.M1_ContactorsReleased_DI ······· câblage réel : 1 = tous contacteurs retombés
//         └─►[ instM1FwdRevSpeedFeedbackOff 🔩 ]← filtre anti-rebond 20 ms
//                └─► M1FwdRevSpeedFeedbackOff · [ESCAL.] TRUE = retombés ✅ | FALSE = contacteur collé 🔴→Méca A/C
//                       └─► PRG_02_Encoders · PRG_03_Safety (instSafetyWinchM1)
instM1FwdRevSpeedFeedbackOff(InputRaw := HwIn.Winch.M1_ContactorsReleased_DI, FilterTime := T#20MS);
M1FwdRevSpeedFeedbackOff := instM1FwdRevSpeedFeedbackOff.State;

//  🔌 HwIn.Winch.M1_ThermalOk_DI ················ câblage réel : 1 = temp. moteur M1 OK (NC)
//         └─►[ instM1Thermal 🔩 ]               ← filtre anti-rebond 20 ms
//                └─► M1ThermalFeedback ········· [ESCAL.] TRUE = temp OK ✅ | FALSE = surchauffe 🔴 (NOTE: PRG_03 inverse en "TRUE=défaut")
//                       └─► PRG_03_Safety (instSafetyWinchM1) · PRG_09_Supervision
instM1Thermal(InputRaw := HwIn.Winch.M1_ThermalOk_DI, FilterTime := T#20MS);
M1ThermalFeedback := instM1Thermal.State;

//  🔌 HwIn.Winch.M1_BrakeIsOpen_DI ·············· câblage réel : 1 = contacteur commandé = DESSERRÉ
//         └─►[ instM1BrakeFeedback 🔩 ]         ← bascule unique BrakeFeedbackInvertLogic, 📄 AF_Partie-09 §5bis
//                └─► M1BrakeFeedback ··········· [ESCAL.] TRUE = frein SERRÉ (état sûr) ✅ | FALSE = desserré 🔴
//                       └─► PRG_02_Encoders · PRG_03_Safety (instSafetyWinchM1 Méca A/B/D/E)
instM1BrakeFeedback(InputRaw := HwIn.Winch.M1_BrakeIsOpen_DI, InvertLogic := BrakeFeedbackInvertLogic, FilterTime := T#20MS);
M1BrakeFeedback := instM1BrakeFeedback.State;
M1BrakeCommandOpenConfirmed := NOT M1BrakeFeedback; // DI filtré : contacteur desserrage confirmé uniquement.

// 🪝 TREUIL M2
//  🔌 HwIn.Winch.M2_ContactorsReleased_DI ······· câblage réel : 1 = tous contacteurs retombés
//         └─►[ instM2FwdRevSpeedFeedbackOff 🔩 ]← filtre anti-rebond 20 ms
//                └─► M2FwdRevSpeedFeedbackOff · [ESCAL.] TRUE = retombés ✅ | FALSE = contacteur collé 🔴→Méca A/C
//                       └─► PRG_02_Encoders · PRG_03_Safety (instSafetyWinchM2)
instM2FwdRevSpeedFeedbackOff(InputRaw := HwIn.Winch.M2_ContactorsReleased_DI, FilterTime := T#20MS);
M2FwdRevSpeedFeedbackOff := instM2FwdRevSpeedFeedbackOff.State;

//  🔌 HwIn.Winch.M2_ThermalOk_DI ················ câblage réel : 1 = temp. moteur M2 OK (NC)
//         └─►[ instM2Thermal 🔩 ]               ← filtre anti-rebond 20 ms
//                └─► M2ThermalFeedback ········· [ESCAL.] TRUE = temp OK ✅ | FALSE = surchauffe 🔴 (NOTE: PRG_03 inverse en "TRUE=défaut")
//                       └─► PRG_03_Safety (instSafetyWinchM2) · PRG_09_Supervision
instM2Thermal(InputRaw := HwIn.Winch.M2_ThermalOk_DI, FilterTime := T#20MS);
M2ThermalFeedback := instM2Thermal.State;

//  🔌 HwIn.Winch.M2_BrakeIsOpen_DI ·············· câblage réel : 1 = contacteur commandé = DESSERRÉ
//         └─►[ instM2BrakeFeedback 🔩 ]         ← bascule unique BrakeFeedbackInvertLogic, 📄 AF_Partie-09 §5bis
//                └─► M2BrakeFeedback ··········· [ESCAL.] TRUE = frein SERRÉ (état sûr) ✅ | FALSE = desserré 🔴
//                       └─► PRG_02_Encoders · PRG_03_Safety (instSafetyWinchM2 Méca A/B/D/E)
instM2BrakeFeedback(InputRaw := HwIn.Winch.M2_BrakeIsOpen_DI, InvertLogic := BrakeFeedbackInvertLogic, FilterTime := T#20MS);
M2BrakeFeedback := instM2BrakeFeedback.State;
M2BrakeCommandOpenConfirmed := NOT M2BrakeFeedback; // DI filtré : contacteur desserrage confirmé uniquement.

// ↔️ TRANSLATION M3
//  🔌 HwIn.Translation.M3_PosTremie_DI ········· câblage réel : 1 = position trémie atteinte (NO)
//         └─►[ instTranslationPosTremie 🔩 ]    ← filtre anti-rebond 20 ms
//                └─► TranslationPosTremie ····· [DIAG] TRUE = en position trémie ✅
//                       └─► instPositionDecoder · PRG_05_Cycle · PRG_09_Supervision
instTranslationPosTremie(InputRaw := HwIn.Translation.M3_PosTremie_DI, FilterTime := T#20MS);
TranslationPosTremie := instTranslationPosTremie.State;

//  🔌 HwIn.Translation.M3_PosPV_DI ············· câblage réel : 1 = zone PV atteinte (NO)
//         └─►[ instTranslationPosPV 🔩 ]        ← filtre anti-rebond 20 ms
//                └─► TranslationPosPV ········· [DIAG] TRUE = zone PV atteinte ✅ (pré-ralentissement Trémie)
//                       └─► instPositionDecoder · PRG_09_Supervision
instTranslationPosPV(InputRaw := HwIn.Translation.M3_PosPV_DI, FilterTime := T#20MS);
TranslationPosPV := instTranslationPosPV.State;

//  🔌 HwIn.Translation.M3_PosP2_DI ············· câblage réel : 1 = position P2 atteinte (NO)
//         └─►[ instTranslationPosP2 🔩 ]        ← filtre anti-rebond 20 ms
//                └─► TranslationPosP2 ········· [DIAG] TRUE = position P2 atteinte ✅
//                       └─► instPositionDecoder · PRG_05_Cycle · PRG_09_Supervision
instTranslationPosP2(InputRaw := HwIn.Translation.M3_PosP2_DI, FilterTime := T#20MS);
TranslationPosP2 := instTranslationPosP2.State;

//  🔌 HwIn.Translation.M3_PosP1_DI ············· câblage réel : 1 = position P1 atteinte (NO)
//         └─►[ instTranslationPosP1 🔩 ]        ← filtre anti-rebond 20 ms
//                └─► TranslationPosP1 ········· [DIAG] TRUE = position P1 atteinte ✅
//                       └─► instPositionDecoder · PRG_05_Cycle · PRG_09_Supervision
instTranslationPosP1(InputRaw := HwIn.Translation.M3_PosP1_DI, FilterTime := T#20MS);
TranslationPosP1 := instTranslationPosP1.State;

//  🔌 HwIn.Translation.M3_PosMaintenance_DI ···· câblage réel : 1 = position service atteinte (NO)
//         └─►[ instTranslationPosMaintenance 🔩 ]← filtre anti-rebond 20 ms
//                └─► TranslationPosMaintenance · [DIAG] TRUE = position service atteinte ✅
//                       └─► instPositionDecoder · PRG_05_Cycle · PRG_09_Supervision
instTranslationPosMaintenance(InputRaw := HwIn.Translation.M3_PosMaintenance_DI, FilterTime := T#20MS);
TranslationPosMaintenance := instTranslationPosMaintenance.State;

//  🔌 ─── §2 DÉCODAGE MOT CAPTEURS M3 ──────────────────────────────────────────
// 🆕 REX 2026-07-21 : Décodage immédiat du mot 5 capteurs position M3 (scan position 0)
instPositionDecoder(
    SensorTremie      := TranslationPosTremie,
    SensorPV          := TranslationPosPV,
    SensorP2          := TranslationPosP2,
    SensorP1          := TranslationPosP1,
    SensorMaintenance := TranslationPosMaintenance
);

//  🔌 HwIn.Translation.M3_BrakeIsOpen_DI ······· câblage réel : 1 = contacteur commandé = DESSERRÉ
//         └─►[ instM3BrakeFeedback 🔩 ]         ← bascule unique BrakeFeedbackInvertLogic, 📄 AF_Partie-12 §5
//                └─► M3BrakeFeedback ··········· [ESCAL.] TRUE = frein SERRÉ (état sûr) ✅ | FALSE = desserré 🔴
//                       └─► PRG_03_Safety (instSafetyTranslationM3 Méca B) · PRG_09_Supervision
instM3BrakeFeedback(InputRaw := HwIn.Translation.M3_BrakeIsOpen_DI, InvertLogic := BrakeFeedbackInvertLogic, FilterTime := T#20MS);
M3BrakeFeedback := instM3BrakeFeedback.State;
M3BrakeCommandOpenConfirmed := NOT M3BrakeFeedback; // DI filtré : contacteur desserrage confirmé uniquement.

// Retours variateur EtherCAT M3 physiques directs (recopie HwIn)
M3_ActualFrequencyHz_Filtered := HwIn.Translation.M3_ActualFrequencyHz;
M3_StatusWord_Filtered        := HwIn.Translation.M3_StatusWord;

(* ═══════════════════════════════════════════════════════════════
   ↔️ FB_Translation_PositionEstimator — Estimateur de Position Continue M3
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-11_Fonction_Translation_v2.1.md §3
   🎯 Rôle : Calculer par odométrie (intégration temporelle vitesse/fréquence Hz * sens)
      la position estimée continue en mètres (0.0 m à la Maintenance -> +X m à la Trémie),
      avec re-calage absolu automatique instantané sur le franchissement des 5 capteurs fixes.
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Translation_PositionEstimator
VAR_INPUT
    Enable               : BOOL;   (* Active le calcul *)
    Reset                : BOOL;   (* Front d'acquittement / réinitialisation *)
    DriveActualFreqHz    : REAL;   (* Fréquence réelle variateur en Hz (ex: 5.0 Hz) *)
    Direction            : INT;    (* Sens effectif : +1 = Fwd (vers Trémie), -1 = Rev (vers Maint), 0 = Arrêt *)
    
    (* 5 Capteurs de position fixes *)
    SensorMaintenance    : BOOL;   (* Capteur 0 : Maintenance (0.0 m) *)
    SensorP1             : BOOL;   (* Capteur 1 : P1 (ex: 6.0 m) *)
    SensorP2             : BOOL;   (* Capteur 2 : P2 (ex: 14.0 m) *)
    SensorPV             : BOOL;   (* Capteur 3 : PV (ex: 21.0 m) *)
    SensorTremie         : BOOL;   (* Capteur 4 : Trémie (ex: 25.0 m) *)

    (* Positions de référence calibrées (mètres) depuis GVL_PERSISTENT *)
    PosMaintenanceM      : REAL := 0.0;
    PosP1M               : REAL := 6.0;
    PosP2M               : REAL := 14.0;
    PosPVM               : REAL := 21.0;
    PosTremieM           : REAL := 25.0;

    (* Gain de vitesse : mètres parcourus par Hz par seconde (ex: 50 Hz = 0.416 m/s => Gain = 0.008333 m/Hz.s) *)
    GainMetersPerHzSec   : REAL := 0.008333;

    (* 🆕 2026-08-06 : reprise après reboot — l'appelant recopie en continu PositionEstimatedM/
       Initialized vers GVL_PERSISTENT (pas de bridge dédié, simple recopie comme _TranslationSetFreq_Hz)
       et réinjecte ici au redémarrage, pour ne pas perdre l'estimation odométrique à chaque coupure. *)
    PersistedPositionM   : REAL := 0.0;
    PersistedInitialized : BOOL := FALSE;
END_VAR

VAR_OUTPUT
    PositionEstimatedM   : REAL;   (* Position continue estimée en mètres *)
    Initialized          : BOOL;   (* 🆕 exposé pour recopie persistante côté appelant *)
    Recalibrated         : BOOL;   (* Pulse 1 cycle lors d'un recalage sur capteur *)
    RecalibratedSensorId : INT;    (* 0=Maint, 1=P1, 2=P2, 3=PV, 4=Trémie, -1=Aucun *)
END_VAR

VAR
    TrigTremie           : R_TRIG;
    TrigPV                : R_TRIG;
    TrigP2                : R_TRIG;
    TrigP1                : R_TRIG;
    TrigMaintenance       : R_TRIG;
    CycleTimeCalc         : FB_CycleTime;
    ColdStart             : BOOL := TRUE;  // 🆕 seed unique depuis Persisted* au premier scan utile
END_VAR

// === IMPLEMENTATION ===

IF NOT Enable THEN
    Recalibrated := FALSE;
    RecalibratedSensorId := -1;
    RETURN;
END_IF;

IF ColdStart THEN
    PositionEstimatedM := PersistedPositionM;
    Initialized := PersistedInitialized;
    ColdStart := FALSE;
END_IF;

CycleTimeCalc(DefaultValueS := 0.010);
Recalibrated := FALSE;

// 1. Détection des fronts montants sur franchissement des capteurs fixes
TrigTremie(CLK := SensorTremie);
TrigPV(CLK := SensorPV);
TrigP2(CLK := SensorP2);
TrigP1(CLK := SensorP1);
TrigMaintenance(CLK := SensorMaintenance);

// 2. Recalage absolu prioritaire sur contact capteur
IF TrigMaintenance.Q THEN
    PositionEstimatedM := PosMaintenanceM;
    Recalibrated := TRUE;
    RecalibratedSensorId := 0;
ELSIF TrigP1.Q THEN
    PositionEstimatedM := PosP1M;
    Recalibrated := TRUE;
    RecalibratedSensorId := 1;
ELSIF TrigP2.Q THEN
    PositionEstimatedM := PosP2M;
    Recalibrated := TRUE;
    RecalibratedSensorId := 2;
ELSIF TrigPV.Q THEN
    PositionEstimatedM := PosPVM;
    Recalibrated := TRUE;
    RecalibratedSensorId := 3;
ELSIF TrigTremie.Q THEN
    PositionEstimatedM := PosTremieM;
    Recalibrated := TRUE;
    RecalibratedSensorId := 4;
ELSE
    // Initialisation au tout premier démarrage sur le premier capteur actif vu
    IF NOT Initialized THEN
        IF SensorTremie THEN PositionEstimatedM := PosTremieM; Initialized := TRUE;
        ELSIF SensorPV THEN PositionEstimatedM := PosPVM; Initialized := TRUE;
        ELSIF SensorP2 THEN PositionEstimatedM := PosP2M; Initialized := TRUE;
        ELSIF SensorP1 THEN PositionEstimatedM := PosP1M; Initialized := TRUE;
        ELSIF SensorMaintenance THEN PositionEstimatedM := PosMaintenanceM; Initialized := TRUE;
        END_IF;
    END_IF;

    // 3. Intégration temporelle continue (Odométrie cycle par cycle)
    // dX = Direction * (FreqHz * Gain) * dt
    IF Direction <> 0 AND DriveActualFreqHz > 0.1 THEN
        PositionEstimatedM := PositionEstimatedM + (INT_TO_REAL(Direction) * DriveActualFreqHz * GainMetersPerHzSec * CycleTimeCalc.CycleTimeS);
    END_IF;
END_IF;

// Bornage de sécurité pour éviter la dérive infinie hors rail
PositionEstimatedM := LIMIT(PosMaintenanceM - 0.5, PositionEstimatedM, PosTremieM + 0.5);

(* =======================================================================
   💾 FB_CfgPersistBridge_CommunCfg — Pont persistance pour ST_CommunCfg
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Restauration et synchronisation bidirectionnelle IHM / Persist
   💾 Persistance : Transfert GVL_PERSISTENT <-> GVL_IHM sur Initialized
   📄 Doc métier : DOC/AF/AF_Partie-03_Contrats_Composants_v2.1.md §3
   ======================================================================= *)
FUNCTION_BLOCK FB_CfgPersistBridge_CommunCfg
VAR_OUTPUT
    // === ETATS RESTAURATION ===
    JustRestored            : BOOL;               // <-- [STAT] Vrai sur le cycle de restauration initiale
END_VAR
VAR_IN_OUT
    // === BUS CONFIGURATION ET PERSISTANCE ===
    Hmi                     : ST_CommunCfg;       // <-> [BUS] Structure de configuration IHM
    Persist                 : ST_CommunCfg;       // <-> [BUS] Structure de configuration persistante
END_VAR

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

(* =======================================================================
   🔌 FB_Encoder_Abs — Acquisition codeur absolu (accès bus EtherCAT)
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Accès bus EtherCAT, extraction positions brutes et séquence de Preset SDO
   🔒 Polarité : EncoderAvailable=TRUE si communication bus et esclave OK
   🔌 Architecture : Module d'acquisition codeur absolu
   📄 Doc métier : DOC/AF/AF_Partie-09_Fonction_Encoder_v2.1.md
   ======================================================================= *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Encoder_Abs) ===

FUNCTION_BLOCK PUBLIC FB_Encoder_Abs
VAR_INPUT
    // === COMMANDES & AUTORISATIONS ===
    Enable              : BOOL;        // --> [CMD] Autorisation generale FB (TRUE=Autorise)
    Reset               : BOOL;        // --> [CMD] Acquittement defaut (front montant)
    PresetRequest       : BOOL;        // --> [CMD] Demande de preset (front montant)

    // === BUS ETHERCAT & CAPTEUR HW ===
    RawPosIn            : UDINT;       // --> [HW]  Position brute EtherCAT
    AlarmsIn            : UINT;        // --> [HW]  Codes alarmes bruts EtherCAT
    WarningsIn          : UINT;        // --> [HW]  Codes avertissements bruts EtherCAT
    SlaveOperational    : BOOL;        // --> [HW]  Statut esclave EtherCAT operationnel

    // === PARAMETRES & REGLAGES ===
    PointsPerRev        : UDINT := 8192; // --> [CFG] Resolution codeur (pts/tour)
    PresetValue         : UDINT;       // --> [CFG] Valeur cible de preset
    PresetTimeout       : TIME := T#2s;// --> [CFG] Temporisation max attente preset
    PresetTolerancePts  : UDINT := 10; // --> [CFG] Tolerance relecture post-preset (pts)
END_VAR
VAR_OUTPUT
    // === ETATS IEC & SYNOPTIQUE ===
    Ready               : BOOL;        // <-- [STAT] FB pret a fonctionner
    // 🧩 Statut transverse (forme cible) — regroupe Busy/Done/Error/ErrorId/State/StateAtError.
    // ErrorId bit0: "Com", bit1: "Preset Timeout".
    Status              : ST_FbStatus;

    // === MESURES & DONNEES CODEUR ===
    RawPos              : UDINT;       // <-- [DIAG] Position brute gelee si non disponible
    EncoderAvailable    : BOOL;        // <-- [STAT] Codeur operationnel et disponible
    AngleRaw            : UINT;        // <-- [DIAG] Angle brut sur un tour (MOD PointsPerRev)
    TurnCount           : UDINT;       // <-- [DIAG] Nombre de tours bruts (RawPos / PointsPerRev)

    // === COMMANDES & ECHANGE BUS ETHERCAT ===
    PresetAck           : BOOL;        // <-- [STAT] Pulse confirmation preset reussi
    PresetNak           : BOOL;        // <-- [STAT] Pulse refus / timeout preset
    PresetTriggerCmd    : WORD;        // <-- [ACT]  Ordre declenchement preset vers PDO Rx
    CodeSeqTriggerCmd   : WORD;        // <-- [ACT]  Ordre sequence code vers PDO Rx
    PresetValueOut      : UDINT;       // <-- [ACT]  Valeur de preset transmise au PDO Rx
END_VAR
VAR
    // === DETECTEURS DE FRONT ===
    ResetEdge           : R_TRIG;      // . [LOC] Detecteur front montant Reset
    ErrorEdge           : R_TRIG;      // . [LOC] Detecteur front montant Error
    PresetReqEdge       : R_TRIG;      // . [LOC] Detecteur front montant PresetRequest

    // === TEMPORISATEURS INTERNES ===
    PresetTimer         : TON;         // . [LOC] Temporisateur timeout sequence preset
    PresetTimerVisual   : TON;         // . [LOC] Temporisateur maintien visuel impulsion (500ms)

    // === VARIABLES INTERNES DE CALCUL & ETAT ===
    PresetSeqStep       : INT;         // . [LOC] Etape sequence preset (0:IDLE, 1:PULSE/WAIT)
    RawDiff             : DINT;        // . [LOC] Ecart signe entre RawPos et PresetValueOut
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Abs) ===

{region "§1 Gate"}
// 🛑 1. GATE
IF NOT Enable THEN
    EncoderAvailable := FALSE;
    Status.State := E_State.DISABLED;
    Ready := FALSE; Status.Busy := FALSE; Status.Done := FALSE;
    PresetTriggerCmd := 16#0000; CodeSeqTriggerCmd := 16#0000; PresetValueOut := 0;
    PresetSeqStep := 0;
    PresetTimer(IN := FALSE, PT := PresetTimeout);
    PresetTimerVisual(IN := FALSE, PT := T#500MS);
    RETURN;
END_IF;

Ready := TRUE;
Status.State := E_State.READY;
{endregion}

{region "§2 Reset front"}
// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);
{endregion}

{region "§3 Diagnostic bus et alarme"}
// 🔍 3. DIAGNOSTIC BUS / ALARME
IF (AlarmsIn <> 0) OR NOT SlaveOperational THEN
    Status.ErrorId := Status.ErrorId OR 16#0001;
ELSE
    Status.ErrorId := Status.ErrorId AND 16#FFFE; (* Auto-clearing dès que le bus et l'esclave sont OK *)
END_IF;
EncoderAvailable := (Status.ErrorId AND 16#0001) = 0;
{endregion}

{region "§4 Lecture position"}
// 📥 4. LECTURE POSITION — GELER SUR DOUTE (Partie10 §6)
// Si EncoderAvailable=FALSE : RawPos/AngleRaw/TurnCount conservent leur dernière valeur (pas de RETURN
// global ici pour ne pas geler aussi la séquence preset/l'état — seule la lecture est gelée).
IF EncoderAvailable THEN
    RawPos := RawPosIn;   // Sens de comptage géré côté codeur (CoE 6000h bit0, startup parameter CODESYS) — voir Partie10 §3bis. Plus de calcul ici.
    AngleRaw := UDINT_TO_UINT(RawPos MOD PointsPerRev);
    TurnCount := RawPos / PointsPerRev;
END_IF;
{endregion}

{region "§5 Séquence preset"}
// 🔧 5. SÉQUENCE PRESET (écriture bus)
// PresetTriggerCmd := 2 déclenche le référencement à PresetValue (valeur de commande, pas un
// masque de bits). CodeSeqTriggerCmd : rôle non identifié — laissé à 0, PAS piloté tant que sa
// fonction n'est pas confirmée. Ne jamais lui donner une valeur arbitraire.
PresetReqEdge(CLK := PresetRequest);
PresetAck := FALSE; PresetNak := FALSE; // pulses 1 cycle uniquement
CodeSeqTriggerCmd := 16#0000;           // non piloté — rôle inconnu, voir note ci-dessus
CASE PresetSeqStep OF
    0: // IDLE
        PresetTriggerCmd := 0;
        IF PresetReqEdge.Q AND EncoderAvailable THEN
            PresetValueOut := PresetValue;
            PresetSeqStep := 1;
            PresetTimer(IN := TRUE, PT := PresetTimeout);
        END_IF;
    1: // Déclenchement preset (laissé actif pendant 0.5s pour confort visuel en simulation/bus)
        PresetTriggerCmd := 2;   // Référence le codeur à PresetValueOut
        RawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(PresetValueOut);
        IF ABS(RawDiff) <= UDINT_TO_DINT(PresetTolerancePts) THEN
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := TRUE, PT := T#500MS);
            IF PresetTimerVisual.Q THEN
                PresetTriggerCmd := 0;
                PresetAck := TRUE;
                PresetSeqStep := 0;
                PresetTimerVisual(IN := FALSE, PT := T#500MS);
            END_IF;
        ELSIF PresetTimer.Q THEN
            PresetTriggerCmd := 0;
            PresetNak := TRUE;
            Status.ErrorId := Status.ErrorId OR 16#0002;
            PresetSeqStep := 0;
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := FALSE, PT := T#500MS);
        END_IF;
END_CASE;
IF ResetEdge.Q AND (PresetSeqStep = 0) THEN
    Status.ErrorId := Status.ErrorId AND 16#FFFD;
END_IF;
{endregion}

{region "§6 Error et StateAtError"}
// 🧾 6. ERROR / STATEATERROR
Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;

Status.Busy := (PresetSeqStep <> 0);
Status.Done := PresetAck;
{endregion}

(* ═══════════════════════════════════════════════════════════════
   🪝 PRG_04_Treuils_Benne — Commande des Treuils M1 (moteur de retenue) / M2 (moteur Benne), Synchro et Benne
   ───────────────────────────────────────────────────────────────
   ⚙️ Exécuté par la tâche PLC en position 4 (après PRG_03_Modes_Cycle).
   ✅ Arbitre entre les commandes Manuelles (Joystick) et Automatiques (PRG_03_Modes_Cycle).
   📄 Docs : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md ; DOC/AF/AF_Partie-10_Fonction_Winch/FB_Bucket_v1.0.md
   ═══════════════════════════════════════════════════════════════ *)

PROGRAM PRG_04_Treuils_Benne

VAR_INPUT
    // === 📥 ENTRÉES PROGRAMME (AUCUNE - PILOTÉ VIA PRG_02 & PRG_03) ===
END_VAR

VAR_OUTPUT
    // === ⚡ DEMANDES DE SORTIES FINALES & INTERLOCKS ===
    WinchM1FinalInterlockRequest : ST_WinchFinalInterlockRequest; // <-- [ACT] Demande finale et interlocks treuil M1
    WinchM2FinalInterlockRequest : ST_WinchFinalInterlockRequest; // <-- [ACT] Demande finale et interlocks treuil M2
    KoboldContactorCmdArbitrated : BOOL;                         // <-- [ACT] Ordre contacteur capteur fond Kobold (1=Alimenter)

    // === 📊 ÉTATS PUBLICS & SYNOPTIQUES DES TREUILS ===
    WinchM1State                 : ST_WinchState;                // <-- [STAT] Etat public treuil Retenue M1
    WinchM2State                 : ST_WinchState;                // <-- [STAT] Etat public treuil Benne M2
    WinchM1Safety                : ST_SafetyWinch;               // <-- [SAFE] Diagnostic et securites treuil M1
    WinchM2Safety                : ST_SafetyWinch;               // <-- [SAFE] Diagnostic et securites treuil M2
    SyncState                    : ST_SyncState;                 // <-- [STAT] Etat synchronisation treuils M1/M2
    BucketState                  : ST_BucketHMIState;            // <-- [STAT] Etat de fonctionnement benne
    Benne_IsRoughlyClosed        : BOOL;                         // <-- [STAT] Benne consideree fermee (1=Fermee)
END_VAR

VAR
    StubMachineEnableN1 : BOOL := TRUE;

    instWinchSync : FB_WinchSync;
    instBucket   : FB_Bucket;
    instSafetyWinchM1 : FB_Safety_Winch;   // Sécurité treuil M1 (SafeStop / permits / PowerCutOff)
    instSafetyWinchM2 : FB_Safety_Winch;
    instWinchM1   : FB_Winch;
    instWinchM2   : FB_Winch;
    instDiveSearch : FB_DiveSearch;
    instExtractionSequence : FB_ExtractionSequence;

    CoupledUserRequestActive : BOOL;
    CoupledUserRequestDirection     : INT;
    ManualBottomPositionConfirmed  : BOOL;
    BottomPositionConfirmed        : BOOL;
    CmdBucketCloseArbitrated       : BOOL;
    // mode "vidage à la trémie" — verrouille descente treuils (P1/Maintenance
    // uniquement) et pilote l'ouverture benne quand on demande DOWN à la trémie (MAINT_N1/N2
    // uniquement, même périmètre que instDiveSearch/instExtractionSequence).
    DumpAtTremieActive             : BOOL;
    DumpAtTremieAssistActive       : BOOL; // Sous-condition Mode MAINT_N1/N2 (assist réellement active)
    DumpAtTremieBucketOpenArmed    : BOOL; // CmdOpen_IHM déclenché par ce mode (diagnostic)

    // Séquencement automatique benne en pilotage couplé (both) normal --
    // descente uniquement benne ouverte, montée uniquement benne
    // fermée. Distinct de DumpAtTremie/DiveSearch/ExtractionSequence (fonctionnement normal,
    // pas une assistance MAINT_N1/N2 dédiée). Réutilise CoupledUserRequestActive/
    // CoupledUserRequestDirection (§1 ci-dessus) : déjà exactement "mouvement couplé (both)
    // demandé" dans les 2 modes (joystick Select=0, ou BtnWinchBothUp/Down) — mêmes variables
    // déjà utilisées par instBucket/instDiveSearch/instExtractionSequence.
    CoupledDiveBucketOpenArmed     : BOOL;  // CmdOpen_IHM déclenché par ce mécanisme (diagnostic IHM)
    CoupledMotionBlockedByBucket   : BOOL;  // Garde-fou direct -- voir §3
    CoupledAscentBucketCloseArmed  : BOOL;  // CmdClose_IHM déclenché par ce mécanisme (diagnostic IHM)
    BucketBusyRiseEdge             : R_TRIG; // Détecte le début d'une action benne (Busy monté)
    BucketBusyFallEdge             : F_TRIG; // Détecte la fin d'une action benne (Busy retombé)
    ControlAscentArmedForThisClose : BOOL;   // Mémorise si LA fermeture en cours a été armée par ce mécanisme
    ControlAscentActive            : BOOL;   // Phase vitesse contrôlée en cours (diagnostic IHM)
    ControlAscentStartM1PosM       : REAL;
    ControlAscentStartM2PosM       : REAL;

    M1LogicRequestStartStop     : BOOL;
    M1LogicRequestDirection     : INT;
    M1LogicRequestSpeedRef_Pct      : REAL;

    M2LogicRequestStartStop     : BOOL;
    M2LogicRequestDirection     : INT;
    M2LogicRequestSpeedRef_Pct      : REAL;
    M2_SpeedStepTableActive : ST_SpeedStepTable;

    SpeedGuardEnableM1 : BOOL := FALSE;
    SpeedGuardEnableM2 : BOOL := FALSE;

    BottomLimitM1_Active    : REAL;
    BottomLimitM2_Active    : REAL;
    DescendPermitM1_Active  : BOOL;
    DescendPermitM2_Active  : BOOL;

    CableLimitAscentM1Reached : BOOL;
    CableLimitAscentM2Reached : BOOL;

    SafeStopM1_Raw          : BOOL;
    SafeStopM2_Raw          : BOOL;
    SafeStopM1_Active       : BOOL;
    SafeStopM2_Active       : BOOL;
    DescendPermitM1_Raw     : BOOL;
    DescendPermitM2_Raw     : BOOL;
    AscentPermitM1_Raw      : BOOL;
    AscentPermitM2_Raw      : BOOL;
    AscentPermitM1_Active   : BOOL;
    AscentPermitM2_Active   : BOOL;

    BenneBusyFallEdge     : F_TRIG;

    // Arrêt auto descente sur détection fond Kobold (pilotage normal)
    KoboldAutoStopRiseEdge  : R_TRIG;
    KoboldAutoStopFallEdge  : F_TRIG;
    KoboldImmersionConfirmed: BOOL;
    KoboldBottomTouchLatched: BOOL;
    DescendPermitDiveBucketOpen : BOOL; // mode Dive actif + benne ouverte = descente permise
    // pilotage unitaire M2 "sécurisé" -- bornes ouvert/fermé + palier 1
    ManualBucketLimitsActive : BOOL;
    SlackCableAscentStep1    : BOOL; // mou de câble en récupération -- bride la montée au Palier 1
    BucketNotClosedAscentStep1 : BOOL; // benne non fermée à 100% à la montée -- bride la montée au Palier 1

