   🎯 Rôle : Pilotage synchrone et séquencement d'ouverture/fermeture benne
   📄 Doc métier : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md
   🔌 Interface : FB standard (Partie3 §1bis)
   🔒 Sécurité : Surveillance du glissement M1 et interlocks de mouvement
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_Bucket
VAR_INPUT
    // === COMMANDES ET ETATS GENERAL ===
    Enable                          : BOOL;                           // --> [CMD] Autorisation generale FB
    Reset                           : BOOL;                           // --> [CMD] Acquittement defauts sur front
    Mode                            : E_Mode;                         // --> [CMD] Mode de marche machine
    CmdOpen_IHM                     : BOOL;                           // --> [CMD] Demande ouverture depuis IHM
    CmdClose_IHM                    : BOOL;                           // --> [CMD] Demande fermeture depuis IHM
    MotionRequestActive             : BOOL;                           // --> [CMD] Intention mouvement arbitree
    MotionDirection                 : INT;                            // --> [CMD] Sens arbitre (1: montee, -1: descente)
    ConfirmOpenPosition             : BOOL;                           // --> [CMD] Bouton IHM confirmation benne ouvert
    ConfirmClosePosition            : BOOL;                           // --> [CMD] Bouton IHM confirmation benne ferme

    // === SECOURS ET HARDWARE ===
    PowerContactorEngaged           : BOOL;                           // --> [SAFE] Condition d'arret d'urgence / puissance
    CablePosM1                      : REAL;                           // --> [HW] Position reelle cable treuil M1 (m)
    CablePosM2                      : REAL;                           // --> [HW] Position reelle cable treuil M2 (m)
    HomedM1                         : BOOL;                           // --> [HW] Codeur M1 reference
    HomedM2                         : BOOL;                           // --> [HW] Codeur M2 reference
    M1_Busy                         : BOOL;                           // --> [HW] Treuil M1 en mouvement (Busy)
    M2_Busy                         : BOOL;                           // --> [HW] Treuil M2 en mouvement (Busy)
    InhibitM1                       : BOOL;                           // --> [HW] Treuil M1 inhibe
    InhibitM2                       : BOOL;                           // --> [HW] Treuil M2 inhibe

    // === REGLAGES ET CONFIGURATION ===
    Config                          : ST_BucketConfig;                // --> [CFG] Configuration parametres benne
    CfgTimeoutDuration              : TIME := T#60s;                  // --> [CFG] Timeout de mouvement configurable
    M1SlipToleranceM                : REAL := 1.0;                    // --> [CFG] Tolerance glissement M1 pendant Busy (m)

    // === BYPASSES ET SIMULATION ===
    BypassGlobal                    : BOOL := FALSE;                  // --> [TST] Force ErrorId=0 global
END_VAR
VAR_OUTPUT
    // === ETATS IEC ET SYNOPTIQUE ===
    Ready                           : BOOL;                           // <-- [STAT] FB pret a fonctionner
    Status                          : ST_FbStatus;                    // <-- [FB] Statut complet (Busy/Done/Error/ErrorId/State/StateAtError)

    // === DEMANDES ET ORDRES ACTIONNEURS ===
    CloseReq                        : BOOL;                           // <-- [STAT] Demande de fermeture memorisee
    OpenReq                         : BOOL;                           // <-- [STAT] Demande d'ouverture memorisee
    M2_StartStop                    : BOOL;                           // <-- [ACT] Ordre StartStop vers Winch M2
    M2_Direction                    : INT;                            // <-- [ACT] Ordre Direction vers Winch M2
    M2_ForceSlowSpeed               : BOOL;                           // <-- [ACT] Forcage vitesse lente sur M2

    // === DIAGNOSTICS ET MESURES ===
    M1SlipDetected                  : BOOL;                           // <-- [DIAG] Glissement M1 detecte
    ActiveOffsetM                   : REAL;                           // <-- [DIAG] Decalage cible pour FB_WinchSync
    DeltaPosition_M                 : REAL;                           // <-- [DIAG] Ecart reel signe M2 - M1 (m)
    RemainingTravelM                : REAL;                           // <-- [DIAG] Distance restante avant cible (m)
END_VAR
VAR_IN_OUT
    // === STRUCTURES DE DONNÉES PARTAGÉES ===
    BucketState                     : ST_BucketState;                 // <-> [BUS] Etat physique memorise du benne
END_VAR
VAR
    // === DETECTEURS ET TIMERS INTERNES ===
    ResetEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Reset
    ErrorEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Erreur
    BusyEdge                        : R_TRIG;                         // . [LOC] Detecteur entree en etat Busy
    ConfirmOpenEdge                 : R_TRIG;                         // . [LOC] Detecteur front confirmation ouverture
    ConfirmCloseEdge                : R_TRIG;                         // . [LOC] Detecteur front confirmation fermeture
    TonTimeout                      : TON;                            // . [LOC] Temporisateur timeout de mouvement

    // === VARIABLES LOCALES CALCULÉES ===
    FirstCycle                      : BOOL := TRUE;                  // . [LOC] Drapeau de premier cycle API
    SevereError                     : BOOL;                           // . [LOC] Erreur grave necessitant arret
    MaxAllowedOffset                : REAL;                           // . [LOC] Offset max calcule dynamiquement
    M1RefPosM                       : REAL;                           // . [LOC] Position M1 memorisee a l'entree Busy
    M2StartPosM                     : REAL;                           // . [LOC] Position M2 memorisee a l'entree Busy
    WasOpenAtStart                  : BOOL;                           // . [LOC] Etat IsOpen memorise a l'entree Busy
    WasClosedAtStart                : BOOL;                           // . [LOC] Etat IsClosed memorise a l'entree Busy
    LeftStartSinceArm               : BOOL;                           // . [LOC] Quitte position de depart
    HoldOffsetM                     : REAL;                           // . [LOC] Ecart reel mémorise (gel en position intermediaire)
END_VAR

{region "§1 Gate securite"}
// 🛑 1. GATE DE SÉCURITÉ
IF NOT Enable OR NOT PowerContactorEngaged THEN
    IF (Status.State = E_State.BUSY) OR CloseReq OR OpenReq THEN
        BucketState.StateIncoherent := TRUE;
    END_IF;
    Ready := FALSE;
    Status.Busy := FALSE;
    Status.Done := FALSE;
    M2_StartStop := FALSE;
    M2_Direction := 0;
    M2_ForceSlowSpeed := FALSE;
    Status.State := E_State.DISABLED;
    M1SlipDetected := FALSE;
    // Les requêtes internes sont réinitialisées
    CloseReq := FALSE;
    OpenReq := FALSE;
    RETURN;
END_IF;

// 🟢 ÉTAT INITIAL READY SI DISABLED PRÉCÉDEMMENT
IF Status.State = E_State.DISABLED THEN
    Status.State := E_State.READY;
END_IF;

{endregion}

{region "§2 Reset et bypass"}
// 🔑 2. GESTION DU RESET (FRONT MONTANT)
ResetEdge(CLK := Reset);

// 🌐 BYPASS GLOBAL : force ErrorId = 0 (ignore toutes les erreurs benne)
IF BypassGlobal THEN
    Status.ErrorId := 16#0000;
END_IF;

IF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFFA; // Efface les bits 0 et 2 (Timeout, Limites)
END_IF;

{endregion}

{region "§3 Coherence et etat mecanique benne"}
// 📏 3. DÉTECTION D'INCOHÉRENCE AU BOOT (PREMIER CYCLE API)
IF FirstCycle THEN
    FirstCycle := FALSE;
    IF Config.CoherenceLimitM > 0.01 THEN
        IF BucketState.IsOpen AND NOT BucketState.IsClosed THEN
            IF ABS(CablePosM2 - BucketState.LastPosM2Open) > Config.CoherenceLimitM THEN
                BucketState.StateIncoherent := TRUE;
            END_IF;
        ELSIF BucketState.IsClosed AND NOT BucketState.IsOpen THEN
            IF ABS(CablePosM2 - BucketState.LastPosM2Close) > Config.CoherenceLimitM THEN
                BucketState.StateIncoherent := TRUE;
            END_IF;
        ELSE
            // Si l'état n'a jamais été initialisé (les deux FALSE/TRUE), on signale une incohérence
            BucketState.StateIncoherent := TRUE;
        END_IF;
    ELSE
        // Limite non configurée ou invalide, par précaution on force l'incohérence
        BucketState.StateIncoherent := TRUE;
    END_IF;
END_IF;

// Met à jour le bit1 d'erreur si incohérence détectée
IF BucketState.StateIncoherent THEN
    Status.ErrorId := Status.ErrorId OR 16#0002;
    // Force l'état inconnu (ni ouvert ni fermé) si incohérence active
    BucketState.IsOpen := FALSE;
    BucketState.IsClosed := FALSE;
ELSE
    Status.ErrorId := Status.ErrorId AND 16#FFFD;
END_IF;

// 🧲 3bis. GARDE-FOU CODEURS NON RÉFÉRENCÉS (bit 3)
// CablePosM1/CablePosM2 ne sont fiables que si le homing (Partie10) a été fait sur les 2 treuils.
// Continu (pas de front Reset) : se lève/efface tout seul selon l'état réel du homing.
IF NOT HomedM1 OR NOT HomedM2 THEN
    Status.ErrorId := Status.ErrorId OR 16#0008;
ELSE
    Status.ErrorId := Status.ErrorId AND 16#FFF7;
END_IF;

// 3bis-bis. CONFIRMATION MANUELLE POSITION OUVERTE — voir bandeau
// Action de CONFIRMATION (aucun mouvement, ne pilote pas M2) : acquitte les défauts et réinitialise
// les demandes. L'état IsOpen/IsClosed reste STRICTEMENT évalué en continu (§3bis-quater) selon la position codeur réelle.
ConfirmOpenEdge(CLK := ConfirmOpenPosition);
IF ConfirmOpenEdge.Q
   AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2)
   AND NOT M1_Busy AND NOT M2_Busy THEN
    BucketState.LastPosM2Open := CablePosM2;
    BucketState.LastPosM2Close := CablePosM2 - Config.OffsetOpenM + Config.OffsetCloseM;
    Status.ErrorId := 16#0000;      // Réinitialisation complète des défauts benne lors du référencement manuel
    CloseReq := FALSE;              // Reset des demandes en attente pour éviter les démarrages intempestifs
    OpenReq := FALSE;
END_IF;

// 3bis-ter. CONFIRMATION MANUELLE POSITION FERMÉE
// Même principe que ConfirmOpenPosition pour acquitter et réinitialiser.
ConfirmCloseEdge(CLK := ConfirmClosePosition);
IF ConfirmCloseEdge.Q
   AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2)
   AND NOT M1_Busy AND NOT M2_Busy THEN
    BucketState.LastPosM2Close := CablePosM2;
    BucketState.LastPosM2Open := CablePosM2 - Config.OffsetCloseM + Config.OffsetOpenM;
    Status.ErrorId := 16#0000;      // Réinitialisation complète des défauts benne lors du référencement manuel
    CloseReq := FALSE;              // Reset des demandes en attente pour éviter les démarrages intempestifs
    OpenReq := FALSE;
END_IF;

// 3bis-quater. DÉTECTION AUTOMATIQUE EN CONTINU (5 ZONES CLAIRES OPÉRATEUR) :
// Recalcule IsOpen, IsClosed, TooOpen, TooClosed, IsIntermediate en PERMANENCE à partir de
// l'écart réel Delta = CablePosM2 - CablePosM1 et de la tolérance Config.CoherenceLimitM.
// Actif à l'arrêt (NOT M1_Busy/M2_Busy), hors séquence active (State <> BUSY), codeurs référencés.
IF (Status.State <> E_State.BUSY) AND NOT M1_Busy AND NOT M2_Busy AND HomedM1 AND HomedM2
   AND (Config.CoherenceLimitM > 0.01) THEN

    // 1. Zone Benne Ouverte (Delta proche de OffsetOpenM)
    IF ABS((CablePosM2 - CablePosM1) - Config.OffsetOpenM) <= Config.CoherenceLimitM THEN
        BucketState.IsOpen := TRUE;
        BucketState.IsClosed := FALSE;
        BucketState.TooOpen := FALSE;
        BucketState.TooClosed := FALSE;
        BucketState.IsIntermediate := FALSE;
        BucketState.LastPosM2Open := CablePosM2;
        BucketState.StateIncoherent := FALSE;

    // 2. Zone Benne Fermée (Delta proche de OffsetCloseM)
    ELSIF ABS((CablePosM2 - CablePosM1) - Config.OffsetCloseM) <= Config.CoherenceLimitM THEN
        BucketState.IsClosed := TRUE;
        BucketState.IsOpen := FALSE;
        BucketState.TooOpen := FALSE;
        BucketState.TooClosed := FALSE;
        BucketState.IsIntermediate := FALSE;
        BucketState.LastPosM2Close := CablePosM2;
        BucketState.StateIncoherent := FALSE;

    // 3. Zone Trop Ouvert (Dépassement en ouverture : Delta < OffsetOpenM - Tolerance)
    ELSIF (CablePosM2 - CablePosM1) < (Config.OffsetOpenM - Config.CoherenceLimitM) THEN
        BucketState.IsOpen := FALSE;
        BucketState.IsClosed := FALSE;
        BucketState.TooOpen := TRUE;
        BucketState.TooClosed := FALSE;
        BucketState.IsIntermediate := FALSE;
        BucketState.StateIncoherent := TRUE;

    // 4. Zone Trop Fermé (Dépassement en fermeture : Delta > OffsetCloseM + Tolerance)
    ELSIF (CablePosM2 - CablePosM1) > (Config.OffsetCloseM + Config.CoherenceLimitM) THEN
        BucketState.IsOpen := FALSE;
        BucketState.IsClosed := FALSE;
        BucketState.TooOpen := FALSE;
        BucketState.TooClosed := TRUE;
        BucketState.IsIntermediate := FALSE;
        BucketState.StateIncoherent := TRUE;

    // 5. Zone Intermédiaire / Entrebâillée (entre OffsetOpenM + Tol et OffsetCloseM - Tol)
    ELSE
        BucketState.IsOpen := FALSE;
        BucketState.IsClosed := FALSE;
        BucketState.TooOpen := FALSE;
        BucketState.TooClosed := FALSE;
        BucketState.IsIntermediate := TRUE;
        BucketState.StateIncoherent := FALSE;
    END_IF;
END_IF;

// 🔍 3ter. MÉCA C COUCHE 1 — GLISSEMENT M1 PENDANT BUSY (bit4)
// M1 doit rester immobile pendant que M2 bouge seul. Référence prise à l'entrée en Busy.
BusyEdge(CLK := (Status.State = E_State.BUSY));
IF BusyEdge.Q THEN
    M1RefPosM := CablePosM1;
    M2StartPosM := CablePosM2;   // Borne le recul autorisé (voir §6 CASE BUSY)
    // Mémorise l'état d'origine (restauré si recul complet jusqu'à M2StartPosM, voir §6 CASE BUSY)
    // puis passe en position transitoire dès le démarrage du mouvement — ni ouvert ni fermé pendant
    // le trajet, quel que soit l'état mémorisé avant.
    WasOpenAtStart := BucketState.IsOpen;
    WasClosedAtStart := BucketState.IsClosed;
    LeftStartSinceArm := FALSE;
    BucketState.IsOpen := FALSE;
    BucketState.IsClosed := FALSE;
END_IF;

IF (Status.State = E_State.BUSY) AND (ABS(CablePosM1 - M1RefPosM) > M1SlipToleranceM) AND NOT InhibitM1 THEN
    Status.ErrorId := Status.ErrorId OR 16#0010;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFEF;
END_IF;
M1SlipDetected := (Status.ErrorId AND 16#0010) <> 16#0000;

{endregion}

{region "§4 Surveillance limites timeout et arret"}
// 🚨 4. SURVEILLANCE DES LIMITES DE PLACEMENT (Limites dépassées - bit 2)
// On s'assure que l'écart réel M1/M2 ne dépasse pas les offsets de configuration + marge de sécurité de 1m
MaxAllowedOffset := MAX(ABS(Config.OffsetOpenM), ABS(Config.OffsetCloseM)) + 1.0;
IF (ABS(CablePosM1 - CablePosM2) > MaxAllowedOffset) AND NOT InhibitM1 AND NOT InhibitM2 THEN
    Status.ErrorId := Status.ErrorId OR 16#0004;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFFB;
END_IF;

// ⏲️ 5. SURVEILLANCE TIMEOUT MOUVEMENT (bit 0)
// Déclenche si le mouvement actif (M2_StartStop = TRUE) dure plus longtemps que le timeout
TonTimeout(IN := (Status.State = E_State.BUSY AND M2_StartStop), PT := CfgTimeoutDuration);
IF TonTimeout.Q THEN
    Status.ErrorId := Status.ErrorId OR 16#0001;
END_IF;

// ❌ Évaluation des erreurs graves (Timeout, Limites dépassées, Codeur(s) non référencé(s), ou Glissement M1)
SevereError := (Status.ErrorId AND 16#001D) <> 16#0000;

IF SevereError THEN
    IF (Status.State = E_State.BUSY) OR CloseReq OR OpenReq THEN
        BucketState.StateIncoherent := TRUE;
    END_IF;
    M2_StartStop := FALSE;
    M2_Direction := 0;
    M2_ForceSlowSpeed := FALSE;
    CloseReq := FALSE;
    OpenReq := FALSE;
    // On repasse en READY et attend un Reset
    Status.State := E_State.READY;
END_IF;

{endregion}

{region "§5 Machine etat commande"}
// 🎛️ 6. MACHINE À ÉTATS DE COMMANDE
CASE Status.State OF
    E_State.READY:
        Ready := TRUE;
        Status.Busy := FALSE;
        Status.Done := FALSE;
        M2_StartStop := FALSE;
        M2_Direction := 0;
        M2_ForceSlowSpeed := FALSE;
        RemainingTravelM := 0.0; // Pas de mouvement en cours

        // Demande benne acceptée UNIQUEMENT si M1 ET M2 sont à l'arrêt (tous
        // modes) — évite qu'un mouvement en cours sur l'un des deux treuils "traverse" l'armement
        // du benne. Ni mémorisation de la requête, ni démarrage tant que ce
        // n'est pas vrai — l'opérateur doit refaire la demande une fois les treuils arrêtés.
        IF NOT M1_Busy AND NOT M2_Busy THEN
            // Mémorisation des requêtes IHM (l'une annule l'autre)
            IF CmdClose_IHM AND NOT SevereError THEN
                CloseReq := TRUE;
                OpenReq := FALSE;
            ELSIF CmdOpen_IHM AND NOT SevereError THEN
                OpenReq := TRUE;
                CloseReq := FALSE;
            END_IF;

            // Condition d'activation du mouvement (Requête IHM + Validation Joystick dans le bon sens)
            // Sens inversés (enroulage ferme, déroulage ouvre)
            IF CloseReq AND MotionRequestActive AND (MotionDirection = 1) THEN
                Status.State := E_State.BUSY;
            ELSIF OpenReq AND MotionRequestActive AND (MotionDirection = -1) THEN
                Status.State := E_State.BUSY;
            END_IF;
        END_IF;

    E_State.BUSY:
        Ready := TRUE;
        Status.Busy := TRUE;
        Status.Done := FALSE;
        M2_ForceSlowSpeed := TRUE; // Vitesse lente forcée sans contacteurs

        // Distance restante avant cible, pour affichage IHM (aiguille/jauge)
        // Toujours positive, décroît vers 0 à mesure que M2 approche la cible.
        IF CloseReq THEN
            RemainingTravelM := MAX(0.0, (CablePosM1 + Config.OffsetCloseM) - CablePosM2);
        ELSIF OpenReq THEN
            RemainingTravelM := MAX(0.0, CablePosM2 - (CablePosM1 + Config.OffsetOpenM));
        ELSE
            RemainingTravelM := 0.0;
        END_IF;

        // Interlock Homme-mort joystick
        // Sens inverse autorisé (recul/annulation partielle) pendant CloseReq/OpenReq, mais BORNÉ
        // à la position de départ (M2StartPosM, mémorisée à l'entrée en Busy) — ne permet jamais de
        // dépasser cette position dans le sens opposé au sens principal.
        IF NOT MotionRequestActive THEN
            // Si relâchement de l'intention opérateur, arrêt temporaire du mouvement.
            M2_StartStop := FALSE;
            M2_Direction := 0;
        ELSIF CloseReq THEN
            IF (MotionDirection = 1) THEN
                // Sens principal (fermeture) : M2 enroule (monte)
                M2_StartStop := TRUE;
                M2_Direction := 1;
            ELSIF (MotionDirection = -1) AND (CablePosM2 > M2StartPosM) THEN
                // Sens inverse : recul autorisé UNIQUEMENT tant qu'on n'est pas revenu à la position
                // de départ (pas au-delà, donc pas de ré-ouverture complète depuis ici)
                M2_StartStop := TRUE;
                M2_Direction := -1;
            ELSE
                // Mauvais sens, ou position de départ déjà atteinte en reculant : arrêt
                M2_StartStop := FALSE;
                M2_Direction := 0;
            END_IF;
        ELSIF OpenReq THEN
            IF (MotionDirection = -1) THEN
                // Sens principal (ouverture) : M2 déroule (descend)
                M2_StartStop := TRUE;
                M2_Direction := -1;
            ELSIF (MotionDirection = 1) AND (CablePosM2 < M2StartPosM) THEN
                // Sens inverse : recul autorisé UNIQUEMENT tant qu'on n'est pas revenu à la position
                // de départ (pas au-delà, donc pas de re-fermeture complète depuis ici)
                M2_StartStop := TRUE;
                M2_Direction := 1;
            ELSE
                M2_StartStop := FALSE;
                M2_Direction := 0;
            END_IF;
        ELSE
            M2_StartStop := FALSE;
            M2_Direction := 0;
        END_IF;

        // Détecte qu'on a réellement quitté la position de départ (évite que le test de retour
        // ci-dessous ne se déclenche instantanément au 1er cycle de Busy, où CablePosM2 =
        // M2StartPosM par définition).
        IF (CloseReq AND (CablePosM2 > M2StartPosM)) OR (OpenReq AND (CablePosM2 < M2StartPosM)) THEN
            LeftStartSinceArm := TRUE;
        END_IF;

        // Condition d'arrêt automatique de la fermeture
        IF CloseReq THEN
            // Compense l'inertie mécanique (coast-down) : coupe la commande
            // CloseAnticipationM avant OffsetCloseM pour amener l'arrêt réel près du
            // vrai offset au lieu de le dépasser.
            IF CablePosM2 >= (CablePosM1 + Config.OffsetCloseM - Config.CloseAnticipationM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                // Mémorisation de l'état physique fermé
                BucketState.IsOpen := FALSE;
                BucketState.IsClosed := TRUE;
                BucketState.LastPosM2Close := CablePosM2;
                BucketState.StateIncoherent := FALSE; // recalage réussi

                CloseReq := FALSE;
                Status.State := E_State.DONE;
            // Recul complet jusqu'à la position de départ — restaure l'état d'origine
            // (physiquement, on est revenu là où on a commencé)
            ELSIF LeftStartSinceArm AND (CablePosM2 <= M2StartPosM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                BucketState.IsOpen := WasOpenAtStart;
                BucketState.IsClosed := WasClosedAtStart;

                CloseReq := FALSE;
                Status.State := E_State.DONE;
            END_IF;
        END_IF;

        // Condition d'arrêt automatique de l'ouverture
        IF OpenReq THEN
            // Même logique que la fermeture ci-dessus, inertie différente en ouverture
            // (OpenAnticipationM distinct).
            IF CablePosM2 <= (CablePosM1 + Config.OffsetOpenM + Config.OpenAnticipationM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                // Mémorisation de l'état physique ouvert
                BucketState.IsOpen := TRUE;
                BucketState.IsClosed := FALSE;
                BucketState.LastPosM2Open := CablePosM2;
                BucketState.StateIncoherent := FALSE; // recalage réussi

                OpenReq := FALSE;
                Status.State := E_State.DONE;
            // Recul complet jusqu'à la position de départ — restaure l'état d'origine
            // (physiquement, on est revenu là où on a commencé)
            ELSIF LeftStartSinceArm AND (CablePosM2 >= M2StartPosM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                BucketState.IsOpen := WasOpenAtStart;
                BucketState.IsClosed := WasClosedAtStart;

                OpenReq := FALSE;
                Status.State := E_State.DONE;
            END_IF;
        END_IF;

    E_State.DONE:
        Ready := TRUE;
        Status.Busy := FALSE;
        Status.Done := TRUE;
        M2_StartStop := FALSE;
        M2_Direction := 0;
        M2_ForceSlowSpeed := FALSE;
        RemainingTravelM := 0.0; // Cible atteinte

        // Attente du relâchement de la validation joystick pour repasser à READY
        IF NOT MotionRequestActive THEN
            Status.State := E_State.READY;
        END_IF;
END_CASE;

// 📤 7. GESTION DES SORTIES D'ÉTAT GLOBALES
Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;

// Calcul continu de l'écart réel signé M2 - M1 pour l'affichage IHM et l'aide au pilotage
DeltaPosition_M := CablePosM2 - CablePosM1;

// Détermination de l'offset actif pour le synchronisme de FB_WinchSync ET pour l'affichage IHM
// (M2PositionCorrected, côté PRG_SUPERVISION_CFC).
// CloseReq/OpenReq sont pris en compte (pas seulement IsClosed/IsOpen, qui sont FALSE pendant
// TOUT le trajet depuis l'état transitoire) pour que la position corrigée de M2 converge
// progressivement vers M1 pendant l'enroulage.
IF Status.State = E_State.BUSY THEN
    // Pendant le déplacement, l'offset actif suit la différence réelle de câble (M2 - M1) afin que
    // la position corrigée de M2 reste stable (égale à M1, cad la hauteur du benne) sans à-coup,
    // tandis que le câble brut de M2 montre son enroulement.
    ActiveOffsetM := CablePosM2 - CablePosM1;
    HoldOffsetM := ActiveOffsetM;   // Mémorise l'écart réel pour le gel en position intermédiaire
ELSIF CloseReq OR BucketState.IsClosed THEN
    ActiveOffsetM := Config.OffsetCloseM;
    HoldOffsetM := ActiveOffsetM;
ELSIF OpenReq OR BucketState.IsOpen THEN
    ActiveOffsetM := Config.OffsetOpenM;
    HoldOffsetM := ActiveOffsetM;
ELSE
    // Position intermédiaire non référencée : gèle l'écart réel mémorisé (HoldOffsetM) au lieu de
    // sauter vers la config. Évite l'à-coup sur la position corrigée M2 / la synchro.
    ActiveOffsetM := HoldOffsetM;
END_IF;

{endregion}

(* =======================================================================
   📊 FB_Diag_Ethercat — Diagnostic bus EtherCAT & Esclaves (M3, COD1, COD2)
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Surveillance bus EtherCAT master, variateur M3 et codeurs M1/M2
   🔌 Architecture : Publication ST_Diag_Device par esclave & E_Diag_State
   📄 Doc métier : DOC/AF/AF_Partie-12_Fonction_Diagnostic_v1.0.md
   ======================================================================= *)
FUNCTION_BLOCK PUBLIC FB_Diag_Ethercat
VAR_INPUT
    // === COMMANDES & CONTROLE ===
    Enable                      : BOOL;         // --> [CMD] Active la surveillance EtherCAT
    Reset                       : BOOL;         // --> [CMD] Front d'acquittement des defauts

    // === ETATS BRUTS MATERIEL & BYPASS VARIATEUR M3 ===
    DeviceVariateurStateRaw     : DEVICE_STATE; // --> [HW]  Valeur brute AC600_ECAT_Drive.GetDeviceState()
    DeviceVariateurSimBypass    : BOOL;         // --> [TST] TRUE = simulation active variateur M3

    // === ETATS BRUTS MATERIEL & BYPASS ENCODEUR M1 ===
    DeviceEncoderM1StateRaw     : DEVICE_STATE; // --> [HW]  Valeur brute COD1_CODEUR.GetDeviceState()
    DeviceEncoderM1SimBypass    : BOOL;         // --> [TST] TRUE = simulation active encodeur M1

    // === ETATS BRUTS MATERIEL & BYPASS ENCODEUR M2 ===
    DeviceEncoderM2StateRaw     : DEVICE_STATE; // --> [HW]  Valeur brute COD2_CODEUR.GetDeviceState()
    DeviceEncoderM2SimBypass    : BOOL;         // --> [TST] TRUE = simulation active encodeur M2

    // === BYPASS RESEAU IHM ===
    NetworkBypassActive         : BOOL;         // --> [TST] TRUE = bypass reseau global IHM
END_VAR
VAR_OUTPUT
    // === ETATS IEC & CONFORMITE ===
    Ready                       : BOOL;         // <-- [STAT] Logique de surveillance active
    Busy                        : BOOL;         // <-- [STAT] Non utilise (conformite interface)
    Done                        : BOOL;         // <-- [STAT] Non utilise
    State                       : E_Diag_State; // <-- [STAT] Phase courante du diagnostic global

    // === DIAGNOSTICS & ALARMES ===
    Error                       : BOOL;         // <-- [DIAG] Resume anomalie de communication bus
    ErrorId                     : WORD;         // <-- [DIAG] Code defaut global resume
    StateAtError                : E_Diag_State; // <-- [DIAG] Phase figee a l'apparition de l'erreur
    DeviceEthercatMaster        : ST_Diag_Device; // <-- [DIAG] Diagnostics bus EtherCAT
    DeviceVariateur             : ST_Diag_Device; // <-- [DIAG] Diagnostics esclave AC600
    DeviceEncoderM1             : ST_Diag_Device; // <-- [DIAG] Diagnostics esclave COD1
    DeviceEncoderM2             : ST_Diag_Device; // <-- [DIAG] Diagnostics esclave COD2

    // === MIROIRS BRUTS MATERIEL ===
    DeviceVariateurStateRawOut  : DEVICE_STATE; // <-- [DIAG] Miroir brut status variateur M3
    DeviceEncoderM1StateRawOut  : DEVICE_STATE; // <-- [DIAG] Miroir brut status encodeur M1
    DeviceEncoderM2StateRawOut  : DEVICE_STATE; // <-- [DIAG] Miroir brut status encodeur M2
END_VAR
VAR
    // === SOUS-INSTANCES FB ===
    ResetEdge                   : R_TRIG;       // * [INST] Detecteur front de reset

    // === CALCULS ET ETATS INTERNES ===
    VariateurOnlineReal         : BOOL;         // . [LOC]  GetDeviceState() = RUNNING, hors tout bypass
    EncoderM1OnlineReal         : BOOL;         // . [LOC]  GetDeviceState() = RUNNING, hors tout bypass
    EncoderM2OnlineReal         : BOOL;         // . [LOC]  GetDeviceState() = RUNNING, hors tout bypass
    VariateurBypass             : BOOL;         // . [LOC]  Simulation OU bypass reseau IHM variateur
    EncoderM1Bypass             : BOOL;         // . [LOC]  Simulation OU bypass reseau IHM encodeur M1
    EncoderM2Bypass             : BOOL;         // . [LOC]  Simulation OU bypass reseau IHM encodeur M2
    VariateurOnlineEff          : BOOL;         // . [LOC]  Online effectif (reel OU bypass)
    EncoderM1OnlineEff          : BOOL;         // . [LOC]  Online effectif (reel OU bypass)
    EncoderM2OnlineEff          : BOOL;         // . [LOC]  Online effectif (reel OU bypass)
END_VAR

{region "§1 Gate de desactivation"}
// 🛑 1. GATE : Désactivation si Enable = FALSE
IF NOT Enable THEN
    Ready := FALSE;
    State := E_Diag_State.DISABLED;
    DeviceVariateur.State := E_Diag_State.DISABLED;
    DeviceEncoderM1.State := E_Diag_State.DISABLED;
    DeviceEncoderM2.State := E_Diag_State.DISABLED;
    DeviceVariateur.Online := FALSE;
    DeviceEncoderM1.Online := FALSE;
    DeviceEncoderM2.Online := FALSE;
    DeviceVariateur.Operational := FALSE;
    DeviceEncoderM1.Operational := FALSE;
    DeviceEncoderM2.Operational := FALSE;
    DeviceVariateur.Error := FALSE;
    DeviceEncoderM1.Error := FALSE;
    DeviceEncoderM2.Error := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    DeviceEthercatMaster.State := E_Diag_State.DISABLED;
    DeviceEthercatMaster.Online := FALSE;
    DeviceEthercatMaster.Operational := FALSE;
    DeviceVariateurStateRawOut := DeviceVariateurStateRaw;
    DeviceEncoderM1StateRawOut := DeviceEncoderM1StateRaw;
    DeviceEncoderM2StateRawOut := DeviceEncoderM2StateRaw;
    RETURN;
END_IF;

Ready := TRUE;

{endregion}

{region "§2 Interpretation etats bruts et bypass"}
// 🧮 2. INTERPRÉTATION DES VALEURS BRUTES
VariateurOnlineReal := (DeviceVariateurStateRaw = DEVICE_STATE.RUNNING);
EncoderM1OnlineReal := (DeviceEncoderM1StateRaw = DEVICE_STATE.RUNNING);
EncoderM2OnlineReal := (DeviceEncoderM2StateRaw = DEVICE_STATE.RUNNING);

VariateurBypass := DeviceVariateurSimBypass OR NetworkBypassActive;
EncoderM1Bypass := DeviceEncoderM1SimBypass OR NetworkBypassActive;
EncoderM2Bypass := DeviceEncoderM2SimBypass OR NetworkBypassActive;

VariateurOnlineEff := VariateurOnlineReal OR VariateurBypass;
EncoderM1OnlineEff := EncoderM1OnlineReal OR EncoderM1Bypass;
EncoderM2OnlineEff := EncoderM2OnlineReal OR EncoderM2Bypass;

// 🔑 3. RESET FRONT
ResetEdge(CLK := Reset);

{endregion}

{region "§3 Diagnostic par equipement"}
// 🔍 4. DIAGNOSTIC VARIATEUR (AC600_ECAT_Drive / Translation M3)
DeviceVariateur.Online := VariateurOnlineEff;
DeviceVariateur.Operational := VariateurOnlineEff;

IF NOT DeviceVariateur.Online THEN
    DeviceVariateur.ErrorId := DeviceVariateur.ErrorId OR 16#0010;  (* Perte liaison physique variateur *)
ELSE
    DeviceVariateur.ErrorId := DeviceVariateur.ErrorId AND 16#FFEF; (* Effacement auto dès que RUNNING *)
END_IF;

// 🔍 5. DIAGNOSTIC ENCODEUR M1 (COD1_CODEUR / WinchM1)
DeviceEncoderM1.Online := EncoderM1OnlineEff;
DeviceEncoderM1.Operational := EncoderM1OnlineEff;

IF NOT DeviceEncoderM1.Online THEN
    DeviceEncoderM1.ErrorId := DeviceEncoderM1.ErrorId OR 16#0020;  (* Perte liaison encodeur M1 *)
ELSE
    DeviceEncoderM1.ErrorId := DeviceEncoderM1.ErrorId AND 16#FFDF; (* Effacement auto dès que RUNNING *)
END_IF;

// 🔍 6. DIAGNOSTIC ENCODEUR M2 (COD2_CODEUR / WinchM2)
DeviceEncoderM2.Online := EncoderM2OnlineEff;
DeviceEncoderM2.Operational := EncoderM2OnlineEff;

IF NOT DeviceEncoderM2.Online THEN
    DeviceEncoderM2.ErrorId := DeviceEncoderM2.ErrorId OR 16#0030;  (* Perte liaison encodeur M2 *)
ELSE
    DeviceEncoderM2.ErrorId := DeviceEncoderM2.ErrorId AND 16#FFCF; (* Effacement auto dès que RUNNING *)
END_IF;

{endregion}

{region "§4 Etats diagnostic par equipement"}
// 🚦 7. STATE MACHINES DE CHAQUE APPAREIL
IF DeviceVariateur.ErrorId <> 0 THEN
    DeviceVariateur.State := E_Diag_State.ERROR;
ELSIF NOT VariateurOnlineEff THEN
    DeviceVariateur.State := E_Diag_State.INIT;
ELSIF VariateurBypass AND NOT VariateurOnlineReal THEN
    DeviceVariateur.State := E_Diag_State.SIMULATED;
ELSE
    DeviceVariateur.State := E_Diag_State.READY;
END_IF;

IF DeviceEncoderM1.ErrorId <> 0 THEN
    DeviceEncoderM1.State := E_Diag_State.ERROR;
ELSIF NOT EncoderM1OnlineEff THEN
    DeviceEncoderM1.State := E_Diag_State.INIT;
ELSIF EncoderM1Bypass AND NOT EncoderM1OnlineReal THEN
    DeviceEncoderM1.State := E_Diag_State.SIMULATED;
ELSE
    DeviceEncoderM1.State := E_Diag_State.READY;
END_IF;

IF DeviceEncoderM2.ErrorId <> 0 THEN
    DeviceEncoderM2.State := E_Diag_State.ERROR;
ELSIF NOT EncoderM2OnlineEff THEN
    DeviceEncoderM2.State := E_Diag_State.INIT;
ELSIF EncoderM2Bypass AND NOT EncoderM2OnlineReal THEN
    DeviceEncoderM2.State := E_Diag_State.SIMULATED;
ELSE
    DeviceEncoderM2.State := E_Diag_State.READY;
END_IF;

// Fige la phase du diagnostic global sur le premier défaut
IF (DeviceVariateur.ErrorId <> 0 OR DeviceEncoderM1.ErrorId <> 0 OR DeviceEncoderM2.ErrorId <> 0) THEN
    IF StateAtError = E_Diag_State.DISABLED THEN
        StateAtError := State;
    END_IF;
END_IF;

{endregion}

{region "§5 Synthese EtherCAT et sorties"}
// 📤 8. RÉSUMÉ ET DÉFAUTS
DeviceVariateur.Error := (DeviceVariateur.ErrorId <> 0);
DeviceEncoderM1.Error := (DeviceEncoderM1.ErrorId <> 0);
DeviceEncoderM2.Error := (DeviceEncoderM2.ErrorId <> 0);

Error := (DeviceVariateur.Error OR DeviceEncoderM1.Error OR DeviceEncoderM2.Error);

ErrorId := 16#0000;
IF DeviceVariateur.Error THEN
    ErrorId := ErrorId OR 16#00F0;
END_IF;
IF DeviceEncoderM1.Error THEN
    ErrorId := ErrorId OR 16#0F00;
END_IF;
IF DeviceEncoderM2.Error THEN
    ErrorId := ErrorId OR 16#F000;
END_IF;

IF Error THEN
    State := E_Diag_State.ERROR;
ELSIF NOT (VariateurOnlineEff AND EncoderM1OnlineEff AND EncoderM2OnlineEff) THEN
    State := E_Diag_State.INIT;
ELSIF (VariateurBypass OR EncoderM1Bypass OR EncoderM2Bypass)
      AND NOT (VariateurOnlineReal AND EncoderM1OnlineReal AND EncoderM2OnlineReal) THEN
    State := E_Diag_State.SIMULATED;
ELSE
    State := E_Diag_State.READY;
END_IF;

DeviceEthercatMaster.Online := VariateurOnlineEff AND EncoderM1OnlineEff AND EncoderM2OnlineEff;
DeviceEthercatMaster.Operational := DeviceEthercatMaster.Online;

DeviceVariateurStateRawOut := DeviceVariateurStateRaw;
DeviceEncoderM1StateRawOut := DeviceEncoderM1StateRaw;
DeviceEncoderM2StateRawOut := DeviceEncoderM2StateRaw;

Busy := FALSE;
Done := FALSE;

{endregion}

(* ═══════════════════════════════════════════════════════════════
   🎮 ST_DredgingAssistCmd — Sélections IHM assistance prélèvement
   ═══════════════════════════════════════════════════════════════ *)
TYPE ST_DredgingAssistCmd :
STRUCT
    TglEnableDiveSearch         : BOOL := FALSE; (* Assistance plongée active *)
    TglEnableExtractionSequence : BOOL := FALSE; (* Assistance extraction active *)
    TglBucketAtBottomConfirmed  : BOOL := FALSE; (* Attestation manuelle temporaire du fond *)
    // Bypass simplifié de la séquence FB_DiveSearch complète (préconditions
    // strictes -- benne ouverte, DiveStartMin_M, fenêtre immersion). Si TRUE, un front MONTANT
    // Kobold pendant une descente confirme directement le fond, sans passer par l'état-machine
    // FB_DiveSearch (qui continue de tourner en parallèle, inchangée -- utile pour
    // KoboldMeasureEnable). Défaut FALSE : comportement identique à avant (séquence complète
    // seule source de confirmation).
    TglBypassDiveSearchSequence : BOOL := FALSE;
    TglEnableDumpAtTremie       : BOOL := FALSE; (* : mode vidage à la trémie —
                                                     verrouille descente treuils (P1/Maintenance
                                                     uniquement) + translation M3 (proche du haut
                                                     uniquement) ; TRUE par défaut —
                                                     ⚠️ contrairement aux deux autres, ce mode
                                                     RESTREINT des mouvements existants dès le boot *)
END_STRUCT
END_TYPE

(* ═══════════════════════════════════════════════════════════════
   ↔️ FB_Translation_PositionDecoder — Décodage mot capteurs M3 (5 positions)
   ───────────────────────────────────────────────────────────────
    📄 Doc métier : DOC/AF_Partie-02_Architecture_Programme_v3.1.md §3
   🧩 Brique technique (AF_Partie-03 §2) : contrat minimal, pas de
      StartStop/Enable/Reset/Mode — décode 5 capteurs TOR (Trémie|PV|P2|P1|
      Maintenance) en mot de progression, dérive les 2 limites extrêmes,
      détecte toute combinaison incohérente (défense en profondeur M3) et
      les fronts individuels par capteur (arrivée/cible, robuste décalage came).
   🎯 Mot valide : progression monotone de 11111 (extrême Trémie) à 00000
      (extrême Maintenance) : 11111→01111→00111→00011→00001→00000.
      Tout autre mot = incohérence câblage/mécanique (capteur collé/HS).
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Translation_PositionDecoder
VAR_INPUT
    SensorTremie      : BOOL;   // Capteur extrême gauche (Trémie)
    SensorPV          : BOOL;   // Capteur pré-ralentissement avant Trémie (Point de Vitesse)
    SensorP2          : BOOL;   // Capteur zone de travail P2
    SensorP1          : BOOL;   // Capteur zone de travail P1
    SensorMaintenance : BOOL;   // Capteur extrême droite (Maintenance, accès MAINT_N2 uniquement)
END_VAR
VAR_OUTPUT
    LimitSwitchFwd    : BOOL;   // Extrême Trémie confirmé (mot = 11111)
    LimitSwitchRev    : BOOL;   // Extrême Maintenance confirmé (mot = 00000)
    Incoherent        : BOOL;   // Mot hors des 6 combinaisons valides -> défaut sécurité (SafeStop+PowerCutOff, voir FB_Safety_Translation)
    SensorsWord       : BYTE;   // Diagnostic (bit4=Trémie, bit3=PV, bit2=P2, bit1=P1, bit0=Maintenance)

    // 🆕 Exposition des positions individuelles pour consommation par les programmes aval (migration PRG_00_Inputs)
    // ⚠️ CUMULATIF ("au-dessus de ce seuil") — pour le ralentissement d'approche (zone large,
    // doit tenir toute la durée de l'approche, pas juste un instant). Ne PAS utiliser pour
    // détecter une arrivée/cible (voir TranslationAtXxx ci-dessous, mot exact, avec front).
    TranslationPosTremie      : BOOL;   // TRUE = capteur Trémie actif
    TranslationPosPV          : BOOL;   // TRUE = capteur PV actif
    TranslationPosP2          : BOOL;   // TRUE = capteur P2 actif
    TranslationPosP1          : BOOL;   // TRUE = capteur P1 actif
    TranslationPosMaintenance : BOOL;   // TRUE = capteur Maintenance actif

    // 🆕 2026-08-06 (REX terrain, confirmé sur machine réelle) : mot EXACT (5 bits combinés)
    // ABANDONNÉ pour la détection d'arrivée/cible — fragile au décalage came. Détection par FRONT
    // DU CAPTEUR PROPRE à chaque position (montant OU descendant) : le franchissement d'un point Xi
    // est marqué par SON PROPRE capteur qui bascule (front descendant en venant de Trémie = on
    // vient de dépasser Xi ; front montant en venant de Maintenance = on vient d'atteindre Xi) —
    // PAS par le capteur voisin (une tentative précédente basée sur le mot thermomètre utilisait le
    // capteur PRÉCÉDENT et armait le point ~un cran trop tôt, dès l'entrée de la zone d'approche au
    // lieu du franchissement réel du point — confirmé en direct sur machine : arrêt bloqué à P2 au
    // lieu de P1). Trémie et Maintenance (bouts de chaîne) n'ont qu'un seul sens d'arrivée valide
    // chacun (pas de zone au-delà). ⚠️ Signal TRANSITOIRE (1 cycle) — distingue "être ENTRE 2
    // capteurs" (zone, niveau, TranslationPosXxx cumulatif ci-dessus, pilote le ralentissement
    // d'approche) de "être À la position d'UN capteur" (point, front, ci-dessous, pilote l'arrêt).
    // L'appelant (PRG_05_Translation §0quater) le mémorise en verrou bistable (doctrine
    // M3_LimitSwitchFwd/RevStable §0ter) pour tenir le niveau nécessaire au débounce/verrou
    // anti-rebond de FB_Translation.
    TranslationAtTremie      : BOOL;   // TRUE 1 cycle : front montant SensorTremie (arrivée venant de Maintenance uniquement)
    TranslationAtPV          : BOOL;   // TRUE 1 cycle : front (montant ou descendant) SensorPV
    TranslationAtP2          : BOOL;   // TRUE 1 cycle : front (montant ou descendant) SensorP2
    TranslationAtP1          : BOOL;   // TRUE 1 cycle : front (montant ou descendant) SensorP1
    TranslationAtMaintenance : BOOL;   // TRUE 1 cycle : front descendant SensorMaintenance (arrivée venant de Trémie uniquement)
END_VAR

VAR
    EdgeUpTremie      : R_TRIG;
    EdgeDnTremie      : F_TRIG;
    EdgeUpPV          : R_TRIG;
    EdgeDnPV          : F_TRIG;
    EdgeUpP2          : R_TRIG;
    EdgeDnP2          : F_TRIG;
    EdgeUpP1          : R_TRIG;
    EdgeDnP1          : F_TRIG;
    EdgeUpMaintenance : R_TRIG;
    EdgeDnMaintenance : F_TRIG;
END_VAR

// === IMPLEMENTATION ===

// 🧾 Assemblage du mot (bit4=Trémie ... bit0=Maintenance, ordre doc AF_Partie-02 §3bis)
SensorsWord := 0;
IF SensorTremie      THEN SensorsWord := SensorsWord OR 16#10; END_IF;
IF SensorPV          THEN SensorsWord := SensorsWord OR 16#08; END_IF;
IF SensorP2          THEN SensorsWord := SensorsWord OR 16#04; END_IF;
IF SensorP1          THEN SensorsWord := SensorsWord OR 16#02; END_IF;
IF SensorMaintenance THEN SensorsWord := SensorsWord OR 16#01; END_IF;

// 🎯 Les 6 combinaisons valides (progression monotone décroissante Trémie→Maintenance)
CASE SensorsWord OF
    2#11111, 2#01111, 2#00111, 2#00011, 2#00001, 2#00000:
        Incoherent := FALSE;
    ELSE
        Incoherent := TRUE;
END_CASE;

// 🚧 Limites extrêmes — uniquement sur mot valide (évite un Fdc fantôme déclenché par une incohérence)
LimitSwitchFwd := (NOT Incoherent) AND (SensorsWord = 2#11111);
LimitSwitchRev := (NOT Incoherent) AND (SensorsWord = 2#00000);

// 🆕 Reprise des capteurs de position pour les consommateurs legacy (passthrough, identique à l'entrée filtrée)
// ⚠️ CUMULATIF — voir avertissement en déclaration, réservé au ralentissement d'approche.
TranslationPosTremie      := SensorTremie;
TranslationPosPV          := SensorPV;
TranslationPosP2          := SensorP2;
TranslationPosP1          := SensorP1;
TranslationPosMaintenance := SensorMaintenance;

// 🆕 2026-08-06 (REX décalage came) : front individuel par capteur — voir avertissement en
// déclaration. Transitoire (1 cycle), mémorisé par l'appelant.
EdgeUpTremie(CLK := SensorTremie);           EdgeDnTremie(CLK := SensorTremie);
EdgeUpPV(CLK := SensorPV);                   EdgeDnPV(CLK := SensorPV);
EdgeUpP2(CLK := SensorP2);                   EdgeDnP2(CLK := SensorP2);
EdgeUpP1(CLK := SensorP1);                   EdgeDnP1(CLK := SensorP1);
EdgeUpMaintenance(CLK := SensorMaintenance); EdgeDnMaintenance(CLK := SensorMaintenance);

// 🆕 Front du capteur PROPRE à chaque position — voir modèle en déclaration (confirmé terrain).
// Extrémités : un seul sens valide chacune. Points intermédiaires : les deux fronts de LEUR PROPRE
// capteur (montant = atteint en venant de Maintenance, descendant = dépassé en venant de Trémie).
TranslationAtTremie      := EdgeUpTremie.Q;
TranslationAtPV          := EdgeUpPV.Q OR EdgeDnPV.Q;
TranslationAtP2          := EdgeUpP2.Q OR EdgeDnP2.Q;
TranslationAtP1          := EdgeUpP1.Q OR EdgeDnP1.Q;
TranslationAtMaintenance := EdgeDnMaintenance.Q;

(* =======================================================================
   💾 FB_CfgPersistBridge_CommunCfg — Pont persistance pour ST_CommunCfg
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Restauration et synchronisation bidirectionnelle IHM / Persist
   💾 Persistance : Transfert GVL_PERSISTENT <-> GVL_IHM sur Initialized
   📄 Doc métier : DOC/AF/AF_Partie-03_Contrats_Composants_v2.1.md §3
   ======================================================================= *)
FUNCTION_BLOCK FB_CfgPersistBridge_CommunCfg
VAR_OUTPUT
    // === ETATS RESTAURATION ===
    JustRestored            : BOOL;               // <-- [STAT] Vrai sur le cycle de restauration initiale
END_VAR
VAR_IN_OUT
    // === BUS CONFIGURATION ET PERSISTANCE ===
    Hmi                     : ST_CommunCfg;       // <-> [BUS] Structure de configuration IHM
    Persist                 : ST_CommunCfg;       // <-> [BUS] Structure de configuration persistante
END_VAR

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   🧪 PRG_AU_TestBench — Programme principal de test chaîne AU
   ───────────────────────────────────────────────────────────────
   📄 Ordonnance les étages Acquisition → Outputs dans l'ordre
      correct (même flux que MainTask réelle).
   🎮 Pilotage via Watch CODESYS :
      GVL_IHM_AU.Cmd.BtnEmergencyArming  = TRUE  → lance réarmement
      GVL_IHM_AU.Cmd.BtnFaultReset       = TRUE  → acquitte défauts
      GVL_IHM_AU.Cmd.BtnEmergencyCutOff  = TRUE  → coupure IHM
      GVL_Simulation_AU.SimContactorEngaged = TRUE → simule retour contacteur
      GVL_Simulation_AU.SimPowerCutOffReq   = TRUE → simule coupure métier
   👁️ Observation :
      PRG_AU_Outputs_LD.ArmingSeqStep    → étape séquence (0..6)
      PRG_AU_Outputs_LD.PowerKeepAlive_A_RQ → état maintien A
      PRG_AU_Outputs_LD.EmergencyArming_RQ  → pulse réarmement
      PRG_AU_Outputs_LD.ErrorId          → erreurs/locks
   ═══════════════════════════════════════════════════════════════
    📄 Docs : DOC/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md
              DOC/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md
*)

PROGRAM PRG_AU_TestBench
VAR_OUTPUT
    // 🩺 Synthèse lisible pour Watch
    StepLabel           : STRING;
    MaintainA           : BOOL;
    MaintainB           : BOOL;
    ArmPulse            : BOOL;
    Step                : INT;
    ErrorId             : WORD;
    RedundancyFailed    : BOOL;
    ArmFailed           : BOOL;
    Lockout             : BOOL;
    ChainOk             : BOOL;
    ContactorOk         : BOOL;
    Armable             : BOOL;
END_VAR

// === IMPLEMENTATION ===

// 🔄 1. Acquisition des entrées (simulées)
PRG_AU_Acquisition();

// 📤 2. Traitement et sorties (composite + Q)
PRG_AU_Outputs_LD();

// 🩺 Synthèse Watch — lecture des sorties scalaires (pattern PRG_10_Outputs_LD)
MaintainA        := PRG_AU_Outputs_LD.PowerKeepAlive_A_RQ;
MaintainB        := PRG_AU_Outputs_LD.PowerKeepAlive_B_RQ;
ArmPulse         := PRG_AU_Outputs_LD.EmergencyArming_RQ;
Step             := PRG_AU_Outputs_LD.ArmingSeqStep;
ErrorId          := PRG_AU_Outputs_LD.ErrorId;
RedundancyFailed := PRG_AU_Outputs_LD.RedundancyTestFailed;
ArmFailed        := PRG_AU_Outputs_LD.EmergencyArmingFailed;
Lockout          := PRG_AU_Outputs_LD.EmergencyArmingLockoutActive;
ChainOk          := PRG_AU_Outputs_LD.ChainOk;
ContactorOk      := PRG_AU_Outputs_LD.ContactorOk;
Armable          := PRG_AU_Outputs_LD.Armable;

// 📤 Publication IHM — l'opérateur voit ces retours sur son écran
// [IHM] Publication dans la structure d'etat IHM (lue par la visu operateur)
GVL_IHM_AU.State.ChainOk              := ChainOk;
GVL_IHM_AU.State.ContactorOk          := ContactorOk;
GVL_IHM_AU.State.Armable              := Armable;
GVL_IHM_AU.State.ArmingBusy           := PRG_AU_Outputs_LD.ArmingBusy;
GVL_IHM_AU.State.RedundancyTestFailed := RedundancyFailed;
GVL_IHM_AU.State.ArmingFailed         := ArmFailed;
GVL_IHM_AU.State.LockoutActive        := Lockout;
GVL_IHM_AU.State.Step                 := Step;
GVL_IHM_AU.State.Error                := PRG_AU_Outputs_LD.Error;
GVL_IHM_AU.State.ErrorId              := ErrorId;
GVL_IHM_AU.State.PowerCutOffActive    := GVL_Simulation_AU.SimPowerCutOffReq;

CASE Step OF
    0: StepLabel := 'IDLE (attente armement)';
    1: StepLabel := 'TestA (coupe A)';
    2: StepLabel := 'RestoreA (rétablit A)';
    3: StepLabel := 'TestB (coupe B)';
    4: StepLabel := 'RestoreB (rétablit B)';
    5: StepLabel := 'Pulse (armement 1s)';
    6: StepLabel := 'Confirm (attente contacteur)';
ELSE
    StepLabel := 'ERREUR';
END_CASE;

(* =======================================================================
   💾 FB_CfgPersistBridge_CycleCfg — Pont persistance pour ST_CycleCfg
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Restauration et synchronisation bidirectionnelle IHM / Persist
   💾 Persistance : Transfert GVL_PERSISTENT <-> GVL_IHM sur Initialized
   📄 Doc métier : DOC/AF/AF_Partie-03_Contrats_Composants_v2.1.md §3
   ======================================================================= *)
FUNCTION_BLOCK FB_CfgPersistBridge_CycleCfg
VAR_OUTPUT
    // === ETATS RESTAURATION ===
    JustRestored            : BOOL;               // <-- [STAT] Vrai sur le cycle de restauration initiale
END_VAR
VAR_IN_OUT
    // === BUS CONFIGURATION ET PERSISTANCE ===
    Hmi                     : ST_CycleCfg;        // <-> [BUS] Structure de configuration IHM
    Persist                 : ST_CycleCfg;        // <-> [BUS] Structure de configuration persistante
END_VAR

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

(* =======================================================================
   💾 FB_CfgPersistBridge_SyncCfg — Pont persistance pour ST_SyncCfg
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Restauration et synchronisation bidirectionnelle IHM / Persist
   💾 Persistance : Transfert GVL_PERSISTENT <-> GVL_IHM sur Initialized
   📄 Doc métier : DOC/AF/AF_Partie-03_Contrats_Composants_v2.1.md §3
   ======================================================================= *)
FUNCTION_BLOCK FB_CfgPersistBridge_SyncCfg
VAR_OUTPUT
    // === ETATS RESTAURATION ===
    JustRestored            : BOOL;               // <-- [STAT] Vrai sur le cycle de restauration initiale
END_VAR
VAR_IN_OUT
    // === BUS CONFIGURATION ET PERSISTANCE ===
    Hmi                     : ST_SyncCfg;         // <-> [BUS] Structure de configuration IHM
    Persist                 : ST_SyncCfg;         // <-> [BUS] Structure de configuration persistante
END_VAR

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

