(* ═══════════════════════════════════════════════════════════════
   📡 FB_Diag_Ethercat — Diagnostic bus EtherCAT (3 esclaves)
   ───────────────────────────────────────────────────────────────
   📄 Docs : DOC/AF_Partie-02_Architecture_Programme_v3.1.md
              DOC/AF_Partie-06_Acquisition_Qualification_IO_v2.1.md §3
   🎯 Rôle : Décide Online/Operational pour variateur M3 + codeurs M1/M2.
      Publie ST_Diag_Device par device + state global.
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK PUBLIC FB_Diag_Ethercat
VAR_INPUT
    Enable              : BOOL;        (* Active la surveillance EtherCAT *)
    Reset               : BOOL;        (* Front d'acquittement des défauts *)

    (* Variateur M3 (AC600_ECAT_Drive) *)
    DeviceVariateurStateRaw     : DEVICE_STATE; (* Valeur brute AC600_ECAT_Drive.GetDeviceState() *)
    DeviceVariateurSimBypass    : BOOL;         (* TRUE = simulation active *)

    (* Encodeur M1 (COD1_CODEUR) *)
    DeviceEncoderM1StateRaw     : DEVICE_STATE; (* Valeur brute COD1_CODEUR.GetDeviceState() *)
    DeviceEncoderM1SimBypass    : BOOL;         (* TRUE = simulation active *)

    (* Encodeur M2 (COD2_CODEUR) *)
    DeviceEncoderM2StateRaw     : DEVICE_STATE; (* Valeur brute COD2_CODEUR.GetDeviceState() *)
    DeviceEncoderM2SimBypass    : BOOL;         (* TRUE = simulation active *)

    NetworkBypassActive         : BOOL;         (* TRUE = bypass réseau global IHM *)
END_VAR
VAR_OUTPUT
    Ready               : BOOL;        (* Logique de surveillance active *)
    Busy                : BOOL;        (* Non utilisé (conformité) *)
    Done                : BOOL;        (* Non utilisé *)
    Error               : BOOL;        (* Résumé anomalie de communication bus *)
    ErrorId             : WORD;        (* Code défaut global résumé *)
    State               : E_Diag_State; (* Phase courante du diagnostic global — voir en-tête *)
    StateAtError        : E_Diag_State; (* Phase figée à l'apparition de l'erreur *)
    DeviceEthercatMaster : ST_Diag_Device; (* Diagnostics bus EtherCAT *)
    DeviceVariateur     : ST_Diag_Device;  (* Diagnostics esclave AC600 *)
    DeviceEncoderM1     : ST_Diag_Device;  (* Diagnostics esclave COD1 *)
    DeviceEncoderM2     : ST_Diag_Device;  (* Diagnostics esclave COD2 *)
    (* Miroirs bruts lisibles directement sur l'instance *)
    DeviceVariateurStateRawOut : DEVICE_STATE;
    DeviceEncoderM1StateRawOut : DEVICE_STATE;
    DeviceEncoderM2StateRawOut : DEVICE_STATE;
END_VAR
VAR
    ResetEdge           : R_TRIG;      (* Détecteur front de reset *)
    VariateurOnlineReal  : BOOL; (* GetDeviceState() = RUNNING, hors tout bypass *)
    EncoderM1OnlineReal  : BOOL;
    EncoderM2OnlineReal  : BOOL;
    VariateurBypass      : BOOL; (* Simulation OU bypass réseau IHM, pour ce device *)
    EncoderM1Bypass      : BOOL;
    EncoderM2Bypass      : BOOL;
    VariateurOnlineEff   : BOOL; (* Online effectif (réel OU bypass) *)
    EncoderM1OnlineEff   : BOOL;
    EncoderM2OnlineEff   : BOOL;
END_VAR

// 🛑 1. GATE : Désactivation si Enable = FALSE
IF NOT Enable THEN
    Ready := FALSE;
    State := E_Diag_State.DISABLED;
    DeviceVariateur.State := E_Diag_State.DISABLED;
    DeviceEncoderM1.State := E_Diag_State.DISABLED;
    DeviceEncoderM2.State := E_Diag_State.DISABLED;
    DeviceVariateur.Online := FALSE;
    DeviceEncoderM1.Online := FALSE;
    DeviceEncoderM2.Online := FALSE;
    DeviceVariateur.Operational := FALSE;
    DeviceEncoderM1.Operational := FALSE;
    DeviceEncoderM2.Operational := FALSE;
    DeviceVariateur.Error := FALSE;
    DeviceEncoderM1.Error := FALSE;
    DeviceEncoderM2.Error := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    DeviceEthercatMaster.State := E_Diag_State.DISABLED;
    DeviceEthercatMaster.Online := FALSE;
    DeviceEthercatMaster.Operational := FALSE;
    DeviceVariateurStateRawOut := DeviceVariateurStateRaw;
    DeviceEncoderM1StateRawOut := DeviceEncoderM1StateRaw;
    DeviceEncoderM2StateRawOut := DeviceEncoderM2StateRaw;
    RETURN;
END_IF;

Ready := TRUE;

// 🧮 2. INTERPRÉTATION DES VALEURS BRUTES
VariateurOnlineReal := (DeviceVariateurStateRaw = DEVICE_STATE.RUNNING);
EncoderM1OnlineReal := (DeviceEncoderM1StateRaw = DEVICE_STATE.RUNNING);
EncoderM2OnlineReal := (DeviceEncoderM2StateRaw = DEVICE_STATE.RUNNING);

VariateurBypass := DeviceVariateurSimBypass OR NetworkBypassActive;
EncoderM1Bypass := DeviceEncoderM1SimBypass OR NetworkBypassActive;
EncoderM2Bypass := DeviceEncoderM2SimBypass OR NetworkBypassActive;

VariateurOnlineEff := VariateurOnlineReal OR VariateurBypass;
EncoderM1OnlineEff := EncoderM1OnlineReal OR EncoderM1Bypass;
EncoderM2OnlineEff := EncoderM2OnlineReal OR EncoderM2Bypass;

// 🔑 3. RESET FRONT
ResetEdge(CLK := Reset);

// 🔍 4. DIAGNOSTIC VARIATEUR (AC600_ECAT_Drive / Translation M3)
DeviceVariateur.Online := VariateurOnlineEff;
DeviceVariateur.Operational := VariateurOnlineEff;

IF NOT DeviceVariateur.Online THEN
    DeviceVariateur.ErrorId := DeviceVariateur.ErrorId OR 16#0010;  (* Perte liaison physique variateur *)
ELSE
    DeviceVariateur.ErrorId := DeviceVariateur.ErrorId AND 16#FFEF; (* Effacement auto dès que RUNNING *)
END_IF;

// 🔍 5. DIAGNOSTIC ENCODEUR M1 (COD1_CODEUR / WinchM1)
DeviceEncoderM1.Online := EncoderM1OnlineEff;
DeviceEncoderM1.Operational := EncoderM1OnlineEff;

IF NOT DeviceEncoderM1.Online THEN
    DeviceEncoderM1.ErrorId := DeviceEncoderM1.ErrorId OR 16#0020;  (* Perte liaison encodeur M1 *)
ELSE
    DeviceEncoderM1.ErrorId := DeviceEncoderM1.ErrorId AND 16#FFDF; (* Effacement auto dès que RUNNING *)
END_IF;

// 🔍 6. DIAGNOSTIC ENCODEUR M2 (COD2_CODEUR / WinchM2)
DeviceEncoderM2.Online := EncoderM2OnlineEff;
DeviceEncoderM2.Operational := EncoderM2OnlineEff;

IF NOT DeviceEncoderM2.Online THEN
    DeviceEncoderM2.ErrorId := DeviceEncoderM2.ErrorId OR 16#0030;  (* Perte liaison encodeur M2 *)
ELSE
    DeviceEncoderM2.ErrorId := DeviceEncoderM2.ErrorId AND 16#FFCF; (* Effacement auto dès que RUNNING *)
END_IF;

// 🚦 7. STATE MACHINES DE CHAQUE APPAREIL
IF DeviceVariateur.ErrorId <> 0 THEN
    DeviceVariateur.State := E_Diag_State.ERROR;
ELSIF NOT VariateurOnlineEff THEN
    DeviceVariateur.State := E_Diag_State.INIT;
ELSIF VariateurBypass AND NOT VariateurOnlineReal THEN
    DeviceVariateur.State := E_Diag_State.SIMULATED;
ELSE
    DeviceVariateur.State := E_Diag_State.READY;
END_IF;

IF DeviceEncoderM1.ErrorId <> 0 THEN
    DeviceEncoderM1.State := E_Diag_State.ERROR;
ELSIF NOT EncoderM1OnlineEff THEN
    DeviceEncoderM1.State := E_Diag_State.INIT;
ELSIF EncoderM1Bypass AND NOT EncoderM1OnlineReal THEN
    DeviceEncoderM1.State := E_Diag_State.SIMULATED;
ELSE
    DeviceEncoderM1.State := E_Diag_State.READY;
END_IF;

IF DeviceEncoderM2.ErrorId <> 0 THEN
    DeviceEncoderM2.State := E_Diag_State.ERROR;
ELSIF NOT EncoderM2OnlineEff THEN
    DeviceEncoderM2.State := E_Diag_State.INIT;
ELSIF EncoderM2Bypass AND NOT EncoderM2OnlineReal THEN
    DeviceEncoderM2.State := E_Diag_State.SIMULATED;
ELSE
    DeviceEncoderM2.State := E_Diag_State.READY;
END_IF;

// Fige la phase du diagnostic global sur le premier défaut
IF (DeviceVariateur.ErrorId <> 0 OR DeviceEncoderM1.ErrorId <> 0 OR DeviceEncoderM2.ErrorId <> 0) THEN
    IF StateAtError = E_Diag_State.DISABLED THEN
        StateAtError := State;
    END_IF;
END_IF;

// 📤 8. RÉSUMÉ ET DÉFAUTS
DeviceVariateur.Error := (DeviceVariateur.ErrorId <> 0);
DeviceEncoderM1.Error := (DeviceEncoderM1.ErrorId <> 0);
DeviceEncoderM2.Error := (DeviceEncoderM2.ErrorId <> 0);

Error := (DeviceVariateur.Error OR DeviceEncoderM1.Error OR DeviceEncoderM2.Error);

ErrorId := 16#0000;
IF DeviceVariateur.Error THEN
    ErrorId := ErrorId OR 16#00F0;
END_IF;
IF DeviceEncoderM1.Error THEN
    ErrorId := ErrorId OR 16#0F00;
END_IF;
IF DeviceEncoderM2.Error THEN
    ErrorId := ErrorId OR 16#F000;
END_IF;

IF Error THEN
    State := E_Diag_State.ERROR;
ELSIF NOT (VariateurOnlineEff AND EncoderM1OnlineEff AND EncoderM2OnlineEff) THEN
    State := E_Diag_State.INIT;
ELSIF (VariateurBypass OR EncoderM1Bypass OR EncoderM2Bypass)
      AND NOT (VariateurOnlineReal AND EncoderM1OnlineReal AND EncoderM2OnlineReal) THEN
    State := E_Diag_State.SIMULATED;
ELSE
    State := E_Diag_State.READY;
END_IF;

DeviceEthercatMaster.Online := VariateurOnlineEff AND EncoderM1OnlineEff AND EncoderM2OnlineEff;
DeviceEthercatMaster.Operational := DeviceEthercatMaster.Online;

DeviceVariateurStateRawOut := DeviceVariateurStateRaw;
DeviceEncoderM1StateRawOut := DeviceEncoderM1StateRaw;
DeviceEncoderM2StateRawOut := DeviceEncoderM2StateRaw;

Busy := FALSE;
Done := FALSE;

(* ═══════════════════════════════════════════════════════════════
   🎯 FB_Encoder_Homing — Référencement codeur nominal ou unitaire MAINT_N2
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-09_Fonction_Encoder_v2.1.md §1/§5/§7bis
                   DOC/AF_Partie-03_Contrats_Composants_v2.1.md
   🎯 Rôle : Gestion du flux de homing nominal (capteur haut + cible paramétrable)
      ou unitaire (MAINT_N2, treuil sélectionné).
   🧮 Calcul du point de calage :
      - PresetValue = centre de la plage multi-tour (marge anti-débordement)
      - HomingRefRaw = PresetValue - round(CfgTopSensorPosM × PointsPerRev / CableM_PerRev)
   🧊 Expose ST_Encoder_Calib en VAR_IN_OUT (RETAIN).
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Encoder_Homing) ===

FUNCTION_BLOCK PUBLIC FB_Encoder_Homing
VAR_INPUT
    Enable               : BOOL;        // Standard
    Reset                : BOOL;        // Acquittement défaut (front) — bits 0/2/3/4/5 (voir §ErrorId)
    PowerContactorEngaged      : BOOL;        // Standard
    Mode                 : E_Mode;      // MAINT_N1 requis pour le flux nominal
    Home                 : BOOL;        // Demande de référencement (front, bouton IHM UNIQUE)
    UnitaryMode          : BOOL;        // TRUE = flux unitaire à cible libre (MAINT_N2 uniquement)
    WinchSelected        : BOOL;        // TRUE = cette instance est le treuil sélectionné
    CfgHomingTargetM        : REAL;        // Cible libre unitaire, limitée à [-99.0 ; +99.0] m
    // 🆕 2026-08-07 (19) — retour terrain, demande client : BtnConfirmOpenPos/ClosePos (benne)
    // doivent aussi référencer le codeur M2 (comme BtnHome), pas seulement mémoriser un état
    // logique -- cible DYNAMIQUE (position réelle de M1, calculée côté appelant), pas une valeur
    // de config fixe comme CfgHomingTargetM. Si TRUE au front Home, DynamicHomingTargetM prime
    // sur UnitaryMode/CfgTopSensorPosM.
    UseDynamicTarget        : BOOL := FALSE;
    DynamicHomingTargetM    : REAL := 0.0;
    BtnConfirmCoherence     : BOOL;        // Front — lève le doute §3.7 (bit9), sans réhoming complet
    TopPositionSensor    : BOOL;        // 🔧 2026-07-02 : capteur position haute UNIQUE, COMMUN aux 2 treuils
                                         // (les 2 câbles hissent ensemble le même ensemble mécanique) — câblé
                                         // IDENTIQUEMENT sur les instances M1 ET M2 (PAS un capteur par treuil),
                                         // voir PRG_MAIN.st
    CfgTopSensorPosM   : REAL := 8.5;   // Cible homing nominal (RETAIN site, voir Partie10 §7bis)
    FwdRevSpeedFeedbackOff : BOOL;      // Retour unique "tous contacteurs sens+vitesse retombés" CE TREUIL — arrêt confirmé
    BrakeFeedback        : BOOL;        // Retour contacteur frein CE TREUIL (TRUE = ouvert/desserré — révocation 2026-08-03)
    RawPos               : UDINT;       // Sortie FB_Encoder_Abs (déjà gelée sur doute)
    EncoderAvailable     : BOOL;        // Sortie FB_Encoder_Abs
    PresetAck            : BOOL;        // Pulse — sortie FB_Encoder_Abs (écriture confirmée)
    PresetNak            : BOOL;        // Pulse — sortie FB_Encoder_Abs (écriture refusée/timeout)
    PointsPerRev         : UDINT := 8192;   // Confirmé fiche technique (Partie10 §3.3)
    MultiTurnRevsMax     : UDINT := 4096;   // Confirmé fiche technique (Partie10 §3.3)
    CableM_PerRev        : REAL := 2.0;     // Confirmé terrain 2026-07-02 (Partie10 §2)
    BypassGlobal         : BOOL := FALSE;   // 🌐 Ignore arrêt confirmé et capteur haut (mise en service)
END_VAR
VAR_OUTPUT
    Ready                : BOOL;
    Busy                 : BOOL;
    Done                 : BOOL;        // Pulse 1 cycle — référencement réussi (miroir PresetAck)
    Error                : BOOL;
    ErrorId              : WORD;        // Voir table de bits en en-tête de fichier / doc §5
    State                : E_State;
    StateAtError         : E_State;
    PresetRequest        : BOOL;        // Pulse → FB_Encoder_Abs.PresetRequest
    PresetValue          : UDINT;       // → FB_Encoder_Abs.PresetValue (= HomingRefTargetNominal)
    Homed                : BOOL;        // RETAIN interne, miroir Calib.Homed
    HomingSuspect        : BOOL;        // RETAIN interne, miroir Calib.HomingSuspect
    HomingRefRaw         : UDINT;       // RETAIN interne, miroir Calib.HomingRefRaw → FB_Encoder_Scale
END_VAR
VAR_IN_OUT
    Calib                : ST_Encoder_Calib;   // Référence vers l'état persistant global (survit aux téléchargements)
END_VAR
VAR
    ResetEdge            : R_TRIG;
    ErrorEdge            : R_TRIG;
    HomeEdge             : R_TRIG;
    ConfirmCoherenceEdge : R_TRIG;
    InitDone             : BOOL;        // Contrôle cohérence §3.7 fait une fois par session Enable
    ArretConfirme        : BOOL;
    PresetValueCalc      : UDINT;       // = HomingRefTargetNominal (constant tant que PointsPerRev/MultiTurnRevsMax fixes)
    TargetPoints         : DINT;        // Écart signé CfgTopSensorPosM → points, figé pendant la séquence
    TargetPositionM      : REAL;        // Cible retenue : nominale ou unitaire
    RawDiffRestart       : DINT;        // Écart |RawPos - LastKnownRawPos| au redémarrage (§3.7)
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Homing) ===

// 🛑 1. GATE — neutralisation ; on continue toutefois d'exposer le dernier état RETAIN connu
// (FB_Encoder_Scale a besoin de HomingRefRaw même si ce FB est désactivé)
// 🆕 2026-08-06 : PowerContactorEngaged retiré du GATE (le codeur 24V / EtherCAT peut être homé disjoncteurs coupés)
IF NOT Enable THEN
    PresetRequest := FALSE;
    PresetValue := 0;
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    InitDone := FALSE;   // Force un nouveau contrôle §3.7 à la prochaine activation
    Homed := Calib.Homed;
    HomingSuspect := Calib.HomingSuspect;
    HomingRefRaw := Calib.HomingRefRaw;
    RETURN;
END_IF;

Ready := TRUE;

// 🔑 2. FRONTS
ResetEdge(CLK := Reset);
HomeEdge(CLK := Home);
ConfirmCoherenceEdge(CLK := BtnConfirmCoherence);

// 🔍 3. COHÉRENCE AU REDÉMARRAGE (§3.7) — une fois par session Enable, dès que le codeur répond
IF NOT InitDone THEN
    State := E_State.INIT;
    IF EncoderAvailable THEN
        RawDiffRestart := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(Calib.LastKnownRawPos);
        IF Calib.Homed AND (ABS(RawDiffRestart) > UDINT_TO_DINT(Calib.RestartCoherenceTolerancePts)) THEN
            Calib.HomingSuspect := TRUE;
            ErrorId := ErrorId OR 16#0200;   // bit9 : incohérence codeur au redémarrage
        END_IF;
        InitDone := TRUE;
    END_IF;
ELSE
    IF State = E_State.INIT THEN State := E_State.READY; END_IF;
END_IF;

// ✅ 4. LEVÉE DU DOUTE (BtnConfirmCoherence, §3.7) — indépendant du Reset générique
IF ConfirmCoherenceEdge.Q AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2) THEN
    Calib.HomingSuspect := FALSE;
    ErrorId := ErrorId AND 16#FDFF;   // efface bit9
END_IF;

PresetRequest := FALSE;
IF HomeEdge.Q THEN
    IF UseDynamicTarget THEN
        TargetPositionM := DynamicHomingTargetM;
    ELSIF UnitaryMode THEN
        TargetPositionM := CfgHomingTargetM;
    ELSE
        TargetPositionM := CfgTopSensorPosM;
    END_IF;

    // 🎯 Homing logiciel immédiat sans condition : mise à jour instantanée de HomingRefRaw
    // (garantit que CablePosM passe à 0.0m ou TopSensorPosM immédiatement à l'écran IHM)
    TargetPoints := REAL_TO_DINT(TargetPositionM * UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
    Calib.HomingRefRaw := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) - TargetPoints);
    Calib.Homed := TRUE;
    Calib.HomingSuspect := FALSE;
    Calib.LastKnownRawPos := RawPos;
    HomingRefRaw := Calib.HomingRefRaw;
    Homed := TRUE;
    HomingSuspect := FALSE;
    Done := TRUE;
    ErrorId := 16#0000;
    State := E_State.READY;

    // Envoi parallèle de la demande de Preset SDO au matériel s'il est disponible
    PresetValueCalc := (PointsPerRev * MultiTurnRevsMax) / 2;
    PresetValue := PresetValueCalc;
    PresetRequest := TRUE;
END_IF;

// ⏳ 6. SUIVI DE LA SÉQUENCE SDO OPTIONNELLE
IF State = E_State.BUSY THEN
    IF PresetAck THEN
        Done := TRUE;
        State := E_State.READY;
        // Un homing réussi efface l'intégralité de ErrorId
        ErrorId := 16#0000;
    ELSIF PresetNak THEN
        ErrorId := ErrorId OR 16#0020;        // bit5 : preset refusé/timeout (voir FB_Encoder_Abs)
        State := E_State.READY;
    END_IF;
END_IF;

// 🧾 7. RESET (front) — efface les bits « dernière tentative rejetée » (pas de cause persistante
// à revérifier ici : le prochain Home réévalue toutes les conditions de zéro, voir §5)
IF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFC0;   // efface bits 0..5 (garde bit9, levé seulement par BtnConfirmCoherence/Home)
END_IF;

// 📤 8. SORTIES ÉTAT
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// Mise à jour continue du point brut valide connu (hors séquence de homing elle-même)
IF EncoderAvailable AND (State <> E_State.BUSY) THEN
    Calib.LastKnownRawPos := RawPos;
END_IF;

Busy := (State = E_State.BUSY);
Homed := Calib.Homed AND NOT Calib.HomingSuspect; // 🆕 REX 2026-07-08 : Perd l'état homed si suspect (démarrage ou fonctionnement), restauré après BtnConfirmCoherence
HomingSuspect := Calib.HomingSuspect;
HomingRefRaw := Calib.HomingRefRaw;

FUNCTION_BLOCK FB_TestCheck
VAR_INPUT
    Config      : ST_TestCheckConfig;
    Evaluate    : BOOL;
END_VAR
VAR_IN_OUT
    ProbeBool   : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeBool] OF BOOL;
    ProbeDint   : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeDint] OF DINT;
    ProbeReal   : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeReal] OF REAL;
END_VAR
VAR_OUTPUT
    Passed       : BOOL;
    Failed       : BOOL;
    Pending      : BOOL;
    FailReason   : E_TestFailReason;
    ObservedBool : BOOL;
    ObservedDint : DINT;
    ObservedReal : REAL;
END_VAR
VAR
    RisingTrig   : R_TRIG;
    FallingTrig  : F_TRIG;
    StableTimer  : TON;
    EvaluateTrig : R_TRIG;
    Cond         : BOOL;
    ProbeIdxLocal : INT;
END_VAR
// === IMPLEMENTATION ===
// Toujours mettre à jour les triggers, avec borne validée AVANT l'accès.
ProbeIdxLocal := Config.ProbeIdx;
IF ProbeIdxLocal >= 1 THEN
    IF ProbeIdxLocal <= GVL_PLC_Tests_Const.MaxProbeBool THEN
        RisingTrig(CLK := ProbeBool[ProbeIdxLocal]);
        FallingTrig(CLK := ProbeBool[ProbeIdxLocal]);
    ELSE
        RisingTrig(CLK := FALSE);
        FallingTrig(CLK := FALSE);
    END_IF;
ELSE
    RisingTrig(CLK := FALSE);
    FallingTrig(CLK := FALSE);
END_IF;

EvaluateTrig(CLK := Evaluate);

IF EvaluateTrig.Q THEN
    Passed := FALSE;
    Failed := FALSE;
    Pending := FALSE;
    FailReason := E_TestFailReason.FAIL_NONE;
    StableTimer(IN := FALSE);
END_IF;

// Mise à jour des valeurs observées
IF Config.ProbeIdx >= 1 THEN
    CASE Config.Kind OF
        E_TestCheckKind.BOOL_EQUAL, E_TestCheckKind.BOOL_RISING, E_TestCheckKind.BOOL_FALLING:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeBool THEN
                ObservedBool := ProbeBool[ProbeIdxLocal];
            END_IF;
        E_TestCheckKind.DINT_EQUAL, E_TestCheckKind.DINT_NOT_EQUAL, E_TestCheckKind.DINT_IN_RANGE,
        E_TestCheckKind.WORD_MASK_ALL, E_TestCheckKind.WORD_MASK_ANY, E_TestCheckKind.WORD_MASK_NONE:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeDint THEN
                ObservedDint := ProbeDint[ProbeIdxLocal];
            END_IF;
        E_TestCheckKind.REAL_IN_RANGE:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeReal THEN
                ObservedReal := ProbeReal[ProbeIdxLocal];
            END_IF;
    END_CASE;
END_IF;

// Évaluation de la condition logique (Cond)
Cond := FALSE;
IF Config.ProbeIdx >= 1 THEN
    CASE Config.Kind OF
        E_TestCheckKind.BOOL_EQUAL:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeBool THEN
                Cond := (ObservedBool = Config.ExpectedBool);
            END_IF;
            
        E_TestCheckKind.BOOL_RISING:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeBool THEN
                Cond := RisingTrig.Q;
            END_IF;
            
        E_TestCheckKind.BOOL_FALLING:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeBool THEN
                Cond := FallingTrig.Q;
            END_IF;
            
        E_TestCheckKind.DINT_EQUAL:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeDint THEN
                Cond := (ObservedDint = Config.ExpectedDint);
            END_IF;
            
        E_TestCheckKind.DINT_NOT_EQUAL:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeDint THEN
                Cond := (ObservedDint <> Config.ExpectedDint);
            END_IF;
            
        E_TestCheckKind.DINT_IN_RANGE:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeDint THEN
                Cond := (ObservedDint >= Config.ExpectedMin AND ObservedDint <= Config.ExpectedMax);
            END_IF;
            
        E_TestCheckKind.WORD_MASK_ALL:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeDint THEN
                Cond := ((DINT_TO_WORD(ObservedDint) AND Config.Mask) = Config.Mask);
            END_IF;
            
        E_TestCheckKind.WORD_MASK_ANY:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeDint THEN
                Cond := ((DINT_TO_WORD(ObservedDint) AND Config.Mask) <> 0);
            END_IF;
            
        E_TestCheckKind.WORD_MASK_NONE:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeDint THEN
                Cond := ((DINT_TO_WORD(ObservedDint) AND Config.Mask) = 0);
            END_IF;
            
        E_TestCheckKind.REAL_IN_RANGE:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeReal THEN
                Cond := (ObservedReal >= Config.RealMin AND ObservedReal <= Config.RealMax);
            END_IF;
    END_CASE;
END_IF;

// Application du mode d'évaluation
IF Evaluate THEN
    CASE Config.Mode OF
        E_TestCheckMode.CHECK_INSTANT:
            IF EvaluateTrig.Q THEN
                IF Cond THEN
                    Passed := TRUE;
                    Failed := FALSE;
                    Pending := FALSE;
                ELSE
                    Passed := FALSE;
                    Failed := TRUE;
                    Pending := FALSE;
                    FailReason := E_TestFailReason.FAIL_CHECK;
                END_IF;
            END_IF;

        E_TestCheckMode.CHECK_WAIT_UNTIL:
            IF NOT Passed AND NOT Failed THEN
                StableTimer(IN := Cond, PT := Config.StablePT);
                IF StableTimer.Q THEN
                    Passed := TRUE;
                    Failed := FALSE;
                    Pending := FALSE;
                ELSE
                    Pending := TRUE;
                END_IF;
            END_IF;

        E_TestCheckMode.CHECK_INVARIANT:
            IF NOT Cond THEN
                Passed := FALSE;
                Failed := TRUE;
                Pending := FALSE;
                FailReason := E_TestFailReason.FAIL_INVARIANT;
            ELSE
                Passed := TRUE;
                Failed := FALSE;
                Pending := FALSE;
            END_IF;

        E_TestCheckMode.CHECK_NEVER_DURING:
            IF NOT Failed THEN
                IF Cond THEN
                    Passed := FALSE;
                    Failed := TRUE;
                    Pending := FALSE;
                    FailReason := E_TestFailReason.FAIL_CHECK;
                ELSE
                    Pending := TRUE;
                END_IF;
            END_IF;
    END_CASE;
ELSE
    Passed := FALSE;
    Failed := FALSE;
    Pending := FALSE;
    StableTimer(IN := FALSE);
END_IF;

(* ═══════════════════════════════════════════════════════════════
   🔁 FB_Filter_PT1 — Filtre passe-bas premier ordre (PT1 numérique)
   ───────────────────────────────────────────────────────────────
   📄 Extrait depuis le projet CODESYS (Device.export, JOYSTICK/)
   🎯 Filtre exponentiel discret : y[k] = α·x[k] + (1-α)·y[k-1]
      où α = CycleTimeS / (T + CycleTimeS), T = TimeConst en secondes.
   ⚠️ Si TimeConst = 0 ou CycleTimeS = 0, sortie = entrée (pass-through).
   ═══════════════════════════════════════════════════════════════
   📄 Docs : DOC/AF_Partie-08_Fonction_Joystick_v2.0.md
*)

FUNCTION_BLOCK FB_Filter_PT1
VAR_INPUT
    /// Consigne brute entrée
    ValueIn    : REAL;
    /// Constante de temps du filtre
    TimeConst  : TIME;
    /// Temps de cycle réel en secondes
    CycleTimeS : REAL;
END_VAR
VAR_OUTPUT
    /// Consigne filtrée sortie
    ValueOut : REAL;
END_VAR
VAR
    T     : REAL;
    Alpha : REAL;
END_VAR

T := TIME_TO_REAL(TimeConst) / 1000.0; // ms → s

IF T <= 0.0 OR CycleTimeS <= 0.0 THEN
    ValueOut := ValueIn;
ELSE
    Alpha    := CycleTimeS / (T + CycleTimeS);
    ValueOut := Alpha * ValueIn + (1.0 - Alpha) * ValueOut;
END_IF;

