(* ═══════════════════════════════════════════════════════════════
   🧪 FB_Sim_Encoder — Simulation physique d'un codeur absolu de treuil
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF/AF_Partie-13_Fonction_Simulation_v2.3.md
   🧩 Brique réduite (Partie3 §1bis, "briques E/S & diagnostics") : pas de contrat
      Enable/Reset/Error complet, pas de StartStop/SafeStop — outil de banc, pas
      du métier machine.
   🎯 Rôle : fait "compter" un codeur absolu comme si le treuil tournait
      réellement, à partir des relais de sens commandés et du palier de vitesse courant.
   📥 Enable      : simulation active (SimulationModeActive AND NOT BusEncoderMxIsReal)
   📥 RelayFwd/RelayRev : sens commandé (contacteurs de sens du treuil)
   📥 StepNumber  : palier vitesse courant (1..5) — ex. instWinchM1.StepNumber
      Vitesse = interpolation linéaire : palier 1 → MinSpeedMps (1 m/s), palier 5 → MaxSpeedMps (2 m/s).
   📥 PresetCmd   : TRUE le cycle où un preset (homing) doit être appliqué (PresettTrigCmd = 2)
   📥 PresetValue : valeur brute à charger lors du preset
   📥 SpeedScaleFactor : facteur fin de confort (réglable à chaud, sans recompiler). Défaut 1.0 = vitesse
      réelle telle que définie par MinSpeedMps/MaxSpeedMps/PointsPerRev/CableM_PerRev/CycleTimeS.
   📤 RawPosOut   : position brute simulée (UDINT), à aiguiller à la place de la valeur
      EtherCAT réelle quand le device n'est pas Operational (voir PRG_02_Encoders.st)
   `RawPos` en `VAR_IN_OUT`, référencé depuis `GVL_PERSISTENT`
      (même pattern que `Calib` dans `FB_Encoder_Homing`) — `PERSISTENT` n'est valide que sur du
      `VAR_GLOBAL` en CODESYS, pas sur une variable locale de FB. Un vrai codeur absolu physique
      conserve son comptage brut même à travers un reset FROID (indépendant de l'automate).
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Sim_Encoder) ===

FUNCTION_BLOCK PUBLIC FB_Sim_Encoder
VAR_INPUT
    Enable           : BOOL;   (* --> [CMD] Active la simulation *)
    RelayFwd         : BOOL;   (* --> [HW] Sens commandé avant *)
    RelayRev         : BOOL;   (* --> [HW] Sens commandé arrière *)
    StepNumber       : INT;    (* --> [CMD] Palier vitesse courant (1..5, 0 = arrêt) *)
    PresetCmd        : BOOL;   (* --> [CMD] Applique un preset (homing) *)
    PresetValue      : UDINT;   (* --> [CFG] Valeur brute à charger au preset *)
    SpeedScaleFactor : REAL := 1.0;   (* --> [CFG] Facteur fin de confort (défaut 1.0) *)
    PresetLatencyCycles : INT := 3;   (* --> [CFG] Nb cycles automate avant application du preset (referencement non instantane) *)
    TestOffsetCmd    : BOOL;          (* --> [TST] Front montant = applique TestOffsetPts (test banc) *)
    TestOffsetPts    : DINT := 0;     (* --> [TST] Décalage signé à appliquer (points bruts) *)
    // 📐 Paramètres physiques du treuil (mêmes valeurs que FB_Encoder_Scale) + vitesse réelle.
    // Vitesse simulée = interpolation linéaire du palier : palier 1 → MinSpeedMps, palier 5 → MaxSpeedMps.
    MinSpeedMps      : REAL := 1.0;    (* --> [CFG] Vitesse palier 1 (m/s) *)
    MaxSpeedMps      : REAL := 2.0;    (* --> [CFG] Vitesse palier 5 (m/s) *)
    PointsPerRev     : UDINT := 8192;  (* --> [CFG] Résolution codeur (pts/tour) *)
    CableM_PerRev    : REAL := 2.0;    (* --> [CFG] Développement câble (m/tour) *)
    CycleTimeS       : REAL := 0.010;  (* --> [CFG] Période tâche PLC (s) — MainTask 10 ms *)
END_VAR
VAR_OUTPUT
    RawPosOut   : UDINT;   (* <-- [DIAG] Position brute simulée *)
END_VAR
VAR_IN_OUT
    RawPos      : UDINT;   (* <-> [BUS] Référence _SimEncoderRawPosM1/M2 (survit au reset froid) *)
END_VAR
VAR
    Increment      : UDINT;              (* . [LOC] Points ajoutés par cycle *)
    EffStep        : INT;               (* . [LOC] Pas borné (>= 1) *)
    SpeedMps       : REAL;              (* . [LOC] Vitesse simulée (m/s) *)
    TestOffsetEdge : R_TRIG;             (* . [LOC] Front TestOffsetCmd *)
    PresetEdge     : R_TRIG;             (* . [LOC] Front montant PresetCmd *)
    PresetPending  : BOOL;               (* . [LOC] Preset en attente d'application (latence) *)
    PresetCount    : INT;                (* . [LOC] Compteur cycles de latence restants *)
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Encoder) ===

{region "§1 Gate"}
IF NOT Enable THEN
    RawPosOut := RawPos;
    RETURN;
END_IF;
{endregion}

{region "§2 Injection test"}
// Injection test banc : VRAI saut de position (comme un glissement réel),
// pour tester Concept 1 / Méca E ET le rattrapage joystick (voir GVL_Simulation bandeau).
TestOffsetEdge(CLK := TestOffsetCmd);
IF TestOffsetEdge.Q THEN
    RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) + TestOffsetPts);
END_IF;
{endregion}

{region "§3 Comptage"}
// 🎚️ Vitesse simulée = interpolation linéaire du palier (palier 1 → MinSpeedMps, palier 5 → MaxSpeedMps),
// pas par pas de (Max−Min)/4. Palier 0 (arrêt) ramène au palier 1 mais aucun mouvement n'est
// appliqué tant que RelayFwd/RelayRev = FALSE (section plus bas).
EffStep  := MAX(StepNumber, 1);
SpeedMps := MinSpeedMps + (INT_TO_REAL(EffStep) - 1.0) * ((MaxSpeedMps - MinSpeedMps) / 4.0);
// Points par cycle = vitesse (m/s) × points par mètre × période tâche (s) × facteur confort.
Increment := REAL_TO_UDINT(SpeedMps * (UDINT_TO_REAL(PointsPerRev) / CableM_PerRev) * CycleTimeS * SpeedScaleFactor);

// Front du preset : lance la latence de referencement (le codeur réel n'est pas
// instantane — il met PresetLatencyCycles cycles a se re-referencer apres le front).
PresetEdge(CLK := PresetCmd);
IF PresetEdge.Q THEN
    PresetPending := TRUE;
    PresetCount := PresetLatencyCycles;
END_IF;

// Pendant l'attente, la position brute est conservee (le codeur n'a pas encore re-reference).
// Le mouvement est gelé pendant la latence, comme un codeur réel en cours de referencement.
IF PresetPending THEN
    IF PresetCount > 0 THEN
        PresetCount := PresetCount - 1;
    ELSE
        // Latence écoulée : applique la valeur cible du preset.
        RawPos := PresetValue;
        PresetPending := FALSE;
    END_IF;
ELSIF RelayFwd THEN
    RawPos := RawPos + Increment;
ELSIF RelayRev THEN
    IF RawPos >= Increment THEN
        RawPos := RawPos - Increment;
    ELSE
        RawPos := 0;
    END_IF;
END_IF;
{endregion}

{region "§4 Sortie"}
RawPosOut := RawPos;
{endregion}

(* =======================================================================
   ⚙️ FB_ExtractionSequence — Fermeture benne et remontée assistée
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Séquence d'extraction (fermeture benne, remontée de contrôle, remontée nominale)
   🛡️ Sécurité : Aucune remontée assistée sans fond confirmé, contrôle palier 1
   📄 Doc métier : DOC/AF/AF_Partie-04_Mode_SemiAuto_Sequenceur_v2.1.md
   ======================================================================= *)
FUNCTION_BLOCK FB_ExtractionSequence
VAR_INPUT
    // === COMMANDES & AUTORISATIONS ===
    Enable                      : BOOL;     // --> [CMD] Activation generale du FB (TRUE=Autorise)
    Reset                       : BOOL;     // --> [CMD] Acquittement defaut (front)
    PowerContactorEngaged       : BOOL;     // --> [SAFE] Chaine de securite OK
    Mode                        : E_Mode;   // --> [CMD] Mode de fonctionnement arbitre
    MotionRequestActive         : BOOL;     // --> [CMD] Intention de mouvement active
    MotionDirection             : INT;      // --> [CMD] Sens de mouvement (+1 = montee)
    BottomPositionConfirmed     : BOOL;     // --> [SAFE] Attestation fond confirme (Kobold ou op)

    // === CAPTEURS & ETATS MATERIELS ===
    BucketIsClosed              : BOOL;     // --> [HW] Benne fermee confirmee
    BucketBusy                  : BOOL;     // --> [HW] Mouvement benne en cours
    BucketError                 : BOOL;     // --> [SAFE] Defaut sur sous-systeme benne
    WinchSyncError              : BOOL;     // --> [SAFE] Defaut de desynchronisme treuils M1/M2
    M1Position_M                : REAL;     // --> [HW] Position codeur treuil M1 (m)
    M2Position_M                : REAL;     // --> [HW] Position codeur treuil M2 (m)
    M1MeasuredSpeedValid        : BOOL;     // --> [HW] Validite mesure vitesse M1
    M2MeasuredSpeedValid        : BOOL;     // --> [HW] Validite mesure vitesse M2
    PositionsValid              : BOOL;     // --> [HW] Validite des mesures de position

    // === CONFIGURATION & REGLAGES ===
    ControlAscentDistance_M     : REAL;     // --> [CFG] Distance palier 1 de controle remontee (m)
END_VAR
VAR_OUTPUT
    // === ETATS IEC & DEFECTUOSITES ===
    Ready                       : BOOL;     // <-- [STAT] FB pret a fonctionner (sortie libre, hors ST_FbStatus)
    // 🧩 Statut transverse (forme cible) — regroupe Busy/Done/Error/ErrorId/State/StateAtError.
    // ErrorId bit0:fond ; bit1:ferme ; bit2:ctrl ; bit3:cfg.
    Status                      : ST_FbStatus; // <-- [STAT] Etat global FB (Busy/Done/Error/ErrorId/State/StateAtError)
    ExtractionState             : E_ExtractionSequenceState; // <-- [STAT] Phase interne extraction

    // === ORDRES & AUTORISATIONS ===
    BucketCloseRequest          : BOOL;     // <-- [ACT] Demande de fermeture benne
    AscentPermit                : BOOL;     // <-- [ACT] Autorisation de remontee assistee
    ForceMinSpeedStep           : BOOL;     // <-- [ACT] Forcage vitesse minimale (palier de controle)
    BottomConfirmationConsumed  : BOOL;     // <-- [STAT] Signal confirmation fond consomme

    // === DIAGNOSTIC IHM ===
    OperatorActionId            : WORD;     // <-- [DIAG] ID action operateur requise
    OperatorAction              : STRING(120); // <-- [DIAG] Message explicatif operateur
END_VAR
VAR
    // === DETECTEURS DE FRONTS ===
    ResetEdge                   : R_TRIG;   // . [LOC] Detecteur front montant Reset

    // === MEMORISATIONS & POSITIONS INTERNES ===
    ControlStartM1Position_M    : REAL;     // . [LOC] Position M1 au debut du palier de controle (m)
    ControlStartM2Position_M    : REAL;     // . [LOC] Position M2 au debut du palier de controle (m)

    // === VARIABLES LOCALES INTERNES ===
    ErrorCausePresent           : BOOL;     // . [LOC] Presence d'une cause de defaut parametrage
END_VAR

{region "§1 Gate desactivation"}
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE; Status.Busy := FALSE; Status.Done := FALSE;
    BucketCloseRequest := FALSE; AscentPermit := FALSE; ForceMinSpeedStep := FALSE;
    BottomConfirmationConsumed := FALSE;
    Status.State := E_State.DISABLED;
    Status.StateAtError := E_State.DISABLED;
    ExtractionState := E_ExtractionSequenceState.WAIT_BOTTOM_CONFIRMATION;
    OperatorActionId := 0; OperatorAction := '';
    RETURN;
END_IF;

{endregion}

{region "§2 Preconditions reset et initialisation sorties"}
ResetEdge(CLK := Reset);
ErrorCausePresent := (ControlAscentDistance_M <= 0.0);
IF ErrorCausePresent THEN
    Status.ErrorId := Status.ErrorId OR 16#0008;
END_IF;
IF ResetEdge.Q AND NOT ErrorCausePresent AND NOT MotionRequestActive THEN
    Status.ErrorId := 16#0000;
    Status.StateAtError := E_State.DISABLED;
    ExtractionState := E_ExtractionSequenceState.WAIT_BOTTOM_CONFIRMATION;
END_IF;

Ready := FALSE; Status.Busy := FALSE; Status.Done := FALSE;
BucketCloseRequest := FALSE; AscentPermit := FALSE; ForceMinSpeedStep := FALSE;
BottomConfirmationConsumed := FALSE;
OperatorActionId := 0; OperatorAction := '';

{endregion}

{region "§3 Machine etat fermeture remontee"}
IF Status.ErrorId <> 16#0000 THEN
    Status.State := E_State.READY;
    ExtractionState := E_ExtractionSequenceState.ERROR_HOLD;
    OperatorActionId := 16#0280;
    OperatorAction := 'Vérifier la benne et les treuils puis réarmer avant de reprendre.';
ELSE
    CASE ExtractionState OF
        E_ExtractionSequenceState.WAIT_BOTTOM_CONFIRMATION:
            Status.State := E_State.INIT;
            IF BottomPositionConfirmed THEN
                ExtractionState := E_ExtractionSequenceState.READY_TO_CLOSE;
            ELSE
                OperatorActionId := 16#0200;
                OperatorAction := 'Confirmer que la benne est posée au fond avant extraction.';
            END_IF;

        E_ExtractionSequenceState.READY_TO_CLOSE:
            Status.State := E_State.READY;
            Ready := TRUE;
            OperatorActionId := 16#0201;
            OperatorAction := 'Demander la montée pour fermer la benne.';
            IF MotionRequestActive AND (MotionDirection = 1) THEN
                BottomConfirmationConsumed := TRUE;
                ExtractionState := E_ExtractionSequenceState.CLOSING_BUCKET;
            END_IF;

        E_ExtractionSequenceState.CLOSING_BUCKET:
            Status.State := E_State.BUSY;
            Status.Busy := TRUE;
            BucketCloseRequest := MotionRequestActive AND (MotionDirection = 1);
            OperatorActionId := 16#0202;
            OperatorAction := 'Maintenir la montée : fermeture de la benne en cours.';
            IF BucketError THEN
                Status.ErrorId := Status.ErrorId OR 16#0002;
                Status.StateAtError := Status.State;
            ELSIF BucketIsClosed AND NOT BucketBusy THEN
                ControlStartM1Position_M := M1Position_M;
                ControlStartM2Position_M := M2Position_M;
                ExtractionState := E_ExtractionSequenceState.CONTROL_ASCENT;
            END_IF;

        E_ExtractionSequenceState.CONTROL_ASCENT:
            Status.State := E_State.BUSY;
            Status.Busy := TRUE;
            AscentPermit := MotionRequestActive AND (MotionDirection = 1);
            ForceMinSpeedStep := TRUE;
            OperatorActionId := 16#0203;
            OperatorAction := 'Maintenir la montée : contrôle charge au palier minimal.';
            IF WinchSyncError OR NOT PositionsValid OR NOT M1MeasuredSpeedValid OR NOT M2MeasuredSpeedValid THEN
                Status.ErrorId := Status.ErrorId OR 16#0004;
                Status.StateAtError := Status.State;
            ELSIF (M1Position_M >= (ControlStartM1Position_M + ControlAscentDistance_M))
               AND (M2Position_M >= (ControlStartM2Position_M + ControlAscentDistance_M)) THEN
                ExtractionState := E_ExtractionSequenceState.NOMINAL_ASCENT;
            END_IF;

        E_ExtractionSequenceState.NOMINAL_ASCENT:
            Status.State := E_State.BUSY;
            Status.Busy := TRUE;
            AscentPermit := MotionRequestActive AND (MotionDirection = 1);
            OperatorActionId := 16#0204;
            OperatorAction := 'Maintenir la montée : extraction en cours.';
            IF WinchSyncError OR NOT PositionsValid THEN
                Status.ErrorId := Status.ErrorId OR 16#0004;
                Status.StateAtError := Status.State;
            END_IF;

        E_ExtractionSequenceState.ERROR_HOLD:
            Status.State := E_State.READY;
    END_CASE;
END_IF;

Status.Error := (Status.ErrorId <> 16#0000);

{endregion}

TYPE ST_ChainTranslation :
STRUCT
    Inputs_100    : ST_Chain_Translation_Inputs;
    Demandes_200  : ST_Chain_Translation_Demandes;
    Safety_300    : ST_Chain_Translation_Safety;
    Control_400   : ST_Chain_Translation_Control;
    Outputs_500   : ST_Chain_Translation_Outputs;
END_STRUCT
END_TYPE

(* ═══════════════════════════════════════════════════════════════
   📤 PRG_06_Outputs — Barrière finale des sorties physiques (ST pur)
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF/AF_Partie-06_Acquisition_Qualification_IO_v2.3.md §5
   ⚙️ Exécuté en position 6 (après PRG_05_Translation).
   🛡️ Interlocks finaux M1/M2/M3 + agrégation PowerCutOff + chaîne AU.
   🔒 SafetyStructureNotValidated reste TRUE : aucune sortie moteur/frein
       autorisée tant que ce garde-fou n'est pas retiré.
   🎨 Organisation FONCTIONNELLE : chaque bloc regroupe la chaîne complète d'une
       fonction — conditions qui activent/désactivent la sortie (SafeStop / PowerCutOff /
       interlocks) → FB interlock → ordres → sorties physiques → bus inter-PRG. Lisible
       d'un coup d'œil.
   ═══════════════════════════════════════════════════════════════ *)

PROGRAM PRG_06_Outputs

VAR_INPUT
    // === 📥 ENTRÉES PROGRAMME (AUCUNE - PILOTÉ VIA GVL_IHM & PRG_02 À 05) ===
END_VAR

VAR_OUTPUT
    // === 🚌 BUS INTER-PRG (producteur unique) ===
    Data : ST_OutputsInterPrg; // <-- [BUS] Ordres actionneurs finaux (rebouclés FB_SimBench)

    // === 🚨 ÉTATS CHAÎNE AU & COUPURE ===
    EmergencyArmingPulseActive   : BOOL; // <-- [STAT] Impulsion rearmement AU active
    EmergencyArmingLockoutActive : BOOL; // <-- [STAT] Verrouillage rearmement AU actif
    ArmingSeqStep                : INT;  // <-- [STAT] Etape sequence rearmement AU
    RedundancyTestFailed         : BOOL; // <-- [DIAG] Test redondance AU echoue
    EmergencyArmingFailed        : BOOL; // <-- [DIAG] Echec rearmement AU
    EmergencyState               : ST_Safety_Emergency_State; // <-- [STAT] Etat chaine AU
    EmergencyDiag                : ST_Safety_Emergency_Diag;  // <-- [DIAG] Diagnostic chaine AU
    PowerCutOffActive            : BOOL; // <-- [SAFE] Demande de coupure finale active

    SafetyStructureNotValidated  : BOOL := FALSE; // 🔓 Garde-fou : autorisations M1/M2/M3 liees a leurs securites
    M1InterlockEnable            : BOOL; // <-- [SAFE] Gate finale M1 (Enable AND NOT PowerCutOff)
    M2InterlockEnable            : BOOL; // <-- [SAFE] Gate finale M2 (Enable AND NOT PowerCutOff)
    M3InterlockEnable            : BOOL; // <-- [SAFE] Gate finale M3 (Enable AND NOT PowerCutOff)
    M1PowerCutOffSafetyInfo      : BOOL; // <-- [DIAG] Securites M1 coupant la puissance
    M1SafeStopSafetyInfo         : BOOL; // <-- [DIAG] Securites M1 SafeStop
    M1BlockedBySafetyInfo        : BOOL; // <-- [DIAG] M1 bloque par securite (PowerCutOff OU SafeStop)
    M2PowerCutOffSafetyInfo      : BOOL; // <-- [DIAG] Securites M2 coupant la puissance
    M2SafeStopSafetyInfo         : BOOL; // <-- [DIAG] Securites M2 SafeStop
    M2BlockedBySafetyInfo        : BOOL; // <-- [DIAG] M2 bloque par securite (PowerCutOff OU SafeStop)
    M3PowerCutOffSafetyInfo      : BOOL; // <-- [DIAG] Securites M3 coupant la puissance
    M3SafeStopSafetyInfo         : BOOL; // <-- [DIAG] Securites M3 SafeStop
    M3BlockedBySafetyInfo        : BOOL; // <-- [DIAG] M3 bloque par securite (PowerCutOff OU SafeStop)

    // Les noms Device bruts (*_DQ / *_RQ) ne sont pas declares ici : les declarer
    // creerait une collision avec la globale homonyme du mapping E/S.
    M3_DriveControlWord          : WORD; // <-- [ACT] Mot commande variateur M3 (0x3101) — cible mapping E/S
    M3_DriveFreqRefWord          : WORD; // <-- [ACT] Consigne frequence M3 (0x3100, x100) — cible mapping E/S
    KoboldContactorCmd           : BOOL; // <-- [ACT] Ordre alimentation contacteur capteur fond Kobold
END_VAR

VAR
    // === 🛡️ SOUS-INSTANCES FB INTERLOCKS SORTIES ===
    instWinchOutputInterlockM1       : FB_WinchOutputInterlock;       // * [INST] Barriere finale treuil M1
    instWinchOutputInterlockM2       : FB_WinchOutputInterlock;       // * [INST] Barriere finale treuil M2
    instTranslationOutputInterlockM3 : FB_TranslationOutputInterlock; // * [INST] Barriere finale translation M3
    instSafetyEmergencyManagement    : FB_Safety_EmergencyManagement;    // * [INST] Gestionnaire de rearmement AU

    // === ⚡ ORDRES ACTIONNEURS (publiés via Data) ===
    M1RelayFwd                   : BOOL; // . [LOC] Ordre contacteur montee treuil M1
    M1RelayRev                   : BOOL; // . [LOC] Ordre contacteur descente treuil M1
    M1SpeedContactor1            : BOOL; // . [LOC] Ordre contacteur palier 1 treuil M1
    M1SpeedContactor2            : BOOL; // . [LOC] Ordre contacteur palier 2 treuil M1
    M1SpeedContactor3            : BOOL; // . [LOC] Ordre contacteur palier 3 treuil M1
    M1SpeedContactor4            : BOOL; // . [LOC] Ordre contacteur palier 4 treuil M1
    M1BrakeCmd                   : BOOL; // . [LOC] Ordre desserrage frein M1
    M2RelayFwd                   : BOOL; // . [LOC] Ordre contacteur montee/fermeture treuil M2
    M2RelayRev                   : BOOL; // . [LOC] Ordre contacteur descente/ouverture treuil M2
    M2SpeedContactor1            : BOOL; // . [LOC] Ordre contacteur palier 1 treuil M2
    M2SpeedContactor2            : BOOL; // . [LOC] Ordre contacteur palier 2 treuil M2
    M2SpeedContactor3            : BOOL; // . [LOC] Ordre contacteur palier 3 treuil M2
    M2SpeedContactor4            : BOOL; // . [LOC] Ordre contacteur palier 4 treuil M2
    M2BrakeCmd                   : BOOL; // . [LOC] Ordre desserrage frein M2
    TranslationBrakeCmd          : BOOL; // . [LOC] Demande frein M3 arbitree
    PowerKeepAliveACmd           : BOOL; // . [LOC] Maintien puissance voie A
    PowerKeepAliveBCmd           : BOOL; // . [LOC] Maintien puissance voie B
    EmergencyArmingCmd           : BOOL; // . [LOC] Impulsion rearmement puissance AU

    // === ⚙️ VARIABLES LOCALES INTERNES ===
    PowerCutOffReq                   : BOOL; // . [LOC] Demande agregative coupure puissance
END_VAR

// ═══════════════════════════════════════════════════════════════
// 🛗 §1 TREUIL M1 (Retenue) — conditions + interlock + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ D'un coup d'œil : ce qui active/désactive la sortie M1.
//   - M1InterlockEnable      : gate finale (Enable ET pas de PowerCutOff)
//   - M1PowerCutOffSafetyInfo: défauts qui COUPENT la puissance
//   - M1SafeStopSafetyInfo   : défauts qui font SafeStop (rampe rapide)
//   - M1BlockedBySafetyInfo  : synthèse (PowerCutOff OU SafeStop)
// Sources : PRG_04 (WinchM1FinalInterlockRequest / WinchM1Safety).

M1InterlockEnable := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.Enable
                      AND NOT PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.PowerCutOff;

M1PowerCutOffSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM1Safety.PowerCutOff
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaA
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaB
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaC
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaD
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaE
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ThermalFault;

M1SafeStopSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM1Safety.SafeStop
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.Error
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorOperatorComm
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorEncoder
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorPhaseRotation
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorOppositeDir
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorNoMovement;

M1BlockedBySafetyInfo := M1PowerCutOffSafetyInfo OR M1SafeStopSafetyInfo;

instWinchOutputInterlockM1(
    Enable                     := M1InterlockEnable,
    Reset                      := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged      := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.PowerContactorEngaged,
    SafeStop                   := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.SafeStop,
    BrakeFeedback              := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.BrakeFeedback,
    FwdRevSpeedFeedbackOff     := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.FwdRevSpeedFeedbackOff,
    RequestedRelayFwd          := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedRelayFwd,
    RequestedRelayRev          := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedRelayRev,
    RequestedContactor1        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor1,
    RequestedContactor2        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor2,
    RequestedContactor3        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor3,
    RequestedContactor4        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor4,
    RequestedStep               := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedStep
);

M1RelayFwd        := instWinchOutputInterlockM1.RelayFwd;
M1RelayRev        := instWinchOutputInterlockM1.RelayRev;
M1SpeedContactor1 := instWinchOutputInterlockM1.Contactor1;
M1SpeedContactor2 := instWinchOutputInterlockM1.Contactor2;
M1SpeedContactor3 := instWinchOutputInterlockM1.Contactor3;
M1SpeedContactor4 := instWinchOutputInterlockM1.Contactor4;
// Recalcul independant sur les DQ finaux (pas une recopie de BrakeCmd).
M1BrakeCmd        := M1RelayFwd OR M1RelayRev;

// ── Sorties physiques M1 ──
M1_RelayFwd_Up_DQ            := M1RelayFwd;
M1_RelayRev_Down_DQ          := M1RelayRev;
M1_SpeedContactor_1_DQ       := M1SpeedContactor1;
M1_SpeedContactor_2_DQ       := M1SpeedContactor2;
M1_SpeedContactor_3_DQ       := M1SpeedContactor3;
M1_SpeedContactor_4_DQ       := M1SpeedContactor4;
M1_BrakeRelease_RQ           := M1BrakeCmd;

// ── Bus inter-PRG M1 ──
Data.M1RelayFwd            := M1RelayFwd;
Data.M1RelayRev            := M1RelayRev;
Data.M1SpeedContactor1     := M1SpeedContactor1;
Data.M1SpeedContactor2     := M1SpeedContactor2;
Data.M1SpeedContactor3     := M1SpeedContactor3;
Data.M1SpeedContactor4     := M1SpeedContactor4;
Data.M1BrakeCmd            := M1BrakeCmd;

// ═══════════════════════════════════════════════════════════════
// 🛗 §2 TREUIL M2 (Benne) — conditions + interlock + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ Même lecture que M1 : gate finale, défauts PowerCutOff / SafeStop, synthèse.
// Sources : PRG_04 (WinchM2FinalInterlockRequest / WinchM2Safety / BucketState).

M2InterlockEnable := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.Enable
                      AND NOT PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.PowerCutOff;

M2PowerCutOffSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM2Safety.PowerCutOff
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaA
