(* ═══════════════════════════════════════════════════════════════
   🛡️ FB_Safety_EmergencyManagement — Bloc Safety Composite (Parent)
   ───────────────────────────────────────────────────────────────
   📄 Rôle : Bloc de sécurité principal de la boucle d'arrêt d'urgence.
   🧩 Encapsule la Logique (FB_Safety_EmergencyManagementLogic) et le 
      Pilote Physique (FB_Safety_EmergencyManagementOutput) par composition.
   ═══════════════════════════════════════════════════════════════
    📄 Docs : DOC/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md ; DOC/AF_Partie-03_Contrats_Composants_v2.0.md
*)

FUNCTION_BLOCK PUBLIC FB_Safety_EmergencyManagement
VAR_INPUT
    Enable              : BOOL;        // Active la surveillance
    Reset               : BOOL;        // Front acquittement défauts
    ArmRequest          : BOOL;        // Demande de réarmement (BtnEmergencyArming)
    EmergencyChainClosed      : BOOL;        // Retour physique boucle d'urgence amont contacteur
    PowerContactorEngaged     : BOOL;        // Confirmation contacteur de puissance principal
    PowerCutOffRequest  : BOOL;        // Requête de coupure logique issue des métiers
    BtnEmergencyCutOff  : BOOL;        // Commande d'ouverture d'urgence depuis l'IHM
END_VAR
VAR_OUTPUT
    Ready               : BOOL;
    Busy                : BOOL;
    Done                : BOOL;
    Error               : BOOL;
    ErrorId             : WORD;        // bit0: RedundancyTestFailed, bit1: EmergencyArmingFailed
    
    PowerCutOff_A_RQ    : BOOL;        // Sortie de pilotage canal A (maintenu à TRUE, fail-safe)
    PowerCutOff_B_RQ    : BOOL;        // Sortie de pilotage canal B (maintenu à TRUE, fail-safe)
    EmergencyArming_RQ  : BOOL;        // Impulsion réarmement physique (1s)
    
    ArmingSeqStep       : INT;         // Étape de diagnostic : 0=IDLE, 1=TestA, 2=RestoreA, 3=TestB, 4=RestoreB, 5=Pulse, 6=Confirm
    RedundancyTestFailed: BOOL;        // Canal A ou B resté collé/shunté détecté à l'auto-test
    EmergencyArmingFailed: BOOL;       // Contacteur de puissance n'a pas confirmé l'armement
    EmergencyArmingLockoutActive : BOOL; // Verrouillage temporel de 5s entre les essais
END_VAR
VAR
    // 🧱 Composition interne des sous-blocs
    Logic               : FB_Safety_EmergencyManagementLogic;
    Output              : FB_Safety_EmergencyManagementOutput;
END_VAR

// === IMPLEMENTATION ===

// 🛑 1. Appels des instances internes
Logic(
    Enable := Enable,
    Reset := Reset,
    ArmRequest := ArmRequest,
    EmergencyChainClosed := EmergencyChainClosed,
    PowerContactorEngaged := PowerContactorEngaged,
    PowerCutOffRequest := PowerCutOffRequest,
    BtnEmergencyCutOff := BtnEmergencyCutOff
);

Output(
    Enable := Enable,
    Cmd := Logic.Cmd
);

// 📤 2. Propagation des signaux vers les sorties du bloc parent
Ready := Enable;
Busy  := (Logic.ArmingSeqStep <> 0);
Done  := PowerContactorEngaged;
Error := Logic.Error;
ErrorId := Logic.ErrorId;

PowerCutOff_A_RQ   := Output.PowerCutOff_A_RQ;
PowerCutOff_B_RQ   := Output.PowerCutOff_B_RQ;
EmergencyArming_RQ := Output.EmergencyArming_RQ;

ArmingSeqStep                := Logic.ArmingSeqStep;
RedundancyTestFailed         := Logic.RedundancyTestFailed;
EmergencyArmingFailed        := Logic.EmergencyArmingFailed;
EmergencyArmingLockoutActive := Logic.EmergencyArmingLockoutActive;

(* ═══════════════════════════════════════════════════════════════════════════════
   📊 FB_WinchLoadEstimator — Estimation empirique de charge treuil
   ═══════════════════════════════════════════════════════════════════════════════
   🧩 Brique de diagnostic/information, sans commande moteur et sans SafeStop.
   🎯 Croise le palier commandé et la bande de vitesse mesurée pour lire une
      estimation dans ST_WinchLoadEstimateTable.
   ⚠️ La table doit être explicitement marquée IsConfigured : sinon la sortie
      reste à 0 % et Configured reste FALSE.
   ═══════════════════════════════════════════════════════════════════════════════
   📄 Docs : DOC/AF_Partie-10_Fonction_Winch_v2.0.md
*)

FUNCTION_BLOCK PUBLIC FB_WinchLoadEstimator
VAR_INPUT
    Enable             : BOOL;
    Reset              : BOOL;
    PowerContactorEngaged    : BOOL;
    Mode               : E_Mode;
    ActiveSpeedStep    : INT;                       // Palier commandé 0..5
    MeasuredSpeedMps   : REAL;                      // Vitesse câble absolue
    MeasuredSpeedSignedMps : REAL;                  // Vitesse signée : positive = montée, négative = descente
    SpeedConfig        : ST_WinchSpeedConfig;       // Plages vitesse mesurée
    LoadTable          : ST_WinchLoadEstimateTable;// Table empirique 5x5
END_VAR
VAR_OUTPUT
    Ready              : BOOL;
    Busy               : BOOL;
    Done               : BOOL;
    Error              : BOOL;
    ErrorId            : WORD;                     // bit0 : entrée/table invalide
    State              : E_State;
    StateAtError       : E_State;
    SpeedBand          : INT;                      // Bande vitesse courante 0..5
    EstimatedLoadPct   : REAL;                     // Estimation informative 0..100 %
    Configured         : BOOL;                     // TRUE si table explicitement validée
    Ascending          : BOOL;                     // TRUE uniquement pendant une montée mesurée
END_VAR
VAR
    ResetEdge          : R_TRIG;
    ErrorEdge          : R_TRIG;
    PreviousSpeedBand  : INT;
    HasPreviousBand    : BOOL;
    SelectedLoadPct    : REAL;
END_VAR

// 🛑 1. GATE — aucune estimation lorsque le bloc est désactivé ou l'AU absent.
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE;
    Busy := FALSE;
    Done := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    State := E_State.DISABLED;
    SpeedBand := 0;
    EstimatedLoadPct := 0.0;
    Configured := FALSE;
    Ascending := FALSE;
    HasPreviousBand := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
Busy := FALSE;
Done := FALSE;
State := E_State.READY;
ResetEdge(CLK := Reset);
Configured := LoadTable.IsConfigured;
// 📈 WINCH-CORE-01 : l'estimation de charge n'a de sens qu'en montée.
// La bande de vitesse reste calculée pour le diagnostic et le garde-fou de palier,
// mais EstimatedLoadPct est forcée à zéro à l'arrêt et en descente.
Ascending := (MeasuredSpeedSignedMps > 0.0);

// 📏 2. CLASSEMENT DE LA VITESSE — hystérésis autour des 4 frontières.
IF (MeasuredSpeedMps < 0.0) OR (SpeedConfig.MaxMeasuredSpeedMps <= 0.0) THEN
    ErrorId := ErrorId OR 16#0001;
    SpeedBand := 0;
ELSIF NOT HasPreviousBand THEN
    IF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[1] THEN
        PreviousSpeedBand := 1;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[2] THEN
        PreviousSpeedBand := 2;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[3] THEN
        PreviousSpeedBand := 3;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[4] THEN
        PreviousSpeedBand := 4;
    ELSE
        PreviousSpeedBand := 5;
    END_IF;
    HasPreviousBand := TRUE;
    SpeedBand := PreviousSpeedBand;
ELSE
    // 🔒 Valider l'état mémorisé avant toute indexation dynamique.
    IF PreviousSpeedBand < 1 OR PreviousSpeedBand > 5 THEN
        PreviousSpeedBand := 1;
        ErrorId := ErrorId OR 16#0001;
    END_IF;

    // CODESYS ne garantit pas le court-circuit des expressions AND :
    // chaque borne est donc testée dans une branche séparée avant accès.
    IF PreviousSpeedBand < 5 THEN
        IF MeasuredSpeedMps > (SpeedConfig.SpeedBandMaxMps[PreviousSpeedBand]
                               + SpeedConfig.SpeedBandHysteresisMps) THEN
            PreviousSpeedBand := PreviousSpeedBand + 1;
        END_IF;
    END_IF;
    IF PreviousSpeedBand > 1 THEN
        IF MeasuredSpeedMps < (SpeedConfig.SpeedBandMaxMps[PreviousSpeedBand - 1]
                               - SpeedConfig.SpeedBandHysteresisMps) THEN
            PreviousSpeedBand := PreviousSpeedBand - 1;
        END_IF;
    END_IF;
    SpeedBand := PreviousSpeedBand;
END_IF;

// 📊 3. LECTURE TABLE — bornes séparées avant l'accès au tableau 5x5.
EstimatedLoadPct := 0.0;
IF Configured THEN
    IF Ascending THEN
        IF ActiveSpeedStep >= 1 THEN
            IF ActiveSpeedStep <= 5 THEN
                IF SpeedBand >= 1 THEN
                    IF SpeedBand <= 5 THEN
                        SelectedLoadPct := LoadTable.LoadPctByStepAndSpeedBand[ActiveSpeedStep][SpeedBand];
                        IF (SelectedLoadPct < 0.0) OR (SelectedLoadPct > 100.0) THEN
                            ErrorId := ErrorId OR 16#0001;
                        ELSE
                            EstimatedLoadPct := SelectedLoadPct;
                        END_IF;
                    END_IF;
                END_IF;
            END_IF;
        END_IF;
    END_IF;
END_IF;

// 📤 4. SORTIES D'ÉTAT ET ACQUITTEMENT.
IF ResetEdge.Q AND (ErrorId <> 16#0000) AND (MeasuredSpeedMps >= 0.0) THEN
    ErrorId := 16#0000;
END_IF;
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   ↔️ FB_Translation — Directeur de l'axe transversal M3 (variateur AC600)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : ARCHIVES/Doc/AF_Partie-11_Fonction_Translation_v2.0.md
   🔌 FB DE MOUVEMENT : porte StartStop + SafeStop en plus de l'interface
      standard. Précédence Enable > SafeStop > StartStop.
   📡 Pilotage exclusivement ETHERCAT nominal (mot de commande, consigne fréquence).
   🧩 Compose FB_Brake (réutilisé TEL QUEL depuis COMMUN).
   ⚠️ CORRECTIF (retour terrain 2026-08-05) : une inversion de sens PLUS RAPIDE que le
      temps de décélération réel bloquait indéfiniment `CommandedDirection` (la translation
      ne s'arrêtait jamais, continuait dans l'ancien sens) — la cible de rampe suivait la
      magnitude joystick en continu, sans garantie de croiser le seuil d'arrêt qui
      autorise l'interlock changement de sens (§5). Même bug déjà corrigé sur `FB_Winch`
      (REX 2026-07-02), jamais porté ici. Corrigé : `DirectionChangePending` FORCE
      désormais la cible à 0.0 dès qu'un changement de sens est en attente, de façon
      déterministe et indépendante du joystick (voir §4 dans le corps ST).
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Translation
VAR_INPUT
    Enable                      : BOOL;        // Active le FB. FALSE = neutralisation totale (sorties coupées)
    Reset                       : BOOL;        // Acquittement défaut (front)
    PowerContactorEngaged             : BOOL;        // Chaîne AU réarmée + conditions globales OK
    Mode                        : E_Mode;      // Mode courant
    StartStop                   : BOOL;        // TRUE = rampe accélération, FALSE = rampe décélération NORMALE
    SafeStop                    : BOOL;        // Sortie FB_Safety_Translation : TRUE = rampe décélération RAPIDE (Enable maintenu)
    Direction                   : INT;         // -1 = Rev, 0 = Neutre, +1 = Fwd (source d'autorité du sens)
    SpeedRefPct                 : REAL;        // Magnitude de la consigne (de 0 à 100%)
    PositionSensorTarget        : BOOL;        // Capteur position cible courante
    // 🆕 2026-08-06 : 3 capteurs déclencheurs de ralentissement, un cran avant chaque cible
    // (même principe que PV→Trémie, généralisé — voir §4bis dans le corps ST)
    SlowdownSensorTremie         : BOOL;        // Capteur PV — ralentissement avant Trémie (Direction=1)
    SlowdownSensorMaintenance    : BOOL;        // Capteur P1 — ralentissement avant Maintenance (Direction=-1)
    SlowdownSensorP1             : BOOL;        // Capteur P2 — ralentissement avant P1 (Direction=-1, arrêt propre pour travail)
    LimitSwitchFwd              : BOOL;        // Fin de course extrême avant
    LimitSwitchRev              : BOOL;        // Fin de course extrême arrière

    // 🔌 Spécifique ETHERCAT (image process EtherCAT, rafraîchie par EtherCatTask 4ms)
    DriveStatusWord              : WORD;       // Mot d'état AC600 lu depuis l'image d'entrée EtherCAT
    DriveActualFreqHz            : REAL;       // Fréquence réelle mesurée (Hz)

    BypassContactorCheck         : BOOL;       // 🧪 TRUE = désactive StuckClosed/StuckOpen pour le frein (simulation)
    BypassLimitSwitch            : BOOL;       // 🚧 TRUE = ignore les fins de course extrêmes
    BrakeFeedback                : BOOL;       // Retour physique direct : TRUE = frein OUVERT (desserré)
    // 🆕 2026-08-06 (retour terrain, REX câblage) : compense le câblage moteur (U/V inversés) —
    // UNIQUEMENT sur le mot de commande variateur en sortie (§5bis). Direction/CommandedDirection
    // reste partout ailleurs le sens SÉMANTIQUE réel (+1 = physiquement vers Trémie), pour rester
    // apparié aux vrais capteurs (LimitSwitchFwd/Rev, SlowdownSensorXxx) quel que soit le câblage.
    // ⚠️ AVANT ce correctif, l'inversion était appliquée en amont (PRG_05, sur M3_Direction_Active
    // lui-même) : avec le câblage réel de la machine, ça désaccordait TOUTE la logique sécurité/
    // ralentissement appariée aux capteurs physiques (seule la coupure dure indépendante du sens,
    // §0bis PRG_05, arrêtait encore la machine — le verrou d'arrivée logiciel ne s'armait jamais).
    InvertDriveDirection          : BOOL;

    // Réglages rampe (RETAIN)
    CfgRampAccelRate                : REAL := 20.0;    // %/s — accélération
    CfgRampDecelNormalRate          : REAL := 40.0;    // %/s — décélération normale
    CfgRampDecelFastRate            : REAL := 100.0;   // %/s — décélération RAPIDE
    DirectionInterlockDelay      : TIME := T#200ms; // Délai avant d'autoriser un changement de sens à l'arrêt

    // Réglages ETHERCAT uniquement (RETAIN)
    ApproachSpeedTremieHz        : REAL := 10.0;    // Vitesse réduite d'approche Trémie en Hz (piloté par SlowdownSensorTremie)
    ApproachSpeedMaintenanceHz   : REAL := 10.0;    // Vitesse réduite d'approche Maintenance en Hz (piloté par SlowdownSensorMaintenance)
    ApproachSpeedP1Hz            : REAL := 10.0;    // Vitesse réduite d'approche P1 en Hz (piloté par SlowdownSensorP1)
    DriveFreqScaleMaxHz          : REAL := 60.0;    // Échelle 0..100 % → MaxHz (câblé depuis _TranslationMaxFreq_Hz par PRG_07 — defaut 60.0 si non raccordé)

    // Réglages communs
    CaptorDebounce                : TIME := T#100ms; // Filtrage capteur de position cible
    BrakeDelayContactClose        : TIME := T#100ms; // Voir FB_Brake
    BrakeDelayMagnetise           : TIME := T#300ms; // Voir FB_Brake
    BrakeDelayMotorDecel          : TIME := T#500ms; // Voir FB_Brake
    BrakeFeedbackTimeout          : TIME := T#300ms; // Strictement sous watchdog final 500 ms
END_VAR
VAR_OUTPUT
    Ready               : BOOL;
    Busy                : BOOL;
    Done                : BOOL;
    Error               : BOOL;
    ErrorId             : WORD;        // bit0: "Défaut frein Translation" - Brake.Error ; bit3: "Défaut variateur AC600" - défaut variateur (DriveStatusWord.4) ; bit6: "Limite extrême Translation atteinte" - Fdc extrême atteint
    State               : E_State;
    StateAtError        : E_State;
    TargetReached        : BOOL;       // Capteur position cible
    RequestedDriveControlWord : WORD; // Demande métier AC600, arbitrée par FB_TranslationOutputInterlock_LD
    RequestedDriveFreqHz      : REAL; // Demande métier fréquence, arbitrée par FB_TranslationOutputInterlock_LD
    BrakeReleaseRequest       : BOOL; // Demande métier desserrage, issue de FB_Brake
    BrakeCommandOpenConfirmed : BOOL; // TRUE = frein ouvert = commande ouverture confirmée (depuis FB_Brake)
    BrakeContactorCheck  : ST_ContactorCheck; // Diag contacteur frein
END_VAR
VAR
    Brake                : FB_Brake;       // Séquence frein
    CycleTimeCalc        : FB_CycleTime;
    SpeedRamp             : FB_Ramp;       // Rampe de vitesse logicielle (PLC)
    ResetEdge            : R_TRIG;
    ErrorEdge            : R_TRIG;
    DirectionChangeDelay : TON;            // Interlock changement de sens
    CommandedDirection   : INT;            // Sens réellement appliqué
    DirectionChangePending : BOOL;         // 🆕 2026-08-05 : force la rampe à 0 pendant une inversion de sens en attente
    PhysicalDriveDirection : INT;          // 🆕 2026-08-06 : CommandedDirection compensé câblage (InvertDriveDirection) — UNIQUEMENT pour le mot de commande variateur, jamais pour l'appariement capteur
    RampTargetPct        : REAL;
    CaptorDebounceTon     : TON;
    ArrivalEdge            : R_TRIG;
    DirectionAtArrival     : INT;
    ArrivalLock             : BOOL;        // Arrêt exact sur capteur cible
    MovementRequested      : BOOL;         // Pilote FB_Brake
    FirstScanDone          : BOOL;
    // 🆕 2026-08-06 (revue sécurité) : garde-fou watchdog — DriveActualFreqHz est un passthrough
    // EtherCAT SANS contrôle de fraîcheur (PRG_02_Acquisition, TimeConst=0ms). Si la comm variateur
    // se fige (perte EtherCAT) sur une dernière valeur ≥1.0 Hz, plus rien ne referme le frein tant
    // que ce garde-fou n'existe pas — même si SafeStop a déjà ramené la rampe théorique à 0. Force
    // le relâchement du frein 2s après la fin de la rampe théorique, quoi que dise DriveActualFreqHz.
    TonBrakeRealFreqTimeout : TON;
END_VAR

// === IMPLEMENTATION ===

// 🛑 1. GATE (Enable / PowerContactorEngaged) — neutralisation totale, sorties sûres
IF NOT Enable OR NOT PowerContactorEngaged THEN
    RequestedDriveControlWord := 0; RequestedDriveFreqHz := 0.0;

    Brake(Enable := FALSE, Reset := FALSE, MovementRequested := FALSE, ContactorFeedback := BrakeFeedback,
          DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
          DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout);
    BrakeReleaseRequest := Brake.BrakeCmd;
    BrakeCommandOpenConfirmed := Brake.BrakeCommandOpenConfirmed;
    BrakeContactorCheck := Brake.ContactorCheck;

    CommandedDirection := 0;
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    SpeedRamp(Target := 0.0, AccelRate := CfgRampAccelRate, DecelRate := CfgRampDecelFastRate, CycleTimeS := CycleTimeCalc.CycleTimeS);

    ArrivalLock := FALSE;

    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    RETURN;
END_IF;

// 🧹 Initialisation au premier scan : purge des résidus RAM d'un Online Change / Warm Start et évitement des alarmes transitoires
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;
CycleTimeCalc(DefaultValueS := 0.010);   // MainTask = 10 ms

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 📡 3. CAPTEUR POSITION CIBLE (debounce)
CaptorDebounceTon(IN := PositionSensorTarget, PT := CaptorDebounce);
TargetReached := CaptorDebounceTon.Q;

// ⚙️ 4. CORE — arbitrage rampe : Enable > SafeStop > StartStop
// 🆕 2026-08-05 : DirectionChangePending FORCE la cible à 0.0 dès qu'une inversion de
// sens est en attente — sans ça, la cible suit la magnitude joystick en continu et ne
// croise jamais le seuil d'arrêt (0.1%) qui autorise l'interlock §5 à basculer
// CommandedDirection. Une inversion plus rapide que la décélération réelle bloquait donc
// indéfiniment le mouvement dans l'ancien sens (même bug que FB_Winch, REX 2026-07-02).
DirectionChangePending := (Direction <> CommandedDirection) AND (CommandedDirection <> 0);

RampTargetPct := 0.0;
IF NOT SafeStop AND StartStop AND NOT DirectionChangePending THEN
    // Si butée fin de course extrême atteinte dans le sens de marche demandé, consigne forcée à 0
    // 🌐 BypassLimitSwitch = TRUE → ignore cette protection
    IF NOT BypassLimitSwitch AND ((Direction = 1 AND LimitSwitchFwd) OR (Direction = -1 AND LimitSwitchRev)) THEN
        RampTargetPct := 0.0;
    ELSE
        RampTargetPct := ABS(SpeedRefPct);
        // 🎚️ Consigne minimale joystick (1.0 Hz) : si un mouvement est demandé (SpeedRefPct > 0.0), la consigne est au moins égale à 1.0 Hz
        IF RampTargetPct > 0.0 THEN
            RampTargetPct := MAX(RampTargetPct, (1.0 / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
        END_IF;
    END_IF;
END_IF;

// ⏱️ 4bis. RALENTISSEMENT AUTO À L'APPROCHE (piloté par capteur, remplace le timer)
// 🔧 REX 2026-07-18 : ApproachTime (timer générique, toute direction confondue) remplacé par un
// capteur dédié qui ne déclenche le ralentissement QU'à l'approche de sa cible, jamais l'inverse.
// 🆕 2026-08-06 : généralisé à 3 paires capteur/cible indépendantes — chaque capteur "un cran
// avant" la cible finale déclenche SA propre vitesse réduite, dans SON sens de marche uniquement :
//   PV       + Direction=1  → approche Trémie
//   P1       + Direction=-1 → approche Maintenance
//   P2       + Direction=-1 → approche P1 (arrêt propre pour travail)
IF (Direction = 1) AND SlowdownSensorTremie THEN
    RampTargetPct := LIMIT(0.0, RampTargetPct, (ApproachSpeedTremieHz / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
END_IF;
IF (Direction = -1) AND SlowdownSensorMaintenance THEN
    RampTargetPct := LIMIT(0.0, RampTargetPct, (ApproachSpeedMaintenanceHz / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
END_IF;
IF (Direction = -1) AND SlowdownSensorP1 THEN
    RampTargetPct := LIMIT(0.0, RampTargetPct, (ApproachSpeedP1Hz / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
END_IF;

// 🎯 4ter. VERROUILLAGE ANTI-REBONDS SENS EN BUTÉE (Trémie, P1, Maintenance, Fdc extrêmes)
// 🆕 2026-08-06 (retour terrain + revue) : élargi à P1 (arrêt travail), pas seulement les 2
// extrémités. Dès qu'on touche un capteur d'arrêt (TargetReached, débounce 100ms) OU un fin de
// course dur (LimitSwitchFwd/Rev, §5bis — immédiat, non débounce, mais toute activation même
// brève arme le même verrou), le sens d'arrivée (DirectionAtArrival) est MÉMORISÉ et BLOQUÉ.
// 🔧 REX 2026-08-06 (revue) : LimitSwitchFwd/Rev ne passaient PAS par ce verrou — un Fdc qui
// s'ouvre quelques ms pendant le freinage laissait le §5bis relâcher SA coupure directe sans que
// rien ne prenne le relais, la rampe (encore haute en interne) revenait en sortie -> ré-accélération.
// Désormais toute activation, même un instant, arme DirectionAtArrival comme un TargetReached.
ArrivalEdge(CLK := TargetReached
                 OR (LimitSwitchFwd AND (CommandedDirection = 1))
                 OR (LimitSwitchRev AND (CommandedDirection = -1)));
IF ArrivalEdge.Q THEN
    DirectionAtArrival := CommandedDirection;
END_IF;

// 🔧 REX 2026-08-06 (revue) : un retour au neutre, même SOUTENU (>100ms), ne doit JAMAIS lever
// le verrou — seul un vrai changement de sens (dégagement volontaire, sans ambiguïté) le fait.
// Sinon : neutre 100ms+ puis réappui dans le MÊME sens (le capteur/Fdc étant resté au niveau
// haut en continu, TargetReached ne montre plus de front) contournait le verrou et M3 repartait
// vers la butée. Conforme à la demande d'origine : "on doit repartir dans l'AUTRE sens", jamais
// juste relâcher-réappuyer pareil. Instantané, jamais retardé (le dégagement doit rester rapide).
IF (Direction = DirectionAtArrival * (-1)) OR ResetEdge.Q OR (NOT TargetReached AND NOT LimitSwitchFwd AND NOT LimitSwitchRev) THEN
    DirectionAtArrival := 0;
END_IF;

// Bloque la consigne à 0 tant que l'ordre demande d'insister dans le sens d'arrivée verrouillé
ArrivalLock := (DirectionAtArrival <> 0) AND (Direction = DirectionAtArrival);
IF ArrivalLock THEN
    RampTargetPct := 0.0;
END_IF;

SpeedRamp(Target := RampTargetPct,
          AccelRate := CfgRampAccelRate,
          DecelRate := SEL(SafeStop, CfgRampDecelNormalRate, CfgRampDecelFastRate),
          CycleTimeS := CycleTimeCalc.CycleTimeS);

// 🔒 5. INTERLOCK CHANGEMENT DE SENS — jamais Fwd+Rev simultanés (vitesse confirmée nulle)
IF Direction <> CommandedDirection THEN
    IF CommandedDirection = 0 AND Direction <> 0 THEN
        CommandedDirection := Direction;
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    ELSIF ABS(SpeedRamp.Current) < 0.1 THEN
        DirectionChangeDelay(IN := TRUE, PT := DirectionInterlockDelay);
        IF DirectionChangeDelay.Q THEN
            CommandedDirection := Direction;
            DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
        END_IF;
    ELSE
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    END_IF;
ELSE
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
END_IF;

// 🛑 Pilotage du frein : le mouvement est considéré actif tant que la consigne est supérieure à 0.1%
// OU que la fréquence réelle mesurée du variateur M3 est >= 1.0 Hz.
// Le frein de parking ne serre QUE lorsque la fréquence réelle variateur chute sous 1.0 Hz !
// 🆕 2026-08-06 (revue sécurité) : borné par un garde-fou 2s — DriveActualFreqHz n'a aucun
// contrôle de fraîcheur EtherCAT ; si la comm se fige sur une valeur ≥1.0 Hz (perte réseau en
// mouvement), rien d'autre en aval ne referme le frein (FB_TranslationOutputInterlock_LD ignore
// volontairement SafeStop par conception). Le garde-fou force la fermeture du frein 2s après la
// fin de la rampe THÉORIQUE, quoi que dise la mesure réelle — combine attente réelle (évite un
// serrage sur arbre encore tournant) et certitude de fermeture (n'attend jamais indéfiniment).
TonBrakeRealFreqTimeout(IN := NOT ((CommandedDirection <> 0) AND (ABS(SpeedRamp.Current) > 0.1)), PT := T#2s);
MovementRequested := ((CommandedDirection <> 0) AND (ABS(SpeedRamp.Current) > 0.1))
                     OR (ABS(DriveActualFreqHz) >= 1.0 AND NOT TonBrakeRealFreqTimeout.Q);

// 🔀 5bis. SORTIE PHYSIQUE (ETHERCAT)
RequestedDriveFreqHz := (ABS(SpeedRamp.Current) / 100.0) * DriveFreqScaleMaxHz;

// 🆕 2026-08-06 : compensation câblage moteur appliquée ICI SEULEMENT, sur le mot de commande —
// CommandedDirection (sécurité/capteurs juste au-dessus, §4/§4bis/§4ter) reste le sens réel.
PhysicalDriveDirection := SEL(InvertDriveDirection, CommandedDirection, CommandedDirection * (-1));

// Pilotage nominal Given Command 1 (0x3101) :
// 0: None, 1: Forward, 2: Reverse, 7: Reset
IF Reset THEN
    RequestedDriveControlWord := 7; // Reset défaut variateur
ELSIF Error THEN
    RequestedDriveControlWord := 0; // Arrêt sur défaut
ELSIF MovementRequested THEN
    IF PhysicalDriveDirection = 1 THEN
        RequestedDriveControlWord := 1; // Marche avant
    ELSIF PhysicalDriveDirection = -1 THEN
        RequestedDriveControlWord := 2; // Marche arrière
    ELSE
        RequestedDriveControlWord := 0;
    END_IF;
ELSE
    RequestedDriveControlWord := 0;
END_IF;

// Sécurité : si Fdc extrême atteint dans le sens de marche, coupure commande immédiate (sans rampe ni couple)
// 🌐 BypassLimitSwitch = TRUE → ignore cette protection (test/mise en service)
IF NOT BypassLimitSwitch AND ((CommandedDirection = 1 AND LimitSwitchFwd) OR (CommandedDirection = -1 AND LimitSwitchRev)) THEN
    RequestedDriveControlWord := 0;
    RequestedDriveFreqHz := 0.0;
    SpeedRamp(Target := 0.0, AccelRate := 0.0, DecelRate := 100000.0, CycleTimeS := 1.0);
END_IF;

// 🛑 6. FREIN (composé, réutilisé tel quel)
Brake(Enable := TRUE, Reset := Reset, MovementRequested := MovementRequested,
      ContactorFeedback := BrakeFeedback,
      DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
      DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout,
      BypassContactorCheck := BypassContactorCheck);
BrakeReleaseRequest := Brake.BrakeCmd;
BrakeCommandOpenConfirmed := Brake.BrakeCommandOpenConfirmed;
BrakeContactorCheck := Brake.ContactorCheck;

// 🛡️ FB_Translation ne décide plus la frontière finale : il expose uniquement
// ses demandes métier. SafeStop est déjà appliqué dans la rampe rapide §4 : tant que
// la vitesse ne vaut pas zéro, la demande et le desserrage suivent la décélération.
// FB_TranslationOutputInterlock_LD ne doit jamais transformer SafeStop en coupure sèche.

// 🧾 7. ERRORID (bitfield, cumul)
IF Brake.Error THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// Défaut variateur (bit3) : lu via EtherCAT (DriveStatusWord.4)
IF DriveStatusWord.4 THEN
    ErrorId := ErrorId OR 16#0008;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFF7;
END_IF;

// 🚧 Défaut fin de course extrême (bit6) — si bypassé, on NETTOIE le bit résiduel
IF BypassLimitSwitch THEN
    ErrorId := ErrorId AND 16#FFBF;   // Nettoie le bit 6 (évite résidu d'avant activation)
ELSE
    // Activé UNIQUEMENT en cas de tentative d'avancer DANS la butée active (libéré si dégagement en sens inverse)
    IF (CommandedDirection = 1 AND LimitSwitchFwd) OR (CommandedDirection = -1 AND LimitSwitchRev) THEN
        ErrorId := ErrorId OR 16#0040;
    ELSE
        ErrorId := ErrorId AND 16#FFBF;
    END_IF;
END_IF;

Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// 🚦 8. STATE MACHINE (phase)
IF (NOT StartStop OR SafeStop) AND ABS(SpeedRamp.Current) > 0.1 THEN
    State := E_State.STOPPING;
ELSIF ABS(SpeedRamp.Current) > 0.1 THEN
    State := E_State.BUSY;
ELSE
    State := E_State.READY;
END_IF;

Busy := (State = E_State.BUSY) OR (State = E_State.STOPPING);
Done := FALSE;

// 🛡️ 9. SORTIE SÛRE SUR DÉFAUT
IF Error THEN
    RequestedDriveControlWord := 0; RequestedDriveFreqHz := 0.0;
    BrakeReleaseRequest := FALSE;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   🧪 FB_Sim_Encoder — Simulation physique d'un codeur absolu de treuil
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-13_Fonction_Simulation_v2.0.md
   🧩 Brique réduite (Partie3 §1bis, "briques E/S & diagnostics") : pas de contrat
      Enable/Reset/Error complet, pas de StartStop/SafeStop — outil de banc, pas
      du métier machine.
   🎯 Rôle : fait "compter" un codeur absolu comme si le treuil tournait
      réellement, à partir des relais de sens commandés et de la vitesse rampée
      courante. Extraction PURE de la logique déjà en place dans
      `PRG_02_Encoders.st` (bloc "SIMULATION SUR BANC DE TEST") — aucun
      changement de comportement, juste la dissociation en FB dédié.
   📥 Enable      : simulation active (SimulationModeActive AND NOT BusEncoderMxIsReal)
   📥 RelayFwd/RelayRev : sens commandé (contacteurs de sens du treuil)
   📥 SpeedRefPct : vitesse rampée courante (magnitude, %) — ex. instWinchM1.SpeedRamp.Current
   📥 PresetCmd   : TRUE le cycle où un preset (homing) doit être appliqué (PresettTrigCmd = 2)
   📥 PresetValue : valeur brute à charger lors du preset
   📥 SpeedScaleFactor : 🔧 REX 2026-07-07 — multiplicateur de vitesse simulation (confort de test
      banc uniquement, sans rapport avec une calibration réelle). Défaut 1.0 = comportement
      d'origine. Câblé sur GVL_Simulation.TstEncoderSpeedFactor (réglable à chaud, sans recompiler).
   📤 RawPosOut   : position brute simulée (UDINT), à aiguiller à la place de la valeur
      EtherCAT réelle quand le device n'est pas Operational (voir PRG_02_Encoders.st)
   🔧 REX 2026-07-08 : `RawPos` déplacé en `VAR_IN_OUT`, référencé depuis `GVL_PERSISTENT`
      (même pattern que `Calib` dans `FB_Encoder_Homing`) — `PERSISTENT` n'est valide que sur du
      `VAR_GLOBAL` en CODESYS, pas sur une variable locale de FB (tenté en `VAR RETAIN` puis
      `VAR PERSISTENT RETAIN` locaux, aucun des deux ne convient). Un vrai codeur absolu physique
      conserve son comptage brut même à travers un reset FROID (indépendant de l'automate) —
      il fallait donc bien du PERSISTENT RETAIN réel, regroupé avec le reste dans GVL_PERSISTENT.
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Sim_Encoder) ===

FUNCTION_BLOCK PUBLIC FB_Sim_Encoder
VAR_INPUT
    Enable           : BOOL;
    RelayFwd         : BOOL;
    RelayRev         : BOOL;
    SpeedRefPct      : REAL;
    PresetCmd        : BOOL;
    PresetValue      : UDINT;
    SpeedScaleFactor : REAL := 1.0;   // 🔧 REX 2026-07-07 — confort de test, voir bandeau ci-dessus
    TestOffsetCmd    : BOOL;          // 🆕 REX 2026-07-08 (4) — front montant = applique TestOffsetPts (test banc)
    TestOffsetPts    : DINT := 0;     // 🆕 REX 2026-07-08 (4) — décalage signé à appliquer (points bruts)
END_VAR
VAR_OUTPUT
    RawPosOut   : UDINT;
END_VAR
VAR_IN_OUT
    RawPos      : UDINT;   // 🔧 REX 2026-07-08 : référence _SimEncoderRawPosM1/M2 (survit au reset froid)
END_VAR
VAR
    Increment      : UDINT;              // 🔧 REX 2026-07-07 — évite de dupliquer le calcul 2x
    TestOffsetEdge : R_TRIG;             // 🆕 REX 2026-07-08 (4)
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Encoder) ===

IF NOT Enable THEN
    RawPosOut := RawPos;
    RETURN;
END_IF;

// 🆕 REX 2026-07-08 (4) — injection test banc : VRAI saut de position (comme un glissement réel),
// pour tester Concept 1 / Méca E ET le rattrapage joystick (voir GVL_Simulation bandeau).
TestOffsetEdge(CLK := TestOffsetCmd);
IF TestOffsetEdge.Q THEN
    RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) + TestOffsetPts);
END_IF;

Increment := REAL_TO_UDINT(SpeedRefPct * 0.1 * SpeedScaleFactor);

IF PresetCmd THEN
    RawPos := PresetValue;
ELSIF RelayFwd THEN
    RawPos := RawPos + Increment;
ELSIF RelayRev THEN
    IF RawPos >= Increment THEN
        RawPos := RawPos - Increment;
    ELSE
        RawPos := 0;
    END_IF;
END_IF;

RawPosOut := RawPos;

(* ═══════════════════════════════════════════════════════════════
   💾 GVL_BypassRetain — Variables RETAIN pour les bypass de mise en service
   ───────────────────────────────────────────────────────────────
   🔒 Survit au Warm Restart (CPU Stop/Start) mais PAS au Download.
   🎯 Utilisé uniquement lors de la mise en service / débogage.
   ═══════════════════════════════════════════════════════════════ *)
VAR_GLOBAL RETAIN

    // 🌐 Bypass Global Translation M3 (FB_Safety_Translation + FB_Translation)
    BypassTranslationGlobal     : BOOL := FALSE;
    // 🌐 Bypass Global Treuil M1 (FB_Safety_Winch + FB_Winch)
    BypassWinchM1Global         : BOOL := FALSE;
    // 🌐 Bypass Global Treuil M2 (FB_Safety_Winch + FB_Winch)
    BypassWinchM2Global         : BOOL := FALSE;
    // 🌐 Bypass Global Synchro M1/M2 (FB_WinchSync)
    BypassSyncGlobal            : BOOL := FALSE;
    // 🌐 Bypass Global Réseau CAN/EtherCAT (force Online)
    BypassNetworkGlobal         : BOOL := FALSE;
    // 🌐 Bypass Global Benne (FB_Bucket)
    BypassBucketGlobal          : BOOL := FALSE;

END_VAR

(* 🛡️ Raisons mémorisées de la barrière finale frein/puissance treuil. *)
{attribute 'qualified_only'}
TYPE E_WinchFinalInterlockReason :
(
    NONE := 0,
    BRAKE_COMMAND_NOT_CONFIRMED := 1,
    RESTART_INHIBITED := 2
);
END_TYPE

(* =======================================================================
   🔒 FB_Safety_EmergencyManagementOutput — Projection Physique Fail-Safe
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Enable gate + copie consignes logiques vers sorties physiques
   🔒 Polarité : MaintainA/B_RQ en maintien (TRUE = voie saine)
   🔌 Architecture : Projection physique fail-safe
   📄 Doc métier : DOC/AF/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_Safety_EmergencyManagementOutput
VAR_INPUT
    // === CONSIGNES & COMMANDES LOGIQUES ===
    Enable                  : BOOL; // --> [CMD]  Active le pilote (FALSE = toutes sorties a FALSE)
    Cmd                     : ST_Safety_Emergency_InternalCmd; // --> [CMD] Ordres logiques recus du bloc logique

    // === RETOURS D'ETAT & DIAGNOSTICS (MIROIRS) ===
    ChainOk                 : BOOL; // --> [HW]   Miroir EmergencyChainClosed (pour bus State)
    ContactorOk             : BOOL; // --> [HW]   Miroir PowerContactorEngaged (pour bus State)
    ArmingStep              : INT;  // --> [STAT] Miroir ArmingSeqStep (pour bus State)
    Armable                 : BOOL; // --> [STAT] Calcule par Logic (pour bus State)
    ArmingBusy              : BOOL; // --> [STAT] Calcule par Logic (pour bus State)
    Error                   : BOOL; // --> [DIAG] Miroir Error (pour bus Diag)
    ErrorId                 : WORD; // --> [DIAG] Miroir ErrorId (pour bus Diag)
    RedundancyTestFailed    : BOOL; // --> [DIAG] Miroir RedundancyTestFailed (pour bus Diag)
    ArmFailed               : BOOL; // --> [DIAG] Miroir ArmFailed (pour bus Diag)
    LockoutActive           : BOOL; // --> [DIAG] Miroir LockoutActive (pour bus Diag)
END_VAR
VAR_OUTPUT
    // === SORTIES PHYSIQUES TERMINALES ===
    MaintainA_RQ            : BOOL; // <-- [ACT]  Vers relais maintien canal A (TRUE = voie maintenue)
    MaintainB_RQ            : BOOL; // <-- [ACT]  Vers relais maintien canal B (TRUE = voie maintenue)
    ArmPulse_RQ             : BOOL; // <-- [ACT]  Vers contacteur impulsion rearmement (TRUE = pulse actif)

    // === BUS D'ETAT & DIAGNOSTIC PUBLICS ===
    State                   : ST_Safety_Emergency_State; // <-- [STAT] Bus d'etat public
    Diag                    : ST_Safety_Emergency_Diag;  // <-- [DIAG] Bus diagnostic public
END_VAR

// === IMPLEMENTATION ===

{region "§1 Gate"}
IF NOT Enable THEN
    MaintainA_RQ   := FALSE;
    MaintainB_RQ   := FALSE;
    ArmPulse_RQ    := FALSE;

    State.ChainOk        := FALSE;
    State.ContactorOk    := FALSE;
    State.Step           := 0;
    State.Armable        := FALSE;
    State.ArmingBusy     := FALSE;

    Diag.Error                := FALSE;
    Diag.ErrorId              := 16#0000;
    Diag.RedundancyTestFailed := FALSE;
    Diag.ArmFailed            := FALSE;
    Diag.LockoutActive        := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Projection sorties et bus"}
// ⚡ Sorties physiques — écriture directe des ordres logiques
MaintainA_RQ := Cmd.MaintainA_Cmd;
MaintainB_RQ := Cmd.MaintainB_Cmd;
ArmPulse_RQ  := Cmd.ArmPulse_Cmd;

// 🚦 Bus d'état public
State.ChainOk        := ChainOk;
State.ContactorOk    := ContactorOk;
State.Step           := ArmingStep;
State.Armable        := Armable;
State.ArmingBusy     := ArmingBusy;

// 🛡️ Bus diagnostic public
Diag.Error                := Error;
Diag.ErrorId              := ErrorId;
Diag.RedundancyTestFailed := RedundancyTestFailed;
Diag.ArmFailed            := ArmFailed;
Diag.LockoutActive        := LockoutActive;
{endregion}

(* =======================================================================
   ⚙️ FB_Encoder_SpeedMeasure — Mesure de vitesse câble horodatée
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Calcul de la vitesse absolue et signée sur fenêtre glissante horodatée
   🔒 Polarité : Valid=TRUE après 6 échantillons couvrant au moins 50ms
   📄 Doc métier : DOC/AF/AF_Partie-09_Fonction_Encoder_v2.1.md
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_Encoder_SpeedMeasure
VAR_INPUT
    // === COMMANDES & AUTORISATIONS ===
    Enable              : BOOL;        // --> [CMD] Autorisation generale FB (TRUE=Autorise)
    Reset               : BOOL;        // --> [CMD] Purge immediate de l'historique (front montant)

    // === MESURE SURES EN ENTREE ===
    Position_M          : REAL;        // --> [HW]  Position cable sure en metres (FB_Encoder_Safety)
    PositionValid       : BOOL;        // --> [SAFE] Validite de la chaine codeur
END_VAR
VAR_OUTPUT
    // === VITESSE CALCULÉE & VALIDITE ===
    Speed_Mps           : REAL;        // <-- [DIAG] Vitesse absolue sur la fenetre glissante (m/s)
    SignedSpeed_Mps     : REAL;        // <-- [DIAG] Vitesse signee (+ montee, - descente) (m/s)
    Valid               : BOOL;        // <-- [STAT] Vitesse valide (6 ech. sur 50 ms)
END_VAR
VAR
    // === HISTORIQUE & ECHANTILLONS ===
    Positions_M         : ARRAY[0..5] OF REAL; // . [LOC] Tableau des 6 positions enregistrees
    Timestamps          : ARRAY[0..5] OF TIME; // . [LOC] Horodatage associe aux 6 positions

    // === HORODATAGE & TEMPORISATION ===
    CurrentTimestamp    : TIME;        // . [LOC] Horodatage courant du cycle
    LastTimestamp       : TIME;        // . [LOC] Horodatage de l'echantillon precedent
    ElapsedSinceSample  : TIME;        // . [LOC] Temps ecoule depuis le dernier echantillon
    WindowElapsed       : TIME;        // . [LOC] Temps total ecoule sur la fenetre de mesure

    // === COMPTEURS & ETATS INTERNES ===
    CollectedSamples    : INT;         // . [LOC] Nombre d'echantillons collectes dans la fenetre
    Index               : INT;         // . [LOC] Index de boucle de decalage
    TimestampInitialized: BOOL;        // . [LOC] Indicateur d'initialisation du premier horodatage
END_VAR
VAR CONSTANT
    // === PARAMETRES DE LA FENETRE GLISSANTE ===
    WindowTime          : TIME := T#50MS; // Fenetre glissante de mesure
    SamplePeriod        : TIME := T#10MS; // Periode minimale entre deux echantillons
    SampleCount         : INT := 6;       // Nombre total d'echantillons requis
END_VAR

{region "§1 Horodatage et purge"}
// ⏱️ Horodatage natif : le calcul utilise le temps réellement écoulé, jamais un cycle supposé.
CurrentTimestamp := TIME();

// Purge des six positions sur rupture de confiance : aucune source antérieure ne peut contaminer la mesure.
IF NOT Enable OR Reset OR NOT PositionValid THEN
    Speed_Mps := 0.0;
    SignedSpeed_Mps := 0.0;
    Valid := FALSE;
    CollectedSamples := 0;
    TimestampInitialized := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Première position"}
// 🕒 Première position de la nouvelle fenêtre.
IF NOT TimestampInitialized THEN
    Positions_M[0] := Position_M;
    Timestamps[0] := CurrentTimestamp;
    LastTimestamp := CurrentTimestamp;
    CollectedSamples := 1;
    TimestampInitialized := TRUE;
    Speed_Mps := 0.0;
    SignedSpeed_Mps := 0.0;
    Valid := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§3 Rebouclage TIME"}
// 🛡️ Rebouclage de TIME détecté localement : purge sans réutiliser le delta aberrant.
IF CurrentTimestamp < LastTimestamp THEN
    Positions_M[0] := Position_M;
    Timestamps[0] := CurrentTimestamp;
    LastTimestamp := CurrentTimestamp;
    CollectedSamples := 1;
    Speed_Mps := 0.0;
    SignedSpeed_Mps := 0.0;
    Valid := FALSE;
    RETURN;
END_IF;

ElapsedSinceSample := CurrentTimestamp - LastTimestamp;

// 🛡️ Delta nul : aucune division et aucun doublon d'échantillon.
IF ElapsedSinceSample <= T#0MS THEN
    RETURN;
END_IF;
{endregion}

{region "§4 Collecte échantillons"}
// 📥 Six positions espacées d'au moins 10 ms donnent cinq intervalles sur la fenêtre interne de 50 ms.
IF ElapsedSinceSample >= SamplePeriod THEN
    LastTimestamp := CurrentTimestamp;

    IF CollectedSamples < SampleCount THEN
        Positions_M[CollectedSamples] := Position_M;
        Timestamps[CollectedSamples] := CurrentTimestamp;
        CollectedSamples := CollectedSamples + 1;
    ELSE
        FOR Index := 0 TO 4 DO
            Positions_M[Index] := Positions_M[Index + 1];
            Timestamps[Index] := Timestamps[Index + 1];
        END_FOR;
        Positions_M[5] := Position_M;
        Timestamps[5] := CurrentTimestamp;
    END_IF;
{endregion}

{region "§5 Calcul vitesse"}
    IF CollectedSamples = SampleCount THEN
        // 🛡️ Ordre temporel et durée minimale contrôlés avant toute conversion/division.
        IF Timestamps[5] >= Timestamps[0] THEN
            WindowElapsed := Timestamps[5] - Timestamps[0];
            IF WindowElapsed >= WindowTime THEN
                SignedSpeed_Mps := (Positions_M[5] - Positions_M[0])
                                   / (UDINT_TO_REAL(TIME_TO_UDINT(WindowElapsed)) / 1000.0);
                Speed_Mps := ABS(SignedSpeed_Mps);
                Valid := TRUE;
            ELSE
                Speed_Mps := 0.0;
                SignedSpeed_Mps := 0.0;
                Valid := FALSE;
            END_IF;
        ELSE
            Speed_Mps := 0.0;
            SignedSpeed_Mps := 0.0;
            Valid := FALSE;
            CollectedSamples := 0;
            TimestampInitialized := FALSE;
        END_IF;
    END_IF;
END_IF;
{endregion}

