TEST 'TC-P01-007 timeout confirmation contacteur -> lockout 5s'
    (* meme montee en sequence que TC-P01-003 : les 2 canaux valides, jusqu au pulse *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := FALSE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := FALSE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 5, 'les 2 canaux valides -> pulse');

    (* 1s plus tard : pulse termine -> Confirm (step 6), contacteur PAS engage *)
    ADVANCE_TIME(1000000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 6, 'attente confirmation contacteur');

    (* 2s plus tard (timeout confirmation) : contacteur toujours pas confirme -> echec + lockout *)
    ADVANCE_TIME(2000000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'timeout confirmation doit ramener la sequence a IDLE');
    ASSERT_TRUE(fb.EMERGENCYARMINGLOCKOUTACTIVE, 'timeout doit declencher le lockout (TC-P01-007)');
    ASSERT_TRUE(fb.EMERGENCYARMINGFAILED, 'timeout doit lever le defaut EmergencyArmingFailed');
    ASSERT_TRUE(fb.ERROR, 'defaut doit etre visible sur Error');

    (* pendant le lockout : un nouveau front ArmRequest doit etre bloque *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'lockout actif doit bloquer toute nouvelle tentative de reamement');

    (* 5s apres le debut du lockout : le verrouillage doit se lever automatiquement *)
    ADVANCE_TIME(5000000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_FALSE(fb.EMERGENCYARMINGLOCKOUTACTIVE, 'lockout 5s ecoule -> leve automatiquement');

    (* preuve OPERATIONNELLE (pas juste le drapeau) : un nouveau front doit maintenant relancer
       reellement la sequence -- +1 cycle pour que le retrait du lockout soit visible au scan
       suivant avant de tenter le nouveau front (ordre de calcul : trigger avant re-evaluation
       du lockout dans le meme scan, cf. Logic.st) *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'apres le lockout, un nouveau front doit reellement relancer TestA (pas juste le drapeau qui retombe)');
END_TEST

TEST 'TC-P01-010 BtnEmergencyCutOff pendant le pulse de reamement (step 5) doit couper le pulse comme le maintien'
    (* Meme montee en sequence que TC-P01-003 jusqu au pulse (step 5) *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := FALSE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := FALSE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 5, 'les 2 canaux valides -> pulse (step 5)');
    ASSERT_TRUE(fb.ARMPULSE_RQ, 'precondition : pulse actif');

    (* Operateur appuie sur la coupure d urgence IHM PENDANT l impulsion mecanique de reamement *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := TRUE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'BtnEmergencyCutOff coupe bien le maintien canal A (comportement attendu, deja correct)');
    ASSERT_FALSE(fb.MAINTAINB_RQ, 'BtnEmergencyCutOff coupe bien le maintien canal B (comportement attendu, deja correct)');
    (* Coherence attendue : si la coupure d urgence IHM coupe le maintien de puissance, elle doit
       aussi couper l impulsion mecanique de reamement en cours -- continuer a pulser le contacteur
       de reamement pendant qu on demande sa coupure est incoherent (Cmd.ArmPulse_Cmd n est
       conditionne par aucune des memes gardes que Cmd.MaintainA/B_Cmd dans
       FB_Safety_EmergencyManagementLogic.st §7 -- ecart releve par l audit du 2026-08-22). *)
    ASSERT_FALSE(fb.ARMPULSE_RQ, 'BtnEmergencyCutOff doit aussi couper le pulse de reamement en cours (coherence avec la coupure du maintien)');
END_TEST

TEST 'TC-P01-008 PowerCutOffRequest coupe A et B sans armer'
    (* scan 1 : autotest demarrage (1 cycle, boucle saine, contacteur repos) *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);

    (* scan 2 : regime etabli, maintien sain attendu -- +1 cycle automate (10ms) *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'hors defaut, canal A doit etre maintenu');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'hors defaut, canal B doit etre maintenu');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'pas de sequence en cours');

    (* scan 3 : coupure demandee par un metier (Winch/Translation) -- +1 cycle automate *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := TRUE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'PowerCutOffRequest doit couper le canal A');
    ASSERT_FALSE(fb.MAINTAINB_RQ, 'PowerCutOffRequest doit couper le canal B');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'PowerCutOffRequest ne doit jamais declencher une sequence armement');
END_TEST

// ═══════════════════════════════════════════════════════════════
// 🧪 FB_TranslationStepExecutor — Exécution étape/check Translation M3
// ───────────────────────────────────────────────────────────────
// 🎯 Responsabilité UNIQUE : faire progresser UNE suite de tests
//    Translation, étape par étape (Dwell → Checks → Timeout/MinPT →
//    verdict → étape suivante), en respectant le cantonnement à un
//    seul cas (CaseId 1..6) ou à l'enchaînement complet (CaseId=0).
//    N'écrit AUCUNE variable GVL, ne construit AUCUNE table (voir
//    FB_TranslationTestPlan) et n'assemble AUCUN rapport (voir
//    FB_TranslationReportFinalizer, qui consomme StepVerdict/Verdict*).
// 🆕 Tranche verticale NEUVE Translation (2026-07-22) — n'instancie NI
//    FB_TestSequencer NI FB_TestCheck/FB_Timeout (anciennes BRICKS) :
//    logique de check réécrite ici, restreinte aux 3 Kind / 2 Mode
//    réellement utilisés par les 6 TC Translation (voir FB_TranslationTestPlan).
// 🔒 Cantonnement de cas (remplace le FirstStepId manipulé par le
//    manager, audit v1.0 C2) : CaseId est résolu en 1er step via
//    CaseTable UNIQUEMENT ici (jamais exposé par FB_TranslationValidation).
//    Toute étape suivante qui change de CaseId alors qu'un cas est
//    ciblé (CaseId<>0) termine proprement le run (NextStepId:=0).
// ═══════════════════════════════════════════════════════════════

FUNCTION_BLOCK PUBLIC FB_TranslationStepExecutor
VAR_INPUT
    Start   : BOOL; // Front : résout CaseId -> 1er step (CaseTable) et démarre
    Abort   : BOOL; // Niveau : arrêt immédiat propre
    CaseId  : INT;  // 0 = toutes les cases (1..6) ; 1..6 = case ciblée uniquement
END_VAR
VAR_IN_OUT
    StepTable  : ARRAY[1..GVL_PLC_Tests_Const.MaxSteps]      OF ST_TestStepConfig;
    CheckTable : ARRAY[1..GVL_PLC_Tests_Const.MaxChecks]     OF ST_TestCheckConfig;
    CaseTable  : ARRAY[1..GVL_PLC_Tests_Const.MaxTestCases]  OF ST_TestCaseConfig;
    ProbeBool  : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeBool]  OF BOOL;
    ProbeDint  : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeDint]  OF DINT;
    ProbeReal  : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeReal]  OF REAL;
END_VAR
VAR_OUTPUT
    Busy                : BOOL;
    RunDone              : BOOL;  // Fin de run (niveau, tenu jusqu'au prochain Start)
    AnyFailed            : BOOL;
    ConfigError          : BOOL;  // 🛡️ Garde-fou runtime (Plan valide déjà statiquement)
    ConfigErrorStepId    : INT;
    CurrentStepId        : INT;
    CurrentCaseId        : INT;
    ActiveStimulusId     : INT;   // 0 GARANTI sur tout chemin terminal (Done/Abort/ConfigError)
    StepElapsed          : TIME;
    TerminalState        : E_TestTerminalState;
    // 🧾 Verdict d'étape — pulse 1 scan, consommé par FB_TranslationReportFinalizer
    StepVerdict          : BOOL;
    VerdictStepId        : INT;
    VerdictCaseId        : INT;
    VerdictPassed         : BOOL;
    VerdictFailReason     : E_TestFailReason;
    VerdictFailedCheckIdx : INT;
    VerdictDuration       : TIME;
    VerdictObservedBool   : BOOL;
    VerdictObservedDint   : DINT;
    VerdictObservedReal   : REAL;
END_VAR
VAR
    StartTrig       : R_TRIG;
    StepStarted     : BOOL;
    DwellTimer      : TON;
    StepTimer       : TON;
    StableTimers    : ARRAY[1..GVL_PLC_Tests_Const.MaxChecksPerStep] OF TON;
    CheckPassed     : ARRAY[1..GVL_PLC_Tests_Const.MaxChecksPerStep] OF BOOL;
    CheckFailed     : ARRAY[1..GVL_PLC_Tests_Const.MaxChecksPerStep] OF BOOL;
    InstantEvaluated: ARRAY[1..GVL_PLC_Tests_Const.MaxChecksPerStep] OF BOOL;
    ObsBoolArr      : ARRAY[1..GVL_PLC_Tests_Const.MaxChecksPerStep] OF BOOL;
    ObsDintArr      : ARRAY[1..GVL_PLC_Tests_Const.MaxChecksPerStep] OF DINT;
    ObsRealArr      : ARRAY[1..GVL_PLC_Tests_Const.MaxChecksPerStep] OF REAL;

    Jdx, Kdx        : INT;
    ProbeIdx        : INT;
    Cond            : BOOL;
    AllChecksLatched: BOOL;
    AnyCheckFailedLocal : BOOL;
    FailedCheckIdxLocal : INT;
    FailedCheckSlotLocal : INT; // Slot RÉEL (Jdx, 1..MaxChecksPerStep) du check fautif

    // Verdict de l'étape (émis au plus une fois par scan)
    VerdictReached      : BOOL;
    VerdictPassedLocal   : BOOL;
    VerdictReasonLocal   : E_TestFailReason;
    VerdictCheckIdxLocal : INT;
    VerdictObsBoolLocal  : BOOL;
    VerdictObsDintLocal  : DINT;
    VerdictObsRealLocal  : REAL;

    NextCandidate    : INT;
    TransitionCount  : INT; // Garde anti-cycle runtime, bornée par MaxSteps
END_VAR
// === IMPLEMENTATION ===
StartTrig(CLK := Start);
StepVerdict := FALSE;

// 1. 🛑 Abort — niveau, priorité absolue
IF Abort THEN
    IF Busy THEN
        StepVerdict := TRUE;
        VerdictStepId := CurrentStepId;
        VerdictCaseId := CurrentCaseId;
        VerdictPassed := FALSE;
        VerdictFailReason := E_TestFailReason.FAIL_ABORTED;
        VerdictFailedCheckIdx := 0;
        VerdictDuration := StepElapsed;
        VerdictObservedBool := FALSE;
        VerdictObservedDint := 0;
        VerdictObservedReal := 0.0;
        AnyFailed := TRUE;
        TerminalState := E_TestTerminalState.TEST_TERMINAL_ABORTED;
    END_IF;
    Busy := FALSE;
    RunDone := TRUE;
    ActiveStimulusId := 0;
    CurrentStepId := 0;
    StepStarted := FALSE;
    RETURN;
END_IF;

// 2. 🟢 Démarrage — résolution CaseId -> 1er step, JAMAIS de FirstStepId externe
IF StartTrig.Q THEN
    ConfigError := FALSE;
    ConfigErrorStepId := 0;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;

    IF CaseId < 0 OR CaseId > 6 THEN
        ConfigError := TRUE;
        ConfigErrorStepId := CaseId;
        Busy := FALSE;
        RunDone := TRUE;
        AnyFailed := TRUE;
        ActiveStimulusId := 0;
        CurrentStepId := 0;
        TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        RETURN;
    END_IF;

    IF CaseId = 0 THEN
        CurrentStepId := CaseTable[1].FirstStep;
    ELSE
        CurrentStepId := CaseTable[CaseId].FirstStep;
    END_IF;

    IF CurrentStepId < 1 OR CurrentStepId > GVL_PLC_Tests_Const.MaxSteps THEN
        ConfigError := TRUE;
        ConfigErrorStepId := CurrentStepId;
        Busy := FALSE;
        RunDone := TRUE;
        AnyFailed := TRUE;
        ActiveStimulusId := 0;
        CurrentStepId := 0;
        TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        RETURN;
    END_IF;

    Busy := TRUE;
    RunDone := FALSE;
    AnyFailed := FALSE;
    StepStarted := FALSE;
    TransitionCount := 0;
END_IF;

IF NOT Busy THEN
    RETURN;
END_IF;

// 3. 🛡️ Garde-fou runtime (défense en profondeur — Plan valide déjà statiquement)
IF CurrentStepId < 1 OR CurrentStepId > GVL_PLC_Tests_Const.MaxSteps THEN
    Busy := FALSE;
    RunDone := TRUE;
    AnyFailed := TRUE;
    ActiveStimulusId := 0;
    ConfigError := TRUE;
    ConfigErrorStepId := CurrentStepId;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
    RETURN;
END_IF;

CurrentCaseId := StepTable[CurrentStepId].CaseId;
ActiveStimulusId := StepTable[CurrentStepId].StimulusId;

IF NOT StepStarted THEN
    StepStarted := TRUE;
    StepElapsed := T#0s;
    DwellTimer(IN := FALSE);
    StepTimer(IN := FALSE);
    FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
        CheckPassed[Jdx] := FALSE;
        CheckFailed[Jdx] := FALSE;
        InstantEvaluated[Jdx] := FALSE;
        StableTimers[Jdx](IN := FALSE);
    END_FOR;
END_IF;

StepElapsed := StepElapsed + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));

// 4. 🕐 Dwell (tempo fixe avant évaluation — T#0s = aucune, cas actuel Translation)
DwellTimer(IN := TRUE, PT := StepTable[CurrentStepId].DwellPT);
IF NOT DwellTimer.Q THEN
    RETURN;
END_IF;

// 5. ✅ Évaluation des checks — verrouillage "latch and hold" par check
//    (un check WAIT_UNTIL passé le reste jusqu'à la fin de l'étape, même si
//    la sonde redevient momentanément fausse — sémantique identique à
//    l'ancien FB_TestCheck, réécrite ici sans l'instancier)
FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
    Kdx := StepTable[CurrentStepId].CheckIdx[Jdx];
    // 🔒 CODESYS n'assure pas le court-circuit : valider AVANT tout accès.
    IF Kdx < 0 OR Kdx > GVL_PLC_Tests_Const.MaxChecks THEN
        Busy := FALSE;
        RunDone := TRUE;
        AnyFailed := TRUE;
        ActiveStimulusId := 0;
        ConfigError := TRUE;
        ConfigErrorStepId := CurrentStepId;
        TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        RETURN;
    END_IF;
    IF Kdx > 0 THEN
        Cond := FALSE;
        ProbeIdx := CheckTable[Kdx].ProbeIdx;
        CASE CheckTable[Kdx].Kind OF
            E_TestCheckKind.BOOL_EQUAL:
                IF ProbeIdx >= 1 THEN
                    IF ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeBool THEN
                        ObsBoolArr[Jdx] := ProbeBool[ProbeIdx];
                        Cond := (ObsBoolArr[Jdx] = CheckTable[Kdx].ExpectedBool);
                    END_IF;
                END_IF;
            E_TestCheckKind.WORD_MASK_NONE:
                IF ProbeIdx >= 1 THEN
                    IF ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeDint THEN
                        ObsDintArr[Jdx] := ProbeDint[ProbeIdx];
                        Cond := ((DINT_TO_WORD(ObsDintArr[Jdx]) AND CheckTable[Kdx].Mask) = 0);
                    END_IF;
                END_IF;
            E_TestCheckKind.REAL_IN_RANGE:
                IF ProbeIdx >= 1 THEN
                    IF ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeReal THEN
                        ObsRealArr[Jdx] := ProbeReal[ProbeIdx];
                        Cond := (ObsRealArr[Jdx] >= CheckTable[Kdx].RealMin AND ObsRealArr[Jdx] <= CheckTable[Kdx].RealMax);
                    END_IF;
                END_IF;
            // Kind hors périmètre (voir FB_TranslationTestPlan) -> Cond reste FALSE
        END_CASE;

        IF NOT CheckPassed[Jdx] AND NOT CheckFailed[Jdx] THEN
            CASE CheckTable[Kdx].Mode OF
                E_TestCheckMode.CHECK_INSTANT:
                    IF NOT InstantEvaluated[Jdx] THEN
                        InstantEvaluated[Jdx] := TRUE;
                        IF Cond THEN
                            CheckPassed[Jdx] := TRUE;
                        ELSE
                            CheckFailed[Jdx] := TRUE;
                        END_IF;
                    END_IF;
                E_TestCheckMode.CHECK_WAIT_UNTIL:
                    StableTimers[Jdx](IN := Cond, PT := CheckTable[Kdx].StablePT);
                    IF StableTimers[Jdx].Q THEN
                        CheckPassed[Jdx] := TRUE;
                    END_IF;
            END_CASE;
        END_IF;
    END_IF;
END_FOR;

// 6. 🧾 Agrégat des checks de l'étape
AllChecksLatched := TRUE;
AnyCheckFailedLocal := FALSE;
FailedCheckIdxLocal := 0;
FailedCheckSlotLocal := 0;
FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
    Kdx := StepTable[CurrentStepId].CheckIdx[Jdx];
    IF Kdx > 0 THEN
        IF CheckFailed[Jdx] AND NOT AnyCheckFailedLocal THEN
            AnyCheckFailedLocal := TRUE;
            FailedCheckIdxLocal := Kdx;
            FailedCheckSlotLocal := Jdx; // 🔧 REX : slot RÉEL du check fautif (pas un index figé)
        ELSIF NOT CheckPassed[Jdx] THEN
            AllChecksLatched := FALSE;
        END_IF;
    END_IF;
END_FOR;

// 7. 📸 Verdict
VerdictReached := FALSE;
IF AnyCheckFailedLocal THEN
    VerdictReached := TRUE;
    VerdictPassedLocal := FALSE;
    VerdictReasonLocal := E_TestFailReason.FAIL_CHECK;
    VerdictCheckIdxLocal := FailedCheckIdxLocal;
    // 🔒 Défense en profondeur avant indexation du snapshot fautif.
    IF FailedCheckSlotLocal >= 1 THEN
        IF FailedCheckSlotLocal <= GVL_PLC_Tests_Const.MaxChecksPerStep THEN
            VerdictObsBoolLocal := ObsBoolArr[FailedCheckSlotLocal];
            VerdictObsDintLocal := ObsDintArr[FailedCheckSlotLocal];
            VerdictObsRealLocal := ObsRealArr[FailedCheckSlotLocal];
        ELSE
            VerdictObsBoolLocal := FALSE;
            VerdictObsDintLocal := 0;
            VerdictObsRealLocal := 0.0;
        END_IF;
    ELSE
        VerdictObsBoolLocal := FALSE;
        VerdictObsDintLocal := 0;
        VerdictObsRealLocal := 0.0;
    END_IF;
ELSE
    StepTimer(IN := TRUE, PT := StepTable[CurrentStepId].TimeoutPT);
    IF AllChecksLatched THEN
        VerdictReached := TRUE;
        IF StepElapsed < StepTable[CurrentStepId].MinPT THEN
            VerdictPassedLocal := FALSE;
            VerdictReasonLocal := E_TestFailReason.FAIL_WINDOW_EARLY;
            VerdictCheckIdxLocal := 0;
        ELSE
            VerdictPassedLocal := TRUE;
            VerdictReasonLocal := E_TestFailReason.FAIL_NONE;
            VerdictCheckIdxLocal := 0;
        END_IF;
        VerdictObsBoolLocal := ObsBoolArr[1];
        VerdictObsDintLocal := ObsDintArr[1];
        VerdictObsRealLocal := ObsRealArr[1];
    ELSIF StepTimer.Q THEN
        VerdictReached := TRUE;
        VerdictPassedLocal := FALSE;
        VerdictReasonLocal := E_TestFailReason.FAIL_TIMEOUT;
        VerdictCheckIdxLocal := 0;
        VerdictObsBoolLocal := FALSE;
        VerdictObsDintLocal := 0;
        VerdictObsRealLocal := 0.0;
    END_IF;
END_IF;

IF NOT VerdictReached THEN
    RETURN; // ⏳ Toujours en attente, rien à publier ce scan
END_IF;

// 8. ➡️ Résolution de l'étape suivante — cantonnement de cas ICI (audit v1.0 C2)
IF VerdictPassedLocal THEN
    NextCandidate := StepTable[CurrentStepId].NextOnPass;
ELSIF StepTable[CurrentStepId].FailAction = E_TestFailAction.FAIL_ABORT_SUITE THEN
    NextCandidate := 0;
ELSE
    NextCandidate := StepTable[CurrentStepId].NextOnFail;
END_IF;

// 🔒 Aucun accès StepTable[0] : CODESYS peut évaluer tous les opérandes de AND.
IF NextCandidate <> 0 THEN
    IF NextCandidate < 1 OR NextCandidate > GVL_PLC_Tests_Const.MaxSteps THEN
        Busy := FALSE;
        RunDone := TRUE;
        AnyFailed := TRUE;
        ActiveStimulusId := 0;
        ConfigError := TRUE;
        ConfigErrorStepId := NextCandidate;
        TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        RETURN;
    END_IF;
    // Un cas ciblé ne déborde jamais sur le cas suivant.
    IF CaseId <> 0 THEN
        IF StepTable[NextCandidate].CaseId <> CaseId THEN
            NextCandidate := 0;
        END_IF;
    END_IF;
END_IF;

// 9. 🧾 Publication du verdict pour FB_TranslationReportFinalizer
StepVerdict := TRUE;
VerdictStepId := CurrentStepId;
VerdictCaseId := CurrentCaseId;
VerdictPassed := VerdictPassedLocal;
VerdictFailReason := VerdictReasonLocal;
VerdictFailedCheckIdx := VerdictCheckIdxLocal;
VerdictDuration := StepElapsed;
VerdictObservedBool := VerdictObsBoolLocal;
VerdictObservedDint := VerdictObsDintLocal;
VerdictObservedReal := VerdictObsRealLocal;

IF NOT VerdictPassedLocal THEN
    AnyFailed := TRUE;
END_IF;

// 10. 🔁 Transition bornée (garde runtime contre tout cycle résiduel)
TransitionCount := TransitionCount + 1;
IF TransitionCount > GVL_PLC_Tests_Const.MaxSteps THEN
    Busy := FALSE;
    RunDone := TRUE;
    AnyFailed := TRUE;
    ActiveStimulusId := 0;
    ConfigError := TRUE;
    ConfigErrorStepId := CurrentStepId;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
    RETURN;
END_IF;
CurrentStepId := NextCandidate;
StepStarted := FALSE;
IF NextCandidate = 0 THEN
    Busy := FALSE;
    RunDone := TRUE;
    ActiveStimulusId := 0; // 🛡️ Garantie structurelle — double garantie avec FB_TranslationTestCleanup
    IF AnyFailed THEN
        TerminalState := E_TestTerminalState.TEST_TERMINAL_FAILED;
    ELSE
        TerminalState := E_TestTerminalState.TEST_TERMINAL_DONE;
    END_IF;
END_IF;

// 🧪 Résultat plat de l'autotest indépendant du framework
TYPE ST_TestFrameworkResult :
STRUCT
    InProgress   : BOOL;
    AllPassed    : BOOL;
    AnyFailed    : BOOL;
    CurrentTestId: INT;
    FailedTestId : INT;
    TestsPassed  : INT;
    TestsFailed  : INT;
    ErrorMessage : STRING(160);
    RunCounter   : UDINT;
END_STRUCT
END_TYPE

(* =======================================================================
   🛡️ FB_TranslationOutputInterlock_LD — Barrière finale frein / AC600 M3
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Barrière de sécurité finale pour frein et variateur AC600 M3
   📄 Doc métier : DOC/AF/AF_Partie-11_Fonction_Translation_v2.2.md
   🔌 Interface : Interlock de sortie (entre FB_Translation et PRG_06_Outputs_LD)
   🔒 Sécurité : Surveillance feedback frein et watchdog de desserrage
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_TranslationOutputInterlock_LD
VAR_INPUT
    // === COMMANDES & ETATS GENERAL ===
    Enable                       : BOOL;   // --> [CMD] Autorisation generale FB (TRUE=Autorise)
    Reset                        : BOOL;   // --> [CMD] Acquittement defaut sur front
    SafeStop                     : BOOL;   // --> [SAFE] Entree securite pour interface standard
    PowerContactorEngaged              : BOOL;   // --> [SAFE] Chaine AU rearmee et puissance OK

    // === DEMANDES DE COMMANDE AMONT ===
    BrakeReleaseRequest          : BOOL;   // --> [CMD] Demande de desserrage frein
    BrakeCommandOpenConfirmed    : BOOL;   // --> [HW] Confirmation ouverture frein (contacteur/bobine)
    RequestedDriveControlWord    : WORD;   // --> [CMD] Mot de commande variateur (0=None, 1=Fwd, 2=Rev, 7=Reset)
    RequestedDriveFreqHz         : REAL;   // --> [CMD] Frequence de consigne variateur (Hz)
END_VAR
VAR_OUTPUT
    // === ETATS IEC & SYNOPTIQUE ===
    Ready                        : BOOL;   // <-- [STAT] FB pret a fonctionner
    Busy                         : BOOL;   // <-- [STAT] Interlock actif
    Done                         : BOOL;   // <-- [STAT] Action terminee
    Error                        : BOOL;   // <-- [STAT] Synthese defaut
    ErrorId                      : WORD;   // <-- [DIAG] Code erreur (bit0: timeout desserrage frein)
    State                        : E_State;   // <-- [STAT] Etat courant machine d'etat
    StateAtError                 : E_State;   // <-- [DIAG] Etat memorise lors du dernier defaut
    Reason                       : E_TranslationFinalInterlockReason;   // <-- [DIAG] Cause de blocage

    // === ORDRES ACTIONNEURS VALIDES ===
    DriveControlWord             : WORD;   // <-- [ACT] Mot de commande variateur valide
    DriveFreqRefHz               : REAL;   // <-- [ACT] Frequence de consigne variateur valide (Hz)
    DriveFreqRefWord             : WORD;   // <-- [ACT] Frequence mise a l'echelle registre PDO 0x3100
    BrakeCmd                     : BOOL;   // <-- [ACT] Ordre ouverture frein valide

    // === DIAGNOSTICS & TEMPORISATIONS ===
    BrakeTimeoutElapsed          : TIME;   // <-- [DIAG] Ecoule temporisation watchdog frein
    RestartInhibit               : BOOL;   // <-- [DIAG] Inhibition redemarrage actif
END_VAR
VAR
    // === DETECTEURS DE FRONTS ===
    ResetEdge                    : R_TRIG;   // . [LOC] Detecteur front montant Reset
    ErrorEdge                    : R_TRIG;   // . [LOC] Detecteur front montant Erreur
    BrakeTimeoutCauseEdge        : R_TRIG;   // . [LOC] Detecteur nouvelle occurrence cause timeout

    // === TEMPORISATEURS INTERNES ===
    BrakeTimeout                 : TON;   // . [LOC] Temporisateur watchdog desserrage frein

    // === VARIABLES LOCALES INTERNES ===
    MovementRequested            : BOOL;   // . [LOC] Demande de mouvement active
    NeutralRequestSeen           : BOOL;   // . [LOC] Demande neutre (mot 0) observee
    ResetRequired                : BOOL;   // . [LOC] Front Reset obligatoire avant nouvelle marche
    BrakeTimeoutCause            : BOOL;   // . [LOC] Cause brute timeout desserrage frein
    BrakeTimeoutAck              : BOOL := TRUE;   // . [LOC] Accuse operateur (TRUE = pas d'alarme)
END_VAR
VAR CONSTANT
    // === ECHELLE & BORNES REGISTRE PDO ===
    DriveFreqWordScale            : REAL := 100.0;   // Echelle registre 0x3100 (WORD=5000 -> 50,00 Hz)
    DriveFreqWordMaxHz            : REAL := 600.0;   // Borne haute anti-debordement WORD (Hz)
END_VAR

// ── 1. FRONT RESET AVANT GATE ───────────────────────────────────────────
// Le front est échantillonné même pendant Enable/AU faux. Un Reset maintenu
// durant une gate ne peut donc jamais devenir un faux acquittement au retour.
ResetEdge(CLK := Reset);

// RestartInhibit et ResetRequired sont volontairement conservés : un changement
// Enable/AU ne doit jamais réautoriser automatiquement le mouvement après timeout.
IF NOT Enable OR NOT PowerContactorEngaged THEN
    BrakeTimeout(IN := FALSE, PT := T#500ms);
    DriveControlWord := 0;
    DriveFreqRefHz := 0.0;
    DriveFreqRefWord := 0;
    BrakeCmd := FALSE;
    BrakeTimeoutElapsed := T#0ms;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    // ErrorId reste publiquement visible même hors Enable/AU : une retombée de gate
    // ne doit jamais masquer un timeout mémorisé ni remplacer l'acquittement conscient.
    Error := (ErrorId <> 16#0000);
    State := E_State.DISABLED;
    Reason := E_TranslationFinalInterlockReason.NONE;
    RETURN;
END_IF;

MovementRequested := (RequestedDriveControlWord = 1) OR (RequestedDriveControlWord = 2);

// ── 2. Watchdog : exclusivement après ordre effectif de desserrage ──────
// Pendant RestartInhibit, BrakeCmd reste coupé : l'ordre amont n'est donc plus
// effectif et le watchdog ne doit pas créer une nouvelle faute en boucle.
// Pattern Cause/Ack (CODE_QUALITY_STANDARDS §9) : le Reset est TOUJOURS effectif sur
// l'acquittement (BrakeTimeoutAck), sans condition externe — un front Reset ne peut
// jamais être perdu si la confirmation rebondit au même scan. L'interlock de sécurité
// (RestartInhibit, §3) reste basé sur la cause brute (BrakeTimeoutCause / Error), jamais
// sur l'acquittement seul — l'acquittement n'ouvre jamais l'interlock.
BrakeTimeout(IN := BrakeReleaseRequest AND NOT BrakeCommandOpenConfirmed
                   AND NOT RestartInhibit, PT := T#500ms);
BrakeTimeoutElapsed := BrakeTimeout.ET;
IF BrakeTimeout.Q THEN
    BrakeTimeoutCause := TRUE;
ELSIF BrakeCommandOpenConfirmed THEN
    BrakeTimeoutCause := FALSE;   // cause réellement disparue (retour desserrage confirmé)
END_IF;
BrakeTimeoutCauseEdge(CLK := BrakeTimeoutCause);
IF BrakeTimeoutCauseEdge.Q THEN
    BrakeTimeoutAck := FALSE;    // nouvelle occurrence -> ré-alarme, ack remis à zéro
    RestartInhibit := TRUE;
    ResetRequired := TRUE;
    NeutralRequestSeen := FALSE;
    Reason := E_TranslationFinalInterlockReason.BRAKE_COMMAND_NOT_CONFIRMED;
END_IF;
IF ResetEdge.Q THEN
    BrakeTimeoutAck := TRUE;     // toujours effectif, sans condition externe
    ResetRequired := FALSE;
END_IF;
IF BrakeTimeoutCause OR NOT BrakeTimeoutAck THEN
    ErrorId := ErrorId OR 16#0001;
ELSE
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// ── 3. Réarmement anti-redémarrage automatique ──────────────────────────
// Le mot 7 est un reset AC600, pas un neutre opérateur : il reste autorisé avec
// fréquence nulle mais ne solde pas RestartInhibit. Seul le mot 0, vu APRÈS
// disparition de la cause et front Reset, autorise ensuite une nouvelle demande.
IF RestartInhibit AND NOT Error AND NOT ResetRequired AND NOT ResetEdge.Q THEN
    IF RequestedDriveControlWord = 0 THEN
        NeutralRequestSeen := TRUE;
    ELSIF NeutralRequestSeen AND MovementRequested THEN
        RestartInhibit := FALSE;
        NeutralRequestSeen := FALSE;
    END_IF;
END_IF;

// ── 4. Décision finale : zéro couple utile sans confirmation frein ──────
DriveControlWord := 0;
DriveFreqRefHz := 0.0;
DriveFreqRefWord := 0;
// SafeStop est traité en amont par FB_Translation : rampe rapide avec Enable
// maintenu. La commande/frein suivent cette rampe jusqu'à demande nulle ; seul
// un gate dur, timeout ou défaut final impose ici la coupure immédiate.
BrakeCmd := BrakeReleaseRequest AND NOT Error AND NOT RestartInhibit;
Ready := NOT Error AND NOT RestartInhibit;
Busy := FALSE;
Done := FALSE;
State := E_State.READY;

IF Error THEN
    BrakeCmd := FALSE;
    State := E_State.DISABLED;
ELSIF RequestedDriveControlWord = 7 THEN
    // Reset AC600 préservé, toujours sans consigne fréquence ni couple utile.
    DriveControlWord := 7;
ELSIF RestartInhibit THEN
    Reason := E_TranslationFinalInterlockReason.RESTART_INHIBITED;
    State := E_State.INIT;
ELSIF MovementRequested THEN
    // Double condition obligatoire : ordre effectif de desserrage ET confirmation
    // contacteur/bobine. Une confirmation résiduelle seule ne peut jamais autoriser
    // couple ou fréquence AC600.
    IF BrakeReleaseRequest AND BrakeCommandOpenConfirmed THEN
        DriveControlWord := RequestedDriveControlWord;
        DriveFreqRefHz := MAX(0.0, RequestedDriveFreqHz);
        Busy := TRUE;
        State := E_State.BUSY;
    ELSE
        Busy := TRUE;
        State := E_State.INIT;
    END_IF;
END_IF;

// ── 5. Mise à l'échelle finale REAL Hz -> WORD registre PDO 0x3100 ──────
// Conversion unique en sortie de chaîne, quelle que soit la branche qui a fixé
// DriveFreqRefHz ci-dessus — jamais recalculée ailleurs (producteur unique).
DriveFreqRefWord := REAL_TO_WORD(LIMIT(0.0, DriveFreqRefHz, DriveFreqWordMaxHz) * DriveFreqWordScale);

(* ═══════════════════════════════════════════════════════════════
   🚦 ST_DredgingAssistState — États publics assistance prélèvement
   ═══════════════════════════════════════════════════════════════ *)
TYPE ST_DredgingAssistState :
STRUCT
    DiveReady                  : BOOL;
    DiveBusy                   : BOOL;
    DiveDone                   : BOOL;
    DiveError                  : BOOL;
    DiveErrorId                : WORD;
    DiveState                  : E_DiveSearchState;
    BottomTouchConfirmed       : BOOL;
    ExtractionReady            : BOOL;
    ExtractionBusy             : BOOL;
    ExtractionDone             : BOOL;
    ExtractionError            : BOOL;
    ExtractionErrorId          : WORD;
    ExtractionState            : E_ExtractionSequenceState;
    OperatorActionId           : WORD;       (* Une seule consigne conduite, arbitré en PRG_09 *)
    OperatorAction             : STRING(120); (* Texte de secours ; IHM peut mapper l'identifiant *)
    // : mode vidage à la trémie (pas de FB dédié, logique combinatoire PRG_04)
    DumpAtTremieArmed          : BOOL; (* TglEnableDumpAtTremie (bit IHM brut) *)
    DumpAtTremieAssistActive   : BOOL; (* Armé ET Mode MAINT_N1/N2 (mode réellement actif) *)
    DumpAtTremieAtTremie       : BOOL; (* M3_AtTremieStable *)
    DumpAtTremieBucketOpenArmed: BOOL; (* CmdOpen_IHM déclenché par ce mode *)
    DumpAtTremieDescentLocked  : BOOL; (* DescendPermit M1/M2 forcé par ce mode (hors P1/Maintenance) *)
    // Diagnostic bypass séquence DiveSearch
    BypassDiveActive           : BOOL; (* TglBypassDiveSearchSequence armé (descente couplée en cours) *)
    BypassKoboldBottomTouched  : BOOL; (* Fond confirmé par le bypass (front montant Kobold en descente) *)
END_STRUCT
END_TYPE

(* ============================================================================
   🧪 FB_EncoderValidation — Suite PLC Encoder/Homing nominale
   ============================================================================
   T25 : validation du flux nominal M1/M2 en simulation.
   Le Homing unitaire MAINT_N2 reste volontairement hors périmètre.

   Cette suite est ciblée par Cmd.RunSuite = SuiteEncoder. Elle n'est pas
   ajoutée à RunAll tant que le flux Homing unitaire n'est pas spécifié.
   Chaque étape possède une limite de temps locale ; aucune attente implicite.
   ============================================================================ *)

FUNCTION_BLOCK PUBLIC FB_EncoderValidation
VAR_INPUT
    Start       : BOOL;
    Abort       : BOOL;
    CaseId      : INT; // 0=tous ; 1..2=cas ciblé
END_VAR
VAR_OUTPUT
    Busy            : BOOL;
    Done            : BOOL;
    AnyFailed       : BOOL;
    SimGateOk       : BOOL;
    ActiveStimulusId : INT;
    StepElapsed     : TIME;
    Report          : ST_TestSuiteReport;
    TerminalState   : E_TestTerminalState;
    ConfigError     : BOOL;
    ConfigErrorStepId : INT;
    ConfigErrorCheckIdx : INT;
    ErrorCode       : INT;
    ErrorMessage    : STRING(160);
END_VAR
VAR
    StartPrev       : BOOL;
    ResetIssued     : BOOL;
    Step            : INT;
    CurrentCaseId   : INT;
    StepStarted     : BOOL;
    StepTimer       : TON;
    StepLimit       : TIME;
    StepFailed      : BOOL;
    StepPassed      : BOOL;
    M1HomePulse     : BOOL;
    M2HomePulse     : BOOL;
    Index           : INT;
END_VAR

// Gate simulation : une suite non exécutable se termine explicitement.
SimGateOk := GVL_Simulation.SimulationModeActive
          AND NOT GVL_Simulation.BusEncoderM1IsReal
          AND NOT GVL_Simulation.BusEncoderM2IsReal;

// Valeurs par défaut de commande : aucun front ne reste actif hors étape dédiée.
M1HomePulse := FALSE;
M2HomePulse := FALSE;
ActiveStimulusId := 0;

IF Abort THEN
    GVL_IHM.M1TreuilRetenue.Cmd.BtnHome := FALSE;
    GVL_IHM.M2TreuilBenne.Cmd.BtnHome := FALSE;
    Busy := FALSE;
    Done := TRUE;
    AnyFailed := TRUE;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_ABORTED;
    Report.Aborted := TRUE;
    Report.AnyFailed := TRUE;
    Report.TerminalState := TerminalState;
    Report.FailureSummary := 'Encoder/Homing : ABORTED';
    RETURN;
END_IF;

// Démarrage sur front : rapport réinitialisé et mode de maintenance demandé.
IF Start AND NOT StartPrev AND NOT Busy THEN
    StartPrev := TRUE;
    Busy := TRUE;
    Done := FALSE;
    AnyFailed := FALSE;
    ConfigError := FALSE;
    ErrorCode := 0;
    ErrorMessage := '';
    TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    IF CaseId < 0 OR CaseId > 2 THEN
        Busy := FALSE;
        Done := TRUE;
        AnyFailed := TRUE;
        ConfigError := TRUE;
        ErrorCode := 3002;
        ErrorMessage := 'Encoder/Homing CaseId invalide';
        TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        Report.TerminalState := TerminalState;
        Report.AnyFailed := TRUE;
        Report.ErrorCode := ErrorCode;
        Report.ErrorMessage := ErrorMessage;
        RETURN;
    END_IF;
    IF CaseId = 2 THEN Step := 20; ELSE Step := 10; END_IF;
    Report.Name := 'Encoder/Homing Validation';
    Report.InProgress := TRUE;
    Report.AllPassed := FALSE;
    Report.AnyFailed := FALSE;
    Report.Aborted := FALSE;
    Report.TerminalState := TerminalState;
    Report.ErrorCode := 0;
    Report.ErrorMessage := '';
    Report.FailureSummary := '';
    Report.CurrentStepId := Step;
    Report.CurrentCaseId := SEL(Step >= 20, 2, 1);
    Report.Duration := T#0s;
    Report.RunCounter := Report.RunCounter + 1;
    FOR Index := 1 TO GVL_PLC_Tests_Const.MaxSteps DO
        Report.Steps[Index].Executed := FALSE;
        Report.Steps[Index].Passed := FALSE;
        Report.Steps[Index].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Steps[Index].Duration := T#0s;
    END_FOR;
    FOR Index := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        Report.Cases[Index].Executed := FALSE;
        Report.Cases[Index].Ok := FALSE;
        Report.Cases[Index].FailedStepId := 0;
        Report.Cases[Index].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Cases[Index].Duration := T#0s;
    END_FOR;
    StepStarted := FALSE;
    ResetIssued := FALSE;
ELSIF NOT Start THEN
    StartPrev := FALSE;
END_IF;

IF NOT Busy THEN
    RETURN;
END_IF;

StepElapsed := StepElapsed + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
Report.Duration := Report.Duration + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
Report.CurrentStepId := Step;
// 🧭 Mapping rapport : étapes 10/11 = TC-E1 ; étapes 20/21/22 = TC-E2.
CurrentCaseId := SEL(Step >= 20, 2, 1);
Report.CurrentCaseId := CurrentCaseId;

IF NOT StepStarted THEN
    StepStarted := TRUE;
    StepElapsed := T#0s;
    CASE Step OF
        10: StepLimit := T#2s;
        11: StepLimit := T#2s;
        20: StepLimit := T#2s;
        21: StepLimit := T#2s;
        22: StepLimit := T#10s;
    ELSE
        ConfigError := TRUE;
        ConfigErrorStepId := Step;
        ErrorCode := 3001;
        ErrorMessage := 'Encoder/Homing étape inconnue';
        StepLimit := T#0s;
    END_CASE;
END_IF;

StepTimer(IN := TRUE, PT := StepLimit);

CASE Step OF
    // TC-E1 : gate et interface IHM nominale accessibles.
    10:
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.MAINT_N2;
        IF NOT SimGateOk THEN
            StepFailed := TRUE;
            ErrorCode := 3003;
            ErrorMessage := 'Gate simulation codeurs inactif';
        ELSIF NOT GVL_IHM.M1TreuilRetenue.State.HomingError
           AND NOT GVL_IHM.M2TreuilBenne.State.HomingError THEN
            StepPassed := TRUE;
            Step := 11;
            StepStarted := FALSE;
        END_IF;

    // TC-E1 : vérifier que le rapport IHM des deux treuils existe avant commande.
    11:
        IF (GVL_IHM.M1TreuilRetenue.State.HomingState >= E_State.DISABLED)
           AND (GVL_IHM.M2TreuilBenne.State.HomingState >= E_State.DISABLED) THEN
            StepPassed := TRUE;
            Step := 0;
        END_IF;

    // TC-E2 : fronts BtnHome indépendants, envoyés simultanément.
    20:
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.MAINT_N2;
        IF NOT SimGateOk THEN
            StepFailed := TRUE;
            ErrorCode := 3003;
            ErrorMessage := 'Gate simulation codeurs inactif';
        ELSE
            StepPassed := TRUE;
            Step := 21;
            StepStarted := FALSE;
        END_IF;

    21:
        M1HomePulse := TRUE;
        M2HomePulse := TRUE;
        GVL_IHM.M1TreuilRetenue.Cmd.BtnHome := M1HomePulse;
        GVL_IHM.M2TreuilBenne.Cmd.BtnHome := M2HomePulse;
        StepPassed := TRUE;
        Step := 22;
        StepStarted := FALSE;

    // TC-E2 : aucune attente infinie : les deux instances doivent finir ou déclarer une erreur.
    22:
        GVL_IHM.M1TreuilRetenue.Cmd.BtnHome := FALSE;
        GVL_IHM.M2TreuilBenne.Cmd.BtnHome := FALSE;
        IF (GVL_IHM.M1TreuilRetenue.State.HomingDone OR GVL_IHM.M1TreuilRetenue.State.Homed)
           AND (GVL_IHM.M2TreuilBenne.State.HomingDone OR GVL_IHM.M2TreuilBenne.State.Homed) THEN
            StepPassed := TRUE;
            Step := 0;
        ELSIF GVL_IHM.M1TreuilRetenue.State.HomingError OR GVL_IHM.M2TreuilBenne.State.HomingError THEN
            StepFailed := TRUE;
        END_IF;
END_CASE;

// Verdict local de l'étape : PASS, FAIL ou TIMEOUT contrôlé.
IF StepPassed OR StepFailed OR StepTimer.Q THEN
    IF StepPassed THEN
        Report.Steps[Report.CurrentStepId].Passed := TRUE;
        Report.Steps[Report.CurrentStepId].FailReason := E_TestFailReason.FAIL_NONE;
    ELSE
        Report.Steps[Report.CurrentStepId].Passed := FALSE;
        Report.Steps[Report.CurrentStepId].FailReason := SEL(StepFailed, E_TestFailReason.FAIL_TIMEOUT, E_TestFailReason.FAIL_CHECK);
        AnyFailed := TRUE;
    END_IF;
    Report.Steps[Report.CurrentStepId].Executed := TRUE;
    Report.Steps[Report.CurrentStepId].Duration := StepElapsed;
    Report.ErrorCode := ErrorCode;
    Report.ErrorMessage := ErrorMessage;
    // Un échec ou un timeout termine immédiatement la suite : aucune étape
    // suivante ne doit laisser le banc attendre un signal devenu impossible.
    IF NOT StepPassed THEN
        Step := 0;
    END_IF;
    StepPassed := FALSE;
    StepFailed := FALSE;
    StepTimer(IN := FALSE, PT := StepLimit);
    StepElapsed := T#0s;
    IF Step = 0 THEN
        Busy := FALSE;
        Done := TRUE;
        Report.InProgress := FALSE;
        Report.AnyFailed := AnyFailed;
        Report.AllPassed := NOT AnyFailed;
        Report.TerminalState := SEL(AnyFailed, E_TestTerminalState.TEST_TERMINAL_DONE, E_TestTerminalState.TEST_TERMINAL_FAILED);
        TerminalState := Report.TerminalState;
        IF CurrentCaseId = 1 THEN
            Report.Cases[CurrentCaseId].Name := 'TC-E1 Interface Homing nominale';
        ELSE
            Report.Cases[CurrentCaseId].Name := 'TC-E2 Commandes Home M1/M2';
        END_IF;
        Report.Cases[CurrentCaseId].Executed := TRUE;
        Report.Cases[CurrentCaseId].Ok := NOT AnyFailed;
        Report.Cases[CurrentCaseId].FailedStepId := 0;
        Report.Cases[CurrentCaseId].FailReason := E_TestFailReason.FAIL_NONE;
        IF AnyFailed THEN
            Report.Cases[CurrentCaseId].FailedStepId := Report.CurrentStepId;
            Report.Cases[CurrentCaseId].FailReason := E_TestFailReason.FAIL_CHECK;
        END_IF;
        Report.Cases[CurrentCaseId].Duration := Report.Duration;
        IF AnyFailed THEN Report.FailureSummary := 'Encoder/Homing : échec ou timeout'; END_IF;
    ELSE
        StepStarted := FALSE;
    END_IF;
END_IF;

// Limite globale de sécurité de la suite : 30 s maximum.
IF Report.Duration >= T#30s AND Busy THEN
    GVL_IHM.M1TreuilRetenue.Cmd.BtnHome := FALSE;
    GVL_IHM.M2TreuilBenne.Cmd.BtnHome := FALSE;
    Busy := FALSE;
    Done := TRUE;
    AnyFailed := TRUE;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_WATCHDOG_TIMEOUT;
    Report.InProgress := FALSE;
    Report.AnyFailed := TRUE;
    Report.AllPassed := FALSE;
    Report.TerminalState := TerminalState;
    Report.ErrorCode := 3002;
    Report.ErrorMessage := 'Watchdog Encoder/Homing expire';
    Report.FailureSummary := Report.ErrorMessage;
END_IF;

(* =======================================================================
   🛡️ FB_Brake — Séquence frein à manque de courant (temps physiques)
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Gestion temporisée ouverture/fermeture frein à manque de courant
   🔒 Polarité : Sécurité positive (BrakeCmd=FALSE = frein collé au repos)
   🔌 Interface : Double vérification retour contacteur (ST_ContactorCheck)
   📄 Doc métier : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md §3
   ======================================================================= *)
FUNCTION_BLOCK PUBLIC FB_Brake
VAR_INPUT
    // === COMMANDES ET CONSIGNES ===
    Enable                  : BOOL;               // --> [CMD]  Autorisation generale (FALSE = frein colle)
    Reset                   : BOOL;               // --> [CMD]  Acquittement defaut (front)
    MovementRequested       : BOOL;               // --> [CMD]  Demande de mouvement (sens+palier actifs)

    // === RETOURS MATERIELS & SIMULATION ===
    ContactorFeedback       : BOOL;               // --> [HW]   Retour contacteur frein (TRUE = relache/ouvert)
    BypassContactorCheck    : BOOL;               // --> [TST]  Bypass controle contacteur (simu)

    // === TEMPORISATIONS ET REGLAGES ===
    DelayContactClose       : TIME := T#100ms;    // --> [CFG]  Temps de fermeture contacteur de puissance
    DelayMagnetise          : TIME := T#300ms;    // --> [CFG]  Delai magnetisation moteur avant ouverture frein
    DelayMotorDecel         : TIME := T#500ms;    // --> [CFG]  Delai deceleration avant collage frein
    FeedbackTimeout         : TIME := T#1s;       // --> [CFG]  Delai max coherence commande/retour frein
END_VAR
VAR_OUTPUT
    // === ETATS IEC & DERIVATION ===
    Ready                   : BOOL;               // <-- [STAT] FB pret a fonctionner
    Busy                    : BOOL;               // <-- [STAT] Sequence temporisee en cours
    Done                    : BOOL;               // <-- [STAT] Frein ouvert/relache confirme
    Error                   : BOOL;               // <-- [STAT] Defaut actif sur le frein
    ErrorId                 : WORD;               // <-- [DIAG] Masque de defauts (bit0: incoherence retour)
    State                   : E_State;            // <-- [STAT] Etat operationnel courant
    StateAtError            : E_State;            // <-- [STAT] Etat memorise lors du defaut

    // === COMMANDES ET CONFIRMATIONS ===
    BrakeCmd                : BOOL;               // <-- [ACT]  Commande bobine frein (TRUE = relache/ouvert)
    BrakeCommandOpenConfirmed : BOOL;            // <-- [STAT] Confirmation ouverture frein pour verrous
    ContactorCheck          : ST_ContactorCheck;  // <-- [DIAG] Diagnostic detaille retour contacteur
END_VAR
VAR
    // === TRIGGERS ET DETECTION FRONTS ===
    ResetEdge               : R_TRIG;             // . [LOC]  Detecteur front acquittement
    ErrorEdge               : R_TRIG;             // . [LOC]  Detecteur front apparition defaut
    BypassEdge              : R_TRIG;             // . [LOC]  Detecteur front activation bypass

    // === TEMPORISATEURS INTERNES ===
    TonMagnetise            : TON;                // . [LOC]  Temporisation avant relachement frein
    TonDecel                : TON;                // . [LOC]  Temporisation avant collage frein
    TonFeedback             : TON;                // . [LOC]  Timeout de coherence commande/retour
END_VAR

{region "§1 Gate"}
// 🛑 1. GATE — pas d'Enable = frein collé (sécurité positive), aucune temporisation en cours
IF NOT Enable THEN
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    BrakeCmd := FALSE;
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
{endregion}

{region "§2 Reset et fronts"}
// 🔑 2. RESET FRONT — efface le bit dont la cause a disparu
ResetEdge(CLK := Reset);
BypassEdge(CLK := BypassContactorCheck);
{endregion}

{region "§3 Séquence temporisée"}
// 🛠️ 3. SÉQUENCE TEMPORISÉE (démarrage vs arrêt)
IF MovementRequested THEN
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    TonMagnetise(IN := TRUE, PT := DelayMagnetise + DelayContactClose);
    IF TonMagnetise.Q THEN
        BrakeCmd := TRUE;              // ✅ Contacteur + magnétisation acquis → relâche
        State := E_State.DONE;
    ELSE
        BrakeCmd := FALSE;             // ⏳ Encore collé pendant la magnétisation
        State := E_State.BUSY;
    END_IF;
ELSE
    // Sécurité positive : fermeture immédiate du frein (collé) dès que les contacteurs de sens s'ouvrent
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    BrakeCmd := FALSE;                 // Fermeture immédiate
    State := E_State.READY;
END_IF;

Busy := (State = E_State.BUSY);
Done := (State = E_State.DONE);
{endregion}

{region "§4 Double vérification contacteur"}
// 🔍 4. DOUBLE VÉRIFICATION RETOUR CONTACTEUR (ST_ContactorCheck)
ContactorCheck.Command := BrakeCmd;
ContactorCheck.Feedback := ContactorFeedback;

// ContactorFeedback est dans le MÊME sens que BrakeCmd (TRUE = relâché = frein ouvert).
// En marche saine les deux sont ÉGAUX → c'est leur DIFFÉRENCE qui signale l'incohérence
// (contacteur collé). Le test compare donc `<>`.
TonFeedback(IN := (BrakeCmd <> ContactorFeedback), PT := FeedbackTimeout);
IF NOT BypassContactorCheck THEN
    IF TonFeedback.Q THEN
        ContactorCheck.StuckClosed := (BrakeCmd AND NOT ContactorFeedback);            // relâche commandée (BrakeCmd=TRUE), frein reste serré (ContactorFeedback=FALSE)
        ContactorCheck.StuckOpen   := (NOT BrakeCmd AND ContactorFeedback);             // serrage commandé (BrakeCmd=FALSE), frein reste ouvert (ContactorFeedback=TRUE)
        ErrorId := ErrorId OR 16#0001;
    ELSIF ResetEdge.Q THEN
        ContactorCheck.StuckClosed := FALSE;
        ContactorCheck.StuckOpen   := FALSE;
        ErrorId := ErrorId AND 16#FFFE;
    END_IF;
ELSE
    ContactorCheck.StuckClosed := FALSE;
    ContactorCheck.StuckOpen   := FALSE;
    ErrorId := ErrorId AND 16#FFFE;   // Bypass actif : efface/maintient à 0 le bit 0
    IF BypassEdge.Q THEN
        StateAtError := E_State.DISABLED; // Front activation bypass : débloque l'état figé
    END_IF;
END_IF;

{endregion}

{region "§5 Arbitrage error"}
// 🧾 5. ARBITRAGE ERROR / STATEATERROR (figé jusqu'à acquittement)
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;
{endregion}

{region "§6 Sortie sûre"}
// 🛡️ 6. SORTIE SÛRE SUR DÉFAUT
IF Error THEN
    BrakeCmd := FALSE;
END_IF;
{endregion}

{region "§7 Confirmation ouverture"}
// 📤 7. CONFIRMATION OUVERTURE FREIN (même sens que ContactorFeedback, ou image de BrakeCmd si BypassContactorCheck=TRUE)
IF BypassContactorCheck THEN
    BrakeCommandOpenConfirmed := BrakeCmd;
ELSE
    BrakeCommandOpenConfirmed := ContactorFeedback;  (* TRUE = frein ouvert = desserrage confirmé *)
END_IF;
{endregion}

(* =======================================================================
   🔒 FB_Safety_EmergencyManagementOutput — Projection Physique Fail-Safe
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Enable gate + copie consignes logiques vers sorties physiques
   🔒 Polarité : MaintainA/B_RQ en maintien (TRUE = voie saine)
   🔌 Architecture : Projection physique fail-safe
   📄 Doc métier : DOC/AF/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_Safety_EmergencyManagementOutput
VAR_INPUT
    // === CONSIGNES & COMMANDES LOGIQUES ===
    Enable                  : BOOL; // --> [CMD]  Active le pilote (FALSE = toutes sorties a FALSE)
    Cmd                     : ST_Safety_Emergency_InternalCmd; // --> [CMD] Ordres logiques recus du bloc logique

    // === RETOURS D'ETAT & DIAGNOSTICS (MIROIRS) ===
    ChainOk                 : BOOL; // --> [HW]   Miroir EmergencyChainClosed (pour bus State)
    ContactorOk             : BOOL; // --> [HW]   Miroir PowerContactorEngaged (pour bus State)
    ArmingStep              : INT;  // --> [STAT] Miroir ArmingSeqStep (pour bus State)
    Armable                 : BOOL; // --> [STAT] Calcule par Logic (pour bus State)
    ArmingBusy              : BOOL; // --> [STAT] Calcule par Logic (pour bus State)
    Error                   : BOOL; // --> [DIAG] Miroir Error (pour bus Diag)
    ErrorId                 : WORD; // --> [DIAG] Miroir ErrorId (pour bus Diag)
    RedundancyTestFailed    : BOOL; // --> [DIAG] Miroir RedundancyTestFailed (pour bus Diag)
    ArmFailed               : BOOL; // --> [DIAG] Miroir ArmFailed (pour bus Diag)
    LockoutActive           : BOOL; // --> [DIAG] Miroir LockoutActive (pour bus Diag)
END_VAR
VAR_OUTPUT
    // === SORTIES PHYSIQUES TERMINALES ===
    MaintainA_RQ            : BOOL; // <-- [ACT]  Vers relais maintien canal A (TRUE = voie maintenue)
    MaintainB_RQ            : BOOL; // <-- [ACT]  Vers relais maintien canal B (TRUE = voie maintenue)
    ArmPulse_RQ             : BOOL; // <-- [ACT]  Vers contacteur impulsion rearmement (TRUE = pulse actif)

    // === BUS D'ETAT & DIAGNOSTIC PUBLICS ===
    State                   : ST_Safety_Emergency_State; // <-- [STAT] Bus d'etat public
    Diag                    : ST_Safety_Emergency_Diag;  // <-- [DIAG] Bus diagnostic public
END_VAR

// === IMPLEMENTATION ===

{region "§1 Gate"}
IF NOT Enable THEN
    MaintainA_RQ   := FALSE;
    MaintainB_RQ   := FALSE;
    ArmPulse_RQ    := FALSE;

    State.ChainOk        := FALSE;
    State.ContactorOk    := FALSE;
    State.Step           := 0;
    State.Armable        := FALSE;
    State.ArmingBusy     := FALSE;

    Diag.Error                := FALSE;
    Diag.ErrorId              := 16#0000;
    Diag.RedundancyTestFailed := FALSE;
    Diag.ArmFailed            := FALSE;
    Diag.LockoutActive        := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Projection sorties et bus"}
// ⚡ Sorties physiques — écriture directe des ordres logiques
MaintainA_RQ := Cmd.MaintainA_Cmd;
MaintainB_RQ := Cmd.MaintainB_Cmd;
ArmPulse_RQ  := Cmd.ArmPulse_Cmd;

// 🚦 Bus d'état public
State.ChainOk        := ChainOk;
State.ContactorOk    := ContactorOk;
State.Step           := ArmingStep;
State.Armable        := Armable;
State.ArmingBusy     := ArmingBusy;

// 🛡️ Bus diagnostic public
Diag.Error                := Error;
Diag.ErrorId              := ErrorId;
Diag.RedundancyTestFailed := RedundancyTestFailed;
Diag.ArmFailed            := ArmFailed;
Diag.LockoutActive        := LockoutActive;
{endregion}

(* ═══════════════════════════════════════════════════════════════
   ⚖️ FB_Winch_Symmetry — Mesure passive MES-008 M1/M2
   📄 Doc : ARCHIVES/Doc/AUDITS/PreLivraison/TASKS/TASK_D1_Preflight_et_Symetrie_Winch_v1.0.md
   🔒 Observateur pur : aucune écriture de commande, sécurité ou mouvement.
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK FB_Winch_Symmetry
VAR_INPUT
    Reset : BOOL;
    M1CommandActive : BOOL;
    M2CommandActive : BOOL;
    M1Direction : INT;
    M2Direction : INT;
    M1BrakeCmd, M2BrakeCmd, M1BrakeApplied, M2BrakeApplied : BOOL;
    M1Position_M, M2Position_M, M1Speed_Mps, M2Speed_Mps, SyncDeviation_M : REAL;
    Config : ST_Winch_SymmetryCfg;
END_VAR
VAR_IN_OUT
    Data : ST_Winch_SymmetryData;
END_VAR
VAR_OUTPUT
    SymmetryOk : BOOL;
    SymmetryValid : BOOL;
END_VAR
VAR
    ResetEdge : R_TRIG;
    CycleTime : FB_CycleTime;
    CommandTon : TON;
    Comparable, Qualified, PreviousQualified, Stopping, StartCapturedM1, StartCapturedM2, StopCapturedM1, StopCapturedM2 : BOOL;
    StartMsM1, StartMsM2, ReleaseMsM1, ReleaseMsM2, ApplyMsM1, ApplyMsM2, StopMsM1, StopMsM2 : UDINT;
    MotionTimer, StopTimer : TON;
    StopStartM1_M, StopStartM2_M : REAL;
END_VAR

CycleTime(DefaultValueS := 0.010); ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN Data.DeltaStartDelay_Ms:=0; Data.DeltaBrakeReleaseTime_Ms:=0; Data.DeltaBrakeApplyTime_Ms:=0; Data.DeltaStopDistance_Mm:=0; Data.DeltaStopTime_Ms:=0; Data.MaxSyncDeviation_M:=0.0; END_IF;
Comparable := M1CommandActive AND M2CommandActive AND (M1Direction = M2Direction) AND (M1Direction <> 0);
CommandTon(IN := Comparable, PT := UDINT_TO_TIME(Config.MinimumCommandTime_Ms));
Qualified := CommandTon.Q AND (M1Speed_Mps >= Config.MinimumSpeed_Mps) AND (M2Speed_Mps >= Config.MinimumSpeed_Mps);
MotionTimer(IN := Comparable, PT := T#1h);
StopTimer(IN := Stopping, PT := T#1h);
IF NOT Comparable THEN StartCapturedM1:=FALSE; StartCapturedM2:=FALSE; ReleaseMsM1:=0; ReleaseMsM2:=0; ApplyMsM1:=0; ApplyMsM2:=0; END_IF;
IF Comparable AND (M1Speed_Mps >= Config.MinimumSpeed_Mps) AND NOT StartCapturedM1 THEN StartMsM1:=TIME_TO_UDINT(MotionTimer.ET); StartCapturedM1:=TRUE; END_IF;
IF Comparable AND (M2Speed_Mps >= Config.MinimumSpeed_Mps) AND NOT StartCapturedM2 THEN StartMsM2:=TIME_TO_UDINT(MotionTimer.ET); StartCapturedM2:=TRUE; END_IF;
IF Qualified THEN
    IF M1BrakeCmd AND M1BrakeApplied THEN ReleaseMsM1 := ReleaseMsM1 + REAL_TO_UDINT(CycleTime.CycleTimeS * 1000.0); END_IF;
    IF M2BrakeCmd AND M2BrakeApplied THEN ReleaseMsM2 := ReleaseMsM2 + REAL_TO_UDINT(CycleTime.CycleTimeS * 1000.0); END_IF;
    IF NOT M1BrakeCmd AND NOT M1BrakeApplied THEN ApplyMsM1 := ApplyMsM1 + REAL_TO_UDINT(CycleTime.CycleTimeS * 1000.0); END_IF;
    IF NOT M2BrakeCmd AND NOT M2BrakeApplied THEN ApplyMsM2 := ApplyMsM2 + REAL_TO_UDINT(CycleTime.CycleTimeS * 1000.0); END_IF;
    IF SyncDeviation_M > Data.MaxSyncDeviation_M THEN Data.MaxSyncDeviation_M := SyncDeviation_M; END_IF;
END_IF;
IF PreviousQualified AND NOT Comparable THEN Stopping:=TRUE; StopCapturedM1:=FALSE; StopCapturedM2:=FALSE; StopStartM1_M:=M1Position_M; StopStartM2_M:=M2Position_M; END_IF;
IF Stopping THEN
    IF (M1Speed_Mps < Config.MinimumSpeed_Mps) AND NOT StopCapturedM1 THEN StopMsM1:=TIME_TO_UDINT(StopTimer.ET); StopCapturedM1:=TRUE; END_IF;
    IF (M2Speed_Mps < Config.MinimumSpeed_Mps) AND NOT StopCapturedM2 THEN StopMsM2:=TIME_TO_UDINT(StopTimer.ET); StopCapturedM2:=TRUE; END_IF;
    IF StopCapturedM1 AND StopCapturedM2 THEN
        Data.DeltaStartDelay_Ms := ABS(UDINT_TO_DINT(StartMsM1)-UDINT_TO_DINT(StartMsM2));
        Data.DeltaBrakeReleaseTime_Ms := ABS(UDINT_TO_DINT(ReleaseMsM1)-UDINT_TO_DINT(ReleaseMsM2));
        Data.DeltaBrakeApplyTime_Ms := ABS(UDINT_TO_DINT(ApplyMsM1)-UDINT_TO_DINT(ApplyMsM2));
        Data.DeltaStopDistance_Mm := REAL_TO_UDINT(ABS(ABS(M1Position_M-StopStartM1_M)-ABS(M2Position_M-StopStartM2_M))*1000.0);
        Data.DeltaStopTime_Ms := ABS(UDINT_TO_DINT(StopMsM1)-UDINT_TO_DINT(StopMsM2)); Stopping:=FALSE; SymmetryValid:=TRUE;
    END_IF;
END_IF;
SymmetryOk := SymmetryValid AND (Data.DeltaStartDelay_Ms<=Config.DeltaStartDelay_Ms) AND (Data.DeltaBrakeReleaseTime_Ms<=Config.DeltaBrakeReleaseTime_Ms) AND (Data.DeltaBrakeApplyTime_Ms<=Config.DeltaBrakeApplyTime_Ms) AND (Data.DeltaStopDistance_Mm<=Config.DeltaStopDistance_Mm) AND (Data.DeltaStopTime_Ms<=Config.DeltaStopTime_Ms);
PreviousQualified := Qualified;

(* 🛡️ Raisons mémorisées de la barrière finale frein / AC600 M3. *)
{attribute 'qualified_only'}
TYPE E_TranslationFinalInterlockReason :
(
    NONE := 0,
    BRAKE_COMMAND_NOT_CONFIRMED := 1,
    RESTART_INHIBITED := 2
);
END_TYPE

SETUP
VAR
    fb : FB_SAFETY_EMERGENCYMANAGEMENT;
END_VAR
END_SETUP

(* TC-P01-002 est classee SITE+AUTO dans l AF (mixte). Ce test ne couvre QUE la partie AUTO
   (commande logicielle) : preuve qu un seul canal est coupe a la fois et que le FB interprete
   correctement le retour de boucle fourni en entree. Il ne peut PAS prouver que la coupure
   physique de MaintainA/B_RQ ouvre reellement la boucle materielle -- ca reste une verification
   SITE, sur l automate reel, jamais automatisable en logiciel. *)
TEST 'TC-P01-002 (partie AUTO) chaque canal est commande independamment, l autre reste maintenu'
    (* demarrage + regime etabli, sain *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'hors defaut, canal A maintenu');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'hors defaut, canal B maintenu');

    (* front ArmRequest -> TestA (step 1) : SEUL le canal A doit se couper *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'front doit lancer TestA');
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'TestA : canal A seul doit se couper');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'TestA : canal B ne doit PAS etre affecte');

    (* 200ms plus tard : la boucle reagit reellement a la coupure de A (preuve physique reelle) *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := FALSE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 2, 'TestA reussi (boucle a reagi) -> RestoreA');
    ASSERT_FALSE(fb.ERROR, 'pas de defaut si le canal reagit correctement au test');
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'canal A restaure immediatement apres son test');

    (* 200ms plus tard : boucle refermee (A restaure) -> passage a TestB (step 3) *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 3, 'RestoreA reussi -> TestB');
    ASSERT_FALSE(fb.MAINTAINB_RQ, 'TestB : canal B seul doit se couper');
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'TestB : canal A ne doit PAS etre affecte');

    (* 200ms plus tard : boucle reagit a la coupure de B *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := FALSE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 4, 'TestB reussi -> RestoreB');
    ASSERT_FALSE(fb.ERROR, 'pas de defaut si le canal B reagit correctement au test');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'canal B restaure immediatement apres son test');
END_TEST

TEST 'TC-P01-003 front ArmRequest + boucle OK sur les 2 canaux -> pulse 1s puis confirmation'
    (* demarrage + regime etabli, sain *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);

    (* front ArmRequest -> TestA *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);

    (* TestA reussi (boucle reagit) -> RestoreA *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := FALSE, POWERCONTACTORENGAGED := FALSE);

    (* RestoreA reussi -> TestB *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);

    (* TestB reussi (boucle reagit) -> RestoreB *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := FALSE, POWERCONTACTORENGAGED := FALSE);

    (* RestoreB reussi -> Pulse (step 5), impulsion 1s *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 5, 'les 2 canaux valides -> impulsion de reamement');
    ASSERT_TRUE(fb.ARMPULSE_RQ, 'pulse de reamement doit etre actif (TC-P01-003)');

    (* 1s plus tard : pulse termine -> Confirm (step 6) *)
    ADVANCE_TIME(1000000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 6, 'pulse de 1s termine -> attente confirmation contacteur');
    ASSERT_FALSE(fb.ARMPULSE_RQ, 'pulse retombe apres 1s');
    ASSERT_TRUE(fb.BUSY, 'sequence toujours en cours (attente confirmation)');

    (* contacteur confirme engage -> succes, retour IDLE *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := TRUE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'confirmation contacteur -> retour IDLE');
    ASSERT_TRUE(fb.DONE, 'contacteur engage confirme -> Done');
    ASSERT_FALSE(fb.BUSY, 'sequence terminee');
    ASSERT_FALSE(fb.EMERGENCYARMINGLOCKOUTACTIVE, 'succes -> pas de lockout');
    ASSERT_FALSE(fb.ERROR, 'reamement reussi -> pas de defaut');
END_TEST

TEST 'TC-P01-004/009 Reset acquitte l affichage mais re-alarme si la cause persiste'
    (* reproduit l etat "canal colle" de TC-P01-006 -- setup independant, propre a ce test *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.ERROR, 'precondition : canal colle doit avoir leve une erreur');

    (* Reset : doit acquitter l affichage sans redemarrage auto (TC-P01-004) -- +1 cycle *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := TRUE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_FALSE(fb.ERROR, 'Reset doit effacer l affichage du defaut');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'Reset seul ne relance jamais de sequence (pas de redemarrage auto)');
    (* Complete TC-P01-004 : sa colonne "Comportement attendu" precise "Reset efface l affichage
       (interlock reste sur Cause)" -- assertion manquante jusqu ici. Le canal n a JAMAIS ete
       re-teste physiquement a ce stade (aucun nouveau ArmRequest), donc le maintien de puissance
       ne doit PAS etre restaure par le seul Reset (AF 3.4bis : interlock sur Cause brute,
       jamais sur l Ack). *)
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'TC-P01-004 : Reset seul ne doit PAS restaurer le maintien (interlock reste sur Cause, AF 3.4bis)');

    (* nouvel essai : cause toujours presente (canal toujours colle) -> doit re-alarmer (TC-P01-009) -- +1 cycle *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'un nouveau front ArmRequest doit relancer TestA');

    ADVANCE_TIME(200000000);
