(* =======================================================================
   📐 FB_DriftGuard — Détection de dérive de position sous armement
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Capture position de référence et détection de dérive anormale
   📄 Doc métier : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md
   🔌 Interface : Brique interne de sécurité (compose FB_Safety_Winch)
   🔒 Sécurité : Détection de mouvement non commandé et glissement
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_DriftGuard
VAR_INPUT
    // === COMMANDES ET SEUILS ===
    Arm                             : BOOL;                           // --> [CMD] Condition d'armement de la surveillance
    PositionM                       : REAL;                           // --> [HW] Position courante a surveiller (m)
    ToleranceM                      : REAL;                           // --> [CFG] Tolerance de derive maximale autorisee (m)
END_VAR
VAR_OUTPUT
    // === MESURES ET ETATS ===
    RefPosM                         : REAL;                           // <-- [DIAG] Position de reference capturee a l'armement (m)
    DriftM                          : REAL;                           // <-- [DIAG] Derive absolue courante (m)
    Violation                       : BOOL;                           // <-- [STAT] Alarme derive maximale depassee
END_VAR
VAR
    // === VARIABLES LOCALES INTERNES ===
    WasArmed                        : BOOL;                           // . [LOC] Memoire etat armement cycle precedent
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_DriftGuard) ===

IF Arm THEN
    IF NOT WasArmed THEN
        RefPosM := PositionM;   // Capture au 1er cycle armé uniquement
        WasArmed := TRUE;
    END_IF;
    DriftM := ABS(PositionM - RefPosM);
    Violation := DriftM > ToleranceM;
ELSE
    WasArmed := FALSE;
    DriftM := 0.0;
    Violation := FALSE;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   🔁 FB_Filter_PT1 — Filtre passe-bas premier ordre (PT1 numérique)
   ───────────────────────────────────────────────────────────────
   📄 Extrait depuis le projet CODESYS (Device.export, JOYSTICK/)
   🎯 Filtre exponentiel discret : y[k] = α·x[k] + (1-α)·y[k-1]
      où α = CycleTimeS / (T + CycleTimeS), T = TimeConst en secondes.
   ⚠️ Si TimeConst = 0 ou CycleTimeS = 0, sortie = entrée (pass-through).
   ═══════════════════════════════════════════════════════════════
   📄 Docs : DOC/AF_Partie-08_Fonction_Joystick_v2.0.md
*)

FUNCTION_BLOCK FB_Filter_PT1
VAR_INPUT
    /// Consigne brute entrée
    ValueIn    : REAL;
    /// Constante de temps du filtre
    TimeConst  : TIME;
    /// Temps de cycle réel en secondes
    CycleTimeS : REAL;
END_VAR
VAR_OUTPUT
    /// Consigne filtrée sortie
    ValueOut : REAL;
END_VAR
VAR
    T     : REAL;
    Alpha : REAL;
END_VAR

T := TIME_TO_REAL(TimeConst) / 1000.0; // ms → s

IF T <= 0.0 OR CycleTimeS <= 0.0 THEN
    ValueOut := ValueIn;
ELSE
    Alpha    := CycleTimeS / (T + CycleTimeS);
    ValueOut := Alpha * ValueIn + (1.0 - Alpha) * ValueOut;
END_IF;

// ═══════════════════════════════════════════════════════════════
// 🧪 FB_TranslationTestRuntime — Cycle de vie protégé Translation M3
// ───────────────────────────────────────────────────────────────
// 🎯 Responsabilité UNIQUE : posséder le lifecycle atomique du run :
//    IDLE → RUN → CLEANUP → WAIT_NEUTRAL → VERIFY → TERMINAL.
// 🔒 Aucun terminal n'est publié avant neutralité confirmée.
// ═══════════════════════════════════════════════════════════════

FUNCTION_BLOCK PUBLIC FB_TranslationTestRuntime
VAR_INPUT
    Start   : BOOL;
    Abort   : BOOL;
    CaseId  : INT;
    PlanConfigError         : BOOL;
    PlanConfigErrorStepId   : INT;
    PlanConfigErrorCheckIdx : INT;
    PlanConfigErrorMessage  : STRING(160);
    SimulationModeActive    : BOOL;
    SimGateOk               : BOOL;
    NeutralConfirmed        : BOOL; // Neutralité réellement appliquée au scan précédent
    WatchdogLimitMs         : DINT := 180000; // Paramétrable pour autotest du framework
    CleanupTimeoutScans     : INT := 20;      // Délai max de confirmation du neutre
END_VAR
VAR_IN_OUT
    StepTable  : ARRAY[1..GVL_PLC_Tests_Const.MaxSteps]      OF ST_TestStepConfig;
    CheckTable : ARRAY[1..GVL_PLC_Tests_Const.MaxChecks]     OF ST_TestCheckConfig;
    CaseTable  : ARRAY[1..GVL_PLC_Tests_Const.MaxTestCases]  OF ST_TestCaseConfig;
    ProbeBool  : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeBool]  OF BOOL;
    ProbeDint  : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeDint]  OF DINT;
    ProbeReal  : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeReal]  OF REAL;
    Report     : ST_TestSuiteReport;
    Result     : ST_TranslationTestResult;
END_VAR
VAR_OUTPUT
    Busy                : BOOL;
    Done                : BOOL;
    AnyFailed           : BOOL;
    ActiveStimulusId    : INT;
    StepElapsed         : TIME;
    TerminalState       : E_TestTerminalState;
    ConfigError         : BOOL;
    ConfigErrorStepId   : INT;
    ConfigErrorCheckIdx : INT;
    ErrorCode           : INT;
    ErrorMessage        : STRING(160);
    StartRejected       : BOOL; // Impulsion : Start reçu hors IDLE/TERMINAL
    CleanupRequest      : BOOL; // Niveau : imposer le vecteur neutre complet
END_VAR
VAR CONSTANT
    RuntimeIdle        : INT := 0;
    RuntimeRun         : INT := 10;
    RuntimeCleanup     : INT := 20;
    RuntimeWaitNeutral : INT := 30;
    RuntimeVerify      : INT := 40;
    RuntimeTerminal    : INT := 50;
END_VAR
VAR
    instFixture   : FB_TranslationTestFixture;
    instExecutor  : FB_TranslationStepExecutor;
    instFinalizer : FB_TranslationReportFinalizer;
    StartTrig     : R_TRIG;
    RuntimeState  : INT := 0;
    ExecutorStart : BOOL;
    ExecutorAbort : BOOL;
    RunStartPulse : BOOL;
    FinalizePulse : BOOL;
    PendingTerminalState : E_TestTerminalState;
    PendingErrorCode     : INT;
    PendingErrorMessage  : STRING(160);
    SuiteElapsed         : TIME;
    NeutralWaitScans     : INT;
    CleanupElapsedScans  : INT;
END_VAR
// === IMPLEMENTATION ===
StartTrig(CLK := Start);
StartRejected := FALSE;
ExecutorStart := FALSE;
ExecutorAbort := FALSE;
RunStartPulse := FALSE;
FinalizePulse := FALSE;
CleanupRequest := (RuntimeState = RuntimeCleanup)
               OR (RuntimeState = RuntimeWaitNeutral)
               OR (RuntimeState = RuntimeVerify);

// 🎮 Un Start pendant un run/cleanup est refusé sans modifier le run actif.
IF StartTrig.Q AND RuntimeState <> RuntimeIdle AND RuntimeState <> RuntimeTerminal THEN
    StartRejected := TRUE;
END_IF;

// 🚪 Fixture appelée CHAQUE scan : son R_TRIG interne est ainsi toujours réarmé.
instFixture(CheckRequested := StartTrig.Q,
            SimulationModeActive := SimulationModeActive,
            SimGateOk := SimGateOk);

// 🟢 Nouveau run accepté depuis IDLE ou TERMINAL.
IF StartTrig.Q AND (RuntimeState = RuntimeIdle OR RuntimeState = RuntimeTerminal) THEN
    RunStartPulse := TRUE;
    Done := FALSE;
    SuiteElapsed := T#0s;
    NeutralWaitScans := 0;
    CleanupElapsedScans := 0;
    PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    PendingErrorCode := 0;
    PendingErrorMessage := '';

    IF PlanConfigError THEN
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        PendingErrorCode := 1002;
        PendingErrorMessage := CONCAT('Table invalide : ', PlanConfigErrorMessage);
        RuntimeState := RuntimeCleanup;
    ELSIF CaseId < 0 OR CaseId > 6 THEN
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        PendingErrorCode := 1001;
        PendingErrorMessage := 'CaseId invalide (attendu 0..6)';
        RuntimeState := RuntimeCleanup;
    ELSIF instFixture.FixtureFailed THEN
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_PRECONDITION_FAILED;
        PendingErrorCode := 1010;
        PendingErrorMessage := CONCAT('PRECONDITION_FAILED : ', instFixture.FailReason);
        RuntimeState := RuntimeCleanup;
    ELSE
        ExecutorStart := TRUE;
        RuntimeState := RuntimeRun;
    END_IF;
END_IF;

// 🛡️ Causes de sortie du RUN : watchdog > gate perdue > abort opérateur.
IF RuntimeState = RuntimeRun THEN
    SuiteElapsed := SuiteElapsed + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
    IF SuiteElapsed >= DINT_TO_TIME(WatchdogLimitMs) THEN
        ExecutorAbort := TRUE;
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_WATCHDOG_TIMEOUT;
        PendingErrorCode := 1020;
        PendingErrorMessage := 'Watchdog suite Translation expire';
    ELSIF NOT SimulationModeActive OR NOT SimGateOk THEN
        ExecutorAbort := TRUE;
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_PRECONDITION_FAILED;
        PendingErrorCode := 1011;
        PendingErrorMessage := 'Gate Translation perdue pendant le run';
    ELSIF Abort THEN
        ExecutorAbort := TRUE;
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_ABORTED;
        PendingErrorCode := 1030;
        PendingErrorMessage := 'Abandon operateur';
    END_IF;
END_IF;

// 🪜 L'exécuteur ne possède que les étapes, jamais le terminal public.
instExecutor(
    Start := ExecutorStart,
    Abort := ExecutorAbort,
    CaseId := CaseId,
    StepTable := StepTable,
    CheckTable := CheckTable,
    CaseTable := CaseTable,
    ProbeBool := ProbeBool,
    ProbeDint := ProbeDint,
    ProbeReal := ProbeReal
);

IF RuntimeState = RuntimeRun AND instExecutor.RunDone THEN
    IF PendingTerminalState = E_TestTerminalState.TEST_TERMINAL_NONE THEN
        PendingTerminalState := instExecutor.TerminalState;
        IF instExecutor.ConfigError THEN
            PendingErrorCode := 1003;
            PendingErrorMessage := 'Garde-fou runtime : transition invalide';
        END_IF;
    END_IF;
    RuntimeState := RuntimeCleanup;
    NeutralWaitScans := 0;
END_IF;

// 🧹 Tous les chemins imposent au moins deux scans complets au neutre.
IF RuntimeState = RuntimeCleanup THEN
    CleanupRequest := TRUE;
    NeutralWaitScans := 0;
    CleanupElapsedScans := 0;
    RuntimeState := RuntimeWaitNeutral;
ELSIF RuntimeState = RuntimeWaitNeutral THEN
    CleanupRequest := TRUE;
    NeutralWaitScans := NeutralWaitScans + 1;
    CleanupElapsedScans := CleanupElapsedScans + 1;
    IF NeutralWaitScans >= 2 THEN
        RuntimeState := RuntimeVerify;
    END_IF;
ELSIF RuntimeState = RuntimeVerify THEN
    CleanupRequest := TRUE;
    CleanupElapsedScans := CleanupElapsedScans + 1;
    IF NeutralConfirmed THEN
        FinalizePulse := TRUE;
        RuntimeState := RuntimeTerminal;
        Done := TRUE;
    ELSIF CleanupElapsedScans >= CleanupTimeoutScans THEN
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        PendingErrorCode := 1040;
        PendingErrorMessage := 'Cleanup Translation non confirme';
        FinalizePulse := TRUE;
        RuntimeState := RuntimeTerminal;
        Done := TRUE;
    END_IF;
END_IF;

// 📊 Le rapport consomme directement chaque verdict, même consécutif.
instFinalizer(
    RunStart := RunStartPulse,
    RequestedCaseId := CaseId,
    Busy := (RuntimeState = RuntimeRun),
    StepVerdict := instExecutor.StepVerdict,
    StepId := instExecutor.VerdictStepId,
    StepCaseId := instExecutor.VerdictCaseId,
    StepPassed := instExecutor.VerdictPassed,
    StepFailReason := instExecutor.VerdictFailReason,
    StepFailedCheckIdx := instExecutor.VerdictFailedCheckIdx,
    StepDuration := instExecutor.VerdictDuration,
    StepObservedBool := instExecutor.VerdictObservedBool,
    StepObservedDint := instExecutor.VerdictObservedDint,
    StepObservedReal := instExecutor.VerdictObservedReal,
    Finalize := FinalizePulse,
    TerminalState := PendingTerminalState,
    ErrorCode := PendingErrorCode,
    ErrorMessage := PendingErrorMessage,
    StepTable := StepTable,
    CaseTable := CaseTable,
    Report := Report,
    Result := Result
);

// 📤 Publication : Busy inclut cleanup ; aucun stimulus métier hors RUN.
Busy := (RuntimeState = RuntimeRun)
     OR (RuntimeState = RuntimeCleanup)
     OR (RuntimeState = RuntimeWaitNeutral)
     OR (RuntimeState = RuntimeVerify);
IF RuntimeState = RuntimeRun THEN
    ActiveStimulusId := instExecutor.ActiveStimulusId;
ELSE
    ActiveStimulusId := 0;
END_IF;
StepElapsed := instExecutor.StepElapsed;
TerminalState := Result.TerminalState;
AnyFailed := Result.AnyFailed;
ConfigError := PlanConfigError OR instExecutor.ConfigError;
IF PlanConfigError THEN
    ConfigErrorStepId := PlanConfigErrorStepId;
    ConfigErrorCheckIdx := PlanConfigErrorCheckIdx;
ELSE
    ConfigErrorStepId := instExecutor.ConfigErrorStepId;
    ConfigErrorCheckIdx := 0;
END_IF;
ErrorCode := Result.ErrorCode;
ErrorMessage := Result.ErrorMessage;

(* ═══════════════════════════════════════════════════════════════
   📡 FB_AcquisitionRouter — Sélecteur atomique Réel / Simulé
   ───────────────────────────────────────────────────────────────
   📄 AF06 §2, AF13 §2
   🎯 Reprend strictement le comportement d'aiguillage historique :
      un domaine entier est réel ou simulé, jamais un mélange.
   🛡️ Ce FB ne qualifie ni polarité, ni safety, ni autorisation.
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK FB_AcquisitionRouter
VAR_INPUT
    HwReal : ST_HardwareImage;
    HwSim : ST_HardwareImage;
    SimulationModeActive : BOOL;
    SimWinchActive : BOOL;
    SimTranslationActive : BOOL;
    SimOperatorActive : BOOL;
    SimMachineActive : BOOL;
END_VAR
VAR_OUTPUT
    HwIn : ST_HardwareImage;
    WinchInputSourceChanged : BOOL;
END_VAR
VAR
    WinchInputSourceSimulated : BOOL;
    PreviousWinchInputSourceSimulated : BOOL;
    WinchInputSourceInitialized : BOOL;
END_VAR

(* Le premier cycle mémorise la source sans générer de faux front. *)
WinchInputSourceSimulated := SimulationModeActive AND SimWinchActive;
IF NOT WinchInputSourceInitialized THEN
    PreviousWinchInputSourceSimulated := WinchInputSourceSimulated;
    WinchInputSourceInitialized := TRUE;
    WinchInputSourceChanged := FALSE;
ELSE
    WinchInputSourceChanged := WinchInputSourceSimulated <> PreviousWinchInputSourceSimulated;
    PreviousWinchInputSourceSimulated := WinchInputSourceSimulated;
END_IF;

(* Sélection atomique par domaine : aucune fusion réel/simulation. *)
IF WinchInputSourceSimulated THEN
    HwIn.Winch := HwSim.Winch;
ELSE
    HwIn.Winch := HwReal.Winch;
END_IF;

IF SimulationModeActive AND SimTranslationActive THEN
    HwIn.Translation := HwSim.Translation;
ELSE
    HwIn.Translation := HwReal.Translation;
END_IF;

IF SimulationModeActive AND SimOperatorActive THEN
    HwIn.Operator := HwSim.Operator;
ELSE
    HwIn.Operator := HwReal.Operator;
END_IF;

IF SimulationModeActive AND SimMachineActive THEN
    HwIn.Machine := HwSim.Machine;
ELSE
    HwIn.Machine := HwReal.Machine;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   🧪 PRG_Test_KoboldMaintenance — Tests PLC isolés T81/T82
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF_Partie-04_Mode_SemiAuto_Sequenceur_v2.0.md §3ter
   ⚠️ Programme de qualification MANUELLE : non appelé par MainTask.
      L'opérateur l'appelle temporairement dans une tâche de test, pose TestEnable,
      puis lit Passed/Failed. Aucun accès E/S, aucun ordre machine.
   ═══════════════════════════════════════════════════════════════ *)
PROGRAM PRG_Test_KoboldMaintenance
VAR_INPUT
    TestEnable : BOOL;
    ResetTests : BOOL;
END_VAR
VAR_OUTPUT
    Busy       : BOOL;
    Passed     : BOOL;
    Failed     : BOOL;
    ErrorId    : WORD; (* bit0 Dive valide, bit1 Dive invalide, bit2 Extraction, bit3 défaut extraction *)
END_VAR
VAR
    ResetEdge        : R_TRIG;
    DiveValid        : FB_DiveSearch;
    DiveInvalid      : FB_DiveSearch;
    ExtractionValid  : FB_ExtractionSequence;
    ExtractionInvalid: FB_ExtractionSequence;
    DiveValidStep    : INT;
    DiveInvalidStep  : INT;
    ExtractionStep   : INT;
    DiveKobold       : BOOL;
    DiveMotion       : BOOL;
    DivePosition_M   : REAL;
    InvalidKobold    : BOOL;
    InvalidMotion    : BOOL;
    InvalidPosition_M: REAL;
    ExtractionMotion : BOOL;
    ExtractionClosed : BOOL;
    ExtractionBusy   : BOOL;
    ExtractionPos_M  : REAL;
END_VAR

ResetEdge(CLK := ResetTests);
IF ResetEdge.Q OR NOT TestEnable THEN
    Busy := FALSE; Passed := FALSE; Failed := FALSE; ErrorId := 16#0000;
    DiveValidStep := 0; DiveInvalidStep := 0; ExtractionStep := 0;
    DiveKobold := FALSE; DiveMotion := FALSE; DivePosition_M := 1.0;
    InvalidKobold := FALSE; InvalidMotion := FALSE; InvalidPosition_M := 1.0;
    ExtractionMotion := FALSE; ExtractionClosed := FALSE; ExtractionBusy := FALSE; ExtractionPos_M := 0.0;
ELSE
    Busy := NOT Passed AND NOT Failed;

    (* TC-KM-01 : Kobold hors eau 0 → immersion 1 dans fenêtre → fond 0. *)
    CASE DiveValidStep OF
        0: DiveMotion := FALSE; DiveKobold := FALSE; DivePosition_M := 1.0; DiveValidStep := 1;
        1: DiveMotion := FALSE; DiveKobold := FALSE; DivePosition_M := 1.0; DiveValidStep := 2;
        2: DiveMotion := TRUE;  DiveKobold := FALSE; DivePosition_M := 0.4; DiveValidStep := 3;
        3: DiveMotion := TRUE;  DiveKobold := TRUE;  DivePosition_M := 0.0; DiveValidStep := 4;
        4: DiveMotion := TRUE;  DiveKobold := TRUE;  DivePosition_M := -0.1; DiveValidStep := 5;
        5: DiveMotion := TRUE;  DiveKobold := FALSE; DivePosition_M := -0.2; DiveValidStep := 6;
    END_CASE;

    (* TC-KM-02 : front immersion hors fenêtre → T82 / ErrorId bit1. *)
    CASE DiveInvalidStep OF
        0: InvalidMotion := FALSE; InvalidKobold := FALSE; InvalidPosition_M := 1.0; DiveInvalidStep := 1;
        1: InvalidMotion := FALSE; InvalidKobold := FALSE; InvalidPosition_M := 1.0; DiveInvalidStep := 2;
        2: InvalidMotion := TRUE;  InvalidKobold := FALSE; InvalidPosition_M := 0.4; DiveInvalidStep := 3;
        3: InvalidMotion := TRUE;  InvalidKobold := TRUE;  InvalidPosition_M := 0.7; DiveInvalidStep := 4;
    END_CASE;

    (* TC-KM-03 : fond → fermeture → palier 1 sur 2 m → montée nominale. *)
    CASE ExtractionStep OF
        0: ExtractionMotion := FALSE; ExtractionClosed := FALSE; ExtractionBusy := FALSE; ExtractionPos_M := 0.0; ExtractionStep := 1;
        1: ExtractionMotion := FALSE; ExtractionStep := 2;
        2: ExtractionMotion := TRUE;  ExtractionStep := 3;
        3: ExtractionMotion := TRUE;  ExtractionClosed := FALSE; ExtractionBusy := TRUE; ExtractionStep := 4;
        4: ExtractionMotion := TRUE;  ExtractionClosed := TRUE;  ExtractionBusy := FALSE; ExtractionPos_M := 0.0; ExtractionStep := 5;
        5: ExtractionMotion := TRUE;  ExtractionPos_M := 0.0; ExtractionStep := 6;
        6: ExtractionMotion := TRUE;  ExtractionPos_M := 2.0; ExtractionStep := 7;
    END_CASE;
END_IF;

DiveValid(
    Enable := TestEnable, Reset := FALSE, PowerContactorEngaged := TRUE, Mode := E_Mode.MAINT_N1,
    MotionRequestActive := DiveMotion, MotionDirection := -1, BucketIsOpen := TRUE,
    KoboldImmersed := DiveKobold, M1Position_M := DivePosition_M, M2Position_M := DivePosition_M,
    PositionsValid := TRUE, DiveStartMin_M := 1.0, ImmersionUpper_M := 0.5, ImmersionLower_M := -0.5
);
DiveInvalid(
    Enable := TestEnable, Reset := FALSE, PowerContactorEngaged := TRUE, Mode := E_Mode.MAINT_N1,
    MotionRequestActive := InvalidMotion, MotionDirection := -1, BucketIsOpen := TRUE,
    KoboldImmersed := InvalidKobold, M1Position_M := InvalidPosition_M, M2Position_M := InvalidPosition_M,
    PositionsValid := TRUE, DiveStartMin_M := 1.0, ImmersionUpper_M := 0.5, ImmersionLower_M := -0.5
);
ExtractionValid(
    Enable := TestEnable, Reset := FALSE, PowerContactorEngaged := TRUE, Mode := E_Mode.MAINT_N1,
    MotionRequestActive := ExtractionMotion, MotionDirection := 1, BottomPositionConfirmed := TRUE,
    BucketIsClosed := ExtractionClosed, BucketBusy := ExtractionBusy, BucketError := FALSE,
    WinchSyncError := FALSE, M1Position_M := ExtractionPos_M, M2Position_M := ExtractionPos_M,
    M1MeasuredSpeedValid := TRUE, M2MeasuredSpeedValid := TRUE, PositionsValid := TRUE,
    ControlAscentDistance_M := 2.0
);
ExtractionInvalid(
    Enable := TestEnable, Reset := FALSE, PowerContactorEngaged := TRUE, Mode := E_Mode.MAINT_N1,
    MotionRequestActive := FALSE, MotionDirection := 0, BottomPositionConfirmed := FALSE,
    BucketIsClosed := FALSE, BucketBusy := FALSE, BucketError := FALSE, WinchSyncError := FALSE,
    M1Position_M := 0.0, M2Position_M := 0.0, M1MeasuredSpeedValid := TRUE,
    M2MeasuredSpeedValid := TRUE, PositionsValid := TRUE, ControlAscentDistance_M := 0.0
);

IF DiveValid.BottomTouchConfirmed THEN ErrorId := ErrorId OR 16#0001; END_IF;
IF DiveInvalid.Error AND ((DiveInvalid.ErrorId AND 16#0002) <> 16#0000) THEN ErrorId := ErrorId OR 16#0002; END_IF;
IF (ExtractionValid.ExtractionState = E_ExtractionSequenceState.CONTROL_ASCENT)
   AND ExtractionValid.ForceMinSpeedStep THEN ErrorId := ErrorId OR 16#0004; END_IF;
IF ExtractionValid.ExtractionState = E_ExtractionSequenceState.NOMINAL_ASCENT
   AND ExtractionValid.AscentPermit THEN ErrorId := ErrorId OR 16#0004; END_IF;
IF ExtractionInvalid.Error AND ((ExtractionInvalid.ErrorId AND 16#0008) <> 16#0000) THEN ErrorId := ErrorId OR 16#0008; END_IF;

IF (ErrorId AND 16#000F) = 16#000F THEN
    Passed := TRUE;
    Busy := FALSE;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   🛡️ FB_Encoder_Safety — Bornage physique & relais incohérence redémarrage
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-09_Fonction_Encoder_v2.1.md §3.6/§3.7
                   DOC/AF_Partie-03_Contrats_Composants_v2.1.md
   🎯 Rôle :
      - Bornage absolu [-99.00 ; +99.00] m (CablePosMSafe gelée sur dernière valeur plausible).
      - Relais de HomingSuspect (ErrorId bit1).
      - Expose EncoderIncoherent (= Error) consommé par FB_Modes.
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Encoder_Safety) ===

FUNCTION_BLOCK PUBLIC FB_Encoder_Safety
VAR_INPUT
    Enable           : BOOL;        // Standard
    Reset            : BOOL;        // Acquittement défaut (front) — bit0 uniquement (bit1 suit HomingSuspect, voir §7bis)
    PowerContactorEngaged  : BOOL;        // Standard
    Mode             : E_Mode;      // Standard (contexte, pas encore exploité ce lot)
    CablePosM        : REAL;        // Sortie FB_Encoder_Scale DE CE TREUIL
    HomingSuspect    : BOOL;        // Sortie FB_Encoder_Homing DE CE TREUIL (§3.7, déjà calculé)
    PositionMinM     : REAL := -99.0;  // Bornage physique dur (Partie10 §3.6)
    PositionMaxM     : REAL := 99.0;
    BypassGlobal     : BOOL := FALSE;  // 🌐 Force ErrorId=0, ignore bornage (mise en service)
END_VAR
VAR_OUTPUT
    Ready            : BOOL;
    Busy             : BOOL;
    Done             : BOOL;
    Error            : BOOL;
    ErrorId          : WORD;        // bit0: "Position câble hors plage" - position hors plage physique ; bit1: "Incohérence position boot" - incohérence redémarrage (miroir HomingSuspect)
    State            : E_State;
    StateAtError     : E_State;
    CablePosMSafe    : REAL;        // CablePosM gelée sur dernière valeur plausible si hors plage
    EncoderIncoherent: BOOL;        // = Error — consommé par FB_Modes (refuse SEMI_AUTO)
END_VAR
VAR
    ResetEdge             : R_TRIG;
    ErrorEdge             : R_TRIG;
    LastPlausibleCablePosM: REAL;
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Safety) ===

// 🛑 1. GATE — expose la dernière valeur plausible connue même désactivé
IF NOT Enable THEN
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    State := E_State.DISABLED;
    CablePosMSafe := LastPlausibleCablePosM;
    EncoderIncoherent := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🌐 BYPASS GLOBAL : force ErrorId = 0, ignore bornage et incohérence
IF BypassGlobal THEN
    ErrorId := 16#0000;
END_IF;

// 🔍 3. BORNAGE PHYSIQUE ABSOLU (§3.6) — bit0
IF NOT BypassGlobal AND ((CablePosM < PositionMinM) OR (CablePosM > PositionMaxM)) THEN
    ErrorId := ErrorId OR 16#0001;
ELSE
    ErrorId := ErrorId AND 16#FFFE; (* Auto-clearing dès que la position revient dans la plage valide *)
END_IF;

// 🔍 4. RELAIS INCOHÉRENCE REDÉMARRAGE (§3.7, calculée par FB_Encoder_Homing) — bit1
// Pas d'acquittement ici : la levée se fait via BtnConfirmCoherence/nouveau Home côté
// FB_Encoder_Homing (source), ce FB ne fait QUE relayer l'information pour FB_Modes.
IF NOT BypassGlobal THEN
    IF HomingSuspect THEN
        ErrorId := ErrorId OR 16#0002;
    ELSE
        ErrorId := ErrorId AND 16#FFFD;
    END_IF;
END_IF;

// 🧊 5. GELER SUR DOUTE (§6) — CablePosMSafe ne suit PAS CablePosM si hors plage
IF (ErrorId AND 16#0001) = 16#0000 THEN
    LastPlausibleCablePosM := CablePosM;
END_IF;
CablePosMSafe := LastPlausibleCablePosM;

// 📤 6. SORTIES ÉTAT
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

EncoderIncoherent := Error;
Busy := FALSE;
Done := FALSE;

(* ═══════════════════════════════════════════════════════════════
   🛡️ FB_Safety_Translation — Bloc Safety pour le Translation M3 (EtherCAT)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF/AF_Partie-11_Fonction_Translation_v2.2.md
   Rôle : Surveillance joystick, bus EtherCAT, rotation de phases,
      thermique frein commun, Méca A (vitesse non commandée à l'arrêt),
      Méca B (frein/variateur en mouvement à l'arrêt), et Fdc extrêmes.
   🎯 Invariant : les défauts de communication (bits 0/1/2) ne coupent
      jamais la puissance amont (SafeStop seul) ; seuls les défauts
      physiques (bits 3..7) déclenchent PowerCutOff.
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Safety_Translation
VAR_INPUT
    Enable              : BOOL;        // --> [CMD] Active la surveillance
    Reset               : BOOL;        // --> [CMD] Front acquittement défauts
    PowerContactorEngaged     : BOOL;        // --> [SAFE] Chaîne AU réarmée + conditions globales OK
    Mode                : E_Mode;      // --> [CMD] Mode courant
    JoystickOnline      : BOOL;        // --> [HW] instDiagCanOpen.DeviceJoystick.Online
    JoystickOperational : BOOL;        // --> [HW] instDiagCanOpen.DeviceJoystick.Operational
    HeartbeatIhmOk      : BOOL;        // --> [HW] IHM↔PLC : TRUE après front post-boot, FALSE = perte communication opérateur
    PhaseRotationOk     : BOOL;        // --> [HW] PRG_02_Acquisition.HwIn.Machine.PhaseRotationOk_DI (TRUE = OK)
    BrakeThermalFeedback: BOOL;        // --> [HW] Thermique frein commun M1/M2/M3 (NC, TRUE = surchauffe/perte)

    // 🔌 Spécifique EtherCAT & Capteurs réels
    DriveOnline         : BOOL;        // --> [HW] Status diagnostic communication EtherCAT (Online)
    DriveOperational    : BOOL;        // --> [HW] Status diagnostic communication EtherCAT (Operational)
    DriveStatusWord     : WORD;        // --> [HW] Mot d'état variateur AC600
    DriveActualFreqHz   : REAL;        // --> [HW] Vitesse réelle variateur (Hz)
    BrakeFeedback       : BOOL;        // --> [HW] Retour d'état bobine frein (TRUE = ouvert/desserré)
    BrakeCmd            : BOOL;        // --> [HW] Commande frein
    Direction           : INT;         // --> [CMD] Direction commandée
    LimitSwitchFwd      : BOOL;        // --> [HW] Fin de course extrême avant
    LimitSwitchRev      : BOOL;        // --> [HW] Fin de course extrême arrière
    SensorWordIncoherent: BOOL;        // --> [HW] Mot des 5 capteurs position hors combinaisons valides (FB_Translation_PositionDecoder.Incoherent)

    // 🔧 Bypass des surveillances (GVL_IHM.TranslationM3.Bypass)
    BypassGlobal          : BOOL := FALSE;   // --> [TST] Bypass GLOBAL : ignore TOUTES les surveillances ci-dessous (prioritaire)
    BypassOperatorComm    : BOOL := FALSE;   // --> [TST] Bypass perte communication opérateur
    BypassDriveComm       : BOOL := FALSE;   // --> [TST] Bypass perte communication drive
    BypassPhaseRotation   : BOOL := FALSE;   // --> [TST] Bypass défaut rotation phases
    BypassBrakeThermal    : BOOL := FALSE;   // --> [TST] Bypass surchauffe frein
    BypassMecaB           : BOOL := FALSE;   // --> [TST] Bypass Méca B
    BypassMecaA           : BOOL := FALSE;   // --> [TST] Bypass Méca A
    BypassLimitSwitch     : BOOL := FALSE;   // --> [TST] Bypass butées extrêmes
    BypassSensorIncoherent: BOOL := FALSE;   // --> [TST] Bypass incohérence mot capteurs
    BypassSafety          : BOOL := FALSE;   // --> [TST] Bypass groupé PowerCutOff (BrakeThermal/MecaB/MecaA/LimitSwitch/SensorIncoherent)
    BypassProcess         : BOOL := FALSE;   // --> [TST] Bypass groupé SafeStop seul (OperatorComm/DriveComm/PhaseRotation/ContactorFeedback)
END_VAR
VAR_OUTPUT
    Ready               : BOOL;   // <-- [STAT] FB prêt
    Busy                : BOOL;   // <-- [STAT] FB occupé
    Done                : BOOL;   // <-- [STAT] Action terminée
    Error               : BOOL;   // <-- [STAT] Synthèse défaut
    ErrorId             : WORD;        // <-- [DIAG] bit0: "Perte communication opérateur" - joystick CAN ou heartbeat IHM absent ; bit1: "Perte communication EtherCAT" - perte com EtherCAT ; bit2: "Défaut Rotation Phases" - rotation phases ; bit3: "Surchauffe Frein Translation" - thermique frein ; bit4: "Absence confirmation arrêt (Méca B)" - Méca B (incohérence arrêt) ; bit5: "Mouvement non commandé (Méca A)" - Méca A (mouvement non commandé) ; bit6: "Limite extrême Translation atteinte" - Fdc extrême atteint ; bit7: "Incohérence mot capteurs position" - combinaison des 5 capteurs Trémie/PV/P2/P1/Maintenance hors table valide
    State               : E_State;   // <-- [STAT] Etat courant
    StateAtError        : E_State;   // <-- [DIAG] Etat mémorisé au dernier défaut
    SafeStop            : BOOL;        // <-- [ACT] Décélération rapide (PLC)
    PowerCutOff         : BOOL;        // <-- [ACT] Coup de poing / coupure puissance amont
    ErrorOperatorComm   : BOOL;        // <-- [DIAG] Perte communication opérateur : joystick CAN ou heartbeat IHM (bit0)
    ErrorDriveComm      : BOOL;        // <-- [DIAG] Perte communication EtherCAT variateur (bit1)
    ErrorPhaseRotation  : BOOL;        // <-- [DIAG] Mauvaise rotation de phases (bit2)
    ErrorBrakeThermal   : BOOL;        // <-- [DIAG] Surchauffe thermique frein commun (bit3)
    ErrorMecaB          : BOOL;        // <-- [DIAG] Absence confirmation arrêt (Méca B - bit4)
    ErrorMecaA          : BOOL;        // <-- [DIAG] Mouvement non commandé (Méca A - bit5)
    ErrorLimitSwitch    : BOOL;        // <-- [DIAG] Limite extrême Translation atteinte (bit6)
    ErrorSensorIncoherent: BOOL;       // <-- [DIAG] Incohérence mot capteurs position (bit7)
END_VAR
VAR
    ResetEdge           : R_TRIG;   // . [LOC] Front Reset
    ErrorEdge           : R_TRIG;   // . [LOC] Front Erreur
    TonMecaB            : TON;         // . [LOC] Sécurité à l'arrêt (Méca B)
    TonMecaA            : TON;         // . [LOC] Sécurité mouvement non commandé (Méca A)
    TonLimitSwitchOverrun : TON;       // . [LOC] Surveillance poussée anormale / escalade fin de course
    OverrunCondition    : BOOL;   // . [LOC] Condition escalade fin de course
    PostRampTimeout     : TIME := T#3S;   // . [LOC] Délai Méca B
    UncommandedActiveB  : BOOL;   // . [LOC] Méca B active
    UncommandedActiveA  : BOOL;   // . [LOC] Méca A active
    FirstScanDone       : BOOL;   // . [LOC] Initialisation premier scan
    TonStartupWarmup    : TON;         // . [LOC] Inhibition 3s au boot + effacement auto coms
END_VAR

// === IMPLEMENTATION ===

{region "§1 Gate neutralisation"}
// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    Error := FALSE;
    ErrorId := 16#0000;
    SafeStop := FALSE;
    PowerCutOff := FALSE;
    ErrorOperatorComm := FALSE;
    ErrorDriveComm := FALSE;
    ErrorPhaseRotation := FALSE;
    ErrorBrakeThermal := FALSE;
    ErrorMecaB := FALSE;
    ErrorMecaA := FALSE;
    ErrorLimitSwitch := FALSE;
    ErrorSensorIncoherent := FALSE;
    TonMecaB(IN := FALSE);
    TonMecaA(IN := FALSE);
    TonLimitSwitchOverrun(IN := FALSE);
    TonStartupWarmup(IN := FALSE);
    State := E_State.DISABLED;
    Busy := FALSE; Done := FALSE; Ready := FALSE;
    RETURN;
END_IF;

{endregion}

{region "§1bis Initialisation et bypass global"}
Ready := TRUE;
ResetEdge(CLK := Reset);

// 🧹 Initialisation au premier scan : purge des résidus RAM d'un Online Change / Warm Start et évitement des alarmes transitoires
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

// 🌐 BYPASS GLOBAL : si actif → force ErrorId = 0 et saute toutes les vérifications
// (les bits d'erreur resteraient coincés si on ne les nettoie pas)
IF BypassGlobal THEN
    ErrorId := 16#0000;
    TonMecaB(IN := FALSE);
    TonMecaA(IN := FALSE);
END_IF;

{endregion}

{region "§2 Diagnostics et protections translation"}
// ⚠️ ResetEdge doit être traité même si bypass actif, pour que le reset IHM fonctionne.
// On ne l'exécute que si on n'est PAS en bypass global (sinon ErrorId déjà à 0).
IF NOT BypassGlobal THEN
    // ⏱️ Temporisation 3s de mise en route des bus de terrain au boot (EtherCAT / CANopen / Modbus IHM)
    TonStartupWarmup(IN := Enable, PT := T#3s);

    // 🔍 2. PERTE COMMUNICATION OPÉRATEUR (bit0) — joystick CAN ou heartbeat IHM.
    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassOperatorComm) THEN
        IF (NOT JoystickOnline OR NOT JoystickOperational OR NOT HeartbeatIhmOk) THEN
            ErrorId := ErrorId OR 16#0001;
        ELSE
            ErrorId := ErrorId AND 16#FFFE; (* Effacement auto si la com repasse saine *)
        END_IF;
    ELSIF NOT TonStartupWarmup.Q THEN
        ErrorId := ErrorId AND 16#FFFE; (* Inhibition pendant l'initialisation boot *)
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFFE; END_IF;

    // 🔍 2bis. PERTE ETHERCAT VARIATEUR M3 (bit1)
    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassDriveComm) THEN
        IF (NOT DriveOnline OR NOT DriveOperational) THEN
            ErrorId := ErrorId OR 16#0002;
        ELSE
            ErrorId := ErrorId AND 16#FFFD; (* Effacement auto si l'EtherCAT variateur M3 repasse sain *)
        END_IF;
    ELSIF NOT TonStartupWarmup.Q THEN
        ErrorId := ErrorId AND 16#FFFD; (* Inhibition pendant l'initialisation boot *)
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFFD; END_IF;

    // 🔍 3. MAUVAISE ROTATION DE PHASE (bit2)
    IF NOT (BypassProcess OR BypassPhaseRotation) THEN
        IF NOT PhaseRotationOk THEN
            ErrorId := ErrorId OR 16#0004;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFFB; END_IF;

    // 🔍 3ter. THERMIQUE FREIN COMMUN M1/M2/M3 (bit3)
    IF NOT (BypassSafety OR BypassBrakeThermal) THEN
        IF BrakeThermalFeedback THEN
            ErrorId := ErrorId OR 16#0008;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFF7; END_IF;

    // 🔍 3quater. INCOHÉRENCE À L'ARRÊT (Méca B — bit4)
    IF NOT (BypassSafety OR BypassMecaB) THEN
        IF NOT HeartbeatIhmOk THEN
            UncommandedActiveB := (ABS(DriveActualFreqHz) > 0.5) OR DriveStatusWord.0 OR BrakeFeedback;
        ELSIF (Direction = 0) AND NOT BrakeCmd THEN
            UncommandedActiveB := DriveStatusWord.0 OR BrakeFeedback;
        ELSE
            UncommandedActiveB := FALSE;
        END_IF;
        TonMecaB(IN := UncommandedActiveB, PT := PostRampTimeout);
        IF TonMecaB.Q THEN ErrorId := ErrorId OR 16#0010; END_IF;
    ELSE
        TonMecaB(IN := FALSE);
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFEF; END_IF;

    // 🔍 3quinquies. MOUVEMENT NON COMMANDÉ (Méca A — bit5)
    IF NOT (BypassSafety OR BypassMecaA) THEN
        IF (Direction = 0) AND NOT BrakeCmd THEN
            UncommandedActiveA := ABS(DriveActualFreqHz) > 0.5;
        ELSE
            UncommandedActiveA := FALSE;
        END_IF;
        TonMecaA(IN := UncommandedActiveA, PT := T#1S);
        IF TonMecaA.Q THEN ErrorId := ErrorId OR 16#0020; END_IF;
    ELSE
        TonMecaA(IN := FALSE);
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFDF; END_IF;

    // 🔍 3sexies. SURVEILLANCE ESCALADE FIN DE COURSE (bit6)
    IF (BypassSafety OR BypassLimitSwitch) THEN
        // Nettoie le bit 6 résiduel (posé avant activation du bypass)
        ErrorId := ErrorId AND 16#FFBF;
        TonLimitSwitchOverrun(IN := FALSE);
    ELSE
        // 🧱 L'erreur 64 (escalade / poussée anormale en butée) ne s'active QUE SI :
        // 1. On est sur le capteur Trémie (LimitSwitchFwd) ET qu'on continue d'insister en Marche Avant (Direction = 1) avec vitesse/commande variateur active.
        // 2. OU qu'on est sur le capteur Maintenance (LimitSwitchRev) ET qu'on continue d'insister en Marche Arrière (Direction = -1) avec vitesse/commande variateur active.
        OverrunCondition := (LimitSwitchFwd AND (Direction = 1) AND (ABS(DriveActualFreqHz) > 0.5 OR DriveStatusWord.0))
                         OR (LimitSwitchRev AND (Direction = -1) AND (ABS(DriveActualFreqHz) > 0.5 OR DriveStatusWord.0));

        TonLimitSwitchOverrun(IN := OverrunCondition, PT := T#1S500MS);

        IF TonLimitSwitchOverrun.Q THEN
            ErrorId := ErrorId OR 16#0040; // Défaut escalade confirmé (coupure puissance amont)
        ELSE
            // Si la poussée dans le mauvais sens cesse (ou si on repart en arrière), le défaut s'auto-efface
            ErrorId := ErrorId AND 16#FFBF;
        END_IF;
    END_IF;

    // 🔍 3septies. INCOHÉRENCE MOT CAPTEURS POSITION (bit7)
    IF (BypassSafety OR BypassSensorIncoherent) THEN
        // Nettoye le bit 7 résiduel
        ErrorId := ErrorId AND 16#FF7F;
    ELSE
        IF SensorWordIncoherent THEN
            ErrorId := ErrorId OR 16#0080;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FF7F; END_IF;

END_IF; // fin IF NOT BypassGlobal

{endregion}

{region "§4 Arbitrage sorties et etat"}
// 📤 4. ARBITRAGE DES SORTIES MAÎTRESSES
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

SafeStop := Error OR NOT PowerContactorEngaged;

// PowerCutOff actif si thermique frein (bit3), incohérence arrêt (bit4),
// mouvement non commandé (bit5), dépassement de fin de course (bit6),
// ou incohérence mot capteurs position (bit7)
PowerCutOff := (ErrorId AND 16#00F8) <> 16#0000;

// Décapsulage du bitfield ErrorId pour l'IHM
ErrorOperatorComm   := (ErrorId AND 16#0001) <> 16#0000;
ErrorDriveComm      := (ErrorId AND 16#0002) <> 16#0000;
ErrorPhaseRotation  := (ErrorId AND 16#0004) <> 16#0000;
ErrorBrakeThermal   := (ErrorId AND 16#0008) <> 16#0000;
ErrorMecaB          := (ErrorId AND 16#0010) <> 16#0000;
ErrorMecaA          := (ErrorId AND 16#0020) <> 16#0000;
ErrorLimitSwitch    := (ErrorId AND 16#0040) <> 16#0000;
ErrorSensorIncoherent := (ErrorId AND 16#0080) <> 16#0000;

Busy := FALSE;
Done := FALSE;

// 🚦 5. STATE MACHINE (phase diagnostic)
State := E_State.READY;


{endregion}

SETUP
VAR
    fb : FB_SAFETY_EMERGENCYMANAGEMENT;
END_VAR
END_SETUP

(* TC-P01-002 est classee SITE+AUTO dans l AF (mixte). Ce test ne couvre QUE la partie AUTO
   (commande logicielle) : preuve qu un seul canal est coupe a la fois et que le FB interprete
   correctement le retour de boucle fourni en entree. Il ne peut PAS prouver que la coupure
   physique de MaintainA/B_RQ ouvre reellement la boucle materielle -- ca reste une verification
   SITE, sur l automate reel, jamais automatisable en logiciel. *)
TEST 'TC-P01-002 (partie AUTO) chaque canal est commande independamment, l autre reste maintenu'
    (* demarrage + regime etabli, sain *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'hors defaut, canal A maintenu');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'hors defaut, canal B maintenu');

    (* front ArmRequest -> TestA (step 1) : SEUL le canal A doit se couper *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'front doit lancer TestA');
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'TestA : canal A seul doit se couper');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'TestA : canal B ne doit PAS etre affecte');

    (* 200ms plus tard : la boucle reagit reellement a la coupure de A (preuve physique reelle) *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := FALSE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 2, 'TestA reussi (boucle a reagi) -> RestoreA');
    ASSERT_FALSE(fb.ERROR, 'pas de defaut si le canal reagit correctement au test');
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'canal A restaure immediatement apres son test');

    (* 200ms plus tard : boucle refermee (A restaure) -> passage a TestB (step 3) *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 3, 'RestoreA reussi -> TestB');
    ASSERT_FALSE(fb.MAINTAINB_RQ, 'TestB : canal B seul doit se couper');
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'TestB : canal A ne doit PAS etre affecte');

    (* 200ms plus tard : boucle reagit a la coupure de B *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := FALSE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 4, 'TestB reussi -> RestoreB');
    ASSERT_FALSE(fb.ERROR, 'pas de defaut si le canal B reagit correctement au test');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'canal B restaure immediatement apres son test');
END_TEST

