(* ═══════════════════════════════════════════════════════════════
   🌉 FB_CfgPersistBridge_BucketCfg — Pont persistance générique pour ST_BucketCfg
   ───────────────────────────────────────────────────────────────
   🎯 Voir FB_CfgPersistBridge_SyncCfg.st (Lot 3a) pour la logique de référence — identique,
   seul le type ST_BucketCfg change. La copie struct-à-struct gère aussi le sous-struct imbriqué
   Config : ST_BucketConfig automatiquement (pas de traitement spécial nécessaire).
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK FB_CfgPersistBridge_BucketCfg
VAR_IN_OUT
    Hmi     : ST_BucketCfg; (* 🖥️ ex. GVL_IHM.M2TreuilBenne.Bucket.Cfg *)
    Persist : ST_BucketCfg; (* 💾 ex. GVL_PERSISTENT._BucketCfgPersist *)
END_VAR
VAR_OUTPUT
    JustRestored : BOOL;
END_VAR

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

// ═══════════════════════════════════════════════════════════════
// 🧪 E_TestFailReason — Raisons d'échec du test
// ═══════════════════════════════════════════════════════════════

TYPE E_TestFailReason :
(
    FAIL_NONE           := 0,
    FAIL_TIMEOUT        := 1,  // TimeoutPT écoulé sans pass (couvre "trop tard")
    FAIL_CHECK          := 2,  // CHECK_INSTANT faux, ou NEVER_DURING violé
    FAIL_INVARIANT      := 3,  // Invariant multi-étapes violé (voir FailedInvariantId)
    FAIL_WINDOW_EARLY   := 4,  // Pass survenu AVANT MinPT (réaction trop rapide = anormale)
    FAIL_ABORTED        := 5   // Abort commandé ou gate simulation perdu
);
END_TYPE

// ═══════════════════════════════════════════════════════════════
// 🧪 E_TestCheckMode — Mode d'évaluation des checks
// ═══════════════════════════════════════════════════════════════

TYPE E_TestCheckMode :
(
    CHECK_INSTANT      := 0,  // Vérité exigée au 1er cycle d'évaluation de l'étape (fail sinon)
    CHECK_WAIT_UNTIL   := 1,  // Attendre que ça devienne vrai, tenu StablePT en continu (T#0s = immédiat), borné par TimeoutPT d'étape
    CHECK_INVARIANT    := 2,  // Doit rester vrai CHAQUE cycle de la fenêtre — fail immédiat à la 1re violation
    CHECK_NEVER_DURING := 3   // Ne doit JAMAIS devenir vrai — pass à l'expiration du TimeoutPT d'étape (= la fenêtre)
);
END_TYPE

