(* =======================================================================
   🛡️ FB_Encoder_Safety — Bornage physique & surveillance cohérence
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Bornage physique absolu [-99; +99]m et relais d'incohérence redémarrage
   🔒 Polarité : EncoderIncoherent=TRUE en cas de hors bornes ou HomingSuspect
   🛡️ Sécurité : Verrouillage de la position câble sûre
   📄 Doc métier : DOC/AF/AF_Partie-09_Fonction_Encoder_v2.1.md
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_Encoder_Safety
VAR_INPUT
    // === COMMANDES & AUTORISATIONS ===
    Enable                : BOOL;        // --> [CMD] Autorisation generale FB (TRUE=Autorise)
    Reset                 : BOOL;        // --> [CMD] Acquittement defaut (front montant)

    // === CONTEXTE & ETAT PUISSANCE ===
    PowerContactorEngaged : BOOL;        // --> [HW]  Ligne puissance enclenchee
    Mode                  : E_Mode;      // --> [CMD] Mode d'exploitation actif

    // === MESURES & ALERTE HOMING ===
    CablePosM             : REAL;        // --> [HW]  Position calculee (m, sortie FB_Encoder_Scale)
    HomingSuspect         : BOOL;        // --> [SAFE] Alerte incoherence redemarrage (FB_Encoder_Homing)

    // === REGLAGES & BORNES PHYSIQUES ===
    PositionMinM          : REAL := -99.0; // --> [CFG] Plafond bornage physique bas (m)
    PositionMaxM          : REAL := 99.0;  // --> [CFG] Plafond bornage physique haut (m)

    // === TESTS & BYPASS ===
    BypassGlobal          : BOOL := FALSE; // --> [TST] Neutralisation defaut de bornage pour mise en service
END_VAR
VAR_OUTPUT
    // === ETATS IEC & SYNOPTIQUE ===
    Ready                 : BOOL;        // <-- [STAT] FB pret a fonctionner
    Busy                  : BOOL;        // <-- [STAT] FB en cours de traitement
    Done                  : BOOL;        // <-- [STAT] Traitement termine
    Error                 : BOOL;        // <-- [STAT] Synthese defaut (ErrorId <> 0)
    ErrorId               : WORD;        // <-- [DIAG] Code defaut (bit0: Bornes, bit1: Boot suspect)
    State                 : E_State;     // <-- [STAT] Etat courant du FB
    StateAtError          : E_State;     // <-- [DIAG] Etat courant lors du dernier defaut

    // === MESURES SURE & SECURITE ===
    CablePosMSafe         : REAL;        // <-- [DIAG] Position cable instantanee transmise (m)
    EncoderIncoherent     : BOOL;        // <-- [SAFE] Incoherence ou hors bornes (TRUE = defaut)
END_VAR
VAR
    // === DETECTEURS DE FRONT ===
    ResetEdge             : R_TRIG;      // . [LOC] Detecteur front montant Reset
    ErrorEdge             : R_TRIG;      // . [LOC] Detecteur front montant Error
END_VAR

{region "§1 Gate"}
// 🛑 1. GATE
IF NOT Enable THEN
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    State := E_State.DISABLED;
    CablePosMSafe := CablePosM;
    EncoderIncoherent := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;
{endregion}

{region "§2 Reset front"}
// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);
{endregion}

{region "§3 Bypass global"}
// 🌐 3. BYPASS GLOBAL
IF BypassGlobal THEN
    ErrorId := 16#0000;
END_IF;
{endregion}

{region "§4 Surveillance bornage"}
// 🔍 4. SURVEILLANCE BORNAGE PHYSIQUE ABSOLU (bit0)
IF NOT BypassGlobal AND ((CablePosM < PositionMinM) OR (CablePosM > PositionMaxM)) THEN
    ErrorId := ErrorId OR 16#0001;
ELSE
    ErrorId := ErrorId AND 16#FFFE; (* Auto-clearing dès retour dans la plage *)
END_IF;
{endregion}

{region "§5 Relais incohérence redémarrage"}
// 🔍 5. RELAIS INCOHÉRENCE REDÉMARRAGE (bit1)
IF NOT BypassGlobal THEN
    IF HomingSuspect THEN
        ErrorId := ErrorId OR 16#0002;
    ELSE
        ErrorId := ErrorId AND 16#FFFD;
    END_IF;
END_IF;
{endregion}

{region "§6 Transmission mesure"}
// 📏 6. TRANSMISSION DE LA MESURE (Toujours réelle, non figée)
CablePosMSafe := CablePosM;
{endregion}

{region "§7 Sorties état et sécurité"}
// 📤 7. SORTIES ÉTAT & SÉCURITÉ
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

EncoderIncoherent := Error;
Busy := FALSE;
Done := FALSE;
{endregion}

(* =======================================================================
   🧩 FB_FbStatus — Socle de statut standard d'un FB métier
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : remplit de façon standardisée `Status : ST_FbStatus`
      (warning auto-effacé / défaut laté acquitté, textes IHM prêts).
   🧬 Contrat : tout FB `standard` expose `Status : ST_FbStatus`
      rempli via UNE instance de ce socle → même comportement partout.
   🔒 Sécurité : WarningMask fail-safe (0 = tout fault à acquitter).
      Reset TOUJOURS effectif, jamais conditionné (std §9).
      Interlock toujours sur la cause brute, jamais sur l'acquittement.
   📄 Doc : DOC/STDS/CODE_QUALITY_STANDARDS.md §2quinquies / §9
   ======================================================================= *)

FUNCTION_BLOCK FB_FbStatus
VAR_INPUT
    // === PERMIS & ACQUITTEMENT ===
    Enable          : BOOL;    // --> [CMD] Autorisation générale FB
    Reset           : BOOL;    // --> [CMD] Front acquittement défaut (jamais conditionné, §9)

    // === CAUSES & CLASSIFICATION (producteur = bloc métier) ===
    ErrorIdCause    : WORD;    // --> [HW]  Bits d'erreur ACTIFS (cause brute)
    WarningMask     : WORD;    // --> [CFG] bit=1 → cette erreur est WARNING (auto) ; bit=0 → FAULT (à acquitter)

    // === TEXTES IHM (métier, indexés par bit) ===
    ErrorTexts      : ARRAY[0..15] OF STRING;   // --> [CFG] Textes des erreurs (par bit)
    WarningTexts    : ARRAY[0..15] OF STRING;  // --> [CFG] Textes des warnings (par bit)

    // === CONFIG DISPLAY ===
    RotatePeriod    : TIME := T#1S;   // --> [CFG] Période de rotation texte multi-erreurs
END_VAR
VAR_OUTPUT
    // === ÉTAT & SYNOPTIQUE (forme cible) ===
    Ready           : BOOL;    // <-- [STAT] FB prêt (Enable)
    Status          : ST_FbStatus; // <-- [STAT] Statut complet (mappé 1:1 sur la sortie du bloc)
END_VAR
VAR
    // === SOUS-INSTANCES & MEMOIRES ===
    ResetEdge       : R_TRIG;  // * [INST] Front Reset
    FaultEdge       : R_TRIG;  // * [INST] Front apparition cause fault (ré-alarme)
    RotateTimer     : TON;     // * [INST] Rotation du texte affiché (multi-erreurs)

    // === VARIABLES LOCALES ===
    FaultCause      : WORD;    // . [LOC] bits Fault (cause brute)
    WarningCause    : WORD;    // . [LOC] bits Warning (cause brute)
    ErrorIdLatched  : WORD;    // . [LOC] code fault mémorisé (jusqu'au Reset)
    ErrIdx          : INT;     // . [LOC] index de rotation du texte (multi-erreurs)
    WrnIdx          : INT;     // . [LOC] index texte warning courant (multi-erreurs)
END_VAR

{region "§1 Gate neutralisation"}
// 🛑 1. GATE — Enable = FALSE → statut neutre/sûr
Ready := Enable;
IF NOT Enable THEN
    Status.Busy := FALSE; Status.Done := FALSE;
    Status.Error := FALSE; Status.ErrorId := 0;
    Status.Warning := FALSE; Status.WarningId := 0;
    Status.State := E_State.DISABLED; Status.StateAtError := E_State.DISABLED;
    Status.ResetRequested := FALSE;
    Status.WarningIdTxt := ''; Status.ErrorIdTxt := '';
    ErrorIdLatched := 0; FaultCause := 0; WarningCause := 0;
    RotateTimer(IN := FALSE, PT := RotatePeriod);
    RETURN;
END_IF;
Status.State := E_State.READY;
{endregion}

{region "§2 Classification des causes (exclusivité)"}
// 2. Un bit est exclusivement warning OU fault (jamais les deux, §3bis)
FaultCause   := ErrorIdCause AND (NOT WarningMask);  // bits fault (à acquitter)
WarningCause := ErrorIdCause AND WarningMask;          // bits warning (auto-effacés)
{endregion}

{region "§3 Défaut laté + acquittement"}
// 3. Front Reset : TOUJOURS effectif, jamais conditionné (std §9)
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    ErrorIdLatched := 0;
END_IF;
// 4. Ré-alarme : nouvelle apparition d'un fault non encore acquitté -> relatte
FaultEdge(CLK := (FaultCause <> 16#0000));
IF FaultEdge.Q THEN
    ErrorIdLatched := ErrorIdLatched OR FaultCause;
END_IF;
// 5. Mémoire de l'état au défaut
IF (FaultCause <> 16#0000) THEN
    Status.StateAtError := Status.State;
END_IF;
// 6. Sorties défaut : affiché = laté OU cause courante
Status.ErrorId := ErrorIdLatched OR FaultCause;
Status.Error := (Status.ErrorId <> 16#0000);
Status.ResetRequested := (ErrorIdLatched <> 16#0000);
{endregion}

{region "§4 Warning auto-effacé"}
Status.WarningId := WarningCause;
Status.Warning := (WarningCause <> 16#0000);
{endregion}

{region "§5 Textes IHM + rotation 1s"}
// 8. Sélection du texte : on affiche le texte du bit le plus bas encore présent.
//    S'il y a plusieurs erreurs/warnings, l'affichage tourne toutes les RotatePeriod.
//    (parcours par boucle d'indices -> aucun masque hexa, maintenance simple)
Status.ErrorIdTxt := '';
Status.WarningIdTxt := '';

RotateTimer(IN := (Status.ErrorId <> 0) OR (Status.WarningId <> 0),
            PT := RotatePeriod);
IF RotateTimer.Q THEN
    ErrIdx := (ErrIdx + 1) MOD 16;
    RotateTimer(IN := FALSE, PT := RotatePeriod);
END_IF;

// -- Texte ERROR : index du bit set le plus bas -- 
ErrIdx := 0;
WHILE ErrIdx <= 15 AND (Status.ErrorId = 0 OR (Status.ErrorId AND (2#0000_0000_0000_0001 SHL ErrIdx)) = 0) DO
    ErrIdx := ErrIdx + 1;
END_WHILE;
IF ErrIdx <= 15 THEN
    Status.ErrorIdTxt := ErrorTexts[ErrIdx];
END_IF;

// -- Texte WARNING : index du bit set le plus bas --
WrnIdx := 0;
WHILE WrnIdx <= 15 AND (Status.WarningId = 0 OR (Status.WarningId AND (2#0000_0000_0000_0001 SHL WrnIdx)) = 0) DO
    WrnIdx := WrnIdx + 1;
END_WHILE;
IF WrnIdx <= 15 THEN
    Status.WarningIdTxt := WarningTexts[WrnIdx];
END_IF;
{endregion}

// Busy/Done : conditionneur toujours prêt -> Busy/Done FALSE (usage métier)
Status.Busy := FALSE;
Status.Done := FALSE;

(* ═══════════════════════════════════════════════════════════════
   📥 PRG_01_Inputs_LD — ACQUISITION & QUALIFICATION DES ENTRÉES (LADDER)
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF_Partie-06_Acquisition_Qualification_IO_v2.1.md §1/§4
   ⚙️ Exécuté par la tâche PLC en position 1 (premier programme).
   🎯 Lit les 22 TOR réelles depuis leurs symboles bruts mappés (CSV
       Device_IO_20260729.csv), applique un filtre anti-rebond 20 ms et
       publie :
         • Qualified : ST_InputsQualified  (image qualifiée, lecteur unique
                                            PRG_02_Acquisition_CFC)
         • 14 scalaires legacy             (consommateurs historiques)
   🛡️ Polarité : le nom de chaque entrée dit ce que TRUE signifie. Seuls
       les freins portent InvertLogic := FALSE (REX 2026-08-03 : TRUE =
       frein OUVERT). Aucune autre inversion (contacts NC câblés 1 = sain).
   📄 Converti automatiquement en Ladder Diagram (<LD>) dans CODESYS.
   ═══════════════════════════════════════════════════════════════ *)

PROGRAM PRG_01_Inputs_LD
VAR_OUTPUT
    Qualified : ST_InputsQualified;
    PowerContactorEngaged : BOOL;   // TRUE = contacteur de puissance engagé (NO)
    EmergencyChainClosed  : BOOL;   // TRUE = boucle AU fermée (NC, câblage 1 = sain)
    PhaseRotationOk       : BOOL;   // TRUE = rotation phases correcte (NC)
    BrakeThermalFeedback  : BOOL;   // TRUE = thermique freins M1/M2/M3 OK (NC)
    M1ThermalFeedback     : BOOL;   // TRUE = thermique M1 OK (NC)
    M2ThermalFeedback     : BOOL;   // TRUE = thermique M2 OK (NC)
    M1BrakeFeedback       : BOOL;   // TRUE = frein M1 OUVERT (desserré) — REX 2026-08-03
    M2BrakeFeedback       : BOOL;   // TRUE = frein M2 OUVERT (desserré) — REX 2026-08-03
    M3BrakeFeedback       : BOOL;   // TRUE = frein M3 OUVERT (desserré) — REX 2026-08-03
    M1FwdRevSpeedFeedbackOff : BOOL; // TRUE = contacteurs sens M1 retombés (NO)
    M2FwdRevSpeedFeedbackOff : BOOL; // TRUE = contacteurs sens M2 retombés (NO)
    TopPositionSensor     : BOOL;   // TRUE = position extrême haut libre (NC)
    SlackCableSwitch      : BOOL;   // TRUE = câble M2 tendu (NC)
    KoboldContactFond     : BOOL;   // TRUE = Kobold fond détecté (NO)
END_VAR
VAR
    instPowerContactorEngaged : FB_Input;
    instEmergencyChainClosed  : FB_Input;
    instCtrlPhaseRotation     : FB_Input;
    instBrakeThermalFeedback  : FB_Input;
    instKoboldContactFond     : FB_Input;
    instHydraulicThermalOk    : FB_Input;
    instConveyorInfeedReady   : FB_Input;
    instM1FwdRevSpeedFeedbackOff : FB_Input;
    instM1Thermal             : FB_Input;
    instM1BrakeFeedback       : FB_Input;
    instM2FwdRevSpeedFeedbackOff : FB_Input;
    instM2Thermal             : FB_Input;
    instM2BrakeFeedback       : FB_Input;
    instTopPositionSensor     : FB_Input;
    instSlackCableSwitch      : FB_Input;
    instM3BrakeFeedback       : FB_Input;
    instM3ThermalFeedback     : FB_Input;
    instTranslationPosTremie  : FB_Input;
    instTranslationPosPV      : FB_Input;
    instTranslationPosP2      : FB_Input;
    instTranslationPosP1      : FB_Input;
