END_IF;

(* ═══════════════════════════════════════════════════════════════
   🛑 FB_Brake — Séquence frein à manque de courant (temps physiques)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-10_Fonction_Winch_v2.0.md §3
                   (règles issues de DOC/AF_Partie-04_Mode_SemiAuto_Sequenceur_v2.0.md §4)
   🛠️ Frein à manque de courant : colle au repos (sécurité positive).
   📥 MovementRequested : mouvement demandé par FB_Winch (sens+palier > 0)
   📤 BrakeCmd          : commande bobine frein — TRUE = relâché (alimenté)
   ⏱️ Séquence démarrage : attend fermeture contacteur + magnétisation
      moteur AVANT de relâcher (sinon charge retombe → à-coup).
   ⏱️ Séquence arrêt     : attend décélération/ouverture contacteur AVANT
      de coller (sinon usure/casse mécanique en plein mouvement).
   🔍 Double vérification retour contacteur bobine (ST_ContactorCheck) :
      incohérence commande/retour au-delà de FeedbackTimeout → ErrorId.
   🆕 REX 2026-08-03 (révocation 2026-07-26) : le retour câblé est l'image du CONTACTEUR DE COMMANDE
      (DI = 1 ⟺ frein ouvert). Plus d'inversion à la frontière : ce FB reçoit maintenant un
      signal dans le MÊME sens que `BrakeCmd` en marche saine (TRUE = relâché = ouvert) → le test d'incohérence est `<>`, pas `=`.
      ⚠️ Ce retour n'est PAS une mesure du frein : il détecte un contacteur/bobine défaillant, mais
      pas un frein usé ou qui patine. Le patinage reste couvert par Méca A (dérive codeur,
      FB_Safety_Winch bit7) — pas par ce bloc.
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Brake) ===

FUNCTION_BLOCK PUBLIC FB_Brake
VAR_INPUT
    Enable              : BOOL;                     // Contexte général (comme tout FB) — FALSE = frein collé (sûr)
    Reset               : BOOL;                     // Acquittement défaut (front)
    MovementRequested   : BOOL;                      // TRUE = FB_Winch demande un mouvement (sens+palier actifs)
    ContactorFeedback   : BOOL;                      // Retour frein (PRG_01_Inputs_LD) : TRUE = frein OUVERT (desserré)
                                                       // 🆕 REX 2026-08-03 : même sens que BrakeCmd (TRUE = relâché)
                                                       // → en marche normale les deux sont ÉGAUX ; c'est leur
                                                       //   DIFFÉRENCE qui trahit un contacteur collé (voir §4).
    DelayContactClose   : TIME := T#100ms;            // Temps de fermeture contacteur de puissance
    DelayMagnetise      : TIME := T#300ms;            // Délai magnétisation moteur avant ouverture frein
    DelayMotorDecel     : TIME := T#500ms;            // Délai décélération/ouverture contacteur avant collage frein
    FeedbackTimeout     : TIME := T#1s;               // Délai max cohérence commande/retour frein
    BypassContactorCheck: BOOL;                       // 🧪 TRUE = désactive StuckClosed/StuckOpen (axe simulé,
                                                       // voir GVL_Simulation.SensorMxContactorFeedbackIsReal, passé
                                                       // par l'appelant FB_Winch/FB_Translation — TOUJOURS FALSE réel)
END_VAR
VAR_OUTPUT
    Ready               : BOOL;
    Busy                : BOOL;
    Done                : BOOL;
    Error               : BOOL;
    ErrorId             : WORD;          // bit0: "Défaut engagement frein" - incohérence commande/retour frein (collage ou non-relâche)
    State               : E_State;
    StateAtError        : E_State;
    BrakeCmd            : BOOL;          // Commande sortie bobine frein : TRUE = relâché
    BrakeCommandOpenConfirmed : BOOL;    // TRUE = frein ouvert = commande ouverture confirmée (même sens que ContactorFeedback)
    ContactorCheck      : ST_ContactorCheck;  // Diag détaillé (IHM / FB_Safety_Winch)
END_VAR
VAR
    ResetEdge           : R_TRIG;
    ErrorEdge           : R_TRIG;
    BypassEdge          : R_TRIG;        // 🔑 REX 2026-07-24 : Front montant activation bypass pour réarmement immédiat
    TonMagnetise        : TON;           // Temporisation avant relâche
    TonDecel            : TON;           // Temporisation avant collage
    TonFeedback         : TON;           // Timeout cohérence commande/retour
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Brake) ===

// 🛑 1. GATE — pas d'Enable = frein collé (sécurité positive), aucune temporisation en cours
IF NOT Enable THEN
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    BrakeCmd := FALSE;
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    RETURN;
END_IF;

Ready := TRUE;

// 🔑 2. RESET FRONT — efface le bit dont la cause a disparu
ResetEdge(CLK := Reset);
BypassEdge(CLK := BypassContactorCheck);

// 🛠️ 3. SÉQUENCE TEMPORISÉE (démarrage vs arrêt)
IF MovementRequested THEN
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    TonMagnetise(IN := TRUE, PT := DelayMagnetise + DelayContactClose);
    IF TonMagnetise.Q THEN
        BrakeCmd := TRUE;              // ✅ Contacteur + magnétisation acquis → relâche
        State := E_State.DONE;
    ELSE
        BrakeCmd := FALSE;             // ⏳ Encore collé pendant la magnétisation
        State := E_State.BUSY;
    END_IF;
ELSE
    // 🆕 REX 2026-07-08 : Sécurité positive - fermeture immédiate du frein (collé) dès que les contacteurs de sens s'ouvrent
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    BrakeCmd := FALSE;                 // Fermeture immédiate
    State := E_State.READY;
END_IF;

Busy := (State = E_State.BUSY);
Done := (State = E_State.DONE);

// 🔍 4. DOUBLE VÉRIFICATION RETOUR CONTACTEUR (ST_ContactorCheck)
ContactorCheck.Command := BrakeCmd;
ContactorCheck.Feedback := ContactorFeedback;

// 🆕 REX 2026-08-03 (révocation 2026-07-26) : `ContactorFeedback` est maintenant dans le MÊME sens
// que `BrakeCmd` (TRUE = relâché = frein ouvert). En marche saine les deux sont ÉGAUX → c'est leur
// DIFFÉRENCE qui signale l'incohérence (contacteur collé).
// ⚠️ Le test repasse en `<>` (retour à la logique d'origine pré-2026-07-26).
TonFeedback(IN := (BrakeCmd <> ContactorFeedback), PT := FeedbackTimeout);
IF NOT BypassContactorCheck THEN
    IF TonFeedback.Q THEN
        ContactorCheck.StuckClosed := (BrakeCmd AND NOT ContactorFeedback);            // relâche commandée (BrakeCmd=TRUE), frein reste serré (ContactorFeedback=FALSE)
        ContactorCheck.StuckOpen   := (NOT BrakeCmd AND ContactorFeedback);             // serrage commandé (BrakeCmd=FALSE), frein reste ouvert (ContactorFeedback=TRUE)
        ErrorId := ErrorId OR 16#0001;
    ELSIF ResetEdge.Q THEN
        ContactorCheck.StuckClosed := FALSE;
        ContactorCheck.StuckOpen   := FALSE;
        ErrorId := ErrorId AND 16#FFFE;
    END_IF;
ELSE
    ContactorCheck.StuckClosed := FALSE;
    ContactorCheck.StuckOpen   := FALSE;
    ErrorId := ErrorId AND 16#FFFE;   // Bypass actif : efface/maintient à 0 le bit 0
    IF BypassEdge.Q THEN
        StateAtError := E_State.DISABLED; // Front activation bypass : débloque l'état figé
    END_IF;
END_IF;

// 🧾 5. ARBITRAGE ERROR / STATEATERROR (figé jusqu'à acquittement)
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// 🛡️ 6. SORTIE SÛRE SUR DÉFAUT
IF Error THEN
    BrakeCmd := FALSE;
END_IF;

// 📤 7. CONFIRMATION OUVERTURE FREIN (même sens que ContactorFeedback)
BrakeCommandOpenConfirmed := ContactorFeedback;  (* TRUE = frein ouvert = desserrage confirmé *)

SETUP
VAR
    fb : FB_SAFETY_EMERGENCYMANAGEMENT;
END_VAR
END_SETUP

TEST 'TC-P01-008 PowerCutOffRequest coupe A et B sans armer'
    (* scan 1 : autotest demarrage (1 cycle, boucle saine, contacteur repos) *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);

    (* scan 2 : regime etabli, maintien sain attendu -- +1 cycle automate (10ms) *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'hors defaut, canal A doit etre maintenu');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'hors defaut, canal B doit etre maintenu');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'pas de sequence en cours');

    (* scan 3 : coupure demandee par un metier (Winch/Translation) -- +1 cycle automate *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := TRUE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'PowerCutOffRequest doit couper le canal A');
    ASSERT_FALSE(fb.MAINTAINB_RQ, 'PowerCutOffRequest doit couper le canal B');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'PowerCutOffRequest ne doit jamais declencher une sequence armement');
END_TEST

TEST 'TC-P01-006 canal colle bloque le reamement (echec auto-test)'
    (* scans 1-2 : demarrage + regime etabli, sain *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);

    (* front ArmRequest -> ArmingSeqStep passe a 1 (TestA), boucle encore saine ce scan -- +1 cycle *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'front ArmRequest doit lancer TestA (step 1)');

    (* 200ms plus tard : le canal A est cense etre coupe, mais la boucle reste fermee -> collage *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.ERROR, 'canal colle doit lever une erreur (RedundancyTestFailed)');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'echec auto-test doit ramener la sequence a IDLE');
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'un canal colle bloque aussi le maintien normal (interlock sur Cause brute)');
END_TEST

TEST 'TC-P01-004/009 Reset acquitte l affichage mais re-alarme si la cause persiste'
    (* reproduit l etat "canal colle" de TC-P01-006 -- setup independant, propre a ce test *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.ERROR, 'precondition : canal colle doit avoir leve une erreur');

    (* Reset : doit acquitter l affichage sans redemarrage auto (TC-P01-004) -- +1 cycle *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := TRUE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_FALSE(fb.ERROR, 'Reset doit effacer l affichage du defaut');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'Reset seul ne relance jamais de sequence (pas de redemarrage auto)');

    (* nouvel essai : cause toujours presente (canal toujours colle) -> doit re-alarmer (TC-P01-009) -- +1 cycle *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'un nouveau front ArmRequest doit relancer TestA');

    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.ERROR, 'cause persistante doit re-alarmer au nouvel essai, meme apres Reset');
END_TEST

(* ═══════════════════════════════════════════════════════════════
   🧪 FB_SimBench — Enveloppe unique de simulation pour banc d'essai
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF/AF_Partie-13_Fonction_Simulation_v2.3.md
   
   🎯 Rôle : Compose les 4 blocs de modèle de simulation existants :
      - FB_Sim_Encoder (instM1, instM2)
      - FB_Sim_Translation (instTranslation)
      - FB_Sim_Joystick (instJoystick)
      - FB_Sim_Safety (instSafety)
   
   🔒 Brique réduite : 0 lecture de variable globale en interne.
      Toutes les entrées (commandes, stimuli, HwReal) sont passées en paramètres.
   
   🔴 RÈGLES SÉCURITÉ ET POLARITÉ :
      - Modèle frein M1/M2/M3 : M1_BrakeIsOpen_DI := M1_BrakeCmd (1 = OUVERT).
        Ne JAMAIS faire NOT BrakeCmd !
      - Retours contacteurs M1/M2 : 1 = tous retombés (TRUE quand RelayFwd=0 et RelayRev=0).
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_SimBench
VAR_INPUT
    Enable                     : BOOL;             (* --> [CMD] Activation globale (GVL_Simulation.SimulationModeActive) *)

    // ── Commandes issues de l'automate (Scan N-1 / PRG_07 / PRG_10) ──────────
    M1_RelayFwd                : BOOL;   (* --> [CMD] Sens avant M1 *)
    M1_RelayRev                : BOOL;   (* --> [CMD] Sens arrière M1 *)
    // Les 4 contacteurs de palier participent au retour unique
    // « tous contacteurs retombés » — sans eux, le modèle annonce l'arrêt alors qu'un
    // palier est encore engagé (fausse condition d'armement Méca A).
    M1_SpeedContactor_1        : BOOL;   (* --> [HW] Contacteur palier 1 M1 *)
    M1_SpeedContactor_2        : BOOL;   (* --> [HW] Contacteur palier 2 M1 *)
    M1_SpeedContactor_3        : BOOL;   (* --> [HW] Contacteur palier 3 M1 *)
    M1_SpeedContactor_4        : BOOL;   (* --> [HW] Contacteur palier 4 M1 *)
    M1_SpeedRefPct             : REAL;   (* --> [CMD] Consigne vitesse M1 *)
    M1_StepNumber              : INT;    (* --> [CMD] Palier vitesse courant M1 (1..5) *)
    M1_PresetTriggerCmd        : WORD;   (* --> [CMD] Trigger preset M1 *)
    M1_PresetValueOut          : UDINT;   (* --> [CFG] Valeur preset M1 *)
    M1_BrakeCmd                : BOOL;             (* --> [CMD] TRUE = commande desserrage frein M1 *)

    M2_RelayFwd                : BOOL;   (* --> [CMD] Sens avant M2 *)
    M2_RelayRev                : BOOL;   (* --> [CMD] Sens arrière M2 *)
    M2_SpeedContactor_1        : BOOL;   (* --> [HW] Idem M1, voir ci-dessus *)
    M2_SpeedContactor_2        : BOOL;   (* --> [HW] Contacteur palier 2 M2 *)
    M2_SpeedContactor_3        : BOOL;   (* --> [HW] Contacteur palier 3 M2 *)
    M2_SpeedContactor_4        : BOOL;   (* --> [HW] Contacteur palier 4 M2 *)
    M2_SpeedRefPct             : REAL;   (* --> [CMD] Consigne vitesse M2 *)
    M2_StepNumber              : INT;    (* --> [CMD] Palier vitesse courant M2 (1..5) *)
    M2_PresetTriggerCmd        : WORD;   (* --> [CMD] Trigger preset M2 *)
    M2_PresetValueOut          : UDINT;   (* --> [CFG] Valeur preset M2 *)
    M2_BrakeCmd                : BOOL;             (* --> [CMD] TRUE = commande desserrage frein M2 *)

    M3_Direction               : INT;              (* --> [CMD] 1 = Avant, -1 = Arrière, 0 = Arrêt *)
    M3_SpeedRefPct             : REAL;   (* --> [CMD] Consigne vitesse M3 *)
    M3_BrakeCmd                : BOOL;             (* --> [CMD] TRUE = commande desserrage frein M3 *)

    PowerKeepAlive_A           : BOOL;             (* --> [SAFE] TRUE = relais A maintenu sagement par le PLC *)
    PowerKeepAlive_B           : BOOL;             (* --> [SAFE] TRUE = relais B maintenu sagement par le PLC *)
    EmergencyArming_RQ         : BOOL;             (* --> [CMD] Impulsion de réarmement puissance *)

    // ── Stimuli & Paramètres de banc ─────────────────────────────────────────
    SimEncoderSpeedFactor      : REAL := 1.0;   (* --> [CFG] Facteur vitesse codeur *)
    SimSyncDeviationInjectM1   : BOOL := FALSE;   (* --> [TST] Injection écart synchro M1 *)
    SimSyncDeviationInjectM2   : BOOL := FALSE;   (* --> [TST] Injection écart synchro M2 *)
    SimSyncDeviationOffset_M   : REAL := 0.5;   (* --> [TST] Offset écart synchro *)

    SimM3SensorsWordOverrideActive : BOOL := FALSE;   (* --> [TST] Override mot capteurs M3 *)
    SimM3SensorsWord               : BYTE := 16#07;   (* --> [TST] Mot capteurs M3 forcé *)

    SimJoystickLeft_Rev_TREMIE_Active  : BOOL := FALSE;   (* --> [TST] Bouton joystick gauche *)
    SimJoystickRight_Fwd_MAINT_Active  : BOOL := FALSE;   (* --> [TST] Bouton joystick droite *)
    SimJoystickFwd_Up_Close_Active     : BOOL := FALSE;   (* --> [TST] Bouton joystick avant *)
    SimJoystickRev_Down_Open_Active    : BOOL := FALSE;   (* --> [TST] Bouton joystick arrière *)
    SimJoystickRawX                    : INT := 5000;   (* --> [TST] Valeur brute X *)
    SimJoystickRawY                    : INT := 5000;   (* --> [TST] Valeur brute Y *)
    SimJoystickRawButton               : BOOL := FALSE;   (* --> [TST] Bouton homme-mort *)

    SimKoboldContactValue      : BOOL := FALSE;   (* --> [TST] Contact fond Kobold *)
    BtnEmergencyStop           : BOOL := FALSE;    (* --> [TST] Simulation appui coup-de-poing AU *)

    // ── Image réelle fallback ────────────────────────────────────────────────
    HwReal                     : ST_HardwareImage;   (* --> [HW] Image réelle fallback *)
END_VAR

VAR_OUTPUT
    (* Sorties d'état du profil AF_Partie-03 §2.
       En LD, CODESYS réserve la PREMIÈRE broche de sortie au flux du rung :
       `Ready` n'y porte jamais d'expression, les broches suivantes oui. *)
    Ready                      : BOOL;             (* <-- [STAT] TRUE = banc prêt (Enable actif, modèles à jour) *)
    Busy                       : BOOL;             (* <-- [STAT] TRUE = cycle de simulation en cours *)
    Done                       : BOOL;             (* <-- [STAT] TRUE = images de simulation publiées ce scan *)

    Winch                      : ST_HwWinch;   (* <-- [DIAG] Image treuils simulée *)
    Translation                : ST_HwTranslation;   (* <-- [DIAG] Image translation simulée *)
    Operator                   : ST_HwOperator;   (* <-- [DIAG] Image opérateur simulée *)
    Machine                    : ST_HwMachine;   (* <-- [DIAG] Image machine simulée *)
END_VAR

VAR_IN_OUT
    RawPosM1                   : UDINT;            (* <-> [BUS] Mémoire _SimEncoderRawPosM1 dans GVL_PERSISTENT *)
    RawPosM2                   : UDINT;            (* <-> [BUS] Mémoire _SimEncoderRawPosM2 dans GVL_PERSISTENT *)
END_VAR

VAR CONSTANT
    CST_M3FullTravelTimeS       : REAL := 8.0; // Temps de Trémie à Maintenance à 100 %, modèle banc uniquement
END_VAR

VAR
    // Modèles sous-jacents
    instSimEncoderM1           : FB_Sim_Encoder;   (* * [INST] Modèle codeur M1 *)
    instSimEncoderM2           : FB_Sim_Encoder;   (* * [INST] Modèle codeur M2 *)
    instSimTranslation         : FB_Sim_Translation;   (* * [INST] Modèle translation M3 *)
    instSimJoystick            : FB_Sim_Joystick;   (* * [INST] Modèle joystick *)
    instSimSafety              : FB_Sim_Safety;   (* * [INST] Modèle sécurité *)

    // Calculs internes
    M1_PresetCmd               : BOOL;   (* . [LOC] Trigger preset M1 *)
    M2_PresetCmd               : BOOL;   (* . [LOC] Trigger preset M2 *)
    M1_OffsetPts               : DINT;   (* . [LOC] Offset synchro M1 *)
    M2_OffsetPts               : DINT;   (* . [LOC] Offset synchro M2 *)

    M3_RelayFwd                : BOOL;   (* . [LOC] Sens avant M3 *)
    M3_RelayRev                : BOOL;   (* . [LOC] Sens arrière M3 *)

    SimJoystickDirectionCount  : INT;   (* . [LOC] Nombre de directions actives *)

    M3_ActualFreqHz            : UINT;   (* . [LOC] Fréquence simulée M3 *)
    M3_StatusWordSim           : WORD;   (* . [LOC] StatusWord simulé M3 *)
END_VAR

// === IMPLEMENTATION ===

{region "§1 Repli image reelle banc desactive"}
IF NOT Enable THEN
    // 🔌 Banc désactivé : repli sur l'image réelle, aucune simulation en cours
    Ready       := FALSE;
    Busy        := FALSE;
    Done        := FALSE;
    Winch       := HwReal.Winch;
    Translation := HwReal.Translation;
    Operator    := HwReal.Operator;
    Machine     := HwReal.Machine;
    RETURN;
END_IF;

// ▶️ Banc actif : le cycle de simulation démarre pour ce scan
Ready := TRUE;
Busy  := TRUE;
Done  := FALSE;


{endregion}

{region "§2 Simulation treuils M1/M2"}
// ── 1. MODÈLE TREUILS (M1 + M2) ─────────────────────────────────────────────
// Presets codeurs : déclenchés si PresetTriggerCmd = 2
M1_PresetCmd := (M1_PresetTriggerCmd = 2);
M2_PresetCmd := (M2_PresetTriggerCmd = 2);

// Conversions d'injection d'écart synchro (0.5m -> points codeur avec 8192 pts/tour, 2m/tour)
// 1m = 4096 points codeur.
M1_OffsetPts := REAL_TO_DINT(SimSyncDeviationOffset_M * 4096.0);
M2_OffsetPts := REAL_TO_DINT(SimSyncDeviationOffset_M * 4096.0);

// Instance modèle codeur M1
instSimEncoderM1(
    Enable           := TRUE,
    RelayFwd         := M1_RelayFwd,
    RelayRev         := M1_RelayRev,
    StepNumber       := M1_StepNumber,
    PresetCmd        := M1_PresetCmd,
    PresetValue      := M1_PresetValueOut,
    SpeedScaleFactor := SimEncoderSpeedFactor,
    TestOffsetCmd    := SimSyncDeviationInjectM1,
    TestOffsetPts    := M1_OffsetPts,
    RawPos           := RawPosM1
);

// Instance modèle codeur M2
instSimEncoderM2(
    Enable           := TRUE,
    RelayFwd         := M2_RelayFwd,
    RelayRev         := M2_RelayRev,
    StepNumber       := M2_StepNumber,
    PresetCmd        := M2_PresetCmd,
    PresetValue      := M2_PresetValueOut,
    SpeedScaleFactor := SimEncoderSpeedFactor,
    TestOffsetCmd    := SimSyncDeviationInjectM2,
    TestOffsetPts    := M2_OffsetPts,
    RawPos           := RawPosM2
);

// Recopie structures Winch simulées :
// 🛑 POLARITÉ DE FREIN SIMULÉ : 1 = contacteur commandé = frein OUVERT.
// Câblage réel : DI = 1 ⟺ frein OUVERT. Le modèle produit donc M1_BrakeIsOpen_DI := M1_BrakeCmd !
Winch.M1_BrakeIsOpen_DI        := M1_BrakeCmd;
// Retour UNIQUE « tous contacteurs retombés » = sens ET vitesse.
// Omettre les paliers ferait croire à l'arrêt pendant les transitoires → Méca A armée à tort.
Winch.M1_ContactorsReleased_DI := NOT (M1_RelayFwd OR M1_RelayRev
                                    OR M1_SpeedContactor_1 OR M1_SpeedContactor_2
                                    OR M1_SpeedContactor_3 OR M1_SpeedContactor_4);
Winch.M1_ThermalOk_DI          := TRUE; // Sauf panne simulée

Winch.M2_BrakeIsOpen_DI        := M2_BrakeCmd;
Winch.M2_ContactorsReleased_DI := NOT (M2_RelayFwd OR M2_RelayRev
                                    OR M2_SpeedContactor_1 OR M2_SpeedContactor_2
                                    OR M2_SpeedContactor_3 OR M2_SpeedContactor_4);
Winch.M2_ThermalOk_DI          := TRUE;

Winch.M1M2_TopPositionFree_DI  := TRUE; // Butée libre au repos en simu
Winch.M2_TensionedCable_DI     := TRUE; // Câble tendu en simu

Winch.COD1_PosValue            := instSimEncoderM1.RawPosOut;
Winch.COD1_Alarms              := 0;
Winch.COD1_Warnings            := 0;
Winch.COD1_DeviceState         := DEVICE_STATE.RUNNING; // État device RUNNING (bus OK)

Winch.COD2_PosValue            := instSimEncoderM2.RawPosOut;
Winch.COD2_Alarms              := 0;
Winch.COD2_Warnings            := 0;
Winch.COD2_DeviceState         := DEVICE_STATE.RUNNING; // État device RUNNING


{endregion}

{region "§3 Simulation translation M3"}
// ── 2. MODÈLE TRANSLATION M3 (AC600) ─────────────────────────────────────────
M3_RelayFwd := (M3_Direction = 1);
M3_RelayRev := (M3_Direction = -1);

instSimTranslation(
    Enable          := TRUE,
    Direction       := M3_Direction,
    SpeedRefPct     := M3_SpeedRefPct,
    FullTravelTimeS := CST_M3FullTravelTimeS
);

// Remplissage capteurs de position M3 : l'override manuel conserve exactement le
// même ordre que FB_Translation_PositionDecoder (bit4=Trémie ... bit0=Maintenance).
IF SimM3SensorsWordOverrideActive THEN
    Translation.M3_PosTremie_DI      := SimM3SensorsWord.4;
    Translation.M3_PosPV_DI          := SimM3SensorsWord.3;
    Translation.M3_PosPVP2_DI        := SimM3SensorsWord.2;
    Translation.M3_PosP1_DI          := SimM3SensorsWord.1;
    Translation.M3_PosMaintenance_DI := SimM3SensorsWord.0;
ELSE
    Translation.M3_PosTremie_DI      := instSimTranslation.PosTremie;
    Translation.M3_PosPV_DI          := instSimTranslation.PosPV;
    Translation.M3_PosPVP2_DI        := instSimTranslation.PosP2;
    Translation.M3_PosP1_DI          := instSimTranslation.PosP1;
    Translation.M3_PosMaintenance_DI := instSimTranslation.PosMaintenance;
END_IF;

// Polarité frein M3 (1 = OUVERT)
Translation.M3_BrakeIsOpen_DI    := M3_BrakeCmd;

// Thermique moteur/variateur AC600 — pas de panne simulée, toujours OK (comme Winch.M1/M2_ThermalOk_DI)
Translation.M3_ThermalOK_DI      := TRUE;

// Simulation StatusWord AC600 : Bit 0 (Power Ready) = 1, Bit 7 (Comm Ready) = 1 -> 16#0087 en mouvement
// Bit0 retombe à l'arrêt, cohérent avec un variateur qui confirme l'arrêt sans rester "actif" —
// FB_Safety_Translation lit ce bit comme indicateur "mouvement non commandé" (Méca B, TonMecaB 3s) :
// un Bit0 forcé à 1 en continu à l'arrêt déclencherait un PowerCutOff simulé permanent après 3s.
// DrivePowerReady (diagnostic IHM seul, non consommé par un interlock) est le seul autre lecteur,
// aucune régression de mouvement possible.
IF (M3_Direction <> 0) THEN
    M3_StatusWordSim := 16#0087; // + Operating/Running
    M3_ActualFreqHz  := REAL_TO_UINT(M3_SpeedRefPct * 50.0); // 50.0 Hz à 100% (x100 -> 5000)
ELSE
    M3_StatusWordSim := 16#0080; // Comm Ready seul -- Bit0 retombé, arrêt confirmé
    M3_ActualFreqHz  := 0;
END_IF;

Translation.M3_StatusWord        := M3_StatusWordSim;
Translation.M3_ActualFrequencyHz := M3_ActualFreqHz;
Translation.AC600_DeviceState    := DEVICE_STATE.RUNNING; // État device RUNNING


{endregion}

{region "§4 Simulation operateur joystick"}
// ── 3. MODÈLE OPÉRATEUR / JOYSTICK ───────────────────────────────────────────
instSimJoystick(
    Enable     := TRUE,
    NeutralRaw := 5000,
    MaxRaw     := 10000
);

// Les boutons directionnels simplifient les essais : une commande unique impose
// une butée d'axe ; aucune commande ou une combinaison reste au neutre / stimulus avancé.
SimJoystickDirectionCount := BOOL_TO_INT(SimJoystickLeft_Rev_TREMIE_Active)
                           + BOOL_TO_INT(SimJoystickRight_Fwd_MAINT_Active)
                           + BOOL_TO_INT(SimJoystickFwd_Up_Close_Active)
                           + BOOL_TO_INT(SimJoystickRev_Down_Open_Active);
IF SimJoystickDirectionCount = 1 THEN
    IF SimJoystickLeft_Rev_TREMIE_Active THEN
        Operator.JoyXRaw_ANA1 := 0;
        Operator.JoyYRaw_ANA2 := 5000;
    ELSIF SimJoystickRight_Fwd_MAINT_Active THEN
        Operator.JoyXRaw_ANA1 := 10000;
        Operator.JoyYRaw_ANA2 := 5000;
    ELSIF SimJoystickFwd_Up_Close_Active THEN
        Operator.JoyXRaw_ANA1 := 5000;
        Operator.JoyYRaw_ANA2 := 10000;
    ELSE
        Operator.JoyXRaw_ANA1 := 5000;
        Operator.JoyYRaw_ANA2 := 0;
    END_IF;
ELSIF SimJoystickDirectionCount > 1 THEN
    // Deux directions simultanées ne créent jamais une diagonale / un double mouvement implicite.
    Operator.JoyXRaw_ANA1 := 5000;
    Operator.JoyYRaw_ANA2 := 5000;
ELSE
    Operator.JoyXRaw_ANA1 := SimJoystickRawX;
    Operator.JoyYRaw_ANA2 := SimJoystickRawY;
END_IF;

// Homme-mort : stimulus brut amont. En simulation avec boutons directionnels actifs,
// l'appui homme-mort est automatiquement inclus pour faciliter les essais sur banc.
Operator.JoyBtnRaw := SimJoystickRawButton OR (SimJoystickDirectionCount > 0);

Operator.CanBusState      := 2; // CANbusState 2 = ACTIVE
Operator.JOY1_DeviceState := DEVICE_STATE.RUNNING; // État device RUNNING


{endregion}

{region "§5 Simulation securite et image machine"}
// ── 4. MODÈLE SÉCURITÉ & COMMUNS MACHINE ─────────────────────────────────────
instSimSafety(
    Enable           := TRUE,
    PowerCutOff_A    := PowerKeepAlive_A,
    PowerCutOff_B    := PowerKeepAlive_B,
    EmergencyArming  := EmergencyArming_RQ,
    BtnEmergencyStop := BtnEmergencyStop
);

Machine.PowerContactorEngaged_DI   := instSimSafety.SimContactorOk;
Machine.EmergencyChainClosed_DI    := instSimSafety.SimChainOk;
Machine.PhaseRotationOk_DI             := TRUE;
Machine.M1_M2_M3_BrakeThermalOk_DI     := TRUE;
Machine.M1_M2_KoboldBottomTouch_DI     := SimKoboldContactValue;
Machine.HydraulicThermalOk_DI          := TRUE;
Machine.HopperFull_OR_GateRaised_DI    := FALSE; // Pas encore câblé, simulé inactif par défaut

// ✅ Cycle de simulation terminé : les 4 images sont publiées pour ce scan
Busy := FALSE;
Done := TRUE;

{endregion}

(* ═══════════════════════════════════════════════════════════════
   ⚙️ ST_SyncHMI — Données d'échange IHM pour la synchronisation M1/M2
   ───────────────────────────────────────────────────────────────
   📄 Structuration en Cmd / State / Cfg / Bypass , homogène avec ST_WinchHMI.
   ═══════════════════════════════════════════════════════════════ *)
TYPE ST_SyncHMI :
STRUCT
    Cmd    : ST_SyncCmd;
    State  : ST_SyncState;
    Cfg    : ST_SyncCfg;
    Bypass : ST_BypassSync;
END_STRUCT
END_TYPE

(* ═══════════════════════════════════════════════════════════════
   🛡️ FB_Safety_Translation — Bloc Safety pour le Translation M3 (EtherCAT)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : ARCHIVES/Doc/AF_Partie-11_Fonction_Translation_v2.0.md
   🔁 Rôle : Surveillance joystick, bus EtherCAT, rotation de phases, 
      thermique frein commun, Méca A (vitesse non commandée à l'arrêt), 
      Méca B (frein/variateur en mouvement à l'arrêt), et Fdc extrêmes.
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Safety_Translation
VAR_INPUT
    Enable              : BOOL;        // Active la surveillance
    Reset               : BOOL;        // Front acquittement défauts
    PowerContactorEngaged     : BOOL;        // Chaîne AU réarmée + conditions globales OK
    Mode                : E_Mode;      // Mode courant
    JoystickOnline      : BOOL;        // instDiagCanOpen.DeviceJoystick.Online
    JoystickOperational : BOOL;        // instDiagCanOpen.DeviceJoystick.Operational
    HeartbeatIhmOk      : BOOL;        // 💓 IHM↔PLC : TRUE après front post-boot, FALSE = perte communication opérateur
    PhaseRotationOk     : BOOL;        // PRG_02_Acquisition.HwIn.Machine.PhaseRotationOk_DI (TRUE = OK)
    BrakeThermalFeedback: BOOL;        // Thermique frein commun M1/M2/M3 (NC, TRUE = surchauffe/perte)

    // 🔌 Spécifique EtherCAT & Capteurs réels
    DriveOnline         : BOOL;        // Status diagnostic communication EtherCAT (Online)
    DriveOperational    : BOOL;        // Status diagnostic communication EtherCAT (Operational)
    DriveStatusWord     : WORD;        // Mot d'état variateur AC600
    DriveActualFreqHz   : REAL;        // Vitesse réelle variateur (Hz)
    BrakeFeedback       : BOOL;        // Retour d'état bobine frein (TRUE = ouvert/desserré — révocation 2026-08-03)
    BrakeCmd            : BOOL;        // Commande frein
    Direction           : INT;         // Direction commandée
    LimitSwitchFwd      : BOOL;        // Fin de course extrême avant
    LimitSwitchRev      : BOOL;        // Fin de course extrême arrière
    SensorWordIncoherent: BOOL;        // 🆕 REX 2026-07-18 : mot des 5 capteurs position hors combinaisons valides (FB_Translation_PositionDecoder.Incoherent)

    // 🔧 Bypass des surveillances (GVL_IHM.TranslationM3.Bypass)
    BypassGlobal          : BOOL := FALSE;   // 🌐 Bypass GLOBAL : ignore TOUTES les surveillances ci-dessous (prioritaire)
    BypassOperatorComm    : BOOL := FALSE;   // 🎮 Bypass perte communication opérateur
    BypassDriveComm       : BOOL := FALSE;   // 📡 Bypass perte communication drive
    BypassPhaseRotation   : BOOL := FALSE;   // ⚡ Bypass défaut rotation phases
    BypassBrakeThermal    : BOOL := FALSE;   // 🌡️ Bypass surchauffe frein
    BypassMecaB           : BOOL := FALSE;   // 🛑 Bypass Méca B
    BypassMecaA           : BOOL := FALSE;   // 🔄 Bypass Méca A
    BypassLimitSwitch     : BOOL := FALSE;   // 🚧 Bypass butées extrêmes
    BypassSensorIncoherent: BOOL := FALSE;   // 🧭 Bypass incohérence mot capteurs
    BypassSafety          : BOOL := FALSE;   // 🛡️ Bypass groupé PowerCutOff (BrakeThermal/MecaB/MecaA/LimitSwitch/SensorIncoherent)
    BypassProcess         : BOOL := FALSE;   // ⚙️ Bypass groupé SafeStop seul (OperatorComm/DriveComm/PhaseRotation/ContactorFeedback)
END_VAR
VAR_OUTPUT
    Ready               : BOOL;
    Busy                : BOOL;
    Done                : BOOL;
    Error               : BOOL;
    ErrorId             : WORD;        // bit0: "Perte communication opérateur" - joystick CAN ou heartbeat IHM absent ; bit1: "Perte communication EtherCAT" - perte com EtherCAT ; bit2: "Défaut Rotation Phases" - rotation phases ; bit3: "Surchauffe Frein Translation" - thermique frein ; bit4: "Absence confirmation arrêt (Méca B)" - Méca B (incohérence arrêt) ; bit5: "Mouvement non commandé (Méca A)" - Méca A (mouvement non commandé) ; bit6: "Limite extrême Translation atteinte" - Fdc extrême atteint ; bit7: "Incohérence mot capteurs position" - combinaison des 5 capteurs Trémie/PV/P2/P1/Maintenance hors table valide
    State               : E_State;
    StateAtError        : E_State;
    SafeStop            : BOOL;        // 🟧 Décélération rapide (PLC)
    PowerCutOff         : BOOL;        // 🧨 Coup de poing / coupure puissance amont
    ErrorOperatorComm   : BOOL;        // 🎮 Perte communication opérateur : joystick CAN ou heartbeat IHM (bit0)
    ErrorDriveComm      : BOOL;        // 📡 Perte communication EtherCAT variateur (bit1)
    ErrorPhaseRotation  : BOOL;        // ⚡ Mauvaise rotation de phases (bit2)
    ErrorBrakeThermal   : BOOL;        // 🌡️ Surchauffe thermique frein commun (bit3)
    ErrorMecaB          : BOOL;        // 🛑 Absence confirmation arrêt (Méca B - bit4)
    ErrorMecaA          : BOOL;        // 🔄 Mouvement non commandé (Méca A - bit5)
    ErrorLimitSwitch    : BOOL;        // 🚧 Limite extrême Translation atteinte (bit6)
    ErrorSensorIncoherent: BOOL;       // 🧭 Incohérence mot capteurs position (bit7)
END_VAR
VAR
    ResetEdge           : R_TRIG;
    ErrorEdge           : R_TRIG;
    TonMecaB            : TON;         // Sécurité à l'arrêt (Méca B)
    TonMecaA            : TON;         // Sécurité mouvement non commandé (Méca A)
    TonLimitSwitchOverrun : TON;       // 🆕 Surveillance poussée anormale / escalade fin de course
    OverrunCondition    : BOOL;
    PostRampTimeout     : TIME := T#3S;
    UncommandedActiveB  : BOOL;
    UncommandedActiveA  : BOOL;
    FirstScanDone       : BOOL;
    TonStartupWarmup    : TON;         // ⏱️ Inhibition 3s au boot + effacement auto coms
END_VAR

// === IMPLEMENTATION ===

// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    Error := FALSE;
    ErrorId := 16#0000;
    SafeStop := FALSE;
    PowerCutOff := FALSE;
    ErrorOperatorComm := FALSE;
    ErrorDriveComm := FALSE;
    ErrorPhaseRotation := FALSE;
    ErrorBrakeThermal := FALSE;
    ErrorMecaB := FALSE;
    ErrorMecaA := FALSE;
    ErrorLimitSwitch := FALSE;
    ErrorSensorIncoherent := FALSE;
    TonMecaB(IN := FALSE);
    TonMecaA(IN := FALSE);
    TonLimitSwitchOverrun(IN := FALSE);
    TonStartupWarmup(IN := FALSE);
    State := E_State.DISABLED;
    Busy := FALSE; Done := FALSE; Ready := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
ResetEdge(CLK := Reset);

// 🧹 Initialisation au premier scan : purge des résidus RAM d'un Online Change / Warm Start et évitement des alarmes transitoires
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

// 🌐 BYPASS GLOBAL : si actif → force ErrorId = 0 et saute toutes les vérifications
// (les bits d'erreur resteraient coincés si on ne les nettoie pas)
IF BypassGlobal THEN
    ErrorId := 16#0000;
    TonMecaB(IN := FALSE);
    TonMecaA(IN := FALSE);
END_IF;

// ⚠️ ResetEdge doit être traité même si bypass actif, pour que le reset IHM fonctionne.
// On ne l'exécute que si on n'est PAS en bypass global (sinon ErrorId déjà à 0).
IF NOT BypassGlobal THEN
    // ⏱️ Temporisation 3s de mise en route des bus de terrain au boot (EtherCAT / CANopen / Modbus IHM)
    TonStartupWarmup(IN := Enable, PT := T#3s);

    // 🔍 2. PERTE COMMUNICATION OPÉRATEUR (bit0) — joystick CAN ou heartbeat IHM.
    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassOperatorComm) THEN
        IF (NOT JoystickOnline OR NOT JoystickOperational OR NOT HeartbeatIhmOk) THEN
            ErrorId := ErrorId OR 16#0001;
        ELSE
            ErrorId := ErrorId AND 16#FFFE; (* Effacement auto si la com repasse saine *)
        END_IF;
    ELSIF NOT TonStartupWarmup.Q THEN
        ErrorId := ErrorId AND 16#FFFE; (* Inhibition pendant l'initialisation boot *)
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFFE; END_IF;

    // 🔍 2bis. PERTE ETHERCAT VARIATEUR M3 (bit1)
    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassDriveComm) THEN
        IF (NOT DriveOnline OR NOT DriveOperational) THEN
            ErrorId := ErrorId OR 16#0002;
        ELSE
            ErrorId := ErrorId AND 16#FFFD; (* Effacement auto si l'EtherCAT variateur M3 repasse sain *)
        END_IF;
    ELSIF NOT TonStartupWarmup.Q THEN
        ErrorId := ErrorId AND 16#FFFD; (* Inhibition pendant l'initialisation boot *)
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFFD; END_IF;

    // 🔍 3. MAUVAISE ROTATION DE PHASE (bit2)
    IF NOT (BypassProcess OR BypassPhaseRotation) THEN
        IF NOT PhaseRotationOk THEN
            ErrorId := ErrorId OR 16#0004;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFFB; END_IF;

    // 🔍 3ter. THERMIQUE FREIN COMMUN M1/M2/M3 (bit3)
    IF NOT (BypassSafety OR BypassBrakeThermal) THEN
        IF BrakeThermalFeedback THEN
            ErrorId := ErrorId OR 16#0008;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFF7; END_IF;

    // 🔍 3quater. INCOHÉRENCE À L'ARRÊT (Méca B — bit4)
    IF NOT (BypassSafety OR BypassMecaB) THEN
        IF NOT HeartbeatIhmOk THEN
            UncommandedActiveB := (ABS(DriveActualFreqHz) > 0.5) OR DriveStatusWord.0 OR BrakeFeedback;
        ELSIF (Direction = 0) AND NOT BrakeCmd THEN
            UncommandedActiveB := DriveStatusWord.0 OR BrakeFeedback;
        ELSE
            UncommandedActiveB := FALSE;
        END_IF;
        TonMecaB(IN := UncommandedActiveB, PT := PostRampTimeout);
        IF TonMecaB.Q THEN ErrorId := ErrorId OR 16#0010; END_IF;
    ELSE
        TonMecaB(IN := FALSE);
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFEF; END_IF;

    // 🔍 3quinquies. MOUVEMENT NON COMMANDÉ (Méca A — bit5)
    IF NOT (BypassSafety OR BypassMecaA) THEN
        IF (Direction = 0) AND NOT BrakeCmd THEN
            UncommandedActiveA := ABS(DriveActualFreqHz) > 0.5;
        ELSE
            UncommandedActiveA := FALSE;
        END_IF;
        TonMecaA(IN := UncommandedActiveA, PT := T#1S);
        IF TonMecaA.Q THEN ErrorId := ErrorId OR 16#0020; END_IF;
    ELSE
        TonMecaA(IN := FALSE);
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFDF; END_IF;

    // 🔍 3sexies. SURVEILLANCE ESCALADE FIN DE COURSE (bit6)
    IF (BypassSafety OR BypassLimitSwitch) THEN
        // Nettoie le bit 6 résiduel (posé avant activation du bypass)
        ErrorId := ErrorId AND 16#FFBF;
        TonLimitSwitchOverrun(IN := FALSE);
    ELSE
        // 🧱 L'erreur 64 (escalade / poussée anormale en butée) ne s'active QUE SI :
        // 1. On est sur le capteur Trémie (LimitSwitchFwd) ET qu'on continue d'insister en Marche Avant (Direction = 1) avec vitesse/commande variateur active.
        // 2. OU qu'on est sur le capteur Maintenance (LimitSwitchRev) ET qu'on continue d'insister en Marche Arrière (Direction = -1) avec vitesse/commande variateur active.
        OverrunCondition := (LimitSwitchFwd AND (Direction = 1) AND (ABS(DriveActualFreqHz) > 0.5 OR DriveStatusWord.0))
                         OR (LimitSwitchRev AND (Direction = -1) AND (ABS(DriveActualFreqHz) > 0.5 OR DriveStatusWord.0));

        TonLimitSwitchOverrun(IN := OverrunCondition, PT := T#1S500MS);

        IF TonLimitSwitchOverrun.Q THEN
            ErrorId := ErrorId OR 16#0040; // Défaut escalade confirmé (coupure puissance amont)
        ELSE
            // Si la poussée dans le mauvais sens cesse (ou si on repart en arrière), le défaut s'auto-efface
            ErrorId := ErrorId AND 16#FFBF;
        END_IF;
    END_IF;

    // 🔍 3septies. INCOHÉRENCE MOT CAPTEURS POSITION (bit7)
    IF (BypassSafety OR BypassSensorIncoherent) THEN
        // Nettoye le bit 7 résiduel
        ErrorId := ErrorId AND 16#FF7F;
    ELSE
        IF SensorWordIncoherent THEN
            ErrorId := ErrorId OR 16#0080;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FF7F; END_IF;

END_IF; // fin IF NOT BypassGlobal

// 📤 4. ARBITRAGE DES SORTIES MAÎTRESSES
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

SafeStop := Error OR NOT PowerContactorEngaged;

// PowerCutOff actif si thermique frein (bit3), incohérence arrêt (bit4),
// mouvement non commandé (bit5), dépassement de fin de course (bit6),
// ou incohérence mot capteurs position (bit7)
PowerCutOff := (ErrorId AND 16#00F8) <> 16#0000;

// Décapsulage du bitfield ErrorId pour l'IHM
ErrorOperatorComm   := (ErrorId AND 16#0001) <> 16#0000;
ErrorDriveComm      := (ErrorId AND 16#0002) <> 16#0000;
ErrorPhaseRotation  := (ErrorId AND 16#0004) <> 16#0000;
ErrorBrakeThermal   := (ErrorId AND 16#0008) <> 16#0000;
ErrorMecaB          := (ErrorId AND 16#0010) <> 16#0000;
ErrorMecaA          := (ErrorId AND 16#0020) <> 16#0000;
ErrorLimitSwitch    := (ErrorId AND 16#0040) <> 16#0000;
ErrorSensorIncoherent := (ErrorId AND 16#0080) <> 16#0000;

Busy := FALSE;
Done := FALSE;

// 🚦 5. STATE MACHINE (phase diagnostic)
State := E_State.READY;

(* ═══════════════════════════════════════════════════════════════
   📤 FB_Output — Sortie relais + feedback (brique réduite)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-06_Acquisition_Qualification_IO_v2.0.md §2
   🧭 Interface RÉDUITE (Partie3 §1bis) — relais de commande BAS NIVEAU :
      transmet fidèlement `Command` (déjà résolu/rampé par le FB métier
      appelant), ne décide JAMAIS lui-même d'un arrêt de mouvement.
   🔁 Rôle : inversion NO/NC, option blink 1Hz, double vérification
      commande/retour (contacteur collé/absent), diagnostic voie/carte.
   🔴 INTÉGRATION dans Winch/Translation/etc. : PAS encore décidée (choix
      d'architecture en attente — composition interne, remplacerait la
      logique actuelle TonFwdFeedback/ST_ContactorCheck manuelle dans
      FB_Winch/FB_Translation — vs FB_IO générique séparé). Ce fichier
      ne fait QUE créer la brique elle-même.
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Output) ===

FUNCTION_BLOCK PUBLIC FB_Output
VAR_INPUT
    Command         : BOOL;         // Ordre logique, déjà résolu/rampé par le FB métier appelant
    InvertLogic     : BOOL;         // TRUE = NC
    FeedbackRaw     : BOOL;         // Retour d'état actionneur (optionnel)
    UseFeedback     : BOOL;         // Activer le contrôle de rétroaction
    Blink1Hz        : BOOL;         // Option : clignotement 1 Hz (diagnostic/visu)
    FeedbackTimeout : TIME := T#500ms; // Délai max cohérence cmd/retour
    ChannelOk       : BOOL := TRUE;    // Diag voie/carte sortie OK — TRUE par défaut si pas de diag dispo
END_VAR
VAR_OUTPUT
    State       : BOOL;         // Vers la carte de sortie
    FeedbackOk      : BOOL;         // Retour cohérent avec la commande
    Error           : BOOL;
    ErrorId         : WORD;         // bit0: "Feedback sortie incohérent" - feedback incohérent ; bit1: "Défaut matériel sortie (Carte HS)" - voie/carte HS
END_VAR
VAR
    BlinkTimer      : TON;
    BlinkState      : BOOL;
    FeedbackTon     : TON;
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Output) ===

// 1. Inversion NO/NC
State := Command XOR InvertLogic;

// 2. Option blink 1 Hz (diagnostic/visualisation) — modulation à 500ms ON/500ms OFF
IF Blink1Hz AND State THEN
    BlinkTimer(IN := NOT BlinkTimer.Q, PT := T#500ms);
    IF BlinkTimer.Q THEN
        BlinkState := NOT BlinkState;
    END_IF;
    State := BlinkState;
ELSE
    BlinkTimer(IN := FALSE, PT := T#500ms);
    BlinkState := FALSE;
END_IF;

// 3. Double vérification commande/retour (contacteur collé/ne colle pas)
IF UseFeedback THEN
    FeedbackTon(IN := (State <> FeedbackRaw), PT := FeedbackTimeout);
    IF FeedbackTon.Q THEN
        ErrorId := ErrorId OR 16#0001;
        FeedbackOk := FALSE;
    ELSE
        ErrorId := ErrorId AND 16#FFFE;
        FeedbackOk := TRUE;
    END_IF;
ELSE
    FeedbackTon(IN := FALSE, PT := FeedbackTimeout);
    FeedbackOk := TRUE;   // Pas de contrôle demandé — pas d'incohérence à signaler
END_IF;

// 4. Diagnostic voie/carte
IF NOT ChannelOk THEN
    ErrorId := ErrorId OR 16#0002;
ELSE
    ErrorId := ErrorId AND 16#FFFD;
END_IF;

Error := (ErrorId <> 16#0000);

(* =======================================================================
   🛡️ FB_Safety_Winch — Surveillance et sécurité d'un treuil (M1 / M2)
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Protection machine, surveillance codeurs, dérives et interlocks
   📄 Doc métier : DOC/AF/AF_Partie-10_Fonction_Winch_v2.0.md
   🔒 Sécurité : Gestion des autorisations SafeStop, PowerCutOff et permis
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_Safety_Winch
VAR_INPUT
    // === COMMANDES ET ETATS GENERAL ===
    Enable                          : BOOL;                           // --> [CMD] Active la surveillance globale FB
    Reset                           : BOOL;                           // --> [CMD] Front acquittement defauts
    Mode                            : E_Mode;                         // --> [CMD] Mode d'exploitation actif
    SyncEnable                      : BOOL;                           // --> [CMD] Validation synchronisation treuils
    Direction                       : INT;                            // --> [CMD] Consigne active de direction (-1/0/+1)
    MovementCommanded               : BOOL;                           // --> [CMD] Au moins un contacteur de sens commande

    // === ETATS SECOURS ET HARDWARE ===
    PowerContactorEngaged           : BOOL;                           // --> [SAFE] Chaine AU rearmee + puissance OK
    JoystickOnline                  : BOOL;                           // --> [HW] Statut bus CAN Joystick Online
    JoystickOperational             : BOOL;                           // --> [HW] Statut bus CAN Joystick Operational
    HeartbeatIhmOk                  : BOOL;                           // --> [HW] Communication IHM-PLC valide
    EncoderAvailable                : BOOL;                           // --> [HW] Codeur disponible pour ce treuil
    ThermalFeedback                 : BOOL;                           // --> [HW] Retour thermique moteur (NC)
    BrakeThermalFeedback            : BOOL;                           // --> [HW] Retour thermique frein (NC)
    SlackCableDetected              : BOOL;                           // --> [HW] Delecteur mou de cable (NC)
    PhaseRotationOk                 : BOOL;                           // --> [HW] Sens de rotation des phases OK
    TopPositionSensor               : BOOL;                           // --> [HW] Capteur fin de course haut (NC)
    FwdRevSpeedFeedbackOff          : BOOL;                           // --> [HW] Feedback retombe tous contacteurs
    BrakeFeedback                   : BOOL;                           // --> [HW] Feedback frein ouvert
    JoystickYNeutral                : BOOL;                           // --> [HW] Joystick au neutre
    BenneHoldStillActive            : BOOL;                           // --> [HW] Maintien fixe M1 actif pendant benne
    BenneBusy                       : BOOL;                           // --> [HW] Cycle benne actif sur l'autre treuil
    OtherWinchInhibited             : BOOL;                           // --> [HW] Autre treuil inhibe (maintenance)

    // === REGLAGES ET LIMITES SÉCURITÉ ===
    InReferencingMode               : BOOL;                           // --> [CFG] Treuil en cours de homing
    CablePosM                       : REAL;                           // --> [CFG] Position actuelle cable (m)
    CfgCableLimitDescentM           : REAL;                           // --> [CFG] Limite basse physique descente (m)
    LimitLegalReached               : BOOL;                           // --> [CFG] Limite legale de profondeur atteinte
    Homed                           : BOOL;                           // --> [CFG] Treuil reference
    HomingSuspect                   : BOOL;                           // --> [CFG] Referencement suspect
    TopLimitM                       : REAL;                           // --> [CFG] Position limite haute active (m)
    UncommandedSpeedThresholdMps    : REAL := 0.02;                   // --> [CFG] Seuil vitesse non commandee Meca A (m/s)
    UncommandedDriftToleranceM      : REAL := 2.0;                    // --> [CFG] Tolerance derive position Meca A (m)
    PostRampTimeout                 : TIME := T#3s;                   // --> [CFG] Delai attente retombee contacteurs/frein Meca B
    BenneSlipToleranceM             : REAL := 2.0;                    // --> [CFG] Tolerance glissement M1 pendant benne (m)
    ExpectedOtherWinchPosM          : REAL;                           // --> [CFG] Position attendue de l'autre treuil (m)
    CriticalSyncToleranceM          : REAL := 2.5;                    // --> [CFG] Tolerance ecart critique synchro (m)
    MovementSpeedThresholdMps       : REAL := 0.02;                   // --> [CFG] Seuil vitesse mesurable (m/s)
    MeasuredSpeedMps                : REAL;                           // --> [CFG] Mesure absolue vitesse (m/s)
    MeasuredSpeedSignedMps          : REAL;                           // --> [CFG] Mesure signee vitesse (m/s)
    MeasuredSpeedValid              : BOOL;                           // --> [CFG] Mesure vitesse valide
    OppositeDirectionTimeout        : TIME := T#500ms;                // --> [CFG] Delai confirmation sens oppose
    NoMovementTimeout               : TIME := T#3s;                   // --> [CFG] Delai confirmation absence mouvement

    // === BYPASSES ET SIMULATION ===
    EncoderFaultBypass              : BOOL;                           // --> [TST] Bypass defaut codeur
    BypassGlobal                    : BOOL := FALSE;                  // --> [TST] Force ErrorId=0 global
    BypassSafety                    : BOOL := FALSE;                  // --> [TST] Bypass groupe PowerCutOff
    BypassProcess                   : BOOL := FALSE;                  // --> [TST] Bypass groupe SafeStop/Permit
    BypassTopLimitSwitch            : BOOL := FALSE;                  // --> [TST] Bypass individuel fin de course haut capteur
    BypassTopLimitSoftware          : BOOL := FALSE;                  // --> [TST] Bypass individuel fin de course haut logiciel
    BypassCableLimitSwitch          : BOOL := FALSE;                  // --> [TST] Bypass individuel limite basse cable
    BypassLimitLegal                : BOOL := FALSE;                  // --> [TST] Bypass individuel limite legale
    BypassOperatorComm              : BOOL := FALSE;                  // --> [TST] Bypass perte com operateur
    BypassPhaseRotation             : BOOL := FALSE;                  // --> [TST] Bypass defaut rotation phases
    BypassBrakeThermal              : BOOL := FALSE;                  // --> [TST] Bypass surchauffe frein
    BypassMotorThermal              : BOOL := FALSE;                  // --> [TST] Bypass surchauffe moteur
    BypassMecaA                     : BOOL := FALSE;                  // --> [TST] Bypass Meca A
    BypassMecaB                     : BOOL := FALSE;                  // --> [TST] Bypass Meca B
    BypassMecaC                     : BOOL := FALSE;                  // --> [TST] Bypass Meca C
    BypassMecaD                     : BOOL := FALSE;                  // --> [TST] Bypass Meca D
    BypassMecaE                     : BOOL := FALSE;                  // --> [TST] Bypass Meca E
END_VAR
VAR_OUTPUT
    // === ETATS IEC ET SYNOPTIQUE ===
    Ready                           : BOOL;                           // <-- [STAT] FB pret a fonctionner
    // 🧩 Statut transverse (forme cible) — regroupe Busy/Done/Error/ErrorId/State/StateAtError.
    // ErrorId bitmask: bit0: "Perte comms opérateur" ; bit1: "Perte codeur" ; bit2: "Surchauffe moteur" ;
    // bit3: "Mou de câble" ; bit4: "Rotation phases" ; bit5: "Fin de course haut capteur" ;
    // bit6: "Limite max câble" ; bit7: "Méca A" ; bit8: "Méca B" ; bit9: "Méca C" ; bit10: "Thermique frein" ;
    // bit11: "Méca D" ; bit12/13: "Méca E écart synchro" ; bit14: "Sens opposé" ; bit15: "Absence mouvement".
    Status                         : ST_FbStatus;

    // === SORTIES DE SÉCURITÉ ET AUTORISATIONS ===
    SafeStop                        : BOOL;                           // <-- [SAFE] Arret rapide 2 sens (Enable maintenu)
    DescendPermit                   : BOOL;                           // <-- [SAFE] Permis de descente autorise
    AscentPermit                    : BOOL;                           // <-- [SAFE] Permis de montee autorise
    PowerCutOff                     : BOOL;                           // <-- [SAFE] Coupure puissance amont

    // === DIAGNOSTICS ET MESURES ===
    MecaADriftM                     : REAL;                           // <-- [DIAG] Derive mesuree Meca A (m)
    MecaCDriftM                     : REAL;                           // <-- [DIAG] Derive mesuree Meca C (m)
    MecaBElapsedTime                : TIME;                           // <-- [DIAG] Ecoule confirmation contacteurs/frein
END_VAR
VAR
    // === SOUS-INSTANCES FB ===
    DriftGuardA                     : FB_DriftGuard;                  // * [INST] Surveillance derive Meca A
    DriftGuardC                     : FB_DriftGuard;                  // * [INST] Surveillance derive Meca C

    // === DETECTEURS ET TIMERS INTERNES ===
    ResetEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Reset
    ErrorEdge                       : R_TRIG;                         // . [LOC] Detecteur front montant Erreur
    TonMecaB                        : TON;                            // . [LOC] Tempo confirmation arret Meca B
    TonMecaD                        : TON;                            // . [LOC] Tempo arret fin de course haut Meca D
    TonMecaE                        : TON;                            // . [LOC] Tempo confirmation arret synchro Meca E
    TonOppositeDirection            : TON;                            // . [LOC] Tempo confirmation sens oppose
    TonNoMovement                   : TON;                            // . [LOC] Tempo confirmation absence mouvement
    TonMecaStopSettled              : TON;                            // . [LOC] Tempo "arret confirme" Meca A (purge fenetre vitesse)
    TonStartupWarmup                : TON;                            // . [LOC] Tempo masquage transitoire au boot

    // === VARIABLES LOCALES INTERNES ===
    FirstScanDone                   : BOOL;                           // . [LOC] Premier cycle effectue
    MecaB_NoOperatorCmd             : BOOL;                           // . [LOC] Absence commande operateur
    LastInReferencingMode           : BOOL;                           // . [LOC] Memorisation etat homing precedent
    OppositeDirectionActive         : BOOL;                           // . [LOC] Sens oppose confirme actif
    EncoderAvailableEffective       : BOOL;                           // . [LOC] Codeur valide ou bypass effectif
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Safety_Winch) ===

{region "§1 Gate neutralisation"}
// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    // 🔑 RESET effectif même en DISABLE : le gate RETURNe avant le ResetEdge du chemin
    // principal, sinon une cause resterait figée et la machine serait impossible à réarmer
    // (récupération). On traite ici le front Reset pour effacer la cause en mode neutre.
    ResetEdge(CLK := Reset);
    IF ResetEdge.Q THEN
        Status.ErrorId := 16#0000;
    END_IF;
    Ready := FALSE;
    Status.Busy := FALSE;
    Status.Done := FALSE;
    SafeStop := TRUE;
    DescendPermit := FALSE; // 🛡️ Fail-Safe : aucun mouvement permis si Safety désactivé
    AscentPermit := FALSE;  // 🛡️ Fail-Safe : aucun mouvement permis si Safety désactivé
    PowerCutOff := FALSE;
    Status.State := E_State.DISABLED;
    // 🛡️ ErrorId conservé : la cause du dernier défaut reste visible IHM.
    // Error en miroir de cette cause ; les sorties restent fail-safe (lignes ci-dessus).
    Status.Error := (Status.ErrorId <> 16#0000);
    // Force le réarmement (WasArmed→FALSE) via FB_DriftGuard.
    DriftGuardA(Arm := FALSE, PositionM := CablePosM, ToleranceM := UncommandedDriftToleranceM);
    DriftGuardC(Arm := FALSE, PositionM := CablePosM, ToleranceM := BenneSlipToleranceM);
    TonMecaB(IN := FALSE);
    TonMecaD(IN := FALSE);
    TonMecaE(IN := FALSE);
    TonOppositeDirection(IN := FALSE);
    TonNoMovement(IN := FALSE);
    TonStartupWarmup(IN := FALSE);
    RETURN;
END_IF;

Ready := TRUE;
Status.State := E_State.READY;

{endregion}

{region "§2 Initialisation et bypass global"}
// Détecte la fin du référencement pour éviter le pic de vitesse au cycle de transition (offset appliqué)
IF LastInReferencingMode AND NOT InReferencingMode THEN
    DriftGuardA(Arm := FALSE, PositionM := CablePosM, ToleranceM := UncommandedDriftToleranceM);
END_IF;
LastInReferencingMode := InReferencingMode;

// Si le contacteur de puissance est ouvert (PowerContactorEngaged = FALSE), on force les sorties de sécurité
// mais on ne fait pas de RETURN pour permettre le diagnostic et l'acquittement (Reset) des défauts.
IF NOT PowerContactorEngaged THEN
    DriftGuardA(Arm := FALSE, PositionM := CablePosM, ToleranceM := UncommandedDriftToleranceM);
    DriftGuardC(Arm := FALSE, PositionM := CablePosM, ToleranceM := BenneSlipToleranceM);
END_IF;

// 🔑 2. RESET FRONT — efface le bit dont la cause a disparu
ResetEdge(CLK := Reset);

// 🧹 Initialisation au premier scan : évitement des alarmes transitoires au démarrage
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    Status.ErrorId := 16#0000;
    RETURN;
END_IF;

// 🌐 BYPASS GLOBAL : si TRUE, on force ErrorId = 0 ET on saute toute la logique de sécurité
IF BypassGlobal THEN
    Status.ErrorId := 16#0000;
    TonMecaB(IN := FALSE);
    TonMecaD(IN := FALSE);
    TonOppositeDirection(IN := FALSE);
    TonMecaE(IN := FALSE);
END_IF;

{endregion}

{region "§3 Protections immediates position"}
// 🔍 3sexties. FIN DE COURSE HAUT / CAPTEUR DE POSITION HAUTE (anti-débordement) — bit5
// ⚠️ Convention NAMING_CONVENTION.md : TopPositionSensor TRUE = sain/non atteint (NF), FALSE =
// position haute réellement atteinte (contact ouvert). Si la position haute EST atteinte
// (TopPositionSensor=FALSE), qu'on n'est pas en phase de référencement (homing), ET qu'on
// commande un mouvement vers le haut (Direction > 0), alors on lève le défaut.
// SORTI du bloc "IF NOT BypassGlobal" ci-dessous — même doctrine que le blocage réel (§4) :
// BypassGlobal M1/M2 ne doit masquer NI le mouvement NI l'alarme IHM de ces 2 fins de course
// physiques. Seuls BypassProcess (groupé, conscient) ou BypassTopLimitSwitch (individuel)
// peuvent encore éteindre CETTE alarme — exactement comme tous les autres bypass individuels du
// fichier (une alarme ne s'éteint QUE si on a explicitement demandé à ignorer CETTE protection
// précise, jamais via le bypass global qui vise le reste du domaine : Méca A-E, thermique, phase,
// comm, sync, codeur).
IF NOT (BypassProcess OR BypassTopLimitSwitch) AND NOT TopPositionSensor AND NOT InReferencingMode AND (Direction > 0) THEN
    Status.ErrorId := Status.ErrorId OR 16#0020;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFDF;
END_IF;

// 🔍 3septies. LONGUEUR MAX DE CÂBLE (profondeur max autorisée) — bit6
// Sécurité active hors référencement. Si la position de câble descend sous la limite basse
// physique (CablePosM <= CfgCableLimitDescentM), alors on interdit uniquement la descente.
// SORTI du bloc "IF NOT BypassGlobal" — même doctrine que bit5 ci-dessus.
IF NOT (BypassProcess OR BypassCableLimitSwitch) AND (CfgCableLimitDescentM < 0.0) AND (CablePosM <= CfgCableLimitDescentM) AND NOT InReferencingMode THEN
    Status.ErrorId := Status.ErrorId OR 16#0040;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFBF;
END_IF;

{endregion}

{region "§4 Diagnostics et protections treuil"}
// 🔍 3. DIAGNOSTIC DU DOMAINE TREUIL (uniquement si bypass global désactivé)
IF NOT BypassGlobal THEN

    // ⏱️ Temporisation 3s de mise en route des bus de terrain au boot (CANopen / Modbus IHM)
    TonStartupWarmup(IN := Enable, PT := T#3s);

    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassOperatorComm) THEN
        IF (NOT JoystickOnline OR NOT JoystickOperational OR NOT HeartbeatIhmOk) THEN
            Status.ErrorId := Status.ErrorId OR 16#0001;       // Perte communication opérateur : joystick CAN ou heartbeat IHM absent
        ELSE
            Status.ErrorId := Status.ErrorId AND 16#FFFE;      // Effacement auto si la com repasse saine
        END_IF;
    ELSIF NOT TonStartupWarmup.Q THEN
        Status.ErrorId := Status.ErrorId AND 16#FFFE;          // Inhibition pendant l'initialisation boot
    END_IF;
    IF ResetEdge.Q THEN
        Status.ErrorId := Status.ErrorId AND 16#FFFE;
    END_IF;

// 🔍 3bis. PERTE CODEUR DE CE TREUIL
// Le fonctionnement sans codeur reste interdit par défaut.
// Le bypass est individuel, maintenu consciemment depuis l'IHM et strictement limité à MAINT_N2.
// Il ne masque aucun autre défaut du treuil et n'agit jamais sur l'autre instance.
EncoderAvailableEffective := EncoderAvailable
                             OR BypassGlobal
                             OR ((EncoderFaultBypass OR BypassProcess) AND (Mode = E_Mode.MAINT_N2));
IF NOT EncoderAvailableEffective THEN
    Status.ErrorId := Status.ErrorId OR 16#0002;
ELSE
    Status.ErrorId := Status.ErrorId AND 16#FFFD; (* Effacement auto si le codeur est dispo OU bypassé *)
END_IF;

// 🔍 3ter. SURCHAUFFE MOTEUR — bit2, participe au SafeStop total
// ET BypassMotorThermal — même doctrine que BypassBrakeThermal (§3sexies-ter),
// bypass dédié plutôt que de dépendre uniquement du bypass groupé BypassSafety.
IF NOT (BypassSafety OR BypassMotorThermal) AND ThermalFeedback THEN
    Status.ErrorId := Status.ErrorId OR 16#0004;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFFB;
END_IF;

// 🔍 3quater. MOU DE CÂBLE (physiquement sur tambour M2, câblé sur les 2 instances Safety)
// Mode NORMAL (SyncEnable=TRUE) → SafeStop M1+M2 (bit3 inclus dans SafeStop)
// Mode RÉCUPÉRATION (SyncEnable=FALSE) → DescendPermit uniquement (descente interdite pour ne pas dérouler, montée OK pour retendre/fermer)
IF NOT BypassProcess AND SlackCableDetected THEN
    Status.ErrorId := Status.ErrorId OR 16#0008;
ELSIF ResetEdge.Q AND NOT SlackCableDetected THEN
    Status.ErrorId := Status.ErrorId AND 16#FFF7;
END_IF;

// 🔍 3quinquies. ROTATION DE PHASE —
// bit4, participe au SafeStop total (sens moteur potentiellement inversé, danger 2 sens).
IF NOT (BypassProcess OR BypassPhaseRotation) AND NOT PhaseRotationOk THEN
    Status.ErrorId := Status.ErrorId OR 16#0010;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFEF;
END_IF;

// 🔍 3octies. MÉCA A — MOUVEMENT NON COMMANDÉ GÉNÉRAL — bit7
// Armé quand tout est physiquement confirmé coupé (contacteurs + frein). Si dérive ou vitesse
// détectée pendant que c'est armé → roue libre / frein insuffisant.
// La chaîne codeur produit la mesure ; ce bloc safety la surveille seulement.
DriftGuardA(
    Arm        := MeasuredSpeedValid AND FwdRevSpeedFeedbackOff AND NOT BrakeFeedback AND NOT InReferencingMode,
    PositionM  := CablePosM,
    ToleranceM := UncommandedDriftToleranceM
);
MecaADriftM := DriftGuardA.DriftM;   // Diagnostic IHM

// 🕐 La vitesse Meca A est une derive de position sur fenetre glissante 50ms : a l'arret, elle met
// ~50ms a retomber a 0 alors que l'armement (contacts/frein) est instantane -> faux Meca a chaque
// arret. Exiger une confirmation "vitesse < seuil" maintenue >= 1 fenetre (100ms) avant d'armer la
// detection de VITESSE Meca. Impact securite negligeable : une vraie roue libre dure >> 100ms.
TonMecaStopSettled(IN := (MeasuredSpeedMps < UncommandedSpeedThresholdMps), PT := T#100ms);

IF NOT (BypassSafety OR BypassMecaA) AND MeasuredSpeedValid AND (DriftGuardA.Violation OR (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback AND NOT InReferencingMode AND TonMecaStopSettled.Q AND (MeasuredSpeedMps > UncommandedSpeedThresholdMps))) THEN
    Status.ErrorId := Status.ErrorId OR 16#0080;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FF7F;
END_IF;

// 🔍 3nonies. MÉCA B — PILOTAGE ACTIF SANS COMMANDE OPÉRATEUR — bit8
// Indépendant de FB_Winch (défense en profondeur). Perte CAN (bit0) OU joystick au neutre ;
// si les contacteurs OU LE FREIN ne confirment pas être retombés/serrés dans PostRampTimeout, défaut.
// Un frein qui ne confirme pas son engagement dans ce délai est tout aussi dangereux qu'un
// contacteur qui ne retombe pas (risque de mouvement/roue libre non détecté).
MecaB_NoOperatorCmd := (NOT JoystickOnline) OR (NOT JoystickOperational)
                       OR (NOT HeartbeatIhmOk) OR JoystickYNeutral;
TonMecaB(IN := NOT (BypassSafety OR BypassMecaB) AND MecaB_NoOperatorCmd AND NOT (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback), PT := PostRampTimeout);
MecaBElapsedTime := TonMecaB.ET;   // Diagnostic IHM
IF TonMecaB.Q THEN
    Status.ErrorId := Status.ErrorId OR 16#0100;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FEFF;
END_IF;

// 🔍 3decies. MÉCA C — GLISSEMENT M1 PENDANT BENNE, ESCALADE — bit9
// Armé UNIQUEMENT pour l'instance M1 (BenneHoldStillActive câblé sur instBucket.Busy côté M1
// seulement, toujours FALSE côté M2). Tolérance plus large que celle de FB_Bucket (1.0 m) —
// n'intervient que si la couche Benne (SafeStop M1 seul) n'a pas suffi.
// Dérive surveillée via FB_DriftGuard.
DriftGuardC(
    Arm        := NOT (BypassSafety OR BypassMecaC) AND BenneHoldStillActive,
    PositionM  := CablePosM,
    ToleranceM := BenneSlipToleranceM
);
MecaCDriftM := DriftGuardC.DriftM;   // Diagnostic IHM

IF DriftGuardC.Violation THEN
    Status.ErrorId := Status.ErrorId OR 16#0200;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FDFF;
END_IF;

// 🔍 3undecies. THERMIQUE FREIN COMMUN M1/M2/M3 — bit10
// Signal commun (1 seul fil, câblé identiquement sur les 3 instances Safety) : sa perte peut
// signifier qu'un frein colle instantanément (frein à manque de courant) → SafeStop ET
// PowerCutOff (voir bandeau en-tête).
IF NOT (BypassSafety OR BypassBrakeThermal) AND BrakeThermalFeedback THEN
    Status.ErrorId := Status.ErrorId OR 16#0400;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FBFF;
END_IF;

// 🔍 3duodecies. MÉCA D — ARRIVÉE CAPTEUR HAUT HORS RÉFÉRENCEMENT — bit11
// Complète le bit5 (AscentPermit immédiat) : arme la MÊME condition (capteur haut atteint, hors
// homing) mais avec un délai de confirmation, comme Méca B. Si les contacteurs ET le frein ne
// confirment pas être retombés/serrés dans PostRampTimeout après l'arrivée au capteur → défaut
// → SafeStop ET PowerCutOff (la coupure AscentPermit seule ne suffit pas à arrêter réellement
// le treuil : roue libre ou contacteur/frein défaillant).
TonMecaD(
    IN := NOT (BypassSafety OR BypassMecaD) AND ((((NOT TopPositionSensor AND NOT InReferencingMode) 
            OR (Homed AND NOT HomingSuspect AND (CablePosM >= (TopLimitM + 0.10))))
           AND (Direction >= 0)) // Neutralise la butée haute en descente (Direction = -1)
          AND NOT (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback)), 
    PT := PostRampTimeout
);
IF TonMecaD.Q THEN
    Status.ErrorId := Status.ErrorId OR 16#0800;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#F7FF;
END_IF;

// 🔍 3terdecies. MÉCA E — ÉCART SYNCHRO M1/M2 CRITIQUE — bits 12/13
// Couche INDÉPENDANTE de FB_WinchSync (écart mineur, 1er niveau) — défense en profondeur pour un
// écart VRAIMENT important. ExpectedOtherWinchPosM est DÉJÀ corrigé de l'offset benne actif par
// l'appelant : comparaison directe valable que le benne soit ouvert, fermé, ou absent du calcul.
// Suppression pendant BenneBusy (trajet actif = écart transitoire normal, pas un défaut),
// InReferencingMode (position pas fiable pendant homing) et OtherWinchInhibited (l'autre treuil
// en maintenance a une position figée, non comparable).
// Bit12 : détection → SafeStop immédiat. Bit13 : escalade si pas confirmé arrêté → PowerCutOff.
IF NOT (BypassProcess OR BypassMecaE) AND SyncEnable AND NOT BenneBusy AND NOT InReferencingMode AND NOT OtherWinchInhibited
   AND (ABS(CablePosM - ExpectedOtherWinchPosM) > CriticalSyncToleranceM) THEN
    Status.ErrorId := Status.ErrorId OR 16#1000;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#EFFF;
END_IF;

TonMecaE(IN := NOT (BypassSafety OR BypassMecaE) AND (((Status.ErrorId AND 16#1000) <> 16#0000) AND NOT (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback)),
         PT := PostRampTimeout);
IF TonMecaE.Q THEN
    Status.ErrorId := Status.ErrorId OR 16#2000;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#DFFF;
END_IF;

// 🔍 3quaterdecies — SENS RÉEL OPPOSÉ À LA COMMANDE (bit14)
// Le signe de la vitesse câble est comparé à la direction commandée uniquement pendant un
// mouvement effectivement demandé. La temporisation filtre bruit codeur et inversion transitoire.
OppositeDirectionActive := NOT BypassProcess AND MeasuredSpeedValid AND (MovementCommanded AND NOT InReferencingMode
    AND (((Direction > 0) AND (MeasuredSpeedSignedMps < -MovementSpeedThresholdMps))
      OR ((Direction < 0) AND (MeasuredSpeedSignedMps > MovementSpeedThresholdMps))));
TonOppositeDirection(IN := OppositeDirectionActive, PT := OppositeDirectionTimeout);
IF TonOppositeDirection.Q THEN
    Status.ErrorId := Status.ErrorId OR 16#4000;
ELSIF ResetEdge.Q AND NOT OppositeDirectionActive THEN
    Status.ErrorId := Status.ErrorId AND 16#BFFF;
END_IF;

// ⏱️ 3quindecies — ABSENCE DE MOUVEMENT MALGRÉ COMMANDE (bit15)
// Détecte charge coincée, contacteur inefficace ou chaîne mécanique non entraînée. SafeStop seul :
// aucun retour ne justifie une coupure puissance brutale immédiate ; l'escalade reste matérielle.
TonNoMovement(
    IN := NOT BypassProcess AND MeasuredSpeedValid AND (MovementCommanded AND NOT InReferencingMode
          AND (ABS(MeasuredSpeedSignedMps) < MovementSpeedThresholdMps)),
    PT := NoMovementTimeout
);
IF TonNoMovement.Q THEN
    Status.ErrorId := Status.ErrorId OR 16#8000;
ELSIF ResetEdge.Q AND (NOT MeasuredSpeedValid OR NOT MovementCommanded OR (ABS(MeasuredSpeedSignedMps) >= MovementSpeedThresholdMps)) THEN
    Status.ErrorId := Status.ErrorId AND 16#7FFF;
END_IF;

END_IF; // fin IF NOT BypassGlobal

{endregion}

{region "§5 Arbitrage sorties securite"}
// 📤 4. ARBITRAGE DES SORTIES MAÎTRESSES
Status.Error := (Status.ErrorId <> 16#0000);       // 🧭 Partie3 §4 : miroir de TOUT le domaine, y compris mou de câble (visible IHM)
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;

// 🟧 SafeStop : bits 0/1/2/3/4 (joystick, codeur, thermique moteur, MOU CÂBLE, phases) + 7/8/9
// (Méca A/B/C) + 10 (thermique frein commun) + 11 (Méca D) + 12/13 (Méca E, écart synchro critique) ou si contacteur coupé
IF NOT PowerContactorEngaged THEN
    SafeStop := TRUE;
ELSIF NOT SyncEnable THEN
    SafeStop := (Status.ErrorId AND 16#FF97) <> 16#0000;   // bit3 exclu → SafeStop normal sans mou câble
ELSE
    SafeStop := (Status.ErrorId AND 16#FF9F) <> 16#0000;   // bit3 inclus → SafeStop complet avec mou câble
END_IF;

// ⬇️ DescendPermit : TRUE = descente autorisée (pas de limite basse, pas de mou câble en mode récup, contacteur engagé)
// Polarité positive Fail-Safe (TRUE = mouvement autorisé).
DescendPermit := NOT (
    (((Status.ErrorId AND 16#0040) <> 16#0000 OR NOT PowerContactorEngaged) AND NOT (BypassGlobal OR BypassCableLimitSwitch))
    OR (((CfgCableLimitDescentM < 0.0) AND (CablePosM <= CfgCableLimitDescentM) AND NOT InReferencingMode) AND NOT BypassCableLimitSwitch)
    OR (LimitLegalReached AND NOT (BypassProcess OR BypassLimitLegal))
    OR (((Status.ErrorId AND 16#0008) <> 16#0000 AND NOT SyncEnable) AND NOT (BypassProcess OR BypassGlobal))
);

// ⬆️ AscentPermit : TRUE = montée autorisée (pas de fin course haut, pas de dépassement position)
// Polarité positive Fail-Safe (TRUE = mouvement autorisé).
AscentPermit := NOT (
    (((Status.ErrorId AND 16#0020) <> 16#0000
    OR (NOT TopPositionSensor AND NOT InReferencingMode))
    AND NOT BypassTopLimitSwitch)
    OR ((Homed AND NOT HomingSuspect AND NOT InReferencingMode AND (CablePosM >= TopLimitM)) AND NOT BypassTopLimitSoftware)
);

// PowerCutOff — bits 7/8/9 (Méca A/B/C, voir bandeau en-tête).
// Coupure puissance amont : les contacteurs locaux sont déjà confirmés coupés/insuffisants,
// SafeStop seul ne sert à rien dans ces 3 cas précis.
// bit2 (surchauffe/perte thermique MOTEUR) et bit10 (surchauffe/perte thermique FREIN commun) :
// un frein à manque de courant peut coller instantanément sur perte de son retour thermique ;
// une rampe SafeStop seule ne protège pas la mécanique dans ce cas, coupure puissance immédiate
// nécessaire. Même raisonnement appliqué au thermique moteur par cohérence/défense en profondeur.
// bit11 (Méca D, capteur haut) : même raisonnement que Méca A/B — contacteurs/frein déjà censés
// être coupés (AscentPermit immédiat sur capteur), une confirmation manquante après délai signifie
// que la coupure locale n'a pas suffi.
// bit13 (Méca E escalade) : PAS bit12 seul (détection immédiate = SafeStop uniquement ;
// PowerCutOff seulement si l'arrêt n'est pas confirmé après délai).
PowerCutOff := (Status.ErrorId AND 16#2F84) <> 16#0000;

// Busy, Done non utilisés mais présents pour conformité (comme FB_Diag_CanOpen)
Status.Busy := FALSE;
Status.Done := FALSE;

{endregion}

(* ═══════════════════════════════════════════════════════════════
   🔄 FB_Cycle — Séquenceur du Cycle Automatique (Grafcet de dragage)
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF/AF_Partie-04_Mode_SemiAuto_Sequenceur_v2.0.md
            DOC/WFLOW/AUDITS/DESIGN_SEMI_AUTO_CYCLE_v0.1.md
   🔌 Conforme au contrat FB standard (Partie3 §1bis) + §11bis R1-R9.
   🧩 Deux instances : instCycleMaintenance (MAINT_N1/N2) et
      instCycleSemiAuto (SEMI_AUTO) — gating sorties par mode.
   🕹️ Homme-mort (D2) : appui = autorisation 3 s ; mouvement continue
      sans appui ; arrêt au centre du manche (CycleMotionPermit).
   ⏱️ Tempo max d'étape : lancée SEULEMENT si pilotage joystick actif.
   🧊 CycleStepAtError : étape spécifique mémorisée avant STABILIZING (R9).
   🏁 Début de graphe : à la TRÉMIE, treuils en position HAUTE — rebouclage sur X0.
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Cycle
VAR_INPUT
    Enable                  : BOOL;         // Activation générale du séquenceur
    Reset                   : BOOL;         // Acquittement défaut (front)
    PowerContactorEngaged   : BOOL;         // Chaîne de sécurité OK
    Mode                    : E_Mode;       // Mode arbitré (SEMI_AUTO pour l'instance cycle)
    CycleMotionPermit       : BOOL;         // 🕹️ Manche défléchi (non centré) — D2
    DeadmanArmed            : BOOL;         // 🔫 Appui homme-mort (fenêtre 3 s)
    HeartbeatIhmOk          : BOOL;         // 💓 IHM↔PLC valide

    // Commandes opérateur
    StartCycle              : BOOL;         // Demande lancement / reprise (IHM)
    AbortCycle              : BOOL;         // Demande abandon (IHM) — pas de Pause (D3)

    // Cibles et paramètres (réutilise config maintenance — Q4)
    SelTarget               : INT;          // 🎯 Cible sélectionnée (GVL_IHM.TranslationM3.Cmd.SelTarget) : 1=Trémie, 2=P2, 3=P1, 4=Maintenance
    SetDepthM               : REAL;         // Profondeur de consigne (négative)
    SetOffsetM              : REAL;         // Écart de fermeture benne cible

    // Feedbacks physique & matériel
    KoboldContactFond       : BOOL;         // Retour dédié Kobold : TRUE = contact fond
    LimitLegalReached       : BOOL;         // Limite légale atteinte (descente interdite)
    LimitLegalDepthM        : REAL;         // Profondeur légale minimale autorisée
    WinchSyncError          : BOOL;         // Désynchronisme bloquant M1/M2
    WinchSyncDeltaM         : REAL;         // Écart codeurs M1/M2 pour diagnostic
    M1_CablePosM            : REAL;         // Position câble treuil M1 (recalée)
    M2_CablePosM            : REAL;         // Position câble treuil M2 (recalée)
    M1_MeasuredSpeedMps     : REAL;         // Vitesse linéaire mesurée M1 (m/s)
    M2_MeasuredSpeedMps     : REAL;         // Vitesse linéaire mesurée M2 (m/s)
    SpeedMismatchThresholdMps : REAL;       // Seuil écart vitesse ; 0 = contrôle désactivé
    SpeedMismatchTimeout    : TIME;         // Durée de confirmation ; 0 = contrôle désactivé
    CableLimitM1AscentM     : REAL;         // Limite haute d'exploitation M1

    // Feedbacks Translation M3
    Translation_At_P1           : BOOL;     // Capteur position P1 (arrêt travail)
    Translation_At_Tremie       : BOOL;     // Capteur fin de course trémie
    Translation_At_Maintenance : BOOL;     // Capteur fin de course maintenance
    Translation_Busy            : BOOL;     // Mouvement translation en cours
    Translation_Done            : BOOL;     // Cible translation atteinte

    // Feedbacks Benne
    Benne_Busy              : BOOL;         // Mouvement mâchoires benne en cours
    Benne_Done              : BOOL;         // Mouvement ouverture/fermeture terminé
    Benne_IsOpen            : BOOL;         // Benne mécaniquement ouvert mémorisé
    Benne_IsClosed          : BOOL;         // Benne mécaniquement fermé mémorisé
    Benne_IsRoughlyClosed   : BOOL;         // 🆕 Benne « à peu près fermée » (tolérance matière)

    // 🆕 Référencement (X1_HOMING)
    HomedM1                 : BOOL;         // Codeur M1 référencé
    HomedM2                 : BOOL;         // Codeur M2 référencé
    TopPositionSensor       : BOOL;         // Capteur position haute (référencement)
    HomingRequest           : BOOL;         // Demande de référencement (front)
END_VAR
VAR_OUTPUT
    Ready                   : BOOL;         // Séquenceur disponible
    Busy                    : BOOL;         // Cycle automatique actif
    Done                    : BOOL;         // Cycle automatique complété
    Error                   : BOOL;         // Défaut cycle
    ErrorId                 : WORD;         // bit0: timeout/limite, bit1: désynchronisme, bit2: cible invalide, bit3: stabilisation impossible, bit4: écart vitesse, bit5: perte heartbeat, bit6: tempo max étape
    SpeedMismatchMps        : REAL;         // Écart absolu vitesse M1/M2 (m/s)
    SpeedMismatchActive     : BOOL;         // Seuil vitesse dépassé sur le cycle courant
    SpeedMismatchConfirmed  : BOOL;         // Écart vitesse confirmé pendant SpeedMismatchTimeout

    // Commandes structurées (demandes de mouvement)
    WinchM1Cmd              : ST_WinchCmdDemand;        // Demande treuil M1
    WinchM2Cmd              : ST_WinchCmdDemand;        // Demande treuil M2
    TranslationCmd          : ST_TranslationCmdDemand;  // Demande translation M3
    BucketCmd               : ST_BucketCmdDemand;       // Demande benne

    // Métadonnées d'affichage IHM
    CycleStep               : E_CycleStep;  // Étape active du Grafcet
    CycleStateStr           : STRING(80);   // Libellé en clair de l'étape (Xn - texte)
    CycleStepAtError        : E_CycleStep;  // 🧊 Étape spécifique au moment du défaut (R9)
    SampleCount             : INT;          // 🆕 Compteur de prélèvements (RETAIN, Q3bis)
END_VAR
VAR
    ResetEdge               : R_TRIG;
    StartEdge               : R_TRIG;
    AbortEdge               : R_TRIG;
    ErrorEdge               : R_TRIG;       // 🧊 Capture CycleStepAtError avant bascule (R9)

    // Séquencement
    State                   : E_CycleStep := E_CycleStep.X0_PREPARATION;
    SavedState              : E_CycleStep := E_CycleStep.X0_PREPARATION;

    // Mémorisations et Timers
    TouchPositionM          : REAL;         // Position M1 mémorisée lors du contact fond
    RaiseTargetM            : REAL;         // Profondeur de remontée mémorisée
    DrainingTimer           : TON;          // Temporisateur de vidage (égouttage)
    StabilizationTimer      : TON;          // Temporisation maximale de remontée lente
    SpeedMismatchTimer      : TON;          // Confirmation temporelle écart de vitesse
    StepMaxTimer            : TON;          // 🆕 Tempo max d'étape (R5) — lancée si pilotage
    SelectedWorkTarget      : INT;          // Cible de travail mémorisée (1=Trémie, 3=P1, 4=Maintenance)

    // Paramètres internes
    CtrlAscentDistM         : REAL := 2.0;      // Distance de remontée lente de contrôle
    CtrlAscentToleranceM    : REAL := 0.25;     // Écart maximal admis entre les deux codeurs
    CtrlAscentTimeout       : TIME := T#30s;    // Temps max pour atteindre la zone de stabilisation
    DrainingTime            : TIME := T#5s;     // Temps d'égouttage par défaut
    StepMaxTimeout          : TIME := T#60s;   // 🆕 Tempo max d'étape (à valider, Q4)
END_VAR

// === IMPLEMENTATION ===

{region "Gate securite"}
// 🛑 1. GATES DE SÉCURITÉ ET BLOCAGE (R8)
IF NOT Enable OR NOT PowerContactorEngaged THEN
    WinchM1Cmd.StartStop   := FALSE;
    WinchM1Cmd.Direction   := 0;
    WinchM1Cmd.SpeedPct    := 0.0;

    WinchM2Cmd.StartStop   := FALSE;
    WinchM2Cmd.Direction   := 0;
    WinchM2Cmd.SpeedPct    := 0.0;

    TranslationCmd.Start   := FALSE;
    TranslationCmd.Target  := 0;

    BucketCmd.Open         := FALSE;
    BucketCmd.Close        := FALSE;
    BucketCmd.KoboldContactorCmd := FALSE;

    State                := E_CycleStep.X0_PREPARATION;   // retour à la PREMIÈRE étape (R8)
    CycleStep            := E_CycleStep.X0_PREPARATION;
    CycleStateStr        := 'X0 - Désactivé : sécurité absente ou auto désactivé';
    Ready                := FALSE;
    Busy                 := FALSE;
    Done                 := FALSE;
    RETURN;
END_IF;
{endregion}

{region "Preparation surveillance et commandes cycle"}
Ready := TRUE;
ResetEdge(CLK := Reset);
StartEdge(CLK := StartCycle);
AbortEdge(CLK := AbortCycle);
ErrorEdge(CLK := Error);

// 🧊 R9 — capture l'étape spécifique AVANT la bascule vers STABILIZING
IF ErrorEdge.Q THEN
    CycleStepAtError := State;
END_IF;

// ⏱️ T36 — surveillance indépendante de la remontée lente
StabilizationTimer(IN := (State = E_CycleStep.X7_CTRL_ASCENT), PT := CtrlAscentTimeout);

// 📏 T43 — comparaison vitesse réelle M1/M2
SpeedMismatchMps := ABS(M1_MeasuredSpeedMps - M2_MeasuredSpeedMps);
SpeedMismatchActive := (State = E_CycleStep.X7_CTRL_ASCENT)
                       AND CycleMotionPermit
                       AND (SpeedMismatchThresholdMps > 0.0)
                       AND (SpeedMismatchTimeout > T#0ms)
                       AND (SpeedMismatchMps > SpeedMismatchThresholdMps);
SpeedMismatchTimer(IN := SpeedMismatchActive, PT := SpeedMismatchTimeout);
SpeedMismatchConfirmed := SpeedMismatchTimer.Q;

// 🆕 Tempo max d'étape (R5) — lancée SEULEMENT si pilotage joystick actif (pas de défaut au repos)
StepMaxTimer(IN := CycleMotionPermit AND (State <> E_CycleStep.X0_PREPARATION)
                  AND (State <> E_CycleStep.X13_DONE_SYNC)
                  AND (State <> E_CycleStep.STABILIZING),
             PT := StepMaxTimeout);

IF ResetEdge.Q THEN
    Error := FALSE;
    ErrorId := 16#0000;
    SavedState := E_CycleStep.X0_PREPARATION;
    IF State = E_CycleStep.STABILIZING THEN
        State := E_CycleStep.X0_PREPARATION;
    END_IF;
END_IF;

// 💓 Perte IHM : repli mémorisé. La reconnexion seule ne relance jamais le cycle.
IF NOT HeartbeatIhmOk AND State <> E_CycleStep.STABILIZING THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0020;
    State := E_CycleStep.STABILIZING;
END_IF;

// Défaut de synchronisme : arrêt sûr et acquittement obligatoire.
IF WinchSyncError AND State <> E_CycleStep.STABILIZING THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0002;
    State := E_CycleStep.STABILIZING;
END_IF;

// 🛡️ T43 — écart de vitesse confirmé : arrêt du cycle et STABILIZING.
IF SpeedMismatchConfirmed AND State <> E_CycleStep.STABILIZING THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0010;
    State := E_CycleStep.STABILIZING;
END_IF;

// 🆕 Tempo max d'étape dépassée (blocage probable) → défaut
IF StepMaxTimer.Q AND State <> E_CycleStep.STABILIZING THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0040;
    State := E_CycleStep.STABILIZING;
END_IF;

// Gestion de l'Abandon (D3 — pas de Pause)
IF AbortEdge.Q THEN
    State := E_CycleStep.X0_PREPARATION;
END_IF;
{endregion}

{region "Machine etat cycle automatique"}
// 🔁 2. LOGIQUE DU SÉQUENCEUR (Machine d'état) — CASE sur enum unique (R1)
CASE State OF

    E_CycleStep.X0_PREPARATION:
        CycleStep := E_CycleStep.X0_PREPARATION;
        CycleStateStr := 'X0 - Vérification cohérence système';
        WinchM1Cmd.StartStop := FALSE; WinchM1Cmd.Direction := 0; WinchM1Cmd.SpeedPct := 0.0;
        WinchM2Cmd.StartStop := FALSE; WinchM2Cmd.Direction := 0; WinchM2Cmd.SpeedPct := 0.0;
        TranslationCmd.Start := FALSE; TranslationCmd.Target := 0;
        BucketCmd.Open := FALSE; BucketCmd.Close := FALSE; BucketCmd.KoboldContactorCmd := FALSE;
        Busy := FALSE; Done := FALSE;

        // Transition si système sain et réarmé (front reset ou démarrage)
        IF StartEdge.Q THEN
            State := E_CycleStep.X1_HOMING;
        END_IF;

    E_CycleStep.X1_HOMING:
        CycleStep := E_CycleStep.X1_HOMING;
        CycleStateStr := 'X1 - Référencement codeurs (vitesses lentes)';
        Busy := TRUE;

        // 🆕 Vitesses lentes pour chercher capteur top + référencement
        IF NOT HomedM1 OR NOT HomedM2 THEN
            WinchM1Cmd.StartStop := CycleMotionPermit;
            WinchM1Cmd.Direction := 1;   // montée lente vers capteur top
            WinchM1Cmd.SpeedPct := 10.0;
            WinchM2Cmd.StartStop := CycleMotionPermit;
            WinchM2Cmd.Direction := 1;
            WinchM2Cmd.SpeedPct := 10.0;
            IF HomingRequest THEN
                // déclenche le référencement (via FB_Encoder_Homing en aval)
                State := E_CycleStep.X2_WORK_POS_SELECT;
            END_IF;
        ELSE
            // déjà homé → passe vite
            State := E_CycleStep.X2_WORK_POS_SELECT;
        END_IF;

    E_CycleStep.X2_WORK_POS_SELECT:
        CycleStep := E_CycleStep.X2_WORK_POS_SELECT;
        CycleStateStr := 'X2 - Sélection position travail (P1)';
        Busy := TRUE;

        // 🆕 Destinations sélectionnables : Trémie(1), P1(3), Maintenance(4).
        // P2(2) n'est PAS une destination — capteur de passage en petite vitesse (PV).
        IF (SelTarget <> 1) AND (SelTarget <> 3) AND (SelTarget <> 4) THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0004;
            State := E_CycleStep.STABILIZING;
        ELSE
            SelectedWorkTarget := SelTarget;
            TranslationCmd.Target := SelTarget;
            TranslationCmd.Start := CycleMotionPermit;
            // Arrivée à la cible (Trémie/P1/Maintenance) — capteurs PV/PVP2/P2 = ralentissement
            IF CycleMotionPermit AND (
                (SelTarget = 1 AND Translation_At_Tremie) OR
                (SelTarget = 3 AND Translation_At_P1) OR
                (SelTarget = 4 AND Translation_At_Maintenance)) THEN
                TranslationCmd.Start := FALSE;
                State := E_CycleStep.X3_OPEN_BUCKET;
            END_IF;
        END_IF;

    E_CycleStep.X3_OPEN_BUCKET:
        CycleStep := E_CycleStep.X3_OPEN_BUCKET;
        CycleStateStr := 'X3 - Ouverture benne';
        Busy := TRUE;

        // 🆕 Ouverture benne ; si déjà ouverte → passe vite
        IF Benne_IsOpen THEN
            State := E_CycleStep.X4_DESCEND_OPEN;
        ELSE
            BucketCmd.Open := CycleMotionPermit;
            IF CycleMotionPermit AND Benne_Done AND Benne_IsOpen THEN
                BucketCmd.Open := FALSE;
                State := E_CycleStep.X4_DESCEND_OPEN;
            END_IF;
        END_IF;

    E_CycleStep.X4_DESCEND_OPEN:
        CycleStep := E_CycleStep.X4_DESCEND_OPEN;
        CycleStateStr := 'X4 - Plongée benne ouverte (synchro)';

        // M1 et M2 descendent ensemble (synchro gérée en aval)
        WinchM1Cmd.StartStop := CycleMotionPermit;
        WinchM1Cmd.Direction := -1;
        WinchM1Cmd.SpeedPct  := 50.0;
        WinchM2Cmd.StartStop := CycleMotionPermit;
        WinchM2Cmd.Direction := -1;
        WinchM2Cmd.SpeedPct  := 50.0;
        BucketCmd.KoboldContactorCmd := TRUE;

        // Transition uniquement sur le retour dédié Kobold.
        IF CycleMotionPermit AND KoboldContactFond THEN
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            BucketCmd.KoboldContactorCmd := FALSE;
            TouchPositionM := M1_CablePosM;
            IF LimitLegalDepthM < -0.01 THEN
                RaiseTargetM := MAX(TouchPositionM + 0.5, LimitLegalDepthM + 0.5);
            ELSE
                RaiseTargetM := TouchPositionM + 0.5;
            END_IF;
            State := E_CycleStep.X5_BOTTOM_CONFIRMED;
        ELSIF LimitLegalReached THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0001;
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            BucketCmd.KoboldContactorCmd := FALSE;
            State := E_CycleStep.STABILIZING;
        END_IF;

    E_CycleStep.X5_BOTTOM_CONFIRMED:
        CycleStep := E_CycleStep.X5_BOTTOM_CONFIRMED;
        CycleStateStr := 'X5 - Fond confirmé : remontée sécurisée';

        WinchM1Cmd.StartStop := CycleMotionPermit;
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct := 20.0;
        WinchM2Cmd.StartStop := CycleMotionPermit;
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct := 20.0;

        // Les deux treuils restent synchronisés jusqu'au-dessus de la limite légale.
        IF CycleMotionPermit AND (M1_CablePosM >= RaiseTargetM) AND (M2_CablePosM >= RaiseTargetM) THEN
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            State := E_CycleStep.X6_CLOSE_BUCKET;
        END_IF;

    E_CycleStep.X6_CLOSE_BUCKET:
        CycleStep := E_CycleStep.X6_CLOSE_BUCKET;
        CycleStateStr := 'X6 - Fermeture benne (tolérance à peu près fermé)';

        WinchM1Cmd.StartStop := FALSE;
        BucketCmd.Close := TRUE;

        // 🆕 Tolérance : si benne « à peu près fermée » (matière/objet), on remonte et on contrôle
        IF CycleMotionPermit AND (Benne_Done AND (Benne_IsClosed OR Benne_IsRoughlyClosed)) THEN
            BucketCmd.Close := FALSE;
            State := E_CycleStep.X7_CTRL_ASCENT;
        END_IF;

    E_CycleStep.X7_CTRL_ASCENT:
        CycleStep := E_CycleStep.X7_CTRL_ASCENT;
        CycleStateStr := 'X7 - Remontée lente de contrôle';

        WinchM1Cmd.StartStop := CycleMotionPermit;
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct  := 20.0;
        WinchM2Cmd.StartStop := CycleMotionPermit;
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct  := 20.0;

        // Contrôle des deux codeurs
        IF WinchSyncError OR (ABS(M1_CablePosM - M2_CablePosM) > CtrlAscentToleranceM) THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0008;
            State := E_CycleStep.STABILIZING;
        ELSIF CycleMotionPermit
           AND (M1_CablePosM >= (TouchPositionM + CtrlAscentDistM))
           AND (M2_CablePosM >= (TouchPositionM + CtrlAscentDistM))
           AND (ABS(M1_CablePosM - M2_CablePosM) <= CtrlAscentToleranceM) THEN
            State := E_CycleStep.X8_ASCENT_LOADED;
        ELSIF StabilizationTimer.Q THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0008;
            State := E_CycleStep.STABILIZING;
        END_IF;

    E_CycleStep.X8_ASCENT_LOADED:
        CycleStep := E_CycleStep.X8_ASCENT_LOADED;
        CycleStateStr := 'X8 - Remontée en charge';

        WinchM1Cmd.StartStop := CycleMotionPermit;
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct  := 70.0;
        WinchM2Cmd.StartStop := CycleMotionPermit;
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct  := 70.0;

        // Transition alignée sur la limite haute d'exploitation
        IF CycleMotionPermit AND M1_CablePosM >= CableLimitM1AscentM THEN
            WinchM1Cmd.StartStop := FALSE;
            WinchM2Cmd.StartStop := FALSE;
            State := E_CycleStep.X9_DRAIN_PAUSE;
        END_IF;

    E_CycleStep.X9_DRAIN_PAUSE:
        CycleStep := E_CycleStep.X9_DRAIN_PAUSE;
        CycleStateStr := 'X9 - Égouttage du godet en cours';
        WinchM1Cmd.StartStop := FALSE;
        WinchM2Cmd.StartStop := FALSE;

        DrainingTimer(IN := TRUE, PT := DrainingTime);
        // 🆕 Temps écoulé affiché IHM (CycleStateStr + champ dédié)
        IF CycleMotionPermit AND DrainingTimer.Q THEN
            DrainingTimer(IN := FALSE);
            State := E_CycleStep.X10_TRANSLATE_DUMP;
        END_IF;

    E_CycleStep.X10_TRANSLATE_DUMP:
        CycleStep := E_CycleStep.X10_TRANSLATE_DUMP;
        CycleStateStr := 'X10 - Déplacement vers trémie (grille/crible libres)';

        TranslationCmd.Target := 1; // Trémie
        TranslationCmd.Start := CycleMotionPermit;

        // 🆕 Avertissement IHM : grille abaissée/libre, crible libre pour réceptionner la charge
        // (porté par CycleStateStr + OperatorAction côté supervision)

        // Transition si translation arrivé à la trémie
        IF CycleMotionPermit AND Translation_At_Tremie THEN
            TranslationCmd.Start := FALSE;
            State := E_CycleStep.X11_OPEN_DUMP;
        END_IF;

    E_CycleStep.X11_OPEN_DUMP:
        CycleStep := E_CycleStep.X11_OPEN_DUMP;
        CycleStateStr := 'X11 - Vidange / ouverture du godet (montée possible, descente ouvre)';

        // 🆕 Montée possible (treuils vers le haut) ; descente fait ouvrir la benne.
        // Montée : on laisse l'opérateur remonter les 2 treuils en synchro si besoin.
        WinchM1Cmd.StartStop := CycleMotionPermit AND (WinchM1Cmd.Direction = 1);
        WinchM1Cmd.Direction := 1;
        WinchM1Cmd.SpeedPct  := 20.0;
        WinchM2Cmd.StartStop := CycleMotionPermit AND (WinchM2Cmd.Direction = 1);
        WinchM2Cmd.Direction := 1;
        WinchM2Cmd.SpeedPct  := 20.0;

        // Descente → ouverture benne (vidage)
        BucketCmd.Open := CycleMotionPermit AND (WinchM1Cmd.Direction = -1);

        // 🆕 Contrôle convoyeurs par MESSAGE utilisateur (pas encore câblé) :
        // CycleStateStr + OperatorAction côté supervision demandent de vérifier
        // que les convoyeurs sont en route avant/au lâcher.
        IF CycleMotionPermit AND Benne_Done AND Benne_IsOpen THEN
            BucketCmd.Open := FALSE;
            State := E_CycleStep.X13_DONE_SYNC;
        END_IF;

    E_CycleStep.X13_DONE_SYNC:
        CycleStep := E_CycleStep.X13_DONE_SYNC;
        CycleStateStr := 'X13 - Cycle automatique complété - prêt';
        WinchM1Cmd.StartStop := FALSE;
        WinchM2Cmd.StartStop := FALSE;
        TranslationCmd.Start := FALSE;
        Done := TRUE;
        Busy := FALSE;

        // 🆕 Compteur de prélèvements (RETAIN, Q3bis) — compte inconditionnellement
        SampleCount := SampleCount + 1;

        // 🆕 Rebouclage sur X0_PREPARATION (trémie, treuils hauts) — pas de retour P1
        IF StartEdge.Q THEN
            Done := FALSE;
            State := E_CycleStep.X0_PREPARATION;
        END_IF;

    E_CycleStep.STABILIZING:
        CycleStep := E_CycleStep.STABILIZING;
        CycleStateStr := 'X14 - Cycle en attente / stabilisation (STAB)';
        WinchM1Cmd.StartStop := FALSE;
        WinchM2Cmd.StartStop := FALSE;
        TranslationCmd.Start := FALSE;
        BucketCmd.Open := FALSE;
        BucketCmd.Close := FALSE;

END_CASE;
{endregion}

{region "Repli homme mort"}
// 🛑 Relâchement du manche (retour au centre) : aucune demande d'actionneur ne reste active.
// L'étape est mémorisée et reprend au prochain appui valide (D2).
IF Busy AND NOT CycleMotionPermit THEN
    WinchM1Cmd.StartStop := FALSE;
    WinchM2Cmd.StartStop := FALSE;
    TranslationCmd.Start := FALSE;
    BucketCmd.Open := FALSE;
    BucketCmd.Close := FALSE;
    BucketCmd.KoboldContactorCmd := FALSE;
END_IF;
{endregion}

END_FUNCTION_BLOCK

(* ═══════════════════════════════════════════════════════════════
   🕹️ FB_Joystick — Acquisition & traitement Hall (Homme-mort ISO 13850)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-08_Fonction_Joystick_v2.0.md
                   DOC/AF_Partie-03_Contrats_Composants_v2.1.md
   🎯 Rôle : Acquisition 2 axes Hall + bouton homme-mort normatif.
      Pipeline par axe : FB_AxisScale → FB_Filter_PT1 → Homme-Mort → ST_Joystick_AxisCmd.
      Les rampes d'accélération/décélération sont gérées exclusivement par les
      FB de mouvement aval (FB_Winch, FB_Translation), hors de ce bloc.
    🔒 Bouton homme-mort :
       - Armement au neutre strict (ScaleX/Y.OutPct = 0.0).
       - Consentement au démarrage : mouvement libre SANS surveillance du bouton
         (défaut, DeadmanReconfEnable := FALSE). Optionnel : reconfirmation périodique
         en mouvement (délai DeadmanRearmTimeout) si DeadmanReconfEnable := TRUE.
       - Désarmement sur maintien au neutre (durée NeutralHoldTime) + gate/mode/fin benne.
   📤 Produit AxisCmdX, AxisCmdY, et signaux de diagnostic/miroir.
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Joystick) ===

FUNCTION_BLOCK FB_Joystick
VAR_INPUT
    Enable          : BOOL;       // Active la logique
    Reset           : BOOL;       // Acquittement défaut
    PowerContactorEngaged : BOOL;       // Conditions globales OK (chaîne AU réarmée)
    Mode            : E_Mode;     // Changement de mode désarme le homme-mort
    BenneBusy       : BOOL;       // Fin de cycle benne (front descendant) désarme le homme-mort
    PreserveArmingAfterBucket : BOOL; // TRUE uniquement pendant fermeture ExtractionSequence : enchaînement palier 1 autorisé
    BusCanOpenOP    : ST_Diag_Device;       // État présence nœud CAN
    JoystickOP      : ST_Diag_Device;       // Mode esclave CANopen actif
    RawX            : INT;        // Valeur brute axe X
    RawY            : INT;        // Valeur brute axe Y
    RawButton       : BOOL;       // État brut bouton
    BtnCalibrate    : BOOL;       // Demande de recalage neutre
    InvertX         : BOOL := FALSE;
    InvertY         : BOOL := FALSE;
    DeadbandRaw     : INT := 300;    // 🔧 2026-08-07 (demande client) : zone morte en compte brut ADC (0..10000), remplace l'ancien % — mesure terrain bruit neutre ±200, marge à ±300
    FilterTime      : TIME := TIME#0ms;
    DeadmanRearmTimeout : TIME := T#10S; // Délai max entre 2 appuis en mouvement (si reconfirmation activée)
    NeutralHoldTime     : TIME := T#100MS; // Temps continu au neutre avant désarmement (100 ms)
    DeadmanArmHoldTime  : TIME := T#100MS; // 🆕 2026-08-07 : Temps d'appui continu avant armement (indépendant position axes)
    DeadmanArmGraceTime : TIME := T#3S;    // 🆕 2026-08-07 : Délai après armement avant que le désarmement "neutre tenu" (NeutralHoldTime) puisse s'appliquer — laisse le temps de sortir de la zone morte après un appui au centre
    DeadmanReconfEnable : BOOL := FALSE; // 🆕 2026-08-03 : FALSE = bouton = consentement au démarrage (mouvement libre, défaut cible) ; TRUE = reconfirmation périodique en mouvement (comportement historique)
END_VAR
VAR_OUTPUT
    Ready           : BOOL;       // Prêt à commuter
    Busy            : BOOL;       // Traitement en cours
    Done            : BOOL;       // Données valides dispo
    Error           : BOOL;       // Présence anomalie
    ErrorId         : WORD;       // bit0: "Échec calibration Joystick" - Valeurs RawX/Y hors plage lors du recalage
    AxisCmdX        : ST_Joystick_AxisCmd; // Sortie normalisée X
    AxisCmdY        : ST_Joystick_AxisCmd; // Sortie normalisée Y
    Button          : BOOL;       // Bouton filtré
    NeutralXAct     : INT;        // Point neutre X actuel pour IHM/Test
    NeutralYAct     : INT;        // Point neutre Y actuel pour IHM/Test
    // 🆕 Miroirs directs (maintenance) — mêmes valeurs que AxisCmdX/Y.SpeedRef/.Direction,
    // exposés à plat pour lecture immédiate en vue instance CODESYS (pas de dépliage struct).
    SpeedXPct       : REAL;       // Consigne vitesse axe X en % SIGNÉE (-100..+100), miroir AxisCmdX.SpeedRef
    DirectionX      : INT;        // Sens axe X (-1=Rev/0=Neutre/+1=Fwd), miroir AxisCmdX.Direction
    SpeedYPct       : REAL;       // Consigne vitesse axe Y en % SIGNÉE (-100..+100), miroir AxisCmdY.SpeedRef
    DirectionY      : INT;        // Sens axe Y (-1=Rev/0=Neutre/+1=Fwd), miroir AxisCmdY.Direction
    DeadmanArmed    : BOOL;       // 🆕 Geste armé (bouton appuyé au neutre) — IHM/diagnostic
    AtNeutral       : BOOL;       // 🆕 2026-08-07 : TRUE si les 2 axes sont en zone morte (position centrale) — IHM/diagnostic
END_VAR
VAR_IN_OUT
    NeutralXMem     : INT; // Point neutre X persistant global
    NeutralYMem     : INT; // Point neutre Y persistant global
END_VAR
VAR
    CycleTimeCalc   : FB_CycleTime;
    ScaleX          : FB_AxisScale;
    ScaleY          : FB_AxisScale;
    FilterX         : FB_Filter_PT1;
    FilterY         : FB_Filter_PT1;
    CmdXVal         : REAL;
    CmdYVal         : REAL;
    LastCalibrate   : BOOL;
    ResetEdge       : R_TRIG;
    DeadmanEdge     : R_TRIG;
    DeadmanTimer    : TON;
    NeutralHoldTimer: TON;
    DeadmanArmTimer : TON;
    DeadmanArmPending : BOOL;
    DeadmanArmGraceTimer : TON;
    LastMode        : E_Mode;
    BenneBusyFallEdge : F_TRIG;
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Joystick) ===

// 🛑 1. GATE (Sécurités et coupures prioritaires)
IF NOT Enable OR NOT PowerContactorEngaged OR NOT BusCanOpenOP.Operational OR NOT JoystickOP.Operational THEN
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    AxisCmdX.Enable := FALSE; AxisCmdX.StartStop := FALSE; AxisCmdX.SpeedRef := 0.0; AxisCmdX.Direction := 0;
    AxisCmdY.Enable := FALSE; AxisCmdY.StartStop := FALSE; AxisCmdY.SpeedRef := 0.0; AxisCmdY.Direction := 0;
    SpeedXPct := 0.0; DirectionX := 0;
    SpeedYPct := 0.0; DirectionY := 0;
    Button := FALSE;
    AtNeutral := TRUE;   // 🆕 2026-08-07 — pas de commande possible pendant la neutralisation
    DeadmanArmed := FALSE;   // 🆕 Désarmé sur toute neutralisation — nouvel appui au neutre exigé
    DeadmanArmPending := FALSE;   // 🆕 2026-08-07 — annule toute tentative d'armement en cours
    DeadmanTimer(IN := FALSE, PT := DeadmanRearmTimeout);   // 🆕 2026-07-03decies — pas d'accumulation à froid
    NeutralHoldTimer(IN := FALSE, PT := NeutralHoldTime);   // 🆕 2026-07-03duodecies — idem
    DeadmanArmTimer(IN := FALSE, PT := DeadmanArmHoldTime);   // 🆕 2026-08-07 — idem
    DeadmanArmGraceTimer(IN := FALSE, PT := DeadmanArmGraceTime);   // 🆕 2026-08-07 — idem
    NeutralXAct := NeutralXMem;
    NeutralYAct := NeutralYMem;
    LastMode := Mode;   // 🆕 REX 2026-07-08 — pas de faux changement détecté à la réactivation
    RETURN;
END_IF;

Ready := TRUE; Busy := TRUE;

// 🔑 2. RESET DÉFAUT (front + cause disparue, Partie3 §5)
ResetEdge(CLK := Reset);
IF ResetEdge.Q AND (RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000) THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 📥 3. ACQUISITION TIMING & BOUTON
CycleTimeCalc();
Button := RawButton;

// 🎯 4. CALIBRATION DYNAMIQUE (Zone RETAIN)
IF BtnCalibrate AND NOT LastCalibrate THEN
    IF RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000 THEN
        NeutralXMem := RawX;
        NeutralYMem := RawY;
    ELSE
        // Un seul bit pour une seule cause (Partie3 §3)
        ErrorId := ErrorId OR 16#0001;
    END_IF;
END_IF;
Error := (ErrorId <> 16#0000);
LastCalibrate := BtnCalibrate;

// 🧮 4bis. MISE À L'ÉCHELLE (avant homme-mort — le neutre s'évalue sur les 2 axes déjà deadbandés)
ScaleX(RawIn := RawX, Neutral := NeutralXMem, DeadbandRaw := DeadbandRaw);
ScaleY(RawIn := RawY, Neutral := NeutralYMem, DeadbandRaw := DeadbandRaw);
AtNeutral := (ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0);   // 🆕 2026-08-07 : IHM/diagnostic — position centrale (zone morte)

// 4ter-bis. CHANGEMENT DE MODE : désarme le homme-mort dès que Mode change
// (MAINT_N1/N2/SEMI_AUTO/AUTO). Évite qu'une commande en cours traverse le changement
// de mode et soit réinterprétée soudainement. Repassage par le neutre + nouvel appui exigé.
IF Mode <> LastMode THEN
    DeadmanArmed := FALSE;
    DeadmanArmPending := FALSE;   // 🆕 2026-08-07 — nouvel appui exigé après changement de mode
END_IF;
LastMode := Mode;

// 4ter-ter. FIN DE CYCLE BENNE : désarmement général pour qu'une fermeture manuelle
// ne démarre jamais M1/M2 par surprise. Exception : ExtractionSequence garde l'armement
// pendant sa fermeture (enchaînement palier 1 sous ses propres interlocks synchro/position).
BenneBusyFallEdge(CLK := BenneBusy);
IF BenneBusyFallEdge.Q AND NOT PreserveArmingAfterBucket THEN
    DeadmanArmed := FALSE;
    DeadmanArmPending := FALSE;   // 🆕 2026-08-07 — nouvel appui exigé après fin de cycle benne
END_IF;

// 4ter. BOUTON HOMME-MORT — armement par MAINTIEN (DeadmanArmHoldTime), indépendant de la
// position des axes pendant l'appui.
// 🔧 2026-08-07 (retour terrain) : l'ancien armement ("front bouton" ET "axes strictement à
// 0.0 sur le MÊME scan") échouait dès que l'opérateur poussait le joystick quelques ms après
// avoir appuyé — trop contraignant en pratique (le geste naturel "j'appuie PUIS je pousse" ratait
// systématiquement la fenêtre d'un seul scan). Nouvelle séquence : appui (front) → maintien
// DeadmanArmHoldTime (100 ms) → armé, quelle que soit la position des axes durant ce maintien.
// Relâchement AVANT la fin du maintien = tentative annulée (DeadmanArmPending retombe), un
// nouvel appui (front) est requis — pas d'armement différé "surprise" sur un appui prolongé après
// un désarmement (mode/benne/neutre). Sûr même si le joystick est déjà hors zone morte à la fin
// du maintien : les rampes d'accel/décel restent gérées par les FB aval (FB_Winch/FB_Translation,
// cf. §"Rôle" en tête de fichier), donc pas de démarrage brutal possible côté ce FB.
DeadmanEdge(CLK := RawButton);
IF DeadmanEdge.Q THEN
    DeadmanArmPending := TRUE;
END_IF;
IF NOT RawButton THEN
    DeadmanArmPending := FALSE;
END_IF;
DeadmanArmTimer(IN := DeadmanArmPending AND NOT DeadmanArmed, PT := DeadmanArmHoldTime);
IF DeadmanArmTimer.Q THEN
    DeadmanArmed := TRUE;
    DeadmanArmPending := FALSE;
END_IF;

// 🔧 2026-08-06 (retour terrain) : décision 2026-08-03 ("l'opérateur a le temps qu'il veut
// pour démarrer après armement") ANNULÉE explicitement — un armement resté au neutre sans
// mouvement démarré ne désarmait JAMAIS (LeftNeutralSinceArm restait FALSE indéfiniment),
// laissant DeadmanArmed collé à TRUE d'une session à l'autre. Neutre tenu NeutralHoldTime
// désarme désormais TOUJOURS, qu'un mouvement ait été démarré ou non depuis l'armement.
// 🔧 2026-08-07 (retour terrain) : SANS garde-fou, ce désarmement se déclenchait ~100-200ms après
// CHAQUE armement (l'appui se fait typiquement AU neutre depuis le nouvel armement par maintien —
// voir §4ter — donc AtNeutral est déjà vrai dès l'instant où DeadmanArmed passe à TRUE, et
// NeutralHoldTime=100ms est trop court pour laisser le temps de sortir de la zone morte). Ajout
// DeadmanArmGraceTimer (3s) : le désarmement neutre ne peut s'appliquer qu'APRÈS ce délai suivant
// l'armement — le risque du 2026-08-06 (armement collé indéfiniment) reste couvert, juste avec
// une marge de départ au lieu de 100ms. Aucun risque moteur pendant la grâce : au neutre,
// CmdXVal/CmdYVal restent à 0 (deadband), armé ou non.
DeadmanArmGraceTimer(IN := DeadmanArmed, PT := DeadmanArmGraceTime);
NeutralHoldTimer(IN := DeadmanArmed AND AtNeutral AND DeadmanArmGraceTimer.Q,
                 PT := NeutralHoldTime);
IF NeutralHoldTimer.Q THEN
    DeadmanArmed := FALSE;      // Neutre tenu assez longtemps (après la grâce) = désarmement
END_IF;

// 4quater. RECONFIRMATION PÉRIODIQUE (optionnelle) — activée uniquement si DeadmanReconfEnable := TRUE.
// 🆕 2026-08-03 : par défaut FALSE → bouton = CONSENTEMENT AU DÉMARRAGE : une fois armé, le mouvement
// est libre SANS surveillance du bouton ; seuls gate/mode/fin benne/neutre 500ms désarment.
// ⚠️ CORRECTIF (garde-fou si réactivé) : le 1er jet ne détectait qu'un FRONT (`DeadmanEdge.Q`) — un
// opérateur qui MAINTIENT le bouton enfoncé en continu (réflexe naturel homme-mort) ne générait
// plus jamais de front après le 1er appui → désarmement surprise au bout de 3s MALGRÉ la présence
// continue. Corrigé : `NOT RawButton` (niveau, pas front) — maintenir OU réappuyer dans le délai
// remettent tous les deux `IN` à FALSE (TON.ET repart de 0), seul un RELÂCHEMENT PROLONGÉ désarme.
DeadmanTimer(IN := DeadmanReconfEnable AND DeadmanArmed
                   AND NOT AtNeutral AND NOT RawButton,
             PT := DeadmanRearmTimeout);
IF DeadmanTimer.Q THEN
    DeadmanArmed := FALSE;      // Pas de reconfirmation dans le délai → désarmement (décélération sûre)
END_IF;

// 🕹️ 5. PIPELINE TRAITEMENT — AXE X
IF InvertX THEN
    FilterX(ValueIn := -ScaleX.OutPct, TimeConst := FilterTime, CycleTimeS := CycleTimeCalc.CycleTimeS);
ELSE
    FilterX(ValueIn := ScaleX.OutPct, TimeConst := FilterTime, CycleTimeS := CycleTimeCalc.CycleTimeS);
END_IF;

// Consigne forcée à 0.0 tant que le geste n'est pas armé (homme-mort)
CmdXVal := SEL(DeadmanArmed, 0.0, FilterX.ValueOut);

// Mapping Sortie Standardisée Axe X
AxisCmdX.Enable := TRUE;
AxisCmdX.SpeedRef := CmdXVal;
AxisCmdX.StartStop := (ABS(CmdXVal) > 0.1);

IF CmdXVal > 0.1 THEN
    AxisCmdX.Direction := 1;
ELSIF CmdXVal < -0.1 THEN
    AxisCmdX.Direction := -1;
ELSE
    AxisCmdX.Direction := 0;
    AxisCmdX.SpeedRef := 0.0;
END_IF;

// Miroirs maintenance
SpeedXPct := AxisCmdX.SpeedRef;
DirectionX := AxisCmdX.Direction;

// 🕹️ 6. PIPELINE TRAITEMENT — AXE Y
IF InvertY THEN
    FilterY(ValueIn := -ScaleY.OutPct, TimeConst := FilterTime, CycleTimeS := CycleTimeCalc.CycleTimeS);
ELSE
    FilterY(ValueIn := ScaleY.OutPct, TimeConst := FilterTime, CycleTimeS := CycleTimeCalc.CycleTimeS);
END_IF;

// Consigne forcée à 0.0 tant que le geste n'est pas armé (homme-mort)
CmdYVal := SEL(DeadmanArmed, 0.0, FilterY.ValueOut);

// Mapping Sortie Standardisée Axe Y
AxisCmdY.Enable := TRUE;
AxisCmdY.SpeedRef := CmdYVal;
AxisCmdY.StartStop := (ABS(CmdYVal) > 0.1);

IF CmdYVal > 0.1 THEN
    AxisCmdY.Direction := 1;
ELSIF CmdYVal < -0.1 THEN
    AxisCmdY.Direction := -1;
ELSE
    AxisCmdY.Direction := 0;
    AxisCmdY.SpeedRef := 0.0;
END_IF;

// Miroirs maintenance
SpeedYPct := AxisCmdY.SpeedRef;
DirectionY := AxisCmdY.Direction;

// 📤 7. VALIDATION DES SORTIES ÉTAT
NeutralXAct := NeutralXMem;
NeutralYAct := NeutralYMem;
Done := NOT Error;

(* ═══════════════════════════════════════════════════════════════
   📡 PRG_02_Acquisition — Programme d'Acquisition et Conditionnement I/O
   ───────────────────────────────────────────────────────────────
   ⚙️ Exécuté par la tâche PLC en position 1 (premier POU du cycle).
   📄 Doc : DOC/AF/AF_Partie-06_Acquisition_Qualification_IO_v2.3.md §2
   🎯 Rôle unique : Produire les images HwReal/HwSim/HwIn,
      acquérir et traiter les mesures codeurs (M1/M2), décoder M3, traiter le joystick
      et publier les retours.
   ═══════════════════════════════════════════════════════════════ *)

PROGRAM PRG_02_Acquisition

VAR_INPUT
    // === 📥 ENTRÉES PROGRAMME (AUCUNE - PILOTÉ VIA GVL_IHM & GVL_Simulation) ===
END_VAR

VAR_OUTPUT
    // === 🚌 BUS INTER-PRG (producteur unique) ===
    Data                     : ST_AcquisitionInterPrg; // <-- [BUS] Mesures/joystick/positions M3/diag DI publiés

    // === 🖼️ IMAGES PROCESS MATÉRIEL / SIMULATION ===
    HwReal                   : ST_HardwareImage; // <-- [STAT] Image brute reelle physique
    HwSim                    : ST_HardwareImage; // <-- [STAT] Image simulee banc
    HwIn                     : ST_HardwareImage; // <-- [STAT] Image utilisee par le metier (arbitree)
END_VAR

VAR
    // === 🧩 SOUS-INSTANCES FB ===
    instSimBench             : FB_SimBench;                   // * [INST] Banc de simulation integré
    instJoystick             : FB_Joystick;                   // * [INST] Traitement et filtrage joystick
    instDiagCanOpen          : FB_Diag_CanOpen;               // * [INST] Diagnostic reseau CANopen (joystick) — rang 02 (consomme PRG 04/05)
    instDiagEthercat         : FB_Diag_Ethercat;              // * [INST] Diagnostic reseau EtherCAT (codeurs/variateur) — rang 02
    instEncoderM1            : FB_Encoder;                    // * [INST] Facade codeur complet M1 (Abs+Homing+Scale+Safety+Rel+Speed)
    instEncoderM2            : FB_Encoder;                    // * [INST] Facade codeur complet M2
    instPosDecoderM3         : FB_Translation_PositionDecoder;// * [INST] Decodage position translation M3

    // === 🎛️ VARIABLES LOCALES & DÉTECTEURS ===
    M2BucketRefOpenEdge      : R_TRIG; // . [LOC] Front demande reference benne ouverte
    M2BucketRefCloseEdge     : R_TRIG; // . [LOC] Front demande reference benne fermee
    M2BucketRefRequested     : BOOL;   // . [LOC] Demande d'etalonnage M2 active
    M2BucketRefTargetM       : REAL;   // . [LOC] Cible metrique etalonnage M2
    HwM1                     : ST_EncoderHw; // . [LOC] Frontiere hardware codeur M1 (in/out)
    HwM2                     : ST_EncoderHw; // . [LOC] Frontiere hardware codeur M2 (in/out)

    WinchInputSourceSimulated         : BOOL; // . [LOC] Source Winch simulee active
    TranslationInputSourceSimulated   : BOOL; // . [LOC] Source Translation simulee active
    OperatorInputSourceSimulated      : BOOL; // . [LOC] Source Pupitre simulee active
    MachineInputSourceSimulated       : BOOL; // . [LOC] Source Machine simulee active

    PreviousWinchInputSourceSimulated : BOOL; // . [LOC] Memoire cycle precedent source Winch
    WinchInputSourceInitialized       : BOOL; // . [LOC] Indicateur initialisation source Winch

    SimulationModeRise                : R_TRIG; // . [LOC] Front montant activation simulation
    SimulationModeFall                : F_TRIG; // . [LOC] Front descendant desactivation simulation
END_VAR

VAR CONSTANT
    // === ⚙️ CONSTANTES MÉCANIQUES (AF09 §2) ===
    ENCODER_POINTS_PER_REV     : UDINT := 8192; // 13 bits single-turn (8192 pts/tour)
    ENCODER_MULTITURN_REVS_MAX : UDINT := 4096; // 12 bits multi-turn (4096 tours max)
    WINCH_CABLE_M_PER_REV      : REAL  := 2.0;  // 2.0 metres de cable par tour tambour
END_VAR

{region "§0 Session simulation & aiguillage"}
// === 🧪 §0 SIMULATION & SÉLECTION DE SOURCE ===
// 🎯 Producteur unique des aiguillages Reel/Simu par domaine (HwReal vs HwSim -> HwIn).

SimulationModeRise(CLK := GVL_Simulation.SimulationModeActive);
SimulationModeFall(CLK := GVL_Simulation.SimulationModeActive);

IF SimulationModeRise.Q THEN
    GVL_Simulation.SimWinchActive := TRUE;
    GVL_Simulation.SimTranslationActive := TRUE;
    GVL_Simulation.SimOperatorActive := TRUE;
    GVL_Simulation.SimSafetyActive := TRUE;
END_IF;

IF SimulationModeFall.Q THEN
    GVL_Simulation.SimWinchActive := FALSE;
    GVL_Simulation.SimTranslationActive := FALSE;
    GVL_Simulation.SimOperatorActive := FALSE;
    GVL_Simulation.SimSafetyActive := FALSE;

    GVL_Simulation.SimM3SensorsWordOverrideActive := FALSE;
    GVL_Simulation.SimM3SensorsWord := 16#07;
    GVL_Simulation.SimJoystickLeft_Rev_TREMIE_Active := FALSE;
    GVL_Simulation.SimJoystickRight_Fwd_MAINT_Active := FALSE;
    GVL_Simulation.SimJoystickFwd_Up_Close_Active := FALSE;
    GVL_Simulation.SimJoystickRev_Down_Open_Active := FALSE;
    GVL_Simulation.SimJoystickRawX := 5000;
    GVL_Simulation.SimJoystickRawY := 5000;
    GVL_Simulation.SimJoystickRawButton := FALSE;
    GVL_Simulation.SimEncoderSpeedFactor := 1.0;
    GVL_Simulation.SimSyncDeviationInjectM1 := FALSE;
    GVL_Simulation.SimSyncDeviationInjectM2 := FALSE;
    GVL_Simulation.SimSyncDeviationOffset_M := 0.5;
    GVL_Simulation.SimKoboldContactValue := FALSE;
END_IF;

// 🔀 Aiguillages de source uniques par domaine
WinchInputSourceSimulated       := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimWinchActive;
TranslationInputSourceSimulated := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimTranslationActive;
OperatorInputSourceSimulated    := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimOperatorActive;
MachineInputSourceSimulated     := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimSafetyActive;
{endregion}

{region "§1 Acquisition brute — HwReal"}
// === 📥 §1 ACQUISITION BRUTE MATÉRIELLE (HwReal) ===

// Winch M1 / M2 et codeurs
HwReal.Winch.M1_ContactorsReleased_DI := M1_ContactorsReleased_DI;
HwReal.Winch.M1_ThermalOk_DI          := M1_ThermalOk_DI;
HwReal.Winch.M1_BrakeIsOpen_DI        := M1_BrakeIsOpen_DI;

HwReal.Winch.M2_ContactorsReleased_DI := M2_ContactorsReleased_DI;
HwReal.Winch.M2_ThermalOk_DI          := M2_ThermalOk_DI;
HwReal.Winch.M2_BrakeIsOpen_DI        := M2_BrakeIsOpen_DI;

HwReal.Winch.M1M2_TopPositionFree_DI  := M1M2_TopPositionFree_DI;
HwReal.Winch.M2_TensionedCable_DI     := M2_TensionedCable_DI;

HwReal.Winch.COD1_PosValue            := COD1_PosValue;
HwReal.Winch.COD1_Alarms              := COD1_Alarms;
HwReal.Winch.COD1_Warnings            := COD1_Warnings;
HwReal.Winch.COD1_DeviceState         := COD1_CODEUR.GetDeviceState();

HwReal.Winch.COD2_PosValue            := COD2_PosValue;
HwReal.Winch.COD2_Alarms              := COD2_Alarms;
HwReal.Winch.COD2_Warnings            := COD2_Warnings;
HwReal.Winch.COD2_DeviceState         := COD2_CODEUR.GetDeviceState();

// Translation M3 et variateur AC600
HwReal.Translation.M3_PosTremie_DI      := M3_PosTremie_DI;
HwReal.Translation.M3_PosPV_DI          := M3_PosPV_DI;
HwReal.Translation.M3_PosPVP2_DI        := M3_PosPVP2_DI;
HwReal.Translation.M3_PosP1_DI          := M3_PosP1_DI;
HwReal.Translation.M3_PosMaintenance_DI := M3_PosMaintenance_DI;
HwReal.Translation.M3_BrakeIsOpen_DI    := M3_BrakeIsOpen_DI;
HwReal.Translation.M3_ThermalOK_DI       := M3_ThermalOK_DI;
HwReal.Translation.M3_StatusWord        := M3_StatusWord;
HwReal.Translation.M3_ActualFrequencyHz := M3_ActualFrequencyHz;
HwReal.Translation.AC600_DeviceState    := AC600_ECAT_Drive.GetDeviceState();

// Opérateur / Joystick / bus CANopen
HwReal.Operator.JoyXRaw_ANA1      := JoyXRaw_ANA1;
HwReal.Operator.JoyYRaw_ANA2      := JoyYRaw_ANA2;
HwReal.Operator.JoyBtnRaw         := JoyBtnRaw;
HwReal.Operator.CanBusState       := CANbus.GetBusState();
HwReal.Operator.JOY1_DeviceState  := JOY1_JOYSTICK_MCB560_CO4201A.GetDeviceState();

// Sécurités / Communs Machine
HwReal.Machine.PowerContactorEngaged_DI   := PowerContactorEngaged_DI;
HwReal.Machine.EmergencyChainClosed_DI    := EmergencyChainClosed_DI;
HwReal.Machine.PhaseRotationOk_DI         := PhaseRotationOk_DI;
HwReal.Machine.M1_M2_M3_BrakeThermalOk_DI  := M1_M2_M3_BrakeThermalOk_DI;
HwReal.Machine.M1_M2_KoboldBottomTouch_DI  := M1_M2_KoboldBottomTouch_DI;
HwReal.Machine.HydraulicThermalOk_DI       := HydraulicThermalOk_DI;
HwReal.Machine.ConveyorInfeedReady_DI      := ConveyorInfeedReady_DI;
HwReal.Machine.HopperFull_OR_GateRaised_DI := HopperFull_OR_GateRaised_DI; // Déclaré, pas encore consommé
{endregion}

{region "§1bis Diagnostic modules DI"}
// 🩺 Diagnostic carte des 3 modules DI portant les 22 TOR réelles (AF06 §3bis).
// GetDeviceState() = RUNNING => module opérationnel. Si la simulation globale/machine est active,
// les cartes physiques absentes sont simulées OK pour permettre le fonctionnement banc.
IF MachineInputSourceSimulated THEN
    Data.LocalDigitalIoOk := TRUE;
    Data.Vh0800EndOk      := TRUE;
    Data.Vh0808EtpOk      := TRUE;
ELSE
    Data.LocalDigitalIoOk := (Local_Digital_IO.GetDeviceState() = DEVICE_STATE.RUNNING);
    Data.Vh0800EndOk      := (VH_0800END.GetDeviceState() = DEVICE_STATE.RUNNING);
    Data.Vh0808EtpOk      := (VH_0808ETP.GetDeviceState() = DEVICE_STATE.RUNNING);
END_IF;
Data.InputModuleFault := NOT (Data.LocalDigitalIoOk AND Data.Vh0800EndOk AND Data.Vh0808EtpOk);
{endregion}

{region "§1ter Diagnostic reseaux (CANopen + EtherCAT)"}
// 🔌 Diagnostics reseau produits ICI (rang 02) car consommes par PRG_02 (joystick,
// codeurs) et par les PRG 04/05 — producteur avant consommateur (AF02 §4).
instDiagCanOpen(
    Enable                 := TRUE,
    Reset                  := PRG_07_Supervision.FaultMachineReset_IHM,
    CANbusStateRaw         := HwReal.Operator.CanBusState,
    DeviceJoystickStateRaw := HwReal.Operator.JOY1_DeviceState,
    SimBypassActive        := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimOperatorActive,
    NetworkBypassActive    := GVL_IHM.Network.Bypass.Global
);
instDiagEthercat(
    Enable                   := TRUE,
    Reset                    := PRG_07_Supervision.FaultMachineReset_IHM,
    DeviceVariateurStateRaw  := HwReal.Translation.AC600_DeviceState,
    DeviceVariateurSimBypass := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimTranslationActive,
    DeviceEncoderM1StateRaw  := HwReal.Winch.COD1_DeviceState,
    DeviceEncoderM1SimBypass := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimWinchActive,
    DeviceEncoderM2StateRaw  := HwReal.Winch.COD2_DeviceState,
    DeviceEncoderM2SimBypass := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimWinchActive,
    NetworkBypassActive      := GVL_IHM.Network.Bypass.Global
);
{endregion}

{region "§2 Simulation et aiguillage — HwIn"}
// === 🎭 §2 SIMULATION & AIGUILLAGE (HwIn) ===

instSimBench(
    Enable                   := GVL_Simulation.SimulationModeActive,
    M1_RelayFwd              := PRG_06_Outputs.Data.M1RelayFwd,
    M1_RelayRev              := PRG_06_Outputs.Data.M1RelayRev,
    M1_SpeedContactor_1      := PRG_06_Outputs.Data.M1SpeedContactor1,
    M1_SpeedContactor_2      := PRG_06_Outputs.Data.M1SpeedContactor2,
    M1_SpeedContactor_3      := PRG_06_Outputs.Data.M1SpeedContactor3,
    M1_SpeedContactor_4      := PRG_06_Outputs.Data.M1SpeedContactor4,
    M1_SpeedRefPct           := PRG_04_Treuils_Benne.Data.M1LogicRequestSpeedRef_Pct,
    M1_StepNumber            := PRG_04_Treuils_Benne.Data.WinchM1State.StepNumber,
    M1_PresetTriggerCmd      := instEncoderM1.HwOut.PresetTriggerCmd,
    M1_PresetValueOut        := instEncoderM1.HwOut.PresetValueOut,
    M1_BrakeCmd              := PRG_06_Outputs.Data.M1BrakeCmd,
    M2_RelayFwd              := PRG_06_Outputs.Data.M2RelayFwd,
    M2_RelayRev              := PRG_06_Outputs.Data.M2RelayRev,
    M2_SpeedContactor_1      := PRG_06_Outputs.Data.M2SpeedContactor1,
    M2_SpeedContactor_2      := PRG_06_Outputs.Data.M2SpeedContactor2,
    M2_SpeedContactor_3      := PRG_06_Outputs.Data.M2SpeedContactor3,
    M2_SpeedContactor_4      := PRG_06_Outputs.Data.M2SpeedContactor4,
    M2_SpeedRefPct           := PRG_04_Treuils_Benne.Data.M2LogicRequestSpeedRef_Pct,
    M2_StepNumber            := PRG_04_Treuils_Benne.Data.WinchM2State.StepNumber,
    M2_PresetTriggerCmd      := instEncoderM2.HwOut.PresetTriggerCmd,
    M2_PresetValueOut        := instEncoderM2.HwOut.PresetValueOut,
    M2_BrakeCmd              := PRG_06_Outputs.Data.M2BrakeCmd,
    // 🧪 Simulation M3 — FIDÉLITÉ : le modèle ne doit progresser QUE quand la
    // vraie machine commande réellement (sortie FB_Translation, post-interlock), pas sur la
    // commande brute (sinon il outrepasse butées/limites). Même principe que les treuils M1/M2
    // (alimentés par la sortie PRG_06). Gate direction + vitesse = demande réelle (rampe/arrêt).
    M3_Direction             := SEL(PRG_05_Translation.Data.TranslationFinalInterlockRequest.RequestedDriveControlWord <> 0,
                                    PRG_05_Translation.M3_Direction_Active, 0),
    M3_SpeedRefPct           := LIMIT(0.0,
                                      PRG_05_Translation.Data.TranslationFinalInterlockRequest.RequestedDriveFreqHz / GVL_PERSISTENT._TranslationMaxFreq_Hz * 100.0,
                                      100.0),
    M3_BrakeCmd              := PRG_06_Outputs.Data.TranslationBrakeCmd,
    PowerKeepAlive_A         := PRG_06_Outputs.Data.PowerKeepAliveACmd,
    PowerKeepAlive_B         := PRG_06_Outputs.Data.PowerKeepAliveBCmd,
    // 🧪 Simulation uniquement : l'état étape 5 sécurise le transfert même si la sortie
    // inter-POU ArmPulse est observée avec un cycle de retard dans la tâche.
    EmergencyArming_RQ       := PRG_06_Outputs.Data.EmergencyArmingCmd
                                 OR (PRG_06_Outputs.ArmingSeqStep = 5),
    SimEncoderSpeedFactor    := GVL_Simulation.SimEncoderSpeedFactor,
    SimSyncDeviationInjectM1 := GVL_Simulation.SimSyncDeviationInjectM1,
    SimSyncDeviationInjectM2 := GVL_Simulation.SimSyncDeviationInjectM2,
    SimSyncDeviationOffset_M := GVL_Simulation.SimSyncDeviationOffset_M,
    SimM3SensorsWordOverrideActive := GVL_Simulation.SimM3SensorsWordOverrideActive,
    SimM3SensorsWord               := GVL_Simulation.SimM3SensorsWord,
    SimJoystickLeft_Rev_TREMIE_Active  := GVL_Simulation.SimJoystickLeft_Rev_TREMIE_Active,
    SimJoystickRight_Fwd_MAINT_Active  := GVL_Simulation.SimJoystickRight_Fwd_MAINT_Active,
    SimJoystickFwd_Up_Close_Active     := GVL_Simulation.SimJoystickFwd_Up_Close_Active,
    SimJoystickRev_Down_Open_Active    := GVL_Simulation.SimJoystickRev_Down_Open_Active,
    SimJoystickRawX                    := GVL_Simulation.SimJoystickRawX,
    SimJoystickRawY                    := GVL_Simulation.SimJoystickRawY,
    SimJoystickRawButton               := GVL_Simulation.SimJoystickRawButton,
    SimKoboldContactValue    := GVL_Simulation.SimKoboldContactValue,
    BtnEmergencyStop         := GVL_IHM.Modes.Cmd.BtnEmergencyCutOff,
    HwReal                   := HwReal,
    RawPosM1                 := _SimEncoderRawPosM1,
    RawPosM2                 := _SimEncoderRawPosM2
);

// Exposition de l'image de simulation produite par le banc
HwSim.Winch       := instSimBench.Winch;
HwSim.Translation := instSimBench.Translation;
HwSim.Operator    := instSimBench.Operator;
HwSim.Machine     := instSimBench.Machine;

IF NOT WinchInputSourceInitialized THEN
    PreviousWinchInputSourceSimulated := WinchInputSourceSimulated;
    WinchInputSourceInitialized := TRUE;
    Data.WinchInputSourceChanged := FALSE;
ELSE
    Data.WinchInputSourceChanged := (WinchInputSourceSimulated <> PreviousWinchInputSourceSimulated);
    PreviousWinchInputSourceSimulated := WinchInputSourceSimulated;
END_IF;

// 🔧 SEL(G, IN0, IN1) : brique standard IEC 61131-3, retourne IN1 si G=TRUE, IN0 sinon
// (AF_Partie-03 §1 : composer l'existant avant réimplémentation) — remplace les 4 IF/ELSE
// compactés qui cassaient le générateur ST→LD (CODE_QUALITY_STANDARDS.md §11).
// Utilisation explicite de HwSim.* et des 4 variables de sélection par domaine.
HwIn.Winch       := SEL(WinchInputSourceSimulated, HwReal.Winch, HwSim.Winch);
HwIn.Translation := SEL(TranslationInputSourceSimulated, HwReal.Translation, HwSim.Translation);
HwIn.Operator    := SEL(OperatorInputSourceSimulated, HwReal.Operator, HwSim.Operator);
HwIn.Machine     := SEL(MachineInputSourceSimulated, HwReal.Machine, HwSim.Machine);
{endregion}


{region "§3 Traitement joystick"}
// === 🕹️ §3 TRAITEMENT JOYSTICK ===

instJoystick(
    Enable                    := TRUE,
    Reset                     := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged     := HwIn.Machine.PowerContactorEngaged_DI,
    Mode                      := PRG_03_Modes_Cycle.Auth.Mode,
    BenneBusy                 := PRG_04_Treuils_Benne.instBucket.Status.Busy,
    PreserveArmingAfterBucket := PRG_04_Treuils_Benne.instExtractionSequence.Status.Busy
                                 AND (PRG_04_Treuils_Benne.instExtractionSequence.ExtractionState = E_ExtractionSequenceState.CLOSING_BUCKET),
    BusCanOpenOP              := instDiagCanOpen.DeviceCanOpenMaster,
    JoystickOP                := instDiagCanOpen.DeviceJoystick,
    RawX                      := HwIn.Operator.JoyXRaw_ANA1,
    RawY                      := HwIn.Operator.JoyYRaw_ANA2,
    RawButton                 := HwIn.Operator.JoyBtnRaw,
    BtnCalibrate              := GVL_IHM.JOY1Joystick.Cmd.BtnCalibrate,
    InvertX                   := _JoystickInvertX,
    InvertY                   := _JoystickInvertY,
    DeadbandRaw               := _JoystickDeadbandRaw,
    FilterTime                := _JoystickFilterTime,
    NeutralHoldTime           := T#100MS,
    DeadmanArmHoldTime        := T#100MS,
    DeadmanArmGraceTime       := T#3S,
    NeutralXMem               := _JoystickNeutralX,
    NeutralYMem               := _JoystickNeutralY
);

// 📤 Publication des états et axes joystick
Data.JoystickDeadmanArmed := instJoystick.DeadmanArmed;
Data.JoystickYNeutral     := (instJoystick.DirectionY = 0);
Data.JoystickDirectionX   := instJoystick.DirectionX;
Data.JoystickSpeedPctX    := ABS(instJoystick.SpeedXPct);
