    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'hors defaut, canal A doit etre maintenu');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'hors defaut, canal B doit etre maintenu');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'pas de sequence en cours');

    (* scan 3 : coupure demandee par un metier (Winch/Translation) -- +1 cycle automate *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := TRUE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'PowerCutOffRequest doit couper le canal A');
    ASSERT_FALSE(fb.MAINTAINB_RQ, 'PowerCutOffRequest doit couper le canal B');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'PowerCutOffRequest ne doit jamais declencher une sequence armement');
END_TEST

TEST 'TC-P01-006 echec auto-test (canal colle) + TC-P01-004/009 Reset et re-latch'
    (* scans 1-2 : demarrage + regime etabli, sain *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);

    (* front ArmRequest -> ArmingSeqStep passe a 1 (TestA), boucle encore saine ce scan -- +1 cycle *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'front ArmRequest doit lancer TestA (step 1)');

    (* 200ms plus tard : le canal A est cense etre coupe, mais la boucle reste fermee -> collage *)
    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.ERROR, 'canal colle doit lever une erreur (RedundancyTestFailed)');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'echec auto-test doit ramener la sequence a IDLE');
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'un canal colle bloque aussi le maintien normal (interlock sur Cause brute)');

    (* Reset : doit acquitter l affichage sans redemarrage auto (TC-P01-004) -- +1 cycle *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := TRUE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_FALSE(fb.ERROR, 'Reset doit effacer l affichage du defaut');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'Reset seul ne relance jamais de sequence (pas de redemarrage auto)');

    (* nouvel essai : cause toujours presente (canal toujours colle) -> doit re-alarmer (TC-P01-009) -- +1 cycle *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'un nouveau front ArmRequest doit relancer TestA');

    ADVANCE_TIME(200000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.ERROR, 'cause persistante doit re-alarmer au nouvel essai, meme apres Reset');
END_TEST

(* ═══════════════════════════════════════════════════════════════
   🕹️ FB_Joystick — Acquisition & traitement Hall (Homme-mort ISO 13850)
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-08_Fonction_Joystick_v2.0.md
                   DOC/AF_Partie-03_Contrats_Composants_v2.0.md
   🎯 Rôle : Acquisition 2 axes Hall + bouton homme-mort normatif.
      Pipeline par axe : FB_AxisScale → FB_Filter_PT1 → Homme-Mort → ST_Joystick_AxisCmd.
      Les rampes d'accélération/décélération sont gérées exclusivement par les
      FB de mouvement aval (FB_Winch, FB_Translation), hors de ce bloc.
   🔒 Bouton homme-mort :
      - Armement au neutre strict (ScaleX/Y.OutPct = 0.0).
      - Reconfirmation périodique en mouvement (délai DeadmanRearmTimeout).
      - Désarmement sur maintien au neutre (durée NeutralHoldTime).
   📤 Produit AxisCmdX, AxisCmdY, et signaux de diagnostic/miroir.
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Joystick) ===

FUNCTION_BLOCK FB_Joystick
VAR_INPUT
    Enable          : BOOL;       // Active la logique
    Reset           : BOOL;       // Acquittement défaut
    PowerContactorEngaged : BOOL;       // Conditions globales OK (chaîne AU réarmée)
    Mode            : E_Mode;     // Changement de mode désarme le homme-mort
    BenneBusy       : BOOL;       // Fin de cycle benne (front descendant) désarme le homme-mort
    PreserveArmingAfterBucket : BOOL; // TRUE uniquement pendant fermeture ExtractionSequence : enchaînement palier 1 autorisé
    BusCanOpenOP    : ST_Diag_Device;       // État présence nœud CAN
    JoystickOP      : ST_Diag_Device;       // Mode esclave CANopen actif
    RawX            : INT;        // Valeur brute axe X
    RawY            : INT;        // Valeur brute axe Y
    RawButton       : BOOL;       // État brut bouton
    BtnCalibrate    : BOOL;       // Demande de recalage neutre
    InvertX         : BOOL := FALSE;
    InvertY         : BOOL := FALSE;
    Deadband        : REAL := 10.0;  // Zone morte en %
    FilterTime      : TIME := TIME#100ms;
    DeadmanRearmTimeout : TIME := T#10S; // Délai max entre 2 appuis en mouvement
    NeutralHoldTime     : TIME := T#500MS; // Temps continu au neutre avant désarmement
END_VAR
VAR_OUTPUT
    Ready           : BOOL;       // Prêt à commuter
    Busy            : BOOL;       // Traitement en cours
    Done            : BOOL;       // Données valides dispo
    Error           : BOOL;       // Présence anomalie
    ErrorId         : WORD;       // bit0: "Échec calibration Joystick" - Valeurs RawX/Y hors plage lors du recalage
    AxisCmdX        : ST_Joystick_AxisCmd; // Sortie normalisée X
    AxisCmdY        : ST_Joystick_AxisCmd; // Sortie normalisée Y
    Button          : BOOL;       // Bouton filtré
    NeutralXAct     : INT;        // Point neutre X actuel pour IHM/Test
    NeutralYAct     : INT;        // Point neutre Y actuel pour IHM/Test
    // 🆕 Miroirs directs (maintenance) — mêmes valeurs que AxisCmdX/Y.SpeedRef/.Direction,
    // exposés à plat pour lecture immédiate en vue instance CODESYS (pas de dépliage struct).
    SpeedXPct       : REAL;       // Consigne vitesse axe X en % SIGNÉE (-100..+100), miroir AxisCmdX.SpeedRef
    DirectionX      : INT;        // Sens axe X (-1=Rev/0=Neutre/+1=Fwd), miroir AxisCmdX.Direction
    SpeedYPct       : REAL;       // Consigne vitesse axe Y en % SIGNÉE (-100..+100), miroir AxisCmdY.SpeedRef
    DirectionY      : INT;        // Sens axe Y (-1=Rev/0=Neutre/+1=Fwd), miroir AxisCmdY.Direction
    DeadmanArmed    : BOOL;       // 🆕 Geste armé (bouton appuyé au neutre) — IHM/diagnostic
END_VAR
VAR_IN_OUT
    NeutralXMem     : INT; // Point neutre X persistant global
    NeutralYMem     : INT; // Point neutre Y persistant global
END_VAR
VAR
    CycleTimeCalc   : FB_CycleTime;
    ScaleX          : FB_AxisScale;
    ScaleY          : FB_AxisScale;
    FilterX         : FB_Filter_PT1;
    FilterY         : FB_Filter_PT1;
    CmdXVal         : REAL;
    CmdYVal         : REAL;
    LastCalibrate   : BOOL;
    ResetEdge       : R_TRIG;
    DeadmanEdge     : R_TRIG;
    DeadmanTimer    : TON;
    NeutralHoldTimer: TON;
    LeftNeutralSinceArm : BOOL;
    LastMode        : E_Mode;
    BenneBusyFallEdge : F_TRIG;
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Joystick) ===

// 🛑 1. GATE (Sécurités et coupures prioritaires)
IF NOT Enable OR NOT PowerContactorEngaged OR NOT BusCanOpenOP.Operational OR NOT JoystickOP.Operational THEN
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    AxisCmdX.Enable := FALSE; AxisCmdX.StartStop := FALSE; AxisCmdX.SpeedRef := 0.0; AxisCmdX.Direction := 0;
    AxisCmdY.Enable := FALSE; AxisCmdY.StartStop := FALSE; AxisCmdY.SpeedRef := 0.0; AxisCmdY.Direction := 0;
    SpeedXPct := 0.0; DirectionX := 0;
    SpeedYPct := 0.0; DirectionY := 0;
    Button := FALSE;
    DeadmanArmed := FALSE;   // 🆕 Désarmé sur toute neutralisation — nouvel appui au neutre exigé
    LeftNeutralSinceArm := FALSE;   // 🔧 2026-07-03terdecies — repart propre au prochain armement
    DeadmanTimer(IN := FALSE, PT := DeadmanRearmTimeout);   // 🆕 2026-07-03decies — pas d'accumulation à froid
    NeutralHoldTimer(IN := FALSE, PT := NeutralHoldTime);   // 🆕 2026-07-03duodecies — idem
    NeutralXAct := NeutralXMem;
    NeutralYAct := NeutralYMem;
    LastMode := Mode;   // 🆕 REX 2026-07-08 — pas de faux changement détecté à la réactivation
    RETURN;
END_IF;

Ready := TRUE; Busy := TRUE;

// 🔑 2. RESET DÉFAUT (front + cause disparue, Partie3 §5)
ResetEdge(CLK := Reset);
IF ResetEdge.Q AND (RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000) THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 📥 3. ACQUISITION TIMING & BOUTON
CycleTimeCalc();
Button := RawButton;

// 🎯 4. CALIBRATION DYNAMIQUE (Zone RETAIN)
IF BtnCalibrate AND NOT LastCalibrate THEN
    IF RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000 THEN
        NeutralXMem := RawX;
        NeutralYMem := RawY;
    ELSE
        // Un seul bit pour une seule cause (Partie3 §3)
        ErrorId := ErrorId OR 16#0001;
    END_IF;
END_IF;
Error := (ErrorId <> 16#0000);
LastCalibrate := BtnCalibrate;

// 🧮 4bis. MISE À L'ÉCHELLE (avant homme-mort — le neutre s'évalue sur les 2 axes déjà deadbandés)
ScaleX(RawIn := RawX, Neutral := NeutralXMem, Deadband := Deadband);
ScaleY(RawIn := RawY, Neutral := NeutralYMem, Deadband := Deadband);

// 4ter-bis. CHANGEMENT DE MODE : désarme le homme-mort dès que Mode change
// (MAINT_N1/N2/SEMI_AUTO/AUTO). Évite qu'une commande en cours traverse le changement
// de mode et soit réinterprétée soudainement. Repassage par le neutre + nouvel appui exigé.
IF Mode <> LastMode THEN
    DeadmanArmed := FALSE;
    LeftNeutralSinceArm := FALSE;
END_IF;
LastMode := Mode;

// 4ter-ter. FIN DE CYCLE BENNE : désarmement général pour qu'une fermeture manuelle
// ne démarre jamais M1/M2 par surprise. Exception : ExtractionSequence garde l'armement
// pendant sa fermeture (enchaînement palier 1 sous ses propres interlocks synchro/position).
BenneBusyFallEdge(CLK := BenneBusy);
IF BenneBusyFallEdge.Q AND NOT PreserveArmingAfterBucket THEN
    DeadmanArmed := FALSE;
    LeftNeutralSinceArm := FALSE;
END_IF;

// 4ter. BOUTON HOMME-MORT
DeadmanEdge(CLK := RawButton);

// LeftNeutralSinceArm distingue "vient d'armer, n'a pas encore bougé" (ne désarme pas,
// l'opérateur a le temps qu'il veut pour démarrer) de "a bougé, puis est revenu au neutre"
// (NeutralHoldTime s'applique).
IF NOT DeadmanArmed THEN
    LeftNeutralSinceArm := FALSE;   // Repos/désarmé : prêt pour le prochain armement
ELSIF NOT ((ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0)) THEN
    LeftNeutralSinceArm := TRUE;    // Armé et a quitté le neutre au moins une fois : geste réellement démarré
END_IF;

// Neutre tenu NeutralHoldTime avant désarmement (pas juste traversé). Filtre les inversions
// rapides (Fwd→Rev). Ne s'applique qu'après un geste réellement démarré.
NeutralHoldTimer(IN := DeadmanArmed AND LeftNeutralSinceArm AND (ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0),
                 PT := NeutralHoldTime);
IF NeutralHoldTimer.Q THEN
    DeadmanArmed := FALSE;      // Neutre tenu assez longtemps après geste = fin réelle
END_IF;
IF DeadmanEdge.Q AND (ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0) THEN
    DeadmanArmed := TRUE;       // Appui bouton au neutre = armement
END_IF;

// 4quater. RECONFIRMATION PÉRIODIQUE — tant qu'armé ET en mouvement, le bouton doit être
// maintenu ou ré-appuyé avant DeadmanRearmTimeout. Seul un relâchement prolongé désarme.
// qu'armé ET en mouvement (hors neutre), le bouton doit être soit MAINTENU, soit ré-appuyé, avant
// DeadmanRearmTimeout. ⚠️ CORRECTIF : le 1er jet ne détectait qu'un FRONT (`DeadmanEdge.Q`) — un
// opérateur qui MAINTIENT le bouton enfoncé en continu (réflexe naturel homme-mort) ne générait
// plus jamais de front après le 1er appui → désarmement surprise au bout de 3s MALGRÉ la présence
// continue. Corrigé : `NOT RawButton` (niveau, pas front) — maintenir OU réappuyer dans le délai
// remettent tous les deux `IN` à FALSE (TON.ET repart de 0), seul un RELÂCHEMENT PROLONGÉ désarme.
DeadmanTimer(IN := DeadmanArmed AND NOT ((ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0)) AND NOT RawButton,
             PT := DeadmanRearmTimeout);
IF DeadmanTimer.Q THEN
    DeadmanArmed := FALSE;      // Pas de reconfirmation dans le délai → désarmement (décélération sûre)
END_IF;

// 🕹️ 5. PIPELINE TRAITEMENT — AXE X
IF InvertX THEN
    FilterX(ValueIn := -ScaleX.OutPct, TimeConst := FilterTime, CycleTimeS := CycleTimeCalc.CycleTimeS);
ELSE
    FilterX(ValueIn := ScaleX.OutPct, TimeConst := FilterTime, CycleTimeS := CycleTimeCalc.CycleTimeS);
END_IF;

// Consigne forcée à 0.0 tant que le geste n'est pas armé (homme-mort)
CmdXVal := SEL(DeadmanArmed, 0.0, FilterX.ValueOut);

// Mapping Sortie Standardisée Axe X
AxisCmdX.Enable := TRUE;
AxisCmdX.SpeedRef := CmdXVal;
AxisCmdX.StartStop := (ABS(CmdXVal) > 0.1);

IF CmdXVal > 0.1 THEN
    AxisCmdX.Direction := 1;
ELSIF CmdXVal < -0.1 THEN
    AxisCmdX.Direction := -1;
ELSE
    AxisCmdX.Direction := 0;
    AxisCmdX.SpeedRef := 0.0;
END_IF;

// Miroirs maintenance
SpeedXPct := AxisCmdX.SpeedRef;
DirectionX := AxisCmdX.Direction;

// 🕹️ 6. PIPELINE TRAITEMENT — AXE Y
IF InvertY THEN
    FilterY(ValueIn := -ScaleY.OutPct, TimeConst := FilterTime, CycleTimeS := CycleTimeCalc.CycleTimeS);
ELSE
    FilterY(ValueIn := ScaleY.OutPct, TimeConst := FilterTime, CycleTimeS := CycleTimeCalc.CycleTimeS);
END_IF;

// Consigne forcée à 0.0 tant que le geste n'est pas armé (homme-mort)
CmdYVal := SEL(DeadmanArmed, 0.0, FilterY.ValueOut);

// Mapping Sortie Standardisée Axe Y
AxisCmdY.Enable := TRUE;
AxisCmdY.SpeedRef := CmdYVal;
AxisCmdY.StartStop := (ABS(CmdYVal) > 0.1);

IF CmdYVal > 0.1 THEN
    AxisCmdY.Direction := 1;
ELSIF CmdYVal < -0.1 THEN
    AxisCmdY.Direction := -1;
ELSE
    AxisCmdY.Direction := 0;
    AxisCmdY.SpeedRef := 0.0;
END_IF;

// Miroirs maintenance
SpeedYPct := AxisCmdY.SpeedRef;
DirectionY := AxisCmdY.Direction;

// 📤 7. VALIDATION DES SORTIES ÉTAT
NeutralXAct := NeutralXMem;
NeutralYAct := NeutralYMem;
Done := NOT Error;

(* ═══════════════════════════════════════════════════════════════
   ↔️ PRG_05_Translation — Pilotage de la Translation M3
   ───────────────────────────────────────────────────────────────
   ⚙️ Exécuté par la tâche PLC en position 5 (après PRG_04_Treuils_Benne).
   ✅ Arbitre entre les commandes Manuelles (Joystick) et Automatiques (PRG_03_Modes_Cycle).
   📄 Docs : DOC/AF/AF_Partie-11_Fonction_Translation_v2.2.md
   🛡️ Sécurité : instSafetyTranslationM3 (FB_Safety_Translation) câblée en parallèle
      de instTranslationM3 — SafeStop/PowerCutOff réels.
   ═══════════════════════════════════════════════════════════════ *)

PROGRAM PRG_05_Translation

VAR_INPUT
    // === 📥 ENTRÉES PROGRAMME (AUCUNE - PILOTÉ VIA PRG_02, PRG_03 & PRG_04) ===
END_VAR

VAR_OUTPUT
    // === ⚡ DEMANDES DE SORTIES FINALES & INTERLOCKS ===
    TranslationFinalInterlockRequest : ST_TranslationFinalInterlockRequest; // <-- [ACT] Demande finale et interlocks translation M3

    // === 📊 ÉTATS PUBLICS & SÉCURITÉS TRANSLATION ===
    TranslationState                 : ST_TranslationState;                 // <-- [STAT] Etat public translation M3
    TranslationSafety                : ST_SafetyTranslation;                // <-- [SAFE] Diagnostic et securites translation M3
END_VAR

VAR
    instTranslationM3           : FB_Translation;
    instSafetyTranslationM3     : FB_Safety_Translation;
    instPosEstimatorM3          : FB_Translation_PositionEstimator;

    M3_StartStop_Active     : BOOL;
    M3_Direction_Active     : INT;
    M3_SpeedRef_Active      : REAL;
    M3_PositioningActive    : BOOL;
    M3_PositionSensorTarget : BOOL;

    SelTarget       : INT;
    FreqPct                 : REAL;

    M3_SafeStop_Active      : BOOL; // SafeStop sur défaut module d'entrée (InputModuleFault, AF06 §3bis)
    M3_SafeStop_Aggregate   : BOOL; // 🛡️ SafeStop réellement appliqué au mouvement = InputModuleFault OR safety M3 (8 mécanismes)

    M3_HeightInterlockOk    : BOOL; // TRUE = M1 ET M2 au-dessus de la hauteur mini (ou bypass actif)
    M3_LimitSwitchRevEffective : BOOL; // Coupure dure §5bis — bascule sur P1 si Maintenance interdite
    M3_LimitSwitchFwdStable : BOOL; // Verrou bistable Fdc Trémie (mémorisé stable contre les rebonds)
    M3_LimitSwitchRevStable : BOOL; // Verrou bistable Fdc Maintenance/P1 (mémorisé stable contre les rebonds)

    // Verrous bistables des positions cibles (§0quater) — PositionDecoder n'émet
    // plus qu'un front transitoire par capteur, mémorisé ici jusqu'à dégagement.
    M3_AtTremieStable      : BOOL;
    M3_AtPVStable          : BOOL;
    M3_AtP2Stable          : BOOL;
    M3_AtP1Stable          : BOOL;
    M3_AtMaintenanceStable : BOOL;

    // Libération du verrou §0quater sur MOUVEMENT CONFIRMÉ soutenu (fréquence réelle mesurée,
    // pas juste une consigne de sens), pendant une durée mini avant de considérer qu'on a
    // vraiment quitté le point — pas un changement de sens instantané ni un timer fixe
    // indépendant du mouvement réel (rebond capteur mal filtré).
    TonM3ConfirmedMoving : TON;
    M3_ConfirmedMoving   : BOOL;
END_VAR

{region "§0 Interlock hauteur M1/M2"}
// === 🚧 §0 INTERLOCK HAUTEUR M1/M2 (risque collision translation) ===
// PRG_02_Acquisition s'exécute avant ce POU dans la MainTask (rang 01 < 05) : lecture
// du même scan, aucun retard. Bypass = maintenance consciente, doctrine ST_BypassTranslation.
// ⚠️ Une position encodeur incohérente (hors plage OU homing suspect,
// FB_Encoder_Safety) ne doit PAS pouvoir se lire comme "≥ seuil" par accident — fail-safe :
// hauteur non confirmée = interlock actif (comme une hauteur insuffisante), sauf bypass.
// 🔒 Bypass.Global NE lève PLUS cet interlock (contrairement aux autres
// causes de l'axe M3) — risque de collision jugé trop grave pour être levé par un bypass
// générique. Seul Bypass.MinHeight (dédié, conscient) lève l'anti-collision hauteur.
M3_HeightInterlockOk := GVL_IHM.TranslationM3.Bypass.MinHeight
                        OR (NOT PRG_02_Acquisition.M1_EncoderIncoherent
                            AND NOT PRG_02_Acquisition.M2_EncoderIncoherent
                            AND (PRG_02_Acquisition.CablePosM1 >= GVL_PERSISTENT._TranslationMinHeightM1M2_M)
                            AND (PRG_02_Acquisition.CablePosM2 >= GVL_PERSISTENT._TranslationMinHeightM1M2_M));
TranslationState.HeightInterlockBlocking := NOT M3_HeightInterlockOk;

{endregion}

{region "§0bis Coupure dure limite translation"}
// === 🚧 §0bis COUPURE DURE (LimitSwitchRev) — bascule sur P1 si Maintenance interdite ===
// LimitSwitchFwd/Rev protègent nativement Trémie/Maintenance
// (§5bis FB_Translation : coupure immédiate, sans rampe, dès que CommandedDirection insiste
// dans l'extrémité). P1/P2 n'ont aucune protection dure équivalente — seul le verrou souple
// (arrival-lock) les couvre. Quand Maintenance est interdite, la coupure dure doit protéger
// P1 comme si c'était l'extrémité réelle : mot 00001 (P1=0 ET Maintenance=1), UN CRAN AVANT
// la vraie extrémité Maintenance (00000) — backup si le verrou souple a déjà échoué à arrêter
// avant P1, garde la machine hors de la zone interdite plutôt que d'attendre le vrai fond.
M3_LimitSwitchRevEffective := SEL(PRG_03_Modes_Cycle.Auth.MaintenanceM3TargetEnable,
                                   NOT PRG_02_Acquisition.TranslationPosP1 AND PRG_02_Acquisition.TranslationPosMaintenance,
                                   PRG_02_Acquisition.M3_LimitSwitchRev);

// 🔒 §0ter STABILISATION BISTABLE FINS DE COURSE EXTRÊMES (Trémie & Maintenance/P1)
// Maintient la détection stable à 1 même si le capteur physique vibre ou saute brièvement.
// Se libère uniquement sur un mouvement effectif dans le SENS INVERSE (dégagement).
IF PRG_02_Acquisition.M3_LimitSwitchFwd THEN
    M3_LimitSwitchFwdStable := TRUE;
ELSIF M3_Direction_Active = -1 THEN
    M3_LimitSwitchFwdStable := FALSE;
END_IF;

IF M3_LimitSwitchRevEffective THEN
    M3_LimitSwitchRevStable := TRUE;
ELSIF M3_Direction_Active = 1 OR (PRG_03_Modes_Cycle.Auth.MaintenanceM3TargetEnable AND NOT PRG_02_Acquisition.M3_LimitSwitchRev) THEN
    M3_LimitSwitchRevStable := FALSE;
END_IF;

// 🔒 §0quater MÉMORISATION DU DERNIER POINT ATTEINT (front → jeton unique)
// PositionDecoder n'émet qu'un front transitoire (1 cycle) par capteur, montant OU descendant
// SELON LE SENS (voir FB_Translation_PositionDecoder.st) — mémorisé ici pour
// tenir le niveau nécessaire au débounce (100ms) + verrou anti-rebond (§4ter DirectionAtArrival)
// de FB_Translation, et pour l'affichage IHM. MUTUELLEMENT EXCLUSIFS : un nouveau front RAZ tous
// les autres (jeton "dernier point franchi" unique). Libéré
// (RAZ complet) UNIQUEMENT sur mouvement CONFIRMÉ (fréquence réelle mesurée, pas juste la consigne
// de sens) soutenu ≥1.5s — pas un rebond capteur ni un changement de sens instantané.
M3_ConfirmedMoving := (UINT_TO_REAL(PRG_02_Acquisition.M3_ActualFrequencyHz_Filtered) / 100.0) > 0.5;
TonM3ConfirmedMoving(IN := M3_ConfirmedMoving, PT := T#1s500ms);

IF PRG_02_Acquisition.TranslationAtTremie THEN
    M3_AtTremieStable := TRUE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF PRG_02_Acquisition.TranslationAtPV THEN
    M3_AtPVStable := TRUE; M3_AtTremieStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF PRG_02_Acquisition.TranslationAtP2 THEN
    M3_AtP2Stable := TRUE; M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF PRG_02_Acquisition.TranslationAtP1 THEN
    M3_AtP1Stable := TRUE; M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF PRG_02_Acquisition.TranslationAtMaintenance THEN
    M3_AtMaintenanceStable := TRUE; M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE;
ELSIF TonM3ConfirmedMoving.Q THEN
    // Mouvement réel confirmé ≥1.5s sans nouveau front : on a vraiment quitté le dernier point.
    M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
END_IF;

{endregion}

{region "§1 Arbitrage cible et direction"}
// === 🔀 §1 ARBITRAGE DU SÉLECTEUR DE CIBLE ET DE LA DIRECTION ===

IF PRG_03_Modes_Cycle.Auth.Mode = E_Mode.SEMI_AUTO THEN
    // Pont SEMI_AUTO : consomme la demande du séquenceur de cycle.
    // FB_Cycle produit TranslationCmd.Start conditionné par CycleMotionPermit (homme-mort 3s, D2).
    M3_PositioningActive  := TRUE;
    SelTarget    := PRG_03_Modes_Cycle.instCycleSemiAuto.TranslationCmd.Target;
    M3_StartStop_Active  := PRG_03_Modes_Cycle.instCycleSemiAuto.TranslationCmd.Start;

    // 🔒 Direction/vitesse M3 uniquement si le cycle commande réellement le mouvement (Start).
    // Sans Start, M3 reste à l'arrêt (direction=0, vitesse=0) — aucun mouvement parasite.
    IF M3_StartStop_Active THEN
        M3_SpeedRef_Active := 100.0;
        // Direction déduite de la cible (Trémie=1 → Fwd, sinon Rev)
        IF SelTarget = 1 THEN
            M3_Direction_Active := 1;
        ELSE
            M3_Direction_Active := -1;
        END_IF;
    ELSE
        M3_SpeedRef_Active := 0.0;
        M3_Direction_Active := 0;
    END_IF;
ELSIF (PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N1)
   OR (PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N2) THEN
    M3_PositioningActive := GVL_IHM.TranslationM3.Cmd.SelPositioning;
    SelTarget := 0;

    IF NOT GVL_IHM.Modes.Cmd.TglJoystickMaster AND GVL_IHM.TranslationM3.Cmd.BtnFwd THEN
        M3_Direction_Active := 1;
    ELSIF NOT GVL_IHM.Modes.Cmd.TglJoystickMaster AND GVL_IHM.TranslationM3.Cmd.BtnRev THEN
        M3_Direction_Active := -1;
    ELSIF GVL_IHM.Modes.Cmd.TglJoystickMaster THEN
        M3_Direction_Active := PRG_02_Acquisition.JoystickDirectionX;
    ELSE
        M3_Direction_Active := 0;
    END_IF;

    // Homme-mort exigé même pour boutons IHM en MAINT_N1/N2
    // (AF_Partie-08 §6, AF_Partie-11 §4.2) — pas seulement pour un pilotage joystick réel.
    // TglJoystickMaster consolidé — un seul switch machine (GVL_IHM.Modes.Cmd).
    M3_StartStop_Active := (M3_Direction_Active <> 0)
                           AND (GVL_IHM.TranslationM3.Bypass.Global
                                OR NOT GVL_IHM.Modes.Cmd.TglJoystickMaster
                                OR GVL_IHM.Modes.Cmd.TglJoystickMaster)
                           AND PRG_02_Acquisition.JoystickDeadmanArmed
                           AND M3_HeightInterlockOk; // Hauteur mini M1/M2 (risque collision)

    FreqPct := SEL(GVL_IHM.TranslationM3.Cmd.SetFreq_Hz > 0.0,
                  100.0,
                  (GVL_IHM.TranslationM3.Cmd.SetFreq_Hz / SEL(GVL_PERSISTENT._TranslationMaxFreq_Hz > 0.0, 50.0, GVL_PERSISTENT._TranslationMaxFreq_Hz)) * 100.0);
    // 🕹️ Si TglJoystickMaster (global) = TRUE, le manche (0..100%) est mis à l'échelle sur la consigne SetFreq_Hz (ou 100% si non renseignée).
    M3_SpeedRef_Active := SEL(GVL_IHM.Modes.Cmd.TglJoystickMaster,
                              FreqPct,
                              (PRG_02_Acquisition.JoystickSpeedPctX / 100.0) * FreqPct);
ELSE
    M3_PositioningActive := FALSE;
    SelTarget    := 0;
    M3_StartStop_Active  := FALSE;
    M3_Direction_Active  := 0;
    M3_SpeedRef_Active   := 0.0;
END_IF;

// InvertDirection est appliqué dans FB_Translation (InvertDriveDirection), uniquement au mot
// de commande variateur en sortie — M3_Direction_Active reste partout le sens sémantique réel.

M3_SpeedRef_Active := LIMIT(0.0, ABS(M3_SpeedRef_Active), 100.0);

IF (SelTarget = 4) AND NOT PRG_03_Modes_Cycle.Auth.MaintenanceM3TargetEnable THEN
    SelTarget := 0;
END_IF;

// 🩺 InputModuleFault (AF06 §3bis) : un module DI TOR hors service rend indisponibles
// les retours frein/thermique/positions du VH_0808ETP/VH_0800END portant M3 — rampe rapide.
M3_SafeStop_Active := PRG_02_Acquisition.InputModuleFault;

// En mode manuel (SelTarget=0), n'importe quel des 3 points d'arrêt (Trémie/P1/Maintenance)
// arme le verrou anti-rebond §4ter de FB_Translation (DirectionAtArrival). Mot EXACT
// (TranslationAtXxx), pas le cumulatif (TranslationPosXxx) — front franc à l'arrivée quel que
// soit le sens de venue (voir FB_Translation_PositionDecoder.st).
CASE SelTarget OF
    1: M3_PositionSensorTarget := M3_AtTremieStable;
    2: M3_PositionSensorTarget := M3_AtP2Stable;
    3: M3_PositionSensorTarget := M3_AtP1Stable;
    4: M3_PositionSensorTarget := M3_AtMaintenanceStable;
ELSE
    IF M3_Direction_Active = 1 THEN
        // En Marche Avant (+1 vers Trémie) : seule Trémie est le point d'arrêt automatique
        M3_PositionSensorTarget := M3_AtTremieStable;
    ELSIF M3_Direction_Active = -1 THEN
        // En Marche Arrière (-1 vers Maintenance) :
        // - Si Maintenance autorisée -> arrêt sur Maintenance
        // - Si Maintenance interdite -> arrêt sur P1
        IF PRG_03_Modes_Cycle.Auth.MaintenanceM3TargetEnable THEN
            M3_PositionSensorTarget := M3_AtMaintenanceStable;
        ELSE
            M3_PositionSensorTarget := M3_AtP1Stable;
        END_IF;
    ELSE
        M3_PositionSensorTarget := FALSE;
    END_IF;
END_CASE;


{endregion}

{region "§1bis Securite M3"}
// === 🛡️ §1bis SÉCURITÉ M3 (FB_Safety_Translation, câblée en parallèle visible) ===
// ⚠️ Ordre d'appel volontaire : la safety lit ici le BrakeReleaseRequest et le
// BrakeCmd du SCAN PRÉCÉDENT d'instTranslationM3 (elle est appelée avant), soit un retard
// d'un scan. Bénin : BrakeReleaseRequest ne change pas plus vite qu'un scan MainTask 10 ms
// sur une commande frein.
instSafetyTranslationM3(
    Enable                  := (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.DISABLE),
    Reset                   := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                    := PRG_03_Modes_Cycle.Auth.Mode,
    JoystickOnline          := PRG_07_Supervision.instDiagCanOpen.DeviceJoystick.Online,
    JoystickOperational     := PRG_07_Supervision.instDiagCanOpen.DeviceJoystick.Operational,
    HeartbeatIhmOk          := GVL_IHM.Commun.HeartbeatIhmOk,
    PhaseRotationOk         := PRG_02_Acquisition.HwIn.Machine.PhaseRotationOk_DI,
    BrakeThermalFeedback    := NOT PRG_02_Acquisition.HwIn.Machine.M1_M2_M3_BrakeThermalOk_DI,
    DriveOnline             := PRG_07_Supervision.instDiagEthercat.DeviceVariateur.Online,
    DriveOperational        := PRG_07_Supervision.instDiagEthercat.DeviceVariateur.Operational,
    DriveStatusWord         := PRG_02_Acquisition.M3_StatusWord_Filtered,
    DriveActualFreqHz       := UINT_TO_REAL(PRG_02_Acquisition.M3_ActualFrequencyHz_Filtered) / 100.0,
    BrakeFeedback           := SEL(GVL_IHM.TranslationM3.Bypass.ContactorFeedback OR GVL_IHM.TranslationM3.Bypass.Global, PRG_02_Acquisition.HwIn.Translation.M3_BrakeIsOpen_DI, instTranslationM3.BrakeReleaseRequest),
    BrakeCmd                := instTranslationM3.BrakeReleaseRequest,
    Direction               := M3_Direction_Active,
    LimitSwitchFwd          := M3_LimitSwitchFwdStable,
    LimitSwitchRev          := M3_LimitSwitchRevStable,
    SensorWordIncoherent    := PRG_02_Acquisition.M3_SensorWordIncoherent,
    BypassGlobal            := GVL_IHM.TranslationM3.Bypass.Global,
    BypassOperatorComm      := GVL_IHM.TranslationM3.Bypass.OperatorComm,
    BypassDriveComm         := GVL_IHM.TranslationM3.Bypass.DriveComm,
    BypassPhaseRotation     := GVL_IHM.TranslationM3.Bypass.PhaseRotation,
    BypassBrakeThermal      := GVL_IHM.TranslationM3.Bypass.BrakeThermal,
    BypassMecaB             := GVL_IHM.TranslationM3.Bypass.MecaB,
    BypassMecaA             := GVL_IHM.TranslationM3.Bypass.MecaA,
    BypassLimitSwitch       := GVL_IHM.TranslationM3.Bypass.LimitSwitch,
    BypassSensorIncoherent  := GVL_IHM.TranslationM3.Bypass.SensorIncoherent,
    BypassSafety            := GVL_IHM.TranslationM3.Bypass.Safety,
    BypassProcess           := GVL_IHM.TranslationM3.Bypass.Process
);

// SafeStop réellement appliqué au mouvement = agrégat InputModuleFault OR safety M3
// (8 mécanismes) — aucune des deux causes ne doit être perdue.
M3_SafeStop_Aggregate := M3_SafeStop_Active OR instSafetyTranslationM3.SafeStop;

{endregion}

{region "§2 Pilotage translation M3"}
// === ⚙️ §2 EXÉCUTION PILOTAGE TRANSLATION M3 ===

instTranslationM3(
    Enable                  := (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.DISABLE),
    Reset                   := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                    := PRG_03_Modes_Cycle.Auth.Mode,
    StartStop               := M3_StartStop_Active,
    SafeStop                := M3_SafeStop_Aggregate,
    Direction               := M3_Direction_Active,
    InvertDriveDirection    := GVL_IHM.TranslationM3.Cmd.InvertDirection,
    SpeedRefPct             := M3_SpeedRef_Active,
    PositionSensorTarget    := M3_PositionSensorTarget,
    SlowdownSensorTremie       := PRG_02_Acquisition.TranslationPosPV,
    // Les 5 capteurs forment un code thermomètre cumulatif depuis la Trémie (voir
    // FB_Translation_PositionDecoder.st). Chaque zone est délimitée par "capteur PRÉCÉDENT retombé
    // à 0" ET "capteur de la zone encore à 1" — zone P2→P1 = NOT PosP2 AND PosP1 (mot 00011) ;
    // zone P1→Maintenance = NOT PosP1 AND PosMaintenance (mot 00001). Zones mutuellement exclusives,
    // chacune sa propre vitesse d'approche (CfgApproachSpeedP1_Hz / CfgApproachSpeedMaintenance_Hz).
    SlowdownSensorMaintenance  := (NOT PRG_02_Acquisition.TranslationPosP1) AND PRG_02_Acquisition.TranslationPosMaintenance,
    // Ralentissement P2→P1 UNIQUEMENT si P1 est un vrai point
    // d'arrêt (zone Maintenance NON autorisée). Zone Maintenance autorisée -> 100% vitesse jusqu'à
    // P1, ralentissement seulement après (zone P1→Maintenance, SlowdownSensorMaintenance ci-dessus).
    SlowdownSensorP1           := (NOT PRG_02_Acquisition.TranslationPosP2) AND PRG_02_Acquisition.TranslationPosP1
                                   AND NOT PRG_03_Modes_Cycle.Auth.MaintenanceM3TargetEnable,
    LimitSwitchFwd          := M3_LimitSwitchFwdStable,
    LimitSwitchRev          := M3_LimitSwitchRevStable,
    DriveStatusWord         := PRG_02_Acquisition.M3_StatusWord_Filtered,
    DriveActualFreqHz       := UINT_TO_REAL(PRG_02_Acquisition.M3_ActualFrequencyHz_Filtered) / 100.0,
    CfgRampAccelRate        := _TranslationRampAccelRate_Pct,
    CfgRampDecelNormalRate  := _TranslationRampDecelNormal_Pct,
    CfgRampDecelFastRate    := _TranslationRampDecelFast_Pct,
    ApproachSpeedTremieHz       := GVL_IHM.TranslationM3.Cfg.CfgApproachSpeedTremie_Hz,
    ApproachSpeedMaintenanceHz  := GVL_IHM.TranslationM3.Cfg.CfgApproachSpeedMaintenance_Hz,
    ApproachSpeedP1Hz           := GVL_IHM.TranslationM3.Cfg.CfgApproachSpeedP1_Hz,
    DriveFreqScaleMaxHz     := _TranslationMaxFreq_Hz,
    BrakeFeedback           := SEL(GVL_IHM.TranslationM3.Bypass.ContactorFeedback OR GVL_IHM.TranslationM3.Bypass.Global, PRG_02_Acquisition.HwIn.Translation.M3_BrakeIsOpen_DI, instTranslationM3.BrakeReleaseRequest),
    BypassContactorCheck    := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.ContactorFeedback,
    BypassLimitSwitch       := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.LimitSwitch
);

// 📐 Estimateur de position continue M3 (odométrie + recalage 5 capteurs)
instPosEstimatorM3(
    Enable               := (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.DISABLE),
    Reset                := PRG_07_Supervision.FaultMachineReset_IHM,
    DriveActualFreqHz    := TO_REAL(PRG_02_Acquisition.M3_ActualFrequencyHz_Filtered) / 100.0,
    Direction            := M3_Direction_Active,
    SensorMaintenance    := PRG_02_Acquisition.TranslationPosMaintenance,
    SensorP1             := PRG_02_Acquisition.TranslationPosP1,
    SensorP2             := PRG_02_Acquisition.TranslationPosP2,
    SensorPV             := PRG_02_Acquisition.TranslationPosPV,
    SensorTremie         := PRG_02_Acquisition.TranslationPosTremie,
    PosMaintenanceM      := GVL_PERSISTENT._TranslationPosMaintenance_M,
    PosP1M               := GVL_PERSISTENT._TranslationPosP1_M,
    PosP2M               := GVL_PERSISTENT._TranslationPosP2_M,
    PosPVM               := GVL_PERSISTENT._TranslationPosPV_M,
    PosTremieM           := GVL_PERSISTENT._TranslationPosTremie_M,
    GainMetersPerHzSec   := GVL_PERSISTENT._TranslationGainMetersPerHzSec,
    PersistedPositionM   := GVL_PERSISTENT._TranslationPosEstimated_M,
    PersistedInitialized := GVL_PERSISTENT._TranslationPosEstimatedInitialized
);
// Recopie continue (reprise après reboot, doctrine _TranslationSetFreq_Hz) — pas de bridge dédié.
GVL_PERSISTENT._TranslationPosEstimated_M := instPosEstimatorM3.PositionEstimatedM;
GVL_PERSISTENT._TranslationPosEstimatedInitialized := instPosEstimatorM3.Initialized;


{endregion}

{region "§3 Publication demande translation"}
// === 📤 §3 PUBLICATION DEMANDE BRUTE TRANSLATION ===

TranslationFinalInterlockRequest.Enable := (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.DISABLE);
TranslationFinalInterlockRequest.Reset := PRG_07_Supervision.FaultMachineReset_IHM;
TranslationFinalInterlockRequest.PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI;
TranslationFinalInterlockRequest.SafeStop := M3_SafeStop_Aggregate;
TranslationFinalInterlockRequest.PowerCutOff := instSafetyTranslationM3.PowerCutOff;
TranslationFinalInterlockRequest.BrakeReleaseRequest := instTranslationM3.BrakeReleaseRequest;
TranslationFinalInterlockRequest.BrakeCommandOpenConfirmed := instTranslationM3.BrakeCommandOpenConfirmed;
TranslationFinalInterlockRequest.RequestedDriveControlWord := instTranslationM3.RequestedDriveControlWord;
TranslationFinalInterlockRequest.RequestedDriveFreqHz := instTranslationM3.RequestedDriveFreqHz;

{endregion}

{region "§4 Publication etat IHM"}
// === 📤 PUBLICATION ÉTAT TRANSLATION IHM (lecture seule) ===
TranslationState.FBState := instTranslationM3.State;
TranslationState.Ready := instTranslationM3.Ready;
TranslationState.Busy := instTranslationM3.Busy;
TranslationState.Done := instTranslationM3.Done;
TranslationState.Error := instTranslationM3.Error;
TranslationState.ErrorId := instTranslationM3.ErrorId;
TranslationState.BrakeCmd := instTranslationM3.BrakeReleaseRequest;
TranslationState.BrakeCommandOpenConfirmed := instTranslationM3.BrakeCommandOpenConfirmed;
TranslationState.PositionReached := instTranslationM3.TargetReached;
TranslationState.DriveControlWord := instTranslationM3.RequestedDriveControlWord;
TranslationState.DriveFreqRef_Hz := instTranslationM3.RequestedDriveFreqHz;
TranslationState.ActiveDirection := M3_Direction_Active;
TranslationState.ActiveSpeedRef_Pct := M3_SpeedRef_Active;
TranslationState.PositionTremie := PRG_02_Acquisition.TranslationPosTremie;
TranslationState.PositionPV := PRG_02_Acquisition.TranslationPosPV;
TranslationState.PositionP2 := PRG_02_Acquisition.TranslationPosP2;
TranslationState.PositionP1 := PRG_02_Acquisition.TranslationPosP1;
TranslationState.PositionMaintenance := PRG_02_Acquisition.TranslationPosMaintenance;
// Affichage IHM = M3_AtXxxStable (§0quater) — armé sur front
// (direction-dépendant), libéré sur mouvement réel confirmé ≥1.5s (pas juste un rebond capteur
// ni un changement de sens instantané). Même signal que celui consommé par M3_PositionSensorTarget.
TranslationState.AtTremie := M3_AtTremieStable;
TranslationState.AtPV := M3_AtPVStable;
TranslationState.AtP2 := M3_AtP2Stable;
TranslationState.AtP1 := M3_AtP1Stable;
TranslationState.AtMaintenance := M3_AtMaintenanceStable;
TranslationState.EstimatedPosM3_M := instPosEstimatorM3.PositionEstimatedM;
TranslationState.SensorsWord := PRG_02_Acquisition.M3_SensorsWord;
TranslationState.SensorWordIncoherent := PRG_02_Acquisition.M3_SensorWordIncoherent;
TranslationState.LimitSwitchFwd := M3_LimitSwitchFwdStable;
TranslationState.LimitSwitchRev := M3_LimitSwitchRevStable;
TranslationState.DriveActualFreq_Hz := TO_REAL(PRG_02_Acquisition.M3_ActualFrequencyHz_Filtered) / 100.0;
TranslationState.DriveThermalOk := PRG_02_Acquisition.HwIn.Translation.M3_ThermalOK_DI;
TranslationState.JoystickDeflection_Pct := INT_TO_REAL(PRG_02_Acquisition.HwIn.Operator.JoyXRaw_ANA1);
TranslationState.FinalInterlockState := PRG_06_Outputs_LD.instTranslationOutputInterlockM3.State;
TranslationState.FinalInterlockReason := PRG_06_Outputs_LD.instTranslationOutputInterlockM3.Reason;
TranslationState.FinalInterlockError := PRG_06_Outputs_LD.instTranslationOutputInterlockM3.Error;
TranslationState.FinalInterlockErrorId := PRG_06_Outputs_LD.instTranslationOutputInterlockM3.ErrorId;
TranslationState.FinalBrakeTimeoutElapsed := PRG_06_Outputs_LD.instTranslationOutputInterlockM3.BrakeTimeoutElapsed;
TranslationState.DriveCommReady := (PRG_02_Acquisition.M3_StatusWord_Filtered AND 16#0080) <> 0;
TranslationState.DrivePowerReady := (PRG_02_Acquisition.M3_StatusWord_Filtered AND 16#0001) <> 0;
TranslationState.MaintenanceTargetEnable := PRG_03_Modes_Cycle.Auth.MaintenanceM3TargetEnable;
TranslationState.SimulationModeActive := GVL_Simulation.SimulationModeActive;

// 🛡️ Producteur unique (CODE_QUALITY_STANDARDS §5) : la safety M3 (instSafetyTranslationM3)
// est la source de tous les diagnostics de sécurité (ErrorLimitSwitch/ErrorSensorIncoherent).
// Les erreurs propres au mouvement (frein, variateur AC600) restent sur TranslationState.ErrorId
// ci-dessus, bitfield différent, jamais mélangé.
TranslationSafety.SafeStop := M3_SafeStop_Aggregate;
TranslationSafety.PowerCutOff := instSafetyTranslationM3.PowerCutOff;
TranslationSafety.Error := instSafetyTranslationM3.Error;
TranslationSafety.ErrorId := instSafetyTranslationM3.ErrorId;
TranslationSafety.ErrorOperatorComm := instSafetyTranslationM3.ErrorOperatorComm;
TranslationSafety.ErrorDriveComm := instSafetyTranslationM3.ErrorDriveComm;
TranslationSafety.ErrorPhaseRotation := instSafetyTranslationM3.ErrorPhaseRotation;
TranslationSafety.ErrorBrakeThermal := instSafetyTranslationM3.ErrorBrakeThermal;
TranslationSafety.ErrorMecaB := instSafetyTranslationM3.ErrorMecaB;
TranslationSafety.ErrorMecaA := instSafetyTranslationM3.ErrorMecaA;
TranslationSafety.ErrorLimitSwitch := instSafetyTranslationM3.ErrorLimitSwitch;
TranslationSafety.ErrorSensorIncoherent := instSafetyTranslationM3.ErrorSensorIncoherent;
TranslationSafety.PowerCutOffSafety := PRG_06_Outputs_LD.M3PowerCutOffSafetyInfo;
TranslationSafety.SafeStopSafety := PRG_06_Outputs_LD.M3SafeStopSafetyInfo;
TranslationSafety.BlockedBySafety := PRG_06_Outputs_LD.M3BlockedBySafetyInfo;

{endregion}
END_PROGRAM

SETUP
VAR
    fb : FB_CYCLETIME;
END_VAR
END_SETUP

TEST 'Premier cycle retourne la valeur de secours (pas de dt mesurable)'
    fb(DEFAULTVALUES := 0.004);
    ASSERT_NEAR(fb.CYCLETIMES, 0.004, 0.0001, 'premier appel : aucun dt reel disponible, DefaultValueS renvoye tel quel');
END_TEST

TEST 'Cycle suivant calcule le dt reel ecoule (ms->s)'
    fb(DEFAULTVALUES := 0.004);
    ADVANCE_TIME(10000000);
    fb(DEFAULTVALUES := 0.004);
    ASSERT_NEAR(fb.CYCLETIMES, 0.01, 0.0001, '10ms ecoulees entre les 2 appels -> 0.01s calcule (pas la valeur de secours)');

    ADVANCE_TIME(25000000);
    fb(DEFAULTVALUES := 0.004);
    ASSERT_NEAR(fb.CYCLETIMES, 0.025, 0.0001, 'dt variable d un cycle a l autre correctement mesure (25ms)');
END_TEST

(* =======================================================================
   🔒 FB_Safety_EmergencyManagementOutput — Projection Physique Fail-Safe
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Enable gate + copie consignes logiques vers sorties physiques
   🔒 Polarité : MaintainA/B_RQ en maintien (TRUE = voie saine)
   🔌 Architecture : Projection physique fail-safe
   📄 Doc métier : DOC/AF/AF_Partie-01_Analyse_Fonctionnelle_v2.0.md
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_Safety_EmergencyManagementOutput
VAR_INPUT
    // === CONSIGNES & COMMANDES LOGIQUES ===
    Enable                  : BOOL; // --> [CMD]  Active le pilote (FALSE = toutes sorties a FALSE)
    Cmd                     : ST_Safety_Emergency_InternalCmd; // --> [CMD] Ordres logiques recus du bloc logique

    // === RETOURS D'ETAT & DIAGNOSTICS (MIROIRS) ===
    ChainOk                 : BOOL; // --> [HW]   Miroir EmergencyChainClosed (pour bus State)
    ContactorOk             : BOOL; // --> [HW]   Miroir PowerContactorEngaged (pour bus State)
    ArmingStep              : INT;  // --> [STAT] Miroir ArmingSeqStep (pour bus State)
    Armable                 : BOOL; // --> [STAT] Calcule par Logic (pour bus State)
    ArmingBusy              : BOOL; // --> [STAT] Calcule par Logic (pour bus State)
    Error                   : BOOL; // --> [DIAG] Miroir Error (pour bus Diag)
    ErrorId                 : WORD; // --> [DIAG] Miroir ErrorId (pour bus Diag)
    RedundancyTestFailed    : BOOL; // --> [DIAG] Miroir RedundancyTestFailed (pour bus Diag)
    ArmFailed               : BOOL; // --> [DIAG] Miroir ArmFailed (pour bus Diag)
    LockoutActive           : BOOL; // --> [DIAG] Miroir LockoutActive (pour bus Diag)
END_VAR
VAR_OUTPUT
    // === SORTIES PHYSIQUES TERMINALES ===
    MaintainA_RQ            : BOOL; // <-- [ACT]  Vers relais maintien canal A (TRUE = voie maintenue)
    MaintainB_RQ            : BOOL; // <-- [ACT]  Vers relais maintien canal B (TRUE = voie maintenue)
    ArmPulse_RQ             : BOOL; // <-- [ACT]  Vers contacteur impulsion rearmement (TRUE = pulse actif)

    // === BUS D'ETAT & DIAGNOSTIC PUBLICS ===
    State                   : ST_Safety_Emergency_State; // <-- [STAT] Bus d'etat public
    Diag                    : ST_Safety_Emergency_Diag;  // <-- [DIAG] Bus diagnostic public
END_VAR

// === IMPLEMENTATION ===

{region "§1 Gate"}
IF NOT Enable THEN
    MaintainA_RQ   := FALSE;
    MaintainB_RQ   := FALSE;
    ArmPulse_RQ    := FALSE;

    State.ChainOk        := FALSE;
    State.ContactorOk    := FALSE;
    State.Step           := 0;
    State.Armable        := FALSE;
    State.ArmingBusy     := FALSE;

    Diag.Error                := FALSE;
    Diag.ErrorId              := 16#0000;
    Diag.RedundancyTestFailed := FALSE;
    Diag.ArmFailed            := FALSE;
    Diag.LockoutActive        := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Projection sorties et bus"}
// ⚡ Sorties physiques — écriture directe des ordres logiques
MaintainA_RQ := Cmd.MaintainA_Cmd;
MaintainB_RQ := Cmd.MaintainB_Cmd;
ArmPulse_RQ  := Cmd.ArmPulse_Cmd;

// 🚦 Bus d'état public
State.ChainOk        := ChainOk;
State.ContactorOk    := ContactorOk;
State.Step           := ArmingStep;
State.Armable        := Armable;
State.ArmingBusy     := ArmingBusy;

// 🛡️ Bus diagnostic public
Diag.Error                := Error;
Diag.ErrorId              := ErrorId;
Diag.RedundancyTestFailed := RedundancyTestFailed;
Diag.ArmFailed            := ArmFailed;
Diag.LockoutActive        := LockoutActive;
{endregion}

(* =======================================================================
   ⚙️ FB_DiveSearch — Assistance plongée et recherche du fond Kobold
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Qualification du capteur Kobold et autorisation de descente
   🛡️ Sécurité : Verrouillage si séquence d'immersion 0->1->0 invalide
   🔌 Interface : Intention de descente et mesures vers permis de descente
   📄 Doc métier : DOC/AF/AF_Partie-04_Mode_SemiAuto_Sequenceur_v2.1.md
   ======================================================================= *)
FUNCTION_BLOCK FB_DiveSearch
VAR_INPUT
    // === COMMANDES & AUTORISATIONS ===
    Enable                  : BOOL;         // --> [CMD] Activation generale du FB (TRUE=Autorise)
    Reset                   : BOOL;         // --> [CMD] Acquittement defaut (front)
    PowerContactorEngaged   : BOOL;         // --> [SAFE] Chaine de securite OK
    Mode                    : E_Mode;       // --> [CMD] Mode de fonctionnement arbitre
    MotionRequestActive     : BOOL;         // --> [CMD] Intention de mouvement active
    MotionDirection         : INT;          // --> [CMD] Sens de mouvement (-1 = descente)

    // === CAPTEURS & ETATS BENNE ===
    BucketIsOpen            : BOOL;         // --> [HW] Benne ouverte confirmee
    KoboldImmersed          : BOOL;         // --> [HW] Capteur Kobold immerge (FALSE=hors eau, TRUE=immerge)
    M1Position_M            : REAL;         // --> [HW] Position codeur treuil M1 (m)
    M2Position_M            : REAL;         // --> [HW] Position codeur treuil M2 (m)
    PositionsValid          : BOOL;         // --> [HW] Validite des mesures de position

    // === CONFIGURATION & SEUILS ===
    DiveStartMin_M          : REAL;         // --> [CFG] Seuil position min pour debut plongee (m)
    ImmersionUpper_M        : REAL;         // --> [CFG] Borne haute fenetre d'immersion (m)
    ImmersionLower_M        : REAL;         // --> [CFG] Borne basse fenetre d'immersion (m)
    BypassPreconditions     : BOOL := FALSE;// --> [TST] Bypass preconditions et seuils (mode test)
END_VAR
VAR_OUTPUT
    // === ETATS IEC & DEFECTUOSITES ===
    Ready                   : BOOL;         // <-- [STAT] FB pret a fonctionner
    // Status.ErrorId : bit0 precond, bit1 seq, bit2 cfg
    Status                  : ST_FbStatus;  // <-- [STAT] Etat global FB (Busy/Done/Error/ErrorId/State/StateAtError)
    DiveState               : E_DiveSearchState; // <-- [STAT] Phase interne de recherche fond

    // === PERMIS & AUTORISATIONS ===
    DescendPermit           : BOOL;         // <-- [ACT] Autorisation de descente assistee
    KoboldMeasureEnable     : BOOL;         // <-- [ACT] Activation mesure/acquisition Kobold
    BottomTouchConfirmed    : BOOL;         // <-- [STAT] Contact fond valide et confirme

    // === DIAGNOSTIC IHM ===
    OperatorActionId        : WORD;         // <-- [DIAG] ID action operateur requise
    OperatorAction          : STRING(120);  // <-- [DIAG] Message explicatif operateur
END_VAR
VAR
    // === DETECTEURS DE FRONTS ===
    ResetEdge               : R_TRIG;       // . [LOC] Detecteur front montant Reset
    KoboldRiseEdge          : R_TRIG;       // . [LOC] Detecteur front entrant eau (0->1)
    KoboldFallEdge          : F_TRIG;       // . [LOC] Detecteur front sortie eau / fond (1->0)

    // === VARIABLES LOCALES INTERNES ===
    ImmersionConfirmed      : BOOL;         // . [LOC] Immersion dans la fenetre d'eau validee
    ErrorCausePresent       : BOOL;         // . [LOC] Presence d'une cause de defaut parametrage
END_VAR

{region "§1 Gate desactivation"}
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE; Status.Busy := FALSE; Status.Done := FALSE;
    DescendPermit := FALSE; KoboldMeasureEnable := FALSE;
    BottomTouchConfirmed := FALSE;
    Status.State := E_State.DISABLED;
    Status.StateAtError := E_State.DISABLED;
    DiveState := E_DiveSearchState.WAIT_PRECONDITIONS;
    OperatorActionId := 0; OperatorAction := '';
    ImmersionConfirmed := FALSE;
    RETURN;
END_IF;

{endregion}

{region "§2 Preconditions fronts et rearmement"}
ResetEdge(CLK := Reset);
KoboldRiseEdge(CLK := KoboldImmersed);
KoboldFallEdge(CLK := KoboldImmersed);

ErrorCausePresent := NOT BypassPreconditions AND ((DiveStartMin_M < ImmersionUpper_M)
                  OR (ImmersionUpper_M <= ImmersionLower_M));
IF ErrorCausePresent THEN
    Status.ErrorId := Status.ErrorId OR 16#0004;
END_IF;

(* Reset = front + causes disparues ; aucun redémarrage automatique. *)
IF ResetEdge.Q AND NOT ErrorCausePresent AND NOT KoboldImmersed AND NOT MotionRequestActive THEN
    Status.ErrorId := 16#0000;
    ImmersionConfirmed := FALSE;
    BottomTouchConfirmed := FALSE;
    Status.StateAtError := E_State.DISABLED;
    DiveState := E_DiveSearchState.WAIT_PRECONDITIONS;
END_IF;

DescendPermit := FALSE; KoboldMeasureEnable := FALSE;
Ready := FALSE; Status.Busy := FALSE; Status.Done := FALSE;
OperatorActionId := 0; OperatorAction := '';

{endregion}

{region "§3 Machine etat plongee recherche fond"}
IF Status.ErrorId <> 16#0000 THEN
    Status.State := E_State.READY;
    DiveState := E_DiveSearchState.ERROR_HOLD;
    OperatorActionId := 16#0180;
    OperatorAction := 'Vérifier les conditions puis réarmer avant une nouvelle plongée.';
ELSE
    CASE DiveState OF
        E_DiveSearchState.WAIT_PRECONDITIONS:
            Status.State := E_State.INIT;
            IF NOT BypassPreconditions
               AND (NOT BucketIsOpen OR NOT PositionsValid OR KoboldImmersed
                    OR (M1Position_M < DiveStartMin_M) OR (M2Position_M < DiveStartMin_M)) THEN
                OperatorActionId := 16#0100;
                OperatorAction := 'Vérifier les conditions initiales de plongée.';
            ELSE
                DiveState := E_DiveSearchState.READY_TO_DESCEND;
            END_IF;

        E_DiveSearchState.READY_TO_DESCEND:
            Status.State := E_State.READY;
            Ready := TRUE;
            OperatorActionId := 16#0101;
            OperatorAction := 'Demander une descente pour rechercher le fond.';
            IF MotionRequestActive AND (MotionDirection = -1) THEN
                DiveState := E_DiveSearchState.SEARCHING_IMMERSION;
            END_IF;

        E_DiveSearchState.SEARCHING_IMMERSION:
            Status.State := E_State.BUSY;
            Status.Busy := TRUE;
            DescendPermit := MotionRequestActive AND (MotionDirection = -1);
            KoboldMeasureEnable := TRUE;
            OperatorActionId := 16#0102;
            OperatorAction := 'Maintenir la descente : recherche immersion Kobold.';
            IF KoboldRiseEdge.Q THEN
                IF (M1Position_M <= ImmersionUpper_M) AND (M1Position_M >= ImmersionLower_M)
                   AND (M2Position_M <= ImmersionUpper_M) AND (M2Position_M >= ImmersionLower_M) THEN
                    ImmersionConfirmed := TRUE;
                    DiveState := E_DiveSearchState.SEARCHING_BOTTOM;
                ELSE
                    Status.ErrorId := Status.ErrorId OR 16#0002;
                    Status.StateAtError := Status.State;
                END_IF;
            ELSIF (M1Position_M < ImmersionLower_M) OR (M2Position_M < ImmersionLower_M) THEN
                Status.ErrorId := Status.ErrorId OR 16#0002;
                Status.StateAtError := Status.State;
            END_IF;

        E_DiveSearchState.SEARCHING_BOTTOM:
            Status.State := E_State.BUSY;
            Status.Busy := TRUE;
            DescendPermit := MotionRequestActive AND (MotionDirection = -1);
            KoboldMeasureEnable := TRUE;
            OperatorActionId := 16#0103;
            OperatorAction := 'Maintenir la descente : immersion validée, recherche du fond.';
            IF KoboldFallEdge.Q AND ImmersionConfirmed THEN
                BottomTouchConfirmed := TRUE;
                ImmersionConfirmed := FALSE;
                DiveState := E_DiveSearchState.BOTTOM_CONFIRMED;
            END_IF;

        E_DiveSearchState.BOTTOM_CONFIRMED:
            Status.State := E_State.DONE;
            Status.Done := TRUE;
            OperatorActionId := 16#0104;
            OperatorAction := 'Fond détecté : demander la fermeture ou l extraction.';

        E_DiveSearchState.ERROR_HOLD:
            Status.State := E_State.READY;
    END_CASE;
END_IF;

Status.Error := (Status.ErrorId <> 16#0000);

{endregion}

(* ═══════════════════════════════════════════════════════════════
   🧩 FB_Translation_PositionDecoder — Décodage mot capteurs M3 (5 positions)
   ───────────────────────────────────────────────────────────────
    📄 Doc métier : DOC/AF/AF_Partie-11_Fonction_Translation_v2.2.md
   🧩 Brique technique (AF_Partie-03 §2) : contrat minimal, pas de
      StartStop/Enable/Reset/Mode — décode 5 capteurs TOR (Trémie|PV|P2|P1|
      Maintenance) en mot de progression, dérive les 2 limites extrêmes,
      détecte toute combinaison incohérente (défense en profondeur M3) et
      les fronts individuels par capteur (arrivée/cible, robuste décalage came).
   🎯 Mot valide : progression monotone de 11111 (extrême Trémie) à 00000
      (extrême Maintenance) : 11111→01111→00111→00011→00001→00000.
      Tout autre mot = incohérence câblage/mécanique (capteur collé/HS).
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_Translation_PositionDecoder
VAR_INPUT
    SensorTremie      : BOOL;   // --> [HW] Capteur extrême gauche (Trémie)
    SensorPV          : BOOL;   // --> [HW] Capteur pré-ralentissement avant Trémie (Point de Vitesse)
    SensorP2          : BOOL;   // --> [HW] Capteur zone de travail P2
    SensorP1          : BOOL;   // --> [HW] Capteur zone de travail P1
    SensorMaintenance : BOOL;   // --> [HW] Capteur extrême droite (Maintenance, accès MAINT_N2 uniquement)
END_VAR
VAR_OUTPUT
    LimitSwitchFwd    : BOOL;   // <-- [STAT] Extrême Trémie confirmé (mot = 11111)
    LimitSwitchRev    : BOOL;   // <-- [STAT] Extrême Maintenance confirmé (mot = 00000)
    Incoherent        : BOOL;   // <-- [DIAG] Mot hors des 6 combinaisons valides -> défaut sécurité (SafeStop+PowerCutOff, voir FB_Safety_Translation)
    SensorsWord       : BYTE;   // <-- [DIAG] Diagnostic (bit4=Trémie, bit3=PV, bit2=P2, bit1=P1, bit0=Maintenance)

    // Exposition des positions individuelles pour consommation par les programmes aval
    // ⚠️ CUMULATIF ("au-dessus de ce seuil") — pour le ralentissement d'approche (zone large,
    // doit tenir toute la durée de l'approche, pas juste un instant). Ne PAS utiliser pour
    // détecter une arrivée/cible (voir TranslationAtXxx ci-dessous, mot exact, avec front).
    TranslationPosTremie      : BOOL;   // <-- [STAT] TRUE = capteur Trémie actif
    TranslationPosPV          : BOOL;   // <-- [STAT] TRUE = capteur PV actif
    TranslationPosP2          : BOOL;   // <-- [STAT] TRUE = capteur P2 actif
    TranslationPosP1          : BOOL;   // <-- [STAT] TRUE = capteur P1 actif
    TranslationPosMaintenance : BOOL;   // <-- [STAT] TRUE = capteur Maintenance actif

    // Détection d'arrivée/cible par FRONT DU CAPTEUR PROPRE à chaque position (montant OU
    // descendant) : le franchissement d'un point Xi est marqué par SON PROPRE capteur qui bascule
    // (front descendant en venant de Trémie = on vient de dépasser Xi ; front montant en venant de
    // Maintenance = on vient d'atteindre Xi). Trémie et Maintenance (bouts de chaîne) n'ont qu'un
    // seul sens d'arrivée valide chacun. ⚠️ Signal TRANSITOIRE (1 cycle) — distinct des
    // TranslationPosXxx (niveau cumulatif, réservé au ralentissement). L'appelant
    // (PRG_05_Translation §0quater) le mémorise en verrou bistable pour le débounce/verrou
    // anti-rebond de FB_Translation.
    TranslationAtTremie      : BOOL;   // <-- [STAT] TRUE 1 cycle : front montant SensorTremie (arrivée venant de Maintenance uniquement)
    TranslationAtPV          : BOOL;   // <-- [STAT] TRUE 1 cycle : front (montant ou descendant) SensorPV
    TranslationAtP2          : BOOL;   // <-- [STAT] TRUE 1 cycle : front (montant ou descendant) SensorP2
    TranslationAtP1          : BOOL;   // <-- [STAT] TRUE 1 cycle : front (montant ou descendant) SensorP1
    TranslationAtMaintenance : BOOL;   // <-- [STAT] TRUE 1 cycle : front descendant SensorMaintenance (arrivée venant de Trémie uniquement)
END_VAR

VAR
    EdgeUpTremie      : R_TRIG;   // . [LOC] Front montant Trémie
    EdgeDnTremie      : F_TRIG;   // . [LOC] Front descendant Trémie
    EdgeUpPV          : R_TRIG;   // . [LOC] Front montant PV
    EdgeDnPV          : F_TRIG;   // . [LOC] Front descendant PV
    EdgeUpP2          : R_TRIG;   // . [LOC] Front montant P2
    EdgeDnP2          : F_TRIG;   // . [LOC] Front descendant P2
    EdgeUpP1          : R_TRIG;   // . [LOC] Front montant P1
    EdgeDnP1          : F_TRIG;   // . [LOC] Front descendant P1
    EdgeUpMaintenance : R_TRIG;   // . [LOC] Front montant Maintenance
    EdgeDnMaintenance : F_TRIG;   // . [LOC] Front descendant Maintenance
END_VAR

// === IMPLEMENTATION ===

{region "§1 Assemblage mot et cohérence"}
// 🧾 Assemblage du mot (bit4=Trémie ... bit0=Maintenance, ordre doc AF_Partie-02 §3bis)
SensorsWord := 0;
IF SensorTremie      THEN SensorsWord := SensorsWord OR 16#10; END_IF;
IF SensorPV          THEN SensorsWord := SensorsWord OR 16#08; END_IF;
IF SensorP2          THEN SensorsWord := SensorsWord OR 16#04; END_IF;
IF SensorP1          THEN SensorsWord := SensorsWord OR 16#02; END_IF;
IF SensorMaintenance THEN SensorsWord := SensorsWord OR 16#01; END_IF;

// 🎯 Les 6 combinaisons valides (progression monotone décroissante Trémie→Maintenance)
CASE SensorsWord OF
    2#11111, 2#01111, 2#00111, 2#00011, 2#00001, 2#00000:
        Incoherent := FALSE;
    ELSE
        Incoherent := TRUE;
END_CASE;

// 🚧 Limites extrêmes — uniquement sur mot valide (évite un Fdc fantôme déclenché par une incohérence)
LimitSwitchFwd := (NOT Incoherent) AND (SensorsWord = 2#11111);
LimitSwitchRev := (NOT Incoherent) AND (SensorsWord = 2#00000);
{endregion}

{region "§2 Reprise capteurs"}
// Reprise des capteurs de position pour les consommateurs aval (passthrough, identique à l'entrée filtrée)
// ⚠️ CUMULATIF — voir avertissement en déclaration, réservé au ralentissement d'approche.
TranslationPosTremie      := SensorTremie;
TranslationPosPV          := SensorPV;
TranslationPosP2          := SensorP2;
TranslationPosP1          := SensorP1;
TranslationPosMaintenance := SensorMaintenance;
{endregion}

{region "§3 Fronts individuels"}
// Front individuel par capteur — voir avertissement en déclaration. Transitoire (1 cycle),
// mémorisé par l'appelant.
EdgeUpTremie(CLK := SensorTremie);           EdgeDnTremie(CLK := SensorTremie);
EdgeUpPV(CLK := SensorPV);                   EdgeDnPV(CLK := SensorPV);
EdgeUpP2(CLK := SensorP2);                   EdgeDnP2(CLK := SensorP2);
EdgeUpP1(CLK := SensorP1);                   EdgeDnP1(CLK := SensorP1);
EdgeUpMaintenance(CLK := SensorMaintenance); EdgeDnMaintenance(CLK := SensorMaintenance);

// Front du capteur PROPRE à chaque position — voir modèle en déclaration.
// Extrémités : un seul sens valide chacune. Points intermédiaires : les deux fronts de LEUR PROPRE
// capteur (montant = atteint en venant de Maintenance, descendant = dépassé en venant de Trémie).
TranslationAtTremie      := EdgeUpTremie.Q;
TranslationAtPV          := EdgeUpPV.Q OR EdgeDnPV.Q;
TranslationAtP2          := EdgeUpP2.Q OR EdgeDnP2.Q;
TranslationAtP1          := EdgeUpP1.Q OR EdgeDnP1.Q;
TranslationAtMaintenance := EdgeDnMaintenance.Q;
{endregion}

(* =======================================================================
   ⚙️ FB_Modes — Arbitrage du mode machine
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Source unique du mode arbitré et calcul du bus d'autorisations
   🔒 Sécurité : Refus du mode Semi-Auto en cas de défaut codeur
   🔌 Interface : Standard composant d'arbitrage applicatif
   📄 Doc métier : DOC/AF/AF_Partie-05_Modes_Maintenance_v2.0.md
                   DOC/AF/AF_Partie-03_Contrats_Composants_v2.1.md
   ======================================================================= *)

FUNCTION_BLOCK PUBLIC FB_Modes
VAR_INPUT
    // === GESTION FB & AUTORISATIONS ===
    Enable                  : BOOL;   // --> [CMD] Autorisation generale FB (TRUE = active)
    Reset                   : BOOL;   // --> [CMD] Front acquittement defauts
    PowerContactorEngaged   : BOOL;   // --> [SAFE] Chaine AU OK (TRUE = armee)

    // === SELECTIONS IHM & COMMANDES MODES ===
    SelMode                 : E_Mode; // --> [CMD] Selecteur de mode IHM
    SelSyncEnable           : BOOL;   // --> [CMD] Selection synchro treuils IHM
    InhibitM1Request        : BOOL;   // --> [CMD] Demande inhibition treuil M1
    InhibitM2Request        : BOOL;   // --> [CMD] Demande inhibition treuil M2
    SelHomingApproachEnable : BOOL;   // --> [CMD] Selection approche homing IHM
    JoystickWinchSelectRequest : INT; // --> [CMD] Selection treuils joystick (0=Couple, 1=M1, 2=M2)
    SelMaintenanceZoneAccess: BOOL;   // --> [CMD] Autorisation acces zone maintenance M3

    // === RETOURS CAPTEURS & DIAGNOSTICS ===
    EncoderFaultPresent     : BOOL;   // --> [HW] Defaut codeur agrege (1 cycle retard)
END_VAR
VAR_OUTPUT
    // === ETATS & DIAGNOSTICS IEC ===
    Ready                   : BOOL;   // <-- [STAT] FB pret a fonctionner
    Busy                    : BOOL;   // <-- [STAT] FB en traitement
    Done                    : BOOL;   // <-- [STAT] Traitement termine
    Error                   : BOOL;   // <-- [DIAG] Defaut present
    ErrorId                 : WORD;   // <-- [DIAG] Code erreur (bit0=Semi-Auto refuse)
    State                   : E_State;// <-- [STAT] Etat courant du FB
    StateAtError            : E_State;// <-- [DIAG] Etat au moment du dernier defaut

    // === BUS D'AUTORISATIONS ARBITREES ===
    Auth                    : ST_Modes_Autorisations; // <-- [STAT] Bus d'autorisations typees machine
END_VAR
VAR
    // === SOUS-INSTANCES FB ===
    ResetEdge               : R_TRIG; // * [INST] Detecteur front montant Reset
    ErrorEdge               : R_TRIG; // * [INST] Detecteur front montant Error

    // === VARIABLES LOCALES & MEMOIRES ===
    PrevInhibitM1           : BOOL;   // . [LOC] Memoire etat inhibition M1 (exclusion mutuelle)
    PrevInhibitM2           : BOOL;   // . [LOC] Memoire etat inhibition M2 (exclusion mutuelle)
END_VAR

// === IMPLEMENTATION ===

{region "§1 Gate neutralisation"}
// 1. GATE — neutralisation si désactivé ou AU non armé
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Auth.Mode := E_Mode.DISABLE;
    Auth.SyncEnable := TRUE;
    Auth.InhibitM1 := FALSE;
    Auth.InhibitM2 := FALSE;
    Auth.HomingApproachEnable := FALSE;
    Auth.JoystickWinchSelectArbitrated := 0;  // Couplé nominal par défaut
    Auth.MaintenanceM3TargetEnable := FALSE;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    State := E_State.DISABLED;
    PrevInhibitM1 := FALSE;
    PrevInhibitM2 := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;

{endregion}

{region "§2 Reset et arbitrage mode"}
// 2. RESET FRONT (bit0 = défaut codeur)
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;  // Efface bit0 si front Reset
END_IF;

// 3. GARDE-FOU — refus SEMI_AUTO si défaut codeur
IF (SelMode = E_Mode.SEMI_AUTO) AND EncoderFaultPresent THEN
    ErrorId := ErrorId OR 16#0001;  // bit0 : défaut codeur
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 4. ARBITRAGE DU MODE
// MAINT_N2 accepté directement (authentification côté IHM).
IF (SelMode = E_Mode.SEMI_AUTO) AND EncoderFaultPresent THEN
    Auth.Mode := E_Mode.MAINT_N1;
ELSE
    Auth.Mode := SelMode;
END_IF;

{endregion}

{region "§3 Calcul autorisations machine"}
// 5. SYNC ENABLE — actionnable en MAINT_N1 ou MAINT_N2
// FALSE (désactivé) seulement si en MAINT_N1/N2 ET case décochée ; TRUE partout ailleurs.
Auth.SyncEnable := NOT ((Auth.Mode = E_Mode.MAINT_N1 OR Auth.Mode = E_Mode.MAINT_N2) AND NOT SelSyncEnable);

// 5bis. EXCLUSION MUTUELLE INHIBITIONS + RESET SYNC ENABLE
// Inhibition M1/M2 mutuellement exclusives (soit l'un, soit l'autre, jamais les deux).
// Si les deux demandés simultanément : on garde celle déjà active, sinon on rejette les deux.
// Reset SelSyncEnable si une inhibition devient active (synchro incompatible avec inhibit).
// Mémorisation états précédents pour détection front montant.

// Détection fronts montants inhibitions
IF InhibitM1Request AND NOT PrevInhibitM1 THEN
    // Front montant M1
    IF PrevInhibitM2 THEN
        // M2 déjà actif → rejette M1
        Auth.InhibitM1 := FALSE;
    ELSE
        // M2 inactif → active M1, désactive M2
        Auth.InhibitM1 := TRUE;
        Auth.InhibitM2 := FALSE;
        // Synchro incompatible avec inhibition → reset case IHM
        SelSyncEnable := FALSE;
    END_IF;
ELSIF InhibitM2Request AND NOT PrevInhibitM2 THEN
    // Front montant M2
    IF PrevInhibitM1 THEN
        // M1 déjà actif → rejette M2
        Auth.InhibitM2 := FALSE;
    ELSE
        // M1 inactif → active M2, désactive M1
        Auth.InhibitM2 := TRUE;
        Auth.InhibitM1 := FALSE;
        SelSyncEnable := FALSE;
    END_IF;
ELSE
    // Pas de front montant → maintenir états actuels
    // Mais si les deux demandes sont TRUE sans front (cas synchrone sans transition)
    IF InhibitM1Request AND InhibitM2Request THEN
        // Les deux demandées simultanément sans transition : repli sécurité
        Auth.InhibitM1 := FALSE;
        Auth.InhibitM2 := FALSE;
    END_IF;
END_IF;

// Mise à jour mémoires pour prochaine détection front
PrevInhibitM1 := InhibitM1Request;
PrevInhibitM2 := InhibitM2Request;

// 5bis-bis. Sortie inhibitions effectives (calculées ci-dessus)
Auth.InhibitM1 := (Auth.Mode = E_Mode.MAINT_N2) AND Auth.InhibitM1;
Auth.InhibitM2 := (Auth.Mode = E_Mode.MAINT_N2) AND Auth.InhibitM2;

// 5ter. AUTORISATION ARRÊT HAUT (HomingApproach)
// Uniquement actionnable en MAINT_N2.
Auth.HomingApproachEnable := (Auth.Mode = E_Mode.MAINT_N2) AND SelHomingApproachEnable;

// 5quater. SÉLECTEUR JOYSTICK TREUIL
// M1 seul ou M2 seul autorisé en MAINT_N1 et MAINT_N2. Forcé à Couplé (=0) sinon.
IF (Auth.Mode = E_Mode.MAINT_N2) OR (Auth.Mode = E_Mode.MAINT_N1) THEN
    Auth.JoystickWinchSelectArbitrated := JoystickWinchSelectRequest;
ELSE
    Auth.JoystickWinchSelectArbitrated := 0;  // Couplé nominal forcé
END_IF;

// 5quinquies. CIBLE TRANSLATION MAINTENANCE
// MAINT_N2 ou MAINT_N1 + bit IHM dédié (SelMaintenanceZoneAccess) exigé EN PLUS
Auth.MaintenanceM3TargetEnable := ((Auth.Mode = E_Mode.MAINT_N2) OR (Auth.Mode = E_Mode.MAINT_N1)) AND SelMaintenanceZoneAccess;

// GATE — désactivation inhibitions/sync si mode change (sortie N1/N2)
IF (Auth.Mode <> E_Mode.MAINT_N2) AND (Auth.Mode <> E_Mode.MAINT_N1) THEN
    Auth.InhibitM1 := FALSE;
    Auth.InhibitM2 := FALSE;
    Auth.HomingApproachEnable := FALSE;
    Auth.MaintenanceM3TargetEnable := FALSE;
    Auth.JoystickWinchSelectArbitrated := 0;
END_IF;

{endregion}

{region "§4 Etats et defauts"}
// 6. SORTIES ÉTAT
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

Busy := FALSE;
Done := FALSE;

{endregion}

END_FUNCTION_BLOCK

SETUP
VAR
    fb : FB_JOYSTICK;
    nx : INT := 5000;
    ny : INT := 5000;
    diagOk : ST_DIAG_DEVICE;
    diagDown : ST_DIAG_DEVICE;
END_VAR
END_SETUP

TEST 'Bus non operationnel neutralise les sorties sans lever Error'
    diagDown.ONLINE := FALSE; diagDown.OPERATIONAL := FALSE; diagDown.ERROR := FALSE;
    diagDown.ERRORID := 0; diagDown.STATE := E_DIAG_STATE.INIT; diagDown.STATEATERROR := E_DIAG_STATE.DISABLED;
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;

    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagDown, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);

    ASSERT_FALSE(fb.READY, 'bus CAN non operationnel doit bloquer Ready');
    ASSERT_FALSE(fb.ERROR, 'un bus down est un GATE de securite, PAS une Error diagnostiquee (pas de bit ErrorId leve ici)');
    ASSERT_FALSE(fb.AXISCMDX.ENABLE, 'sorties axe neutralisees si non operationnel');
END_TEST

TEST 'Reset acquitte une erreur de calibration seulement si la cause a disparu'
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;

    (* RawX/RawY hors zone neutre valide (2000..8000) + front BtnCalibrate *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 9500, RAWY := 9500, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);

    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 9500, RAWY := 9500, RAWBUTTON := FALSE, BTNCALIBRATE := TRUE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);

    ASSERT_TRUE(fb.ERROR, 'calibration hors zone doit lever Error');

    (* Reset alors que la cause est toujours presente (axes toujours hors zone) : ne doit PAS acquitter *)
    fb(ENABLE := TRUE, RESET := TRUE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 9500, RAWY := 9500, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);

    ASSERT_TRUE(fb.ERROR, 'Reset ne doit PAS acquitter tant que les axes restent hors zone (cause toujours presente)');

    (* Reset retombe (front consomme) ; axes reviennent en zone ; nouveau front Reset : doit acquitter *)
    fb(ENABLE := TRUE, RESET := FALSE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);

    fb(ENABLE := TRUE, RESET := TRUE, POWERCONTACTORENGAGED := TRUE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300, FILTERTIME := T#0MS,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);

    ASSERT_FALSE(fb.ERROR, 'front Reset avec axes revenus en zone valide doit acquitter (cause disparue + appui conscient)');
END_TEST

(* ═══════════════════════════════════════════════════════════════
   💓 FB_HeartbeatValidation — Suite table-driven Heartbeat IHM↔PLC
   ───────────────────────────────────────────────────────────────
   📄 Doc : DOC/AF_Partie-14_PLC_Tests_Validation_v1.2.md §7
   🎯 Simulation uniquement. Stimuli amont : toggle IHM, demande SEMI_AUTO,
      retours contacteurs/frein M1/M2, frein M3. Jamais d'écriture dans
      SafeStop/PowerCutOff/HeartbeatOk calculés.
   🧪 TC-H1 sain ; TC-H2 perte 2 s ; TC-H3 reprise sans redémarrage ;
      TC-H4 reset conscient ; TC-H5 escalade Méca B M3.
   ═══════════════════════════════════════════════════════════════ *)

FUNCTION_BLOCK PUBLIC FB_HeartbeatValidation
VAR_INPUT
    Start       : BOOL;
    Abort       : BOOL;
    CaseId      : INT; // 0=tous ; 1..5=cas ciblé
END_VAR
VAR_OUTPUT
    Busy                    : BOOL;
    Done                    : BOOL;
    AnyFailed               : BOOL;
    SimGateOk               : BOOL;
    ActiveStimulusId        : INT;
    StepElapsed             : TIME;
    Report                  : ST_TestSuiteReport;
    TerminalState           : E_TestTerminalState;
    ConfigError             : BOOL;
    ConfigErrorStepId       : INT;
    ConfigErrorCheckIdx     : INT;
    ErrorCode               : INT;
    ErrorMessage            : STRING(160);
END_VAR
VAR CONSTANT
    // ── Sondes ──
    SigHeartbeatIhmOk       : INT := 1;
    SigHeartbeatIhmTimeout  : INT := 2;
    SigSafetyM1ErrorId      : INT := 3;
    SigSafetyM2ErrorId      : INT := 4;
    SigSafetyM3ErrorId      : INT := 5;
    SigCycleErrorId         : INT := 6;
    SigM1FwdRevSpeedFbOff   : INT := 7;
    SigM1BrakeFeedback      : INT := 8;
    SigM2FwdRevSpeedFbOff   : INT := 9;
    SigM2BrakeFeedback      : INT := 10;
    SigM3BrakeFeedback      : INT := 11;
    SigM3DriveActualFreqHz  : INT := 12;
    SigM3DriveStatusWord    : INT := 13;
    SigPowerCutOffActive    : INT := 14;
    // ── Étapes ──
    StepTcH1Setup           : INT := 10;
    StepTcH1WaitToggle      : INT := 11;
    StepTcH1Assert          : INT := 12;
    StepTcH1Teardown        : INT := 19;
    StepTcH2Setup           : INT := 20;
    StepTcH2Freeze          : INT := 21;
    StepTcH2Assert          : INT := 22;
    StepTcH2Teardown        : INT := 29;
    StepTcH3Setup           : INT := 30;
    StepTcH3Resume          : INT := 31;
    StepTcH3Assert          : INT := 32;
    StepTcH3Teardown        : INT := 39;
    StepTcH4Setup           : INT := 40;
    StepTcH4Reset           : INT := 41;
    StepTcH4Assert          : INT := 42;
    StepTcH4Teardown        : INT := 49;
    StepTcH5Setup           : INT := 50;
    StepTcH5MecaB           : INT := 51;
    StepTcH5Assert          : INT := 52;
    StepTcH5Teardown        : INT := 59;
END_VAR
VAR
    // Moteur
    Sequencer               : FB_TestSequencer;
    // Tables
    StepTable               : ARRAY[1..GVL_PLC_Tests_Const.MaxSteps]      OF ST_TestStepConfig;
    CheckTable              : ARRAY[1..GVL_PLC_Tests_Const.MaxChecks]     OF ST_TestCheckConfig;
    CaseTable               : ARRAY[1..GVL_PLC_Tests_Const.MaxTestCases]  OF ST_TestCaseConfig;
    InvariantTable          : ARRAY[1..GVL_PLC_Tests_Const.MaxInvariants] OF ST_TestInvariantConfig;
    // Sondes
    ProbeBool               : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeBool]  OF BOOL;
    ProbeDint               : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeDint]  OF DINT;
    ProbeReal               : ARRAY[1..GVL_PLC_Tests_Const.MaxProbeReal]  OF REAL;
    TableReady              : BOOL := FALSE;
    StartPrev               : BOOL;
    // Stimuli locaux
    StimToggleTimer         : TON;
    StimModeRequest         : E_Mode;
    StimResetPulseTimer     : TON;
END_VAR

// ═══════════════════════════════════════════════════════════════
// 1. 🛡️ GATE
// ═══════════════════════════════════════════════════════════════
IF NOT GVL_Simulation.SimulationModeActive THEN
    Sequencer(Start := FALSE, Abort := TRUE, CaseId := CaseId,
              StepTable := StepTable, CheckTable := CheckTable, CaseTable := CaseTable, InvariantTable := InvariantTable,
              ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal, Report := Report);
    GVL_PLC_Tests.OverrideIhmHeartbeatActive := FALSE;
    GVL_PLC_Tests.OverrideM3BrakeStuckOpen := FALSE;
    GVL_PLC_Tests.OverrideM1FwdRevSpeedFbOff := FALSE;
    GVL_PLC_Tests.OverrideM1BrakeFeedback := FALSE;
    GVL_PLC_Tests.OverrideM2FwdRevSpeedFbOff := FALSE;
    GVL_PLC_Tests.OverrideM2BrakeFeedback := FALSE;
    GVL_IHM.Modes.Cmd.BtnFaultReset := FALSE;
    GVL_IHM.Cycle.Cmd.BtnReset := FALSE;
    Busy := FALSE; Done := TRUE; AnyFailed := TRUE;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_ABORTED;
    Report.InProgress := FALSE; Report.Aborted := TRUE; Report.AnyFailed := TRUE;
    Report.TerminalState := TerminalState; Report.FailureSummary := 'Heartbeat : NOT SimulationModeActive';
    RETURN;
END_IF;

SimGateOk := GVL_Simulation.SimulationModeActive
          AND NOT GVL_Simulation.SensorM1ContactorFeedbackIsReal
          AND NOT GVL_Simulation.SensorM2ContactorFeedbackIsReal
          AND NOT GVL_Simulation.SensorBrakeThermalIsReal
          AND NOT GVL_Simulation.SensorM3ContactorFeedbackIsReal;

IF Abort OR NOT SimGateOk THEN
    GVL_PLC_Tests.OverrideIhmHeartbeatActive := FALSE;
    GVL_PLC_Tests.OverrideM3BrakeStuckOpen := FALSE;
    GVL_PLC_Tests.OverrideM1FwdRevSpeedFbOff := FALSE;
    GVL_PLC_Tests.OverrideM1BrakeFeedback := FALSE;
    GVL_PLC_Tests.OverrideM2FwdRevSpeedFbOff := FALSE;
    GVL_PLC_Tests.OverrideM2BrakeFeedback := FALSE;
    GVL_IHM.Modes.Cmd.BtnFaultReset := FALSE;
    GVL_IHM.Cycle.Cmd.BtnReset := FALSE;
    IF Busy THEN GVL_IHM.Modes.Cmd.SelMode := StimModeRequest; END_IF;
    Busy := FALSE; Done := TRUE; AnyFailed := TRUE;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_ABORTED;
    Report.InProgress := FALSE; Report.Aborted := TRUE; Report.AnyFailed := TRUE;
    Report.TerminalState := TerminalState; Report.FailureSummary := 'Heartbeat : ABORTED or SimGateOk=FALSE';
    RETURN;
END_IF;

IF Start AND NOT StartPrev AND NOT Busy THEN
    StartPrev := TRUE;
    Busy := TRUE; Done := FALSE; AnyFailed := FALSE; ConfigError := FALSE;
    ErrorCode := 0; ErrorMessage := '';
    StepElapsed := T#0s;
    StimModeRequest := GVL_IHM.Modes.Cmd.SelMode;

    Report.Name := 'Heartbeat Validation';
    Report.InProgress := TRUE; Report.AllPassed := FALSE; Report.AnyFailed := FALSE; Report.Aborted := FALSE;
    Report.TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    Report.ErrorCode := 0; Report.ErrorMessage := ''; Report.FailureSummary := '';
    Report.FailedTestCase := 0; Report.Duration := T#0s;
    Report.RunCounter := Report.RunCounter + 1;
END_IF;
IF NOT Start THEN StartPrev := FALSE; END_IF;

IF NOT Busy THEN RETURN; END_IF;

// ═══════════════════════════════════════════════════════════════
// 2. 📋 TABLES (remplissage unique)
// ═══════════════════════════════════════════════════════════════
IF NOT TableReady THEN
    Report.Name := 'Heartbeat Validation';

    // ── Cas de tests ──
    CaseTable[1].Name := 'TC-H1 Heartbeat sain';      CaseTable[1].FirstStep := StepTcH1Setup;
    CaseTable[2].Name := 'TC-H2 Perte IHM 2s';        CaseTable[2].FirstStep := StepTcH2Setup;
    CaseTable[3].Name := 'TC-H3 Reprise sans redem';  CaseTable[3].FirstStep := StepTcH3Setup;
    CaseTable[4].Name := 'TC-H4 Reset conscient';     CaseTable[4].FirstStep := StepTcH4Setup;
    CaseTable[5].Name := 'TC-H5 Escalade Meca B M3';  CaseTable[5].FirstStep := StepTcH5Setup;

    // ── Checks (index = ligne CheckTable) ──
    // 1: HeartbeatIhmOk = TRUE
    CheckTable[1].Kind := E_TestCheckKind.BOOL_EQUAL;   CheckTable[1].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[1].ProbeIdx := SigHeartbeatIhmOk;        CheckTable[1].ExpectedBool := TRUE;
    // 2: bit0 Safety M1 = 0
    CheckTable[2].Kind := E_TestCheckKind.WORD_MASK_NONE; CheckTable[2].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[2].ProbeIdx := SigSafetyM1ErrorId;        CheckTable[2].Mask := 16#0001;
    // 3: bit0 Safety M2 = 0
    CheckTable[3].Kind := E_TestCheckKind.WORD_MASK_NONE; CheckTable[3].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[3].ProbeIdx := SigSafetyM2ErrorId;        CheckTable[3].Mask := 16#0001;
    // 4: bit0 Safety M3 = 0
    CheckTable[4].Kind := E_TestCheckKind.WORD_MASK_NONE; CheckTable[4].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[4].ProbeIdx := SigSafetyM3ErrorId;        CheckTable[4].Mask := 16#0001;
    // 5: bit5 Cycle = 0
    CheckTable[5].Kind := E_TestCheckKind.WORD_MASK_NONE; CheckTable[5].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[5].ProbeIdx := SigCycleErrorId;           CheckTable[5].Mask := 16#0020;

    // 6: HeartbeatIhmOk = FALSE
    CheckTable[6].Kind := E_TestCheckKind.BOOL_EQUAL;    CheckTable[6].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[6].ProbeIdx := SigHeartbeatIhmOk;         CheckTable[6].ExpectedBool := FALSE;
    // 7: HeartbeatIhmTimeout = TRUE
    CheckTable[7].Kind := E_TestCheckKind.BOOL_EQUAL;    CheckTable[7].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[7].ProbeIdx := SigHeartbeatIhmTimeout;    CheckTable[7].ExpectedBool := TRUE;
    // 8: bit0 Safety M1 = 1
    CheckTable[8].Kind := E_TestCheckKind.WORD_MASK_ANY; CheckTable[8].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[8].ProbeIdx := SigSafetyM1ErrorId;        CheckTable[8].Mask := 16#0001;
    // 9: bit0 Safety M2 = 1
    CheckTable[9].Kind := E_TestCheckKind.WORD_MASK_ANY; CheckTable[9].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[9].ProbeIdx := SigSafetyM2ErrorId;        CheckTable[9].Mask := 16#0001;
    // 10: bit0 Safety M3 = 1
    CheckTable[10].Kind := E_TestCheckKind.WORD_MASK_ANY; CheckTable[10].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[10].ProbeIdx := SigSafetyM3ErrorId;       CheckTable[10].Mask := 16#0001;
    // 11: bit5 Cycle = 1
    CheckTable[11].Kind := E_TestCheckKind.WORD_MASK_ANY; CheckTable[11].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[11].ProbeIdx := SigCycleErrorId;          CheckTable[11].Mask := 16#0020;

    // 12: SafeStop M1 (via Error)
    CheckTable[12].Kind := E_TestCheckKind.BOOL_EQUAL;   CheckTable[12].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[12].ProbeIdx := SigSafetyM1ErrorId;       CheckTable[12].ExpectedBool := TRUE;
    // 13: SafeStop M2
    CheckTable[13].Kind := E_TestCheckKind.BOOL_EQUAL;   CheckTable[13].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[13].ProbeIdx := SigSafetyM2ErrorId;       CheckTable[13].ExpectedBool := TRUE;
    // 14: SafeStop M3
    CheckTable[14].Kind := E_TestCheckKind.BOOL_EQUAL;   CheckTable[14].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[14].ProbeIdx := SigSafetyM3ErrorId;       CheckTable[14].ExpectedBool := TRUE;

    // 15: HeartbeatIhmOk = TRUE (reprise)
    CheckTable[15].Kind := E_TestCheckKind.BOOL_EQUAL;   CheckTable[15].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[15].ProbeIdx := SigHeartbeatIhmOk;        CheckTable[15].ExpectedBool := TRUE;
    // 16-19: bit0 M1/M2/M3 = 1, bit5 Cycle = 1 (mémorisation)
    CheckTable[16].Kind := E_TestCheckKind.WORD_MASK_ANY; CheckTable[16].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[16].ProbeIdx := SigSafetyM1ErrorId;       CheckTable[16].Mask := 16#0001;
    CheckTable[17].Kind := E_TestCheckKind.WORD_MASK_ANY; CheckTable[17].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[17].ProbeIdx := SigSafetyM2ErrorId;       CheckTable[17].Mask := 16#0001;
    CheckTable[18].Kind := E_TestCheckKind.WORD_MASK_ANY; CheckTable[18].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[18].ProbeIdx := SigSafetyM3ErrorId;       CheckTable[18].Mask := 16#0001;
    CheckTable[19].Kind := E_TestCheckKind.WORD_MASK_ANY; CheckTable[19].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[19].ProbeIdx := SigCycleErrorId;          CheckTable[19].Mask := 16#0020;

    // 20: Reset → bit0 M1/M2/M3 = 0, bit5 Cycle = 0
    CheckTable[20].Kind := E_TestCheckKind.WORD_MASK_NONE; CheckTable[20].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[20].ProbeIdx := SigSafetyM1ErrorId;         CheckTable[20].Mask := 16#0001;
    CheckTable[21].Kind := E_TestCheckKind.WORD_MASK_NONE; CheckTable[21].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[21].ProbeIdx := SigSafetyM2ErrorId;         CheckTable[21].Mask := 16#0001;
    CheckTable[22].Kind := E_TestCheckKind.WORD_MASK_NONE; CheckTable[22].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[22].ProbeIdx := SigSafetyM3ErrorId;         CheckTable[22].Mask := 16#0001;
    CheckTable[23].Kind := E_TestCheckKind.WORD_MASK_NONE; CheckTable[23].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[23].ProbeIdx := SigCycleErrorId;            CheckTable[23].Mask := 16#0020;

    // 24: TC-H5 Méca B M3 — PowerCutOffActive = TRUE
    CheckTable[24].Kind := E_TestCheckKind.BOOL_EQUAL;   CheckTable[24].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[24].ProbeIdx := SigPowerCutOffActive;     CheckTable[24].ExpectedBool := TRUE;

    // ── Étapes ──
    // TC-H1
    StepTable[StepTcH1Setup].Name := 'H1 Setup SEMI_AUTO + toggle sain';
    StepTable[StepTcH1Setup].CaseId := 1; StepTable[StepTcH1Setup].StimulusId := 1;
    StepTable[StepTcH1Setup].CheckIdx[1] := 1; StepTable[StepTcH1Setup].CheckIdx[2] := 2;
    StepTable[StepTcH1Setup].CheckIdx[3] := 3; StepTable[StepTcH1Setup].CheckIdx[4] := 4;
    StepTable[StepTcH1Setup].CheckIdx[5] := 5;
    StepTable[StepTcH1Setup].TimeoutPT := T#5s; StepTable[StepTcH1Setup].NextOnPass := StepTcH1WaitToggle;
    StepTable[StepTcH1Setup].NextOnFail := StepTcH1Teardown; StepTable[StepTcH1Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH1WaitToggle].Name := 'H1 Attente 1er front post-boot';
    StepTable[StepTcH1WaitToggle].CaseId := 1; StepTable[StepTcH1WaitToggle].StimulusId := 1;
    StepTable[StepTcH1WaitToggle].CheckIdx[1] := 1;
    StepTable[StepTcH1WaitToggle].TimeoutPT := T#4s; StepTable[StepTcH1WaitToggle].NextOnPass := StepTcH1Assert;
    StepTable[StepTcH1WaitToggle].NextOnFail := StepTcH1Teardown; StepTable[StepTcH1WaitToggle].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH1Assert].Name := 'H1 Assert bit0=0 & bit5=0';
    StepTable[StepTcH1Assert].CaseId := 1; StepTable[StepTcH1Assert].StimulusId := 1;
    StepTable[StepTcH1Assert].CheckIdx[1] := 2; StepTable[StepTcH1Assert].CheckIdx[2] := 3;
    StepTable[StepTcH1Assert].CheckIdx[3] := 4; StepTable[StepTcH1Assert].CheckIdx[4] := 5;
    StepTable[StepTcH1Assert].TimeoutPT := T#2s; StepTable[StepTcH1Assert].NextOnPass := StepTcH1Teardown;
    StepTable[StepTcH1Assert].NextOnFail := StepTcH1Teardown; StepTable[StepTcH1Assert].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH1Teardown].Name := 'H1 Teardown';
    StepTable[StepTcH1Teardown].CaseId := 1; StepTable[StepTcH1Teardown].StimulusId := 0;
    StepTable[StepTcH1Teardown].DwellPT := T#200ms; StepTable[StepTcH1Teardown].TimeoutPT := T#1s;
    StepTable[StepTcH1Teardown].NextOnPass := 0; StepTable[StepTcH1Teardown].NextOnFail := 0;

    // TC-H2
    StepTable[StepTcH2Setup].Name := 'H2 Setup toggle figé';
    StepTable[StepTcH2Setup].CaseId := 2; StepTable[StepTcH2Setup].StimulusId := 2;
    StepTable[StepTcH2Setup].TimeoutPT := T#1s; StepTable[StepTcH2Setup].NextOnPass := StepTcH2Freeze;
    StepTable[StepTcH2Setup].NextOnFail := StepTcH2Teardown; StepTable[StepTcH2Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH2Freeze].Name := 'H2 Figer toggle > 2s timeout';
    StepTable[StepTcH2Freeze].CaseId := 2; StepTable[StepTcH2Freeze].StimulusId := 2;
    StepTable[StepTcH2Freeze].TimeoutPT := T#3s; StepTable[StepTcH2Freeze].NextOnPass := StepTcH2Assert;
    StepTable[StepTcH2Freeze].NextOnFail := StepTcH2Teardown; StepTable[StepTcH2Freeze].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH2Assert].Name := 'H2 Assert bit0=1 & SafeStop';
    StepTable[StepTcH2Assert].CaseId := 2; StepTable[StepTcH2Assert].StimulusId := 2;
    StepTable[StepTcH2Assert].CheckIdx[1] := 6;  StepTable[StepTcH2Assert].CheckIdx[2] := 7;
    StepTable[StepTcH2Assert].CheckIdx[3] := 8;  StepTable[StepTcH2Assert].CheckIdx[4] := 9;
    StepTable[StepTcH2Assert].CheckIdx[5] := 10; StepTable[StepTcH2Assert].CheckIdx[6] := 11;
    StepTable[StepTcH2Assert].CheckIdx[7] := 12; StepTable[StepTcH2Assert].CheckIdx[8] := 13;
    StepTable[StepTcH2Assert].CheckIdx[9] := 14;
    StepTable[StepTcH2Assert].TimeoutPT := T#3s; StepTable[StepTcH2Assert].NextOnPass := StepTcH2Teardown;
    StepTable[StepTcH2Assert].NextOnFail := StepTcH2Teardown; StepTable[StepTcH2Assert].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH2Teardown].Name := 'H2 Teardown';
    StepTable[StepTcH2Teardown].CaseId := 2; StepTable[StepTcH2Teardown].StimulusId := 0;
    StepTable[StepTcH2Teardown].DwellPT := T#200ms; StepTable[StepTcH2Teardown].TimeoutPT := T#1s;
    StepTable[StepTcH2Teardown].NextOnPass := 0; StepTable[StepTcH2Teardown].NextOnFail := 0;

    // TC-H3
    StepTable[StepTcH3Setup].Name := 'H3 Setup reprise toggle';
    StepTable[StepTcH3Setup].CaseId := 3; StepTable[StepTcH3Setup].StimulusId := 3;
    StepTable[StepTcH3Setup].TimeoutPT := T#1s; StepTable[StepTcH3Setup].NextOnPass := StepTcH3Resume;
    StepTable[StepTcH3Setup].NextOnFail := StepTcH3Teardown; StepTable[StepTcH3Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH3Resume].Name := 'H3 Reprise toggle > 2s';
    StepTable[StepTcH3Resume].CaseId := 3; StepTable[StepTcH3Resume].StimulusId := 3;
    StepTable[StepTcH3Resume].TimeoutPT := T#3s; StepTable[StepTcH3Resume].NextOnPass := StepTcH3Assert;
    StepTable[StepTcH3Resume].NextOnFail := StepTcH3Teardown; StepTable[StepTcH3Resume].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH3Assert].Name := 'H3 Assert bit0=1 & bit5=1';
    StepTable[StepTcH3Assert].CaseId := 3; StepTable[StepTcH3Assert].StimulusId := 3;
    StepTable[StepTcH3Assert].CheckIdx[1] := 15; StepTable[StepTcH3Assert].CheckIdx[2] := 16;
    StepTable[StepTcH3Assert].CheckIdx[3] := 17; StepTable[StepTcH3Assert].CheckIdx[4] := 18;
    StepTable[StepTcH3Assert].CheckIdx[5] := 19;
    StepTable[StepTcH3Assert].TimeoutPT := T#3s; StepTable[StepTcH3Assert].NextOnPass := StepTcH3Teardown;
    StepTable[StepTcH3Assert].NextOnFail := StepTcH3Teardown; StepTable[StepTcH3Assert].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH3Teardown].Name := 'H3 Teardown';
    StepTable[StepTcH3Teardown].CaseId := 3; StepTable[StepTcH3Teardown].StimulusId := 0;
    StepTable[StepTcH3Teardown].DwellPT := T#200ms; StepTable[StepTcH3Teardown].TimeoutPT := T#1s;
    StepTable[StepTcH3Teardown].NextOnPass := 0; StepTable[StepTcH3Teardown].NextOnFail := 0;

    // TC-H4
    StepTable[StepTcH4Setup].Name := 'H4 Setup reset pulse';
    StepTable[StepTcH4Setup].CaseId := 4; StepTable[StepTcH4Setup].StimulusId := 4;
    StepTable[StepTcH4Setup].TimeoutPT := T#1s; StepTable[StepTcH4Setup].NextOnPass := StepTcH4Reset;
    StepTable[StepTcH4Setup].NextOnFail := StepTcH4Teardown; StepTable[StepTcH4Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH4Reset].Name := 'H4 Pulse Reset IHM & Cycle';
    StepTable[StepTcH4Reset].CaseId := 4; StepTable[StepTcH4Reset].StimulusId := 4;
    StepTable[StepTcH4Reset].TimeoutPT := T#2s; StepTable[StepTcH4Reset].NextOnPass := StepTcH4Assert;
    StepTable[StepTcH4Reset].NextOnFail := StepTcH4Teardown; StepTable[StepTcH4Reset].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH4Assert].Name := 'H4 Assert bit0=0 & bit5=0';
    StepTable[StepTcH4Assert].CaseId := 4; StepTable[StepTcH4Assert].StimulusId := 1; // retour toggle sain
    StepTable[StepTcH4Assert].CheckIdx[1] := 20; StepTable[StepTcH4Assert].CheckIdx[2] := 21;
    StepTable[StepTcH4Assert].CheckIdx[3] := 22; StepTable[StepTcH4Assert].CheckIdx[4] := 23;
    StepTable[StepTcH4Assert].TimeoutPT := T#3s; StepTable[StepTcH4Assert].NextOnPass := StepTcH4Teardown;
    StepTable[StepTcH4Assert].NextOnFail := StepTcH4Teardown; StepTable[StepTcH4Assert].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH4Teardown].Name := 'H4 Teardown';
    StepTable[StepTcH4Teardown].CaseId := 4; StepTable[StepTcH4Teardown].StimulusId := 0;
    StepTable[StepTcH4Teardown].DwellPT := T#200ms; StepTable[StepTcH4Teardown].TimeoutPT := T#1s;
    StepTable[StepTcH4Teardown].NextOnPass := 0; StepTable[StepTcH4Teardown].NextOnFail := 0;

    // TC-H5
    StepTable[StepTcH5Setup].Name := 'H5 Setup Meca B M3 frein open';
    StepTable[StepTcH5Setup].CaseId := 5; StepTable[StepTcH5Setup].StimulusId := 5;
    StepTable[StepTcH5Setup].TimeoutPT := T#1s; StepTable[StepTcH5Setup].NextOnPass := StepTcH5MecaB;
    StepTable[StepTcH5Setup].NextOnFail := StepTcH5Teardown; StepTable[StepTcH5Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH5MecaB].Name := 'H5 Perte IHM + M3 open > 3s';
    StepTable[StepTcH5MecaB].CaseId := 5; StepTable[StepTcH5MecaB].StimulusId := 5;
    StepTable[StepTcH5MecaB].TimeoutPT := T#7s; StepTable[StepTcH5MecaB].NextOnPass := StepTcH5Assert;
    StepTable[StepTcH5MecaB].NextOnFail := StepTcH5Teardown; StepTable[StepTcH5MecaB].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH5Assert].Name := 'H5 Assert PowerCutOffActive';
    StepTable[StepTcH5Assert].CaseId := 5; StepTable[StepTcH5Assert].StimulusId := 5;
    StepTable[StepTcH5Assert].CheckIdx[1] := 24;
    StepTable[StepTcH5Assert].TimeoutPT := T#3s; StepTable[StepTcH5Assert].NextOnPass := StepTcH5Teardown;
    StepTable[StepTcH5Assert].NextOnFail := StepTcH5Teardown; StepTable[StepTcH5Assert].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH5Teardown].Name := 'H5 Teardown';
    StepTable[StepTcH5Teardown].CaseId := 5; StepTable[StepTcH5Teardown].StimulusId := 0;
    StepTable[StepTcH5Teardown].DwellPT := T#200ms; StepTable[StepTcH5Teardown].TimeoutPT := T#1s;
    StepTable[StepTcH5Teardown].NextOnPass := 0; StepTable[StepTcH5Teardown].NextOnFail := 0;

    TableReady := TRUE;
END_IF;

// ═══════════════════════════════════════════════════════════════
// 3. 📥 ACQUIRE — câblage sondes (1 ligne par signal, pas de logique)
// ═══════════════════════════════════════════════════════════════
ProbeBool[SigHeartbeatIhmOk]       := PRG_01_Diagnostics.instIhmHeartbeat.HeartbeatIhmOk;
ProbeBool[SigHeartbeatIhmTimeout]  := PRG_01_Diagnostics.instIhmHeartbeat.HeartbeatIhmTimeout;
ProbeDint[SigSafetyM1ErrorId]      := WORD_TO_DINT(PRG_03_Safety.instSafetyWinchM1.ErrorId);
ProbeDint[SigSafetyM2ErrorId]      := WORD_TO_DINT(PRG_03_Safety.instSafetyWinchM2.ErrorId);
ProbeDint[SigSafetyM3ErrorId]      := WORD_TO_DINT(PRG_03_Safety.instSafetyTranslationM3.ErrorId);
ProbeDint[SigCycleErrorId]         := WORD_TO_DINT(PRG_05_Cycle.instCycle.ErrorId);
ProbeBool[SigM1FwdRevSpeedFbOff]   := PRG_00_Inputs.M1FwdRevSpeedFeedbackOff;
ProbeBool[SigM1BrakeFeedback]      := PRG_00_Inputs.M1BrakeFeedback;
ProbeBool[SigM2FwdRevSpeedFbOff]   := PRG_00_Inputs.M2FwdRevSpeedFeedbackOff;
ProbeBool[SigM2BrakeFeedback]      := PRG_00_Inputs.M2BrakeFeedback;
ProbeBool[SigM3BrakeFeedback]      := PRG_00_Inputs.M3BrakeFeedback;
ProbeReal[SigM3DriveActualFreqHz]  := UINT_TO_REAL(PRG_00_Inputs.M3_ActualFrequencyHz_Filtered) / 100.0;
ProbeDint[SigM3DriveStatusWord]    := WORD_TO_DINT(PRG_00_Inputs.M3_StatusWord_Filtered);
ProbeBool[SigPowerCutOffActive]    := GVL_IHM.Modes.State.PowerCutOffActive;

// ═══════════════════════════════════════════════════════════════
// 4. ⚙️ MOTEUR
// ═══════════════════════════════════════════════════════════════
Sequencer(Start := Start, Abort := Abort, CaseId := CaseId,
          StepTable := StepTable, CheckTable := CheckTable, CaseTable := CaseTable, InvariantTable := InvariantTable,
          ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal, Report := Report,
          Busy => Busy, Done => Done, AnyFailed => AnyFailed,
          ConfigError => ConfigError, ConfigErrorStepId => ConfigErrorStepId, ConfigErrorCheckIdx => ConfigErrorCheckIdx,
          ActiveStimulusId => ActiveStimulusId, StepElapsed => StepElapsed,
          TerminalState => TerminalState, ErrorCode => ErrorCode, ErrorMessage => ErrorMessage);

// ═══════════════════════════════════════════════════════════════
// 5. ⚡ STIMULI — modèle hybride : TOR état-complet + pulse timer
// ═══════════════════════════════════════════════════════════════
// StimulusId 0 = neutre garanti (tout relâché) — sur Done/Abort par le moteur
GVL_PLC_Tests.OverrideIhmHeartbeatActive := FALSE;
GVL_PLC_Tests.OverrideM3BrakeStuckOpen := FALSE;
GVL_PLC_Tests.OverrideM1FwdRevSpeedFbOff := FALSE;
GVL_PLC_Tests.OverrideM1BrakeFeedback := FALSE;
GVL_PLC_Tests.OverrideM2FwdRevSpeedFbOff := FALSE;
GVL_PLC_Tests.OverrideM2BrakeFeedback := FALSE;
GVL_IHM.Modes.Cmd.SelMode := StimModeRequest;
GVL_IHM.Modes.Cmd.BtnFaultReset := FALSE;
GVL_IHM.Cycle.Cmd.BtnReset := FALSE;

CASE ActiveStimulusId OF
    1: // TC-H1/TC-H4 : toggle sain 500 ms + SEMI_AUTO
        GVL_PLC_Tests.OverrideIhmHeartbeatActive := TRUE;
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.SEMI_AUTO;
        // Toggle 500 ms
        StimToggleTimer(IN := TRUE, PT := T#500ms);
        IF StimToggleTimer.Q THEN
            GVL_PLC_Tests.OverrideIhmHeartbeatToggle := NOT GVL_PLC_Tests.OverrideIhmHeartbeatToggle;
            StimToggleTimer(IN := FALSE);
        END_IF;

    2: // TC-H2 : toggle figé (perte IHM)
        GVL_PLC_Tests.OverrideIhmHeartbeatActive := TRUE;
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.SEMI_AUTO;
        // OverrideIhmHeartbeatToggle figé = pas de front

    3: // TC-H3 : reprise toggle sain
        GVL_PLC_Tests.OverrideIhmHeartbeatActive := TRUE;
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.SEMI_AUTO;
        StimToggleTimer(IN := TRUE, PT := T#500ms);
        IF StimToggleTimer.Q THEN
            GVL_PLC_Tests.OverrideIhmHeartbeatToggle := NOT GVL_PLC_Tests.OverrideIhmHeartbeatToggle;
            StimToggleTimer(IN := FALSE);
        END_IF;

    4: // TC-H4 : pulse reset conscient
        GVL_PLC_Tests.OverrideIhmHeartbeatActive := TRUE;
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.SEMI_AUTO;
        StimToggleTimer(IN := TRUE, PT := T#500ms);
        IF StimToggleTimer.Q THEN
            GVL_PLC_Tests.OverrideIhmHeartbeatToggle := NOT GVL_PLC_Tests.OverrideIhmHeartbeatToggle;
            StimToggleTimer(IN := FALSE);
        END_IF;
        StimResetPulseTimer(IN := TRUE, PT := T#1500ms);
        IF NOT StimResetPulseTimer.Q THEN
            GVL_IHM.Modes.Cmd.BtnFaultReset := TRUE;
            GVL_IHM.Cycle.Cmd.BtnReset := TRUE;
        END_IF;

    5: // TC-H5 : perte IHM + frein M3 desserré → Méca B
        GVL_PLC_Tests.OverrideIhmHeartbeatActive := TRUE;
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.SEMI_AUTO;
        GVL_PLC_Tests.OverrideM3BrakeStuckOpen := TRUE; // frein M3 desserré
        // Toggle figé = perte IHM
END_CASE;

// ═══════════════════════════════════════════════════════════════
// 6. 🛑 Premier échec → fin explicite, stimuli relâchés, rapport figé
// ═══════════════════════════════════════════════════════════════
IF ErrorCode <> 0 THEN
    GVL_PLC_Tests.OverrideIhmHeartbeatActive := FALSE;
    GVL_PLC_Tests.OverrideM3BrakeStuckOpen := FALSE;
    GVL_PLC_Tests.OverrideM1FwdRevSpeedFbOff := FALSE;
    GVL_PLC_Tests.OverrideM1BrakeFeedback := FALSE;
    GVL_PLC_Tests.OverrideM2FwdRevSpeedFbOff := FALSE;
    GVL_PLC_Tests.OverrideM2BrakeFeedback := FALSE;
    GVL_IHM.Modes.Cmd.BtnFaultReset := FALSE;
    GVL_IHM.Cycle.Cmd.BtnReset := FALSE;
    GVL_IHM.Modes.Cmd.SelMode := StimModeRequest;
    Busy := FALSE; Done := TRUE; AnyFailed := TRUE;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_FAILED;
    Report.InProgress := FALSE; Report.TerminalState := TerminalState;
END_IF;

(* ═══════════════════════════════════════════════════════════════
   🎯 FB_Encoder_Homing — Référencement codeur nominal ou unitaire MAINT_N2
   ───────────────────────────────────────────────────────────────
   📄 Doc métier : DOC/AF_Partie-09_Fonction_Encoder_v2.1.md §1/§5/§7bis
                   DOC/AF_Partie-03_Contrats_Composants_v2.0.md
   🎯 Rôle : Gestion du flux de homing nominal (capteur haut + cible paramétrable)
      ou unitaire (MAINT_N2, treuil sélectionné).
   🧮 Calcul du point de calage :
      - PresetValue = centre de la plage multi-tour (marge anti-débordement)
      - HomingRefRaw = PresetValue - round(CfgTopSensorPosM × PointsPerRev / CableM_PerRev)
   🧊 Expose ST_Encoder_Calib en VAR_IN_OUT (RETAIN).
   ═══════════════════════════════════════════════════════════════ *)

// === DECLARATION (à coller dans la partie déclaration du POU FB_Encoder_Homing) ===

FUNCTION_BLOCK PUBLIC FB_Encoder_Homing
VAR_INPUT
    Enable               : BOOL;        // Standard
    Reset                : BOOL;        // Acquittement défaut (front) — bits 0/2/3/4/5 (voir §ErrorId)
    PowerContactorEngaged      : BOOL;        // Standard
    Mode                 : E_Mode;      // MAINT_N1 requis pour le flux nominal
    Home                 : BOOL;        // Demande de référencement (front, bouton IHM UNIQUE)
    UnitaryMode          : BOOL;        // TRUE = flux unitaire à cible libre (MAINT_N2 uniquement)
    WinchSelected        : BOOL;        // TRUE = cette instance est le treuil sélectionné
    CfgHomingTargetM        : REAL;        // Cible libre unitaire, limitée à [-99.0 ; +99.0] m
    BtnConfirmCoherence     : BOOL;        // Front — lève le doute §3.7 (bit9), sans réhoming complet
    TopPositionSensor    : BOOL;        // 🔧 2026-07-02 : capteur position haute UNIQUE, COMMUN aux 2 treuils
                                         // (les 2 câbles hissent ensemble le même ensemble mécanique) — câblé
                                         // IDENTIQUEMENT sur les instances M1 ET M2 (PAS un capteur par treuil),
                                         // voir PRG_MAIN.st
    CfgTopSensorPosM   : REAL := 8.5;   // Cible homing nominal (RETAIN site, voir Partie10 §7bis)
    FwdRevSpeedFeedbackOff : BOOL;      // Retour unique "tous contacteurs sens+vitesse retombés" CE TREUIL — arrêt confirmé
    BrakeFeedback        : BOOL;        // Retour contacteur frein CE TREUIL (TRUE = ouvert/desserré — révocation 2026-08-03)
    RawPos               : UDINT;       // Sortie FB_Encoder_Abs (déjà gelée sur doute)
    EncoderAvailable     : BOOL;        // Sortie FB_Encoder_Abs
    PresetAck            : BOOL;        // Pulse — sortie FB_Encoder_Abs (écriture confirmée)
    PresetNak            : BOOL;        // Pulse — sortie FB_Encoder_Abs (écriture refusée/timeout)
    PointsPerRev         : UDINT := 8192;   // Confirmé fiche technique (Partie10 §3.3)
    MultiTurnRevsMax     : UDINT := 4096;   // Confirmé fiche technique (Partie10 §3.3)
    CableM_PerRev        : REAL := 2.0;     // Confirmé terrain 2026-07-02 (Partie10 §2)
    BypassGlobal         : BOOL := FALSE;   // 🌐 Ignore arrêt confirmé et capteur haut (mise en service)
END_VAR
VAR_OUTPUT
    Ready                : BOOL;
    Busy                 : BOOL;
    Done                 : BOOL;        // Pulse 1 cycle — référencement réussi (miroir PresetAck)
    Error                : BOOL;
    ErrorId              : WORD;        // Voir table de bits en en-tête de fichier / doc §5
    State                : E_State;
    StateAtError         : E_State;
    PresetRequest        : BOOL;        // Pulse → FB_Encoder_Abs.PresetRequest
    PresetValue          : UDINT;       // → FB_Encoder_Abs.PresetValue (= HomingRefTargetNominal)
    Homed                : BOOL;        // RETAIN interne, miroir Calib.Homed
    HomingSuspect        : BOOL;        // RETAIN interne, miroir Calib.HomingSuspect
    HomingRefRaw         : UDINT;       // RETAIN interne, miroir Calib.HomingRefRaw → FB_Encoder_Scale
END_VAR
VAR_IN_OUT
    Calib                : ST_Encoder_Calib;   // Référence vers l'état persistant global (survit aux téléchargements)
END_VAR
VAR
    ResetEdge            : R_TRIG;
    ErrorEdge            : R_TRIG;
    HomeEdge             : R_TRIG;
    ConfirmCoherenceEdge : R_TRIG;
    InitDone             : BOOL;        // Contrôle cohérence §3.7 fait une fois par session Enable
    ArretConfirme        : BOOL;
    PresetValueCalc      : UDINT;       // = HomingRefTargetNominal (constant tant que PointsPerRev/MultiTurnRevsMax fixes)
    TargetPoints         : DINT;        // Écart signé CfgTopSensorPosM → points, figé pendant la séquence
    TargetPositionM      : REAL;        // Cible retenue : nominale ou unitaire
    RawDiffRestart       : DINT;        // Écart |RawPos - LastKnownRawPos| au redémarrage (§3.7)
END_VAR

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Homing) ===

// 🛑 1. GATE — neutralisation ; on continue toutefois d'exposer le dernier état RETAIN connu
// (FB_Encoder_Scale a besoin de HomingRefRaw même si ce FB est désactivé)
IF NOT Enable OR NOT PowerContactorEngaged THEN
    PresetRequest := FALSE;
    PresetValue := 0;
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    InitDone := FALSE;   // Force un nouveau contrôle §3.7 à la prochaine activation
    Homed := Calib.Homed;
    HomingSuspect := Calib.HomingSuspect;
    HomingRefRaw := Calib.HomingRefRaw;
    RETURN;
END_IF;

Ready := TRUE;

// 🔑 2. FRONTS
ResetEdge(CLK := Reset);
HomeEdge(CLK := Home);
ConfirmCoherenceEdge(CLK := BtnConfirmCoherence);

// 🔍 3. COHÉRENCE AU REDÉMARRAGE (§3.7) — une fois par session Enable, dès que le codeur répond
IF NOT InitDone THEN
    State := E_State.INIT;
    IF EncoderAvailable THEN
        RawDiffRestart := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(Calib.LastKnownRawPos);
        IF Calib.Homed AND (ABS(RawDiffRestart) > UDINT_TO_DINT(Calib.RestartCoherenceTolerancePts)) THEN
            Calib.HomingSuspect := TRUE;
            ErrorId := ErrorId OR 16#0200;   // bit9 : incohérence codeur au redémarrage
        END_IF;
        InitDone := TRUE;
    END_IF;
ELSE
    IF State = E_State.INIT THEN State := E_State.READY; END_IF;
END_IF;

// ✅ 4. LEVÉE DU DOUTE (BtnConfirmCoherence, §3.7) — indépendant du Reset générique
IF ConfirmCoherenceEdge.Q AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2) THEN
    Calib.HomingSuspect := FALSE;
    ErrorId := ErrorId AND 16#FDFF;   // efface bit9
END_IF;

// 🎯 5. DEMANDE DE RÉFÉRENCEMENT (flux nominal)
// Les cibles nominale et unitaire sont rejetées hors du domaine codeur sûr [-99.00;+99.00] m.
// BypassGlobal = TRUE → saute la vérification d'arrêt (mise en service)
ArretConfirme := BypassGlobal OR (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback);

PresetRequest := FALSE;   // Défaut chaque cycle — repose uniquement sur le front HomeEdge ci-dessous
IF HomeEdge.Q AND (State <> E_State.BUSY) THEN
    IF UnitaryMode THEN
        TargetPositionM := CfgHomingTargetM;
    ELSE
        TargetPositionM := CfgTopSensorPosM;
    END_IF;

    // ✅ Homing autorisé en MAINT_N1 et MAINT_N2 — interdit en SEMI_AUTO et en cycle AUTO
    // 🌐 BypassGlobal = TRUE → saute TOUTES les vérifications, force le homing
    IF BypassGlobal THEN
        // Force homing sans condition
        PresetValueCalc := (PointsPerRev * MultiTurnRevsMax) / 2;
        TargetPoints := REAL_TO_DINT(TargetPositionM * UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
        PresetValue := PresetValueCalc;
        PresetRequest := TRUE;
        State := E_State.BUSY;
    ELSIF (Mode <> E_Mode.MAINT_N1) AND (Mode <> E_Mode.MAINT_N2) THEN
        ErrorId := ErrorId OR 16#0001;        // bit0 : mode non autorisé (seulement MAINT N1/N2)
    ELSIF UnitaryMode AND (Mode <> E_Mode.MAINT_N2) THEN
        ErrorId := ErrorId OR 16#0001;
    ELSIF UnitaryMode AND NOT WinchSelected THEN
        ErrorId := ErrorId OR 16#0002;        // bit1 : mauvais treuil sélectionné
    ELSIF NOT EncoderAvailable THEN
        ErrorId := ErrorId OR 16#0008;        // bit3 : codeur indisponible
    ELSIF NOT ArretConfirme THEN
        ErrorId := ErrorId OR 16#0004;        // bit2 : arrêt non confirmé (contacteurs/frein)
    ELSIF (TargetPositionM < -99.0) OR (TargetPositionM > 99.0) THEN
        ErrorId := ErrorId OR 16#0010;        // bit4 : cible nominale/unitaire hors limites
    ELSIF NOT BypassGlobal AND NOT UnitaryMode AND (TargetPositionM <> 0.0) AND TopPositionSensor THEN
        ErrorId := ErrorId OR 16#0010;        // bit4 : capteur position haute non confirmé
    ELSE
        // ✅ Toutes conditions réunies : calcul de la cible brute et déclenchement
        ErrorId := ErrorId AND 16#FFC0;       // Nettoie les erreurs de rejet 0..5
        PresetValueCalc := (PointsPerRev * MultiTurnRevsMax) / 2;               // Centre exact (§3.3)
        TargetPoints := REAL_TO_DINT(TargetPositionM * UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
        PresetValue := PresetValueCalc;
        PresetRequest := TRUE;                // Pulse 1 cycle — FB_Encoder_Abs détecte le front lui-même
        State := E_State.BUSY;
    END_IF;
END_IF;

// ⏳ 6. SUIVI DE LA SÉQUENCE (BUSY → confirmation)
Done := FALSE;
IF State = E_State.BUSY THEN
    IF PresetAck THEN
        Calib.HomingRefRaw := DINT_TO_UDINT(UDINT_TO_DINT(PresetValueCalc) - TargetPoints);
        Calib.Homed := TRUE;
        Calib.HomingSuspect := FALSE;
        Calib.LastKnownRawPos := PresetValueCalc;
        Done := TRUE;
        State := E_State.READY;
        // Un homing réussi efface l'intégralité de ErrorId
        ErrorId := 16#0000;
    ELSIF PresetNak THEN
        ErrorId := ErrorId OR 16#0020;        // bit5 : preset refusé/timeout (voir FB_Encoder_Abs)
        State := E_State.READY;
    END_IF;
END_IF;

// 🧾 7. RESET (front) — efface les bits « dernière tentative rejetée » (pas de cause persistante
// à revérifier ici : le prochain Home réévalue toutes les conditions de zéro, voir §5)
IF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFC0;   // efface bits 0..5 (garde bit9, levé seulement par BtnConfirmCoherence/Home)
END_IF;

// 📤 8. SORTIES ÉTAT
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// Mise à jour continue du point brut valide connu (hors séquence de homing elle-même)
IF EncoderAvailable AND (State <> E_State.BUSY) THEN
    Calib.LastKnownRawPos := RawPos;
END_IF;

Busy := (State = E_State.BUSY);
Homed := Calib.Homed AND NOT Calib.HomingSuspect; // 🆕 REX 2026-07-08 : Perd l'état homed si suspect (démarrage ou fonctionnement), restauré après BtnConfirmCoherence
HomingSuspect := Calib.HomingSuspect;
HomingRefRaw := Calib.HomingRefRaw;

// ═══════════════════════════════════════════════════════════════
// 🧪 ST_TranslationTestResult — Résultat plat de la suite Translation
// ───────────────────────────────────────────────────────────────
// 🎯 Vue synthétique lisible en 1 coup d'œil (IHM/Watch), en complément
//    du rapport détaillé existant ST_TestSuiteReport (Steps[]/Cases[]).
//    Alimenté par FB_TranslationReportFinalizer (CORE).
// ═══════════════════════════════════════════════════════════════

TYPE ST_TranslationTestResult :
STRUCT
    TerminalState    : E_TestTerminalState; // État terminal du dernier run (NONE tant qu'aucun run)
    RequestedCaseId  : INT;                 // CaseId demandé au dernier Start (0=tous, 1..6=case ciblée)
    ExecutedCaseId   : INT;                 // Dernier cas en cours/joué (0 si aucun)
    AllPassed        : BOOL;
    AnyFailed        : BOOL;
    FailedCaseId     : INT;                 // Premier cas en échec (0 = aucun)
    FailedCaseName   : STRING(32);
    FailReason       : E_TestFailReason;    // Cause du 1er cas en échec (FAIL_NONE si aucun)
    ErrorCode        : INT;
    ErrorMessage     : STRING(160);
    CasesTotal       : INT;
    CasesPassed      : INT;
    CasesFailed      : INT;
    Duration         : TIME;
    RunCounter       : UDINT;
END_STRUCT
END_TYPE

(* ═══════════════════════════════════════════════════════════════
   📡 FB_Diag_Ethercat — Diagnostic bus EtherCAT (3 esclaves)
   ───────────────────────────────────────────────────────────────
   📄 Docs : DOC/AF_Partie-02_Architecture_Programme_v3.0.md
              DOC/AF_Partie-06_Acquisition_Qualification_IO_v2.0.md §3
   🎯 Rôle : Décide Online/Operational pour variateur M3 + codeurs M1/M2.
      Publie ST_Diag_Device par device + state global.
   ═══════════════════════════════════════════════════════════════ *)
FUNCTION_BLOCK PUBLIC FB_Diag_Ethercat
VAR_INPUT
    Enable              : BOOL;        (* Active la surveillance EtherCAT *)
    Reset               : BOOL;        (* Front d'acquittement des défauts *)

    (* Variateur M3 (AC600_ECAT_Drive) *)
    DeviceVariateurStateRaw     : DEVICE_STATE; (* Valeur brute AC600_ECAT_Drive.GetDeviceState() *)
    DeviceVariateurSimBypass    : BOOL;         (* TRUE = simulation active *)

    (* Encodeur M1 (COD1_CODEUR) *)
    DeviceEncoderM1StateRaw     : DEVICE_STATE; (* Valeur brute COD1_CODEUR.GetDeviceState() *)
    DeviceEncoderM1SimBypass    : BOOL;         (* TRUE = simulation active *)

    (* Encodeur M2 (COD2_CODEUR) *)
    DeviceEncoderM2StateRaw     : DEVICE_STATE; (* Valeur brute COD2_CODEUR.GetDeviceState() *)
    DeviceEncoderM2SimBypass    : BOOL;         (* TRUE = simulation active *)

    NetworkBypassActive         : BOOL;         (* TRUE = bypass réseau global IHM *)
END_VAR
VAR_OUTPUT
    Ready               : BOOL;        (* Logique de surveillance active *)
    Busy                : BOOL;        (* Non utilisé (conformité) *)
    Done                : BOOL;        (* Non utilisé *)
    Error               : BOOL;        (* Résumé anomalie de communication bus *)
    ErrorId             : WORD;        (* Code défaut global résumé *)
    State               : E_Diag_State; (* Phase courante du diagnostic global — voir en-tête *)
    StateAtError        : E_Diag_State; (* Phase figée à l'apparition de l'erreur *)
    DeviceEthercatMaster : ST_Diag_Device; (* Diagnostics bus EtherCAT *)
    DeviceVariateur     : ST_Diag_Device;  (* Diagnostics esclave AC600 *)
    DeviceEncoderM1     : ST_Diag_Device;  (* Diagnostics esclave COD1 *)
    DeviceEncoderM2     : ST_Diag_Device;  (* Diagnostics esclave COD2 *)
    (* Miroirs bruts lisibles directement sur l'instance *)
    DeviceVariateurStateRawOut : DEVICE_STATE;
    DeviceEncoderM1StateRawOut : DEVICE_STATE;
    DeviceEncoderM2StateRawOut : DEVICE_STATE;
END_VAR
VAR
    ResetEdge           : R_TRIG;      (* Détecteur front de reset *)
    VariateurOnlineReal  : BOOL; (* GetDeviceState() = RUNNING, hors tout bypass *)
    EncoderM1OnlineReal  : BOOL;
    EncoderM2OnlineReal  : BOOL;
    VariateurBypass      : BOOL; (* Simulation OU bypass réseau IHM, pour ce device *)
    EncoderM1Bypass      : BOOL;
    EncoderM2Bypass      : BOOL;
    VariateurOnlineEff   : BOOL; (* Online effectif (réel OU bypass) *)
    EncoderM1OnlineEff   : BOOL;
    EncoderM2OnlineEff   : BOOL;
END_VAR

// 🛑 1. GATE : Désactivation si Enable = FALSE
IF NOT Enable THEN
    Ready := FALSE;
    State := E_Diag_State.DISABLED;
    DeviceVariateur.State := E_Diag_State.DISABLED;
    DeviceEncoderM1.State := E_Diag_State.DISABLED;
    DeviceEncoderM2.State := E_Diag_State.DISABLED;
    DeviceVariateur.Online := FALSE;
    DeviceEncoderM1.Online := FALSE;
    DeviceEncoderM2.Online := FALSE;
    DeviceVariateur.Operational := FALSE;
    DeviceEncoderM1.Operational := FALSE;
    DeviceEncoderM2.Operational := FALSE;
    DeviceVariateur.Error := FALSE;
    DeviceEncoderM1.Error := FALSE;
    DeviceEncoderM2.Error := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    DeviceEthercatMaster.State := E_Diag_State.DISABLED;
    DeviceEthercatMaster.Online := FALSE;
    DeviceEthercatMaster.Operational := FALSE;
    DeviceVariateurStateRawOut := DeviceVariateurStateRaw;
    DeviceEncoderM1StateRawOut := DeviceEncoderM1StateRaw;
    DeviceEncoderM2StateRawOut := DeviceEncoderM2StateRaw;
    RETURN;
END_IF;

Ready := TRUE;

// 🧮 2. INTERPRÉTATION DES VALEURS BRUTES
VariateurOnlineReal := (DeviceVariateurStateRaw = DEVICE_STATE.RUNNING);
EncoderM1OnlineReal := (DeviceEncoderM1StateRaw = DEVICE_STATE.RUNNING);
EncoderM2OnlineReal := (DeviceEncoderM2StateRaw = DEVICE_STATE.RUNNING);

VariateurBypass := DeviceVariateurSimBypass OR NetworkBypassActive;
EncoderM1Bypass := DeviceEncoderM1SimBypass OR NetworkBypassActive;
EncoderM2Bypass := DeviceEncoderM2SimBypass OR NetworkBypassActive;

VariateurOnlineEff := VariateurOnlineReal OR VariateurBypass;
EncoderM1OnlineEff := EncoderM1OnlineReal OR EncoderM1Bypass;
EncoderM2OnlineEff := EncoderM2OnlineReal OR EncoderM2Bypass;

// 🔑 3. RESET FRONT
ResetEdge(CLK := Reset);

// 🔍 4. DIAGNOSTIC VARIATEUR (AC600_ECAT_Drive / Translation M3)
DeviceVariateur.Online := VariateurOnlineEff;
DeviceVariateur.Operational := VariateurOnlineEff;

IF NOT DeviceVariateur.Online THEN
    DeviceVariateur.ErrorId := DeviceVariateur.ErrorId OR 16#0010;  (* Perte liaison physique variateur *)
ELSE
    DeviceVariateur.ErrorId := DeviceVariateur.ErrorId AND 16#FFEF; (* Effacement auto dès que RUNNING *)
END_IF;

// 🔍 5. DIAGNOSTIC ENCODEUR M1 (COD1_CODEUR / WinchM1)
DeviceEncoderM1.Online := EncoderM1OnlineEff;
DeviceEncoderM1.Operational := EncoderM1OnlineEff;

IF NOT DeviceEncoderM1.Online THEN
    DeviceEncoderM1.ErrorId := DeviceEncoderM1.ErrorId OR 16#0020;  (* Perte liaison encodeur M1 *)
ELSE
    DeviceEncoderM1.ErrorId := DeviceEncoderM1.ErrorId AND 16#FFDF; (* Effacement auto dès que RUNNING *)
END_IF;

// 🔍 6. DIAGNOSTIC ENCODEUR M2 (COD2_CODEUR / WinchM2)
DeviceEncoderM2.Online := EncoderM2OnlineEff;
DeviceEncoderM2.Operational := EncoderM2OnlineEff;

IF NOT DeviceEncoderM2.Online THEN
    DeviceEncoderM2.ErrorId := DeviceEncoderM2.ErrorId OR 16#0030;  (* Perte liaison encodeur M2 *)
ELSE
    DeviceEncoderM2.ErrorId := DeviceEncoderM2.ErrorId AND 16#FFCF; (* Effacement auto dès que RUNNING *)
END_IF;

// 🚦 7. STATE MACHINES DE CHAQUE APPAREIL
IF DeviceVariateur.ErrorId <> 0 THEN
    DeviceVariateur.State := E_Diag_State.ERROR;
ELSIF NOT VariateurOnlineEff THEN
    DeviceVariateur.State := E_Diag_State.INIT;
ELSIF VariateurBypass AND NOT VariateurOnlineReal THEN
    DeviceVariateur.State := E_Diag_State.SIMULATED;
ELSE
    DeviceVariateur.State := E_Diag_State.READY;
END_IF;

IF DeviceEncoderM1.ErrorId <> 0 THEN
    DeviceEncoderM1.State := E_Diag_State.ERROR;
ELSIF NOT EncoderM1OnlineEff THEN
    DeviceEncoderM1.State := E_Diag_State.INIT;
ELSIF EncoderM1Bypass AND NOT EncoderM1OnlineReal THEN
    DeviceEncoderM1.State := E_Diag_State.SIMULATED;
ELSE
    DeviceEncoderM1.State := E_Diag_State.READY;
END_IF;

IF DeviceEncoderM2.ErrorId <> 0 THEN
    DeviceEncoderM2.State := E_Diag_State.ERROR;
ELSIF NOT EncoderM2OnlineEff THEN
    DeviceEncoderM2.State := E_Diag_State.INIT;
ELSIF EncoderM2Bypass AND NOT EncoderM2OnlineReal THEN
    DeviceEncoderM2.State := E_Diag_State.SIMULATED;
ELSE
    DeviceEncoderM2.State := E_Diag_State.READY;
END_IF;

// Fige la phase du diagnostic global sur le premier défaut
IF (DeviceVariateur.ErrorId <> 0 OR DeviceEncoderM1.ErrorId <> 0 OR DeviceEncoderM2.ErrorId <> 0) THEN
    IF StateAtError = E_Diag_State.DISABLED THEN
        StateAtError := State;
    END_IF;
END_IF;

// 📤 8. RÉSUMÉ ET DÉFAUTS
DeviceVariateur.Error := (DeviceVariateur.ErrorId <> 0);
DeviceEncoderM1.Error := (DeviceEncoderM1.ErrorId <> 0);
DeviceEncoderM2.Error := (DeviceEncoderM2.ErrorId <> 0);

Error := (DeviceVariateur.Error OR DeviceEncoderM1.Error OR DeviceEncoderM2.Error);

ErrorId := 16#0000;
IF DeviceVariateur.Error THEN
    ErrorId := ErrorId OR 16#00F0;
END_IF;
IF DeviceEncoderM1.Error THEN
    ErrorId := ErrorId OR 16#0F00;
END_IF;
IF DeviceEncoderM2.Error THEN
    ErrorId := ErrorId OR 16#F000;
END_IF;

IF Error THEN
    State := E_Diag_State.ERROR;
ELSIF NOT (VariateurOnlineEff AND EncoderM1OnlineEff AND EncoderM2OnlineEff) THEN
    State := E_Diag_State.INIT;
ELSIF (VariateurBypass OR EncoderM1Bypass OR EncoderM2Bypass)
      AND NOT (VariateurOnlineReal AND EncoderM1OnlineReal AND EncoderM2OnlineReal) THEN
    State := E_Diag_State.SIMULATED;
ELSE
    State := E_Diag_State.READY;
END_IF;

DeviceEthercatMaster.Online := VariateurOnlineEff AND EncoderM1OnlineEff AND EncoderM2OnlineEff;
DeviceEthercatMaster.Operational := DeviceEthercatMaster.Online;

DeviceVariateurStateRawOut := DeviceVariateurStateRaw;
DeviceEncoderM1StateRawOut := DeviceEncoderM1StateRaw;
DeviceEncoderM2StateRawOut := DeviceEncoderM2StateRaw;

Busy := FALSE;
Done := FALSE;

SETUP
VAR
    fb : FB_JOYSTICK;
    nx : INT := 5000;
    ny : INT := 5000;
    diagOk : ST_DIAG_DEVICE;
    diagDown : ST_DIAG_DEVICE;
END_VAR
END_SETUP

TEST 'TC-P08-001 Perte bus CAN pendant un mouvement arme neutralise, desarme et leve Error (auto-efface au retour)'
    diagDown.ONLINE := FALSE; diagDown.OPERATIONAL := FALSE; diagDown.ERROR := FALSE;
    diagDown.ERRORID := 0; diagDown.STATE := E_DIAG_STATE.INIT; diagDown.STATEATERROR := E_DIAG_STATE.DISABLED;
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;
    nx := 5000; ny := 5000;

    (* arme le geste au neutre, bus sain *)
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ADVANCE_TIME(110000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, 'precondition : geste arme');

    (* deplace le joystick : mouvement actif, bus toujours sain *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 60.0, 0.01, 'mouvement actif : consigne non nulle (RawX=8000, Neutral=5000)');
    ASSERT_EQ(fb.AXISCMDX.DIRECTION, 1, 'sens avant pendant le mouvement');
    ASSERT_NEAR(fb.AXISCMDY.SPEEDREF, 0.0, 0.01, 'RawY au neutre : axe Y reste a 0, aucun couplage entre les axes');
    ASSERT_EQ(fb.AXISCMDY.DIRECTION, 0, 'axe Y au neutre : Direction=0');

    (* perte du bus CAN EN PLEIN MOUVEMENT : neutralisation immediate + desarmement *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagDown, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.READY, 'bus CAN non operationnel doit bloquer Ready');
    ASSERT_TRUE(fb.ERROR, 'perte de comm doit lever Error (AF08)');
    ASSERT_EQ(fb.ERRORID, 16#0004, 'bit2 : HW/bus non operationnel');
    ASSERT_FALSE(fb.AXISCMDX.ENABLE, 'sorties axe X neutralisees des la perte du bus, meme en plein mouvement');
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 0.0, 0.01, 'consigne X coupee immediatement, pas de decel progressive');
    ASSERT_FALSE(fb.AXISCMDY.ENABLE, 'sorties axe Y aussi neutralisees (gate global, pas seulement l axe en mouvement)');
    ASSERT_NEAR(fb.AXISCMDY.SPEEDREF, 0.0, 0.01, 'consigne Y aussi coupee');
    ASSERT_FALSE(fb.DEADMANARMED, 'le geste est desarme par la perte du bus (AF08 TC-P08-001)');

    (* bus revient : pas de rearmement automatique, nouvel appui conscient exige *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.READY, 'bus revenu : FB de nouveau pret');
    ASSERT_FALSE(fb.ERROR, 'bus revenu : Error auto-effacee sans geste operateur (categorie Info/Warning, pas un Fault a acquitter)');
    ASSERT_EQ(fb.ERRORID, 0, 'bit2 efface automatiquement');
    ASSERT_FALSE(fb.DEADMANARMED, 'pas de rearmement automatique au retour du bus : nouvel appui conscient exige');
END_TEST

TEST 'TC-P08-002 Maintien DeadmanArmHoldTime : arme si tenu 100ms, annule si relache avant'
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;

    (* baseline : neutre, bouton relache *)
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'baseline : bouton relache, pas arme');

    (* front bouton : demarre le maintien, pas encore arme *)
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'front bouton seul ne doit pas armer immediatement (maintien requis)');

    (* 50ms plus tard : maintien pas termine -- l operateur bouge DEJA l axe X seul (Y reste
       neutre) pendant l attente : aucune commande ne doit partir tant que ce n est pas arme *)
    ADVANCE_TIME(50000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, '50ms < DeadmanArmHoldTime (100ms) : pas encore arme');
    ASSERT_NEAR(fb.CMDXVAL, 0.0, 0.01, 'consigne interne X (CmdXVal) forcee a 0 : pas encore arme');
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 0.0, 0.01, 'axe X seul pousse (RawX=8000, RawY neutre) mais pas encore arme : aucune commande ne part');

    (* 20ms de plus (toujours < 100ms) : cette fois l axe Y seul est pousse (X revient au
       neutre) -- meme preuve, isolee sur l autre axe *)
    ADVANCE_TIME(20000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 2000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, '70ms < DeadmanArmHoldTime (100ms) : toujours pas arme');
    ASSERT_NEAR(fb.CMDYVAL, 0.0, 0.01, 'consigne interne Y (CmdYVal) forcee a 0 : pas encore arme');
    ASSERT_NEAR(fb.AXISCMDY.SPEEDREF, 0.0, 0.01, 'axe Y seul pousse (RawY=2000, RawX neutre) mais pas encore arme : aucune commande ne part');

    (* relache a 50ms, avant la fin des 100ms de maintien : annule la tentative *)
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'relachement avant la fin du maintien annule la tentative');

    (* le bouton reste relache PENDANT 1s ENTIERE, manche pousse a fond (RawX=8000) tout du
       long : aucun armement differe, et surtout aucune commande de mouvement ne demarre,
       meme apres une longue attente sur une position hors neutre *)
    ADVANCE_TIME(1000000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 8000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'pas d armement differe sur une tentative deja annulee, meme apres 1s (nouvel appui conscient exige)');
    ASSERT_NEAR(fb.AXISCMDX.SPEEDREF, 0.0, 0.01, 'manche a fond depuis 1s mais jamais arme : toujours aucune commande de mouvement');

    (* nouveau front + maintien complet (110ms) : l armement redevient possible normalement *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ADVANCE_TIME(110000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, '110ms >= DeadmanArmHoldTime (100ms) : geste arme');
END_TEST

TEST 'TC-P08-004 Delai de grace protege l armement au neutre, puis le neutre prolonge desarme apres la grace'
    diagOk.ONLINE := TRUE; diagOk.OPERATIONAL := TRUE; diagOk.ERROR := FALSE;
    diagOk.ERRORID := 0; diagOk.STATE := E_DIAG_STATE.READY; diagOk.STATEATERROR := E_DIAG_STATE.DISABLED;

    (* nx/ny fixes explicitement a 5000 avant CHAQUE appel : STruCpp ne re-copie PAS la sortie
       VAR_IN_OUT vers la variable de test entre deux appels fb() (limite outillage constatee,
       round-trip IN_OUT absent -- cf. README). Sans ce forcage, NeutralXMem retomberait a 0
       (valeur SETUP jamais appliquee non plus) des le 2e scan, et AtNeutral resterait FALSE. *)
    nx := 5000; ny := 5000;

    (* arme le geste au neutre *)
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ADVANCE_TIME(110000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := TRUE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, 'precondition : geste arme');

    (* bouton relache, reste au neutre : 500ms plus tard (largement > NeutralHoldTime seul 100ms) mais < grace (3s) *)
    ADVANCE_TIME(500000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, 'la grace (3s) protege l armement malgre un neutre deja tenu bien plus longtemps que NeutralHoldTime seul (evite le REX terrain : desarmement 100-200ms apres l armement)');

    (* 2.6s de plus (total 3.1s depuis l armement) : la grace vient de s ecouler ce scan meme --
       NeutralHoldTimer ne fait que DEMARRER (son IN passe a TRUE ce scan), pas encore Q *)
    ADVANCE_TIME(2600000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_TRUE(fb.DEADMANARMED, 'grace tout juste ecoulee : NeutralHoldTimer demarre seulement ce scan (pas encore ecoule)');

    (* 100ms de plus (NeutralHoldTime ecoule depuis la fin de la grace) : desarme *)
    ADVANCE_TIME(100000000);
    fb(ENABLE := TRUE, RESET := FALSE,
       MODE := E_MODE.MAINT_N1, BENNEBUSY := FALSE, PRESERVEARMINGAFTERBUCKET := FALSE,
       BUSCANOPENOP := diagOk, JOYSTICKOP := diagOk,
       RAWX := 5000, RAWY := 5000, RAWBUTTON := FALSE, BTNCALIBRATE := FALSE,
       INVERTX := FALSE, INVERTY := FALSE, DEADBANDRAW := 300,
       NEUTRALHOLDTIME := T#100MS, DEADMANARMHOLDTIME := T#100MS, DEADMANARMGRACETIME := T#3S,
       NEUTRALXMEM := nx, NEUTRALYMEM := ny);
    ASSERT_FALSE(fb.DEADMANARMED, 'grace ecoulee (3s) + neutre tenu (NeutralHoldTime) : desarmement');
END_TEST

