       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'timeout confirmation doit ramener la sequence a IDLE');
    ASSERT_TRUE(fb.EMERGENCYARMINGLOCKOUTACTIVE, 'timeout doit declencher le lockout (TC-P01-007)');
    ASSERT_TRUE(fb.EMERGENCYARMINGFAILED, 'timeout doit lever le defaut EmergencyArmingFailed');
    ASSERT_TRUE(fb.ERROR, 'defaut doit etre visible sur Error');

    (* pendant le lockout : un nouveau front ArmRequest doit etre bloque *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'lockout actif doit bloquer toute nouvelle tentative de reamement');

    (* 5s apres le debut du lockout : le verrouillage doit se lever automatiquement *)
    ADVANCE_TIME(5000000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_FALSE(fb.EMERGENCYARMINGLOCKOUTACTIVE, 'lockout 5s ecoule -> leve automatiquement');

    (* preuve OPERATIONNELLE (pas juste le drapeau) : un nouveau front doit maintenant relancer
       reellement la sequence -- +1 cycle pour que le retrait du lockout soit visible au scan
       suivant avant de tenter le nouveau front (ordre de calcul : trigger avant re-evaluation
       du lockout dans le meme scan, cf. Logic.st) *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := TRUE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_EQ(fb.ARMINGSEQSTEP, 1, 'apres le lockout, un nouveau front doit reellement relancer TestA (pas juste le drapeau qui retombe)');
END_TEST

TEST 'TC-P01-008 PowerCutOffRequest coupe A et B sans armer'
    (* scan 1 : autotest demarrage (1 cycle, boucle saine, contacteur repos) *)
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);

    (* scan 2 : regime etabli, maintien sain attendu -- +1 cycle automate (10ms) *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := FALSE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_TRUE(fb.MAINTAINA_RQ, 'hors defaut, canal A doit etre maintenu');
    ASSERT_TRUE(fb.MAINTAINB_RQ, 'hors defaut, canal B doit etre maintenu');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'pas de sequence en cours');

    (* scan 3 : coupure demandee par un metier (Winch/Translation) -- +1 cycle automate *)
    ADVANCE_TIME(10000000);
    fb(ENABLE := TRUE, RESET := FALSE, ARMREQUEST := FALSE, POWERCUTOFFREQUEST := TRUE,
       BTNEMERGENCYCUTOFF := FALSE, EMERGENCYCHAINCLOSED := TRUE, POWERCONTACTORENGAGED := FALSE);
    ASSERT_FALSE(fb.MAINTAINA_RQ, 'PowerCutOffRequest doit couper le canal A');
    ASSERT_FALSE(fb.MAINTAINB_RQ, 'PowerCutOffRequest doit couper le canal B');
    ASSERT_EQ(fb.ARMINGSEQSTEP, 0, 'PowerCutOffRequest ne doit jamais declencher une sequence armement');
END_TEST

FUNCTION_BLOCK FB_TestEventOrder
VAR_INPUT
    Arm       : BOOL;
    EventA    : BOOL;
    EventB    : BOOL;
    TimeoutPT : TIME;
END_VAR
VAR_OUTPUT
    OrderOk   : BOOL;
    Failed    : BOOL;
END_VAR
VAR
    TrigA     : R_TRIG;
    TrigB     : R_TRIG;
    Timer     : TON;
    HasA      : BOOL;
END_VAR
// === IMPLEMENTATION ===
TrigA(CLK := EventA);
TrigB(CLK := EventB);

IF NOT Arm THEN
    OrderOk := FALSE;
    Failed  := FALSE;
    HasA    := FALSE;
    Timer(IN := FALSE);
    RETURN;
END_IF;

// Échec immédiat si B se produit avant A
IF TrigB.Q AND NOT HasA THEN
    Failed  := TRUE;
    OrderOk := FALSE;
END_IF;

// Mémorisation de la survenue de A
IF TrigA.Q AND NOT Failed AND NOT OrderOk THEN
    HasA := TRUE;
END_IF;

// Armement du timeout une fois que A s'est produit
Timer(IN := HasA AND NOT OrderOk AND NOT Failed, PT := TimeoutPT);

IF Timer.Q THEN
    Failed  := TRUE;
    OrderOk := FALSE;
END_IF;

// Validation du succès si B arrive après A et dans les temps
IF HasA AND TrigB.Q AND NOT Failed THEN
    OrderOk := TRUE;
END_IF;

(* =======================================================================
   ⚙️ FB_Ramp — Rampe d'accélération et décélération asymétrique
   ───────────────────────────────────────────────────────────────
   🎯 Rôle : Limitation de variation anti-à-coups (%/s) sur signal analogique
   🔒 Polarité : Distingue l'éloignement de zéro (Accel) et le retour à zéro (Decel)
   📄 Doc métier : DOC/AF/AF_Partie-08_Fonction_Joystick_v2.0.md §2
   ======================================================================= *)
FUNCTION_BLOCK FB_Ramp
VAR_INPUT
    // === CONSIGNES ET TAUX DE RAMPE ===
    Target                  : REAL;               // --> [CMD] Valeur cible visee (-100.0..+100.0 %)
    AccelRate               : REAL;               // --> [CFG] Taux d'acceleration (%/s)
    DecelRate               : REAL;               // --> [CFG] Taux de deceleration (%/s)
    CycleTimeS              : REAL;               // --> [CFG] Temps de cycle reel en secondes (dt)
END_VAR
VAR_OUTPUT
    // === VALEUR RAMPEE ===
    Current                 : REAL;               // <-- [STAT] Valeur courante amortie (-100.0..+100.0 %)
END_VAR
VAR
    // === CALCULS INTERNES ===
    StepX                   : REAL;               // . [LOC] Pas de variation pour le cycle courant
    TargetLimited           : REAL;               // . [LOC] Cible bornee a [-100.0, +100.0]
END_VAR

// Détection du comportement (Accélération vs Décélération)
// Classification par CÔTÉ DE ZÉRO + sens de déplacement, plus par signe brut de Target seul
// (robuste à une traversée de zéro rapide).
// 🛡️ Garde-fou : la rampe ne sort jamais de la plage normalisée ±100 %.
TargetLimited := LIMIT(-100.0, Target, 100.0);
Current := LIMIT(-100.0, Current, 100.0);

IF (Current >= 0.0 AND TargetLimited >= Current) OR (Current <= 0.0 AND TargetLimited <= Current) THEN
    StepX := AccelRate * CycleTimeS; // S'éloigne du zéro (reste du même côté, va plus loin)
ELSE
    StepX := DecelRate * CycleTimeS; // Retourne vers zéro, ou le traverse vers l'autre signe
END_IF;

// Application de la rampe
IF Current < TargetLimited THEN
    Current := Current + StepX;
    IF Current > TargetLimited THEN Current := TargetLimited; END_IF;
ELSIF Current > TargetLimited THEN
    Current := Current - StepX;
    IF Current < TargetLimited THEN Current := TargetLimited; END_IF;
END_IF;

// 🛡️ Limitation finale : même une valeur d'état déjà corrompue reste bornée.
Current := LIMIT(-100.0, Current, 100.0);

SETUP
VAR
    fb : FB_CYCLETIME;
END_VAR
END_SETUP

